proc renderInternalUsage*(programName: string): string =
  ## Usage text for the documented-but-hidden ``repro internal …`` command
  ## group (Executable-Consolidation M1). These subcommands are role
  ## processes that ``repro`` reaches by self-spawn (``getAppFilename()`` +
  ## the ``internal`` argv) rather than via standalone sibling binaries.
  ## They are intentionally kept OUT of the primary ``repro`` help body —
  ## discoverable for debugging, walled off from the user surface — but
  ## ``repro internal --help`` prints this so the namespace is documented.
  ##
  ## The ``__repro-*`` argument spellings remain accepted as compatibility
  ## aliases for one release; the ``internal``-namespaced spellings below
  ## are the documented forms.
  programName & " " & versionString() & "\n" &
    "usage: " & programName & " internal <subcommand> [args...]\n\n" &
    "internal subcommands (role processes; not part of `" & programName &
      " help`):\n" &
    "  io monitor [options] -- <command> [args...] filesystem-monitor shim " &
      "(user form: " & programName & " debug io monitor)\n" &
    "  runquota-helper …                           RunQuota lease helper " &
      "(alias of __repro-runquota-helper)\n" &
    "  compile-provider …                          provider-compile helper " &
      "(alias of __repro-compile-provider)\n" &
    "  extract-interface …                         interface-extraction " &
      "helper (alias of __repro-extract-interface)\n" &
    "  compile-profile …                           profile-compile helper " &
      "(alias of __repro-compile-profile)\n" &
    "  dev-env-introspect …                        dev-env introspection " &
      "helper (alias of __repro-dev-env-introspect)\n" &
    "  render-dev-env-shell …                      dev-env shell renderer " &
      "(alias of __repro-render-dev-env-shell)\n" &
    "  direnv-activate …                           direnv activation helper " &
      "(alias of __repro-direnv-activate)\n" &
    "  native-shell-activate …                     native-shell activation " &
      "helper (alias of __repro-native-shell-activate)\n" &
    "  dev-session-supervisor …                    dev-session supervisor " &
      "(alias of __repro-dev-session-supervisor)\n" &
    "  dev-session-http …                          dev-session HTTP bridge " &
      "(alias of __repro-dev-session-http)\n" &
    "  cmake-regenerate …                          CMake regeneration helper " &
      "(alias of __repro-cmake-regenerate)"

proc parseToolProvisioning*(value: string): ToolProvisioningMode =
  case value
  of "path":
    tpmPathOnly
  of "nix":
    tpmNix
  of "tarball":
    tpmTarball
  of "scoop":
    tpmScoop
  of "from-source", "fromSource", "source":
    # M9.Q: principled from-source provisioning. Maps each ``uses:
    # <name>`` selector onto a sibling recipe at
    # ``recipes/packages/source/<name>/``; threads the recipe's
    # output bin dir into ``pathSearchList``. v1 hard-fails when the
    # sibling recipe or its artefact is missing — auto-recurse is
    # the M9.Q.1 follow-up. Accepts the spelling ``from-source``
    # (CLI canonical), ``fromSource`` (Nim/DSL canonical), and
    # ``source`` (shorthand).
    tpmFromSource
  else:
    raise newException(ValueError, "unsupported --tool-provisioning=" & value)

const ToolProvisioningEnvVar = "REPRO_TOOL_PROVISIONING"

proc resolveToolProvisioningWithEnv(cliMode: ToolProvisioningMode):
    ToolProvisioningMode =
  ## Apply the ``REPRO_TOOL_PROVISIONING`` env var when the CLI did not pin
  ## ``--tool-provisioning`` explicitly. Precedence is: explicit CLI flag >
  ## env var > the package's ``defaultToolProvisioning`` (resolved later, in
  ## ``executeBuildTarget``).
  ##
  ## Today the in-repo ``repro.nim`` project files declare
  ## ``defaultToolProvisioning "path"`` on Linux/macOS (toolchains supplied
  ## by Nix on ``$PATH`` via ``nix develop``) and ``scoop`` is the intended
  ## Windows default — a deliberately temporary arrangement. This env var
  ## lets a developer opt a Linux/macOS checkout into reprobuild-managed Nix
  ## provisioning (``REPRO_TOOL_PROVISIONING=nix``) without editing every
  ## project's ``repro.nim`` or threading ``--tool-provisioning=nix`` through
  ## every invocation. An explicit flag still wins, so scripted callers are
  ## unaffected. Accepts the same ``path|nix|tarball|scoop|from-source``
  ## vocabulary as the flag; an unset/empty value is a no-op. M9.Q adds
  ## the ``from-source`` mode that maps each ``uses:`` selector onto a
  ## sibling recipe at ``recipes/packages/source/<name>/`` and threads
  ## the recipe's output bin dir into ``pathSearchList``.
  if cliMode != tpmUnspecified:
    return cliMode
  let raw = getEnv(ToolProvisioningEnvVar).strip()
  if raw.len == 0:
    return cliMode
  parseToolProvisioning(raw)

proc bytesOf(text: string): seq[byte] =
  result = newSeq[byte](text.len)
  for i, ch in text:
    result[i] = byte(ord(ch))

proc digestHex(digest: ContentDigest): string =
  toHex(digest.bytes)

proc safePathSegment(value, fallback: string): string =
  for ch in value:
    if ch in {'a' .. 'z'} or ch in {'A' .. 'Z'} or ch in {'0' .. '9'} or
        ch in {'-', '_', '.'}:
      result.add(ch)
    else:
      result.add('_')
  if result.len == 0:
    result = fallback

proc configuredWorkRoot(explicitRoot: string): string =
  if explicitRoot.len > 0:
    return explicitRoot
  getEnv("REPROBUILD_WORK_ROOT")

proc resolveActionCacheRoot*(explicitRoot: string = ""): string =
  ## Returns the user-level action-cache root with the precedence documented
  ## in Provider-Compile-Tiering.md §"Cache Scope" Phase 1:
  ##   1. ``explicitRoot`` (e.g. ``--action-cache-root=`` CLI flag)
  ##   2. ``REPROBUILD_ACTION_CACHE_ROOT`` (direct cache root override)
  ##   3. ``${REPROBUILD_STORE_ROOT}/action-cache`` if the env var is set
  ##   4. ``${REPRO_STORE_ROOT}/action-cache`` (compat alias)
  ##   5. Platform default user cache dir
  ##
  ## The returned path is a *directory* root. The build engine adds the
  ## conventional ``action-cache`` and ``cas`` subdirectories. So this
  ## function returns ``<root-for-cache-and-cas>`` directly.
  if explicitRoot.len > 0:
    return explicitRoot
  let envRoot = getEnv("REPROBUILD_ACTION_CACHE_ROOT")
  if envRoot.len > 0:
    return envRoot
  let storeRoot = block:
    let v = getEnv("REPROBUILD_STORE_ROOT")
    if v.len > 0: v else: getEnv("REPRO_STORE_ROOT")
  if storeRoot.len > 0:
    return storeRoot / "action-cache"
  when defined(windows):
    let local = getEnv("LOCALAPPDATA")
    let base = if local.len > 0: local
               else: getEnv("USERPROFILE") / "AppData" / "Local"
    return base / "repro" / "action-cache"
  elif defined(macosx):
    let home = getEnv("HOME")
    return home / "Library" / "Caches" / "repro" / "action-cache"
  else:
    let xdg = getEnv("XDG_CACHE_HOME")
    let base = if xdg.len > 0: xdg else: getEnv("HOME") / ".cache"
    return base / "repro" / "action-cache"

# Process-wide override for the user-level action-cache root. Set by the
# ``--action-cache-root=`` CLI flag and consumed by every BuildEngineConfig
# constructor in this module. Empty means "use the platform default".
var actionCacheRootOverride: string = ""

proc setActionCacheRootOverride*(value: string) =
  actionCacheRootOverride = value

var unicodeOverride: Option[bool] = none(bool)

proc setUnicodeOverride*(value: bool) =
  unicodeOverride = some(value)

proc unicodeEnabled*(): bool =
  if unicodeOverride.isSome:
    return unicodeOverride.get
  let envVal = getEnv("REPRO_UNICODE", "").toLowerAscii()
  if envVal in ["1", "true", "yes", "on"]:
    return true
  false

proc currentActionCacheRoot(): string {.gcsafe.} =
  {.cast(gcsafe).}:
    resolveActionCacheRoot(actionCacheRootOverride)

proc splitTarget(target: string): tuple[base: string; fragment: string] =
  let marker = target.find('#')
  if marker < 0:
    (base: target, fragment: "")
  else:
    (base: target[0 ..< marker], fragment: target[marker + 1 .. ^1])

type
  TargetFragmentKind = enum
    tfkNone
    tfkModule
    tfkActionSelection

  ParsedBuildTarget = object
    modulePath: string
    outputName: string
    selectedActionId: string
    fragmentKind: TargetFragmentKind

proc parseBuildTarget(target: string): ParsedBuildTarget =
  let parts = splitTarget(target)
  if parts.fragment.len > 0:
    if dirExists(extendedPath(parts.base)):
      let fragmentFileName = parts.fragment & ".nim"
      let fragmentModule = parts.base / fragmentFileName
      # A named target may legitimately have the same name as the project
      # file (for example ``repro build repro`` in a directory containing
      # ``repro.nim``). Bare-name resolution represents that selector as
      # ``.#repro``. Anchor that case in the project file instead of treating
      # it as the legacy ``directory#module`` form.
      if fragmentFileName in ProjectFileNames:
        let projectMatch = resolveProjectFile(parts.base)
        if projectMatch.fileName == fragmentFileName:
          return ParsedBuildTarget(
            modulePath: projectMatch.path,
            outputName: splitFile(projectMatch.path).name,
            selectedActionId: parts.fragment,
            fragmentKind: tfkActionSelection)
      if fileExists(extendedPath(fragmentModule)):
        return ParsedBuildTarget(
          modulePath: fragmentModule,
          outputName: parts.fragment,
          fragmentKind: tfkModule)
      # Project-file alias: prefer ``repro.nim``, fall back to
      # ``reprobuild.nim``. See repro_core/project_file.nim and
      # reprobuild-specs/Three-Mode-Convention-System.md. Having both
      # files in the same directory raises ``ProjectFileAmbiguousError``
      # which propagates to the CLI top-level handler.
      let projectMatch = resolveProjectFile(parts.base)
      if projectMatch.path.len > 0:
        return ParsedBuildTarget(
          modulePath: projectMatch.path,
          outputName: splitFile(projectMatch.path).name,
          selectedActionId: parts.fragment,
          fragmentKind: tfkActionSelection)
      return ParsedBuildTarget(
        modulePath: fragmentModule,
        outputName: parts.fragment,
        fragmentKind: tfkModule)
    return ParsedBuildTarget(
      modulePath: parts.base,
      outputName: parts.fragment,
      fragmentKind: tfkModule)

  let modulePath =
    if dirExists(extendedPath(parts.base)):
      # Project-file alias: prefer ``repro.nim``, fall back to
      # ``reprobuild.nim``. Empty match falls through to legacy name so
      # downstream "file not found" diagnostics still mention a concrete
      # filename. Both-files-present raises ``ProjectFileAmbiguousError``.
      let match = resolveProjectFile(parts.base)
      if match.path.len > 0: match.path
      else: parts.base / LegacyProjectFileName
    else:
      parts.base
  ParsedBuildTarget(
    modulePath: modulePath,
    outputName: splitFile(modulePath).name,
    fragmentKind: tfkNone)

proc moduleForTarget(target: string): string =
  parseBuildTarget(target).modulePath

type
  BuildSelectorKind* = enum
    ## Named-Targets M2: how a positional ``repro build`` argument is
    ## interpreted by the resolver. The path / fragment forms preserve
    ## the legacy ``parseBuildTarget`` behavior; the name forms go
    ## through the project's M1 target-export table.
    bskPath        ## Path / directory / fragment selector (legacy form).
    bskName        ## Unqualified implicit or explicit target name.
    bskQualified   ## ``<package>:<name>`` cross-package disambiguator.

  ClassifiedBuildSelector* = object
    raw*: string
    kind*: BuildSelectorKind
    package*: string  ## Only set for ``bskQualified``.
    name*: string     ## ``bskName``: the bare name. ``bskQualified``:
                      ## the post-``:`` half. ``bskPath``: empty.

  BuildTargetAmbiguousError* = object of CatchableError
    ## Raised by the M2 resolver when a name selector matches more than
    ## one package. The CLI top-level catches this and exits 2 with
    ## ``target_ambiguous`` diagnostic listing the qualified candidates.
    selectorName*: string
    candidates*: seq[string]

  BuildTargetUnknownError* = object of CatchableError
    ## Raised by the M2 resolver when a name selector matches no edge.
    ## The CLI top-level catches this and exits 2 with the
    ## ``unknown_target`` diagnostic and Levenshtein candidates.
    selectorName*: string
    suggestions*: seq[string]

proc renderAmbiguousTargetDiagnostic*(err: BuildTargetAmbiguousError): string =
  ## Named-Targets M2 ``target_ambiguous`` stderr diagnostic. Shared by
  ## the top-level CLI dispatch arm and the daemon-side
  ## ``installUserDaemonBuildExecutor`` hook so the two code paths
  ## cannot drift. Lines are terminated with ``\n`` and the returned
  ## string ends with a trailing newline, matching the ``writeLine``
  ## semantics of the original direct-mode emission.
  result.add("repro build: error: target_ambiguous: target '")
  result.add(err.selectorName)
  result.add("' is exported by multiple packages\n")
  result.add("repro build: candidates:\n")
  for cand in err.candidates:
    result.add("  ")
    result.add(cand)
    result.add('\n')
  result.add("repro build: hint: re-run with the qualified " &
    "<package>:<name> form\n")

proc renderUnknownTargetDiagnostic*(err: BuildTargetUnknownError): string =
  ## Named-Targets M2 ``unknown_target`` stderr diagnostic. Shared by
  ## the top-level CLI dispatch arm and the daemon-side
  ## ``installUserDaemonBuildExecutor`` hook so the two code paths
  ## cannot drift. Lines are terminated with ``\n`` and the returned
  ## string ends with a trailing newline.
  result.add("repro build: error: unknown_target: no build target matches '")
  result.add(err.selectorName)
  result.add("'\n")
  if err.suggestions.len > 0:
    result.add("repro build: did you mean:\n")
    for cand in err.suggestions:
      result.add("  ")
      result.add(cand)
      result.add('\n')

proc classifyBuildSelector*(raw: string): ClassifiedBuildSelector =
  ## Named-Targets M2 / [CLI/build.md §"Target Selection"] discriminator.
  ## A selector is a *path / fragment* selector when ANY of these holds:
  ## - it contains ``/`` or ``\\`` (path separator),
  ## - it contains ``.`` (file extension or relative-path marker),
  ## - it contains ``#`` (fragment selector),
  ## - it names an existing path on disk (file or directory).
  ##
  ## Otherwise it is a *name* selector. Names containing a single ``:``
  ## (and no other special chars) are treated as the qualified
  ## ``<package>:<name>`` form so M2 can disambiguate cross-package
  ## collisions even though M5 fully polishes the surface.
  result = ClassifiedBuildSelector(raw: raw)
  if raw.len == 0:
    result.kind = bskPath
    return
  for ch in raw:
    if ch == '/' or ch == '\\' or ch == '.' or ch == '#':
      result.kind = bskPath
      return
  if fileExists(extendedPath(raw)) or dirExists(extendedPath(raw)):
    result.kind = bskPath
    return
  let colon = raw.find(':')
  if colon > 0 and colon < raw.high:
    # ``<package>:<name>`` qualified form. Only accept when neither half
    # is empty AND there's exactly one ``:`` (so Windows drive letters
    # like ``C:\foo`` already get filtered by the path-shape check
    # above on ``\\``).
    let secondColon = raw.find(':', colon + 1)
    if secondColon < 0:
      result.kind = bskQualified
      result.package = raw[0 ..< colon]
      result.name = raw[colon + 1 .. ^1]
      return
  result.kind = bskName
  result.name = raw

type
  ResolvedPositionalSelectors* = object
    ## Named-Targets M3 shared resolver output. ``runBuildCommand`` and
    ## ``runWatchCommand`` both consume this so the path-vs-name
    ## discriminator + multi-target lowering are implemented in exactly
    ## one place.
    target*: string
      ## The engine's project anchor. For path-shaped positionals this
      ## is the original selector verbatim; for name-only invocations it
      ## is ``"."`` or ``".#<firstName>"`` so the legacy
      ## ``parseBuildTarget`` codepath still resolves a module.
    extraNameSelectors*: seq[string]
      ## Name-shaped positionals beyond the first. The lowering pass in
      ## ``lowerProviderSnapshot`` unions every selector's dependency
      ## closure in one engine pass.
    targetWasOmitted*: bool
      ## True when no positional was supplied. ``runBuildCommand`` uses
      ## this to flip ``selectDefaultAction = true``; watch sets the
      ## same flag for the same reason.

proc findSiblingProjectFile*(packageName: string;
                             currentDir = ""): string =
  ## **Deferred Item D2** cross-project sibling discovery.
  ##
  ## Given a bare package name (the LHS of a ``<pkg>:<target>`` qualified
  ## selector), check whether a sibling checkout exists alongside the
  ## current project (one level up: ``../<pkg>/repro.nim`` or
  ## ``../<pkg>/reprobuild.nim``). Returns the resolved project-file path
  ## when found, otherwise the empty string.
  ##
  ## This is the minimum-viable cross-project discovery for D2 — the
  ## broader workspace-manifest-backed develop-mode mechanism
  ## (Workspace-And-Develop-Mode.md) is deferred to a later milestone.
  ## Until that lands, sibling-directory discovery is enough to make
  ## ``repro build runquota:runquotad`` route through the engine's
  ## existing path-with-fragment codepath (which already supports
  ## arbitrary out-of-tree project files; see the B0 outcome).
  if packageName.len == 0:
    return ""
  # Filter out obviously-unsafe spellings — a package name with a path
  # separator is not a bare package name; let the upstream qualified-
  # selector validator reject it instead.
  for ch in packageName:
    if ch == '/' or ch == '\\' or ch == '.' or ch == ':':
      return ""
  let anchor =
    if currentDir.len > 0: currentDir
    else: getCurrentDir()
  # Walk UP from the anchor, probing ``<ancestor>/<packageName>`` at each level.
  # Level one (``anchor.parentDir / packageName``) is the direct-sibling
  # convention; the walk-up extends it to the WORKSPACE-ROOT sibling convention
  # so a DEEP out-of-tree consumer (several dirs below the workspace root) can
  # still discover a top-level workspace sibling (the RP5c2 shape). Purely
  # additive — a direct sibling is still found at level one, and the nearest
  # ancestor owning ``<packageName>`` wins (a closer same-named sibling shadows a
  # farther one). Mirrors ``workspaceProducerModule``'s compile-time walk so the
  # runtime and macro-time discoveries stay in lock-step.
  var dir = anchor
  for _ in 0 ..< 16:
    let parent = dir.parentDir
    if parent.len == 0 or parent == dir:
      break
    let siblingDir = parent / packageName
    if dirExists(extendedPath(siblingDir)):
      let match =
        try:
          resolveProjectFile(siblingDir)
        except ProjectFileAmbiguousError:
          # Both repro.nim AND reprobuild.nim — let the regular project-
          # loading codepath surface the diagnostic if the user proceeds.
          return ""
        except CatchableError:
          ProjectFileMatch()
      if match.path.len > 0:
        return match.path
    dir = parent
  ""

proc parseAndResolveSelectors*(positionalSelectors: openArray[string];
                               command: string): ResolvedPositionalSelectors =
  ## Named-Targets M3: shared path-vs-name resolver for ``repro build``
  ## and ``repro watch``. Mirrors the rules in
  ## [CLI/build.md §"Target Selection"] and
  ## [CLI/watch.md §"Target Selection"]:
  ##
  ## - The first positional whose ``classifyBuildSelector`` kind is
  ##   ``bskPath`` becomes the engine's project anchor (``target``).
  ##   A second path-shaped positional is rejected — the engine still
  ##   expects exactly one project anchor in M3 (qualified-name +
  ##   ``--list-targets`` polish lands in M5).
  ## - The first name-shaped positional, when no path anchor is present,
  ##   becomes ``".#<name>"`` so ``parseBuildTarget`` routes it through
  ##   the fragment / action-selection codepath. When a path anchor is
  ##   present, the first name-shaped positional joins
  ##   ``extraNameSelectors`` instead.
  ## - Every other name-shaped positional appends to
  ##   ``extraNameSelectors``. ``lowerProviderSnapshot`` unions their
  ##   closures with the anchor's in one engine pass.
  ##
  ## ``command`` is the user-visible verb (``"repro build"`` /
  ## ``"repro watch"``) so the duplicate-path-anchor diagnostic blames
  ## the right command.
  result.targetWasOmitted = positionalSelectors.len == 0
  if positionalSelectors.len == 0:
    result.target = ""
    return
  var anchorSet = false
  var firstNameSelector = ""
  for sel in positionalSelectors:
    let classified = classifyBuildSelector(sel)
    case classified.kind
    of bskPath:
      if not anchorSet:
        result.target = sel
        anchorSet = true
      else:
        raise newException(ValueError,
          command & ": multiple path / fragment selectors are not " &
            "supported in M3 (got '" & result.target & "' and '" & sel &
            "'); name-shaped selectors may follow a single path anchor")
    of bskQualified:
      # **Deferred Item D2** cross-project selector resolution. A
      # qualified selector ``<pkg>:<target>`` whose LHS names a sibling
      # checkout (``../<pkg>/repro.nim`` or ``reprobuild.nim``) routes
      # through the engine's existing path-with-fragment codepath. The
      # sibling's project file becomes the engine's project anchor, and
      # the RHS becomes the named-target fragment. This intentionally
      # short-circuits ahead of the same-project ``<package>:<name>``
      # disambiguator below — the disambiguator is for cross-package
      # collisions inside ONE project, so it never legitimately matches
      # a sibling-checkout package name. The sibling-found branch wins.
      let siblingProjectFile = findSiblingProjectFile(classified.package)
      if siblingProjectFile.len > 0:
        if not anchorSet:
          result.target = siblingProjectFile & "#" & classified.name
          anchorSet = true
          # Do NOT also push the qualified selector into
          # ``extraNameSelectors``: the path-with-fragment form already
          # selects the action by name; a duplicate selector would
          # trigger the lowering pass's name-resolver on the SIBLING
          # project's export table (which would also work, but in
          # ``--list-targets``-style invocations we want exactly one
          # selector per action).
          continue
        else:
          # A second cross-project anchor isn't supported in the same
          # invocation today; the engine still loads one project per
          # ``repro build`` run. Surface the same diagnostic shape as
          # the multi-path-anchor case so the user knows to split it.
          raise newException(ValueError,
            command & ": multiple project anchors are not supported " &
              "in one invocation (got '" & result.target & "' and " &
              "cross-project selector '" & sel & "'); run two builds")
      # Fall through to the in-project name-selector handling — a
      # qualified selector without a matching sibling still routes
      # through the existing same-project resolver, which lets the
      # spec's same-project ``<package>:<name>`` disambiguator keep
      # working unchanged.
      if not anchorSet and firstNameSelector.len == 0:
        firstNameSelector = sel
      else:
        if result.extraNameSelectors.find(sel) < 0:
          result.extraNameSelectors.add(sel)
    of bskName:
      if not anchorSet and firstNameSelector.len == 0:
        firstNameSelector = sel
      else:
        if result.extraNameSelectors.find(sel) < 0:
          result.extraNameSelectors.add(sel)
  if not anchorSet:
    # All selectors are name-shaped. Anchor at the current directory
    # and let ``parseBuildTarget`` route the first name through the
    # fragment / action-selection codepath. Remaining names go into
    # ``extraNameSelectors`` so the lowering pass takes their union.
    if firstNameSelector.len > 0:
      result.target = "." & "#" & firstNameSelector
    else:
      result.target = "."
  elif firstNameSelector.len > 0 and
      result.extraNameSelectors.find(firstNameSelector) < 0:
    # Path anchor + name selectors: the path is the project root, and
    # every name selector contributes its closure on top.
    result.extraNameSelectors.add(firstNameSelector)

proc scopedWorktreeRoot(modulePath, explicitWorkRoot: string): string =
  let workRoot = configuredWorkRoot(explicitWorkRoot)
  if workRoot.len == 0:
    return ""
  let base =
    if workRoot.isAbsolute:
      os.normalizedPath(workRoot)
    else:
      os.normalizedPath(absolutePath(workRoot))
  let projectRoot = os.normalizedPath(parentDir(absolutePath(modulePath)))
  let (_, tail) = splitPath(projectRoot)
  let hash = digestHex(blake3DomainDigest(projectRoot.bytesOf(),
    hdMetadataEnvelope))
  # The worktree dir name combines the project tail (for debuggability)
  # and a 16-char content-hash (for identity). When the resulting full
  # path approaches Windows' MAX_PATH (260 chars) the host's underlying
  # tools — notably nim's own stdlib used by the provider compile —
  # fail with ERROR_FILENAME_EXCED_RANGE since they don't transparently
  # prefix `\\?\` for every OS call. Detect that and fall back to the
  # bare hash; we lose a small amount of debuggability but the build
  # stays correct. The threshold leaves room for the tail of the path
  # the engine adds inside the worktree
  # (`/build/<outputName>/provider/project-provider.exe` ≈ 60 chars).
  const reservedTailChars = 80
  let tailSegment = safePathSegment(tail, "worktree")
  let combined = tailSegment & "-" & hash[0 .. 15]
  let baseLen = base.len + "/worktrees/".len
  let segment =
    if baseLen + combined.len + reservedTailChars > 260:
      hash[0 .. 15]
    else:
      combined
  base / "worktrees" / segment

proc outputDirForTarget(target: ParsedBuildTarget;
    explicitWorkRoot = ""): string =
  let scopedRoot = scopedWorktreeRoot(target.modulePath, explicitWorkRoot)
  if scopedRoot.len > 0:
    return scopedRoot / "build" / target.outputName
  parentDir(target.modulePath) / ".repro" / "build" / target.outputName

const DefaultBuildActionMetadataName = "reprobuild.default-build-action.v1"

proc q(value: string): string =
  quoteShell(value)

proc shellCommand(args: openArray[string]): string =
  args.mapIt(q(it)).join(" ")

proc projectRootForModule(modulePath: string): string =
  parentDir(modulePath)

type
  CmakeRegenerationMetadata = object
    enabled: bool
    suppressed: bool
    metadataFile: string
    sourceDir: string
    binaryDir: string
    providerRoot: string
    cmakeCommand: string
    checkFile: string
    globVerifyScript: string
    providerFile: string
    providerStateFile: string
    values: Table[string, string]

proc readKeyValueMetadata(path: string): Table[string, string] =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return
  for rawLine in readFile(extendedPath(path)).splitLines():
    let line = rawLine.strip()
    if line.len == 0 or line.startsWith("#"):
      continue
    let eq = line.find('=')
    if eq <= 0:
      continue
    result[line[0 ..< eq]] = line[eq + 1 .. ^1]

proc metadataValue(values: Table[string, string]; key: string;
                   fallback = ""): string =
  values.getOrDefault(key, fallback)

proc metadataFlag(values: Table[string, string]; key: string): bool =
  case values.getOrDefault(key, "").toLowerAscii()
  of "1", "on", "true", "yes", "enabled":
    true
  else:
    false

proc materializeCmakePath(meta: CmakeRegenerationMetadata;
                          path: string): string =
  if path.len == 0:
    return ""
  if path.isAbsolute:
    os.normalizedPath(path)
  else:
    os.normalizedPath(meta.binaryDir / path)

proc parseCmakeQuotedList(text, setName: string): seq[string] =
  var parsed: seq[string] = @[]
  var inSet = false
  var token = ""
  var inQuote = false
  var escaping = false

  proc finishToken() =
    if token.len > 0:
      parsed.add(token)
      token.setLen(0)

  for rawLine in text.splitLines():
    var line = rawLine.strip()
    if not inSet:
      if line == "set(" & setName:
        inSet = true
        continue
      if line.startsWith("set(" & setName & " "):
        inSet = true
        line = line.substr(("set(" & setName).len).strip()
      else:
        continue

    var i = 0
    while i < line.len:
      let ch = line[i]
      if inQuote:
        if escaping:
          token.add(ch)
          escaping = false
        elif ch == '\\':
          escaping = true
        elif ch == '"':
          inQuote = false
          finishToken()
        else:
          token.add(ch)
      else:
        case ch
        of '"':
          inQuote = true
        of ')':
          finishToken()
          return parsed
        of ' ', '\t':
          finishToken()
        else:
          token.add(ch)
      inc i
    if not inQuote:
      finishToken()
  parsed

proc parseCmakeListFromFile(path, setName: string): seq[string] =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return
  parseCmakeQuotedList(readFile(extendedPath(path)), setName)

proc addUniquePath(paths: var seq[string]; path: string) =
  if path.len == 0:
    return
  let normalized = os.normalizedPath(path)
  if paths.find(normalized) < 0:
    paths.add(normalized)

proc cmakeRegenerationMetadataForModule(modulePath: string):
    CmakeRegenerationMetadata =
  let binaryDir = parentDir(modulePath)
  let metadataFile = binaryDir / "CMakeFiles" / "reprobuild" / "provider.meta"
  let values = readKeyValueMetadata(metadataFile)
  if values.len == 0 or values.metadataValue("generator") != "Reprobuild":
    return
  let sourceDir = values.metadataValue("source_dir")
  if sourceDir.len == 0:
    return
  result.values = values
  result.metadataFile = metadataFile
  result.sourceDir = os.normalizedPath(sourceDir)
  result.binaryDir = os.normalizedPath(values.metadataValue("binary_dir",
    binaryDir))
  result.providerRoot = os.normalizedPath(values.metadataValue("provider_root",
    result.binaryDir / "CMakeFiles" / "reprobuild"))
  result.cmakeCommand = values.metadataValue("cmake_command", "cmake")
  result.checkFile = values.metadataValue("cmake_regeneration_check_file",
    "CMakeFiles/Makefile.cmake")
  result.globVerifyScript = values.metadataValue(
    "cmake_regeneration_glob_verify",
    result.binaryDir / "CMakeFiles" / "VerifyGlobs.cmake")
  result.providerFile = values.metadataValue("cmake_regeneration_provider_file",
    result.binaryDir / "reprobuild.nim")
  result.providerStateFile = values.metadataValue(
    "cmake_regeneration_provider_state",
    result.providerRoot / "provider.last")
  result.suppressed = values.metadataFlag("cmake_regeneration_suppressed")
  result.enabled =
    not result.suppressed and
    values.metadataValue("cmake_regeneration", "enabled") != "disabled"

proc cmakeRegenerationInputs(meta: CmakeRegenerationMetadata;
                             publicCliPath: string): seq[string] =
  result.addUniquePath(meta.metadataFile)
  if publicCliPath.len > 0 and fileExists(extendedPath(publicCliPath)):
    result.addUniquePath(publicCliPath)
  if meta.cmakeCommand.isAbsolute and fileExists(extendedPath(meta.cmakeCommand)):
    result.addUniquePath(meta.cmakeCommand)
  let checkPath = meta.materializeCmakePath(meta.checkFile)
  result.addUniquePath(checkPath)
  result.addUniquePath(meta.binaryDir / "CMakeCache.txt")
  result.addUniquePath(meta.binaryDir / "CMakeFiles" / "cmake.check_cache")
  if meta.globVerifyScript.len > 0 and fileExists(extendedPath(meta.globVerifyScript)):
    result.addUniquePath(meta.globVerifyScript)
  for input in parseCmakeListFromFile(checkPath, "CMAKE_MAKEFILE_DEPENDS"):
    result.addUniquePath(meta.materializeCmakePath(input))

proc cmakeRegenerationHasGlobVerification(meta: CmakeRegenerationMetadata): bool =
  meta.globVerifyScript.len > 0 and fileExists(extendedPath(meta.globVerifyScript))

proc cmakeRegenerationOutputs(meta: CmakeRegenerationMetadata): seq[string] =
  result.addUniquePath(meta.providerFile)
  result.addUniquePath(meta.providerStateFile)
  if meta.cmakeRegenerationHasGlobVerification():
    # CMake's VerifyGlobs.cmake detects directory membership changes by
    # touching an empty marker. The action cache is content-based, so glob
    # projects must execute this edge until glob membership evidence is modeled.
    result.addUniquePath(meta.providerRoot /
      "cmake-regeneration-glob-always-run.sentinel")
  for key, value in meta.values:
    if key == "clean_manifest" or key.startsWith("clean_manifest_") or
        key == "hcr_metadata":
      result.addUniquePath(value)

proc cmakeRegenerationDepfile(meta: CmakeRegenerationMetadata): string =
  meta.providerRoot / "cmake-regeneration.d"

proc makeDepPath(path: string): string =
  for ch in path:
    case ch
    of ' ', '\t', ':', '\\', '#', '$':
      result.add('\\')
      result.add(ch)
    else:
      result.add(ch)

proc writeMakeDepfile(path: string; outputs, inputs: openArray[string]) =
  if path.len == 0:
    return
  createDir(extendedPath(path.parentDir))
  var text = ""
  for i, output in outputs:
    if i > 0:
      text.add(' ')
    text.add(makeDepPath(output))
  text.add(":")
  for input in inputs:
    text.add(' ')
    text.add(makeDepPath(input))
  text.add('\n')
  writeFile(extendedPath(path), text)

proc requiredMakeDepfilePolicy(path: string): DependencyGatheringPolicy =
  DependencyGatheringPolicy(
    kind: dgRecognizedFormat,
    completeness: decComplete,
    recognizedReports: @[
      RecognizedDependencyReportSpec(
        formatName: DependencyFormatName(MakeDepfileFormatName),
        outputs: @[
          ExpectedDependencyFile(
            logicalName: "deps",
            path: path,
            required: true)
        ],
        completeness: decComplete)
    ])

proc addCmakeFingerprintField(payload: var string; value: string) =
  payload.add($value.len)
  payload.add(":")
  payload.add(value)
  payload.add("\n")

proc cmakeRegenerationFingerprint(meta: CmakeRegenerationMetadata;
                                  publicCliPath: string):
    ContentDigest =
  var payload = ""
  payload.addCmakeFingerprintField("reprobuild.cmake.regeneration.v1")
  payload.addCmakeFingerprintField(publicCliPath)
  payload.addCmakeFingerprintField(meta.cmakeCommand)
  payload.addCmakeFingerprintField(meta.sourceDir)
  payload.addCmakeFingerprintField(meta.binaryDir)
  payload.addCmakeFingerprintField(meta.checkFile)
  payload.addCmakeFingerprintField(meta.globVerifyScript)
  payload.addCmakeFingerprintField(meta.providerFile)
  payload.addCmakeFingerprintField(meta.providerStateFile)
  weakFingerprintFromText(payload)

const ActionPathPassthrough = ["PATH"]
  ## The environment variables an action's `PATH` composition takes from
  ## the HOST. Declared beside `actionPathEntry` below, and used by every
  ## lowering site that calls it, so the two can never drift apart: a
  ## site that composes a host value without saying so is exactly the
  ## defect this pair exists to prevent.
  ##
  ## ## THE CLASSIFICATION RULE
  ##
  ## An action's declared environment mixes two very different kinds of
  ## value, and which class a variable belongs in is decided by WHERE
  ## THE LOWERING GOT IT, not by what it looks like:
  ##
  ## * **Obtained by reading the ambient environment** (`getEnv`) or by
  ##   probing the host filesystem — PASSTHROUGH. The value is a fact
  ##   about this machine, it does not determine what the action
  ##   computes, and pinning it would key every edge to one host.
  ##   `PATH` and `REPROBUILD_SOURCE_ROOT` are the two.
  ##
  ## * **Obtained from the solved graph** — DECLARED, by value. These
  ##   look host-absolute and are not: `DEP_NIM_ROOT`, `BEARSSL_SRC`,
  ##   `OUT_MIRROR` and the rest of the `DEP_*_ROOT` / `*_SRC` family
  ##   are `/nix/store` paths, but they are *package identities*. A
  ##   different `DEP_NIM_ROOT` is a different compiler, and an action
  ##   built against it really is a different action. Excluding them
  ##   would be a stale-serve hole, not a portability win.
  ##
  ## Two consequences worth being explicit about, because they are the
  ## first things a reader will suspect are oversights:
  ##
  ## 1. Those fifteen `/nix/store` values are in every key BY VALUE.
  ##    That is deliberate under the rule above, and it is also NOT a
  ##    change: they arrive through the DSL's `extraEnv`, which
  ##    `encodeBuildActionPayload` has serialised since v14 and which
  ##    every lowering site already folds into its fingerprint text via
  ##    `node.payload`. Keying the environment admitted no new value to
  ##    any key — every value now in a key was already in one.
  ##
  ## 2. It DOES make those keys non-portable across machines, which is
  ##    the same complaint `repro_build_engine.nim`'s shim-library seed
  ##    answers differently: it keeps the machine-specific
  ##    `REPRO_MONITOR_SHIM_LIB` out of `action.env` entirely, injecting
  ##    it at launch. That is consistent with the rule, not in conflict
  ##    with it — the shim path is a host probe, not a solved-graph
  ##    identity, so it is in the first class. Making the solved-graph
  ##    values portable is content-addressing work, not a reason to
  ##    reclassify them.
  ##
  ## ## Applied unconditionally, and what that costs
  ##
  ## Every lowering site that composes a `PATH` passes this whole list;
  ## there is no per-variable opt-in and no way for a recipe to ask for
  ## `PATH` to be keyed by value. The price is real and one-directional:
  ## a recipe that overrides `PATH` explicitly through `extraEnv` gets
  ## that override applied to the process (it is appended after the
  ## prefix and wins) but NOT reflected in the key, so two recipes
  ## differing only in an explicit `extraEnv` `PATH` share a cache
  ## entry. This is most reachable on inline-exec edges, which carry no
  ## `profile.profileFingerprint` to distinguish them by other means.
  ## BuildXL has the same behaviour for the same reason — a passthrough
  ## variable's value is untracked even when the build sets it — but
  ## BuildXL lets a spec choose per variable and this does not.

proc actionPathEntry(actionPathPrefix: string): string =
  ## The action's `PATH`: the resolved tool directories this edge
  ## declares, then whatever the host has.
  ##
  ## ## The `getEnv` here is deliberate, and it is not in a cache key
  ##
  ## Every caller pairs this with `envPassthrough =
  ## ActionPathPassthrough`, which puts `PATH` in BuildXL's passthrough
  ## class: `keyedOnActionEnvironment` records the NAME and refuses the
  ## VALUE. So the host's `PATH` cannot reach a cache record, which is
  ## the property that matters — PR #96's `NIX_STORE_DIR` defect was an
  ## ambient value entering a record permanently because a key
  ## computation read the environment.
  ##
  ## Keying on this value instead would be a much larger defect than the
  ## one it appears to fix. The prefix is absolute store paths and the
  ## tail is the host's `PATH`; neither is the same under `nix develop`
  ## as in CI. Every edge of every graph would invalidate on any host
  ## difference. BuildXL reaches the same conclusion twice over: `PATH`
  ## is one of its untracked base variables
  ## (`PipEnvironment.cs:88-110`), and a passthrough variable's value is
  ## not fingerprinted even when the build declares it explicitly
  ## (`Build-Parameters-(Environment-variables).md:39`).
  ##
  ## What this does NOT recover is the PREFIX's contribution: the
  ## resolved tool directories are also excluded, because they are
  ## host-absolute for the same reason. For typed-tool edges the tool
  ## identity is already keyed through `profile.profileFingerprint`.
  ## For inline-exec edges it is not yet, and making it so needs the
  ## portable-key work, not a raw path in a key.
  "PATH=" & actionPathPrefix & $PathSep & getEnv("PATH")

proc cmakeRegenerationBuildAction(meta: CmakeRegenerationMetadata;
                                  publicCliPath: string): BuildAction =
  # CMake may invoke ``repro build --prepare-only`` while regenerating.
  # Keep that provider-priming call in the current process tree instead of
  # handing a transient CMake binary dir to a second daemon session.
  var env: seq[string] = @["REPRO_DAEMON=off"]
  # The FOURTH lowering site, and the one that makes the rule worth
  # stating as a rule: this edge composes its environment by hand, ~400
  # lines away from the three that go through `lowerGraphAction`, and a
  # sweep of "the lowering sites" missed it. Both values below are
  # obtained by reading the ambient environment, so both are
  # PASSTHROUGH — see `ActionPathPassthrough` for the classification
  # rule and why keying them by value would be the very defect the
  # passthrough class exists to prevent.
  var envPassthrough: seq[string] = @[]
  if meta.providerRoot.len > 0:
    let wrapperPath = meta.values.metadataValue("wrapper_path",
      meta.providerRoot / "bin")
    if wrapperPath.len > 0:
      env.add(actionPathEntry(wrapperPath))
      envPassthrough.add("PATH")
  let sourceRoot = getEnv("REPROBUILD_SOURCE_ROOT")
  if sourceRoot.len > 0:
    # A machine-specific absolute path read straight from the host, and
    # the exact shape `repro_build_engine.nim`'s shim-library seed
    # refuses to put in `action.env` because it "would make the action
    # ID non-reproducible across machines". Passthrough records that
    # this edge reads it without pinning one machine's answer.
    env.add("REPROBUILD_SOURCE_ROOT=" & sourceRoot)
    envPassthrough.add("REPROBUILD_SOURCE_ROOT")
  let depfilePath = cmakeRegenerationDepfile(meta)
  let hasGlobVerification = meta.cmakeRegenerationHasGlobVerification()
  action("__repro_cmake_regenerate", @[
    publicCliPath,
    "__repro-cmake-regenerate",
    "--metadata", meta.metadataFile,
    "--public-cli", publicCliPath,
    "--depfile", depfilePath
  ],
    # Named-Lock-Files §7.2. CMake regeneration re-runs the generator over
    # recorded metadata; no solved package instance reaches it. See
    # `lockIdentityOutsideSolvedGraph`.
    governingLockIdentity = lockIdentityOutsideSolvedGraph(),
    cwd = meta.binaryDir,
    inputs = cmakeRegenerationInputs(meta, publicCliPath),
    outputs = cmakeRegenerationOutputs(meta),
    commandStatsId = "repro cmake regeneration edge",
    cacheable = not hasGlobVerification,
    weakFingerprint = cmakeRegenerationFingerprint(meta, publicCliPath),
    depfile = depfilePath,
    dependencyPolicy = requiredMakeDepfilePolicy(depfilePath),
    env = env,
    envPassthrough = envPassthrough)

proc prependProcessPath(path: string) =
  if path.len == 0:
    return
  let normalized = os.normalizedPath(path)
  let current = getEnv("PATH")
  for item in current.split(PathSep):
    if item.len > 0 and os.normalizedPath(item) == normalized:
      return
  if current.len > 0:
    putEnv("PATH", normalized & $PathSep & current)
  else:
    putEnv("PATH", normalized)

proc applyCmakeProviderEnvironment(meta: CmakeRegenerationMetadata) =
  if meta.values.len == 0:
    return
  prependProcessPath(meta.values.metadataValue("wrapper_path",
    meta.providerRoot / "bin"))

proc prependExplicitWorkRootToolPath(explicitWorkRoot: string) =
  let root = configuredWorkRoot(explicitWorkRoot)
  if root.len == 0:
    return
  let absRoot =
    if root.isAbsolute:
      os.normalizedPath(root)
    else:
      os.normalizedPath(absolutePath(root))
  let toolDir = absRoot / "bin"
  if dirExists(extendedPath(toolDir)):
    prependProcessPath(toolDir)

proc reprobuildLibraryWorkDir(): string =
  proc hasReprobuildLibs(root: string): bool =
    dirExists(extendedPath(root / "libs" / "repro_project_dsl" / "src"))

  let envRoot = getEnv("REPROBUILD_SOURCE_ROOT")
  if envRoot.len > 0 and hasReprobuildLibs(envRoot):
    return envRoot
  let cwd = getCurrentDir()
  if hasReprobuildLibs(cwd):
    return cwd
  var sourceRoot = parentDir(currentSourcePath())
  for _ in 0 ..< 3:
    sourceRoot = parentDir(sourceRoot)
  if hasReprobuildLibs(sourceRoot):
    return sourceRoot
  cwd

proc resolveMonitorShimLibPath(): string =
  ## Develop-mode improvement: locate ``librepro_monitor_shim.{dll,so,dylib}``
  ## without requiring the operator to set ``REPRO_MONITOR_SHIM_LIB`` by
  ## hand. Resolution order:
  ##
  ## 1. ``$REPRO_MONITOR_SHIM_LIB`` (operator override; legacy).
  ## 2. ``<repro binary's repo>/build/lib/librepro_monitor_shim.<ext>``
  ##    when the running ``repro`` lives inside a reprobuild source
  ##    checkout (the develop-mode default — equivalent to how the
  ##    sibling-repo path resolver in repro_interface_artifacts walks
  ##    up from ``getAppFilename()``).
  ## 3. ``$REPROBUILD_SOURCE_ROOT/build/lib/librepro_monitor_shim.<ext>``.
  ##    The daemon-hosted build path re-derives the build graph (including
  ##    the CMake regeneration edge) from a *staged* daemon binary whose
  ##    ``getAppFilename`` sits under the daemon state dir, not the source
  ##    checkout — so step (2) returns empty there. ``repro develop``
  ##    threads the user's checkout through ``REPROBUILD_SOURCE_ROOT`` (and
  ##    the daemon forwards it), so this fallback recovers the shim in the
  ##    daemon-hosted CMake develop flow.
  ## 4. Empty string when none match; the caller (the engine's monitor
  ##    launcher) treats that as "monitor not configured" and falls back
  ##    to ``REPRO_MONITOR_BYPASS=1`` semantics.
  let override = getEnv("REPRO_MONITOR_SHIM_LIB")
  if override.len > 0:
    return override
  const dllExt =
    when defined(windows): "dll"
    elif defined(macosx):  "dylib"
    else:                  "so"
  let exePath = getAppFilename()
  if exePath.len > 0:
    let localSourceRoot =
      reprobuildSourceRootFromBinaryLocation(exePath)
    let candidate =
      if localSourceRoot.len > 0:
        localSourceRoot / "build" / "lib" /
          ("librepro_monitor_shim." & dllExt)
      else:
        ""
    if candidate.len > 0 and fileExists(extendedPath(candidate)):
      if getEnv("REPROBUILD_SOURCE_ROOT").len == 0:
        putEnv("REPROBUILD_SOURCE_ROOT", localSourceRoot)
      return candidate
  let sourceRoot = getEnv("REPROBUILD_SOURCE_ROOT")
  if sourceRoot.len > 0:
    let candidate = sourceRoot / "build" / "lib" /
      ("librepro_monitor_shim." & dllExt)
    if fileExists(extendedPath(candidate)):
      return candidate
  ""

proc moduleHasBuildBlock(modulePath: string): bool =
  for line in readFile(extendedPath(modulePath)).splitLines:
    if line.strip() == "build:":
      return true

proc moduleHasDevEnvBlock(modulePath: string): bool =
  for line in readFile(extendedPath(modulePath)).splitLines:
    if line.strip() == "devEnv:":
      return true

proc materialProjectPath(projectRoot, path: string): string =
  if path.len == 0 or path.isAbsolute:
    path
  else:
    projectRoot / path

proc jsonStringSeq(values: openArray[string]): JsonNode =
  result = newJArray()
  for value in values:
    result.add(%value)

proc capabilitiesJson*(): JsonNode =
  var query = newJObject()
  query["command"] = %"repro capabilities"
  query["defaultFormat"] = %"json"
  query["formats"] = jsonStringSeq(["json", "text"])
  query["schemaId"] = %"reprobuild.capabilities.v1"

  var provider = newJObject()
  provider["metadataVersion"] = %3
  provider["generatedProviderKind"] = %"nim-source"
  provider["features"] = jsonStringSeq([
    "public-target-aliases",
    "default-target-metadata",
    "build-pool-metadata",
    "compile-commands",
    "declared-inputs-and-outputs",
    "depfile-dependency-evidence",
    "dyndep-fragment-conversion",
    "runquota-execution",
    "cmake-regeneration-edge",
    "provider-cache-priming",
    "build-report-json-inspection"])

  var hcrProfile = newJObject()
  hcrProfile["id"] = %"clang-gcc-debug-patchable-no-lto-v1"
  hcrProfile["status"] = %"prototype"
  hcrProfile["languages"] = jsonStringSeq(["C", "CXX"])
  hcrProfile["requires"] = jsonStringSeq([
    "debug-info",
    "patchable-function-entry",
    "relocatable-object-inputs",
    "source-object-link-relations",
    "linkgraph-evidence"])
  hcrProfile["rejects"] = jsonStringSeq([
    "lto",
    "interprocedural-optimization",
    "unsupported-asm-sources",
    "missing-debug-info"])
  var hcrProfiles = newJArray()
  hcrProfiles.add(hcrProfile)
  var codetracerProfile = newJObject()
  codetracerProfile["id"] = %"macos-arm64-direct-hcr-in-codetracer-v1"
  codetracerProfile["status"] = %"prototype"
  codetracerProfile["languages"] = jsonStringSeq(["C", "CXX"])
  codetracerProfile["requires"] = jsonStringSeq([
    "hcr-agent-protocol",
    "coordinator-agent-negotiation",
    "direct-patch-injection",
    "debug-object-payloads",
    "unwind-metadata-payloads",
    "source-generation-metadata",
    "codetracer-owned-launch",
    "mcr-recorded-agent-ipc"])
  codetracerProfile["features"] = jsonStringSeq([
    "hcr-agent-content-length-framing",
    "coordinator-agent-session-validation",
    "coordinator-direct-patch-request-packaging",
    "unix-domain-agent-ipc",
    "agent-socket-env-contract",
    "coordinator-report-json",
    "target-linked-c-agent-startup",
    "repro-hcr-coordinate-command",
    "codetracer-mcr-launch-bridge"])
  codetracerProfile["missingComponents"] = jsonStringSeq([])
  codetracerProfile["rejects"] = jsonStringSeq([
    "post-launch-attach",
    "same-process-direct-transaction-shortcut",
    "stdin-pipe-patch-substitute",
    "shared-library-positive-path",
    "coordinator-resend-during-replay",
    "disassembly-only-debugging"])
  hcrProfiles.add(codetracerProfile)

  var hcr = newJObject()
  hcr["decisionAuthority"] = %"reprobuild"
  hcr["buildSystemRole"] = %(
    "annotate candidate targets and static source/object/link relations")
  hcr["runtimeDecisions"] = jsonStringSeq([
    "rebuilt-actions",
    "changed-outputs",
    "affected-link-targets",
    "patchability",
    "reload-vs-restart"])
  hcr["candidateAnnotations"] = jsonStringSeq([
    "target-identity",
    "source-to-object-action",
    "object-to-link-action",
    "link-output",
    "linkgraph-action",
    "support-profile"])
  hcr["profiles"] = hcrProfiles

  var execution = newJObject()
  execution["scheduler"] = %"local"
  execution["runQuota"] = %"supported"
  execution["reports"] = jsonStringSeq(["build-report.json"])

  var interfaces = newJObject()
  interfaces["capabilityQuery"] = query
  interfaces["provider"] = provider
  interfaces["execution"] = execution
  interfaces["hcr"] = hcr

  result = newJObject()
  result["schemaId"] = %"reprobuild.capabilities.v1"
  result["reprobuildVersion"] = %versionString()
  result["host"] = %*{
    "os": hostOS,
    "cpu": hostCPU
  }
  result["interfaces"] = interfaces

proc renderCapabilitiesJson*(): string =
  capabilitiesJson().pretty()

proc renderCapabilitiesText*(): string =
  let caps = capabilitiesJson()
  "schemaId: " & caps["schemaId"].getStr() & "\n" &
    "reprobuildVersion: " & caps["reprobuildVersion"].getStr() & "\n" &
    "capabilityQuery: " &
      caps["interfaces"]["capabilityQuery"]["command"].getStr() & "\n" &
    "providerMetadataVersion: " &
      $caps["interfaces"]["provider"]["metadataVersion"].getInt() & "\n" &
    "hcrDecisionAuthority: " &
      caps["interfaces"]["hcr"]["decisionAuthority"].getStr()

proc runConfigsCommand(args: openArray[string]): int =
  ## List the recognized standard build configurations and the currently
  ## selected ``buildType`` (Standard-Configurations.md). A "configuration"
  ## is a value of the conventional ``buildType`` variant axis; the
  ## ``--release`` / ``--debug`` flags are sugar for
  ## ``--variant buildType=<config>``.
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--help" or arg == "-h":
      echo "usage: repro configs"
      echo "List the recognized standard build configurations " &
        "(values of the buildType variant axis)."
      return 0
    else:
      raise newException(ValueError, "unsupported configs argument: " & arg)
    inc i
  var current = "debug"
  for assignment in getEnv("REPRO_VARIANTS").split(','):
    let kv = assignment.split('=', 1)
    if kv.len == 2 and kv[0].strip == "buildType":
      current = kv[1].strip
  echo "Standard configurations (values of the `buildType` variant axis):"
  echo "  debug           development build (default)"
  echo "  release         optimized build  (shorthand: --release)"
  echo "  relWithDebInfo  optimized build with debug info"
  echo "  minSizeRel      size-optimized build"
  echo ""
  echo "current buildType: " & current
  echo "select with: repro build --release   " &
    "(or --variant buildType=<value>)"
  0

proc runCapabilitiesCommand(args: openArray[string]): int =
  var format = "json"
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--help" or arg == "-h":
      echo "usage: repro capabilities [--format=json|text]"
      return 0
    elif arg == "--format":
      if i + 1 >= args.len:
        raise newException(ValueError, "--format requires json or text")
      format = args[i + 1]
      inc i
    elif arg.startsWith("--format="):
      format = arg["--format=".len .. ^1]
    else:
      raise newException(ValueError, "unsupported capabilities argument: " & arg)
    inc i

  case format
  of "json":
    echo renderCapabilitiesJson()
  of "text":
    echo renderCapabilitiesText()
  else:
    raise newException(ValueError, "unsupported --format=" & format)
  0

proc profileIndex(identity: PathOnlyBuildIdentity):
    Table[string, PathOnlyToolProfile] =
  for profile in identity.profiles:
    result[profile.packageSelector & "|" & profile.executableName] = profile
    if not result.hasKey(profile.executableName):
      result[profile.executableName] = profile

proc bareToolSelector(value: string): string =
  result = value
  for i, ch in result:
    if ch == ' ' or ch in {'>', '<', '=', '~', '^'}:
      result = result[0 ..< i]
      break

proc toolPathPrefix(profiles: Table[string, PathOnlyToolProfile];
                    packageName, executableName: string;
                    refs: openArray[string]): string =
  var dirs: seq[string] = @[]
  proc addDir(profile: PathOnlyToolProfile) =
    let dir = parentDir(profile.resolvedExecutablePath)
    if dir.len > 0 and dirs.find(dir) < 0:
      dirs.add(dir)

  let exactKey = packageName & "|" & executableName
  if profiles.hasKey(exactKey):
    addDir(profiles[exactKey])
  elif profiles.hasKey(executableName):
    addDir(profiles[executableName])

  for refName in refs:
    var matchingDirs: seq[string] = @[]
    for profile in profiles.values:
      if profile.executableName != refName and
          bareToolSelector(profile.packageSelector) != refName:
        continue
      let dir = parentDir(profile.resolvedExecutablePath)
      if dir.len > 0 and dir notin matchingDirs:
        matchingDirs.add(dir)
    matchingDirs.sort()
    for dir in matchingDirs:
      if dir notin dirs:
        dirs.add(dir)
  dirs.join($PathSep)

proc scriptInterpreterArgv(executablePath: string): seq[string] =
  ## Windows does not interpret shebangs before CreateProcessW. Lower a typed
  ## script tool to its declared interpreter while keeping native executables
  ## and every non-Windows invocation unchanged.
  when defined(windows):
    if not fileExists(extendedPath(executablePath)):
      return
    var executableFile: File
    if not open(executableFile, extendedPath(executablePath), fmRead):
      return
    defer:
      executableFile.close()
    var marker: array[2, char]
    if executableFile.readBuffer(addr marker[0], marker.len) != marker.len or
        marker != ['#', '!']:
      return
    var firstLine = ""
    if not executableFile.readLine(firstLine):
      return
    let fields = firstLine.strip().splitWhitespace()
    if fields.len == 0:
      return
    let normalizedInterpreter = fields[0].replace('\\', '/')
    if normalizedInterpreter.endsWith("/env"):
      var firstCommandArg = 1
      if firstCommandArg < fields.len and fields[firstCommandArg] == "-S":
        inc firstCommandArg
      for i in firstCommandArg ..< fields.len:
        result.add(fields[i])
    else:
      if normalizedInterpreter.startsWith("/"):
        result.add(lastPathPart(normalizedInterpreter))
      else:
        result.add(fields[0])
      for i in 1 ..< fields.len:
        result.add(fields[i])

proc argvForCall*(call: PublicCliCall;
                  profile: PathOnlyToolProfile): seq[string] =
  result = scriptInterpreterArgv(profile.resolvedExecutablePath)
  result.add(profile.resolvedExecutablePath)

  proc encodedValues(arg: PublicCliArg): seq[string] =
    if arg.nimType.normalize == "seq[string]":
      if arg.encodedValue.len > 0:
        for item in arg.encodedValue.split("\x1f"):
          result.add(item)
    else:
      result.add(arg.encodedValue)

  proc addFormattedValue(outp: var seq[string]; flagName, value: string;
                         format: CliArgFormat) =
    case format
    of cafSeparate:
      outp.add(flagName)
      outp.add(value)
    of cafConcat:
      outp.add(flagName & value)
    of cafEquals:
      outp.add(flagName & "=" & value)

  proc addFlagArg(outp: var seq[string]; arg: PublicCliArg) =
    let flagName =
      if arg.alias.len > 0:
        arg.alias
      else:
        "--" & arg.name
    if arg.nimType.normalize == "bool":
      if arg.encodedValue.normalize == "true":
        outp.add(flagName)
      return
    let values = encodedValues(arg)
    if values.len == 0:
      return
    if arg.format == cafSeparate and not arg.repeated:
      outp.add(flagName)
      for value in values:
        outp.add(value)
    else:
      for value in values:
        outp.addFormattedValue(flagName, value, arg.format)

  proc addPositionalArg(outp: var seq[string]; arg: PublicCliArg) =
    for value in encodedValues(arg):
      outp.add(value)

  var beforeSubcommand: seq[PublicCliArg] = @[]
  var afterSubcommand: seq[PublicCliArg] = @[]
  var positional: seq[PublicCliArg] = @[]
  for arg in call.arguments:
    if arg.kind == cpkPositional:
      positional.add(arg)
      continue
    if arg.placement == capBeforeSubcommand:
      beforeSubcommand.add(arg)
    else:
      afterSubcommand.add(arg)

  for arg in beforeSubcommand:
    result.addFlagArg(arg)
  # CMake's typed API names its three invocation modes for fluent recipe
  # calls, but the real CLI encodes those modes entirely through flags:
  # configure uses -S/-B, while build/install use --build/--install.
  let hasLiteralSubcommand =
    not (call.packageName == "cmake" and
      call.executableName == "cmakeBin" and
      call.subcommand in ["configure", "build", "install"])
  if call.subcommand.len > 0 and hasLiteralSubcommand:
    result.add(call.subcommand)
  for arg in afterSubcommand:
    result.addFlagArg(arg)

  positional.sort do (a, b: PublicCliArg) -> int:
    cmp(a.position, b.position)
  for arg in positional:
    result.addPositionalArg(arg)

proc depfilePolicyMulti(paths: openArray[string]): DependencyGatheringPolicy =
  ## MR16: build a recognized-format policy from N depfile paths. Each
  ## path becomes one ``ExpectedDependencyFile`` on a single
  ## ``RecognizedDependencyReportSpec``. The engine's evidence reader
  ## walks every output and expands literal/glob paths at
  ## evidence-collection time. Empty input -> automatic-monitor
  ## fallback (matches the legacy single-path behavior on ``""``).
  if paths.len == 0:
    return repro_core.automaticMonitorGatheringPolicy()
  var outputs: seq[ExpectedDependencyFile] = @[]
  for path in paths:
    outputs.add(ExpectedDependencyFile(
      logicalName: "deps",
      path: path,
      required: false))
        # ``required = false`` because glob entries may legitimately
        # expand to zero files (e.g. cargo's debug/release split: only
        # one profile dir exists per build). The engine surfaces "no
        # depfile produced at all" as a missing-evidence diagnostic at
        # the aggregate-policy level, not per-path.
  DependencyGatheringPolicy(
    kind: dgRecognizedFormat,
    completeness: decComplete,
    recognizedReports: @[
      RecognizedDependencyReportSpec(
        formatName: DependencyFormatName(MakeDepfileFormatName),
        outputs: outputs,
        completeness: decComplete)
    ])

proc depfilePolicy(depfile: string): DependencyGatheringPolicy =
  if depfile.len == 0:
    return repro_core.automaticMonitorGatheringPolicy()
  depfilePolicyMulti([depfile])

proc lowerDependencyPolicy(actionId, depfile: string;
                           policy: BuildActionDependencyPolicy):
    DependencyGatheringPolicy =
  case policy.kind
  of bdpDefault:
    result = depfilePolicy(depfile)
  of bdpAutomaticMonitor:
    if depfile.len > 0:
      raise newException(ValueError,
        "action " & actionId & " supplies legacy depfile and " &
          "automatic monitor dependencyPolicy; remove depfile or use " &
          "makeDepfilePolicy")
    result = DependencyGatheringPolicy(kind: dgAutomaticMonitor,
        completeness: decComplete)
  of bdpTrustedDeclaredInputs:
    # HAZARDOUS, owner-authorized 2026-08-21. No monitor wrap and no result
    # processing: the author's inline list IS the evidence. ``decComplete``
    # keeps the edge cacheable, which is simultaneously the point of the
    # policy and its entire hazard, because nothing ever re-checks the list.
    # ``dgTrustedDeclaredInputs`` is deliberately absent from the engine's
    # ``MonitorPolicyKinds``, so ``monitoredAction`` returns early and no
    # ``LD_PRELOAD`` shim is injected.
    #
    # Guards are re-checked here, not only in the constructor, because a
    # policy can also arrive from a decoded payload.
    if policy.trustedInputs.len == 0:
      raise newException(ValueError,
        "action " & actionId & " uses trustedDeclaredInputsPolicy with an " &
          "empty input list; that would disable dependency tracking entirely")
    if policy.trustedReason.len == 0:
      raise newException(ValueError,
        "action " & actionId & " uses trustedDeclaredInputsPolicy without a " &
          "reason; the justification is surfaced in the build report")
    result = DependencyGatheringPolicy(
      kind: dgTrustedDeclaredInputs,
      completeness: decComplete)
  of bdpMakeDepfile:
    # MR16: ``policy.depfiles`` is the canonical multi-path list.
    # ``depfile`` (the per-action legacy single-path field) is merged
    # in so recipes that still set both keep working — duplicates are
    # filtered.
    var merged: seq[string] = @[]
    if depfile.len > 0:
      merged.add(depfile)
    for path in policy.depfiles:
      if path.len > 0 and path notin merged:
        merged.add(path)
    if merged.len == 0:
      raise newException(ValueError,
        "action " & actionId & " uses makeDepfilePolicy without a depfile path")
    result = depfilePolicyMulti(merged)
  result.ignoredInputPrefixes = policy.ignoredInputPrefixes

# ---------------------------------------------------------------------------
# Named-Lock-Files §3.1 / §7.2 — the workspace's governing lock identity
# ---------------------------------------------------------------------------

const CommittedLockFileNameForIdentity = "repro.lock"
  ## Deliberately a separate constant from `CommittedLockFileName`, which is
  ## declared thousands of lines below this point and cannot be forward-
  ## referenced. A drift guard asserts the two agree
  ## (`t_lock_identity_two_names_one_content` reads the real committed lock
  ## through this resolver, so a divergence fails a test rather than going
  ## unnoticed).

# Named-Lock-Files §3.1 — "The stdlib declares one well-known lock file,
# `default`." A workspace that declares nothing, binds nothing and passes
# nothing is governed by it.
#
# NLF-M8: this file used to declare its OWN `DefaultLockFileName` const
# alongside the one in `repro_lock_files/declarations.nim`. Both said
# `"default"`, so nothing was wrong — until a consumer imported both modules,
# at which point every mention of the name became an ambiguous identifier.
# Two definitions of one well-known name is the drift hazard §4.2 records for
# lock-file declarations themselves ("is that one lock file mentioned twice,
# or a conflict?"), so the declaration leaf owns it and this module
# re-exports.
export repro_lock_files.DefaultLockFileName

var lockProvenanceTable {.threadvar.}: LockProvenance
var lockProvenanceInit {.threadvar.}: bool

proc recordLockBinding*(name: string; identity: LockIdentity) =
  ## Record that lock-file name `name` resolved to `identity` (§6.3).
  ##
  ## The table is a SIDE table: nothing in this module composes a name with an
  ## identity to form a key, and `BuildAction.governingLockIdentity` carries
  ## the identity alone. §6.3: "maintained alongside the cache and never mixed
  ## into any key. Diagnostics read from it; identity does not."
  if not lockProvenanceInit:
    lockProvenanceTable = initLockProvenance()
    lockProvenanceInit = true
  lockProvenanceTable.recordBinding(identity, name)

proc lockProvenance*(): LockProvenance =
  ## The provenance side table as diagnostics see it.
  if not lockProvenanceInit:
    lockProvenanceTable = initLockProvenance()
    lockProvenanceInit = true
  lockProvenanceTable

var workspaceLockIdentityCache {.threadvar.}: Table[string, LockIdentity]
var workspaceLockIdentityCacheInit {.threadvar.}: bool

proc governingLockIdentityFor*(projectRoot, lockFileName: string):
    LockIdentity =
  ## The identity of the lock file NAMED `lockFileName` in `projectRoot`.
  ##
  ## Named-Lock-Files NLF-M8, folded from NLF-M7 — **`--lock <name>=<path>` is
  ## consumed per name by the build path.** M7 landed the flag's grammar, its
  ## validation, its errors and §5.3's resolution, and then this resolver read
  ## only `default`, so a binding for any other name parsed and governed
  ## nothing.
  ##
  ## The path comes from §5.3, in its order and with no fourth case:
  ##
  ##   1. an explicit `--lock <name>=<path>` binding for THIS invocation;
  ##   2. the declaration's committed `path =` field;
  ##   3. otherwise the workspace lock file — "and there is **no third case,
  ##      and in particular no error for an unbound lock file**".
  ##
  ## Steps 1 and 2 are `repro_lock_files.activeLockFilePath`; step 3 is the
  ## committed lock at the project root, which is the one thing that library
  ## cannot know and this one does. An invocation that binds nothing therefore
  ## resolves every name to exactly the file it resolved before NLF-M8, and
  ## every identity is byte-unchanged — NLF-STAT-4's requirement, restated at
  ## the resolver.
  ##
  ## Named-Lock-Files §3.1: a workspace that declares no lock files has
  ## exactly one — `default` — and it governs everything, "precisely the
  ## behaviour specified in §2.1: one workspace lock file, committed, unifying
  ## versions **and** variants across every package in the workspace".
  ##
  ## The identity is content-derived (§6.2) from the committed lock's SOLVED
  ## GRAPH. Two consequences worth stating because they are the properties
  ## corpus cases NLF-ID-1/2 test:
  ##
  ##   * the lock's *path* and any *name* bound to it are not inputs, so
  ##     renaming a binding invalidates nothing;
  ##   * two workspaces whose committed locks resolve to the same graph share
  ##     one identity, which is sharing and not a collision (§6.3).
  ##
  ## **This reads the lock; it never solves.** Lowering a graph must not
  ## invoke clingo — `Core-Invariants.md` §"Static Metadata Is The Hot Path"
  ## requires ordinary operations to be answerable from lock files, and a
  ## per-action solve would reintroduce §1.1's curve at a new site. When no
  ## committed lock exists there is no solved graph to be governed by, and the
  ## edges say so explicitly via `lockIdentityOutsideSolvedGraph`.
  ##
  ## Memoised per project root: `lowerGraphAction` runs once per edge and a
  ## large graph has thousands.
  if not workspaceLockIdentityCacheInit:
    workspaceLockIdentityCache = initTable[string, LockIdentity]()
    workspaceLockIdentityCacheInit = true
  let name =
    if lockFileName.len > 0: lockFileName else: DefaultLockFileName
  # §5.3 steps 1 and 2. Empty means "no explicit path", which is step 3.
  let bound = activeLockFilePath(name)
  let lockPath =
    if bound.len > 0: absolutePath(bound)
    else: projectRoot / CommittedLockFileNameForIdentity
  # The memo is keyed on the RESOLVED PATH as well as the name, so a second
  # invocation in one process (which is what a test is) cannot be served the
  # first one's answer for a binding it changed. Keying on the name alone
  # would make the cache a place where a stale identity survives a rebinding,
  # and a stale governing identity is a wrong cache key, not a slow one.
  let cacheKey = projectRoot & "\x1f" & name & "\x1f" & lockPath
  if workspaceLockIdentityCache.hasKey(cacheKey):
    return workspaceLockIdentityCache[cacheKey]
  var identity = lockIdentityOutsideSolvedGraph()
  if fileExists(extendedPath(lockPath)):
    try:
      identity = lockIdentityOf(
        parseSolvedGraphLock(readFile(extendedPath(lockPath))))
    except CatchableError:
      # A malformed or wrong-schema lock is diagnosed loudly by the build
      # path's own reader (`resolveSolvedGraphForBuild`), which runs before
      # any edge executes. Swallowing it HERE and reporting the
      # outside-the-solved-graph identity keeps one diagnostic instead of
      # two, and cannot mask the failure: the build still stops.
      identity = lockIdentityOutsideSolvedGraph()
  workspaceLockIdentityCache[cacheKey] = identity
  # Named-Lock-Files §6.3: record the binding in the provenance side table,
  # under the NAME that was resolved. Two names bound to one file resolve to
  # one identity and both are recorded against it, which §6.3 calls sharing
  # rather than a collision — and it is what lets `repro why` answer "which
  # lock file governs this edge" with every name that does.
  recordLockBinding(name, identity)
  identity

proc workspaceGoverningLockIdentity*(projectRoot: string): LockIdentity =
  ## The identity governing an edge that designated nothing — §4.3's final
  ## rung, which is `default`.
  ##
  ## **Stated bound, because it is the honest half of the criterion above.**
  ## A designation made in a recipe (`lockFile hostTools` on an artifact, or a
  ## `withLockFile` region) does not reach this call site today: the lowered
  ## graph the CLI receives over the provider protocol carries no per-edge
  ## lock-file name, so the CLI cannot ask for one. `governingLockIdentityFor`
  ## resolves whatever name it is given, and the remaining work is
  ## transporting the name — a protocol and codec change, not a resolution
  ## one.
  governingLockIdentityFor(projectRoot, DefaultLockFileName)

proc noScheduledAction*(): BuildAction =
  ## A `BuildAction` value for a slot that carries NO scheduled edge — the
  ## `action` half of a `(hasAction: false, action: …)` tuple, never read.
  ##
  ## Named-Lock-Files §7.2 makes `governingLockIdentity` non-optional, which
  ## removes `BuildAction()` as a spelling for "nothing here". Rather than let
  ## each such site invent a value, they share this one and its name says what
  ## it is. Constructed through `builtinAction` so it goes down the same
  ## required-field path as every other action; the `bakStamp` kind and the
  ## sentinel id make it obvious in a debugger if one ever escapes.
  builtinAction(bakStamp, "__repro_no_scheduled_action",
    cacheable = false,
    governingLockIdentity = lockIdentityOutsideSolvedGraph())

proc resolveCanonicalExecRoot*(cwdKind: ActionCwdKind; cwdCustomPath: string;
                               projectRoot: string): string =
  ## M9.R.74 — canonical execution root (R2) resolver.
  ##
  ## Maps a ``(cwdKind, cwdCustomPath)`` declaration to the absolute
  ## path the engine sets on the spawned action's ``BuildAction.cwd``.
  ##
  ## Resolution rules:
  ##
  ## * ``acwdRecipeRoot`` — return ``projectRoot``. This matches the
  ##   pre-M9.R.74 hardcoded ``cwd = projectRoot`` behaviour on every
  ##   non-``inlineExecCall`` branch of ``lowerGraphAction`` so
  ##   legacy actions get byte-identical spawn-time CWDs.
  ##
  ## * ``acwdSource`` / ``acwdBuild`` / ``acwdInstall`` — use
  ##   ``cwdCustomPath`` when non-empty (the convention emitter is
  ##   expected to supply the path it computed via
  ##   ``fetchExtractedRoot`` / ``buildDir`` / ``destdir`` at emit
  ##   time). When empty, fall back to ``projectRoot`` so an
  ##   improperly-declared kind cannot silently break execution.
  ##   The kind is preserved through the payload for
  ##   Filesystem-Policy-And-Observed-Inputs.md §"Read-Only Versus
  ##   Writable Roots" classification but resolution collapses to
  ##   ``cwdCustomPath`` today.
  ##
  ## * ``acwdCustom`` — use ``cwdCustomPath`` when non-empty. Empty
  ##   reduces to ``projectRoot`` — matching the pre-M9.R.74
  ##   behaviour of ``inlineExecCall(argv, cwd = "")``.
  ##
  ## Relative paths in ``cwdCustomPath`` are resolved against
  ## ``projectRoot`` to keep the recipe-side declaration convenient
  ## (``cwdCustomPath = "build"`` means ``<projectRoot>/build``, not
  ## the CLI's own cwd).
  let raw =
    case cwdKind
    of acwdRecipeRoot:
      projectRoot
    of acwdSource, acwdBuild, acwdInstall, acwdCustom:
      if cwdCustomPath.len > 0: cwdCustomPath
      else: projectRoot
  if raw.len == 0:
    return projectRoot
  if raw.isAbsolute:
    return raw
  # Relative path — resolve against projectRoot so recipes can pass
  # ``"build"`` and get ``<projectRoot>/build``. Fall back to
  # projectRoot when we have no project root to resolve against
  # (shouldn't happen through normal lowering).
  if projectRoot.len > 0:
    projectRoot / raw
  else:
    raw

proc lowerGraphAction(node: GraphNode; profiles: Table[string, PathOnlyToolProfile];
                      projectRoot: string): BuildAction =
  # `BuildAction.governingLockIdentity` is required. Give `result` a complete
  # sentinel value before the deferred metadata copier can observe it; every
  # successful branch below replaces the sentinel with its real action.
  result = noScheduledAction()
  let payload = decodeBuildActionPayload(toBytes(node.payload))
  let actionPathPrefix = toolPathPrefix(profiles, payload.call.packageName,
    payload.call.executableName, payload.toolIdentityRefs)
  # Named-Targets M1: copy implicit-target names off the decoded
  # payload onto every constructed ``BuildAction`` at the bottom of
  # this proc. The action constructors below don't know about
  # ``targetNames``; we stamp the field after the engine factory
  # returns so the engine-side edge record matches the DSL-side
  # ``BuildActionDef`` and the target-export table.
  #
  # Typed-Outputs M1: same plumbing for the per-output (fieldName,
  # types, path) entries — the engine consumes them downstream
  # without re-parsing the DSL.
  defer:
    result.targetNames = payload.targetNames
    var engineTypedOutputs: seq[EngineTypedOutput]
    for entry in payload.typedOutputs:
      engineTypedOutputs.add(EngineTypedOutput(
        fieldName: entry.fieldName,
        types: entry.types,
        path: entry.path))
    result.typedOutputs = engineTypedOutputs
    # M9.L.4-refactor Step B: stamp the convention-supplied
    # binary-cache publish wiring on the engine-side ``BuildAction``.
    # The DSL ``BuildActionDef`` and the engine ``BuildAction`` carry
    # the same ``Option[CacheEntryIdentity]`` shape (both defined in
    # terms of ``repro_binary_cache_client/cache_key.CacheEntryIdentity``)
    # so the propagation is a straight field copy. The engine's
    # ``publishBinaryCacheBundle`` honours both fields after a
    # successful action when the config supplies a non-nil
    # ``binaryCachePublisher`` closure.
    result.publishToBinaryCache = payload.publishToBinaryCache
    result.cacheEntryIdentity = payload.cacheEntryIdentity
    # M9.N Batch B: propagate the convention-supplied tool-identity
    # refs through to the engine-side ``BuildAction``. The engine
    # resolves each ref via ``BuildEngineConfig.toolIdentityResolver``
    # at fork time and prepends the resolved bin dirs to PATH so the
    # action's bare-name argv (``meson`` / ``ninja`` / ``gcc`` / ...)
    # finds the right binaries.
    result.toolIdentityRefs = payload.toolIdentityRefs
    result.toolIdentityRefKinds = @[]
    for kind in payload.toolIdentityRefKinds:
      result.toolIdentityRefKinds.add(
        case kind
        of tirkBuild: dkBuild
        of tirkNative: dkNative
        of tirkRuntime: dkRuntime)
    # M9.R.75: propagate the convention-supplied R6/R7 write-scope
    # declarations through to the engine-side ``BuildAction``. The
    # engine's ``validateGraph`` R7 pairwise-intersection pass reads
    # ``declaredOutputs``; the spawn wrapper + post-hoc monitor check
    # read ``readOnlyRoots``. Empty seqs (the default for legacy
    # actions that don't opt in) reduce to no-op enforcement,
    # preserving pre-M9.R.75 behaviour byte-for-byte.
    result.declaredOutputs = payload.declaredOutputs
    result.readOnlyRoots = payload.readOnlyRoots
  let actionCachePolicy =
    case payload.actionCachePolicy
    of acfpTimestamp:
      ffpTimestamp
    of acfpChecksum:
      ffpChecksum
    of acfpHybrid:
      ffpHybrid
  proc argValue(name: string): string =
    for arg in payload.call.arguments:
      if arg.name == name:
        return arg.encodedValue
    ""

  proc argSeqValue(name: string): seq[string] =
    let encoded = argValue(name)
    if encoded.len == 0:
      return @[]
    encoded.split("\x1f")

  if payload.call.packageName == "reprobuild.builtin" and
      payload.call.executableName == "exec":
    # Inline-exec builtin: the call carries a literal argv (and optional cwd)
    # and the action is launched directly via the engine's process action
    # without any package-profile lookup. The wrapper layer is bypassed
    # entirely; the binary graph cache holds the resolved argv.
    let literalArgv = argSeqValue("argv")
    if literalArgv.len == 0:
      raise newException(ValueError,
        "reprobuild.builtin.exec action " & payload.id &
          " has empty argv")
    # Windows-System-Resources Phase E — the `@FILE:<path>` argv
    # preprocessor. Every argv entry of the form `@FILE:<path>` is
    # replaced with the trimmed contents of `<path>` at the moment of
    # execution. The hook lives in the `reprobuild.builtin.exec`
    # lowering so BOTH elevated and non-elevated edges run the same
    # expansion semantics (spec §2.1). The build-graph payload keeps
    # the literal `@FILE:...` (no secret in the plan); the substituted
    # bytes only ride in the spawned process's argv. The audit-log
    # rendering uses the literal `@FILE:<path>` form via the engine's
    # log path — `auditArgvWithRedaction` is wired through the
    # elevated-broker dispatch; the non-elevated direct-fork path is
    # logged through the engine's own command-stats record which
    # already redacts via this same engine boundary.
    let argv = expandArgFiles(literalArgv, defaultArgFileReader)
    let cwdValue = argValue("cwd")
    # M9.R.74 — canonical execution root (R2) resolution. The DSL
    # ``BuildActionDef.cwdKind`` declaration wins; when it is
    # ``acwdRecipeRoot`` (the enum's zero value / legacy default)
    # we honour the ``inlineExecCall(argv, cwd = X)`` override as
    # before so existing recipes that pass an explicit ``cwd``
    # argument keep their historical behaviour byte-for-byte.
    let effectiveCwdKind =
      if payload.cwdKind != acwdRecipeRoot: payload.cwdKind
      elif cwdValue.len > 0: acwdCustom
      else: acwdRecipeRoot
    let effectiveCwdCustomPath =
      if payload.cwdKind != acwdRecipeRoot: payload.cwdCustomPath
      else: cwdValue
    let commandStatsId =
      if payload.commandStatsId.len > 0:
        payload.commandStatsId
      else:
        payload.id
    let fingerprintText = [
      "reprobuild.localInlineExecAction.v1",
      payload.id,
      node.payload
    ].join("\n")
    # M9.R.14c.4 — inline-exec actions (autotools configure scripts,
    # from-source-custom shell rows, ...) need the same PATH +
    # extraEnv enrichment as typed-tool actions. Without this, an
    # autotools configure script driven via inlineExecCall lands with
    # no tool-bin dirs on PATH and shells out to ``m4`` / ``perl`` /
    # ``make`` against the host's PATH (empty in a from-source
    # nix-shell), failing with diagnostics like:
    #   ``configure: error: no acceptable m4 could be found in $PATH``
    # The fix mirrors the typed-tool path below: prepend the called tool and
    # this action's explicit tool refs to PATH, then append per-edge overrides.
    var inlineEnv: seq[string] = @[]
    var inlineEnvPassthrough: seq[string] = @[]
    if actionPathPrefix.len > 0:
      inlineEnv.add(actionPathEntry(actionPathPrefix))
      inlineEnvPassthrough = @ActionPathPassthrough
    for entry in payload.env:
      inlineEnv.add(entry[0] & "=" & entry[1])
    return repro_build_engine.action(
      payload.id,
      argv,
      # Named-Lock-Files §3.1/§7.2: every edge in a workspace that declares
      # no lock files is governed by `default`, the one workspace lock.
      governingLockIdentity = workspaceGoverningLockIdentity(projectRoot),
      cwd = resolveCanonicalExecRoot(effectiveCwdKind,
        effectiveCwdCustomPath, projectRoot),
      deps = payload.deps,
      inputs = payload.inputs.mapIt(materialProjectPath(projectRoot, it)),
      outputs = payload.outputs,
      pool = payload.pool,
      poolUnits = payload.poolUnits,
      depfile = payload.depfile,
      dynamicDepsFile = payload.dynamicDepsFile,
      cacheable = payload.cacheable,
      weakFingerprint = weakFingerprintFromText(fingerprintText),
      actionCachePolicy = actionCachePolicy,
      dependencyPolicy = lowerDependencyPolicy(payload.id, payload.depfile,
        payload.dependencyPolicy),
      commandStatsId = commandStatsId,
      env = inlineEnv,
      envPassthrough = inlineEnvPassthrough,
      requiresElevation = payload.requiresElevation)

  if payload.call.packageName == "reprobuild.builtin" and
      payload.call.executableName == "fs":
    let commandStatsId =
      if payload.commandStatsId.len > 0:
        payload.commandStatsId
      else:
        payload.id
    let fingerprintText = [
      "reprobuild.localBuiltinAction.v1",
      payload.id,
      payload.call.subcommand,
      node.payload
    ].join("\n")
    let kind =
      case payload.call.subcommand
      of "copyFile": bakCopyFile
      of "ensureDir": bakEnsureDir
      of "writeText": bakWriteText
      of "stamp": bakStamp
      of "preserveTree": bakPreserveTree
      of "ensureLine": bakEnsureLine
      of "ensureSnippet": bakEnsureSnippet
      else:
        raise newException(ValueError,
          "unknown built-in fs operation: " & payload.call.subcommand)
    return repro_build_engine.builtinAction(
      kind,
      payload.id,
      # Named-Lock-Files §3.1/§7.2: every edge in a workspace that declares
      # no lock files is governed by `default`, the one workspace lock.
      governingLockIdentity = workspaceGoverningLockIdentity(projectRoot),

      # M9.R.74 — honour the DSL's ``cwdKind`` declaration. Default
      # ``acwdRecipeRoot`` collapses to ``projectRoot`` so every
      # legacy ``reprobuild.builtin.fs`` action gets byte-identical
      # CWD to the pre-milestone hardcoded path.
      cwd = resolveCanonicalExecRoot(payload.cwdKind,
        payload.cwdCustomPath, projectRoot),
      deps = payload.deps,
      inputs = payload.inputs.mapIt(materialProjectPath(projectRoot, it)),
      outputs = payload.outputs,
      commandStatsId = commandStatsId,
      cacheable = payload.cacheable,
      weakFingerprint = weakFingerprintFromText(fingerprintText),
      actionCachePolicy = actionCachePolicy,
      text = if payload.call.subcommand == "preserveTree":
          argValue("sourceRoot") & "\n" & argValue("outputRoot")
        elif payload.call.subcommand == "ensureLine":
          argValue("line")
        else:
          argValue("text") & argValue("title"),
      entries = if payload.call.subcommand == "ensureSnippet":
          @[argValue("openSentinel"), argValue("closeSentinel"),
            argValue("openSearch"), argValue("closeSearch"),
            argValue("snippet")]
        else:
          argSeqValue("entries"))

  if payload.call.packageName == "reprobuild.builtin" and
      payload.call.executableName == "hcr":
    if payload.call.subcommand != "prepareObject":
      raise newException(ValueError,
        "unknown built-in HCR operation: " & payload.call.subcommand)
    let commandStatsId =
      if payload.commandStatsId.len > 0:
        payload.commandStatsId
      else:
        payload.id
    let fingerprintText = [
      "reprobuild.localBuiltinHcrAction.v1",
      payload.id,
      payload.call.subcommand,
      node.payload
    ].join("\n")
    var argv = @[
      getAppFilename(), "hcr", "prepare-object",
      "--input", argValue("input"),
      "--output", argValue("output"),
      "--segment", argValue("segment")
    ]
    let functionName = argValue("function")
    if functionName.len > 0:
      argv.add "--function"
      argv.add functionName
    else:
      argv.add "--all-code"
    var inputs: seq[string] = @[]
    for input in payload.inputs:
      inputs.add(materialProjectPath(projectRoot, input))
    return repro_build_engine.action(
      payload.id,
      argv,
      # Named-Lock-Files §3.1/§7.2: every edge in a workspace that declares
      # no lock files is governed by `default`, the one workspace lock.
      governingLockIdentity = workspaceGoverningLockIdentity(projectRoot),
      # M9.R.74 — R2 declaration wins; legacy default = projectRoot.
      cwd = resolveCanonicalExecRoot(payload.cwdKind,
        payload.cwdCustomPath, projectRoot),
      deps = payload.deps,
      inputs = inputs,
      outputs = payload.outputs,
      pool = payload.pool,
      poolUnits = payload.poolUnits,
      depfile = payload.depfile,
      dynamicDepsFile = payload.dynamicDepsFile,
      cacheable = payload.cacheable,
      weakFingerprint = weakFingerprintFromText(fingerprintText),
      actionCachePolicy = actionCachePolicy,
      dependencyPolicy = lowerDependencyPolicy(payload.id, payload.depfile,
        payload.dependencyPolicy),
      commandStatsId = commandStatsId)

  let executableName = payload.call.executableName
  let packageName = payload.call.packageName
  let exactKey = packageName & "|" & executableName

  # Spec-Implementation M4 retired the
  # ``ct_test_nim_unittest.buildNimUnittest.build`` typed-tool
  # passthrough that used to sit here. The pre-M4 shim translated the
  # typed-tool call into a hand-rolled ``nim c`` argv:
  #
  #   subcommand "build"          -> subcommand "c"
  #   --source=<path> (positional)-> positional <path>
  #   --binary=<path>             -> --out:<path>
  #   --threads:on / --hints:off / --warnings:off (verbatim)
  #   --define:<X> / --import:<X> (verbatim)
  #
  # The shim existed because the typed-tool's executable identifier
  # ``ct_test_nim_unittest.buildNimUnittest`` had no real backing binary
  # — every action was conceptually a ``nim c`` invocation. M4 reshapes
  # the typed-tool wrapper at
  # ``libs/ct_test_nim_unittest/src/ct_test_nim_unittest.nim``
  # so it records a ``PublicCliCall`` against the ``nim`` profile
  # directly (``executableName = "nim"``, ``subcommand = "c"``) with the
  # same flag aliases the ``nim.c`` typed-tool exposes (``--out:``,
  # ``-d:``, ``--import:``, ``--threads:on``, ``--hints:off``,
  # ``--warnings:off``). The engine's normal typed-tool resolution path
  # below now finds the ``nim`` profile and ``argvForCall`` produces
  # byte-for-byte the same argv shape the shim was synthesising — the
  # 500+ reprobuild test edges flow through the standard path. The
  # ``TestRunner`` cross-cutting interface from M3, satisfied by the
  # standalone ``reprobuild-ct-test-runner`` repo's
  # ``libs/ct_test_runner_adapter`` package, handles RUN/LIST/ENUMERATE
  # at engine execution time so recipes that need to dispatch back to
  # ct-test-runner do so through ``currentBuildContext().testRunner``.

  # Deferred-Item D1: ``ct_test_nim_unittest.buildNimUnittest.{run,
  # runTest, list}`` execute-edge passthrough. The
  # ``NimUnittestBinary`` UFCS dispatch procs at
  # ``libs/ct_test_nim_unittest/src/ct_test_nim_unittest.nim``
  # record their call against the ``NimUnittestToolId`` typed-tool
  # identifier (``ct_test_nim_unittest.buildNimUnittest``) — there is
  # NO backing executable for that identifier on PATH because the
  # test binary IS the executable to invoke. The binary path flows in
  # as a typed input under the ``binary`` arg slot. Resolve the call
  # by treating the ``binary`` input value as the executable directly
  # and translating the per-subcommand argv to the convention the
  # stdlib's ``directRun`` / ``directList`` / ``directEnumerate``
  # implementations in
  # ``libs/repro_dsl_stdlib/src/repro_dsl_stdlib/interfaces/test_runner.nim``
  # use today:
  #
  #   subcommand "run"     -> [binary]  (+ filter as positional)
  #   subcommand "runTest" -> [binary, testName]
  #   subcommand "list"    -> [binary, "--list-json"]
  #
  # This unblocks the Bootstrap-And-Self-Build B3/B4 outcomes by
  # closing the path-mode resolver gap the engine documented in the
  # ``no tool profile was resolved`` diagnostic. The ``test`` build
  # graph collection's EXECUTE half now lowers without a profile
  # lookup — the binary's own content is the action's executable
  # contract.
  const NimUnittestToolId = "ct_test_nim_unittest.buildNimUnittest"
  if executableName == NimUnittestToolId and
      payload.call.subcommand in ["run", "runTest", "list"]:
    var binaryPath = ""
    var filterValue = ""
    var testNameValue = ""
    var listJson = false
    for arg in payload.call.arguments:
      case arg.name
      of "binary":
        binaryPath = arg.encodedValue
      of "filter":
        filterValue = arg.encodedValue
      of "run":
        testNameValue = arg.encodedValue
      of "list-json":
        listJson = arg.encodedValue.normalize == "true"
      else:
        discard
    if binaryPath.len == 0:
      raise newException(ValueError,
        "tool-resolution failed: action " & payload.id &
          " references " & NimUnittestToolId &
          " but the ``binary`` input slot is empty")
    let resolvedBinary = materialProjectPath(projectRoot, binaryPath)
    var argv: seq[string] = @[resolvedBinary]
    case payload.call.subcommand
    of "run":
      if filterValue.len > 0:
        argv.add(filterValue)
    of "runTest":
      if testNameValue.len > 0:
        argv.add(testNameValue)
    of "list":
      if listJson:
        argv.add("--list-json")
    else:
      discard
    var translatedInputs: seq[string] = @[]
    for input in payload.inputs:
      translatedInputs.add(materialProjectPath(projectRoot, input))
    let commandStatsId =
      if payload.commandStatsId.len > 0:
        payload.commandStatsId
      else:
        payload.id
    let fingerprintText = [
      "reprobuild.localProjectAction.v1",
      payload.id,
      NimUnittestToolId,
      NimUnittestToolId,
      payload.call.subcommand,
      node.payload
    ].join("\n")
    var mergedEnv: seq[string] = @[]
    var mergedEnvPassthrough: seq[string] = @[]
    if actionPathPrefix.len > 0:
      mergedEnv.add(actionPathEntry(actionPathPrefix))
      mergedEnvPassthrough = @ActionPathPassthrough
    # MR10: per-edge env-var injections from the typed-tool wrapper's
    # ``extraEnv`` parameter. Appended after ``PATH`` so a recipe that
    # explicitly sets ``PATH`` via ``extraEnv`` overrides the prefix.
    for entry in payload.env:
      mergedEnv.add(entry[0] & "=" & entry[1])
    return repro_build_engine.action(
      payload.id,
      argv,
      # Named-Lock-Files §3.1/§7.2: every edge in a workspace that declares
      # no lock files is governed by `default`, the one workspace lock.
      governingLockIdentity = workspaceGoverningLockIdentity(projectRoot),
      # M9.R.74 — R2 declaration wins; legacy default = projectRoot.
      cwd = resolveCanonicalExecRoot(payload.cwdKind,
        payload.cwdCustomPath, projectRoot),
      deps = payload.deps,
      inputs = translatedInputs,
      outputs = payload.outputs,
      pool = payload.pool,
      poolUnits = payload.poolUnits,
      depfile = payload.depfile,
      dynamicDepsFile = payload.dynamicDepsFile,
      cacheable = payload.cacheable,
      weakFingerprint = weakFingerprintFromText(fingerprintText),
      actionCachePolicy = actionCachePolicy,
      dependencyPolicy = lowerDependencyPolicy(payload.id, payload.depfile,
        payload.dependencyPolicy),
      commandStatsId = commandStatsId,
      env = mergedEnv,
      envPassthrough = mergedEnvPassthrough)

  # M9.R.12.2 — fall back to ``packageName`` alone when the recipe's
  # ``nativeBuildDeps:`` declares the tool by its package selector
  # (e.g. ``"make"``) but the typed-tool wrapper records the action
  # under the package's inner executable name (e.g. ``"makeBin"`` from
  # the ``executable makeBin:`` block inside ``package make:``). The
  # profile registry only indexes by ``packageSelector & "|" &
  # executableName`` and ``executableName``, so the lookup misses both
  # keys despite the recipe carrying a valid ``make`` use. The third
  # fallback by ``packageName`` closes the gap deterministically for
  # every typed-tool surface in the stdlib (``cmake.call`` →
  # ``cmakeBin``, ``meson.call`` → ``mesonBin``, ``ninja.call`` →
  # ``ninjaBin``, ``make.call`` → ``makeBin``).
  let profile =
    if profiles.hasKey(exactKey):
      profiles[exactKey]
    elif profiles.hasKey(executableName):
      profiles[executableName]
    elif packageName.len > 0 and profiles.hasKey(packageName):
      profiles[packageName]
    else:
      raise newException(ValueError,
        "tool-resolution failed: action " & payload.id &
          " references executable " & executableName &
          " but no tool profile was resolved for it")
  var inputs: seq[string] = @[]
  for input in payload.inputs:
    inputs.add(materialProjectPath(projectRoot, input))
  let outputs = payload.outputs
  let depfile = payload.depfile
  let commandStatsId =
    if payload.commandStatsId.len > 0:
      payload.commandStatsId
    else:
      payload.id
  let invocationArgv = argvForCall(payload.call, profile)
  let executableArgIndex = invocationArgv.find(profile.resolvedExecutablePath)
  let invocationPrefix =
    if executableArgIndex > 0:
      invocationArgv[0 ..< executableArgIndex].join("\x1f")
    else:
      ""
  let fingerprintText = [
    "reprobuild.localProjectAction.v1",
    payload.id,
    payload.call.packageName,
    executableName,
    payload.call.subcommand,
    node.payload,
    digestHex(profile.profileFingerprint),
    invocationPrefix
  ].join("\n")
  var mergedEnv: seq[string] = @[]
  var mergedEnvPassthrough: seq[string] = @[]
  if actionPathPrefix.len > 0:
    mergedEnv.add(actionPathEntry(actionPathPrefix))
    mergedEnvPassthrough = @ActionPathPassthrough
  # MR10: per-edge env-var injections from the typed-tool wrapper's
  # ``extraEnv`` parameter. Appended after ``PATH`` so a recipe that
  # explicitly sets ``PATH`` via ``extraEnv`` overrides the prefix.
  for entry in payload.env:
    mergedEnv.add(entry[0] & "=" & entry[1])
  result = repro_build_engine.action(
    payload.id,
    invocationArgv,
    # Named-Lock-Files §3.1/§7.2: every edge in a workspace that declares no
    # lock files is governed by `default`, the one workspace lock.
    governingLockIdentity = workspaceGoverningLockIdentity(projectRoot),
    # M9.R.74 — R2 declaration wins; legacy default = projectRoot so
    # every pre-milestone typed-tool action gets byte-identical CWD.
    cwd = resolveCanonicalExecRoot(payload.cwdKind,
      payload.cwdCustomPath, projectRoot),
    deps = payload.deps,
    inputs = inputs,
    outputs = outputs,
    pool = payload.pool,
    poolUnits = payload.poolUnits,
    depfile = depfile,
    dynamicDepsFile = payload.dynamicDepsFile,
    cacheable = payload.cacheable,
    weakFingerprint = weakFingerprintFromText(fingerprintText),
    actionCachePolicy = actionCachePolicy,
    dependencyPolicy = lowerDependencyPolicy(payload.id, depfile,
      payload.dependencyPolicy),
    commandStatsId = commandStatsId,
    env = mergedEnv,
    envPassthrough = mergedEnvPassthrough)

proc levenshtein(a, b: string): int =
  ## Named-Targets M2 ``unknown_target`` diagnostic helper. A small
  ## inline edit-distance implementation rather than ``std/editdistance``
  ## so the resolver stays self-contained and predictable across the
  ## CLI's existing import surface. O(len(a)*len(b)) time / O(len(b))
  ## extra memory; the resolver only ever calls this against the
  ## handful of names in the project's target-export table.
  if a.len == 0: return b.len
  if b.len == 0: return a.len
  var prev = newSeq[int](b.len + 1)
  var curr = newSeq[int](b.len + 1)
  for j in 0 .. b.len:
    prev[j] = j
  for i in 1 .. a.len:
    curr[0] = i
    for j in 1 .. b.len:
      let cost =
        if a[i - 1] == b[j - 1]: 0
        else: 1
      var v = prev[j] + 1
      if curr[j - 1] + 1 < v:
        v = curr[j - 1] + 1
      if prev[j - 1] + cost < v:
        v = prev[j - 1] + cost
      curr[j] = v
    swap(prev, curr)
  prev[b.len]

proc topLevenshteinCandidates(query: string; candidates: openArray[string];
                              limit = 3): seq[string] =
  ## Return up to ``limit`` candidate names from ``candidates`` ordered
  ## by ascending Levenshtein distance to ``query``. Used by the M2
  ## ``unknown_target`` diagnostic.
  if candidates.len == 0:
    return @[]
  var scored: seq[tuple[name: string; dist: int]] = @[]
  for name in candidates:
    scored.add((name: name, dist: levenshtein(query, name)))
  scored.sort(proc(a, b: tuple[name: string; dist: int]): int =
    if a.dist != b.dist: a.dist - b.dist
    else: cmp(a.name, b.name))
  for i in 0 ..< min(limit, scored.len):
    result.add(scored[i].name)

proc aggregateTargetExportTable*(snapshot: ProviderGraphSnapshot):
    TargetExportTable =
  ## Named-Targets M2 aggregation: ``buildPackageFragment`` runs per
  ## package in isolation, so each fragment carries only the rows
  ## emitted while that package's ``build:`` body was running. The M2
  ## resolver needs a project-scoped view, so this proc walks every
  ## fragment's ``reprobuild.target-export-table.v1`` metadata node and
  ## merges the rows. Cross-package ambiguity is re-computed here
  ## because per-fragment ambiguity records only see same-name within a
  ## single package's call set.
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      # Spec-Implementation M5: accept both v1 and v2 metadata-node
      # stable names. The on-disk payload codec is backward-compatible
      # (v1 envelopes decode through ``decodeTargetExportTablePayload``
      # with the original two-value ``kind`` enum) so existing
      # snapshots from older builds still flow through this aggregator.
      if node.kind == gnkMetadata and
          (node.stableName == "reprobuild.target-export-table.v1" or
           node.stableName == "reprobuild.target-export-table.v2"):
        let perPackage = decodeTargetExportTablePayload(toBytes(node.payload))
        for entry in perPackage.entries:
          result.entries.add(entry)
  # Re-derive cross-package ambiguity over the unioned rows. A name is
  # ambiguous when two or more distinct ``owningPackage`` values claim
  # it. Per-fragment ambiguities (same-name collisions within one
  # package) are already raised as build-time errors at M1, so they
  # never reach M2.
  var packagesByName = initTable[string, seq[string]]()
  for entry in result.entries:
    if not packagesByName.hasKey(entry.name):
      packagesByName[entry.name] = @[]
    if packagesByName[entry.name].find(entry.owningPackage) < 0:
      packagesByName[entry.name].add(entry.owningPackage)
  for name, pkgs in packagesByName.pairs:
    if pkgs.len >= 2:
      var candidates: seq[string] = @[]
      for pkg in pkgs:
        candidates.add(pkg & ":" & name)
      candidates.sort()
      result.ambiguities.add(TargetExportAmbiguity(name: name,
        candidates: candidates))

proc aggregateResourceGraph*(snapshot: ProviderGraphSnapshot):
    tuple[resources: seq[ResourceInstance]; groups: seq[StateGroupDef];
          providerArtifacts: seq[tuple[typeId: string;
                                       artifact: ResourceProviderArtifactRef]]] =
  ## Named-Runnable-Edges N2/N3b: union the ``reprobuild.resource-graph.v1``
  ## metadata nodes each package fragment emitted (see
  ## ``buildPackageFragment``) into one project-scoped resource-lane graph —
  ## the ``stateGroup`` resource subgraph + membership the leased-consumes
  ## bridge reconciles, PLUS the N3b per-typeId provider-artifact refs the CLI
  ## opens out-of-tree sessions over. A snapshot with no such node (a project
  ## that declares no resources) yields empty seqs, so a non-consuming
  ## ``repro run`` never pays for the decode.
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      if node.kind == gnkMetadata and
          node.stableName == "reprobuild.resource-graph.v1":
        let decoded = decodeResourceGraphPayload(toBytes(node.payload))
        for inst in decoded.resources:
          result.resources.add(inst)
        for g in decoded.groups:
          result.groups.add(g)
        for pa in decoded.providerArtifacts:
          result.providerArtifacts.add(pa)

type
  TargetResolutionKind* = enum
    ## Named-Targets M5: how a single selector was resolved against the
    ## project-scoped target-export table. Recorded in the build report
    ## under ``targetResolution`` so JSON consumers see the same shape as
    ## the CLI text diagnostics.
    trkResolved
    trkAmbiguous
    trkUnknown

  TargetResolutionRecord* = object
    selector*: string
    kind*: TargetResolutionKind
    actionId*: string         ## ``trkResolved``: the engine handle the
                              ## selector resolved to.
    owningPackage*: string    ## ``trkResolved``: the package whose call
                              ## emitted this edge (empty for explicit
                              ## ``target "..."`` labels and action ids).
    targetKind*: TargetExportKind ## Spec-Implementation M5: per
                              ## Build-Graph-Collections.md §"Persistence
                              ## and the Target-Export Table" the build
                              ## report carries the resolved row's
                              ## origin marker so JSON consumers can
                              ## tell a ``collection`` resolution apart
                              ## from an ``aggregate`` resolution apart
                              ## from a plain implicit / explicit
                              ## target. Defaults to ``tekImplicit`` (the
                              ## historical record kind) when the
                              ## resolver could not derive a row — e.g.
                              ## action-id pass-throughs.
    candidates*: seq[string]  ## ``trkAmbiguous``: the sorted qualified
                              ## ``<package>:<name>`` candidates.
    suggestions*: seq[string] ## ``trkUnknown``: top-3 Levenshtein
                              ## suggestions over known target names.

proc resolveTargetExportSelector*(exportTable: TargetExportTable;
                                  knownActionIds: openArray[string];
                                  knownExplicitTargets: openArray[string];
                                  selector: string;
                                  collectionMembers:
                                    Table[string, seq[string]] =
                                      initTable[string, seq[string]]()):
    TargetResolutionRecord =
  ## Named-Targets M5: shared name-lookup that ``runGraphCommand`` /
  ## ``runWhyCommand`` use to translate a bare name or qualified
  ## ``<package>:<name>`` selector into an action id BEFORE handing the
  ## selector to ``parseBuildTarget``. Mirrors the in-lowering resolver
  ## inside ``lowerProviderSnapshot`` so the two code paths cannot
  ## drift. The return record is also embedded in the build report by
  ## ``writeBuildReport`` (M5 diagnostic-taxonomy polish).
  ##
  ## **Deferred Item D5** — when ``collectionMembers`` is supplied,
  ## ``<collection>#<member>`` selectors resolve against it the same
  ## way ``lowerProviderSnapshot``'s in-engine resolver does. The
  ## parameter defaults to empty so the M5 callers that don't have a
  ## collection-membership view (the build-target-export table alone
  ## doesn't carry one) keep working unchanged.
  result.selector = selector

  # Build the same indexes the lowering resolver computes.
  var entriesByQualified = initTable[string, TargetExportEntry]()
  var entriesByName = initTable[string, seq[TargetExportEntry]]()
  for entry in exportTable.entries:
    let qualified = entry.owningPackage & ":" & entry.name
    if not entriesByQualified.hasKey(qualified):
      entriesByQualified[qualified] = entry
    if not entriesByName.hasKey(entry.name):
      entriesByName[entry.name] = @[]
    entriesByName[entry.name].add(entry)

  # Spec-Implementation M5: collection rows shadow same-name implicit
  # / explicit / aggregate rows per Build-Graph-Collections.md
  # §"Naming" — the bare-name path below prefers a ``tekCollection``
  # entry when both exist. The qualified-resolution and pass-through
  # paths return the entry's recorded kind directly.

  # 1. Qualified ``<package>:<name>``.
  let colon = selector.find(':')
  if colon > 0 and colon < selector.high:
    let secondColon = selector.find(':', colon + 1)
    if secondColon < 0 and entriesByQualified.hasKey(selector):
      let entry = entriesByQualified[selector]
      result.kind = trkResolved
      result.actionId = entry.actionId
      result.owningPackage = entry.owningPackage
      result.targetKind = entry.kind
      return

  # 2. Existing action id pass-through.
  for actionId in knownActionIds:
    if actionId == selector:
      result.kind = trkResolved
      result.actionId = selector
      result.targetKind = tekImplicit
      return

  # **Deferred Item D5** ``<collection>#<member>`` shorthand.
  # Mirrors the resolver inside ``lowerProviderSnapshot`` so the
  # build-report ``targetResolution`` row matches what the engine
  # actually selected. Only fires when the caller supplied a
  # collection-membership view (the engine path has one because it
  # decodes ``reprobuild.build-target.v1`` nodes from the snapshot;
  # the M5 graph/why callers may not).
  let hashPos = selector.find('#')
  if hashPos > 0 and hashPos < selector.high and collectionMembers.len > 0:
    let collectionName = selector[0 ..< hashPos]
    let memberName = selector[hashPos + 1 .. ^1]
    if collectionMembers.hasKey(collectionName) and memberName.len > 0:
      let actions = collectionMembers[collectionName]
      var matches: seq[string] = @[]
      # Direct action-id match.
      for actionId in actions:
        if actionId == memberName and matches.find(actionId) < 0:
          matches.add(actionId)
      # ``.<member>`` suffix match.
      let needle = "." & memberName
      for actionId in actions:
        if actionId.len >= needle.len and
            actionId[actionId.len - needle.len .. ^1] == needle and
            matches.find(actionId) < 0:
          matches.add(actionId)
      # Implicit-name match — the export table's row whose ``name``
      # equals ``<member>`` and whose ``actionId`` is in the
      # collection's action list.
      if entriesByName.hasKey(memberName):
        for entry in entriesByName[memberName]:
          if entry.actionId in actions and matches.find(entry.actionId) < 0:
            matches.add(entry.actionId)
      if matches.len == 1:
        result.kind = trkResolved
        result.actionId = matches[0]
        result.targetKind = tekCollection
        return
      if matches.len > 1:
        result.kind = trkAmbiguous
        result.candidates = matches
        return

  # 3. Bare implicit name.
  if entriesByName.hasKey(selector):
    var ownerPackages: seq[string] = @[]
    var lastEntry: TargetExportEntry
    # Spec-Implementation M5: prefer a ``tekCollection`` entry when
    # one is present so ``repro build test`` resolves to the test
    # collection rather than an implicit name with the same spelling
    # produced by a test-binary edge.
    var collectionEntry: TargetExportEntry
    var hasCollectionEntry = false
    for entry in entriesByName[selector]:
      if ownerPackages.find(entry.owningPackage) < 0:
        ownerPackages.add(entry.owningPackage)
      lastEntry = entry
      if entry.kind == tekCollection and not hasCollectionEntry:
        collectionEntry = entry
        hasCollectionEntry = true
    if ownerPackages.len > 1:
      var candidates: seq[string] = @[]
      for pkg in ownerPackages:
        candidates.add(pkg & ":" & selector)
      candidates.sort()
      result.kind = trkAmbiguous
      result.candidates = candidates
      return
    let chosen = if hasCollectionEntry: collectionEntry else: lastEntry
    result.kind = trkResolved
    result.actionId = chosen.actionId
    result.owningPackage = chosen.owningPackage
    result.targetKind = chosen.kind
    return

  # 4. Legacy explicit-target fallback. Current provider snapshots carry an
  # export-table row with the real action
  # handle and target kind. Older snapshots may only carry the build-target
  # metadata name, so retain this fallback after the richer row lookup.
  for explicitName in knownExplicitTargets:
    if explicitName == selector:
      result.kind = trkResolved
      result.actionId = selector
      result.targetKind = tekExplicit
      return

  # 5. Unknown — synthesize Levenshtein suggestions.
  var known: seq[string] = @[]
  for actionId in knownActionIds:
    if known.find(actionId) < 0:
      known.add(actionId)
  for explicitName in knownExplicitTargets:
    if known.find(explicitName) < 0:
      known.add(explicitName)
  for name in entriesByName.keys:
    if known.find(name) < 0:
      known.add(name)
  result.kind = trkUnknown
  result.suggestions = topLevenshteinCandidates(selector, known)

proc materializedCachePrefix(action: BuildAction): string =
  let raw =
    if action.declaredOutputs.len == 1:
      action.declaredOutputs[0]
    elif action.outputs.len > 0:
      action.outputs[0]
    else:
      ""
  if raw.len == 0 or raw.isAbsolute:
    return raw
  action.cwd / raw

proc removeMaterializedPath(path: string) =
  if dirExists(path):
    removeDir(path)
  elif fileExists(path) or symlinkExists(path):
    removeFile(path)

proc substituteMaterializedBinaryCacheEntries(g: BuildGraph):
    BuildRunResult =
  ## Restore tagged public-interface roots before source auto-recurse builds
  ## their tool dependencies. A miss is represented as a failed action so the
  ## caller can fall back to the unchanged source-build path.
  for action in g.actions:
    if not action.publishToBinaryCache or action.cacheEntryIdentity.isNone:
      continue
    let key = deriveActionCacheKeyHex(action)
    let prefix = materializedCachePrefix(action)
    var item = ActionResult(
      id: action.id,
      status: asFailed,
      cacheDecision: cdMiss,
      reason: "materialized-binary-cache-substitute key=" & key)
    if prefix.len == 0:
      item.stderr = "materialized binary-cache prefix is empty"
      result.results.add(item)
      continue
    let staged = prefix & ".repro-cache-substitute-" &
      $getCurrentProcessId()
    removeMaterializedPath(staged)
    createDir(parentDir(staged))
    let rc = bcCliDispatch.runCacheSubcommand(
      @["substitute", key, staged])
    if rc == 0:
      removeMaterializedPath(prefix)
      moveDir(staged, prefix)
      item.status = asCacheHit
      item.cacheDecision = cdHit
      item.reason = "materialized-binary-cache-substituted key=" & key
    else:
      removeMaterializedPath(staged)
      item.stderr = "trusted binary-cache miss for " & key
    result.results.add(item)
  if result.results.len == 0:
    result.results.add(ActionResult(
      id: "binary-cache-materialized",
      status: asFailed,
      cacheDecision: cdMiss,
      reason: "materialized-binary-cache-no-entries",
      stderr: "no tagged materialized binary-cache entries in selected graph"))

proc materializedSubstitutionConfigured(): bool =
  if getEnv("REPRO_CACHE_DISABLE", "") in ["1", "true", "yes"]:
    return false
  try:
    bcCachesConfig.loadEndpoints().len > 0
  except CatchableError:
    false

proc lowerProviderSnapshot*(snapshot: ProviderGraphSnapshot;
                            identity: PathOnlyBuildIdentity;
                            projectRoot: string;
                            selectedActionIds: openArray[string];
                            publishableOnly = false):
    tuple[actions: seq[BuildAction]; pools: seq[BuildPool]] =
  ## Named-Targets M2: accept multiple selectors and union their
  ## dependency closures in a single engine pass. Each selector may be
  ## an action id, an explicit ``target "name", handle`` label, an
  ## implicit target name carried by the M1 export table, or a
  ## qualified ``<package>:<name>`` form. When a selector matches more
  ## than one package, raises ``BuildTargetAmbiguousError``. When it
  ## matches no edge, raises ``BuildTargetUnknownError`` with up to
  ## three closest known names.
  let profiles = profileIndex(identity)
  var actionNodes: seq[tuple[node: GraphNode; payload: BuildActionDef]] = @[]
  var targets = initTable[string, BuildTargetDef]()
  var pools = initTable[string, BuildPoolDef]()
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      if node.kind == gnkAction:
        actionNodes.add((
          node: node,
          payload: decodeBuildActionPayload(toBytes(node.payload))))
      elif node.kind == gnkMetadata and
          node.stableName == "reprobuild.build-target.v1":
        let target = decodeBuildTargetPayload(toBytes(node.payload))
        if targets.hasKey(target.name):
          raise newException(ValueError,
            "duplicate build target metadata: " & target.name)
        targets[target.name] = target
      elif node.kind == gnkMetadata and
          node.stableName == "reprobuild.build-pool.v1":
        let pool = decodeBuildPoolPayload(toBytes(node.payload))
        if pools.hasKey(pool.name):
          raise newException(ValueError,
            "duplicate build pool metadata: " & pool.name)
        pools[pool.name] = pool
  for pool in pools.values:
    result.pools.add(repro_build_engine.pool(pool.name, pool.capacity))
  var declaredActions = newSeq[BuildActionDef](actionNodes.len)
  for i in 0 ..< actionNodes.len:
    declaredActions[i] = actionNodes[i].payload
  let inferredActions = inferDeclaredActionDeps(declaredActions, projectRoot)
  for i in 0 ..< actionNodes.len:
    actionNodes[i].payload = inferredActions[i]
  var aliasForAction = initTable[string, string]()
  for target in targets.values:
    # A collection names a set; it does not rename its sole member. Treating
    # one-member collections as aliases makes an action that also has a public
    # target appear to have two conflicting names.
    if target.kind == btkAggregate and target.actions.len == 1 and
        target.targets.len == 0:
      let actionId = target.actions[0]
      if aliasForAction.hasKey(actionId) and aliasForAction[actionId] !=
          target.name:
        raise newException(ValueError,
          "action " & actionId & " has multiple direct target aliases: " &
            aliasForAction[actionId] & " and " & target.name)
      aliasForAction[actionId] = target.name

  proc publicPayload(action: BuildActionDef): BuildActionDef =
    result = action
    if aliasForAction.hasKey(action.id):
      result.id = aliasForAction[action.id]
    for i in 0 ..< result.deps.len:
      if aliasForAction.hasKey(result.deps[i]):
        result.deps[i] = aliasForAction[result.deps[i]]

  proc lowerItem(item: tuple[node: GraphNode; payload: BuildActionDef]):
      BuildAction =
    var node = item.node
    node.payload = actionPayload(publicPayload(item.payload))
    lowerGraphAction(node, profiles, projectRoot)

  proc shouldLower(item: tuple[node: GraphNode;
                               payload: BuildActionDef]): bool =
    not publishableOnly or
      (item.payload.publishToBinaryCache and
        item.payload.cacheEntryIdentity.isSome)

  # When no selector is provided, schedule every emitted edge — the
  # legacy "build everything" behavior preserved from the single-target
  # entry point.
  var hasSelector = false
  for s in selectedActionIds:
    if s.len > 0:
      hasSelector = true
      break
  if not hasSelector:
    var excludedActionIds = initHashSet[string]()
    for name, target in targets:
      if name == "test" or name.endsWith(":test") or
         name == "bench" or name.endsWith(":bench") or
         name == "lint" or name.endsWith(":lint"):
        for aid in target.actions:
          excludedActionIds.incl(aid)
    for item in actionNodes:
      if not excludedActionIds.contains(item.payload.id) and
          shouldLower(item):
        result.actions.add(lowerItem(item))
    return

  var byId = initTable[string, BuildActionDef]()
  for item in actionNodes:
    byId[item.payload.id] = item.payload

  # Named-Targets M2: aggregate every fragment's target-export table
  # into one project-scoped view. Cross-package ambiguity is re-derived
  # over the unioned rows because per-fragment ambiguity records only
  # see same-name collisions within one package's call set.
  let exportTable = aggregateTargetExportTable(snapshot)
  var entriesByQualified = initTable[string, TargetExportEntry]()
  var entriesByName = initTable[string, seq[TargetExportEntry]]()
  for entry in exportTable.entries:
    let qualified = entry.owningPackage & ":" & entry.name
    if not entriesByQualified.hasKey(qualified):
      entriesByQualified[qualified] = entry
    if not entriesByName.hasKey(entry.name):
      entriesByName[entry.name] = @[]
    entriesByName[entry.name].add(entry)

  proc resolveSelectorToActionId(selector: string): string =
    ## Returns the action id (or explicit target name) the selector
    ## resolves to. Raises ``BuildTargetAmbiguousError`` or
    ## ``BuildTargetUnknownError`` per the M2 diagnostic contract.
    # Try qualified ``<package>:<name>`` first — the form the
    # ambiguity diagnostic asks the user to re-run with.
    let colon = selector.find(':')
    if colon > 0 and colon < selector.high:
      if entriesByQualified.hasKey(selector):
        return entriesByQualified[selector].actionId
      # When the qualified form doesn't match a row, fall through to
      # the unqualified path below so we still attempt action-id /
      # explicit-target lookup (preserving the legacy behavior for
      # action ids that happen to contain a ``:``).

    # Existing action id (legacy ``parseBuildTarget`` ``#<id>`` form).
    if byId.hasKey(selector):
      return selector
    # Existing ``target "name", handle`` label.
    if targets.hasKey(selector):
      return selector

    # **Deferred Item D5** ``<collection>#<member>`` shorthand. When the
    # selector contains a ``#`` (carried through from the CLI's
    # ``.#<collection>#<member>`` outer-fragment form: the outer ``.#``
    # is consumed by ``parseBuildTarget`` as the project-file anchor,
    # leaving the inner ``<collection>#<member>`` as ``selectedActionId``),
    # interpret the left half as a build-graph collection name and the
    # right half as a member selector. The member resolves against the
    # collection's action list using the same conventions the engine
    # already understands:
    #
    #   1. action-id equality — ``<member>`` equals an action id in the
    #      collection (rare; the user would normally spell the full id),
    #   2. ``.<member>`` suffix — the typical case for
    #      ``reprobuild.<verb>.<stem>`` action ids registered by the
    #      ``test`` / ``apps`` / ``test-helpers`` collections (per
    #      reprobuild/repro.nim), and
    #   3. implicit-name match — a typed-tool wrapper registered the
    #      binary's basename (e.g. ``t_dsl_outputs_statement_basic_accepted``)
    #      as an implicit target name pointing at the build edge's
    #      auto-generated id (e.g. ``nim-c-9a79fb5ba32…``). This is the
    #      shape ``test-builds#<stem>`` lands on because the build edges
    #      do not carry an explicit ``actionId =``.
    #
    # The selector parser intentionally leaves the resolution to the
    # engine: at parse time the project's collection registry isn't
    # available yet (it's persisted into the provider snapshot during
    # graph emission), but at lowering time the snapshot's per-fragment
    # ``BuildTargetDef`` rows give us the full ``actions`` membership.
    # When neither half resolves, fall through to the generic
    # ``unknown_target`` diagnostic below so the user still sees the
    # available-names hint.
    let hashPos = selector.find('#')
    if hashPos > 0 and hashPos < selector.high:
      let collectionName = selector[0 ..< hashPos]
      let memberName = selector[hashPos + 1 .. ^1]
      if targets.hasKey(collectionName) and memberName.len > 0:
        let collection = targets[collectionName]
        var memberIdsByActionId = initHashSet[string]()
        for actionId in collection.actions:
          memberIdsByActionId.incl(actionId)
        # Pass 1: direct action-id match.
        if memberIdsByActionId.contains(memberName):
          return memberName
        # Pass 2: ``.<member>`` suffix match against any action id in
        # the collection. Matches the
        # ``reprobuild.test_execute.<stem>`` /
        # ``reprobuild.python_test.<stem>`` / ``reprobuild.apps.<name>``
        # conventions used by reprobuild's collections.
        var suffixMatches: seq[string] = @[]
        let needle = "." & memberName
        for actionId in collection.actions:
          if actionId.len >= needle.len and
              actionId[actionId.len - needle.len .. ^1] == needle:
            if suffixMatches.find(actionId) < 0:
              suffixMatches.add(actionId)
        # Pass 3: implicit-name match — find export-table entries
        # whose ``name`` equals ``<member>`` and whose ``actionId`` is
        # in the collection's action list.
        if entriesByName.hasKey(memberName):
          for entry in entriesByName[memberName]:
            if memberIdsByActionId.contains(entry.actionId) and
                suffixMatches.find(entry.actionId) < 0:
              suffixMatches.add(entry.actionId)
        if suffixMatches.len == 1:
          return suffixMatches[0]
        if suffixMatches.len > 1:
          var err = newException(BuildTargetAmbiguousError,
            "collection member '" & memberName & "' in '" &
              collectionName & "' matches multiple actions: " &
              suffixMatches.join(", ") &
              " — re-run with the qualified action id")
          err.selectorName = selector
          err.candidates = suffixMatches
          raise err
        # No member matched: surface the same ``unknown_target`` shape
        # as the generic miss, but enumerate the collection's members
        # in the suggestions so the user sees what's available. The
        # suggestion list is the per-action implicit names when known
        # (more user-friendly), falling back to the raw action ids.
        var members: seq[string] = @[]
        for actionId in collection.actions:
          var displayed = actionId
          # When the action id has a ``.``-separated last segment,
          # use that as the member-shorthand form so the suggestion
          # matches what the user just typed.
          let lastDot = actionId.rfind('.')
          if lastDot > 0 and lastDot < actionId.high:
            displayed = actionId[lastDot + 1 .. ^1]
          else:
            # Fall back to any implicit target name pointing at this
            # action.
            for entry in exportTable.entries:
              if entry.actionId == actionId and entry.name.len > 0:
                displayed = entry.name
                break
          if members.find(displayed) < 0:
            members.add(displayed)
        var err = newException(BuildTargetUnknownError,
          "unknown build target: " & selector &
            " (no member '" & memberName & "' in collection '" &
            collectionName & "')")
        err.selectorName = selector
        err.suggestions = topLevenshteinCandidates(memberName, members)
        raise err

    # M2 implicit / explicit target-name lookup.
    if entriesByName.hasKey(selector):
      var ownerPackages: seq[string] = @[]
      var lastEntry: TargetExportEntry
      for entry in entriesByName[selector]:
        if ownerPackages.find(entry.owningPackage) < 0:
          ownerPackages.add(entry.owningPackage)
        lastEntry = entry
      if ownerPackages.len > 1:
        var candidates: seq[string] = @[]
        for pkg in ownerPackages:
          candidates.add(pkg & ":" & selector)
        candidates.sort()
        var err = newException(BuildTargetAmbiguousError,
          "target '" & selector & "' is exported by multiple packages: " &
            candidates.join(", ") &
            " — re-run with the qualified <package>:<name> form")
        err.selectorName = selector
        err.candidates = candidates
        raise err
      return lastEntry.actionId

    # Nothing matched — surface ``unknown_target`` with Levenshtein
    # suggestions over the known action ids, explicit target labels,
    # and implicit names.
    var known: seq[string] = @[]
    for item in actionNodes:
      if known.find(item.payload.id) < 0:
        known.add(item.payload.id)
    for name in targets.keys:
      if known.find(name) < 0:
        known.add(name)
    for name in entriesByName.keys:
      if known.find(name) < 0:
        known.add(name)
    let suggestions = topLevenshteinCandidates(selector, known)
    var err = newException(BuildTargetUnknownError,
      "unknown build target: " & selector &
        (if suggestions.len > 0:
          " (did you mean: " & suggestions.join(", ") & "?)"
        elif known.len > 0:
          " (available: " & known.join(", ") & ")"
        else: " (project defines no build actions or targets)"))
    err.selectorName = selector
    err.suggestions = suggestions
    raise err

  var resolvedRoots: seq[string] = @[]
  for selector in selectedActionIds:
    if selector.len == 0:
      continue
    let resolved = resolveSelectorToActionId(selector)
    if resolvedRoots.find(resolved) < 0:
      resolvedRoots.add(resolved)

  var selected = initHashSet[string]()
  var visitingTargets = initHashSet[string]()
  var expandedTargets = initHashSet[string]()
  var currentSelector = ""

  proc includeClosure(actionId: string) =
    if selected.contains(actionId):
      return
    if not byId.hasKey(actionId):
      raise newException(ValueError,
        "unknown dependency " & actionId & " while selecting build target " &
          currentSelector)
    selected.incl(actionId)
    for dep in byId[actionId].deps:
      includeClosure(dep)

  proc includeTarget(targetName: string) =
    if expandedTargets.contains(targetName):
      return
    if visitingTargets.contains(targetName):
      raise newException(ValueError,
        "cyclic build target dependency involving " & targetName)
    if not targets.hasKey(targetName):
      raise newException(ValueError,
        "unknown build target " & targetName & " while selecting " &
          currentSelector)
    visitingTargets.incl(targetName)
    let target = targets[targetName]
    for depTarget in target.targets:
      includeTarget(depTarget)
    for actionId in target.actions:
      includeClosure(actionId)
    visitingTargets.excl(targetName)
    expandedTargets.incl(targetName)

  for root in resolvedRoots:
    currentSelector = root
    if targets.hasKey(root):
      includeTarget(root)
    else:
      includeClosure(root)
  for item in actionNodes:
    if selected.contains(item.payload.id) and shouldLower(item):
      result.actions.add(lowerItem(item))

proc lowerProviderSnapshot*(snapshot: ProviderGraphSnapshot;
                            identity: PathOnlyBuildIdentity;
                            projectRoot: string;
                            selectedActionId = ""):
    tuple[actions: seq[BuildAction]; pools: seq[BuildPool]] =
  ## Single-selector entry point preserved for the existing call sites
  ## (graph / why / etc.). The Named-Targets M2 multi-selector resolver
  ## lives on the ``openArray[string]`` overload above; this wrapper
  ## delegates to it with a one-element selector list.
  if selectedActionId.len == 0:
    lowerProviderSnapshot(snapshot, identity, projectRoot, [""])
  else:
    lowerProviderSnapshot(snapshot, identity, projectRoot, [selectedActionId])

proc lowerMaterializedProviderSnapshot*(snapshot: ProviderGraphSnapshot;
    projectRoot: string; selectedActionIds: openArray[string]):
    tuple[actions: seq[BuildAction]; pools: seq[BuildPool]] =
  ## Resolve the requested target closure through the normal named-target
  ## machinery, but lower only explicitly tagged public-interface actions.
  ## Materialized publication never launches an edge, so an empty identity is
  ## sufficient and avoids provisioning tools for the omitted build actions.
  lowerProviderSnapshot(snapshot, PathOnlyBuildIdentity(), projectRoot,
    selectedActionIds, publishableOnly = true)

proc poolsFromSnapshot*(snapshot: ProviderGraphSnapshot): seq[BuildPool] =
  ## Gather the recipe's declared build pools DIRECTLY from the provider-graph
  ## snapshot's ``reprobuild.build-pool.v1`` metadata nodes — the SAME pass
  ## ``lowerProviderSnapshot`` runs (above), but WITHOUT the action-lowering /
  ## tool-identity resolution that the full lower performs.
  ##
  ## RX pool-forwarding resilience: a recipe's ``buildPool(...)`` calls execute
  ## at PROVIDER-EXECUTION time and land in the snapshot's fragments as
  ## build-pool metadata nodes — they are INDEPENDENT of ``uses:`` sibling
  ## resolution. Full graph LOWERING, by contrast, can throw for a CONSUMER
  ## recipe whose ``uses:`` siblings are not yet resolvable at daemon-spawn
  ## time. This proc lets the pool-forwarding path recover the consumer's OWN
  ## declared pools from the snapshot even when lowering is incomplete, so a
  ## consumer's ``buildPool("x.serial", 1)`` still reaches its runquotad.
  var pools = initTable[string, BuildPoolDef]()
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      if node.kind == gnkMetadata and
          node.stableName == "reprobuild.build-pool.v1":
        let pool = decodeBuildPoolPayload(toBytes(node.payload))
        if not pools.hasKey(pool.name):
          pools[pool.name] = pool
  for pool in pools.values:
    result.add(repro_build_engine.pool(pool.name, pool.capacity))

const DefaultBuildCollectionName* = "default"
  ## Per Build-Graph-Collections.md §"`default`" — the conventional
  ## collection that `repro build` with no positional target resolves
  ## to. Stdlib `executable` / `library` macros auto-enrol their
  ## primary edge into it; explicit `collect("default", ...)` calls
  ## contribute alongside auto-enrolments.
  ##
  ## The bare name is `default` (not `build`) so the CLI surface stays
  ## ergonomic: `repro build` (no arg) and `repro build default` are
  ## equivalent, while a literal `repro build build` would have read
  ## like an authoring mistake.

proc projectHasDefaultCollection*(snapshot: ProviderGraphSnapshot): bool =
  ## Returns true when the project's aggregated target-export table
  ## carries at least one row for the `default` conventional collection.
  ## Drives the `repro build` (no-arg) default resolution: when this
  ## holds, the engine schedules `repro build default` instead of
  ## falling back to the legacy `DefaultBuildActionMetadataName`
  ## action pin.
  let exportTable = aggregateTargetExportTable(snapshot)
  for entry in exportTable.entries:
    if entry.kind == tekCollection and entry.name == DefaultBuildCollectionName:
      return true
  false

proc defaultBuildActionId(snapshot: ProviderGraphSnapshot): string =
  ## Returns the selector `repro build` (no positional target) should
  ## materialize. Resolution order matches
  ## CLI/build.md §"Current-Directory Default":
  ##
  ## 1. The `default` conventional collection if any package contributes
  ##    to it (the modern shape per Build-Graph-Collections.md).
  ## 2. The legacy `DefaultBuildActionMetadataName` action id pinned by
  ##    a `defaultBuildAction("...")` call inside a `build:` block.
  ##
  ## Returns the empty string when neither path matches, signalling to
  ## the caller that the historical unselected project-root behavior
  ## should apply.
  if projectHasDefaultCollection(snapshot):
    return DefaultBuildCollectionName
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      if node.kind == gnkMetadata and
          node.stableName == DefaultBuildActionMetadataName:
        if result.len > 0 and result != node.payload:
          raise newException(ValueError,
            "conflicting default build action metadata: " & result &
              " and " & node.payload)
        result = node.payload

const
  LoweredGraphCacheMagic = "RBLG"
  # v6 — the lowered-graph cache learned `BuildAction.envPassthrough`.
  # A v5 record cannot carry it, and a v5 record READ as v6 would come
  # back with an empty passthrough set: every action's declared-vs-host
  # classification silently lost on the warm path, which is exactly the
  # defect the bump exists to make impossible. The weak fingerprint is
  # stored explicitly so keys do not move, but `launchChildEnv`'s
  # passthrough resolution and the stage-2 census both read this field,
  # and a census that answers differently cold and warm is not a
  # measurement.
  LoweredGraphCacheVersion = 6'u16
  LoweredGraphAlgorithmVersion = "reprobuild.loweredGraph.v1"

type
  LoweredGraphCacheRecord = object
    modulePath: string
    projectRoot: string
    selectedActionId: string
    pathEnv: string
    cacheKey: string
    actions: seq[BuildAction]
    pools: seq[BuildPool]

  DurableFileEvidence = object
    exists: bool
    size: BiggestInt
    mtimeUnix: int64
    mtimeNs: int64

  WarmToolIdentity = ref object
    key: string
    identityPath: string
    inspectionPath: string
    identityEvidence: DurableFileEvidence
    keyEvidence: DurableFileEvidence
    identity: PathOnlyBuildIdentity

  WarmProviderSnapshot = ref object
    providerArtifactId: string
    snapshotPath: string
    snapshotEvidence: DurableFileEvidence
    snapshot: ProviderGraphSnapshot

  WarmLoweredGraph = ref object
    cachePath: string
    modulePath: string
    projectRoot: string
    selectedActionId: string
    pathEnv: string
    cacheKey: string
    cacheEvidence: DurableFileEvidence
    actions: seq[BuildAction]
    pools: seq[BuildPool]

var warmToolIdentities = initTable[string, WarmToolIdentity]()
var warmProviderSnapshots = initTable[string, WarmProviderSnapshot]()
var warmLoweredGraphs = initTable[string, WarmLoweredGraph]()

# DSL-port M9.R.9 — auto-recurse guards for from-source provisioning.
# When ``--tool-provisioning=from-source`` is active, the dispatcher
# (``ensureFromSourceArtifacts`` below) probes each tool use and may
# schedule a recursive sub-build for any sibling recipe whose artefact
# is missing. The guards cap the call depth, detect cycles, and dedupe
# repeat resolutions across a single build session.
const FromSourceMaxRecursionDepth* = 32
  ## DSL-port M9.R.9 — sanity ceiling for recursive from-source
  ## sub-builds. A 33-recipe chain trips the depth bound diagnostic; in
  ## practice production graphs reach single-digit depth.
var fromSourceBuildStack*: seq[string] = @[]
  ## DSL-port M9.R.9 — active recursion stack (absolute recipe dirs).
  ## A cycle is detected when the dispatcher would push a recipe dir
  ## already present in the stack. Exported for test introspection +
  ## ``repro why`` diagnostics; not intended for external mutation.
var fromSourceResolvedRecipes*: HashSet[string] = initHashSet[string]()
  ## DSL-port M9.R.9 — per-process cache. Once a sibling recipe has
  ## been successfully built once in a session, repeat probes return
  ## immediately (the artefact is now on disk so
  ## ``tryResolveFromSourceTool`` would resolve, but the dedup avoids
  ## even re-walking the candidate list). Exported for test
  ## introspection + ``repro why`` diagnostics.

# ---------------------------------------------------------------------------
# Cross-Repo-Source-Consumption SC-2 — producer graph load + splice
# (executable channel). The pre-pass ``buildAndSpliceProducers`` (defined next
# to ``executeBuildTarget``) resolves each ``uses:`` selector through the SC-1
# ``resolveProducerBinding`` hook, and for a cross-repo PRODUCER (a develop-
# overridden sibling checkout, or a lock-pinned checkout on disk) loads the
# producer's ``repro.nim``, builds its declared ``executable``'s producing
# edge from source (recursively, via ``executeBuildTarget`` — the SAME
# in-process sub-build the from-source auto-recurse pass uses, NOT a ``repro
# build`` subprocess), and records the producer's output ``bin`` dir here so
# the ``mkToolIdentityResolver`` closure can splice it onto the consuming
# action's ``PATH`` (§4.2 point 4, ``repro_build_engine.nim:1975-2010``).
#
# This is the "producer edge is a real input; its bin dir reaches the action
# PATH" deliverable. Keyed by the consumer selector name (matching the ref the
# resolver closure sees). Empty for a build that consumes no cross-repo
# producer, so a non-producer build resolves every ref byte-for-byte as before.
var producerMaterializedBinDirs*: Table[string, seq[string]] =
  initTable[string, seq[string]]()
  ## SC-2 splice sink: consumer selector -> producer output ``bin`` dirs. The
  ## resolver closure returns these as a ``ResolvedToolIdentity.binDirs`` so
  ## the freshly-built producer executable lands on the consuming action's
  ## ``PATH``. Exported for the SC-2 integration test to observe the splice.

type ProducerAuxPaths* = object
  ## Cross-Repo-Source-Consumption SC-3 — the library-channel splice payload
  ## for one resolved producer. A NEW SOURCE (a from-source sibling PROJECT
  ## build), projected onto the SAME aux channels the tool-identity resolver
  ## already threads (``repro_build_engine.nim:611-662,634-650``;
  ## ``ResolvedToolIdentity``'s
  ## ``includeDirs``/``libDirs``/``pkgConfigDirs``/``cmakePrefixDirs`` fields):
  ##   * ``includeDirs``    → ``CPATH``
  ##   * ``libDirs``        → ``LIBRARY_PATH`` + ``LD_LIBRARY_PATH``
  ##   * ``pkgConfigDirs``  → ``PKG_CONFIG_PATH``
  ##   * ``cmakePrefixDirs`` → ``CMAKE_PREFIX_PATH``
  ## No new channel is introduced; SC-3 adds only the SOURCE.
  ##
  ## Cross-Repo-Source-Consumption SC-11 (§4.2a) adds the PARALLEL Nim
  ## language channel ``nimPathDirs``: the importable ``src/`` root of a
  ## sibling Nim ``library``, projected onto the consumer's ``nim c
  ## --path:<dir>`` (a compiler flag, not an env var) — the Nim analogue of
  ## ``includeDirs`` carrying a C library's header root. Driven off the SAME
  ## ``ProducerAuxPaths`` through the same aux-projection seam.
  includeDirs*: seq[string]
  libDirs*: seq[string]
  pkgConfigDirs*: seq[string]
  cmakePrefixDirs*: seq[string]
  nimPathDirs*: seq[string]

proc mergeProducerRuntimeIdentity*(identity: PathOnlyBuildIdentity;
                                   binDirs: var seq[string];
                                   aux: var ProducerAuxPaths) =
  ## Project a consumed executable's declared runtime tools onto the same
  ## PATH and auxiliary channels as the executable producer itself.
  template addUnique(target: var seq[string]; value: string) =
    if value.len > 0 and value notin target:
      target.add(value)

  for actionIdentity in identity.actionIdentities:
    if actionIdentity.resolvedExecutablePath.len > 0:
      binDirs.addUnique(parentDir(actionIdentity.resolvedExecutablePath))
    for path in actionIdentity.pathSearchList:
      binDirs.addUnique(path)
    for path in actionIdentity.pkgConfigSearchList:
      aux.pkgConfigDirs.addUnique(path)
    for path in actionIdentity.cmakePrefixList:
      aux.cmakePrefixDirs.addUnique(path)
      let prefixBin = path / "bin"
      if dirExists(extendedPath(prefixBin)):
        binDirs.addUnique(prefixBin)
    for path in actionIdentity.cpathList:
      aux.includeDirs.addUnique(path)
    for path in actionIdentity.libraryPathList:
      aux.libDirs.addUnique(path)

var producerMaterializedAuxPaths*: Table[string, ProducerAuxPaths] =
  initTable[string, ProducerAuxPaths]()
  ## SC-3 splice sink: consumer selector -> the producer's realized library
  ## aux-channel dirs. The ``mkToolIdentityResolver`` closure returns these as
  ## a ``ResolvedToolIdentity``'s
  ## ``includeDirs``/``libDirs``/``pkgConfigDirs``/``cmakePrefixDirs`` so the
  ## consuming action links/loads the freshly-built sibling library through
  ## ``CPATH``/``LIBRARY_PATH``/``LD_LIBRARY_PATH`` — no manual copy/patchelf.
  ## Empty for a build that consumes no cross-repo LIBRARY producer, so a
  ## non-producer / executable-only build resolves every ref byte-for-byte as
  ## before. Exported for the SC-3 integration test to observe the splice.

var producerActionHashes*: Table[string, string] =
  initTable[string, string]()
  ## SC-2 fingerprint fold sink: consumer selector -> the producer edge's
  ## ACTION-HASH (a content digest over the producer's realized build
  ## product — its executable binaries — bound by declared-output basename).
  ## Folded into the ``weakFingerprint`` of every consumer action that names
  ## the producer via ``toolIdentityRefs`` (``foldProducerActionHashes``),
  ## so the producer edge is a real input of the consuming action and "the
  ## producer's build product changed" invalidates the consumer cache key
  ## (§4.2 point 3; SC-2 deliverable #2 sub-clause). Empty for a build that
  ## consumes no cross-repo producer, so a non-producer action's cache key is
  ## byte-identical to today. Exported for the SC-2 integration test.

var producerBuildStack*: seq[string] = @[]
  ## SC-2 cycle/depth guard (absolute producer roots), the analogue of
  ## ``fromSourceBuildStack`` (``repro_cli_support.nim:5456-5521``). A producer
  ## that transitively consumes the consumer would push a root already on the
  ## stack; that raises loudly with the full cycle path rather than looping.

var producerSourceBindings*: Table[string, ResolvedPackageBinding] =
  initTable[string, ResolvedPackageBinding]()
  ## Cross-Repo-Source-Consumption SC-4 (§4.3) — the SOURCE-content
  ## invalidation sink: consumer selector -> the resolved package binding whose
  ## SOURCE identity folds into the consuming action's weak fingerprint.
  ##
  ## In develop mode the entry is the ``rpbkOverride``
  ## ``ResolvedPackageBinding`` the SC-1 hook returned — carrying the develop
  ## override's ``contentIdentity`` (``computeOverrideContentIdentity``,
  ## ``override_resolution.nim:235-263``, which folds the sibling checkout's
  ## local-path root mtime). ``foldProducerSourceIdentities`` (below) drives
  ## the NEVER-CALLED-OUTSIDE-A-TEST ``foldOverridesIntoFingerprint``
  ## (``override_resolution.nim:349-380``) with these bindings — activating that
  ## fold at the splice seam IS the SC-4 invalidation hook: a change to the
  ## sibling producer's source (a new mtime -> a new ``contentIdentity``) shifts
  ## the consumer action's weak fingerprint so the consumer rebuilds.
  ##
  ## In lock-pinned mode the source identity is the producer ``LockedDep``'s
  ## pinned ``revision`` + ``integrity`` (``repro_lock.nim:143-149``); it is
  ## projected onto the SAME fold framing by synthesizing a ``rpbkOverride``
  ## binding whose ``contentIdentity`` is a digest of ``revision`` + ``integrity``
  ## (a refreshed pin shifts the consumer cache key; an unchanged pin does not).
  ##
  ## Empty for a build that consumes no cross-repo producer, so a no-producer
  ## action's cache key is byte-identical to today
  ## (``foldOverridesIntoFingerprint`` returns the weak fingerprint unchanged
  ## when no ``rpbkOverride`` binding participates, ``override_resolution.nim:375-379``).
  ## Exported for the SC-4 integration test to observe the fold.

proc attachProducerAuxRefs*(actions: var seq[BuildAction]) =
  ## Resolve library aux channels only for the producer refs already carried by
  ## each action. Selecting a producer for one target must not change unrelated
  ## action identities or expose search paths those actions did not request.
  ## String-based shell actions register library refs explicitly; typed
  ## producer calls register the same refs while lowering.
  discard actions

proc foldProducerActionHashes*(actions: var seq[BuildAction]) =
  ## SC-2 (§4.2 point 3): after the consumer graph is lowered, fold each
  ## materialized cross-repo producer's ACTION-HASH (``producerActionHashes``)
  ## into the ``weakFingerprint`` of every consumer action that names that
  ## producer via ``toolIdentityRefs``. This makes the producer edge a real
  ## input of the consuming action's cache key: a changed producer build
  ## product shifts the folded hash and rebuilds the consumer.
  ##
  ## An action that names NO materialized producer keeps its ``weakFingerprint``
  ## byte-for-byte (the fold is skipped entirely), preserving the "an action
  ## consuming no cross-repo producer keeps its cache key unchanged" property
  ## (the same property ``foldOverridesIntoFingerprint`` guarantees). When
  ## ``producerActionHashes`` is empty (the common case — no cross-repo
  ## producer), this is a no-op over the whole graph.
  if producerActionHashes.len == 0:
    return
  for action in actions.mitems:
    if action.toolIdentityRefs.len == 0:
      continue
    # Collect the folded producer hashes for this action in the action's own
    # ref order (stable), so the resulting fingerprint is deterministic.
    var contributions: seq[string] = @[]
    for refName in action.toolIdentityRefs:
      if producerActionHashes.hasKey(refName):
        contributions.add(refName & "=" & producerActionHashes[refName])
    if contributions.len == 0:
      continue
    var payload = "cross-repo-producer-fold.v1\x00" &
      digestHex(action.weakFingerprint) & "\x00"
    for contribution in contributions:
      payload.add(contribution)
      payload.add('\x00')
    action.weakFingerprint =
      blake3DomainDigest(payload.bytesOf(), hdActionFingerprint)

proc lockPinnedSourceBinding*(selector: string; dep: LockedDep):
    ResolvedPackageBinding =
  ## Cross-Repo-Source-Consumption SC-4 (§4.3, lock-pinned arm) — project a
  ## lock-pinned producer's SOURCE identity (its ``LockedDep``'s pinned
  ## ``revision`` + ``integrity``, ``repro_lock.nim:143-149``) onto the SAME
  ## ``foldOverridesIntoFingerprint`` framing develop mode uses, by synthesizing
  ## an ``rpbkOverride`` binding whose ``contentIdentity`` is a deterministic
  ## digest of the pinned coordinates + integrity. A refreshed pin (a new
  ## ``revision``/``integrity``) shifts this digest and therefore the consumer
  ## cache key; an unchanged pin leaves it stable — the lock-pinned analogue of
  ## the develop ``contentIdentity`` (§4.3: "a changed pin ... shifts the
  ## consumer's cache key through the same fold framing").
  let coordRevision =
    if dep.coordinates.kind == ckVcs: dep.coordinates.revision
    else: ""
  let coordUrl =
    if dep.coordinates.kind == ckVcs: dep.coordinates.url
    else: ""
  var payload = "cross-repo-producer-lock-source.v1\x00" & selector & "\x00" &
    coordUrl & "\x00" & coordRevision & "\x00" & dep.integrity & "\x00"
  let identity = toHex(blake3DomainDigest(payload.bytesOf(),
    hdActionFingerprint).bytes)
  ResolvedPackageBinding(
    kind: rpbkOverride,
    shadowed: UpstreamPackageBinding(
      packageName: selector, fetchUrl: coordUrl, revision: coordRevision),
    override: DevelopOverrideEntry(package: selector, state: "pinned"),
    localPathAbsolute: "",
    contentIdentity: identity)

proc onDiskSiblingSourceBinding*(selector, siblingRoot: string):
    ResolvedPackageBinding =
  ## Cross-Repo-Source-Consumption SC-4 (§4.3, develop-mode on-disk-sibling arm)
  ## — project a producer consumed as a plain on-disk workspace sibling (no
  ## develop-override entry, no committed lock pin: ``pbkOnDiskSibling``) onto
  ## the SAME ``foldOverridesIntoFingerprint`` framing develop mode uses, by
  ## synthesizing an ``rpbkOverride`` binding whose ``contentIdentity`` folds the
  ## sibling's absolute root path + its root mtime — the develop-editable analogue
  ## of ``computeOverrideContentIdentity`` (a develop override with ``state ==
  ## "editable"`` points at exactly this same sibling checkout, so the folded
  ## identity matches). A touched sibling root shifts the digest and therefore the
  ## consumer cache key; an unchanged sibling leaves it stable.
  let absRoot = absolutePath(siblingRoot)
  let mtimeIso =
    try:
      if dirExists(extendedPath(absRoot)) or fileExists(extendedPath(absRoot)):
        $getLastModificationTime(extendedPath(absRoot))
      else:
        ""
    except CatchableError:
      ""
  var payload = "cross-repo-producer-sibling-source.v1\x00" & selector &
    "\x00" & absRoot & "\x00" & mtimeIso & "\x00"
  let identity = toHex(blake3DomainDigest(payload.bytesOf(),
    hdActionFingerprint).bytes)
  ResolvedPackageBinding(
    kind: rpbkOverride,
    shadowed: UpstreamPackageBinding(packageName: selector),
    override: DevelopOverrideEntry(package: selector, state: "editable"),
    localPathAbsolute: absRoot,
    contentIdentity: identity)

# ---------------------------------------------------------------------------
# Cross-Repo-Source-Consumption SC-6 (§5.2, §6) — lock-pinned VCS-sibling
# fetch. When a producer is consumed in LOCK-PINNED mode (no develop override)
# and its checkout is NOT already on disk beside the consumer, fetch the
# producer's VCS at the committed ``LockedDep``'s pinned ``revision``, verify
# the fetched commit against the locked ``integrity`` (reusing the SAME
# ``gitObjectMultihash`` computation the MO-9 gate uses,
# ``verifyLockedIntegrityAtCoordinates`` / ``computeDepIntegrity``), and hand
# back the fetched tree root so the SC-2/SC-3 splice builds the producer's edge
# from that source. The producer is built from its OWN committed ``repro.lock``
# (§6): we only materialize the producer revision here — the producer's own
# solve is not re-run against the consumer's constraints.
# ---------------------------------------------------------------------------

proc gitObjectFormatOf(repoRoot: string): string
  ## Forward-declared for SC-6's ``fetchLockPinnedProducer`` integrity check;
  ## the body (MO-8) lives with the other lock-integrity helpers below.

proc lockPinnedProducerCacheRoot(workspaceRoot: string): string =
  ## Where a fetched lock-pinned producer checkout is materialized. Under the
  ## consumer workspace's ``.repro`` tree (workspace-local, never ``$HOME``), so
  ## the fetch is hermetic to the consumer and cleaned with the workspace. Keyed
  ## per-producer + per-revision below so a refreshed pin fetches a fresh tree.
  absolutePath(workspaceRoot) / ".repro" / "cross-repo-producers"

proc fetchLockPinnedProducer*(dep: LockedDep; workspaceRoot: string): string =
  ## SC-6 (§5.2): materialize a lock-pinned producer's source at its pinned
  ## revision and verify integrity. Returns the checkout root of the fetched
  ## producer tree; raises loudly (never silently falls back) on an unreachable
  ## revision or an integrity mismatch — the reproducibility boundary §5.2/§6
  ## require. Only the ``ckVcs`` (git) coordinate kind is materialized here (the
  ## primary workspace-repo case, ``repro_lock.nim:110-133``); a non-VCS
  ## coordinate returns "" (left to its own resolution path).
  ##
  ## Idempotent + revision-keyed: the checkout lives at
  ## ``<workspace>/.repro/cross-repo-producers/<name>/<revision>``. A second
  ## consume of the SAME pin reuses the existing verified checkout; a REFRESHED
  ## pin (new revision) materializes a fresh sibling tree, so a changed pin is
  ## observable to the SC-4 fold AND rebuilds from the new source.
  if dep.coordinates.kind != ckVcs:
    return ""
  let url = dep.coordinates.url
  let revision = dep.coordinates.revision
  if url.len == 0 or revision.len == 0:
    raise newException(OSError,
      "cross-repo producer \"" & dep.name &
      "\" is pinned in the lock but its VCS coordinates are incomplete " &
      "(url=\"" & url & "\" revision=\"" & revision &
      "\"); cannot fetch it at the pinned revision. Regenerate the lock at a " &
      "concrete revision.")
  let gitBin = findExe("git")
  if gitBin.len == 0:
    raise newException(OSError,
      "cross-repo producer \"" & dep.name &
      "\" must be fetched from its VCS at the pinned revision " & revision &
      " but no ``git`` binary is on PATH.")
  let checkoutRoot =
    lockPinnedProducerCacheRoot(workspaceRoot) / dep.name / revision

  proc git(args: openArray[string]; cwd = ""): tuple[code: int; output: string] =
    var cmd = quoteShell(gitBin)
    for a in args:
      cmd.add(" ")
      cmd.add(quoteShell(a))
    let r = execCmdEx(cmd, options = {poUsePath}, workingDir = cwd,
      env = scrubbedGitRepositoryEnv())
    (code: r.exitCode, output: r.output)

  proc verifyRevisionIntegrity() =
    ## Reuse the MO-9 gate computation: the fetched commit object at the pinned
    ## revision must be PRESENT and its self-describing object id must equal the
    ## locked integrity. A tampered integrity or an unreachable revision fails.
    let rp = git(["-C", checkoutRoot, "rev-parse", "--verify", "--quiet",
      revision & "^{commit}"])
    if rp.code != 0 or rp.output.strip().len == 0:
      raise newException(OSError,
        "cross-repo producer \"" & dep.name & "\" locked revision " & revision &
        " is not present/reachable in the fetched checkout at " & checkoutRoot &
        " (the pin points at a revision the remote " & url &
        " does not provide).")
    if dep.integrity.len > 0 and dep.integrity.startsWith("git-sha"):
      let observed =
        gitObjectMultihash(gitObjectFormatOf(checkoutRoot), revision)
      if observed != dep.integrity:
        raise newException(OSError,
          "cross-repo producer \"" & dep.name &
          "\" integrity check FAILED: the fetched commit at the pinned " &
          "revision " & revision & " has integrity " & observed &
          " but the lock records " & dep.integrity &
          " (the fetch is refused; regenerate the lock or fix the remote).")

  # Reuse an already-materialized + verified checkout for the SAME pin.
  if dirExists(extendedPath(checkoutRoot / ".git")):
    verifyRevisionIntegrity()
    return checkoutRoot

  createDir(extendedPath(parentDir(checkoutRoot)))
  # A partially-materialized directory from a prior interrupted fetch is not
  # trustworthy — start clean so the integrity check governs.
  if dirExists(extendedPath(checkoutRoot)):
    removeDir(extendedPath(checkoutRoot))
  createDir(extendedPath(checkoutRoot))

  # Initialize an empty repo and fetch exactly the pinned revision from the
  # remote, then check it out detached. ``git fetch <url> <rev>`` fetches the
  # single commit (and its reachable tree) without needing a named branch — the
  # minimal fetch the pinned-revision contract needs.
  var step = git(["-C", checkoutRoot, "init", "--quiet"])
  if step.code != 0:
    raise newException(OSError,
      "cross-repo producer \"" & dep.name &
      "\" fetch failed: could not initialize a checkout at " & checkoutRoot &
      ": " & step.output.strip())
  step = git(["-C", checkoutRoot, "fetch", "--quiet", "--depth", "1", url,
    revision])
  if step.code != 0:
    # A remote that cannot serve a bare revision by SHA (some servers reject
    # ``fetch <sha>`` without ``uploadpack.allowReachableSHA1InWant``) — fall
    # back to fetching everything, then checking out the pinned revision.
    step = git(["-C", checkoutRoot, "fetch", "--quiet", url])
    if step.code != 0:
      raise newException(OSError,
        "cross-repo producer \"" & dep.name & "\" fetch failed from " & url &
        " at pinned revision " & revision & ": " & step.output.strip())
  step = git(["-C", checkoutRoot, "checkout", "--quiet", "--detach", revision])
  if step.code != 0:
    raise newException(OSError,
      "cross-repo producer \"" & dep.name &
      "\" fetch succeeded but could not check out the pinned revision " &
      revision & " at " & checkoutRoot & ": " & step.output.strip())

  # Verify integrity AFTER materialization — a tampered integrity or an
  # unreachable revision fails the fetch loudly (§5.2 "verifies integrity").
  verifyRevisionIntegrity()
  checkoutRoot

proc foldProducerSourceIdentities*(actions: var seq[BuildAction]) =
  ## Cross-Repo-Source-Consumption SC-4 (§4.3): after the consumer graph is
  ## lowered, fold each materialized cross-repo producer's SOURCE identity into
  ## the ``weakFingerprint`` of every consumer action that names the producer
  ## via ``toolIdentityRefs``. This is the SOURCE-content arm of invalidation —
  ## the complement of SC-2/SC-3's build-PRODUCT ``foldProducerActionHashes``.
  ##
  ## The fold is driven by ``foldOverridesIntoFingerprint``
  ## (``override_resolution.nim:349-380``) — the fold that until SC-4 was called
  ## ONLY from ``t_workspace_override_shadows_upstream_in_resolver.nim``, never
  ## from the engine. Activating it HERE, at the splice seam, IS the SC-4
  ## invalidation hook the spec calls for: a change to a develop-overridden
  ## sibling producer's source (a new local-path root mtime -> a new
  ## ``computeOverrideContentIdentity`` -> a new binding ``contentIdentity``)
  ## shifts the consumer action's weak fingerprint so the consumer rebuilds. In
  ## lock-pinned mode the source identity is the producer ``LockedDep``'s
  ## pinned ``revision`` + ``integrity`` (``lockPinnedSourceBinding``), projected
  ## onto the SAME fold.
  ##
  ## An action that names NO materialized producer (or whose named producers all
  ## resolved to non-``rpbkOverride`` bindings) keeps its ``weakFingerprint``
  ## byte-for-byte: ``foldOverridesIntoFingerprint`` returns the input digest
  ## unchanged when no ``rpbkOverride`` binding participates
  ## (``override_resolution.nim:375-379``). When ``producerSourceBindings`` is
  ## empty (the common case — no cross-repo producer), this is a whole-graph
  ## no-op, so a no-producer action's cache key is byte-identical to today.
  if producerSourceBindings.len == 0:
    return
  for action in actions.mitems:
    if action.toolIdentityRefs.len == 0:
      continue
    # Collect the source bindings for this action's producer refs in the
    # action's own ref order (stable), so the fold is deterministic. Only
    # ``rpbkOverride`` bindings actually shift the fingerprint; the collection
    # follows the ref order the SC-2 build-product fold already relies on.
    var bindings: seq[ResolvedPackageBinding] = @[]
    for refName in action.toolIdentityRefs:
      if producerSourceBindings.hasKey(refName):
        bindings.add(producerSourceBindings[refName])
    if bindings.len == 0:
      continue
    action.weakFingerprint =
      foldOverridesIntoFingerprint(action.weakFingerprint, bindings)

proc durableFileEvidence(path: string): DurableFileEvidence =
  try:
    if not fileExists(extendedPath(path)):
      return DurableFileEvidence(exists: false)
    let info = getFileInfo(extendedPath(path), followSymlink = false)
    DurableFileEvidence(exists: true, size: info.size,
      mtimeUnix: info.lastWriteTime.toUnix,
      mtimeNs: int64(info.lastWriteTime.nanosecond))
  except CatchableError:
    DurableFileEvidence(exists: false)

proc evidenceFresh(path: string; evidence: DurableFileEvidence): bool =
  durableFileEvidence(path) == evidence

proc readByteValue(bytes: openArray[byte]; pos: var int): byte =
  if pos >= bytes.len:
    raiseEnvelopeError(eeMalformed, "truncated byte")
  result = bytes[pos]
  inc pos

proc writeDigestPayload(outp: var seq[byte]; digest: ContentDigest) =
  outp.add(byte(ord(digest.algorithm)))
  outp.add(byte(ord(digest.domain)))
  outp.add(digest.bytes)

proc readDigestPayload(bytes: openArray[byte]; pos: var int): ContentDigest =
  let algorithm = readByteValue(bytes, pos)
  let domain = readByteValue(bytes, pos)
  if algorithm > byte(ord(haXxh3_64)):
    raiseEnvelopeError(eeMalformed, "invalid digest algorithm")
  if domain > byte(ord(hdMetadataEnvelope)):
    raiseEnvelopeError(eeMalformed, "invalid digest domain")
  if pos + 32 > bytes.len:
    raiseEnvelopeError(eeMalformed, "truncated digest bytes")
  result.algorithm = HashAlgorithm(algorithm)
  result.domain = HashDomain(domain)
  for i in 0 ..< 32:
    result.bytes[i] = bytes[pos + i]
  pos += 32

proc writeStringSeq(outp: var seq[byte]; values: openArray[string]) =
  outp.writeU32Le(uint32(values.len))
  for value in values:
    outp.writeString(value)

proc readStringSeq(bytes: openArray[byte]; pos: var int): seq[string] =
  let count = int(readU32Le(bytes, pos))
  result = newSeq[string](count)
  for i in 0 ..< count:
    result[i] = readString(bytes, pos)

proc writeExpectedDependencyFile(outp: var seq[byte];
                                 value: ExpectedDependencyFile) =
  outp.writeString(value.logicalName)
  outp.writeString(value.path)
  outp.add(if value.required: 1'u8 else: 0'u8)

proc readExpectedDependencyFile(bytes: openArray[byte]; pos: var int):
    ExpectedDependencyFile =
  result.logicalName = readString(bytes, pos)
  result.path = readString(bytes, pos)
  result.required = readByteValue(bytes, pos) != 0

proc writeProcessSpec(outp: var seq[byte]; process: ProcessSpec) =
  outp.add(byte(ord(process.kind)))
  outp.writeString(process.executable.value)
  outp.writeStringSeq(process.args)
  outp.writeU32Le(uint32(process.env.len))
  for item in process.env:
    outp.writeString(item.name)
    outp.writeString(item.value)
  outp.writeString(process.cwd.value)
  outp.add(byte(ord(process.stdinPolicy)))
  outp.add(byte(ord(process.stdoutPolicy)))
  outp.add(byte(ord(process.stderrPolicy)))

proc readProcessSpec(bytes: openArray[byte]; pos: var int): ProcessSpec =
  let kind = readByteValue(bytes, pos)
  if kind > byte(ord(ckShell)):
    raiseEnvelopeError(eeMalformed, "invalid process kind")
  result.kind = CommandKind(kind)
  result.executable = NormalizedPath(kind: npRelative, value: readString(bytes, pos))
  result.args = readStringSeq(bytes, pos)
  let envCount = int(readU32Le(bytes, pos))
  result.env = newSeq[EnvVar](envCount)
  for i in 0 ..< envCount:
    result.env[i].name = readString(bytes, pos)
    result.env[i].value = readString(bytes, pos)
  result.cwd = NormalizedPath(kind: npRelative, value: readString(bytes, pos))
  let stdinPolicy = readByteValue(bytes, pos)
  let stdoutPolicy = readByteValue(bytes, pos)
  let stderrPolicy = readByteValue(bytes, pos)
  if stdinPolicy > byte(ord(spCapture)) or stdoutPolicy > byte(ord(spCapture)) or
      stderrPolicy > byte(ord(spCapture)):
    raiseEnvelopeError(eeMalformed, "invalid stdio policy")
  result.stdinPolicy = StdioPolicy(stdinPolicy)
  result.stdoutPolicy = StdioPolicy(stdoutPolicy)
  result.stderrPolicy = StdioPolicy(stderrPolicy)

proc writeDependencyPolicy(outp: var seq[byte];
                           policy: DependencyGatheringPolicy) =
  outp.add(byte(ord(policy.kind)))
  outp.add(byte(ord(policy.completeness)))
  outp.writeU32Le(uint32(policy.recognizedReports.len))
  for report in policy.recognizedReports:
    outp.writeString($report.formatName)
    outp.writeU32Le(uint32(report.outputs.len))
    for output in report.outputs:
      outp.writeExpectedDependencyFile(output)
    outp.add(byte(ord(report.completeness)))
  outp.writeU32Le(uint32(policy.postBuildConverters.len))
  for converterSpec in policy.postBuildConverters:
    outp.writeProcessSpec(converterSpec.converterProcess)
    outp.writeU32Le(uint32(converterSpec.inputs.len))
    for input in converterSpec.inputs:
      outp.writeExpectedDependencyFile(input)
    outp.writeU32Le(uint32(converterSpec.outputs.len))
    for output in converterSpec.outputs:
      outp.writeExpectedDependencyFile(output)
    outp.add(byte(ord(converterSpec.outputKind)))
    outp.writeString($converterSpec.outputFormatName)
    outp.add(byte(ord(converterSpec.completeness)))
  outp.writeStringSeq(policy.ignoredInputPrefixes)

proc readCompleteness(bytes: openArray[byte]; pos: var int):
    DependencyEvidenceCompleteness =
  let value = readByteValue(bytes, pos)
  if value > byte(ord(decDiagnosticOnly)):
    raiseEnvelopeError(eeMalformed, "invalid dependency completeness")
  DependencyEvidenceCompleteness(value)

proc readDependencyPolicy(bytes: openArray[byte]; pos: var int):
    DependencyGatheringPolicy =
  let kind = readByteValue(bytes, pos)
  if kind > byte(ord(dgPostBuildConverterValidatedByMonitor)):
    raiseEnvelopeError(eeMalformed, "invalid dependency gathering kind")
  result.kind = DependencyGatheringKind(kind)
  result.completeness = readCompleteness(bytes, pos)
  let reportCount = int(readU32Le(bytes, pos))
  result.recognizedReports = newSeq[RecognizedDependencyReportSpec](reportCount)
  for i in 0 ..< reportCount:
    result.recognizedReports[i].formatName =
      DependencyFormatName(readString(bytes, pos))
    let outputCount = int(readU32Le(bytes, pos))
    result.recognizedReports[i].outputs = newSeq[ExpectedDependencyFile](outputCount)
    for j in 0 ..< outputCount:
      result.recognizedReports[i].outputs[j] =
        readExpectedDependencyFile(bytes, pos)
    result.recognizedReports[i].completeness = readCompleteness(bytes, pos)
  let converterCount = int(readU32Le(bytes, pos))
  result.postBuildConverters =
    newSeq[PostBuildDependencyConverterSpec](converterCount)
  for i in 0 ..< converterCount:
    result.postBuildConverters[i].converterProcess = readProcessSpec(bytes, pos)
    let inputCount = int(readU32Le(bytes, pos))
    result.postBuildConverters[i].inputs =
      newSeq[ExpectedDependencyFile](inputCount)
    for j in 0 ..< inputCount:
      result.postBuildConverters[i].inputs[j] =
        readExpectedDependencyFile(bytes, pos)
    let outputCount = int(readU32Le(bytes, pos))
    result.postBuildConverters[i].outputs =
      newSeq[ExpectedDependencyFile](outputCount)
    for j in 0 ..< outputCount:
      result.postBuildConverters[i].outputs[j] =
        readExpectedDependencyFile(bytes, pos)
    let outputKind = readByteValue(bytes, pos)
    if outputKind > byte(ord(dcoRecognizedFormat)):
      raiseEnvelopeError(eeMalformed, "invalid converter output kind")
    result.postBuildConverters[i].outputKind =
      DependencyConverterOutputKind(outputKind)
    result.postBuildConverters[i].outputFormatName =
      DependencyFormatName(readString(bytes, pos))
    result.postBuildConverters[i].completeness = readCompleteness(bytes, pos)
  result.ignoredInputPrefixes = readStringSeq(bytes, pos)

proc writeCacheEntryIdentity(outp: var seq[byte];
                             identity: CacheEntryIdentity) =
  outp.writeString(identity.packageName)
  outp.writeString(identity.packageVersion)
  var optionNames: seq[string] = @[]
  for name in identity.selectedOptions.keys:
    optionNames.add(name)
  optionNames.sort(cmp)
  outp.writeU32Le(uint32(optionNames.len))
  for name in optionNames:
    outp.writeString(name)
    outp.writeString(identity.selectedOptions[name])
  outp.writeString(identity.platform.cpu)
  outp.writeString(identity.platform.os)
  outp.writeString(identity.platform.abi)
  outp.writeString(identity.platform.libcVariant)
  outp.writeString(identity.toolchain.name)
  outp.writeString(identity.toolchain.version)
  outp.writeString(identity.toolchain.hostLdSoAbi)
  outp.writeString(identity.toolchain.extraFingerprint)
  outp.writeStringSeq(identity.depClosure)
  outp.writeString(identity.providerRevision)

proc readCacheEntryIdentity(bytes: openArray[byte]; pos: var int):
    CacheEntryIdentity =
  result.packageName = readString(bytes, pos)
  result.packageVersion = readString(bytes, pos)
  result.selectedOptions = newTable[string, string]()
  let optionCount = int(readU32Le(bytes, pos))
  for _ in 0 ..< optionCount:
    let name = readString(bytes, pos)
    result.selectedOptions[name] = readString(bytes, pos)
  result.platform.cpu = readString(bytes, pos)
  result.platform.os = readString(bytes, pos)
  result.platform.abi = readString(bytes, pos)
  result.platform.libcVariant = readString(bytes, pos)
  result.toolchain.name = readString(bytes, pos)
  result.toolchain.version = readString(bytes, pos)
  result.toolchain.hostLdSoAbi = readString(bytes, pos)
  result.toolchain.extraFingerprint = readString(bytes, pos)
  result.depClosure = readStringSeq(bytes, pos)
  result.providerRevision = readString(bytes, pos)

proc writeBuildAction(outp: var seq[byte]; action: BuildAction) =
  outp.writeString($action.governingLockIdentity)
  outp.add(byte(ord(action.kind)))
  outp.writeString(action.id)
  outp.writeStringSeq(action.deps)
  outp.writeStringSeq(action.inputs)
  outp.writeStringSeq(action.outputs)
  outp.writeStringSeq(action.argv)
  outp.writeString(action.cwd)
  outp.writeStringSeq(action.env)
  outp.writeStringSeq(action.envPassthrough)
  outp.writeString(action.pool)
  outp.writeU32Le(action.poolUnits)
  outp.writeU32Le(action.cpuMilli)
  outp.writeU64Le(action.memoryBytes)
  outp.writeString(action.commandStatsId)
  outp.add(if action.cacheable: 1'u8 else: 0'u8)
  outp.writeDigestPayload(action.weakFingerprint)
  outp.add(byte(ord(action.actionCachePolicy)))
  outp.writeString(action.depfile)
  outp.writeString(action.dynamicDepsFile)
  outp.writeString(action.monitorDepfile)
  outp.writeDependencyPolicy(action.dependencyPolicy)
  outp.writeString(action.builtinText)
  outp.writeStringSeq(action.builtinEntries)
  outp.writeStringSeq(action.targetNames)
  outp.writeU32Le(uint32(action.typedOutputs.len))
  for typedOutput in action.typedOutputs:
    outp.writeString(typedOutput.fieldName)
    outp.writeStringSeq(typedOutput.types)
    outp.writeString(typedOutput.path)
  outp.add(if action.publishToBinaryCache: 1'u8 else: 0'u8)
  if action.cacheEntryIdentity.isSome:
    outp.add(1'u8)
    outp.writeCacheEntryIdentity(action.cacheEntryIdentity.get())
  else:
    outp.add(0'u8)
  outp.writeStringSeq(action.toolIdentityRefs)
  outp.writeU32Le(uint32(action.toolIdentityRefKinds.len))
  for kind in action.toolIdentityRefKinds:
    outp.add(byte(ord(kind)))
  outp.writeString(action.cachePlatformTag)
  outp.writeStringSeq(action.declaredOutputs)
  outp.writeStringSeq(action.readOnlyRoots)
  outp.add(if action.requiresElevation: 1'u8 else: 0'u8)

proc readBuildAction(bytes: openArray[byte]; pos: var int): BuildAction =
  result = BuildAction(
    governingLockIdentity: LockIdentity(readString(bytes, pos)))
  let kind = readByteValue(bytes, pos)
  if kind > byte(ord(high(BuildActionKind))):
    raiseEnvelopeError(eeMalformed, "invalid build action kind")
  result.kind = BuildActionKind(kind)
  result.id = readString(bytes, pos)
  result.deps = readStringSeq(bytes, pos)
  result.inputs = readStringSeq(bytes, pos)
  result.outputs = readStringSeq(bytes, pos)
  result.argv = readStringSeq(bytes, pos)
  result.cwd = readString(bytes, pos)
  result.env = readStringSeq(bytes, pos)
  result.envPassthrough = readStringSeq(bytes, pos)
  result.pool = readString(bytes, pos)
  result.poolUnits = readU32Le(bytes, pos)
  result.cpuMilli = readU32Le(bytes, pos)
  result.memoryBytes = readU64Le(bytes, pos)
  result.commandStatsId = readString(bytes, pos)
  result.cacheable = readByteValue(bytes, pos) != 0
  result.weakFingerprint = readDigestPayload(bytes, pos)
  let policy = readByteValue(bytes, pos)
  if policy > byte(ord(ffpHybrid)):
    raiseEnvelopeError(eeMalformed, "invalid action cache policy")
  result.actionCachePolicy = FileFingerprintPolicy(policy)
  result.depfile = readString(bytes, pos)
  result.dynamicDepsFile = readString(bytes, pos)
  result.monitorDepfile = readString(bytes, pos)
  result.dependencyPolicy = readDependencyPolicy(bytes, pos)
  result.builtinText = readString(bytes, pos)
  result.builtinEntries = readStringSeq(bytes, pos)
  result.targetNames = readStringSeq(bytes, pos)
  let typedOutputCount = int(readU32Le(bytes, pos))
  result.typedOutputs = newSeq[EngineTypedOutput](typedOutputCount)
  for i in 0 ..< typedOutputCount:
    result.typedOutputs[i].fieldName = readString(bytes, pos)
    result.typedOutputs[i].types = readStringSeq(bytes, pos)
    result.typedOutputs[i].path = readString(bytes, pos)
  let publishByte = readByteValue(bytes, pos)
  if publishByte > 1'u8:
    raiseEnvelopeError(eeMalformed,
      "invalid lowered action publish sentinel")
  result.publishToBinaryCache = publishByte == 1'u8
  let identityByte = readByteValue(bytes, pos)
  if identityByte > 1'u8:
    raiseEnvelopeError(eeMalformed,
      "invalid lowered action identity sentinel")
  if identityByte == 1'u8:
    result.cacheEntryIdentity = some(readCacheEntryIdentity(bytes, pos))
  result.toolIdentityRefs = readStringSeq(bytes, pos)
  let refKindCount = int(readU32Le(bytes, pos))
  result.toolIdentityRefKinds = newSeq[DepKind](refKindCount)
  for i in 0 ..< refKindCount:
    let rawKind = readByteValue(bytes, pos)
    if rawKind > byte(ord(high(DepKind))):
      raiseEnvelopeError(eeMalformed,
        "invalid lowered action tool-reference kind")
    result.toolIdentityRefKinds[i] = DepKind(rawKind)
  result.cachePlatformTag = readString(bytes, pos)
  result.declaredOutputs = readStringSeq(bytes, pos)
  result.readOnlyRoots = readStringSeq(bytes, pos)
  let elevationByte = readByteValue(bytes, pos)
  if elevationByte > 1'u8:
    raiseEnvelopeError(eeMalformed,
      "invalid lowered action elevation sentinel")
  result.requiresElevation = elevationByte == 1'u8

proc encodeLoweredGraphCache(record: LoweredGraphCacheRecord): seq[byte] =
  result.writeString(LoweredGraphCacheMagic)
  result.writeU16Le(LoweredGraphCacheVersion)
  result.writeString(record.modulePath)
  result.writeString(record.projectRoot)
  result.writeString(record.selectedActionId)
  result.writeString(record.pathEnv)
  result.writeString(record.cacheKey)
  result.writeU32Le(uint32(record.pools.len))
  for pool in record.pools:
    result.writeString(pool.name)
    result.writeU32Le(pool.capacity)
  result.writeU32Le(uint32(record.actions.len))
  for action in record.actions:
    result.writeBuildAction(action)

proc decodeLoweredGraphCache(bytes: openArray[byte]): LoweredGraphCacheRecord =
  var pos = 0
  if readString(bytes, pos) != LoweredGraphCacheMagic:
    raiseEnvelopeError(eeUnknownMagic, "unknown lowered graph cache magic")
  let version = readU16Le(bytes, pos)
  if version != LoweredGraphCacheVersion:
    raiseEnvelopeError(eeUnsupportedVersion,
      "unsupported lowered graph cache version")
  result.modulePath = readString(bytes, pos)
  result.projectRoot = readString(bytes, pos)
  result.selectedActionId = readString(bytes, pos)
  result.pathEnv = readString(bytes, pos)
  result.cacheKey = readString(bytes, pos)
  let poolCount = int(readU32Le(bytes, pos))
  result.pools = newSeq[BuildPool](poolCount)
  for i in 0 ..< poolCount:
    result.pools[i].name = readString(bytes, pos)
    result.pools[i].capacity = readU32Le(bytes, pos)
  let actionCount = int(readU32Le(bytes, pos))
  result.actions = newSeq[BuildAction](actionCount)
  for i in 0 ..< actionCount:
    result.actions[i] = readBuildAction(bytes, pos)
  if pos != bytes.len:
    raiseEnvelopeError(eeMalformed, "trailing lowered graph cache bytes")

when defined(reproLoweredGraphCodecTest):
  proc loweredGraphCacheBytesForTest*(actions: seq[BuildAction]): seq[byte] =
    encodeLoweredGraphCache(LoweredGraphCacheRecord(actions: actions))

  proc loweredGraphCacheActionsForTest*(bytes: seq[byte]): seq[BuildAction] =
    decodeLoweredGraphCache(bytes).actions

  proc loweredGraphCacheVersionOffsetForTest*(): int =
    var prefix: seq[byte]
    prefix.writeString(LoweredGraphCacheMagic)
    prefix.len

  proc loweredGraphActionRoundTripForTest*(actions: seq[BuildAction]):
      seq[BuildAction] =
    loweredGraphCacheActionsForTest(loweredGraphCacheBytesForTest(actions))

proc loweredGraphCachePath(outDir, selectedActionId: string): string =
  let label =
    if selectedActionId.len > 0:
      selectedActionId
    else:
      "__omitted_default__"
  outDir / "lowered-graph-cache" /
    (safePathSegment(label, "default") & "-" &
      toHex(weakFingerprintFromText(label).bytes)[0 .. 15] & ".rbbg")

proc readFreshLoweredGraphCache(path, modulePath, projectRoot, selectedActionId,
                                pathEnv, cacheKey: string):
    Option[tuple[actions: seq[BuildAction]; pools: seq[BuildPool]]] =
  if not fileExists(extendedPath(path)):
    return none(tuple[actions: seq[BuildAction]; pools: seq[BuildPool]])
  try:
    let record = decodeLoweredGraphCache(toBytes(readFile(extendedPath(path))))
    if record.modulePath != modulePath or record.projectRoot != projectRoot or
        record.selectedActionId != selectedActionId or record.pathEnv != pathEnv or
        record.cacheKey != cacheKey:
      return none(tuple[actions: seq[BuildAction]; pools: seq[BuildPool]])
    return some((actions: record.actions, pools: record.pools))
  except CatchableError:
    return none(tuple[actions: seq[BuildAction]; pools: seq[BuildPool]])

proc warmReadFreshLoweredGraphCache(path, modulePath, projectRoot,
                                    selectedActionId, pathEnv,
                                    cacheKey: string):
    Option[tuple[actions: seq[BuildAction]; pools: seq[BuildPool]]] =
  let tableKey = path & "\0" & cacheKey
  if warmLoweredGraphs.hasKey(tableKey):
    let warm = warmLoweredGraphs[tableKey]
    if warm.cachePath == path and warm.modulePath == modulePath and
        warm.projectRoot == projectRoot and
        warm.selectedActionId == selectedActionId and
        warm.pathEnv == pathEnv and warm.cacheKey == cacheKey and
        evidenceFresh(path, warm.cacheEvidence):
      return some((actions: warm.actions, pools: warm.pools))
  result = readFreshLoweredGraphCache(path, modulePath, projectRoot,
    selectedActionId, pathEnv, cacheKey)
  if result.isSome:
    let lowered = result.get()
    warmLoweredGraphs[tableKey] = WarmLoweredGraph(cachePath: path,
      modulePath: modulePath, projectRoot: projectRoot,
      selectedActionId: selectedActionId, pathEnv: pathEnv,
      cacheKey: cacheKey, cacheEvidence: durableFileEvidence(path),
      actions: lowered.actions, pools: lowered.pools)

proc writeLoweredGraphCache(path, modulePath, projectRoot, selectedActionId,
                            pathEnv, cacheKey: string;
                            lowered: tuple[actions: seq[BuildAction];
                                           pools: seq[BuildPool]]) =
  createDir(extendedPath(parentDir(path)))
  let record = LoweredGraphCacheRecord(
    modulePath: modulePath,
    projectRoot: projectRoot,
    selectedActionId: selectedActionId,
    pathEnv: pathEnv,
    cacheKey: cacheKey,
    actions: lowered.actions,
    pools: lowered.pools)
  writeFile(extendedPath(path), fromBytes(encodeLoweredGraphCache(record)))
  warmLoweredGraphs[path & "\0" & cacheKey] = WarmLoweredGraph(cachePath: path,
    modulePath: modulePath, projectRoot: projectRoot,
    selectedActionId: selectedActionId, pathEnv: pathEnv, cacheKey: cacheKey,
    cacheEvidence: durableFileEvidence(path), actions: lowered.actions,
    pools: lowered.pools)

proc evidenceJson(evidence: PathSetEvidence): JsonNode =
  %*{
    "declaredInputs": jsonStringSeq(evidence.declaredInputs),
    "declaredOutputs": jsonStringSeq(evidence.declaredOutputs),
    "depfileInputs": jsonStringSeq(evidence.depfileInputs),
    "monitorReads": jsonStringSeq(evidence.monitorReads),
    "monitorWrites": jsonStringSeq(evidence.monitorWrites),
    "monitorProbes": jsonStringSeq(evidence.monitorProbes),
    "diagnostics": jsonStringSeq(evidence.diagnostics)
  }

proc statsJson(stats: BuildStats): JsonNode =
  var metrics = newJArray()
  for metric in stats.metrics:
    let avgUs =
      if metric.count > 0:
        metric.totalUs / float(metric.count)
      else:
        0.0
    metrics.add(%*{
      "name": metric.name,
      "count": metric.count,
      "avgUs": avgUs,
      "totalMs": metric.totalUs / 1000.0
    })
  %*{"metrics": metrics}

proc metricCount(stats: BuildStats; name: string): int =
  for metric in stats.metrics:
    if metric.name == name:
      return metric.count

proc metricTotalUs(stats: BuildStats; name: string): float =
  for metric in stats.metrics:
    if metric.name == name:
      return metric.totalUs

proc metricBucketUs(stats: BuildStats; names: openArray[string]): float =
  for name in names:
    result += stats.metricTotalUs(name)

proc benchmarkMetricsJson(stats: BuildStats): JsonNode =
  result = newJArray()
  for metric in stats.metrics:
    result.add(%*{
      "name": metric.name,
      "count": metric.count,
      "totalUs": metric.totalUs
    })

proc fileSizeOrZero(path: string): BiggestInt =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return 0
  getFileSize(extendedPath(path))

proc evidenceInputCount(evidence: PathSetEvidence): int =
  var seen: seq[string] = @[]
  for group in [evidence.declaredInputs, evidence.depfileInputs,
      evidence.monitorReads, evidence.monitorProbes]:
    for path in group:
      if path.len > 0 and seen.find(path) < 0:
        seen.add(path)
  seen.len

proc actionPresent(action: ActionResult): bool =
  action.id.len > 0 and action.status != asPending

proc actionResultJson(item: ActionResult): JsonNode =
  # Windows: include exitCode/stdout/stderr in the build report so failed
  # actions can be diagnosed without re-running them. Without this, the JSON
  # report only carries status/cacheDecision/etc. and failures look opaque.
  %*{
    "id": item.id,
    "status": $item.status,
    "exitCode": item.exitCode,
    "launched": item.launched,
    "wouldLaunch": item.wouldLaunch,
    "cacheDecision": $item.cacheDecision,
    "reason": item.reason,
    "dependencyPolicyKind": $item.dependencyPolicyKind,
    "runQuotaBackend": item.runQuotaBackend,
    "runQuotaSocket": item.runQuotaSocket,
    "leaseId": item.leaseId,
    "stdout": item.stdout,
    "stderr": item.stderr,
    "evidence": evidenceJson(item.evidence)
  }

proc targetResolutionJson(record: TargetResolutionRecord): JsonNode =
  ## Named-Targets M5 / Spec-Implementation M5: serialise one resolver
  ## outcome for the build report's ``targetResolution`` array. Mirrors
  ## the CLI text diagnostic taxonomy (``resolved`` / ``ambiguous`` /
  ## ``unknown``) so JSON consumers see the same shape as the stderr
  ## lines. The Spec-Implementation M5 registry split adds a
  ## ``targetKind`` field on ``trkResolved`` records carrying the
  ## row's origin marker per Build-Graph-Collections.md §"Persistence
  ## and the Target-Export Table" — one of ``"collection"``,
  ## ``"aggregate"``, ``"implicit"``, or ``"explicit"``.
  let kindText =
    case record.kind
    of trkResolved: "resolved"
    of trkAmbiguous: "ambiguous"
    of trkUnknown: "unknown"
  result = %*{
    "selector": record.selector,
    "kind": kindText
  }
  case record.kind
  of trkResolved:
    result["actionId"] = %record.actionId
    result["package"] = %record.owningPackage
    let targetKindText =
      case record.targetKind
      of tekImplicit: "implicit"
      of tekExplicit: "explicit"
      of tekAggregate: "aggregate"
      of tekCollection: "collection"
      of tekRunEdge: "run-edge"
    result["targetKind"] = %targetKindText
  of trkAmbiguous:
    result["candidates"] = jsonStringSeq(record.candidates)
  of trkUnknown:
    result["suggestions"] = jsonStringSeq(record.suggestions)

proc runQuotaReportJson*(bypassed: bool): JsonNode =
  ## RA-13: machine-readable resource-authority status for the run report.
  ## ``bypassed`` is true when this build launched at least one action with no
  ## RunQuota lease (explicit ``--runquota=off`` / ``REPROBUILD_NO_RUNQUOTA`` or
  ## the unreachable-daemon fallback). In that state ``authority`` is the
  ## engine's local pool gate only — host limits and cross-session fairness do
  ## NOT apply and concurrent cross-invocation runs cannot be made safe. When
  ## RunQuota gated every launch, ``bypassed`` is false and ``authority`` is
  ## "runquota". Shared by ``writeBuildReport`` and the RA-13 regression test so
  ## the asserted shape is the production shape.
  %*{
    "bypassed": bypassed,
    "authority":
      if bypassed: "local-engine-pool-gate-only" else: "runquota",
    "concurrentInvocationsSafe": not bypassed
  }

proc runQuotaAuthorityHeaderLine*(bypassed: bool): string =
  ## RA-13: the human build-header line stating the resource-authority status.
  ## On bypass it states plainly that limits are locally-enforced-only and that
  ## concurrent cross-invocation runs are NOT made safe. Shared by
  ## ``logRunQuotaAuthority`` and the RA-13 regression test.
  if bypassed:
    "runQuota: bypassed (no lease) — resource limits are " &
      "locally-enforced-only; concurrent cross-invocation runs are NOT " &
      "made safe"
  else:
    "runQuota: active (lease authority)"

proc environmentInheritanceHeaderLine*(
    census: EnvironmentInheritanceCensus): string =
  ## STAGE 2: the build-header line reporting how much of this graph runs
  ## on an environment Reprobuild neither declares nor records.
  ##
  ## Reprobuild passes `env` as an OVERLAY on the environment the build
  ## process inherited, so an action declaring nothing runs with the whole
  ## host environment. That is a real channel and it is currently silent.
  ## This states its size and changes nothing about it — closing the
  ## channel breaks edges, and the breakage should be a measured list
  ## rather than a surprise.
  ##
  ## It is a FACT line, not a warning: nothing here is wrong yet, and
  ## dressing a measurement up as a warning trains people to skip it.
  if census.totalActions == 0:
    return "env: no process actions in this graph"
  let percent = (census.undeclaredActions * 100) div census.totalActions
  "env: " & $census.declaringActions & "/" & $census.totalActions &
    " process actions declare a variable, " & $census.passthroughActions &
    " name a passthrough variable, " & $census.undeclaredActions &
    " (" & $percent & "%) declare nothing; all " & $census.totalActions &
    " also inherit the build environment (declared entries overlay it, " &
    "they do not replace it)"

proc writeBuildReport(path: string; provider: ProviderCompileArtifact;
                      refresh: ProviderRefreshReport;
                      providerInvocationCount: int;
                      cmakeRegenerationResult,
                      providerCompileResult,
                      buildResult: BuildRunResult;
                      workspaceVcs: openArray[
                          workspaceVcsEvidence.WorkspaceVcsEvidence] = [];
                      targetResolutions:
                          openArray[TargetResolutionRecord] = []) =
  ## M4: ``workspaceVcs`` carries the unified Workspace-VCS evidence
  ## seq accumulated by ``repro workspace status`` / ``repro check``
  ## while invoking the M2/M3 query actions. Callers pass an empty seq
  ## (the default) when no query observations occurred during the
  ## reported build. The JSON view embedded under the
  ## ``"workspaceVcs"`` key is derived from the same record the SSZ
  ## codec persists; see ``libs/repro_workspace_vcs/src/evidence.nim``.
  ##
  ## Named-Targets M5: ``targetResolutions`` carries one record per
  ## user-supplied selector classified by the M2 resolver. Empty when
  ## no positional was supplied (the legacy default-action path). The
  ## per-selector ``kind`` field mirrors the CLI text diagnostics
  ## (``resolved`` / ``ambiguous`` / ``unknown``).
  var cmakeRegenerationActions = newJArray()
  for item in cmakeRegenerationResult.results:
    cmakeRegenerationActions.add(actionResultJson(item))
  var providerCompileActions = newJArray()
  for item in providerCompileResult.results:
    providerCompileActions.add(actionResultJson(item))
  var actions = newJArray()
  for item in buildResult.results:
    actions.add(actionResultJson(item))
  var trace = newJArray()
  for event in buildResult.trace:
    trace.add(%*{
      "seq": event.seq,
      "actionId": event.actionId,
      "event": event.event,
      "detail": event.detail
    })
  var targetResolutionArr = newJArray()
  for record in targetResolutions:
    targetResolutionArr.add(targetResolutionJson(record))
  let root = %*{
    "providerBinary": provider.outputBinaryPath,
    "providerFingerprint": digestHex(provider.providerFingerprint),
    "providerCompileOutput": provider.executionResult.output,
    "cmakeRegenerationActions": cmakeRegenerationActions,
    "providerCompileActions": providerCompileActions,
    "providerSnapshot": refresh.persistedSnapshotPath,
    "providerInvocations": providerInvocationCount,
    "actions": actions,
    "trace": trace,
    "workspaceVcs": workspaceVcsEvidence.toJson(workspaceVcs),
    "targetResolution": targetResolutionArr,
    # RA-13: machine-readable resource-authority status (see
    # ``runQuotaReportJson``).
    "runQuota": runQuotaReportJson(buildResult.runQuotaBypassed),
    "stats": statsJson(buildResult.stats)
  }
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), $root)

const BuildFailureReportSchemaId* = "reprobuild.build.failure-report.v1"

proc writeBuildFailureReport*(path: string; buildResult: BuildRunResult;
                              actions: openArray[BuildAction];
                              target, projectRoot, outDir: string;
                              exitCode: int) =
  ## CLI/build.md §"The failure report". Shaped FOR the failure rather than
  ## the success document with a filter applied: only the failing actions,
  ## what they were, what they said, and the cache state that led the
  ## scheduler to run them, plus the ids that never ran because they were
  ## waiting behind a failure. Successful actions are deliberately NOT
  ## enumerated — a 4000-action build with one broken compile must produce a
  ## document a person can read top to bottom.
  var byId = initTable[string, int]()
  for i, action in actions:
    byId[action.id] = i
  var failed = newJArray()
  var blocked = newJArray()
  var counts = (total: 0, succeeded: 0, failed: 0, blocked: 0, cacheHit: 0)
  for item in buildResult.results:
    inc counts.total
    case item.status
    of asFailed:
      inc counts.failed
    of asBlocked:
      inc counts.blocked
    of asCacheHit, asUpToDate:
      inc counts.cacheHit
      inc counts.succeeded
    of asSucceeded:
      inc counts.succeeded
    else:
      discard
  for item in buildResult.results:
    if item.status == asBlocked:
      blocked.add(%*{
        "id": item.id,
        "blockedBy": item.blockedBy,
        "reason": item.reason
      })
      continue
    if item.status != asFailed:
      continue
    var node = %*{
      "id": item.id,
      "status": $item.status,
      "exitCode": item.exitCode,
      "reason": item.reason,
      "blockedBy": item.blockedBy,
      "cacheDecision": $item.cacheDecision,
      "dependencyPolicyKind": $item.dependencyPolicyKind,
      "runQuotaBackend": item.runQuotaBackend,
      "leaseId": item.leaseId,
      "stdout": item.stdout,
      "stderr": item.stderr
    }
    if byId.hasKey(item.id):
      let action = actions[byId[item.id]]
      node["argv"] = %action.argv
      node["cwd"] = %action.cwd
      node["inputs"] = %action.inputs
      node["outputs"] = %action.outputs
      node["cacheable"] = %action.cacheable
      node["weakFingerprint"] = %digestHex(action.weakFingerprint)
    failed.add(node)
  let root = %*{
    "schemaId": BuildFailureReportSchemaId,
    "target": target,
    "projectRoot": projectRoot,
    "outDir": outDir,
    "exitCode": exitCode,
    "counts": {
      "total": counts.total,
      "succeeded": counts.succeeded,
      "failed": counts.failed,
      "blocked": counts.blocked,
      "cacheHit": counts.cacheHit
    },
    "failedActions": failed,
    "blockedActions": blocked,
    "runQuota": runQuotaReportJson(buildResult.runQuotaBypassed)
  }
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), $root)

proc renderBuildTrace*(buildResult: BuildRunResult): string =
  ## ``--show=trace`` presenter for the scheduler trace.
  if buildResult.trace.len == 0:
    return "scheduler trace: (empty — nothing measured or nothing happened)\n"
  result = "scheduler trace:\n"
  for event in buildResult.trace:
    result.add("  " & $event.seq & " " & event.actionId & " " & event.event)
    if event.detail.len > 0:
      result.add(" " & event.detail)
    result.add('\n')

proc renderBuildCacheEvidence*(buildResult: BuildRunResult): string =
  ## ``--show=cache-evidence`` presenter for the per-action evidence counts.
  result = "cache evidence:\n"
  for item in buildResult.results:
    result.add("  " & item.id &
      " declaredInputs=" & $item.evidence.declaredInputs.len &
      " declaredOutputs=" & $item.evidence.declaredOutputs.len &
      " depfileInputs=" & $item.evidence.depfileInputs.len &
      " monitorReads=" & $item.evidence.monitorReads.len &
      " monitorWrites=" & $item.evidence.monitorWrites.len &
      " monitorProbes=" & $item.evidence.monitorProbes.len & '\n')

proc hasFailedActions(buildResult: BuildRunResult): bool =
  for item in buildResult.results:
    if item.status in {asFailed, asBlocked}:
      return true

proc providerCompileBuildAction(plan: ProviderCompilePlan;
                                modulePath, interfacePath, artifactPath,
                                helperCliPath, workDir: string;
                                scratchDir = ""): BuildAction =
  var inputs = plan.inputSources
  if not inputs.contains(interfacePath):
    inputs.add(interfacePath)
  var command = @[
    helperCliPath,
    "__repro-compile-provider",
    "--module", modulePath,
    "--out", plan.outputBinaryPath,
    "--artifact", artifactPath,
    "--interface", interfacePath,
    "--work-dir", workDir
  ]
  if scratchDir.len > 0:
    command.add("--scratch-dir")
    command.add(scratchDir)
  let compilerCwd =
    if scratchDir.len > 0:
      scratchDir
    else:
      parentDir(plan.outputBinaryPath)
  createDir(extendedPath(compilerCwd))
  # The provider-compile edge runs reprobuild's OWN ``nim c`` of the recipe's
  # provider binary (its inputs are reprobuild's pinned libs + the Nim stdlib,
  # NOT the package's source tree). It uses automatic monitoring like every
  # other opaque tool: automatic monitoring is the spec baseline for opaque
  # tools (Reprobuild-Development.milestones.org M17). An earlier macOS-only
  # ``dgNoRuntimeDependencies`` (declared-only) downgrade here was an
  # unapproved soundness hole and has been removed; monitored builds work on
  # arm64e after the io-mon fix.
  action("__repro_provider_compile", command,
    # Named-Lock-Files §7.2 — see `lockIdentityOutsideSolvedGraph`.
    governingLockIdentity = lockIdentityOutsideSolvedGraph(),
    cwd = compilerCwd,
    inputs = inputs,
    outputs = providerCompileOutputs(artifactPath, plan.outputBinaryPath),
    commandStatsId = "repro provider compile edge",
    cacheable = providerCompileCacheable(plan),
    weakFingerprint = plan.compileEdge.actionFingerprint,
    dependencyPolicy = automaticMonitorGatheringPolicy(
      providerCompileIgnoredInputPrefixes(scratchDir)))

proc invalidateStaleProviderCompileArtifact(plan: ProviderCompilePlan;
                                            artifactPath: string) =
  if artifactPath.len == 0 or not fileExists(extendedPath(artifactPath)):
    return
  if providerCompileArtifactFresh(artifactPath, plan.outputBinaryPath,
      plan.interfaceFingerprint, plan.providerFingerprint, plan.workDir):
    return
  removeFile(extendedPath(artifactPath))

const ProviderCompileActionId = "__repro_provider_compile"

var providerCompileConsultations: int
var providerCompileLaunchedInThisProcess: bool
  ## Per-PROCESS ledger of every engine consultation of the ONE
  ## ``__repro_provider_compile`` edge, and whether any of them actually
  ## launched a compile.
  ##
  ## Why this has to exist for the log line to mean anything: one
  ## ``repro build`` reaches the provider-compile edge up to three times —
  ## the daemon-spawn pool discovery (``getRecipeBuildPools`` →
  ## ``refreshRecipeProviderSnapshot``), the scoped-tool snapshot refresh,
  ## and the build itself — for the same reason ``extractInterfaceEdge``
  ## is reached several times (see ``interfaceEdgeSessionResults``). Only
  ## the LAST one is logged. The earlier passes are the ones that do the
  ## work, so the logged pass is a no-op WHENEVER a compile happened, and
  ## reads byte-identically to an invocation in which nothing happened at
  ## all. Measured pre-fix: a run that spent 63 s in a real ``nim c`` of
  ## the provider and a run that did nothing printed the same line.
  ##
  ## Scope, stated plainly: this counts consultations in THIS process. All
  ## the passes above run in one process (the CLI with ``--daemon=off``,
  ## the daemon session process otherwise), so the count is complete for
  ## the invocation it describes; it is not a claim about work some other
  ## process may have done.

proc noteProviderCompileConsultation(buildResult: BuildRunResult) =
  for item in buildResult.results:
    if item.id == ProviderCompileActionId:
      inc providerCompileConsultations
      if item.launched:
        providerCompileLaunchedInThisProcess = true

proc providerCompileInvocationSummary(): string =
  " consultations=" & $providerCompileConsultations &
    " compiled=" & $providerCompileLaunchedInThisProcess

proc providerCompileFailure(buildResult: BuildRunResult): string =
  for item in buildResult.results:
    if item.status in {asFailed, asBlocked}:
      var parts = @[item.id & " " & $item.status]
      if item.stderr.len > 0:
        parts.add(item.stderr)
      if item.stdout.len > 0:
        parts.add(item.stdout)
      return parts.join("\n")
  "provider compile failed"

proc readTextIfExists(path: string): string =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return ""
  readFile(extendedPath(path))

proc runLoggedCommand(argv: openArray[string]; cwd: string): int =
  let command = shellCommand(argv)
  let res = execCmdEx(command, workingDir = cwd)
  if res.output.len > 0:
    stdout.write(res.output)
    stdout.flushFile()
  res.exitCode

proc removeManifestEntries(path: string) =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return
  for rawLine in readFile(extendedPath(path)).splitLines():
    let filePath = rawLine.strip()
    if filePath.len > 0 and fileExists(extendedPath(filePath)):
      removeFile(extendedPath(filePath))

proc invalidateCmakeProviderDerivedState(meta: CmakeRegenerationMetadata) =
  if meta.providerRoot.len > 0:
    let pattern = meta.providerRoot / "worktrees" / "*" / "build" /
      "reprobuild" / "provider-graph" / "provider-fragments.rbsz"
    for fragment in walkFiles(extendedPath(pattern)):
      removeFile(extendedPath(fragment))
  for key, value in meta.values:
    if key == "clean_manifest" or key.startsWith("clean_manifest_"):
      removeManifestEntries(value)

proc runCmakeRegenerationHelper*(args: openArray[string]): int =
  var metadataFile = ""
  var depfilePath = ""
  var publicCliPath = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--metadata":
      if i + 1 >= args.len:
        raise newException(ValueError, "--metadata requires a value")
      metadataFile = args[i + 1]
      inc i, 2
    elif arg.startsWith("--metadata="):
      metadataFile = arg.split("=", maxsplit = 1)[1]
      inc i
    elif arg == "--depfile":
      if i + 1 >= args.len:
        raise newException(ValueError, "--depfile requires a value")
      depfilePath = args[i + 1]
      inc i, 2
    elif arg.startsWith("--depfile="):
      depfilePath = arg.split("=", maxsplit = 1)[1]
      inc i
    elif arg == "--public-cli":
      if i + 1 >= args.len:
        raise newException(ValueError, "--public-cli requires a value")
      publicCliPath = args[i + 1]
      inc i, 2
    elif arg.startsWith("--public-cli="):
      publicCliPath = arg.split("=", maxsplit = 1)[1]
      inc i
    else:
      raise newException(ValueError,
        "unsupported __repro-cmake-regenerate argument: " & arg)
  if metadataFile.len == 0:
    raise newException(ValueError, "--metadata is required")
  if depfilePath.len == 0:
    raise newException(ValueError, "--depfile is required")

  let values = readKeyValueMetadata(metadataFile)
  if values.len == 0:
    raise newException(IOError,
      "CMake regeneration metadata is missing: " & metadataFile)
  let sourceDir = values.metadataValue("source_dir")
  let binaryDir = values.metadataValue("binary_dir", parentDir(parentDir(
    parentDir(metadataFile))))
  if sourceDir.len == 0 or binaryDir.len == 0:
    raise newException(ValueError,
      "CMake regeneration metadata requires source_dir and binary_dir")
  var meta = CmakeRegenerationMetadata(
    enabled: true,
    suppressed: values.metadataFlag("cmake_regeneration_suppressed"),
    metadataFile: metadataFile,
    sourceDir: os.normalizedPath(sourceDir),
    binaryDir: os.normalizedPath(binaryDir),
    providerRoot: os.normalizedPath(values.metadataValue("provider_root",
      binaryDir / "CMakeFiles" / "reprobuild")),
    cmakeCommand: values.metadataValue("cmake_command", "cmake"),
    checkFile: values.metadataValue("cmake_regeneration_check_file",
      "CMakeFiles/Makefile.cmake"),
    globVerifyScript: values.metadataValue("cmake_regeneration_glob_verify",
      binaryDir / "CMakeFiles" / "VerifyGlobs.cmake"),
    providerFile: values.metadataValue("cmake_regeneration_provider_file",
      binaryDir / "reprobuild.nim"),
    providerStateFile: values.metadataValue(
      "cmake_regeneration_provider_state",
      values.metadataValue("provider_root", binaryDir / "CMakeFiles" /
        "reprobuild") / "provider.last"),
    values: values)

  if meta.suppressed:
    echo "cmakeRegeneration: suppressed"
    return 0

  let providerBefore = readTextIfExists(meta.providerStateFile)
  if meta.globVerifyScript.len > 0 and fileExists(extendedPath(meta.globVerifyScript)):
    let verifyRet = runLoggedCommand(@[
      meta.cmakeCommand, "-P", meta.globVerifyScript
    ], meta.binaryDir)
    if verifyRet != 0:
      return verifyRet

  let regenRet = runLoggedCommand(@[
    meta.cmakeCommand,
    "-S", meta.sourceDir,
    "-B", meta.binaryDir,
    "--check-build-system", meta.checkFile,
    "0"
  ], meta.binaryDir)
  if regenRet != 0:
    return regenRet

  let providerAfter = readTextIfExists(meta.providerFile)
  if providerAfter.len == 0:
    raise newException(IOError,
      "CMake regeneration did not produce provider file: " &
        meta.providerFile)
  if providerBefore.len > 0 and providerBefore != providerAfter:
    invalidateCmakeProviderDerivedState(meta)
  createDir(extendedPath(parentDir(meta.providerStateFile)))
  writeFile(extendedPath(meta.providerStateFile), providerAfter)
  writeMakeDepfile(depfilePath,
    cmakeRegenerationOutputs(meta),
    cmakeRegenerationInputs(meta, publicCliPath))
  echo "cmakeRegeneration: complete providerChanged=" &
    $(providerBefore.len > 0 and providerBefore != providerAfter)
  0

proc identityPaths(outDir: string; mode: ToolProvisioningMode):
    tuple[identityPath: string; inspectionPath: string] =
  case mode
  of tpmNix:
    (identityPath: outDir / "nix-tool-identities.rbtp",
      inspectionPath: outDir / "nix-tool-identities.inspect.json")
  of tpmTarball:
    (identityPath: outDir / "tarball-tool-identities.rbtp",
      inspectionPath: outDir / "tarball-tool-identities.inspect.json")
  of tpmScoop:
    (identityPath: outDir / "scoop-tool-identities.rbtp",
      inspectionPath: outDir / "scoop-tool-identities.inspect.json")
  of tpmFromSource:
    (identityPath: outDir / "from-source-tool-identities.rbtp",
      inspectionPath: outDir / "from-source-tool-identities.inspect.json")
  else:
    (identityPath: outDir / "path-only-tool-identities.rbtp",
      inspectionPath: outDir / "path-only-tool-identities.inspect.json")

proc modeName(mode: ToolProvisioningMode): string =
  case mode
  of tpmPathOnly: "path"
  of tpmNix: "nix"
  of tpmTarball: "tarball"
  of tpmScoop: "scoop"
  of tpmFromSource: "from-source"
  else: "unspecified"

proc addCacheField(payload: var string; value: string) =
  payload.add($value.len)
  payload.add(":")
  payload.add(value)
  payload.add("\n")

proc toolIdentityCacheKey(artifact: ProjectInterfaceArtifact;
                          mode: ToolProvisioningMode): string =
  var payload = ""
  payload.addCacheField("reprobuild.toolIdentityCache.v3")
  payload.addCacheField(mode.modeName)
  payload.addCacheField(artifact.projectInterface.projectName)
  payload.addCacheField(artifact.projectInterface.packageName)
  payload.addCacheField(digestHex(artifact.interfaceFingerprint))
  if mode == tpmPathOnly:
    payload.addCacheField(getEnv("PATH"))
  # Cross-Repo-Source-Consumption SC-6 (§5.2 "a changed pin invalidates the
  # consumer") — fold each materialized cross-repo LIBRARY producer's realized
  # producer directories into the tool-identity cache key. Both channels are
  # passed explicitly to identity construction, so a changed producer
  # realized dir (a refreshed lock pin fetches into a NEW revision-keyed dir,
  # ``<ws>/.repro/cross-repo-producers/<name>/<rev>/build``) would
  # otherwise reuse the stale on-disk tool identity from the previous pin and
  # execute/link/load the old product. Folding the realized dirs here re-resolves
  # the identity when the pin changes; an unchanged pin (same dirs) keeps the
  # key stable.
  for selector in toSeq(producerMaterializedBinDirs.keys).sorted:
    payload.addCacheField("producer-bin")
    payload.addCacheField(selector)
    payload.addCacheField(producerMaterializedBinDirs[selector].join("\n"))
  for selector in toSeq(producerMaterializedAuxPaths.keys).sorted:
    let aux = producerMaterializedAuxPaths[selector]
    payload.addCacheField("producer-aux")
    payload.addCacheField(selector)
    payload.addCacheField(aux.includeDirs.join("\n"))
    payload.addCacheField(aux.libDirs.join("\n"))
    payload.addCacheField(aux.pkgConfigDirs.join("\n"))
    payload.addCacheField(aux.cmakePrefixDirs.join("\n"))
    # SC-11: fold the Nim library source roots so a refreshed pin / changed
    # sibling src root re-resolves the tool identity (same rationale as the
    # C/C++ aux dirs above — the Nim channel is threaded through the resolver
    # aux paths, not PATH).
    payload.addCacheField(aux.nimPathDirs.join("\n"))
  for useDef in artifact.projectInterface.toolUses:
    payload.addCacheField(useDef.rawConstraint)
    payload.addCacheField(useDef.packageSelector)
    payload.addCacheField(useDef.executableName)
    payload.addCacheField(useDef.policyPath.join("/"))
    for nix in useDef.nixProvisioning:
      payload.addCacheField(nix.contributor)
      payload.addCacheField(nix.selector)
      payload.addCacheField(nix.executablePath)
      payload.addCacheField(nix.expressionFile)
      payload.addCacheField(nix.packageId)
      payload.addCacheField(nix.lockIdentity)
    for tarball in useDef.tarballProvisioning:
      payload.addCacheField(tarball.contributor)
      payload.addCacheField(tarball.url)
      payload.addCacheField(tarball.mirrors.join("\n"))
      payload.addCacheField(tarball.sha256)
      payload.addCacheField(tarball.archiveType)
      payload.addCacheField($tarball.stripComponents)
      payload.addCacheField(tarball.executablePath)
      payload.addCacheField(tarball.packageId)
      payload.addCacheField(tarball.lockIdentity)
    for scoop in useDef.scoopProvisioning:
      payload.addCacheField(scoop.contributor)
      payload.addCacheField(scoop.bucket)
      payload.addCacheField(scoop.app)
      payload.addCacheField(scoop.version)
      payload.addCacheField(scoop.preferredVersion)
      payload.addCacheField(scoop.manifestChecksum)
      payload.addCacheField(scoop.manifestUrl)
      payload.addCacheField(scoop.executablePath)
      payload.addCacheField($scoop.requiresExecutionProfileChecksum)
      payload.addCacheField(scoop.packageId)
      payload.addCacheField(scoop.lockIdentity)
  digestHex(blake3DomainDigest(payload.bytesOf(), hdMetadataEnvelope))

proc toolIdentityRealizationsUsable(identity: PathOnlyBuildIdentity): bool =
  # The cache is usable when the artifacts the identity points at are
  # still on disk: realized store paths (for nix/tarball/scoop) and the
  # resolved executable itself. The ``pathSearchList`` is the snapshot of
  # ``$PATH`` at resolution time and is fingerprinted into the cache key
  # via ``toolIdentityCacheKey`` — PATH commonly carries entries for
  # directories that don't exist on the current host (e.g. Linux-style
  # ``~/.pixi/bin`` entries persisted in a shell rc and inherited on
  # macOS). Requiring every PATH entry to exist would invalidate the
  # cache on every build and force a fresh probe each time. Cache
  # invalidation when PATH itself changes is already handled by the
  # cache-key check.
  for profile in identity.profiles:
    for storePath in profile.realizedStorePaths:
      if storePath.len > 0 and not dirExists(extendedPath(storePath)):
        return false
    if profile.resolvedExecutablePath.len > 0 and
        not fileExists(extendedPath(profile.resolvedExecutablePath)):
      return false
    if not profile.fromSourceSearchPathsCurrent():
      return false
  true

proc cachedToolIdentity(outDir: string; mode: ToolProvisioningMode;
                        artifact: ProjectInterfaceArtifact;
                        stableIdentityPath,
                        stableInspectionPath: string):
    tuple[hit: bool; identity: PathOnlyBuildIdentity] =
  let key = toolIdentityCacheKey(artifact, mode)
  let cacheDir = outDir / "tool-identity-cache"
  let cacheIdentityPath = cacheDir / (key & ".rbtp")
  let cacheInspectionPath = cacheDir / (key & ".inspect.json")
  let stableKeyPath = cacheDir / (mode.modeName & ".current-key")
  if fileExists(extendedPath(stableIdentityPath)) and fileExists(extendedPath(stableKeyPath)) and
      readFile(extendedPath(stableKeyPath)).strip() == key:
    try:
      let identity = readPathOnlyBuildIdentity(stableIdentityPath)
      if identity.interfaceFingerprint != artifact.interfaceFingerprint:
        return
      if not identity.toolIdentityRealizationsUsable():
        return
      if not fileExists(extendedPath(stableInspectionPath)):
        if fileExists(extendedPath(cacheInspectionPath)):
          createDir(extendedPath(parentDir(stableInspectionPath)))
          copyFile(extendedPath(cacheInspectionPath), extendedPath(stableInspectionPath))
        else:
          writeInspectionJson(stableInspectionPath, identity)
      return (hit: true, identity: identity)
    except CatchableError:
      discard
  if not fileExists(extendedPath(cacheIdentityPath)):
    return
  try:
    let identity = readPathOnlyBuildIdentity(cacheIdentityPath)
    if identity.interfaceFingerprint != artifact.interfaceFingerprint:
      return
    if not identity.toolIdentityRealizationsUsable():
      return
    writePathOnlyBuildIdentity(stableIdentityPath, identity)
    if fileExists(extendedPath(cacheInspectionPath)):
      createDir(extendedPath(parentDir(stableInspectionPath)))
      copyFile(extendedPath(cacheInspectionPath), extendedPath(stableInspectionPath))
    else:
      writeInspectionJson(stableInspectionPath, identity)
    createDir(extendedPath(cacheDir))
    writeFile(extendedPath(stableKeyPath), key & "\n")
    return (hit: true, identity: identity)
  except CatchableError:
    return (hit: false, identity: PathOnlyBuildIdentity())

proc writeToolIdentityCache(outDir: string; mode: ToolProvisioningMode;
                            artifact: ProjectInterfaceArtifact;
                            identity: PathOnlyBuildIdentity) =
  let key = toolIdentityCacheKey(artifact, mode)
  let cacheDir = outDir / "tool-identity-cache"
  writePathOnlyBuildIdentity(cacheDir / (key & ".rbtp"), identity)
  writeInspectionJson(cacheDir / (key & ".inspect.json"), identity)

proc providerSnapshotInputsFresh(snapshot: ProviderGraphSnapshot): bool =
  if snapshot.fragments.len == 0:
    return false
  for fragment in snapshot.fragments:
    for input in fragment.evaluationInputs:
      case input.kind
      of gevFileRead:
        if fileContentDigest(input.identity) != input.digest:
          return false
      of gevDirectoryEnumeration:
        if directoryMemberNames(input.identity) != input.directoryMembers:
          return false
      else:
        return false
  true

proc readFreshProviderGraphSnapshot(storeRoot, providerArtifactId: string):
    Option[ProviderGraphSnapshot] =
  if not fileExists(extendedPath(providerSnapshotPath(storeRoot))):
    return none(ProviderGraphSnapshot)
  try:
    let snapshot = loadProviderGraphSnapshot(storeRoot)
    if snapshot.providerArtifactId != providerArtifactId:
      return none(ProviderGraphSnapshot)
    if not providerSnapshotInputsFresh(snapshot):
      return none(ProviderGraphSnapshot)
    return some(snapshot)
  except CatchableError:
    return none(ProviderGraphSnapshot)

proc warmReadFreshProviderGraphSnapshot(storeRoot, providerArtifactId: string):
    Option[ProviderGraphSnapshot] =
  let path = providerSnapshotPath(storeRoot)
  let key = storeRoot & "\0" & providerArtifactId
  if warmProviderSnapshots.hasKey(key):
    let warm = warmProviderSnapshots[key]
    if warm.providerArtifactId == providerArtifactId and
        evidenceFresh(path, warm.snapshotEvidence) and
        warm.snapshot.providerArtifactId == providerArtifactId and
        providerSnapshotInputsFresh(warm.snapshot):
      return some(warm.snapshot)
  result = readFreshProviderGraphSnapshot(storeRoot, providerArtifactId)
  if result.isSome:
    warmProviderSnapshots[key] = WarmProviderSnapshot(
      providerArtifactId: providerArtifactId,
      snapshotPath: path,
      snapshotEvidence: durableFileEvidence(path),
      snapshot: result.get())

proc canonicalVariantAssignments(): string =
  ## Canonical (sorted, de-duplicated) form of the active variant
  ## assignments from ``REPRO_VARIANTS`` (the env var ``--variant`` /
  ## ``--release`` write). The lowered-graph cache key MUST include this:
  ## solver-participating variants are resolved at provider-run time, not
  ## baked into the compiled provider artifact, so two builds that differ
  ## only in their variant values (e.g. ``buildType=debug`` vs
  ## ``buildType=release``) otherwise share an identical
  ## ``providerArtifactId`` and the engine reuses the stale lowered graph
  ## (``providerInvocations: 0``). Folding the assignments in forces a
  ## re-lowering when a variant changes. Sorted so assignment order does
  ## not perturb the key.
  let raw = getEnv("REPRO_VARIANTS")
  if raw.len == 0:
    return ""
  var parts: seq[string] = @[]
  for item in raw.split(','):
    let s = item.strip()
    if s.len > 0:
      parts.add(s)
  parts.sort()
  parts.join(",")

proc providerGraphStoreRoot(base: string): string =
  ## Provider-graph snapshot store root, isolated per active variant set.
  ##
  ## The provider-graph snapshot (``provider-fragments.rbsz``) caches the
  ## fragments a provider emitted. ``refreshProviderGraph`` reuses a stored
  ## snapshot whenever the ``providerArtifactId`` matches and nothing it tracks
  ## (file mtimes, body hashes, directory membership) changed — but it does
  ## NOT track solver-participating variant values, which are resolved at
  ## provider-run time and change the emitted graph (e.g. ``buildType=release``
  ## moves every output to ``build-release-repro/``). Two builds differing only
  ## in their variants therefore share one snapshot and the second reuses the
  ## first's graph without re-invoking the provider (``providerInvocations:
  ## 0``). Giving each variant set its own snapshot subdirectory forces a cold
  ## start (and a fresh provider invocation) when the variants change, and lets
  ## the two configurations' snapshots coexist and cache independently — the
  ## same way cargo keeps ``target/debug`` and ``target/release`` separate.
  let sig = canonicalVariantAssignments()
  if sig.len == 0:
    return base
  var slug = ""
  for ch in sig:
    if ch.isAlphaNumeric() or ch == '=' or ch == '-' or ch == '_' or ch == '.':
      slug.add(ch)
    else:
      slug.add('_')
  base / ("variants-" & slug)

proc loweredGraphCacheKey(artifact: ProjectInterfaceArtifact;
                          mode: ToolProvisioningMode;
                          providerArtifactId, providerSnapshotPath,
                          pathEnv: string;
                          extensionSignature = ""): string =
  ## ``extensionSignature`` (Workspace-Manifest-Optional MO-13, correcting
  ## MO-6) folds the ACTIVE ``projectExtension`` set into the key. The disk
  ## cache is otherwise keyed on the BASE snapshot's content digest, so an
  ## extension toggled between two builds — whose fragments are merged into
  ## ``refresh.snapshot`` in-memory AFTER the persisted snapshot is read —
  ## would have left the key unchanged and forced a ``--force-rebuild`` to
  ## re-lower. Including the signature makes toggling an extension on/off
  ## invalidate the cache without ``--force-rebuild`` (and toggling back is a
  ## cache hit, since the signature is deterministic for a given extension set).
  ## Empty when no extension is active, so the legacy single-project key is
  ## byte-identical.
  var payload = ""
  payload.addCacheField(LoweredGraphAlgorithmVersion)
  payload.addCacheField(mode.modeName)
  payload.addCacheField(artifact.projectInterface.projectName)
  payload.addCacheField(artifact.projectInterface.packageName)
  payload.addCacheField(digestHex(artifact.interfaceFingerprint))
  payload.addCacheField(toolIdentityCacheKey(artifact, mode))
  payload.addCacheField(providerArtifactId)
  payload.addCacheField(canonicalVariantAssignments())
  if fileExists(extendedPath(providerSnapshotPath)):
    payload.addCacheField(fileContentDigest(providerSnapshotPath))
  else:
    payload.addCacheField("")
  payload.addCacheField(extensionSignature)
  if mode == tpmPathOnly:
    payload.addCacheField(pathEnv)
  digestHex(blake3DomainDigest(payload.bytesOf(), hdMetadataEnvelope))

proc resolveAndWriteIdentity(artifact: ProjectInterfaceArtifact;
                             outDir: string;
                             mode: ToolProvisioningMode):
    tuple[identity: PathOnlyBuildIdentity; identityPath: string;
      inspectionPath: string] =
  let paths = identityPaths(outDir, mode)
  let cached = cachedToolIdentity(outDir, mode, artifact,
    paths.identityPath, paths.inspectionPath)
  if cached.hit:
    return (identity: cached.identity, identityPath: paths.identityPath,
      inspectionPath: paths.inspectionPath)
  # Cross-Repo-Source-Consumption SC-3: selectors the producer pre-pass
  # materialized as LIBRARY-channel producers are consumed through the aux
  # channels, not PATH; pass them so ``toolBuildIdentity`` skips the path-mode
  # executable lookup (which would otherwise raise "not found in PATH" for a
  # pure-library producer). Empty when nothing was materialized → byte-identical
  # to pre-SC-3.
  var producerAuxSelectors = initTable[string, ProducerAuxDirs]()
  for selector, aux in producerMaterializedAuxPaths.pairs:
    producerAuxSelectors[selector] = ProducerAuxDirs(
      includeDirs: aux.includeDirs,
      libDirs: aux.libDirs,
      pkgConfigDirs: aux.pkgConfigDirs,
      cmakePrefixDirs: aux.cmakePrefixDirs)
  var producerExecutableSelectors =
    initTable[string, ProducerExecutableDirs]()
  for selector, binDirs in producerMaterializedBinDirs.pairs:
    producerExecutableSelectors[selector] = ProducerExecutableDirs(
      binDirs: binDirs)
  let identity = toolBuildIdentity(artifact, mode,
    storeRoot = outDir / "tool-store",
    producerExecutableSelectors = producerExecutableSelectors,
    producerAuxSelectors = producerAuxSelectors)
  writePathOnlyBuildIdentity(paths.identityPath, identity)
  writeInspectionJson(paths.inspectionPath, identity)
  writeToolIdentityCache(outDir, mode, artifact, identity)
  createDir(extendedPath(outDir / "tool-identity-cache"))
  writeFile(extendedPath(outDir / "tool-identity-cache" / (mode.modeName & ".current-key")),
    toolIdentityCacheKey(artifact, mode) & "\n")
  (identity: identity, identityPath: paths.identityPath,
    inspectionPath: paths.inspectionPath)

proc warmResolveAndWriteIdentity(artifact: ProjectInterfaceArtifact;
                                 outDir: string;
                                 mode: ToolProvisioningMode):
    tuple[identity: PathOnlyBuildIdentity; identityPath: string;
      inspectionPath: string] =
  let key = toolIdentityCacheKey(artifact, mode)
  let paths = identityPaths(outDir, mode)
  let tableKey = outDir & "\0" & mode.modeName & "\0" & key
  let stableKeyPath = outDir / "tool-identity-cache" /
    (mode.modeName & ".current-key")
  if warmToolIdentities.hasKey(tableKey):
    let warm = warmToolIdentities[tableKey]
    if warm.key == key and warm.identity.interfaceFingerprint ==
        artifact.interfaceFingerprint and
        evidenceFresh(warm.identityPath, warm.identityEvidence) and
        evidenceFresh(stableKeyPath, warm.keyEvidence) and
        warm.identity.toolIdentityRealizationsUsable():
      return (identity: warm.identity, identityPath: warm.identityPath,
        inspectionPath: warm.inspectionPath)
  result = resolveAndWriteIdentity(artifact, outDir, mode)
  warmToolIdentities[tableKey] = WarmToolIdentity(key: key,
    identityPath: result.identityPath, inspectionPath: result.inspectionPath,
    identityEvidence: durableFileEvidence(result.identityPath),
    keyEvidence: durableFileEvidence(stableKeyPath), identity: result.identity)

proc shouldEnterBuildPipeline*(mode: ToolProvisioningMode): bool =
  ## M9.R.8 Part 1 — extracted predicate for the build-pipeline dispatch
  ## gate (formerly an inline ``in {tpmPathOnly, tpmNix, tpmTarball,
  ## tpmScoop}`` literal at three sites in this module). Centralising the
  ## set membership here:
  ##
  ##   * makes the dispatcher gate testable in isolation
  ##     (``t_m9r8_dispatcher_gate.nim``);
  ##   * keeps the three call sites in sync when a new
  ##     ``ToolProvisioningMode`` is added (previously the new mode had
  ##     to remember to update three places — the M9.Q ``tpmFromSource``
  ##     mode missed all three, which is the gap M9.R.8 closes).
  ##
  ## ``tpmFromSource`` is included here so a build invoked with
  ## ``--tool-provisioning=from-source`` enters the same provider-
  ## compile / lowered-graph / engine-run pipeline as the four
  ## pre-existing modes. ``resolveFromSourceTool`` is the downstream
  ## resolver (already wired through ``toolProfileFor``) and the M9.R.7
  ## ``mkToolIdentityResolver`` returns the from-source artefact's
  ## ``parentDir`` in ``binDirs`` so action argv resolves correctly.
  ##
  ## ``tpmUnspecified`` deliberately stays out — the caller resolves
  ## it via ``parseToolProvisioning`` / env var / project default
  ## before reaching this predicate.
  mode in {tpmPathOnly, tpmNix, tpmTarball, tpmScoop, tpmFromSource}

# Cross-Repo-Source-Consumption SC-1 — forward declarations for the
# "resolve package binding" hook + its observability sink, so the
# ``mkToolIdentityResolver`` closure below can route a cross-repo producer ref
# through it. The bodies live next to the committed-lock helpers (where
# ``LockedDep`` / ``parseLockedDependencies`` are in scope).
type
  ProducerBindingKind* = enum
    pbkNotProducer
    pbkDevelopOverride
    pbkLockPinned
    pbkOnDiskSibling
      ## Plain ON-DISK workspace sibling with NEITHER a develop-override entry
      ## NOR a committed ``LockedDep``. The checkout is discoverable one level
      ## up (``../<selector>/repro.nim``), which is useful for compile-time
      ## typed-contract discovery, but it is NOT by itself a declared build
      ## graph producer edge. Build-time materialization/splicing is allowed
      ## only for explicit develop overrides or lock pins; otherwise a consumer
      ## that requires the producer edge must fail instead of silently building
      ## an undeclared sibling.

  ProducerBinding* = object
    selector*: string
    case kind*: ProducerBindingKind
    of pbkNotProducer:
      discard
    of pbkDevelopOverride:
      localPathAbsolute*: string
      contentIdentity*: string
      overrideBinding*: ResolvedPackageBinding
    of pbkLockPinned:
      lockedDep*: LockedDep
    of pbkOnDiskSibling:
      siblingProjectFile*: string
        ## The resolved ``../<selector>/repro.nim`` (or ``reprobuild.nim``);
        ## its ``parentDir`` is the producer source root.

proc resolveProducerBinding*(selector: string;
                             workspaceRoot: string): ProducerBinding

var lastResolvedProducerBinding*: ProducerBinding =
  ProducerBinding(selector: "", kind: pbkNotProducer)
  ## SC-1 observability sink. The ``mkToolIdentityResolver`` closure records
  ## the most-recent cross-repo producer decision here so tests (and, later,
  ## ``repro why``) can observe that a ref was routed through the SC-1 seam
  ## rather than the host-binary branch. SC-2 replaces the closure's
  ## ``return none`` with the spliced producer bin dir; SC-1 records the
  ## decision without yet materializing it.

proc declaresProducerEdge*(binding: ProducerBinding): bool =
  ## True iff ``binding`` represents an explicit build graph producer edge.
  ## A plain on-disk sibling can provide compile-time schema discovery, but it
  ## must not be built/spliced/folded unless the consumer declared the edge via
  ## a develop override or a committed lock pin.
  binding.kind in {pbkDevelopOverride, pbkLockPinned}

proc mkToolIdentityResolver*(identity: PathOnlyBuildIdentity;
                             workspaceRoot = ""):
    ToolIdentityResolver =
  ## M9.N Batch B: project a ``PathOnlyBuildIdentity`` into the engine-
  ## side ``ToolIdentityResolver`` closure shape. The CLI calls this
  ## once at build start and hands the result to
  ## ``BuildEngineConfig.toolIdentityResolver``. The engine then walks
  ## each action's ``toolIdentityRefs`` through the closure at fork
  ## time and prepends the resolved bin dirs to PATH.
  ##
  ## Cross-Repo-Source-Consumption SC-1 (§4.1): ``workspaceRoot`` is the
  ## consumer project root (where ``repro.lock`` +
  ## ``.repro/develop-overrides.toml`` live). When non-empty, a ref that
  ## does NOT match any host / nix / tarball / scoop / corpus-recipe action
  ## identity is routed through the ADDITIVE cross-repo producer branch
  ## (``resolveProducerBinding``) before the closure returns ``none``. That
  ## branch fires ONLY for a ref naming a producer resolved via the develop-
  ## override map or a committed ``LockedDep``; every existing ref keeps its
  ## branch byte-for-byte (the empty-``workspaceRoot`` default preserves the
  ## pre-SC-1 behavior exactly for callers/tests that don't opt in).
  ##
  ## Matching: the ref name (e.g. ``"meson"``) is matched against
  ## ``ToolActionIdentity.executableName`` AND
  ## ``ToolActionIdentity.packageSelector`` (the package selector
  ## carries the bare package name when no version constraint is
  ## pinned; once a constraint is added it includes the operator + ver
  ## suffix which we strip via a prefix-with-space-or-comparator probe).
  ## Empty refs and unmatched refs return ``none`` — the engine then
  ## leaves PATH alone for that ref.
  ##
  ## Bin-dir derivation: prefers the parent directory of
  ## ``resolvedExecutablePath`` (so the catalog's chosen binary is
  ## leftmost in PATH); falls back to the entries of
  ## ``pathSearchList`` (each a ``<storePath>/bin`` for nix/tarball/
  ## scoop adapters) when ``resolvedExecutablePath`` is empty. Both
  ## fields can legitimately be empty when the catalog couldn't
  ## resolve the tool (e.g. path-only mode without the tool
  ## installed) — the closure then returns ``none`` so PATH is
  ## untouched and the action's bare-name argv falls through to the
  ## host's existing PATH.
  let snapshot = identity
  let producerWorkspaceRoot = workspaceRoot
  result = proc(name: string; kind: DepKind): Option[ResolvedToolIdentity]
      {.gcsafe, closure.} =
    if name.len == 0:
      return none(ResolvedToolIdentity)
    # DSL-port M9.R.7. Pick the materialization-cache namespace tag
    # based on the dep kind. The path-only build identity is BUILD-
    # platform-only (the catalog resolves against the host's
    # installed binaries), so for now the resolver hands back the
    # same ``binDirs`` regardless of kind — but it STAMPS the tag
    # field with the platform that would be consulted under a
    # cross-build so ``repro why`` and tests can see the routing
    # decision. The native-build case (``cachePlatformTagFor`` ==
    # ``"native"``) is byte-identical to pre-M9.R.7.
    let cacheTag = cachePlatformTagFor(kind, nil)
    var matched = false
    var mergedBinDirs: seq[string] = @[]
    var mergedExecutablePath = ""
    var mergedPkgConfigDirs: seq[string] = @[]
    var mergedCmakePrefixDirs: seq[string] = @[]
    var mergedIncludeDirs: seq[string] = @[]
    var mergedLibDirs: seq[string] = @[]
    for actionIdy in snapshot.actionIdentities:
      let matchByName = actionIdy.executableName == name
      let bareSelector = block:
        # Strip a trailing constraint like ``" >=3.20"`` so a recipe
        # whose ``uses: cmake >=3.20`` constraint pins a version still
        # matches ``toolIdentityRefs = @["cmake"]``.
        var pkgSel = actionIdy.packageSelector
        for i, ch in pkgSel:
          if ch == ' ' or ch == '>' or ch == '<' or ch == '=' or
              ch == '~' or ch == '^':
            pkgSel = pkgSel[0 ..< i]
            break
        pkgSel
      let matchBySelector = bareSelector == name
      if not (matchByName or matchBySelector):
        continue
      matched = true
      if actionIdy.resolvedExecutablePath.len > 0:
        if mergedExecutablePath.len == 0:
          mergedExecutablePath = actionIdy.resolvedExecutablePath
        let parent = parentDir(actionIdy.resolvedExecutablePath)
        if parent.len > 0 and parent notin mergedBinDirs:
          mergedBinDirs.add(parent)
      for searchDir in actionIdy.pathSearchList:
        if searchDir.len > 0 and searchDir notin mergedBinDirs:
          mergedBinDirs.add(searchDir)
      for path in actionIdy.pkgConfigSearchList:
        if path.len > 0 and path notin mergedPkgConfigDirs:
          mergedPkgConfigDirs.add(path)
      for path in actionIdy.cmakePrefixList:
        if path.len > 0 and path notin mergedCmakePrefixDirs:
          mergedCmakePrefixDirs.add(path)
        let prefixBin = path / "bin"
        if dirExists(extendedPath(prefixBin)) and prefixBin notin mergedBinDirs:
          mergedBinDirs.add(prefixBin)
      for path in actionIdy.cpathList:
        if path.len > 0 and path notin mergedIncludeDirs:
          mergedIncludeDirs.add(path)
      for path in actionIdy.libraryPathList:
        if path.len > 0 and path notin mergedLibDirs:
          mergedLibDirs.add(path)
    if matched:
      var nimPathDirs: seq[string] = @[]
      {.cast(gcsafe).}:
        if producerMaterializedAuxPaths.hasKey(name):
          nimPathDirs = producerMaterializedAuxPaths[name].nimPathDirs
      let hasAuxLists = mergedPkgConfigDirs.len + mergedCmakePrefixDirs.len +
        mergedIncludeDirs.len + mergedLibDirs.len > 0
      if mergedBinDirs.len == 0 and not hasAuxLists and nimPathDirs.len == 0:
        return none(ResolvedToolIdentity)
      return some(ResolvedToolIdentity(
        binDirs: mergedBinDirs,
        resolvedExecutablePath: mergedExecutablePath,
        pkgConfigDirs: mergedPkgConfigDirs,
        cmakePrefixDirs: mergedCmakePrefixDirs,
        includeDirs: mergedIncludeDirs,
        libDirs: mergedLibDirs,
        nimPathDirs: nimPathDirs,
        cachePlatformTag: cacheTag))
    # Cross-Repo-Source-Consumption SC-1 (§4.1) — ADDITIVE cross-repo
    # producer branch. A ref that matched NO host / nix / tarball / scoop /
    # corpus-recipe action identity above is a candidate cross-repo producer.
    # Route it through the SC-1 "resolve package binding" hook: the develop-
    # override map first, then the committed ``LockedDep``. This fires ONLY
    # when a consumer workspace root was supplied AND the selector actually
    # resolves as a producer — otherwise the closure falls through to the
    # SAME ``return none`` as before, so every non-producer ref is
    # byte-identical to the pre-SC-1 resolver.
    #
    # SC-1 was the RESOLUTION seam only: it recorded the producer decision in
    # the observability sink so the seam was genuinely exercised (not test-
    # only, the never-called ``resolvePackageWithOverrides`` gap). SC-2 turns
    # that decision into a materialized bin dir on ``PATH`` (executable
    # channel): the ``buildAndSpliceProducers`` pre-pass (run inside
    # ``executeBuildTarget`` before this closure fires) has already loaded the
    # producer's ``repro.nim``, built its declared ``executable`` edge from
    # source, and recorded the output ``bin`` dir in
    # ``producerMaterializedBinDirs``. The closure returns it here so the
    # engine prepends it to the consuming action's ``PATH``
    # (``repro_build_engine.nim:1975-2010``). SC-3 will add the library
    # aux-channel projection alongside this on the same producer branch.
    if producerWorkspaceRoot.len > 0:
      # ``resolveProducerBinding`` reads the committed ``repro.lock`` +
      # ``.repro/develop-overrides.toml`` (file I/O); the observability sink
      # and the splice sink are module-level ``var``s holding GC'd strings.
      # The CLI build path is single-threaded at this seam (the resolver runs
      # on the fork-scheduling thread), so both are safe. Wrap in
      # ``cast(gcsafe)`` to match the established pattern in this module (see
      # the git_actions / repro_local_store gcsafe I/O sites).
      {.cast(gcsafe).}:
        let producer = resolveProducerBinding(name, producerWorkspaceRoot)
        if producer.declaresProducerEdge:
          lastResolvedProducerBinding = producer
          # SC-2/SC-3 splice: the pre-pass has built this producer's declared
          # edge(s) and recorded the executable channel (``build/bin`` dir on
          # ``producerMaterializedBinDirs``) and/or the library channel (the
          # realized library aux-channel dirs on ``producerMaterializedAuxPaths``).
          # Project WHATEVER channel(s) the pre-pass materialized into one
          # ``ResolvedToolIdentity`` here: ``binDirs`` → PATH (executable), and
          # ``includeDirs``/``libDirs``/``pkgConfigDirs``/``cmakePrefixDirs`` →
          # the aux env channels (library). A producer that materialized neither
          # (nothing on disk for this ref) still falls through to ``none``.
          var binDirs: seq[string] = @[]
          if producerMaterializedBinDirs.hasKey(name):
            binDirs = producerMaterializedBinDirs[name]
          var aux = ProducerAuxPaths()
          if producerMaterializedAuxPaths.hasKey(name):
            aux = producerMaterializedAuxPaths[name]
          let haveLib = aux.includeDirs.len > 0 or aux.libDirs.len > 0 or
            aux.pkgConfigDirs.len > 0 or aux.cmakePrefixDirs.len > 0 or
            aux.nimPathDirs.len > 0
          if binDirs.len > 0 or haveLib:
            # ``resolvedExecutablePath`` is the catalog's tool-of-record
            # path for the ref (``repro_build_engine.nim:629-633``); it must
            # be an EXECUTABLE, not a bin DIRECTORY. Bind it to the produced
            # binary named after the selector when it materialized under a
            # spliced bin dir; leave it empty otherwise (the PATH-splice
            # channel reads only ``binDirs``, so an empty tool-of-record path
            # is harmless — a pure-library producer has no executable of
            # record and the aux channels carry the library).
            var toolOfRecord = ""
            for binDir in binDirs:
              let candidate = binDir / addFileExt(name, ExeExt)
              if fileExists(extendedPath(candidate)):
                toolOfRecord = candidate
                break
            return some(ResolvedToolIdentity(
              binDirs: binDirs,
              resolvedExecutablePath: toolOfRecord,
              includeDirs: aux.includeDirs,
              libDirs: aux.libDirs,
              pkgConfigDirs: aux.pkgConfigDirs,
              cmakePrefixDirs: aux.cmakePrefixDirs,
              nimPathDirs: aux.nimPathDirs,
              cachePlatformTag: cacheTag))
    none(ResolvedToolIdentity)

proc runQuotaSocketDiagnostic(): string =
  let socket = getEnv("RUNQUOTA_SOCKET", "")
  if socket.len > 0:
    socket
  else:
    "default"

proc buildMaxParallelism(): uint32 =
  let configured = getEnv("REPROBUILD_MAX_PARALLELISM", "")
  if configured.len == 0:
    return 8'u32
  try:
    let parsed = parseInt(configured)
    if parsed < 1:
      return 1'u32
    uint32(parsed)
  except ValueError:
    raise newException(ValueError,
      "REPROBUILD_MAX_PARALLELISM must be a positive integer")

proc stablePublicCliPath(): string =
  let configured = getEnv("REPRO_PUBLIC_CLI_PATH")
  if configured.len > 0:
    if configured.isAbsolute:
      return os.normalizedPath(configured)
    return os.normalizedPath(getCurrentDir() / configured)
  let app = getAppFilename()
  if app.isAbsolute:
    return os.normalizedPath(app)
  if app.contains(DirSep) or app.contains(AltSep):
    return os.normalizedPath(getCurrentDir() / app)
  let resolved = findExe(app)
  if resolved.len > 0:
    if resolved.isAbsolute:
      return os.normalizedPath(resolved)
    return os.normalizedPath(getCurrentDir() / resolved)
  os.normalizedPath(getCurrentDir() / app)

# Executable-Consolidation M1: the internal io-monitor driver is no longer a
# standalone monitor binary. ``repro`` self-spawns its own image with this
# subcommand selector (``repro internal io monitor …``). The
# executable path is ``getAppFilename()`` (more robust than argv[0]/sibling
# lookup) and the selector below is prepended by the build engine via
# ``BuildEngineConfig.monitorCliArgs``.
const internalIoMonitorArgs* = @["internal", "io", "monitor"]

proc selfSpawnIoMonitorPath(publicCliPath = ""): string =
  ## Path to the running ``repro`` image used to self-spawn the internal
  ## io-monitor role.
  let publicPath =
    if publicCliPath.len > 0: publicCliPath else: stablePublicCliPath()
  if publicPath.len > 0:
    return os.normalizedPath(publicPath)
  os.normalizedPath(getAppFilename())

proc internalReproHelperCliPath(publicCliPath: string): string =
  ## Path used for monitored internal helper actions. Since the single-`repro`
  ## consolidation the running ``repro`` image IS the full CLI (no thin wrapper,
  ## no ``repro-full`` companion), so a real ``repro`` process self-spawns its
  ## current image. Embedded/test callers (whose ``getAppFilename`` is a test
  ## binary) fall back to the explicit ``publicCliPath`` they pass in.
  let current = os.normalizedPath(getAppFilename())
  if extractFilename(current) == addFileExt("repro", ExeExt):
    return current
  if publicCliPath.len > 0:
    return os.normalizedPath(publicCliPath)
  current

proc siblingTryCompileProviderPath(publicCliPath: string): string =
  ## Pre-built Tier 2a direct provider binary, normally shipped next to
  ## the repro CLI by ``scripts/build_apps.sh``. Empty string means the
  ## direct provider is unavailable on this install — callers must fall
  ## back to per-project provider compile.
  let candidate = parentDir(publicCliPath) /
    addFileExt("repro-cmake-trycompile-provider", ExeExt)
  if fileExists(extendedPath(candidate)):
    os.normalizedPath(candidate)
  else:
    ""

proc siblingStandardProviderPath(publicCliPath: string): string =
  ## Pre-built Tier 2b standard-provider binary, normally shipped next
  ## to the repro CLI by ``scripts/build_apps.sh``. Empty string means
  ## the standard provider is unavailable on this install — callers
  ## must fall back to per-project provider compile and surface a
  ## warning. See ``Provider-Compile-Tiering.md`` §"2b — repro-standard-
  ## provider".
  let candidate = parentDir(publicCliPath) /
    addFileExt("repro-standard-provider", ExeExt)
  if fileExists(extendedPath(candidate)):
    os.normalizedPath(candidate)
  else:
    ""

proc standardProviderArtifactIdForBinary*(binaryPath: string): string =
  ## Graph snapshots contain convention-lowered commands, so their identity
  ## must change whenever the standard-provider implementation changes.
  ## Content addressing preserves sharing across installations at different
  ## filesystem paths.
  if not fileExists(extendedPath(binaryPath)):
    raise newException(IOError,
      "standard provider binary does not exist: " & binaryPath)
  StandardProviderArtifactId & "." & fileContentDigest(binaryPath)

type
  BuildProgressMode = enum
    bpmQuiet
    bpmLine
    bpmBarLine
    bpmLines
    bpmLinesBar
    bpmDots
    bpmSimpleDots
    bpmSimpleLines
    bpmLiveLines

  BuildProgressBarStyle* = enum
    bpbsOverlay
    bpbsSplit

  MeasureCategory* = enum
    ## CLI/README.md §"Measurement: Collect, Present, Persist" — the
    ## measurement categories. Each one is backed by a real on/off
    ## collection switch in the engine, and each one's data has NO consumer
    ## in the correctness path: it lands in a report, on the screen, or in
    ## the analytics store, and nothing reads it back to decide anything.
    ##
    ## Deliberately absent, and specified as never admissible here: runtime
    ## input/output observation for actions that EXECUTE (it decides whether
    ## the dependency set is publishable, narrows invalidation, and is folded
    ## into the cache record), monitor depfile parsing, dynamic-dependency
    ## discovery, fingerprints/cache keys, and per-action status/exit codes.
    ## Those are the build, not telemetry about the build.
    mcTrace = "trace"
      ## Scheduler trace events (``BuildRunResult.trace``). Sole consumers:
      ## the report document's ``trace`` array and the ``scheduler-trace``
      ## stats observation.
    mcCacheEvidence = "cache-evidence"
      ## Dependency evidence decoded back out of the cache record for
      ## actions that were CACHE HITS. Sole consumers: the report's
      ## ``actions[].evidence``, the per-action log line, and the
      ## ``dependency-evidence`` stats observation. Note the asymmetry with
      ## the evidence collected from an action that RAN, which is inherent
      ## and never gated: this category only skips reading stored evidence
      ## for work that did not happen.
    mcTiming = "timing"
      ## Phase/metric timers (``BuildStats``). Sole consumers: the on-screen
      ## timing table, the report's ``stats`` object, the benchmark document,
      ## and the ``metric`` stats observation.

  MeasureSet* = set[MeasureCategory]

  BuildReportPersistence* = object
    ## PERSIST axis for ``repro build``'s report documents. The default is
    ## outcome-dependent: a successful build writes nothing, a FAILED build
    ## writes the failure report unasked. On failure the report is the
    ## diagnostic payload rather than an optional artifact, and a re-run to
    ## obtain it may not reproduce the failure at all.
    requested*: bool
      ## ``--write-report[=PATH]`` — write the FULL document whatever the
      ## outcome.
    path*: string
      ## Exact destination from ``--write-report=PATH``; empty means the
      ## conventional ``<outDir>/build-report.json``.
    suppressed*: bool
      ## ``--no-write-report`` — write nothing on any outcome. For hermetic
      ## and CI-controlled contexts that must leave the tree untouched.

  BuildLogMode = enum
    blmActions
    blmSummary
    blmQuiet

  BuildDaemonMode = enum
    bdmAuto
    bdmRequire
    bdmOff

  DaemonBuildUnsupported = object of CatchableError

  BuildProgressRenderer = object
    enabled: bool
    mode: BuildProgressMode
    barStyle: BuildProgressBarStyle
    ansi: bool
    color: bool
    nativeProgress: bool
    lastLen: int
    actionStartTimes: Table[string, float]
    actionCommands: Table[string, string]
    activeActions: seq[string]
    completedActions: HashSet[string]

  BuildCommandOutcome = object
    exitCode: int
    modulePath: string
    projectRoot: string
    outDir: string
    buildReportPath: string
    inputEvidencePaths: seq[string]
      ## Every input path the just-finished run observed, harvested
      ## straight off ``BuildRunResult.results[].evidence`` (declared +
      ## depfile + monitor reads/probes).
      ##
      ## ``repro watch`` arms its filesystem watcher from this set, so it
      ## must NOT be derived from the persisted build report: report
      ## persistence is an operator PRESENTATION choice
      ## (``--write-report`` / ``--no-write-report``), while the watched
      ## path set is operational input the watch loop cannot function
      ## without. Reading it from the report file made
      ## ``repro watch`` silently blind to every source file outside the
      ## project's own directory whenever the operator did not pass
      ## ``--write-report`` — the watcher then armed on the project file
      ## plus its parent only, and inotify/kqueue directory watches are
      ## not recursive, so an edit under ``src/`` produced no event and
      ## the loop blocked forever.

  BuildCommandEventSink = proc(kind, message, payloadJson: string)
  WatchCommandEventSink = proc(kind, message, payloadJson: string;
                               terminal: bool; exitCode: int;
                               watchedPaths: seq[string]; lastResult: string)

proc writeBuildBenchmark(path: string; outcome: BuildCommandOutcome;
                         stats: BuildStats; modeName, fastPath: string;
                         executedActions: int;
                         daemonConnectionUs = 0.0) =
  if path.len == 0:
    return
  let graphReadinessUs = stats.metricBucketUs([
    "repro interface extract",
    "repro tool identity resolve",
    "repro provider compile",
    "repro provider graph refresh",
    "repro lowered graph cache read",
    "repro graph lower",
    "repro lowered graph cache write",
    "repro graph infer deps",
    "repro graph validate",
    "repro cmake regeneration",
    "repro cmake state check"])
  let invalidationChecksUs = stats.metricBucketUs([
    "repro output stat",
    "repro fast noop scan",
    "repro hot input scan",
    "repro hot index navigator scan"])
  let cacheChecksUs = stats.metricBucketUs([
    "repro cas open",
    "repro action cache open",
    "repro cache lookup",
    "repro hot record lookup",
    "repro cache hit result materialize",
    "repro cache restore",
    "repro cache record"])
  let node = %*{
    "schemaId": "reprobuild.build.benchmark.v1",
    "mode": modeName,
    "fastPath": fastPath,
    "modulePath": outcome.modulePath,
    "projectRoot": outcome.projectRoot,
    "outDir": outcome.outDir,
    "exitCode": outcome.exitCode,
    "phases": {
      "daemonConnectionUs": daemonConnectionUs,
      "graphReadinessUs": graphReadinessUs,
      "invalidationChecksUs": invalidationChecksUs,
      "cacheChecksUs": cacheChecksUs,
      "executedActions": executedActions
    },
    "metrics": benchmarkMetricsJson(stats)
  }
  let dir = parentDir(path)
  if dir.len > 0:
    createDir(extendedPath(dir))
  writeFile(extendedPath(path), $node)

proc updateBenchmarkDaemonConnection(path: string; daemonConnectionUs: float) =
  if path.len == 0 or not fileExists(extendedPath(path)):
    return
  try:
    let node = parseFile(extendedPath(path))
    if not node.hasKey("phases") or node["phases"].kind != JObject:
      node["phases"] = newJObject()
    node["mode"] = %"daemon"
    node["phases"]["daemonConnectionUs"] = %daemonConnectionUs
    writeFile(extendedPath(path), $node)
  except CatchableError:
    discard

proc parseBuildProgressMode(value: string): BuildProgressMode =
  case value.toLowerAscii()
  of "quiet", "silent", "none", "off":
    bpmQuiet
  of "line", "ninja", "single-line":
    bpmLine
  of "bar-line", "bar", "ninja-bar", "auto", "plain":
    bpmBarLine
  of "lines", "tup", "per-line":
    bpmLines
  of "lines-bar", "tup-bar", "per-line-bar":
    bpmLinesBar
  of "dots", "dot":
    bpmDots
  of "simple-dots":
    bpmSimpleDots
  of "simple-lines":
    bpmSimpleLines
  of "live-lines":
    bpmLiveLines
  else:
    raise newException(ValueError,
      "unsupported --progress=" & value &
        " (expected quiet, line, bar-line, lines, lines-bar, dots, simple-dots, simple-lines, or live-lines)")

proc configuredBuildProgressMode(): BuildProgressMode =
  let configured = getEnv("REPROBUILD_PROGRESS", "")
  if configured.len == 0:
    if getEnv("IN_AGENT_SHELL", "").len > 0:
      return bpmQuiet
    return bpmBarLine
  parseBuildProgressMode(configured)

proc parseBuildProgressBarStyle(value: string): BuildProgressBarStyle =
  case value.toLowerAscii()
  of "overlay", "overlaid", "single", "combined":
    bpbsOverlay
  of "split", "two", "two-bars", "separate":
    bpbsSplit
  else:
    raise newException(ValueError,
      "unsupported --progress-bars=" & value &
        " (expected overlay or split)")

proc configuredBuildProgressBarStyle(): BuildProgressBarStyle =
  let configured = getEnv("REPROBUILD_PROGRESS_BARS", "")
  if configured.len == 0:
    return bpbsOverlay
  parseBuildProgressBarStyle(configured)

const
  DefaultMeasureSet*: MeasureSet = {mcTrace, mcCacheEvidence}
    ## The collection default. ``trace`` and ``cache-evidence`` are on because
    ## measurement is what makes a failure explicable and the moment you need
    ## it is after the failure has already happened. ``timing`` is off: it
    ## instruments the invalidation and cache-lookup hot paths, which is
    ## exactly where a build's own overhead lives.

proc measureCategoryNames*(): seq[string] =
  result = @[]
  for category in MeasureCategory:
    result.add($category)

proc parseMeasureCategories*(current: MeasureSet; value, flag: string):
    MeasureSet =
  ## Additive category-list parse. ``all`` selects every category and
  ## ``none`` CLEARS the set, so ``--measure=none,timing`` is the idiom for an
  ## exact set. There is deliberately no subtractive ``-category`` syntax.
  result = current
  let trimmed = value.strip()
  if trimmed.len == 0:
    raise newException(ValueError,
      "unsupported " & flag & "= (expected one or more of " &
        measureCategoryNames().join(",") & ",all,none)")
  for rawItem in trimmed.split(','):
    let item = rawItem.strip().toLowerAscii()
    case item
    of "":
      raise newException(ValueError,
        "unsupported " & flag & " entry in " & value)
    of "all":
      result = {low(MeasureCategory) .. high(MeasureCategory)}
    of "none":
      result = {}
    else:
      var matched = false
      for category in MeasureCategory:
        if $category == item:
          result.incl(category)
          matched = true
          break
      if not matched:
        raise newException(ValueError,
          "unsupported " & flag & "=" & item & " (expected one or more of " &
            measureCategoryNames().join(",") & ",all,none)")

proc measureSetText*(selection: MeasureSet): string =
  if selection.card == 0:
    return "none"
  var names: seq[string] = @[]
  for category in MeasureCategory:
    if category in selection:
      names.add($category)
  names.join(",")

proc configuredMeasureSet(): MeasureSet =
  let configured = getEnv("REPROBUILD_MEASURE", "")
  if configured.len == 0:
    return DefaultMeasureSet
  parseMeasureCategories(DefaultMeasureSet, configured, "REPROBUILD_MEASURE")

proc configuredShowSet(): MeasureSet =
  ## Presentation defaults to nothing: a build prints progress and
  ## diagnostics, not measurements, unless asked.
  let configured = getEnv("REPROBUILD_SHOW", "")
  if configured.len == 0:
    return {}
  parseMeasureCategories({}, configured, "REPROBUILD_SHOW")

proc parseBuildLogMode(value: string): BuildLogMode =
  case value.toLowerAscii()
  of "actions", "verbose":
    blmActions
  of "summary", "normal":
    blmSummary
  of "quiet", "none", "off":
    blmQuiet
  else:
    raise newException(ValueError,
      "unsupported --log=" & value & " (expected actions, summary, or quiet)")

proc configuredBuildLogMode(): BuildLogMode =
  let configured = getEnv("REPROBUILD_LOG", "")
  if configured.len == 0:
    return blmQuiet
  parseBuildLogMode(configured)

proc parseBuildDaemonMode(value, source: string): BuildDaemonMode =
  case value.normalize
  of "auto":
    bdmAuto
  of "require":
    bdmRequire
  of "off":
    bdmOff
  else:
    raise newException(ValueError,
      "unsupported " & source & "=" & value &
        " (expected auto, require, or off)")

proc configuredBuildDaemonMode(): BuildDaemonMode =
  let configured = getEnv("REPRO_DAEMON", "")
  if configured.len == 0:
    return bdmAuto
  parseBuildDaemonMode(configured, "REPRO_DAEMON")

proc supportsAnsiProgress(): bool =
  isatty(stderr) and getEnv("NO_COLOR", "").len == 0 and
    getEnv("TERM", "") != "dumb"

proc colorProgressEnabled(): bool =
  let configured = getEnv("REPROBUILD_COLOR", "auto").normalize
  case configured
  of "0", "false", "no", "off", "never":
    return false
  of "1", "true", "yes", "on", "always":
    return true
  else:
    if getEnv("NO_COLOR", "").len > 0:
      return false
    return supportsAnsiProgress()

proc nativeTerminalProgressEnabled(): bool =
  let configured = getEnv("REPROBUILD_TERMINAL_PROGRESS", "auto").normalize
  case configured
  of "0", "false", "no", "off", "never":
    return false
  of "1", "true", "yes", "on", "always":
    return supportsAnsiProgress()
  else:
    if not supportsAnsiProgress():
      return false
    if getEnv("WT_SESSION", "").len > 0 or
        getEnv("KONSOLE_VERSION", "").len > 0 or
        getEnv("WEZTERM_PANE", "").len > 0 or
        getEnv("ConEmuPID", "").len > 0 or
        getEnv("MINTTY_SHORTCUT", "").len > 0:
      return true
    let termProgram = getEnv("TERM_PROGRAM", "").toLowerAscii()
    termProgram in ["iterm.app", "wezterm", "ghostty"]

proc newBuildProgressRenderer(mode: BuildProgressMode;
                              barStyle: BuildProgressBarStyle):
    BuildProgressRenderer =
  BuildProgressRenderer(
    enabled: mode != bpmQuiet,
    mode: mode,
    barStyle: barStyle,
    ansi: supportsAnsiProgress(),
    color: colorProgressEnabled(),
    nativeProgress: nativeTerminalProgressEnabled(),
    lastLen: 0,
    actionStartTimes: initTable[string, float](),
    actionCommands: initTable[string, string](),
    activeActions: @[],
    completedActions: initHashSet[string]())

proc ansi(code, text: string): string =
  "\27[" & code & "m" & text & "\27[0m"

proc isUtf8Continuation(ch: char): bool =
  (ord(ch) and 0xC0) == 0x80

proc utf8CharLen(text: string; index: int): int =
  if index >= text.len:
    return 0
  let b = ord(text[index])
  result =
    if (b and 0x80) == 0x00: 1
    elif (b and 0xE0) == 0xC0: 2
    elif (b and 0xF0) == 0xE0: 3
    elif (b and 0xF8) == 0xF0: 4
    else: 1
  result = min(result, text.len - index)

proc visibleLen(text: string): int =
  var i = 0
  while i < text.len:
    if text[i] == '\27' and i + 1 < text.len and text[i + 1] == '[':
      i.inc(2)
      while i < text.len and not (text[i] in {'A' .. 'Z', 'a' .. 'z'}):
        i.inc
      if i < text.len:
        i.inc
    else:
      if not isUtf8Continuation(text[i]):
        result.inc
      i.inc

proc takeVisiblePrefix(text: string; width: int): string =
  var
    i = 0
    visible = 0
    inAnsi = false
  while i < text.len and (visible < width or inAnsi):
    if text[i] == '\27' and i + 1 < text.len and text[i + 1] == '[':
      result.add(text[i])
      inAnsi = true
      i.inc
    elif inAnsi and text[i] in {'A' .. 'Z', 'a' .. 'z'}:
      result.add(text[i])
      inAnsi = false
      i.inc
    elif inAnsi:
      result.add(text[i])
      i.inc
    elif not isUtf8Continuation(text[i]):
      let charLen = utf8CharLen(text, i)
      result.add(text[i ..< i + charLen])
      visible.inc
      i.inc(charLen)
    else:
      i.inc
  if result.contains("\27["):
    result.add("\27[0m")

proc progressCell(glyph, colorCode: string; color: bool): string =
  if color: ansi(colorCode, glyph) else: glyph

proc progressBar(completed, total, width: int; color = false;
                 filledColor = "38;5;42"; emptyColor = "38;5;240";
                 filledGlyph = "#"; emptyGlyph = "."): string =
  let safeWidth = max(width, 1)
  let clampedCompleted =
    if total <= 0:
      0
    else:
      min(max(completed, 0), total)
  let filled =
    if total <= 0:
      0
    else:
      min(safeWidth, (clampedCompleted * safeWidth) div total)
  let
    openBracket = if color: ansi("38;5;244", "[") else: "["
    closeBracket = if color: ansi("38;5;244", "]") else: "]"
    filledCell = progressCell(filledGlyph, filledColor, color)
    emptyCell = progressCell(emptyGlyph, emptyColor, color)
  result = openBracket
  for i in 0 ..< safeWidth:
    result.add(if i < filled: filledCell else: emptyCell)
  result.add(closeBracket)

proc fitProgressLine(line: string; width: int): string =
  if width <= 0 or line.visibleLen <= width:
    return line
  if width <= 3:
    return line.takeVisiblePrefix(width)
  line.takeVisiblePrefix(width - 3) & "..."

proc statusLabel(event: BuildProgressEvent): string =
  case event.kind
  of bpkActionStarted:
    "started"
  of bpkActionCompleted:
    case event.status
    of asSucceeded:
      if event.launched: "executed" else: "succeeded"
    of asCacheHit:
      "cache-hit"
    of asUpToDate:
      "up-to-date"
    of asFailed:
      "failed"
    of asBlocked:
      "blocked"
    else:
      $event.status

proc buildProgressPercent(event: BuildProgressEvent): int =
  if event.total <= 0:
    100
  else:
    let checked =
      if event.checked > 0 or event.completed == 0: event.checked
      else: event.completed
    min(100, (max(checked, 0) * 100) div event.total)

proc countWidth(total: int): int =
  max(1, ($max(total, 0)).len)

proc checkedCount(event: BuildProgressEvent): int =
  if event.checked > 0 or event.completed == 0: event.checked
  else: event.completed

proc settledCount(event: BuildProgressEvent): int =
  if event.settled > 0 or event.completed == 0: event.settled
  else: event.completed

proc checkedCounter(event: BuildProgressEvent): string =
  let width = countWidth(event.total)
  "checked=" & align($checkedCount(event), width) & "/" &
    align($event.total, width)

proc builtCounter(event: BuildProgressEvent): string =
  let width = countWidth(event.plannedExecutions)
  "built=" & align($event.completedExecutions, width) & "/" &
    align($event.plannedExecutions, width)

proc buildProgressCounters(event: BuildProgressEvent): string =
  result = checkedCounter(event)
  if event.executionPlanKnown and event.plannedExecutions > 0:
    result.add(" " & builtCounter(event))
  elif event.plannedExecutions > 0 or event.running > 0:
    result.add(" settled=" & align($settledCount(event), countWidth(event.total)) &
      "/" & align($event.total, countWidth(event.total)))

proc buildProgressOverlayBar(event: BuildProgressEvent; width: int;
                             color = false): string =
  let checked =
    if event.checked > 0 or event.completed == 0: event.checked
    else: event.completed
  let settled =
    if event.settled > 0 or event.completed == 0: event.settled
    else: event.completed
  let safeWidth = max(width, 1)
  let executionScale = event.executionPlanKnown and
    event.plannedExecutions > 0 and settled < event.total
  let
    checkedFilled =
      if event.total <= 0: 0
      else: min(safeWidth, (max(checked, 0) * safeWidth) div event.total)
    settledFilled =
      if event.total <= 0: 0
      else: min(safeWidth, (max(settled, 0) * safeWidth) div event.total)
    executedFilled =
      if event.plannedExecutions <= 0: 0
      else: min(safeWidth,
        (max(event.completedExecutions, 0) * safeWidth) div
          event.plannedExecutions)
  let
    openBracket = if color: ansi("38;5;244", "▕") else: "["
    closeBracket = if color: ansi("38;5;244", "▏") else: "]"
    settledGlyph = if color: "█" else: "#"
    checkedGlyph = if color: "▓" else: "+"
    executeGlyph = if color: "█" else: "#"
    emptyGlyph = if color: "░" else: "."
  result = openBracket
  for i in 0 ..< safeWidth:
    if executionScale:
      if i < executedFilled:
        result.add(progressCell(executeGlyph, "38;5;213", color))
      else:
        result.add(progressCell(emptyGlyph, "38;5;240", color))
    elif i < settledFilled:
      result.add(progressCell(settledGlyph, "38;5;39", color))
    elif i < checkedFilled:
      result.add(progressCell(checkedGlyph, "38;5;42", color))
    else:
      result.add(progressCell(emptyGlyph, "38;5;240", color))
  result.add(closeBracket)

proc buildProgressSplitBars(event: BuildProgressEvent; width: int;
                            color = false): string =
  let checked =
    if event.checked > 0 or event.completed == 0: event.checked
    else: event.completed
  let checkWidth =
    if event.plannedExecutions > 0 or event.running > 0:
      max(8, (width * 3) div 5)
    else:
      max(width, 1)
  let execWidth = max(6, width - checkWidth)
  result = progressBar(checked, event.total, checkWidth, color,
    filledColor = "38;5;42", filledGlyph = if color: "█" else: "#",
    emptyGlyph = if color: "░" else: ".")
  if event.plannedExecutions > 0 or event.running > 0:
    result.add(" exec")
    result.add(progressBar(event.completedExecutions, event.plannedExecutions,
      execWidth, color, filledColor = "38;5;213",
      filledGlyph = if color: "█" else: "#",
      emptyGlyph = if color: "░" else: "."))

proc buildProgressBarsWithCounters(event: BuildProgressEvent; width: int;
                                   color = false;
                                   barStyle = bpbsOverlay): string =
  let hasExecBar = barStyle == bpbsSplit and
    (event.plannedExecutions > 0 or event.running > 0)
  let checkedText = checkedCounter(event)
  let builtText =
    if hasExecBar:
      " " & builtCounter(event)
    else:
      ""
  let checkWidth =
    if hasExecBar:
      max(8, (width * 3) div 5)
    else:
      max(width, 1)
  let execWidth = max(6, width - checkWidth)
  case barStyle
  of bpbsOverlay:
    result = buildProgressOverlayBar(event, width, color) & " " & checkedText
    if event.executionPlanKnown and event.plannedExecutions > 0:
      result.add(" " & builtCounter(event))
  of bpbsSplit:
    result = progressBar(checkedCount(event), event.total, checkWidth, color,
      filledColor = "38;5;42", filledGlyph = if color: "█" else: "#",
      emptyGlyph = if color: "░" else: ".") & " " & checkedText
    if hasExecBar:
      result.add(" ")
      result.add(progressBar(event.completedExecutions, event.plannedExecutions,
        execWidth, color, filledColor = "38;5;213",
        filledGlyph = if color: "█" else: "#",
        emptyGlyph = if color: "░" else: "."))
      result.add(builtText)

proc buildProgressBars(event: BuildProgressEvent; width: int;
                       color = false;
                       barStyle = bpbsOverlay): string =
  case barStyle
  of bpbsOverlay:
    buildProgressOverlayBar(event, width, color)
  of bpbsSplit:
    buildProgressSplitBars(event, width, color)

proc buildProgressInvocation(event: BuildProgressEvent): string =
  let invocation =
    if event.currentCommand.len > 0:
      event.currentCommand
    elif event.kind == bpkActionCompleted and not event.launched:
      event.actionId
    elif event.command.len > 0:
      event.command
    else:
      event.actionId
  var singleLine = invocation
  for i in 0 ..< singleLine.len:
    if singleLine[i] in {'\r', '\n', '\t'}:
      singleLine[i] = ' '
  while singleLine.contains("  "):
    singleLine = singleLine.replace("  ", " ")
  if event.currentCommand.len > 0:
    singleLine.strip()
  else:
    statusLabel(event) & " " & singleLine.strip()

proc nativeProgressPercent(event: BuildProgressEvent): int =
  let executionScale = event.executionPlanKnown and
    event.plannedExecutions > 0 and event.settled < event.total
  if executionScale:
    if event.plannedExecutions <= 0: 100
    else:
      min(100, (max(event.completedExecutions, 0) * 100) div
        event.plannedExecutions)
  elif event.total <= 0:
    100
  else:
    let checked =
      if event.checked > 0 or event.completed == 0: event.checked
      else: event.completed
    min(100, (max(checked, 0) * 100) div event.total)

proc writeNativeProgress(renderer: BuildProgressRenderer;
                         event: BuildProgressEvent) =
  if not renderer.nativeProgress:
    return
  let state =
    if event.status == asFailed: 2
    elif event.running > 0 or event.ready > 0 or event.checked < event.total: 1
    else: 1
  stderr.write("\27]9;4;" & $state & ";" & $nativeProgressPercent(event) & "\7")

proc clearNativeProgress(renderer: BuildProgressRenderer) =
  if renderer.nativeProgress:
    stderr.write("\27]9;4;0\7")

proc formatBuildProgressLine*(event: BuildProgressEvent; width = 80;
                              includeBar = true; barWidth = 20;
                              color = false;
                              barStyle = bpbsOverlay): string =
  let prefix =
    if includeBar:
      buildProgressBarsWithCounters(event, barWidth, color, barStyle)
    else:
      buildProgressCounters(event)
  let counters = " running=" & $event.running
  let tail = " " & buildProgressInvocation(event)
  fitProgressLine(prefix & counters & tail, max(width, 20))

proc formatBuildProgressBarLine(event: BuildProgressEvent; width: int;
                                color = false;
                                barStyle = bpbsOverlay): string =
  let suffix = " running=" & $event.running
  let barWidth = max(10, width - suffix.len - 2)
  fitProgressLine(buildProgressBarsWithCounters(event, barWidth, color,
    barStyle) & suffix, max(width, 20))

proc progressLineWidth(): int =
  min(max(terminalWidth(), 40), 160)

proc clearProgressLine(renderer: BuildProgressRenderer) =
  if renderer.ansi:
    stderr.write("\r\27[2K")
  else:
    stderr.write("\r")

proc writeRedrawnProgress(renderer: var BuildProgressRenderer; line: string) =
  renderer.clearProgressLine()
  var outLine = line
  if not renderer.ansi and outLine.len < renderer.lastLen:
    outLine.add(repeat(' ', renderer.lastLen - outLine.len))
  stderr.write(outLine)
  stderr.flushFile()
  renderer.lastLen = line.len

proc clearLines(renderer: BuildProgressRenderer; count: int) =
  if count <= 0: return
  if renderer.ansi:
    stderr.write("\r\27[2K")
    for _ in 1 ..< count:
      stderr.write("\27[1A\27[2K")
  else:
    stderr.write("\r")
  stderr.flushFile()

proc formatDuration(secs: float): string =
  if secs < 1.0:
    $int(secs * 1000.0) & "ms"
  else:
    formatFloat(secs, ffDecimal, 1) & "s"

proc renderPhase(renderer: var BuildProgressRenderer; phase: string) =
  if not renderer.enabled:
    return
  renderer.writeRedrawnProgress(fitProgressLine(phase, progressLineWidth()))

proc shouldEmitProgressUnit(event: BuildProgressEvent): bool =
  event.kind == bpkActionCompleted

proc renderProgress(renderer: var BuildProgressRenderer; event: BuildProgressEvent) =
  if not renderer.enabled:
    return
  renderer.writeNativeProgress(event)
  let width = progressLineWidth()
  case renderer.mode
  of bpmQuiet:
    discard
  of bpmLine:
    renderer.writeRedrawnProgress(formatBuildProgressLine(event, width,
      includeBar = false))
  of bpmBarLine:
    renderer.writeRedrawnProgress(formatBuildProgressLine(event, width,
      includeBar = true, barWidth = 24, color = renderer.color,
      barStyle = renderer.barStyle))
  of bpmLines:
    stderr.writeLine(formatBuildProgressLine(event, width, includeBar = false))
    stderr.flushFile()
    renderer.lastLen = 0
  of bpmLinesBar:
    renderer.clearProgressLine()
    stderr.writeLine(formatBuildProgressLine(event, width, includeBar = false))
    renderer.writeRedrawnProgress(formatBuildProgressBarLine(event, width,
      color = renderer.color, barStyle = renderer.barStyle))
  of bpmDots:
    if event.kind == bpkActionStarted:
      if event.actionId notin renderer.actionStartTimes:
        renderer.actionStartTimes[event.actionId] = epochTime()
        renderer.actionCommands[event.actionId] = event.command
        renderer.activeActions.add(event.actionId)
    elif event.kind == bpkActionCompleted:
      if event.actionId notin renderer.actionStartTimes:
        renderer.actionStartTimes[event.actionId] = epochTime()
        renderer.actionCommands[event.actionId] = event.command
      var newActive: seq[string] = @[]
      for act in renderer.activeActions:
        if act != event.actionId:
          newActive.add(act)
      renderer.activeActions = newActive
      renderer.completedActions.incl(event.actionId)

    if renderer.actionStartTimes.len > 0:
      renderer.clearProgressLine()
      var dotsStr = ""
      for id, _ in renderer.actionStartTimes:
        if id in renderer.completedActions:
          if renderer.color:
            dotsStr.add(ansi("32", "."))
          else:
            dotsStr.add(".")
        else:
          if renderer.color:
            dotsStr.add(ansi("90", "."))
          else:
            if unicodeEnabled():
              dotsStr.add("·")
            else:
              dotsStr.add(",")
      renderer.writeRedrawnProgress(fitProgressLine(dotsStr, width))

  of bpmSimpleDots:
    if event.kind == bpkActionCompleted:
      stderr.write(".")
      stderr.flushFile()
      renderer.lastLen.inc

  of bpmSimpleLines:
    if event.kind == bpkActionStarted:
      if event.actionId notin renderer.actionStartTimes:
        renderer.actionStartTimes[event.actionId] = epochTime()
        renderer.actionCommands[event.actionId] = event.command
        stderr.writeLine("Starting: " & event.command)
        stderr.flushFile()
    elif event.kind == bpkActionCompleted:
      let startTime =
        if event.actionId in renderer.actionStartTimes:
          renderer.actionStartTimes[event.actionId]
        else:
          stderr.writeLine("Starting: " & event.command)
          stderr.flushFile()
          epochTime()
      let elapsed = epochTime() - startTime
      let statusStr = if event.status == asFailed: "FAILED" else: "SUCCESS"
      stderr.writeLine("Finished: " & event.command & " in " & formatDuration(elapsed) & " [" & statusStr & "]")
      stderr.flushFile()
      renderer.completedActions.incl(event.actionId)

  of bpmLiveLines:
    if event.kind == bpkActionStarted:
      if event.actionId notin renderer.actionStartTimes:
        renderer.actionStartTimes[event.actionId] = epochTime()
        renderer.actionCommands[event.actionId] = event.command
        renderer.activeActions.add(event.actionId)
    elif event.kind == bpkActionCompleted:
      let startTime =
        if event.actionId in renderer.actionStartTimes:
          renderer.actionStartTimes[event.actionId]
        else:
          epochTime()
      
      var newActive: seq[string] = @[]
      for act in renderer.activeActions:
        if act != event.actionId:
          newActive.add(act)
      renderer.activeActions = newActive
      renderer.completedActions.incl(event.actionId)
      
      # Write completed action permanently
      renderer.clearLines(renderer.lastLen)
      renderer.lastLen = 0
      
      let elapsed = epochTime() - startTime
      let checkbox =
        if event.status == asFailed:
          if renderer.color: ansi("31", if unicodeEnabled(): "[✗]" else: "[FAIL]")
          else: (if unicodeEnabled(): "[✗]" else: "[FAIL]")
        else:
          if renderer.color: ansi("32", if unicodeEnabled(): "[✓]" else: "[OK]")
          else: (if unicodeEnabled(): "[✓]" else: "[OK]")
      
      stderr.writeLine(event.command & " (" & formatDuration(elapsed) & ") " & checkbox)
      stderr.flushFile()

    # Redraw active actions
    if event.kind != bpkActionCompleted:
      renderer.clearLines(renderer.lastLen)
      renderer.lastLen = 0

    for actId in renderer.activeActions:
      let elapsed = epochTime() - renderer.actionStartTimes[actId]
      let cmd = renderer.actionCommands.getOrDefault(actId, "")
      stderr.writeLine(cmd & " (" & formatDuration(elapsed) & ")")
    stderr.flushFile()
    renderer.lastLen = renderer.activeActions.len

proc finishProgress(renderer: var BuildProgressRenderer) =
  renderer.clearNativeProgress()
  if renderer.enabled:
    if renderer.mode == bpmLiveLines:
      renderer.clearLines(renderer.lastLen)
      renderer.lastLen = 0
    elif renderer.lastLen > 0:
      stderr.write("\n")
      stderr.flushFile()
      renderer.lastLen = 0

proc tryRenderDaemonProgress(renderer: var BuildProgressRenderer;
                             payloadJson: string): bool =
  ## Re-render a daemon-forwarded progress event through the CLIENT's own
  ## `BuildProgressRenderer` so `--progress` is honored in daemon-hosted mode.
  ## The daemon emits each `BuildProgressEvent` as a `bekDiagnostic` whose
  ## payload carries the structured fields (tagged `"event":"progress"`);
  ## without this the client would print the raw `progress: <kind> <id>`
  ## message verbatim and ignore the requested progress mode. Returns true
  ## (and renders) when `payloadJson` is a progress event.
  if payloadJson.len == 0:
    return false
  var node: JsonNode
  try:
    node = parseJson(payloadJson)
  except CatchableError:
    return false
  if node.kind != JObject or node{"event"}.getStr != "progress":
    return false
  var event: BuildProgressEvent
  try:
    event.kind = parseEnum[BuildProgressKind](node{"kind"}.getStr)
    if node{"status"}.getStr.len > 0:
      event.status = parseEnum[ActionStatus](node{"status"}.getStr)
  except ValueError:
    return false
  event.actionId = node{"actionId"}.getStr
  event.command = node{"command"}.getStr
  event.currentCommand = node{"currentCommand"}.getStr
  event.total = node{"total"}.getInt
  event.completed = node{"completed"}.getInt
  event.checked = node{"checked"}.getInt
  event.running = node{"running"}.getInt
  event.ready = node{"ready"}.getInt
  renderer.renderProgress(event)
  true

proc emitFailedActionSummaries(buildResult: BuildRunResult;
                               eventSink: BuildCommandEventSink;
                               renderer: var BuildProgressRenderer) =
  ## Surface each failed action's id, exit code, and stderr to the terminal.
  ## Otherwise the only failure signal is a non-zero exit code (and, over the
  ## daemon protocol, the generic "daemon-hosted build failed" line), which
  ## forces the user to open build-report.json to learn what actually broke.
  for item in buildResult.results:
    if item.status != asFailed:
      continue
    var summary = "repro build: action failed: " & item.id &
      " (exit code " & $item.exitCode & ")"
    if item.stderr.len > 0:
      summary.add('\n')
      summary.add(strip(item.stderr, leading = false))
    if eventSink != nil:
      # The client routes ``"stream":"stderr"`` diagnostics to its stderr.
      eventSink("diagnostic", summary, "{\"stream\":\"stderr\"}")
    else:
      renderer.clearProgressLine()
      stderr.writeLine(summary)
      stderr.flushFile()

proc statStart(enabled: bool): float =
  if enabled:
    epochTime()
  else:
    0.0

proc finishStat(stats: var BuildStats; enabled: bool; name: string;
                started: float) =
  if enabled:
    stats.addMetric(name, (epochTime() - started) * 1_000_000.0)

proc addCounterMetric(stats: var BuildStats; enabled: bool; name: string;
                      count: int) =
  if not enabled:
    return
  for _ in 0 ..< count:
    stats.addMetric(name, 0.0)

proc recordInterfaceArtifactWarmStats(stats: var BuildStats; enabled: bool) =
  let warmStats = consumeInterfaceArtifactWarmStats()
  stats.addCounterMetric(enabled, "repro interface metadata cold read",
    warmStats.metadataColdReads)
  stats.addCounterMetric(enabled, "repro interface metadata warm hit",
    warmStats.metadataWarmHits)
  stats.addCounterMetric(enabled, "repro interface metadata warm miss",
    warmStats.metadataWarmMisses)
  stats.addCounterMetric(enabled, "repro interface metadata source revalidate",
    warmStats.metadataRevalidatedSources)
  stats.addCounterMetric(enabled, "repro interface metadata reprolib revalidate",
    warmStats.metadataRevalidatedReproLibs)
  stats.addCounterMetric(enabled, "repro interface artifact cold read",
    warmStats.artifactColdReads)
  stats.addCounterMetric(enabled, "repro interface artifact warm hit",
    warmStats.artifactWarmHits)
  stats.addCounterMetric(enabled, "repro interface artifact warm miss",
    warmStats.artifactWarmMisses)

proc renderBuildStats*(stats: BuildStats): string =
  let nameWidth = 36
  result = "metric" & repeat(' ', nameWidth - "metric".len) &
    " count   avg (us)        total (ms)\n"
  for metric in stats.metrics:
    let avgUs =
      if metric.count > 0:
        metric.totalUs / float(metric.count)
      else:
        0.0
    let totalMs = metric.totalUs / 1000.0
    let paddedName =
      if metric.name.len < nameWidth:
        metric.name & repeat(' ', nameWidth - metric.name.len)
      else:
        metric.name & " "
    result.add(paddedName & " " &
      align($metric.count, 5) & "   " &
      align(formatFloat(avgUs, ffDecimal, 1), 8) & "        " &
      formatFloat(totalMs, ffDecimal, 1) & "\n")

proc recordStatsForBuildRun(runResult: BuildRunResult) =
  if not statsCaptureActive():
    return
  for metric in runResult.stats.metrics:
    enqueueStatsObservation(scgTiming, "metric", %*{
      "name": metric.name,
      "count": metric.count,
      "totalUs": metric.totalUs
    })
  for traceEvent in runResult.trace:
    enqueueStatsObservation(scgTiming, "scheduler-trace", %*{
      "seq": traceEvent.seq,
      "actionId": traceEvent.actionId,
      "event": traceEvent.event,
      "detail": traceEvent.detail
    })
  for item in runResult.results:
    enqueueStatsObservation(scgSessions, "action-result", %*{
      "actionId": item.id,
      "status": $item.status,
      "launched": item.launched,
      "wouldLaunch": item.wouldLaunch,
      "exitCode": item.exitCode,
      "reason": item.reason
    })
    enqueueStatsObservation(scgCache, "cache-decision", %*{
      "actionId": item.id,
      "cacheDecision": $item.cacheDecision,
      "status": $item.status,
      "launched": item.launched,
      "reason": item.reason
    })
    enqueueStatsObservation(scgRunQuota, "lease-completion", %*{
      "actionId": item.id,
      "launched": item.launched,
      "leaseId": item.leaseId,
      "runQuotaBackend": item.runQuotaBackend,
      "runQuotaSocket": item.runQuotaSocket,
      "exitCode": item.exitCode,
      "status": $item.status
    })
    enqueueStatsObservation(scgDeps, "dependency-evidence", %*{
      "actionId": item.id,
      "policy": $item.dependencyPolicyKind,
      "declaredInputs": item.evidence.declaredInputs.len,
      "declaredOutputs": item.evidence.declaredOutputs.len,
      "depfileInputs": item.evidence.depfileInputs.len,
      "monitorReads": item.evidence.monitorReads.len,
      "monitorWrites": item.evidence.monitorWrites.len,
      "monitorProbes": item.evidence.monitorProbes.len,
      "diagnostics": item.evidence.diagnostics.len
    })

proc cliPathExists(path: string): bool =
  fileExists(extendedPath(path)) or dirExists(extendedPath(path))

proc actionOutputsPresent(action: BuildAction): bool =
  if action.outputs.len == 0:
    return false
  for output in action.outputs:
    let path =
      if output.isAbsolute or action.cwd.len == 0:
        output
      else:
        action.cwd / output
    if not path.cliPathExists():
      return false
  true

proc cmakeGeneratedStateFresh(meta: CmakeRegenerationMetadata;
                              publicCliPath: string): bool =
  if meta.providerFile.len == 0 or meta.providerStateFile.len == 0:
    return false
  if not fileExists(extendedPath(meta.providerFile)) or not fileExists(extendedPath(meta.providerStateFile)):
    return false
  if readFile(extendedPath(meta.providerFile)) != readFile(extendedPath(meta.providerStateFile)):
    return false
  let stamp = getLastModificationTime(extendedPath(meta.providerStateFile))
  for input in cmakeRegenerationInputs(meta, publicCliPath):
    if (fileExists(extendedPath(input)) or dirExists(extendedPath(input))) and
        getLastModificationTime(extendedPath(input)) > stamp:
      return false
  true

proc seedCmakeRegenerationCache(meta: CmakeRegenerationMetadata;
                                publicCliPath, outDir: string): bool =
  let regenerationAction = cmakeRegenerationBuildAction(meta, publicCliPath)
  if not regenerationAction.cacheable:
    return false
  if not regenerationAction.actionOutputsPresent():
    return false
  # CAS + action-cache moved to the user-level shared root in M70 (see
  # Provider-Compile-Tiering.md §"Cache Scope" Phase 1). The project-local
  # cmake-regeneration-cache dir is still used for per-build scratch
  # (runquota-results, monitor depfiles, dependency-evidence files) but the
  # action cache itself lives under the shared root so cross-project hits
  # are possible.
  # The action cache + CAS live under the user-level shared root (Phase 1
  # of Provider-Compile-Tiering.md §"Cache Scope"); the dependency-evidence
  # file stays project-local because it tracks per-project regeneration
  # state, not action result bytes.
  let sharedRoot = currentActionCacheRoot()
  let cmakeCacheRoot = outDir / "cmake-regeneration-cache"
  let cas = openLocalCas(sharedRoot / "cas")
  var cache = openActionCache(sharedRoot / "action-cache")
  defer:
    cache.flushHotIndex()
  let record = cache.recordActionResult(cas, regenerationAction.weakFingerprint,
    regenerationAction.actionCachePolicy, regenerationAction.inputs,
    regenerationAction.outputs, regenerationAction.cwd,
    storeOutputBlobs = false)
  writeActionResultRecordFile(
    dependencyEvidencePath(cmakeCacheRoot, regenerationAction.id), record)
  true

proc mergeProjectExtensions(snapshot: var ProviderGraphSnapshot;
                            projectRoot, originalPackageName: string;
                            mode: ToolProvisioningMode;
                            publicCliPath, workRoot: string;
                            lowerGraph = true): string
  ## Workspace-Manifest-Optional MO-6 — forward declaration. Defined
  ## after ``prepareBuildGraphInspection`` (which it reuses to compile +
  ## evaluate each discovered extension recipe). ``executeBuildTarget``
  ## and ``prepareBuildGraphInspection`` both call it to fold any
  ## present ``projectExtension`` sibling's fragments into the target
  ## project's snapshot before lowering / target-export aggregation.

type
  RecipeProviderSnapshotRefresh = object
    snapshot: Option[ProviderGraphSnapshot]
    providerInvocations: int

proc refreshRecipeProviderSnapshot(target: string;
                                   mode: ToolProvisioningMode;
                                   publicCliPath, workRoot: string;
                                   bypassRunQuotaExplicit: bool):
    RecipeProviderSnapshotRefresh
  ## Forward declaration for focused tool provisioning. The implementation
  ## reuses metadata-only graph inspection and is defined below it.

proc selectedToolIdentitySelectors(snapshot: ProviderGraphSnapshot;
                                   projectRoot: string;
                                   selectedActionIds: openArray[string]):
    HashSet[string] =
  ## Resolve the selected action closure without provisioning tools, then
  ## return the package/executable selectors that closure actually references.
  ## Synthetic profiles only satisfy the lowering layer's typed-call lookup;
  ## they are never persisted or used to execute an action.
  var identity = PathOnlyBuildIdentity(projectName: "metadata-selection")
  var packageNamesByExecutable = initTable[string, seq[string]]()
  var seenProfiles = initHashSet[string]()
  for fragment in snapshot.fragments:
    for node in fragment.nodes:
      if node.kind != gnkAction:
        continue
      let action = decodeBuildActionPayload(toBytes(node.payload))
      let packageName = action.call.packageName
      let executableName = action.call.executableName
      if packageName.len == 0 or executableName.len == 0:
        continue
      let key = packageName & "\0" & executableName
      if not seenProfiles.containsOrIncl(key):
        identity.profiles.add(PathOnlyToolProfile(
          packageSelector: packageName,
          executableName: executableName,
          resolvedExecutablePath: executableName))
      if not packageNamesByExecutable.hasKey(executableName):
        packageNamesByExecutable[executableName] = @[]
      if packageNamesByExecutable[executableName].find(packageName) < 0:
        packageNamesByExecutable[executableName].add(packageName)

  let selected = lowerProviderSnapshot(snapshot, identity, projectRoot,
    selectedActionIds)
  for action in selected.actions:
    for selector in action.toolIdentityRefs:
      if selector.len > 0:
        result.incl(selector)
    if action.argv.len > 0 and
        packageNamesByExecutable.hasKey(action.argv[0]):
      result.incl(action.argv[0])
      for packageName in packageNamesByExecutable[action.argv[0]]:
        result.incl(packageName)

proc scopedToolArtifact(artifact: ProjectInterfaceArtifact;
                        snapshot: ProviderGraphSnapshot;
                        projectRoot: string;
                        selectedActionIds: openArray[string]):
    ProjectInterfaceArtifact =
  ## Keep the full interface fingerprint for provider/cache invalidation while
  ## narrowing identity realization to tools referenced by the selected graph.
  result = artifact
  let required = selectedToolIdentitySelectors(snapshot, projectRoot,
    selectedActionIds)
  result.projectInterface.toolUses = @[]
  for useDef in artifact.projectInterface.toolUses:
    if useDef.packageSelector in required or
        useDef.executableName in required:
      result.projectInterface.toolUses.add(useDef)

proc selectorFilesystemKey(selector: string): string =
  ## A filesystem-safe directory name for a cross-repo producer selector:
  ## alphanumerics + ``.`` / ``_`` / ``-`` pass through; every other byte
  ## becomes ``_``. Empty selectors (never reached here — the caller guards
  ## ``selector.len == 0``) map to ``package`` for safety.
  for ch in selector:
    if ch.isAlphaNumeric() or ch in {'.', '_', '-'}:
      result.add(ch)
    else:
      result.add('_')
  if result.len == 0:
    result = "package"

proc producerSourceRoot(binding: ProducerBinding; selector,
                        workspaceRoot: string;
                        fetchMissingPinnedSource: bool): string =
  ## Resolve the source root used by both producer builds and graph
  ## inspection. Inspection normally finds an existing workspace sibling;
  ## lock-only consumers may fetch the pinned source when requested.
  case binding.kind
  of pbkDevelopOverride:
    result = binding.localPathAbsolute
  of pbkLockPinned:
    let sibling = findSiblingProjectFile(selector, workspaceRoot)
    if sibling.len > 0:
      result = parentDir(sibling)
    elif fetchMissingPinnedSource:
      result = fetchLockPinnedProducer(binding.lockedDep, workspaceRoot)
  of pbkOnDiskSibling, pbkNotProducer:
    discard

proc recordProducerMaterialization(selector, producerRootAbs: string;
                                   producerArtifact: ProjectInterfaceArtifact;
                                   producerRuntimeIdentity: PathOnlyBuildIdentity;
                                   binding: ProducerBinding): bool =
  ## Discover a producer's already-materialized public outputs and project
  ## them onto the consumer's executable/library channels. The build path
  ## calls this after the producer sub-build; graph inspection calls it while
  ## loading an existing graph. Keeping this projection shared prevents the
  ## two surfaces from resolving different producer identities.
  var binDirs: seq[string] = @[]
  var realizedBinaries: seq[string] = @[]
  for exe in producerArtifact.projectInterface.publicExecutables:
    let binName =
      if exe.binaryName.len > 0: exe.binaryName else: exe.exportName
    if binName.len == 0:
      continue
    let realized = producerRootAbs / "build" / "bin" /
      addFileExt(binName, ExeExt)
    if fileExists(extendedPath(realized)):
      let binDir = parentDir(realized)
      if binDir notin binDirs:
        binDirs.add(binDir)
      if realized notin realizedBinaries:
        realizedBinaries.add(realized)

  var aux = ProducerAuxPaths()
  mergeProducerRuntimeIdentity(producerRuntimeIdentity, binDirs, aux)
  var realizedLibraries: seq[string] = @[]
  block libraryChannel:
    let libOutDir = producerRootAbs / "build" / "lib"
    let includeOutDir = producerRootAbs / "build" / "include"
    let pkgConfigOutDir = libOutDir / "pkgconfig"
    if not dirExists(extendedPath(libOutDir)):
      break libraryChannel
    for lib in producerArtifact.projectInterface.publicLibraries:
      if lib.name.len == 0 or lib.kind == lkHeaderOnly:
        continue
      let stem = lib.name
      let libStem = "lib" & lib.name
      for entryKind, entryPath in walkDir(extendedPath(libOutDir)):
        if entryKind != pcFile:
          continue
        let tail = splitPath(entryPath).tail
        let dotIdx = tail.find('.')
        let base = if dotIdx > 0: tail[0 ..< dotIdx] else: tail
        if base == stem or base == libStem:
          let realizedLib = libOutDir / tail
          if realizedLib notin realizedLibraries:
            realizedLibraries.add(realizedLib)
    if realizedLibraries.len > 0:
      if libOutDir notin aux.libDirs:
        aux.libDirs.add(libOutDir)
      if dirExists(extendedPath(includeOutDir)) and
          includeOutDir notin aux.includeDirs:
        aux.includeDirs.add(includeOutDir)
      if dirExists(extendedPath(pkgConfigOutDir)) and
          pkgConfigOutDir notin aux.pkgConfigDirs:
        aux.pkgConfigDirs.add(pkgConfigOutDir)

  for lib in producerArtifact.projectInterface.publicLibraries:
    if lib.name.len == 0:
      continue
    let exported =
      if lib.exportedPath.len > 0: lib.exportedPath else: "src"
    let nimSrcDir = producerRootAbs / exported
    if dirExists(extendedPath(nimSrcDir)) and nimSrcDir notin aux.nimPathDirs:
      aux.nimPathDirs.add(nimSrcDir)

  let haveLibChannel = aux.libDirs.len > 0 or aux.includeDirs.len > 0 or
    aux.pkgConfigDirs.len > 0 or aux.cmakePrefixDirs.len > 0 or
    aux.nimPathDirs.len > 0
  if realizedBinaries.len == 0 and not haveLibChannel:
    return false

  if binDirs.len > 0:
    producerMaterializedBinDirs[selector] = binDirs
  if haveLibChannel:
    producerMaterializedAuxPaths[selector] = aux

  realizedBinaries.sort()
  realizedLibraries.sort()
  var actionHashPayload = "cross-repo-producer-action-hash.v1\x00" &
    selector & "\x00"
  for realized in realizedBinaries:
    actionHashPayload.add(extractFilename(realized))
    actionHashPayload.add('\x00')
    actionHashPayload.add(fileContentDigest(realized))
    actionHashPayload.add('\x00')
  for realizedLib in realizedLibraries:
    actionHashPayload.add("lib:")
    actionHashPayload.add(extractFilename(realizedLib))
    actionHashPayload.add('\x00')
    actionHashPayload.add(fileContentDigest(realizedLib))
    actionHashPayload.add('\x00')
  var runtimeFingerprints: seq[string] = @[]
  for actionIdentity in producerRuntimeIdentity.actionIdentities:
    runtimeFingerprints.add(actionIdentity.packageSelector & "\x00" &
      actionIdentity.executableName & "\x00" &
      digestHex(actionIdentity.actionFingerprint))
  runtimeFingerprints.sort()
  for runtimeFingerprint in runtimeFingerprints:
    actionHashPayload.add("runtime:")
    actionHashPayload.add(runtimeFingerprint)
    actionHashPayload.add('\x00')
  producerActionHashes[selector] =
    digestHex(blake3DomainDigest(actionHashPayload.bytesOf(),
      hdActionFingerprint))

  case binding.kind
  of pbkDevelopOverride:
    producerSourceBindings[selector] = binding.overrideBinding
  of pbkLockPinned:
    producerSourceBindings[selector] =
      lockPinnedSourceBinding(selector, binding.lockedDep)
  of pbkOnDiskSibling, pbkNotProducer:
    discard
  true

# ---------------------------------------------------------------------
# Interface extraction as an ordinary build edge.
#
# ``reprobuild-specs/Compiles-Are-Normal-Edges.md``: every compile reprobuild
# performs — including the ones it performs on its own behalf — is an
# ordinary build-graph edge executed through the engine and subject to
# io-mon monitoring. The recipe interface-extraction compile was the
# exception: ``extractInterfaceFromModule`` spawned ``nim c`` with
# ``startProcess``, so ``monitoredAction`` (which only wraps ``bakProcess``
# actions) never saw it, and its freshness rested on hand-enumerated keys.
#
# The failure mode that produced the rule: ``--define:reproBin`` /
# ``--define:reproConsumerRoot`` were added to that compile, reached the
# command line, and had no effect, because the hand-written key did not
# mention defines. A green build reported success while the dependent
# feature did nothing.
#
# The edge below is shaped exactly like the provider-compile edge
# (``providerCompileBuildAction`` + ``__repro-compile-provider``): a helper
# subcommand does the work in a child process the engine can monitor. The
# whole extraction — the ``nim c`` AND the runner execution that projects
# the interface — is one action, so the outputs it is addressed by are the
# stable artifact/stub paths rather than the per-invocation scratch
# directory the raw compile writes into.
# ---------------------------------------------------------------------

var interfaceEdgeSessionResults: Table[string, ProjectInterfaceArtifact]
  ## Per-PROCESS memo of extraction edges already materialized in this run,
  ## keyed by the edge's own identity (its argv hash).
  ##
  ## This is NOT a freshness cache and deliberately holds no input list: it
  ## only says "this exact edge already ran, in this process, a moment ago".
  ## One ``repro build`` reaches the same extraction several times (graph
  ## inspection, snapshot refresh, the build itself), and re-entering the
  ## engine for each would re-validate the same evidence with nothing able to
  ## have changed in between.

proc extractInterfaceEdge(modulePath, artifactPath, stubPath: string;
                          workDir, scratchDir, consumerRoot, publicCliPath,
                          cacheRoot: string;
                          stats: var BuildStats;
                          requireStub = true;
                          resourceModule = "";
                          extraPaths: openArray[string] = [];
                          bypassRunQuota = false;
                          fallbackToRunQuotaBypass = false;
                          forceRebuild = false;
                          suppressTrace = true;
                          skipCacheHitEvidence = true;
                          statsEnabled = false;
                          cancelCheck: BuildCancelCallback = nil):
    ProjectInterfaceArtifact =
  ## Materialize a project interface through the build engine.
  ##
  ## THE ENGINE ALONE decides whether the edge re-runs. There is deliberately
  ## no hand-written freshness check in front of it any more.
  ##
  ## There used to be one (``cachedInterfaceArtifact``), because io-mon graded
  ## every monitored action that consumed an OS pipe as
  ## ``out-of-tree content channel consumed`` — a Level 2 (unknown-scope)
  ## loss. ``collectEvidence`` set ``disableCacheHits``, the engine skipped
  ## ``recordActionResult``, and the edge had NO cache entry to hit on this or
  ## any later build; without the gate every ``repro build`` paid the full
  ## extraction (~55 s instead of ~1.5 s). The helper captures the compiler's
  ## output through a pipe, so the extraction was always in that class.
  ##
  ## io-mon IM-3/IM-4 (IoMon-Pipeline-Capture.milestones.org) removed the
  ## cause: the shim now records ``pipe``/``pipe2``/``socketpair`` creates, so
  ## a channel created inside the monitored tree pairs with its consume, and
  ## an unpaired consume whose producer is a monitored pid no longer
  ## downgrades. A pipeline that is closed under monitoring is graded
  ## ``mcComplete`` and the edge publishes normally.
  ##
  ## Deleting the gate is not just a tidy-up: it was UNSOUND. It was keyed by
  ## an import walk of the recipe's TEXT bounded to the project root, so a
  ## dependency the recipe acquires during macro expansion — a ``dslDeps``
  ## package's own ``repro.nim``, or anything a ``staticExec`` in a macro
  ## reads — could not appear in it. Editing such a file left the gate warm
  ## and served a stale interface with a green build. The engine's decision
  ## comes from the monitored read set, which does see those files.
  let helperCliPath = internalReproHelperCliPath(publicCliPath)
  if helperCliPath.len == 0 or not cliPathExists(helperCliPath):
    # No engine-executable image to spawn back into. Embedded callers and
    # the bootstrap path land here; they get the pre-existing in-process
    # extraction, which is the same code the helper runs.
    return extractInterfaceFromModule(modulePath, artifactPath, stubPath,
      workDir, scratchDir, requireStub, resourceModule, extraPaths,
      consumerRoot)

  var command = @[
    helperCliPath,
    "__repro-extract-interface",
    "--module", modulePath,
    "--artifact", artifactPath,
    "--stub", stubPath,
    "--work-dir", workDir,
    "--consumer-root", consumerRoot,
    "--require-stub", (if requireStub: "1" else: "0")]
  if scratchDir.len > 0:
    command.add("--scratch-dir")
    command.add(scratchDir)
  if resourceModule.len > 0:
    command.add("--resource-module")
    command.add(resourceModule)
  for extra in extraPaths:
    if extra.len > 0:
      command.add("--extra-path")
      command.add(extra)

  createDir(extendedPath(parentDir(artifactPath)))
  let edgeCwd =
    if scratchDir.len > 0: scratchDir else: parentDir(artifactPath)
  createDir(extendedPath(edgeCwd))
  var inputs = @[modulePath]
  if resourceModule.len > 0 and resourceModule != modulePath:
    inputs.add(resourceModule)
  # The action key must distinguish one consumer's extraction from another's.
  # ``action()``'s default weak fingerprint is derived from the action ID
  # alone, so a fixed ID would give every project in a shared action-cache
  # root the SAME key — one consumer's interface restored into another's
  # build. The fingerprint is taken from the ARGV instead, which already
  # names the module, the artifact, the work dir and the consumer root. That
  # is the property the spec is after: the command line is an input by
  # construction, not a list somebody maintains. Content changes are caught
  # by the engine's recorded-input revalidation on top of it.
  let edgeIdentity = weakFingerprintFromText(command.join("\x00"))
  let sessionKey = toHex(edgeIdentity.bytes)
  if not forceRebuild and interfaceEdgeSessionResults.hasKey(sessionKey) and
      fileExists(extendedPath(artifactPath)):
    return interfaceEdgeSessionResults[sessionKey]
  let actionId = "__repro_interface_extract-" &
    toHex(weakFingerprintFromText(absolutePath(artifactPath)).bytes)[0 .. 15]
  # The extraction's own scratch is NOT an input. It reads back what it just
  # wrote there: the Nim incremental cache (``nimcache-interface``), the
  # generated extract-runner tree under ``m7-temp`` (a fresh random directory
  # every invocation), and the runner binary it links and then executes.
  # Recording those as inputs would make the edge miss its cache on every
  # single build — the random directory does not even exist next time — and
  # would turn a correct warm build into a full recompile. Everything under
  # the scratch root is machine-local derived state; the real inputs are the
  # recipe, the reprobuild libs, the toolchain and the config files, all of
  # which live elsewhere and stay recorded.
  var ignoredInputPrefixes: seq[string] = @[]
  if scratchDir.len > 0:
    ignoredInputPrefixes.add(absolutePath(scratchDir))
  when defined(windows):
    ignoredInputPrefixes.add(
      absolutePath(getTempDir() / "repro-interface-extract"))
  let extractAction = action(actionId, command,
    # Named-Lock-Files §7.2 — see `lockIdentityOutsideSolvedGraph`.
    governingLockIdentity = lockIdentityOutsideSolvedGraph(),
    cwd = edgeCwd,
    inputs = inputs,
    outputs = interfaceExtractionOutputs(artifactPath, stubPath),
    commandStatsId = "repro interface extract edge",
    cacheable = true,
    weakFingerprint = edgeIdentity,
    dependencyPolicy =
      automaticMonitorGatheringPolicy(ignoredInputPrefixes))
  var edgeConfig = BuildEngineConfig(
    cacheRoot: cacheRoot,
    actionCacheRoot: currentActionCacheRoot(),
    runQuotaCliPath: publicCliPath,
    monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
    monitorCliArgs: internalIoMonitorArgs,
    maxParallelism: 1'u32,
    stdoutLimit: 1024 * 1024,
    stderrLimit: 1024 * 1024,
    rebuildMissingOutputsOnCacheHit: true,
    deferLocalOutputBlobs: true,
    bypassRunQuota: bypassRunQuota,
    fallbackToRunQuotaBypass: fallbackToRunQuotaBypass,
    inlineRunQuota: true,
    dryRun: false,
    forceRebuild: forceRebuild,
    suppressTrace: suppressTrace,
    skipCacheHitEvidence: skipCacheHitEvidence,
    cancelCallback: cancelCheck)
  edgeConfig.statsEnabled = statsEnabled
  var artifactLock = acquireInterfaceArtifactLock(artifactPath)
  try:
    let edgeResult = runBuild(graph([extractAction]), edgeConfig)
    stats.mergeStats(edgeResult.stats)
    if edgeResult.hasFailedActions():
      # The child's captured stdout/stderr carries the recipe's own compiler
      # diagnostics (file, line, message). Surfacing them verbatim is the whole
      # reason the extraction can be a monitored child at all: a failed edge
      # must still read like a failed recipe compile.
      var detail = ""
      for item in edgeResult.results:
        if item.status in {asFailed, asBlocked}:
          var parts = @["interface extraction edge " & $item.status &
            " for " & modulePath]
          if item.stderr.len > 0:
            parts.add(item.stderr)
          if item.stdout.len > 0:
            parts.add(item.stdout)
          detail = parts.join("\n")
          break
      if detail.len == 0:
        detail = "interface extraction edge failed for " & modulePath
      raise newException(OSError, detail)
    if not fileExists(extendedPath(artifactPath)):
      raise newException(IOError,
        "interface extraction edge did not write artifact: " & artifactPath)
    result = readInterfaceArtifact(artifactPath)
    interfaceEdgeSessionResults[sessionKey] = result
  finally:
    releaseInterfaceArtifactLock(artifactLock)

proc executeBuildTarget(target: string; mode: ToolProvisioningMode;
                        publicCliPath: string;
                        selectDefaultAction = false;
                        workRoot = "";
                        progressMode = bpmBarLine;
                        progressBarStyle = bpbsOverlay;
                        showSet: MeasureSet = {};
                        measureSet: MeasureSet = DefaultMeasureSet;
                        reportPersistence = BuildReportPersistence();
                        logMode = blmActions;
                        diagnosticsPath = "";
                        prepareOnly = false;
                        dryRun = false;
                        forceRebuild = false;
                        noOutputCleanup = false;
                        publishCacheHits = false;
                        publishMaterialized = false;
                        substituteMaterialized = false;
                        skipCmakeRegeneration = false;
                        bypassRunQuotaExplicit = false;
                        benchmarkPath = "";
                        eventSink: BuildCommandEventSink = nil;
                        cancelCheck: BuildCancelCallback = nil;
                        extraNameSelectors: seq[string] = @[];
                        forwardedActionArgs: seq[string] = @[];
                        peerCacheFetcher: PeerCacheActionFetcher = nil;
                        peerCachePublisher: PeerCacheActionPublisher = nil;
                        peerCacheInstaller: PeerCacheActionBundleInstaller =
                          nil):
    BuildCommandOutcome =
  ## ``extraNameSelectors`` carries the Named-Targets M2 name-shaped
  ## positional arguments AFTER the first positional has been folded
  ## into ``target``. They join the closure union inside
  ## ``lowerProviderSnapshot`` so multi-target ``repro build`` runs in
  ## a single engine pass. Path-shaped positionals stay on the legacy
  ## one-call-per-target path (handled in ``runBuildCommand``).
  # Configure-level aggregation: when REPRO_STATS_DIR is set, each repro
  # build invocation drops a JSON record into that directory. The companion
  # ``scripts/aggregate-stats.py`` script rolls them up into a single
  # per-CMake-configure breakdown. The dir is created lazily on first use.
  # Setting the dir also implicitly opts every spawned repro build into
  # text-mode stat collection so the per-metric breakdown survives — CMake
  # never passes --show= to its child repro build invocations, so the dir
  # is the only handle we have on enabling them.
  let configureStatsDir = getEnv("REPRO_STATS_DIR")
  let statsEnabled = mcTiming in measureSet or configureStatsDir.len > 0 or
    benchmarkPath.len > 0 or statsGroupEnabled(scgTiming)
  var buildStats: BuildStats
  discard consumeInterfaceArtifactWarmStats()
  let buildTotalStart = statStart(statsEnabled)
  let invocationWallStart = epochTime()
  let materializedOnly =
    publishMaterialized or substituteMaterialized
  var progressRenderer = newBuildProgressRenderer(progressMode,
    progressBarStyle)
  progressRenderer.renderPhase("preparing build")
  defer:
    progressRenderer.finishProgress()
  var invocationFastPath = ""
  var benchmarkExecutedActions = 0
  defer:
    if benchmarkPath.len > 0:
      try:
        writeBuildBenchmark(benchmarkPath, result, buildStats,
          if eventSink == nil: "direct" else: "daemon-worker",
          invocationFastPath, benchmarkExecutedActions)
      except CatchableError:
        discard
  var diagnosticLines: seq[string] = @[]
  proc appendDiagnostic(line: string) =
    if diagnosticsPath.len > 0:
      diagnosticLines.add(line)
  proc emitMeasurements(buildResult: BuildRunResult) =
    ## PRESENT axis (CLI/build.md §"Present"). Renders exactly the categories
    ## ``--show`` asked for and nothing else. Independent of what was
    ## collected beyond that (``--show=X`` implies ``--measure=X``, resolved
    ## at parse time) and independent of what was persisted.
    if showSet.card == 0:
      return
    var body = ""
    if mcTiming in showSet:
      body.add(renderBuildStats(buildResult.stats))
    if mcTrace in showSet:
      body.add(renderBuildTrace(buildResult))
    if mcCacheEvidence in showSet:
      body.add(renderBuildCacheEvidence(buildResult))
    if body.len == 0:
      return
    if eventSink != nil:
      eventSink("diagnostic", body, "{}")
    else:
      stderr.write(body)
      stderr.flushFile()
  defer:
    if diagnosticsPath.len > 0:
      try:
        let diagnosticsDir = parentDir(diagnosticsPath)
        if diagnosticsDir.len > 0:
          createDir(extendedPath(diagnosticsDir))
        var body = diagnosticLines.join("\n")
        if body.len > 0:
          body.add("\n")
        writeFile(extendedPath(diagnosticsPath), body)
      except CatchableError:
        discard
  defer:
    if configureStatsDir.len > 0:
      try:
        createDir(extendedPath(configureStatsDir))
        let wallMs = (epochTime() - invocationWallStart) * 1000.0
        let stamp = $getCurrentProcessId() & "-" &
          $int(epochTime() * 1_000_000.0)
        let recordPath = configureStatsDir / (stamp & ".json")
        var node = %*{
          "pid": getCurrentProcessId(),
          "target": target,
          "modulePath": result.modulePath,
          "projectRoot": result.projectRoot,
          "outDir": result.outDir,
          "wallMs": wallMs,
          "exitCode": result.exitCode,
          "mode": $mode,
          "fastPath": invocationFastPath,
        }
        var metrics = newJArray()
        for metric in buildStats.metrics:
          metrics.add(%*{
            "name": metric.name,
            "count": metric.count,
            "totalUs": metric.totalUs,
          })
        node["metrics"] = metrics
        writeFile(extendedPath(recordPath), $node)
      except CatchableError:
        # Telemetry is best-effort — never fail a build because we
        # couldn't write a stats record.
        discard
  var parsedTarget = parseBuildTarget(target)
  parsedTarget.modulePath = absolutePath(parsedTarget.modulePath)
  let modulePath = parsedTarget.modulePath
  if not fileExists(extendedPath(modulePath)):
    # Tier 2a: when the CMake generator emits ``trycompile.rbsz`` as the
    # sole project descriptor, no ``reprobuild.nim`` is written. Accept
    # the target as long as that metadata file is present next to the
    # would-be module — the fast path below recognises it explicitly and
    # never tries to compile a per-project provider.
    let trycompileSiblingMeta = parentDir(modulePath) / "trycompile.rbsz"
    if not fileExists(extendedPath(trycompileSiblingMeta)):
      raise newException(IOError, "build target module not found: " & modulePath)

  let outDir = outputDirForTarget(parsedTarget, workRoot)
  result.modulePath = modulePath
  result.projectRoot = projectRootForModule(modulePath)
  result.outDir = outDir
  # Local copy: the failure-report closure below must not capture ``result``.
  let reportProjectRoot = result.projectRoot
  # When --no-runquota was passed (or the env knob is set), skip the daemon
  # entirely: every action goes through the bypass-spawn path with no lease
  # round-trip. Default is "use runquota when reachable, fall back if not".
  let bypassRunQuota = bypassRunQuotaExplicit
  var fallbackToRunQuotaBypass = mode in {tpmPathOnly, tpmScoop}
  var warnedRunQuotaBypass = false

  template logSummary(line: string) =
    appendDiagnostic(line)
    if eventSink != nil:
      eventSink("diagnostic", line, "{}")
    elif logMode != blmQuiet:
      # Terminate any in-flight progress line on stderr before the stdout
      # echo so captured output (execCmdEx merges stderr+stdout) keeps each
      # diagnostic line on its own physical line. Without this, the
      # progress renderer's `\r`-redrawn phase text on non-ANSI streams
      # accumulates without a newline and gets concatenated with the next
      # `echo` line, breaking helpers like `valueAfter` that look for a
      # line that `startsWith(prefix)`.
      progressRenderer.finishProgress()
      echo line

  template logAction(line: string) =
    appendDiagnostic(line)
    if eventSink != nil and logMode == blmActions:
      eventSink("diagnostic", line, "{}")
    elif logMode == blmActions:
      progressRenderer.finishProgress()
      echo line

  proc persistFailureReport(buildResult: BuildRunResult;
                            actions: openArray[BuildAction]) =
    ## PERSIST axis, outcome-dependent default (CLI/README.md §"Reports on
    ## failure are written by default"). A failed build leaves its post-mortem
    ## behind without being asked; ``--no-write-report`` is the only way to
    ## suppress it.
    if reportPersistence.suppressed:
      return
    let path = outDir / "build-failure-report.json"
    try:
      writeBuildFailureReport(path, buildResult, actions,
        target, reportProjectRoot, outDir, 1)
      logSummary("buildFailureReport: " & path)
    except CatchableError:
      discard

  proc usesRunQuotaBypass(runResult: BuildRunResult): bool =
    for item in runResult.results:
      if item.launched and item.runQuotaBackend == "runquota-bypass":
        return true

  var loggedRunQuotaAuthority = false
  proc logRunQuotaAuthority(runResult: BuildRunResult) =
    # RA-13: surface the resource-authority status in the build header. When
    # this build launched at least one action with no RunQuota lease (explicit
    # --runquota=off / REPROBUILD_NO_RUNQUOTA, or the unreachable-daemon
    # fallback), say so plainly: limits are locally-enforced-only and cannot
    # make concurrent cross-invocation runs safe. Emit once per build command.
    if loggedRunQuotaAuthority:
      return
    loggedRunQuotaAuthority = true
    logSummary(runQuotaAuthorityHeaderLine(runResult.runQuotaBypassed))
    # STAGE 2: report the undeclared-environment population beside the
    # resource-authority line, for the same reason — a state the build
    # is in that nobody can see is a state nobody can decide about.
    logSummary(environmentInheritanceHeaderLine(
      runResult.environmentInheritance))

  proc warnRunQuotaBypassIfUsed(runResult: BuildRunResult) =
    if warnedRunQuotaBypass or not fallbackToRunQuotaBypass:
      return
    if not usesRunQuotaBypass(runResult):
      return
    warnedRunQuotaBypass = true
    logSummary("repro build: WARNING runquotad is not reachable; using " &
      "RunQuota bypass for tool-provisioning=" & mode.modeName &
      " (no quotas/leases enforced). Start `runquotad` and rerun to " &
      "use the real lease coordinator.")

  # M9.N Batch B: late-bound holder for the tool-identity resolver
  # closure. The closure is built once the build identity is resolved
  # (further below) and attached to the engine config inside
  # ``runLoweredGraphBuild``. On the early cache-warm fast path the
  # holder is still ``nil`` — the engine then doesn't prepend any
  # catalog bin dirs to PATH, and bare-name argv entries fall through
  # to the host's existing PATH (the legacy pre-Batch-B behaviour).
  var pendingToolIdentityResolver: ToolIdentityResolver = nil
  var effectiveSelectDefaultAction = selectDefaultAction
  let ownsFromSourceDryRunPlan =
    dryRun and mode == tpmFromSource and fromSourceBuildStack.len == 0
  if ownsFromSourceDryRunPlan:
    fromSourceDryRunPlannedRecipes.clear()
  defer:
    if ownsFromSourceDryRunPlan:
      fromSourceDryRunPlannedRecipes.clear()

  # Input evidence harvested off every engine run this call makes, so
  # ``repro watch`` can arm its watcher without depending on whether the
  # operator asked for a persisted report. Accumulated here rather than
  # assigned to ``result`` directly because ``runLoweredGraphBuild``
  # below is a nested proc whose own ``result`` is an ``int``.
  var collectedInputEvidence: seq[string] = @[]

  proc appendForwardedArgs(actions: var seq[BuildAction];
                           selectedActionId: string) =
    if forwardedActionArgs.len == 0:
      return
    if selectedActionId.len == 0:
      raise newException(ValueError,
        "forwarded action arguments require one selected build action")
    for action in actions.mitems:
      if action.id == selectedActionId:
        if action.kind != bakProcess:
          raise newException(ValueError,
            "forwarded action arguments require a process target: " &
              selectedActionId)
        action.argv.add(forwardedActionArgs)
        return
    raise newException(ValueError,
      "selected action does not accept forwarded arguments: " &
        selectedActionId)

  proc collectInputEvidence(buildResult: BuildRunResult) =
    for item in buildResult.results:
      for group in [item.evidence.declaredInputs, item.evidence.depfileInputs,
          item.evidence.monitorReads, item.evidence.monitorProbes]:
        for path in group:
          collectedInputEvidence.add(path)

  proc runLoweredGraphBuild(lowered: tuple[actions: seq[BuildAction];
                                          pools: seq[BuildPool]];
                            selectedActionId: string): int =
    if parsedTarget.fragmentKind == tfkActionSelection:
      logSummary("selectedTarget: " & parsedTarget.selectedActionId)
    elif effectiveSelectDefaultAction and selectedActionId.len > 0:
      logSummary("selectedTarget: " & selectedActionId)
    logSummary("scheduler: actions=" & $lowered.actions.len)
    if lowered.actions.len == 0:
      return 0
    var engineConfig = BuildEngineConfig(
      cacheRoot: outDir / "build-engine-cache",
      actionCacheRoot: currentActionCacheRoot(),
      runQuotaCliPath: publicCliPath,
      monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
      monitorCliArgs: internalIoMonitorArgs,
      maxParallelism: buildMaxParallelism(),
      stdoutLimit: 1024 * 1024,
      stderrLimit: 1024 * 1024,
      rebuildMissingOutputsOnCacheHit: true,
      # Peer-Cache M1 (LDRV M5): retain output blobs in the local CAS
      # when a peer-cache publisher closure is attached so the
      # publisher can read them back; otherwise honour the legacy
      # ``deferLocalOutputBlobs = true`` default.
      deferLocalOutputBlobs: peerCachePublisher == nil,
      bypassRunQuota: bypassRunQuota,
      fallbackToRunQuotaBypass: fallbackToRunQuotaBypass,
      inlineRunQuota: true,
      dryRun: dryRun,
      forceRebuild: forceRebuild,
      publishCachedResults: publishCacheHits,
      suppressTrace: mcTrace notin measureSet,
      skipCacheHitEvidence: mcCacheEvidence notin measureSet,
      cancelCallback: cancelCheck,
      peerCacheActionFetcher: peerCacheFetcher,
      peerCacheActionPublisher: peerCachePublisher,
      peerCacheActionInstaller: peerCacheInstaller)
    # M9.L.4-refactor Step C: wire the binary-cache publisher closure
    # into the production engine config. The closure is inert when
    # ``REPRO_CACHE_DISABLE=1`` (silent) or when the key/cert env vars
    # are unset (soft-fail with structured warning); otherwise it
    # forwards each engine ``BinaryCachePublishRequest`` to
    # ``publishInProcess``. The engine only fires the closure for
    # actions that carry ``publishToBinaryCache = true`` AND a
    # populated ``cacheEntryIdentity`` — the from-source conventions
    # tag install + stage-copy actions accordingly.
    engineConfig.binaryCachePublisher = mkBinaryCachePublisher()
    # L3 PUBLISH-SCOPE: resolve the target cache's scope. An INTERMEDIATE
    # cache publishes every built store output; a RELEASE cache (default)
    # only the public-interface members tagged ``publishToBinaryCache``.
    engineConfig.binaryCacheIntermediateScope =
      bcCachesConfig.publishTargetScope() == bcCachesConfig.csIntermediate
    # M9.N Batch B: attach the tool-identity resolver closure once
    # the outer scope has resolved the build identity. ``nil`` is
    # the legitimate fast-path-no-identity value — the engine then
    # leaves PATH alone for actions that carry refs.
    engineConfig.toolIdentityResolver = pendingToolIdentityResolver
    engineConfig.statsEnabled = statsEnabled
    if eventSink != nil:
      engineConfig.progressCallback = proc(event: BuildProgressEvent) =
        enqueueStatsObservation(scgSessions, "progress", %*{
          "kind": $event.kind,
          "actionId": event.actionId,
          "status": $event.status,
          "cacheDecision": $event.cacheDecision,
          "total": event.total,
          "completed": event.completed,
          "running": event.running,
          "ready": event.ready
        })
        eventSink("diagnostic", "progress: " & $event.kind & " " &
          event.actionId, $(%*{
            "event": "progress",
            "kind": $event.kind,
            "actionId": event.actionId,
            "command": event.command,
            "currentCommand": event.currentCommand,
            "status": $event.status,
            "cacheDecision": $event.cacheDecision,
            "total": event.total,
            "completed": event.completed,
            "checked": event.checked,
            "running": event.running,
            "ready": event.ready
          }))
    elif progressRenderer.enabled:
      engineConfig.progressCallback = proc(event: BuildProgressEvent) =
        enqueueStatsObservation(scgSessions, "progress", %*{
          "kind": $event.kind,
          "actionId": event.actionId,
          "status": $event.status,
          "cacheDecision": $event.cacheDecision,
          "total": event.total,
          "completed": event.completed,
          "running": event.running,
          "ready": event.ready
        })
        progressRenderer.renderProgress(event)
    var buildResult: BuildRunResult
    let engineStart = statStart(statsEnabled)
    # Cross-Repo-Source-Consumption SC-2/SC-3 (§4.2 points 3-4): attach each
    # materialized LIBRARY-channel producer as a tool ref on the consumer
    # actions (SC-3, so the engine threads its realized library dirs onto the
    # aux channels), then fold each materialized producer's action-hash into
    # the consumer actions that name it, so the producer edge is a real input
    # of the consumer cache key. Both are no-ops when nothing was materialized
    # (byte-identical to today).
    var scheduledActions = lowered.actions
    appendForwardedArgs(scheduledActions, selectedActionId)
    attachProducerAuxRefs(scheduledActions)
    foldProducerActionHashes(scheduledActions)
    # Cross-Repo-Source-Consumption SC-4 (§4.3): fold each materialized
    # producer's SOURCE identity (develop ``contentIdentity`` / lock-pinned
    # ``revision``+``integrity``) into the consumer actions that name it, so a
    # producer SOURCE change rebuilds the consumer. No-op when nothing was
    # materialized (byte-identical to today).
    foldProducerSourceIdentities(scheduledActions)
    try:
      progressRenderer.renderPhase("checking graph actions=" &
        $scheduledActions.len)
      let scheduledGraph = graph(scheduledActions, lowered.pools)
      if substituteMaterialized:
        buildResult = substituteMaterializedBinaryCacheEntries(scheduledGraph)
      elif publishMaterialized:
        buildResult = publishMaterializedBinaryCacheEntries(
          scheduledGraph, engineConfig.binaryCachePublisher)
      else:
        buildResult = runBuild(scheduledGraph, engineConfig)
    except CatchableError:
      progressRenderer.finishProgress()
      raise
    finishStat(buildStats, statsEnabled, "repro engine runBuild", engineStart)
    buildStats.mergeStats(buildResult.stats)
    benchmarkExecutedActions = 0
    for item in buildResult.results:
      if item.launched:
        inc benchmarkExecutedActions
    warnRunQuotaBypassIfUsed(buildResult)
    logRunQuotaAuthority(buildResult)
    finishStat(buildStats, statsEnabled, "repro build total", buildTotalStart)
    buildResult.stats = buildStats
    let actionLogStart = statStart(statsEnabled)
    for item in buildResult.results:
      logAction("action: " & item.id & " status=" & $item.status &
        " launched=" & $item.launched & " cache=" & $item.cacheDecision &
        " wouldLaunch=" & $item.wouldLaunch &
        (if item.reason.len > 0: " reason=" & item.reason else: "") &
        " runquota=" & item.runQuotaBackend &
        " socket=" & (if item.runQuotaSocket.len >
            0: item.runQuotaSocket else: "default") &
        " lease=" & $item.leaseId &
        " evidence=depfile:" & $item.evidence.depfileInputs.len)
    finishStat(buildStats, statsEnabled, "repro action log render",
      actionLogStart)
    buildResult.stats = buildStats
    collectInputEvidence(buildResult)
    recordStatsForBuildRun(buildResult)
    if buildResult.hasFailedActions():
      emitFailedActionSummaries(buildResult, eventSink, progressRenderer)
      persistFailureReport(buildResult, lowered.actions)
    let statsRenderStart = statStart(statsEnabled)
    emitMeasurements(buildResult)
    finishStat(buildStats, statsEnabled, "repro stats render", statsRenderStart)
    if buildResult.hasFailedActions():
      1
    else:
      0

  var cmakeRegenerationResult: BuildRunResult
  let cmakeMeta = cmakeRegenerationMetadataForModule(modulePath)
  cmakeMeta.applyCmakeProviderEnvironment()
  if cmakeMeta.enabled and parsedTarget.selectedActionId.len == 0 and
      extraNameSelectors.len == 0:
    effectiveSelectDefaultAction = true
  var cmakeRegenerated = false
  if cmakeMeta.enabled and not skipCmakeRegeneration:
    logSummary("cmakeRegeneration: started")
    progressRenderer.renderPhase("cmake regeneration")
    let cmakeRegenerationStart = statStart(statsEnabled)
    let cmakeRegenerationAction =
      cmakeRegenerationBuildAction(cmakeMeta, publicCliPath)
    let cmakeCacheRoot = outDir / "cmake-regeneration-cache"
    var cmakeFastHit = false
    if mcCacheEvidence notin measureSet and not forceRebuild:
      # The CMake regeneration action's cache lives under the shared
      # user-level action cache root, matching the runBuild() path below
      # (Provider-Compile-Tiering.md §"Cache Scope" Phase 1).
      let sharedRoot = currentActionCacheRoot()
      var cmakeCache = openActionCache(sharedRoot / "action-cache")
      defer:
        cmakeCache.flushHotIndex()
      let outputStatStart = statStart(statsEnabled)
      let outputsPresent = cmakeRegenerationAction.actionOutputsPresent()
      finishStat(buildStats, statsEnabled, "repro output stat", outputStatStart)
      if outputsPresent:
        let lookupStart = statStart(statsEnabled)
        let hot = cmakeCache.lookupHotMetadataRecord(
          cmakeRegenerationAction.weakFingerprint,
          cmakeRegenerationAction.actionCachePolicy)
        if hot.isSome:
          let selectedInputsUnchanged =
            hotMetadataRecordInputsUnchanged(@[hot.get()])
          if selectedInputsUnchanged:
            cmakeFastHit = true
            cmakeRegenerationResult.results.add(ActionResult(
              id: cmakeRegenerationAction.id,
              status: asCacheHit,
              launched: false,
              cacheDecision: cdHit,
              dependencyPolicyKind: cmakeRegenerationAction.dependencyPolicy.kind))
        finishStat(buildStats, statsEnabled, "repro cache lookup", lookupStart)
    if not cmakeFastHit:
      let stateStart = statStart(statsEnabled)
      let stateFresh = cmakeGeneratedStateFresh(cmakeMeta, publicCliPath)
      finishStat(buildStats, statsEnabled, "repro cmake state check",
        stateStart)
      if stateFresh and not forceRebuild:
        discard seedCmakeRegenerationCache(cmakeMeta, publicCliPath, outDir)
        cmakeFastHit = true
        cmakeRegenerationResult.results.add(ActionResult(
          id: cmakeRegenerationAction.id,
          status: asCacheHit,
          launched: false,
          cacheDecision: cdHit,
          dependencyPolicyKind: cmakeRegenerationAction.dependencyPolicy.kind))
    if not cmakeFastHit:
      var cmakeRegenerationConfig = BuildEngineConfig(
        cacheRoot: cmakeCacheRoot,
        actionCacheRoot: currentActionCacheRoot(),
        runQuotaCliPath: publicCliPath,
        monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
        monitorCliArgs: internalIoMonitorArgs,
        maxParallelism: 1'u32,
        stdoutLimit: 1024 * 1024,
        stderrLimit: 1024 * 1024,
        rebuildMissingOutputsOnCacheHit: true,
        deferLocalOutputBlobs: true,
        bypassRunQuota: bypassRunQuota,
        fallbackToRunQuotaBypass: fallbackToRunQuotaBypass,
        inlineRunQuota: true,
        dryRun: false,
        forceRebuild: forceRebuild,
        suppressTrace: mcTrace notin measureSet,
        skipCacheHitEvidence: mcCacheEvidence notin measureSet,
        cancelCallback: cancelCheck)
      cmakeRegenerationConfig.statsEnabled = statsEnabled
      cmakeRegenerationResult = runBuild(graph([cmakeRegenerationAction]),
        cmakeRegenerationConfig)
      buildStats.mergeStats(cmakeRegenerationResult.stats)
    finishStat(buildStats, statsEnabled, "repro cmake regeneration",
      cmakeRegenerationStart)
    warnRunQuotaBypassIfUsed(cmakeRegenerationResult)
    for item in cmakeRegenerationResult.results:
      logAction("cmakeRegenerationAction: " & item.id & " status=" &
        $item.status & " launched=" & $item.launched & " cache=" &
        $item.cacheDecision & " wouldLaunch=" & $item.wouldLaunch &
        (if item.reason.len > 0: " reason=" & item.reason else: ""))
      if eventSink != nil and logMode != blmQuiet and item.stdout.len > 0:
        eventSink("diagnostic", item.stdout, "{\"stream\":\"stdout\"}")
      elif logMode != blmQuiet and item.stdout.len > 0:
        stdout.write(item.stdout)
        stdout.flushFile()
      if eventSink != nil and logMode != blmQuiet and item.stderr.len > 0:
        eventSink("diagnostic", item.stderr, "{\"stream\":\"stderr\"}")
      elif logMode != blmQuiet and item.stderr.len > 0:
        stderr.write(item.stderr)
        stderr.flushFile()
    if cmakeRegenerationResult.hasFailedActions():
      raise newException(OSError,
        "CMake regeneration edge failed: " &
          providerCompileFailure(cmakeRegenerationResult))
    for item in cmakeRegenerationResult.results:
      if item.launched and item.status == asSucceeded:
        cmakeRegenerated = true

  let pathEnv = getEnv("PATH")
  let cacheSelectedActionId =
    if parsedTarget.selectedActionId.len > 0:
      parsedTarget.selectedActionId
    elif effectiveSelectDefaultAction and logMode == blmQuiet:
      ""
    else:
      "\0"
  if cmakeMeta.enabled and not cmakeRegenerated and not prepareOnly and
      mode == tpmPathOnly and not reportPersistence.requested and
      cacheSelectedActionId != "\0":
    let loweredCacheStart = statStart(statsEnabled)
    progressRenderer.renderPhase("reading lowered graph cache")
    let loweredCache = warmReadFreshLoweredGraphCache(
      loweredGraphCachePath(outDir, cacheSelectedActionId), modulePath,
      result.projectRoot, cacheSelectedActionId, pathEnv, "cmake-pre-provider")
    finishStat(buildStats, statsEnabled, "repro lowered graph cache read",
      loweredCacheStart)
    if loweredCache.isSome:
      logSummary("loweredGraphCache: hit")
      result.exitCode = runLoweredGraphBuild(loweredCache.get(),
        cacheSelectedActionId)
      result.inputEvidencePaths = collectedInputEvidence
      return

  # Tier 2a fast path: stereotyped CMake try_compile() projects ship a
  # ``trycompile.rbsz`` metadata file emitted by the Reprobuild generator
  # and skip the per-project provider compile entirely. The engine
  # dispatches the pre-built ``repro-cmake-trycompile-provider`` binary
  # which parses the metadata, registers the synthesized actions via the
  # standard DSL primitives, and emits the build graph. The provider
  # artifact id is a constant per ``repro`` release so every TryCompile
  # against the same toolchain shares a cache key.
  # Per Provider-Compile-Tiering.md §"2a — repro-cmake-trycompile-provider".
  let tryCompileMetaPath = result.projectRoot / "trycompile.rbsz"
  let tryCompileProviderBinary = siblingTryCompileProviderPath(publicCliPath)
  if mode == tpmPathOnly and
      fileExists(extendedPath(tryCompileMetaPath)) and
      tryCompileProviderBinary.len > 0:
    invocationFastPath =
      if prepareOnly: "tier2c-direct-prepare"
      else: "tier2a-trycompile-direct"
    logSummary("trycompileDirect: dispatching " & tryCompileProviderBinary)
    logSummary("project: " & TryCompileProviderPackageName)
    logSummary("interface: " & tryCompileMetaPath)
    logSummary("providerBinary: " & tryCompileProviderBinary)
    logSummary("providerArtifact: " & TryCompileProviderArtifactId)
    logSummary("runQuotaSocket: " & runQuotaSocketDiagnostic())
    let synthIdentity = PathOnlyBuildIdentity(
      projectName: TryCompileProviderPackageName,
      interfaceFingerprint: blake3DomainDigest(
        toBytes(TryCompileProviderArtifactId), hdActionFingerprint))
    let providerGraphStart = statStart(statsEnabled)
    progressRenderer.renderPhase("refreshing trycompile provider graph")
    let refresh = refreshProviderGraph(RefreshConfig(
      storeRoot: providerGraphStoreRoot(outDir / "provider-graph"),
      providerBinaryPath: tryCompileProviderBinary,
      providerArtifactId: TryCompileProviderArtifactId,
      rootEntryPointId: TryCompileProviderRootEntryPointId,
      rootArguments: result.projectRoot,
      namespace: TryCompileProviderNamespace,
      lockSliceId: digestHex(synthIdentity.interfaceFingerprint),
      activity: "build",
      providerWorkingDir: result.projectRoot))
    finishStat(buildStats, statsEnabled, "repro provider graph refresh",
      providerGraphStart)
    logSummary("providerGraphSnapshot: " & refresh.persistedSnapshotPath)
    logSummary("providerInvocations: " & $refresh.invoked.len)
    var selectedActionId = parsedTarget.selectedActionId
    if effectiveSelectDefaultAction and selectedActionId.len == 0:
      selectedActionId = defaultBuildActionId(refresh.snapshot)
      if selectedActionId.len > 0:
        logSummary("defaultTarget: " & selectedActionId)
    let graphLowerStart = statStart(statsEnabled)
    progressRenderer.renderPhase("lowering trycompile graph")
    # Named-Targets M2: union the first selector (action id or default)
    # with any extra name-shaped positional selectors so the closure
    # is computed once.
    var selectorList: seq[string] = @[]
    if selectedActionId.len > 0:
      selectorList.add(selectedActionId)
    for extra in extraNameSelectors:
      if extra.len > 0 and selectorList.find(extra) < 0:
        selectorList.add(extra)
    let lowered =
      if selectorList.len == 0:
        lowerProviderSnapshot(refresh.snapshot, synthIdentity,
          result.projectRoot, "")
      else:
        lowerProviderSnapshot(refresh.snapshot, synthIdentity,
          result.projectRoot, selectorList)
    finishStat(buildStats, statsEnabled, "repro graph lower", graphLowerStart)
    if prepareOnly:
      # PrimeProviderMetadata's prepare-only invocation used to compile
      # the per-project provider so subsequent TryCompile probes wouldn't
      # have to. With the direct provider that prep is unnecessary, but
      # the cmake-regeneration state-file snapshot still needs to be
      # written so cmake's regeneration check works on the next configure.
      if cmakeMeta.enabled and not skipCmakeRegeneration and
          fileExists(extendedPath(modulePath)):
        createDir(extendedPath(parentDir(cmakeMeta.providerStateFile)))
        writeFile(extendedPath(cmakeMeta.providerStateFile),
          readFile(extendedPath(modulePath)))
        let seedStart = statStart(statsEnabled)
        discard seedCmakeRegenerationCache(cmakeMeta, publicCliPath, outDir)
        finishStat(buildStats, statsEnabled,
          "repro cmake regeneration cache seed", seedStart)
      result.exitCode = 0
      return
    result.exitCode = runLoweredGraphBuild(lowered, selectedActionId)
    result.inputEvidencePaths = collectedInputEvidence
    return

  let interfacePath = outDir / "project-interface.rbsz"
  let stubPath = outDir / "project-interface.nim"
  let compileWorkDir = reprobuildLibraryWorkDir()
  let compileScratchDir = outDir / "provider-work"
  let interfaceStart = statStart(statsEnabled)
  progressRenderer.renderPhase("loading project interface")
  # MR5 — ensure a reprobuild-provisioned nim+gcc is on $REPRO_NIM_COMPILER /
  # $CC for the interface-extract step. See `ensureBootstrapToolchainEnv`
  # for the rationale. Bootstrap toolchain is cached in the per-user
  # tool-store (shared across projects), not the per-build outDir.
  ensureBootstrapToolchainEnv(mode, resolveStoreRoot() / "tool-store")
  let artifact = extractInterfaceEdge(modulePath, interfacePath, stubPath,
    compileWorkDir, compileScratchDir, result.projectRoot, publicCliPath,
    outDir / "build-engine-cache", buildStats,
    requireStub = false,
    bypassRunQuota = bypassRunQuota,
    fallbackToRunQuotaBypass = fallbackToRunQuotaBypass,
    forceRebuild = forceRebuild,
    suppressTrace = mcTrace notin measureSet,
    skipCacheHitEvidence = mcCacheEvidence notin measureSet,
    statsEnabled = statsEnabled,
    cancelCheck = cancelCheck)
  finishStat(buildStats, statsEnabled, "repro interface extract",
    interfaceStart)
  recordInterfaceArtifactWarmStats(buildStats, statsEnabled)

  var effectiveMode = mode
  if effectiveMode == tpmUnspecified and
      artifact.projectInterface.defaultToolProvisioning.len > 0:
    effectiveMode = parseToolProvisioning(
      artifact.projectInterface.defaultToolProvisioning)
    fallbackToRunQuotaBypass = effectiveMode in {tpmPathOnly, tpmScoop}

  var buildArtifact = artifact
  var focusedSnapshotInvocations = 0
  if not materializedOnly and artifact.projectInterface.toolUses.len > 0 and
      shouldEnterBuildPipeline(effectiveMode) and
      moduleHasBuildBlock(modulePath):
    let focusedRefresh = refreshRecipeProviderSnapshot(target, effectiveMode,
      publicCliPath, workRoot, bypassRunQuotaExplicit)
    if focusedRefresh.snapshot.isSome:
      focusedSnapshotInvocations = focusedRefresh.providerInvocations
      let snapshot = focusedRefresh.snapshot.get()
      var selectors: seq[string] = @[]
      var selectedActionId = parsedTarget.selectedActionId
      if effectiveSelectDefaultAction and selectedActionId.len == 0:
        selectedActionId = defaultBuildActionId(snapshot)
      if selectedActionId.len > 0:
        selectors.add(selectedActionId)
      for selector in extraNameSelectors:
        if selector.len > 0 and selectors.find(selector) < 0:
          selectors.add(selector)
      buildArtifact = scopedToolArtifact(artifact, snapshot,
        result.projectRoot, selectors)
      logSummary("selected tool identities: " &
        $buildArtifact.projectInterface.toolUses.len & "/" &
        $artifact.projectInterface.toolUses.len)

  if not materializedOnly and
      buildArtifact.projectInterface.toolUses.len > 0 and
      effectiveMode == tpmUnspecified:
    raise newException(ValueError,
      "typed tool provisioning is required for uses declarations; refusing " &
        "implicit PATH fallback. Pass --tool-provisioning=path to use the " &
        "explicit weak local profile.")

  # DSL-port M9.R.9 — auto-recurse pass for from-source provisioning.
  # When the active mode is ``tpmFromSource`` we probe every tool use
  # against the sibling-recipe layout BEFORE the identity resolver runs.
  # Any ``rrNeedsBuild`` outcome (sibling recipe present but artefact
  # missing) triggers a recursive ``executeBuildTarget`` call for the
  # sibling, threaded through the same provider-compile + lowered-graph
  # + engine pipeline (NOT a ``repro build`` subprocess). After every
  # sibling resolves the outer build proceeds with the resolver pass,
  # which now finds the artefacts on disk.
  #
  # Guards (in order of consultation):
  #   1. ``fromSourceResolvedRecipes`` — per-process dedup, so a single
  #      sibling shared across many tool uses is built once.
  #   2. ``fromSourceBuildStack`` — cycle detection: pushing a recipe
  #      dir that's already on the stack raises with the full cycle
  #      path so the operator can edit one of the recipes' uses lists.
  #   3. ``FromSourceMaxRecursionDepth`` — sanity ceiling. Production
  #      recipe chains stay below 10; the ceiling exists to crash
  #      cleanly on a runaway pattern rather than blow the stack.
  if effectiveMode == tpmFromSource and not materializedOnly:
    # M9.R.14c.2 — proactively seed the bootstrap tool chain so the
    # auto-recurse loop short-circuits gcc / make / binutils (and
    # binutils sub-binaries: ld, ar, ranlib, strip, nm, objdump,
    # objcopy, as, readelf, size, strings) to stdlib provisioning from
    # the first probe pass on. Without this seed the reactive cycle
    # break (M9.R.10a) only fires on the closing edge of an observed
    # recursion cycle: e.g. ``gcc → binutils → gcc`` adds ``gcc`` but
    # leaves ``binutils`` to recurse into a 15-minute from-source
    # build. The bootstrap layer is treated as a stdlib-provisioned
    # floor; the upper layers (autoconf / automake / expat / libffi /
    # etc.) still build from source.
    seedBootstrapCycleBreakTools()
    for useDef in buildArtifact.projectInterface.toolUses:
      # A completed source mirror remains authoritative even for a
      # bootstrap tool. The cycle-break set only suppresses recursive
      # construction when that mirror is absent; this lets later
      # consumers use bootstrap tools that an earlier build completed.
      let outcome = tryResolveFromSourceTool(useDef)
      if outcome.kind == rrResolved:
        continue
      # M9.R.14c.2 — if the unresolved tool is in the cycle-break set
      # (either seeded as part of the bootstrap floor OR added
      # reactively by an earlier closing-edge cycle), skip auto-recurse.
      # The downstream resolver routes it through stdlib provisioning.
      if useDef.executableName.len > 0 and
          useDef.executableName in fromSourceCycleBrokenTools:
        continue
      if outcome.kind != rrNeedsBuild:
        continue
      let siblingRecipeDir = absolutePath(outcome.recipeDir)
      if siblingRecipeDir in fromSourceResolvedRecipes:
        continue
      if siblingRecipeDir in fromSourceBuildStack:
        # DSL-port M9.R.10a — cycle break via stdlib fall-through.
        # Instead of raising the cycle diagnostic, mark the closing-edge
        # tool in ``fromSourceCycleBrokenTools`` so the downstream
        # ``toolProfileFor(tpmFromSource, ...)`` resolves it via stdlib
        # provisioning (nix / scoop / tarball) rather than recursing
        # again into the sibling recipe. The probe inside
        # ``toolProfileFor`` confirms the stdlib has a usable channel —
        # if it does not, the resolver raises with a tighter diagnostic
        # that points the operator at the stdlib package definition.
        # This unblocks bootstrap tool chains (gcc ↔ binutils ↔ make)
        # without sacrificing from-source semantics for the rest of the
        # build graph: every tool that doesn't close a cycle continues
        # to build from source recursively.
        var cycle = fromSourceBuildStack
        cycle.add(siblingRecipeDir)
        logSummary("from-source cycle break: routing \"" & outcome.toolName &
          "\" through stdlib provisioning to break cycle " &
          cycle.join(" -> "))
        fromSourceCycleBrokenTools.incl(outcome.toolName)
        # Mark the recipe as "already resolved" so the caller doesn't
        # try to recurse again on the next probe pass — the closing-edge
        # tool resolves via stdlib from here on.
        fromSourceResolvedRecipes.incl(siblingRecipeDir)
        continue
      if fromSourceBuildStack.len >= FromSourceMaxRecursionDepth:
        raise newException(ValueError,
          "tool-resolution failed: from-source recursion depth bound " &
          "exceeded (" & $FromSourceMaxRecursionDepth & ") while resolving \"" &
          outcome.toolName & "\" at " & siblingRecipeDir &
          ". Active stack: " & fromSourceBuildStack.join(" -> ") &
          ". This is a sanity ceiling — production recipe chains should " &
          "stay well below it; investigate the call chain for an " &
          "accidental fan-out.")
      let siblingManifest = siblingRecipeDir / "repro.nim"
      if materializedSubstitutionConfigured() and
          not prepareOnly and not dryRun and not forceRebuild:
        let substituteOutcome = executeBuildTarget(
          siblingManifest, effectiveMode, publicCliPath,
          selectDefaultAction = true,
          workRoot = workRoot,
          progressMode = bpmQuiet,
          progressBarStyle = progressBarStyle,
          showSet = {},
          measureSet = {},
          reportPersistence = BuildReportPersistence(suppressed: true),
          logMode = blmSummary,
          diagnosticsPath = "",
          prepareOnly = false,
          dryRun = false,
          forceRebuild = false,
          noOutputCleanup = true,
          publishCacheHits = false,
          publishMaterialized = false,
          substituteMaterialized = true,
          skipCmakeRegeneration = skipCmakeRegeneration,
          bypassRunQuotaExplicit = bypassRunQuotaExplicit,
          eventSink = eventSink,
          cancelCheck = cancelCheck)
        if substituteOutcome.exitCode == 0:
          logSummary("from-source cache substitute: restored \"" &
            outcome.toolName & "\" at " & siblingRecipeDir)
          fromSourceResolvedRecipes.incl(siblingRecipeDir)
          continue
      logSummary("from-source auto-recurse: building \"" & outcome.toolName &
        "\" at " & siblingRecipeDir)
      fromSourceBuildStack.add(siblingRecipeDir)
      try:
        let siblingOutcome = executeBuildTarget(siblingManifest, effectiveMode,
          publicCliPath,
          selectDefaultAction = true,
          workRoot = workRoot,
          progressMode = progressMode,
          progressBarStyle = progressBarStyle,
          showSet = showSet,
          measureSet = measureSet,
          reportPersistence = reportPersistence,
          logMode = logMode,
          diagnosticsPath = "",
          prepareOnly = prepareOnly,
          dryRun = dryRun,
          forceRebuild = forceRebuild,
          publishCacheHits = publishCacheHits,
          publishMaterialized = publishMaterialized,
          substituteMaterialized = substituteMaterialized,
          skipCmakeRegeneration = skipCmakeRegeneration,
          bypassRunQuotaExplicit = bypassRunQuotaExplicit,
          eventSink = eventSink,
          cancelCheck = cancelCheck)
        if siblingOutcome.exitCode != 0:
          raise newException(OSError,
            "tool-resolution failed: from-source auto-recurse sub-build of " &
            siblingRecipeDir & " (tool \"" & outcome.toolName &
            "\") exited with status " & $siblingOutcome.exitCode &
            ". See the sub-build's diagnostics for the underlying failure.")
        if dryRun:
          fromSourceDryRunPlannedRecipes.incl(siblingRecipeDir)
      finally:
        if fromSourceBuildStack.len > 0 and
            fromSourceBuildStack[^1] == siblingRecipeDir:
          discard fromSourceBuildStack.pop()
      fromSourceResolvedRecipes.incl(siblingRecipeDir)

  # Cross-Repo-Source-Consumption SC-2 (§4.2) — producer graph load + splice
  # (executable channel). A pre-pass that mirrors the from-source auto-recurse
  # above, but keyed on the SC-1 "resolve package binding" hook instead of the
  # corpus-recipe layout: for every ``uses:`` selector that resolves to a
  # cross-repo PRODUCER (a develop-overridden sibling checkout, or a lock-
  # pinned dependency), LOAD the producer's ``repro.nim``, BUILD
  # its declared ``executable``'s producing edge from source (recursively, via
  # the SAME in-process ``executeBuildTarget`` the from-source pass uses — NOT
  # a ``repro build`` subprocess), and RECORD the producer's output ``bin`` dir
  # in ``producerMaterializedBinDirs`` so the ``mkToolIdentityResolver`` closure
  # splices it onto the consuming action's ``PATH``
  # (``repro_build_engine.nim:1975-2010``). The producer edge runs FIRST (this
  # pre-pass completes before the consumer's engine pass), so its realized
  # output is available as the consumer action starts.
  #
  # The declared-executable edge is bound by declared-output BASENAME (§4.2
  # point 2): the producer's ``executable <name>: name: "<bin>"`` maps to
  # ``build/bin/<bin>`` under the producer root (the canonical output layout
  # every DSL ``nim.c(binary = "build/bin/<bin>")`` / shell edge writes to; see
  # the runquota edges producing ``build/bin/runquotad``).
  #
  # Cycle/depth guard: ``producerBuildStack`` (the analogue of
  # ``fromSourceBuildStack``) — a producer that transitively consumes the
  # consumer would push a root already on the stack; that raises loudly with
  # the full cycle path rather than looping. ``FromSourceMaxRecursionDepth`` is
  # reused as the shared sanity ceiling.
  #
  # This branch fires ONLY for a ``uses:`` selector that resolves as a declared
  # producer edge via the develop-override map / committed ``LockedDep``. A
  # plain on-disk sibling is schema-visible but not an edge declaration, so it
  # is intentionally left to the existing host/PATH behavior. Every other
  # selector (host / nix / tarball / scoop / corpus-recipe) is untouched, so a
  # build that consumes no cross-repo producer is byte-identical to today.
  if not materializedOnly and result.projectRoot.len > 0:
    # Producer materialization follows the selected action closure. Both typed
    # calls and library-consuming actions carry their dependencies through
    # ``toolIdentityRefs``; ``scopedToolArtifact`` retains only those refs.
    # Package-wide ``uses:`` declarations remain available while compiling the
    # provider and its public interface, but must not materialize producers for
    # an unrelated target.
    for useDef in buildArtifact.projectInterface.toolUses:
      let selector = useDef.packageSelector
      if selector.len == 0:
        continue
      if producerMaterializedBinDirs.hasKey(selector) or
          producerMaterializedAuxPaths.hasKey(selector):
        continue  # already built + spliced in this session (dedup)
      # ``resolveProducerBinding`` re-raises a structured override diagnostic
      # (a registered override whose local checkout is missing) instead of a
      # silent host-PATH fallthrough — the SC-1 "no silent fallback" contract.
      let producer = resolveProducerBinding(selector, result.projectRoot)
      if not producer.declaresProducerEdge:
        continue
      # Materialize the producer's SOURCE root. Develop mode always has one on
      # disk (``localPathAbsolute``). Lock-pinned mode uses an existing sibling
      # checkout beside the consumer if present (SC-2); OTHERWISE — the SC-6
      # case — it FETCHES the producer's VCS at the committed ``LockedDep``'s
      # pinned revision into a workspace-local cache and VERIFIES it against the
      # locked integrity (§5.2), so a consumer with only a pinned lock (no
      # sibling on disk) builds the producer from its own repo source at the
      # pinned revision — identical to develop mode from the consuming action's
      # perspective.
      let producerRoot = producerSourceRoot(producer, selector,
        result.projectRoot, fetchMissingPinnedSource = true)
      if producerRoot.len == 0 or
          not dirExists(extendedPath(producerRoot)):
        continue
      let producerRootAbs = absolutePath(producerRoot)
      let producerProjectFile =
        try:
          resolveProjectFile(producerRootAbs).path
        except CatchableError:
          ""
      if producerProjectFile.len == 0:
        continue
      # Cycle guard: a producer that (transitively) resolves back to a root
      # already being built raises with the full cycle path.
      if producerRootAbs in producerBuildStack:
        var cycle = producerBuildStack
        cycle.add(producerRootAbs)
        raise newException(ValueError,
          "cross-repo producer cycle detected while resolving \"" & selector &
          "\": " & cycle.join(" -> ") &
          ". A producer project transitively consumes its consumer; break " &
          "the ``uses:`` cycle in one of these projects.")
      if producerBuildStack.len >= FromSourceMaxRecursionDepth:
        raise newException(ValueError,
          "cross-repo producer recursion depth bound exceeded (" &
          $FromSourceMaxRecursionDepth & ") while resolving \"" & selector &
          "\" at " & producerRootAbs & ". Active stack: " &
          producerBuildStack.join(" -> ") & ".")
      logSummary("cross-repo producer: resolving \"" & selector &
        "\" from source at " & producerRootAbs & " (" & $producer.kind & ")")
      producerBuildStack.add(producerRootAbs)
      # Stable per-producer output base under the consumer's ``outDir`` for the
      # producer's interface-extract artifacts. Independent of whether the
      # producer sub-build runs (it may be skipped for a pure-Nim library), so
      # the interface can be extracted up front to SCOPE the decision below.
      let producerOutDirBase =
        outDir / "cross-repo-producers" / selectorFilesystemKey(selector)
      createDir(extendedPath(producerOutDirBase))
      try:
        # Extract the producer's interface FIRST — BEFORE any sub-build — so we
        # can SCOPE the sub-build to the exact artifact the consumer consumes.
        # Interface extraction compiles only the producer's provider (its
        # ``repro.nim``); it does NOT run the producer's build edges, so it is
        # cheap and side-effect free with respect to the consumed artifact.
        #
        # Bug-fix (producer sub-build over-build): the old code ran
        # ``executeBuildTarget(..., selectDefaultAction = true, ...)``
        # unconditionally, which for a LIBRARY-ONLY producer materialized the
        # producer's DEFAULT action — i.e. its test suite, including any
        # POOL-SERIALIZED test-execute edges (``buildPool(...)``). The
        # consumer's runquotad has no such producer-local pool, so those pooled
        # edges lease-deny forever and the consumer build HANGS. Consuming a
        # sibling library must build (at most) THAT library's own artifact and
        # must never compile or run the producer's test suite.
        let producerIface = producerOutDirBase / "producer-interface.rbsz"
        let producerStub = producerOutDirBase / "producer-interface.nim"
        var producerRuntimeIdentity = PathOnlyBuildIdentity()
        let producerArtifact =
          try:
            # The producer's OWN root is the consumer root for ITS recipe —
            # not the consumer that pulled it in. Passing it explicitly is
            # what keeps two producers extracted in one session from
            # resolving their declared dependencies against each other's
            # workspace; an ambient ``getCurrentDir()`` would hand both the
            # same (wrong) root.
            extractInterfaceEdge(producerProjectFile, producerIface,
              producerStub, reprobuildLibraryWorkDir(),
              producerOutDirBase / "producer-iface-work",
              projectRootForModule(producerProjectFile), publicCliPath,
              producerOutDirBase / "build-engine-cache", buildStats,
              requireStub = false,
              bypassRunQuota = bypassRunQuota,
              fallbackToRunQuotaBypass = fallbackToRunQuotaBypass,
              forceRebuild = forceRebuild,
              suppressTrace = mcTrace notin measureSet,
              skipCacheHitEvidence = mcCacheEvidence notin measureSet,
              statsEnabled = statsEnabled,
              cancelCheck = cancelCheck)
          except CatchableError:
            raise newException(OSError,
              "cross-repo producer \"" & selector & "\" at " &
              producerRootAbs & "'s interface could not be loaded to bind " &
              "the declared executable / library to its output.")
        if producerArtifact.projectInterface.runtimeToolUses.len > 0:
          var runtimeArtifact = producerArtifact
          runtimeArtifact.projectInterface.toolUses =
            producerArtifact.projectInterface.runtimeToolUses
          runtimeArtifact.projectInterface.runtimeToolUses = @[]
          producerRuntimeIdentity = toolBuildIdentity(runtimeArtifact,
            effectiveMode, storeRoot = producerOutDirBase / "runtime-tool-store")
        # Decide whether the producer sub-build is required for the CONSUMED
        # artifact. A build is needed only when the producer exposes a
        # COMPILED artifact on disk:
        #
        #   * a declared ``executable`` — its ``build/bin/<name>`` binary must
        #     exist so the PATH / executable channel finds it (the byte-
        #     identical pre-existing executable-consumption path — e.g.
        #     runquota → ``build/bin/runquotad``); OR
        #   * a declared non-header ``library`` whose consumed artifact is a
        #     compiled ``.so``/``.a``/``.dylib`` rather than a pure-Nim source
        #     tree — i.e. NO importable Nim source root exists at the library's
        #     ``exportedPath`` (default ``src``). A C/C++ shared/static library
        #     must be linked before the consumer can bind against it.
        #
        # A PURE-NIM-SOURCE library (SC-11 — ``library nim_pty`` etc.) exports
        # NO compiled artifact: the consumer imports it directly from the
        # producer's ``src/`` threaded onto ``nim c --path:`` (the nimPathDirs
        # channel below). Its source root is discovered from disk + the
        # interface alone and its source identity folds via SC-4 WITHOUT the
        # producer having run any build edge, so we skip the producer
        # sub-build entirely. This is what keeps a library consumer from
        # dragging in the producer's pooled test suite.
        var needsProducerBuild = false
        for exe in producerArtifact.projectInterface.publicExecutables:
          let binName =
            if exe.binaryName.len > 0: exe.binaryName else: exe.exportName
          if binName.len > 0:
            needsProducerBuild = true
            break
        if not needsProducerBuild:
          for lib in producerArtifact.projectInterface.publicLibraries:
            if lib.name.len == 0 or lib.kind == lkHeaderOnly:
              continue
            let exported =
              if lib.exportedPath.len > 0: lib.exportedPath else: "src"
            let nimSrcDir = producerRootAbs / exported
            if not dirExists(extendedPath(nimSrcDir)):
              # No importable Nim source root — the consumed artifact is a
              # compiled ``.so``/``.a`` that must be built + discovered under
              # ``build/lib``.
              needsProducerBuild = true
              break
        if needsProducerBuild:
          let producerOutcome = executeBuildTarget(producerProjectFile,
            effectiveMode, publicCliPath,
            selectDefaultAction = true,
            workRoot = workRoot,
            progressMode = progressMode,
            progressBarStyle = progressBarStyle,
            showSet = showSet,
            measureSet = measureSet,
            reportPersistence = reportPersistence,
            logMode = logMode,
            diagnosticsPath = "",
            prepareOnly = false,
            dryRun = dryRun,
            forceRebuild = forceRebuild,
            publishCacheHits = publishCacheHits,
            publishMaterialized = publishMaterialized,
            substituteMaterialized = substituteMaterialized,
            skipCmakeRegeneration = skipCmakeRegeneration,
            bypassRunQuotaExplicit = bypassRunQuotaExplicit,
            eventSink = eventSink,
            cancelCheck = cancelCheck)
          if producerOutcome.exitCode != 0:
            raise newException(OSError,
              "cross-repo producer build failed: sub-build of " &
              producerRootAbs & " (selector \"" & selector &
              "\") exited with status " & $producerOutcome.exitCode &
              ". See the sub-build's diagnostics for the underlying failure.")
        else:
          logSummary("cross-repo producer: consuming \"" & selector &
            "\" as a pure-Nim-source library — skipping producer sub-build " &
            "(no compiled artifact; src threaded via nimPathDirs).")
        if not recordProducerMaterialization(selector, producerRootAbs,
            producerArtifact, producerRuntimeIdentity, producer):
          raise newException(OSError,
            "cross-repo producer \"" & selector & "\" at " & producerRootAbs &
            " declares no materialized executable, library, or Nim source " &
            "output to splice onto the consumer's tool channels.")
        if producerMaterializedBinDirs.hasKey(selector):
          logSummary("cross-repo producer: spliced \"" & selector &
            "\" bin dir(s) into tool identities: " &
            producerMaterializedBinDirs[selector].join(", "))
        if producerMaterializedAuxPaths.hasKey(selector):
          let aux = producerMaterializedAuxPaths[selector]
          logSummary("cross-repo producer: spliced \"" & selector &
            "\" library aux dir(s): libDirs=" & aux.libDirs.join(", ") &
            (if aux.includeDirs.len > 0: " includeDirs=" &
              aux.includeDirs.join(", ") else: "") &
            (if aux.nimPathDirs.len > 0: " nimPathDirs=" &
              aux.nimPathDirs.join(", ") else: ""))
      finally:
        if producerBuildStack.len > 0 and
            producerBuildStack[^1] == producerRootAbs:
          discard producerBuildStack.pop()

  # Tier 2b fast path: a package whose DSL body declared no ``build:``
  # block is eligible for the pre-built ``repro-standard-provider``
  # binary. The provider walks language conventions (Nim/Rust/Go/...) to
  # derive a fine-grained graph fragment without a per-project provider
  # compile. We dispatch only when the standard provider binary is
  # actually shipped next to ``repro``; missing-binary installs fall
  # back to the slow path with a warning so users get a build either
  # way.
  # Per Provider-Compile-Tiering.md §"2b — repro-standard-provider" and
  # reprobuild-specs/Standard-Provider-Implementation.milestones.org §M2.
  if mode == tpmPathOnly and not prepareOnly and
      artifact.projectInterface.standardBuildEligible:
    let standardProviderBinary = siblingStandardProviderPath(publicCliPath)
    if standardProviderBinary.len > 0:
      let standardProviderArtifactId =
        standardProviderArtifactIdForBinary(standardProviderBinary)
      invocationFastPath = "tier2b-standard-direct"
      logSummary("standardDirect: dispatching " & standardProviderBinary)
      logSummary("project: " & artifact.projectInterface.projectName)
      logSummary("interface: " & interfacePath)
      logSummary("providerBinary: " & standardProviderBinary)
      logSummary("providerArtifact: " & standardProviderArtifactId)
      logSummary("runQuotaSocket: " & runQuotaSocketDiagnostic())
      let synthIdentity = PathOnlyBuildIdentity(
        projectName: artifact.projectInterface.projectName,
        interfaceFingerprint: artifact.interfaceFingerprint)
      let providerGraphStart = statStart(statsEnabled)
      progressRenderer.renderPhase("refreshing standard provider graph")
      let refresh = refreshProviderGraph(RefreshConfig(
        storeRoot: providerGraphStoreRoot(outDir / "provider-graph"),
        providerBinaryPath: standardProviderBinary,
        providerArtifactId: standardProviderArtifactId,
        rootEntryPointId: StandardProviderRootEntryPointId,
        rootArguments: result.projectRoot,
        namespace: StandardProviderNamespace,
        lockSliceId: digestHex(synthIdentity.interfaceFingerprint),
        activity: "build",
        providerWorkingDir: result.projectRoot))
      finishStat(buildStats, statsEnabled, "repro provider graph refresh",
        providerGraphStart)
      logSummary("providerGraphSnapshot: " & refresh.persistedSnapshotPath)
      logSummary("providerInvocations: " & $refresh.invoked.len)
      var selectedActionId = parsedTarget.selectedActionId
      if effectiveSelectDefaultAction and selectedActionId.len == 0:
        selectedActionId = defaultBuildActionId(refresh.snapshot)
        if selectedActionId.len > 0:
          logSummary("defaultTarget: " & selectedActionId)
      let graphLowerStart = statStart(statsEnabled)
      progressRenderer.renderPhase("lowering standard provider graph")
      # Named-Targets M2 multi-selector union (see trycompile branch above).
      var selectorList: seq[string] = @[]
      if selectedActionId.len > 0:
        selectorList.add(selectedActionId)
      for extra in extraNameSelectors:
        if extra.len > 0 and selectorList.find(extra) < 0:
          selectorList.add(extra)
      let lowered =
        if materializedOnly:
          lowerMaterializedProviderSnapshot(
            refresh.snapshot, result.projectRoot, selectorList)
        elif selectorList.len == 0:
          lowerProviderSnapshot(refresh.snapshot, synthIdentity,
            result.projectRoot, "")
        else:
          lowerProviderSnapshot(refresh.snapshot, synthIdentity,
            result.projectRoot, selectorList)
      finishStat(buildStats, statsEnabled, "repro graph lower", graphLowerStart)
      result.exitCode = runLoweredGraphBuild(lowered, selectedActionId)
      result.inputEvidencePaths = collectedInputEvidence
      return
    else:
      logSummary("standardDirect: provider binary missing; falling back to " &
        "per-project provider compile")

  if shouldEnterBuildPipeline(effectiveMode):
    let identityStart = statStart(statsEnabled)
    let resolved =
      if materializedOnly:
        progressRenderer.renderPhase(
          "skipping tool provisioning for materialized publication")
        (identity: PathOnlyBuildIdentity(
            projectName: artifact.projectInterface.projectName,
            interfaceFingerprint: artifact.interfaceFingerprint),
          identityPath: "",
          inspectionPath: "")
      else:
        progressRenderer.renderPhase("resolving tool identities")
        warmResolveAndWriteIdentity(buildArtifact, outDir, effectiveMode)
    finishStat(buildStats, statsEnabled, "repro tool identity resolve",
      identityStart)
    let identity = resolved.identity
    # M9.N Batch B: now that the build identity is resolved, build the
    # tool-identity resolver closure once and stash it in the outer-
    # scope holder so ``runLoweredGraphBuild`` (which may be called
    # both before AND after this point in different fast paths) can
    # pick it up on subsequent invocations. Calls that happen on the
    # cache-warm fast path BEFORE this point fall through to a nil
    # resolver — see the holder's declaration.
    # Cross-Repo-Source-Consumption SC-1 (§4.1): pass the consumer project
    # root so the resolver closure routes cross-repo producer refs through the
    # develop-override + committed-``LockedDep`` seam.
    pendingToolIdentityResolver =
      if materializedOnly: nil
      else: mkToolIdentityResolver(identity, result.projectRoot)
    if materializedOnly:
      logSummary("repro build: materialized " &
        (if substituteMaterialized: "substitution" else: "publication") &
        " active (tool provisioning skipped)")
    else:
      logSummary("repro build: tool provisioning active " &
        "(tool-provisioning=" & effectiveMode.modeName & ")")
    if not materializedOnly and effectiveMode == tpmPathOnly:
      logSummary("repro build: provisioning-disabled mode active (tool-provisioning=path)")
    logSummary("project: " & artifact.projectInterface.projectName)
    logSummary("interface: " & interfacePath)
    if materializedOnly:
      logSummary("toolIdentity: skipped for materialized operation")
    else:
      logSummary("toolIdentity: " & resolved.identityPath)
      logSummary("inspection: " & resolved.inspectionPath)
    let portability =
      if effectiveMode == tpmNix:
        "portable"
      elif effectiveMode == tpmTarball:
        "portable"
      elif effectiveMode == tpmScoop:
        # Scoop receipts may be cache-portable or cache-local depending on
        # the practical hardening tier. Read the resolved identity to find
        # out, defaulting to local-only when no profiles are present.
        var anyLocal = false
        var anyPortable = false
        for profile in identity.profiles:
          if profile.cachePortability == cpPortable:
            anyPortable = true
          else:
            anyLocal = true
        if anyPortable and not anyLocal:
          "portable"
        elif anyPortable and anyLocal:
          "mixed"
        else:
          "local-only"
      else:
        "local-only"
    logSummary("cachePortability: " & portability)
    logSummary("runQuotaSocket: " & runQuotaSocketDiagnostic())
    if not moduleHasBuildBlock(modulePath):
      result.exitCode = 0
      return
    let providerBinaryPath = outDir / "provider" / "project-provider"
    let providerArtifactPath = outDir / "provider-compile.rbsz"
    logSummary("providerCompile: started")
    progressRenderer.renderPhase("checking provider compile")
    let providerCompileStart = statStart(statsEnabled)
    var providerCompileResult: BuildRunResult
    var provider: ProviderCompileArtifact
    let providerPlan = providerCompilePlan(modulePath, providerBinaryPath,
      artifact.interfaceFingerprint, compileWorkDir, compileScratchDir)
    let cachedProvider =
      if forceRebuild and not dryRun:
        none(ProviderCompileArtifact)
      else:
        staticFreshnessFallbackProvider(providerPlan, providerArtifactPath,
          modulePath, providerBinaryPath, artifact.interfaceFingerprint,
          compileWorkDir)
    if cachedProvider.isSome:
      provider = cachedProvider.get()
    else:
      invalidateStaleProviderCompileArtifact(providerPlan, providerArtifactPath)
      let providerCompileAction = providerCompileBuildAction(providerPlan,
        modulePath, interfacePath, providerArtifactPath,
        internalReproHelperCliPath(publicCliPath), compileWorkDir,
        compileScratchDir)
      var providerCompileConfig = BuildEngineConfig(
        cacheRoot: outDir / "build-engine-cache",
        actionCacheRoot: currentActionCacheRoot(),
        runQuotaCliPath: publicCliPath,
        # The provider compile is monitored like every other action: wrapping
        # the inner ``repro __repro-compile-provider`` (which runs ``nim c``)
        # with io-monitor captures every file the compile reads — repro.nim and
        # ALL transitively imported modules (repro_project_dsl,
        # ct_test_nim_unittest, repro_tests.nim, the stdlib). Without this the
        # provider's fingerprint covered only its statically declared inputs,
        # so editing e.g. the DSL or the test-edge adapter left a stale
        # provider (and, transitively, stale build/execute edges). This is the
        # same monitor wiring the main build's engine config uses.
        monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
        monitorCliArgs: internalIoMonitorArgs,
        maxParallelism: 1'u32,
        stdoutLimit: 1024 * 1024,
        stderrLimit: 1024 * 1024,
        rebuildMissingOutputsOnCacheHit: true,
        deferLocalOutputBlobs: true,
        bypassRunQuota: bypassRunQuota,
        fallbackToRunQuotaBypass: fallbackToRunQuotaBypass,
        inlineRunQuota: true,
        dryRun: false,
        forceRebuild: forceRebuild,
        suppressTrace: mcTrace notin measureSet,
        skipCacheHitEvidence: mcCacheEvidence notin measureSet,
        cancelCallback: cancelCheck)
      providerCompileConfig.statsEnabled = statsEnabled
      # Distinguish "running" from "checking" so a silent hang inside
      # the build engine (e.g. inline runquota session that wedges on a
      # stale daemon) is visibly attributed to the launch path rather
      # than the cache-freshness check above.
      progressRenderer.renderPhase("running provider compile")
      providerCompileResult = runBuild(graph([providerCompileAction]),
        providerCompileConfig)
      buildStats.mergeStats(providerCompileResult.stats)
      warnRunQuotaBypassIfUsed(providerCompileResult)
      noteProviderCompileConsultation(providerCompileResult)
      for item in providerCompileResult.results:
        # `status`/`launched`/`cache` describe THIS consultation only.
        # `consultations`/`compiled` describe the whole invocation, which
        # is what a reader of this line is actually asking about — see
        # `providerCompileLaunchedInThisProcess`.
        logAction("providerCompileAction: " & item.id & " status=" &
          $item.status & " launched=" & $item.launched & " cache=" &
          $item.cacheDecision & " wouldLaunch=" & $item.wouldLaunch &
          (if item.reason.len > 0: " reason=" & item.reason else: "") &
          providerCompileInvocationSummary())
      if providerCompileResult.hasFailedActions():
        raise newException(OSError, providerCompileFailure(providerCompileResult))
      if not fileExists(extendedPath(providerArtifactPath)):
        raise newException(IOError,
          "provider compile edge did not write artifact: " & providerArtifactPath)
      provider = readProviderCompileArtifact(providerArtifactPath)
      if not providerCompileArtifactFresh(providerArtifactPath,
          providerPlan.outputBinaryPath, providerPlan.interfaceFingerprint,
          providerPlan.providerFingerprint, providerPlan.workDir):
        raise newException(IOError,
          "provider compile artifact is stale after edge execution: " &
            providerArtifactPath)
    finishStat(buildStats, statsEnabled, "repro provider compile",
      providerCompileStart)
    let providerArtifactId = digestHex(provider.providerFingerprint)
    logSummary("providerBinary: " & provider.outputBinaryPath)
    logSummary("providerCompileArtifact: " & providerArtifactPath)
    logSummary("providerArtifact: " & providerArtifactId)

    let projectRoot = result.projectRoot
    let providerGraphStore = providerGraphStoreRoot(outDir / "provider-graph")
    let providerGraphStart = statStart(statsEnabled)
    var refresh: ProviderRefreshReport
    progressRenderer.renderPhase("checking project provider graph snapshot")
    let freshSnapshot =
      if forceRebuild or dryRun:
        none(ProviderGraphSnapshot)
      else:
        warmReadFreshProviderGraphSnapshot(providerGraphStore, providerArtifactId)
    if freshSnapshot.isSome:
      refresh.snapshot = freshSnapshot.get()
      refresh.persistedSnapshotPath = providerSnapshotPath(providerGraphStore)
    else:
      progressRenderer.renderPhase("refreshing project provider graph")
      refresh = refreshProviderGraph(RefreshConfig(
        storeRoot: providerGraphStore,
        providerBinaryPath: provider.outputBinaryPath,
        providerArtifactId: providerArtifactId,
        rootEntryPointId: artifact.projectInterface.packageName & ".root",
        rootArguments: projectRoot,
        namespace: "project",
        lockSliceId: digestHex(artifact.interfaceFingerprint),
        activity: "build",
        providerWorkingDir: projectRoot))
    finishStat(buildStats, statsEnabled, "repro provider graph refresh",
      providerGraphStart)
    let providerInvocationCount =
      focusedSnapshotInvocations + refresh.invoked.len
    logSummary("providerGraphSnapshot: " & refresh.persistedSnapshotPath)
    logSummary("providerInvocations: " & $providerInvocationCount)

    # Workspace-Manifest-Optional MO-6 — presence-driven projectExtension
    # auto-activation. Any develop-mode sibling carrying a
    # ``projectExtension <ext>, <thisProject>:`` recipe contributes its
    # edges / targets into THIS project's graph. The merge runs in-memory
    # on every build invocation (even on a provider-graph cache hit, since
    # the snapshot is re-read into ``refresh.snapshot`` above), so a newly
    # checked-out extension auto-activates without any explicit enable
    # step. When no sibling extension targets this project the snapshot is
    # left byte-identical and the legacy single-project build is preserved.
    let extensionSignature = mergeProjectExtensions(refresh.snapshot,
      projectRoot, artifact.projectInterface.packageName, effectiveMode,
      publicCliPath, workRoot)

    # M84: owned-effect-claim output cleanup. When the provider graph refresh
    # dropped edges that owned build outputs (a removed/renamed generated
    # action), delete the now-orphaned files — honoring each claim's cleanup
    # policy, retaining effects still claimed by a surviving fragment (including
    # any just merged in from a project extension above), and refusing any path
    # that escapes the project root. A warm snapshot cache hit leaves
    # ``staleEffects`` empty, so this is a no-op then. ``--dry-run`` and
    # ``--no-output-cleanup`` compute the plan and report it without deleting.
    if refresh.staleEffects.len > 0:
      let cleanupDryRun = dryRun or noOutputCleanup
      let cleanup = applyOutputCleanup(refresh, projectRoot,
        dryRun = cleanupDryRun)
      let cleanupMsg = cleanup.summaryLine()
      if cleanupMsg.len > 0:
        logSummary("outputCleanup: " & cleanupMsg)
      for act in cleanup.actions:
        if act.outcome == ocoFailed:
          logSummary("outputCleanup FAILED: " & act.resolvedPath & " — " &
            act.detail)
        elif act.outcome == ocoRefusedOutsideRoot:
          logSummary("outputCleanup REFUSED: " & act.claim.identity & " — " &
            act.detail)

    var selectedActionId = parsedTarget.selectedActionId
    if effectiveSelectDefaultAction and selectedActionId.len == 0:
      selectedActionId = defaultBuildActionId(refresh.snapshot)
      if selectedActionId.len > 0:
        logSummary("defaultTarget: " & selectedActionId)

    # Named-Targets M2: union the first selector with any extra
    # name-shaped positional selectors for the lowering pass. The
    # lowered-graph cache is keyed by a single ``selectedActionId``, so
    # when extra selectors are present we skip the cache and recompute
    # — the cache schema upgrade to keyed-on-selector-set is M5 work.
    var selectorList: seq[string] = @[]
    if selectedActionId.len > 0:
      selectorList.add(selectedActionId)
    for extra in extraNameSelectors:
      if extra.len > 0 and selectorList.find(extra) < 0:
        selectorList.add(extra)
    let multiTarget = extraNameSelectors.len > 0

    # Named-Targets M5: classify every user-supplied selector against
    # the project-scoped target-export table so the build report records
    # the resolver's outcome (``resolved`` / ``ambiguous`` / ``unknown``)
    # under ``targetResolution``. This is descriptive — the engine has
    # already used the selectors to assemble ``selectorList`` above.
    # Ambiguous / unknown selectors that survive to this point are the
    # action-id / explicit-target labels the user passed directly (the
    # M2 dispatch would have raised a typed exception for unresolvable
    # name selectors before reaching here).
    var targetResolutions: seq[TargetResolutionRecord] = @[]
    var publicActionAliases = initTable[string, string]()
    block computeTargetResolutions:
      let exportTable = aggregateTargetExportTable(refresh.snapshot)
      var actionIds: seq[string] = @[]
      var explicitTargets: seq[string] = @[]
      # **Deferred Item D5** collection-membership view passed to
      # ``resolveTargetExportSelector`` so the build report's
      # ``targetResolution`` row for a ``<collection>#<member>``
      # selector matches what the engine actually executed (instead
      # of being recorded as ``unknown_target``).
      var collectionMembers = initTable[string, seq[string]]()
      var seenAction = initHashSet[string]()
      var seenExplicit = initHashSet[string]()
      for fragment in refresh.snapshot.fragments:
        for node in fragment.nodes:
          if node.kind == gnkAction:
            let payload = decodeBuildActionPayload(toBytes(node.payload))
            if not seenAction.containsOrIncl(payload.id):
              actionIds.add(payload.id)
          elif node.kind == gnkMetadata and
              node.stableName == "reprobuild.build-target.v1":
            let targetDef = decodeBuildTargetPayload(toBytes(node.payload))
            if not seenExplicit.containsOrIncl(targetDef.name):
              explicitTargets.add(targetDef.name)
            if targetDef.kind == btkAggregate and
                targetDef.actions.len == 1 and targetDef.targets.len == 0:
              publicActionAliases[targetDef.actions[0]] = targetDef.name
            if targetDef.kind == btkCollection:
              if collectionMembers.hasKey(targetDef.name):
                for a in targetDef.actions:
                  if a notin collectionMembers[targetDef.name]:
                    collectionMembers[targetDef.name].add(a)
              else:
                collectionMembers[targetDef.name] = targetDef.actions
      var userSelectors: seq[string] = @[]
      if parsedTarget.fragmentKind == tfkActionSelection and
          parsedTarget.selectedActionId.len > 0:
        userSelectors.add(parsedTarget.selectedActionId)
      for extra in extraNameSelectors:
        if extra.len > 0 and userSelectors.find(extra) < 0:
          userSelectors.add(extra)
      for sel in userSelectors:
        targetResolutions.add(resolveTargetExportSelector(exportTable,
          actionIds, explicitTargets, sel, collectionMembers))

    # A named run-edge selector is an export-table name, not necessarily the
    # underlying action id. Forward arguments to the exact action selected by
    # the shared resolver rather than guessing from the lowered graph shape.
    var forwardedActionId = selectedActionId
    if forwardedActionArgs.len > 0 and targetResolutions.len == 1 and
        targetResolutions[0].kind == trkResolved:
      forwardedActionId = targetResolutions[0].actionId
      if publicActionAliases.hasKey(forwardedActionId):
        forwardedActionId = publicActionAliases[forwardedActionId]

    let graphCacheKey = loweredGraphCacheKey(buildArtifact, effectiveMode,
      providerArtifactId, refresh.persistedSnapshotPath, pathEnv,
      extensionSignature)
    let graphCacheReadStart = statStart(statsEnabled)
    progressRenderer.renderPhase("reading lowered graph cache")
    let cachedLowered =
      if forceRebuild or multiTarget or materializedOnly:
        none(tuple[actions: seq[BuildAction]; pools: seq[BuildPool]])
      else:
        warmReadFreshLoweredGraphCache(loweredGraphCachePath(outDir, selectedActionId),
          modulePath, projectRoot, selectedActionId, pathEnv, graphCacheKey)
    finishStat(buildStats, statsEnabled, "repro lowered graph cache read",
      graphCacheReadStart)
    let lowered =
      if cachedLowered.isSome:
        logSummary("loweredGraphCache: hit")
        cachedLowered.get()
      else:
        let graphLowerStart = statStart(statsEnabled)
        progressRenderer.renderPhase("lowering project graph")
        let computed =
          if materializedOnly:
            lowerMaterializedProviderSnapshot(refresh.snapshot, projectRoot,
              selectorList)
          elif selectorList.len == 0:
            lowerProviderSnapshot(refresh.snapshot, identity,
              projectRoot, "")
          else:
            lowerProviderSnapshot(refresh.snapshot, identity,
              projectRoot, selectorList)
        finishStat(buildStats, statsEnabled, "repro graph lower", graphLowerStart)
        let cacheWriteStart = statStart(statsEnabled)
        if not multiTarget and not materializedOnly:
          writeLoweredGraphCache(loweredGraphCachePath(outDir, selectedActionId),
            modulePath, projectRoot, selectedActionId, pathEnv, graphCacheKey,
            computed)
          if effectiveSelectDefaultAction and parsedTarget.selectedActionId.len == 0:
            writeLoweredGraphCache(loweredGraphCachePath(outDir, ""), modulePath,
              projectRoot, "", pathEnv, graphCacheKey, computed)
        finishStat(buildStats, statsEnabled, "repro lowered graph cache write",
          cacheWriteStart)
        computed
    if prepareOnly:
      if cmakeMeta.enabled:
        createDir(extendedPath(parentDir(cmakeMeta.providerStateFile)))
        writeFile(extendedPath(cmakeMeta.providerStateFile), readFile(extendedPath(modulePath)))
        let seedStart = statStart(statsEnabled)
        discard seedCmakeRegenerationCache(cmakeMeta, publicCliPath, outDir)
        finishStat(buildStats, statsEnabled,
          "repro cmake regeneration cache seed", seedStart)
      finishStat(buildStats, statsEnabled, "repro build total",
        buildTotalStart)
      emitMeasurements(BuildRunResult(stats: buildStats))
      result.exitCode = 0
      return
    if parsedTarget.fragmentKind == tfkActionSelection:
      logSummary("selectedTarget: " & parsedTarget.selectedActionId)
    elif effectiveSelectDefaultAction and selectedActionId.len > 0:
      logSummary("selectedTarget: " & selectedActionId)
    logSummary("scheduler: actions=" & $lowered.actions.len)
    if lowered.actions.len == 0:
      result.exitCode = 0
      return
    var engineConfig = BuildEngineConfig(
      cacheRoot: outDir / "build-engine-cache",
      actionCacheRoot: currentActionCacheRoot(),
      runQuotaCliPath: publicCliPath,
      monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
      monitorCliArgs: internalIoMonitorArgs,
      maxParallelism: buildMaxParallelism(),
      stdoutLimit: 1024 * 1024,
      stderrLimit: 1024 * 1024,
      rebuildMissingOutputsOnCacheHit: true,
      deferLocalOutputBlobs: true,
      bypassRunQuota: bypassRunQuota,
      fallbackToRunQuotaBypass: fallbackToRunQuotaBypass,
      inlineRunQuota: true,
      dryRun: dryRun,
      forceRebuild: forceRebuild,
      publishCachedResults: publishCacheHits,
      suppressTrace: mcTrace notin measureSet,
      skipCacheHitEvidence: mcCacheEvidence notin measureSet,
      cancelCallback: cancelCheck)
    # M9.L.4-refactor Step C: wire the binary-cache publisher closure
    # into the production engine config for the main inline build
    # path (the runLoweredGraphBuild helper above gets the same
    # wiring). Closure is inert without ``REPRO_BINARY_CACHE_*`` env
    # vars; engine only fires it for actions carrying
    # ``publishToBinaryCache = true`` + populated
    # ``cacheEntryIdentity``.
    engineConfig.binaryCachePublisher = mkBinaryCachePublisher()
    # L3 PUBLISH-SCOPE: intermediate cache → publish everything;
    # release cache (default) → only tagged public-interface members.
    engineConfig.binaryCacheIntermediateScope =
      bcCachesConfig.publishTargetScope() == bcCachesConfig.csIntermediate
    # M9.N Batch B: attach the tool-identity resolver closure here
    # too. ``identity`` is in scope at this site (the main inline
    # build path resolves it before reaching here); the closure
    # walks each action's ``toolIdentityRefs`` and prepends the
    # resolved bin dirs to PATH at fork time.
    # Cross-Repo-Source-Consumption SC-1 (§4.1): thread the consumer project
    # root through so the resolver routes cross-repo producer refs through the
    # develop-override + committed-``LockedDep`` seam.
    engineConfig.toolIdentityResolver =
      mkToolIdentityResolver(identity, projectRoot)
    engineConfig.statsEnabled = statsEnabled
    if eventSink != nil:
      engineConfig.progressCallback = proc(event: BuildProgressEvent) =
        enqueueStatsObservation(scgSessions, "progress", %*{
          "kind": $event.kind,
          "actionId": event.actionId,
          "status": $event.status,
          "cacheDecision": $event.cacheDecision,
          "total": event.total,
          "completed": event.completed,
          "running": event.running,
          "ready": event.ready
        })
        eventSink("diagnostic", "progress: " & $event.kind & " " &
          event.actionId, $(%*{
            "event": "progress",
            "kind": $event.kind,
            "actionId": event.actionId,
            "command": event.command,
            "currentCommand": event.currentCommand,
            "status": $event.status,
            "cacheDecision": $event.cacheDecision,
            "total": event.total,
            "completed": event.completed,
            "checked": event.checked,
            "running": event.running,
            "ready": event.ready
          }))
    elif progressRenderer.enabled:
      engineConfig.progressCallback = proc(event: BuildProgressEvent) =
        enqueueStatsObservation(scgSessions, "progress", %*{
          "kind": $event.kind,
          "actionId": event.actionId,
          "status": $event.status,
          "cacheDecision": $event.cacheDecision,
          "total": event.total,
          "completed": event.completed,
          "running": event.running,
          "ready": event.ready
        })
        progressRenderer.renderProgress(event)
    var buildResult: BuildRunResult
    let engineStart = statStart(statsEnabled)
    # Cross-Repo-Source-Consumption SC-2/SC-3 (§4.2 points 3-4): attach each
    # materialized LIBRARY-channel producer as a tool ref on the consumer
    # actions (SC-3, so the engine threads its realized library dirs onto the
    # aux channels), then fold each materialized producer's action-hash into
    # the consumer actions that name it, so the producer edge is a real input
    # of the consumer cache key. Both are no-ops when nothing was materialized
    # (byte-identical to today).
    var scheduledActions = lowered.actions
    appendForwardedArgs(scheduledActions, forwardedActionId)
    attachProducerAuxRefs(scheduledActions)
    foldProducerActionHashes(scheduledActions)
    # Cross-Repo-Source-Consumption SC-4 (§4.3): fold each materialized
    # producer's SOURCE identity (develop ``contentIdentity`` / lock-pinned
    # ``revision``+``integrity``) into the consumer actions that name it, so a
    # producer SOURCE change rebuilds the consumer. No-op when nothing was
    # materialized (byte-identical to today).
    foldProducerSourceIdentities(scheduledActions)
    try:
      progressRenderer.renderPhase("checking graph actions=" &
        $scheduledActions.len)
      let scheduledGraph = graph(scheduledActions, lowered.pools)
      if substituteMaterialized:
        buildResult = substituteMaterializedBinaryCacheEntries(scheduledGraph)
      elif publishMaterialized:
        buildResult = publishMaterializedBinaryCacheEntries(
          scheduledGraph, engineConfig.binaryCachePublisher)
      else:
        buildResult = runBuild(scheduledGraph, engineConfig)
    except CatchableError:
      progressRenderer.finishProgress()
      raise
    finishStat(buildStats, statsEnabled, "repro engine runBuild", engineStart)
    buildStats.mergeStats(buildResult.stats)
    benchmarkExecutedActions = 0
    for item in buildResult.results:
      if item.launched:
        inc benchmarkExecutedActions
    warnRunQuotaBypassIfUsed(buildResult)
    logRunQuotaAuthority(buildResult)
    finishStat(buildStats, statsEnabled, "repro build total", buildTotalStart)
    buildResult.stats = buildStats
    let reportPath =
      if reportPersistence.path.len > 0: absolutePath(reportPersistence.path)
      else: outDir / "build-report.json"
    if reportPersistence.requested and not reportPersistence.suppressed:
      let reportStart = statStart(statsEnabled)
      writeBuildReport(reportPath, provider, refresh, providerInvocationCount,
        cmakeRegenerationResult, providerCompileResult, buildResult,
        targetResolutions = targetResolutions)
      finishStat(buildStats, statsEnabled, "repro report write", reportStart)
      buildResult.stats = buildStats
      result.buildReportPath = reportPath
    let actionLogStart = statStart(statsEnabled)
    for item in buildResult.results:
      logAction("action: " & item.id & " status=" & $item.status &
        " launched=" & $item.launched & " cache=" & $item.cacheDecision &
        " wouldLaunch=" & $item.wouldLaunch &
        (if item.reason.len > 0: " reason=" & item.reason else: "") &
        " runquota=" & item.runQuotaBackend &
        " socket=" & (if item.runQuotaSocket.len >
            0: item.runQuotaSocket else: "default") &
        " lease=" & $item.leaseId &
        " evidence=depfile:" & $item.evidence.depfileInputs.len)
    if reportPersistence.requested and not reportPersistence.suppressed:
      logSummary("buildReport: " & reportPath)
    finishStat(buildStats, statsEnabled, "repro action log render",
      actionLogStart)
    buildResult.stats = buildStats
    collectInputEvidence(buildResult)
    result.inputEvidencePaths = collectedInputEvidence
    recordStatsForBuildRun(buildResult)
    if buildResult.hasFailedActions():
      emitFailedActionSummaries(buildResult, eventSink, progressRenderer)
      persistFailureReport(buildResult, scheduledActions)
    let statsRenderStart = statStart(statsEnabled)
    emitMeasurements(buildResult)
    finishStat(buildStats, statsEnabled, "repro stats render", statsRenderStart)
    result.exitCode =
      if buildResult.hasFailedActions():
        1
      else:
        0
    return

  logSummary("repro build: no external tools requested")
  logSummary("interface: " & interfacePath)
  result.exitCode = 0

proc isUnderReproDir(path: string): bool =
  for part in path.split({'/', '\\'}):
    if part == ".repro":
      return true

proc addWatchCandidate(paths: var HashSet[string]; projectRoot, path: string) =
  if path.len == 0:
    return
  var candidate =
    if path.isAbsolute:
      path
    else:
      projectRoot / path
  candidate = os.normalizedPath(candidate)
  if candidate.isUnderReproDir():
    return
  paths.incl(candidate)
  let parent = parentDir(candidate)
  if parent.len > 0 and not parent.isUnderReproDir():
    paths.incl(parent)

proc watchPathsFromOutcome(outcome: BuildCommandOutcome): seq[string] =
  ## The path set ``repro watch`` arms its filesystem watcher over: the
  ## project file plus every input the run observed. The in-memory
  ## evidence is the primary source (always collected); the persisted
  ## report is read as well so a caller that has one loses nothing, but
  ## it is never the only source — see ``inputEvidencePaths``.
  var paths = initHashSet[string]()
  addWatchCandidate(paths, outcome.projectRoot, outcome.modulePath)
  for item in outcome.inputEvidencePaths:
    addWatchCandidate(paths, outcome.projectRoot, item)
  if outcome.buildReportPath.len > 0 and fileExists(extendedPath(outcome.buildReportPath)):
    let report = parseFile(outcome.buildReportPath)
    for action in report{"actions"}:
      let evidence = action{"evidence"}
      for key in ["declaredInputs", "depfileInputs", "monitorReads",
          "monitorProbes"]:
        for item in evidence{key}:
          addWatchCandidate(paths, outcome.projectRoot, item.getStr())
  result = toSeq(paths)
  result.sort()

proc flushStdout() =
  stdout.flushFile()

proc binDirsForDevelop(identity: PathOnlyBuildIdentity): seq[string] =
  for profile in identity.profiles:
    if profile.installMethod == "nix":
      for storePath in profile.realizedStorePaths:
        let binDir = storePath / "bin"
        if dirExists(extendedPath(binDir)) and not result.contains(binDir):
          result.add(binDir)
    else:
      for binDir in profile.pathSearchList:
        if binDir.len > 0 and dirExists(extendedPath(binDir)) and not result.contains(binDir):
          result.add(binDir)

proc runInDevelopEnvironment(command: openArray[string]; projectRoot: string;
                             identity: PathOnlyBuildIdentity;
                             identityPath, inspectionPath,
                             interfacePath: string): int =
  if command.len == 0:
    raise newException(ValueError, "develop command is empty")
  # Canonicalize projectRoot before plumbing it through both the child's
  # working-directory and REPRO_PROJECT_ROOT. On macOS the system temp
  # roots (/tmp, /var/folders/...) are symlinks into /private/..., and
  # after the child shell chdirs into the working directory it sets PWD
  # from getcwd(), which returns the realpath form. If the env var
  # disagreed with PWD the user-visible contract (REPRO_PROJECT_ROOT =
  # the shell's cwd) would break for any path that traverses a symlink.
  let canonicalProjectRoot =
    try:
      expandFilename(projectRoot)
    except OSError:
      projectRoot
  let profileBinDirs = binDirsForDevelop(identity)
  let pathValue =
    if profileBinDirs.len > 0:
      profileBinDirs.join($PathSep) & $PathSep & getEnv("PATH")
    else:
      getEnv("PATH")
  let artifact = DevEnvArtifact(
    projectRoot: canonicalProjectRoot,
    selectedActivities: @["develop"],
    shellOps: @[
      DevEnvShellOp(kind: deskSetEnv, name: "PATH", value: pathValue),
      DevEnvShellOp(kind: deskSetEnv, name: "REPRO_TOOL_PROFILE_ARTIFACT",
        value: identityPath),
      DevEnvShellOp(kind: deskSetEnv, name: "REPRO_TOOL_PROFILE_INSPECTION",
        value: inspectionPath),
      DevEnvShellOp(kind: deskSetEnv, name: "REPRO_PROJECT_INTERFACE",
        value: interfacePath),
      DevEnvShellOp(kind: deskSetEnv, name: "REPRO_PROJECT_ROOT",
        value: canonicalProjectRoot)
    ])
  runActivatedCommand(artifact, "", command, canonicalProjectRoot)

proc valueAfterFlag(args: openArray[string]; flag: string): string =
  var i = 0
  while i < args.len:
    if args[i] == flag and i + 1 < args.len:
      return args[i + 1]
    inc i
  ""

proc navigatorStatsJson(stats: DevEnvNavigatorStats): JsonNode =
  %*{
    "envelopeBytesChecked": stats.envelopeBytesChecked,
    "payloadBytesHashed": stats.payloadBytesHashed,
    "payloadHeaderBytesRead": stats.payloadHeaderBytesRead,
    "shellOpRecordsDecoded": stats.shellOpRecordsDecoded,
    "taskRecordsDecoded": stats.taskRecordsDecoded,
    "serviceRecordsDecoded": stats.serviceRecordsDecoded,
    "maxDecodedPayloadOffset": stats.maxDecodedPayloadOffset,
    "shellOpsSectionStart": stats.shellOpsSectionStart,
    "shellOpsSectionEnd": stats.shellOpsSectionEnd,
    "tasksSectionStart": stats.tasksSectionStart,
    "servicesSectionStart": stats.servicesSectionStart
  }

proc runProviderCompileHelper(args: openArray[string]): int =
  let modulePath = valueAfterFlag(args, "--module")
  let outputPath = valueAfterFlag(args, "--out")
  let artifactPath = valueAfterFlag(args, "--artifact")
  let interfacePath = valueAfterFlag(args, "--interface")
  let workDir = valueAfterFlag(args, "--work-dir")
  let scratchDir = valueAfterFlag(args, "--scratch-dir")
  for (name, value) in [
    ("--module", modulePath),
    ("--out", outputPath),
    ("--artifact", artifactPath),
    ("--interface", interfacePath),
    ("--work-dir", workDir)
  ]:
    if value.len == 0:
      stderr.writeLine("repro provider compile: missing " & name)
      return 2
  try:
    let interfaceArtifact = readInterfaceArtifact(interfacePath)
    # ``useFreshnessCache = false``: reaching this process at all means the
    # engine already decided the edge must run, from monitored evidence that
    # sees more than the recipe's import closure. Re-asking the narrower
    # text-closure key here would veto that decision and re-publish the stale
    # binary the edge was re-run to replace.
    discard compileProviderBinary(modulePath, outputPath,
      interfaceArtifact.interfaceFingerprint, artifactPath, workDir,
      scratchDir, useFreshnessCache = false)
    return 0
  except CatchableError as err:
    stderr.writeLine("repro provider compile: error: " & err.msg)
    return 1

proc runInterfaceExtractHelper(args: openArray[string]): int =
  ## Child side of the interface-extraction edge. Runs INSIDE the monitored
  ## process, so everything the extraction reads — the recipe, every module
  ## it imports, every nim config file, and whatever a ``staticExec`` in a
  ## recipe macro reaches — is observed by io-mon and becomes evidence for
  ## the edge, without anyone declaring it.
  let modulePath = valueAfterFlag(args, "--module")
  let artifactPath = valueAfterFlag(args, "--artifact")
  let stubPath = valueAfterFlag(args, "--stub")
  let workDir = valueAfterFlag(args, "--work-dir")
  let scratchDir = valueAfterFlag(args, "--scratch-dir")
  # Passed explicitly, never taken from the child's cwd: the engine chooses
  # the action's working directory, and this value is baked into the
  # compiled recipe as ``-d:reproConsumerRoot``. Deriving it from the
  # ambient cwd here would silently point a recipe's dependency resolution
  # at the wrong workspace.
  let consumerRoot = valueAfterFlag(args, "--consumer-root")
  let resourceModule = valueAfterFlag(args, "--resource-module")
  let requireStub = valueAfterFlag(args, "--require-stub") == "1"
  var extraPaths: seq[string] = @[]
  for i in 0 ..< args.len - 1:
    if args[i] == "--extra-path" and args[i + 1].len > 0:
      extraPaths.add(args[i + 1])
  for (name, value) in [
    ("--module", modulePath),
    ("--artifact", artifactPath),
    ("--stub", stubPath),
    ("--work-dir", workDir)
  ]:
    if value.len == 0:
      stderr.writeLine("repro interface extract: missing " & name)
      return 2
  try:
    # ``useExtractionCache = false``: reaching this process at all means the
    # engine already decided the edge must run. Re-asking the narrower
    # text-closure key here could only ever overrule that decision, and it
    # would do so exactly in the cases the edge was introduced for — a
    # dependency acquired during macro expansion, which that key cannot see.
    discard extractInterfaceFromModule(modulePath, artifactPath, stubPath,
      workDir, scratchDir, requireStub, resourceModule, extraPaths,
      consumerRoot, useExtractionCache = false)
    return 0
  except CatchableError as err:
    stderr.writeLine("repro interface extract: error: " & err.msg)
    return 1

proc splitDevEnvActivities(value: string): seq[string] =
  let source = if value.len > 0: value else: "default"
  for raw in source.split(','):
    let item = raw.strip()
    if item.len > 0:
      result.add(item)
  if result.len == 0:
    result.add("default")

proc descriptorById(manifest: ProviderManifest; id: string):
    Option[GraphEntryPointDescriptor] =
  for descriptor in manifest.entryPoints:
    if descriptor.id == id:
      return some(descriptor)
  none(GraphEntryPointDescriptor)

proc validateDevEnvManifest(manifest: ProviderManifest;
                            providerArtifactId: string) =
  if manifest.protocolVersion != ProviderProtocolVersion:
    raise newException(ValueError, "unsupported provider protocol version " &
      $manifest.protocolVersion)
  if providerArtifactId.len > 0 and
      manifest.providerArtifactId != providerArtifactId:
    raise newException(ValueError,
      "provider manifest artifact mismatch: expected " &
        providerArtifactId & ", got " & manifest.providerArtifactId)

proc runStableProviderProtocol(binaryPath, protocolRoot, stem, cwd: string;
                               request: ProviderGraphRequest):
                               ProviderGraphResponse =
  createDir(extendedPath(protocolRoot))
  let requestPath = protocolRoot / (stem & ".request.rbpg")
  let responsePath = protocolRoot / (stem & ".response.rbpg")
  writeProviderRequestFile(requestPath, request)
  if fileExists(extendedPath(responsePath)):
    removeFile(extendedPath(responsePath))
  let argv = @[
    binaryPath,
    "--repro-provider-request", requestPath,
    "--repro-provider-response", responsePath]
  # M8 stderr-truncation fix: previously used
  # ``startProcess + outputStream.readAll + waitForExit`` to drive the
  # provider here too, with the same symptom — diagnostics from the
  # standard provider arrived truncated to a single byte on Windows.
  # See the matching switch in
  # ``libs/repro_provider_runtime/src/repro_provider_runtime/runtime.nim``
  # for the full audit. ``execCmdEx`` drains incrementally via
  # ``readLine`` + ``peekExitCode``.
  #
  # Windows grandchild evidence: ``startProcess`` here used to spawn
  # the provider through Nim's ``winlean.createProcessW`` (a
  # ``nimGetProcAddr``-resolved pointer that bypasses the shim's IAT
  # hook), so the provider grandchild ran naked and its CRT-mediated
  # ``CreateFileW`` calls never recorded into the fragment dir. M72
  # closes that gap at the shim layer by inline-detouring
  # ``kernel32!CreateProcessW`` (``ct_inline_hook_install``); every
  # call to CreateProcessW — IAT-routed, dynlib-resolved, or anything
  # else — now lands in ``trampolineCreateProcessW``, whose
  # The Windows process-spawn hook re-injects the shim into the grandchild
  # via the same ``CreateRemoteThread(LoadLibraryW)`` flow
  # the io-monitor uses to seed the top-level child. No
  # subprocess-spawn-site rewrite needed here.
  let (output, exitCode) = execCmdEx(quoteShellCommand(argv),
    options = {poStdErrToStdOut, poUsePath},
    workingDir = cwd)
  if exitCode != 0:
    raise newException(OSError,
      "provider exited with code " & $exitCode & ": " & output)
  if not fileExists(extendedPath(responsePath)):
    raise newException(IOError, "provider did not write response: " &
      responsePath)
  readProviderResponseFile(responsePath)

const DevelopOverridesEnvVar = "REPRO_DEVELOP_OVERRIDES_FILE"
  ## The env var naming the develop-override document. One spelling, because
  ## the engine both SETS it (when it launches a provider that must see the
  ## overrides) and WITHDRAWS it (when it probes a sibling, which must not).
  ## It MUST match
  ## ``repro_dsl_stdlib/configurables/develop_sources.readDevelopSources`` —
  ## that module is std-only by design and shares this CONTRACT with the
  ## engine rather than any code, so the two spellings have nothing but this
  ## comment holding them together.

proc runDevEnvIntrospectionHelper(args: openArray[string]): int =
  let providerBinary = valueAfterFlag(args, "--provider-binary")
  let providerArtifactId = valueAfterFlag(args, "--provider-artifact-id")
  let projectRoot = valueAfterFlag(args, "--project-root")
  let artifactPath = valueAfterFlag(args, "--out")
  let protocolRoot = valueAfterFlag(args, "--protocol-root")
  let entryPointId = valueAfterFlag(args, "--entry-point")
  let activity = valueAfterFlag(args, "--activity")
  let lockSliceId = valueAfterFlag(args, "--lock-slice")
  let developOverridesPath = valueAfterFlag(args, "--develop-overrides")
  for (name, value) in [
    ("--provider-binary", providerBinary),
    ("--provider-artifact-id", providerArtifactId),
    ("--project-root", projectRoot),
    ("--out", artifactPath),
    ("--protocol-root", protocolRoot)
  ]:
    if value.len == 0:
      stderr.writeLine("repro dev-env introspection: missing " & name)
      return 2
  try:
    if developOverridesPath.len > 0:
      putEnv(DevelopOverridesEnvVar, developOverridesPath)
    let cwd = if projectRoot.len > 0: projectRoot else: getCurrentDir()
    let manifestResponse = runStableProviderProtocol(providerBinary,
      protocolRoot, "manifest", cwd, ProviderGraphRequest(
        kind: prkManifest,
        providerArtifactId: providerArtifactId,
        reason: girExplicitUserRequest))
    if manifestResponse.kind != pskManifest:
      raise newException(ValueError,
        "provider manifest request returned non-manifest response")
    validateDevEnvManifest(manifestResponse.manifest, providerArtifactId)

    var selectedEntryPoint = entryPointId
    if selectedEntryPoint.len == 0:
      for descriptor in manifestResponse.manifest.entryPoints:
        if descriptor.kind == gpkDevEnvIntrospection:
          selectedEntryPoint = descriptor.id
          break
    if selectedEntryPoint.len == 0:
      raise newException(ValueError,
        "provider manifest does not expose dev-env introspection")
    let descriptorOpt = manifestResponse.manifest.descriptorById(
      selectedEntryPoint)
    if descriptorOpt.isNone:
      raise newException(ValueError,
        "dev-env entry point is missing from provider manifest")
    let descriptor = descriptorOpt.get()
    if descriptor.kind != gpkDevEnvIntrospection:
      raise newException(ValueError,
        "entry point is not dev-env introspection: " & selectedEntryPoint)

    let selectedActivity = if activity.len > 0: activity else: "default"
    let request = ProviderGraphRequest(
      kind: prkDevEnvIntrospection,
      providerArtifactId: providerArtifactId,
      entryPointId: selectedEntryPoint,
      entryPointBodyHash: descriptor.bodyHash,
      reason: girExplicitUserRequest,
      arguments: projectRoot,
      lockSliceId: lockSliceId,
      activity: selectedActivity)
    let response = runStableProviderProtocol(providerBinary, protocolRoot,
      "dev-env", cwd, request)
    if response.kind != pskDevEnvResult:
      raise newException(ValueError,
        "provider dev-env request did not return a dev-env result")
    validateDevEnvManifest(response.manifest, providerArtifactId)
    if response.devEnv.providerArtifactId != providerArtifactId:
      raise newException(ValueError, "provider artifact mismatch in dev-env result")
    if response.devEnv.providerEntryPointId != selectedEntryPoint:
      raise newException(ValueError, "provider entry point mismatch in dev-env result")
    if response.devEnv.providerEntryPointBodyHash != descriptor.bodyHash:
      raise newException(ValueError, "provider body hash mismatch in dev-env result")
    if response.devEnv.projectRoot != projectRoot:
      raise newException(ValueError, "project root mismatch in dev-env result")
    if response.devEnv.lockSliceId != lockSliceId:
      raise newException(ValueError, "lock slice mismatch in dev-env result")
    if response.devEnv.selectedActivities !=
        splitDevEnvActivities(selectedActivity):
      raise newException(ValueError, "activity selection mismatch in dev-env result")

    writeDevEnvArtifact(artifactPath, artifactFromDevEnvResult(response.devEnv))
    return 0
  except CatchableError as err:
    stderr.writeLine("repro dev-env introspection: error: " & err.msg)
    return 1

proc runDevEnvShellRenderHelper(args: openArray[string]): int =
  let artifactPath = valueAfterFlag(args, "--artifact")
  let outputPath = valueAfterFlag(args, "--out")
  let navigatorStatsPath = valueAfterFlag(args, "--navigator-stats")
  for (name, value) in [
    ("--artifact", artifactPath),
    ("--out", outputPath)
  ]:
    if value.len == 0:
      stderr.writeLine("repro dev-env shell render: missing " & name)
      return 2
  try:
    var navigatorStats: DevEnvNavigatorStats
    let ops = shellOpsFromNavigatorFile(artifactPath, navigatorStats)
    createDir(extendedPath(parentDir(outputPath)))
    writeFile(extendedPath(outputPath), renderDevEnvShellOps(ops, depPosix))
    if navigatorStatsPath.len > 0:
      createDir(extendedPath(parentDir(navigatorStatsPath)))
      writeFile(extendedPath(navigatorStatsPath),
        pretty(navigatorStatsJson(navigatorStats)) & "\n")
    return 0
  except CatchableError as err:
    stderr.writeLine("repro dev-env shell render: error: " & err.msg)
    return 1

type
  DevelopOverrideVariantDecl = object
    ## Named-Lock-Files NLF-M2, the writer half — one variant DECLARATION
    ## recorded against a develop override, in the shape
    ## ``repro_dsl_stdlib/configurables/develop_sources.nim`` parses.
    ##
    ## A DECLARATION, never an assignment (owner decision Q-4, 2026-08-18:
    ## "variants of a develop-mode package are SOLVED, not recorded"). The
    ## name, the universe and the recipe's declared default are the shape of
    ## the question; the answer stays the solve's to give, and the reader
    ## turns ``default`` into a default-band contribution rather than a pin
    ## precisely so it can be overruled.
    ##
    ## The name is the SIBLING's own, unqualified. Qualification by package is
    ## the reader's job (``qualifiedVariantName``); doing it here as well would
    ## produce ``libfoo.libfoo.enableTls`` and reach nothing.
    name: string
    kind: string             ## ``bool`` or ``enum`` — the reader's two shapes.
    values: seq[string]      ## the enum universe; empty for ``bool``.
    default: string          ## the declared default, or ``""`` when none.

  DevelopOverrideEntry = object
    ## One entry of ``develop-overrides.json``. ``node`` and ``path`` are what
    ## the engine has always written; ``version`` and ``variants`` are the two
    ## fields `develop_sources.nim` has read since NLF-M2 and nothing produced.
    ##
    ## Both of the new fields are OMITTED when unknown rather than filled with
    ## a stand-in, and that is the whole of the design. The consumer's version
    ## chain is `an explicit version` -> `a VERSION file` -> a loud refusal;
    ## writing `0.0.0`, a timestamp, or the declared range's lower bound would
    ## short-circuit that chain with a value nobody observed — which is the
    ## defect NLF-M2 removed from the solve, re-introduced one layer up with
    ## better-looking provenance.
    node: string
    path: string
    version: string
      ## The upstream solved identity this override REPLACED, read from the
      ## consumer's committed lock. Empty = the lock does not say, and the
      ## field is not written at all.
    variants: seq[DevelopOverrideVariantDecl]
      ## The sibling's own variant declarations. Empty = none were obtained,
      ## and the field is not written at all.
      ##
      ## "The sibling declares none" and "the sibling could not be asked" are
      ## deliberately NOT distinguished here, because the probe that answers
      ## the question cannot distinguish them either: a recipe with no
      ## variants emits no solver inputs at all, which is the same `none` a
      ## failed provider compile returns. Recording an empty array for one of
      ## them would be a claim the engine is not in a position to make. The
      ## consumer treats both as "no variants", so nothing downstream turns on
      ## the difference.

  DevEnvCliSelection = object
    selector: string
    modulePath: string
    projectRoot: string
    outDir: string
    workRoot: string
    activity: string
    lockSliceId: string
    developOverridesPath: string
    statsPath: string

  ParsedDevEnvExec = object
    selection: DevEnvCliSelection
    command: seq[string]

  ParsedDevEnvShell = object
    selection: DevEnvCliSelection
    printEnv: bool
    printFormat: DevEnvPrintFormat
    shellPath: string

  RunTargetQualifier = enum
    ## Named-Runnable-Edges N1: how the user spelled the ``repro run``
    ## positional, so resolution can honour an explicit disambiguation
    ## prefix (spec §5 / §7).
    rtqNone       ## bare ``<name>`` — resolve task-first, then run-edge.
    rtqTask       ## ``task:<name>`` — force the dev-env-task tier only.
    rtqPackage    ## ``<pkg>:<name>`` — force the export-table (run-edge)
                  ## tier, qualified to owning package ``<pkg>``.

  ParsedReproRun = object
    selection: DevEnvCliSelection
    target: string
      ## Named-Runnable-Edges N1: the bare target name with any
      ## ``task:`` / ``<pkg>:`` qualifier stripped.
    rawTarget: string
      ## Named-Runnable-Edges N1: the original positional as typed
      ## (qualifier included) — the selector delegated to
      ## ``runBuildCommand`` for a ``<pkg>:<name>`` run-edge hit and the
      ## name echoed in diagnostics.
    qualifier: RunTargetQualifier
    qualifierPackage: string
      ## Named-Runnable-Edges N1: the ``<pkg>`` of an ``rtqPackage`` form.
    choose: bool
    forwardedArgs: seq[string]

  ParsedReproTasks = object
    selection: DevEnvCliSelection

proc valueFromFlag(args: openArray[string]; i: var int; flag: string): string =
  let arg = args[i]
  if arg.startsWith(flag & "="):
    return arg.split("=", maxsplit = 1)[1]
  if arg == flag:
    if i + 1 >= args.len:
      raise newException(ValueError, flag & " requires a value")
    inc i
    return args[i]
  ""

type
  ReportSpec* = object
    ## ``--write-report[=PATH]`` surface shared by every workspace verb that
    ## can persist a JSON report artifact. ``requested`` is false unless the
    ## operator asked for one — on a SUCCESSFUL run the default is to write
    ## NOTHING to disk (the ``--json`` stdout surface is independent and
    ## unaffected). A FAILED run writes its failure report unasked; see
    ## ``failureReportDestination``. ``--no-write-report`` sets
    ## ``suppressed`` and defeats both.
    requested*: bool
    path*: string
    suppressed*: bool

proc consumeReportFlag*(arg: string; spec: var ReportSpec): bool =
  ## True when ``arg`` was a ``--write-report`` / ``--write-report=PATH`` /
  ## ``--no-write-report`` flag and has been consumed into ``spec``. Callers
  ## place this branch BEFORE their generic "unsupported flag" catch-all.
  if arg == "--write-report":
    spec.requested = true
    return true
  if arg.startsWith("--write-report="):
    spec.requested = true
    spec.path = arg["--write-report=".len .. ^1]
    return true
  if arg == "--no-write-report":
    spec.suppressed = true
    return true
  false

proc workspaceReportDir*(workspaceRoot: string): string =
  ## Conventional home for workspace-wide report artifacts. Reports are
  ## derived output, so they live under the WORKSPACE ROOT's disposable
  ## ``.repro/build/`` tree rather than beside the ``.repro/workspace.toml``
  ## metadata. Note this is deliberately the workspace root's build dir and
  ## NOT ``<workspaceRoot>/<repo>/.repro/build/`` — the per-project build dir
  ## that resolves relative to a module path. Nesting disambiguates; no path
  ## hashing is needed.
  workspaceRoot / ".repro" / "build" / "reports"

proc reportDestination*(spec: ReportSpec; workspaceRoot, verb: string): string =
  ## Absolute path the FULL report must be written to, or ``""`` when no
  ## report was requested (in which case the writer is a no-op).
  if spec.suppressed or not spec.requested:
    return ""
  if spec.path.len > 0:
    return absolutePath(spec.path)
  if workspaceRoot.len == 0:
    return ""
  workspaceReportDir(workspaceRoot) / (verb & "-report.json")

proc failureReportDestination*(spec: ReportSpec; workspaceRoot, verb: string;
                               exitCode: int): string =
  ## Absolute path the FAILURE report must be written to, or ``""`` when the
  ## run succeeded or ``--no-write-report`` suppressed it. On failure the
  ## report IS the diagnostic payload, so it is written without being asked:
  ## requiring a re-run with a flag to learn why something broke asks for the
  ## flag at the worst possible moment, and a re-run may not reproduce.
  if spec.suppressed or exitCode == 0 or workspaceRoot.len == 0:
    return ""
  workspaceReportDir(workspaceRoot) / (verb & "-failure-report.json")

const WorkspaceFailureReportSchemaId* = "reprobuild.workspace.failure-report.v1"

var stagedFailureReport: tuple[spec: ReportSpec, root, verb: string,
                               document: JsonNode]

proc stageFailureReport*(spec: ReportSpec; workspaceRoot, verb: string;
                         document: JsonNode) =
  ## Records what a verb WOULD leave behind if the command turns out to have
  ## failed. The exit code is not known at the point a verb writes its
  ## report, so the decision is deferred to ``flushStagedFailureReport``,
  ## called once with the real exit code.
  stagedFailureReport = (spec, workspaceRoot, verb, document)

proc flushStagedFailureReport*(exitCode: int) =
  ## PERSIST axis, outcome-dependent default. A workspace verb that FAILED
  ## leaves its post-mortem behind without being asked; on success nothing is
  ## written unless ``--write-report`` asked for it.
  ##
  ## Unlike ``repro build``, whose failure document is independently shaped
  ## because a build can carry thousands of successful actions, a workspace
  ## report is bounded by the repo count and is already outcome-oriented, so
  ## the failure document is that report inside a failure envelope.
  if stagedFailureReport.document == nil:
    return
  let staged = stagedFailureReport
  stagedFailureReport.document = nil
  let dest = failureReportDestination(staged.spec, staged.root, staged.verb,
    exitCode)
  if dest.len == 0:
    return
  try:
    createDir(extendedPath(parentDir(dest)))
    writeFile(extendedPath(dest), $(%*{
      "schemaId": WorkspaceFailureReportSchemaId,
      "verb": staged.verb,
      "exitCode": exitCode,
      "report": staged.document
    }))
  except CatchableError:
    discard

# ---------------------------------------------------------------------------
# `repro prompt` state cache.
#
# The prompt segment is recomputed on EVERY shell render, so it must answer
# from a cheap cached fact rather than enumerating repos live. It used to
# answer from ``sync-report.json``, which is wrong twice over: a report is the
# record of one invocation and is never a source of truth, and it carries no
# way to tell a fresh record from a months-old one — so the segment could
# confidently print drift counts describing a workspace that no longer exists.
# Making the report opt-in turned that into a visible blank as well.
#
# This is a purpose-built cache instead: its own file, under the workspace
# root's disposable build dir, carrying the timestamp and the BRANCH it
# describes so the reader can say "these numbers may be stale" rather than
# quietly print the wrong ones. It is written by the commands that CHANGE
# workspace state, never by a read-only query, and the prompt still never runs
# git.
# ---------------------------------------------------------------------------

const
  PromptCacheSchema* = "reprobuild.prompt-cache.v1"
  PromptCacheMaxAgeSeconds* = 7'i64 * 24 * 60 * 60
    ## Beyond this the cache is reported STALE regardless of any other
    ## signal. There is no cheap way to notice a repo someone deleted by
    ## hand, so an absolute bound is the honest backstop: after a week the
    ## segment says "possibly stale" instead of asserting a stale number.

proc promptCachePath*(workspaceRoot: string): string =
  ## The prompt cache is NOT a report and deliberately does not live in
  ## ``reports/``: a report records one invocation and is never read back,
  ## whereas this file exists precisely to be read back. Keeping them separate
  ## is what stops ``--write-report`` from becoming load-bearing for the prompt.
  workspaceRoot / ".repro" / "build" / "prompt-cache.json"

proc writePromptCache*(workspaceRoot, verb: string;
                       repoBranches: openArray[string]) =
  ## Refresh the prompt cache after a state-changing command. ``repoBranches``
  ## is the per-repo branch the command left each checkout on (empty entries
  ## are counted as repos but never as drift).
  ##
  ## Best-effort and never raises: failing to refresh a prompt segment must not
  ## fail the command that changed the workspace.
  if workspaceRoot.len == 0:
    return
  try:
    var branch = ""
    let recorded = readWorkspaceBranch(workspaceRoot)
    if recorded.isSome:
      branch = recorded.get()
    var drift = 0
    for repoBranch in repoBranches:
      if branch.len > 0 and repoBranch.len > 0 and repoBranch != branch:
        inc drift
    let doc = %*{
      "schema": PromptCacheSchema,
      "writtenAtUnix": getTime().toUnix,
      "writtenBy": verb,
      "branch": branch,
      "repoCount": repoBranches.len,
      "driftRepos": drift,
    }
    let path = promptCachePath(workspaceRoot)
    createDir(parentDir(path))
    writeFile(path, pretty(doc, indent = 2) & "\n")
  except CatchableError:
    discard

proc appendActivitySelection(current: var string; value: string) =
  for raw in value.split(','):
    let item = raw.strip()
    if item.len == 0:
      continue
    if current.len == 0:
      current = item
    elif current.split(',').find(item) < 0:
      current.add("," & item)

proc gitDirForProjectRoot(projectRoot: string): string =
  let dotGit = projectRoot / ".git"
  if dirExists(extendedPath(dotGit)):
    return dotGit
  if fileExists(extendedPath(dotGit)):
    let content = readFile(extendedPath(dotGit)).strip()
    const prefix = "gitdir:"
    if content.normalize().startsWith(prefix):
      let raw = content[prefix.len .. ^1].strip()
      if raw.isAbsolute:
        return os.normalizedPath(raw)
      return os.normalizedPath(projectRoot / raw)
  ""

proc developOverridesMetadataPath(projectRoot: string): string =
  let gitDir = gitDirForProjectRoot(projectRoot)
  if gitDir.len > 0:
    return gitDir / "reprobuild" / "develop-overrides.json"
  projectRoot / ".repro" / "local" / "develop-overrides.json"

proc readDevelopOverrides(path: string): seq[DevelopOverrideEntry] =
  ## Read the document back. ``version`` and ``variants`` are read as well as
  ## written, and that is load-bearing rather than symmetric-for-tidiness:
  ## ``upsertDevelopOverride`` reads the whole document, edits one entry and
  ## writes all of it back, so a reader that dropped the two fields would strip
  ## them from every entry it did not touch. The damage would be silent and
  ## would surface much later as the consumer's version fallback mysteriously
  ## firing again for a sibling that had been fine.
  ##
  ## A document written before those fields existed simply has neither, which
  ## is the ordinary case and reads as the empty defaults.
  if path.len == 0 or not fileExists(extendedPath(path)):
    return @[]
  let root = parseFile(extendedPath(path))
  if root.kind != JObject or not root.hasKey("overrides"):
    return @[]
  for item in root["overrides"]:
    if item.kind != JObject:
      continue
    let node = item{"node"}.getStr()
    let localPath = item{"path"}.getStr()
    if node.len == 0 or localPath.len == 0:
      continue
    var entry = DevelopOverrideEntry(node: node, path: localPath,
      version: item{"version"}.getStr())
    let recordedVariants = item{"variants"}
    if not recordedVariants.isNil and recordedVariants.kind == JArray:
      for declared in recordedVariants:
        if declared.kind != JObject:
          continue
        var decl = DevelopOverrideVariantDecl(
          name: declared{"name"}.getStr(),
          kind: declared{"kind"}.getStr(),
          default: declared{"default"}.getStr())
        let values = declared{"values"}
        if not values.isNil and values.kind == JArray:
          for value in values:
            decl.values.add(value.getStr())
        entry.variants.add(decl)
    result.add(entry)

proc writeDevelopOverrides(path, projectRoot: string;
                           entries: openArray[DevelopOverrideEntry]) =
  var sorted = @entries
  sorted.sort(proc (a, b: DevelopOverrideEntry): int = cmp(a.node, b.node))
  var overrides = newJArray()
  for entry in sorted:
    var rendered = %*{
      "node": entry.node,
      "path": entry.path
    }
    # Both fields are written ONLY when the engine actually has them. An
    # entry it could say nothing about renders exactly as it always has, which
    # is why landing this moves no action fingerprint: today's overrides carry
    # `node` and `path` and the rendering for them is byte-unchanged.
    if entry.version.len > 0:
      rendered["version"] = %entry.version
    if entry.variants.len > 0:
      var declared = newJArray()
      for decl in entry.variants:
        var one = %*{"name": decl.name, "kind": decl.kind}
        if decl.values.len > 0:
          one["values"] = %decl.values
        if decl.default.len > 0:
          one["default"] = %decl.default
        declared.add(one)
      rendered["variants"] = declared
    overrides.add(rendered)
  let payload = %*{
    "schemaId": "reprobuild.develop-overrides.v1",
    "projectRoot": projectRoot,
    "overrides": overrides
  }
  createDir(extendedPath(parentDir(path)))
  let tmp = path & ".tmp"
  writeFile(extendedPath(tmp), pretty(payload) & "\n")
  if fileExists(extendedPath(path)):
    removeFile(extendedPath(path))
  moveFile(extendedPath(tmp), extendedPath(path))

proc findDevEnvProjectRoot(startPath: string): string

proc replacedSolvedVersion(projectRoot, dependency: string): string
  ## Forward declaration: the body needs ``committedLockPath``, which is
  ## declared with the rest of the lock plumbing far below this section.

proc siblingVariantDeclarations(checkout: string):
    seq[DevelopOverrideVariantDecl]
  ## Forward declaration: the body needs the compiled-provider probe
  ## (``solverInputsFromCompiledProvider``), which is declared far below.

proc activeProjectRootFromCwd(): string =
  result = findDevEnvProjectRoot(getCurrentDir())
  if result.len == 0:
    raise newException(ValueError,
      "repro develop requires a current project containing " &
        CanonicalProjectFileName & " (or legacy " &
        LegacyProjectFileName & ")")

proc resolveDevelopOverrideCheckout(dependency, intoPath: string): string =
  if intoPath.len == 0:
    raise newException(ValueError,
      "repro develop <dependency> requires --into=PATH for local overrides")
  let intoAbs = os.normalizedPath(absolutePath(intoPath))
  var candidates = @[intoAbs]
  let (_, tail) = splitPath(intoAbs)
  if tail != dependency:
    candidates.add(intoAbs / safePathSegment(dependency, "dependency"))
  for candidate in candidates:
    # Project-file alias: probe for either ``repro.nim`` or
    # ``reprobuild.nim``.
    if resolveProjectFile(candidate).path.len > 0:
      return os.normalizedPath(candidate)
  raise newException(IOError,
    "develop override checkout for " & dependency &
      " must already exist and contain " & CanonicalProjectFileName &
      " (or legacy " & LegacyProjectFileName & ") under " &
      candidates.join(" or "))

proc upsertDevelopOverride(projectRoot, dependency, localPath: string): string =
  ## Register (or re-point) the develop override for ``dependency``, recording
  ## everything the engine knows about the substitution it is making.
  ##
  ## Named-Lock-Files NLF-M2 left this writer emitting ``node`` and ``path``
  ## while `develop_sources.nim` read three fields, so the other two were a
  ## contract with no producer: every develop sibling on disk fell through to
  ## the `VERSION`-file source or to `EDevelopVersionUnknown`, and contributed
  ## no variants at all. Both facts are known HERE, at registration:
  ##
  ##   * the version is the identity the override REPLACES, which the
  ##     consumer's committed lock records;
  ##   * the variants are the sibling's own declarations, which its recipe
  ##     states and its compiled provider reports.
  ##
  ## Both are recomputed on every upsert, including a re-point of an existing
  ## entry: the fields describe the checkout at ``localPath``, so carrying an
  ## older entry's values across a path change would describe the wrong tree.
  result = developOverridesMetadataPath(projectRoot)
  var entries = readDevelopOverrides(result)
  let version = replacedSolvedVersion(projectRoot, dependency)
  let variants = siblingVariantDeclarations(localPath)
  var replaced = false
  for entry in entries.mitems:
    if entry.node == dependency:
      entry.path = localPath
      entry.version = version
      entry.variants = variants
      replaced = true
  if not replaced:
    entries.add(DevelopOverrideEntry(node: dependency, path: localPath,
      version: version, variants: variants))
  writeDevelopOverrides(result, projectRoot, entries)

proc devEnvActivitySegment(activity: string): string =
  safePathSegment(if activity.len > 0: activity else: "default", "default")

proc defaultDevEnvOutDir(modulePath, workRoot, activity: string): string =
  let scopedRoot = scopedWorktreeRoot(modulePath, workRoot)
  if scopedRoot.len > 0:
    return scopedRoot / "dev-env" / devEnvActivitySegment(activity)
  parentDir(modulePath) / ".repro" / "dev-env" /
    devEnvActivitySegment(activity)

proc resolveDevEnvSelection(selection: var DevEnvCliSelection) =
  if selection.selector.len == 0:
    selection.selector = "."
  if selection.activity.len == 0:
    selection.activity = "default"
  selection.modulePath = absolutePath(moduleForTarget(selection.selector))
  if not fileExists(extendedPath(selection.modulePath)):
    raise newException(IOError,
      "dev-env target module not found: " & selection.modulePath)
  selection.projectRoot = projectRootForModule(selection.modulePath)
  selection.developOverridesPath =
    developOverridesMetadataPath(selection.projectRoot)
  selection.outDir = defaultDevEnvOutDir(selection.modulePath,
    selection.workRoot, selection.activity)

proc parseDevEnvExecArgs(args: openArray[string]): ParsedDevEnvExec =
  var selection = DevEnvCliSelection()
  var afterSeparator = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if afterSeparator:
      result.command.add(arg)
    elif arg == "--":
      afterSeparator = true
    elif arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i,
        "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      selection.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported exec flag: " & arg)
    elif selection.selector.len == 0:
      selection.selector = arg
    else:
      raise newException(ValueError,
        "unexpected exec argument before --: " & arg)
    inc i
  if result.command.len == 0:
    raise newException(ValueError,
      "repro exec requires -- <command> [args...]")
  selection.resolveDevEnvSelection()
  result.selection = selection

proc parseDevEnvShellArgs(args: openArray[string]): ParsedDevEnvShell =
  var selection = DevEnvCliSelection()
  result.printFormat = depPosix
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i,
        "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      selection.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg == "--shell" or arg.startsWith("--shell="):
      result.shellPath = valueFromFlag(args, i, "--shell")
    elif arg == "--print-env" or arg.startsWith("--print-env="):
      result.printEnv = true
      result.printFormat = parseDevEnvPrintFormat(valueFromFlag(args, i,
        "--print-env"))
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported shell flag: " & arg)
    elif selection.selector.len == 0:
      selection.selector = arg
    else:
      raise newException(ValueError,
        "unexpected shell argument: " & arg)
    inc i
  selection.resolveDevEnvSelection()
  result.selection = selection

proc parseReproRunArgs(args: openArray[string]): ParsedReproRun =
  var selection = DevEnvCliSelection()
  var afterSeparator = false
  var rawTarget = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if afterSeparator:
      result.forwardedArgs.add(arg)
    elif arg == "--":
      afterSeparator = true
    elif arg == "--choose":
      result.choose = true
    elif arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i, "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      selection.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported run flag: " & arg)
    elif rawTarget.len == 0:
      rawTarget = arg
    else:
      raise newException(ValueError, "unexpected run argument before --: " & arg)
    inc i

  # Named-Runnable-Edges N1: the dev-env edge is always computed against
  # the current project (``.``) — a ``<pkg>:<name>`` qualifier disambiguates
  # the export-table resolution, NOT the project anchor, so it must not be
  # fed to ``moduleForTarget`` (which would treat ``<pkg>`` as a sibling
  # checkout path and fail). The raw positional is kept verbatim for the
  # run-edge delegation + diagnostics.
  selection.selector = "."
  result.rawTarget = rawTarget
  if rawTarget.len > 0:
    if rawTarget.contains('/') or rawTarget.contains('\\') or
        rawTarget.startsWith("."):
      # A path/fragment positional stays as-is (dev-env task fallback keeps
      # today's behaviour); no qualifier applies.
      result.target = rawTarget
      result.qualifier = rtqNone
    else:
      let colonIdx = rawTarget.find(':')
      if colonIdx > 0 and colonIdx < rawTarget.high:
        let lhs = rawTarget[0 ..< colonIdx]
        let rhs = rawTarget[colonIdx + 1 .. ^1]
        if lhs == "task":
          result.qualifier = rtqTask
          result.target = rhs
        else:
          result.qualifier = rtqPackage
          result.qualifierPackage = lhs
          result.target = rhs
      else:
        result.qualifier = rtqNone
        result.target = rawTarget

  selection.resolveDevEnvSelection()
  result.selection = selection

proc parseReproTasksArgs(args: openArray[string]): ParsedReproTasks =
  var selection = DevEnvCliSelection()
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i, "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      selection.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported tasks flag: " & arg)
    elif selection.selector.len == 0:
      selection.selector = arg
    else:
      raise newException(ValueError, "unexpected tasks argument: " & arg)
    inc i
  selection.resolveDevEnvSelection()
  result.selection = selection

proc publicDevEnvMonitor(publicCliPath: string):
    tuple[path: string, args: seq[string]] =
  ## Executable-Consolidation M1: the dev-env monitor self-spawns the ``repro``
  ## image (``internal io monitor`` selector returned in ``args``, threaded via
  ## ``DevEnvEdgeConfig.monitorCliArgs``) rather than locating a standalone
  ## monitor binary.
  (selfSpawnIoMonitorPath(publicCliPath), internalIoMonitorArgs)

proc computePublicDevEnv(selection: DevEnvCliSelection;
                         publicCliPath: string;
                         renderShell = false): DevEnvEdgeResult =
  let monitor = publicDevEnvMonitor(publicCliPath)
  computeDevEnvEdge(DevEnvEdgeConfig(
    modulePath: selection.modulePath,
    projectRoot: selection.projectRoot,
    outDir: selection.outDir,
    workDir: reprobuildLibraryWorkDir(),
    publicCliPath: publicCliPath,
    monitorCliPath: monitor.path,
    monitorCliArgs: monitor.args,
    monitorShimLibPath: resolveMonitorShimLibPath(),
    activity: selection.activity,
    lockSliceId: selection.lockSliceId,
    developOverridesPath: selection.developOverridesPath,
    renderShell: renderShell,
    statsEnabled: selection.statsPath.len > 0))

proc devEnvPerformanceEvidenceJson(edge: DevEnvEdgeResult): JsonNode =
  let devStats = edge.devEnvResult.stats
  let compileStats = edge.providerCompileResult.stats
  let introspectionInputs = edge.introspectionAction.evidence.evidenceInputCount()
  let shellInputs = edge.shellRenderAction.evidence.evidenceInputCount()
  let shellRenderPresent = edge.shellRenderAction.actionPresent()
  %*{
    "schemaId": "reprobuild.dev-env.performance-evidence.v1",
    "providerBuild": {
      "checks": 1,
      "launched": edge.stats.providerBuildLaunched,
      "skippedFresh": edge.stats.providerBuildSkippedFresh,
      "cacheHit": edge.stats.providerBuildCacheHit,
      "actionPresent": edge.providerCompileAction.actionPresent(),
      "actionStatus": $edge.providerCompileAction.status,
      "cacheLookupCount": compileStats.metricCount("repro cache lookup"),
      "cacheLookupTotalUs": compileStats.metricTotalUs("repro cache lookup"),
      "hotInputScanCount": compileStats.metricCount("repro hot input scan"),
      "outputStatCount": compileStats.metricCount("repro output stat"),
      "runBuildTotalUs": compileStats.metricTotalUs("repro scheduler total")
    },
    "providerIntrospection": {
      "actions": 1,
      "launched": edge.stats.providerIntrospectionLaunched,
      "cacheHit": edge.stats.providerIntrospectionCacheHit,
      "actionStatus": $edge.introspectionAction.status,
      "cacheDecision": $edge.introspectionAction.cacheDecision,
      "evidenceInputPathCount": introspectionInputs,
      "declaredInputCount": edge.introspectionAction.evidence.declaredInputs.len,
      "monitorReadCount": edge.introspectionAction.evidence.monitorReads.len,
      "monitorProbeCount": edge.introspectionAction.evidence.monitorProbes.len
    },
    "artifactLookup": {
      "artifactPath": edge.artifactPath,
      "artifactBytes": edge.artifactPath.fileSizeOrZero(),
      "artifactWriteLaunched": edge.stats.artifactWriteLaunched,
      "artifactWriteSkipped": edge.stats.artifactWriteSkipped,
      "introspectionCacheHit": edge.stats.providerIntrospectionCacheHit
    },
    "invalidation": {
      "cacheLookupCount": devStats.metricCount("repro cache lookup"),
      "cacheLookupTotalUs": devStats.metricTotalUs("repro cache lookup"),
      "hotRecordLookupCount": devStats.metricCount("repro hot record lookup"),
      "hotRecordLookupTotalUs": devStats.metricTotalUs("repro hot record lookup"),
      "hotInputScanCount": devStats.metricCount("repro hot input scan"),
      "hotInputScanTotalUs": devStats.metricTotalUs("repro hot input scan"),
      "fastNoopScanCount": devStats.metricCount("repro fast noop scan"),
      "fastNoopScanTotalUs": devStats.metricTotalUs("repro fast noop scan"),
      "outputStatCount": devStats.metricCount("repro output stat"),
      "checkedInputPathCount": introspectionInputs + shellInputs,
      "cacheHitResultMaterializeCount":
        devStats.metricCount("repro cache hit result materialize")
    },
    "shellRender": {
      "actions": if shellRenderPresent: 1 else: 0,
      "launched": edge.stats.shellRenderingLaunched,
      "cacheHit": edge.stats.shellRenderingCacheHit,
      "skipped": edge.stats.shellRenderingSkipped,
      "actionStatus": $edge.shellRenderAction.status,
      "cacheDecision": $edge.shellRenderAction.cacheDecision,
      "evidenceInputPathCount": shellInputs,
      "shellFragmentPath": edge.shellFragmentPath,
      "shellFragmentBytes": edge.shellFragmentPath.fileSizeOrZero(),
      "navigatorStatsPath": edge.shellNavigatorStatsPath,
      "navigatorStatsBytes": edge.shellNavigatorStatsPath.fileSizeOrZero()
    }
  }

proc devEnvStatsJson(edge: DevEnvEdgeResult; commandName: string): JsonNode =
  let navigatorStats =
    if edge.shellNavigatorStatsPath.len > 0 and fileExists(
        extendedPath(edge.shellNavigatorStatsPath)):
      parseFile(extendedPath(edge.shellNavigatorStatsPath))
    else:
      newJNull()
  %*{
    "schemaId": "reprobuild.dev-env.cli-stats.v1",
    "command": commandName,
    "artifactPath": edge.artifactPath,
    "shellFragmentPath": edge.shellFragmentPath,
    "shellNavigatorStatsPath": edge.shellNavigatorStatsPath,
    "shellNavigatorStats": navigatorStats,
    "providerArtifactPath": edge.providerArtifactPath,
    "providerBinaryPath": edge.providerBinaryPath,
    "providerArtifactId": edge.providerArtifactId,
    "stats": {
      "providerBuildLaunched": edge.stats.providerBuildLaunched,
      "providerBuildSkippedFresh": edge.stats.providerBuildSkippedFresh,
      "providerBuildCacheHit": edge.stats.providerBuildCacheHit,
      "providerIntrospectionLaunched": edge.stats.providerIntrospectionLaunched,
      "providerIntrospectionCacheHit": edge.stats.providerIntrospectionCacheHit,
      "artifactWriteLaunched": edge.stats.artifactWriteLaunched,
      "artifactWriteSkipped": edge.stats.artifactWriteSkipped,
      "shellRenderingLaunched": edge.stats.shellRenderingLaunched,
      "shellRenderingCacheHit": edge.stats.shellRenderingCacheHit,
      "shellRenderingSkipped": edge.stats.shellRenderingSkipped
    },
    "providerCompileAction": actionResultJson(edge.providerCompileAction),
    "introspectionAction": actionResultJson(edge.introspectionAction),
    "shellRenderAction": actionResultJson(edge.shellRenderAction),
    "providerCompileRunStats": statsJson(edge.providerCompileResult.stats),
    "devEnvRunStats": statsJson(edge.devEnvResult.stats),
    "performance": devEnvPerformanceEvidenceJson(edge)
  }

proc writeDevEnvStats(path: string; edge: DevEnvEdgeResult;
                      commandName: string) =
  if path.len == 0:
    return
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), $devEnvStatsJson(edge, commandName) & "\n")

proc emitDevEnvDiagnostics(artifact: DevEnvArtifact): bool =
  ## Returns true when an error diagnostic was emitted.
  for diagnostic in artifact.diagnostics:
    if diagnostic.severity == dedsInfo:
      continue
    let prefix =
      case diagnostic.severity
      of dedsInfo: "info"
      of dedsWarning: "warning"
      of dedsError: "error"
    stderr.writeLine("repro dev-env: " & prefix & ": " &
      diagnostic.message)
    if diagnostic.severity == dedsError:
      result = true

proc runTaskCommand(artifact: DevEnvArtifact; artifactPath: string;
                    task: DevEnvTaskSummary; forwardedArgs: seq[string];
                    defaultWorkingDirectory: string): int =
  when defined(windows):
    let shellLine =
      if forwardedArgs.len > 0:
        task.command & " " & forwardedArgs.mapIt(quoteShell(it)).join(" ")
      else:
        task.command
    let activation = activatedEnvironment(artifact, artifactPath, defaultWorkingDirectory)
    let cmdExe = getEnv("COMSPEC", "cmd.exe")
    var process = startProcess(cmdExe,
      args = @["/c", shellLine],
      env = activation.env,
      workingDir = activation.workingDirectory,
      options = {poUsePath, poParentStreams})
    result = process.waitForExit()
    process.close()
  else:
    let activation = activatedEnvironment(artifact, artifactPath, defaultWorkingDirectory)
    let shellPath = getEnv("SHELL", "/bin/sh")
    let shellLine = task.command & " \"$@\""
    var childArgs = @["-c", shellLine, "--"]
    for arg in forwardedArgs:
      childArgs.add(arg)
    var process = startProcess(shellPath,
      args = childArgs,
      env = activation.env,
      workingDir = activation.workingDirectory,
      options = {poUsePath, poParentStreams})
    result = process.waitForExit()
    process.close()

type
  GraphOutputFormat = enum
    gofText
    gofJson
    gofDot

  BuildGraphInspection = object
    ## Named-Targets M5 build-graph inspection record. Defined here (ahead
    ## of ``prepareBuildGraphInspection`` and the graph/build surfaces that
    ## consume it) so the Named-Runnable-Edges N1 ``repro run`` resolver —
    ## which sits earlier in the file — can forward-declare
    ## ``prepareBuildGraphInspection`` with this return type in scope.
    target: string
    modulePath: string
    projectRoot: string
    outDir: string
    interfacePath: string
    toolProvisioning: ToolProvisioningMode
    toolIdentityPath: string
    toolInspectionPath: string
    providerBinaryPath: string
    providerCompileArtifactPath: string
    providerArtifactId: string
    providerGraphSnapshotPath: string
    providerInvocations: int
    providerCompileCacheHit: bool
    providerGraphCacheHit: bool
    loweredGraphCachePath: string
    loweredGraphCacheHit: bool
    selectedActionId: string
    defaultActionId: string
    actions: seq[BuildAction]
    pools: seq[BuildPool]
    targetExportTable: TargetExportTable
      ## Named-Targets M5: cross-fragment aggregate of every package's
      ## ``reprobuild.target-export-table.v1`` metadata node. Populated by
      ## ``prepareBuildGraphInspection`` and used by ``runGraphCommand``
      ## / ``runWhyCommand`` / ``--list-targets`` so the inspection
      ## surface honours implicit / explicit target names without a
      ## second pass over the snapshot.
    explicitTargetNames: seq[string]
      ## Named-Targets M5: every explicit ``target "name", handle`` label
      ## visible in the lowered graph, captured before lowering so
      ## ``resolveTargetExportSelector`` can pass it through.
    snapshot: ProviderGraphSnapshot
      ## Workspace-Manifest-Optional MO-6: the (possibly extension-merged)
      ## provider-graph snapshot this inspection lowered. Exposed so
      ## ``mergeProjectExtensions`` can reuse this proc to compile + evaluate
      ## a discovered ``projectExtension`` recipe and harvest its fragments.

# Named-Runnable-Edges N1 forward declarations: ``repro run`` resolves a
# named run-edge/build target through the SAME target-export-table
# resolver ``repro build`` uses (``prepareBuildGraphInspection`` +
# ``resolveTargetExportSelector``) and delegates its execution to
# ``runBuildCommand`` (which materializes the closure and, for a run-edge,
# runs it — exactly as ``repro build <run-edge-name>`` does today). The
# definitions all live further down the file; forward-declare them here so
# the ``run`` command can call them (mirroring the M5 ``runListTargetsCommand``
# forward declaration at the top of the build surface).
proc prepareBuildGraphInspection(target: string; mode: ToolProvisioningMode;
                                 publicCliPath: string;
                                 selectDefaultAction = false;
                                 workRoot = "";
                                 forceRefresh = false;
                                 mergeExtensions = true;
                                 includeDevEnvOnlyProvider = false;
                                 lowerGraph = true;
                                 selectedActionOverride = ""):
                                   BuildGraphInspection

proc startAutoRunQuotaIfNeeded(bypassRunQuota: bool;
                               extraPools: openArray[BuildPool] = []):
    owned(Process)

proc runBuildCommand(args: openArray[string]; publicCliPath: string;
                     forceDirect = false;
                     daemonHosted = false;
                     eventSink: BuildCommandEventSink = nil;
                     cancelCheck: BuildCancelCallback = nil): int

type
  RunTargetResolution = object
    ## Named-Runnable-Edges N1: the outcome of resolving a ``repro run``
    ## positional against the project's target-export table (the second
    ## resolution tier, after dev-env tasks). Mirrors the ``repro build``
    ## resolver's ``trkResolved/trkAmbiguous/trkUnknown`` outcomes plus the
    ## run-edge-vs-artifact distinction the ``run`` verb needs.
    record: TargetResolutionRecord
    entryKind: TargetExportKind
    hasEntry: bool
    entry: TargetExportEntry
      ## Named-Runnable-Edges N2: the resolved ``tekRunEdge`` row itself, so
      ## the leased-consumes bridge can read its ``consumes`` list without a
      ## second table lookup. Meaningful only when ``hasEntry`` and
      ## ``entryKind == tekRunEdge``.
    resources: seq[ResourceInstance]
      ## Named-Runnable-Edges N2: the project-scoped resource-lane graph
      ## (``aggregateResourceGraph``) — the ``stateGroup`` member resources
      ## the bridge reconciles. Empty when the project declares none.
    groups: seq[StateGroupDef]
      ## Named-Runnable-Edges N2: the ``stateGroup`` membership records.
    providerArtifacts: seq[tuple[typeId: string;
                                 artifact: ResourceProviderArtifactRef]]
      ## Named-Runnable-Edges N3b: the per-typeId provider-artifact refs
      ## harvested from the resource-graph metadata. The bridge builds the
      ## out-of-tree session resolver from these. Empty when every member is
      ## in-tree (the in-process fast path).

proc runEdgeExportEntries(publicCliPath: string):
    seq[TargetExportEntry] =
  ## Named-Runnable-Edges N1: the project's named run-edge rows
  ## (``tekRunEdge``), sorted by ``(package, name)`` for deterministic
  ## listing. Best-effort: a project with no recipe / no export table
  ## yields an empty seq so ``repro run`` listing degrades to the
  ## dev-env-task-only view rather than erroring.
  let info =
    try:
      prepareBuildGraphInspection(".", tpmPathOnly, publicCliPath,
        selectDefaultAction = false, lowerGraph = false)
    except CatchableError:
      return @[]
  for entry in info.targetExportTable.entries:
    if entry.kind == tekRunEdge:
      result.add(entry)
  result.sort(proc(a, b: TargetExportEntry): int =
    let pkgCmp = cmp(a.owningPackage, b.owningPackage)
    if pkgCmp != 0: pkgCmp else: cmp(a.name, b.name))

proc inspectDevEnvTasks(selection: DevEnvCliSelection;
                        publicCliPath: string): seq[DevEnvTaskSummary] =
  ## Task listing reads provider metadata without provisioning the dev env.
  let info = prepareBuildGraphInspection(selection.selector, tpmPathOnly,
    publicCliPath, selectDefaultAction = false, workRoot = selection.workRoot,
    includeDevEnvOnlyProvider = true, lowerGraph = false)
  if info.providerBinaryPath.len == 0 or info.providerArtifactId.len == 0:
    return @[]

  let provider = ProviderExecutionConfig(
    binaryPath: info.providerBinaryPath,
    workingDir: info.projectRoot,
    tempRoot: info.outDir / "provider-task-inspection")
  let manifest = readProviderManifest(provider, info.providerArtifactId)
  var entryPointId = ""
  for descriptor in manifest.entryPoints:
    if descriptor.kind == gpkDevEnvIntrospection:
      entryPointId = descriptor.id
      break
  if entryPointId.len == 0:
    return @[]

  let devEnv = invokeProviderDevEnvIntrospection(provider,
    info.providerArtifactId, info.projectRoot,
    entryPointId = entryPointId,
    activity = selection.activity,
    lockSliceId = selection.lockSliceId)
  for task in devEnv.tasks:
    result.add(DevEnvTaskSummary(
      name: task.name,
      description: task.description,
      activityRequirements: task.activityRequirements,
      command: task.command))

proc resolveRunTarget(parsed: ParsedReproRun;
                      publicCliPath: string): RunTargetResolution =
  ## Named-Runnable-Edges N1: resolve the ``repro run`` positional against
  ## the target-export table the same way ``repro build`` /
  ## ``runGraphCommand`` do (``resolveTargetExportSelector`` over the
  ## aggregated table + the lowered graph's action ids + explicit target
  ## names). ``selector`` is the qualified form for a ``<pkg>:<name>``
  ## invocation so cross-package disambiguation reuses the M5 path.
  let selector =
    if parsed.qualifier == rtqPackage:
      parsed.qualifierPackage & ":" & parsed.target
    else:
      parsed.target
  let info = prepareBuildGraphInspection(".", tpmPathOnly, publicCliPath,
    selectDefaultAction = false, lowerGraph = false)
  var actionIds: seq[string] = @[]
  for action in info.actions:
    actionIds.add(action.id)

  # A same-name artifact is not a runnable candidate, while multiple matching
  # run edges remain an ambiguity for the shared selector resolver.
  var resolutionTable = info.targetExportTable
  var explicitTargetNames = info.explicitTargetNames
  var matchingRunEntries: seq[TargetExportEntry] = @[]
  for entry in info.targetExportTable.entries:
    if entry.kind == tekRunEdge and entry.name == parsed.target and
        (parsed.qualifier != rtqPackage or
         entry.owningPackage == parsed.qualifierPackage):
      matchingRunEntries.add(entry)
  if matchingRunEntries.len > 0:
    resolutionTable.entries = matchingRunEntries
    resolutionTable.ambiguities = @[]
    explicitTargetNames.setLen(0)
  result.record = resolveTargetExportSelector(resolutionTable,
    actionIds, explicitTargetNames, selector)
  if result.record.kind == trkResolved:
    result.entryKind = result.record.targetKind
    result.hasEntry = true
    for entry in info.targetExportTable.entries:
      if entry.kind == tekRunEdge and
          entry.actionId == result.record.actionId and
          (entry.name == parsed.target or
           (parsed.qualifier == rtqPackage and
            entry.owningPackage == parsed.qualifierPackage and
            entry.name == parsed.target)):
        result.entry = entry
        break
    let aggregated = aggregateResourceGraph(info.snapshot)
    result.resources = aggregated.resources
    result.groups = aggregated.groups
    result.providerArtifacts = aggregated.providerArtifacts

proc emitMergedRunListing(tasks: seq[DevEnvTaskSummary];
                          runEdges: seq[TargetExportEntry]) =
  ## Named-Runnable-Edges N1: the merged ``repro run`` / ``repro run
  ## --choose`` / ``repro tasks`` listing — dev-env tasks AND named
  ## run-edges, each labelled by source (``[task]`` / ``[run-edge]``), in
  ## a deterministic order (tasks then run-edges, each already sorted by
  ## name). Spec §5.
  if tasks.len == 0 and runEdges.len == 0:
    echo "No tasks or run-edges declared in this project."
    return
  echo "Available targets:"
  var sortedTasks = tasks
  sortedTasks.sort(proc(a, b: DevEnvTaskSummary): int = cmp(a.name, b.name))
  for task in sortedTasks:
    let desc = if task.description.len > 0: "  - " & task.description else: ""
    echo "  [task]     ", task.name, desc
  for entry in runEdges:
    echo "  [run-edge] ", entry.name

type
  RunConsumesBridgeResult* = object
    ## Named-Runnable-Edges N2: the outcome of reconciling a consuming run-
    ## edge's leased ``stateGroup``s before the exec. Purely observational —
    ## the store write is the correctness source of truth; the daemon renew
    ## is best-effort. Surfaced for the hermetic bridge tests + a diagnostic.
    reconciled*: seq[ReconcileResult]     ## one per consumed group, in order
    renewedGroups*: seq[string]           ## group addresses a renew was forwarded for
    missingGroups*: seq[string]           ## consumed names with no ``stateGroup`` / no members
    daemonSent*: seq[string]              ## group addresses whose renew reached a daemon

proc buildStateGroupDesired*(lease: RunEdgeLease;
                             runEdgeName: string;
                             resources: seq[ResourceInstance];
                             groups: seq[StateGroupDef]):
    seq[ResourceInstance] =
  ## Named-Runnable-Edges N2: assemble the desired graph the reconciler drives
  ## for ONE consumed ``leased(group, policy)`` edge:
  ##
  ##   * the group's member ``ResourceInstance``s (the leased states to
  ##     materialize-or-reuse), resolved from the project resource graph by the
  ##     ``stateGroup`` membership; plus
  ##   * a synthetic CONSUMER instance whose ``consumes`` targets every member
  ##     under ``runEdgeName`` (the run-edge's stable name is the holder id, per
  ##     spec §7) and the lease's policy — the edge the store-backed reconcile
  ##     renews. This mirrors the L3 reaper tests' materialize helper (a state +
  ##     a separate consumer that ``consumes`` it), reusing the landed lease
  ##     renewal path verbatim.
  ##
  ## Returns an empty seq when the group is unknown / has no members present in
  ## the graph, so a consuming edge whose group is not declared runs with no
  ## reconcile (the N1 no-lease path) rather than erroring.
  var members: seq[string] = @[]
  for g in groups:
    if g.name == lease.address:
      members = g.members
      break
  # Fallback: a leased address that names a resource directly (not a group)
  # still reconciles as a one-member group.
  if members.len == 0:
    for inst in resources:
      if inst.address == lease.address:
        members = @[lease.address]
        break
  if members.len == 0:
    return @[]
  var byAddr = initTable[string, ResourceInstance]()
  for inst in resources:
    byAddr[inst.address] = inst
  var present: seq[string] = @[]
  for m in members:
    if byAddr.hasKey(m):
      result.add(byAddr[m])
      present.add(m)
  if present.len == 0:
    return @[]
  # The synthetic consumer: one leased edge per member, all held by the run-
  # edge's stable name under the declared policy. The consumer resource itself
  # carries a never-reap (keep) record and is skipped by the reaper.
  let policy = toLeasedDep(lease).policy
  var consumes: seq[LeasedDep] = @[]
  for m in present:
    consumes.add(leased(m, runEdgeName, policy))
  result.add(ResourceInstance(
    typeId: RunEdgeConsumerTypeId,
    address: runEdgeName & "::consumes::" & lease.address,
    attrs: TypedExtensionBox[RunEdgeConsumerAttrs](
      typeId: RunEdgeConsumerTypeId,
      val: RunEdgeConsumerAttrs(runEdge: runEdgeName, group: lease.address)),
    dependsOn: @[],
    determinism: rdVolatile,
    consumes: consumes))

proc anyMemberUnlinked(desired: seq[ResourceInstance]): bool =
  ## True when ANY member of the desired group's graph has a ``typeId`` whose
  ## driver is NOT registered in this process — i.e. an OUT-OF-TREE resource
  ## (a vm-harness Incus type the ``repro`` CLI does not link). The synthetic
  ## run-edge-consumer type is always linked, so a group whose real members are
  ## all in-tree returns false and keeps the in-process fast path.
  for inst in desired:
    if not isResourceProviderRegistered(inst.typeId):
      return true
  false

proc reconcileConsumedStateGroups*(consumes: seq[RunEdgeLease];
                                   runEdgeName: string;
                                   resources: seq[ResourceInstance];
                                   groups: seq[StateGroupDef];
                                   store: StateStore;
                                   scope: DaemonLeaseScope = dlsUser;
                                   endpoint = defaultUserDaemonEndpoint();
                                   now: Time = getTime();
                                   sessionResolver: ResourceSessionResolver = nil):
    RunConsumesBridgeResult =
  ## Named-Runnable-Edges N2 — the build↔resource bridge (spec §3.2). For each
  ## ``leased(group, policy)`` the run-edge consumes: materialize-or-reuse the
  ## group against the L1 store (``reconcileResources`` — first run stands it
  ## up; a re-run whose digest matches REUSES it, no re-apply) and renew the
  ## lease to the scope's daemon (``renewLeaseBestEffort`` via
  ## ``reconcileLeasedResources``; no-daemon-safe, never raises). The run-edge's
  ## stable name is the ``consumerId``. ``immediate`` / ``delayed(ttl)`` /
  ## ``keep`` are honored verbatim by the landed reference-counted MAX /
  ## keep-dominates fold — this bridge only assembles the desired graph and
  ## delegates.
  ##
  ## Reaping is NOT done here — the L4 daemon wall-clock tick / L5 provider
  ## session (or ``repro reap`` / the reconcile-start opportunistic reap)
  ## destroys idle groups. Correctness is independent of the daemon: the store
  ## write is the source of truth.
  ##
  ## Driver resolution (N3a). Per consumed group the bridge picks the
  ## materialize path by whether the group's members are LINKED in this process:
  ##
  ##   * ALL members linked (an in-tree ``stateGroup`` / the N2 hermitic mock)
  ##     — the IN-PROCESS ``reconcileResources(store)`` fast path, byte-identical
  ##     to N2.
  ##   * ANY member OUT-OF-TREE (a vm-harness Incus type the ``repro`` CLI does
  ##     not link) — the PROVIDER-SESSION path
  ##     ``reconcileResourcesViaSession(store)``, the same artifact-backed
  ##     resolver the L5 daemon reaper uses via ``buildLeaseReapTransport``. The
  ##     out-of-tree members' ``observe/digest/apply`` run in the provider over
  ##     the session (no driver linked here); the synthetic run-edge-consumer
  ##     type — always linked, lease bookkeeping only, no provider binary — runs
  ##     in-process via the ``inProcess = isResourceProviderRegistered`` hybrid
  ##     gate, in the SAME pass so its ``consumes`` edges drive the members'
  ##     store-backed reuse/renew. The store write is the source of truth in
  ##     BOTH paths; the daemon renew (L4) is a best-effort notify.
  ##
  ## ``sessionResolver`` (non-nil) supplies the launched provider session for an
  ## out-of-tree ``typeId`` — a hermetic test injects one over a mock provider
  ## binary; production wires it from the pooled provider artifacts (the same
  ## discovery the reaper transport uses). When a group has an out-of-tree
  ## member but no ``sessionResolver`` is available, the member is recorded in
  ## ``missingGroups`` rather than hard-erroring (the run proceeds without the
  ## unreconcilable state — a clear diagnostic, not a crash).
  for lease in consumes:
    let desired = buildStateGroupDesired(lease, runEdgeName, resources, groups)
    if desired.len == 0:
      result.missingGroups.add(lease.address)
      continue
    # Materialize-or-reuse against the L1 store (the correctness source of
    # truth — L2 reuse-on-digest-match / renew), then forward a best-effort
    # daemon renew (L4). We drive the two steps ourselves rather than
    # ``reconcileLeasedResources`` so we can observe whether the renew reached a
    # daemon (``sent``) without a second redundant renew.
    let outcome =
      if anyMemberUnlinked(desired):
        # OUT-OF-TREE members: reconcile over the provider session WITH the
        # store, routing the always-linked synthetic consumer in-process.
        if sessionResolver == nil:
          result.missingGroups.add(lease.address)
          continue
        reconcileResourcesViaSession(desired, sessionResolver,
          store = some(store), now = now,
          inProcess = proc (typeId: string): bool =
            # Hybrid routing (spec §3.2): the always-linked synthetic run-edge
            # consumer (registered in THIS process, no provider binary) runs
            # in-process; the out-of-tree member types the CLI does not link go
            # over the session. This is the ``isResourceProviderRegistered``
            # gate the reconcile doc describes — and it lets the production
            # ``sessionResolver`` map ONLY the real out-of-tree typeIds (the
            # provider-artifact refs the resource-graph carries), never the
            # synthetic consumer.
            isResourceProviderRegistered(typeId))
      else:
        reconcileResources(desired, store = some(store), now = now)
    result.reconciled.add(outcome)
    result.renewedGroups.add(lease.address)
    for edge in renewLeasesForConsumed(desired, scope, endpoint):
      if edge.sent and lease.address notin result.daemonSent:
        result.daemonSent.add(lease.address)

# ---------------------------------------------------------------------------
# Named-Runnable-Edges N3b — auto-build the out-of-tree session resolver.
#
# ``reconcileConsumedStateGroups`` takes a ``sessionResolver`` that a hermetic
# test injects; in production ``repro run`` must construct it itself from the
# provider-artifact refs the resource-graph metadata carries (N3b). This is the
# CLI-side twin of the daemon reaper's ``buildLeaseReapTransport``
# (``lease_registry.nim``): a per-typeId ``ProviderArtifactRef`` registry drives
# a pooled resolver — one launched session per artifact id, reused across the
# reconcile pass. The daemon reaper opens sessions from ``leaseReapProviders``;
# here the same shape is fed from the run-edge's harvested provider artifacts.
# ---------------------------------------------------------------------------

proc runEdgeSessionEngineHello(): EngineHello =
  ## The engine handshake ``repro run`` opens out-of-tree member sessions with
  ## — the CLI analog of ``leaseReapEngineHello``.
  EngineHello(
    protocolVersion: ProviderProtocolVersion,
    engineCapabilities: @["named-run-edge-consumes"],
    lockSliceId: "run-edge-consumes",
    canonicalExecutionRoot: getCurrentDir())

proc buildRunEdgeSessionResolver*(
    providerArtifacts: openArray[tuple[typeId: string;
                                       artifact: ResourceProviderArtifactRef]];
    pool: ProviderSessionPool):
    ResourceSessionResolver =
  ## Build the ``ResourceSessionResolver`` ``reconcileConsumedStateGroups`` uses
  ## for an out-of-tree member, from the harvested per-typeId provider artifacts
  ## — mirroring ``buildLeaseReapTransport``'s ``rtSession`` resolver. Returns
  ## ``nil`` when no artifact is registered (all-in-tree ⇒ the in-process fast
  ## path stays; the bridge records a still-out-of-tree member as missing rather
  ## than crashing). ``pool`` is the caller-owned ``ProviderSessionPool`` (closed
  ## after the run) so a session per artifact id is launched once and reused.
  if providerArtifacts.len == 0:
    return nil
  var byType = initTable[string, ResourceProviderArtifactRef]()
  for pa in providerArtifacts:
    byType[pa.typeId] = pa.artifact
  result = proc (typeId: string): ProviderHandle =
    if not byType.hasKey(typeId):
      raise newException(ValueError,
        "no provider artifact registered for out-of-tree resource type " &
        typeId)
    let a = byType[typeId]
    let artifact = ProviderArtifactRef(
      binaryPath: a.binaryPath,
      providerArtifactId: a.providerArtifactId,
      workingDir: a.workingDir)
    pool.openProviderSession(artifact, defaultSessionPolicy(),
      runEdgeSessionEngineHello())

proc runReproRunCommand(args: openArray[string];
                        publicCliPath: string): int =
  let parsed = parseReproRunArgs(args)
  var listedTasks = inspectDevEnvTasks(parsed.selection, publicCliPath)
  if parsed.selection.statsPath.len > 0:
    let edge = computePublicDevEnv(parsed.selection, publicCliPath)
    writeDevEnvStats(parsed.selection.statsPath, edge, "run")
    let artifact = readDevEnvArtifact(edge.artifactPath)
    if emitDevEnvDiagnostics(artifact):
      return 1
    listedTasks = artifact.tasks

  # Named-Runnable-Edges N1: bare ``repro run`` / ``--choose`` lists BOTH
  # dev-env tasks and named run-edges, source-labelled (spec §5). The
  # run-edge rows come from the same target-export table ``repro build``
  # resolves against.
  if parsed.target.len == 0 or parsed.choose:
    emitMergedRunListing(listedTasks, runEdgeExportEntries(publicCliPath))
    return 0

  # Tier 1 — dev-env task (today's behaviour, unchanged). A ``task:<name>``
  # qualifier forces this tier only; a ``<pkg>:<name>`` qualifier skips it
  # (it explicitly names an export-table row).
  var matchingTask: Option[DevEnvTaskSummary]
  if parsed.qualifier != rtqPackage:
    for task in listedTasks:
      if task.name == parsed.target:
        matchingTask = some(task)
        break

  if matchingTask.isSome:
    # Named-Runnable-Edges N1 (spec §7): a bare name colliding between a
    # dev-env task and a run-edge prefers the task, with a warning naming
    # the qualifier to disambiguate. Only warn for the bare form — an
    # explicit ``task:`` qualifier is already unambiguous.
    if parsed.qualifier == rtqNone:
      let runResolution = resolveRunTarget(parsed, publicCliPath)
      if runResolution.hasEntry and runResolution.entryKind == tekRunEdge:
        stderr.writeLine("repro run: warning: '" & parsed.target &
          "' names both a dev-env task and a run-edge; running the task. " &
          "Use 'task:" & parsed.target & "' or '<package>:" & parsed.target &
          "' to disambiguate.")
    let edge = computePublicDevEnv(parsed.selection, publicCliPath)
    writeDevEnvStats(parsed.selection.statsPath, edge, "run")
    let artifact = readDevEnvArtifact(edge.artifactPath)
    if emitDevEnvDiagnostics(artifact):
      return 1
    var task = matchingTask.get()
    for activeTask in artifact.tasks:
      if activeTask.name == parsed.target:
        task = activeTask
        break
    return runTaskCommand(artifact, edge.artifactPath, task,
      parsed.forwardedArgs, parsed.selection.projectRoot)

  if parsed.qualifier == rtqTask:
    # ``task:<name>`` explicitly requested the task tier, but no task
    # matched — do NOT silently fall through to a run-edge.
    stderr.writeLine("repro run: error: no dev-env task named '" &
      parsed.target & "'.")
    return 2

  # Tier 2 — named run-edge / build target in the project's target-export
  # table (the same resolver ``repro build`` uses). On a run-edge hit,
  # delegate execution to ``runBuildCommand`` with an explicit name
  # selector: the build engine materializes the edge's dependency closure
  # and, because the edge's action is an execution, RUNS it — precisely
  # what ``repro build <run-edge-name>`` already does. Trailing ``-- args``
  # are forwarded to ``repro build`` after ``--``.
  #
  # Named-Runnable-Edges N2: a run-edge that declares ``consumes`` (leased
  # ``stateGroup``s) now RECONCILES + RENEWS them before the exec (spec §3.2) —
  # see the bridge below.
  let resolution = resolveRunTarget(parsed, publicCliPath)
  case resolution.record.kind
  of trkResolved:
    if resolution.entryKind == tekRunEdge or
        resolution.entryKind == tekCollection:
      # Named-Runnable-Edges N2 — the leased-consumes bridge (spec §3.2). BEFORE
      # delegating to the build engine, materialize-or-reuse each consumed
      # ``stateGroup`` against the L1 store and renew the lease to the daemon
      # (no-daemon-safe). The run-edge's stable name is the ``consumerId``. A
      # non-consuming edge (empty ``consumes``) skips this entirely and runs
      # exactly as N1. The reconcile NEVER blocks the run on a daemon: the store
      # write is the correctness source of truth (L2), the daemon renew is a
      # best-effort notification (L4), and idle reaping is the daemon's job.
      if resolution.hasEntry and resolution.entry.kind == tekRunEdge and
          resolution.entry.consumes.len > 0:
        try:
          let storeRoot = leaseStoreRootForScope(dlsUser)
          let store = openStateStore(storeRoot)
          # Named-Runnable-Edges N3b: auto-build the out-of-tree session
          # resolver from the harvested provider-artifact refs (nil when every
          # member is in-tree ⇒ the in-process fast path). A pooled resolver so
          # a session per artifact id is launched once + reused; closed after
          # the reconcile. No-daemon / no-session-safe: a nil resolver falls
          # through to the missing-group warning below, never blocking the run.
          let sessionPool = newProviderSessionPool()
          defer: (try: sessionPool.closeAll() except CatchableError: discard)
          let sessionResolver = buildRunEdgeSessionResolver(
            resolution.providerArtifacts, sessionPool)
          let bridge = reconcileConsumedStateGroups(
            resolution.entry.consumes, resolution.entry.name,
            resolution.resources, resolution.groups, store,
            sessionResolver = sessionResolver)
          for missing in bridge.missingGroups:
            stderr.writeLine("repro run: warning: run-edge '" &
              resolution.entry.name & "' consumes leased state '" & missing &
              "' but no matching stateGroup / resource was found; running " &
              "without it.")
        except CatchableError as bridgeErr:
          # A reconcile failure must not silently swallow the run in a way that
          # hides the cause; surface it but let the edge run (the leased state
          # is an optimization, and N1's no-lease path still executes).
          stderr.writeLine("repro run: warning: leased-state reconcile for '" &
            resolution.entry.name & "' failed: " & bridgeErr.msg &
            " — running without it.")
      # Run-edge (or a collection of run-edges) — delegate to the build
      # engine, which executes it. Collections mirror ``repro build test``.
      var buildArgs = @[parsed.rawTarget]
      var actionArgs: seq[string] = @[]
      if resolution.hasEntry and resolution.entry.kind == tekRunEdge:
        actionArgs.add(resolution.entry.runArgs)
      actionArgs.add(parsed.forwardedArgs)
      if actionArgs.len > 0:
        buildArgs.add("--")
        for a in actionArgs:
          buildArgs.add(a)
      return runBuildCommand(buildArgs, publicCliPath)
    else:
      # Named-Runnable-Edges N1 (spec §3.1 / §7 — conservative default): a
      # plain artifact edge that is not a run-edge is NOT run by ``repro
      # run``. Point the user at ``repro build`` rather than guessing which
      # output to execute. (Single-executable-output auto-run is deferred.)
      stderr.writeLine("repro run: error: '" & parsed.rawTarget &
        "' is a build target, not a runnable edge; build it with " &
        "'repro build " & parsed.rawTarget & "'.")
      return 2
  of trkAmbiguous:
    stderr.writeLine("repro run: error: target_ambiguous: '" &
      parsed.rawTarget & "' is exported by multiple packages:")
    for cand in resolution.record.candidates:
      stderr.writeLine("  " & cand)
    stderr.writeLine("repro run: hint: re-run with the qualified " &
      "<package>:<name> form")
    return 2
  of trkUnknown:
    # Exit-code + diagnostic parity with ``repro build``'s
    # ``unknown_target`` (spec deliverable). Reuse the shared renderer so
    # the two verbs cannot drift.
    var err = newException(BuildTargetUnknownError,
      "unknown run target: " & parsed.rawTarget)
    err.selectorName = parsed.rawTarget
    err.suggestions = resolution.record.suggestions
    stderr.write(renderUnknownTargetDiagnostic(err[]))
    return 2

proc runReproTasksCommand(args: openArray[string];
                          publicCliPath: string): int =
  let parsed = parseReproTasksArgs(args)
  var listedTasks = inspectDevEnvTasks(parsed.selection, publicCliPath)
  if parsed.selection.statsPath.len > 0:
    let edge = computePublicDevEnv(parsed.selection, publicCliPath)
    writeDevEnvStats(parsed.selection.statsPath, edge, "tasks")
    let artifact = readDevEnvArtifact(edge.artifactPath)
    if emitDevEnvDiagnostics(artifact):
      return 1
    listedTasks = artifact.tasks

  # Named-Runnable-Edges N1: ``repro tasks`` lists dev-env tasks AND named
  # run-edges, source-labelled (spec §5), matching ``repro run --choose``.
  emitMergedRunListing(listedTasks, runEdgeExportEntries(publicCliPath))
  0

proc runReproExecCommand(args: openArray[string];
                         publicCliPath: string): int =
  let parsed = parseDevEnvExecArgs(args)
  let edge = computePublicDevEnv(parsed.selection, publicCliPath)
  writeDevEnvStats(parsed.selection.statsPath, edge, "exec")
  let artifact = readDevEnvArtifact(edge.artifactPath)
  if emitDevEnvDiagnostics(artifact):
    return 1
  runActivatedCommand(artifact, edge.artifactPath, parsed.command,
    parsed.selection.projectRoot)

proc defaultInteractiveShell(): string =
  when defined(windows):
    let comspec = getEnv("COMSPEC")
    if comspec.len > 0:
      return comspec
    let pwsh = findExe("pwsh")
    if pwsh.len > 0:
      return pwsh
    "powershell"
  else:
    getEnv("SHELL", "/bin/sh")

proc runReproShellCommand(args: openArray[string];
                          publicCliPath: string): int =
  let parsed = parseDevEnvShellArgs(args)
  let edge = computePublicDevEnv(parsed.selection, publicCliPath)
  writeDevEnvStats(parsed.selection.statsPath, edge, "shell")
  let artifact = readDevEnvArtifact(edge.artifactPath)
  if emitDevEnvDiagnostics(artifact):
    return 1
  if parsed.printEnv:
    stdout.write(renderDevEnvArtifact(artifact, edge.artifactPath,
      parsed.printFormat))
    return 0
  let shellPath =
    if parsed.shellPath.len > 0:
      parsed.shellPath
    else:
      defaultInteractiveShell()
  spawnActivatedShell(artifact, edge.artifactPath, shellPath,
    parsed.selection.projectRoot)

# M74 — ``repro dev-env export <shell>``.
#
# This is the inner CLI of the Shell-Direnv-Hook plan. The fast-path
# cache-key check arrives in M77; this milestone always walks the
# dev-env edge. The architecture is:
#
#   1. Parse positional ``<shell>`` first (so unknown shells fail with
#      exit 2 BEFORE we touch the filesystem).
#   2. Parse flags (``--project-root``, ``--activity``,
#      ``--develop-overrides``, ``--allow-stale``).
#   3. Resolve project root: explicit flag wins; else walk up from
#      ``$PWD`` for ``repro.nim`` / ``reprobuild.nim`` / ``.repro/``.
#   4. Walk the dev-env edge via ``computePublicDevEnv``.
#   5. Read the RBDE artifact, convert to ``ExportPlan``, append the
#      ``__REPRO_APPLIED`` marker, format, write to stdout.
type
  ParsedDevEnvExport = object
    shell: ShellKind
    projectRoot: string
    activity: string
    developOverridesPath: string
    allowStale: bool
    preActivationEnvPath: string

proc parseDevEnvExportArgs(args: openArray[string]): ParsedDevEnvExport =
  if args.len == 0:
    raise newException(ValueError,
      "repro dev-env export requires a shell argument " &
        "(bash|zsh|fish|nushell|pwsh)")
  result.shell = parseShellKind(args[0])
  var i = 1
  while i < args.len:
    let arg = args[i]
    if arg == "--project-root" or arg.startsWith("--project-root="):
      result.projectRoot = valueFromFlag(args, i, "--project-root")
    elif arg == "--activity" or arg.startsWith("--activity="):
      result.activity = valueFromFlag(args, i, "--activity")
    elif arg == "--develop-overrides" or
        arg.startsWith("--develop-overrides="):
      result.developOverridesPath =
        valueFromFlag(args, i, "--develop-overrides")
    elif arg == "--allow-stale":
      result.allowStale = true
    elif arg == "--pre-activation-env" or
        arg.startsWith("--pre-activation-env="):
      # M75 — shell hook writes its env to this file before calling
      # ``export`` so the rollback manifest captures the SHELL's env,
      # not the spawned child's env. Optional; when absent we fall
      # back to the child process's own env (graceful-degradation
      # path used by direct CLI invocation outside the hook).
      result.preActivationEnvPath =
        valueFromFlag(args, i, "--pre-activation-env")
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported dev-env export flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected dev-env export argument: " & arg)
    inc i
  if result.activity.len == 0:
    result.activity = "default"

proc artifactIdFingerprint(artifact: DevEnvArtifact): string =
  ## Deterministic, content-derived. The artifact's ``artifactId`` is
  ## the canonical SSZ hash the codec computes; same bytes -> same
  ## fingerprint across runs / hosts.
  result = newStringOfCap(64)
  for b in artifact.artifactId:
    result.add(toHex(int(b), 2).toLowerAscii())

proc allowFileHash(path: string): string =
  digestHex(blake3DomainDigest(path.bytesOf(), hdMetadataEnvelope))

proc emitDirectoryNotAllowedScript(shell: ShellKind; path: string): string =
  let msg = "repro: dev-env directory " & path & " is not allowed/trusted.\n" &
            "Run 'repro allow' to trust it and activate the environment."
  case shell
  of skBash, skZsh:
    result = "echo \"" & msg.replace("\"", "\\\"") & "\" >&2\n"
    result.add("export __REPRO_WARNED=\"" & path.replace("\"", "\\\"") & "\"\n")
  of skFish:
    result = "echo \"" & msg.replace("\"", "\\\"") & "\" >&2\n"
    result.add("set -gx __REPRO_WARNED \"" & path.replace("\"", "\\\"") & "\"\n")
  of skNushell:
    result = "print -e \"" & msg.replace("\"", "\\\"") & "\"\n"
    result.add("$env.__REPRO_WARNED = \"" & path.replace("\"", "\\\"") & "\"\n")
  of skPwsh:
    result = "[Console]::Error.WriteLine(\"" & msg.replace("\"", "\\\"") & "\")\n"
    result.add("$env:__REPRO_WARNED = '" & path.replace("'", "''") & "'\n")

proc emitWarnedResetScript(shell: ShellKind): string =
  case shell
  of skBash, skZsh: "unset __REPRO_WARNED\n"
  of skFish: "set -e __REPRO_WARNED\n"
  of skNushell: "hide-env __REPRO_WARNED\n"
  of skPwsh: "Remove-Item Env:__REPRO_WARNED -ErrorAction SilentlyContinue\n"

proc runReproAllowCommand(args: openArray[string]): int =
  var path = ""
  if args.len > 0:
    path = args[0]
  else:
    path = getCurrentDir()
  
  let root = os.normalizedPath(absolutePath(path))
  let hash = allowFileHash(root)
  let allowDir = getConfigDir() / "repro" / "allow"
  try:
    createDir(allowDir)
    writeFile(allowDir / hash, root)
    stderr.writeLine("Allowed repro dev-env for: " & root)
    return 0
  except CatchableError as err:
    stderr.writeLine("repro allow: error writing trust file: " & err.msg)
    return 1

proc runReproDenyCommand(args: openArray[string]): int =
  var path = ""
  if args.len > 0:
    path = args[0]
  else:
    path = getCurrentDir()
  
  let root = os.normalizedPath(absolutePath(path))
  let hash = allowFileHash(root)
  let f = getConfigDir() / "repro" / "allow" / hash
  try:
    if fileExists(f):
      removeFile(f)
      stderr.writeLine("Denied/removed repro dev-env trust for: " & root)
    else:
      stderr.writeLine("repro deny: directory was not trusted: " & root)
    return 0
  except CatchableError as err:
    stderr.writeLine("repro deny: error removing trust file: " & err.msg)
    return 1

proc runDevEnvExportCommand(args: openArray[string];
                            publicCliPath: string): int =
  ## ``repro dev-env export <shell>`` dispatch arm. Exit codes:
  ##   0 — success
  ##   1 — engine error (project not found, edge failure, ...)
  ##   2 — usage error (unknown shell, bad flag)
  var parsed: ParsedDevEnvExport
  try:
    parsed = parseDevEnvExportArgs(args)
  except ExportPlanError as err:
    stderr.writeLine("repro dev-env export: " & err.msg)
    return 2
  except ValueError as err:
    stderr.writeLine("repro dev-env export: " & err.msg)
    return 2

  if parsed.projectRoot.len == 0:
    parsed.projectRoot = findDevEnvProjectRoot(getCurrentDir())
    if parsed.projectRoot.len == 0:
      stderr.writeLine("repro dev-env export: no project root found; " &
        "expected " & CanonicalProjectFileName & " or " &
        LegacyProjectFileName &
        " in the current directory or one of its parents")
      return 1
  else:
    parsed.projectRoot = os.normalizedPath(absolutePath(parsed.projectRoot))

  # Check if directory is allowed/trusted
  let allowFilePath = getConfigDir() / "repro" / "allow" / allowFileHash(parsed.projectRoot)
  var isAllowed = false
  if fileExists(allowFilePath):
    try:
      let contents = readFile(allowFilePath).strip()
      if contents == parsed.projectRoot:
        isAllowed = true
    except CatchableError:
      discard

  if getEnv("REPRO_DEV_ENV_AUTO_ALLOW") == "1":
    isAllowed = true

  if not isAllowed:
    proc samePath(a, b: string): bool =
      if a == b: return true
      if a.len == 0 or b.len == 0: return false
      var canonicalA = a
      var canonicalB = b
      try: canonicalA = expandFilename(a)
      except CatchableError: discard
      try: canonicalB = expandFilename(b)
      except CatchableError: discard
      return canonicalA == canonicalB

    if samePath(getEnv("__REPRO_WARNED"), parsed.projectRoot):
      return 0
    stdout.write(emitDirectoryNotAllowedScript(parsed.shell, parsed.projectRoot))
    return 0

  # M77 — cache-key fast path. BEFORE the project file is even
  # resolved or the selection's heavy ``resolveDevEnvSelection`` runs,
  # hash the cache-key inputs and compare against ``$__REPRO_APPLIED``.
  # On a match, emit the per-shell no-op script and exit 0 without
  # touching the build engine, the project-interface extractor, or
  # the develop-overrides resolver.
  #
  # Variable choice: the spec memo separates ``REPRO_APPLIED`` (the
  # fast-path env var) from ``__REPRO_APPLIED`` (the activation
  # marker). M77 collapses them onto the single ``__REPRO_APPLIED``
  # name: the marker the activation script sets IS the cache key, the
  # hook never has to copy it across env vars, and there is no
  # observable difference between "applied" and "would short-circuit".
  # The cost is one env-var slot of namespace overhead on the user's
  # shell, which is already paid for by the marker.
  let fastPathOverridesPath =
    if parsed.developOverridesPath.len > 0:
      os.normalizedPath(absolutePath(parsed.developOverridesPath))
    else:
      developOverridesMetadataPath(parsed.projectRoot)
  let fastPathConfig = DevEnvEdgeConfig(
    projectRoot: parsed.projectRoot,
    activity:
      if parsed.activity.len > 0: parsed.activity else: "default",
    developOverridesPath: fastPathOverridesPath)
  let candidateKey = computeDevEnvEdgeCacheKey(fastPathConfig)
  let activeKey = getEnv("__REPRO_APPLIED")
  if not parsed.allowStale and activeKey.len > 0 and
      candidateKey == activeKey:
    stdout.write(emitFastPathNoOpScript(parsed.shell))
    return 0

  let resolved = resolveProjectFile(parsed.projectRoot)
  if resolved.path.len == 0:
    stderr.writeLine("repro dev-env export: " & parsed.projectRoot &
      " does not contain " & CanonicalProjectFileName & " or " &
      LegacyProjectFileName)
    return 1

  var selection = DevEnvCliSelection(
    selector: parsed.projectRoot,
    activity: parsed.activity)
  try:
    selection.resolveDevEnvSelection()
  except CatchableError as err:
    stderr.writeLine("repro dev-env export: " & err.msg)
    return 1
  if parsed.developOverridesPath.len > 0:
    selection.developOverridesPath =
      os.normalizedPath(absolutePath(parsed.developOverridesPath))

  let edge =
    try:
      computePublicDevEnv(selection, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro dev-env export: " & err.msg)
      return 1
  let artifact = readDevEnvArtifact(edge.artifactPath)
  if not parsed.allowStale and emitDevEnvDiagnostics(artifact):
    return 1

  var plan = devEnvArtifactToExportPlan(edge.artifactPath)
  # M77 — emit the cache-key as the ``__REPRO_APPLIED`` marker. The
  # next prompt's fast path re-derives the same key from on-disk
  # inputs and compares; a match short-circuits without any build
  # engine work. Using the cache key (not the SSZ artifact ID) is what
  # makes the fast path actually fast.
  let fingerprint = candidateKey
  let manifestPath = rollbackManifestPath(edge.artifactPath)
  # M75 — emit the manifest path as a marker BEFORE the
  # ``__REPRO_APPLIED`` fingerprint so the hook's deactivation arm
  # can locate the manifest via ``$__REPRO_ACTIVE_MANIFEST`` on the
  # next cd-out.
  plan.appendReproActiveManifestMarker(manifestPath)
  plan.appendReproAppliedMarker(fingerprint)
  let activationScript =
    emitWarnedResetScript(parsed.shell) & formatExportPlan(plan, parsed.shell)

  # M75 — write the rollback manifest alongside the RBDE artifact.
  let preEnv =
    if parsed.preActivationEnvPath.len > 0:
      try:
        readPreActivationEnv(parsed.preActivationEnvPath)
      except CatchableError as err:
        stderr.writeLine("repro dev-env export: " & err.msg)
        return 1
    else:
      snapshotProcessEnv()
  let manifest = buildRollbackManifest(plan, preEnv, fingerprint,
    activationScript, parsed.shell)
  try:
    writeRollbackManifest(manifestPath, manifest)
  except CatchableError as err:
    stderr.writeLine("repro dev-env export: " & err.msg)
    return 1

  stdout.write(activationScript)
  0

# M75 — ``repro dev-env deactivate <rollback-manifest>``.
#
# Reads the manifest, walks its ``vars`` array in REVERSE order, and
# emits a per-shell script that restores the pre-activation values
# of every var the matching activation touched. Tamper detection:
# the deactivation emitter re-derives the activation script from the
# manifest's referenced RBDE artifact and re-hashes it; mismatch
# means the user has presumably edited their env manually since
# activation. In that case we emit a no-op script + a stderr
# diagnostic and exit with code 3 (distinct from 0 / 1 / 2 so the
# shell hook can branch on it).
type
  ParsedDevEnvDeactivate = object
    manifestPath: string
    shell: ShellKind
    shellSet: bool

proc parseDevEnvDeactivateArgs(args: openArray[string]):
    ParsedDevEnvDeactivate =
  result.shell = skBash
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--shell" or arg.startsWith("--shell="):
      result.shell = parseShellKind(valueFromFlag(args, i, "--shell"))
      result.shellSet = true
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported dev-env deactivate flag: " & arg)
    elif result.manifestPath.len == 0:
      result.manifestPath = arg
    else:
      raise newException(ValueError,
        "unexpected dev-env deactivate argument: " & arg)
    inc i
  if result.manifestPath.len == 0:
    raise newException(ValueError,
      "repro dev-env deactivate requires a rollback manifest path")

proc runDevEnvDeactivateCommand(args: openArray[string]): int =
  ## ``repro dev-env deactivate <rollback-manifest> [--shell=<shell>]``
  ## dispatch arm. Exit codes:
  ##   0 — success
  ##   1 — engine error (manifest / artifact missing or corrupt)
  ##   2 — usage error (unknown shell, missing argument)
  ##   3 — tamper detected (activation hash mismatch)
  var parsed: ParsedDevEnvDeactivate
  try:
    parsed = parseDevEnvDeactivateArgs(args)
  except ExportPlanError as err:
    stderr.writeLine("repro dev-env deactivate: " & err.msg)
    return 2
  except ValueError as err:
    stderr.writeLine("repro dev-env deactivate: " & err.msg)
    return 2

  let manifest =
    try:
      readRollbackManifest(parsed.manifestPath)
    except CatchableError as err:
      stderr.writeLine("repro dev-env deactivate: " & err.msg)
      return 1

  # Locate the RBDE artifact. By construction the manifest path is
  # ``<artifact>.rollback.json``, so strip the suffix to find the
  # artifact. We use this only for the tamper-detection re-hash; the
  # actual rollback data is fully self-contained in the manifest.
  if not parsed.manifestPath.endsWith(".rollback.json"):
    stderr.writeLine("repro dev-env deactivate: manifest path must end " &
      "with '.rollback.json': " & parsed.manifestPath)
    return 1
  let artifactPath = parsed.manifestPath[0 ..< parsed.manifestPath.len -
    ".rollback.json".len]
  if not fileExists(artifactPath):
    stderr.writeLine("repro dev-env deactivate: RBDE artifact missing " &
      "(cannot verify tamper seal): " & artifactPath)
    return 1

  # Tamper detection: re-derive the activation script bytes from the
  # on-disk artifact and re-hash, using the SHELL recorded in the
  # manifest (NOT ``parsed.shell`` — the deactivation caller may
  # request a different shell's deactivation syntax, e.g. user-side
  # ``--shell=pwsh`` against a bash-activated manifest, and the hash
  # seal must compare against the activation-time shell).
  var rederivedPlan = devEnvArtifactToExportPlan(artifactPath)
  rederivedPlan.appendReproActiveManifestMarker(parsed.manifestPath)
  rederivedPlan.appendReproAppliedMarker(manifest.artifact)
  let rederivedScript =
    emitWarnedResetScript(manifest.activationShell) &
    formatExportPlan(rederivedPlan, manifest.activationShell)
  let rederivedHash = computeActivationScriptHash(rederivedScript)
  if rederivedHash != manifest.activationScriptHash:
    stderr.writeLine("repro dev-env deactivate: tamper detected — " &
      "activation_script_hash mismatch (manifest: " &
      manifest.activationScriptHash & ", recomputed: " &
      rederivedHash & "). Env left as-is.")
    stdout.write(emitNoOpScript(parsed.shell))
    return 3

  stdout.write(formatDeactivate(manifest, parsed.shell))
  0

# M76 — ``repro shell hook <shell>``.
#
# Emits the per-shell hook installation script. The user sources the
# output ONCE at shell start (from ``~/.bashrc`` /
# ``~/.config/fish/config.fish`` / ``$PROFILE`` / etc.). The emitted
# script defines a ``__repro_shell_hook`` function that runs per
# prompt / per cd, walks up from ``$PWD`` for the project root, and
# composes the M74 ``dev-env export`` + M75 ``dev-env deactivate``
# arms to drive activation/deactivation on cd.
#
# This is distinct from ``repro hooks`` (CLI/hooks.md), which manages
# rc-file ENTRIES; ``repro shell hook`` only EMITS the per-shell
# snippet that the user adds to their rc file (or pipes through
# ``eval`` / ``source`` / ``Out-String | Invoke-Expression`` directly).
#
# Exit codes:
#   0 — success
#   2 — usage error (missing/unknown shell argument)
type
  ParsedShellHook = object
    shell: ShellKind
    reproBin: string  ## explicit path; otherwise we autodetect

proc parseShellHookArgs(args: openArray[string]): ParsedShellHook =
  if args.len == 0:
    raise newException(ValueError,
      "repro shell hook requires a shell argument " &
        "(bash|zsh|fish|nushell|pwsh)")
  result.shell = parseShellKind(args[0])
  var i = 1
  while i < args.len:
    let arg = args[i]
    if arg == "--repro-bin" or arg.startsWith("--repro-bin="):
      # Escape hatch for the test surface — embed an explicit absolute
      # path to ``repro.exe`` so the hook does not depend on PATH
      # resolution. Default (empty) means "use the bare ``repro``
      # name and rely on PATH".
      result.reproBin = valueFromFlag(args, i, "--repro-bin")
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported shell hook flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected shell hook argument: " & arg)
    inc i

proc runShellHookCommand(args: openArray[string]): int =
  ## ``repro shell hook <shell>`` dispatch arm.
  var parsed: ParsedShellHook
  try:
    parsed = parseShellHookArgs(args)
  except ExportPlanError as err:
    stderr.writeLine("repro shell hook: " & err.msg)
    return 2
  except ValueError as err:
    stderr.writeLine("repro shell hook: " & err.msg)
    return 2

  let script =
    case parsed.shell
    of skBash: renderBashHook(parsed.reproBin)
    of skZsh: renderZshHook(parsed.reproBin)
    of skFish: renderFishHook(parsed.reproBin)
    of skNushell: renderNushellHook(parsed.reproBin)
    of skPwsh: renderPwshHook(parsed.reproBin)
  stdout.write(script)
  0

type
  ParsedDevSessionCommand = object
    selection: DevEnvCliSelection
    foreground: bool
    httpBind: string
    debounceMs: int
    force: bool

proc parseDevSessionArgs(args: openArray[string]; commandName: string):
    ParsedDevSessionCommand =
  var selection = DevEnvCliSelection()
  result.httpBind = "127.0.0.1:0"
  result.debounceMs = 250
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i,
        "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--foreground":
      result.foreground = true
    elif arg == "--force":
      result.force = true
    elif arg == "--http" or arg.startsWith("--http="):
      result.httpBind = valueFromFlag(args, i, "--http")
    elif arg == "--debounce-ms" or arg.startsWith("--debounce-ms="):
      result.debounceMs = parseInt(valueFromFlag(args, i, "--debounce-ms"))
      if result.debounceMs < 0:
        raise newException(ValueError, "--debounce-ms must be non-negative")
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported " & commandName & " flag: " & arg)
    elif selection.selector.len == 0:
      selection.selector = arg
    else:
      raise newException(ValueError,
        "unexpected " & commandName & " argument: " & arg)
    inc i
  selection.resolveDevEnvSelection()
  result.selection = selection

proc supervisorConfig(parsed: ParsedDevSessionCommand;
                      edge: DevEnvEdgeResult;
                      publicCliPath: string;
                      mode: DevSessionMode): DevSessionSupervisorConfig =
  DevSessionSupervisorConfig(
    mode: mode,
    foreground: parsed.foreground,
    projectRoot: parsed.selection.projectRoot,
    modulePath: parsed.selection.modulePath,
    outDir: parsed.selection.outDir,
    workDir: reprobuildLibraryWorkDir(),
    publicCliPath: publicCliPath,
    monitorCliPath: publicDevEnvMonitor(publicCliPath).path,
    monitorShimLibPath: resolveMonitorShimLibPath(),
    artifactPath: edge.artifactPath,
    activity: parsed.selection.activity,
    lockSliceId: parsed.selection.lockSliceId,
    developOverridesPath: parsed.selection.developOverridesPath,
    httpBind: parsed.httpBind,
    debounceMs: parsed.debounceMs)

proc supervisorCliArgs(config: DevSessionSupervisorConfig): seq[string] =
  result = @[
    "__repro-dev-session-supervisor",
    "--mode", config.mode.modeName,
    "--project-root", config.projectRoot,
    "--module", config.modulePath,
    "--out-dir", config.outDir,
    "--work-dir", config.workDir,
    "--artifact", config.artifactPath,
    "--activity", config.activity,
    "--lock-slice", config.lockSliceId,
    "--develop-overrides", config.developOverridesPath,
    "--monitor-cli", config.monitorCliPath,
    "--monitor-shim", config.monitorShimLibPath,
    "--http", config.httpBind,
    "--debounce-ms", $config.debounceMs
  ]
  if config.foreground:
    result.add("--foreground")

proc startBackgroundSupervisor(config: DevSessionSupervisorConfig) =
  createDir(extendedPath(config.outDir.sessionDir))
  let logPath = config.outDir.sessionDir / "supervisor.log"
  when defined(windows):
    discard startProcess(config.publicCliPath,
      args = config.supervisorCliArgs(),
      workingDir = config.projectRoot,
      options = {poUsePath, poDaemon, poParentStreams})
  else:
    var fdsToClose: seq[string] = @[]
    for fd in 3 .. 64:
      fdsToClose.add($fd)
    let closeInheritedFds = "for fd in " & fdsToClose.join(" ") &
      "; do eval \"exec $fd>&-\"; done; "
    let command = "(cd " & q(config.projectRoot) & " && " &
      closeInheritedFds &
      "exec " &
      shellCommand(@[config.publicCliPath] & config.supervisorCliArgs()) &
      ") </dev/null >> " & q(logPath) & " 2>&1 &"
    let exitCode = execShellCmd(command)
    if exitCode != 0:
      raise newException(OSError,
        "failed to launch dev session supervisor: " & command)

proc runUpOrDevCommand(args: openArray[string]; publicCliPath: string;
                       mode: DevSessionMode): int =
  let commandName = if mode == dsmDev: "dev" else: "up"
  var parsed = parseDevSessionArgs(args, commandName)
  let edge = computePublicDevEnv(parsed.selection, publicCliPath)
  let config = supervisorConfig(parsed, edge, publicCliPath, mode)
  if parsed.foreground:
    return runDevSessionSupervisor(config)
  config.startBackgroundSupervisor()
  let status = waitForDevSessionReady(config)
  echo "repro " & commandName & ": session " &
    status["sessionId"].getStr() & " " & status["status"].getStr() &
    " " & status["httpBind"].getStr()
  0

proc runDownCommand(args: openArray[string]): int =
  let parsed = parseDevSessionArgs(args, "down")
  let metadataPath = parsed.selection.outDir.sessionMetadataPath()
  if not fileExists(extendedPath(metadataPath)):
    raise newException(IOError,
      "no authoritative Reprobuild dev session metadata at " & metadataPath)
  # readJsonFileResilient retries past the brief `writeFile(O_TRUNC)`
  # window the dev-session supervisor produces every time it republishes
  # session.json (status transitions, service events, etc.). Without the
  # retry a parallel reader (us, plus the e2e test polling every 100 ms)
  # observes a zero-byte file and raises `session.json(1, 0) Error: {
  # expected`. See readJsonFileResilient for the race rationale.
  let metadata = readJsonFileResilient(metadataPath)
  let httpBindValue = metadata{"httpBind"}.getStr()
  if httpBindValue.len == 0:
    raise newException(ValueError,
      "dev session metadata is missing httpBind: " & metadataPath)
  try:
    let response = httpRequest(httpBindValue, "/session/stop",
      httpMethod = "POST")
    if response.status < 200 or response.status >= 300:
      raise newException(IOError,
        "session stop request failed with HTTP " & $response.status &
          ": " & response.body)
  except CatchableError as err:
    if not parsed.force:
      raise
    writeFile(extendedPath(parsed.selection.outDir.sessionDir /
      StopRequestFile), "{\"source\":\"force-file\"}\n")
    stderr.writeLine("repro down: HTTP stop failed; wrote stop request file: " &
      err.msg)
  var waited = 0
  while waited <= 10000:
    if fileExists(extendedPath(metadataPath)):
      let current = readJsonFileResilient(metadataPath)
      if current{"status"}.getStr() == "down":
        echo "repro down: session " & current{"sessionId"}.getStr() &
          " down"
        return 0
    sleep(100)
    waited.inc(100)
  raise newException(IOError,
    "timed out waiting for dev session to stop: " & metadataPath)

proc runDevSessionSupervisorHelper(args: openArray[string];
                                   publicCliPath: string): int =
  let modeText = valueAfterFlag(args, "--mode")
  let mode =
    case modeText
    of "dev": dsmDev
    of "up", "": dsmUp
    else:
      raise newException(ValueError, "unsupported dev session mode: " & modeText)
  let debounceText = valueAfterFlag(args, "--debounce-ms")
  let config = DevSessionSupervisorConfig(
    mode: mode,
    foreground: args.find("--foreground") >= 0,
    projectRoot: valueAfterFlag(args, "--project-root"),
    modulePath: valueAfterFlag(args, "--module"),
    outDir: valueAfterFlag(args, "--out-dir"),
    workDir: valueAfterFlag(args, "--work-dir"),
    publicCliPath: publicCliPath,
    monitorCliPath: valueAfterFlag(args, "--monitor-cli"),
    monitorShimLibPath: valueAfterFlag(args, "--monitor-shim"),
    artifactPath: valueAfterFlag(args, "--artifact"),
    activity: valueAfterFlag(args, "--activity"),
    lockSliceId: valueAfterFlag(args, "--lock-slice"),
    developOverridesPath: valueAfterFlag(args, "--develop-overrides"),
    httpBind: valueAfterFlag(args, "--http"),
    debounceMs: if debounceText.len > 0: parseInt(debounceText) else: 250)
  runDevSessionSupervisor(config)

proc runDevSessionHttpHelper(args: openArray[string]): int =
  let portText = valueAfterFlag(args, "--port")
  runDevSessionHttpServer(DevSessionHttpConfig(
    sessionDir: valueAfterFlag(args, "--session-dir"),
    host: valueAfterFlag(args, "--host"),
    port: if portText.len > 0: parseInt(portText) else: 0))

const
  DirenvManagedBlockId = "repro-dev-env-direnv"
  DirenvActivationGuard = "REPRO_DIRENV_ACTIVATING"
  NativeShellManagedBlockPrefix = "repro-dev-env-native-"
  NativeShellActivationGuard = "REPRO_NATIVE_SHELL_HOOK_RUNNING"
  VcsDispatcherMarker = V2DispatcherMarker
  # M17: full VCS-hook bundle the workspace publication gate (M18)
  # and the manifest auto-refresh hook (M19a) depend on. Order matters
  # only for the deterministic JSON-report iteration.
  VcsHookNames = ["pre-push", "post-commit", "post-merge", "post-checkout"]

type
  HookActionKind = enum
    hakEnsure
    hakReinstall
    hakUninstall

  NativeShellKind = enum
    nskBash
    nskZsh
    nskFish
    nskPowerShell

  ParsedHooksCommand = object
    action: HookActionKind
    targetPath: string
    shellDirenv: bool
    vcs: bool
    nativeShells: seq[NativeShellKind]
    workspaceRoot: string  ## M17: explicit --workspace-root override.
    json: bool             ## M17: emit JSON to stdout in addition to the report file.
    report: ReportSpec     ## Opt-in ``--write-report[=PATH]`` artifact.

  NativeShellActivationRequest = object
    cwd: string
    shell: NativeShellKind
    previousArtifact: string
    previousProjectRoot: string
    statsPath: string

proc nativeShellName(shell: NativeShellKind): string =
  case shell
  of nskBash: "bash"
  of nskZsh: "zsh"
  of nskFish: "fish"
  of nskPowerShell: "powershell"

proc parseNativeShell(value: string): NativeShellKind =
  case value.normalize()
  of "bash":
    nskBash
  of "zsh":
    nskZsh
  of "fish":
    nskFish
  of "powershell", "pwsh", "ps1":
    nskPowerShell
  else:
    raise newException(ValueError,
      "unsupported shell for repro hooks --shell: " & value)

proc nativeShellFormat(shell: NativeShellKind): DevEnvPrintFormat =
  case shell
  of nskBash, nskZsh:
    depPosix
  of nskFish:
    depFish
  of nskPowerShell:
    depPowerShell

proc nativeShellBlockId(shell: NativeShellKind): string =
  NativeShellManagedBlockPrefix & shell.nativeShellName()

proc nativeShellRcPath(shell: NativeShellKind; homeDir = getEnv("HOME")): string =
  case shell
  of nskBash:
    homeDir / ".bashrc"
  of nskZsh:
    homeDir / ".zshrc"
  of nskFish:
    let xdg = getEnv("XDG_CONFIG_HOME")
    if xdg.len > 0:
      xdg / "fish" / "config.fish"
    else:
      homeDir / ".config" / "fish" / "config.fish"
  of nskPowerShell:
    when defined(windows):
      let profileHome = getEnv("USERPROFILE", homeDir)
      profileHome / "Documents" / "PowerShell" /
        "Microsoft.PowerShell_profile.ps1"
    else:
      homeDir / ".config" / "powershell" /
        "Microsoft.PowerShell_profile.ps1"

proc containsNixStoreSegment(path: string): bool =
  let normalized = path.replace('\\', '/')
  normalized.startsWith("/nix/store/") or normalized.contains("/nix/store/")

proc absoluteSymlinkTarget(linkPath: string): string =
  let rawTarget = expandSymlink(extendedPath(linkPath))
  if rawTarget.isAbsolute:
    os.normalizedPath(rawTarget)
  else:
    os.normalizedPath(parentDir(linkPath) / rawTarget)

proc rcFileWritePath(rcPath: string): string =
  ## Return the file to edit for a shell rc managed block. Refuses Nix-managed
  ## read-only symlinks instead of replacing the symlink with a regular file.
  let expandedRc = extendedPath(rcPath)
  if symlinkExists(expandedRc):
    let target = absoluteSymlinkTarget(rcPath)
    if target.containsNixStoreSegment():
      raise newException(ValueError,
        "refusing to write shell rc file " & rcPath &
          ": it is a Nix-managed symlink into the Nix store (" & target &
          "). Edit the source file in your dotfiles/home-manager " &
          "configuration and rebuild with home-switch.")
    if fileExists(extendedPath(target)):
      let permissions = getFilePermissions(extendedPath(target))
      if fpUserWrite notin permissions:
        raise newException(ValueError,
          "refusing to write shell rc file " & rcPath &
            ": it points at a read-only file (" & target &
            "). Edit the owning source file instead.")
    return target
  if expandedRc.containsNixStoreSegment():
    raise newException(ValueError,
      "refusing to write shell rc file in the Nix store: " & rcPath &
        ". Edit the source file in your dotfiles/home-manager configuration " &
        "and rebuild with home-switch.")
  if fileExists(expandedRc):
    let permissions = getFilePermissions(expandedRc)
    if fpUserWrite notin permissions:
      raise newException(ValueError,
        "refusing to write read-only shell rc file " & rcPath &
          ". Edit the owning source file instead.")
  rcPath

proc posixLiteral(value: string): string =
  result = "'"
  for ch in value:
    if ch == '\'':
      result.add("'\\''")
    else:
      result.add(ch)
  result.add("'")

proc fishLiteral(value: string): string =
  result = "'"
  for ch in value:
    case ch
    of '\'':
      result.add("\\'")
    of '\\':
      result.add("\\\\")
    else:
      result.add(ch)
  result.add("'")

proc powerShellLiteral(value: string): string =
  "'" & value.replace("'", "''") & "'"

const NativeMetadataNames = [
  "REPRO_DEV_ENV_ARTIFACT",
  "REPRO_DEV_ENV_PROJECT_ROOT",
  "REPRO_DEV_ENV_SELECTED_ACTIVITIES",
  "REPRO_DEV_ENV_TASKS",
  "REPRO_DEV_ENV_SERVICES"
]

proc sortedUnique(values: seq[string]): seq[string] =
  var seen: HashSet[string]
  for value in values:
    if value.len > 0 and value notin seen:
      seen.incl(value)
      result.add(value)
  result.sort()

proc nativeUnsetNames(artifact: DevEnvArtifact): seq[string] =
  var names: seq[string] = @[]
  for op in artifact.shellOps:
    case op.kind
    of deskSetEnv, deskSetPathList, deskUnsetEnv:
      names.add(op.name)
    of deskPrependPath, deskAppendPath, deskSetWorkingDirectory:
      discard
  for name in NativeMetadataNames:
    names.add(name)
  names.sortedUnique()

proc nativePathRemovals(artifact: DevEnvArtifact):
    seq[tuple[name, value, separator: string]] =
  var seen: HashSet[string]
  for op in artifact.shellOps:
    case op.kind
    of deskPrependPath, deskAppendPath:
      let sep = if op.separator.len > 0: op.separator else: $PathSep
      let key = op.name & "\0" & op.value & "\0" & sep
      if key notin seen:
        seen.incl(key)
        result.add((name: op.name, value: op.value, separator: sep))
    else:
      discard

proc renderPosixDevEnvUnload(artifact: DevEnvArtifact): string =
  result = "# Reprobuild native shell unload\n"
  let removals = nativePathRemovals(artifact)
  if removals.len > 0:
    result.add("__repro_native_remove_path() {\n")
    result.add("  __repro_native_var=$1\n")
    result.add("  __repro_native_remove=$2\n")
    result.add("  __repro_native_sep=$3\n")
    result.add("  eval \"__repro_native_value=\\${$__repro_native_var-}\"\n")
    result.add("  __repro_native_out=\n")
    result.add("  __repro_native_old_ifs=$IFS\n")
    result.add("  IFS=$__repro_native_sep\n")
    result.add("  for __repro_native_part in $__repro_native_value; do\n")
    result.add("    if [ \"$__repro_native_part\" != \"$__repro_native_remove\" ]; then\n")
    result.add("      if [ -n \"$__repro_native_out\" ]; then\n")
    result.add("        __repro_native_out=$__repro_native_out$__repro_native_sep$__repro_native_part\n")
    result.add("      else\n")
    result.add("        __repro_native_out=$__repro_native_part\n")
    result.add("      fi\n")
    result.add("    fi\n")
    result.add("  done\n")
    result.add("  IFS=$__repro_native_old_ifs\n")
    result.add("  export \"$__repro_native_var=$__repro_native_out\"\n")
    result.add("}\n")
    for removal in removals:
      result.add("__repro_native_remove_path " & posixLiteral(removal.name) &
        " " & posixLiteral(removal.value) & " " &
        posixLiteral(removal.separator) & "\n")
    result.add("unset -f __repro_native_remove_path 2>/dev/null || true\n")
    result.add("unset __repro_native_var __repro_native_remove __repro_native_sep __repro_native_value __repro_native_out __repro_native_old_ifs __repro_native_part\n")
  let names = nativeUnsetNames(artifact)
  if names.len > 0:
    result.add("unset " & names.join(" ") & "\n")

proc renderFishDevEnvUnload(artifact: DevEnvArtifact): string =
  result = "# Reprobuild native shell unload\n"
  let removals = nativePathRemovals(artifact)
  if removals.len > 0:
    result.add("function __repro_native_remove_path\n")
    result.add("  set -l __repro_native_var $argv[1]\n")
    result.add("  set -l __repro_native_remove $argv[2]\n")
    result.add("  set -l __repro_native_kept\n")
    result.add("  for __repro_native_part in $$__repro_native_var\n")
    result.add("    if test \"$__repro_native_part\" != \"$__repro_native_remove\"\n")
    result.add("      set __repro_native_kept $__repro_native_kept \"$__repro_native_part\"\n")
    result.add("    end\n")
    result.add("  end\n")
    result.add("  if test (count $__repro_native_kept) -gt 0\n")
    result.add("    set -gx $__repro_native_var $__repro_native_kept\n")
    result.add("  else\n")
    result.add("    set -e $__repro_native_var\n")
    result.add("  end\n")
    result.add("end\n")
    for removal in removals:
      result.add("__repro_native_remove_path " & fishLiteral(removal.name) &
        " " & fishLiteral(removal.value) & "\n")
    result.add("functions -e __repro_native_remove_path\n")
  for name in nativeUnsetNames(artifact):
    result.add("set -e " & name & "\n")

proc renderPowerShellDevEnvUnload(artifact: DevEnvArtifact): string =
  result = "# Reprobuild native shell unload\n"
  let removals = nativePathRemovals(artifact)
  if removals.len > 0:
    result.add("function __ReproNativeRemovePath($Name, $Value, $Sep) {\n")
    result.add("  $current = [Environment]::GetEnvironmentVariable($Name, 'Process')\n")
    result.add("  if ($null -eq $current) { return }\n")
    result.add("  $kept = @()\n")
    result.add("  foreach ($part in $current -split [regex]::Escape($Sep)) {\n")
    result.add("    if ($part -ne $Value) { $kept += $part }\n")
    result.add("  }\n")
    result.add("  if ($kept.Count -gt 0) { Set-Item -Path \"Env:$Name\" -Value ($kept -join $Sep) }\n")
    result.add("  else { Remove-Item -Path \"Env:$Name\" -ErrorAction SilentlyContinue }\n")
    result.add("}\n")
    for removal in removals:
      result.add("__ReproNativeRemovePath " &
        powerShellLiteral(removal.name) & " " &
        powerShellLiteral(removal.value) & " " &
        powerShellLiteral(removal.separator) & "\n")
    result.add("Remove-Item Function:__ReproNativeRemovePath -ErrorAction SilentlyContinue\n")
  for name in nativeUnsetNames(artifact):
    result.add("Remove-Item Env:" & name & " -ErrorAction SilentlyContinue\n")

proc renderDevEnvUnload(artifact: DevEnvArtifact;
                        format: DevEnvPrintFormat): string =
  case format
  of depPosix:
    renderPosixDevEnvUnload(artifact)
  of depFish:
    renderFishDevEnvUnload(artifact)
  of depPowerShell:
    renderPowerShellDevEnvUnload(artifact)
  of depJson:
    raise newException(ValueError,
      "json is not a native shell activation format")

proc renderNativeShellTransition(previousArtifactPath: string;
                                 nextArtifact: Option[DevEnvArtifact];
                                 nextArtifactPath: string;
                                 format: DevEnvPrintFormat): string =
  if previousArtifactPath.len > 0 and
      fileExists(extendedPath(previousArtifactPath)):
    result.add(renderDevEnvUnload(readDevEnvArtifact(previousArtifactPath),
      format))
  elif previousArtifactPath.len > 0:
    for name in NativeMetadataNames:
      case format
      of depPosix:
        result.add("unset " & name & "\n")
      of depFish:
        result.add("set -e " & name & "\n")
      of depPowerShell:
        result.add("Remove-Item Env:" & name &
          " -ErrorAction SilentlyContinue\n")
      of depJson:
        discard
  if nextArtifact.isSome:
    result.add(renderDevEnvArtifact(nextArtifact.get(), nextArtifactPath,
      format))

proc findDevEnvProjectRoot(startPath: string): string =
  var cursor = os.normalizedPath(absolutePath(startPath))
  if fileExists(extendedPath(cursor)) and not dirExists(extendedPath(cursor)):
    cursor = parentDir(cursor)
  while cursor.len > 0:
    # Project-file alias: a directory containing either ``repro.nim`` or
    # ``reprobuild.nim`` is a valid project root.
    let match = resolveProjectFile(cursor)
    if match.path.len > 0:
      return cursor
    let parent = parentDir(cursor)
    if parent == cursor or parent.len == 0:
      break
    cursor = parent
  ""

proc direnvOpenSentinel(): string =
  ResourceOpenSentinelPrefix & DirenvManagedBlockId & ResourceOpenSentinelSuffix

proc direnvCloseSentinel(): string =
  ResourceCloseSentinelPrefix & DirenvManagedBlockId &
    ResourceCloseSentinelSuffix

proc direnvManagedBlockContent(): string =
  let guard = DirenvActivationGuard
  result = "# Generated by repro hooks ensure --shell-direnv. Do not edit this block.\n"
  result.add("_repro_direnv_activate() {\n")
  result.add("  if [ -n \"${" & guard & ":-}\" ]; then\n")
  result.add("    return 0\n")
  result.add("  fi\n")
  result.add("  export " & guard & "=1\n")
  result.add("  local repro_cmd=\"${REPROBUILD_REPRO:-repro}\"\n")
  result.add("  if ! command -v \"$repro_cmd\" >/dev/null 2>&1 && [ ! -x \"$repro_cmd\" ]; then\n")
  result.add("    echo \"repro hooks: repro CLI not found; set REPROBUILD_REPRO or put repro on PATH\" >&2\n")
  result.add("    unset " & guard & "\n")
  result.add("    return 1\n")
  result.add("  fi\n")
  result.add("  \"$repro_cmd\" hooks ensure --vcs \"$PWD\" >/dev/null 2>&1 || true\n")
  result.add("  local repro_status=0\n")
  result.add("  if [ -n \"${REPRO_DIRENV_STATS:-}\" ]; then\n")
  result.add("    eval \"$(\"$repro_cmd\" __repro-direnv-activate \"$PWD\" --dev-env-stats \"$REPRO_DIRENV_STATS\")\" || repro_status=$?\n")
  result.add("  else\n")
  result.add("    eval \"$(\"$repro_cmd\" __repro-direnv-activate \"$PWD\")\" || repro_status=$?\n")
  result.add("  fi\n")
  result.add("  unset " & guard & "\n")
  result.add("  return \"$repro_status\"\n")
  result.add("}\n")
  result.add("_repro_direnv_activate\n")
  result.add("_repro_direnv_status=$?\n")
  result.add("unset -f _repro_direnv_activate\n")
  result.add("return \"$_repro_direnv_status\"\n")

proc resolveHooksTarget(path: string): string =
  let raw = if path.len > 0: path else: "."
  result = os.normalizedPath(absolutePath(raw))
  if fileExists(extendedPath(result)) and not dirExists(extendedPath(result)):
    result = parentDir(result)

proc managedBlockMalformed(content: string): bool =
  let openIdx = content.find(direnvOpenSentinel())
  let closeIdx = content.find(direnvCloseSentinel())
  (openIdx >= 0 and closeIdx < 0) or (openIdx < 0 and closeIdx >= 0) or
    (openIdx >= 0 and closeIdx >= 0 and closeIdx <= openIdx)

proc contentOutsideManagedBlock(content: string): string =
  let openS = direnvOpenSentinel()
  let closeS = direnvCloseSentinel()
  let openIdx = content.find(openS)
  let closeIdx = content.find(closeS)
  if openIdx < 0 or closeIdx < 0 or closeIdx <= openIdx:
    return content
  var openLineStart = openIdx
  while openLineStart > 0 and content[openLineStart - 1] != '\n':
    dec openLineStart
  var closeLineEnd = closeIdx + closeS.len
  if closeLineEnd < content.len and content[closeLineEnd] == '\n':
    inc closeLineEnd
  content[0 ..< openLineStart] & content[closeLineEnd .. ^1]

proc hasUnmanagedDirenvConflict(content: string): bool =
  let outside = content.contentOutsideManagedBlock().toLowerAscii()
  for marker in [
    "__repro-direnv-activate",
    "repro shell",
    "repro exec",
    "repro_dev_env_",
    "repro_direnv_",
    "reprobuild_repro"
  ]:
    if outside.contains(marker):
      return true

proc validateEnvrcForEnsure(envrcPath: string) =
  if not fileExists(extendedPath(envrcPath)):
    return
  let content = readFile(extendedPath(envrcPath))
  if content.managedBlockMalformed():
    raise newException(ValueError,
      "conflicting .envrc: found an incomplete Reprobuild managed block in " &
        envrcPath & "; repair or remove the sentinels before running ensure")
  if content.hasUnmanagedDirenvConflict():
    raise newException(ValueError,
      "conflicting unmanaged .envrc in " & envrcPath &
        ": existing user-owned content appears to activate Reprobuild. " &
        "Move that logic into the Reprobuild-managed block by removing it " &
        "or run uninstall first.")

proc ensureDirenvHook(targetPath: string; reinstall = false) =
  let projectRoot = resolveHooksTarget(targetPath)
  createDir(extendedPath(projectRoot))
  let envrcPath = projectRoot / ".envrc"
  if reinstall:
    destroyManagedBlockResource(envrcPath, DirenvManagedBlockId)
  validateEnvrcForEnsure(envrcPath)
  discard applyManagedBlockResource(envrcPath, DirenvManagedBlockId,
    direnvManagedBlockContent())
  echo "repro hooks: ensured direnv .envrc block at " & envrcPath

proc uninstallDirenvHook(targetPath: string) =
  let projectRoot = resolveHooksTarget(targetPath)
  let envrcPath = projectRoot / ".envrc"
  if fileExists(extendedPath(envrcPath)) and
      readFile(extendedPath(envrcPath)).managedBlockMalformed():
    raise newException(ValueError,
      "conflicting .envrc: found an incomplete Reprobuild managed block in " &
        envrcPath & "; refusing to edit user-owned content")
  destroyManagedBlockResource(envrcPath, DirenvManagedBlockId)
  echo "repro hooks: removed direnv .envrc block from " & envrcPath

proc nativePosixHookContent(shell: NativeShellKind): string =
  let shellName = shell.nativeShellName()
  let shellArg = if shell == nskZsh: "zsh" else: "bash"
  result = "# Generated by repro hooks ensure --shell " & shellName &
    ". Do not edit this block.\n"
  result.add("__repro_native_shell_hook() {\n")
  result.add("  if [ -n \"${" & NativeShellActivationGuard & ":-}\" ]; then\n")
  result.add("    return 0\n")
  result.add("  fi\n")
  result.add("  export " & NativeShellActivationGuard & "=1\n")
  result.add("  local __repro_native_repro=\"${REPROBUILD_REPRO:-repro}\"\n")
  result.add("  if ! command -v \"$__repro_native_repro\" >/dev/null 2>&1 && [ ! -x \"$__repro_native_repro\" ]; then\n")
  result.add("    echo \"repro hooks: repro CLI not found; set REPROBUILD_REPRO or put repro on PATH\" >&2\n")
  result.add("    unset " & NativeShellActivationGuard & "\n")
  result.add("    return 1\n")
  result.add("  fi\n")
  result.add("  local __repro_native_status=0\n")
  result.add("  local __repro_native_script\n")
  result.add("  if [ -n \"${REPRO_NATIVE_SHELL_STATS:-}\" ]; then\n")
  result.add("    __repro_native_script=\"$(\"$__repro_native_repro\" __repro-native-shell-activate \"$PWD\" --shell " & shellArg & " --previous-artifact \"${REPRO_DEV_ENV_ARTIFACT:-}\" --previous-project-root \"${REPRO_DEV_ENV_PROJECT_ROOT:-}\" --dev-env-stats \"$REPRO_NATIVE_SHELL_STATS\")\" || __repro_native_status=$?\n")
  result.add("  else\n")
  result.add("    __repro_native_script=\"$(\"$__repro_native_repro\" __repro-native-shell-activate \"$PWD\" --shell " & shellArg & " --previous-artifact \"${REPRO_DEV_ENV_ARTIFACT:-}\" --previous-project-root \"${REPRO_DEV_ENV_PROJECT_ROOT:-}\")\" || __repro_native_status=$?\n")
  result.add("  fi\n")
  result.add("  if [ \"$__repro_native_status\" -eq 0 ]; then\n")
  result.add("    eval \"$__repro_native_script\"\n")
  result.add("  else\n")
  result.add("    printf '%s\\n' \"$__repro_native_script\" >&2\n")
  result.add("  fi\n")
  result.add("  unset " & NativeShellActivationGuard & "\n")
  result.add("  unset __repro_native_repro __repro_native_script\n")
  result.add("  return \"$__repro_native_status\"\n")
  result.add("}\n")
  case shell
  of nskBash:
    result.add("cd() { builtin cd \"$@\" || return $?; __repro_native_shell_hook; }\n")
    result.add("pushd() { builtin pushd \"$@\" || return $?; __repro_native_shell_hook; }\n")
    result.add("popd() { builtin popd \"$@\" || return $?; __repro_native_shell_hook; }\n")
  of nskZsh:
    result.add("autoload -Uz add-zsh-hook\n")
    result.add("add-zsh-hook chpwd __repro_native_shell_hook\n")
  else:
    discard
  result.add("__repro_native_shell_hook\n")

proc nativeFishHookContent(): string =
  result = "# Generated by repro hooks ensure --shell fish. Do not edit this block.\n"
  result.add("function __repro_native_shell_hook --on-variable PWD\n")
  result.add("  if set -q " & NativeShellActivationGuard & "\n")
  result.add("    return 0\n")
  result.add("  end\n")
  result.add("  set -gx " & NativeShellActivationGuard & " 1\n")
  result.add("  set -l __repro_native_repro \"$REPROBUILD_REPRO\"\n")
  result.add("  if test -z \"$__repro_native_repro\"\n")
  result.add("    set __repro_native_repro repro\n")
  result.add("  end\n")
  result.add("  if not test -x \"$__repro_native_repro\"; and not type -q \"$__repro_native_repro\"\n")
  result.add("    echo \"repro hooks: repro CLI not found; set REPROBUILD_REPRO or put repro on PATH\" >&2\n")
  result.add("    set -e " & NativeShellActivationGuard & "\n")
  result.add("    return 1\n")
  result.add("  end\n")
  result.add("  set -l __repro_native_tmp (mktemp)\n")
  result.add("  if set -q REPRO_NATIVE_SHELL_STATS\n")
  result.add("    \"$__repro_native_repro\" __repro-native-shell-activate \"$PWD\" --shell fish --previous-artifact \"$REPRO_DEV_ENV_ARTIFACT\" --previous-project-root \"$REPRO_DEV_ENV_PROJECT_ROOT\" --dev-env-stats \"$REPRO_NATIVE_SHELL_STATS\" > \"$__repro_native_tmp\"\n")
  result.add("  else\n")
  result.add("    \"$__repro_native_repro\" __repro-native-shell-activate \"$PWD\" --shell fish --previous-artifact \"$REPRO_DEV_ENV_ARTIFACT\" --previous-project-root \"$REPRO_DEV_ENV_PROJECT_ROOT\" > \"$__repro_native_tmp\"\n")
  result.add("  end\n")
  result.add("  set -l __repro_native_status $status\n")
  result.add("  if test $__repro_native_status -eq 0\n")
  result.add("    source \"$__repro_native_tmp\"\n")
  result.add("  else\n")
  result.add("    cat \"$__repro_native_tmp\" >&2\n")
  result.add("  end\n")
  result.add("  rm -f \"$__repro_native_tmp\"\n")
  result.add("  set -e " & NativeShellActivationGuard & "\n")
  result.add("  return $__repro_native_status\n")
  result.add("end\n")
  result.add("__repro_native_shell_hook\n")

proc nativePowerShellHookContent(): string =
  result = "# Generated by repro hooks ensure --shell powershell. Do not edit this block.\n"
  result.add("function Invoke-ReproNativeShellHook {\n")
  result.add("  if ($env:" & NativeShellActivationGuard & ") { return }\n")
  result.add("  $env:" & NativeShellActivationGuard & " = '1'\n")
  result.add("  $reproCmd = if ($env:REPROBUILD_REPRO) { $env:REPROBUILD_REPRO } else { 'repro' }\n")
  result.add("  $args = @('__repro-native-shell-activate', (Get-Location).Path, '--shell', 'powershell', '--previous-artifact', $env:REPRO_DEV_ENV_ARTIFACT, '--previous-project-root', $env:REPRO_DEV_ENV_PROJECT_ROOT)\n")
  result.add("  if ($env:REPRO_NATIVE_SHELL_STATS) { $args += @('--dev-env-stats', $env:REPRO_NATIVE_SHELL_STATS) }\n")
  result.add("  $script = & $reproCmd @args\n")
  result.add("  if ($LASTEXITCODE -eq 0) { Invoke-Expression ($script -join \"`n\") }\n")
  result.add("  else { [Console]::Error.WriteLine(($script -join \"`n\")) }\n")
  result.add("  Remove-Item Env:" & NativeShellActivationGuard & " -ErrorAction SilentlyContinue\n")
  result.add("}\n")
  result.add("function Set-Location {\n")
  result.add("  Microsoft.PowerShell.Management\\Set-Location @args\n")
  result.add("  if ($?) { Invoke-ReproNativeShellHook }\n")
  result.add("}\n")
  result.add("Set-Alias cd Set-Location -Option AllScope\n")
  result.add("Set-Alias chdir Set-Location -Option AllScope\n")
  result.add("Set-Alias sl Set-Location -Option AllScope\n")
  result.add("Invoke-ReproNativeShellHook\n")

proc nativeShellHookContent(shell: NativeShellKind): string =
  case shell
  of nskBash, nskZsh:
    nativePosixHookContent(shell)
  of nskFish:
    nativeFishHookContent()
  of nskPowerShell:
    nativePowerShellHookContent()

proc ensureNativeShellHook(shell: NativeShellKind; reinstall = false) =
  let rcPath = nativeShellRcPath(shell)
  let writePath = rcFileWritePath(rcPath)
  if reinstall:
    destroyManagedBlockResource(writePath, nativeShellBlockId(shell))
  discard applyManagedBlockResource(writePath, nativeShellBlockId(shell),
    nativeShellHookContent(shell))
  echo "repro hooks: ensured native " & shell.nativeShellName() &
    " shell block at " & rcPath

proc uninstallNativeShellHook(shell: NativeShellKind) =
  let rcPath = nativeShellRcPath(shell)
  let writePath = rcFileWritePath(rcPath)
  destroyManagedBlockResource(writePath, nativeShellBlockId(shell))
  echo "repro hooks: removed native " & shell.nativeShellName() &
    " shell block from " & rcPath

proc gitTopLevel(targetPath: string): string =
  let res = execCmdEx(shellCommand(@["git", "-C", resolveHooksTarget(targetPath),
    "rev-parse", "--show-toplevel"]), env = scrubbedGitRepositoryEnv())
  if res.exitCode == 0:
    result = os.normalizedPath(res.output.strip())

proc gitHooksDir(targetPath: string): string =
  let repoRoot = gitTopLevel(targetPath)
  if repoRoot.len == 0:
    raise newException(ValueError,
      "VCS hook target is not inside a Git repository: " &
        resolveHooksTarget(targetPath))
  # Respect core.hooksPath and linked-worktree/submodule gitdir indirection.
  # Asking Git for its effective hook path is the only source of truth; simply
  # appending `hooks` to --absolute-git-dir silently installs an unused bundle
  # when core.hooksPath is configured.
  var res = execCmdEx(shellCommand(@["git", "-C", repoRoot, "rev-parse",
    "--path-format=absolute", "--git-path", "hooks"]),
    env = scrubbedGitRepositoryEnv())
  if res.exitCode == 0 and res.output.strip().len > 0:
    return os.normalizedPath(res.output.strip())
  # Compatibility fallback for Git versions predating --path-format.
  res = execCmdEx(shellCommand(@["git", "-C", repoRoot, "rev-parse",
    "--git-path", "hooks"]), env = scrubbedGitRepositoryEnv())
  if res.exitCode != 0 or res.output.strip().len == 0:
    raise newException(ValueError,
      "could not locate Git hooks directory for " & repoRoot & ": " &
        res.output.strip())
  let raw = res.output.strip()
  result = if raw.isAbsolute: os.normalizedPath(raw)
    else: os.normalizedPath(repoRoot / raw)

proc hookPath(hooksDir, hookName: string): string =
  hooksDir / hookName

proc localHookPath(hooksDir, hookName: string): string =
  hooksDir / (hookName & ".repro-local")

proc managedHookPath(hooksDir, hookName: string): string =
  hooksDir / (hookName & ".repro-managed")

proc fileContains(path, marker: string): bool =
  fileExists(extendedPath(path)) and readFile(extendedPath(path)).contains(marker)

proc isReprobuildVcsHook(path, hookName: string): bool =
  fileContains(path, VcsDispatcherMarker) or
    fileContains(path, "reprobuild hook dispatcher") or
    fileContains(path, "reprobuild managed " & hookName & " hook")

proc ensureExecutable(path: string) =
  if not fileExists(extendedPath(path)):
    return
  var permissions = getFilePermissions(extendedPath(path))
  permissions.incl(fpUserExec)
  permissions.incl(fpGroupExec)
  permissions.incl(fpOthersExec)
  setFilePermissions(extendedPath(path), permissions)

proc writeExecutableIfChanged(path, content: string): bool =
  if fileExists(extendedPath(path)) and readFile(extendedPath(path)) == content:
    ensureExecutable(path)
    return false
  writeFile(extendedPath(path), content)
  ensureExecutable(path)
  true

proc removeFileIfExists(path: string): bool =
  if fileExists(extendedPath(path)):
    removeFile(extendedPath(path))
    return true
  false

proc moveFileReplacing(source, dest: string) =
  if fileExists(extendedPath(dest)):
    removeFile(extendedPath(dest))
  moveFile(extendedPath(source), extendedPath(dest))

proc vcsDispatcherContent(hookName: string): string =
  ## RA-4: the dispatcher coexists with the pre-commit framework's
  ## ``hook-impl`` shim. Two safeguards (modelled on repo-workspaces
  ## ``9ee9141``):
  ##
  ##   1. A preserved local hook may be pre-commit's ``hook-impl`` shim.
  ##      pre-commit self-checks for migration mode via
  ##      ``PRE_COMMIT_RUNNING_LEGACY`` and ABORTS with a "was installed in
  ##      migration mode" error if it sees that variable set — which happens
  ##      when pre-commit was installed over a previous Reprobuild
  ##      dispatcher. The dispatcher clears that variable in the child env so
  ##      the chained shim runs cleanly instead of re-entering itself.
  ##   2. pre-commit's ``hook-impl`` shim chains into ``$HOOK_DIR/<hook>.legacy``.
  ##      When pre-commit was installed on top of a previous Reprobuild
  ##      dispatcher, that ``.legacy`` file *is* a Reprobuild dispatcher, so
  ##      running the shim re-enters the dispatcher (and the shim) until it
  ##      crashes. Such a file is always our own dispatcher, never a genuine
  ##      user hook, so the dispatcher removes it defensively at runtime.
  ##      (``ensure`` performs the same cleanup; this is the runtime safety
  ##      net for a pre-commit reinstall after hooks were set up.)
  result = "#!/usr/bin/env sh\n"
  result.add("# " & VcsDispatcherMarker & "\n")
  result.add("# Dispatches preserved user hooks and Reprobuild-managed " &
    hookName & " logic.\n")
  result.add("set -eu\n")
  result.add("set +x\n")
  # Protocol v2 never trusts an inherited boolean recursion sentinel. Capture
  # the opaque one-use token, then scrub both it and the legacy sentinel before
  # invoking preserved user hooks.
  result.add("REPROBUILD_CAPTURED_CAPABILITY=${" & HookCapabilityEnv & ":-}\n")
  result.add("REPROBUILD_CAPTURED_INTERNAL_CONTEXT=${" &
    InternalHookContextEnv & ":-}\n")
  result.add("unset " & HookCapabilityEnv & " " & LegacyHookSentinelEnv &
    " " & HookDispatcherProtocolEnv & " " & InternalHookContextEnv & "\n\n")
  result.add("HOOK_DIR=$(CDPATH= cd -- \"$(dirname -- \"$0\")\" && pwd)\n")
  result.add("LOCAL_HOOK=\"$HOOK_DIR/" & hookName & ".repro-local\"\n")
  result.add("MANAGED_HOOK=\"$HOOK_DIR/" & hookName & ".repro-managed\"\n\n")
  result.add("REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd -P)\n")
  result.add("if [ -n \"${REPROBUILD_REPRO:-}\" ] && [ -x \"$REPROBUILD_REPRO\" ]; then\n")
  result.add("  REPRO_REMEDY_CMD=$REPROBUILD_REPRO\n")
  result.add("elif command -v repro >/dev/null 2>&1; then\n")
  result.add("  REPRO_REMEDY_CMD=$(command -v repro)\n")
  result.add("else\n")
  result.add("  REPRO_REMEDY_CMD=repro\n")
  result.add("fi\n\n")
  # (2) Drop a stale pre-commit `.legacy` that is actually our dispatcher,
  # otherwise a chained pre-commit shim re-enters us in a loop.
  result.add("PRECOMMIT_LEGACY=\"$HOOK_DIR/" & hookName & ".legacy\"\n")
  result.add("if [ -f \"$PRECOMMIT_LEGACY\" ] && " &
    "grep -q 'reprobuild hook dispatcher' \"$PRECOMMIT_LEGACY\" 2>/dev/null; then\n")
  result.add("  rm -f \"$PRECOMMIT_LEGACY\"\n")
  result.add("fi\n\n")
  if hookName == "pre-push":
    result.add("TMP_FILE=$(mktemp \"${TMPDIR:-/tmp}/reprobuild-pre-push.XXXXXX\")\n")
    result.add("chmod 600 \"$TMP_FILE\"\n")
    result.add("trap 'rm -f \"$TMP_FILE\"' EXIT HUP INT TERM\n")
    result.add("cat > \"$TMP_FILE\"\n")
    # (1) Clear pre-commit's migration-mode guard for each chained hook.
    result.add("if [ -x \"$LOCAL_HOOK\" ]; then PRE_COMMIT_RUNNING_LEGACY= \"$LOCAL_HOOK\" \"$@\" < \"$TMP_FILE\" || exit $?; fi\n")
    result.add("if [ ! -x \"$MANAGED_HOOK\" ] || ! grep -q '" &
      V2ManagedMarker & "' \"$MANAGED_HOOK\" 2>/dev/null; then\n")
    result.add("  echo \"repro hooks: hook protocol mismatch; run '$REPRO_REMEDY_CMD hooks ensure --vcs $REPO_ROOT' and retry\" >&2\n")
    result.add("  exit 1\n")
    result.add("fi\n")
    result.add("PRE_COMMIT_RUNNING_LEGACY= " & HookDispatcherProtocolEnv &
      "=2 " & HookCapabilityEnv &
      "=\"$REPROBUILD_CAPTURED_CAPABILITY\" \"$MANAGED_HOOK\" \"$@\" < \"$TMP_FILE\" || exit $?\n")
  else:
    result.add("if [ -x \"$LOCAL_HOOK\" ]; then PRE_COMMIT_RUNNING_LEGACY= \"$LOCAL_HOOK\" \"$@\" || exit $?; fi\n")
    result.add("if [ -x \"$MANAGED_HOOK\" ]; then PRE_COMMIT_RUNNING_LEGACY= " &
      InternalHookContextEnv &
      "=\"$REPROBUILD_CAPTURED_INTERNAL_CONTEXT\" \"$MANAGED_HOOK\" \"$@\" || exit $?; fi\n")
  result.add("exit 0\n")

proc vcsManagedHookBody(hookName, hookContract: string): string =
  ## Canonical managed-hook body. M17 wires the dispatch path as
  ## ``repro hooks dispatch <name>`` (no-op until later milestones
  ## register a body). Drift detection compares the on-disk file to
  ## this exact string, so any future change to the body bumps every
  ## installed hook on the next ``ensure``.
  ##
  ## ``hookContract`` is the token the generated body requires its resolved
  ## ``repro`` to confirm before it will dispatch (see
  ## ``managedHookContract``). It is threaded in as a PARAMETER rather than
  ## computed here because the token is a digest OF this body: computing it
  ## inside would be self-referential. ``managedHookContract`` renders the body
  ## once with an empty token to derive the digest; ``vcsManagedHookContent``
  ## then renders it again with the real one.
  result = "#!/usr/bin/env sh\n"
  if hookName == "pre-push":
    result.add("# " & V2ManagedMarker & "\n")
  else:
    result.add("# reprobuild managed " & hookName & " hook\n")
  result.add("# managed-by: reprobuild hooks ensure\n")
  result.add("# dispatches to: repro hooks dispatch " & hookName & "\n")
  result.add("set -eu\n")
  result.add("set +x\n")
  result.add("REPROBUILD_CAPTURED_INTERNAL_CONTEXT=${" &
    InternalHookContextEnv & ":-}\n")
  result.add("unset " & InternalHookContextEnv & "\n")
  if hookName == "post-commit":
    result.add("if [ \"$REPROBUILD_CAPTURED_INTERNAL_CONTEXT\" = \"" &
      InternalLockCommitContext & "\" ]; then exit 0; fi\n")
  if hookName == "pre-push":
    result.add("REPROBUILD_CAPTURED_CAPABILITY=${" & HookCapabilityEnv & ":-}\n")
    result.add("REPROBUILD_CAPTURED_DISPATCH_PROTOCOL=${" &
      HookDispatcherProtocolEnv & ":-}\n")
    result.add("unset " & HookCapabilityEnv & " " &
      HookDispatcherProtocolEnv & " " & LegacyHookSentinelEnv & "\n")
  # The hook records HOW it resolved its interpreter, not just which one. The
  # PATH fallback is the silent step that let an outdated install speak for
  # hooks a newer build generated, so every diagnostic below names both the
  # binary and the source it came from.
  result.add("REPRO_CMD=\n")
  result.add("REPRO_CMD_SOURCE=\n")
  result.add("find_repro_cmd() {\n")
  result.add("  if [ -n \"${REPROBUILD_REPRO:-}\" ]; then\n")
  result.add("    if [ -x \"$REPROBUILD_REPRO\" ]; then\n")
  result.add("      REPRO_CMD=$REPROBUILD_REPRO\n")
  result.add("      REPRO_CMD_SOURCE=REPROBUILD_REPRO\n")
  result.add("      return 0\n")
  result.add("    fi\n")
  result.add("    return 1\n")
  result.add("  fi\n")
  result.add("  if command -v repro >/dev/null 2>&1; then\n")
  result.add("    REPRO_CMD=$(command -v repro)\n")
  result.add("    REPRO_CMD_SOURCE=PATH\n")
  result.add("    return 0\n")
  result.add("  fi\n")
  result.add("  return 1\n")
  result.add("}\n\n")
  # The refusal an unconfirmed interpreter earns. It names the hook, the
  # binary, where the binary came from, and the contract the hook was
  # generated for — everything the operator needs to stop suspecting the
  # workspace and start suspecting the interpreter.
  result.add("repro_contract_refusal() {\n")
  result.add("  echo \"repro hooks: " & hookName & ": the resolved 'repro' " &
    "does not speak this hook's contract.\" >&2\n")
  result.add("  echo \"repro hooks:   resolved binary: $REPRO_CMD " &
    "(resolved from $REPRO_CMD_SOURCE)\" >&2\n")
  result.add("  echo \"repro hooks:   hook contract:   " & hookContract &
    "\" >&2\n")
  result.add("  echo \"repro hooks: This hook was generated by a different " &
    "'repro' build, so that build's\" >&2\n")
  result.add("  echo \"repro hooks: diagnostics would not describe this " &
    "hook. Set REPROBUILD_REPRO to the\" >&2\n")
  result.add("  echo \"repro hooks: matching binary, or reinstall these " &
    "hooks with '<that binary> hooks\" >&2\n")
  result.add("  echo \"repro hooks: ensure --vcs $REPO_ROOT'.\" >&2\n")
  result.add("}\n\n")
  # Attribution for a dispatch that DID run and failed: the binary that
  # produced the refusal is named next to it, so a diagnostic can never be
  # read as coming from a build other than the one that emitted it.
  result.add("repro_dispatch_attribution() {\n")
  result.add("  echo \"repro hooks: " & hookName & " above was produced by " &
    "$REPRO_CMD (resolved from $REPRO_CMD_SOURCE).\" >&2\n")
  result.add("}\n\n")
  result.add("REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd)\n")
  result.add("cd \"$REPO_ROOT\"\n")
  # Resolve the invoking checkout first: Git's hook environment is the source
  # of truth for a linked worktree's root. Only the managed child boundary is
  # scrubbed; the dispatcher has already invoked a preserved user hook with
  # the original Git repository bindings, argv, and stdin.
  result.add("unset " & GitRepositoryLocalEnv.join(" ") & "\n")
  # Do not trust GIT_CONFIG_COUNT to enumerate the indexed variables. A stale
  # or hostile hook environment can contain higher or malformed suffixes, and
  # the in-process scrubber deliberately treats the complete prefixes as
  # repository-local. Environment names cannot contain whitespace, so this
  # POSIX loop safely enumerates every matching name without inspecting values.
  result.add("for REPROBUILD_GIT_CONFIG_NAME in $(env | sed -n " &
    "-e 's/^\\(GIT_CONFIG_KEY_[A-Za-z0-9_]*\\)=.*/\\1/p' " &
    "-e 's/^\\(GIT_CONFIG_VALUE_[A-Za-z0-9_]*\\)=.*/\\1/p'); do\n")
  result.add("  unset \"$REPROBUILD_GIT_CONFIG_NAME\"\n")
  result.add("done\n")
  result.add("unset REPROBUILD_GIT_CONFIG_NAME\n")
  result.add("if find_repro_cmd; then\n")
  if hookName == "pre-push":
    result.add("  if [ \"$REPROBUILD_CAPTURED_DISPATCH_PROTOCOL\" != \"2\" ]; then\n")
    result.add("    echo \"repro hooks: hook protocol mismatch; run '$REPRO_CMD hooks ensure --vcs $REPO_ROOT' and retry\" >&2\n")
    result.add("    exit 1\n")
    result.add("  fi\n")
    result.add("  REFS_FILE=$(mktemp \"${TMPDIR:-/tmp}/reprobuild-pre-push-backend.XXXXXX\")\n")
    result.add("  chmod 600 \"$REFS_FILE\"\n")
    result.add("  trap 'rm -f \"$REFS_FILE\"' EXIT HUP INT TERM\n")
    result.add("  cat > \"$REFS_FILE\"\n")
    # The contract handshake. A binary that predates it rejects the flag it
    # does not know and lands here too — which is the correct verdict for it.
    # pre-push REFUSES: a gate an unidentified build decides is not a gate.
    result.add("  if ! \"$REPRO_CMD\" hooks protocol --require=2 " &
      "--hook-contract=" & hookContract & " >/dev/null 2>&1; then\n")
    result.add("    repro_contract_refusal\n")
    result.add("    exit 1\n")
    result.add("  fi\n")
    result.add("  REPRO_STATUS=0\n")
    result.add("  " & HookCapabilityEnv &
      "=\"$REPROBUILD_CAPTURED_CAPABILITY\" \"$REPRO_CMD\" hooks dispatch " &
      hookName & " --protocol=2 --repo-root \"$REPO_ROOT\" --refs-file \"$REFS_FILE\" -- \"$@\"" &
      " || REPRO_STATUS=$?\n")
  else:
    # The non-blocking hooks announce and keep going: failing a commit after
    # the fact would be worse than the mismatch being reported.
    result.add("  if ! \"$REPRO_CMD\" hooks protocol --require=2 " &
      "--hook-contract=" & hookContract & " >/dev/null 2>&1; then\n")
    result.add("    repro_contract_refusal\n")
    result.add("    exit 0\n")
    result.add("  fi\n")
    result.add("  REPRO_STATUS=0\n")
    result.add("  \"$REPRO_CMD\" hooks dispatch " & hookName &
      " --repo-root \"$REPO_ROOT\" -- \"$@\" || REPRO_STATUS=$?\n")
  result.add("  if [ \"$REPRO_STATUS\" -ne 0 ]; then " &
    "repro_dispatch_attribution; fi\n")
  result.add("  exit $REPRO_STATUS\n")
  result.add("fi\n")
  if hookName == "pre-push":
    result.add("echo \"repro hooks: hook protocol mismatch; run 'repro hooks ensure --vcs $REPO_ROOT' and retry\" >&2\n")
    result.add("exit 1\n")
  else:
    result.add("echo \"repro hooks: repro CLI not found on PATH; skipping " &
      hookName & "\" >&2\n")
    result.add("exit 0\n")

const ManagedHookContractPrefix* = "reprobuild.managed-hook.v1"
  ## Namespace of the token a generated managed-hook body requires its resolved
  ## ``repro`` to confirm.

proc managedHookContract*(hookName: string): string =
  ## The contract token for ``hookName``: the namespace, the hook name, and a
  ## digest of the body THIS build generates for it.
  ##
  ## Deriving the token from the body rather than hand-maintaining a version
  ## constant is the point. The thing that must not drift is the pairing
  ## between an installed hook body and the CLI that services it, so the token
  ## moves exactly when the body does — a constant would have to be remembered,
  ## and the failure of remembering is what this whole check exists to catch.
  ##
  ## Scope, stated honestly: this proves "the binary in front of me generates
  ## the hook I am" — it does NOT prove the two builds agree about everything
  ## else. Two builds that share a hook body but differ in, say, manifest
  ## parsing both pass it. That residue is covered by the second obligation in
  ## the generated body: any dispatch that fails is attributed to the binary
  ## that produced it by path and by how it was resolved.
  ManagedHookContractPrefix & "." & hookName & "." &
    digestHex(weakFingerprintFromText(vcsManagedHookBody(hookName, "")))[0 .. 15]

proc managedHookNameFromContract*(contract: string): string =
  ## Recover the hook name from a contract token, or "" when the token is not
  ## one of ours. The name is the segment between the namespace and the digest.
  let prefix = ManagedHookContractPrefix & "."
  if not contract.startsWith(prefix):
    return ""
  let rest = contract[prefix.len .. ^1]
  let lastDot = rest.rfind('.')
  if lastDot <= 0:
    return ""
  rest[0 ..< lastDot]

proc vcsManagedHookContent(hookName: string): string =
  ## The canonical managed-hook body, carrying the contract token of THIS
  ## build. Drift detection compares the on-disk file to this exact string, so
  ## a hook installed by a build with a different body is rewritten by the next
  ## ``repro hooks ensure --vcs``.
  vcsManagedHookBody(hookName, managedHookContract(hookName))

type
  VcsHookEnsureOutcome* = enum
    ## M17 status codes for ``repro hooks ensure --vcs``. Distinct from
    ## the M18+ runtime outcomes the dispatcher itself can return.
    vheoAlreadyUpToDate ## Dispatcher + managed body already match canonical content.
    vheoInstalled ## A fresh install or a missing file was created.
    vheoChainedUserHook ## A pre-existing non-managed hook was preserved as ``<name>.repro-local``.
    vheoRefreshedDrifted ## Sentinel present but body diverged; rewrote canonical content.
    vheoReclaimedShadowed
      ## The dispatcher had been overwritten at the canonical path by a
      ## foreign installer re-running over an ALREADY-chained copy of
      ## itself, and was reinstalled. Distinct from ``chained-user-hook``
      ## because it reports an interval during which the managed hook did
      ## not run at all — for ``pre-push`` that is an interval during which
      ## the publication gate was silently off. Covers both the case where the
      ## installer rewrote the same bytes and the case where it REGENERATED
      ## its shim against new tool paths, which is the same shadowing with a
      ## different-looking file.

proc sanitizePreCommitLegacyHook(hooksDir, hookName: string): bool =
  ## RA-4: pre-commit's ``hook-impl`` shim chains into
  ## ``<hook>.legacy``. When pre-commit is installed over an existing
  ## Reprobuild dispatcher, it moves that dispatcher to ``<hook>.legacy``.
  ## After ``ensure`` preserves the pre-commit shim as ``<hook>.repro-local``
  ## and reinstalls its own dispatcher, that stale ``<hook>.legacy`` makes
  ## pre-commit re-enter the dispatcher (and itself), tripping its
  ## migration-mode self-check. Such a file is always a Reprobuild
  ## dispatcher, never a genuine user hook, so it is safe to remove.
  let legacy = hooksDir / (hookName & ".legacy")
  if fileExists(extendedPath(legacy)) and
      isReprobuildVcsHook(legacy, hookName):
    return removeFileIfExists(legacy)
  false

const
  PlainToolPathChars = {'A' .. 'Z', 'a' .. 'z', '0' .. '9',
    '/', '\\', '.', '_', '-', '+', ':', '@', '~'}
    ## Characters a bare filesystem path may use and still be read as ONE word
    ## by ``regeneratedShimIdentity``. Anything outside this set (whitespace,
    ## a quote, ``$``, ``;``, ``|``, ``&``, a backtick, a redirection) means
    ## the text is shell syntax rather than a path, and the line is then
    ## compared verbatim instead of being reduced.

proc looksLikeBareToolPath(value: string): bool =
  value.len > 0 and value.allCharsInSet(PlainToolPathChars)

proc regeneratedShimIdentity(content: string): string =
  ## Identity of a hook file that its own installer GENERATES, with the few
  ## parts that installer rewrites on each run reduced away — or ``""`` when
  ## the content is not such a file.
  ##
  ## Only pre-commit's ``hook-impl`` shim is recognised, because it is the one
  ## foreign installer that shares this hooks directory, and because its shim
  ## carries no user content at all: the checks live in
  ## ``.pre-commit-config.yaml``, and the file itself is a fixed template plus
  ## three paths (the interpreter, ``INSTALL_PYTHON``, and the ``pre-commit``
  ## it execs). Under Nix all three move whenever the toolchain is rebuilt,
  ## which is the SAME event that makes pre-commit's installer re-run — so
  ## "the preserved copy differs from the new one" is the expected outcome of
  ## a routine toolchain bump, not a conflict between two authors.
  ##
  ## WHAT IS COMPARED, EXACTLY. This is a fuzzy match, not a byte comparison
  ## with three exceptions, and the difference matters when reading the
  ## refusal it feeds. Two shims compare EQUAL when, line for line:
  ##
  ##   * the ``#!`` line agrees on the interpreter's FILE NAME and on every
  ##     argument after it — so ``#!/store/a/bin/bash`` and
  ##     ``#!/store/b/bin/bash`` are the same, and so are two different
  ##     programs that happen to share a file name;
  ##   * the ``exec`` line agrees on the exec'd program's FILE NAME and on
  ##     every argument after it — same reduction, same blind spot;
  ##   * the ``INSTALL_PYTHON=`` line agrees in INDENTATION and in SHAPE: any
  ##     bare path is equal to any other bare path, because a Python upgrade
  ##     moves the file name too (``python3.13`` -> ``python3.14``) and the
  ##     line carries no user intent. This is a shape check and not a blanket
  ##     elision, so ``INSTALL_PYTHON=x; curl … | sh`` is NOT a bare path, does
  ##     not reduce, and cannot compare equal to a plain one;
  ##   * every OTHER line is byte-identical, indentation included. That covers
  ##     the ``# ID:`` template revision and the whole ``ARGS=(…)`` line, so
  ##     ``--hook-type`` and ``--config`` do discriminate;
  ##   * and the two files agree on their line endings — a CRLF copy and an LF
  ##     copy are not the same file, even though the line split hides it.
  ##
  ## Recognition is narrow at the front, too: the ``# ID:`` line is
  ## pre-commit's own template identity, so a hand-written script that merely
  ## mentions pre-commit yields ``""`` and is never reduced at all.
  ##
  ## The two file-name reductions are deliberately NOT narrowed further: they
  ## are precisely the property that makes a toolchain rebuild repairable
  ## rather than a refusal, which is the whole reason this proc exists. They
  ## are also not a privilege boundary — reaching either one already requires
  ## write access to ``.git/hooks/<hook>``, where the attacker's file is what
  ## Git executes regardless; the only thing decided here is which of two
  ## preserved copies is discarded.
  if not content.contains("File generated by pre-commit"):
    return ""
  var hasId = false
  var normalised: seq[string] = @[]
  for line in content.splitLines():
    let trimmed = line.strip()
    let indent = line[0 ..< line.len - line.strip(trailing = false).len]
    if trimmed.startsWith("# ID: "):
      hasId = true
      normalised.add(line)
    elif line.startsWith("#!"):
      let parts = line[2 .. ^1].strip().splitWhitespace()
      if parts.len == 0:
        normalised.add(line)
      else:
        var rebuilt = "#!" & extractFilename(parts[0])
        for i in 1 ..< parts.len:
          rebuilt.add(" " & parts[i])
        normalised.add(rebuilt)
    elif trimmed.startsWith("INSTALL_PYTHON="):
      let value = trimmed["INSTALL_PYTHON=".len .. ^1]
      if looksLikeBareToolPath(value):
        normalised.add(indent & "INSTALL_PYTHON=<bare-path>")
      else:
        # Not a path: shell syntax, an empty assignment, or something quoted.
        # Whatever it is, it is not what the installer rewrites, so it is
        # compared as written.
        normalised.add(line)
    elif trimmed.startsWith("exec "):
      let parts = trimmed.splitWhitespace()
      if parts.len < 2 or not looksLikeBareToolPath(parts[1]):
        normalised.add(line)
      else:
        var rebuilt = indent & "exec " & extractFilename(parts[1])
        for i in 2 ..< parts.len:
          rebuilt.add(" " & parts[i])
        normalised.add(rebuilt)
    else:
      normalised.add(line)
  if not hasId:
    return ""
  (if '\r' in content: "CRLF\n" else: "LF\n") & normalised.join("\n")

proc ensureVcsHookDetailed(hooksDir, hookName: string): VcsHookEnsureOutcome =
  ## Idempotent installer for one (hooksDir, hookName) pair. Returns a
  ## structured outcome so callers can surface per-repo per-hook status
  ## in the JSON report and the human-readable summary line.
  ##
  ## Outcome priority (the higher-impact change wins when several apply):
  ##   reclaimed-shadowed  >  chained-user-hook  >  refreshed-drifted  >
  ##   installed  >  already-up-to-date
  createDir(extendedPath(hooksDir))
  let standard = hookPath(hooksDir, hookName)
  let local = localHookPath(hooksDir, hookName)
  let managed = managedHookPath(hooksDir, hookName)

  var chainedUser = false
  var reclaimedShadowed = false
  var anyChange = false
  var refreshedDrift = false

  # Stale sentinel-marked local file from an earlier `uninstall` run.
  if fileExists(extendedPath(local)) and isReprobuildVcsHook(local, hookName):
    anyChange = removeFileIfExists(local) or anyChange

  # RA-4: drop a stale pre-commit `<hook>.legacy` that is actually our own
  # dispatcher (left behind when pre-commit was installed over a previous
  # dispatcher) so a chained pre-commit shim does not re-enter us.
  anyChange = sanitizePreCommitLegacyHook(hooksDir, hookName) or anyChange

  # Pre-existing user-owned hook at the canonical path: chain it.
  if fileExists(extendedPath(standard)) and
      not isReprobuildVcsHook(standard, hookName):
    if fileExists(extendedPath(local)):
      # RE-SHADOWING. A foreign installer (pre-commit's ``pre-commit
      # install`` is the one that happens in practice) has taken the
      # canonical path a SECOND time, after ``ensure`` already chained its
      # first copy to ``<hook>.repro-local``. This is not a new user hook
      # competing with an old one — it is the same hook body written again
      # over the dispatcher, and it is the state every shadowed repo is
      # actually found in.
      #
      # Refusing here made the documented remedy for a shadowed hook
      # ("run repro hooks ensure --vcs <repo>") fail precisely when it was
      # needed, so a repo that lost its pre-push gate stayed ungated and
      # published no workspace lock for any of its commits.
      #
      # Byte-identical to the copy we already preserve => nothing to keep
      # that we are not already keeping. Drop the duplicate and let the
      # dispatcher be rewritten below; the chain still runs it first.
      let standardBody = readFile(extendedPath(standard))
      let localBody = readFile(extendedPath(local))
      let standardIdentity = regeneratedShimIdentity(standardBody)
      if standardBody == localBody:
        discard removeFileIfExists(standard)
        ensureExecutable(local)
        reclaimedShadowed = true
        anyChange = true
      elif standardIdentity.len > 0 and
          standardIdentity == regeneratedShimIdentity(localBody):
        # REGENERATED, not in conflict. The two files are the same generated
        # shim written twice by the same installer, differing only in the
        # paths that installer rebuilds — so they are not two authors'
        # competing checks and there is nothing of the user's to weigh.
        #
        # Byte-equality alone could not see this, and that made the refusal
        # fire on the one event that reliably produces this state: a toolchain
        # rebuild moves the shim's store paths AND changes the generated
        # config, so the installer re-runs and writes a shim that differs from
        # the copy already preserved. The remedy for a shadowed hook then
        # failed exactly when a shadowed hook existed, leaving the repo with
        # no publication gate and no working way to get one back.
        #
        # Keep the copy at the canonical path — it is the one the installer
        # just wrote, so it is the one whose paths still resolve — and let it
        # replace the stale preserved copy in the chain.
        moveFileReplacing(standard, local)
        ensureExecutable(local)
        reclaimedShadowed = true
        anyChange = true
      else:
        # Two DIFFERENT foreign hooks. There is no basis for discarding
        # either, and silently picking one would lose a user's checks, so
        # refuse — but name both files and the way out.
        raise newException(ValueError,
          "cannot install " & hookName & ": " & standard &
            " is user-owned and " & local &
            " already holds a different preserved hook. Reconcile them by " &
            "hand: merge the checks you want into " & local &
            " (which the dispatcher runs first), delete " & standard &
            ", then re-run 'repro hooks ensure --vcs " &
            parentDir(parentDir(hooksDir)) & "'.")
    else:
      moveFileReplacing(standard, local)
      ensureExecutable(local)
      chainedUser = true
      anyChange = true

  # Detect drift: file exists, sentinel matches, body diverges from canonical.
  let canonicalManaged = vcsManagedHookContent(hookName)
  if fileExists(extendedPath(managed)) and
      isReprobuildVcsHook(managed, hookName) and
      readFile(extendedPath(managed)) != canonicalManaged:
    refreshedDrift = true
  let canonicalDispatcher = vcsDispatcherContent(hookName)
  if fileExists(extendedPath(standard)) and
      isReprobuildVcsHook(standard, hookName) and
      readFile(extendedPath(standard)) != canonicalDispatcher:
    refreshedDrift = true

  let managedChanged = writeExecutableIfChanged(managed, canonicalManaged)
  let dispatcherChanged = writeExecutableIfChanged(standard, canonicalDispatcher)
  anyChange = anyChange or managedChanged or dispatcherChanged

  if reclaimedShadowed:
    return vheoReclaimedShadowed
  if chainedUser:
    return vheoChainedUserHook
  if refreshedDrift:
    return vheoRefreshedDrifted
  if anyChange:
    return vheoInstalled
  vheoAlreadyUpToDate

proc ensureVcsHook(hooksDir, hookName: string): bool =
  ## Back-compat single-hook installer that reports a single
  ## "changed / unchanged" boolean. Retained so the legacy single-repo
  ## ``runVcsHooksCommand`` path (used by ``repro hooks reinstall`` and
  ## ``repro hooks uninstall``) keeps the same shape it had before
  ## the workspace-aware M17 ``ensure`` path was added.
  let outcome = ensureVcsHookDetailed(hooksDir, hookName)
  outcome != vheoAlreadyUpToDate

proc selfHealManagedHooks*(repoRoot: string): seq[string] =
  ## Re-assert this repo's managed hook set from a hook that is CURRENTLY
  ## RUNNING, and return one report line per hook that had to be repaired
  ## (empty when everything was already wired).
  ##
  ## Why a hook repairs its own siblings
  ## -----------------------------------
  ##
  ## The managed hooks live in ``.git/hooks``, which is outside version
  ## control, and they share that directory with whatever else installs hooks.
  ## The one that collides in practice is pre-commit, driven from the Nix dev
  ## shell: ``git-hooks.nix`` sets ``shellHook = pre-commit-check.shellHook``,
  ## so EVERY dev-shell entry runs pre-commit's installer, which first
  ## uninstalls the hook types it manages and then installs its own. Depending
  ## on the repo's ``.pre-commit-config.yaml`` that either overwrites the
  ## managed ``pre-push`` dispatcher or DELETES it outright — and it happens
  ## again every time anyone cd's into the repo. A one-off ``repro hooks
  ## ensure`` cannot survive that; the gate silently stops running, no
  ## workspace lock is published for any subsequent commit, and CI fails much
  ## later with "No workspace lock for <repo>".
  ##
  ## The hooks pre-commit is NOT configured for keep running, so they are the
  ## natural repair point: a shell entry can remove ``pre-push``, but the very
  ## next commit / merge / checkout in that repo puts it back, before any push
  ## can slip past the gate. This needs no per-repo flake or ``.envrc`` edit,
  ## which is what makes it hold across every repo in the workspace.
  ##
  ## Never raises and never blocks the git operation that invoked it: a hook
  ## that fails a commit because it could not repair a DIFFERENT hook would be
  ## a worse failure than the one it is fixing. A repair it cannot make safely
  ## (two competing foreign hooks) is reported here and surfaced again, with a
  ## remedy, by the ``vcs-hooks`` check in ``repro health``.
  if repoRoot.len == 0:
    return
  let top = gitTopLevel(repoRoot)
  if top.len == 0:
    return
  let hooksDir = gitHooksDir(top)
  for hookName in VcsHookNames:
    try:
      let outcome = ensureVcsHookDetailed(hooksDir, hookName)
      case outcome
      of vheoAlreadyUpToDate, vheoChainedUserHook:
        discard
      of vheoInstalled:
        result.add("repro hooks: repaired " & hookName & " in " & top &
          " (installed)")
      of vheoRefreshedDrifted:
        result.add("repro hooks: repaired " & hookName & " in " & top &
          " (refreshed-drifted)")
      of vheoReclaimedShadowed:
        result.add("repro hooks: repaired " & hookName & " in " & top &
          " (reclaimed-shadowed)")
    except CatchableError as err:
      result.add("repro hooks: could NOT repair " & hookName & " in " & top &
        ": " & err.msg)

type
  VcsHookEntry* = object
    ## One per (repo, hookName) pair in the M17 JSON report. ``outcome``
    ## is the lowercased ``vheo*`` string (``installed`` /
    ## ``already-up-to-date`` / ``chained-user-hook`` /
    ## ``refreshed-drifted``); ``hookPath`` and ``managedPath`` are the
    ## absolute paths the installer touched (or would touch).
    repo*: string
    repoPath*: string
    hook*: string
    outcome*: string
    hookPath*: string
    managedPath*: string

  HooksEnsureReport* = object
    ## Structured outcome of one ``repro hooks ensure --vcs`` invocation
    ## written to ``<workspaceRoot>/.repro/build/reports/hooks-report.json``.
    workspaceRoot*: string
    mode*: string                  ## ``workspace`` or ``single-repo``.
    project*: string               ## resolved project name (workspace mode).
    repos*: seq[string]            ## participating repo names.
    entries*: seq[VcsHookEntry]
    summary*: Table[string, int]   ## outcome → count, e.g. {"installed": 8}.
    exitCode*: int

proc vcsHookOutcomeTag(outcome: VcsHookEnsureOutcome): string =
  case outcome
  of vheoAlreadyUpToDate: "already-up-to-date"
  of vheoInstalled: "installed"
  of vheoChainedUserHook: "chained-user-hook"
  of vheoRefreshedDrifted: "refreshed-drifted"
  of vheoReclaimedShadowed: "reclaimed-shadowed"

proc toJsonNode*(report: HooksEnsureReport): JsonNode =
  result = newJObject()
  result["workspaceRoot"] = %report.workspaceRoot
  result["mode"] = %report.mode
  result["project"] = %report.project
  var reposNode = newJArray()
  for r in report.repos:
    reposNode.add(%r)
  result["repos"] = reposNode
  var entriesNode = newJArray()
  for e in report.entries:
    var obj = newJObject()
    obj["repo"] = %e.repo
    obj["repoPath"] = %e.repoPath
    obj["hook"] = %e.hook
    obj["outcome"] = %e.outcome
    obj["hookPath"] = %e.hookPath
    obj["managedPath"] = %e.managedPath
    entriesNode.add(obj)
  result["entries"] = entriesNode
  var summaryNode = newJObject()
  # Sorted summary keys for stable JSON diffs.
  var keys: seq[string]
  for k in report.summary.keys: keys.add(k)
  keys.sort()
  for k in keys:
    summaryNode[k] = %report.summary[k]
  result["summary"] = summaryNode
  result["exitCode"] = %report.exitCode

# --- M17: workspace-wide participating-repo enumeration ------------------
#
# The installer must touch every repo declared by the active project /
# variant. Reuse the same composer-or-resolver dispatch the M9-M16
# subcommands use:
#
#   1. ``.repo/workspace.toml`` is compositional (M8 mode) → run the
#      composer.
#   2. otherwise look up the project name (from a metadata-only M13
#      workspace.toml, then fall back to a single ``projects/*.toml``
#      under ``.repo/manifests/projects/``).
#   3. failing that, treat ``targetPath`` (or cwd) as a single git
#      repo — same fallback path the legacy single-repo ``ensure``
#      command used before M17.

type
  HookRepoTarget = object
    name: string
    repoPath: string  ## absolute path to the repo's working tree.

proc detectWorkspaceProjectName(workspaceRoot: string): string =
  ## When ``workspace.toml`` is metadata-only the project name lives in
  ## ``[workspace].project``; when neither workspace.toml nor that field
  ## is present we look for exactly one ``projects/*.toml`` under
  ## ``projects/`` and use its stem.
  let workspaceToml = workspaceTomlPath(workspaceRoot)
  if fileExists(workspaceToml):
    try:
      let recorded =
        readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
      if recorded.len > 0:
        return recorded
    except WorkspaceManifestParseError:
      discard
  let projectsDir = manifestsRoot(workspaceRoot) / "projects"
  if dirExists(projectsDir):
    var single = ""
    var count = 0
    for kind, path in walkDir(projectsDir):
      if kind == pcFile and path.endsWith(".toml"):
        inc count
        single = path
    if count == 1:
      return extractFilename(single).changeFileExt("")
  ""

proc enumerateParticipatingRepos(workspaceRoot: string):
    tuple[mode: string; projectName: string;
          repos: seq[HookRepoTarget]] =
  ## Returns ``(mode, projectName, repos)``. ``mode`` is
  ## ``"workspace"`` when the workspace shell (workspace.toml or a
  ## resolvable project file) is present, ``"single-repo"`` otherwise.
  let explicitGitRoot = gitTopLevel(workspaceRoot)
  let rootIsItsOwnRepo = explicitGitRoot.len > 0 and
    sameFile(explicitGitRoot, workspaceRoot)
  # DECLARES a workspace — i.e. carries ``.repro/workspace.toml``, whether
  # that file lists ``[[manifest]]`` layers or only records the active
  # project. This, and NOT "the directory happens to hold ``projects/`` and
  # ``repos/``", is what separates a workspace root from the manifest lock
  # backend, which has the manifest-shaped directories and no
  # ``.repro/workspace.toml``.
  #
  # The distinction is load-bearing. A single guard — "an explicitly targeted
  # Git worktree is a single-repo hook target" — used to run FIRST, ahead of
  # both workspace branches. Every real workspace root is a checked-out Git
  # repo (the manifests live in ``metacraft-labs/workspace``), so the guard
  # matched every time: ``repro hooks ensure --vcs`` run at a workspace root
  # reconciled the root repo alone and reported success. Participating repos
  # kept whatever hooks they had — in ~30 of them, none — so their pre-push
  # publication gate never ran, no workspace lock was published for their
  # commits, and CI failed far downstream with "No workspace lock for <repo>".
  #
  # The guard itself is still right, and still applies below: a checkout that
  # merely CONTAINS manifest-shaped data without declaring a workspace must
  # stay a single-repo target. Enumerating that as a workspace would look for
  # non-existent ``<manifest>/<repo.path>`` children, install zero hooks, and
  # make the printed remediation ineffective. It just has to be asked SECOND.
  let declaresWorkspace = fileExists(workspaceTomlPath(workspaceRoot))
  if isCompositionalWorkspaceToml(workspaceRoot):
    let workspaceToml = absolutePath(workspaceTomlPath(workspaceRoot))
    # PS-2: hooks are installed in EVERY participating repo, so the hook
    # target set is the whole active project set — not just the primary.
    let resolved = extendWithActiveProjectSet(workspaceRoot,
      composeManifestLayersFromFile(workspaceToml))
    result.mode = "workspace"
    result.projectName = resolved.projectName
    for repo in resolved.repos:
      result.repos.add(HookRepoTarget(name: repo.name,
        repoPath: workspaceRoot / repo.path))
    # The workspace root repo participates too: it is pushed like any other,
    # and before this branch existed it was the ONLY repo the root-invoked
    # ensure reached. Appending it keeps that coverage instead of trading one
    # gap for another. Guarded against a manifest that already declares a repo
    # at ``path = "."``.
    if rootIsItsOwnRepo:
      var declared = false
      for target in result.repos:
        if dirExists(target.repoPath) and
            sameFile(target.repoPath, workspaceRoot):
          declared = true
          break
      if not declared:
        result.repos.add(HookRepoTarget(name: lastPathPart(workspaceRoot),
          repoPath: workspaceRoot))
    return
  # An explicitly targeted Git worktree that DECLARES no workspace is a
  # single-repo hook target (see the note above). ``detectWorkspaceProjectName``
  # below would otherwise accept it on the strength of a lone
  # ``projects/*.toml``, which is exactly the manifest lock backend's shape.
  if rootIsItsOwnRepo and not declaresWorkspace:
    result.mode = "single-repo"
    return
  let projectName = detectWorkspaceProjectName(workspaceRoot)
  if projectName.len > 0:
    let manifestsRoot = manifestsRoot(workspaceRoot)
    let projectFile = manifestsRoot / "projects" / (projectName & ".toml")
    let variantFile = manifestsRoot / "variants" / (projectName & ".toml")
    var resolved: ResolvedProject
    if fileExists(projectFile):
      resolved = extendWithActiveProjectSet(workspaceRoot,
        resolveProject(projectFile))
    elif fileExists(variantFile):
      resolved = extendWithActiveProjectSet(workspaceRoot,
        resolveVariant(variantFile))
    else:
      resolved.projectName = ""
    if resolved.projectName.len > 0:
      result.mode = "workspace"
      result.projectName = resolved.projectName
      for repo in resolved.repos:
        result.repos.add(HookRepoTarget(name: repo.name,
          repoPath: workspaceRoot / repo.path))
      # The workspace root repo participates too: it is pushed like any
      # other, and before this branch was reachable it was the ONLY repo the
      # root-invoked ensure reached. Appending it keeps that coverage instead
      # of trading one gap for another.
      if rootIsItsOwnRepo:
        var declared = false
        for target in result.repos:
          if dirExists(target.repoPath) and
              sameFile(target.repoPath, workspaceRoot):
            declared = true
            break
        if not declared:
          result.repos.add(HookRepoTarget(name: lastPathPart(workspaceRoot),
            repoPath: workspaceRoot))
      return
  result.mode = "single-repo"
  result.projectName = ""
  # The single-repo path leaves ``repos`` empty; the caller falls back to
  # ``gitHooksDir(targetPath)`` exactly like the pre-M17 implementation.

proc ensureWorkspaceHooks(workspaceRoot: string): HooksEnsureReport =
  ## M17 workspace-aware ``ensure`` driver. Walks every participating
  ## repo, installs the four canonical VCS hooks per repo, and returns
  ## a structured report. Exit code follows: 0 when every entry is
  ## ``installed`` / ``already-up-to-date`` / ``refreshed-drifted`` /
  ## ``chained-user-hook`` (all "success" outcomes — no failure
  ## classification exists for ensure on M17 since the installer either
  ## writes the bytes or raises).
  result.workspaceRoot = workspaceRoot
  let enumerated = enumerateParticipatingRepos(workspaceRoot)
  result.mode = enumerated.mode
  result.project = enumerated.projectName
  for repo in enumerated.repos:
    result.repos.add(repo.name)
  for repo in enumerated.repos:
    if gitTopLevel(repo.repoPath).len == 0:
      # Skip repos that the operator hasn't materialized yet — same
      # rule the legacy repo-workspaces installer used.
      continue
    let hooksDir = gitHooksDir(repo.repoPath)
    for hookName in VcsHookNames:
      let outcome = ensureVcsHookDetailed(hooksDir, hookName)
      let tag = vcsHookOutcomeTag(outcome)
      result.entries.add(VcsHookEntry(
        repo: repo.name,
        repoPath: repo.repoPath,
        hook: hookName,
        outcome: tag,
        hookPath: hookPath(hooksDir, hookName),
        managedPath: managedHookPath(hooksDir, hookName)))
      result.summary[tag] = result.summary.getOrDefault(tag, 0) + 1
  result.exitCode = 0

proc writeHooksEnsureReport(report: HooksEnsureReport; destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc uninstallVcsHook(hooksDir, hookName: string): bool =
  let standard = hookPath(hooksDir, hookName)
  let local = localHookPath(hooksDir, hookName)
  let managed = managedHookPath(hooksDir, hookName)
  if fileExists(extendedPath(standard)) and
      isReprobuildVcsHook(standard, hookName):
    result = removeFileIfExists(standard) or result
    if fileExists(extendedPath(local)):
      moveFileReplacing(local, standard)
      ensureExecutable(standard)
      result = true
  elif fileExists(extendedPath(standard)) and
      fileExists(extendedPath(managed)):
    raise newException(ValueError,
      "refusing to uninstall " & hookName & ": " & standard &
        " is not Reprobuild-managed")
  result = removeFileIfExists(managed) or result
  if fileExists(extendedPath(local)) and isReprobuildVcsHook(local, hookName):
    result = removeFileIfExists(local) or result

proc resolveHooksWorkspaceRoot(parsed: ParsedHooksCommand): string =
  ## Pick the workspace root for M17 enumeration. Priority:
  ##   1. ``--workspace-root=PATH`` (explicit override).
  ##   2. the positional ``[path]`` argument, when supplied.
  ##   3. the current working directory.
  ## The chosen path is normalised to an absolute path. We do NOT
  ## require that it resolves to a workspace — single-repo targets
  ## still flow through the legacy ``gitHooksDir`` fallback below.
  var raw =
    if parsed.workspaceRoot.len > 0: parsed.workspaceRoot
    elif parsed.targetPath.len > 0: parsed.targetPath
    else: getCurrentDir()
  result = os.normalizedPath(absolutePath(raw))

proc runVcsHooksCommand(action: HookActionKind; parsed: ParsedHooksCommand) =
  ## Single-repo legacy path for ``reinstall`` / ``uninstall``. ``ensure``
  ## now runs through the workspace-aware ``ensureWorkspaceHooks``
  ## driver below; this proc handles the single-repo subset the older
  ## actions still target.
  let targetPath = parsed.targetPath
  let hooksDir = gitHooksDir(targetPath)
  let actionName =
    case action
    of hakEnsure: "ensure"
    of hakReinstall: "reinstall"
    of hakUninstall: "uninstall"
  var changed = false
  if action == hakReinstall:
    for hookName in VcsHookNames:
      changed = uninstallVcsHook(hooksDir, hookName) or changed
  case action
  of hakEnsure, hakReinstall:
    for hookName in VcsHookNames:
      changed = ensureVcsHook(hooksDir, hookName) or changed
  of hakUninstall:
    for hookName in VcsHookNames:
      changed = uninstallVcsHook(hooksDir, hookName) or changed
  let status = if changed: "updated" else: "already current"
  echo "repro hooks: VCS hooks " & actionName & " " & status & " at " &
    hooksDir

proc runVcsHooksEnsureCommand(parsed: ParsedHooksCommand): int =
  ## M17 entry point for ``repro hooks ensure --vcs``. Resolves the
  ## workspace root, enumerates participating repos, installs the four
  ## canonical VCS hooks per repo, writes ``hooks-report.json`` and (on
  ## ``--json``) echoes the same JSON to stdout. Falls back to the
  ## legacy single-repo path when the target is not inside a workspace
  ## shell — that path is what ``.envrc`` triggers from non-workspace
  ## projects.
  let workspaceRoot = resolveHooksWorkspaceRoot(parsed)
  let enumerated = enumerateParticipatingRepos(workspaceRoot)
  if enumerated.mode == "single-repo":
    # Single-repo fallback. Mirror the legacy stdout line so callers
    # (notably ``.envrc``) don't lose their idempotent activation
    # signal.
    var single = parsed
    if single.targetPath.len == 0:
      single.targetPath = workspaceRoot
    runVcsHooksCommand(hakEnsure, single)
    return 0
  var report = ensureWorkspaceHooks(workspaceRoot)
  writeHooksEnsureReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "hooks"))
  stageFailureReport(parsed.report, report.workspaceRoot, "hooks",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    echo "repro hooks: ensured " & $report.entries.len &
      " VCS hook(s) across " & $report.repos.len &
      " repo(s) in workspace " & workspaceRoot
    var keys: seq[string]
    for k in report.summary.keys: keys.add(k)
    keys.sort()
    for k in keys:
      echo "  " & k & ": " & $report.summary[k]
  report.exitCode

proc parseHooksCommand(args: openArray[string]): ParsedHooksCommand =
  if args.len == 0:
    raise newException(ValueError,
      "repro hooks requires ensure, reinstall, or uninstall")
  case args[0]
  of "ensure":
    result.action = hakEnsure
  of "reinstall":
    result.action = hakReinstall
  of "uninstall":
    result.action = hakUninstall
  else:
    raise newException(ValueError,
      "unsupported hooks action: " & args[0])
  var i = 1
  while i < args.len:
    let arg = args[i]
    case arg
    of "--shell-direnv":
      result.shellDirenv = true
    of "--vcs":
      result.vcs = true
    of "--shell-autocomplete":
      raise newException(ValueError,
        "repro hooks --shell-autocomplete is not implemented yet")
    of "--shell":
      result.nativeShells.add(parseNativeShell(valueFromFlag(args, i,
        "--shell")))
    of "--workspace-root":
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    of "--json":
      result.json = true
    else:
      if arg.startsWith("--shell="):
        var value = arg["--shell=".len .. ^1]
        if value.len == 0:
          raise newException(ValueError,
            "missing value for --shell")
        result.nativeShells.add(parseNativeShell(value))
      elif arg.startsWith("--workspace-root="):
        result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
      elif consumeReportFlag(arg, result.report):
        discard
      elif arg.startsWith("-"):
        raise newException(ValueError, "unsupported hooks flag: " & arg)
      elif result.targetPath.len > 0:
        raise newException(ValueError,
          "repro hooks accepts at most one path argument")
      else:
        result.targetPath = arg
    inc i
  if not result.shellDirenv and not result.vcs and
      result.nativeShells.len == 0:
    result.shellDirenv = true
    result.vcs = true

# Forward declaration: M18 wires ``pre-push`` dispatch through the
# ``repro check --mode=pre-push`` gate; the implementation lives further
# down (after ``runWorkspaceLockCommand``, which the gate calls to
# create / refresh the workspace lock).
proc runCheckCommand*(args: openArray[string]; hookRemoteName = "";
                      hookRemoteLocation = ""): int
proc validateCommittedLockAdvisory(repoRoot: string)
proc runPostCommitLockCommand*(args: openArray[string]): int
proc runCachePushCommand*(args: openArray[string]): int
proc liveWorkspaceNamesForCache(workspaceRoot: string): seq[string]
proc runManifestRefreshHookCommand*(hookName: string;
                                    args: openArray[string]): int
# Workspace-Membership-Model.md — the ``post-merge`` hook's local-state
# reconciliation. Returns one report line per checkout it changed or deferred
# and NOTHING when the workspace is already consistent. Declared here because
# the implementation needs ``repoRemovalBlockers``, which lives beside the
# membership verbs far below.
proc reconcileLocalStateForHook(workspaceRoot: string):
  tuple[loud, quiet: seq[string]]

proc runHooksDispatchCommand(args: openArray[string]): int =
  ## ``repro hooks dispatch <hook-name> [--repo-root=PATH]
  ## [--refs-file=PATH] -- [hook args...]``. Invoked by the managed
  ## VCS-hook scripts the M17 installer drops into every participating
  ## repo. M17 wired this as a no-op; M18 replaces the ``pre-push``
  ## arm with a call into ``repro check --mode=pre-push``; M19 replaces
  ## the ``post-commit`` arm with an in-process call to the best-effort
  ## lock refresh. M19a will register the post-merge / post-checkout
  ## bodies on top of the same contract.
  if args.len == 0:
    raise newException(ValueError,
      "repro hooks dispatch requires a hook name (one of: " &
      VcsHookNames.join(", ") & ")")
  let hookName = args[0]
  var found = false
  for known in VcsHookNames:
    if known == hookName:
      found = true
      break
  if not found:
    raise newException(ValueError,
      "unsupported hook name for dispatch: " & hookName &
        " (expected one of: " & VcsHookNames.join(", ") & ")")
  # Parse the standard dispatch argv shape: ``--repo-root=PATH`` and
  # (for pre-push) ``--refs-file=PATH``, optionally followed by ``--``
  # and the hook's own positional arguments. The values are forwarded
  # to the body via the documented ``repro check`` flag names so the
  # gate logic stays oblivious to the dispatch wrapper.
  var repoRoot = ""
  var refsFile = ""
  var protocol = 0
  var hookArgs: seq[string]
  var i = 1
  while i < args.len:
    let arg = args[i]
    if arg == "--":
      if i + 1 < args.len:
        hookArgs = @args[(i + 1) .. ^1]
      break
    if arg == "--repo-root" or arg.startsWith("--repo-root="):
      repoRoot = valueFromFlag(args, i, "--repo-root")
    elif arg == "--refs-file" or arg.startsWith("--refs-file="):
      refsFile = valueFromFlag(args, i, "--refs-file")
    elif arg == "--protocol" or arg.startsWith("--protocol="):
      let raw = valueFromFlag(args, i, "--protocol")
      if raw != "2":
        raise newException(ValueError,
          "unsupported managed-hook protocol " & raw & " (required: 2)")
      protocol = 2
    inc i
  case hookName
  of "pre-push":
    # M18 publication gate. Translate the dispatch argv into the
    # documented ``repro check`` surface and propagate the exit code
    # verbatim so the installed hook script can hand it back to git.
    #
    # When no refs are being pushed the hook has nothing to gate. The managed
    # body always creates a refs file, copies stdin into it, and passes its
    # path, so only a proven readable file whose exact byte length is zero is
    # an empty-stream no-op. An omitted flag, a nonexistent path, or an
    # unreadable file is a broken protocol boundary and must fail closed.
    if refsFile.len == 0:
      stderr.writeLine(
        "repro hooks: pre-push protocol requires an existing readable refs file")
      return 1
    if not fileExists(refsFile):
      stderr.writeLine(
        "repro hooks: pre-push protocol requires an existing readable refs file")
      return 1
    var refsBytes: string
    try:
      refsBytes = readFile(refsFile)
    except CatchableError:
      stderr.writeLine(
        "repro hooks: pre-push protocol requires an existing readable refs file")
      return 1
    if refsBytes.len == 0:
      return 0
    if protocol != PrePushProtocolVersion:
      let resolvedRepro = getAppFilename()
      let candidate = if repoRoot.len > 0: repoRoot else: getCurrentDir()
      let discoveredRepo = gitTopLevel(candidate)
      let remedyRepo =
        if discoveredRepo.len > 0: discoveredRepo else: absolutePath(candidate)
      stderr.writeLine("repro hooks: hook protocol mismatch; run '" &
        resolvedRepro & " hooks ensure --vcs " & remedyRepo & "' and retry")
      return 1
    if hookArgs.len != 2:
      stderr.writeLine("repro hooks: pre-push protocol 2 requires Git's " &
        "remote name and location")
      return 1
    let remoteName = hookArgs[0]
    let remoteLocation = hookArgs[1]
    let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
    let capability = getEnv(HookCapabilityEnv)
    # Scrub before any helper or gate work. Only the typed consumer below sees
    # the captured value, and it deletes a successfully claimed record before
    # returning authorization.
    delEnv(HookCapabilityEnv)
    delEnv(LegacyHookSentinelEnv)
    if capability.len > 0:
      let consumed = consumeHookCapability(identity.binaryPath, repoRoot,
        capability, remoteName, remoteLocation, refsFile)
      if consumed.authorized:
        return 0
      if not consumed.claimLost:
        stderr.writeLine("repro hooks: nested publication capability refused: " &
          consumed.diagnostic)
        return 1
      # Another concurrent managed hook won the one-shot atomic claim (or a
      # guessed/replayed token had no pending record). With the token already
      # scrubbed, the loser receives no exemption and must pass the exact same
      # ordinary policy gate as a source push.
    var checkArgs = @["--mode=pre-push"]
    if repoRoot.len > 0:
      checkArgs.add("--current-repo=" & repoRoot)
    checkArgs.add("--pushed-refs=" & refsFile)
    # The gate can REFUSE a push, and git gives the operator no argv to
    # thread a ``--write-report`` through. Same reasoning as post-commit: a
    # hook-driven invocation opts in on the operator's behalf so the
    # refusal always leaves machine-readable evidence behind. Operator
    # invocations of `repro check` stay opt-in.
    checkArgs.add("--write-report")
    return runCheckCommand(checkArgs, remoteName, remoteLocation)
  of "post-commit":
    # M19 best-effort lock refresh. Always exits 0 even when the lock
    # writer refuses, no workspace.toml exists, or the workspace is
    # dirty: a commit must never be blocked by hook failure. The
    # wrapper itself logs all error paths to
    # ``<workspace>/.repro/workspace/post-commit-lock.log`` and writes
    # the JSON report to ``post-commit-report.json`` so the operator
    # can introspect the latest outcome.
    # Repair any managed hook a foreign installer removed or overwrote since
    # the last git operation — see ``selfHealManagedHooks``. Done BEFORE the
    # lock refresh so a repo whose ``pre-push`` was deleted by a dev-shell
    # entry has its gate back before the commit's push can happen.
    for line in selfHealManagedHooks(repoRoot):
      stderr.writeLine(line)
    var postArgs: seq[string]
    if repoRoot.len > 0:
      postArgs.add("--current-repo=" & repoRoot)
    return runPostCommitLockCommand(postArgs)
  of "post-merge", "post-checkout":
    # M19a best-effort manifest-layer refresh. Always exits 0 — git
    # must not see a non-zero hook status. The dispatcher peels the
    # ``--repo-root`` flag off; the hook-supplied positional args
    # (post-checkout: ``<prev> <new> <flag>``; post-merge: the squash
    # flag) appear after ``--`` and are forwarded so the wrapper can
    # short-circuit when ``prev == new``.
    # Same self-heal as the post-commit arm: a dev-shell entry immediately
    # followed by a checkout / merge (and no commit) must not leave the
    # publication gate uninstalled either.
    for line in selfHealManagedHooks(repoRoot):
      stderr.writeLine(line)
    var refreshArgs: seq[string]
    if repoRoot.len > 0:
      refreshArgs.add("--current-repo=" & repoRoot)
    # Find the ``--`` separator in the original args and forward
    # everything after it as the hook-supplied positional argv.
    var j = 1
    while j < args.len and args[j] != "--":
      inc j
    if j < args.len:
      refreshArgs.add("--")
      for k in (j + 1) ..< args.len:
        refreshArgs.add(args[k])
    return runManifestRefreshHookCommand(hookName, refreshArgs)
  else:
    # M17 ground state for any remaining hook names: accept argv,
    # return 0, emit nothing. (All four canonical hooks are now wired,
    # so this branch is currently dead; it stays as a defensive
    # fallback when ``VcsHookNames`` later grows.)
    return 0

proc runHooksCommand(args: openArray[string]): int =
  if args.len > 0 and args[0] == "protocol":
    # ``--require=2`` is the dispatcher-protocol probe. ``--hook-contract=``
    # is the stronger question a generated hook body asks before it hands its
    # work over: "do you generate the hook I am?". A binary that predates the
    # flag falls through to the raise below and fails the handshake — which is
    # the correct answer for it, not an accident.
    var requireSeen = false
    var contract = ""
    var contractSeen = false
    for i in 1 ..< args.len:
      let arg = args[i]
      if arg == "--require=2":
        requireSeen = true
      elif arg.startsWith("--hook-contract="):
        contractSeen = true
        contract = arg["--hook-contract=".len .. ^1]
      else:
        raise newException(ValueError,
          "repro hooks protocol accepts only --require=2 " &
          "[--hook-contract=TOKEN]")
    if not requireSeen:
      raise newException(ValueError,
        "repro hooks protocol requires exactly --require=2")
    if contractSeen:
      let hookName = managedHookNameFromContract(contract)
      if hookName.len == 0 or hookName notin VcsHookNames:
        stderr.writeLine("repro hooks: '" & contract &
          "' is not a managed-hook contract token this build recognizes")
        return 3
      let mine = managedHookContract(hookName)
      if contract != mine:
        stderr.writeLine("repro hooks: this build generates '" & mine &
          "' for " & hookName & ", not '" & contract & "'")
        return 3
    stdout.writeLine("2")
    return 0
  if args.len > 0 and args[0] == "dispatch":
    let dispatchArgs =
      if args.len > 1: args[1 .. ^1]
      else: @[]
    return runHooksDispatchCommand(dispatchArgs)
  if args.len > 0 and args[0] == "cache-push":
    # RA-4: internal entry point invoked by the detached post-commit
    # ``spawnAsyncCachePush`` child. Not part of the operator-facing
    # surface; always exits 0 (best-effort cache-ref push).
    let cacheArgs =
      if args.len > 1: args[1 .. ^1]
      else: @[]
    return runCachePushCommand(cacheArgs)
  let parsed = parseHooksCommand(args)
  case parsed.action
  of hakEnsure:
    if parsed.shellDirenv:
      ensureDirenvHook(parsed.targetPath)
    if parsed.vcs:
      let code = runVcsHooksEnsureCommand(parsed)
      if code != 0:
        return code
    for shell in parsed.nativeShells:
      ensureNativeShellHook(shell)
  of hakReinstall:
    if parsed.shellDirenv:
      ensureDirenvHook(parsed.targetPath, reinstall = true)
    if parsed.vcs:
      runVcsHooksCommand(parsed.action, parsed)
    for shell in parsed.nativeShells:
      ensureNativeShellHook(shell, reinstall = true)
  of hakUninstall:
    if parsed.shellDirenv:
      uninstallDirenvHook(parsed.targetPath)
    if parsed.vcs:
      runVcsHooksCommand(parsed.action, parsed)
    for shell in parsed.nativeShells:
      uninstallNativeShellHook(shell)
  0

proc parseNativeShellActivationRequest(args: openArray[string]):
    NativeShellActivationRequest =
  if args.len == 0:
    raise newException(ValueError,
      "__repro-native-shell-activate requires a directory argument")
  result.cwd = args[0]
  result.shell = nskBash
  var i = 1
  while i < args.len:
    let arg = args[i]
    if arg == "--shell" or arg.startsWith("--shell="):
      result.shell = parseNativeShell(valueFromFlag(args, i, "--shell"))
    elif arg == "--previous-artifact" or
        arg.startsWith("--previous-artifact="):
      result.previousArtifact = valueFromFlag(args, i,
        "--previous-artifact")
    elif arg == "--previous-project-root" or
        arg.startsWith("--previous-project-root="):
      result.previousProjectRoot = valueFromFlag(args, i,
        "--previous-project-root")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      result.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported native shell activation flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected native shell activation argument: " & arg)
    inc i

proc runReproNativeShellActivationHelper(args: openArray[string];
                                         publicCliPath: string): int =
  let request = parseNativeShellActivationRequest(args)
  let format = nativeShellFormat(request.shell)
  let projectRoot = findDevEnvProjectRoot(request.cwd)
  if projectRoot.len == 0:
    stdout.write(renderNativeShellTransition(request.previousArtifact,
      none(DevEnvArtifact), "", format))
    return 0
  var selection = DevEnvCliSelection(
    selector: projectRoot,
    activity: "default",
    statsPath: request.statsPath)
  selection.resolveDevEnvSelection()
  let edge = computePublicDevEnv(selection, publicCliPath, renderShell = true)
  writeDevEnvStats(selection.statsPath, edge, "hooks shell-native")
  let artifact = readDevEnvArtifact(edge.artifactPath)
  if emitDevEnvDiagnostics(artifact):
    return 1
  stdout.write(renderNativeShellTransition(request.previousArtifact,
    some(artifact), edge.artifactPath, format))
  return 0

proc runReproDirenvActivationHelper(args: openArray[string];
                                    publicCliPath: string): int =
  var selection = DevEnvCliSelection()
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--activity" or arg.startsWith("--activity="):
      selection.activity.appendActivitySelection(valueFromFlag(args, i,
        "--activity"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      selection.workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--lock-slice" or arg.startsWith("--lock-slice="):
      selection.lockSliceId = valueFromFlag(args, i, "--lock-slice")
    elif arg == "--dev-env-stats" or arg.startsWith("--dev-env-stats="):
      selection.statsPath = valueFromFlag(args, i, "--dev-env-stats")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported direnv activation flag: " & arg)
    elif selection.selector.len == 0:
      selection.selector = arg
    else:
      raise newException(ValueError,
        "unexpected direnv activation argument: " & arg)
    inc i
  selection.resolveDevEnvSelection()
  let edge = computePublicDevEnv(selection, publicCliPath, renderShell = true)
  writeDevEnvStats(selection.statsPath, edge, "hooks shell-direnv")
  stdout.write(readFile(extendedPath(edge.shellFragmentPath)))
  stdout.write(renderDevEnvShellOps([
    DevEnvShellOp(kind: deskSetEnv, name: "REPRO_DEV_ENV_ARTIFACT",
      value: edge.artifactPath),
    DevEnvShellOp(kind: deskSetEnv, name: "REPRO_DEV_ENV_PROJECT_ROOT",
      value: selection.projectRoot),
    DevEnvShellOp(kind: deskSetEnv, name: "REPRO_DEV_ENV_SELECTED_ACTIVITIES",
      value: selection.activity)
  ], depPosix))
  0

proc sourceLocation(file: string): SourceLocation =
  SourceLocation(file: file, line: 1)

proc cmakeNixExecutable(name: string): string =
  # Windows: Nix store binaries have a `.exe` suffix. The forked CMake build
  # tree from `metacraft-labs/reprobuild-cmake` also produces `cmake.exe`,
  # `cc.exe`, etc. Emit relative paths with `.exe` on Windows so the path-only
  # / Nix executablePath actually points at a runnable file.
  when defined(windows):
    case name
    of "cmake":
      "bin/cmake.exe"
    of "cc":
      "bin/cc.exe"
    of "c++":
      "bin/c++.exe"
    else:
      "bin/" & name & ".exe"
  else:
    case name
    of "cmake":
      "bin/cmake"
    of "cc":
      "bin/cc"
    of "c++":
      "bin/c++"
    else:
      "bin/" & name

proc cmakeNixSelector(name: string): string =
  case name
  of "cmake":
    "nixpkgs#cmake"
  of "cc", "c++":
    "nixpkgs#clang"
  else:
    "nixpkgs#" & name

proc cmakeToolUse(sourceRoot, name: string): InterfaceToolUse =
  let loc = sourceLocation(sourceRoot / "CMakeLists.txt")
  InterfaceToolUse(
    rawConstraint: name & " >=1.0 <2.0",
    packageSelector: name,
    executableName: name,
    nixProvisioning: @[InterfaceNixProvisioning(
      packageName: name,
      selector: cmakeNixSelector(name),
      executablePath: cmakeNixExecutable(name),
      packageId: cmakeNixSelector(name),
      lockIdentity: cmakeNixSelector(name),
      location: loc)],
    location: loc)

proc cmakeDevelopArtifact(sourceRoot: string): ProjectInterfaceArtifact =
  artifactFor(ProjectInterface(
    projectName: "cmakeDevelop",
    packageName: "cmakeDevelop",
    toolUses: @[
      cmakeToolUse(sourceRoot, "cmake"),
      cmakeToolUse(sourceRoot, "cc"),
      cmakeToolUse(sourceRoot, "c++")
    ],
    location: sourceLocation(sourceRoot / "CMakeLists.txt")))

proc cmakeDevelopOutDir(sourceRoot, workRoot: string): string =
  let scopedRoot = scopedWorktreeRoot(sourceRoot / "CMakeLists.txt", workRoot)
  if scopedRoot.len > 0:
    scopedRoot / "develop-cmake"
  else:
    sourceRoot / ".repro" / "develop-cmake"

proc profileFor(identity: PathOnlyBuildIdentity; executableName: string):
    PathOnlyToolProfile =
  for profile in identity.profiles:
    if profile.executableName == executableName:
      return profile
  raise newException(ValueError,
    "cmake develop profile did not resolve required tool: " & executableName)

proc pathListJoin(values: openArray[string]; separator: char): string =
  var filtered: seq[string] = @[]
  for value in values:
    if value.len > 0 and not filtered.contains(value):
      filtered.add(value)
  filtered.join($separator)

proc profilePrefixes(identity: PathOnlyBuildIdentity): seq[string] =
  for profile in identity.profiles:
    if profile.selectedStorePath.len > 0 and dirExists(
        extendedPath(profile.selectedStorePath)):
      if not result.contains(profile.selectedStorePath):
        result.add(profile.selectedStorePath)
    let binDir = parentDir(profile.resolvedExecutablePath)
    if binDir.len > 0:
      let prefix = parentDir(binDir)
      if prefix.len > 0 and dirExists(extendedPath(prefix)) and not result.contains(prefix):
        result.add(prefix)

proc pkgConfigPaths(prefixes: openArray[string]): seq[string] =
  for prefix in prefixes:
    for suffix in ["lib/pkgconfig", "share/pkgconfig"]:
      let candidate = prefix / suffix
      if dirExists(extendedPath(candidate)) and not result.contains(candidate):
        result.add(candidate)

proc cmakeEscape(value: string): string =
  value.replace("\\", "\\\\").replace("\"", "\\\"").replace("$", "\\$")

proc cmakeSet(name, kind, value: string; force = true): string =
  if value.len == 0:
    return ""
  "set(" & name & " \"" & cmakeEscape(value) & "\" CACHE " & kind &
    " \"Generated by repro develop --cmake\"" &
    (if force: " FORCE" else: "") & ")\n"

proc sdkRootForCMake(): string =
  let explicit = getEnv("SDKROOT")
  if explicit.len > 0 and dirExists(extendedPath(explicit)):
    return explicit

proc writeCMakeToolchain(path: string; identity: PathOnlyBuildIdentity;
                         mode: ToolProvisioningMode; identityPath,
                         inspectionPath: string) =
  let cProfile = identity.profileFor("cc")
  let cxxProfile = identity.profileFor("c++")
  let prefixes = profilePrefixes(identity)
  let prefixValue = pathListJoin(prefixes, ';')
  let pkgValue = pathListJoin(pkgConfigPaths(prefixes), PathSep)
  let sdkRoot = sdkRootForCMake()
  var content = "# Generated by repro develop --cmake. Do not edit.\n"
  content.add(cmakeSet("CMAKE_C_COMPILER", "FILEPATH",
    cProfile.resolvedExecutablePath))
  content.add(cmakeSet("CMAKE_CXX_COMPILER", "FILEPATH",
    cxxProfile.resolvedExecutablePath))
  content.add(cmakeSet("CMAKE_PREFIX_PATH", "STRING", prefixValue))
  when defined(macosx):
    content.add(cmakeSet("CMAKE_OSX_SYSROOT", "PATH", sdkRoot))
  elif defined(windows):
    # Windows: MSVC has no sysroot concept; the Windows SDK is selected
    # implicitly via the toolchain (vcvars / VS install), so we deliberately
    # omit both CMAKE_SYSROOT and CMAKE_OSX_SYSROOT here. Proper Windows SDK
    # pinning is a follow-up.
    discard
  else:
    content.add(cmakeSet("CMAKE_SYSROOT", "PATH", sdkRoot))
  content.add(cmakeSet("REPROBUILD_CMAKE_TOOL_PORTABILITY", "STRING",
    mode.modeName))
  content.add(cmakeSet("REPROBUILD_TOOL_PROFILE_ARTIFACT", "FILEPATH",
    identityPath))
  content.add(cmakeSet("REPROBUILD_TOOL_PROFILE_INSPECTION", "FILEPATH",
    inspectionPath))
  if pkgValue.len > 0:
    content.add("set(ENV{PKG_CONFIG_PATH} \"" & cmakeEscape(pkgValue) & "\")\n")
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), content)

proc shellAssign(name, value: string): string =
  name & "=" & q(value) & "\n"

proc resolveCMakeExecutable(candidate: string): string =
  # Windows: the resolved executable path may be recorded without the .exe
  # suffix (for example when it came from a Nix-style "bin/cmake" entry).
  # Probe for a .exe variant first so the wrapper actually points at a
  # runnable file. POSIX paths are returned unchanged.
  when defined(windows):
    if candidate.len == 0:
      return candidate
    if fileExists(extendedPath(candidate)):
      return candidate
    if not candidate.endsWith(".exe"):
      let withExe = candidate & ".exe"
      if fileExists(extendedPath(withExe)):
        return withExe
    candidate
  else:
    candidate

proc ps1SingleQuote(value: string): string =
  # Windows: emit a PowerShell single-quoted literal. PS single-quoted strings
  # do not expand variables and only escape the single quote itself by
  # doubling it.
  "'" & value.replace("'", "''") & "'"

proc writeCMakeConfigureWrapperPosix(path: string;
                                     selectedCmake, toolchainPath,
                                     identityPath, inspectionPath, sourceRoot,
                                     reproPath, sourceRepoRoot, prefixValue,
                                     pkgValue, sdkRoot,
                                     modeName: string) =
  var content = "#!/bin/sh\nset -eu\n"
  content.add(shellAssign("cmake_bin", selectedCmake))
  content.add(shellAssign("toolchain_file", toolchainPath))
  content.add(shellAssign("prefix_path", prefixValue))
  content.add(shellAssign("pkg_config_path", pkgValue))
  content.add(shellAssign("sdk_root", sdkRoot))
  content.add(shellAssign("repro_cli", reproPath))
  content.add(shellAssign("repro_source_root", sourceRepoRoot))
  content.add("export REPROBUILD_REPRO=\"$repro_cli\"\n")
  content.add("export REPROBUILD_SOURCE_ROOT=\"$repro_source_root\"\n")
  content.add("# Provider priming is part of this CMake generation step.\n")
  content.add("export REPRO_DAEMON=off\n")
  content.add("export REPRO_TOOL_PROFILE_ARTIFACT=" & q(identityPath) & "\n")
  content.add("export REPRO_TOOL_PROFILE_INSPECTION=" & q(inspectionPath) & "\n")
  content.add("export REPRO_PROJECT_ROOT=" & q(sourceRoot) & "\n")
  content.add("if [ -n \"$pkg_config_path\" ]; then\n")
  content.add("  if [ -n \"${PKG_CONFIG_PATH:-}\" ]; then\n")
  content.add("    export PKG_CONFIG_PATH=\"$pkg_config_path:$PKG_CONFIG_PATH\"\n")
  content.add("  else\n")
  content.add("    export PKG_CONFIG_PATH=\"$pkg_config_path\"\n")
  content.add("  fi\n")
  content.add("fi\n")
  content.add("extra_sysroot_args=\n")
  content.add("if [ -n \"$sdk_root\" ]; then\n")
  when defined(macosx):
    content.add("  extra_sysroot_args=\"-DCMAKE_OSX_SYSROOT=$sdk_root\"\n")
  else:
    content.add("  extra_sysroot_args=\"-DCMAKE_SYSROOT=$sdk_root\"\n")
  content.add("fi\n")
  content.add("exec \"$cmake_bin\" -G Reprobuild ")
  content.add("-DCMAKE_TOOLCHAIN_FILE=\"$toolchain_file\" ")
  content.add("-DCMAKE_PREFIX_PATH=\"$prefix_path\" ")
  content.add("-DREPROBUILD_CMAKE_TOOL_PORTABILITY=" & modeName & " ")
  content.add("-DREPROBUILD_TOOL_PROFILE_ARTIFACT=" & q(identityPath) & " ")
  content.add("-DREPROBUILD_TOOL_PROFILE_INSPECTION=" & q(inspectionPath) & " ")
  content.add("$extra_sysroot_args \"$@\"\n")
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), content)
  setFilePermissions(extendedPath(path), {fpUserRead, fpUserWrite, fpUserExec,
    fpGroupRead, fpGroupExec, fpOthersRead, fpOthersExec})

proc writeCMakeConfigureWrapperWindows(path: string;
                                       selectedCmake, toolchainPath,
                                       identityPath, inspectionPath, sourceRoot,
                                       reproPath, sourceRepoRoot, prefixValue,
                                       pkgValue,
                                       modeName: string) =
  # Windows: emit a PowerShell wrapper instead of a POSIX `sh` script. The
  # script behaviour mirrors the POSIX wrapper: define the same variables,
  # export the same REPRO_* environment, prepend PKG_CONFIG_PATH if any, and
  # invoke the forked cmake.exe with -G Reprobuild plus any caller args.
  # CMAKE_(OSX_)SYSROOT is intentionally omitted: MSVC has no sysroot concept
  # and the Windows SDK is selected implicitly by the active toolchain.
  var content = "# Generated by repro develop --cmake. Do not edit.\n"
  content.add("$ErrorActionPreference = 'Stop'\n")
  content.add("$cmake_bin = " & ps1SingleQuote(selectedCmake) & "\n")
  content.add("$toolchain_file = " & ps1SingleQuote(toolchainPath) & "\n")
  content.add("$prefix_path = " & ps1SingleQuote(prefixValue) & "\n")
  content.add("$pkg_config_path = " & ps1SingleQuote(pkgValue) & "\n")
  content.add("$repro_cli = " & ps1SingleQuote(reproPath) & "\n")
  content.add("$repro_source_root = " & ps1SingleQuote(sourceRepoRoot) & "\n")
  content.add("$env:REPROBUILD_REPRO = $repro_cli\n")
  content.add("$env:REPROBUILD_SOURCE_ROOT = $repro_source_root\n")
  content.add("# Provider priming is part of this CMake generation step.\n")
  content.add("$env:REPRO_DAEMON = 'off'\n")
  content.add("$env:REPRO_TOOL_PROFILE_ARTIFACT = " &
    ps1SingleQuote(identityPath) & "\n")
  content.add("$env:REPRO_TOOL_PROFILE_INSPECTION = " &
    ps1SingleQuote(inspectionPath) & "\n")
  content.add("$env:REPRO_PROJECT_ROOT = " & ps1SingleQuote(sourceRoot) & "\n")
  # Windows: $env:PATH uses ';' as separator; use [IO.Path]::PathSeparator
  # so the wrapper stays correct even if cross-shelled later.
  content.add("if ($pkg_config_path) {\n")
  content.add("  $sep = [IO.Path]::PathSeparator\n")
  content.add("  if ($env:PKG_CONFIG_PATH) {\n")
  content.add("    $env:PKG_CONFIG_PATH = \"$pkg_config_path$sep$($env:PKG_CONFIG_PATH)\"\n")
  content.add("  } else {\n")
  content.add("    $env:PKG_CONFIG_PATH = $pkg_config_path\n")
  content.add("  }\n")
  content.add("}\n")
  # Build the cmake argv as a PowerShell array. We store the identity and
  # inspection paths in $env:... already and re-reference them here via
  # PowerShell variables so each array element is a single value PS-side
  # (avoids `+` concatenation surprises that CMake mis-parsed as extra
  # source-dir paths).
  content.add("$tool_profile_artifact = " &
    ps1SingleQuote(identityPath) & "\n")
  content.add("$tool_profile_inspection = " &
    ps1SingleQuote(inspectionPath) & "\n")
  content.add("$cmake_args = @(\n")
  content.add("  '-G', 'Reprobuild',\n")
  content.add("  \"-DCMAKE_TOOLCHAIN_FILE=$toolchain_file\",\n")
  content.add("  \"-DCMAKE_PREFIX_PATH=$prefix_path\",\n")
  content.add("  '-DREPROBUILD_CMAKE_TOOL_PORTABILITY=" & modeName & "',\n")
  content.add("  \"-DREPROBUILD_TOOL_PROFILE_ARTIFACT=$tool_profile_artifact\",\n")
  content.add("  \"-DREPROBUILD_TOOL_PROFILE_INSPECTION=$tool_profile_inspection\"\n")
  content.add(")\n")
  content.add("& $cmake_bin @cmake_args @args\n")
  content.add("exit $LASTEXITCODE\n")
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), content)

proc cmakeConfigureWrapperBaseName(): string =
  # Windows: emit a `.ps1` wrapper instead of an extensionless shell script so
  # PowerShell (and the develop runner) picks the right interpreter.
  when defined(windows):
    "repro-cmake-configure.ps1"
  else:
    "repro-cmake-configure"

proc writeCMakeConfigureWrapper(path: string; identity: PathOnlyBuildIdentity;
                                mode: ToolProvisioningMode; cmakeBinary,
                                toolchainPath, identityPath, inspectionPath,
                                sourceRoot, reproPath, sourceRepoRoot: string) =
  let cmakeProfile = identity.profileFor("cmake")
  let rawSelected =
    if cmakeBinary.len > 0:
      absolutePath(cmakeBinary)
    else:
      cmakeProfile.resolvedExecutablePath
  let selectedCmake = resolveCMakeExecutable(rawSelected)
  let prefixes = profilePrefixes(identity)
  # CMake list values (CMAKE_PREFIX_PATH and friends) ALWAYS use ';' as the
  # separator, independent of host platform. PKG_CONFIG_PATH uses the host
  # shell's PATH separator (`PathSep` is ';' on Windows, ':' on POSIX).
  let prefixValue = pathListJoin(prefixes, ';')
  let pkgValue = pathListJoin(pkgConfigPaths(prefixes), PathSep)
  when defined(windows):
    # Windows: the SDK / sysroot concept does not apply to MSVC.
    writeCMakeConfigureWrapperWindows(path, selectedCmake, toolchainPath,
      identityPath, inspectionPath, sourceRoot, reproPath, sourceRepoRoot,
      prefixValue, pkgValue, mode.modeName)
  else:
    let sdkRoot = sdkRootForCMake()
    writeCMakeConfigureWrapperPosix(path, selectedCmake, toolchainPath,
      identityPath, inspectionPath, sourceRoot, reproPath, sourceRepoRoot,
      prefixValue, pkgValue, sdkRoot, mode.modeName)

proc runCMakeDevelopCommand(target: string; mode: ToolProvisioningMode;
                            command: openArray[string]; workRoot,
                            cmakeBinary: string): int =
  if mode notin {tpmPathOnly, tpmNix}:
    raise newException(ValueError,
      "repro develop --cmake requires --tool-provisioning=path|nix")
  let sourceRoot = absolutePath(target)
  if not dirExists(extendedPath(sourceRoot)):
    raise newException(IOError, "cmake source directory not found: " & sourceRoot)
  if not fileExists(extendedPath(sourceRoot / "CMakeLists.txt")):
    raise newException(IOError,
      "cmake source directory does not contain CMakeLists.txt: " & sourceRoot)
  if cmakeBinary.len > 0 and not fileExists(extendedPath(cmakeBinary)):
    raise newException(IOError, "cmake binary not found: " & cmakeBinary)

  let outDir = cmakeDevelopOutDir(sourceRoot, workRoot)
  let interfacePath = outDir / "cmake-develop-interface.rbsz"
  let artifact = cmakeDevelopArtifact(sourceRoot)
  writeInterfaceArtifact(interfacePath, artifact)
  let resolved = warmResolveAndWriteIdentity(artifact, outDir, mode)
  let toolchainPath = outDir / "reprobuild-cmake-toolchain.cmake"
  # Windows: filename includes .ps1 so PowerShell will execute it directly.
  let wrapperPath = outDir / "bin" / cmakeConfigureWrapperBaseName()
  writeCMakeToolchain(toolchainPath, resolved.identity, mode,
    resolved.identityPath, resolved.inspectionPath)
  writeCMakeConfigureWrapper(wrapperPath, resolved.identity, mode, cmakeBinary,
    toolchainPath, resolved.identityPath, resolved.inspectionPath, sourceRoot,
    stablePublicCliPath(), reprobuildLibraryWorkDir())

  echo "repro develop: compatibility cmake dev-env path active " &
    "(provider-driven artifact integration pending, tool-provisioning=" &
    mode.modeName & ")"
  echo "project: " & artifact.projectInterface.projectName
  echo "interface: " & interfacePath
  echo "toolIdentity: " & resolved.identityPath
  echo "inspection: " & resolved.inspectionPath
  echo "toolchain: " & toolchainPath
  echo "configureWrapper: " & wrapperPath
  echo "cachePortability: " & (if mode == tpmNix: "portable" else: "local-only")
  echo "binDirs: " & binDirsForDevelop(resolved.identity).join($PathSep)
  for profile in resolved.identity.profiles:
    echo "tool: " & profile.executableName & " " &
      profile.resolvedExecutablePath

  if command.len == 0:
    return 0
  # The command commonly runs ``cmake --build``, whose generated rules call
  # back into ``repro build`` while the CMake binary dir is transaction-local.
  var devCommand = @["sh", "-c",
    "PATH=" & q(parentDir(wrapperPath) & $PathSep &
      binDirsForDevelop(resolved.identity).join($PathSep) & $PathSep &
      getEnv("PATH")) & " REPRO_DAEMON=off " & shellCommand(command)]
  runInDevelopEnvironment(devCommand, sourceRoot, resolved.identity,
    resolved.identityPath, resolved.inspectionPath, interfacePath)

proc autoRunQuotaEnabled(): bool =
  getEnv("REPROBUILD_AUTO_RUNQUOTA", "1").normalize notin
    ["0", "false", "no", "off"]

const DefaultAutoRunQuotaMemoryBytes* = 16'u64 * 1024'u64 * 1024'u64 *
  1024'u64

proc autoRunQuotaMemoryBytes*(): uint64 =
  let configured = getEnv("REPROBUILD_RUNQUOTA_MEMORY_BYTES", "")
  if configured.len == 0:
    return DefaultAutoRunQuotaMemoryBytes
  try:
    result = parseBiggestUInt(configured).uint64
  except ValueError:
    raise newException(ValueError,
      "REPROBUILD_RUNQUOTA_MEMORY_BYTES must be a positive integer")
  if result == 0:
    raise newException(ValueError,
      "REPROBUILD_RUNQUOTA_MEMORY_BYTES must be a positive integer")

proc executableFile(path: string): bool =
  if path.len == 0 or not fileExists(path):
    return false
  when defined(posix):
    let perms = getFilePermissions(path)
    result = fpUserExec in perms or fpGroupExec in perms or fpOthersExec in perms
  else:
    result = true

proc findRunQuotaDaemonBin*(): string =
  ## M9.R.11 — deterministic discovery of the ``runquotad`` binary.
  ##
  ## Lookup order:
  ##   1. ``$RUNQUOTAD_BIN`` env override (highest priority — operator
  ##      explicit choice; used by the nix dev-shell flake.nix to point
  ##      at the locally-built daemon).
  ##   2. ``runquotad`` on ``$PATH`` (``findExe``). Covers nix dev-shells,
  ##      direnv-managed shells, system installs.
  ##   3. Sibling-repo discovery: ``../runquota/build/bin/runquotad{.exe}``
  ##      relative to the reprobuild source root (the canonical workspace
  ##      layout described in the metacraft env.ps1 sibling-detection
  ##      block + the .envrc flake-overrides comment). This is what makes
  ##      ``repro build`` from a plain Windows pwsh (no nix, no PATH
  ##      install) deterministically discover the daemon: as long as the
  ##      sibling has been built once, the build engine self-spawns it.
  ##   4. Empty string — caller must surface the diagnostic with the
  ##      complete remediation hint (build the sibling, set
  ##      ``RUNQUOTAD_BIN``, or run with ``--bypass-runquota``).
  result = getEnv("RUNQUOTAD_BIN", "")
  if result.len > 0:
    if fileExists(result) and not executableFile(result):
      raise newException(OSError, "RUNQUOTAD_BIN is not executable: " & result)
    if executableFile(result):
      return
  result = findExe("runquotad")
  if result.len > 0:
    return
  # Sibling-repo fall-through. The reprobuild source root is the dir that
  # contains ``repro.nim`` + ``apps/`` — we find it by walking upward
  # from ``getAppDir()`` (the dir of ``repro.exe``) until we hit a path
  # whose parent contains a sibling ``runquota/`` directory with the
  # built ``runquotad`` binary.
  let exeName = when defined(windows): "runquotad.exe" else: "runquotad"
  var dir = getAppDir()
  for _ in 0 .. 8:
    if dir.len == 0:
      break
    let candidate = dir.parentDir / "runquota" / "build" / "bin" / exeName
    if fileExists(candidate) and not executableFile(candidate):
      raise newException(OSError,
        "sibling runquotad exists but is not executable: " & candidate)
    if executableFile(candidate):
      return candidate
    let parent = dir.parentDir
    if parent == dir:
      break
    dir = parent
  # Last resort — the current working directory's sibling. Covers
  # ``cd D:/metacraft/reprobuild; ./build/bin/repro.exe build ...``
  # where ``getAppDir()`` already pointed at the right ancestor but the
  # walk above terminated early.
  let cwdSibling = getCurrentDir().parentDir / "runquota" / "build" / "bin" /
    exeName
  if fileExists(cwdSibling) and not executableFile(cwdSibling):
    raise newException(OSError,
      "current-workdir sibling runquotad exists but is not executable: " &
      cwdSibling)
  if executableFile(cwdSibling):
    return cwdSibling
  result = ""

const
  ## Compatibility inventory of operational variables historically forwarded
  ## from the user-facing CLI into the daemon-hosted build executor. Request
  ## forwarding now preserves the complete caller environment so arbitrary
  ## action ``envPassthrough`` declarations work under the daemon too, but this
  ## exported list remains useful to callers auditing the well-known controls.
  DaemonExplicitForwardedEnvVars* = [
    "PATH", "HOME", "USER", "TMPDIR", "TEMP", "TMP",
    "RUNQUOTA_SOCKET", "RUNQUOTAD_BIN", "RUNQUOTA_BIN",
    "REPROBUILD_STORE_ROOT", "REPROBUILD_SOURCE_ROOT",
    # Source/provider lookup overrides used by workspace builds. These are
    # distinct from REPROBUILD_SOURCE_ROOT in existing project configuration,
    # so preserve all supported spellings across the daemon boundary.
    "REPROBUILD_REPO_ROOT", "REPROBUILD_SRC", "REPROBUILD_PACKAGES_ROOT",
    # The Nix provisioner is an out-of-process helper. Development builds keep
    # it beside the freshly built CLI rather than on the systemd-user PATH.
    "REPROBUILD_NIX_DAEMON_BIN",
    "REPROBUILD_ACTION_CACHE_ROOT", "REPROBUILD_MAX_PARALLELISM",
    "REPROBUILD_RUNQUOTA_MEMORY_BYTES",
    "REPRO_STATS_DIR", "REPROBUILD_NO_RUNQUOTA",
    "REPROBUILD_AUTO_RUNQUOTA",
    "REPRO_DAEMON_TEST_STATS_FLUSH_DELAY_MS",
    # Nested CLI calls launched from daemon-hosted actions must keep using the
    # caller-selected daemon, especially full-suite runs that isolate
    # REPRO_DAEMON_* under a temporary endpoint/state/runtime root.
    "REPRO_DAEMON_ENDPOINT", "REPRO_DAEMON_STATE_DIR",
    "REPRO_DAEMON_RUNTIME_DIR",
    # Binary-cache configuration is resolved inside the daemon-hosted build.
    # Credential variables contain filesystem paths, not key material.
    "REPRO_CACHES_CONFIG", "REPRO_BINARY_CACHE_URL",
    "REPRO_BINARY_CACHE_KEY_PATH", "REPRO_BINARY_CACHE_CERT_PATH",
    "REPRO_BINARY_CACHE_SCOPE",
    # Source checkout overrides used by repro.nim/config.nims to resolve
    # workspace sibling libraries when the daemon-hosted executor evaluates the
    # provider under a login-launched daemon environment.
    "IO_MON_SRC",
    "STACKABLE_HOOKS_SRC",
    "SHM_GSET_SRC",
    "SHM_QUEUE_SRC",
    "REPRO_FROM_SOURCE_ROOT",
    # Tool-provisioning selection. The daemon-hosted executor re-parses the
    # request's rawArgs (which carry no --tool-provisioning when the user
    # selected the mode via the env var), so REPRO_TOOL_PROVISIONING must
    # follow the user into the daemon for resolveToolProvisioningWithEnv to
    # observe it there. Without forwarding, an env-only selection is silently
    # ignored under the default daemon-hosted build path.
    "REPRO_TOOL_PROVISIONING",
    # Solver-participating variant overrides. ``--variant name=value`` /
    # ``--release`` write the selection into ``REPRO_VARIANTS``; like
    # ``REPRO_TOOL_PROVISIONING`` above, the daemon-hosted executor re-parses
    # the request's rawArgs and resolves variants from the env, so without
    # forwarding this the user's variant selection is silently ignored under
    # the default daemon-hosted build path — both for the provider's variant
    # resolution and for the lowered-graph cache key (see
    # ``canonicalVariantAssignments`` / ``loweredGraphCacheKey``), which means
    # ``--release`` would reuse the cached ``debug`` graph.
    "REPRO_VARIANTS",
    # Monitor-shim lookup override. ``repro internal io monitor`` (the
    # automatic-monitor launcher) needs to locate librepro_monitor_shim.{dylib,so}
    # when repro runs against an arbitrary project outside its own build tree;
    # the launchd/systemd-spawned daemon does not inherit the user's shell, so
    # this must follow the user for monitored actions to run.
    "REPRO_MONITOR_SHIM_LIB",
    # Windows MSVC linker pin used by cargo when targetting
    # ``x86_64-pc-windows-msvc``. Recorder ``env.ps1`` scripts set this
    # to bypass PATH-resolution of MSYS2's coreutils ``link.exe``
    # collision; cargo subprocesses launched by the daemon need to see
    # the same value or the link step fails with the
    # ``/usr/bin/link: extra operand`` error documented in
    # ``codetracer-cardano-recorder/env.ps1``.
    "CARGO_TARGET_X86_64_PC_WINDOWS_MSVC_LINKER",
    # Bindgen's libclang lookup. Recorder builds that pull in
    # ``bindgen`` (rb-sys for the Ruby recorder, plus a handful of
    # vendored crates in other recorders) panic during the cargo
    # build step when ``libclang.dll`` is not on a path bindgen can
    # resolve. ``env.ps1`` points this at MSYS2's mingw64/bin where
    # the toolchain ships libclang.dll.
    "LIBCLANG_PATH",
    # Recorder-specific runtime data. The cairo-recorder's
    # integration tests can't resolve ``use core::…`` imports
    # without the Cairo corelib source tree. env.ps1 provisions it
    # via ``ensure-cairo-corelib.ps1`` and points this env var at
    # the extracted ``corelib/`` directory.
    "CAIRO_CORELIB_DIR",
    # PyO3 interpreter pin used by the codetracer-python-recorder
    # cargo build. Without this, PyO3's build script picks the first
    # ``python3`` on PATH (which is the repo-workspaces embeddable
    # Python — no ``libs/python<ver>.lib``) and the link step fails
    # with ``LNK1181: cannot open input file 'python312.lib'``.
    # ``env.ps1`` points this at the python-build-standalone install
    # provisioned by ensure-python-dev.ps1.
    "PYO3_PYTHON",
    "PYTHONHOME",
    # rust libtest's parallelism knob. Recorder test suites that
    # mutate process-global state (env vars, signal handlers, the
    # PyO3 interpreter, etc.) under ``cargo test`` race against
    # each other when libtest schedules them in parallel; setting
    # this to 1 forces sequential execution and matches the
    # serialization the per-test mutex guards already imply. The
    # env var is interpreted by every cargo-test binary at run
    # time so users can override per-invocation.
    "RUST_TEST_THREADS",
    # Reprobuild's own build-time env vars consumed by config.nims and the
    # interface-extraction nim subprocesses. Without these, config.nims
    # defaults to vendored-hash mode and tries to compile from
    # references/mold/, which is gitignored and so missing in CI checkouts.
    "REPROBUILD_USE_SYSTEM_HASH_LIBS",
    "BLAKE3_PREFIX", "XXHASH_PREFIX", "SQLITE_PREFIX", "CLINGO_PREFIX",
    "REPROBUILD_RUNTIME_LIBRARY_PATH",
    "NIMCRYPTO_SRC", "RUNQUOTA_SRC", "BEARSSL_SRC",
    "REPRO_TEST_ADAPTERS_SRC", "REPRO_CT_TEST_RUNNER_SRC",
    "CODETRACER_SRC",
    # CT_INTERPOSE_SRC threads the ct_interpose package (monitor hooks /
    # SIP-rewrite helpers) onto config.nims's --path. REPROBUILD_SOURCE_ROOT
    # lets reprobuildLibraryWorkDir() locate reprobuild's OWN libs
    # (repro_interface_artifacts, repro_project_dsl, ...) when compiling the
    # interface extractor and providers — the compiled-in source path points
    # at the now-deleted build sandbox, so without this env var the daemon
    # falls back to the project dir and the extractor fails with
    # "cannot open file: repro_interface_artifacts".
    "CT_INTERPOSE_SRC", "REPROBUILD_SOURCE_ROOT"
  ]

  ## Well-known toolchain env vars that must also be forwarded to the daemon
  ## when present in the user's shell. On Nix systems (especially macOS where
  ## ``-liconv`` must resolve to ``libiconv`` from the Nix store) the cc-wrapper
  ## consumes these to inject the correct ``-L``/``-isystem`` paths into clang/
  ## ld invocations driven by cargo/rustc. Without forwarding, a daemon spawned
  ## by launchd has none of them and cargo actions like
  ## ``db-replay-server-cargo`` fail at the rustc link step. Values are NEVER
  ## hardcoded; they are read live from the launching shell's environment.
  DaemonNixToolchainEnvVars* = [
    # Nix cc-wrapper inputs — consumed by the wrapper to extend the underlying
    # clang/ld invocation with the correct -L/-isystem paths.
    "NIX_LDFLAGS",
    "NIX_LDFLAGS_FOR_TARGET",
    "NIX_CFLAGS_COMPILE",
    "NIX_CFLAGS_COMPILE_FOR_TARGET",
    "NIX_CFLAGS_LINK",
    "NIX_CFLAGS_LINK_FOR_TARGET",
    "NIX_CXXSTDLIB_COMPILE",
    "NIX_CXXSTDLIB_LINK",
    "NIX_HARDENING_ENABLE",
    "NIX_NO_SELF_RPATH",
    "NIX_DEBUG_INFO_DIRS",
    "NIX_COREFOUNDATION_RPATH",
    "NIX_DONT_SET_RPATH",
    "NIX_DONT_SET_RPATH_FOR_TARGET",
    "NIX_ENFORCE_NO_NATIVE",
    "NIX_IGNORE_LD_THROUGH_GCC",
    "NIX_SSL_CERT_FILE",
    "SSL_CERT_FILE",
    # Loader search paths used by clang/ld during link, and by dyld at runtime.
    "LIBRARY_PATH",
    "LD_LIBRARY_PATH",
    "DYLD_LIBRARY_PATH",
    "DYLD_FALLBACK_LIBRARY_PATH",
    # macOS SDK selection (cc-wrapper uses SDKROOT to gate --sysroot).
    "SDKROOT",
    "MACOSX_DEPLOYMENT_TARGET",
    # Pkgconfig + Cargo toolchain configuration that the user expects to flow
    # into cargo invocations under nix-develop.
    "PKG_CONFIG_PATH",
    "PKG_CONFIG_PATH_FOR_TARGET",
    "CARGO_HOME",
    "RUSTUP_HOME",
    "RUSTUP_TOOLCHAIN",
    "RUSTFLAGS",
    "CARGO_BUILD_TARGET",
    "CARGO_NET_OFFLINE"
  ]

  ## Env-var name prefixes forwarded wholesale. The cc-wrapper synthesizes
  ## per-tuple variables of the form
  ## ``NIX_LDFLAGS_<HOST>_<TARGET>``/``NIX_CFLAGS_COMPILE_<HOST>_<TARGET>`` /
  ## ``NIX_BINTOOLS_WRAPPER_TARGET_HOST_<triple>`` whose suffixes vary by host
  ## triple (e.g. ``aarch64_apple_darwin``). Forwarding them by prefix avoids
  ## host-specific allowlist drift.
  DaemonNixToolchainEnvPrefixes* = [
    "NIX_LDFLAGS_",
    "NIX_CFLAGS_",
    "NIX_BINTOOLS_",
    "NIX_CC_",
    "NIX_BUILD_CORES",
    "NIX_STORE",
    "NIX_USER_PROFILE_DIR",
    "NIX_PROFILES"
  ]

proc daemonCarriedEnvironment*(): seq[string] =
  ## Snapshot the user-facing CLI environment for the daemon-hosted build/watch
  ## executor. Direct builds evaluate providers and resolve action
  ## ``envPassthrough`` values against this environment; daemon builds must be
  ## byte-for-byte equivalent even when a project declares an arbitrary name
  ## that reprobuild could not know in advance.
  ##
  ## The request worker installs this snapshot only for the duration of one
  ## session and restores its prior environment afterwards. The build engine
  ## still filters each action down to its declared passthrough set. The wire
  ## sanitizer removes the test runner's private ownership marker before any
  ## request is encoded.
  var seen = initHashSet[string]()
  for key, value in envPairs():
    if key.len == 0 or seen.contains(key):
      continue
    seen.incl(key)
    result.add(key & "=" & value)
  result = sanitizeUserDaemonRequestEnvironment(result)

const StandardRunquotadPoolCaps* = [
  ("compile", 8'u32),
  ("fetch", 2'u32)
]
  ## RX pool-forwarding — the two convention pools the standard provider's
  ## convention bodies always register (``buildPool("compile", 8'u32)`` /
  ## ``buildPool("fetch", 2'u32)`` in ``runtime_core``; also pinned in the
  ## engine's in-process ``poolCapacity`` table at
  ## ``repro_build_engine.nim`` ~L3592). Kept as a named constant so the
  ## defaults live in one place and the argv assembler + its test share
  ## the same source of truth.

proc assembleRunquotadPoolArgs*(extraPools: openArray[BuildPool]): seq[string] =
  ## Build the ``--pool NAME=CAP`` argv fragment forwarded to ``runquotad``.
  ##
  ## The daemon initialises ``namedPoolCaps`` empty (see
  ## ``runquota_daemon.canAdmitImmediately`` — ``cap == 0 or units > cap``
  ## denies), so every action whose ``pool`` field is non-empty must have a
  ## matching ``--pool`` flag or its lease is denied and the engine's
  ## ``automaticMonitor`` retry loop spins forever (``repro build`` hangs).
  ##
  ## Historically only the two convention pools (``compile`` / ``fetch``)
  ## were forwarded. RX: a recipe can declare its own pool via
  ## ``buildPool("<name>", <cap>)`` and route execute edges through it
  ## (``edge.testBinary.run(pool="<name>", poolUnits=1)``) to serialize
  ## resource-contending tests. Those custom pools reach the CLI as
  ## ``buildGraph.pools`` entries in the extracted project graph. We forward
  ## every such pool here IN ADDITION to the convention defaults so its
  ## leases are granted. Custom pool names carry dots / dashes (e.g.
  ## ``nim_pty.pty-serial``); ``runquotad`` parses ``--pool`` with
  ## ``split("=", 1)`` (apps/runquotad/runquotad.nim ~L91) so only the first
  ## ``=`` splits and dotted names survive intact.
  var seen = initTable[string, uint32]()
  for (name, cap) in StandardRunquotadPoolCaps:
    seen[name] = cap
  # A recipe may legitimately re-declare a convention pool with a different
  # cap (e.g. widen ``compile``). The recipe-declared value wins since it is
  # what the engine's in-process ``poolCapacity`` table gates on, so the
  # daemon budget must match it; otherwise the two gates disagree.
  for pool in extraPools:
    if pool.name.len == 0:
      continue
    seen[pool.name] = pool.capacity
  # Deterministic order: convention pools first (stable historical shape the
  # M9.R.12.3 contract pins), then remaining custom pools sorted by name.
  for (name, _) in StandardRunquotadPoolCaps:
    result.add("--pool")
    result.add(name & "=" & $seen[name])
    seen.del(name)
  var customNames: seq[string] = @[]
  for name in seen.keys:
    customNames.add(name)
  customNames.sort()
  for name in customNames:
    result.add("--pool")
    result.add(name & "=" & $seen[name])

proc startAutoRunQuotaIfNeeded(bypassRunQuota: bool;
                               extraPools: openArray[BuildPool] = []):
    owned(Process) =
  if bypassRunQuota or not autoRunQuotaEnabled():
    return nil
  # If RUNQUOTA_SOCKET is set, the user (or a parent invocation) is
  # managing the daemon explicitly. On Windows we additionally probe
  # reachability so a stale env var inherited from a previous build —
  # which the daemon-hosted executor restores via ``putEnv`` even after
  # the prior runquotad was terminated — does not cause us to skip
  # spawning a fresh one for this build. On POSIX the per-PID socket
  # path is unique so a stale value would point at a missing file; the
  # subsequent runquota client connect would fail. Probing here makes
  # both platforms self-healing.
  if getEnv("RUNQUOTA_SOCKET", "").len > 0 and isRunQuotaDaemonReachable():
    return nil
  # M9.R.11 — also bypass a fresh spawn when the default per-user pipe
  # is already serviced by a healthy daemon (the common case: a previous
  # ``repro build`` left its daemon running and we just need to reuse
  # it). ``isRunQuotaDaemonReachable`` already does the cheap
  # WaitNamedPipeW probe + Hello/HelloOk round-trip via
  # ``connectDefault`` on Windows, so when it returns true the daemon
  # is genuinely accepting connections.
  if isRunQuotaDaemonReachable():
    return nil
  # M9.R.13c.1 — **deterministic stale-pipe recovery**. The wedge that
  # blocked every M9.R.13b iter past iter 11 (and forced the operator
  # to manually ``Stop-Process`` ``runquotad.exe`` between every build)
  # is now closed at the client side: when the pipe exists in NPFS but
  # ``probeWindowsPipeOwner`` reports its owner as dead / inaccessible
  # / unknown, we terminate the dead owner so the kernel reclaims the
  # NPFS object and then fall through to the fresh-spawn block below.
  # The killer-of-last-resort path is conservative — we only terminate
  # processes we can prove are the canonical pipe's server, never a
  # generic Stop-Process equivalent.
  when defined(windows):
    let canonicalPipe = defaultRunQuotaWindowsPipePath()
    if canonicalPipe.len > 0:
      let probe = probeWindowsPipeOwner(canonicalPipe)
      if probe.status == wpsStale:
        # Owner is dead or inaccessible — drop it so NPFS releases the
        # name. ``terminateStalePipeOwner`` is a no-op when the owner
        # has already exited (the kernel may take milliseconds to reap
        # the handle after process exit).
        discard terminateStalePipeOwner(probe.serverPid)
        # Give NPFS a tick to clear the handle then re-probe so the
        # subsequent ``isRunQuotaDaemonReachable`` block in the spawn
        # loop sees a healthy daemon.
        for _ in 0 ..< 10:
          if probeWindowsPipeOwner(canonicalPipe).status == wpsAbsent:
            break
          sleep(50)
  let runquotad = findRunQuotaDaemonBin()
  if runquotad.len == 0:
    # No daemon binary discovered. Return nil silently — downstream
    # ``tryEnsureInlineRunQuotaSession`` will probe ``connectDefault``,
    # and ``config.fallbackToRunQuotaBypass`` (set true for
    # ``tpmPathOnly`` / ``tpmScoop``) routes to the bypass path. For
    # modes with ``fallbackToRunQuotaBypass=false`` (e.g.
    # ``tpmFromSource``) the build engine surfaces the diagnostic
    # through the rewritten exception in ``tryEnsureInlineRunQuotaSession``
    # (M9.R.11 — see ``repro_build_engine.runQuotaUnreachableHint``).
    return nil
  # Pipe-name / socket-path derivation.
  #
  # Windows: omit ``--socket`` so runquotad binds to its built-in
  # per-user default endpoint (``\\.\pipe\runquota-<USERNAME>`` —
  # see ``runquota_ipc.defaultEndpoint``). The client side also
  # falls through to ``defaultEndpoint`` when ``RUNQUOTA_SOCKET``
  # is unset, so both halves of the IPC always meet on the same
  # pipe regardless of which process spawned the daemon, which
  # PID it has, or whether the env var was forwarded across the
  # daemon protocol. This is the fix for the M1 regression where a
  # ``getTempDir()/reprobuild-runquota-<PID>.sock`` derivation
  # produced a different ``windowsPipeToken`` hash on every
  # invocation, so a runquotad spawned by one ``repro build`` was
  # invisible to the next one. We deliberately leave RUNQUOTA_SOCKET
  # unset on Windows so child actions (which inherit the daemon's
  # env) likewise hit the default endpoint.
  #
  # POSIX: a per-PID Unix socket, but inside a DIRECTORY OF ITS OWN
  # rather than loose in ``$TMPDIR``. The socket's parent directory is
  # the rendezvous point that ``runquotad`` verifies before binding and
  # every client verifies before connecting, and a shared ``/tmp`` is
  # root-owned ``1777``, which fails both halves — the daemon exits
  # before it listens and the build dies with the refusal in its log.
  # ``runquotaEndpointPath`` owns that rule; see its docs for why the
  # answer is a private directory and not a laxer check.
  # M9.R.12.3 — declare the standard named pools the convention layer
  # registers (``compile`` + ``fetch``). Without these flags the daemon
  # initialises ``namedPoolCaps`` empty, so every action that requests
  # a non-empty ``pool`` (which the M9.R.6.1 convention sentinel +
  # M9.R.12.1 autotools_package configure action + every from-source-*
  # convention does) hits the
  # ``lease request exceeds named-pool budget: <name>`` denial and the
  # ``automaticMonitor`` retry loop spins until exhaustion.
  #
  # Caps mirror what the standard provider's convention bodies declare
  # at ``buildPool("compile", 8'u32)`` / ``buildPool("fetch", 2'u32)``
  # — the engine-side ``poolCapacity`` table already pins these values
  # for in-process gating; the daemon now sees the matching budget.
  #
  # RX: in ADDITION to the convention defaults, forward every
  # recipe-declared custom pool (``extraPools`` — the pools present in the
  # extracted project graph, i.e. ``buildGraph.pools``). Without this a
  # recipe's ``buildPool("nim_pty.pty-serial", 1)`` never reaches the
  # daemon, its execute-edge lease hits ``lease request exceeds named-pool
  # budget: nim_pty.pty-serial``, and the build hangs.
  let standardPoolArgs = assembleRunquotadPoolArgs(extraPools)
  let memoryBytes = $autoRunQuotaMemoryBytes()
  when defined(windows):
    var args = @[
      "--cpu-milli", $int(buildMaxParallelism() * 1000'u32),
      "--memory-bytes", memoryBytes
    ]
    args.add(standardPoolArgs)
    # Clear any stale value so the client side falls through to
    # ``defaultEndpoint`` and meets the daemon on the per-user pipe.
    putEnv("RUNQUOTA_SOCKET", "")
    let socket = ""
  else:
    let socket = runquotaEndpointPath(
      "reprobuild-runquota-" & $getCurrentProcessId())
    if fileExists(socket):
      removeFile(socket)
    var args = @[
      "--socket", socket,
      "--cpu-milli", $int(buildMaxParallelism() * 1000'u32),
      "--memory-bytes", memoryBytes
    ]
    args.add(standardPoolArgs)
    putEnv("RUNQUOTA_SOCKET", socket)
  result = startProcess(runquotad, args = args, options = {poUsePath})
  for _ in 0 ..< 300:
    if isRunQuotaDaemonReachable():
      return
    if not result.running:
      break
    sleep(50)
  try:
    result.terminate()
    discard result.waitForExit()
    result.close()
  except CatchableError:
    discard
  when not defined(windows):
    putEnv("RUNQUOTA_SOCKET", "")
  let endpointHint =
    when defined(windows): "default per-user named pipe"
    else: socket
  raise newException(OSError,
    "runquotad did not become reachable at " & endpointHint)

proc releaseAutoRunQuotaProcess*(process: var owned(Process)) =
  ## Release this invocation's handle to an automatically started RunQuota
  ## daemon. Windows uses a shared per-user named pipe, so another concurrent
  ## invocation may already have adopted the daemon; terminating it here would
  ## break that client's live session. POSIX auto-daemons use invocation-local
  ## socket paths and remain owned by their spawning process.
  if process == nil:
    return
  try:
    when not defined(windows):
      process.terminate()
      discard process.waitForExit()
    process.close()
  except CatchableError:
    discard
  process = nil

proc autoRunQuotaNeedsPoolPreflight(bypassRunQuota: bool): bool =
  ## Pool discovery compiles/inspects the project provider. Do it only when
  ## this process may actually spawn runquotad and can pass the discovered
  ## pools at daemon startup; an already-reachable daemon cannot be amended.
  if bypassRunQuota or not autoRunQuotaEnabled():
    return false
  if getEnv("RUNQUOTA_SOCKET", "").len > 0 and isRunQuotaDaemonReachable():
    return false
  if isRunQuotaDaemonReachable():
    return false
  findRunQuotaDaemonBin().len > 0

proc runDepsRefreshCommand(args: openArray[string]): int =
  ## Implements ``repro deps refresh`` — the Mode 3 scanner CLI.
  ##
  ## Three behaviours, selected by flag:
  ##   * default      : scan, write ``repro.scanned-deps.nim`` atomically
  ##                    (temp file + rename), return 0.
  ##   * ``--check``  : scan, compare to on-disk file, return 0 if
  ##                    up-to-date or 1 if drifted. Never writes.
  ##   * ``--dry-run``: scan, print what the new file would contain to
  ##                    stdout (and the unified diff against the on-disk
  ##                    file as a comment header). Never writes.
  ##
  ## Project resolution: a single positional argument (or ``--project=PATH``)
  ## is used as the workspace root; default is the current working dir.
  ## See ``reprobuild-specs/Three-Mode-Convention-System.md`` §"`repro
  ## deps refresh` CLI" for the contract.
  var projectArg = ""
  var checkOnly = false
  var dryRun = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--help" or arg == "-h":
      echo "usage: repro deps refresh [--check] [--dry-run] [--project=PATH] [PATH]"
      return 0
    elif arg == "--check":
      checkOnly = true
    elif arg == "--dry-run":
      dryRun = true
    elif arg == "--project":
      if i + 1 >= args.len:
        raise newException(ValueError, "--project requires a value")
      projectArg = args[i + 1]
      inc i
    elif arg.startsWith("--project="):
      projectArg = arg["--project=".len .. ^1]
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported deps refresh flag: " & arg)
    elif projectArg.len == 0:
      projectArg = arg
    else:
      raise newException(ValueError,
        "unexpected deps refresh argument: " & arg)
    inc i

  let workspaceRoot =
    if projectArg.len == 0:
      getCurrentDir()
    else:
      absolutePath(projectArg)
  if not dirExists(workspaceRoot):
    raise newException(ValueError,
      "deps refresh: workspace root does not exist: " & workspaceRoot)

  # Mode 3 multi-language scan: combine the Nim and the C/C++ scanner
  # outputs into a single deterministic ``ScanResult``. ``scanWorkspaceAll``
  # lives in ``repro_core/cpp_dep_scanner`` and unions both scanners'
  # member + edge seqs with per-key dedup so a mixed-language workspace
  # produces a byte-stable ``repro.scanned-deps.nim``.
  let scan = scanWorkspaceAll(workspaceRoot)
  let rendered = renderScannedDepsFile(scan.edges, ReprobuildVersion,
    scan.members, workspaceRoot)

  # The output file lives next to the project file; we honour
  # whichever name the user has on disk (repro.nim vs reprobuild.nim).
  let projectMatch = resolveProjectFile(workspaceRoot)
  let outputPath = workspaceRoot / "repro.scanned-deps.nim"

  if dryRun:
    echo "# DRY RUN — would write to ", outputPath
    if projectMatch.path.len == 0:
      echo "# warning: no repro.nim / reprobuild.nim found at ",
        workspaceRoot,
        " — the generated file will only be useful once one is created."
    stdout.write(rendered)
    return 0

  let existing = readExistingScannedDeps(outputPath)
  if existing == rendered:
    if checkOnly:
      return 0
    # Up-to-date already; nothing to write. Idempotent re-run.
    return 0

  if checkOnly:
    stderr.writeLine("repro deps refresh --check: " &
      "repro.scanned-deps.nim is out of date at " & outputPath)
    stderr.writeLine("  run `repro deps refresh` to regenerate.")
    return 1

  # Atomic write: temp file in the same dir, then rename. The same-dir
  # rule is what guarantees atomicity on Windows + POSIX (cross-volume
  # renames silently fall back to copy+delete).
  let tempPath = outputPath & ".tmp"
  try:
    writeFile(tempPath, rendered)
    moveFile(tempPath, outputPath)
  except CatchableError as err:
    if fileExists(tempPath):
      try:
        removeFile(tempPath)
      except CatchableError:
        discard
    raise newException(ValueError,
      "deps refresh: failed to write " & outputPath & ": " & err.msg)

  echo "wrote ", outputPath, " (", scan.edges.len, " edges across ",
    scan.members.len, " targets)"
  0

const
  KnownConventionRegistry* = [
    "nim",
    "rust",
    "go",
    "python",
    "javascript-typescript",
    "c-cpp-autotools",
    "c-cpp-cmake",
    "c-cpp-meson",
    "c-cpp-make",
    "java-maven",
    "kotlin-gradle",
    "csharp-dotnet",
    "swift-swiftpm",
    "c-cpp-direct",
    "rust-direct",
    "go-direct",
    "python-direct",
    "jsts-direct",
    "fortran-direct",
    "zig-direct",
    "d-direct",
    "ada-direct",
    "pascal-direct",
    "crystal",
    "erlang-rebar3",
    "elixir-mix",
    "ocaml-dune",
    "haskell-cabal",
    "ruby-bundler",
    "php-composer",
  ]
    ## The convention list ``repro show-conventions`` prints when asked
    ## for the registry order. Mirrors the registration order in
    ## ``apps/repro-standard-provider/repro_standard_provider.nim`` (which
    ## is the binary that actually holds the populated
    ## ``defaultConventionRegistry`` — the ``repro`` CLI itself doesn't
    ## link the per-language plugins, so we expose a static
    ## hand-maintained list here for diagnostics rather than touching
    ## the registry on disk).
    ##
    ## **Order matters.** The c-cpp triple must list ``c-cpp-autotools``
    ## BEFORE ``c-cpp-cmake`` BEFORE ``c-cpp-make`` to mirror the
    ## registration order in the standard-provider binary (a project
    ## carrying both a Makefile and ``configure.ac`` is routed through
    ## Autotools because it ``recognize``-matches first; a project
    ## carrying CMakeLists.txt routes through ``c-cpp-cmake`` (M38) ahead
    ## of the Make convention which separately rejects CMakeLists.txt
    ## presence). The order documented here is the order users see in
    ## ``repro show-conventions`` and must match reality. If the standard
    ## provider binary changes registration order, update this constant
    ## to match — the pin test in
    ## ``libs/repro_standard_provider/tests/test_known_convention_registry_pin.nim``
    ## fails loudly when the two drift.

proc renderShowConventionsText(workspaceRoot: string;
                               projectMatch: ProjectFileMatch;
                               members: seq[WorkspaceMember];
                               scanned: seq[DepEdge];
                               manual: seq[ManualDepEdge];
                               targetFilter: string): string =
  ## Pretty-printer for ``repro show-conventions``. Output shape is
  ## documented in ``reprobuild-specs/Three-Mode-Convention-System.md``
  ## §"Observability"; this is the human-readable projection (the JSON
  ## projection lives in ``renderShowConventionsJson``).
  ##
  ## **Attribution / toolchain / no-match** (the three M-deferred items):
  ## the "Language convention" line for each target is now computed by
  ## ``attributeConvention`` (manifest detection + extension census; the
  ## heuristic is documented in ``repro_core/convention_attribution.nim``,
  ## option 1c — the pragmatic CLI-side approximation). After the
  ## per-target section, ``findUnclaimedDirectories`` adds a "No-match
  ## diagnostics" block listing target-shaped dirs the heuristic couldn't
  ## claim. Each detected convention's toolchain version is probed (at
  ## most once per convention per process) via ``probeToolchain`` and
  ## printed next to the target's convention line.
  result = "Project: " & workspaceRoot & "\n"
  if projectMatch.path.len == 0:
    result.add("Project file: (none — no repro.nim or reprobuild.nim " &
      "in this directory)\n")
  else:
    let canonical = projectMatch.fileName == CanonicalProjectFileName
    let suffix = if canonical: " (canonical)" else: " (legacy alias)"
    result.add("Project file: " & projectMatch.fileName & suffix & "\n")
  result.add("\n")

  # Track which conventions appeared at least once so the toolchain
  # probe summary can iterate the right set.
  var conventionsSeen: HashSet[string]

  if members.len == 0:
    result.add("No targets discovered.\n")
    result.add("  (the scanner walks for ``executable`` / ``library`` " &
      "declarations under apps/, libs/, or the workspace root; none " &
      "matched)\n\n")
  else:
    # Index scanned edges + manual edges by source package for fast
    # per-target rendering.
    var scannedByFrom: Table[string, seq[DepEdge]]
    for edge in scanned:
      scannedByFrom.mgetOrPut(edge.fromPackage, @[]).add(edge)
    var manualByFrom: Table[string, seq[ManualDepEdge]]
    for edge in manual:
      manualByFrom.mgetOrPut(edge.fromPackage, @[]).add(edge)
    var matched = 0
    for member in members:
      if targetFilter.len > 0 and member.member != targetFilter and
          member.package != targetFilter:
        continue
      inc matched
      # Attribute the convention from the member's project-root
      # directory. Default to ``"nim"`` when the heuristic abstains
      # (the scanner only finds Nim-declared members today, so an
      # abstain on a discovered member means "no clearer signal than
      # the existence of repro.nim itself" — fall back to ``nim``).
      let attribution = attributeConvention(member.projectRoot)
      let conventionName =
        if attribution.convention.len > 0:
          attribution.convention
        else:
          "nim"
      conventionsSeen.incl(conventionName)
      result.add("Target: " & member.package & "." & member.member & "\n")
      if attribution.evidence.len > 0:
        result.add("  Language convention: " & conventionName &
          " (" & attribution.evidence & ")\n")
      else:
        result.add("  Language convention: " & conventionName & "\n")
      if member.sourceFile.len > 0:
        var relSource =
          try:
            relativePath(member.sourceFile, workspaceRoot)
          except OSError:
            member.sourceFile
        relSource = relSource.replace('\\', '/')
        result.add("  Source layout: " & relSource & "\n")
      else:
        result.add("  Source layout: (no src/" & member.member &
          ".nim on disk)\n")
      var relProjectFile =
        try:
          relativePath(member.projectFile, workspaceRoot)
        except OSError:
          member.projectFile
      relProjectFile = relProjectFile.replace('\\', '/')
      result.add("  Project file: " & relProjectFile & "\n")
      let scannedEdges = scannedByFrom.getOrDefault(member.package, @[])
      # The scanner emits edges keyed by package, not by member —
      # filter to UNIQUE (toPackage, evidence) pairs so two members of
      # the same package don't double-print every edge.
      result.add("  Workspace deps (from scanner):\n")
      if scannedEdges.len == 0:
        result.add("    (no edges)\n")
      else:
        var seen: HashSet[string]
        for edge in scannedEdges:
          let key = edge.toPackage & "\x1f" & edge.evidence
          if key in seen:
            continue
          seen.incl(key)
          result.add("    - " & edge.toPackage & " (evidence: " &
            edge.evidence & ")\n")
      let manualEdges = manualByFrom.getOrDefault(member.package, @[])
      result.add("  Workspace deps (manual, from project file):\n")
      if manualEdges.len == 0:
        result.add("    (none)\n")
      else:
        var seen: HashSet[string]
        for edge in manualEdges:
          let key = edge.toPackage & "\x1f" & $edge.sourceLine
          if key in seen:
            continue
          seen.incl(key)
          result.add("    - " & edge.toPackage & " (declared at " &
            relProjectFile & ":" & $edge.sourceLine & ")\n")
      result.add("\n")
    if targetFilter.len > 0 and matched == 0:
      result.add("(no target named ``" & targetFilter &
        "`` discovered in this workspace)\n\n")

  # No-match diagnostics. Only when the user didn't ask for a single
  # target (the diagnostic is workspace-wide).
  if targetFilter.len == 0:
    var claimedPaths: seq[string] = @[]
    for member in members:
      if member.projectRoot.len > 0:
        claimedPaths.add(member.projectRoot)
    let unclaimed = findUnclaimedDirectories(workspaceRoot, claimedPaths)
    result.add("No-match diagnostics:\n")
    if unclaimed.len == 0:
      result.add("  (no unclaimed target-shaped directories)\n")
    else:
      for entry in unclaimed:
        var line = "  " & entry.relPath & "/ — " & entry.reason
        if entry.sampleFiles.len > 0:
          line.add(" (files: ")
          for i, f in entry.sampleFiles:
            if i > 0: line.add(", ")
            line.add(f)
          line.add(")")
        line.add("\n")
        result.add(line)
    result.add("\n")

  # Toolchain probe summary. We probe each convention that appeared as
  # a per-target claim. Misses print the "not on PATH (skipped)"
  # variant, matching the spec's example output.
  if targetFilter.len == 0 and conventionsSeen.len > 0:
    result.add("Toolchain probes:\n")
    # Iterate the known registry order so the output is deterministic
    # across runs even if the conventions hash to different buckets.
    for name in KnownConventionRegistry:
      if name notin conventionsSeen:
        continue
      let probe = probeToolchain(name)
      if probe.available:
        let suffix =
          if probe.path.len > 0:
            " [" & probe.path.replace('\\', '/') & "]"
          else:
            ""
        result.add("  " & name & ": " & probe.version & suffix & "\n")
      else:
        result.add("  " & name & ": not on PATH (skipped)\n")
    result.add("\n")

  result.add("Conventions registered (in dispatch order):\n")
  for name in KnownConventionRegistry:
    result.add("  - " & name & "\n")
  result.add("\n")
  result.add("Note: the convention registry above is the static list " &
    "the standard-provider binary registers at startup; the per-target " &
    "claim attribution above is a CLI-side heuristic (manifest detection " &
    "plus extension census; see ``repro_core/convention_attribution.nim`` " &
    "option 1c). The standard-provider's actual ``recognize`` is the " &
    "source of truth at build time.\n")

proc renderShowConventionsJson(workspaceRoot: string;
                               projectMatch: ProjectFileMatch;
                               members: seq[WorkspaceMember];
                               scanned: seq[DepEdge];
                               manual: seq[ManualDepEdge];
                               targetFilter: string): JsonNode =
  ## JSON projection of the same data the text renderer prints.
  ## Stable shape: top-level object with ``project``, ``projectFile``,
  ## ``targets[]``, ``conventions[]``. Each target carries its own
  ## ``scannedDeps[]`` and ``manualDeps[]`` arrays.
  result = newJObject()
  result["project"] = %workspaceRoot
  if projectMatch.path.len == 0:
    result["projectFile"] = newJNull()
  else:
    let pfNode = newJObject()
    pfNode["fileName"] = %projectMatch.fileName
    pfNode["canonical"] = %(projectMatch.fileName == CanonicalProjectFileName)
    result["projectFile"] = pfNode
  var scannedByFrom: Table[string, seq[DepEdge]]
  for edge in scanned:
    scannedByFrom.mgetOrPut(edge.fromPackage, @[]).add(edge)
  var manualByFrom: Table[string, seq[ManualDepEdge]]
  for edge in manual:
    manualByFrom.mgetOrPut(edge.fromPackage, @[]).add(edge)
  var conventionsSeen: HashSet[string]
  let targets = newJArray()
  for member in members:
    if targetFilter.len > 0 and member.member != targetFilter and
        member.package != targetFilter:
      continue
    let entry = newJObject()
    entry["package"] = %member.package
    entry["member"] = %member.member
    # Per-target convention attribution (manifest detection + extension
    # census; see ``repro_core/convention_attribution.nim`` option 1c).
    # The heuristic abstains for projects with only a project file (no
    # manifest, no source extensions matched); fall back to ``"nim"``
    # for the scanner-discovered targets because the scanner itself is
    # the Nim-only Mode-3 pilot today.
    let attribution = attributeConvention(member.projectRoot)
    let conventionName =
      if attribution.convention.len > 0:
        attribution.convention
      else:
        "nim"
    conventionsSeen.incl(conventionName)
    entry["convention"] = %conventionName
    let attrNode = newJObject()
    attrNode["convention"] = %conventionName
    attrNode["evidence"] = %attribution.evidence
    entry["attribution"] = attrNode
    if member.sourceFile.len > 0:
      var relSource =
        try:
          relativePath(member.sourceFile, workspaceRoot)
        except OSError:
          member.sourceFile
      relSource = relSource.replace('\\', '/')
      entry["sourceFile"] = %relSource
    else:
      entry["sourceFile"] = newJNull()
    var relProjectFile =
      try:
        relativePath(member.projectFile, workspaceRoot)
      except OSError:
        member.projectFile
    relProjectFile = relProjectFile.replace('\\', '/')
    entry["projectFile"] = %relProjectFile
    let scannedNode = newJArray()
    var seenScan: HashSet[string]
    for edge in scannedByFrom.getOrDefault(member.package, @[]):
      let key = edge.toPackage & "\x1f" & edge.evidence
      if key in seenScan:
        continue
      seenScan.incl(key)
      let e = newJObject()
      e["to"] = %edge.toPackage
      e["evidence"] = %edge.evidence
      scannedNode.add(e)
    entry["scannedDeps"] = scannedNode
    let manualNode = newJArray()
    var seenManual: HashSet[string]
    for edge in manualByFrom.getOrDefault(member.package, @[]):
      let key = edge.toPackage & "\x1f" & $edge.sourceLine
      if key in seenManual:
        continue
      seenManual.incl(key)
      let e = newJObject()
      e["to"] = %edge.toPackage
      e["sourceLine"] = %edge.sourceLine
      manualNode.add(e)
    entry["manualDeps"] = manualNode
    targets.add(entry)
  result["targets"] = targets
  # No-match diagnostics (only when not filtering to a single target).
  let unclaimedNode = newJArray()
  if targetFilter.len == 0:
    var claimedPaths: seq[string] = @[]
    for member in members:
      if member.projectRoot.len > 0:
        claimedPaths.add(member.projectRoot)
    for entry in findUnclaimedDirectories(workspaceRoot, claimedPaths):
      let n = newJObject()
      n["path"] = %entry.relPath
      n["reason"] = %entry.reason
      let samples = newJArray()
      for s in entry.sampleFiles:
        samples.add(%s)
      n["sampleFiles"] = samples
      unclaimedNode.add(n)
  result["unclaimedDirectories"] = unclaimedNode
  # Toolchain probes (only when not filtering to a single target).
  let toolchainNode = newJArray()
  if targetFilter.len == 0:
    for name in KnownConventionRegistry:
      if name notin conventionsSeen:
        continue
      let probe = probeToolchain(name)
      let n = newJObject()
      n["convention"] = %name
      n["available"] = %probe.available
      n["version"] = %probe.version
      if probe.path.len > 0:
        n["path"] = %probe.path.replace('\\', '/')
      else:
        n["path"] = newJNull()
      toolchainNode.add(n)
  result["toolchainProbes"] = toolchainNode
  let conventionsNode = newJArray()
  for name in KnownConventionRegistry:
    conventionsNode.add(%name)
  result["conventions"] = conventionsNode

# ----------------------------------------------------------------------
# M48 — Mode 1 show-conventions renderers. Output prefix ``[Mode 1 —
# inferred from layout]`` so users can tell when they're seeing
# Mode 1 inference vs Mode 3 scanned output. See the M48 section of
# Mode3-Language-Expansion.milestones.org.
# ----------------------------------------------------------------------

proc renderMode1ShowConventionsText(ws: Mode1Workspace;
                                    targetFilter: string): string =
  ## Human-readable Mode 1 show-conventions output. Sibling of
  ## ``renderShowConventionsText`` for the Mode 1 case.
  result = "[Mode 1 — inferred from layout]\n"
  result.add("Project: " & ws.workspaceRoot & "\n")
  result.add("Project file: (none — Mode 1 synthesises in-memory)\n")
  if ws.syntheticProjectFile.len > 0:
    result.add("Synthesised under: " & ws.syntheticProjectFile & "\n")
  result.add("\n")
  if ws.ambiguousImports.len > 0:
    result.add("AMBIGUOUS IMPORTS — Mode 1 cannot proceed:\n")
    for incident in ws.ambiguousImports:
      var rel =
        try:
          relativePath(incident.sourceFile, ws.workspaceRoot)
        except OSError:
          incident.sourceFile
      rel = rel.replace('\\', '/')
      result.add("  - " & rel & ":" & $incident.lineNumber &
        ": import '" & incident.importHead &
        "' resolves to: " & incident.candidates.join(", ") & "\n")
    result.add("\n")
    result.add("Resolve by graduating to Mode 3: write a repro.nim " &
      "with explicit depends_on edges.\n\n")
    return
  if ws.targets.len == 0:
    result.add("No Mode 1 targets discovered.\n")
    result.add("  (the loader scanned apps/, libs/, tools/, cmd/, " &
      "pkg/, bin/ and the workspace's src/ — none matched)\n\n")
    return
  result.add("Inferred targets:\n")
  for target in ws.targets:
    if targetFilter.len > 0 and target.name != targetFilter:
      continue
    let kindLabel =
      if target.kind == m1tkExecutable: "executable" else: "library"
    result.add("  - " & target.name & " (" & kindLabel & ")\n")
    result.add("    Source dir: " & target.relDir & "\n")
    result.add("    Language: " & languageName(target.language) & "\n")
    if target.entrySource.len > 0:
      var rel =
        try:
          relativePath(target.entrySource, ws.workspaceRoot)
        except OSError:
          target.entrySource
      rel = rel.replace('\\', '/')
      result.add("    Entry source: " & rel & "\n")
    var censusKeys: seq[string] = @[]
    for ext, _ in target.extensionCensus.pairs:
      censusKeys.add(ext)
    censusKeys.sort(system.cmp[string])
    var censusParts: seq[string] = @[]
    for ext in censusKeys:
      censusParts.add(ext & "=" & $target.extensionCensus[ext])
    result.add("    Extension census: " & censusParts.join(", ") & "\n")
  result.add("\n")
  if ws.edges.len > 0:
    result.add("Inferred dep edges (scanner):\n")
    for edge in ws.edges:
      result.add("  - " & edge.fromPackage & " -> " & edge.toPackage &
        " (evidence: " & edge.evidence & ")\n")
  else:
    result.add("Inferred dep edges (scanner): (no in-workspace edges)\n")
  result.add("\n")
  if ws.diagnostics.len > 0:
    result.add("Diagnostics:\n")
    for d in ws.diagnostics:
      if d.target.len > 0:
        result.add("  - [" & d.target & "] " & d.message & "\n")
      else:
        result.add("  - " & d.message & "\n")
    result.add("\n")
  result.add("Persistence policy: Mode 1 does NOT write " &
    "repro.scanned-deps.nim to the workspace root.\n")

proc renderMode1ShowConventionsJson(ws: Mode1Workspace;
                                    targetFilter: string): JsonNode =
  ## JSON projection of the Mode 1 show-conventions output.
  result = newJObject()
  result["mode"] = %"mode1"
  result["project"] = %ws.workspaceRoot
  if ws.syntheticProjectFile.len > 0:
    result["synthesisedProjectFile"] = %ws.syntheticProjectFile
  else:
    result["synthesisedProjectFile"] = newJNull()
  let targetsNode = newJArray()
  for target in ws.targets:
    if targetFilter.len > 0 and target.name != targetFilter:
      continue
    let entry = newJObject()
    entry["name"] = %target.name
    entry["relDir"] = %target.relDir
    entry["kind"] =
      %(if target.kind == m1tkExecutable: "executable" else: "library")
    entry["language"] = %languageName(target.language)
    if target.entrySource.len > 0:
      var rel =
        try:
          relativePath(target.entrySource, ws.workspaceRoot)
        except OSError:
          target.entrySource
      rel = rel.replace('\\', '/')
      entry["entrySource"] = %rel
    else:
      entry["entrySource"] = newJNull()
    let censusNode = newJObject()
    for ext, count in target.extensionCensus.pairs:
      censusNode[ext] = %count
    entry["extensionCensus"] = censusNode
    targetsNode.add(entry)
  result["targets"] = targetsNode
  let edgesNode = newJArray()
  for edge in ws.edges:
    let e = newJObject()
    e["from"] = %edge.fromPackage
    e["to"] = %edge.toPackage
    e["evidence"] = %edge.evidence
    edgesNode.add(e)
  result["edges"] = edgesNode
  let diagsNode = newJArray()
  for d in ws.diagnostics:
    let n = newJObject()
    n["target"] = %d.target
    n["message"] = %d.message
    diagsNode.add(n)
  result["diagnostics"] = diagsNode
  let ambNode = newJArray()
  for incident in ws.ambiguousImports:
    let n = newJObject()
    n["fromTarget"] = %incident.fromTarget
    n["importHead"] = %incident.importHead
    n["sourceFile"] = %incident.sourceFile
    n["lineNumber"] = %incident.lineNumber
    n["rawLine"] = %incident.rawLine
    let candsNode = newJArray()
    for c in incident.candidates:
      candsNode.add(%c)
    n["candidates"] = candsNode
    ambNode.add(n)
  result["ambiguousImports"] = ambNode

proc runShowConventionsCommand(args: openArray[string]): int =
  ## Implements ``repro show-conventions`` — step 3 of the Three-Mode
  ## Convention System sequencing plan
  ## (``reprobuild-specs/Three-Mode-Convention-System.md``
  ## §"Observability"). Prints the resolved convention stack for a
  ## project: detected targets, the convention claiming each, the
  ## scanner-inferred edges, and the manual ``depends_on`` overrides.
  ##
  ## Flags:
  ##   * ``--project=PATH`` — workspace root (default: cwd; or a
  ##     positional argument if present).
  ##   * ``--target=NAME``  — only print details for the named member /
  ##     package.
  ##   * ``--json``         — emit a JSON document instead of the
  ##     human-readable text shape.
  ##
  ## Honest scope:
  ##   * Per-target convention attribution uses the heuristic from
  ##     ``repro_core/convention_attribution.nim`` (option 1c — manifest
  ##     detection plus extension census). The standard-provider's
  ##     actual ``recognize`` remains the source of truth at build time;
  ##     this is a CLI-side approximation good enough for the 95% case
  ##     (``Cargo.toml`` → Rust, ``pyproject.toml`` → Python, ...). The
  ##     follow-on milestone replaces the heuristic with either a shared
  ##     introspection library (option 1b) or a query-mode IPC to the
  ##     standard-provider binary (option 1a).
  ##   * The ``Conventions registered`` list is a static mirror of
  ##     the standard-provider binary's registration order. A test
  ##     fails loudly if the two drift.
  ##   * No-match diagnostics surface every target-shaped directory
  ##     (``apps/<x>``, ``libs/<x>``, ``cmd/<x>``, ``tools/<x>``,
  ##     ``pkg/<x>``, plus the workspace root when no parent directory
  ##     contains target slots) the heuristic couldn't claim.
  ##   * Toolchain probes run ``<tool> --version`` (or ``go version``)
  ##     for every convention that appears as a per-target claim, at
  ##     most once per convention per process invocation.
  var projectArg = ""
  var jsonOut = false
  var targetFilter = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--help" or arg == "-h":
      echo "usage: repro show-conventions [--project=PATH] " &
        "[--target=NAME] [--json] [PATH]"
      return 0
    elif arg == "--json":
      jsonOut = true
    elif arg == "--project":
      if i + 1 >= args.len:
        raise newException(ValueError, "--project requires a value")
      projectArg = args[i + 1]
      inc i
    elif arg.startsWith("--project="):
      projectArg = arg["--project=".len .. ^1]
    elif arg == "--target":
      if i + 1 >= args.len:
        raise newException(ValueError, "--target requires a value")
      targetFilter = args[i + 1]
      inc i
    elif arg.startsWith("--target="):
      targetFilter = arg["--target=".len .. ^1]
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported show-conventions flag: " & arg)
    elif projectArg.len == 0:
      projectArg = arg
    else:
      raise newException(ValueError,
        "unexpected show-conventions argument: " & arg)
    inc i

  let workspaceRoot =
    if projectArg.len == 0:
      getCurrentDir()
    else:
      absolutePath(projectArg)
  if not dirExists(workspaceRoot):
    raise newException(ValueError,
      "show-conventions: workspace root does not exist: " & workspaceRoot)

  let projectMatch = resolveProjectFile(workspaceRoot)

  # M48 — Mode 1 detection. When the workspace has NO project file
  # AND NO Mode 2 manifest, run the Mode 1 loader and render its
  # output with the ``[Mode 1 — inferred from layout]`` prefix so the
  # user sees the difference from Mode 3.
  if projectMatch.path.len == 0 and
      not hasMode2Manifest(workspaceRoot):
    let ws = loadMode1Workspace(workspaceRoot)
    if ws.targets.len > 0 or ws.ambiguousImports.len > 0:
      if jsonOut:
        let doc = renderMode1ShowConventionsJson(ws, targetFilter)
        echo doc.pretty()
      else:
        stdout.write(renderMode1ShowConventionsText(ws, targetFilter))
      if ws.ambiguousImports.len > 0:
        # Surface the hard-error diagnostic even in show-conventions
        # so users running ``repro show-conventions`` to debug see
        # the exit-non-zero signal that ``repro build`` would emit.
        return 1
      return 0

  # ``scanWorkspaceAll`` unions the Nim + C/C++ scanners so a mixed-
  # language workspace surfaces every member, not just the Nim ones.
  let scan = scanWorkspaceAll(workspaceRoot)
  # Collect manual ``depends_on`` edges from every project file the
  # scanner discovered (a workspace can hold several — apps/<name>/
  # repro.nim, libs/<name>/repro.nim, ...). We dedup by project-file
  # path so we don't double-emit when two members share a file.
  var manual: seq[ManualDepEdge] = @[]
  var seenProjectFiles: HashSet[string]
  for member in scan.members:
    if member.projectFile.len == 0:
      continue
    if member.projectFile in seenProjectFiles:
      continue
    seenProjectFiles.incl(member.projectFile)
    for edge in extractManualDependsOnFromProjectFile(member.projectFile):
      manual.add(edge)
  # Also consider the top-level project file in case there are no
  # members discovered (manual-only configuration).
  if projectMatch.path.len > 0 and
      projectMatch.path notin seenProjectFiles:
    for edge in extractManualDependsOnFromProjectFile(projectMatch.path):
      manual.add(edge)

  if jsonOut:
    let doc = renderShowConventionsJson(workspaceRoot, projectMatch,
      scan.members, scan.edges, manual, targetFilter)
    echo doc.pretty()
  else:
    stdout.write(renderShowConventionsText(workspaceRoot, projectMatch,
      scan.members, scan.edges, manual, targetFilter))
  0

proc runDepsCommand(args: openArray[string]): int =
  ## Dispatch ``repro deps <subcommand>``. Today the only subcommand is
  ## ``refresh``; the spec leaves room for ``deps show`` /
  ## ``deps explain`` as part of the ``repro show-conventions`` follow-on
  ## work (step 3 of the sequencing plan in
  ## ``Three-Mode-Convention-System.md`` §"Sequencing plan").
  if args.len == 0:
    stderr.writeLine("repro deps: missing subcommand (expected: refresh)")
    stderr.writeLine("usage: repro deps refresh [--check] [--dry-run] " &
      "[--project=PATH] [PATH]")
    return 2
  let sub = args[0]
  let rest =
    if args.len > 1:
      args[1 .. ^1]
    else:
      @[]
  case sub
  of "refresh":
    return runDepsRefreshCommand(rest)
  of "--help", "-h", "help":
    echo "usage: repro deps refresh [--check] [--dry-run] " &
      "[--project=PATH] [PATH]"
    return 0
  else:
    stderr.writeLine("repro deps: unknown subcommand: " & sub)
    return 2

# Named-Targets M5 forward declaration: the actual definition lives after
# ``prepareBuildGraphInspection`` (which the implementation calls) further
# down in this file.
proc runListTargetsCommand(target: string; mode: ToolProvisioningMode;
                           publicCliPath, workRoot: string;
                           asJson: bool; packageFilter: string;
                           bypassRunQuota: bool): int

# RX pool-forwarding forward declaration: extracts a recipe's declared
# ``buildPool(...)`` set (the ``buildGraph.pools`` present in the extracted
# project graph) so ``startAutoRunQuotaIfNeeded`` can forward them to the
# daemon as ``--pool NAME=CAP``. Best-effort — defined after
# ``prepareBuildGraphInspection`` (which it reuses) further down in the file.
proc extractRecipeBuildPools(target: string; mode: ToolProvisioningMode;
                             publicCliPath, workRoot: string;
                             bypassRunQuota: bool): seq[BuildPool]

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-1 — committed solved-graph lock.
#
# Canonical path convention: the committed lock lives next to the project
# file (``repro.nim`` / ``reprobuild.nim``) at ``<projectDir>/repro.lock``.
# The solver inputs the CLI solves for ``repro lock refresh`` / build-time
# lock consumption come (in MO-1) from a sidecar ``<projectDir>/repro.solver``
# in the M2e explain-fixture format (variants + packages + version ranges).
# A future milestone extracts the solver inputs/solution directly from the
# compiled project provider; until then the sidecar is the CLI-readable
# source of the same solve the DSL runs.
#
# ``--lock <file>`` (build/test/run + the lock verbs) selects an alternate
# committed lock; the default is the canonical path.
# ---------------------------------------------------------------------------

const
  CommittedLockFileName* = "repro.lock"
  SolverInputsFileName* = "repro.solver"

static:
  # Named-Lock-Files §7.2 drift guard. `workspaceGoverningLockIdentity` (above,
  # before this declaration point) must resolve the SAME file the build path
  # reads, or the governing lock identity stamped on every action would be
  # derived from a document nobody builds against. A forward reference is not
  # available in this module, so the duplicate is asserted away at compile
  # time rather than left to drift.
  doAssert CommittedLockFileNameForIdentity == CommittedLockFileName,
    "committed-lock filename drift: workspaceGoverningLockIdentity reads " &
    CommittedLockFileNameForIdentity & " but the build path reads " &
    CommittedLockFileName

proc committedLockPath*(projectDir: string): string =
  projectDir / CommittedLockFileName

proc solverInputsPath*(projectDir: string): string =
  projectDir / SolverInputsFileName

proc replacedSolvedVersion(projectRoot, dependency: string): string =
  ## Named-Lock-Files NLF-M2, the writer half — the version a develop override
  ## for ``dependency`` REPLACES, as the consumer's committed lock records it.
  ##
  ## `develop_sources.nim` names this source first and says why it needs no
  ## other: "the engine knows the upstream solved identity the override
  ## replaced, and when it records that, nothing else needs consulting". The
  ## committed lock is the document that holds that identity — a develop
  ## override substitutes a checkout for a solved node, and the solved node's
  ## version is exactly what `repro.lock` pins.
  ##
  ## THE CHECKOUT IS DELIBERATELY NOT CONSULTED HERE. It is the consumer's
  ## SECOND source, and reading it from the writer as well would collapse a
  ## two-source chain into one place where a value could come from either —
  ## so a checkout whose `VERSION` file changed after registration would keep
  ## reporting the stale registration-time value, which is worse than having
  ## no first source at all.
  ##
  ## Returns "" when the lock does not say, and "" means the field is not
  ## written. There is deliberately no fallback: a synthesized version here
  ## would be handed to a consumer that trusts source 1 unconditionally, which
  ## is the defect NLF-M2 removed from the solve wearing better provenance.
  if projectRoot.len == 0 or dependency.len == 0:
    return ""
  let lockP = committedLockPath(projectRoot)
  if not fileExists(extendedPath(lockP)):
    return ""
  var lock: LockedDependencies
  try:
    lock = parseLockedDependencies(readFile(extendedPath(lockP)))
  except CatchableError:
    # An unreadable lock is "we do not know", not "there is no version". The
    # caller writes nothing either way, and `repro lock validate` is the verb
    # whose job it is to complain about the lock itself.
    return ""
  # The solved graph first: a develop override replaces a SOLVED node, and
  # `packages` is where the solve's answer for that node lives. `deps` is
  # consulted second because a workspace repo carries an empty `version` there
  # (repro_lock.nim: "empty for a plain workspace repo") and only a
  # source-with-a-version entry answers this question at all.
  for pkg in lock.packages:
    if pkg.name == dependency and pkg.version.len > 0:
      return pkg.version
  for dep in lock.deps:
    if dep.name == dependency and dep.version.len > 0:
      return dep.version
  ""

# ---------------------------------------------------------------------------
# Cross-Repo-Source-Consumption SC-1 — the "resolve package binding" hook.
#
# Spec: ``Cross-Repo-Source-Consumption.md`` §4.1 (call-site wiring); §2 (the
# gap). This is the engine-facing entry point the M21 resolver contract was
# built for and the M22 comment (``override_resolution.nim:56-68``) deferred:
# a SINGLE seam that routes a cross-repo PRODUCER selector through
#
#   1. the develop-override map (``resolvePackageWithOverrides`` →
#      ``rpbkOverride`` → ``localPathAbsolute`` + ``contentIdentity``), then
#   2. on no override match, the consumer's committed ``repro.lock``
#      ``LockedDep`` for that producer (``Coordinates`` + ``integrity``).
#
# It is ADDITIVE and surface-agnostic (§4). It reuses — does NOT reinvent —
# ``resolvePackageWithOverrides`` (``override_resolution.nim:269-343``, until
# now called ONLY from a test) and the MO-8 ``LockedDep`` model
# (``repro_lock.nim:135-164``). SC-1 delivers the RESOLUTION seam only; the
# producer graph load + splice (SC-2/SC-3), the aux-channel materialization,
# and the ``foldOverridesIntoFingerprint`` invalidation (SC-4) build on the
# ``ProducerBinding`` this hook returns.
#
# A ref that is NOT a declared cross-repo producer (no develop override AND no
# matching ``LockedDep``) must not be materialized or spliced by the build graph,
# so every existing host-binary / nix / tarball / scoop / corpus-recipe ref keeps
# its resolver branch byte-for-byte (§4.1, §10). Plain on-disk siblings remain
# discoverable for typed-contract import, but ``declaresProducerEdge`` keeps
# them out of the build graph until an override or lock pin declares the edge.
# ---------------------------------------------------------------------------

## SC-1 ``ProducerBinding`` / ``ProducerBindingKind`` are declared up next to
## ``mkToolIdentityResolver`` (forward-declaration block) so the resolver
## closure can route a producer ref through the hook. The kind semantics:
##
##   * ``pbkNotProducer`` — no develop override matched AND no committed
##     ``LockedDep`` carries the selector: the caller keeps its existing
##     resolution branch unchanged (the "byte-identical for non-producer
##     refs" property, §4.1/§10).
##   * ``pbkDevelopOverride`` — a ``.repro/develop-overrides.toml`` entry
##     shadows the producer with a local checkout; ``localPathAbsolute`` is
##     the sibling checkout root and ``contentIdentity`` folds into the
##     consuming action's fingerprint (SC-4). ``overrideBinding`` is retained
##     so SC-4 can feed ``foldOverridesIntoFingerprint`` without re-resolving.
##   * ``pbkLockPinned`` — no override matched but the consumer's committed
##     ``repro.lock`` pins the producer as a ``LockedDep`` (VCS ``Coordinates``
##     + ``integrity``, §5.2) SC-6 fetches + verifies + builds from.
##   * ``pbkOnDiskSibling`` — a sibling source tree is discoverable, but no
##     build graph edge was declared. Typed schema import may use it; producer
##     materialization/splicing must not.

proc resolveProducerBinding*(selector: string;
                             workspaceRoot: string;
                             lock: LockedDependencies;
                             overrides: Option[DevelopOverrides]):
    ProducerBinding =
  ## The SC-1 "resolve package binding" hook (§4.1). Route ``selector``
  ## through the develop-override map first, then the committed ``LockedDep``
  ## set, and return the ``ProducerBinding`` describing how (or whether) the
  ## selector names a cross-repo producer or discoverable sibling.
  ##
  ## Order is significant and matches §5: a develop override always shadows a
  ## lock pin (develop-mode local-on-top, §6), so we consult
  ## ``resolvePackageWithOverrides`` FIRST and only fall through to the
  ## committed ``LockedDep`` when no override matched (``rpbkUpstream``). A
  ## selector present in NEITHER surface — but whose checkout is present as an
  ## on-disk workspace SIBLING (``../<selector>/repro.nim``) — yields
  ## ``pbkOnDiskSibling`` for schema discovery/diagnostics only. It is not a
  ## declared build graph edge; callers that materialize producers must gate on
  ## ``declaresProducerEdge``. A selector present in NONE of the three surfaces
  ## yields ``pbkNotProducer`` so the caller's existing PATH / host-tool
  ## resolution branch is unchanged.
  ##
  ## ``workspaceRoot`` MUST be absolute when ``overrides`` is ``some`` (see
  ## ``resolveOverrideAbsolutePath``). A resolution DIAGNOSTIC from the
  ## override resolver (override registered but its path is missing on disk)
  ## is surfaced by re-raising it — silent fallback to the lock pin is exactly
  ## the failure mode ``override_resolution.nim`` warns against (a remote
  ## worker would compute a divergent cache key).
  if selector.len == 0:
    return ProducerBinding(selector: selector, kind: pbkNotProducer)

  # 1. develop mode — the override map shadows the upstream/lock binding.
  let upstream = UpstreamPackageBinding(packageName: selector)
  let resolved = resolvePackageWithOverrides(upstream, overrides, workspaceRoot)
  if resolved.kind == orrkError:
    # The override matched by name but its local checkout is missing. Do NOT
    # silently fall through to the lock pin — re-raise the structured
    # diagnostic (Cross-Repo-Source-Consumption.md §4.1; the "no silent
    # fallback" property of ``override_resolution.nim``).
    raiseDiagnostic(resolved.diagnostic)
  if resolved.binding.kind == rpbkOverride:
    return ProducerBinding(
      selector: selector,
      kind: pbkDevelopOverride,
      localPathAbsolute: resolved.binding.localPathAbsolute,
      contentIdentity: resolved.binding.contentIdentity,
      overrideBinding: resolved.binding)

  # 2. lock-pinned mode — no override matched; consult the committed lock.
  for dep in lock.deps:
    if dep.name == selector:
      return ProducerBinding(
        selector: selector,
        kind: pbkLockPinned,
        lockedDep: dep)

  # 3. on-disk sibling — no override entry and no lock pin, but a checkout is
  #    present one level up (``../<selector>/repro.nim``). This is intentionally
  #    a discovery result, not a build-edge declaration: SC-8/SC-9 can import a
  #    typed schema from the sibling, while SC-2/SC-3 materialization still
  #    requires an explicit override or lock pin. Otherwise a no-producer-edge
  #    consumer would silently build and splice a sibling it did not declare.
  block onDiskSibling:
    let sibling = findSiblingProjectFile(selector, workspaceRoot)
    if sibling.len > 0:
      return ProducerBinding(
        selector: selector,
        kind: pbkOnDiskSibling,
        siblingProjectFile: sibling)

  # 4. Not a cross-repo producer — the caller keeps its existing branch.
  ProducerBinding(selector: selector, kind: pbkNotProducer)

proc resolveProducerBinding*(selector: string;
                             workspaceRoot: string): ProducerBinding =
  ## Workspace-rooted convenience: read the committed ``repro.lock`` and the
  ## ``.repro/develop-overrides.toml`` from ``workspaceRoot`` and delegate to
  ## the explicit overload. This is the shape the engine seam calls — it has
  ## only the workspace root at fork time. A missing lock file yields an empty
  ## ``LockedDependencies`` (no lock-pinned producers); a missing overrides
  ## file yields ``none`` (no develop overrides) — so a workspace that
  ## declares no cross-repo producers resolves every ref to ``pbkNotProducer``.
  let lockP = committedLockPath(workspaceRoot)
  let lock =
    if fileExists(extendedPath(lockP)):
      parseLockedDependencies(readFile(extendedPath(lockP)))
    else:
      LockedDependencies()
  var overrides =
    if workspaceRoot.len > 0:
      readDevelopOverridesFile(workspaceRoot)
    else:
      none(DevelopOverrides)
  if overrides.isNone and workspaceRoot.len > 0:
    var translated = newDevelopOverrides()
    var foundLegacyOverride = false
    for entry in readDevelopOverrides(
        developOverridesMetadataPath(workspaceRoot)):
      translated = translated.addOverride(
        repro_workspace_manifests.DevelopOverrideEntry(
          package: entry.node,
          local_path: entry.path,
          state: "editable",
          created_at: "1970-01-01T00:00:00Z",
          provenance: some("repro develop --into")))
      foundLegacyOverride = true
    if foundLegacyOverride:
      overrides = some(translated)
  resolveProducerBinding(selector, workspaceRoot, lock, overrides)

# ---------------------------------------------------------------------------
# Cross-Repo-Source-Consumption SC-8 — the producer's ``executable … cli:`` /
# ``library`` schema as a consumable TYPED CONTRACT keyed by workspace project
# name (export-by-default).
#
# Spec: ``Cross-Repo-Source-Consumption.md`` §9.1 (producer export contract),
# §1.3 (the two-layer split). Milestone
# ``Cross-Repo-Source-Consumption.milestones.org`` §SC-8.
#
# SC-8 establishes WHAT crosses the workspace boundary as a producer's typed
# contract. Layer 2 of the typed surface (§1.3) is the compile-time
# schema-import + accessor emission; SC-9 extends ``usesImportCode``
# (``macros_a.nim:2187-2316``) to IMPORT this contract and SC-10 proves the
# end-to-end typed call. SC-8 is the piece BENEATH that import: a producer's
# declared ``executable <name>: cli:`` command schema (command names, params,
# the ``providerEntrypointId`` — exactly what ``toolActionWrapperCode``,
# ``macros_a.nim:1973-2099``, turns into per-command typed wrapper procs) and
# its ``library`` blocks are EXPORT-BY-DEFAULT (no new DSL keyword — the
# producer ALREADY declares them) and become addressable, keyed by the
# workspace project NAME.
#
# The payload is projected straight out of the shipped
# ``ProjectInterface.publicExecutables`` / ``.publicLibraries``
# (``repro_interface_artifacts.nim:106-114``) the SC-2/SC-3 pre-pass already
# extracts via ``extractInterfaceFromModule`` — SC-8 reuses that projection
# verbatim, adding only the workspace-name-keyed DISCOVERY + the "does this
# producer export a typed contract at all" verdict. The schema-import mechanism
# (SC-9) is MODE-AGNOSTIC — it runs at consumer macro expansion regardless of
# how the producer artifact is later materialized — so SC-8's discovery locates
# the producer's SOURCE root (a develop override or an on-disk workspace
# sibling), NOT a built artifact.
# ---------------------------------------------------------------------------

type
  ProducerTypedContractKind* = enum
    ## The verdict of ``resolveProducerTypedContract``.
    ptckNoProducer
      ## The selector names no discoverable workspace producer (no develop
      ## override, no on-disk sibling project) — the caller keeps its existing
      ## resolution branch; typed consumption is not possible for this
      ## selector (SC-9 falls back to the bundled-stdlib list / local import).
    ptckNoContract
      ## A workspace producer WAS discovered, but it declares NEITHER an
      ## ``executable`` NOR a ``library`` — there is no typed contract to
      ## export. A consumer trying to bind ``producer.tool(...)`` against it
      ## must fail loudly at macro expansion (SC-9), not silently no-op.
    ptckContract
      ## The producer exports a consumable typed contract: its declared
      ## ``executable … cli:`` command schema and/or ``library`` blocks
      ## and/or ``resourceType`` resource contracts (RP5a).

  ProducerTypedContract* = object
    ## SC-8: a workspace producer's export-by-default typed contract, keyed by
    ## the workspace project ``selector``. This is the exact schema payload a
    ## typed consumer imports (SC-9) to emit ``producer.tool(args)`` accessors
    ## through the EXISTING ``toolActionWrapperCode`` machinery — no new schema
    ## shape is invented; the fields mirror ``ProjectInterface`` verbatim.
    selector*: string
      ## The workspace project name the contract is keyed by (the ``uses:``
      ## selector / the LHS of a ``producer.tool`` typed call).
    kind*: ProducerTypedContractKind
    projectName*: string
      ## The producer's declared ``package`` name (``ProjectInterface.projectName``).
    sourceRoot*: string
      ## The producer's discovered source root (a develop override checkout or
      ## an on-disk workspace sibling). Empty for ``ptckNoProducer``.
    projectFile*: string
      ## The resolved producer ``repro.nim`` / ``reprobuild.nim`` path — the
      ## module SC-9's ``usesImportCode`` extension imports the CLI schema from.
    publicExecutables*: seq[InterfaceExecutable]
      ## The exported ``executable … cli:`` schema (command names, params,
      ## ``providerEntrypointId``) — export-by-default, exactly the payload
      ## ``toolActionWrapperCode`` consumes to emit per-command typed wrappers.
    publicLibraries*: seq[InterfaceLibrary]
      ## The exported ``library`` blocks — export-by-default.
    publicResources*: seq[InterfaceResource]
      ## RP5a (the SC-9 analog for resource types): the exported
      ## ``resourceType`` contracts — each ``InterfaceResource``'s stable
      ## ``typeId``, determinism class, typed ``attr`` schema, and the
      ## observe/plan/apply entry-point ids. Export-by-default: a producer
      ## declaring a ``resourceType`` block exposes it here WITHOUT its
      ## driver/implementation closure crossing the boundary — the consumer
      ## imports the typed wrapper + contract only (compile-time, mode-
      ## agnostic; the driver-invocation-via-protocol is RP5b).
    interfaceFingerprint*: string
      ## TI3 (interface/provider fingerprint split): the hex
      ## ``InterfaceFingerprint`` of the producer's lifted ``ProjectInterface``
      ## (``interfaceFingerprint(ProjectInterface)`` — computed to EXCLUDE the
      ## producer's implementation bodies, per TI1's TI3-readiness property).
      ## The TI3 two-level accessor-cache freshness key (``usesImportCode``)
      ## uses this as its Level-2 discriminant: when the producer's cheap
      ## source stamp changed but this fingerprint did NOT, the edit was
      ## private-impl-only and the cached accessor is byte-identical — so it is
      ## reused in place (no downstream input change). Empty for
      ## ``ptckNoProducer`` (no interface could be lifted).

proc hasTypedContract*(contract: ProducerTypedContract): bool =
  ## True iff the producer exports at least one ``executable``, ``library``,
  ## or ``resourceType`` (RP5a) the consumer can bind a typed accessor against.
  contract.kind == ptckContract

proc typedContractCommands*(contract: ProducerTypedContract;
                            exportName: string): seq[string] =
  ## The command names a consumer may bind as ``producer.<exportName>.<cmd>``
  ## typed calls — the per-command payload ``toolActionWrapperCode`` turns into
  ## wrapper procs (``macros_a.nim:1973-2099``). Returns the empty seq when the
  ## producer declares no ``executable`` with that export name, so a mistyped
  ## command name / renamed ``cli:`` verb yields no binding (SC-8 deliverable:
  ## "a producer whose ``cli:`` command is renamed shifts the exported schema").
  for exe in contract.publicExecutables:
    if exe.exportName == exportName:
      for cmd in exe.commands:
        result.add(cmd.name)
      return

proc hasResourceContract*(contract: ProducerTypedContract): bool =
  ## RP5a: True iff the producer exports at least one ``resourceType``
  ## resource contract (regardless of whether it also exports an
  ## ``executable`` / ``library``).
  contract.publicResources.len > 0

proc typedContractResourceTypeIds*(contract: ProducerTypedContract):
    seq[string] =
  ## RP5a: the ``typeId``s of the resource contracts a consumer may bind a
  ## typed resource wrapper against (the SC-9 analog of
  ## ``typedContractCommands``, at the resource-type grain). A renamed /
  ## dropped resource type therefore no longer appears here, so a stale
  ## consumer bind fails to resolve.
  for res in contract.publicResources:
    result.add(res.typeId)

proc typedContractResource*(contract: ProducerTypedContract;
                            typeId: string): InterfaceResource =
  ## RP5a: the exported resource contract for ``typeId`` — the typed
  ## attribute schema + observe/plan/apply entry-point ids a consumer's
  ## typed resource wrapper is emitted from. Returns a resource with an
  ## empty ``typeId`` when the producer declares no resource type with that
  ## id, so a renamed / mistyped resource id yields no binding (the RP5a
  ## falsifiability end).
  for res in contract.publicResources:
    if res.typeId == typeId:
      return res
  InterfaceResource()

proc typedContractResourceAttrs*(contract: ProducerTypedContract;
                                 typeId: string): seq[string] =
  ## RP5a: the ordered attribute NAMES of the resource contract ``typeId``
  ## — the wrapper formals a consumer binds. Renaming an ``attr`` in the
  ## producer shifts this set (the RP5a falsifiability end).
  for res in contract.publicResources:
    if res.typeId == typeId:
      for attr in res.attributes:
        result.add(attr.name)
      return

proc discoverProducerSourceRoot*(selector: string;
                                 workspaceRoot: string): string =
  ## SC-8 workspace-name-keyed producer SOURCE discovery. Locate the producer's
  ## checkout keyed by the workspace project ``selector``:
  ##
  ##   1. a develop override (``resolveProducerBinding`` → ``pbkDevelopOverride``
  ##      → ``localPathAbsolute`` — the sibling checkout, §5.1), then
  ##   2. an on-disk workspace SIBLING (``findSiblingProjectFile`` — one level
  ##      up: ``../<selector>/repro.nim``, the same discovery
  ##      ``repro build <sibling>:<target>`` already drives, §7).
  ##
  ## Returns the producer's source root, or the empty string when the selector
  ## names no discoverable workspace producer. The schema import (SC-9) is
  ## compile-time + mode-agnostic, so a lock-pinned-only producer (no override,
  ## no on-disk sibling) is NOT discovered here for the typed-contract payload —
  ## the fetched-source materialization is SC-6's build-time concern, distinct
  ## from the compile-time schema export SC-8 pins down.
  if selector.len == 0 or workspaceRoot.len == 0:
    return ""
  # 1. develop override — the sibling checkout the override points at.
  let binding =
    try:
      resolveProducerBinding(selector, workspaceRoot)
    except CatchableError:
      # A registered override whose checkout is missing re-raises the structured
      # diagnostic in ``resolveProducerBinding``; for the pure discovery query we
      # treat a resolution failure as "not discoverable" and fall through to the
      # on-disk sibling probe rather than propagating.
      ProducerBinding(selector: selector, kind: pbkNotProducer)
  if binding.kind == pbkDevelopOverride and
      binding.localPathAbsolute.len > 0 and
      dirExists(extendedPath(binding.localPathAbsolute)):
    return binding.localPathAbsolute
  # 2. on-disk workspace sibling (``../<selector>/repro.nim``).
  let sibling = findSiblingProjectFile(selector, workspaceRoot)
  if sibling.len > 0:
    return parentDir(sibling)
  ""

proc resolveProducerTypedContract*(selector: string;
                                   workspaceRoot: string):
    ProducerTypedContract =
  ## SC-8: resolve a workspace producer's export-by-default typed contract,
  ## keyed by the workspace project ``selector``. Discovers the producer's
  ## source root (``discoverProducerSourceRoot``), extracts its shipped
  ## ``ProjectInterface`` (``extractInterfaceFromModule`` — the SAME extractor
  ## the SC-2/SC-3 splice pre-pass uses), and projects its
  ## ``publicExecutables`` / ``publicLibraries`` as the consumable typed
  ## contract. The producer's ``executable … cli:`` / ``library`` are
  ## export-by-default: a producer that declares one exposes a discoverable
  ## typed schema (``ptckContract``); a producer that declares NEITHER exposes
  ## none (``ptckNoContract``); a selector naming no workspace producer yields
  ## ``ptckNoProducer``.
  result = ProducerTypedContract(selector: selector, kind: ptckNoProducer)
  let sourceRoot = discoverProducerSourceRoot(selector, workspaceRoot)
  if sourceRoot.len == 0:
    return
  let sourceRootAbs = absolutePath(sourceRoot)
  let projectFile =
    try:
      resolveProjectFile(sourceRootAbs).path
    except CatchableError:
      ""
  if projectFile.len == 0:
    return
  result.sourceRoot = sourceRootAbs
  result.projectFile = projectFile
  # Extract the producer's ProjectInterface — the shipped extractor the SC-2/
  # SC-3 pre-pass already drives. The interface artifact + stub scratch land in
  # a workspace-local, selector-keyed dir under the consumer's ``.repro`` tree
  # (hermetic to the consumer; never $HOME).
  let scratchRoot =
    if workspaceRoot.len > 0:
      absolutePath(workspaceRoot) / ".repro" / "typed-contracts" / selector
    else:
      sourceRootAbs / ".repro" / "typed-contract"
  createDir(extendedPath(scratchRoot))
  let ifacePath = scratchRoot / "producer-typed-contract.rbsz"
  let stubPath = scratchRoot / "producer-typed-contract.nim"
  let artifact =
    try:
      # TI2: read the producer's interface via TI1's CACHED, content-addressed
      # interface-artifact edge (``interfaceLiftPlan`` + ``liftInterfaceArtifact``)
      # rather than re-extracting per consumer. The lift materializes ONCE into
      # the selector-keyed artifact path (its ``.liftkey`` sidecar records the
      # ``InterfaceLiftActionKey``); a second resolve with an unchanged producer
      # source closure is a cache HIT that reads the artifact back without
      # re-running the lift edge (replaces the RP5a re-extract-per-consumer path).
      # The stub is written to the scratch tree (the extract runner emits it) but
      # the typed-contract projection reads only the artifact.
      # TI2 (separate-module producer — the RP5c2 vm-harness shape): if the
      # producer's ``repro.nim`` NAMES a separate resource module via a
      # ``resourceModule "<path>": path "<dir>" …`` surface entry, thread that
      # module + its extra ``--path``s into the lift so the cached artifact's
      # ``publicResources`` genuinely reflect the separate module (its
      # ``resourceType`` blocks are NOT inline in ``repro.nim``). Without this the
      # cached lift would only see the separate module if ``repro.nim``
      # transitively imported it within the project root — which it must NOT (the
      # core build stays reprobuild-free). The declaration is parsed TEXTUALLY
      # from ``repro.nim`` (no import) and its paths are absolute (resolved
      # against the producer root by ``parseResourceModuleDecl``).
      let resDecl =
        parseResourceModuleDecl(readFile(projectFile), sourceRootAbs)
      let plan = interfaceLiftPlan(projectFile, ifacePath, stubPath,
        resourceModule = resDecl.resourceModule,
        extraPaths = resDecl.extraPaths,
        workDir = reprobuildLibraryWorkDir())
      liftInterfaceArtifact(plan)
    except CatchableError as ex:
      # The producer's interface could not be extracted. Keep the caller's
      # graceful behavior — surface as "no discoverable typed contract"
      # (``ptckNoProducer``) rather than a hard failure, so a malformed /
      # non-reprobuild sibling does not crash the consumer's macro expansion;
      # SC-9 then falls back to the bundled-stdlib / local import.
      #
      # But do NOT swallow it silently: a swallowed extraction failure that
      # silently yields ``ptckNoProducer`` is a footgun (RP5a review) — the
      # next debugger must SEE why a producer that plainly declares an
      # ``executable`` / ``library`` / ``resourceType`` resolved to "no
      # producer". Emit a diagnostic naming the selector, the project file, and
      # the underlying error so the failure is visible without changing the
      # graceful outcome. ``resolveProducerTypedContract`` is called both at
      # runtime (CLI) AND at consumer compile time (the RP5a ``uses:`` macro
      # path runs it in the Nim VM, where ``stderr`` is unavailable) — so route
      # the diagnostic through ``echo`` under ``nimvm`` and ``stderr`` at
      # runtime. Either way the failure is no longer swallowed silently.
      let diag = "repro: interface extraction for producer '" &
        selector & "' (" & projectFile & ") failed; treating as no " &
        "discoverable typed contract: " & ex.msg
      when nimvm:
        echo diag
      else:
        stderr.writeLine(diag)
      return
  result.projectName = artifact.projectInterface.projectName
  # TI3: carry the producer's InterfaceFingerprint (impl-EXCLUDING — TI1) so the
  # consumer's two-level accessor-cache freshness key can distinguish a private-
  # impl edit (fingerprint unchanged → reuse cached accessor in place) from a
  # public-signature edit (fingerprint changed → regenerate). This is the
  # fingerprint recorded on TI1's cached interface-lift artifact, so obtaining it
  # here is the SAME cached lift edge (no second extraction).
  result.interfaceFingerprint = digestHex(artifact.interfaceFingerprint)
  result.publicExecutables = artifact.projectInterface.publicExecutables
  result.publicLibraries = artifact.projectInterface.publicLibraries
  # RP5a (the SC-9 analog for resource types): project the producer's
  # ``resourceType`` contracts off the SAME shipped ``ProjectInterface`` the
  # extractor lifts (``publicResources`` — RP4's ``InterfaceResource``),
  # verbatim, alongside the executables/libraries. Only the resource CONTRACT
  # crosses (typeId + determinism + typed attr schema + observe/plan/apply
  # entry-point ids); the producer's driver/implementation is NOT in the
  # interface artifact, so it does not enter the consumer (RP5a: no closure).
  result.publicResources = artifact.projectInterface.publicResources
  # Export-by-default verdict: a producer declaring an ``executable``, a
  # ``library``, and/or a ``resourceType`` exposes a typed contract; one
  # declaring NONE of them exposes none.
  if result.publicExecutables.len > 0 or result.publicLibraries.len > 0 or
      result.publicResources.len > 0:
    result.kind = ptckContract
  else:
    result.kind = ptckNoContract

# ---------------------------------------------------------------------------
# RP5a — the resource-contract consumer-import ACCESSOR EMITTER (the SC-9
# accessor-emission analog for resource types).
#
# For ``executable``/``library`` contracts, SC-9's ``usesImportCode`` widens
# consumption by IMPORTING the producer's ``repro.nim`` module wholesale — cheap
# because a ``toolActionWrapperCode`` producer module carries only pure wrapper
# procs. A ``resourceType`` producer module is different: its expansion emits a
# module-init ``registerResourceProvider(... driver: <driver>)`` that references
# the producer's DRIVER, and module-init side effects are NOT dead-code
# eliminated — so importing it whole would drag the producer's driver /
# implementation closure into the consumer, exactly what the RP5a gate forbids.
#
# Instead RP5a emits the consumer's typed resource surface FROM THE EXTRACTED
# ``InterfaceResource`` SCHEMA (``resolveProducerTypedContract`` above) — the
# contract-only projection, which by construction contains no driver. The
# emitted source is a driver-free typed wrapper (an attrs record synthesised
# from the exported ``attr`` schema + a wrapper proc lowering to
# ``resource(typeId, ...)``) plus the ``typeId`` / entry-point-id constants a
# consumer binds against. It compiles into a consumer that links
# ``repro_resources`` but NOT the producer's driver, so the resource CONTRACT
# crosses at compile time while the IMPLEMENTATION stays behind (the driver
# invocation is reconnected over the protocol in RP5b).
# ---------------------------------------------------------------------------

proc resourceAttrsTypeName*(typeId: string): string =
  ## The synthesised consumer-side attrs record name for a resource
  ## ``typeId`` — a filesystem/identifier-safe rendering (dots/dashes → ``_``)
  ## suffixed ``Attrs``. Deterministic: two consumers of the same producer
  ## resource type synthesise the same name.
  var ident = ""
  for ch in typeId:
    if ch.isAlphaNumeric: ident.add(ch)
    else: ident.add('_')
  # Title-case the leading char so the record type reads as a type.
  if ident.len > 0 and ident[0] in {'a'..'z'}:
    ident[0] = char(ord(ident[0]) - 32)
  ident & "Attrs"

proc resourceWrapperProcName*(typeId: string): string =
  ## The synthesised consumer-side typed wrapper proc name — the LAST dotted
  ## segment of the ``typeId`` (e.g. ``vm_harness.container`` → ``container``),
  ## dash-sanitised. This is the ``producer.<wrapper>(address, attrs…)`` verb a
  ## consumer binds. Derived from the ``typeId`` (part of the exported
  ## contract) so it stays stable across the interface boundary without adding
  ## a wrapper-name field to the codec.
  let segs = typeId.split('.')
  var last = if segs.len > 0: segs[^1] else: typeId
  var ident = ""
  for ch in last:
    if ch.isAlphaNumeric: ident.add(ch)
    else: ident.add('_')
  if ident.len == 0: ident = "resource"
  ident

proc emitResourceContractAccessors*(contract: ProducerTypedContract): string =
  ## RP5a: emit the driver-free Nim source that imports a producer's resource
  ## CONTRACTS into a consumer as a typed surface. For each exported
  ## ``InterfaceResource`` it emits:
  ##
  ##   * ``type <TypeId>Attrs = object`` with one field per exported ``attr``
  ##     (name + nimType) — the consumer-side typed attribute record;
  ##   * ``proc <wrapper>(address; <attr>: <type>…; dependsOn): ResourceRef``
  ##     lowering to ``resource(<typeId>, address, <Attrs>(…), dependsOn)`` —
  ##     the same low-level surface the producer's own wrapper lowers to, but
  ##     synthesised from the schema (no driver reference);
  ##   * ``const <wrapper>TypeId* = "<typeId>"`` and the observe/plan/apply
  ##     entry-point-id consts — the contract metadata a consumer / RP5b binds.
  ##
  ## The producer's driver body is never referenced, so linking this source
  ## does not pull the producer's implementation closure. The emitted module
  ## needs ``repro_resources`` (for ``resource`` / ``ResourceRef``) in scope.
  result = ""
  for res in contract.publicResources:
    if res.typeId.len == 0:
      continue
    let attrsType = resourceAttrsTypeName(res.typeId)
    let wrapper = resourceWrapperProcName(res.typeId)
    # attrs record. An object with no fields is written with no body (Nim
    # rejects a ``discard`` body on a type section), so emit the field lines
    # only when the resource declares ``attr``s.
    result.add("type\n  " & attrsType & "* = object\n")
    for attr in res.attributes:
      result.add("    " & attr.name & "*: " & attr.nimType & "\n")
    # typed wrapper proc
    var formals = @["address: string"]
    for attr in res.attributes:
      formals.add(attr.name & ": " & attr.nimType)
    formals.add("dependsOn: seq[string] = @[]")
    result.add("proc " & wrapper & "*(" & formals.join("; ") &
      "): ResourceRef =\n")
    var ctorFields: seq[string] = @[]
    for attr in res.attributes:
      ctorFields.add(attr.name & ": " & attr.name)
    let ctor = attrsType & "(" & ctorFields.join(", ") & ")"
    result.add("  resource(" & escape(res.typeId) & ", address, " &
      ctor & ", dependsOn)\n")
    # contract metadata
    result.add("const " & wrapper & "TypeId* = " & escape(res.typeId) & "\n")
    result.add("const " & wrapper & "ObserveEntrypoint* = " &
      escape(res.entrypoints.observe) & "\n")
    result.add("const " & wrapper & "PlanEntrypoint* = " &
      escape(res.entrypoints.plan) & "\n")
    result.add("const " & wrapper & "ApplyEntrypoint* = " &
      escape(res.entrypoints.apply) & "\n")

# ---------------------------------------------------------------------------
# RP8 (LSP mode) — interface-extraction-backed editor CAPABILITIES: cross-
# project TYPECHECK and GO-TO-DEFINITION over a consumer ``repro.nim`` that
# ``uses:`` a producer declaring resource/executable types.
#
# The whole point of the Provider-Runtime-Protocol interface-extraction stack
# is that a consumer resolves a producer's PUBLIC symbols WITHOUT compiling the
# producer's driver/implementation closure. RP8 exposes that same extraction as
# the two capabilities an editor language-server needs:
#
#   * TYPECHECK — resolve the producer's public symbols against the driver-free
#     accessor splice. This is already demonstrable through TI2's accessor
#     path: a ``nim check`` over a consumer resolves ``container(...)`` via the
#     cached accessor (``nim check`` cannot run ``staticExec``, so a green check
#     PROVES the exec-free interface path, not a full producer compile). RP8's
#     ``typecheckConsumerAgainstInterface`` formalises that flow behind one proc
#     and makes the "no impl compile" property assertable.
#   * GO-TO-DEFINITION — given a public symbol reference from a ``uses:``-
#     imported producer (a resource-type wrapper such as ``container``, a
#     resource attribute such as ``cpus``, or a public executable/command),
#     return the DEFINITION source location (producer file + line) read from the
#     interface artifact's preserved ``SourceLocation`` — WITHOUT compiling the
#     producer's driver/impl closure. Private helpers and unknown symbols do NOT
#     resolve (the interface only carries the public surface), so a "go to
#     definition" on a private name reports not-found rather than leaking an
#     implementation location.
#
# Both capabilities reuse ``resolveProducerTypedContract`` verbatim — the SAME
# TI1 cached interface-lift edge the RP5a/TI2/TI3 consumer paths drive — so no
# new extraction machinery is introduced. This is a focused, tested capability
# (typecheck-without-impl + a go-to-definition resolver), NOT a socket LSP
# server process; the RP8 gate is satisfied by the capability being real and
# backed by interface extraction.
# ---------------------------------------------------------------------------

type
  GotoDefSymbolKind* = enum
    ## RP8: the kind of producer public symbol a go-to-definition query
    ## resolved to. ``gdskNotFound`` is the rejection outcome for a private
    ## helper / unknown name (the interface exposes only the public surface).
    gdskNotFound
    gdskResourceType      ## a ``resourceType`` wrapper (e.g. ``container``)
    gdskResourceAttr      ## a resource ``attr`` (e.g. ``cpus``)
    gdskExecutable        ## a public ``executable`` export
    gdskCommand           ## a public executable ``cli:`` command

  GotoDefResult* = object
    ## RP8: the outcome of a go-to-definition query. ``kind`` is
    ## ``gdskNotFound`` when the symbol is not a resolvable producer public
    ## symbol (a private helper, a mistyped name, or a producer with no typed
    ## contract) — in that case ``location`` is an empty sentinel. Otherwise
    ## ``location`` is the producer's PUBLIC-decl source location (file + line),
    ## read from the interface artifact WITHOUT compiling the producer driver.
    kind*: GotoDefSymbolKind
    typeId*: string
      ## For a resource-type / attr hit: the resolved resource ``typeId``.
    symbol*: string
      ## The queried symbol name, echoed back for the caller's diagnostics.
    location*: SourceLocation

proc gotoDefinitionInProducerContract*(contract: ProducerTypedContract;
                                       symbol: string): GotoDefResult =
  ## RP8 go-to-definition over an ALREADY-RESOLVED producer typed contract.
  ## Given a public ``symbol`` reference — a resource-type wrapper name (the
  ## last dotted ``typeId`` segment, e.g. ``container`` for
  ## ``vm_harness.container``) or the full ``typeId`` itself; a resource
  ## attribute name (e.g. ``cpus``); or a public executable / command name —
  ## return the producer's DEFINITION ``SourceLocation`` (file + line) read from
  ## the interface artifact's preserved location. The producer's driver/impl is
  ## NOT compiled: ``contract`` was lifted via the TI1 cached interface edge
  ## (``resolveProducerTypedContract``), which carries no driver.
  ##
  ## Resolution precedence keeps a resource-type wrapper name (``container``)
  ## resolving to the ``resourceType`` decl even if an attribute shares the
  ## name: resource types, then attributes, then executables/commands. An
  ## unknown or PRIVATE name (a driver helper that never crossed the interface)
  ## resolves to ``gdskNotFound`` — the interface only exposes the public
  ## surface, so a private symbol has no location to report.
  result = GotoDefResult(kind: gdskNotFound, symbol: symbol)
  if symbol.len == 0:
    return
  # (1) resource-type wrapper — match on the full typeId OR on the synthesised
  #     wrapper proc name (the last dotted segment). This is the ``container``
  #     the consumer binds; its definition is the ``resourceType`` block.
  for res in contract.publicResources:
    if res.typeId == symbol or resourceWrapperProcName(res.typeId) == symbol:
      return GotoDefResult(kind: gdskResourceType, typeId: res.typeId,
        symbol: symbol, location: res.location)
  # (2) resource attribute — an ``attr <name>: <type>`` line inside a
  #     ``resourceType`` block. Return the attribute's own location.
  for res in contract.publicResources:
    for attr in res.attributes:
      if attr.name == symbol:
        return GotoDefResult(kind: gdskResourceAttr, typeId: res.typeId,
          symbol: symbol, location: attr.location)
  # (3) public executable / command (easy wins on the same interface).
  for exe in contract.publicExecutables:
    if exe.exportName == symbol or exe.binaryName == symbol:
      return GotoDefResult(kind: gdskExecutable, symbol: symbol,
        location: exe.location)
    for cmd in exe.commands:
      if cmd.name == symbol:
        return GotoDefResult(kind: gdskCommand, symbol: symbol,
          location: cmd.location)
  # No public symbol matched — a private helper / unknown name. Stays
  # ``gdskNotFound`` (the interface never carried a location for it).

proc gotoDefinitionForProducerSymbol*(selector, workspaceRoot,
                                      symbol: string): GotoDefResult =
  ## RP8 go-to-definition end-to-end: resolve the producer ``selector``'s typed
  ## contract (``resolveProducerTypedContract`` — the TI1 cached interface-lift
  ## edge, NO driver/impl compile) and locate ``symbol``'s public declaration in
  ## it (``gotoDefinitionInProducerContract``). Returns ``gdskNotFound`` when the
  ## selector names no discoverable producer, the producer exports no typed
  ## contract, or the symbol is private/unknown.
  let contract = resolveProducerTypedContract(selector, workspaceRoot)
  if contract.kind != ptckContract:
    return GotoDefResult(kind: gdskNotFound, symbol: symbol)
  gotoDefinitionInProducerContract(contract, symbol)

type
  InterfaceTypecheckResult* = object
    ## RP8: the outcome of a ``nim check`` typecheck of a consumer ``repro.nim``
    ## against a producer's interface-extraction accessor — WITHOUT compiling
    ## the producer's driver/impl closure. ``ok`` is the check verdict;
    ## ``output`` is the compiler's diagnostic text (surfaced on failure).
    ok*: bool
    output*: string

proc typecheckConsumerAgainstInterface*(consumerProjectFile: string;
                                        repoRoot: string;
                                        nimcache: string;
                                        nimExe = ""): InterfaceTypecheckResult =
  ## RP8 TYPECHECK capability. Run ``nim check`` over a consumer ``repro.nim``
  ## that ``uses:`` a producer. ``nim check`` DOES NOT run ``staticExec``, so
  ## the cold RP5a-style per-consumer accessor generator is unavailable — a
  ## consumer that type-checks here resolved the producer's public symbols
  ## THROUGH the driver-free interface accessor (TI2's exec-free VM ``readFile``
  ## of the cached accessor splice), NOT through a full producer compile. This
  ## is exactly the property an editor typecheck needs: cross-project public
  ## symbols resolve from interface extraction, the producer's implementation is
  ## never compiled into the consumer.
  ##
  ## ``nimcache`` MUST be a private, caller-owned cache dir (RP8 runs each check
  ## in its own nimcache). ``repoRoot`` is the reprobuild checkout whose
  ## ``config.nims`` wires the ``--path`` set. Returns the check verdict + the
  ## compiler diagnostics; a failing check (e.g. a reference to a non-existent
  ## public symbol) reports ``ok = false`` with the compiler's error text.
  let nim = if nimExe.len > 0: nimExe else: findExe("nim")
  doAssert nim.len > 0, "nim compiler not on PATH"
  createDir(extendedPath(nimcache))
  let cmd =
    nim & " check --hints:off --warnings:off" &
    " --nimcache:" & quoteShell(nimcache) &
    " " & quoteShell(consumerProjectFile)
  let (output, code) =
    execCmdEx("cd " & quoteShell(repoRoot) & " && " & cmd)
  InterfaceTypecheckResult(ok: code == 0, output: output)

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-9 — the unified locked-dependency populator.
#
# ONE entry point — ``populateLockedDeps(source)`` — fills the MO-8
# ``LockedDependencies`` model from ANY supported source (committed lock file,
# a manifest repo's per-repo SHA lock, or an external DB-backed store). A
# workspace may MIX sources per repo-set (MO-4 routing); every source feeds the
# SAME object. The lock-handling algorithms (sync / gate / check / pull /
# build) then consume ``LockedDependencies`` regardless of which source supplied
# a given repo's locked entry: the gate verifies observed content against the
# locked INTEGRITY, sync fetches to the locked COORDINATES.
#
# The discriminator + the populator's signature are declared here so the
# committed-lock-derived resolver below can route through the SAME seam; the
# bodies (which need the LockStore backends + the per-repo backend router) are
# defined once those are in scope.
# ---------------------------------------------------------------------------

type
  LockSourceKind* = enum
    ## The supported provenances a unified ``LockedDependencies`` is populated
    ## from (Workspace-Manifests.md §"Populating the locked-dependency model").
    lskCommittedLock = "committed-lock"
      ## the committed ``repro.lock`` (schema v2) — populated from the lock's
      ## CONTENT (coordinates + integrity), never from live ``git HEAD``.
    lskManifestRepo = "manifest-repo"
      ## a manifest repo: the resolved project membership PLUS the
      ## manifest-repo per-repo SHA lock (a ``git-checkout`` ``LockStore``).
    lskExternalStore = "external-store"
      ## an external DB-backed ``LockStore`` (the MO-3 external-CLI /
      ## committed-file / any non-manifest backend).

  LockSource* = object
    ## A single source feeding ``populateLockedDeps``. ``workspaceRoot`` anchors
    ## the on-disk reads. The committed-lock kind needs only the root; the
    ## manifest / external kinds carry the repo-set this source covers plus the
    ## backend ``LockStore`` that holds their locked revisions, so a MIXED
    ## workspace routes different repo-sets (MO-4) to different sources, all
    ## feeding ONE object.
    kind*: LockSourceKind
    workspaceRoot*: string
    projectName*: string
    repos*: seq[ResolvedRepo]
    store*: LockStore

  LockedIntegrityCause* = enum
    ## WHY a locked entry failed verification. "the content changed" and "the
    ## revision is gone" are different failures with different repairs, and a
    ## refusal that conflates them sends the operator looking for a tamper that
    ## never happened. The gate renders the remedy prose from this, and emits it
    ## as a ``cause=`` token in the failure's evidence so a consumer can branch
    ## on it without parsing English.
    ##
    ## ``licContentMismatch`` is first so a default-constructed failure claims
    ## only the weaker, always-true thing ("what we obtained is not what was
    ## locked") rather than asserting an unreachable revision.
    licContentMismatch      ## obtained content ≠ recorded integrity
    licRevisionUnreachable  ## the locked revision's object is absent/unreachable
    licNoRevisionPinned     ## a VCS-native integrity with no revision to verify at

  LockedIntegrityFailure* = object
    ## One dependency whose obtained content did not match its locked integrity.
    name*: string
    path*: string
    expected*: string   ## the locked integrity multihash
    observed*: string   ## recomputed from the content at the locked coordinates
    revision*: string   ## the locked VCS revision, when the entry pins one
    cause*: LockedIntegrityCause
    diagnostic*: string

proc populateLockedDeps*(source: LockSource): LockedDependencies
proc verifyLockedIntegrityAtCoordinates*(workspaceRoot: string;
    ld: LockedDependencies): seq[LockedIntegrityFailure]

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-2 — committed-lock-derived workspace
# resolution.
#
# When a workspace has NO ``.repo/manifests`` resolved checkout and NO
# compositional ``.repo/workspace.toml``, but DOES carry the committed
# ``repro.lock`` (the MO-1 solved-graph lock), the participating repo set +
# locked revisions are derived from REPO-LOCAL STATE instead of requiring a
# manifest repo. This is the fallback that makes ``sync`` / ``pull`` /
# ``check`` / the pre-push gate OPERATE on an all-public, single-repo
# workspace with no manifest repo, rather than raising "no manifest".
#
# Honest boundary: MO-1's ``repro.lock`` pins the SOLVED PACKAGE GRAPH
# (versions / options / source identities), NOT per-repo workspace SHAs. So
# the locked revision here comes from the repo's own ``HEAD`` (repo-local
# state), and the participating set is the workspace repo ITSELF. Develop-
# mode siblings are not yet folded into this committed-lock-derived set —
# that participation model lands with a later milestone; until then the set
# is exactly the one repo, which is the all-public single-repo workspace the
# milestone targets.
# ---------------------------------------------------------------------------

proc committedLockRepoFacts(repoRoot: string):
    tuple[headSha, branch, originUrl: string] =
  ## Read the repo-local facts the committed-lock-derived model needs: the
  ## current ``HEAD`` SHA, the checked-out branch (empty when detached), and
  ## the canonical fetch URL (empty when the repo has NO remote at all).
  ## Best-effort: a missing ``git`` or a non-git directory yields empty fields
  ## (sync's plan and the gate's own per-repo probes still work without them).
  ##
  ## The fetch URL is resolved ROBUSTLY rather than hard-coded to ``origin``:
  ## workspace repos do not universally name their canonical remote ``origin``
  ## (a fork-based flow names it after the upstream org — e.g. the metacraft
  ## workspace's ``metacraft-labs`` remote). Populating an EMPTY url here is
  ## not harmless: it becomes the ``ckVcs`` coordinate url in the committed
  ## lock, and ``fetchLockPinnedProducer`` then REFUSES to fetch a pinned
  ## sibling with an incomplete coordinate — so a lock-only / lock-driven-CI
  ## build cannot materialize the pinned source. The resolution order is:
  ##   1. ``origin`` — preserves the historical behaviour where it exists;
  ##   2. ``upstream`` — git's conventional name for the canonical upstream of
  ##      a fork, so a fork checkout still records its true upstream URL;
  ##   3. the FIRST remote (remotes are listed alphabetically by ``git``) — the
  ##      general fallback that gives ANY repo with at least one remote a
  ##      non-empty url.
  ## No remotes at all → empty (unchanged graceful degradation).
  if not (dirExists(extendedPath(repoRoot / ".git")) or
      fileExists(extendedPath(repoRoot / ".git"))):
    return ("", "", "")
  let gitBin = findExe("git")
  if gitBin.len == 0:
    return ("", "", "")
  proc run(extra: openArray[string]): string =
    var cmd = quoteShell(gitBin)
    for a in extra:
      cmd.add(" ")
      cmd.add(quoteShell(a))
    let r = execCmdEx(cmd, options = {poUsePath},
      env = scrubbedGitRepositoryEnv())
    if r.exitCode == 0: r.output.strip() else: ""
  proc remoteUrl(name: string): string =
    if name.len == 0: "" else: run(["-C", repoRoot, "remote", "get-url", name])
  proc resolveFetchUrl(): string =
    let origin = remoteUrl("origin")
    if origin.len > 0:
      return origin
    # Enumerate remotes and pick the canonical upstream, else the first.
    let listed = run(["-C", repoRoot, "remote"])
    if listed.len == 0:
      return ""
    var remotes: seq[string] = @[]
    for line in listed.splitLines():
      let name = line.strip()
      if name.len > 0:
        remotes.add(name)
    if remotes.len == 0:
      return ""
    if "upstream" in remotes:
      let u = remoteUrl("upstream")
      if u.len > 0:
        return u
    remoteUrl(remotes[0])
  result.headSha = run(["-C", repoRoot, "rev-parse", "HEAD"])
  result.branch = run(["-C", repoRoot, "symbolic-ref", "--short", "-q", "HEAD"])
  result.originUrl = resolveFetchUrl()

const nestedDevelopDirs* = ["deps", "vendor", "third-party", "develop"]
  ## Workspace-Manifest-Optional MO-7 — the conventional project-local
  ## subdirectories that may hold NESTED develop-mode dependency checkouts
  ## (Workspace-And-Develop-Mode.md §"Checkout Topologies" → "Nested
  ## topology": ``./deps/<dep>``, ``./vendor/<dep>``, ``./third-party/<dep>``,
  ## ``./develop/<dep>``). A single project repo with its develop-mode deps
  ## nested under it — and a committed solved-graph lock — is a complete,
  ## manifest-free workspace; the org-root / star layout is OPTIONAL, not
  ## required. The list is searched in declaration order and the discovered
  ## set is path-sorted, so the derived participating set is deterministic
  ## regardless of filesystem iteration order.

proc discoverNestedDevelopDeps(workspaceRoot: string): seq[ResolvedRepo] =
  ## MO-7 — discover NESTED develop-mode dependency checkouts under
  ## ``workspaceRoot`` and return them as participating ``ResolvedRepo``s.
  ##
  ## A nested dep is an immediate subdirectory of one of the conventional
  ## ``nestedDevelopDirs`` that is BOTH a git checkout (carries ``.git``) AND
  ## a reprobuild project (carries ``repro.nim`` / ``reprobuild.nim``). Those
  ## two discriminators together mean the directory is a co-developed
  ## reprobuild package — not an arbitrary vendored source tree — so folding
  ## it into the workspace's participating set (where ``sync`` plans it and
  ## the pre-push gate enforces its cleanliness/publication) is sound. The
  ## ``path`` is workspace-relative (e.g. ``deps/<dep>``), the ``revision`` is
  ## the nested repo's own ``HEAD``, and the ``fetchUrl`` is its ``origin``.
  ##
  ## Result is sorted by ``path`` so the participating set is DETERMINISTIC.
  result = @[]
  let root = absolutePath(workspaceRoot)
  for sub in nestedDevelopDirs:
    let containerAbs = root / sub
    if not dirExists(extendedPath(containerAbs)):
      continue
    for kind, entry in walkDir(containerAbs):
      if kind notin {pcDir, pcLinkToDir}:
        continue
      if not dirExists(extendedPath(entry / ".git")) and
          not fileExists(extendedPath(entry / ".git")):
        # Not a git checkout — a develop-mode participant must be a repo the
        # gate can probe for cleanliness/publication. (A ``.git`` FILE is a
        # worktree/submodule gitlink; accept it too.)
        continue
      var recipePath = ""
      try:
        recipePath = resolveProjectFile(entry).path
      except CatchableError:
        # Ambiguous (both repro.nim + reprobuild.nim) — not a discoverable
        # single-recipe dep here; skip rather than guess.
        continue
      if recipePath.len == 0:
        continue
      let depName = extractFilename(entry.strip(
        leading = false, trailing = true, chars = {'/', '\\'}))
      if depName.len == 0:
        continue
      let facts = committedLockRepoFacts(entry)
      let revision =
        if facts.headSha.len > 0: facts.headSha
        elif facts.branch.len > 0: facts.branch
        else: "HEAD"
      result.add(ResolvedRepo(
        name: depName,
        path: sub & "/" & depName,
        projectRemote: "origin",
        fetchUrl: facts.originUrl,
        revision: revision,
        vcs: defaultRepoVcs,
        stability: defaultRepoStability,
        visibility: wvPublic))
  result.sort(proc(a, b: ResolvedRepo): int = cmp(a.path, b.path))

proc discoverSiblingDevelopDeps(workspaceRoot: string): seq[ResolvedRepo] =
  ## MO-12 — discover SIBLING develop-mode dependency checkouts (the RA-22
  ## develop-override set, one level up from the workspace) recorded in
  ## ``<workspaceRoot>/.repro/develop-overrides.toml`` and return them as
  ## participating ``ResolvedRepo``s, mirroring ``discoverNestedDevelopDeps``
  ## for the nested case so the committed-lock-derived workspace folds sibling
  ## deps into BOTH its participating set and (via ``lockedDepsForWorkspace``)
  ## the committed lock's ``deps``.
  ##
  ## Each override's ``local_path`` (e.g. ``../sibling``) is resolved relative
  ## to the workspace root and folded in ONLY when that location is BOTH a git
  ## checkout AND a reprobuild project — the same two discriminators the nested
  ## scan uses — so an override pointing at a non-checked-out / non-reprobuild
  ## path is skipped rather than enforced. ``path`` is the workspace-relative
  ## location (``../sibling``), ``revision`` the sibling's own ``HEAD``,
  ## ``fetchUrl`` its ``origin``. Sorted by ``path`` for a deterministic set.
  result = @[]
  let root = absolutePath(workspaceRoot)
  let overridesOpt =
    try: readDevelopOverridesFile(root)
    except CatchableError: return result
  if overridesOpt.isNone:
    return result
  var seenPaths: seq[string] = @[]
  for entry in listOverrides(overridesOpt.get()):
    if entry.package.len == 0 or entry.local_path.len == 0:
      continue
    let depAbs =
      if entry.local_path.isAbsolute: os.normalizedPath(entry.local_path)
      else: os.normalizedPath(root / entry.local_path)
    if depAbs in seenPaths: continue
    seenPaths.add(depAbs)
    if not dirExists(extendedPath(depAbs)):
      continue
    if not dirExists(extendedPath(depAbs / ".git")) and
        not fileExists(extendedPath(depAbs / ".git")):
      # A develop-mode participant must be a repo the gate can probe for
      # cleanliness/publication (a ``.git`` FILE is a worktree/submodule
      # gitlink; accept it too).
      continue
    var recipePath = ""
    try:
      recipePath = resolveProjectFile(depAbs).path
    except CatchableError:
      continue
    if recipePath.len == 0:
      continue
    let facts = committedLockRepoFacts(depAbs)
    let revision =
      if facts.headSha.len > 0: facts.headSha
      elif facts.branch.len > 0: facts.branch
      else: "HEAD"
    let relPath = relativePath(depAbs, root).replace('\\', '/')
    result.add(ResolvedRepo(
      name: entry.package,
      path: relPath,
      projectRemote: "origin",
      fetchUrl: facts.originUrl,
      revision: revision,
      vcs: defaultRepoVcs,
      stability: defaultRepoStability,
      visibility: wvPublic))
  result.sort(proc(a, b: ResolvedRepo): int = cmp(a.path, b.path))

proc discoverDevelopDeps(workspaceRoot: string): seq[ResolvedRepo] =
  ## MO-7/MO-12 — the full on-disk develop-mode participating set folded into a
  ## committed-lock-only workspace: NESTED deps under ``deps/vendor/…`` (MO-7)
  ## PLUS SIBLING deps from the RA-22 develop-override set one level up
  ## (MO-12), deduped by workspace-relative ``path`` and path-sorted for a
  ## deterministic set. When neither is present the result is empty and the
  ## derived set is exactly the one workspace repo (MO-2 behaviour).
  result = discoverNestedDevelopDeps(workspaceRoot)
  var seen: seq[string] = @[]
  for r in result:
    seen.add(r.path)
  for s in discoverSiblingDevelopDeps(workspaceRoot):
    if s.path in seen: continue
    seen.add(s.path)
    result.add(s)
  result.sort(proc(a, b: ResolvedRepo): int = cmp(a.path, b.path))

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-8 — self-describing integrity computation.
# ---------------------------------------------------------------------------

proc gitObjectFormatOf(repoRoot: string): string =
  ## The git object format (``sha1`` / ``sha256``) of a checkout, used to tag
  ## the VCS-native integrity multihash. Defaults to ``sha1`` when unknown.
  let gitBin = findExe("git")
  if gitBin.len == 0: return "sha1"
  let r = execCmdEx(quoteShell(gitBin) & " -C " & quoteShell(repoRoot) &
    " rev-parse --show-object-format", options = {poUsePath},
    env = scrubbedGitRepositoryEnv())
  if r.exitCode == 0 and r.output.strip().len > 0: r.output.strip()
  else: "sha1"

proc collectTreeEntries(dirAbs: string): seq[tuple[path, content: string]] =
  ## Gather (workspace-relative path, file content) for every regular file
  ## under ``dirAbs``, EXCLUDING VCS metadata (``.git``), the CLI's own
  ## ``.repro`` work tree, and the committed lock itself (Reprobuild output,
  ## never part of a source's content identity). Feeds the NAR-style
  ## own-file-hash for a source the VCS does not content-address.
  result = @[]
  for path in walkDirRec(dirAbs, yieldFilter = {pcFile}):
    let rel = relativePath(path, dirAbs).replace('\\', '/')
    if rel == ".git" or rel.startsWith(".git/") or
        rel == ".repro" or rel.startsWith(".repro/") or
        rel == CommittedLockFileName:
      continue
    var content = ""
    try: content = readFile(extendedPath(path))
    except CatchableError: content = ""
    result.add((path: rel, content: content))

proc computeDepIntegrity*(repoAbsPath, headSha: string): string =
  ## The self-describing integrity multihash for a locked dependency:
  ##   * a git checkout with a resolved HEAD commit -> the VCS-native object
  ##     id (``git-sha1:`` / ``git-sha256:``); the commit IS the integrity, so
  ##     no recomputation over files is needed.
  ##   * otherwise -> Reprobuild's OWN deterministic NAR-style tree hash over
  ##     the checked-out files (``blake3:``), which genuinely hashes the file
  ##     contents (changing any file changes the digest).
  if headSha.len > 0:
    return gitObjectMultihash(gitObjectFormatOf(repoAbsPath), headSha)
  narStyleTreeMultihash(collectTreeEntries(repoAbsPath))

proc usesProducerLockedDep(selector, root: string;
                           existingDeps: seq[LockedDep]): Option[LockedDep] =
  ## FUP-M — resolve a recipe ``uses:`` producer SELECTOR to a locked sibling
  ## dependency so ``repro lock refresh`` carries the declared cross-repo
  ## producer edge in the committed lock (the bug: refresh previously dropped
  ## every ``uses:`` sibling, writing a self-only ``deps`` that would not
  ## resolve on a lock-only checkout).
  ##
  ## A selector whose checkout is DISCOVERABLE on disk (a develop-override
  ## checkout OR an on-disk workspace sibling — ``discoverProducerSourceRoot``)
  ## is RE-PINNED from its live git facts. A selector present only in the
  ## EXISTING committed lock (its checkout not present here) carries that pin
  ## forward unchanged, preserving pinned revisions during a refresh. A selector
  ## that names NO workspace producer — a plain toolchain/host ``uses:`` such as
  ## ``nim`` / ``gcc`` — yields ``none`` and is not locked.
  if selector.len == 0: return none(LockedDep)
  let srcRoot =
    try: discoverProducerSourceRoot(selector, root)
    except CatchableError: ""
  if srcRoot.len > 0 and dirExists(extendedPath(srcRoot)):
    let depAbs = absolutePath(srcRoot)
    let facts = committedLockRepoFacts(depAbs)
    let rel = relativePath(depAbs, root).replace('\\', '/')
    return some(LockedDep(
      name: selector, path: rel,
      coordinates: Coordinates(kind: ckVcs, url: facts.originUrl,
        gitRef: facts.branch, revision: facts.headSha),
      integrity: computeDepIntegrity(depAbs, facts.headSha),
      version: "", visibility: "public", participation: "",
      depends: @[], tags: @[]))
  # Not discoverable on disk — carry an existing VCS lock pin forward if present.
  for d in existingDeps:
    if d.name == selector and d.coordinates.kind == ckVcs:
      return some(d)
  none(LockedDep)

proc repositoryNameFromUrl(url: string): string =
  ## Return the repository leaf from HTTPS, SSH/scp, file, or local-path Git
  ## coordinates. Lock identities must survive cloning the same repository into
  ## a differently named checkout directory.
  var value = url.strip()
  while value.len > 0 and value[^1] in {'/', '\\'}:
    value.setLen(value.len - 1)
  let separator = max(value.rfind('/'), max(value.rfind('\\'), value.rfind(':')))
  if separator >= 0 and separator + 1 < value.len:
    value = value[separator + 1 .. ^1]
  if value.toLowerAscii().endsWith(".git"):
    value.setLen(value.len - 4)
  value

proc lockedDepsForWorkspace(workspaceRoot: string;
                            usesSelectors: seq[string] = @[];
                            sourceRecipeRoots: seq[string] = @[]):
                            seq[LockedDep] =
  ## MO-8 — observe the workspace's participating repos and produce a
  ## ``LockedDep`` per dependency, each with checkout COORDINATES (vcs
  ## url/ref/revision) and a genuinely-computed INTEGRITY multihash. The root
  ## repo (``path = "."``) is always recorded; any develop-mode deps
  ## (``discoverDevelopDeps`` — NESTED deps under ``deps/…`` AND SIBLING
  ## develop-override deps one level up) follow. ``repro lock refresh``
  ## serializes these into the v2 committed lock so a lock-file-only workspace
  ## — including its sibling develop deps — is fully self-describing.
  ##
  ## FUP-M — ``usesSelectors`` (the recipe's declared ``uses:`` producer
  ## selectors) fold each cross-repo SOURCE sibling into ``deps`` too. Before
  ## this, a ``uses:``-only sibling (present neither under ``deps/…`` nor in
  ## ``.repro/develop-overrides.toml``) was silently dropped by refresh — the
  ## lock resolved by the solver carried the sibling in ``packages`` but the
  ## unified ``deps`` set omitted it, so a lock-only build could not resolve the
  ## producer graph.
  result = @[]
  let root = absolutePath(workspaceRoot)
  let rootFacts = committedLockRepoFacts(root)
  let nested = discoverDevelopDeps(root)
  let bare = extractFilename(root.strip(
    leading = false, trailing = true, chars = {'/', '\\'}))
  let originName = repositoryNameFromUrl(rootFacts.originUrl)
  let rootName =
    if originName.len > 0: originName
    elif bare.len > 0: bare
    else: "workspace"
  # Existing committed lock — the carry-forward source for a ``uses:`` sibling
  # that is pinned but not checked out here.
  var existingDeps: seq[LockedDep] = @[]
  let existingLockP = committedLockPath(root)
  if fileExists(extendedPath(existingLockP)):
    try: existingDeps = parseLockedDependencies(
      readFile(extendedPath(existingLockP))).deps
    except CatchableError: discard
  # Sibling deps: the develop-mode discovery set FIRST, then the recipe's
  # ``uses:`` producer siblings folded in (deduped by path and name).
  var siblingDeps: seq[LockedDep] = @[]
  var seenPaths: seq[string] = @[]
  var seenNames: seq[string] = @[]
  for d in nested:
    let depAbs = root / d.path
    let facts = committedLockRepoFacts(depAbs)
    siblingDeps.add(LockedDep(
      name: d.name, path: d.path,
      coordinates: Coordinates(kind: ckVcs, url: facts.originUrl,
        gitRef: facts.branch, revision: facts.headSha),
      integrity: computeDepIntegrity(depAbs, facts.headSha),
      version: "", visibility: "public", participation: "",
      depends: @[], tags: @[]))
    seenPaths.add(d.path)
    seenNames.add(d.name)
  for selector in usesSelectors:
    if selector in seenNames: continue
    let depOpt = usesProducerLockedDep(selector, root, existingDeps)
    if depOpt.isNone: continue
    let dep = depOpt.get()
    if dep.path in seenPaths or dep.name in seenNames: continue
    siblingDeps.add(dep)
    seenPaths.add(dep.path)
    seenNames.add(dep.name)
  # A federated source catalog is itself a reproducibility input. Recipe paths
  # live below that repository, so normalize each one to its enclosing Git
  # worktree and lock the repository once rather than recording hundreds of
  # package subdirectories as unrelated dependencies.
  for recipeRoot in sourceRecipeRoots:
    let repoRoot = gitTopLevel(recipeRoot)
    if repoRoot.len == 0:
      continue
    let depAbs = absolutePath(repoRoot)
    if cmpPaths(depAbs, root) == 0:
      continue
    let rel = relativePath(depAbs, root).replace('\\', '/')
    if rel in seenPaths:
      continue
    let facts = committedLockRepoFacts(depAbs)
    let bareName = extractFilename(depAbs.strip(
      leading = false, trailing = true, chars = {'/', '\\'}))
    let originName = repositoryNameFromUrl(facts.originUrl)
    let depName =
      if originName.len > 0: originName
      elif bareName.len > 0: bareName
      else: "source-catalog"
    if depName in seenNames:
      continue
    siblingDeps.add(LockedDep(
      name: depName, path: rel,
      coordinates: Coordinates(kind: ckVcs, url: facts.originUrl,
        gitRef: facts.branch, revision: facts.headSha),
      integrity: computeDepIntegrity(depAbs, facts.headSha),
      version: "", visibility: "public", participation: "",
      depends: @[], tags: @[]))
    seenPaths.add(rel)
    seenNames.add(depName)
  var rootDepends: seq[string] = @[]
  for d in siblingDeps: rootDepends.add(d.name)
  result.add(LockedDep(
    name: rootName, path: ".",
    coordinates: Coordinates(kind: ckVcs, url: rootFacts.originUrl,
      gitRef: rootFacts.branch, revision: rootFacts.headSha),
    integrity: computeDepIntegrity(root, rootFacts.headSha),
    version: "", visibility: "public", participation: "",
    depends: rootDepends, tags: @[]))
  for d in siblingDeps:
    result.add(d)

proc visibilityFromLockString(s: string): WorkspaceVisibility =
  case s.strip().toLowerAscii()
  of "org": wvOrg
  of "team": wvTeam
  of "personal", "private": wvPersonal
  else: wvPublic

proc committedLockDerivedProject(workspaceRoot: string):
    Option[ResolvedProject] =
  ## MO-2/MO-7/MO-8 — derive a ``ResolvedProject`` for a committed-lock-only
  ## workspace. Returns ``none`` when ``workspaceRoot`` carries no committed
  ## ``repro.lock`` (so the caller keeps its manifest-required behavior).
  ##
  ## MO-8 — POPULATE FROM THE LOCK CONTENT. When the v2 committed lock carries
  ## a usable VCS root dependency, the participating set + per-repo revisions
  ## come from the LOCK's coordinates (not live ``git HEAD``): the workspace is
  ## *described by* the lock, so the resolved revisions reflect the LOCKED
  ## state even if the checkout's HEAD has since moved. Any nested develop-mode
  ## dep present on disk but NOT in the lock (a develop sibling checked out
  ## after the lock was refreshed) is still folded in via discovery — the lock
  ## pins what it pins; a local develop overlay augments it (mode-agnostic).
  ##
  ## FALLBACK (documented boundary): when the committed lock carries no usable
  ## VCS workspace dep (or cannot be parsed as a v2 lock), the original
  ## MO-2/MO-7 HEAD-derivation runs unchanged (root repo at its own HEAD +
  ## nested-dep discovery), preserving behavior where v2 workspace data is
  ## absent.
  if not hasCommittedLockWorkspaceMarker(workspaceRoot):
    return none(ResolvedProject)
  let root = absolutePath(workspaceRoot)
  let lockP = committedLockPath(root)

  # MO-8/MO-9 — populate-from-lock-content path, routed through the unified
  # ``populateLockedDeps`` seam (the committed-lock source). The seam returns an
  # empty ``deps`` set on a missing / unparseable / non-v2 lock, in which case
  # the ``hasRootVcsDep`` guard below falls through to the HEAD-derivation
  # fallback — preserving the MO-2/MO-7 boundary.
  block fromLock:
    let ld = populateLockedDeps(
      LockSource(kind: lskCommittedLock, workspaceRoot: root))
    var hasRootVcsDep = false
    for d in ld.deps:
      if d.path == "." and d.coordinates.kind == ckVcs and
          d.coordinates.revision.len > 0:
        hasRootVcsDep = true
        break
    if not hasRootVcsDep:
      break fromLock
    var repos: seq[ResolvedRepo] = @[]
    var lockedPaths: seq[string] = @[]
    var rootIdx = -1
    var rootName = ""
    var rootRef = ""
    var rootRevision = ""
    for d in ld.deps:
      if d.coordinates.kind != ckVcs or d.coordinates.revision.len == 0:
        continue
      repos.add(ResolvedRepo(
        name: d.name, path: d.path, projectRemote: "origin",
        fetchUrl: d.coordinates.url, revision: d.coordinates.revision,
        vcs: defaultRepoVcs, stability: defaultRepoStability,
        visibility: visibilityFromLockString(d.visibility),
        participation: d.participation, depends: d.depends, tags: d.tags))
      lockedPaths.add(d.path)
      if d.path == ".":
        rootIdx = repos.high
        rootName = d.name
        rootRef = d.coordinates.gitRef
        rootRevision = d.coordinates.revision
    # Fold in on-disk develop deps the lock does not (yet) carry — NESTED deps
    # (MO-7) and SIBLING develop-override deps one level up (MO-12).
    var extraDepends: seq[string] = @[]
    for nd in discoverDevelopDeps(root):
      if nd.path in lockedPaths: continue
      repos.add(nd)
      extraDepends.add(nd.name)
    if rootIdx >= 0:
      for n in extraDepends:
        if n notin repos[rootIdx].depends:
          repos[rootIdx].depends.add(n)
    if rootName.len == 0: rootName = "workspace"
    return some(ResolvedProject(
      projectName: rootName,
      defaultRevision: rootRevision,
      trunk: (if rootRef.len > 0: rootRef else: "HEAD"),
      repos: repos,
      projectFile: lockP))

  # MO-2/MO-7 HEAD-derivation fallback (no usable VCS workspace dep in lock).
  let facts = committedLockRepoFacts(root)
  let bareName = extractFilename(root.strip(
    leading = false, trailing = true, chars = {'/', '\\'}))
  let repoName = if bareName.len > 0: bareName else: "workspace"
  let trunk = if facts.branch.len > 0: facts.branch else: "HEAD"
  let revision =
    if facts.headSha.len > 0: facts.headSha
    elif facts.branch.len > 0: facts.branch
    else: "HEAD"
  let nestedDeps = discoverDevelopDeps(root)
  var dependsOn: seq[string] = @[]
  for dep in nestedDeps:
    dependsOn.add(dep.name)
  let repo = ResolvedRepo(
    name: repoName,
    path: ".",
    projectRemote: "origin",
    fetchUrl: facts.originUrl,
    revision: revision,
    vcs: defaultRepoVcs,
    stability: defaultRepoStability,
    visibility: wvPublic,
    depends: dependsOn)
  some(ResolvedProject(
    projectName: repoName,
    defaultRevision: revision,
    trunk: trunk,
    repos: @[repo] & nestedDeps,
    projectFile: committedLockPath(root)))

proc resolveProjectDirFromTarget(target: string): string =
  ## Resolve the directory that owns the committed lock for a build
  ## target. An existing directory is itself; an existing file resolves
  ## to its parent; everything else (a bare name selector, or an empty
  ## target) falls back to the current working directory.
  if target.len == 0:
    return getCurrentDir()
  let abs = absolutePath(target)
  if dirExists(extendedPath(abs)):
    return abs
  if fileExists(extendedPath(abs)):
    return parentDir(abs)
  getCurrentDir()

# Forward declarations — bodies live after ``parseExplainFixture`` (which
# they consume to turn the sidecar solver-inputs text into the solver's
# ``VariantDecl`` / ``PackageDecl`` lists).
proc loadSolverInputsFile(path: string): tuple[
    variants: seq[variant_encoder.VariantDecl],
    packages: seq[PackageDecl], text: string]
proc resolveSolvedGraphForBuild(projectDir, lockOverride,
                                inputsOverride: string): tuple[
    solution: UnifiedSolution, source: string, lockPath: string,
    found: bool]
const LockStrategyNames* = "default, lowest, highest, lowest-direct"
  ## The valid strategy spellings, as ONE string.
  ##
  ## NLF-M6 / corpus NLF-STRAT-6 requires an unknown strategy to error "and
  ## list the valid ones, rather than being silently dropped". A single
  ## constant is what keeps the listed set and the accepted set the same set:
  ## the previous shape repeated the list in two diagnostics, so adding
  ## `lowest-direct` to the parser would have left both messages advertising
  ## three strategies while four were accepted.

proc unknownStrategyDiagnostic*(command, raw: string): string =
  ## The exact line every `--strategy` refusal writes.
  ##
  ## Exported, and built here rather than at each call site, for the reason
  ## NLF-STRAT-6 asks about: "an unknown strategy errors and LISTS THE VALID
  ## ONES". Two hand-written copies of that list is how the listed set and the
  ## accepted set come apart — and the wrong direction of that drift tells a
  ## user a working spelling is invalid. Exporting it also lets a test assert
  ## on the text without capturing a process's stderr, which is not portable.
  command & ": unknown --strategy '" & raw & "' (expected: " &
    LockStrategyNames & ")"

proc parseLockStrategy(raw: string; strategy: var LockStrategy): bool =
  ## Named-Lock-Files §5.5's strategy set, parsed from the CLI spelling.
  ## Defined here rather than beside the lock verbs because `repro build
  ## --strategy` and `repro lock solve --strategy` must accept exactly the
  ## same vocabulary, and two parsers is how a vocabulary drifts.
  ##
  ## Derived from the enum rather than from a hand-written `case`, so a
  ## strategy that exists cannot fail to be spellable and a spelling that
  ## parses cannot fail to exist.
  for s in LockStrategy:
    if $s == raw:
      strategy = s
      return true
  false

# Named-Lock-Files NLF-M5 §5.4 — the `--strategy` door. Body lives beside the
# other lock-generation entry points (it needs `resolveRefreshSolverInputs`).
proc applyStrategyHiddenLock(projectDir: string; strategy: LockStrategy;
                             committedLock: string;
                             solved: var UnifiedSolution): int

proc runBuildCommand(args: openArray[string]; publicCliPath: string;
                     forceDirect = false;
                     daemonHosted = false;
                     eventSink: BuildCommandEventSink = nil;
                     cancelCheck: BuildCancelCallback = nil): int =
  let originalArgs = @args
  # Named-Lock-Files NLF-M5 §5.4 — `--strategy <s>`. Absent, `strategyGiven`
  # stays false and the lock-consumption block below is byte-unchanged.
  var buildStrategy = lsDefault
  var strategyGiven = false
  var target = ""
  var positionalSelectors: seq[string] = @[]
  var mode = tpmUnspecified
  var workRoot = ""
  var daemonMode = bdmAuto
  var daemonModeExplicit = false
  var progressMode = configuredBuildProgressMode()
  var progressBarStyle = configuredBuildProgressBarStyle()
  var showSet = configuredShowSet()
  var measureSet = configuredMeasureSet()
  var measureExplicit = false
  var showExplicit = false
  var reportPersistence = BuildReportPersistence()
  var logMode = configuredBuildLogMode()
  var diagnosticsPath = ""
  var benchmarkPath = ""
  var statsCapture = StatsCaptureConfig()
  var prepareOnly = false
  var dryRun = false
  var forceRebuild = false
  var noOutputCleanup = false
  var publishCacheHits = false
  var publishMaterialized = false
  var skipCmakeRegeneration = false
  var forwardedActionArgs: seq[string] = @[]
  var afterArgumentSeparator = false
  # MO-1 — committed solved-graph lock. ``--lock <file>`` selects an
  # alternate committed lock (default = ``<projectDir>/repro.lock``);
  # ``--print-solved-graph`` resolves + prints the solved graph the build
  # would pin from the lock (or a fresh solve when no lock is present) and
  # exits WITHOUT building — the no-build inspection surface that exercises
  # the exact lock-consumption path the real build uses.
  var lockOverride = ""
  var lockBindings = initLockBindings()
    ## Named-Lock-Files NLF-M7 (§5.1). Every `--lock` occurrence lands here,
    ## whichever of the two forms it took, so the "two bindings for `default`
    ## in one invocation" case (NLF-CLI-4) is an error rather than a
    ## precedence puzzle even when the two arrived through different
    ## spellings.
  var printSolvedGraph = false
  var logModeExplicit = false
  # Default: use runquota when reachable; --no-runquota forces full bypass.
  var bypassRunQuota = getEnv("REPROBUILD_NO_RUNQUOTA").normalize in
    ["1", "true", "yes", "on"]
  # Named-Targets M5: ``--list-targets`` enumerates every implicit /
  # explicit target name visible in the current project's target-export
  # table. ``--list-targets-json`` is the JSON view; ``--list-targets``
  # alone prints a text table. ``--package=NAME`` filters the output to
  # one owning package.
  var listTargets = false
  var listTargetsJson = false
  var listTargetsPackage = ""
  # Peer-Cache M1 (Linux-Distro-Recipe-Validation M5 wiring,
  # 2026-06-12): ``--peer-cache=<spec>`` makes ``repro build`` consult
  # a LAN peer cache before falling through to a local rebuild. The
  # spec string mirrors ``repro test``'s flag — ``parsePeerCache``
  # recognises ``none`` (no-op), ``remote://<url>`` (parsed but not yet
  # consumed at the engine seam), and ``lan://<CIDR>[:port]`` (starts
  # the multicast discovery plane). When the spec validates and
  # surfaces a runnable client, the build engine receives the
  # action-bundle fetcher / publisher / installer closures via the
  # ``BuildEngineConfig`` peer-cache fields; the legacy local-only
  # flow is byte-for-byte preserved when the flag is absent.
  var peerCacheSpec = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if afterArgumentSeparator:
      forwardedActionArgs.add(arg)
    elif arg == "--":
      afterArgumentSeparator = true
    elif arg == "--daemon" or arg.startsWith("--daemon="):
      daemonMode = parseBuildDaemonMode(valueFromFlag(args, i, "--daemon"),
        "--daemon")
      daemonModeExplicit = true
    elif arg == "--list-targets":
      listTargets = true
    elif arg == "--list-targets-json":
      listTargets = true
      listTargetsJson = true
    elif arg == "--json" and listTargets:
      # ``repro build --list-targets --json`` is the spec-mandated
      # shape; accept ``--json`` as a follower of ``--list-targets``
      # without consuming the flag for any other build subcommand
      # surface. The ordering check above keeps the bare ``--json``
      # token unrecognised for non-list-targets invocations so the
      # legacy "unsupported build flag" error still fires.
      listTargetsJson = true
    elif arg == "--package" or arg.startsWith("--package="):
      listTargetsPackage = valueFromFlag(args, i, "--package")
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i,
        "--tool-provisioning"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--action-cache-root" or arg.startsWith("--action-cache-root="):
      # Phase 1 cache-scope split: user-level action cache + CAS root.
      # See Provider-Compile-Tiering.md §"Cache Scope". When omitted, we
      # resolve from ${REPROBUILD_STORE_ROOT}/action-cache or the platform
      # default user cache dir at engine config build time.
      setActionCacheRootOverride(valueFromFlag(args, i,
        "--action-cache-root"))
    elif arg == "--progress" or arg.startsWith("--progress="):
      progressMode = parseBuildProgressMode(valueFromFlag(args, i,
        "--progress"))
    elif arg == "--progress-bars" or arg.startsWith("--progress-bars="):
      progressBarStyle = parseBuildProgressBarStyle(valueFromFlag(args, i,
        "--progress-bars"))
    elif arg == "--write-diagnostics" or
        arg.startsWith("--write-diagnostics="):
      diagnosticsPath = valueFromFlag(args, i, "--write-diagnostics")
    elif arg == "--write-benchmark" or arg.startsWith("--write-benchmark="):
      benchmarkPath = valueFromFlag(args, i, "--write-benchmark")
    elif arg == "--write-stats" or arg.startsWith("--write-stats="):
      # PERSIST axis, third sink: the accumulating analytics store. Bare
      # enables it at the conventional store path; ``=PATH`` names the store.
      statsCapture.enabled = true
      if statsCapture.groups.card == 0:
        statsCapture.groups = AllStatsCaptureGroups
        statsCapture.raw = "all"
      if arg.startsWith("--write-stats="):
        statsCapture.storePath = arg.split("=", maxsplit = 1)[1]
    elif arg.startsWith("--stats-groups="):
      # Section filter over the store. Naming any group enables the sink.
      statsCapture = parseStatsCaptureGroups(arg.split("=", maxsplit = 1)[1],
        statsCapture.storePath)
    elif arg == "--stats-groups":
      raise newException(ValueError,
        "--stats-groups requires an inline value, for example " &
          "--stats-groups=timing,cache")
    elif arg == "--measure" or arg.startsWith("--measure="):
      # COLLECT axis. Additive across occurrences; an explicit flag replaces
      # the environment default rather than adding to it.
      if not measureExplicit:
        measureSet = {}
        measureExplicit = true
      measureSet = parseMeasureCategories(measureSet,
        valueFromFlag(args, i, "--measure"), "--measure")
    elif arg == "--show" or arg.startsWith("--show="):
      # PRESENT axis. Same vocabulary; showing implies measuring.
      if not showExplicit:
        showSet = {}
        showExplicit = true
      showSet = parseMeasureCategories(showSet,
        valueFromFlag(args, i, "--show"), "--show")
    elif arg == "--write-report" or arg.startsWith("--write-report="):
      reportPersistence.requested = true
      if arg.startsWith("--write-report="):
        reportPersistence.path = arg["--write-report=".len .. ^1]
    elif arg == "--no-write-report":
      reportPersistence.suppressed = true
    elif arg == "--log" or arg.startsWith("--log="):
      logMode = parseBuildLogMode(valueFromFlag(args, i, "--log"))
      logModeExplicit = true
    elif arg == "-v" or arg == "--verbose":
      logMode = blmSummary
      logModeExplicit = true
    elif arg == "-vv" or arg == "--very-verbose":
      logMode = blmActions
      logModeExplicit = true
    elif arg == "--prepare-only":
      prepareOnly = true
    elif arg == "--dry-run":
      dryRun = true
    elif arg in ["--force-rebuild", "--rebuild"]:
      forceRebuild = true
    elif arg == "--no-output-cleanup":
      noOutputCleanup = true
    elif arg == "--publish-cache-hits":
      publishCacheHits = true
    elif arg == "--publish-materialized":
      publishMaterialized = true
    elif arg == "--skip-cmake-regeneration":
      skipCmakeRegeneration = true
    elif arg == "--no-runquota":
      bypassRunQuota = true
    elif arg == "--runquota":
      bypassRunQuota = false
    elif arg == "--unicode":
      setUnicodeOverride(true)
    elif arg == "--no-unicode":
      setUnicodeOverride(false)
    elif arg == "--peer-cache" or arg.startsWith("--peer-cache="):
      peerCacheSpec = valueFromFlag(args, i, "--peer-cache")
    elif arg == "--lock" or arg.startsWith("--lock="):
      # MO-1 alternate committed lock, generalised by Named-Lock-Files §5.1.
      # ``--lock-slice`` is a distinct flag handled elsewhere; the exact
      # ``--lock`` / ``--lock=`` match here never swallows it.
      #
      # §5.1: "**One flag, not two.** `--lock` is the existing whole-build
      # flag (§2.3) generalised: with an `=` it binds a named lock file,
      # without one it binds `default`." And §5.2: "`--lock <path>` … is
      # exactly `--lock default=<path>`. It is retained as the spelling for
      # the overwhelmingly common single-lock-file case and is **not**
      # deprecated. The two forms are distinguished by the presence of `=`."
      let raw = valueFromFlag(args, i, "--lock")
      try:
        lockBindings.applyLockFlag(raw)
      except LockFileError as err:
        stderr.writeLine("repro build: " & err.msg)
        return 2
      # The un-named form keeps its existing meaning verbatim, so every
      # pre-NLF-M7 invocation is byte-unchanged.
      if lockBindings.byName.hasKey(DefaultLockFileName):
        lockOverride = lockBindings.byName[DefaultLockFileName]
      # NLF-M8, folded from NLF-M7 — and this is the line that makes
      # `--lock <name>=<path>` mean something for a name other than
      # `default`. `lockOverride` above is the VERSION-pinning half and only
      # `default` has one; `setActiveLockBindings` is the IDENTITY half, and
      # `governingLockIdentityFor` resolves every name through it. Without
      # this the flag parses, validates, errors correctly on a typo — and
      # then governs one graph.
      setActiveLockBindings(lockBindings)
    elif arg == "--strategy" or arg.startsWith("--strategy="):
      # Named-Lock-Files §5.5: `repro build --strategy lowest` is
      # `--lock default=strategy:lowest` — "generate a lock file under the
      # given strategy into a hidden, uncommitted location, then use it.
      # Nothing else."
      let raw = valueFromFlag(args, i, "--strategy")
      if not parseLockStrategy(raw, buildStrategy):
        stderr.writeLine(unknownStrategyDiagnostic("repro build", raw))
        return 2
      strategyGiven = true
    elif arg == "--print-solved-graph":
      printSolvedGraph = true
    elif arg == "--variant" or arg.startsWith("--variant="):
      # Spec-Implementation M1 — ``--variant name=value`` registers a
      # ``prSet`` contribution against the named solver-participating
      # Configurable before evaluation begins. The accumulated set is
      # exported as the ``REPRO_VARIANTS`` env var so it survives the
      # CLI -> provider process hop; both halves of the contract live
      # in ``repro_dsl_stdlib/configurables/variants.nim``.
      #
      # M1 explicitly defers solver integration to M2; here the flag
      # only feeds the priority lattice (``prDefault < prSet <
      # prOverride < prForce``) the existing ``Configurable`` system
      # already implements.
      let spec = valueFromFlag(args, i, "--variant")
      if spec.find('=') <= 0:
        raise newException(ValueError,
          "--variant expects name=value (got: " & spec & ")")
      var existing = getEnv("REPRO_VARIANTS")
      if existing.len > 0:
        existing.add(',')
      existing.add(spec)
      putEnv("REPRO_VARIANTS", existing)
    elif arg == "--release" or arg == "--debug":
      # Standard-configuration shorthand (Standard-Configurations.md):
      # ``--release`` / ``--debug`` are sugar for ``--variant
      # buildType=release|debug``. Recognized standard configs map a
      # leading-dash flag to the conventional ``buildType`` axis value;
      # other configs still use the explicit ``--variant buildType=…``.
      let cfg = arg[2 .. ^1]
      var existing = getEnv("REPRO_VARIANTS")
      if existing.len > 0:
        existing.add(',')
      existing.add("buildType=" & cfg)
      putEnv("REPRO_VARIANTS", existing)
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported build flag: " & arg)
    else:
      # Named-Targets M2: collect every positional. Classification into
      # path vs. name selectors happens below so the build dispatch can
      # fold name-shaped selectors into one engine pass.
      positionalSelectors.add(arg)
    inc i

  # ----------------------------------------------------------------
  # MO-1 — ``--print-solved-graph`` no-build inspection. Resolved BEFORE
  # selector classification so it works against a committed-lock-only
  # fixture directory that has no ``repro.nim``. Prints the solved graph
  # the build would pin (from the committed lock when present, else a
  # fresh solve of the ``repro.solver`` sidecar) and exits without
  # building — exercising the exact lock-consumption loader the real build
  # uses.
  # ----------------------------------------------------------------
  if printSolvedGraph:
    let rawTarget =
      if positionalSelectors.len > 0: positionalSelectors[0] else: ""
    let projDir = resolveProjectDirFromTarget(rawTarget)
    # NLF-M5 §5.5 — a strategy OVERRIDES the committed lock for THIS
    # invocation, and `--print-solved-graph` is an invocation. Printing the
    # committed graph under `--strategy highest` would report the opposite of
    # what was asked for, in the one command whose entire job is to say what
    # the build will pin.
    var graph =
      if strategyGiven:
        let committed =
          if lockOverride.len > 0: absolutePath(lockOverride)
          else: committedLockPath(projDir)
        var strategySolution: UnifiedSolution
        let rc = applyStrategyHiddenLock(projDir, buildStrategy, committed,
                                         strategySolution)
        if rc != 0: return rc
        (solution: strategySolution, source: "strategy:" & $buildStrategy,
         lockPath: committed, found: true)
      else:
        resolveSolvedGraphForBuild(projDir, lockOverride, "")
    var inputsTxt = ""
    let sip = solverInputsPath(projDir)
    if fileExists(extendedPath(sip)):
      try:
        inputsTxt = readFile(extendedPath(sip))
      except CatchableError:
        inputsTxt = ""
    let lk = solutionToLock(graph.solution, currentPlatformId(), inputsTxt)
    stdout.write(serializeSolvedGraphLock(lk))
    stdout.write("# source: " & graph.source & "\n")
    return 0

  # ----------------------------------------------------------------
  # Named-Targets M2 positional resolution lives in the shared M3
  # ``parseAndResolveSelectors`` helper so ``runBuildCommand`` and
  # ``runWatchCommand`` cannot drift. The helper classifies every
  # selector via ``classifyBuildSelector``; the first path-shaped
  # selector (or the current directory when there's none) becomes the
  # engine's project anchor, and every name-shaped selector contributes
  # its closure to ``extraNameSelectors`` so the build runs in one
  # pass.
  # ----------------------------------------------------------------
  let resolved = parseAndResolveSelectors(positionalSelectors, "repro build")
  target = resolved.target
  var extraNameSelectors: seq[string] = resolved.extraNameSelectors
  let targetWasOmitted = resolved.targetWasOmitted
  if target.len == 0:
    target = "."

  # ----------------------------------------------------------------
  # MO-1 / Named-Lock-Files NLF-M3 — consume the committed solved-graph lock,
  # as PINS.
  #
  # When a committed lock is present at the canonical path (or at
  # ``--lock <file>``), the WHOLE solved graph it records — the resolved
  # package VERSIONS as well as the variant assignments — is forwarded to the
  # provider process as hard pins (``REPRO_LOCK_PINS`` / ``REPRO_LOCK_PATH``,
  # the grammar in ``repro_solver/lock_pins``). The solve then asserts them as
  # facts instead of searching for them, so the build reproduces the locked
  # graph rather than re-solving to something that merely scores well.
  #
  # WHAT THIS REPLACED, and why the replacement is not cosmetic
  # (Named-Lock-Files.md §1.2): this block used to fold only
  # ``graph.solution.variants`` into ``REPRO_VARIANTS`` and never read
  # ``graph.solution.packages`` at all. So the locked VERSIONS were dropped
  # outright — version concretization re-ran fully unpinned with a lock
  # present — and the variant half arrived as an ordinary contribution, which
  # the encoder renders as a ``#minimize`` WEIGHT that a better-scoring model
  # can outvote. The lock biased the solve; it did not pin it.
  #
  # The variants are NO LONGER injected into ``REPRO_VARIANTS``. That is
  # required, not incidental: an explicit ``--variant`` still outranks the lock
  # (§2.5 — the lock is mode-agnostic and CLI overrides layer above it), and
  # the provider tells the two apart by exactly that env var. Injecting the
  # lock's own variants there would disguise every one of them as an explicit
  # override and no pin would ever apply.
  #
  # ``graph.lockPath`` is whichever lock was RESOLVED, so ``--lock <file>``
  # reaches the pinning path with no separate wiring.
  # ----------------------------------------------------------------
  block lockConsumption:
    let projDir = resolveProjectDirFromTarget(splitTarget(target).base)
    let effectiveLock =
      if lockOverride.len > 0: absolutePath(lockOverride)
      else: committedLockPath(projDir)
    if strategyGiven:
      # NLF-M5 §5.5's decision, which "must have a defined answer": a strategy
      # OVERRIDES the committed lock for this invocation and NEVER writes it
      # back. Overrides rather than errors, "because the primary use is exactly
      # an application *with* a committed lock checking that its declared
      # ranges still hold"; never writes back, because "under `lowest` a
      # write-back would downgrade the whole project as a side effect of
      # running a test".
      var strategySolution: UnifiedSolution
      let rc = applyStrategyHiddenLock(projDir, buildStrategy, effectiveLock,
                                       strategySolution)
      if rc != 0: return rc
      break lockConsumption
    let graph = resolveSolvedGraphForBuild(projDir, lockOverride, "")
    if graph.found and graph.source == "lock":
      putEnv(LockPinsEnvVar,
             renderLockPins(graph.solution.packages, graph.solution.variants))
      putEnv(LockPathEnvVar, graph.lockPath)

  # Apply the REPRO_TOOL_PROVISIONING env override before any dispatch so
  # both ``--list-targets`` and the engine build observe the same mode. A
  # value here only takes effect when ``--tool-provisioning`` was not passed.
  mode = resolveToolProvisioningWithEnv(mode)
  prependExplicitWorkRootToolPath(workRoot)

  # Named-Targets M5: ``--list-targets`` short-circuits the engine pass.
  # The flag's job is to list every implicit / explicit target name
  # visible in the project's aggregated target-export table so users can
  # discover what `repro build NAME` accepts. Implementation lives in
  # ``runListTargetsCommand`` (declared further down so it can call
  # ``prepareBuildGraphInspection``).
  if listTargets:
    return runListTargetsCommand(target, mode, publicCliPath, workRoot,
      listTargetsJson, listTargetsPackage, bypassRunQuota)

  if not daemonModeExplicit:
    daemonMode = configuredBuildDaemonMode()

  if progressMode == bpmQuiet:
    # Both are terminal output, so a quiet terminal clears the presentation
    # axis. It does NOT touch ``--measure``: no UI setting may gate a
    # collection decision (CLI/README.md §"UI flags are not part of this
    # system").
    if not logModeExplicit:
      logMode = blmQuiet
    if not showExplicit:
      showSet = {}

  # PRESENT and PERSIST are consumers of COLLECT, so asking for either
  # implies gathering what it needs. The implication is one-directional:
  # measuring never implies showing or writing.
  measureSet = measureSet + showSet
  if benchmarkPath.len > 0:
    measureSet.incl(mcTiming)
  if statsCapture.enabled:
    if scgTiming in statsCapture.groups:
      measureSet.incl(mcTiming)
    if scgDeps in statsCapture.groups:
      measureSet.incl(mcCacheEvidence)

  # ----------------------------------------------------------------
  # M48 — Mode 1 (layout-as-manifest) fallback.
  # When the target points at a directory that has NO repro.nim /
  # reprobuild.nim AND NO Mode 2 ecosystem manifest, attempt to load
  # the workspace from layout. The loader synthesises a repro.nim +
  # repro.scanned-deps.nim under <workspaceRoot>/.repro/mode1-synth/
  # and we redirect the build target to that path. Per spec, NOTHING
  # is written to the workspace root itself — the synth dir is plain
  # build scratch.
  # ----------------------------------------------------------------
  let parts = splitTarget(target)
  if dirExists(extendedPath(parts.base)):
    let workspaceCandidate = absolutePath(parts.base)
    if not hasAnyProjectFile(workspaceCandidate) and
        not hasMode2Manifest(workspaceCandidate):
      var ws = loadMode1Workspace(workspaceCandidate)
      if ws.ambiguousImports.len > 0:
        stderr.writeLine(renderAmbiguousImportError(ws))
        return 2
      if ws.targets.len > 0:
        # Mixed-language Mode 1 surfaces a diagnostic with empty
        # target field; surface as a hard error.
        for d in ws.diagnostics:
          if d.target.len == 0 and
              d.message.contains("mixed-language workspace"):
            stderr.writeLine("repro build: error: " & d.message)
            return 2
        let synth = materializeMode1ProjectFile(ws)
        if synth.len > 0:
          # Redirect the target: preserve any ``#fragment`` selector
          # the user passed (``#default`` etc.).
          if parts.fragment.len > 0:
            target = synth & "#" & parts.fragment
          else:
            target = synth

  if statsCapture.enabled and (forceDirect or daemonMode == bdmOff) and
      not daemonHosted:
    raise newException(ValueError,
      "--write-stats requires daemon-hosted build; direct-mode persistent " &
        "capture is not implemented")

  proc runDirectBuild(): int =
    if statsCapture.enabled and daemonHosted:
      let nowTime = getTime()
      let runId = "build-" & $getCurrentProcessId() & "-" &
        $nowTime.toUnix & "-" & $nowTime.nanosecond
      let projectRoot =
        try:
          projectRootForModule(absolutePath(parseBuildTarget(target).modulePath))
        except CatchableError:
          getCurrentDir()
      beginStatsCapture(runId, runId, projectRoot, "build", target,
        statsCapture)
      enqueueStatsObservation(scgSessions, "build-start", %*{
        "captureGroups": statsCapture.captureGroupsText,
        "daemonHosted": true
      })
    # RX: forward recipe-declared custom pools to a freshly spawned daemon so
    # their execute-edge leases are granted (not denied -> hung). If a daemon
    # is already reachable, pool caps are fixed and the inspection would only
    # warm provider caches before the visible build.
    let recipePools =
      if autoRunQuotaNeedsPoolPreflight(bypassRunQuota):
        extractRecipeBuildPools(target, mode, publicCliPath, workRoot,
          bypassRunQuota)
      else:
        @[]
    var autoRunQuota = startAutoRunQuotaIfNeeded(bypassRunQuota, recipePools)
    # Peer-Cache M1 wiring (LDRV M5): start the LAN peer-cache runtime
    # when the user passed ``--peer-cache=lan://…``. The actual setup
    # lives in ``buildPeerCacheWiringFor`` further down the file so
    # the forward-declared peer-cache helpers (``parsePeerCache``,
    # ``startPeerCacheServices``) are in scope.
    let peerCacheBuildWiring =
      try:
        buildPeerCacheWiringFor(peerCacheSpec)
      except CatchableError as exc:
        stderr.writeLine("repro build: error: " & exc.msg)
        return 2
    try:
      result = executeBuildTarget(target, mode, publicCliPath,
        selectDefaultAction = targetWasOmitted,
        workRoot = workRoot,
        progressMode = progressMode,
        progressBarStyle = progressBarStyle,
        showSet = showSet,
        measureSet = measureSet,
        reportPersistence = reportPersistence,
        logMode = logMode,
        diagnosticsPath = diagnosticsPath,
        prepareOnly = prepareOnly,
        dryRun = dryRun,
        forceRebuild = forceRebuild,
        noOutputCleanup = noOutputCleanup,
        publishCacheHits = publishCacheHits,
        publishMaterialized = publishMaterialized,
        skipCmakeRegeneration = skipCmakeRegeneration,
        bypassRunQuotaExplicit = bypassRunQuota,
        benchmarkPath = benchmarkPath,
        eventSink = eventSink,
        cancelCheck = cancelCheck,
        extraNameSelectors = extraNameSelectors,
        forwardedActionArgs = forwardedActionArgs,
        peerCacheFetcher = peerCacheBuildWiring.fetcher,
        peerCachePublisher = peerCacheBuildWiring.publisher,
        peerCacheInstaller = peerCacheBuildWiring.installer).exitCode
      if statsCapture.enabled and daemonHosted:
        enqueueStatsObservation(scgSessions, "build-finish", %*{
          "exitCode": result
        })
    finally:
      releaseAutoRunQuotaProcess(autoRunQuota)

  proc buildRunId(): string =
    let nowTime = getTime()
    "build-" & $getCurrentProcessId() & "-" & $nowTime.toUnix & "-" &
      $nowTime.nanosecond

  proc requestProjectRoot(): string =
    try:
      projectRootForModule(absolutePath(parseBuildTarget(target).modulePath))
    except CatchableError:
      getCurrentDir()

  proc daemonBuildEnvironment(): seq[string] =
    # Delegates to the shared ``daemonCarriedEnvironment`` so that the build
    # and watch sessions agree on the env-forwarding contract, and so that
    # cargo/rustc actions launched by the daemon see Nix cc-wrapper variables
    # (NIX_LDFLAGS et al) from the user's nix-develop shell.
    sanitizeUserDaemonRequestEnvironment(daemonCarriedEnvironment())

  proc runDaemonBuild(): int =
    # Auto-spawn the daemon in dev (self-restart) mode. The daemon is a
    # persistent process that can outlive the `repro` that started it; when
    # `repro` is rebuilt to a new version, a frozen daemon keeps decoding
    # build-target payloads with its old engine and the build fails with
    # `unsupported build target payload version`. In dev mode the idle daemon
    # notices its on-disk image changed and self-restarts to the new build —
    # see `restartCandidateReady`, which only fires on a real hash change,
    # debounces, and defers while any session is active. `repro-daemon`
    # launched directly (no `--dev`) still defaults to the frozen regime.
    let config = defaultUserDaemonConfig(devMode = true)
    let projectRoot = requestProjectRoot()
    discard startUserDaemon(publicCliPath, config)
    # Honor --progress in daemon-hosted mode. The daemon forwards each
    # BuildProgressEvent as a tagged diagnostic; render it through the
    # client's own renderer so the requested mode (bar-line/etc.) is applied
    # instead of dumping the raw "progress: <kind> <id>" line.
    var clientProgress = newBuildProgressRenderer(progressMode,
      progressBarStyle)
    let request = UserDaemonBuildRequest(
      runId: buildRunId(),
      target: target,
      workingDir: getCurrentDir(),
      projectRoot: projectRoot,
      toolProvisioning: mode.modeName,
      workRoot: workRoot,
      publicCliPath: publicCliPath,
      rawArgs: originalArgs,
      environment: daemonBuildEnvironment(),
      attached: true,
      cancelOnDisconnect: true)
    let daemonResult = requestUserDaemonBuild(request, config.endpoint,
      proc(event: UserDaemonBuildEvent) =
        # Progress events carry the structured BuildProgressEvent in their
        # payload — render them through the client renderer and stop.
        if event.kind == bekDiagnostic and
            tryRenderDaemonProgress(clientProgress, event.payloadJson):
          return
        # Daemon-side error paths (e.g. the "refusing implicit PATH
        # fallback" ValueError when --tool-provisioning is omitted)
        # surface as a single bekFinished event with severity=error
        # whose message carries "daemon-hosted build failed: <inner>".
        # Without printing those, the CLI exits non-zero with no
        # diagnostic at all — and tests like
        # t_e2e_codetracer_build_subset_without_tup that gate on the
        # error text (`refusing implicit PATH fallback`) can't see it.
        let isError = event.kind in {bekFinished, bekCancelled,
            bekUnsupported} and event.severity == "error"
        if (event.kind == bekDiagnostic or isError) and
            event.message.len > 0:
          # Clear any in-progress bar line so the message lands cleanly.
          clientProgress.clearProgressLine()
          if isError or
              event.payloadJson.contains("\"stream\":\"stderr\""):
            stderr.write(event.message)
            if not event.message.endsWith("\n"):
              stderr.writeLine("")
          else:
            stdout.write(event.message)
            if not event.message.endsWith("\n"):
              stdout.writeLine(""))
    clientProgress.finishProgress()
    if not daemonResult.supported:
      raise newException(DaemonBuildUnsupported, daemonResult.message)
    updateBenchmarkDaemonConnection(benchmarkPath, daemonResult.connectionUs)
    daemonResult.exitCode

  if forceDirect or daemonMode == bdmOff:
    return runDirectBuild()
  try:
    return runDaemonBuild()
  except DaemonBuildUnsupported as err:
    if daemonMode == bdmRequire:
      raise newException(ValueError,
        "daemon mode required but repro-daemon cannot execute builds: " &
          err.msg)
    if statsCapture.enabled:
      raise newException(ValueError,
        "daemon-hosted stats capture requested but repro-daemon cannot " &
          "execute builds: " & err.msg)
    if logMode != blmQuiet:
      stderr.writeLine("repro build: daemon build unsupported; falling " &
        "back to direct mode: " & err.msg)
    if statsCapture.enabled:
      raise newException(ValueError,
        "daemon-hosted stats capture requested but repro-daemon is unavailable: " &
          err.msg)
    return runDirectBuild()
  except CatchableError as err:
    if daemonMode == bdmRequire:
      raise newException(ValueError,
        "daemon mode required but repro-daemon is unavailable: " & err.msg)
    if statsCapture.enabled:
      raise newException(ValueError,
        "daemon-hosted stats capture requested but repro-daemon is unavailable: " &
          err.msg)
    if logMode != blmQuiet:
      stderr.writeLine("repro build: daemon unavailable; falling back to " &
        "direct mode: " & err.msg)
    return runDirectBuild()

proc parseGraphOutputFormat(value: string; allowDot: bool): GraphOutputFormat =
  case value.normalize()
  of "text":
    gofText
  of "json":
    gofJson
  of "dot":
    if allowDot:
      gofDot
    else:
      raise newException(ValueError, "unsupported format for this command: dot")
  else:
    raise newException(ValueError,
      "unsupported format: " & value &
        (if allowDot: " (expected text, json, or dot)"
        else: " (expected text or json)"))

proc buildActionById(actions: openArray[BuildAction]): Table[string, BuildAction] =
  for action in actions:
    result[action.id] = action

proc availableActionIds(actions: openArray[BuildAction]): seq[string] =
  for action in actions:
    result.add(action.id)
  result.sort()

proc requireAction(actions: openArray[BuildAction]; id: string): BuildAction =
  for action in actions:
    if action.id == id:
      return action
  let available = availableActionIds(actions)
  raise newException(ValueError,
    "unknown build action: " & id &
      (if available.len > 0:
        " (available: " & available.join(", ") & ")"
      else:
        " (graph contains no build actions)"))

proc directDependents(actions: openArray[BuildAction]; id: string): seq[string] =
  for action in actions:
    if action.deps.contains(id):
      result.add(action.id)
  result.sort()

proc directDependencies(actions: openArray[BuildAction]; id: string): seq[string] =
  let action = requireAction(actions, id)
  result = action.deps
  result.sort()

proc commandDisplay(action: BuildAction): string =
  if action.argv.len > 0:
    shellCommand(action.argv)
  else:
    case action.kind
    of bakCopyFile:
      "builtin copyFile"
    of bakEnsureDir:
      "builtin ensureDir"
    of bakWriteText:
      "builtin writeText"
    of bakStamp:
      "builtin stamp"
    of bakPreserveTree:
      "builtin preserveTree"
    else:
      "builtin action"

proc expectedDependencyFileJson(item: ExpectedDependencyFile): JsonNode =
  %*{
    "logicalName": item.logicalName,
    "path": item.path,
    "required": item.required
  }

proc expectedDependencyFilesJson(
    items: openArray[ExpectedDependencyFile]): JsonNode =
  result = newJArray()
  for item in items:
    result.add(expectedDependencyFileJson(item))

proc processSpecJson(process: ProcessSpec): JsonNode =
  var env = newJArray()
  for item in process.env:
    env.add(%*{"name": item.name, "value": item.value})
  %*{
    "kind": $process.kind,
    "executable": process.executable.value,
    "args": jsonStringSeq(process.args),
    "cwd": process.cwd.value,
    "env": env,
    "stdin": $process.stdinPolicy,
    "stdout": $process.stdoutPolicy,
    "stderr": $process.stderrPolicy
  }

proc dependencyPolicyJson(policy: DependencyGatheringPolicy): JsonNode =
  var reports = newJArray()
  for report in policy.recognizedReports:
    reports.add(%*{
      "formatName": $report.formatName,
      "outputs": expectedDependencyFilesJson(report.outputs),
      "completeness": $report.completeness
    })
  var converters = newJArray()
  for converterSpec in policy.postBuildConverters:
    converters.add(%*{
      "converterProcess": processSpecJson(converterSpec.converterProcess),
      "inputs": expectedDependencyFilesJson(converterSpec.inputs),
      "outputs": expectedDependencyFilesJson(converterSpec.outputs),
      "outputKind": $converterSpec.outputKind,
      "outputFormatName": $converterSpec.outputFormatName,
      "completeness": $converterSpec.completeness
    })
  %*{
    "kind": $policy.kind,
    "completeness": $policy.completeness,
    "recognizedReports": reports,
    "postBuildConverters": converters,
    "ignoredInputPrefixes": jsonStringSeq(policy.ignoredInputPrefixes)
  }

proc buildPoolJson(pool: BuildPool): JsonNode =
  %*{"name": pool.name, "capacity": pool.capacity}

proc buildPoolsJson(pools: openArray[BuildPool]): JsonNode =
  result = newJArray()
  for pool in pools:
    result.add(buildPoolJson(pool))

proc buildActionJson(action: BuildAction): JsonNode =
  %*{
    "id": action.id,
    "kind": $action.kind,
    "deps": jsonStringSeq(action.deps),
    "inputs": jsonStringSeq(action.inputs),
    "outputs": jsonStringSeq(action.outputs),
    "argv": jsonStringSeq(action.argv),
    "cwd": action.cwd,
    "env": jsonStringSeq(action.env),
    "envPassthrough": jsonStringSeq(action.envPassthrough),
    "pool": action.pool,
    "poolUnits": action.poolUnits,
    "cpuMilli": action.cpuMilli,
    "memoryBytes": $action.memoryBytes,
    "commandStatsId": action.commandStatsId,
    "cacheable": action.cacheable,
    "weakFingerprint": digestHex(action.weakFingerprint),
    "publishToBinaryCache": action.publishToBinaryCache,
    "binaryCacheKey": deriveActionCacheKeyHex(action),
    "actionCachePolicy": $action.actionCachePolicy,
    "depfile": action.depfile,
    "dynamicDepsFile": action.dynamicDepsFile,
    "monitorDepfile": action.monitorDepfile,
    "toolIdentityRefs": jsonStringSeq(action.toolIdentityRefs),
    "toolIdentityRefKinds": jsonStringSeq(
      action.toolIdentityRefKinds.mapIt($it)),
    "dependencyPolicy": dependencyPolicyJson(action.dependencyPolicy),
    "builtinText": action.builtinText,
    "builtinEntries": jsonStringSeq(action.builtinEntries)
  }

proc buildActionsJson(actions: openArray[BuildAction]): JsonNode =
  result = newJArray()
  for action in actions:
    result.add(buildActionJson(action))

proc buildGraphInspectionJson(info: BuildGraphInspection): JsonNode =
  %*{
    "schemaId": "reprobuild.graph.build.v1",
    "target": info.target,
    "modulePath": info.modulePath,
    "projectRoot": info.projectRoot,
    "outDir": info.outDir,
    "interfacePath": info.interfacePath,
    "toolProvisioning": info.toolProvisioning.modeName,
    "toolIdentityPath": info.toolIdentityPath,
    "toolInspectionPath": info.toolInspectionPath,
    "providerBinaryPath": info.providerBinaryPath,
    "providerCompileArtifactPath": info.providerCompileArtifactPath,
    "providerArtifactId": info.providerArtifactId,
    "providerGraphSnapshotPath": info.providerGraphSnapshotPath,
    "providerInvocations": info.providerInvocations,
    "providerCompileCacheHit": info.providerCompileCacheHit,
    "providerGraphCacheHit": info.providerGraphCacheHit,
    "loweredGraphCachePath": info.loweredGraphCachePath,
    "loweredGraphCacheHit": info.loweredGraphCacheHit,
    "selectedActionId": info.selectedActionId,
    "defaultActionId": info.defaultActionId,
    "pools": buildPoolsJson(info.pools),
    "actions": buildActionsJson(info.actions)
  }

proc loweredGraphRecordJson(record: LoweredGraphCacheRecord): JsonNode =
  %*{
    "schemaId": "reprobuild.debug.lowered-graph-cache.v1",
    "modulePath": record.modulePath,
    "projectRoot": record.projectRoot,
    "selectedActionId": record.selectedActionId,
    "pathEnv": record.pathEnv,
    "cacheKey": record.cacheKey,
    "pools": buildPoolsJson(record.pools),
    "actions": buildActionsJson(record.actions)
  }

proc renderActionDetail(action: BuildAction): string =
  var lines: seq[string] = @[]
  lines.add("action " & action.id)
  lines.add("  kind: " & $action.kind)
  lines.add("  deps: " & (if action.deps.len > 0: action.deps.join(", ") else: "-"))
  lines.add("  inputs: " & $action.inputs.len)
  for item in action.inputs:
    lines.add("    input: " & item)
  lines.add("  outputs: " & $action.outputs.len)
  for item in action.outputs:
    lines.add("    output: " & item)
  lines.add("  cwd: " & action.cwd)
  lines.add("  command: " & commandDisplay(action))
  if action.env.len > 0:
    lines.add("  env:")
    for item in action.env:
      lines.add("    " & item)
  if action.pool.len > 0:
    lines.add("  pool: " & action.pool & " units=" & $action.poolUnits)
  lines.add("  cacheable: " & $action.cacheable)
  lines.add("  cachePolicy: " & $action.actionCachePolicy)
  lines.add("  dependencyPolicy: " & $action.dependencyPolicy.kind &
    " completeness=" & $action.dependencyPolicy.completeness)
  if action.depfile.len > 0:
    lines.add("  depfile: " & action.depfile)
  if action.dynamicDepsFile.len > 0:
    lines.add("  dynamicDepsFile: " & action.dynamicDepsFile)
  if action.monitorDepfile.len > 0:
    lines.add("  monitorDepfile: " & action.monitorDepfile)
  lines.join("\n")

proc renderBuildGraphText(info: BuildGraphInspection; focus = ""): string =
  var lines: seq[string] = @[]
  lines.add("build graph")
  lines.add("target: " & info.target)
  lines.add("projectRoot: " & info.projectRoot)
  lines.add("modulePath: " & info.modulePath)
  lines.add("outDir: " & info.outDir)
  lines.add("toolProvisioning: " & info.toolProvisioning.modeName)
  if info.selectedActionId.len > 0:
    lines.add("selectedAction: " & info.selectedActionId)
  elif info.defaultActionId.len > 0:
    lines.add("defaultAction: " & info.defaultActionId)
  lines.add("actions: " & $info.actions.len)
  lines.add("pools: " & $info.pools.len)
  lines.add("providerCompileCacheHit: " & $info.providerCompileCacheHit)
  lines.add("providerGraphCacheHit: " & $info.providerGraphCacheHit)
  lines.add("loweredGraphCacheHit: " & $info.loweredGraphCacheHit)
  if focus.len > 0:
    let action = requireAction(info.actions, focus)
    lines.add("")
    lines.add(renderActionDetail(action))
    let deps = directDependencies(info.actions, focus)
    let dependents = directDependents(info.actions, focus)
    lines.add("  directDependencies: " &
      (if deps.len > 0: deps.join(", ") else: "-"))
    lines.add("  directDependents: " &
      (if dependents.len > 0: dependents.join(", ") else: "-"))
    return lines.join("\n")
  for action in info.actions:
    lines.add("- " & action.id &
      " deps=[" & action.deps.join(", ") & "]" &
      " outputs=" & $action.outputs.len &
      " policy=" & $action.dependencyPolicy.kind &
      " command=" & commandDisplay(action))
  lines.join("\n")

proc dotQuote(value: string): string =
  "\"" & value.replace("\\", "\\\\").replace("\"", "\\\"") & "\""

proc focusNodeSet(actions: openArray[BuildAction]; focus: string): HashSet[string] =
  result.incl(focus)
  let action = requireAction(actions, focus)
  for dep in action.deps:
    result.incl(dep)
  for dependent in directDependents(actions, focus):
    result.incl(dependent)

proc renderBuildGraphDot(info: BuildGraphInspection; focus = ""): string =
  var lines = @["digraph repro_build {"]
  let shown =
    if focus.len > 0:
      focusNodeSet(info.actions, focus)
    else:
      initHashSet[string]()
  for action in info.actions:
    if focus.len > 0 and not shown.contains(action.id):
      continue
    lines.add("  " & dotQuote(action.id) & " [label=" &
      dotQuote(action.id) & "];")
  for action in info.actions:
    if focus.len > 0 and not shown.contains(action.id):
      continue
    for dep in action.deps:
      if focus.len == 0 or shown.contains(dep):
        lines.add("  " & dotQuote(dep) & " -> " & dotQuote(action.id) & ";")
  lines.add("}")
  lines.join("\n")

proc runQuotaBypassedByEnv(): bool =
  ## ``REPROBUILD_NO_RUNQUOTA`` is the documented full-bypass switch the build
  ## engine forces onto every test edge (see ``childBypassEnv`` in
  ## repro_build_engine). Internal build steps that a test's ``repro exec``
  ## drives — notably the provider-compile refresh below — must honour it too,
  ## otherwise they open an inline runquota session that the surrounding test
  ## explicitly opted out of. (Mirrors the ``--no-runquota`` handling in the
  ## ``build`` command parser.)
  getEnv("REPROBUILD_NO_RUNQUOTA").normalize in ["1", "true", "yes", "on"]

proc effectiveProviderCompileRunQuotaBypass*(explicitBypass: bool): bool =
  ## Provider compilation is scheduled before the main recipe graph. Carry the
  ## parsed CLI decision into that scheduler instead of relying only on the
  ## environment fallback used by nested invocations.
  explicitBypass or runQuotaBypassedByEnv()

proc recordMaterializedProducersForInspection(
    artifact: ProjectInterfaceArtifact; projectRoot, outDir,
    publicCliPath: string; mode: ToolProvisioningMode) =
  ## Graph inspection does not execute producer build edges, but it must bind
  ## producer outputs that a prior build has already materialized. Otherwise a
  ## declared cross-repository executable falls through to the package catalog
  ## and reports a misleading missing source-recipe error.
  for useDef in artifact.projectInterface.toolUses:
    let selector = useDef.packageSelector
    if selector.len == 0 or producerMaterializedBinDirs.hasKey(selector) or
        producerMaterializedAuxPaths.hasKey(selector):
      continue
    let binding = resolveProducerBinding(selector, projectRoot)
    if not binding.declaresProducerEdge:
      continue
    let sourceRoot = producerSourceRoot(binding, selector, projectRoot,
      fetchMissingPinnedSource = true)
    if sourceRoot.len == 0 or not dirExists(extendedPath(sourceRoot)):
      raise newException(IOError,
        "cross-repo producer \"" & selector &
        "\" has no source checkout available for graph inspection")
    let sourceRootAbs = absolutePath(sourceRoot)
    let projectFile = resolveProjectFile(sourceRootAbs).path
    let producerOutDir = outDir / "cross-repo-producers" /
      selectorFilesystemKey(selector)
    createDir(extendedPath(producerOutDir))
    var inspectionStats: BuildStats
    let producerArtifact = extractInterfaceEdge(projectFile,
      producerOutDir / "producer-interface.rbsz",
      producerOutDir / "producer-interface.nim", reprobuildLibraryWorkDir(),
      producerOutDir / "producer-iface-work",
      projectRootForModule(projectFile), publicCliPath,
      producerOutDir / "build-engine-cache", inspectionStats,
      requireStub = false)
    var runtimeIdentity = PathOnlyBuildIdentity()
    if producerArtifact.projectInterface.runtimeToolUses.len > 0:
      var runtimeArtifact = producerArtifact
      runtimeArtifact.projectInterface.toolUses =
        producerArtifact.projectInterface.runtimeToolUses
      runtimeArtifact.projectInterface.runtimeToolUses = @[]
      runtimeIdentity = toolBuildIdentity(runtimeArtifact, mode,
        storeRoot = producerOutDir / "runtime-tool-store")
    if not recordProducerMaterialization(selector, sourceRootAbs,
        producerArtifact, runtimeIdentity, binding):
      raise newException(IOError,
        "cross-repo producer \"" & selector & "\" at " & sourceRootAbs &
        " is not materialized; run `repro build` for the consuming target " &
        "before inspecting its resolved graph")

proc prepareBuildGraphInspection(target: string; mode: ToolProvisioningMode;
                                 publicCliPath: string;
                                 selectDefaultAction = false;
                                 workRoot = "";
                                 forceRefresh = false;
                                 mergeExtensions = true;
                                 includeDevEnvOnlyProvider = false;
                                 lowerGraph: bool;
                                 selectedActionOverride: string):
                                   BuildGraphInspection =
  ## ``mergeExtensions`` (MO-6) folds any present ``projectExtension``
  ## sibling's fragments into this project's snapshot before lowering /
  ## target-export aggregation. It is set to ``false`` when this proc is
  ## reused by ``mergeProjectExtensions`` to evaluate an extension recipe
  ## itself, so extensions do not recurse into their own extensions.
  var parsedTarget = parseBuildTarget(target)
  parsedTarget.modulePath = absolutePath(parsedTarget.modulePath)
  let modulePath = parsedTarget.modulePath
  if not fileExists(extendedPath(modulePath)):
    raise newException(IOError, "build target module not found: " & modulePath)
  let outDir = outputDirForTarget(parsedTarget, workRoot)
  let projectRoot = projectRootForModule(modulePath)
  result.target = target
  result.modulePath = modulePath
  result.projectRoot = projectRoot
  result.outDir = outDir

  let interfacePath = outDir / "project-interface.rbsz"
  let stubPath = outDir / "project-interface.nim"
  let compileWorkDir = reprobuildLibraryWorkDir()
  let compileScratchDir = outDir / "provider-work"
  # MR5 — see executeBuildTarget for the bootstrap toolchain rationale.
  ensureBootstrapToolchainEnv(mode, resolveStoreRoot() / "tool-store")
  var inspectionStats: BuildStats
  let artifact = extractInterfaceEdge(modulePath, interfacePath, stubPath,
    compileWorkDir, compileScratchDir, projectRoot, publicCliPath,
    outDir / "build-engine-cache", inspectionStats, requireStub = false)
  result.interfacePath = interfacePath

  var effectiveMode = mode
  if effectiveMode == tpmUnspecified and
      artifact.projectInterface.defaultToolProvisioning.len > 0:
    effectiveMode = parseToolProvisioning(
      artifact.projectInterface.defaultToolProvisioning)
  if artifact.projectInterface.toolUses.len > 0 and
      effectiveMode == tpmUnspecified:
    raise newException(ValueError,
      "typed tool provisioning is required for uses declarations; refusing " &
        "implicit PATH fallback. Pass --tool-provisioning=path to use the " &
        "explicit weak local profile.")
  result.toolProvisioning = effectiveMode

  var identity = PathOnlyBuildIdentity(
    projectName: artifact.projectInterface.projectName,
    interfaceFingerprint: artifact.interfaceFingerprint)
  if lowerGraph and shouldEnterBuildPipeline(effectiveMode):
    recordMaterializedProducersForInspection(artifact, projectRoot, outDir,
      publicCliPath, effectiveMode)
    let resolved = warmResolveAndWriteIdentity(artifact, outDir, effectiveMode)
    identity = resolved.identity
    result.toolIdentityPath = resolved.identityPath
    result.toolInspectionPath = resolved.inspectionPath

  let hasBuildBlock = moduleHasBuildBlock(modulePath)
  if not hasBuildBlock and
      (not includeDevEnvOnlyProvider or not moduleHasDevEnvBlock(modulePath)):
    return

  let providerBinaryPath = outDir / "provider" / "project-provider"
  let providerArtifactPath = outDir / "provider-compile.rbsz"
  result.providerBinaryPath = providerBinaryPath
  result.providerCompileArtifactPath = providerArtifactPath

  var provider: ProviderCompileArtifact
  let providerPlan = providerCompilePlan(modulePath, providerBinaryPath,
    artifact.interfaceFingerprint, compileWorkDir, compileScratchDir)
  let cachedProvider =
    if forceRefresh:
      none(ProviderCompileArtifact)
    else:
      staticFreshnessFallbackProvider(providerPlan, providerArtifactPath,
        modulePath, providerBinaryPath, artifact.interfaceFingerprint,
        compileWorkDir)
  if cachedProvider.isSome:
    provider = cachedProvider.get()
    result.providerCompileCacheHit = true
  else:
    invalidateStaleProviderCompileArtifact(providerPlan, providerArtifactPath)
    let providerCompileAction = providerCompileBuildAction(providerPlan,
      modulePath, interfacePath, providerArtifactPath,
      internalReproHelperCliPath(publicCliPath), compileWorkDir,
      compileScratchDir)
    var providerCompileConfig = BuildEngineConfig(
      cacheRoot: outDir / "build-engine-cache",
      actionCacheRoot: currentActionCacheRoot(),
      runQuotaCliPath: publicCliPath,
      # Monitor the provider compile so its fingerprint covers every file the
      # compile reads (repro.nim + all transitive imports), not just the
      # statically declared inputs. See the matching wiring on the primary
      # provider-compile config above.
      monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
      monitorCliArgs: internalIoMonitorArgs,
      maxParallelism: 1'u32,
      stdoutLimit: 1024 * 1024,
      stderrLimit: 1024 * 1024,
      rebuildMissingOutputsOnCacheHit: true,
      deferLocalOutputBlobs: true,
      bypassRunQuota: runQuotaBypassedByEnv(),
      fallbackToRunQuotaBypass: effectiveMode in {tpmPathOnly, tpmScoop},
      inlineRunQuota: true,
      dryRun: false,
      forceRebuild: forceRefresh,
      suppressTrace: true,
      skipCacheHitEvidence: true)
    let providerCompileResult = runBuild(graph([providerCompileAction]),
      providerCompileConfig)
    # This pass logs nothing of its own, and it is the pass that most
    # often does the actual compiling. Record it so the ONE line that IS
    # logged (in `executeBuildTarget`) can report the invocation rather
    # than just its own last consultation.
    noteProviderCompileConsultation(providerCompileResult)
    if providerCompileResult.hasFailedActions():
      raise newException(OSError, providerCompileFailure(providerCompileResult))
    # Re-derived from the engine's own decision now that the hand-written
    # freshness gate is gone: the edge was scheduled, and the engine either
    # restored its outputs from the CAS (``asCacheHit``) or accepted the
    # already-present outputs against a revalidated action-cache record
    # (``asUpToDate``). Either way no compile ran.
    for item in providerCompileResult.results:
      if item.id == providerCompileAction.id:
        result.providerCompileCacheHit = item.status in {asCacheHit, asUpToDate}
    if not fileExists(extendedPath(providerArtifactPath)):
      raise newException(IOError,
        "provider compile edge did not write artifact: " & providerArtifactPath)
    provider = readProviderCompileArtifact(providerArtifactPath)
    if not providerCompileArtifactFresh(providerArtifactPath,
        providerPlan.outputBinaryPath, providerPlan.interfaceFingerprint,
        providerPlan.providerFingerprint, providerPlan.workDir):
      raise newException(IOError,
        "provider compile artifact is stale after edge execution: " &
          providerArtifactPath)

  result.providerArtifactId = digestHex(provider.providerFingerprint)
  result.providerBinaryPath = provider.outputBinaryPath

  # Task introspection needs the provider manifest, but a dev-env-only recipe
  # has no project-root graph to refresh or lower.
  if not hasBuildBlock:
    return

  let providerGraphStore = providerGraphStoreRoot(outDir / "provider-graph")
  var refresh: ProviderRefreshReport
  let freshSnapshot =
    if forceRefresh:
      none(ProviderGraphSnapshot)
    else:
      warmReadFreshProviderGraphSnapshot(providerGraphStore, result.providerArtifactId)
  if freshSnapshot.isSome:
    refresh.snapshot = freshSnapshot.get()
    refresh.persistedSnapshotPath = providerSnapshotPath(providerGraphStore)
    result.providerGraphCacheHit = true
  else:
    refresh = refreshProviderGraph(RefreshConfig(
      storeRoot: providerGraphStore,
      providerBinaryPath: provider.outputBinaryPath,
      providerArtifactId: result.providerArtifactId,
      rootEntryPointId: artifact.projectInterface.packageName & ".root",
      rootArguments: projectRoot,
      namespace: "project",
      lockSliceId: digestHex(artifact.interfaceFingerprint),
      activity: "build",
      providerWorkingDir: projectRoot))
  # Workspace-Manifest-Optional MO-6 — fold any present projectExtension
  # sibling's fragments into this project's snapshot (see the matching
  # call in ``executeBuildTarget``). Skipped when this proc is reused to
  # evaluate an extension recipe itself so extensions do not recurse.
  var extensionSignature = ""
  if mergeExtensions:
    extensionSignature = mergeProjectExtensions(refresh.snapshot, projectRoot,
      artifact.projectInterface.packageName, effectiveMode, publicCliPath,
      workRoot, lowerGraph = lowerGraph)
  result.snapshot = refresh.snapshot
  result.providerGraphSnapshotPath = refresh.persistedSnapshotPath
  result.providerInvocations = refresh.invoked.len
  result.defaultActionId = defaultBuildActionId(refresh.snapshot)

  # Metadata consumers do not need tool resolution or a lowered action graph.
  result.targetExportTable = aggregateTargetExportTable(refresh.snapshot)
  for fragment in refresh.snapshot.fragments:
    for node in fragment.nodes:
      if node.kind == gnkMetadata and
          node.stableName == "reprobuild.build-target.v1":
        let target = decodeBuildTargetPayload(toBytes(node.payload))
        if result.explicitTargetNames.find(target.name) < 0:
          result.explicitTargetNames.add(target.name)

  if not lowerGraph:
    return

  var selectedActionId =
    if selectedActionOverride.len > 0:
      selectedActionOverride
    else:
      parsedTarget.selectedActionId
  if selectDefaultAction and selectedActionId.len == 0:
    selectedActionId = result.defaultActionId
  result.selectedActionId = selectedActionId

  let pathEnv = getEnv("PATH")
  let graphCacheKey = loweredGraphCacheKey(artifact, effectiveMode,
    result.providerArtifactId, refresh.persistedSnapshotPath, pathEnv,
    extensionSignature)
  let cachePath = loweredGraphCachePath(outDir, selectedActionId)
  result.loweredGraphCachePath = cachePath
  let cachedLowered =
    if forceRefresh:
      none(tuple[actions: seq[BuildAction]; pools: seq[BuildPool]])
    else:
      warmReadFreshLoweredGraphCache(cachePath, modulePath, projectRoot,
        selectedActionId, pathEnv, graphCacheKey)
  let lowered =
    if cachedLowered.isSome:
      result.loweredGraphCacheHit = true
      cachedLowered.get()
    else:
      let computed = lowerProviderSnapshot(refresh.snapshot, identity,
        projectRoot, selectedActionId)
      writeLoweredGraphCache(cachePath, modulePath, projectRoot,
        selectedActionId, pathEnv, graphCacheKey, computed)
      computed
  result.actions = lowered.actions
  result.pools = lowered.pools

proc refreshRecipeProviderSnapshot(target: string;
                                   mode: ToolProvisioningMode;
                                   publicCliPath, workRoot: string;
                                   bypassRunQuotaExplicit: bool):
    RecipeProviderSnapshotRefresh =
  ## Produce the recipe's (extension-merged) provider-graph snapshot — the
  ## SNAPSHOT ONLY, with NO tool-identity resolution and NO graph lowering.
  ##
  ## This is the seam the RX pool-forwarding path needs. A recipe's declared
  ## ``buildPool(...)`` calls execute at PROVIDER-EXECUTION time and land in
  ## the snapshot's fragments as ``reprobuild.build-pool.v1`` metadata nodes.
  ## Producing the snapshot requires only the interface extract + the provider
  ## compile + the provider-graph refresh — it does NOT require resolving the
  ## recipe's ``uses:`` sibling tools (that resolution happens later, in
  ## ``warmResolveAndWriteIdentity`` / graph lowering, and THROWS at
  ## daemon-spawn time for a CONSUMER whose siblings are not yet materialized).
  ## By stopping at the snapshot we recover the consumer's OWN pools without
  ## tripping over the unresolved-sibling failure. Returns ``none`` when the
  ## recipe has no build block (leaf with no pools) — the caller treats that as
  ## "no custom pools".
  var parsedTarget = parseBuildTarget(target)
  parsedTarget.modulePath = absolutePath(parsedTarget.modulePath)
  let modulePath = parsedTarget.modulePath
  if not fileExists(extendedPath(modulePath)):
    raise newException(IOError, "build target module not found: " & modulePath)
  let outDir = outputDirForTarget(parsedTarget, workRoot)
  let projectRoot = projectRootForModule(modulePath)
  let interfacePath = outDir / "project-interface.rbsz"
  let stubPath = outDir / "project-interface.nim"
  let compileWorkDir = reprobuildLibraryWorkDir()
  let compileScratchDir = outDir / "provider-work"
  ensureBootstrapToolchainEnv(mode, resolveStoreRoot() / "tool-store")
  var snapshotStats: BuildStats
  let artifact = extractInterfaceEdge(modulePath, interfacePath, stubPath,
    compileWorkDir, compileScratchDir, projectRoot, publicCliPath,
    outDir / "build-engine-cache", snapshotStats, requireStub = false)

  var effectiveMode = mode
  if effectiveMode == tpmUnspecified and
      artifact.projectInterface.defaultToolProvisioning.len > 0:
    effectiveMode = parseToolProvisioning(
      artifact.projectInterface.defaultToolProvisioning)
  # NOTE: deliberately NO tool-identity resolution here — pool metadata does
  # not depend on it, and it is exactly the step that throws for an
  # unresolved-sibling CONSUMER at spawn time.

  if not moduleHasBuildBlock(modulePath):
    return RecipeProviderSnapshotRefresh(
      snapshot: none(ProviderGraphSnapshot))

  let providerBinaryPath = outDir / "provider" / "project-provider"
  let providerArtifactPath = outDir / "provider-compile.rbsz"
  var provider: ProviderCompileArtifact
  let providerPlan = providerCompilePlan(modulePath, providerBinaryPath,
    artifact.interfaceFingerprint, compileWorkDir, compileScratchDir)
  let cachedProvider =
    staticFreshnessFallbackProvider(providerPlan, providerArtifactPath,
      modulePath, providerBinaryPath, artifact.interfaceFingerprint,
      compileWorkDir)
  if cachedProvider.isSome:
    provider = cachedProvider.get()
  else:
    invalidateStaleProviderCompileArtifact(providerPlan, providerArtifactPath)
    let providerCompileAction = providerCompileBuildAction(providerPlan,
      modulePath, interfacePath, providerArtifactPath,
      internalReproHelperCliPath(publicCliPath), compileWorkDir,
      compileScratchDir)
    var providerCompileConfig = BuildEngineConfig(
      cacheRoot: outDir / "build-engine-cache",
      actionCacheRoot: currentActionCacheRoot(),
      runQuotaCliPath: publicCliPath,
      monitorCliPath: selfSpawnIoMonitorPath(publicCliPath),
      monitorCliArgs: internalIoMonitorArgs,
      maxParallelism: 1'u32,
      stdoutLimit: 1024 * 1024,
      stderrLimit: 1024 * 1024,
      rebuildMissingOutputsOnCacheHit: true,
      deferLocalOutputBlobs: true,
      bypassRunQuota:
        effectiveProviderCompileRunQuotaBypass(bypassRunQuotaExplicit),
      fallbackToRunQuotaBypass: effectiveMode in {tpmPathOnly, tpmScoop},
      inlineRunQuota: true,
      dryRun: false,
      forceRebuild: false,
      suppressTrace: true,
      skipCacheHitEvidence: true)
    let providerCompileResult = runBuild(graph([providerCompileAction]),
      providerCompileConfig)
    # This pass logs nothing of its own, and it is the pass that most
    # often does the actual compiling. Record it so the ONE line that IS
    # logged (in `executeBuildTarget`) can report the invocation rather
    # than just its own last consultation.
    noteProviderCompileConsultation(providerCompileResult)
    if providerCompileResult.hasFailedActions():
      raise newException(OSError, providerCompileFailure(providerCompileResult))
    if not fileExists(extendedPath(providerArtifactPath)):
      raise newException(IOError,
        "provider compile edge did not write artifact: " & providerArtifactPath)
    provider = readProviderCompileArtifact(providerArtifactPath)

  let providerArtifactId = digestHex(provider.providerFingerprint)
  let providerGraphStore = providerGraphStoreRoot(outDir / "provider-graph")
  var refresh: ProviderRefreshReport
  let freshSnapshot =
    warmReadFreshProviderGraphSnapshot(providerGraphStore, providerArtifactId)
  if freshSnapshot.isSome:
    refresh.snapshot = freshSnapshot.get()
  else:
    refresh = refreshProviderGraph(RefreshConfig(
      storeRoot: providerGraphStore,
      providerBinaryPath: provider.outputBinaryPath,
      providerArtifactId: providerArtifactId,
      rootEntryPointId: artifact.projectInterface.packageName & ".root",
      rootArguments: projectRoot,
      namespace: "project",
      lockSliceId: digestHex(artifact.interfaceFingerprint),
      activity: "build",
      providerWorkingDir: projectRoot))
  discard mergeProjectExtensions(refresh.snapshot, projectRoot,
    artifact.projectInterface.packageName, effectiveMode, publicCliPath,
    workRoot, lowerGraph = false)
  result.snapshot = some(refresh.snapshot)
  result.providerInvocations = refresh.invoked.len

proc extractRecipeBuildPools(target: string; mode: ToolProvisioningMode;
                             publicCliPath, workRoot: string;
                             bypassRunQuota: bool): seq[BuildPool] =
  ## RX pool-forwarding — return the recipe's declared build pools (the
  ## ``buildGraph.pools`` present in the extracted project graph) so the
  ## caller can forward them to ``runquotad`` alongside the convention
  ## ``compile`` / ``fetch`` pools.
  ##
  ## Consumer-own-pool forwarding fix: this is called at daemon-spawn time,
  ## BEFORE the producer sub-builds / develop-override resolution have run, so
  ## a CONSUMER recipe with ``uses:`` selectors cannot yet resolve its sibling
  ## tools. The OLD path routed through ``prepareBuildGraphInspection``, whose
  ## tool-identity resolution / graph lowering THROWS on those unresolved
  ## siblings; the best-effort ``except`` then swallowed the failure and
  ## returned an EMPTY pool set — dropping the consumer's OWN
  ## ``buildPool(...)`` and starving its pooled edges (cap-0 → lease denial →
  ## livelock). The consumer's own pools execute at provider-execution time
  ## and are INDEPENDENT of ``uses:`` resolution, so we now recover them from
  ## the provider-graph SNAPSHOT (``refreshRecipeProviderSnapshot`` +
  ## ``poolsFromSnapshot``) — which stops BEFORE the throwing sibling
  ## resolution. Still best-effort: a genuine recipe error (no build block,
  ## provider compile failure) yields an empty seq so the daemon spawns with
  ## the convention defaults and the pre-RX behaviour is preserved.
  var effectiveMode = mode
  if effectiveMode == tpmUnspecified:
    effectiveMode = tpmPathOnly
  try:
    let refresh = refreshRecipeProviderSnapshot(target, effectiveMode,
      publicCliPath, workRoot, bypassRunQuota)
    if refresh.snapshot.isSome:
      result = poolsFromSnapshot(refresh.snapshot.get())
    else:
      result = @[]
  except CatchableError:
    result = @[]

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-6 — projectExtension discovery + merge.
#
# A ``projectExtension <ext>, <originalProject>:`` recipe (see the macro in
# ``libs/repro_project_dsl/src/repro_project_dsl/macros_b.nim``) contributes
# libraries, build-graph edges, and named targets ONTO an already-defined
# ``originalProject`` *without modifying that project's source*. The
# extension is activated by mere PRESENCE in the develop workspace: when its
# repo is checked out as a sibling (one level up from the target project's
# root — the same workspace-sibling convention ``findSiblingProjectFile``
# uses), the recipe-discovery pass below finds it by its
# ``projectExtension`` head and the build folds its provider-graph fragments
# into ``originalProject``'s snapshot. Absence leaves ``originalProject``
# building standalone (the extension is inert; no error).
#
# This is the EXTEND inverse of the consume-only ``uses:`` path: ``uses:``
# pulls a producer's exported binding into a consumer (routed through
# ``registerCrossProjectUses`` / ``generatedCrossProjectAccessors`` in the
# DSL); ``projectExtension`` pushes new edges/targets outward onto an
# unaware target via this snapshot-merge pass. The two share no code.
# ---------------------------------------------------------------------------

proc parseProjectExtensionHead(recipeText, originalPackageName: string): string =
  ## Lightweight textual recognition of a ``projectExtension <ext>,
  ## <originalProject>:`` recipe head — the recipe-discovery convention's
  ## presence check (no provider compile needed to decide candidacy).
  ## Returns the extension name when the recipe extends
  ## ``originalPackageName``; the empty string otherwise.
  for rawLine in recipeText.splitLines:
    var line = rawLine.strip()
    if not line.startsWith("projectExtension"):
      continue
    line = line["projectExtension".len .. ^1]
    if line.len == 0 or line[0] notin {' ', '\t', '('}:
      continue
    # Tolerate both ``projectExtension ext, orig:`` and the parenthesised
    # ``projectExtension(ext, orig):`` spelling.
    line = line.strip()
    if line.len > 0 and line[0] == '(':
      line = line[1 .. ^1]
    let colon = line.find(':')
    if colon < 0:
      continue
    var head = line[0 ..< colon].strip()
    if head.len > 0 and head[^1] == ')':
      head = head[0 ..< head.len - 1].strip()
    let comma = head.find(',')
    if comma < 0:
      continue
    let extName = head[0 ..< comma].strip()
    let orig = head[comma + 1 .. ^1].strip()
    if extName.len > 0 and orig == originalPackageName:
      return extName
  return ""

proc projectExtensionCandidateDirs(projectRoot: string): seq[string] =
  ## The directories searched for ``projectExtension`` recipes, covering
  ## BOTH supported checkout topologies (Workspace-And-Develop-Mode.md
  ## §"Checkout Topologies"):
  ##
  ##   * **Sibling topology** — every immediate subdirectory one level up
  ##     from ``projectRoot`` (the original develop-workspace-sibling
  ##     convention ``findSiblingProjectFile`` uses), EXCEPT ``projectRoot``
  ##     itself.
  ##   * **Nested topology** (MO-7) — every immediate subdirectory of the
  ##     conventional project-local ``nestedDevelopDirs`` (``./deps/<dep>``,
  ##     ``./vendor/<dep>``, ``./third-party/<dep>``, ``./develop/<dep>``).
  ##     This is the nested-topology equivalent of the one-level-up sibling
  ##     scan, so a nested develop-mode extension auto-activates by presence
  ##     exactly like a sibling one does — no org-root / star layout needed.
  ##
  ## Order is deterministic (siblings first, then each nested container in
  ## ``nestedDevelopDirs`` declaration order); the caller re-sorts the final
  ## extension set by ``extName`` so merge order never depends on this.
  result = @[]
  let canonicalProject = absolutePath(projectRoot)
  var seenDirs = initHashSet[string]()
  var containers: seq[string] = @[]
  let workspaceRoot = projectRoot.parentDir
  if workspaceRoot.len > 0 and dirExists(extendedPath(workspaceRoot)):
    containers.add(workspaceRoot)
  for sub in nestedDevelopDirs:
    let containerAbs = canonicalProject / sub
    if dirExists(extendedPath(containerAbs)):
      containers.add(containerAbs)
  for container in containers:
    for kind, path in walkDir(container):
      if kind notin {pcDir, pcLinkToDir}:
        continue
      let abs = absolutePath(path)
      if abs == canonicalProject or abs in seenDirs:
        continue
      seenDirs.incl(abs)
      result.add(path)

proc discoverProjectExtensionRecipes(projectRoot, originalPackageName: string):
    seq[tuple[extName: string; recipePath: string]] =
  ## Scan the develop-workspace checkouts — sibling (one level up) AND nested
  ## (under ``./deps``/``./vendor``/``./third-party``/``./develop``; MO-7) —
  ## for recipe files whose ``projectExtension`` head names
  ## ``originalPackageName``. Returns ``(extName, recipePath)`` pairs sorted
  ## by ``extName`` so the merge order is DETERMINISTIC (stable across
  ## checkout layout) rather than dependent on filesystem iteration order.
  result = @[]
  if originalPackageName.len == 0:
    return
  var seenExtNames = initTable[string, string]()
  for path in projectExtensionCandidateDirs(projectRoot):
    var recipePath = ""
    try:
      recipePath = resolveProjectFile(path).path
    except CatchableError:
      # Ambiguous (both repro.nim + reprobuild.nim) or unreadable — skip;
      # a checkout that cannot present one canonical recipe is not a
      # discoverable extension here.
      continue
    if recipePath.len == 0 or not fileExists(extendedPath(recipePath)):
      continue
    var recipeText = ""
    try:
      recipeText = readFile(extendedPath(recipePath))
    except CatchableError:
      continue
    let extName = parseProjectExtensionHead(recipeText, originalPackageName)
    if extName.len == 0:
      continue
    if seenExtNames.hasKey(extName):
      raise newException(ValueError,
        "projectExtension conflict: two extensions of '" &
        originalPackageName & "' share the name '" & extName & "' (" &
        seenExtNames[extName] & " and " & recipePath &
        "). Extension names must be unique within a workspace.")
    seenExtNames[extName] = recipePath
    result.add((extName: extName, recipePath: recipePath))
  result.sort(proc(a, b: tuple[extName: string; recipePath: string]): int =
    cmp(a.extName, b.extName))

proc fragmentTargetNames(frags: seq[StoredGraphFragment]): seq[string] =
  ## Every ``aggregate`` / ``target`` name carried by ``frags`` (the
  ## ``reprobuild.build-target.v1`` metadata nodes). Used for the
  ## cross-contributor conflict check below.
  result = @[]
  for f in frags:
    for node in f.nodes:
      if node.kind == gnkMetadata and
          node.stableName == "reprobuild.build-target.v1":
        let target = decodeBuildTargetPayload(toBytes(node.payload))
        if target.name.len > 0 and result.find(target.name) < 0:
          result.add(target.name)

proc rehomeExtensionFragment(frag: StoredGraphFragment;
                             originalPackageName: string): StoredGraphFragment =
  ## Workspace-Manifest-Optional MO-13 (correcting MO-6) — re-home an
  ## extension fragment's exported targets under ``originalPackageName``.
  ## MO-6 merged an extension's edges/targets into the original project's
  ## GRAPH, but the target-export-table rows still carried the EXTENSION's
  ## own ``owningPackage`` (e.g. ``extProj``), so a target was not reachable
  ## under the original project's package name and
  ## ``repro build <orig>:<ext-target>`` did not resolve. Rewriting the
  ## ``owningPackage`` of every ``reprobuild.target-export-table.v1/v2``
  ## entry to ``originalPackageName`` re-homes the target: it now appears
  ## under the original project in ``--list-targets`` and resolves through
  ## the qualified ``<originalProject>:<ext-target>`` selector path. The
  ## action / build-target nodes (which carry no owning-package field) and
  ## every other fragment byte are left untouched.
  result = frag
  for ni in 0 ..< result.nodes.len:
    let node = result.nodes[ni]
    if node.kind == gnkMetadata and
        (node.stableName == "reprobuild.target-export-table.v1" or
         node.stableName == "reprobuild.target-export-table.v2"):
      var table = decodeTargetExportTablePayload(toBytes(node.payload))
      var changed = false
      for ei in 0 ..< table.entries.len:
        if table.entries[ei].owningPackage != originalPackageName:
          table.entries[ei].owningPackage = originalPackageName
          changed = true
      # Re-derive cross-package ambiguity over the re-homed owners so a
      # qualified candidate string never references the extension package.
      table.ambiguities = @[]
      var packagesByName = initTable[string, seq[string]]()
      for entry in table.entries:
        if not packagesByName.hasKey(entry.name):
          packagesByName[entry.name] = @[]
        if packagesByName[entry.name].find(entry.owningPackage) < 0:
          packagesByName[entry.name].add(entry.owningPackage)
      for name, pkgs in packagesByName.pairs:
        if pkgs.len >= 2:
          var candidates: seq[string] = @[]
          for pkg in pkgs:
            candidates.add(pkg & ":" & name)
          candidates.sort()
          table.ambiguities.add(TargetExportAmbiguity(name: name,
            candidates: candidates))
      if changed or table.ambiguities.len > 0:
        result.nodes[ni].payload = fromBytes(
          encodeTargetExportTablePayload(table))

proc mergeProjectExtensions(snapshot: var ProviderGraphSnapshot;
                            projectRoot, originalPackageName: string;
                            mode: ToolProvisioningMode;
                            publicCliPath, workRoot: string;
                            lowerGraph: bool): string =
  ## Fold every present ``projectExtension`` sibling's provider-graph
  ## fragments into ``snapshot`` (the target project's graph). Composition
  ## rules (Project-DSL-Composition.md §"Project extensions"):
  ##
  ##   * **Additive.** Extensions only ADD fragments; the base project's
  ##     own fragments are never rewritten or removed.
  ##   * **Deterministic ordering.** Extensions merge in ``extName`` order
  ##     (see ``discoverProjectExtensionRecipes``), not filesystem order.
  ##   * **Conflicts diagnosed, not silently resolved.** Two contributors
  ##     (an extension and the base, or two extensions) that define the
  ##     same target name raise a clear error naming BOTH.
  ##
  ## Returns the ACTIVE-extension SIGNATURE (MO-13): a deterministic digest
  ## of the merged extension set (each extension's name + the digest of the
  ## fragments it contributed), folded into the lowered-graph disk-cache key
  ## so toggling an extension on/off invalidates the cache WITHOUT
  ## ``--force-rebuild`` (and toggling back is a cache hit). Empty string when
  ## no extension is active, so the legacy single-project key is unchanged.
  result = ""
  if originalPackageName.len == 0:
    return
  let discovered = discoverProjectExtensionRecipes(projectRoot,
    originalPackageName)
  if discovered.len == 0:
    return
  # Seed the conflict map with the base project's target names so an
  # extension that collides with a base target is caught too.
  var targetOrigin = initTable[string, string]()
  for name in fragmentTargetNames(snapshot.fragments):
    if not targetOrigin.hasKey(name):
      targetOrigin[name] = "base project '" & originalPackageName & "'"
  var signaturePayload = ""
  for ext in discovered:
    # Reuse the standard compile + provider-evaluate pipeline; the
    # extension is just another DSL recipe. ``mergeExtensions = false``
    # keeps an extension from recursively merging its own extensions.
    let info = prepareBuildGraphInspection(ext.recipePath, mode,
      publicCliPath, selectDefaultAction = false, workRoot = workRoot,
      mergeExtensions = false, lowerGraph = lowerGraph)
    let extFrags = info.snapshot.fragments
    for name in fragmentTargetNames(extFrags):
      if targetOrigin.hasKey(name):
        raise newException(ValueError,
          "projectExtension conflict: target '" & name &
          "' is contributed by both " & targetOrigin[name] &
          " and projectExtension '" & ext.extName & "' (" & ext.recipePath &
          "). Two contributors must not define the same target name.")
      targetOrigin[name] = "projectExtension '" & ext.extName & "'"
    # Re-home the extension's exported targets under the original project,
    # then merge the (re-homed) fragments into the base graph.
    var fragDigestPayload = ""
    for f in extFrags:
      let rehomed = rehomeExtensionFragment(f, originalPackageName)
      snapshot.fragments.add(rehomed)
      fragDigestPayload.add(rehomed.fragmentDigest)
      for node in rehomed.nodes:
        fragDigestPayload.add(node.stableName)
        fragDigestPayload.add(node.payload)
    signaturePayload.addCacheField(ext.extName)
    signaturePayload.addCacheField(
      digestHex(blake3DomainDigest(fragDigestPayload.bytesOf(),
        hdMetadataEnvelope)))
  if signaturePayload.len > 0:
    result = digestHex(blake3DomainDigest(signaturePayload.bytesOf(),
      hdMetadataEnvelope))

proc runListTargetsCommand(target: string; mode: ToolProvisioningMode;
                           publicCliPath, workRoot: string;
                           asJson: bool; packageFilter: string;
                           bypassRunQuota: bool): int =
  ## Named-Targets M5: enumerate every implicit / explicit target name
  ## carried by the project's aggregated target-export table. Entries
  ## are sorted by ``(package, name)`` for deterministic CLI output and
  ## JSON consumers. ``packageFilter`` (if non-empty) restricts the
  ## listing to one owning package.
  discard bypassRunQuota
  var effectiveMode = mode
  if effectiveMode == tpmUnspecified:
    effectiveMode = tpmPathOnly
  let info = prepareBuildGraphInspection(target, effectiveMode,
    publicCliPath, selectDefaultAction = false, workRoot = workRoot,
    lowerGraph = false)
  var entries: seq[TargetExportEntry] = @[]
  for entry in info.targetExportTable.entries:
    if packageFilter.len > 0 and entry.owningPackage != packageFilter:
      continue
    entries.add(entry)
  entries.sort(proc(a, b: TargetExportEntry): int =
    let pkgCmp = cmp(a.owningPackage, b.owningPackage)
    if pkgCmp != 0: pkgCmp else: cmp(a.name, b.name))
  proc kindToText(k: TargetExportKind): string =
    case k
    of tekImplicit: "implicit"
    of tekExplicit: "explicit"
    of tekAggregate: "aggregate"
    of tekCollection: "collection"
    of tekRunEdge: "run-edge"
  if asJson:
    var arr = newJArray()
    for entry in entries:
      arr.add(%*{
        "name": entry.name,
        "kind": kindToText(entry.kind),
        "package": entry.owningPackage,
        "actionId": entry.actionId,
        "source-file": entry.sourceFile,
        "source-line": entry.sourceLine
      })
    var node = %*{
      "schemaId": "reprobuild.list-targets.v1",
      "projectRoot": info.projectRoot,
      "modulePath": info.modulePath,
      "targets": arr
    }
    if packageFilter.len > 0:
      node["package"] = %packageFilter
    echo $node
  else:
    if entries.len == 0:
      if packageFilter.len > 0:
        echo "repro build --list-targets: no targets for package=" &
          packageFilter
      else:
        echo "repro build --list-targets: no named targets in this project"
    else:
      echo "kind        package                   name                      source"
      for entry in entries:
        let source = entry.sourceFile & ":" & $entry.sourceLine
        echo kindToText(entry.kind) & "  " & entry.owningPackage & "  " &
          entry.name & "  " & source
  0

proc renderFocusedGraphJson(info: BuildGraphInspection; focus: string): JsonNode =
  let action = requireAction(info.actions, focus)
  %*{
    "schemaId": "reprobuild.graph.build.focus.v1",
    "graph": buildGraphInspectionJson(info),
    "focus": focus,
    "action": buildActionJson(action),
    "directDependencies": jsonStringSeq(directDependencies(info.actions, focus)),
    "directDependents": jsonStringSeq(directDependents(info.actions, focus))
  }

type
  StatsOutputFormat = enum
    sofText
    sofJson

  StatsActionRollup = object
    actionId: string
    statsKey: string
      ## The action's RunQuota stats key, carried from the spine row the
      ## extension row was joined to. It is what ties an action to the
      ## work RunQuota admitted, and it replaces the M7 store's
      ## project-local ``target`` field, which the shared store has no
      ## dimension for.
    resultSamples: int
    cacheSamples: int
    cacheHits: int
    cacheMisses: int
    launched: int
    inputSamples: int
    maxInputCount: int
    maxOutputCount: int

proc nowUnixMsCli(): int64 =
  let current = getTime()
  current.toUnix * 1000 + int64(current.nanosecond div 1_000_000)

proc parseStatsOutputFormat(value: string): StatsOutputFormat =
  case value.normalize()
  of "text":
    sofText
  of "json":
    sofJson
  else:
    raise newException(ValueError,
      "unsupported stats format: " & value & " (expected text or json)")

proc safeSnapshotLabel(label: string): string =
  if label.len == 0:
    raise newException(ValueError, "--label requires a non-empty value")
  for ch in label:
    if not (ch.isAlphaNumeric or ch in {'-', '_', '.'}):
      raise newException(ValueError,
        "unsupported snapshot label: " & label &
          " (use letters, digits, '.', '-', or '_')")
  if label == "." or label == ".." or label.contains(".."):
    raise newException(ValueError, "unsupported snapshot label: " & label)
  label

proc statsSnapshotPath(projectRoot, label: string): string =
  defaultStatsSnapshotDir(projectRoot) / (safeSnapshotLabel(label) & ".json")

proc statsWindowJson(view: SharedStoreView): JsonNode =
  ## THE QUALIFICATION EVERY REPORTED STATISTIC CARRIES (M18).
  ##
  ## Time window, sample count, and the host/hardware profiles the figures
  ## describe, plus the STATE that says whether they may be believed at
  ## all. ``observationCount`` is retained as the count of
  ## ``ext_repro_action`` rows in the window so the shape of this object is
  ## still the one ``repro stats`` documents; everything beside it is new
  ## and is what OS-2 and OS-6 require to be visible.
  result = windowJson(view)
  result["observationCount"] = %view.actionRows.len

proc unavailableReason(view: SharedStoreView): string =
  ## The reason a view carries when the shared store has no figures to
  ## render. NEVER "no data": each state has its own sentence, because the
  ## reader's next action differs for each and a view that collapses them
  ## has told the reader nothing.
  view.reason

proc actionRollups(view: SharedStoreView): Table[string, StatsActionRollup] =
  ## Rolled up from ``ext_repro_action`` rows read back over RQSP.
  ##
  ## ONE ROW PER EXECUTION, WHICH IS NOT ONE ROW PER ACTION. RunQuota's
  ## spine records executions, and a cache HIT is precisely the case where
  ## nothing executed — so the hit counted here is only the hit an
  ## execution reported, and ``docs/stats.md`` says so where a reader will
  ## find it.
  proc count(row: SharedActionRow; name: string): int =
    try:
      parseInt(row.value(name))
    except ValueError:
      0
  for row in view.actionRows:
    let actionId = row.value("action_id")
    if actionId.len == 0:
      continue
    var item = result.getOrDefault(actionId)
    item.actionId = actionId
    item.statsKey = row.statsKey
    inc item.resultSamples
    inc item.launched
    inc item.cacheSamples
    case row.value("cache_outcome")
    of "hit":
      inc item.cacheHits
    of "miss":
      inc item.cacheMisses
    else:
      discard
    inc item.inputSamples
    item.maxInputCount = max(item.maxInputCount,
      row.count("declared_inputs") + row.count("depfile_inputs") +
        row.count("monitor_reads") + row.count("monitor_probes"))
    item.maxOutputCount = max(item.maxOutputCount,
      row.count("declared_outputs") + row.count("monitor_writes"))
    result[actionId] = item

proc graphActionMap(info: BuildGraphInspection): Table[string, BuildAction] =
  for action in info.actions:
    result[action.id] = action

proc graphMetadataJson(info: BuildGraphInspection): JsonNode =
  %*{
    "target": info.target,
    "projectRoot": info.projectRoot,
    "modulePath": info.modulePath,
    "outDir": info.outDir,
    "providerCompileCacheHit": info.providerCompileCacheHit,
    "providerGraphCacheHit": info.providerGraphCacheHit,
    "loweredGraphCacheHit": info.loweredGraphCacheHit,
    "loweredGraphCachePath": info.loweredGraphCachePath
  }

proc unavailableStatsJson(command, scope, metric, projectRoot, storePath,
                          reason: string; view: SharedStoreView): JsonNode =
  %*{
    "schemaId": "reprobuild.stats.rank.v1",
    "command": command,
    "scope": scope,
    "metric": metric,
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "sampleCount": 0,
    "availability": {"available": false, "reason": reason},
    "rows": newJArray()
  }

proc storeUnavailableStatsJson(command, scope, metric, projectRoot,
                               storePath: string;
                               view: SharedStoreView): JsonNode =
  ## What a view renders when the shared store cannot answer.
  ##
  ## THE POINT OF THIS PROC IS THAT IT IS NOT A ZERO. An unreachable
  ## daemon, a daemon with capture off, a failed query and an empty store
  ## are four different states, and each arrives here carrying its own
  ## sentence. Rendering any of them as an empty ranking with
  ## ``available: true`` would present an absent sample as a complete one,
  ## which is exactly what OS-2 forbids.
  unavailableStatsJson(command, scope, metric, projectRoot, storePath,
    unavailableReason(view), view)

proc outputSizeForAction(projectRoot: string; action: BuildAction): BiggestInt =
  for output in action.outputs:
    let path = materialProjectPath(projectRoot, output)
    if fileExists(extendedPath(path)):
      result += getFileSize(extendedPath(path))

proc actionRankJson(projectRoot, storePath, metric: string; top: int;
                    view: SharedStoreView;
                    graphInfo: Option[BuildGraphInspection]): JsonNode =
  let rollups = actionRollups(view)
  let graphById =
    if graphInfo.isSome: graphActionMap(graphInfo.get())
    else: initTable[string, BuildAction]()
  let unavailable = {
    "build-time": "per-action durations are not projected into this view yet",
    "critical-path": "critical-path contribution needs per-action dynamic timings",
    "duration-variance": "duration variance needs multiple per-action duration samples",
    "peak-memory": "peak memory is not captured by this view",
    "queue-time": "queue time is not captured by this view"
  }.toTable
  if unavailable.hasKey(metric):
    return unavailableStatsJson("stats rank", "actions", metric, projectRoot,
      storePath, unavailable[metric], view)
  # THE STORE STATE IS CHECKED BEFORE ANY FIGURE IS COMPUTED, and after the
  # metric-support check so that "this metric is not projected" keeps its
  # own reason rather than being masked by a missing daemon.
  if not figuresArePresentable(view.state):
    return storeUnavailableStatsJson("stats rank", "actions", metric,
      projectRoot, storePath, view)

  var rows = newJArray()
  type Row = tuple[id: string; value: float; samples: int; evidence: JsonNode]
  var raw: seq[Row] = @[]
  case metric
  of "cache-hit-ratio":
    for id, item in rollups:
      if item.cacheSamples > 0:
        raw.add((id, float(item.cacheHits) / float(item.cacheSamples),
          item.cacheSamples, %*{
            "cacheHits": item.cacheHits,
            "cacheMisses": item.cacheMisses,
            "cacheSamples": item.cacheSamples
          }))
    raw.sort(proc(a, b: Row): int = cmp(a.value, b.value))
  of "cache-miss-count":
    for id, item in rollups:
      raw.add((id, float(item.cacheMisses), item.cacheSamples, %*{
        "cacheMisses": item.cacheMisses,
        "cacheSamples": item.cacheSamples
      }))
    raw.sort(proc(a, b: Row): int = cmp(b.value, a.value))
  of "input-count":
    for id, item in rollups:
      raw.add((id, float(item.maxInputCount), item.inputSamples, %*{
        "maxInputCount": item.maxInputCount,
        "inputSamples": item.inputSamples
      }))
    raw.sort(proc(a, b: Row): int = cmp(b.value, a.value))
  of "output-size":
    if graphInfo.isNone:
      return unavailableStatsJson("stats rank", "actions", metric, projectRoot,
        storePath, "output-size needs a materialized build graph", view)
    for id, action in graphById:
      raw.add((id, float(outputSizeForAction(projectRoot, action)), 1, %*{
        "outputs": jsonStringSeq(action.outputs)
      }))
    raw.sort(proc(a, b: Row): int = cmp(b.value, a.value))
  else:
    raise newException(ValueError,
      "unsupported actions metric: " & metric)

  let limit = if top <= 0: raw.len else: min(top, raw.len)
  for index in 0 ..< limit:
    let row = raw[index]
    var node = %*{
      "rank": index + 1,
      "id": row.id,
      "actionId": row.id,
      "value": row.value,
      "sampleCount": row.samples,
      "evidence": row.evidence,
      "nextCommand": "repro stats show --scope=actions --id " & row.id
    }
    if graphById.hasKey(row.id):
      node["commandStatsId"] = %graphById[row.id].commandStatsId
      node["graphCommand"] = %("repro graph --view=neighborhood --focus " & row.id)
    rows.add(node)
  result = %*{
    "schemaId": "reprobuild.stats.rank.v1",
    "command": "stats rank",
    "scope": "actions",
    "metric": metric,
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "sampleCount": rows.len,
    "availability": {"available": rows.len > 0, "reason": ""},
    "rows": rows
  }
  if graphInfo.isSome:
    result["graph"] = graphMetadataJson(graphInfo.get())
  if rows.len == 0:
    result["availability"]["reason"] = %"no matching action observations"

proc inputDependents(info: BuildGraphInspection; path: string): HashSet[string]
proc downstreamClosure(info: BuildGraphInspection; roots: HashSet[string]): HashSet[string]

proc inputRankJson(projectRoot, storePath, metric: string; top: int;
                   view: SharedStoreView;
                   graphInfo: Option[BuildGraphInspection]): JsonNode =
  ## STRUCTURAL, NOT HISTORICAL, and deliberately still so. Blast radius
  ## and fanout are properties of the build graph, so this view does not
  ## consult the shared store for its figures and does not become
  ## unavailable when no daemon is running. It still carries the store
  ## window, because the two historical metrics below are the ones that
  ## would need it.
  if metric in ["change-frequency", "critical-path-impact"]:
    return unavailableStatsJson("stats rank", "inputs", metric, projectRoot,
      storePath,
      if metric == "change-frequency":
        "changed input paths are not recorded on the shared store's spine"
      else:
        "critical-path impact needs per-action dynamic timings and input paths",
      view)
  if graphInfo.isNone:
    return unavailableStatsJson("stats rank", "inputs", metric, projectRoot,
      storePath, "input ranking needs a materialized build graph", view)
  if metric notin ["blast-radius", "fanout"]:
    raise newException(ValueError, "unsupported inputs metric: " & metric)

  let info = graphInfo.get()
  var paths = initHashSet[string]()
  for action in info.actions:
    for input in action.inputs:
      if input.len > 0:
        paths.incl(input)
  type Row = tuple[path: string; value: int; direct: int]
  var raw: seq[Row] = @[]
  for path in paths:
    let direct = inputDependents(info, path)
    let closure = downstreamClosure(info, direct)
    raw.add((path, if metric == "fanout": direct.len else: closure.len,
      direct.len))
  raw.sort(proc(a, b: Row): int =
    let byValue = cmp(b.value, a.value)
    if byValue != 0: byValue else: cmp(a.path, b.path))
  let limit = if top <= 0: raw.len else: min(top, raw.len)
  var rows = newJArray()
  for index in 0 ..< limit:
    let row = raw[index]
    rows.add(%*{
      "rank": index + 1,
      "path": row.path,
      "value": row.value,
      "sampleCount": 1,
      "evidence": {
        "directDependents": row.direct,
        "source": "build-graph-structure"
      },
      "graphCommand": "repro graph --view=blast-radius --path " & row.path
    })
  %*{
    "schemaId": "reprobuild.stats.rank.v1",
    "command": "stats rank",
    "scope": "inputs",
    "metric": metric,
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "sampleCount": rows.len,
    "availability": {
      "available": rows.len > 0,
      "reason": if rows.len == 0: "graph contains no declared inputs" else: ""
    },
    "graph": graphMetadataJson(info),
    "rows": rows
  }

proc targetRankJson(projectRoot, storePath, metric: string; top: int;
                    view: SharedStoreView): JsonNode =
  ## TARGETS HAVE NO DIMENSION ON THE SHARED STORE, AND THAT IS STATED
  ## RATHER THAN APPROXIMATED.
  ##
  ## RunQuota's execution spine records host, profile, stats key, owner
  ## and outcome; the reprobuild TARGET a build was invoked for is not one
  ## of them, and ``ext_repro_action`` version 1 does not carry it either.
  ## The M7 project-local store had it because it was written by the
  ## command that knew it.
  ##
  ## There are two ways to keep this view answering: attribute every row
  ## to the target of whichever invocation happens to be asking, or pool
  ## every row under one synthetic target. Both produce a number, and
  ## neither produces the number the caller asked for -- a ranking over
  ## one bucket is not a ranking, and attributing history to the current
  ## invocation is a figure about the question rather than about the work.
  ## OS-2 rules both out, so the view says what it cannot answer and names
  ## the dimension that would make it answerable.
  discard top
  if metric notin ["build-time", "cache-hit-ratio", "rebuild-count",
      "critical-path"]:
    raise newException(ValueError, "unsupported targets metric: " & metric)
  let reason =
    if metric == "critical-path":
      "critical path needs per-action dynamic timings"
    else:
      "the shared observation store carries no reprobuild target dimension; " &
        "rank by --scope=tools (RunQuota stats key) or --scope=actions instead"
  unavailableStatsJson("stats rank", "targets", metric, projectRoot,
    storePath, reason, view)

proc toolRankJson(projectRoot, storePath, metric: string; top: int;
                  view: SharedStoreView;
                  graphInfo: Option[BuildGraphInspection]): JsonNode =
  if metric in ["build-time", "queue-time", "duration-variance", "peak-memory"]:
    return unavailableStatsJson("stats rank", "tools", metric, projectRoot,
      storePath, "per-tool resource/timing is not projected into this view",
      view)
  if metric != "cache-hit-ratio":
    raise newException(ValueError, "unsupported tools metric: " & metric)
  if graphInfo.isNone:
    return unavailableStatsJson("stats rank", "tools", metric, projectRoot,
      storePath, "tool ranking needs a materialized build graph", view)
  if not figuresArePresentable(view.state):
    return storeUnavailableStatsJson("stats rank", "tools", metric,
      projectRoot, storePath, view)
  let actions = actionRollups(view)
  let graphById = graphActionMap(graphInfo.get())
  type Tool = object
    id: string
    samples: int
    hits: int
    misses: int
    actions: HashSet[string]
  var tools = initTable[string, Tool]()
  for actionId, rollup in actions:
    if rollup.cacheSamples == 0:
      continue
    # THE TOOL ID COMES OFF THE SPINE, not out of the graph. RunQuota's
    # ``stats_key`` IS reprobuild's command stats id, carried on the row
    # the daemon joined, so the identity a figure is grouped by is the
    # identity the measurement was recorded under rather than one
    # re-derived from a graph the measurement never saw.
    var toolId = rollup.statsKey
    if toolId.len == 0 and graphById.hasKey(actionId):
      toolId = graphById[actionId].commandStatsId
    if toolId.len == 0:
      toolId = "unknown-command-shape"
    var item = tools.getOrDefault(toolId)
    item.id = toolId
    item.samples += rollup.cacheSamples
    item.hits += rollup.cacheHits
    item.misses += rollup.cacheMisses
    item.actions.incl(actionId)
    tools[toolId] = item
  type Row = tuple[id: string; value: float; item: Tool]
  var raw: seq[Row] = @[]
  for id, item in tools:
    if item.samples > 0:
      raw.add((id, float(item.hits) / float(item.samples), item))
  raw.sort(proc(a, b: Row): int = cmp(a.value, b.value))
  let limit = if top <= 0: raw.len else: min(top, raw.len)
  var rows = newJArray()
  for index in 0 ..< limit:
    let row = raw[index]
    var actionIds: seq[string] = @[]
    for actionId in row.item.actions:
      actionIds.add(actionId)
    actionIds.sort()
    rows.add(%*{
      "rank": index + 1,
      "toolId": row.id,
      "value": row.value,
      "sampleCount": row.item.samples,
      "evidence": {
        "cacheHits": row.item.hits,
        "cacheMisses": row.item.misses,
        "actions": jsonStringSeq(actionIds)
      }
    })
  %*{
    "schemaId": "reprobuild.stats.rank.v1",
    "command": "stats rank",
    "scope": "tools",
    "metric": metric,
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "sampleCount": rows.len,
    "availability": {
      "available": rows.len > 0,
      "reason": if rows.len == 0: "no tool/cache observations" else: ""
    },
    "graph": graphMetadataJson(graphInfo.get()),
    "rows": rows
  }

proc renderStatsRankText(node: JsonNode): string =
  var lines: seq[string] = @[]
  let scope = node{"scope"}.getStr()
  let metric = node{"metric"}.getStr()
  let window = node{"window"}
  lines.add("Stats rank: scope=" & scope & " by=" & metric &
    " state=" & window{"state"}.getStr("unknown") &
    " samples=" & $window{"sampleCount"}.getInt(0) &
    " observations=" & $window{"observationCount"}.getInt(0) &
    " window=" & $window{"firstObservationUnixMs"}.getBiggestInt(0) & ".." &
    $window{"lastObservationUnixMs"}.getBiggestInt(0) & "ms")
  if not node{"availability"}{"available"}.getBool(false):
    lines.add("unavailable: " & node{"availability"}{"reason"}.getStr())
    return lines.join("\n") & "\n"
  for row in node{"rows"}:
    let name =
      if row.hasKey("actionId"): row{"actionId"}.getStr()
      elif row.hasKey("path"): row{"path"}.getStr()
      elif row.hasKey("target"): row{"target"}.getStr()
      elif row.hasKey("toolId"): row{"toolId"}.getStr()
      else: row{"id"}.getStr()
    lines.add(align($row{"rank"}.getInt(), 2) & "  " & name &
      "  value=" & formatFloat(row{"value"}.getFloat(), ffDecimal, 3) &
      "  samples=" & $row{"sampleCount"}.getInt(0))
  if node{"rows"}.len > 0:
    let first = node{"rows"}[0]
    if first.hasKey("graphCommand"):
      lines.add("next: " & first{"graphCommand"}.getStr())
    elif first.hasKey("nextCommand"):
      lines.add("next: " & first{"nextCommand"}.getStr())
  lines.join("\n") & "\n"

proc showActionStatsJson(projectRoot, storePath, actionId: string;
                         view: SharedStoreView;
                         graphInfo: Option[BuildGraphInspection]): JsonNode =
  if not figuresArePresentable(view.state):
    # NOT "unknown action". A missing daemon and an action the store has
    # never seen are different answers, and reporting the first as the
    # second would send a reader looking for a typo in the action id.
    raise newException(ValueError,
      "the shared observation store has no figures to show: " &
        unavailableReason(view))
  let rollups = actionRollups(view)
  if not rollups.hasKey(actionId):
    raise newException(ValueError, "unknown action in stats store: " & actionId)
  let item = rollups[actionId]
  var recent = newJArray()
  for row in view.actionRows:
    if row.value("action_id") != actionId:
      continue
    var values = newJObject()
    for i, name in row.columns:
      if i < row.values.len:
        values[name] = %row.values[i]
    recent.add(%*{
      "executionId": row.executionId,
      "statsKey": row.statsKey,
      "profile": profileJson(row.profile),
      "values": values
    })
  result = %*{
    "schemaId": "reprobuild.stats.show.v1",
    "command": "stats show",
    "scope": "actions",
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "id": actionId,
    "actionId": actionId,
    "rollup": {
      "resultSamples": item.resultSamples,
      "cacheSamples": item.cacheSamples,
      "cacheHits": item.cacheHits,
      "cacheMisses": item.cacheMisses,
      "launched": item.launched,
      "maxInputCount": item.maxInputCount,
      "maxOutputCount": item.maxOutputCount,
      "cacheHitRatio": if item.cacheSamples > 0:
        float(item.cacheHits) / float(item.cacheSamples) else: 0.0
    },
    "recentObservations": recent,
    "unavailableMetrics": jsonStringSeq([
      "per-action build-time",
      "critical-path contribution",
      "duration variance",
      "peak memory",
      "queue time"
    ]),
    "graphCommand": "repro graph --view=neighborhood --focus " & actionId
  }
  if graphInfo.isSome:
    let byId = graphActionMap(graphInfo.get())
    if byId.hasKey(actionId):
      result["graph"] = graphMetadataJson(graphInfo.get())
      result["action"] = buildActionJson(byId[actionId])

proc renderStatsShowText(node: JsonNode): string =
  var lines: seq[string] = @[]
  if node{"scope"}.getStr() == "actions":
    let rollup = node{"rollup"}
    lines.add("Stats action: " & node{"actionId"}.getStr())
    lines.add("samples: results=" & $rollup{"resultSamples"}.getInt(0) &
      " cache=" & $rollup{"cacheSamples"}.getInt(0) &
      " launched=" & $rollup{"launched"}.getInt(0))
    lines.add("cache: hits=" & $rollup{"cacheHits"}.getInt(0) &
      " misses=" & $rollup{"cacheMisses"}.getInt(0) &
      " ratio=" & formatFloat(rollup{"cacheHitRatio"}.getFloat(0.0),
        ffDecimal, 3))
    lines.add("dependency counts: inputs=" & $rollup{"maxInputCount"}.getInt(0) &
      " outputs=" & $rollup{"maxOutputCount"}.getInt(0))
    lines.add("next: " & node{"graphCommand"}.getStr())
  else:
    lines.add("Stats input: " & node{"path"}.getStr())
    lines.add("directDependents: " &
      $node{"rollup"}{"directDependents"}.getInt(0) &
      " blastRadius: " & $node{"rollup"}{"blastRadius"}.getInt(0))
    lines.add("observed change frequency: unavailable (changed input " &
      "paths are not recorded on the shared store's spine)")
    lines.add("next: " & node{"graphCommand"}.getStr())
  lines.join("\n") & "\n"

proc actionIdsJson(values: HashSet[string]): JsonNode =
  var ids: seq[string] = @[]
  for value in values:
    ids.add(value)
  ids.sort()
  jsonStringSeq(ids)

proc showInputStatsJson(projectRoot, storePath, path: string;
                        view: SharedStoreView;
                        graphInfo: Option[BuildGraphInspection]): JsonNode =
  if graphInfo.isNone:
    return %*{
      "schemaId": "reprobuild.stats.show.v1",
      "command": "stats show",
      "scope": "inputs",
      "projectRoot": projectRoot,
      "storePath": storePath,
      "window": statsWindowJson(view),
      "path": path,
      "availability": {
        "available": false,
        "reason": "input show needs a materialized build graph"
      }
    }
  let direct = inputDependents(graphInfo.get(), path)
  let closure = downstreamClosure(graphInfo.get(), direct)
  %*{
    "schemaId": "reprobuild.stats.show.v1",
    "command": "stats show",
    "scope": "inputs",
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "path": path,
    "availability": {"available": true, "reason": ""},
    "rollup": {
      "directDependents": direct.len,
      "blastRadius": closure.len,
      "observedChangeFrequency": newJNull(),
      "observedCriticalPathImpact": newJNull()
    },
    "directDependentActionIds": actionIdsJson(direct),
    "blastRadiusActionIds": actionIdsJson(closure),
    "graph": graphMetadataJson(graphInfo.get()),
    "graphCommand": "repro graph --view=blast-radius --path " & path
  }

proc snapshotJson(projectRoot, storePath, label: string;
                  view: SharedStoreView;
                  graphInfo: Option[BuildGraphInspection]): JsonNode =
  let actions = actionRankJson(projectRoot, storePath, "cache-miss-count", 0,
    view, graphInfo)
  let tools = toolRankJson(projectRoot, storePath, "cache-hit-ratio", 0,
    view, graphInfo)
  result = %*{
    "schemaId": "reprobuild.stats.snapshot.v1",
    "label": label,
    "createdAtUnixMs": nowUnixMsCli(),
    "projectRoot": projectRoot,
    "storePath": storePath,
    "window": statsWindowJson(view),
    "rollups": {
      "actionsByCacheMissCount": actions{"rows"},
      # THE TARGET ROLLUP IS GONE BECAUSE THE DIMENSION IS. A snapshot
      # that kept the key and filled it with an empty array would record
      # "no targets were slow" where the truth is "targets are not a
      # dimension of the store this snapshot is taken from". The tool
      # rollup replaces it: RunQuota's stats key is the identity the
      # measurements were actually recorded under.
      "toolsByCacheHitRatio": tools{"rows"}
    },
    "unavailableMetrics": jsonStringSeq([
      "per-action build-time",
      "critical-path",
      "duration-variance",
      "peak-memory",
      "queue-time",
      "input change-frequency",
      "input critical-path-impact"
    ])
  }
  if graphInfo.isSome:
    result["graph"] = graphMetadataJson(graphInfo.get())

proc renderSnapshotText(node: JsonNode; path: string): string =
  "stats snapshot: " & node{"label"}.getStr() &
    " observations=" & $node{"window"}{"observationCount"}.getInt(0) &
    " samples=" & $node{"window"}{"sampleCount"}.getInt(0) &
    " state=" & node{"window"}{"state"}.getStr("unknown") &
    "\npath: " & path & "\n"

proc rollupDeltaRows(baseRows, candRows: JsonNode; keyField: string): JsonNode =
  var baseByKey = initTable[string, JsonNode]()
  var candByKey = initTable[string, JsonNode]()
  var keys: seq[string] = @[]
  proc remember(key: string) =
    if key.len > 0 and keys.find(key) < 0:
      keys.add(key)
  if baseRows.kind == JArray:
    for row in baseRows:
      let key = row{keyField}.getStr()
      if key.len > 0:
        baseByKey[key] = row
        remember(key)
  if candRows.kind == JArray:
    for row in candRows:
      let key = row{keyField}.getStr()
      if key.len > 0:
        candByKey[key] = row
        remember(key)
  keys.sort()
  result = newJArray()
  for key in keys:
    let hasBase = baseByKey.hasKey(key)
    let hasCand = candByKey.hasKey(key)
    let baseValue = if hasBase: baseByKey[key]{"value"}.getFloat(0.0) else: 0.0
    let candValue = if hasCand: candByKey[key]{"value"}.getFloat(0.0) else: 0.0
    let baseSamples =
      if hasBase: baseByKey[key]{"sampleCount"}.getInt(0) else: 0
    let candSamples =
      if hasCand: candByKey[key]{"sampleCount"}.getInt(0) else: 0
    var row = newJObject()
    row[keyField] = %key
    row["baselineValue"] = if hasBase: %baseValue else: newJNull()
    row["candidateValue"] = if hasCand: %candValue else: newJNull()
    row["deltaValue"] = if hasBase and hasCand: %(candValue - baseValue) else: newJNull()
    row["baselineSampleCount"] = %baseSamples
    row["candidateSampleCount"] = %candSamples
    row["deltaSampleCount"] = %(candSamples - baseSamples)
    result.add(row)

proc compareSnapshotsJson(projectRoot, baseline, candidate: string): JsonNode =
  let baselinePath = statsSnapshotPath(projectRoot, baseline)
  let candidatePath = statsSnapshotPath(projectRoot, candidate)
  if not fileExists(baselinePath):
    raise newException(IOError, "stats snapshot not found: " & baseline)
  if not fileExists(candidatePath):
    raise newException(IOError, "stats snapshot not found: " & candidate)
  let base = parseFile(baselinePath)
  let cand = parseFile(candidatePath)
  %*{
    "schemaId": "reprobuild.stats.compare.v1",
    "command": "stats compare",
    "projectRoot": projectRoot,
    "baseline": {
      "label": baseline,
      "path": baselinePath,
      "window": base{"window"}
    },
    "candidate": {
      "label": candidate,
      "path": candidatePath,
      "window": cand{"window"}
    },
    "deltas": {
      "observationCount": cand{"window"}{"observationCount"}.getInt(0) -
        base{"window"}{"observationCount"}.getInt(0),
      "sampleCount": cand{"window"}{"sampleCount"}.getInt(0) -
        base{"window"}{"sampleCount"}.getInt(0),
      "actionCacheMissRows": cand{"rollups"}{"actionsByCacheMissCount"}.len -
        base{"rollups"}{"actionsByCacheMissCount"}.len,
      "toolCacheHitRatioRows": cand{"rollups"}{"toolsByCacheHitRatio"}.len -
        base{"rollups"}{"toolsByCacheHitRatio"}.len
    },
    "rollupDeltas": {
      "actionsByCacheMissCount": rollupDeltaRows(
        base{"rollups"}{"actionsByCacheMissCount"},
        cand{"rollups"}{"actionsByCacheMissCount"},
        "actionId"),
      "toolsByCacheHitRatio": rollupDeltaRows(
        base{"rollups"}{"toolsByCacheHitRatio"},
        cand{"rollups"}{"toolsByCacheHitRatio"},
        "toolId")
    },
    "notes": jsonStringSeq([
      "Compare uses current M7 rollups; per-action timing/resource deltas are unavailable until those metrics are captured."
    ])
  }

proc renderCompareText(node: JsonNode): string =
  let deltas = node{"deltas"}
  "stats compare: " & node{"baseline"}{"label"}.getStr() & " -> " &
    node{"candidate"}{"label"}.getStr() & "\n" &
    "delta observations: " & $deltas{"observationCount"}.getInt(0) & "\n" &
    "delta samples: " & $deltas{"sampleCount"}.getInt(0) & "\n" &
    "note: " & node{"notes"}[0].getStr() & "\n"

proc maybePrepareStatsGraph(projectRoot, target, publicCliPath, workRoot: string;
                            mode: ToolProvisioningMode): Option[BuildGraphInspection] =
  let graphTarget = if target.len > 0: target else: projectRoot
  try:
    return some(prepareBuildGraphInspection(graphTarget, mode, publicCliPath,
      selectDefaultAction = true, workRoot = workRoot))
  except CatchableError:
    return none(BuildGraphInspection)

proc defaultMetricForScope(scope: string): string =
  case scope
  of "actions":
    "cache-miss-count"
  of "inputs":
    "blast-radius"
  of "targets":
    "build-time"
  of "tools":
    "cache-hit-ratio"
  else:
    raise newException(ValueError, "unsupported stats scope: " & scope)

proc runStatsCommand(args: openArray[string]; publicCliPath: string): int =
  var view = "overview"
  var scope = ""
  var metric = ""
  var actionId = ""
  var inputPath = ""
  var label = ""
  var baseline = ""
  var candidate = ""
  var projectRoot = getCurrentDir()
  var target = ""
  var workRoot = ""
  var mode = tpmUnspecified
  var top = 10
  var format = sofText
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg in ["status", "overview", "rank", "show", "snapshot", "compare"]:
      view = arg
    elif arg == "--scope" or arg.startsWith("--scope="):
      scope = valueFromFlag(args, i, "--scope")
    elif arg == "--by" or arg.startsWith("--by="):
      metric = valueFromFlag(args, i, "--by")
    elif arg == "--id" or arg.startsWith("--id="):
      actionId = valueFromFlag(args, i, "--id")
    elif arg == "--path" or arg.startsWith("--path="):
      inputPath = valueFromFlag(args, i, "--path")
    elif arg == "--label" or arg.startsWith("--label="):
      label = valueFromFlag(args, i, "--label")
    elif arg == "--baseline" or arg.startsWith("--baseline="):
      baseline = valueFromFlag(args, i, "--baseline")
    elif arg == "--candidate" or arg.startsWith("--candidate="):
      candidate = valueFromFlag(args, i, "--candidate")
    elif arg == "--project-root" or arg.startsWith("--project-root="):
      projectRoot = valueFromFlag(args, i, "--project-root")
    elif arg == "--target" or arg.startsWith("--target="):
      target = valueFromFlag(args, i, "--target")
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--action-cache-root" or arg.startsWith("--action-cache-root="):
      setActionCacheRootOverride(valueFromFlag(args, i, "--action-cache-root"))
    elif arg == "--top" or arg.startsWith("--top="):
      top = parseInt(valueFromFlag(args, i, "--top"))
    elif arg == "--json":
      format = sofJson
    elif arg == "--format" or arg.startsWith("--format="):
      format = parseStatsOutputFormat(valueFromFlag(args, i, "--format"))
    elif arg == "--help" or arg == "-h":
      echo "usage: repro stats [status|overview|rank|show|snapshot|compare] [--format=text|json] [--project-root=PATH]"
      return 0
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported stats flag: " & arg)
    else:
      raise newException(ValueError, "unsupported stats view: " & arg)
    inc i

  projectRoot = absolutePath(projectRoot)
  let storePath = derivedStatsStorePath(projectRoot)
  # ONE QUERY PER INVOCATION, AND EVERY VIEW BELOW RENDERS FROM IT.
  # ``runquotad`` is the only sanctioned reader of the observation store,
  # so this is the whole of what ``repro stats`` can know about raw rows.
  let sharedStore = readSharedStore()
  case view
  of "status":
    stdout.write(statsStatusText(projectRoot, sharedStore))
  of "overview":
    stdout.write(statsOverviewText(projectRoot, sharedStore))
  of "rank":
    if scope.len == 0:
      raise newException(ValueError, "stats rank requires --scope")
    if metric.len == 0:
      metric = defaultMetricForScope(scope)
    let needsGraph = scope in ["inputs", "tools"] or
      (scope == "actions" and metric == "output-size")
    let graphInfo =
      if needsGraph:
        maybePrepareStatsGraph(projectRoot, target, publicCliPath, workRoot, mode)
      else:
        none(BuildGraphInspection)
    let outputNode =
      case scope
      of "actions":
        actionRankJson(projectRoot, storePath, metric, top, sharedStore,
          graphInfo)
      of "inputs":
        inputRankJson(projectRoot, storePath, metric, top, sharedStore,
          graphInfo)
      of "targets":
        targetRankJson(projectRoot, storePath, metric, top, sharedStore)
      of "tools":
        toolRankJson(projectRoot, storePath, metric, top, sharedStore,
          graphInfo)
      else:
        raise newException(ValueError, "unsupported stats scope: " & scope)
    if format == sofJson:
      echo $outputNode
    else:
      stdout.write(renderStatsRankText(outputNode))
  of "show":
    if scope.len == 0:
      raise newException(ValueError, "stats show requires --scope")
    let needsGraph = scope == "inputs"
    let graphInfo =
      if needsGraph or actionId.len > 0:
        maybePrepareStatsGraph(projectRoot, target, publicCliPath, workRoot, mode)
      else:
        none(BuildGraphInspection)
    let outputNode =
      case scope
      of "actions":
        if actionId.len == 0:
          raise newException(ValueError, "stats show --scope=actions requires --id")
        showActionStatsJson(projectRoot, storePath, actionId, sharedStore,
          graphInfo)
      of "inputs":
        if inputPath.len == 0:
          raise newException(ValueError, "stats show --scope=inputs requires --path")
        showInputStatsJson(projectRoot, storePath, inputPath, sharedStore,
          graphInfo)
      else:
        raise newException(ValueError, "unsupported stats show scope: " & scope)
    if format == sofJson:
      echo $outputNode
    else:
      stdout.write(renderStatsShowText(outputNode))
  of "snapshot":
    if label.len == 0:
      raise newException(ValueError, "stats snapshot requires --label")
    let graphInfo = maybePrepareStatsGraph(projectRoot, target, publicCliPath,
      workRoot, mode)
    let outputNode = snapshotJson(projectRoot, storePath,
      safeSnapshotLabel(label), sharedStore, graphInfo)
    let path = statsSnapshotPath(projectRoot, label)
    createDir(parentDir(path))
    writeFile(path, pretty(outputNode))
    if format == sofJson:
      echo $outputNode
    else:
      stdout.write(renderSnapshotText(outputNode, path))
  of "compare":
    if baseline.len == 0 or candidate.len == 0:
      raise newException(ValueError,
        "stats compare requires --baseline and --candidate")
    let outputNode = compareSnapshotsJson(projectRoot, baseline, candidate)
    if format == sofJson:
      echo $outputNode
    else:
      stdout.write(renderCompareText(outputNode))
  else:
    raise newException(ValueError, "unsupported stats view: " & view)
  0

proc normalizedGraphPath(projectRoot, path: string): string =
  let material = materialProjectPath(projectRoot, path)
  try:
    os.normalizedPath(material)
  except CatchableError:
    material.replace('\\', '/')

proc pathMatches(projectRoot, candidate, query: string): bool =
  if candidate == query:
    return true
  normalizedGraphPath(projectRoot, candidate) == normalizedGraphPath(projectRoot, query)

proc actionUsesPath(info: BuildGraphInspection; action: BuildAction;
                    path: string): bool =
  for input in action.inputs:
    if pathMatches(info.projectRoot, input, path):
      return true
  if action.depfile.len > 0 and pathMatches(info.projectRoot, action.depfile, path):
    return true
  if action.dynamicDepsFile.len > 0 and
      pathMatches(info.projectRoot, action.dynamicDepsFile, path):
    return true
  if action.monitorDepfile.len > 0 and
      pathMatches(info.projectRoot, action.monitorDepfile, path):
    return true

proc inputDependents(info: BuildGraphInspection; path: string): HashSet[string] =
  for action in info.actions:
    if actionUsesPath(info, action, path):
      result.incl(action.id)

proc downstreamClosure(info: BuildGraphInspection; roots: HashSet[string]): HashSet[string] =
  var queue: seq[string] = @[]
  for root in roots:
    if not result.contains(root):
      result.incl(root)
      queue.add(root)
  var head = 0
  while head < queue.len:
    let current = queue[head]
    inc head
    for dependent in directDependents(info.actions, current):
      if not result.contains(dependent):
        result.incl(dependent)
        queue.add(dependent)

proc edgeJson(fromId, toId, kind: string): JsonNode =
  %*{"from": fromId, "to": toId, "kind": kind}

proc analysisBaseJson(info: BuildGraphInspection; view: string): JsonNode =
  %*{
    "schemaId": "reprobuild.graph.analysis-view.v1",
    "command": "graph",
    "view": view,
    "target": info.target,
    "projectRoot": info.projectRoot,
    "graph": graphMetadataJson(info)
  }

proc graphNeighborhoodJson(info: BuildGraphInspection; focus: string): JsonNode =
  let action = requireAction(info.actions, focus)
  let deps = directDependencies(info.actions, focus)
  let dependents = directDependents(info.actions, focus)
  var nodes = newJArray()
  var edges = newJArray()
  nodes.add(buildActionJson(action))
  for dep in deps:
    nodes.add(buildActionJson(requireAction(info.actions, dep)))
    edges.add(edgeJson(dep, focus, "dependency"))
  for dependent in dependents:
    nodes.add(buildActionJson(requireAction(info.actions, dependent)))
    edges.add(edgeJson(focus, dependent, "dependency"))
  result = analysisBaseJson(info, "neighborhood")
  result["focus"] = %focus
  result["actions"] = nodes
  result["edges"] = edges
  result["directDependencies"] = jsonStringSeq(deps)
  result["directDependents"] = jsonStringSeq(dependents)

proc graphInputsJson(info: BuildGraphInspection; focus: string): JsonNode =
  let action = requireAction(info.actions, focus)
  result = analysisBaseJson(info, "inputs")
  result["focus"] = %focus
  result["actionId"] = %focus
  result["inputs"] = jsonStringSeq(action.inputs)
  result["outputs"] = jsonStringSeq(action.outputs)
  result["depfile"] = %action.depfile
  result["dynamicDepsFile"] = %action.dynamicDepsFile
  result["monitorDepfile"] = %action.monitorDepfile
  result["dependencyPolicy"] = dependencyPolicyJson(action.dependencyPolicy)
  result["note"] = %"This graph view reports static graph inputs and dependency policy; dynamic path identities require captured dependency reports."

proc graphDependentsJson(info: BuildGraphInspection; path: string): JsonNode =
  let direct = inputDependents(info, path)
  let closure = downstreamClosure(info, direct)
  result = analysisBaseJson(info, "dependents")
  result["path"] = %path
  result["directDependentActionIds"] = actionIdsJson(direct)
  result["dependentActionIds"] = actionIdsJson(closure)
  result["directDependentCount"] = %direct.len
  result["dependentCount"] = %closure.len

proc graphBlastRadiusJson(info: BuildGraphInspection; path: string): JsonNode =
  let direct = inputDependents(info, path)
  let closure = downstreamClosure(info, direct)
  var targetOutputs = newJArray()
  for action in info.actions:
    if closure.contains(action.id):
      for output in action.outputs:
        targetOutputs.add(%*{"actionId": action.id, "path": output})
  result = analysisBaseJson(info, "blast-radius")
  result["path"] = %path
  result["directDependentActionIds"] = actionIdsJson(direct)
  result["blastRadiusActionIds"] = actionIdsJson(closure)
  result["directDependentCount"] = %direct.len
  result["blastRadiusCount"] = %closure.len
  result["affectedOutputs"] = targetOutputs
  result["note"] = %"Structural graph blast radius; historical observed impact belongs to repro stats rank --scope=inputs --by=blast-radius."

proc graphCriticalPathJson(info: BuildGraphInspection; run: string): JsonNode =
  ## THE SELECTED RUN IS NO LONGER GUESSED FROM A LOCAL FILE. The M7
  ## project-local JSONL store carried a ``runId`` per observation and this
  ## view picked the last one out of it; that store is retired, and
  ## RunQuota's query interface does not expose the ``runs`` table, so
  ## ``--run=last`` has nothing to resolve against. Reporting an empty
  ## string as though it were a resolved run id would be a fabricated
  ## answer, so the view resolves only what the caller named.
  result = analysisBaseJson(info, "critical-path")
  result["run"] = %run
  result["selectedRunId"] = %(if run == "last": "" else: run)
  result["availability"] = %*{
    "available": false,
    "reason": "per-action dynamic durations required for critical path " &
      "reconstruction are not projected from the shared observation store"
  }
  result["criticalPath"] = newJArray()
  result["sampleCount"] = %0

proc graphPartitionCandidatesJson(info: BuildGraphInspection; kind: string): JsonNode =
  result = analysisBaseJson(info, "partition-candidates")
  result["kind"] = %kind
  result["availability"] = %*{
    "available": false,
    "reason": "deferred/experimental: linker-level object and symbol evidence is not collected yet"
  }
  result["candidates"] = newJArray()

proc renderGraphAnalysisText(node: JsonNode): string =
  var lines: seq[string] = @[]
  let view = node{"view"}.getStr()
  lines.add("graph view: " & view)
  case view
  of "neighborhood":
    lines.add("focus: " & node{"focus"}.getStr())
    lines.add("directDependencies: " &
      (if node{"directDependencies"}.len > 0:
        node{"directDependencies"}.getElems().mapIt(it.getStr()).join(", ")
      else: "-"))
    lines.add("directDependents: " &
      (if node{"directDependents"}.len > 0:
        node{"directDependents"}.getElems().mapIt(it.getStr()).join(", ")
      else: "-"))
  of "inputs":
    lines.add("focus: " & node{"focus"}.getStr())
    lines.add("inputs: " & $node{"inputs"}.len)
    for item in node{"inputs"}:
      lines.add("  input: " & item.getStr())
    lines.add("outputs: " & $node{"outputs"}.len)
  of "dependents":
    lines.add("path: " & node{"path"}.getStr())
    lines.add("directDependents: " & $node{"directDependentCount"}.getInt(0))
    lines.add("dependents: " & $node{"dependentCount"}.getInt(0))
  of "blast-radius":
    lines.add("path: " & node{"path"}.getStr())
    lines.add("directDependents: " & $node{"directDependentCount"}.getInt(0))
    lines.add("blastRadius: " & $node{"blastRadiusCount"}.getInt(0))
  of "critical-path":
    lines.add("run: " & node{"selectedRunId"}.getStr())
    lines.add("unavailable: " & node{"availability"}{"reason"}.getStr())
  of "partition-candidates":
    lines.add("kind: " & node{"kind"}.getStr())
    lines.add("deferred: " & node{"availability"}{"reason"}.getStr())
  else:
    lines.add("unsupported view")
  lines.join("\n") & "\n"

proc runGraphCommand(args: openArray[string]; publicCliPath: string): int =
  var target = ""
  var view = "actions"
  var focus = ""
  var path = ""
  var runId = ""
  var kind = ""
  var mode = tpmUnspecified
  var workRoot = ""
  var format = gofText
  var positionals: seq[string] = @[]
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--build":
      inc i
    elif arg == "--view" or arg.startsWith("--view="):
      view = valueFromFlag(args, i, "--view")
      inc i
    elif arg in ["--lock", "--infra", "--all"]:
      raise newException(ValueError,
        arg & " is not implemented yet; use repro lock visualize/debug for " &
          "solved package graph inspection")
    elif arg.startsWith("--focus="):
      focus = arg.split("=", maxsplit = 1)[1]
      inc i
    elif arg == "--focus":
      if i + 1 >= args.len:
        raise newException(ValueError, "--focus requires a value")
      focus = args[i + 1]
      inc i, 2
    elif arg == "--path" or arg.startsWith("--path="):
      path = valueFromFlag(args, i, "--path")
      inc i
    elif arg == "--run" or arg.startsWith("--run="):
      runId = valueFromFlag(args, i, "--run")
      inc i
    elif arg == "--kind" or arg.startsWith("--kind="):
      kind = valueFromFlag(args, i, "--kind")
      inc i
    elif arg == "--target" or arg.startsWith("--target="):
      target = valueFromFlag(args, i, "--target")
      inc i
    elif arg == "--json":
      format = gofJson
      inc i
    elif arg == "--dot":
      format = gofDot
      inc i
    elif arg.startsWith("--format="):
      format = parseGraphOutputFormat(arg.split("=", maxsplit = 1)[1],
        allowDot = true)
      inc i
    elif arg == "--format":
      if i + 1 >= args.len:
        raise newException(ValueError, "--format requires a value")
      format = parseGraphOutputFormat(args[i + 1], allowDot = true)
      inc i, 2
    elif arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(arg.split("=", maxsplit = 1)[1])
      inc i
    elif arg == "--tool-provisioning":
      if i + 1 >= args.len:
        raise newException(ValueError, "--tool-provisioning requires a value")
      mode = parseToolProvisioning(args[i + 1])
      inc i, 2
    elif arg.startsWith("--work-root="):
      workRoot = arg.split("=", maxsplit = 1)[1]
      inc i
    elif arg == "--work-root":
      if i + 1 >= args.len:
        raise newException(ValueError, "--work-root requires a value")
      workRoot = args[i + 1]
      inc i, 2
    elif arg.startsWith("--action-cache-root="):
      setActionCacheRootOverride(arg.split("=", maxsplit = 1)[1])
      inc i
    elif arg == "--action-cache-root":
      if i + 1 >= args.len:
        raise newException(ValueError, "--action-cache-root requires a value")
      setActionCacheRootOverride(args[i + 1])
      inc i, 2
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported graph flag: " & arg)
    else:
      positionals.add(arg)
      inc i

  if positionals.len > 2:
    raise newException(ValueError,
      "unexpected graph arguments: " & positionals[2 .. ^1].join(" "))
  if positionals.len >= 1:
    target = positionals[0]
  if positionals.len >= 2:
    focus = positionals[1]
  let targetWasOmitted = target.len == 0
  # Named-Targets M5: if the first positional is a bare or
  # qualified name (not a path/fragment selector), route it through
  # the shared resolver. The project anchor stays the current
  # directory; the resolved action id flows into ``focus`` so the
  # downstream `--view=neighborhood`/`--view=inputs` paths and the
  # `actions` / `text` renderers receive it as their focal action.
  var nameSelector = ""
  if not targetWasOmitted:
    let classified = classifyBuildSelector(target)
    if classified.kind in {bskName, bskQualified}:
      nameSelector = target
      target = "."
  if target.len == 0:
    target = "."

  var autoRunQuota = startAutoRunQuotaIfNeeded(runQuotaBypassedByEnv())
  try:
    let info = prepareBuildGraphInspection(target, mode, publicCliPath,
      # Preserve the project anchor while selecting the named target as the
      # lowering root. This includes explicitly requested test/lint/bench
      # closures that an unselected graph intentionally omits.
      selectDefaultAction = targetWasOmitted,
      workRoot = workRoot,
      selectedActionOverride = nameSelector)
    if nameSelector.len > 0:
      var actionIds: seq[string] = @[]
      for action in info.actions:
        actionIds.add(action.id)
      let resolution = resolveTargetExportSelector(info.targetExportTable,
        actionIds, info.explicitTargetNames, nameSelector)
      case resolution.kind
      of trkResolved:
        # Aggregate and collection selectors lower a multi-action closure and
        # therefore have no single focus action. A legacy explicit-target
        # fallback can likewise resolve to the target name rather than an
        # action id. Keep the full selected graph in both cases.
        if resolution.targetKind notin {tekAggregate, tekCollection} and
            resolution.actionId in actionIds:
          focus = resolution.actionId
        else:
          focus = ""
      of trkAmbiguous:
        var err = newException(BuildTargetAmbiguousError,
          "target '" & nameSelector &
            "' is exported by multiple packages: " &
            resolution.candidates.join(", ") &
            " — re-run with the qualified <package>:<name> form")
        err.selectorName = nameSelector
        err.candidates = resolution.candidates
        raise err
      of trkUnknown:
        var err = newException(BuildTargetUnknownError,
          "unknown build target: " & nameSelector)
        err.selectorName = nameSelector
        err.suggestions = resolution.suggestions
        raise err
    if view == "actions":
      discard
    elif view == "env":
      # STAGE 2's instrument, and the one that answers "does a host
      # difference invalidate this graph?" without guessing.
      #
      # One line per process action: the weak fingerprint the action
      # cache is keyed by, followed by the environment declaration that
      # produced it. Two runs under two different hosts diff to exactly
      # the set of edges that would rebuild. The alternative — asserting
      # from the source that nothing host-varying reaches the key — is
      # how a regression here would be missed, because the reasoning and
      # the code drift apart silently.
      #
      # It lives in the CLI rather than a transcript because a
      # measurement that exists only in a transcript is a measurement
      # nobody can repeat.
      var census: EnvironmentInheritanceCensus
      var lines: seq[string] = @[]
      for action in info.actions:
        if action.kind != bakProcess:
          continue
        inc census.totalActions
        if action.env.len > 0: inc census.declaringActions
        if action.envPassthrough.len > 0: inc census.passthroughActions
        if action.env.len == 0 and action.envPassthrough.len == 0:
          inc census.undeclaredActions
        var declaredNames: seq[string] = @[]
        for entry in action.env:
          let eq = entry.find('=')
          if eq > 0:
            declaredNames.add(entry[0 ..< eq])
        declaredNames.sort()
        var passthroughNames = @(action.envPassthrough)
        passthroughNames.sort()
        lines.add(toHex(action.weakFingerprint.bytes) & " " & action.id &
          " declared=[" & declaredNames.join(",") & "]" &
          " passthrough=[" & passthroughNames.join(",") & "]")
      lines.sort()
      echo environmentInheritanceHeaderLine(census)
      for line in lines:
        echo line
      return 0
    elif view == "neighborhood":
      if focus.len == 0:
        focus = info.selectedActionId
      if focus.len == 0:
        raise newException(ValueError, "--view=neighborhood requires --focus")
      let outputNode = graphNeighborhoodJson(info, focus)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        echo renderBuildGraphDot(info, focus)
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    elif view == "inputs":
      if focus.len == 0:
        focus = info.selectedActionId
      if focus.len == 0:
        raise newException(ValueError, "--view=inputs requires --focus")
      let outputNode = graphInputsJson(info, focus)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        raise newException(ValueError, "dot format is not supported for --view=inputs")
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    elif view == "dependents":
      if path.len == 0:
        raise newException(ValueError, "--view=dependents requires --path")
      let outputNode = graphDependentsJson(info, path)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        raise newException(ValueError, "dot format is not supported for --view=dependents")
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    elif view == "blast-radius":
      if path.len == 0:
        raise newException(ValueError, "--view=blast-radius requires --path")
      let outputNode = graphBlastRadiusJson(info, path)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        raise newException(ValueError, "dot format is not supported for --view=blast-radius")
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    elif view == "critical-path":
      if runId.len == 0:
        raise newException(ValueError, "--view=critical-path requires --run")
      let outputNode = graphCriticalPathJson(info, runId)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        raise newException(ValueError, "dot format is not supported for --view=critical-path")
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    elif view == "partition-candidates":
      if kind.len == 0:
        kind = "dylib"
      let outputNode = graphPartitionCandidatesJson(info, kind)
      if format == gofJson:
        echo $outputNode
      elif format == gofDot:
        raise newException(ValueError, "dot format is not supported for --view=partition-candidates")
      else:
        stdout.write(renderGraphAnalysisText(outputNode))
      return 0
    else:
      raise newException(ValueError, "unsupported graph view: " & view)
    case format
    of gofText:
      echo renderBuildGraphText(info, focus)
    of gofJson:
      if focus.len > 0:
        echo $renderFocusedGraphJson(info, focus)
      else:
        echo $buildGraphInspectionJson(info)
    of gofDot:
      echo renderBuildGraphDot(info, focus)
    return 0
  finally:
    releaseAutoRunQuotaProcess(autoRunQuota)

proc latestReportAction(info: BuildGraphInspection; actionId: string): Option[JsonNode] =
  let reportPath = info.outDir / "build-report.json"
  if not fileExists(extendedPath(reportPath)):
    return none(JsonNode)
  try:
    let report = parseFile(extendedPath(reportPath))
    for section in ["actions", "providerCompileActions", "cmakeRegenerationActions"]:
      for action in report{section}:
        if action{"id"}.getStr() == actionId:
          return some(action)
  except CatchableError:
    return none(JsonNode)

proc shortestActionPath(actions: openArray[BuildAction];
                        roots: openArray[string];
                        subject: string): seq[string] =
  let byId = buildActionById(actions)
  if not byId.hasKey(subject):
    discard requireAction(actions, subject)
  var queue: seq[string] = @[]
  var parent = initTable[string, string]()
  var seen = initHashSet[string]()
  for root in roots:
    if root.len > 0 and byId.hasKey(root) and not seen.contains(root):
      queue.add(root)
      seen.incl(root)
      parent[root] = ""
  var head = 0
  while head < queue.len:
    let current = queue[head]
    inc head
    if current == subject:
      var node = current
      while node.len > 0:
        result.add(node)
        node = parent[node]
      result.reverse()
      return
    for dep in byId[current].deps:
      if byId.hasKey(dep) and not seen.contains(dep):
        seen.incl(dep)
        parent[dep] = current
        queue.add(dep)

proc jsonArrayLength(node: JsonNode; key: string): int =
  if node.kind == JObject and node.hasKey(key) and node[key].kind == JArray:
    node[key].len
  else:
    0

proc evidenceCountsJsonFromReport(action: JsonNode): JsonNode =
  let evidence = action{"evidence"}
  %*{
    "declaredInputs": evidence.jsonArrayLength("declaredInputs"),
    "declaredOutputs": evidence.jsonArrayLength("declaredOutputs"),
    "depfileInputs": evidence.jsonArrayLength("depfileInputs"),
    "monitorReads": evidence.jsonArrayLength("monitorReads"),
    "monitorWrites": evidence.jsonArrayLength("monitorWrites"),
    "monitorProbes": evidence.jsonArrayLength("monitorProbes"),
    "diagnostics": evidence.jsonArrayLength("diagnostics")
  }

proc whyActionJson(info: BuildGraphInspection; actionId: string): JsonNode =
  let action = requireAction(info.actions, actionId)
  let roots =
    if info.selectedActionId.len > 0:
      @[info.selectedActionId]
    else:
      newSeq[string]()
  let path = shortestActionPath(info.actions, roots, actionId)
  let report = latestReportAction(info, actionId)
  var node = %*{
    "schemaId": "reprobuild.why.action.v1",
    "subjectKind": "action",
    "subject": actionId,
    "selectedActionId": info.selectedActionId,
    "defaultActionId": info.defaultActionId,
    "path": jsonStringSeq(path),
    "directDependencies": jsonStringSeq(directDependencies(info.actions, actionId)),
    "directDependents": jsonStringSeq(directDependents(info.actions, actionId)),
    "action": buildActionJson(action),
    # Named-Lock-Files §6.3. The identity is the key; the names are
    # provenance, carried as an ARRAY so a consumer sees the whole set rather
    # than whichever name happened to be recorded first.
    "governingLockIdentity": %($action.governingLockIdentity),
    "lockFileNames": jsonStringSeq(
      lockProvenance().namesFor(action.governingLockIdentity))
  }
  if report.isSome:
    let item = report.get()
    node["lastResult"] = item
    node["evidenceCounts"] = evidenceCountsJsonFromReport(item)
  else:
    node["lastResult"] = newJNull()
    node["evidenceCounts"] = newJNull()
  node

proc optionalReportField(action: JsonNode; key: string): string =
  if action.kind == JObject and action.hasKey(key):
    let value = action[key]
    case value.kind
    of JString:
      result = value.getStr()
    of JInt:
      result = $value.getInt()
    of JFloat:
      result = $value.getFloat()
    of JBool:
      result = $value.getBool()
    of JNull:
      result = ""
    else:
      result = $value

proc renderWhyActionText(info: BuildGraphInspection; actionId: string): string =
  let action = requireAction(info.actions, actionId)
  let roots =
    if info.selectedActionId.len > 0:
      @[info.selectedActionId]
    else:
      newSeq[string]()
  let path = shortestActionPath(info.actions, roots, actionId)
  var lines: seq[string] = @[]
  lines.add("why action " & actionId)
  if info.selectedActionId.len > 0:
    lines.add("selectedAction: " & info.selectedActionId)
  elif info.defaultActionId.len > 0:
    lines.add("defaultAction: " & info.defaultActionId)
  if path.len > 0:
    lines.add("path: " & path.join(" -> "))
  else:
    lines.add("path: not rooted by the selected action; present in full graph")
  let deps = directDependencies(info.actions, actionId)
  let dependents = directDependents(info.actions, actionId)
  lines.add("directDependencies: " &
    (if deps.len > 0: deps.join(", ") else: "-"))
  lines.add("directDependents: " &
    (if dependents.len > 0: dependents.join(", ") else: "-"))
  lines.add("command: " & commandDisplay(action))
  # Named-Lock-Files §6.3 / corpus NLF-ID-5. Which lock file governs this
  # edge, and — when more than one name resolved to it — that the names
  # resolved identically and their artifacts are SHARED. Presented as
  # sharing, never as a warning: §6.3 is explicit that "a collision in the
  # provenance table means genuine sharing, not a lost name … It is a success
  # condition."
  for line in lockProvenanceReportLines(lockProvenance(),
      action.governingLockIdentity):
    lines.add(line)
  lines.add("dependencyPolicy: " & $action.dependencyPolicy.kind &
    " completeness=" & $action.dependencyPolicy.completeness)
  let report = latestReportAction(info, actionId)
  if report.isSome:
    let item = report.get()
    lines.add("lastResult: status=" & item.optionalReportField("status") &
      " cache=" & item.optionalReportField("cacheDecision") &
      " launched=" & item.optionalReportField("launched") &
      " wouldLaunch=" & item.optionalReportField("wouldLaunch") &
      (if item.optionalReportField("reason").len > 0:
        " reason=" & item.optionalReportField("reason")
      else:
        ""))
    let counts = evidenceCountsJsonFromReport(item)
    lines.add("evidenceCounts: declaredInputs=" &
      $counts["declaredInputs"].getInt() &
      " declaredOutputs=" & $counts["declaredOutputs"].getInt() &
      " depfileInputs=" & $counts["depfileInputs"].getInt() &
      " monitorReads=" & $counts["monitorReads"].getInt() &
      " monitorWrites=" & $counts["monitorWrites"].getInt() &
      " monitorProbes=" & $counts["monitorProbes"].getInt() &
      " diagnostics=" & $counts["diagnostics"].getInt())
  else:
    lines.add("lastResult: no build-report.json entry")
  lines.join("\n")

const
  WhySelectedReason* =
    "a non-dormant edge in this solved graph required this package"
    ## NLF-M9 — the `repro why` wording for a SELECTED package instance.
    ## Exported so a test asserts on the product's own string rather than a
    ## copy of it that can drift.
  WhyUnselectedReason* =
    "nothing selected it — no non-dormant edge in this solved graph " &
    "required this package"
    ## NLF-M9 — the wording for an UNSELECTED instance.
    ##
    ## **Phrased as information, not as a warning**, and deliberately so. §5.6
    ## leaves open whether such an instance should appear in the lock at all,
    ## whether it enters `lockIdentity`, and whether its metadata is material;
    ## a diagnostic that said "warning" or "unused — remove it" would be this
    ## command answering those questions on the user's behalf. It reports what
    ## the solve recorded and stops.

proc selectionStatusOf(sol: UnifiedSolution; name: string): SelectionStatus =
  ## The recorded status of one package instance, for a name already known to
  ## be IN `sol.packages`.
  ##
  ## Absence of an entry is not "unselected": both producers (`solve()` and
  ## `lockToSolution`) populate an entry for every package they put in the
  ## graph, so a missing entry means the record predates NLF-M9, and the
  ## status-quo reading of such a record is that every instance was required.
  if name in sol.selected: sol.selected[name] else: ssSelected

proc renderWhyPackageText(sol: UnifiedSolution; name, graphSource,
                          lockPath: string): string =
  let status = selectionStatusOf(sol, name)
  var lines: seq[string] = @[]
  lines.add("package: " & name)
  lines.add("version: " & sol.packages[name])
  lines.add("selection: " & $status)
  lines.add("why: " &
    (if status == ssSelected: WhySelectedReason else: WhyUnselectedReason))
  lines.add("graph: " & graphSource &
    (if graphSource == "lock" and lockPath.len > 0: " (" & lockPath & ")"
     else: ""))
  lines.join("\n")

proc whyPackageJson(sol: UnifiedSolution; name, graphSource,
                    lockPath: string): JsonNode =
  let status = selectionStatusOf(sol, name)
  result = newJObject()
  result["package"] = %name
  result["version"] = %sol.packages[name]
  result["selection"] = %($status)
  result["reason"] = %(
    if status == ssSelected: WhySelectedReason else: WhyUnselectedReason)
  result["graphSource"] = %graphSource
  if graphSource == "lock":
    result["lockPath"] = %lockPath

proc runWhyCommand(args: openArray[string]; publicCliPath: string): int =
  var subject = ""
  var target = ""
  var mode = tpmUnspecified
  var workRoot = ""
  var format = gofText
  var explicitAction = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg.startsWith("--action="):
      subject = arg.split("=", maxsplit = 1)[1]
      explicitAction = true
      inc i
    elif arg == "--action":
      if i + 1 >= args.len:
        raise newException(ValueError, "--action requires a value")
      subject = args[i + 1]
      explicitAction = true
      inc i, 2
    elif arg == "--json":
      format = gofJson
      inc i
    elif arg.startsWith("--format="):
      format = parseGraphOutputFormat(arg.split("=", maxsplit = 1)[1],
        allowDot = false)
      inc i
    elif arg == "--format":
      if i + 1 >= args.len:
        raise newException(ValueError, "--format requires a value")
      format = parseGraphOutputFormat(args[i + 1], allowDot = false)
      inc i, 2
    elif arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(arg.split("=", maxsplit = 1)[1])
      inc i
    elif arg == "--tool-provisioning":
      if i + 1 >= args.len:
        raise newException(ValueError, "--tool-provisioning requires a value")
      mode = parseToolProvisioning(args[i + 1])
      inc i, 2
    elif arg.startsWith("--work-root="):
      workRoot = arg.split("=", maxsplit = 1)[1]
      inc i
    elif arg == "--work-root":
      if i + 1 >= args.len:
        raise newException(ValueError, "--work-root requires a value")
      workRoot = args[i + 1]
      inc i, 2
    elif arg.startsWith("--action-cache-root="):
      setActionCacheRootOverride(arg.split("=", maxsplit = 1)[1])
      inc i
    elif arg == "--action-cache-root":
      if i + 1 >= args.len:
        raise newException(ValueError, "--action-cache-root requires a value")
      setActionCacheRootOverride(args[i + 1])
      inc i, 2
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported why flag: " & arg)
    elif explicitAction:
      if target.len == 0:
        target = arg
        inc i
      else:
        raise newException(ValueError, "unexpected why argument: " & arg)
    elif subject.len == 0:
      subject = arg
      inc i
    elif target.len == 0:
      target = arg
      inc i
    else:
      raise newException(ValueError, "unexpected why argument: " & arg)

  if subject.len == 0:
    raise newException(ValueError,
      "missing why subject; use repro why <package-or-action> or " &
        "repro why --action=<action-id>")
  # Named-Targets M5: when the second positional is a path or a bare
  # name, the user may have intended the *name* to be the subject. The
  # legacy single-positional form already worked because the subject
  # came first and the target was current directory. The two-positional
  # ``repro why subject target`` form keeps the ambiguity. We classify
  # ``target``: a name-shaped value is rejected to keep behaviour
  # predictable — the user should re-run as ``repro why <name>`` with
  # one positional.
  let targetClassified =
    if target.len == 0: ClassifiedBuildSelector(kind: bskPath)
    else: classifyBuildSelector(target)
  if target.len > 0 and targetClassified.kind in {bskName, bskQualified}:
    raise newException(ValueError,
      "repro why: the second positional must be a path or fragment " &
        "selector; got the name-shaped value '" & target &
        "' (re-run as `repro why " & target & "` with one positional)")
  if target.len == 0:
    target = "."

  # NLF-M9 (design §5.6, owner decision 2026-08-21) — the package-level
  # answer. `repro why <package>` can now say why a package is in the solved
  # graph, and "nothing selected it" is a FIRST-CLASS answer rather than the
  # absence of one: before the solve recorded selection, this command could
  # only say "package-level why is not implemented".
  #
  # It is computed lazily and consulted only AFTER the action lookup fails, so
  # a name that resolves as a build action keeps resolving as one and this
  # cannot shadow it.
  proc packageSelectionAnswer(): string =
    if explicitAction:
      return ""
    let projDir =
      try: resolveProjectDirFromTarget(target)
      except CatchableError: return ""
    var graph: tuple[solution: UnifiedSolution, source: string,
                     lockPath: string, found: bool]
    try:
      graph = resolveSolvedGraphForBuild(projDir, "", "")
    except CatchableError:
      return ""
    if not graph.found or subject notin graph.solution.packages:
      return ""
    case format
    of gofJson:
      $whyPackageJson(graph.solution, subject, graph.source, graph.lockPath)
    else:
      renderWhyPackageText(graph.solution, subject, graph.source,
                           graph.lockPath)

  var autoRunQuota = startAutoRunQuotaIfNeeded(runQuotaBypassedByEnv())
  try:
    let info =
      try:
        prepareBuildGraphInspection(target, mode, publicCliPath,
          selectDefaultAction = true,
          workRoot = workRoot)
      except CatchableError:
        # A lock-only project (no `repro.nim`) has no build graph to inspect,
        # and that is exactly the shape the package-level question is asked
        # in. Fall back to it; re-raise unchanged when the subject is not a
        # package either, so a genuine graph failure is never swallowed.
        let answer = packageSelectionAnswer()
        if answer.len == 0:
          raise
        echo answer
        return 0
    # Named-Targets M5: route the subject through the shared
    # ``resolveTargetExportSelector`` helper so the bare implicit name
    # and qualified ``<package>:<name>`` forms reach the same action id
    # they would have via ``repro build NAME``. Action ids and explicit
    # ``target "..."`` labels still resolve via the legacy
    # ``requireAction`` lookup; only the name forms need translation.
    if not explicitAction:
      let subjClassified = classifyBuildSelector(subject)
      if subjClassified.kind in {bskName, bskQualified}:
        var actionIds: seq[string] = @[]
        for action in info.actions:
          actionIds.add(action.id)
        let resolution = resolveTargetExportSelector(info.targetExportTable,
          actionIds, info.explicitTargetNames, subject)
        case resolution.kind
        of trkResolved:
          subject = resolution.actionId
        of trkAmbiguous:
          var err = newException(BuildTargetAmbiguousError,
            "target '" & subject &
              "' is exported by multiple packages: " &
              resolution.candidates.join(", ") &
              " — re-run with the qualified <package>:<name> form")
          err.selectorName = subject
          err.candidates = resolution.candidates
          raise err
        of trkUnknown:
          # Fall through to the legacy ``requireAction`` lookup below
          # so action ids that happen to lack a path/fragment shape
          # still work without surfacing the diagnostic. The
          # ``requireAction`` failure will raise its own ValueError
          # with the candidate-action list.
          discard
    try:
      discard requireAction(info.actions, subject)
    except ValueError:
      if explicitAction:
        raise
      # NLF-M9 — the subject is not an action; try the package question.
      let answer = packageSelectionAnswer()
      if answer.len > 0:
        echo answer
        return 0
      raise newException(ValueError,
        "package-level why is not implemented for this project context yet, " &
          "and no build action named " & subject & " exists")
    case format
    of gofText:
      echo renderWhyActionText(info, subject)
    of gofJson:
      echo $whyActionJson(info, subject)
    of gofDot:
      discard
    return 0
  finally:
    releaseAutoRunQuotaProcess(autoRunQuota)

proc renderLoweredGraphRecordText(record: LoweredGraphCacheRecord): string =
  var lines: seq[string] = @[]
  lines.add("lowered graph cache")
  lines.add("modulePath: " & record.modulePath)
  lines.add("projectRoot: " & record.projectRoot)
  lines.add("selectedActionId: " &
    (if record.selectedActionId.len > 0: record.selectedActionId else: "-"))
  lines.add("actions: " & $record.actions.len)
  lines.add("pools: " & $record.pools.len)
  for action in record.actions:
    lines.add("- " & action.id &
      " deps=[" & action.deps.join(", ") & "]" &
      " outputs=" & $action.outputs.len &
      " command=" & commandDisplay(action))
  lines.join("\n")

proc runDebugArtifactCommand(args: openArray[string]): int =
  var path = ""
  var format = gofText
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--json":
      format = gofJson
      inc i
    elif arg.startsWith("--format="):
      format = parseGraphOutputFormat(arg.split("=", maxsplit = 1)[1],
        allowDot = false)
      inc i
    elif arg == "--format":
      if i + 1 >= args.len:
        raise newException(ValueError, "--format requires a value")
      format = parseGraphOutputFormat(args[i + 1], allowDot = false)
      inc i, 2
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported debug artifact flag: " & arg)
    elif path.len == 0:
      path = arg
      inc i
    else:
      raise newException(ValueError,
        "unexpected debug artifact argument: " & arg)
  if path.len == 0:
    raise newException(ValueError, "debug artifact requires a path")
  let record = decodeLoweredGraphCache(toBytes(readFile(extendedPath(path))))
  case format
  of gofText:
    echo renderLoweredGraphRecordText(record)
  of gofJson:
    echo $loweredGraphRecordJson(record)
  of gofDot:
    discard
  0

proc parsePositiveIntFlag(flagName, value: string): int =
  try:
    result = parseInt(value)
  except ValueError:
    raise newException(ValueError, flagName & " must be an integer")
  if result <= 0:
    raise newException(ValueError, flagName & " must be greater than zero")

const CodetracerHcrSupportProfile =
  "macos-arm64-direct-hcr-in-codetracer-v1"

type
  HcrWatchConfig = object
    targetName: string
      ## Named-Targets M4: the target name this HCR config attaches to.
      ## Empty for the legacy single-target convenience surface (the
      ## ``--hcr-agent-socket`` / ``--hcr-artifacts`` / ``--hcr-metadata``
      ## flag triad). For the multi-target surface added in M4, every
      ## ``--hcr-target=NAME:SOCKET:ARTIFACTS[:METADATA]`` flag produces a
      ## ``HcrWatchConfig`` whose ``targetName`` is the selector spelling
      ## the user passed on the CLI (matching the M3
      ## ``parseAndResolveSelectors`` output). The target name appears in
      ## every HCR event payload (§3.4 SSE event table) so consumers can
      ## route events back to a specific target.
    socketPath: string
    artifacts: string
    metadataPath: string

  HcrWatchPatchMetadata* = object
    functionName*: string
    targetSymbol*: string
    objectSymbol*: string
    objectPath*: string
    sourcePath*: string

  HcrWatchObjectBaseline* = object
    objectPath*: string
    sourcePath*: string
    generation0Object*: string

  HcrWatchInferredPatch* = object
    metadata*: HcrWatchPatchMetadata
    oldObject*: string
    newObject*: string

  HcrWatchSession = object
    enabled: bool
    config: HcrWatchConfig
    metadata: HcrWatchPatchMetadata
    inferredBaselines: seq[HcrWatchObjectBaseline]
    listener: HcrAgentUnixListener
    connection: HcrAgentSocketConnection
    client: HcrCoordinatorClient
    connected: bool
    oldObject: string
    newObject: string
    baselineSourceDigest: string
      ## Named-Targets M4 (metadata mode): the digest of the metadata
      ## source file at baseline time. Used by ``deliverHcrWatchPatch``
      ## to detect "this target's source did NOT change this cycle" so
      ## the per-target patch lifecycle can silently skip (raise
      ## ``HcrWatchNoChange``) rather than delivering a no-op patch.
      ## Multi-target HCR (HCR §3.2) needs this so a multi-target run
      ## "no patch is delivered to b" when b's closure didn't change.
    fallbackOnly: bool
      ## Named-Targets M4 per-target failure isolation: when a session's
      ## baseline / patch lifecycle raises, this flag is flipped and the
      ## session falls back to the ordinary rebuild path for the rest of
      ## the watch loop. ``hcr/patchFailed`` is emitted exactly once on
      ## the failing target so SSE consumers see the failure exactly
      ## once. Other sessions in the seq are unaffected (per HCR
      ## §3.2 "Multi-Target HCR" — "a failure to inject the agent into
      ## one target does not stop the others").

proc writeJsonFile(path: string; node: JsonNode) =
  createDir(extendedPath(parentDir(path)))
  writeFile(extendedPath(path), pretty(node))

proc hcrSourceDigest(path: string): string =
  byteDigest(readFile(extendedPath(path)).bytesOf())

proc objectFunctionBytes(objectPath, symbolName: string): seq[byte] =
  let graph = parseMachOArm64Object(objectPath)
  let symbol = graph.findSymbol(symbolName)
  result = graph.functionBytes(symbol)
  if result.len == 0:
    raise newException(ValueError,
      "could not extract function bytes for " & symbolName & " from " &
        objectPath)

proc hcrWatchEnabled(config: HcrWatchConfig): bool =
  config.socketPath.len > 0 or config.artifacts.len > 0 or
    config.metadataPath.len > 0

proc hcrEventTargetLabel(config: HcrWatchConfig): string =
  ## Named-Targets M4: the ``target`` value carried in every HCR SSE
  ## payload. Falls back to ``"default"`` for the legacy single-target
  ## ``--hcr-agent-socket`` surface so the JSON schema stays uniform
  ## across single- and multi-target runs.
  if config.targetName.len > 0:
    config.targetName
  else:
    "default"

proc hcrEventPayload(config: HcrWatchConfig; extra: JsonNode = nil):
    string =
  ## Named-Targets M4 §3.4 (HCR SSE event payloads gain a ``target``
  ## field): build the JSON payload for an ``hcr/*`` watch event.
  ## ``extra`` may contribute additional fields per the SSE event table
  ## (``patchId``, ``error``, etc.). The ``target`` field is always
  ## present so multi-target SSE consumers can route every event.
  var node = %*{
    "target": hcrEventTargetLabel(config)
  }
  if extra != nil and extra.kind == JObject:
    for key, value in extra.pairs:
      node[key] = value
  $node

proc validateHcrWatchConfig(config: HcrWatchConfig) =
  if not config.hcrWatchEnabled:
    return
  if config.socketPath.len == 0:
    raise newException(ValueError,
      "--hcr-agent-socket is required when HCR watch mode is enabled")
  if config.artifacts.len == 0:
    raise newException(ValueError,
      "--hcr-artifacts is required when HCR watch mode is enabled")

proc resolveProjectPath(projectRoot, path: string): string =
  if path.len == 0:
    return ""
  result =
    if path.isAbsolute:
      path
    else:
      projectRoot / path
  result = os.normalizedPath(result)

proc requiredJsonString(node: JsonNode; key, context: string): string =
  if node.kind != JObject or not node.hasKey(key):
    raise newException(ValueError, context & " missing required field " & key)
  result = node[key].getStr()
  if result.len == 0:
    raise newException(ValueError, context & " field " & key &
      " must not be empty")

proc optionalJsonString(node: JsonNode; key: string): string =
  if node.kind == JObject and node.hasKey(key):
    result = node[key].getStr()

proc defaultObjectSymbol(functionName: string): string =
  when defined(macosx):
    "_" & functionName
  else:
    functionName

proc readHcrWatchPatchMetadata(projectRoot, metadataPath: string):
    HcrWatchPatchMetadata =
  let resolvedMetadataPath = resolveProjectPath(projectRoot, metadataPath)
  if not fileExists(extendedPath(resolvedMetadataPath)):
    raise newException(ValueError,
      "HCR watch metadata does not exist: " & resolvedMetadataPath)
  let root = parseFile(resolvedMetadataPath)
  var patch: JsonNode = nil
  if root.kind == JObject and root.hasKey("patches") and
      root["patches"].kind == JArray and root["patches"].len > 0:
    patch = root["patches"][0]
  else:
    patch = root

  result.functionName = patch.requiredJsonString("function", "HCR patch metadata")
  result.targetSymbol = patch.optionalJsonString("targetSymbol")
  if result.targetSymbol.len == 0:
    result.targetSymbol = result.functionName
  result.objectSymbol = patch.optionalJsonString("objectSymbol")
  if result.objectSymbol.len == 0:
    result.objectSymbol = defaultObjectSymbol(result.functionName)
  result.objectPath = resolveProjectPath(
    projectRoot, patch.requiredJsonString("object", "HCR patch metadata"))
  result.sourcePath = resolveProjectPath(
    projectRoot, patch.requiredJsonString("source", "HCR patch metadata"))

proc jsonStringSeqField(node: JsonNode; key: string): seq[string] =
  let values = node{key}
  if values.kind != JArray:
    return
  for value in values:
    if value.kind == JString and value.getStr().len > 0:
      result.add value.getStr()

proc materialReportPath(projectRoot, path: string): string =
  if path.len == 0:
    return ""
  result =
    if path.isAbsolute:
      path
    else:
      projectRoot / path
  result = os.normalizedPath(result)

proc isCxxSource(path: string): bool =
  splitFile(path).ext.toLowerAscii in [".c", ".cc", ".cpp", ".cxx"]

proc isObjectFile(path: string): bool =
  splitFile(path).ext.toLowerAscii in [".o", ".obj"]

proc stripObjectSymbolPrefix(symbol: string): string =
  if symbol.startsWith("_") and symbol.len > 1:
    symbol[1 .. ^1]
  else:
    symbol

proc hcrWatchObjectCandidatesFromReport*(projectRoot, buildReportPath: string):
    seq[HcrWatchObjectBaseline] =
  if buildReportPath.len == 0 or not fileExists(extendedPath(buildReportPath)):
    raise newException(ValueError,
      "HCR watch inference requires a build report")
  let report = parseFile(buildReportPath)
  for action in report{"actions"}:
    let evidence = action{"evidence"}
    if evidence.kind != JObject:
      continue

    var inputs: seq[string]
    for key in ["declaredInputs", "depfileInputs", "monitorReads"]:
      for path in evidence.jsonStringSeqField(key):
        inputs.addUnique(projectRoot.materialReportPath(path))
    var sourceInputs: seq[string]
    for path in inputs:
      if path.isCxxSource and fileExists(extendedPath(path)):
        sourceInputs.addUnique(path)
    if sourceInputs.len != 1:
      continue

    for path in evidence.jsonStringSeqField("declaredOutputs"):
      let objectPath = projectRoot.materialReportPath(path)
      if objectPath.isObjectFile and fileExists(extendedPath(objectPath)):
        result.add HcrWatchObjectBaseline(
          objectPath: objectPath,
          sourcePath: sourceInputs[0])

proc captureInferredHcrWatchBaseline*(projectRoot, buildReportPath,
                                      artifacts: string):
    seq[HcrWatchObjectBaseline] =
  result = hcrWatchObjectCandidatesFromReport(projectRoot, buildReportPath)
  if result.len == 0:
    raise newException(ValueError,
      "HCR watch could not infer any C/C++ object outputs from the build report")
  createDir(extendedPath(artifacts))
  for i in 0 ..< result.len:
    let objectSegment = safePathSegment(result[i].objectPath, "object")
    result[i].generation0Object =
      artifacts / ("generation0-" & align($i, 4, '0') & "-" & objectSegment)
    copyFile(extendedPath(result[i].objectPath),
      extendedPath(result[i].generation0Object))

type
  HcrWatchNoChange* = object of CatchableError
    ## Named-Targets M4: raised by ``inferHcrWatchPatch`` when none of
    ## the baselines saw a code change in this cycle. Per-target multi-
    ## target HCR catches this distinctly from real injection failures:
    ## a no-change cycle is silent (the target's source didn't change,
    ## so there is nothing to patch), while a real failure (missing
    ## metadata, agent disconnect, malformed object) emits
    ## ``hcr/patchFailed`` and falls back.

proc inferHcrWatchPatch*(baselines: openArray[HcrWatchObjectBaseline];
                         artifacts: string; cycle: int):
    HcrWatchInferredPatch =
  type Candidate = object
    baseline: HcrWatchObjectBaseline
    objectSymbol: string

  var candidates: seq[Candidate]
  for baseline in baselines:
    if not fileExists(extendedPath(baseline.generation0Object)) or
        not fileExists(extendedPath(baseline.objectPath)):
      continue
    let oldGraph = parseMachOArm64Object(baseline.generation0Object)
    let newGraph = parseMachOArm64Object(baseline.objectPath)
    let diff = diffFunctions(oldGraph, newGraph)
    for entry in diff.functions:
      case entry.kind
      of fckUnchanged:
        discard
      of fckRemoved:
        raise newException(ValueError,
          "HCR watch does not support removed function " & entry.name)
      of fckChangedCode, fckRelocationSignatureChanged, fckAdded:
        candidates.add Candidate(
          baseline: baseline,
          objectSymbol: entry.name)

  if candidates.len == 0:
    raise newException(HcrWatchNoChange,
      "HCR watch did not find a changed function in rebuilt object outputs")
  if candidates.len > 1:
    var names: seq[string]
    for candidate in candidates:
      names.add candidate.objectSymbol
    raise newException(ValueError,
      "HCR watch currently requires exactly one changed function; found " &
        names.join(", "))

  let candidate = candidates[0]
  let functionName = stripObjectSymbolPrefix(candidate.objectSymbol)
  let newObject = artifacts /
    (safePathSegment(functionName, "patch") & "-generation" &
      $(cycle - 1) & ".o")
  copyFile(extendedPath(candidate.baseline.objectPath), extendedPath(newObject))
  result = HcrWatchInferredPatch(
    metadata: HcrWatchPatchMetadata(
      functionName: functionName,
      targetSymbol: functionName,
      objectSymbol: candidate.objectSymbol,
      objectPath: candidate.baseline.objectPath,
      sourcePath: candidate.baseline.sourcePath),
    oldObject: candidate.baseline.generation0Object,
    newObject: newObject)

type
  WatchHcrEventEmit = proc(eventKind: string; message: string;
                           payloadJson: string) {.closure.}
    ## Named-Targets M4: per-target HCR SSE emit hook handed to the
    ## ``captureHcrWatchBaseline`` / ``deliverHcrWatchPatch`` procs by
    ## ``runWatchCommand``. The hook is wired to the shared watch SSE
    ## event stream (``emitWatchLine``) so every HCR event lands in the
    ## same stream as ``cycle-start`` / ``rebuild-queued`` and carries a
    ## ``target`` field per HCR/CLI-Integration §3.4.

proc emitHcrEvent(emit: WatchHcrEventEmit; config: HcrWatchConfig;
                  eventKind, message: string; extra: JsonNode = nil) =
  if emit == nil:
    return
  emit(eventKind, message, hcrEventPayload(config, extra))

proc initHcrWatchSession(config: HcrWatchConfig): HcrWatchSession =
  config.validateHcrWatchConfig()
  result.enabled = config.hcrWatchEnabled
  result.config = config
  if result.enabled:
    createDir(extendedPath(config.artifacts))
    result.listener = listenHcrAgentUnixSocket(config.socketPath)
    result.client = initHcrCoordinatorClient(CodetracerHcrSupportProfile)

proc closeHcrWatchSession(session: var HcrWatchSession) =
  if session.enabled:
    if session.connected:
      try: session.connection.close()
      except CatchableError: discard
      session.connected = false
    try: session.listener.close()
    except CatchableError: discard
    # Named-Targets M4: ``runDirectWatch`` may call this early via the
    # per-target failure-isolation block AND again in the final defer.
    # Mark ``enabled = false`` so the second call is a cheap no-op.
    session.enabled = false

proc targetLogSuffix(config: HcrWatchConfig): string =
  ## Named-Targets M4: stdout suffix that names which target the HCR
  ## log line belongs to. Empty string for single-target runs so the
  ## legacy log shape (used by existing tests like
  ## ``t_e2e_hcr_watch_inference``) keeps its byte layout.
  if config.targetName.len > 0:
    " target=" & config.targetName
  else:
    ""

proc captureHcrWatchBaseline(session: var HcrWatchSession;
                             outcome: BuildCommandOutcome;
                             emit: WatchHcrEventEmit = nil) =
  if not session.enabled:
    return
  if session.config.metadataPath.len > 0:
    session.metadata = readHcrWatchPatchMetadata(
      outcome.projectRoot, session.config.metadataPath)
    if not fileExists(extendedPath(session.metadata.objectPath)):
      raise newException(ValueError,
        "HCR watch object does not exist after initial build: " &
          session.metadata.objectPath)
    session.oldObject = session.config.artifacts /
      (safePathSegment(session.metadata.functionName, "patch") & "-generation0.o")
    copyFile(extendedPath(session.metadata.objectPath),
      extendedPath(session.oldObject))
    # Named-Targets M4: record baseline source digest so multi-target
    # metadata-mode runs can detect "this target's source did not
    # change this cycle" and skip patch delivery silently.
    if fileExists(extendedPath(session.metadata.sourcePath)):
      session.baselineSourceDigest =
        hcrSourceDigest(session.metadata.sourcePath)
    writeJsonFile(session.config.artifacts / "hcr-watch-baseline.json", %*{
      "schemaId": "reprobuild.hcr.watch-baseline.v1",
      "supportProfile": CodetracerHcrSupportProfile,
      "mode": "metadata",
      "function": session.metadata.functionName,
      "targetSymbol": session.metadata.targetSymbol,
      "objectSymbol": session.metadata.objectSymbol,
      "object": session.metadata.objectPath,
      "source": session.metadata.sourcePath,
      "generation0Object": session.oldObject
    })
    echo "repro watch: hcr baseline captured object=" &
      session.metadata.objectPath & targetLogSuffix(session.config)
  else:
    session.inferredBaselines = captureInferredHcrWatchBaseline(
      outcome.projectRoot, outcome.buildReportPath, session.config.artifacts)
    var objects = newJArray()
    for baseline in session.inferredBaselines:
      objects.add %*{
        "object": baseline.objectPath,
        "source": baseline.sourcePath,
        "generation0Object": baseline.generation0Object
      }
    writeJsonFile(session.config.artifacts / "hcr-watch-baseline.json", %*{
      "schemaId": "reprobuild.hcr.watch-baseline.v1",
      "supportProfile": CodetracerHcrSupportProfile,
      "mode": "inferred",
      "objects": objects
    })
    echo "repro watch: hcr baseline inferred objects=" &
      $session.inferredBaselines.len & targetLogSuffix(session.config)
  echo "repro watch: hcr waiting for agent socket=" &
    session.config.socketPath & targetLogSuffix(session.config)
  flushStdout()
  # Named-Targets M4: emit the baseline event into the shared SSE stream
  # so per-target HCR consumers see the agent-injection lifecycle as it
  # progresses, even on the cycle-1 baseline.
  emit.emitHcrEvent(session.config, "hcr/agentWaiting",
    "repro watch: hcr waiting for agent socket=" & session.config.socketPath,
    %*{"socket": session.config.socketPath})
  session.connection = acceptHcrAgentConnection(session.listener)
  session.connected = true
  discard session.client.receiveAgentMessage(session.connection)
  session.client.sendCoordinatorMessage(
    session.connection, session.client.coordinatorHelloAckMessage())
  echo "repro watch: hcr agent connected" & targetLogSuffix(session.config)
  flushStdout()
  emit.emitHcrEvent(session.config, "hcr/agentConnected",
    "repro watch: hcr agent connected")

proc deliverHcrWatchPatch(session: var HcrWatchSession;
                          outcome: BuildCommandOutcome; cycle: int;
                          emit: WatchHcrEventEmit = nil) =
  if not session.enabled:
    return
  if not session.connected:
    raise newException(ValueError,
      "HCR watch cannot deliver a patch before the target agent connects")
  if session.config.metadataPath.len > 0:
    session.metadata = readHcrWatchPatchMetadata(
      outcome.projectRoot, session.config.metadataPath)
    if not fileExists(extendedPath(session.metadata.objectPath)):
      raise newException(ValueError,
        "HCR watch object does not exist after rebuild: " &
          session.metadata.objectPath)
    # Named-Targets M4: in multi-target metadata-mode runs, the source
    # digest comparison tells us this target's owned closure did NOT
    # change this cycle (the rebuild was a cache hit for our target).
    # Per HCR §3.2, a target whose closure didn't change MUST NOT
    # receive a patch — raise ``HcrWatchNoChange`` so the per-target
    # lifecycle loop silently skips delivery for this cycle.
    if session.config.targetName.len > 0 and
        session.baselineSourceDigest.len > 0 and
        fileExists(extendedPath(session.metadata.sourcePath)):
      let nowDigest = hcrSourceDigest(session.metadata.sourcePath)
      if nowDigest == session.baselineSourceDigest:
        raise newException(HcrWatchNoChange,
          "HCR watch: target '" & session.config.targetName &
            "' source unchanged this cycle")
    session.newObject = session.config.artifacts /
      (safePathSegment(session.metadata.functionName, "patch") & "-generation" &
        $(cycle - 1) & ".o")
    copyFile(extendedPath(session.metadata.objectPath),
      extendedPath(session.newObject))
  else:
    let inferred = inferHcrWatchPatch(
      session.inferredBaselines, session.config.artifacts, cycle)
    session.metadata = inferred.metadata
    session.oldObject = inferred.oldObject
    session.newObject = inferred.newObject
    echo "repro watch: hcr inferred changed function=" &
      session.metadata.functionName & " object=" & session.metadata.objectPath &
      targetLogSuffix(session.config)
  if not fileExists(extendedPath(session.metadata.sourcePath)):
    raise newException(ValueError,
      "HCR watch source does not exist after rebuild: " &
        session.metadata.sourcePath)

  let patchBytes = objectFunctionBytes(session.newObject,
    session.metadata.objectSymbol)
  let sourceGeneration = HcrSourceGenerationEntry(
    sourcePath: session.metadata.sourcePath,
    generation: uint32(cycle - 1),
    snapshotDigest: hcrSourceDigest(session.metadata.sourcePath),
    lineTableDigest: byteDigest(patchBytes))
  let objectBytes = readFile(extendedPath(session.newObject)).bytesOf()
  let plan = directPatchPlanFromBytes(
    session.metadata.functionName, patchBytes,
    supportProfile = CodetracerHcrSupportProfile,
    snapshotId = "repro-watch-hcr-generation-" & $(cycle - 1))
  let request = directPatchRequest(
    patchId = "repro-watch-hcr-patch-" & align($(cycle - 1), 4, '0'),
    supportProfile = CodetracerHcrSupportProfile,
    changedFunctions = [session.metadata.functionName],
    targetSymbols = [session.metadata.targetSymbol],
    directPatchBytes = patchBytes,
    debugObjectBytes = objectBytes,
    unwindMetadataBytes = minimalAarch64EhFrameTemplate(),
    sourceGenerationMap = [sourceGeneration])
  # Named-Targets M4 §3.4: emit ``hcr/patchCompiling`` for the SSE
  # consumer before the patch is sent to the agent. ``target`` is the
  # per-target label set on the config.
  emit.emitHcrEvent(session.config, "hcr/patchCompiling",
    "repro watch: hcr patch compiling patchId=" & request.patchId,
    %*{
      "patchId": request.patchId,
      "files": %*[session.metadata.sourcePath]
    })
  session.client.sendCoordinatorMessage(
    session.connection, session.client.coordinatorPatchRequestMessage(request))
  while session.client.session.state == hssPatchRequested:
    discard session.client.receiveAgentMessage(session.connection)

  let delivery = HcrCoordinatorDelivery(
    session: session.client.session,
    transcript: session.client.transcript,
    patchApplied: session.client.patchApplied,
    patchFailed: session.client.patchFailed)
  writeJsonFile(session.config.artifacts / "hcr-coordinator-report.json",
    coordinatorDeliveryJson(delivery))
  writeJsonFile(session.config.artifacts / "agent-protocol-transcript.json",
    transcriptJson(session.client.transcript))
  writeJsonFile(session.config.artifacts / "patch-bundle-metadata.json", %*{
    "schemaId": "reprobuild.hcr.codetracer-patch-bundle-metadata.v1",
    "supportProfile": CodetracerHcrSupportProfile,
    "patchId": request.patchId,
    "changedFunction": session.metadata.functionName,
    "targetSymbol": session.metadata.targetSymbol,
    "objectSymbol": session.metadata.objectSymbol,
    "oldObject": session.oldObject,
    "newObject": session.newObject,
    "patchByteCount": patchBytes.len,
    "patchDigest": byteDigest(patchBytes),
    "debugObjectDigest": request.debugObjectPayload.digest,
    "unwindMetadataDigest": request.unwindMetadataPayload.digest,
    "sourceGeneration": %*{
      "sourcePath": sourceGeneration.sourcePath,
      "generation": sourceGeneration.generation,
      "snapshotDigest": sourceGeneration.snapshotDigest,
      "lineTableDigest": sourceGeneration.lineTableDigest
    },
    "patchPlan": patchPlanJson(plan),
    "watch": {
      "cycle": cycle,
      "sourceEditObservedByFilesystemWatcher": true
    }
  })

  if session.client.patchFailed.isSome:
    raise newException(ValueError,
      "HCR watch patch failed: " & session.client.patchFailed.get().message)
  if session.client.patchApplied.isNone:
    raise newException(ValueError,
      "HCR watch did not receive a patchApplied response")
  echo "repro watch: hcr patch applied patchId=" & request.patchId &
    targetLogSuffix(session.config)
  flushStdout()
  # Named-Targets M4 §3.4: ``hcr/patchApplied`` carries ``target`` so
  # SSE consumers can route per-target events.
  var functions = newJArray()
  functions.add(%session.metadata.functionName)
  emit.emitHcrEvent(session.config, "hcr/patchApplied",
    "repro watch: hcr patch applied patchId=" & request.patchId,
    %*{
      "patchId": request.patchId,
      "functions": functions
    })

type
  WatchCtIncrementalFlags* = object
    ## Trace-Based-Incremental-Testing M2: the two ``repro watch`` flags that
    ## control runtime-incremental skip/re-run. Parsed by
    ## ``applyWatchCtIncrementalFlag`` from the same argument loop that parses
    ## every other watch flag, so the test that drives this parser exercises the
    ## real CLI surface (no duplicated grammar).
    enabled*: bool        ## Set by ``--ct-incremental``.
    traceDir*: string     ## Set by ``--ct-incremental-trace-dir=PATH``.

proc applyWatchCtIncrementalFlag*(flags: var WatchCtIncrementalFlags;
                                  arg: string): bool =
  ## Apply a single CLI argument to `flags` if it is one of the M2
  ## ct-incremental flags. Returns ``true`` when `arg` was consumed (so the
  ## caller's elif chain can stop), ``false`` when it is some other flag.
  ##
  ## A bare ``--ct-incremental-trace-dir`` (no inline value) raises the same
  ## ``ValueError`` shape as the other value-taking watch flags — the value is
  ## mandatory, never silently empty.
  if arg == "--ct-incremental":
    flags.enabled = true
    true
  elif arg.startsWith("--ct-incremental-trace-dir="):
    flags.traceDir = arg.split("=", maxsplit = 1)[1]
    true
  elif arg == "--ct-incremental-trace-dir":
    raise newException(ValueError,
      "--ct-incremental-trace-dir requires an inline value, for example " &
        "--ct-incremental-trace-dir=.repro/ct-trace")
  else:
    false

proc runWatchCommand(args: openArray[string]; publicCliPath: string;
                     forceDirect = false;
                     daemonHosted = false;
                     eventSink: WatchCommandEventSink = nil;
                     cancelCheck: BuildCancelCallback = nil): int =
  let originalArgs = @args
  var target = ""
  var positionalSelectors: seq[string] = @[]
  var mode = tpmUnspecified
  var maxCycles = 0
  var debounceMs = 250
  var workRoot = ""
  # Measurement axes (CLI/README.md §"Measurement: Collect, Present, Persist").
  # ``repro watch`` drives the same engine as ``repro build``, so it carries
  # the same three axes rather than a private subset.
  var showSet = configuredShowSet()
  var measureSet = configuredMeasureSet()
  var measureExplicit = false
  var showExplicit = false
  var reportPersistence = BuildReportPersistence()
  var hcrConfig: HcrWatchConfig
  # Named-Targets M4: per-target HCR config seq, populated by the
  # repeatable ``--hcr-target=NAME:SOCKET:ARTIFACTS[:METADATA]`` flag.
  # The legacy single-target triad (``--hcr-agent-socket`` etc.)
  # populates ``hcrConfig`` above; M4 keeps that surface for backward
  # compatibility (the existing ``t_e2e_hcr_watch_inference`` test
  # exercises it).
  var hcrTargetConfigs: seq[HcrWatchConfig] = @[]
  var daemonMode = bdmAuto
  var daemonModeExplicit = false
  var detach = false
  var attachSessionId = ""
  var stopSessionId = ""
  var statsCapture = StatsCaptureConfig()
  # Trace-Based-Incremental-Testing M2: opt-in runtime-incremental mode for a
  # watched test edge. ``--ct-incremental`` enables the mode;
  # ``--ct-incremental-trace-dir=PATH`` points at the directory where the
  # watched test produces its CodeTracer trace (prototype assumption — a fixed
  # dir the test writes its trace to). Absence of ``--ct-incremental`` leaves
  # the legacy watch behaviour byte-for-byte unchanged.
  var ctFlags = WatchCtIncrementalFlags()

  for arg in args:
    if arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(arg.split("=", maxsplit = 1)[1])
    elif arg == "--tool-provisioning":
      raise newException(ValueError,
        "--tool-provisioning requires an inline value, for example " &
          "--tool-provisioning=path")
    elif arg.startsWith("--work-root="):
      workRoot = arg.split("=", maxsplit = 1)[1]
    elif arg == "--work-root":
      raise newException(ValueError,
        "--work-root requires an inline value, for example --work-root=.repro")
    elif arg.startsWith("--max-cycles="):
      maxCycles = parsePositiveIntFlag("--max-cycles",
        arg.split("=", maxsplit = 1)[1])
    elif arg.startsWith("--debounce-ms="):
      debounceMs = parsePositiveIntFlag("--debounce-ms",
        arg.split("=", maxsplit = 1)[1])
    elif arg.startsWith("--daemon="):
      daemonMode = parseBuildDaemonMode(arg.split("=", maxsplit = 1)[1],
        "--daemon")
      daemonModeExplicit = true
    elif arg == "--daemon":
      raise newException(ValueError,
        "--daemon requires an inline value, for example --daemon=require")
    elif arg == "--detach":
      detach = true
    elif arg == "--write-stats" or arg.startsWith("--write-stats="):
      statsCapture.enabled = true
      if statsCapture.groups.card == 0:
        statsCapture.groups = AllStatsCaptureGroups
        statsCapture.raw = "all"
      if arg.startsWith("--write-stats="):
        statsCapture.storePath = arg.split("=", maxsplit = 1)[1]
    elif arg.startsWith("--stats-groups="):
      statsCapture = parseStatsCaptureGroups(arg.split("=", maxsplit = 1)[1],
        statsCapture.storePath)
    elif arg == "--stats-groups":
      raise newException(ValueError,
        "--stats-groups requires an inline value, for example " &
          "--stats-groups=timing,cache")
    elif arg.startsWith("--measure="):
      if not measureExplicit:
        measureSet = {}
        measureExplicit = true
      measureSet = parseMeasureCategories(measureSet,
        arg.split("=", maxsplit = 1)[1], "--measure")
    elif arg == "--measure":
      raise newException(ValueError,
        "--measure requires an inline value, for example --measure=timing")
    elif arg.startsWith("--show="):
      if not showExplicit:
        showSet = {}
        showExplicit = true
      showSet = parseMeasureCategories(showSet,
        arg.split("=", maxsplit = 1)[1], "--show")
    elif arg == "--show":
      raise newException(ValueError,
        "--show requires an inline value, for example --show=timing")
    elif arg == "--write-report" or arg.startsWith("--write-report="):
      reportPersistence.requested = true
      if arg.startsWith("--write-report="):
        reportPersistence.path = arg["--write-report=".len .. ^1]
    elif arg == "--no-write-report":
      reportPersistence.suppressed = true
    elif arg.startsWith("--attach="):
      attachSessionId = arg.split("=", maxsplit = 1)[1]
    elif arg == "--attach":
      raise newException(ValueError,
        "--attach requires an inline session id, for example --attach=watch-...")
    elif arg.startsWith("--stop="):
      stopSessionId = arg.split("=", maxsplit = 1)[1]
    elif arg == "--stop":
      raise newException(ValueError,
        "--stop requires an inline session id, for example --stop=watch-...")
    elif arg.startsWith("--hcr-agent-socket="):
      hcrConfig.socketPath = arg.split("=", maxsplit = 1)[1]
    elif arg == "--hcr-agent-socket":
      raise newException(ValueError,
        "--hcr-agent-socket requires an inline value, for example " &
          "--hcr-agent-socket=/tmp/repro-hcr.sock")
    elif arg.startsWith("--hcr-artifacts="):
      hcrConfig.artifacts = arg.split("=", maxsplit = 1)[1]
    elif arg == "--hcr-artifacts":
      raise newException(ValueError,
        "--hcr-artifacts requires an inline value, for example " &
          "--hcr-artifacts=.repro/hcr")
    elif arg.startsWith("--hcr-metadata="):
      hcrConfig.metadataPath = arg.split("=", maxsplit = 1)[1]
    elif arg == "--hcr-metadata":
      raise newException(ValueError,
        "--hcr-metadata requires an inline value, for example " &
          "--hcr-metadata=build/hcr-metadata.json")
    elif arg.startsWith("--hcr-target="):
      # Named-Targets M4 + M5: repeatable per-target HCR binding.
      # Two shapes are accepted (the parser picks based on the first
      # token):
      #   1. Legacy colon-delimited NAME:SOCKET:ARTIFACTS[:METADATA].
      #      Fine when NAME is a bare implicit name with no ``:``.
      #   2. M5 key=value form ``name=NAME,socket=SOCKET,artifacts=
      #      ARTIFACTS[,metadata=METADATA]`` so a qualified
      #      ``<package>:<name>`` target like ``pkgA:cli`` survives
      #      without colliding with the SOCKET position. The key=value
      #      shape is recognised when the raw value starts with
      #      ``name=`` — any other input falls through to the colon
      #      parser so existing CLI invocations stay byte-compatible.
      let raw = arg.split("=", maxsplit = 1)[1]
      var perTarget: HcrWatchConfig
      if raw.startsWith("name="):
        # M5 structured form. Split on ``,`` and unpack each
        # ``key=value`` pair. Required keys: ``name``, ``socket``,
        # ``artifacts``; optional: ``metadata``. Whitespace inside
        # values is preserved, but the parser does not unescape ``,``
        # (paths should not contain literal commas; if that ever
        # bites we can promote to a JSON form).
        var nameVal = ""
        var socketVal = ""
        var artifactsVal = ""
        var metadataVal = ""
        for pair in raw.split(','):
          let eq = pair.find('=')
          if eq <= 0:
            raise newException(ValueError,
              "--hcr-target: expected key=value pair, got '" & pair & "'")
          let key = pair[0 ..< eq]
          let value = pair[eq + 1 .. ^1]
          case key
          of "name": nameVal = value
          of "socket": socketVal = value
          of "artifacts": artifactsVal = value
          of "metadata": metadataVal = value
          else:
            raise newException(ValueError,
              "--hcr-target: unknown key '" & key &
                "' (expected name|socket|artifacts|metadata)")
        if nameVal.len == 0 or socketVal.len == 0 or artifactsVal.len == 0:
          raise newException(ValueError,
            "--hcr-target structured form requires non-empty " &
              "name=, socket=, and artifacts= keys (got '" & raw & "')")
        perTarget.targetName = nameVal
        perTarget.socketPath = socketVal
        perTarget.artifacts = artifactsVal
        perTarget.metadataPath = metadataVal
      else:
        # Legacy colon-delimited NAME:SOCKET:ARTIFACTS[:METADATA].
        let parts = raw.split(':')
        if parts.len < 3 or parts.len > 4 or parts[0].len == 0 or
            parts[1].len == 0 or parts[2].len == 0:
          raise newException(ValueError,
            "--hcr-target expects NAME:SOCKET:ARTIFACTS[:METADATA] " &
              "or name=NAME,socket=SOCKET,artifacts=ARTIFACTS" &
              "[,metadata=METADATA] (got '" & raw & "')")
        perTarget.targetName = parts[0]
        perTarget.socketPath = parts[1]
        perTarget.artifacts = parts[2]
        if parts.len == 4:
          perTarget.metadataPath = parts[3]
      hcrTargetConfigs.add(perTarget)
    elif arg == "--hcr-target":
      raise newException(ValueError,
        "--hcr-target requires an inline value, for example " &
          "--hcr-target=alpha:/tmp/a.sock:.repro/hcr-alpha " &
          "or --hcr-target=name=pkgA:cli,socket=/tmp/a.sock," &
          "artifacts=.repro/hcr-alpha")
    elif applyWatchCtIncrementalFlag(ctFlags, arg):
      # Trace-Based-Incremental-Testing M2: ``--ct-incremental`` /
      # ``--ct-incremental-trace-dir=PATH`` consumed by the shared parser.
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported watch flag: " & arg)
    else:
      # Named-Targets M3: watch inherits the M2 multi-selector surface.
      # Classification into path vs. name selectors happens below via
      # the shared ``parseAndResolveSelectors`` helper.
      positionalSelectors.add(arg)

  if not daemonModeExplicit:
    daemonMode = configuredBuildDaemonMode()

  measureSet = measureSet + showSet
  if statsCapture.enabled:
    if scgTiming in statsCapture.groups:
      measureSet.incl(mcTiming)
    if scgDeps in statsCapture.groups:
      measureSet.incl(mcCacheEvidence)
  if statsCapture.enabled and (forceDirect or daemonMode == bdmOff) and
      not daemonHosted:
    raise newException(ValueError,
      "--write-stats requires daemon-hosted watch; direct-mode persistent " &
        "capture is not implemented")

  proc renderDaemonWatchEvent(event: UserDaemonBuildEvent) =
    if event.message.len == 0 or event.kind == bekAccepted:
      return
    if event.message.startsWith("repro watch: "):
      stdout.writeLine(event.message)
    else:
      stdout.writeLine("repro watch: " & event.message)
    flushStdout()

  proc runDaemonAttach(): int =
    let config = defaultUserDaemonConfig(devMode = true)
    discard startUserDaemon(publicCliPath, config)
    let result = requestUserDaemonWatchAttach(attachSessionId, config.endpoint,
      renderDaemonWatchEvent)
    if result.message == "daemon-hosted watch stopped":
      return 0
    result.exitCode

  proc runDaemonStop(): int =
    let config = defaultUserDaemonConfig(devMode = true)
    discard startUserDaemon(publicCliPath, config)
    let result = requestUserDaemonWatchStop(stopSessionId, config.endpoint)
    echo "repro watch: " & result.message & " session=" & result.sessionId
    0

  if attachSessionId.len > 0:
    if daemonMode == bdmOff:
      raise newException(ValueError,
        "--attach requires --daemon=auto|require or REPRO_DAEMON=auto|require")
    if positionalSelectors.len > 0:
      raise newException(ValueError,
        "--attach is incompatible with positional target selectors")
    return runDaemonAttach()
  if stopSessionId.len > 0:
    if daemonMode == bdmOff:
      raise newException(ValueError,
        "--stop requires --daemon=auto|require or REPRO_DAEMON=auto|require")
    if positionalSelectors.len > 0:
      raise newException(ValueError,
        "--stop is incompatible with positional target selectors")
    return runDaemonStop()

  # ----------------------------------------------------------------
  # Named-Targets M3: watch inherits the M2 multi-selector resolver via
  # the shared ``parseAndResolveSelectors`` helper. The resolver turns
  # ``repro watch name1 name2`` into the project anchor + the union of
  # every name's dependency closure; ``lowerProviderSnapshot`` then
  # builds them in one engine pass and ``watchPathsFromOutcome`` unions
  # the inputs so the watcher monitors every selected closure.
  # ----------------------------------------------------------------
  let resolved = parseAndResolveSelectors(positionalSelectors, "repro watch")
  target = resolved.target
  let extraNameSelectors = resolved.extraNameSelectors
  let targetWasOmitted = resolved.targetWasOmitted
  if target.len == 0:
    target = "."
  # Tool-provisioning resolution mirrors ``repro build`` (CLI/watch.md): an
  # explicit ``--tool-provisioning`` flag wins, else the
  # ``REPRO_TOOL_PROVISIONING`` env var, else the project's
  # ``defaultToolProvisioning`` — the last tier resolved per build cycle inside
  # ``executeBuildTarget``. ``repro watch`` and ``repro watch <target>`` must
  # therefore work WITHOUT a mandatory CLI flag, just like a one-shot build;
  # only the env tier can be applied here (the interface is loaded per cycle),
  # so apply it and let ``executeBuildTarget`` resolve the project default.
  mode = resolveToolProvisioningWithEnv(mode)
  # Windows: kqueue gate dropped — Windows now reaches the live watch loop
  # via ReadDirectoryChangesW in repro_cli_support/watch. Linux still
  # surfaces the deferred-backend OSError from openFilesystemWatcher.

  proc watchRunId(): string =
    let nowTime = getTime()
    "watch-" & $getCurrentProcessId() & "-" & $nowTime.toUnix & "-" &
      $nowTime.nanosecond

  proc requestProjectRoot(): string =
    try:
      projectRootForModule(absolutePath(parseBuildTarget(target).modulePath))
    except CatchableError:
      getCurrentDir()

  proc daemonWatchEnvironment(): seq[string] =
    # See ``daemonBuildEnvironment``; we share one carried-env contract across
    # build and watch so daemon-hosted compilers see the same toolchain
    # configuration the user expects from their nix-develop shell.
    sanitizeUserDaemonRequestEnvironment(daemonCarriedEnvironment())

  proc runDaemonWatch(): int =
    if hcrConfig.hcrWatchEnabled or hcrTargetConfigs.len > 0:
      # Named-Targets M4: per-target HCR bindings inherit the same
      # daemon-hosted HCR limitation as the legacy single-target HCR
      # surface — both flavours fall back to direct mode under
      # ``--daemon=off``.
      raise newException(DaemonBuildUnsupported,
        "daemon-hosted HCR watch is deferred; use --daemon=off")
    let config = defaultUserDaemonConfig(devMode = true)
    let projectRoot = requestProjectRoot()
    discard startUserDaemon(publicCliPath, config)
    # Named-Targets M3: ``selectedRoots`` carries the full user-facing
    # selector list (path anchor + every name selector) so observers of
    # the daemon session register can see what the cycle is watching.
    # The daemon-side executor re-runs ``runWatchCommand`` against the
    # request's ``rawArgs``, so the shared resolver runs once on the
    # client and once on the worker — both invocations are pure and
    # produce identical resolutions.
    var selectedRoots = @[target]
    for sel in extraNameSelectors:
      if selectedRoots.find(sel) < 0:
        selectedRoots.add(sel)
    let request = UserDaemonWatchRequest(
      runId: watchRunId(),
      target: target,
      workingDir: getCurrentDir(),
      projectRoot: projectRoot,
      toolProvisioning: mode.modeName,
      workRoot: workRoot,
      publicCliPath: publicCliPath,
      rawArgs: originalArgs,
      environment: daemonWatchEnvironment(),
      attached: not detach,
      detached: detach,
      cancelOnDisconnect: not detach,
      debounceMs: debounceMs,
      maxCycles: maxCycles,
      selectedRoots: selectedRoots)
    let daemonResult = requestUserDaemonWatchStart(request, config.endpoint,
      renderDaemonWatchEvent)
    if detach:
      echo "repro watch: detached session=" & daemonResult.sessionId
    daemonResult.exitCode

  proc emitWatchLine(line: string; payloadJson = ""; terminal = false;
                     exitCode = 0; watchedPaths: seq[string] = @[];
                     lastResult = "") =
    echo line
    flushStdout()
    if eventSink != nil:
      eventSink("diagnostic", line, payloadJson, terminal, exitCode,
        watchedPaths, lastResult)

  proc runDirectWatch(): int =
    if statsCapture.enabled and daemonHosted:
      let runId = watchRunId()
      beginStatsCapture(runId, runId, requestProjectRoot(), "watch", target,
        statsCapture)
      enqueueStatsObservation(scgSessions, "watch-start", %*{
        "captureGroups": statsCapture.captureGroupsText,
        "daemonHosted": true,
        "maxCycles": maxCycles
      })
    let anyHcrEnabled = hcrConfig.hcrWatchEnabled or hcrTargetConfigs.len > 0
    echo "repro watch: target=" & target & " tool-provisioning=" &
      mode.modeName & " debounceMs=" & $debounceMs &
      (if maxCycles > 0: " maxCycles=" & $maxCycles else: " maxCycles=unbounded") &
      (if anyHcrEnabled: " hcr=enabled" else: " hcr=disabled") &
      (if hcrTargetConfigs.len > 0:
         " hcr-targets=" & $hcrTargetConfigs.len
       else:
         "")
    flushStdout()

    # Named-Targets M4 ----------------------------------------------------
    # Each ``--hcr-target=NAME:SOCKET:ARTIFACTS[:METADATA]`` adds one HCR
    # session to ``hcrSessions``. The legacy single-target triad still
    # contributes one anonymous-target session so existing single-target
    # tests stay untouched. Per HCR §3.2 "Multi-Target HCR", every
    # session's patch lifecycle runs independently; a failure on one
    # session does NOT stop the others (see the per-session try/except
    # below).
    # --------------------------------------------------------------------
    var hcrSessions: seq[HcrWatchSession] = @[]
    if hcrConfig.hcrWatchEnabled:
      hcrSessions.add(initHcrWatchSession(hcrConfig))
    for cfg in hcrTargetConfigs:
      hcrSessions.add(initHcrWatchSession(cfg))
    defer:
      for i in 0 ..< hcrSessions.len:
        hcrSessions[i].closeHcrWatchSession()

    # Trace-Based-Incremental-Testing M2 -----------------------------------
    # When ``--ct-incremental`` is set, the watched target is treated as a
    # single test edge (the prototype assumption). We resolve the seam inputs
    # once: the test id is the resolved ``target`` selector, the source root is
    # the project root the trace's recorded paths resolve under, the trace dir
    # is ``--ct-incremental-trace-dir`` (defaulting to a fixed dir under the
    # project root), and the cache lives at the engine's default path under the
    # project root. On every *rebuild* cycle (cycle > 1, i.e. after a real
    # filesystem change) we call the pure ``watchTestEdgeDecision`` seam: if it
    # says skip, we emit ``skipped (unchanged: <test>)`` and do NOT re-run the
    # edge; otherwise we re-run and ``record`` the fresh trace. Cycle 1 (the
    # initial build) always runs + records so a baseline exists. None of this
    # executes when the flag is absent, keeping the legacy path unchanged.
    let ctProjectRoot = requestProjectRoot()
    let ctTestId = target
    let ctTraceDir =
      if ctFlags.traceDir.len > 0: ctFlags.traceDir
      else: ctProjectRoot / ".repro" / "ct-incremental" / "trace"
    let ctCachePath = defaultCachePath(ctProjectRoot)
    # The watch paths last computed from a real build outcome, reused by the
    # M2 skip branch so a skipped rebuild can resume watching the same paths
    # without a stale ``outcome`` from a prior (out-of-scope) loop iteration.
    var ctLastWatchPaths: seq[string] = @[]

    # The shared SSE emit hook for HCR events — wires each per-target
    # ``hcr/*`` event into the watch event stream so SSE consumers can
    # route by ``target`` (HCR/CLI-Integration §3.4).
    let hcrEmit: WatchHcrEventEmit =
      proc(eventKind, message, payloadJson: string) =
        emitWatchLine(message, payloadJson = payloadJson)

    var cycle = 0
    while true:
      if cancelCheck != nil and cancelCheck():
        return 130
      cycle.inc
      emitWatchLine("repro watch: cycle " & $cycle & " start" &
        (if cycle == 1: " initial" else: " rebuild"),
        payloadJson = "{\"watchEvent\":\"cycle-start\",\"cycle\":" & $cycle &
          "}")
      # Trace-Based-Incremental-Testing M2: on a rebuild cycle (cycle > 1,
      # triggered by a real filesystem change), consult the pure seam. A
      # ``weaSkip`` verdict means no executed function changed, so we report the
      # skip and loop straight back to watching WITHOUT re-running the test edge
      # or recording. Any non-skip verdict (fresh/changed/fail-safe error) falls
      # through to the normal build+record below.
      if ctFlags.enabled and cycle > 1:
        let ctDecision = watchTestEdgeDecision(
          ctTestId, ctTraceDir, ctProjectRoot, ctCachePath)
        if ctDecision.action == weaSkip:
          emitWatchLine("repro watch: skipped (unchanged: " &
              ctDecision.testId & ")",
            payloadJson = "{\"watchEvent\":\"ct-incremental\",\"decision\":" &
              "\"skip\",\"test\":\"" &
              ctDecision.testId.replace("\\", "\\\\").replace("\"", "\\\"") &
              "\"}",
            lastResult = "ct-incremental=skip test=" & ctDecision.testId)
          # Resume watching without re-running: rebuild the watcher over the
          # paths last computed from a real build outcome and block until the
          # next change.
          var skipWatcher = openFilesystemWatcher(ctLastWatchPaths)
          try:
            discard skipWatcher.waitForEvent(
              proc(): bool = cancelCheck != nil and cancelCheck())
            discard skipWatcher.drainDebouncedEvents(debounceMs)
          finally:
            skipWatcher.closeFilesystemWatcher()
          if maxCycles > 0 and cycle >= maxCycles:
            emitWatchLine("repro watch: max cycles reached",
              payloadJson = "{\"watchEvent\":\"max-cycles\"}", terminal = true,
              watchedPaths = @[], lastResult = "max-cycles")
            return 0
          continue
        else:
          emitWatchLine("repro watch: ct-incremental rerun (" &
              ctDecision.reason & ") test=" & ctDecision.testId,
            payloadJson = "{\"watchEvent\":\"ct-incremental\",\"decision\":" &
              "\"rerun\",\"test\":\"" &
              ctDecision.testId.replace("\\", "\\\\").replace("\"", "\\\"") &
              "\"}",
            lastResult = "ct-incremental=rerun test=" & ctDecision.testId)
      # Adapter: executeBuildTarget speaks the build-event shape; the watch
      # caller's eventSink takes additional terminal/exitCode/path fields.
      # Forwarding nested logSummary / logAction lines through the daemon
      # protocol is required so user-visible echoes (selectedTarget=,
      # scheduler=, defaultTarget=) reach the CLI instead of vanishing into
      # the daemon log when this watch runs daemon-hosted.
      let buildEventSink: BuildCommandEventSink =
        if eventSink == nil:
          nil
        else:
          proc(kind, message, payloadJson: string) =
            eventSink(kind, message, payloadJson, false, 0, @[], "")
      let outcome = executeBuildTarget(target, mode, publicCliPath,
        selectDefaultAction = targetWasOmitted,
        workRoot = workRoot,
        showSet = showSet,
        measureSet = measureSet,
        reportPersistence = reportPersistence,
        eventSink = buildEventSink,
        cancelCheck = cancelCheck,
        extraNameSelectors = extraNameSelectors)
      emitWatchLine("repro watch: cycle " & $cycle & " result exitCode=" &
        $outcome.exitCode,
        payloadJson = "{\"watchEvent\":\"cycle-result\",\"cycle\":" & $cycle &
          ",\"exitCode\":" & $outcome.exitCode & "}",
        exitCode = outcome.exitCode,
        lastResult = "cycle=" & $cycle & " exitCode=" & $outcome.exitCode)
      if outcome.exitCode != 0:
        return outcome.exitCode
      # Trace-Based-Incremental-Testing M2: the test edge actually ran this
      # cycle (fresh/changed/initial), so refresh the incremental cache from
      # the freshly-produced trace. ``recordWatchTestEdge`` execs codetracer's
      # ``ct test --incremental --watch-record`` (record + persist in one step);
      # a missing/unreadable trace or a failed ``ct`` is reported but not fatal —
      # the next decision then falls back to a re-run (fail-safe).
      if ctFlags.enabled:
        let rec = recordWatchTestEdge(ctTestId, ctTraceDir, ctProjectRoot,
          ctCachePath)
        if not rec.ok:
          emitWatchLine("repro watch: ct-incremental record skipped (" &
              rec.error & ")",
            payloadJson = "{\"watchEvent\":\"ct-incremental\",\"decision\":" &
              "\"record-error\"}")
      # Named-Targets M4: per-target HCR session lifecycle. Each enabled
      # session runs its own baseline (cycle 1) or patch delivery (cycle
      # N>1). A failure on any single session is isolated: the session
      # is marked ``fallbackOnly`` (no further HCR patches, plain
      # rebuilds only) and ``hcr/patchFailed`` is emitted exactly once
      # carrying ``target: NAME``. Other sessions in the seq keep going
      # — HCR §3.2 "Multi-Target HCR": "a failure to inject the agent
      # into one target does not stop the others".
      for i in 0 ..< hcrSessions.len:
        if not hcrSessions[i].enabled or hcrSessions[i].fallbackOnly:
          continue
        try:
          if cycle == 1:
            hcrSessions[i].captureHcrWatchBaseline(outcome, hcrEmit)
          else:
            hcrSessions[i].deliverHcrWatchPatch(outcome, cycle, hcrEmit)
        except HcrWatchNoChange:
          # Named-Targets M4: this target's source files did not change
          # this cycle. The rebuild was a cache hit for the target's
          # closure; per HCR §3.2 "patch lifecycles are independent",
          # we silently skip patch delivery (no SSE event) and leave
          # the session ready for the next cycle.
          discard
        except CatchableError as err:
          hcrSessions[i].fallbackOnly = true
          let errMsg = err.msg
          let targetLabel = hcrEventTargetLabel(hcrSessions[i].config)
          emitWatchLine("repro watch: hcr patch failed target=" &
              targetLabel & " error=" & errMsg & " (falling back to rebuilds)",
            payloadJson = hcrEventPayload(hcrSessions[i].config, %*{
              "error": errMsg,
              "fallback": "rebuild"
            }))
          # Close the failing session's listener / connection so the
          # socket file is released; subsequent cycles short-circuit
          # the lifecycle calls via ``fallbackOnly``.
          hcrSessions[i].closeHcrWatchSession()
      if maxCycles > 0 and cycle >= maxCycles:
        emitWatchLine("repro watch: max cycles reached",
          payloadJson = "{\"watchEvent\":\"max-cycles\"}", terminal = true,
          watchedPaths = @[], lastResult = "max-cycles")
        if statsCapture.enabled and daemonHosted:
          enqueueStatsObservation(scgSessions, "watch-finish", %*{
            "exitCode": 0,
            "cycles": cycle,
            "reason": "max-cycles"
          })
        return 0

      let paths = watchPathsFromOutcome(outcome)
      ctLastWatchPaths = paths
      var watcher = openFilesystemWatcher(paths)
      try:
        emitWatchLine("repro watch: watching paths=" &
          $watcher.watchedPathCount,
          payloadJson = "{\"watchEvent\":\"watching\",\"pathCount\":" &
            $watcher.watchedPathCount & "}",
          watchedPaths = paths)
        let event = watcher.waitForEvent(
          proc(): bool = cancelCheck != nil and cancelCheck())
        emitWatchLine("repro watch: event seen path=" & event.path &
          " detail=" & event.detail,
          payloadJson = "{\"watchEvent\":\"filesystem\",\"path\":\"" &
            event.path.replace("\\", "\\\\").replace("\"", "\\\"") &
            "\",\"detail\":\"" &
            event.detail.replace("\\", "\\\\").replace("\"", "\\\"") &
            "\"}",
          watchedPaths = paths)
        let coalesced = watcher.drainDebouncedEvents(debounceMs)
        emitWatchLine("repro watch: debounce complete coalesced=" & $coalesced,
          payloadJson = "{\"watchEvent\":\"debounce\",\"coalesced\":" &
            $coalesced & "}",
          watchedPaths = paths)
        emitWatchLine("repro watch: rebuild cycle after filesystem event",
          payloadJson = "{\"watchEvent\":\"rebuild-queued\"}",
          watchedPaths = paths)
      finally:
        watcher.closeFilesystemWatcher()

  if forceDirect or daemonMode == bdmOff:
    return runDirectWatch()

  try:
    return runDaemonWatch()
  except DaemonBuildUnsupported as err:
    if daemonMode == bdmRequire:
      raise newException(ValueError,
        "daemon mode required but repro-daemon cannot execute watch: " &
          err.msg)
    if statsCapture.enabled:
      raise newException(ValueError,
        "daemon-hosted stats capture requested but repro-daemon cannot " &
          "execute watch: " & err.msg)
    stderr.writeLine("repro watch: daemon watch unsupported; falling back " &
      "to direct mode: " & err.msg)
    return runDirectWatch()
  except CatchableError as err:
    if daemonMode == bdmRequire:
      raise newException(ValueError,
        "daemon mode required but repro-daemon is unavailable: " & err.msg)
    if statsCapture.enabled:
      raise newException(ValueError,
        "daemon-hosted stats capture requested but repro-daemon is unavailable: " &
          err.msg)
    stderr.writeLine("repro watch: daemon unavailable; falling back to " &
      "direct mode: " & err.msg)
    return runDirectWatch()

# ---- M22: `repro develop <pkg>` (workspace-overlay form) ------------------
#
# M22 adds the workspace-overlay form documented in
# ``reprobuild-specs/CLI/develop.md``: a bare positional ``<pkg>`` whose
# resolution targets the M6/M7/M8 resolver's package set (the
# ``ResolvedRepo.name`` of every repo declared by the active workspace).
#
# Two outcomes per invocation:
#
#   - ``--source=PATH`` provided: just register the override pointing at
#     the existing on-disk checkout. No VCS clone is scheduled.
#   - no ``--source``: clone the package's upstream URL into a workspace-
#     local conventional location (``<workspaceRoot>/develop/<pkg>``)
#     using the M2 ``bakWorkspaceVcs`` clone action, then register the
#     override pointing at the freshly-cloned tree.
#
# In both cases the override entry is appended via the M20 immutable
# ``addOverride`` helper and persisted with ``writeDevelopOverridesFile``.
# The engine-rebuild step is deferred along with the M21 engine wiring;
# the next ``repro build`` will pick up the override via the M21 resolver
# contract once that wiring lands. M22 is purely the operator-visible
# piece (clone + register + report).
#
# Exit codes (see ``CLI/develop.md`` Conflict And Reuse Rules):
#   - 0  success: clone + register, register-only, or idempotent re-develop
#         of the same package at the same source.
#   - 1  IO / VCS / resolution failure (e.g. unknown package in project,
#         missing ``--source`` path, clone failure, malformed manifest).
#   - 2  refused: an override already exists for the package at a
#         DIFFERENT on-disk source path. The operator must run
#         ``repro develop --drop <pkg>`` (future M22b) or hand-edit the
#         file before re-developing.
#
# JSON report path:
#   ``<workspaceRoot>/.repro/build/reports/develop-report.json``.

type
  WorkspaceDevelopReport* = object
    ## Structured outcome of one ``repro develop <pkg>`` invocation in
    ## the M22 workspace-overlay form. ``mode`` is one of:
    ##
    ##   - ``cloned``       — no ``--source`` provided; the dispatcher
    ##                         cloned the package's upstream URL into
    ##                         ``<workspaceRoot>/develop/<pkg>`` and
    ##                         registered the override pointing at it.
    ##   - ``registered``   — ``--source=PATH`` provided; the dispatcher
    ##                         registered the override pointing at the
    ##                         pre-existing checkout, with no clone.
    ##   - ``idempotent``   — an override already existed for ``pkg`` at
    ##                         the SAME on-disk path; the dispatcher
    ##                         re-emitted the report and returned 0.
    ##   - ``refused``      — an override already existed for ``pkg`` at
    ##                         a DIFFERENT on-disk path; the dispatcher
    ##                         did NOT modify the file and returned 2.
    ##   - ``error``        — IO / VCS / resolve failure; the dispatcher
    ##                         returned 1.
    package*: string
    source*: string
    mode*: string
    workspaceRoot*: string
    project*: string
    overridePackage*: string
    overrideLocalPath*: string
    overrideState*: string
    overrideCreatedAt*: string
    overrideProvenance*: string
    diagnostic*: string
    exitCode*: int

proc toJsonNode*(report: WorkspaceDevelopReport): JsonNode =
  result = newJObject()
  result["pkg"] = %report.package
  result["source"] = %report.source
  result["mode"] = %report.mode
  result["workspaceRoot"] = %report.workspaceRoot
  result["project"] = %report.project
  var entry = newJObject()
  entry["package"] = %report.overridePackage
  entry["local_path"] = %report.overrideLocalPath
  entry["state"] = %report.overrideState
  entry["created_at"] = %report.overrideCreatedAt
  if report.overrideProvenance.len > 0:
    entry["provenance"] = %report.overrideProvenance
  result["overrideEntry"] = entry
  if report.diagnostic.len > 0:
    result["diagnostic"] = %report.diagnostic
  result["exitCode"] = %report.exitCode

proc renderDevelopTextLines*(report: WorkspaceDevelopReport): seq[string] =
  case report.mode
  of "cloned":
    result.add("repro develop: cloned " & report.package & " into " &
      report.overrideLocalPath)
    result.add("repro develop: registered override for " & report.package &
      " (next build will pick it up via the M21 resolver)")
  of "registered":
    result.add("repro develop: registered override for " & report.package &
      " → " & report.overrideLocalPath &
      " (next build will pick it up via the M21 resolver)")
  of "idempotent":
    result.add("repro develop: " & report.package &
      " already in develop mode at " & report.overrideLocalPath &
      " (no change)")
  of "refused":
    result.add("repro develop: refused — override for " & report.package &
      " already points at a different path: " & report.overrideLocalPath)
    if report.diagnostic.len > 0:
      result.add("repro develop: " & report.diagnostic)
  else:
    if report.diagnostic.len > 0:
      result.add("repro develop: error — " & report.diagnostic)

type
  WorkspaceDevelopArgs = object
    package: string
    sourcePath: string
    workspaceRoot: string
    toolProvisioning: ToolProvisioningMode
    json: bool
    explicitWorkspaceRoot: bool
    explicitSource: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseDevelopArgs*(args: openArray[string]): WorkspaceDevelopArgs =
  ## ``repro develop <pkg> [--source=PATH] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## Mirrors the M9 ``parseWorkspaceInitArgs`` shape. The positional
  ## ``<pkg>`` is required and must NOT be combined with ``--``,
  ## ``--cmake``, ``--list``, or ``--into`` (those route to the existing
  ## pre-M22 develop forms). ``--source`` and ``--workspace-root`` accept
  ## both ``flag=value`` and ``flag value`` forms.
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--source" or arg.startsWith("--source="):
      result.sourcePath = valueFromFlag(args, i, "--source")
      result.explicitSource = true
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
      result.explicitWorkspaceRoot = true
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro develop` flag in M22 workspace-overlay form: " &
          arg)
    elif result.package.len == 0:
      result.package = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro develop <pkg>`: " & arg)
    inc i
  if result.package.len == 0:
    raise newException(ValueError,
      "`repro develop <pkg>` requires a package name")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveDevelopWorkspacePrimary(
    workspaceRoot: string): ResolvedProject =
  ## M22 reuses the M9/M10 dispatch rule. Composer wins when
  ## ``.repro/workspace.toml`` declares layers; otherwise we look up the
  ## single recorded project name (via the M13 metadata-only
  ## workspace.toml) or fall back to a single ``projects/*.toml`` if
  ## exactly one exists. A workspace with no resolvable project surfaces
  ## as a ``ValueError`` so the dispatcher exits 1 with a clear message.
  let workspaceToml = workspaceTomlPath(workspaceRoot)
  if isCompositionalWorkspaceToml(workspaceRoot):
    return composeManifestLayersFromFile(workspaceToml)
  let manifestsRoot = manifestsRoot(workspaceRoot)
  if fileExists(workspaceToml):
    try:
      let recorded = readWorkspaceLocal(absolutePath(workspaceToml))
      if recorded.workspace.project.len > 0:
        let projectFile = manifestsRoot / "projects" /
          (recorded.workspace.project & ".toml")
        let variantFile = manifestsRoot / "variants" /
          (recorded.workspace.project & ".toml")
        if fileExists(projectFile):
          return resolveProject(projectFile)
        if fileExists(variantFile):
          return resolveVariant(variantFile)
    except WorkspaceManifestParseError:
      discard
  # Last resort: a workspace with exactly one ``projects/*.toml`` and no
  # metadata file. M22's primary callers always have a workspace.toml
  # (M9 init writes one) so this arm mostly serves tests that pre-seed
  # only the project file.
  let projectsDir = manifestsRoot / "projects"
  if dirExists(projectsDir):
    var candidates: seq[string]
    for kind, path in walkDir(projectsDir):
      if kind == pcFile and path.endsWith(".toml"):
        candidates.add(path)
    if candidates.len == 1:
      return resolveProject(candidates[0])
  raise newException(ValueError,
    "`repro develop` could not resolve a project from workspace root '" &
      workspaceRoot & "' (no .repro/workspace.toml and no single " &
      "projects/*.toml at the workspace root)")

proc resolveDevelopWorkspaceProject(
    workspaceRoot: string): ResolvedProject =
  ## PS-2 — the develop-set candidates are every repo the workspace
  ## participates in, so the primary project resolved above is extended with
  ## the rest of the active project set. Unchanged for single-project
  ## workspaces.
  extendWithActiveProjectSet(workspaceRoot,
    resolveDevelopWorkspacePrimary(workspaceRoot))

proc safeDevelopPathSegment(value: string): string =
  ## File-system safe segment for the develop subdir. Mirrors
  ## ``safeRepoIdSegment`` (only ASCII letters/digits and a couple of
  ## punctuation chars survive untouched) but with a different name so
  ## the two helpers can diverge later if needed.
  for ch in value:
    if ch in {'A'..'Z', 'a'..'z', '0'..'9', '-', '_', '.'}:
      result.add(ch)
    else:
      result.add('-')
  if result.len == 0:
    result = "pkg"

proc cloneForDevelop(workspaceRoot, pkg, fetchUrl, revision: string;
                    identity: GitToolIdentity): tuple[ok: bool; path: string;
                                                    diagnostic: string] =
  ## Schedule a one-shot ``bakWorkspaceVcs`` clone of ``fetchUrl`` into
  ## ``<workspaceRoot>/develop/<pkg>``. The target directory must NOT
  ## pre-exist (the clone action refuses to clone into a non-empty
  ## path); the dispatcher checks for collisions before reaching here.
  ## Returns the absolute target path on success.
  let relTarget = "develop" / safeDevelopPathSegment(pkg)
  let absTarget = workspaceRoot / relTarget
  if dirExists(absTarget):
    return (ok: false, path: absTarget,
      diagnostic: "develop clone target already exists: " & absTarget)
  let receiptDir = workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  let receiptRel = ".repro" / "workspace" / "receipts" /
    ("develop-clone-" & safeDevelopPathSegment(pkg) & ".receipt")
  let actionId = "workspace-develop-clone-" & safeDevelopPathSegment(pkg)
  var action = gitCloneAction(actionId, identity,
    remoteUrl = fetchUrl,
    repoPath = relTarget,
    receiptPath = receiptRel,
    revision = revision)
  action.cwd = workspaceRoot
  let cacheRoot = workspaceRoot / ".repro" / "workspace" / "engine-cache"
  var config = defaultBuildEngineConfig(cacheRoot)
  config.suppressTrace = true
  let res = runBuild(graph([action]), config)
  if res.results.len == 0:
    return (ok: false, path: absTarget,
      diagnostic: "build engine returned no results for develop clone")
  let outcome = res.results[0]
  if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
    return (ok: false, path: absTarget,
      diagnostic: "develop clone failed: status=" & $outcome.status &
        " reason=" & outcome.reason &
        (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: ""))
  (ok: true, path: absTarget, diagnostic: "")

proc currentRfc3339Timestamp(): string =
  ## ISO-8601 UTC timestamp formatted as ``YYYY-MM-DDTHH:MM:SSZ`` so the
  ## M20 strict reader's ``created_at`` field round-trips byte-for-byte.
  let t = utc(now())
  t.format("yyyy-MM-dd'T'HH:mm:ss") & "Z"

proc executeWorkspaceDevelop(args: WorkspaceDevelopArgs):
    WorkspaceDevelopReport =
  ## End-to-end M22 driver. (1) Resolve the active project. (2) Check
  ## that ``args.package`` is declared as a ``ResolvedRepo.name``;
  ## otherwise exit 1 naming the project file. (3) Decide between
  ## clone-and-register and just-register. (4) Read the existing M20
  ## override file (if any) and detect idempotent / collision arms.
  ## (5) Persist the updated override via ``writeDevelopOverridesFile``.
  result.package = args.package
  result.workspaceRoot = args.workspaceRoot

  # Step 1: resolve the workspace's active project.
  var resolved: ResolvedProject
  try:
    resolved = resolveDevelopWorkspaceProject(args.workspaceRoot)
  except CatchableError as err:
    result.mode = "error"
    result.diagnostic = err.msg
    result.exitCode = 1
    return result
  result.project = resolved.projectName

  # Step 2: verify the package is declared.
  var matched: ResolvedRepo
  var found = false
  for repo in resolved.repos:
    if repo.name == args.package:
      matched = repo
      found = true
      break
  if not found:
    result.mode = "error"
    result.diagnostic = "package '" & args.package &
      "' is not declared in project '" & resolved.projectName &
      "' (project file: " & resolved.projectFile & ")"
    result.exitCode = 1
    return result

  # Step 3: determine the on-disk source path.
  var sourcePath = ""
  var willClone = false
  if args.explicitSource:
    if args.sourcePath.len == 0:
      result.mode = "error"
      result.diagnostic = "`--source` requires a path value"
      result.exitCode = 1
      return result
    sourcePath = absolutePath(args.sourcePath)
    if not dirExists(sourcePath):
      result.mode = "error"
      result.diagnostic = "`--source` path does not exist: " & sourcePath
      result.exitCode = 1
      return result
  else:
    sourcePath = absolutePath(
      args.workspaceRoot / "develop" / safeDevelopPathSegment(args.package))
    willClone = true
  result.source = sourcePath

  # Step 4: load the existing override file (if any) and check the
  # idempotent / collision arms BEFORE doing any side-effecting work.
  var existingFile: DevelopOverrides
  let existingOpt =
    try:
      readDevelopOverridesFile(args.workspaceRoot)
    except WorkspaceManifestParseError as e:
      result.mode = "error"
      result.diagnostic = "failed to read existing develop-overrides.toml: " &
        e.msg
      result.exitCode = 1
      return result
  if existingOpt.isSome:
    existingFile = existingOpt.get()
  else:
    existingFile = newDevelopOverrides()

  let priorOpt = findOverride(existingFile, args.package)
  if priorOpt.isSome:
    let prior = priorOpt.get()
    let priorAbs = absolutePath(prior.local_path)
    if priorAbs == sourcePath:
      # Idempotent: same package, same path → no-op (exit 0).
      result.mode = "idempotent"
      result.overridePackage = prior.package
      result.overrideLocalPath = prior.local_path
      result.overrideState = prior.state
      result.overrideCreatedAt = prior.created_at
      if prior.provenance.isSome:
        result.overrideProvenance = prior.provenance.get()
      result.exitCode = 0
      return result
    else:
      # Collision: same package, different path → refuse (exit 2).
      result.mode = "refused"
      result.overridePackage = prior.package
      result.overrideLocalPath = prior.local_path
      result.overrideState = prior.state
      result.overrideCreatedAt = prior.created_at
      if prior.provenance.isSome:
        result.overrideProvenance = prior.provenance.get()
      result.diagnostic = "existing override at " & prior.local_path &
        " does not match requested source " & sourcePath &
        "; drop or relocate the existing override before re-developing"
      result.exitCode = 2
      return result

  # Step 5: clone if needed.
  if willClone:
    var identity: GitToolIdentity
    try:
      identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
      installGitVcsExecutor()
    except CatchableError as err:
      result.mode = "error"
      result.diagnostic = "git tool not resolvable: " & err.msg
      result.exitCode = 1
      return result
    let cloneRes = cloneForDevelop(args.workspaceRoot, args.package,
      cloneUrlFor(matched), matched.revision, identity)
    if not cloneRes.ok:
      result.mode = "error"
      result.diagnostic = cloneRes.diagnostic
      result.exitCode = 1
      return result
    sourcePath = cloneRes.path
    result.source = sourcePath

  # Step 6: register the override.
  let stability = "editable"
  let createdAt = currentRfc3339Timestamp()
  let provenance = "repro develop " & args.package
  var entry: repro_workspace_manifests.DevelopOverrideEntry
  entry.package = args.package
  entry.local_path = sourcePath
  entry.state = stability
  entry.created_at = createdAt
  entry.provenance = some(provenance)
  let updated = addOverride(existingFile, entry)
  try:
    writeDevelopOverridesFile(args.workspaceRoot, updated)
  except CatchableError as err:
    result.mode = "error"
    result.diagnostic = "failed to write develop-overrides.toml: " & err.msg
    result.exitCode = 1
    return result

  result.mode =
    if willClone: "cloned"
    else: "registered"
  result.overridePackage = entry.package
  result.overrideLocalPath = entry.local_path
  result.overrideState = entry.state
  result.overrideCreatedAt = entry.created_at
  result.overrideProvenance = provenance
  result.exitCode = 0

proc writeWorkspaceDevelopReport(report: WorkspaceDevelopReport;
                                 destination: string) =
  ## Persist the JSON view alongside the other workspace dispatcher
  ## reports (``init-report.json``, ``sync-report.json`` etc.) so
  ## downstream tooling can read one well-known location. Opt-in: only
  ## written when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  try:
    createDir(parentDir(destination))
  except CatchableError:
    return
  try:
    writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")
  except CatchableError:
    discard

proc runWorkspaceDevelopCommand*(args: openArray[string]): int =
  ## ``repro develop <pkg> [--source=PATH] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## M22 workspace-overlay dispatcher: clone the package (via M2 VCS
  ## actions) or just register the override (when ``--source`` points at
  ## a pre-existing checkout), then persist the entry in
  ## ``<workspaceRoot>/.repro/develop-overrides.toml`` via M20.
  let parsed = parseDevelopArgs(args)
  let report = executeWorkspaceDevelop(parsed)
  writeWorkspaceDevelopReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "develop"))
  stageFailureReport(parsed.report, report.workspaceRoot, "develop",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderDevelopTextLines(report):
      if report.exitCode == 0:
        stdout.writeLine(line)
      else:
        stderr.writeLine(line)
  report.exitCode

# ---------------------------------------------------------------------------
# L1 REPRO-DEVELOP-ALL — `repro develop --all` (and the related --direct /
# --transitive-of / --filter / --into selection flags).
#
# Spec: reprobuild-specs/Reprobuild-Lock-Driven-Provisioning-And-Publish-
# Scope.milestones.org §L1; CLI/develop.md; Workspace-And-Develop-Mode.md;
# Locking-And-Solver.md.
#
# From inside a project/workspace that carries a committed ``repro.lock``, the
# ``--all`` form resolves the develop SET over the solved graph / lock, clones
# each selected dependency at its LOCK-PINNED revision into a sibling checkout
# (reusing a suitable existing checkout over duplicating), and records the
# ``solved node -> local path`` override in the local, non-versioned M20
# ``.repro/develop-overrides.toml``. It FAILS LOUD on a missing lock and on an
# unmappable node (no branch-tip fallback).
#
# This is DELIBERATELY built on the existing lock/override machinery rather
# than reinventing it:
#   * the develop set + its pinned coordinates come from ``populateLockedDeps``
#     (``LockSource(kind: lskCommittedLock, ...)``), the ONE committed-lock
#     reader that yields ``LockedDep`` with VCS ``Coordinates`` (url, ref,
#     revision) + integrity — the source-of-record Locking-And-Solver.md names;
#   * the clone is the same cacheable ``bakWorkspaceVcs`` engine action the M22
#     single-target path and ``workspace sync`` use, followed by a
#     ``gitForceResetAction`` so the checkout lands at the EXACT locked SHA
#     (``git clone --branch`` alone only pins a branch/tag, not a bare commit);
#   * the override is written through the M20 ``addOverride`` /
#     ``writeDevelopOverridesFile`` helpers (the same file M21 reads to shadow
#     upstream bindings so nix-flake sibling detection resolves the dep locally).
# ---------------------------------------------------------------------------

type
  DevelopAllSelectionMode = enum
    dasmAll            ## every dependency node in the lock (the closure)
    dasmDirect         ## only the root repo's direct dependency edges
    dasmIndirect       ## DS-7 — everything the closure holds that is NOT a
                       ## direct edge of the root repo (specified in the V1
                       ## proposal since the beginning, never implemented)
    dasmTransitiveOf   ## the transitive closure below one named dependency

  DevelopAdhocLockStore = object
    ## DS-8 — one ``--lock-store=[<tier>:]<kind>:<location>`` declaration.
    ## An INVOCATION-LAYER route (``clkInvocation``, above every configuration
    ## file layer), so it composes with the configuration plane through the
    ## same precedence vocabulary rather than bypassing it.
    tier: WorkspaceVisibility
    tierExplicit: bool       ## whether the argv named the tier, or it came
                             ## from the documented `team` default (which is
                             ## ANNOUNCED, never silent — see
                             ## ``parseAdhocLockStore``)
    kind: string             ## one of the five MO-3 backend kinds
    location: string         ## path (or program, for ``external-cli``)
    spec: string             ## the verbatim argv value, for diagnostics

  DevelopSelectionStage = object
    ## DS-7 — one stage of the FIXED composition order, and how many repos
    ## survived it. Emitted in the report so "each stage narrows the previous
    ## one" is OBSERVABLE: swapping two stages changes these counts, which is
    ## what makes the fixed order testable rather than merely asserted.
    stage: string            ## mode / project / group / filter / only / except
    flag: string             ## the flag text this stage applied ("" = inactive)
    kept: int                ## repos remaining AFTER this stage

  DevelopAllArgs = object
    mode: DevelopAllSelectionMode
    transitiveOf: string
    filter: string           ## ``--filter=<glob>`` (CLI/develop.md §"Membership
                             ## axis") — a GLOB (``*`` / ``?``), matched against
                             ## the whole repo name. It may legitimately match
                             ## nothing, which is an empty selection, NOT an
                             ## error (unlike the exact-name selectors).
    only: seq[string]        ## ``--only=<list>`` — keep ONLY these exact names
                             ## (CLI/develop.md §"Membership axis"). Names are
                             ## matched EXACTLY; a name matching nothing is a
                             ## loud error, never a silent no-op.
    exceptNames: seq[string]     ## ``--except=<list>`` — REMOVE these exact names.
                             ## Same exact-name loudness as ``--only``.
    projects: seq[string]    ## ``--project=<list>`` — keep only repos
                             ## contributed by these projects of the ACTIVE
                             ## PROJECT SET. This is a MEMBERSHIP filter and is
                             ## deliberately NOT the lock-record key: a
                             ## commit-addressed record is keyed on the PRIMARY
                             ## project (Workspace-And-Develop-Mode.md §"The
                             ## Primary Project") whatever ``--project`` says.
    tags: seq[string]        ## ``--tag=<list>`` — keep only repos carrying
                             ## these manifest tags (``repos/<repo>.toml``
                             ## ``tags``; a repo with no declared tags is
                             ## in the implicit ``default`` tag).
    tiers: seq[string]       ## DS-8 ``--tier=<list>`` — restrict which TIERS'
                             ## backends contribute records at all. A SOURCE
                             ## axis flag: it narrows the lock set itself, not
                             ## the selection over it.
    lockStores: seq[DevelopAdhocLockStore]
                             ## DS-8 ``--lock-store=<kind>:<location>``,
                             ## repeatable, in INCREASING precedence.
    at: string               ## DS-5 ``--at=<rev>`` — key commit-addressed
                             ## backends on this revision instead of the
                             ## workspace root repo's ``HEAD``.
    list: bool               ## DS-6 ``--list`` — print the resolved lock set
                             ## and exit; mutate nothing.
    intoDir: string          ## ``--into=<dir>`` checkout-placement root (empty
                             ## = sibling ``../<name>`` default)
    workspaceRoot: string
    toolProvisioning: ToolProvisioningMode
    json: bool
    reset: bool              ## ``--reset`` — when an existing on-disk checkout
                             ## has DRIFTED off the locked revision, force it
                             ## back to the lock (destructive re-clone at the
                             ## locked SHA) instead of refusing. Opt-in; the
                             ## default (false) preserves the refuse-on-drift
                             ## contract so fleet consumers are unaffected. This
                             ## is the lever CI uses to reconcile siblings that a
                             ## prior clone step placed at a `=dev` branch tip.
    strict: bool             ## DS-3 — ``--strict`` promotes the personal-tier
                             ## unreachable-backend WARNING to the same refusal
                             ## the public/team tiers get.
    dryRun: bool             ## ``--dry-run`` (CLI/develop.md §"Action axis") —
                             ## resolve the lock set and print the actions that
                             ## WOULD be taken, then exit. Mutates NOTHING: no
                             ## clone, no reset, no override file write. It is
                             ## the query form of the placement step, the way
                             ## ``--list`` is the query form of the lock set.

  DevelopAllNodeOutcome = object
    node: string
    path: string
    revision: string
    mode: string             ## cloned / adopted / reset / idempotent / refused
                             ## / error, plus the ``--dry-run`` plan modes
                             ## would-clone / would-reset
    diagnostic: string
    ok: bool

# ---------------------------------------------------------------------------
# DS-1..DS-4 — the develop-set lock-set composer.
#
# Spec: reprobuild-specs/CLI/develop.md §"The Develop Set Is The Workspace Lock
# Set"; Unified-Locking-And-Hooks.md §2-§5 (the two planes, the four schemes,
# the (tier, backend) resolution) and §7 (evidence-only);
# Workspace-Manifests.md §"Populating the locked-dependency model".
#
#   > Whenever Reprobuild looks at a project in a workspace, it can determine
#   > the set of projects that workspace's lock files manage. That set — the
#   > whole of it, across every lock backend — is what `repro develop` operates
#   > on.
#
# Before DS-1 ``executeDevelopAll`` read ``committedLockPath(root)`` and
# NOTHING else, so a workspace that declares a team or personal route (which is
# what ``repro locking adopt-manifest`` writes) could not see its own
# team-tier repos at all. The composer resolves the CONFIGURATION PLANE
# (``composeLockingRouting`` -> ``resolveRepoBackends``), then folds EVERY
# distinct resolved backend through the ONE ``populateLockedDeps(source)``
# entry point into a single ``LockedDependencies``.
#
# A workspace with no routing config resolves to the built-in public default
# alone, so its lock set IS the committed lock and the composed result is
# byte-identical to the pre-DS-1 read (``t_develop_public_only_unchanged``).
# ---------------------------------------------------------------------------

type
  DevelopBackendReport = object
    ## One distinct ``(tier, backend)`` the composer folded, and whether its
    ## medium could be read at all. Reported so a narrowed set is always
    ## attributable to a named backend.
    tier: string             ## public / org / team / personal
    backendKind: string
    location: string
    reachable: bool
    diagnostic: string
    repos: seq[string]       ## the repos this backend was asked about
    records: int             ## how many lock records it actually contributed
    adhoc: bool              ## DS-8 — declared by ``--lock-store`` rather than
                             ## by a configuration file layer
    excluded: bool           ## DS-8 — present and readable, but ``--tier``
                             ## excluded its tier from contributing
    keyedOn: string          ## DS-5 — the commit this commit-addressed backend
                             ## was keyed on (empty when not commit-addressed
                             ## or when the workspace names no root repo)

  DevelopLockSet = object
    ## The composed workspace lock set. ``lock`` is the union across every
    ## backend; the remaining fields are what the union could NOT say, kept
    ## separate so nothing is dropped silently.
    lock: LockedDependencies
    backends: seq[DevelopBackendReport]
    refusals: seq[string]    ## fatal: conflicting revisions, an unreachable
                             ## public/team backend, an unroutable repo
    warnings: seq[string]    ## non-fatal: an unreachable PERSONAL backend
    omitted: seq[string]     ## repos an unreachable backend removed from the set
    noRecord: seq[string]    ## repos a reachable backend held no exact pin for
    tierOf: Table[string, string]      ## repo name -> resolved tier
    backendOf: Table[string, string]   ## repo name -> resolved backend kind
    locationOf: Table[string, string]  ## repo name -> backend location label
    pinTierOf: Table[string, string]
      ## DS-6 — repo name -> the tier of the backend that ACTUALLY SUPPLIED the
      ## entry now in the union. Deliberately distinct from ``tierOf``, which
      ## is the repo's RESOLVED ``(tier, backend)`` ASSIGNMENT. The two differ
      ## whenever a repo is assigned to one backend and pinned by another —
      ## most visibly under ``--lock-store``, whose invocation-layer route
      ## claims every participating repo, so a public repo whose pin still
      ## comes from the committed lock is ASSIGNED to the ad-hoc backend. The
      ## `--list` columns report the PIN's provenance, because "which backend
      ## does this revision come from" is the question a lock-set listing
      ## answers; the assignment drives the routing diagnostics.
    pinBackendOf: Table[string, string]
    tagsOf: Table[string, seq[string]]
      ## DS-7 — repo name -> its EFFECTIVE manifest groups (``groups`` when
      ## declared, else the implicit ``["default"]``), read from the resolved
      ## manifest membership. Carried on the lock set because selection runs
      ## over ``LockedDep``s, which have no group field.
    projectsOf: Table[string, seq[string]]
      ## DS-7 — repo name -> the projects of the ACTIVE PROJECT SET that
      ## contribute it. MEMBERSHIP only: lock-record lookup is keyed on the
      ## PRIMARY project regardless (see ``DevelopAllArgs.projects``).
    activeProjects: seq[string]        ## the active project set, in order
    knownTags: seq[string]             ## every tag any participating repo carries
    keyNotes: seq[string]  ## DS-5 — one line per commit-addressed backend whose
                           ## record was found at an ANCESTOR of the requested
                           ## key rather than at the key itself

  DevelopListRow = object
    ## DS-6 — one row of ``repro develop --list``: the six columns
    ## CLI/develop.md §"Action axis" names.
    name: string
    tier: string
    backend: string
    revision: string
    path: string
    state: string            ## absent / at-lock / drifted / develop /
                             ## evidence-only

  DevelopAllResult = object
    ## Everything one ``repro develop`` set-form invocation produced. Grown
    ## from the pre-DS-6 ``(outcomes, notices, exitCode)`` tuple so the query
    ## forms can carry their own payload without a second driver.
    outcomes: seq[DevelopAllNodeOutcome]
    notices: seq[string]
    exitCode: int
    listed: bool             ## DS-6 — this run was a ``--list`` query
    rows: seq[DevelopListRow]
    stages: seq[DevelopSelectionStage]
    backends: seq[DevelopBackendReport]

proc composeDevelopLockSet(workspaceRoot: string; identity: GitToolIdentity;
                           args: DevelopAllArgs): DevelopLockSet
  ## Forward declaration: the body needs the configuration plane
  ## (``composeLockingRouting`` / ``resolveRepoBackends``) and the
  ## ``LockStore`` backends, which are declared far below this driver.

proc isRootLockedDep(d: LockedDep): bool =
  ## The workspace root repo is recorded with ``path == "."`` (or empty). It is
  ## the CONSUMER, not a develop-set dependency, so ``--all`` never clones it.
  d.path.len == 0 or d.path == "."

proc isEvidenceOnlyLockedDep(d: LockedDep): bool
  ## DS-4 (Unified-Locking-And-Hooks.md §7) — an evidence-only repo
  ## participates by publishing a source-free evidence triple and NEVER its
  ## source, so it has no obtainable source by construction and is never placed
  ## into develop mode. Defined beside ``isEvidenceOnlyRepo`` (the
  ## ``ResolvedRepo`` sibling) so both read the SAME
  ## ``participationEvidenceOnly`` constant.

proc developNameGlobMatches*(name, pattern: string): bool =
  ## DS-7 — ``--filter=<glob>``. ``*`` matches any (possibly empty) run of
  ## characters, ``?`` matches exactly one; every other character is literal
  ## and the whole NAME must be consumed. A pattern carrying no metacharacter
  ## therefore matches EXACTLY one name, not every name containing it — the
  ## glob is a glob, not a substring test, and a user who wants a substring
  ## writes ``*sub*``. Deliberately anchored at both ends for the same reason
  ## ``--only`` is exact: a selector that quietly matches more than it looks
  ## like it matches is how a bulk mutation hits a repo nobody named.
  var i, j = 0
  var starI = -1
  var starJ = 0
  while i < name.len:
    if j < pattern.len and (pattern[j] == '?' or pattern[j] == name[i]):
      inc i; inc j
    elif j < pattern.len and pattern[j] == '*':
      starI = i; starJ = j; inc j
    elif starI >= 0:
      inc starI; i = starI; j = starJ + 1
    else:
      return false
  while j < pattern.len and pattern[j] == '*': inc j
  j == pattern.len

proc developSetFromLock(lock: LockedDependencies; composed: DevelopLockSet;
                        args: DevelopAllArgs;
                        keepEvidenceOnly = false):
    tuple[nodes: seq[LockedDep]; stages: seq[DevelopSelectionStage]] =
  ## DS-7 — the MEMBERSHIP AXIS. Resolve the requested selection to the
  ## concrete solved dependency nodes (per CLI/develop.md: "resolve the
  ## requested selection to concrete solved dependency nodes before deciding
  ## where any checkout should live").
  ##
  ## Selection is orthogonal to checkout placement — this proc only picks the
  ## SET; the caller maps each node to a path.
  ##
  ## The selectors compose in the spec's **FIXED ORDER**, each stage narrowing
  ## the previous one:
  ##
  ##   1. mode (``--all`` | ``--direct`` | ``--indirect`` | ``--transitive-of``)
  ##   2. ``--project``   3. ``--tag``     4. ``--filter``
  ##   5. ``--only``      6. ``--except``
  ##
  ## The order is fixed **so the result never depends on argv order**. Every
  ## stage is a set intersection or subtraction over the same universe, and the
  ## flags are read into a value BEFORE any of them is applied, so no stage can
  ## observe where in the argv its flag appeared. The per-stage ``kept`` counts
  ## are returned (and printed) precisely so the order is OBSERVABLE rather
  ## than merely asserted: swapping any two stages changes them.
  # Index by name for the edge-following selection modes.
  var byName = initTable[string, LockedDep]()
  for d in lock.deps:
    if d.name.len > 0:
      byName[d.name] = d

  # ---- stage 1: mode ------------------------------------------------------
  var selectedNames: seq[string]
  var modeFlag = "--all"
  proc directEdges(): HashSet[string] =
    result = initHashSet[string]()
    for d in lock.deps:
      if isRootLockedDep(d):
        for dep in d.depends: result.incl(dep)
  case args.mode
  of dasmAll:
    for d in lock.deps:
      if not isRootLockedDep(d):
        selectedNames.add(d.name)
  of dasmDirect:
    # The root repo's declared ``depends`` edges name its DIRECT dependencies.
    modeFlag = "--direct"
    for d in lock.deps:
      if isRootLockedDep(d):
        for dep in d.depends:
          selectedNames.add(dep)
  of dasmIndirect:
    # DS-7 — "all indirect dependencies": the closure MINUS the root repo's
    # direct edges. Specified in the V1 proposal from the start and never
    # implemented; ``--indirect`` used to be rejected as an unsupported flag.
    modeFlag = "--indirect"
    let direct = directEdges()
    for d in lock.deps:
      if not isRootLockedDep(d) and d.name notin direct:
        selectedNames.add(d.name)
  of dasmTransitiveOf:
    modeFlag = "--transitive-of=" & args.transitiveOf
    if args.transitiveOf notin byName:
      return (@[], @[DevelopSelectionStage(stage: "mode", flag: modeFlag,
        kept: 0)])   # caller reports the unmappable root name
    var pending = @[args.transitiveOf]
    var seen = initHashSet[string]()
    while pending.len > 0:
      let cur = pending.pop()
      if cur in seen: continue
      seen.incl(cur)
      let d = byName.getOrDefault(cur)
      for dep in d.depends:
        if dep notin seen:
          pending.add(dep)
      # The named root itself is INCLUDED in its transitive set (it is a dep of
      # the consumer, just like everything below it).
      selectedNames.add(cur)

  # Materialize stage 1 into a de-duplicated, name-sorted working set so every
  # later stage — and the report, and the clone scheduling — is deterministic.
  var working: seq[string]
  var emitted = initHashSet[string]()
  for name in selectedNames:
    if name in emitted or name notin byName: continue
    # DS-4 — an evidence-only repo is NEVER placed into develop mode: it
    # publishes a source-free evidence triple and never its source, so there is
    # no checkout to make. The caller enumerates the exclusions; naming one
    # explicitly is a loud error handled there, never a silent omission here.
    # ``--list`` (DS-6) passes ``keepEvidenceOnly`` because a QUERY must SHOW
    # the repo with state `evidence-only` rather than hide it.
    if not keepEvidenceOnly and isEvidenceOnlyLockedDep(byName[name]): continue
    emitted.incl(name)
    working.add(name)
  working.sort()
  var stages = @[DevelopSelectionStage(stage: "mode", flag: modeFlag,
    kept: working.len)]

  proc narrow(stage, flag: string; keep: proc (n: string): bool {.closure.}) =
    if flag.len == 0:
      stages.add(DevelopSelectionStage(stage: stage, flag: "",
        kept: working.len))
      return
    var next: seq[string]
    for n in working:
      if keep(n): next.add(n)
    working = next
    stages.add(DevelopSelectionStage(stage: stage, flag: flag,
      kept: working.len))

  # ---- stage 2: --project -------------------------------------------------
  var projectSet = initHashSet[string]()
  for p in args.projects: projectSet.incl(p)
  narrow("project",
    (if args.projects.len > 0: "--project=" & args.projects.join(",") else: ""),
    proc (n: string): bool =
      for p in composed.projectsOf.getOrDefault(n, @[]):
        if p in projectSet: return true
      false)

  # ---- stage 3: --tag -----------------------------------------------------
  var tagSet = initHashSet[string]()
  for t in args.tags: tagSet.incl(t)
  narrow("tag",
    (if args.tags.len > 0: "--tag=" & args.tags.join(",") else: ""),
    proc (n: string): bool =
      for t in composed.tagsOf.getOrDefault(n, @[]):
        if t in tagSet: return true
      false)

  # ---- stage 4: --filter (a GLOB; may legitimately match nothing) ---------
  narrow("filter",
    (if args.filter.len > 0: "--filter=" & args.filter else: ""),
    proc (n: string): bool = developNameGlobMatches(n, args.filter))

  # ---- stage 5: --only (EXACT names) --------------------------------------
  var onlySet = initHashSet[string]()
  for n in args.only: onlySet.incl(n)
  narrow("only",
    (if args.only.len > 0: "--only=" & args.only.join(",") else: ""),
    proc (n: string): bool = n in onlySet)

  # ---- stage 6: --except (EXACT names) ------------------------------------
  var exceptSet = initHashSet[string]()
  for n in args.exceptNames: exceptSet.incl(n)
  narrow("except",
    (if args.exceptNames.len > 0: "--except=" & args.exceptNames.join(",") else: ""),
    proc (n: string): bool = n notin exceptSet)

  var nodes: seq[LockedDep]
  for n in working: nodes.add(byName[n])
  (nodes, stages)

proc developAllTargetPath(node: LockedDep; workspaceRoot, intoDir: string):
    string =
  ## Map a selected node to its checkout path. ``--into=<dir>`` places the
  ## checkout under that root (``<dir>/<name>``); the default is the sibling
  ## topology one level above the workspace root (``../<name>``), per
  ## CLI/develop.md §"Checkout Placement". The lock's workspace-relative
  ## ``path`` is honored when it already names a location (e.g. ``../sib``).
  let seg = safeDevelopPathSegment(node.name)
  if intoDir.len > 0:
    return os.normalizedPath(absolutePath(intoDir) / seg)
  if node.path.len > 0 and node.path != ".":
    return os.normalizedPath(absolutePath(workspaceRoot / node.path))
  os.normalizedPath(parentDir(absolutePath(workspaceRoot)) / seg)

proc gitHeadShaOf(gitBinary, repoDir: string): string =
  ## Best-effort ``git rev-parse HEAD`` for adopt/idempotent detection. Returns
  ## "" when the directory is not a resolvable git checkout.
  if gitBinary.len == 0 or not dirExists(repoDir / ".git"):
    return ""
  try:
    let res = execProcess(gitBinary,
      args = ["-C", repoDir, "rev-parse", "HEAD"],
      env = scrubbedGitRepositoryEnv(),
      options = {poUsePath})
    result = res.strip()
  except CatchableError:
    result = ""

proc isExactLockedRevision*(value: string): bool =
  ## DS-5 (CLI/develop.md §"A revision comes from a lock record or not at all")
  ## — the EXACT-PIN predicate of the develop set: exactly 40 LOWERCASE hex
  ## characters, a full git object id and nothing else.
  ##
  ## Deliberately NOT ``looksLikeSha``, which is a divergence-classification
  ## HEURISTIC (7..64 hex, so it answers "is this more likely a SHA than a
  ## branch name?") and is used by ``repro sync`` / workspace-init to decide
  ## whether a MANIFEST revision should be compared as an object id or as a
  ## ref. Two of its accepts are actively harmful once the answer decides what
  ## a checkout is reset to:
  ##
  ##   * an ABBREVIATION (``deadbeef``) is not an exact pin — a prefix can
  ##     become ambiguous as the repo grows, and the develop set's whole
  ##     contract is that the checkout lands at the one revision a lock record
  ##     names;
  ##   * an ALL-HEX BRANCH NAME (a branch literally called ``deadbeef``) is the
  ##     ``revision = "main"`` hazard wearing a costume — the same class of
  ##     defect that let a CI resolver build a moving branch tip;
  ##   * a 41-hex string is not a git object id at all: the clone runs, the
  ##     ``git reset --hard`` fails, and (before this) a checkout was LEFT
  ##     BEHIND at the branch tip — a revision nobody locked.
  ##
  ## Uppercase hex is refused too: git renders object ids lowercase, and a lock
  ## record that does not is not a record this reader will guess about.
  if value.len != 40: return false
  for ch in value:
    if ch notin {'0'..'9', 'a'..'f'}: return false
  true

proc cloneNodeAtLockedRevision(workspaceRoot, absTarget: string;
                               node: LockedDep;
                               identity: GitToolIdentity):
    tuple[ok: bool; diagnostic: string] =
  ## Clone ``node`` from its locked VCS coordinates into ``absTarget`` and
  ## reset the checkout to the EXACT locked ``revision`` SHA. Two chained
  ## ``bakWorkspaceVcs`` actions run in one engine graph:
  ##   1. ``git clone`` (``--branch <ref>`` only when the lock carries an
  ##      advisory branch/tag ref — a bare SHA cannot be a ``--branch`` arg);
  ##   2. ``git reset --hard <revision>`` + ``git clean -ffdx`` so the tree
  ##      lands byte-identical to a fresh checkout at the locked SHA.
  ## The exact SHA is authoritative — there is NO branch-tip fallback.
  let coords = node.coordinates
  if coords.kind != ckVcs or coords.url.len == 0:
    return (ok: false,
      diagnostic: "node '" & node.name & "' has no VCS clone URL in the lock " &
        "(coord_kind=" & $coords.kind &
        "); cannot be mapped to a reproducible source origin")
  if coords.revision.len == 0:
    return (ok: false,
      diagnostic: "node '" & node.name &
        "' has no locked revision in the lock; refusing branch-tip fallback")
  if not isExactLockedRevision(coords.revision):
    # DS-5 — the LAST gate before any filesystem effect. The composer already
    # refuses a non-exact revision, but the committed lock is an equal-status
    # source read through the same path, so the placement step asks the
    # question itself rather than trusting an upstream caller to have asked.
    # Refusing HERE is what keeps the "no partial mutation" promise cheap: no
    # clone has run yet, so there is nothing to unwind.
    return (ok: false,
      diagnostic: "node '" & node.name & "' is pinned to '" & coords.revision &
        "', which is not an EXACT locked revision (exactly 40 lowercase hex " &
        "characters). An abbreviation, a 41-hex string, or a hex-looking " &
        "branch name is not an exact pin, and this command never checks out " &
        "a revision no lock record names; refusing to place it.")
  let relTarget = relativePath(absTarget, workspaceRoot)
  let receiptDir = workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  let idSeg = safeDevelopPathSegment(node.name)
  # The receipt identifies a PLACEMENT — a (node, target path) pair — not a
  # node. ``--into`` (and the lock's own ``path``) decide where the checkout
  # lands, so a key that ignores the target makes two different placements of
  # the same node share one receipt and one action id: the second run reports
  # the first run's receipt as its own.
  let placementSeg = idSeg & "-" &
    digestHex(blake3DomainDigest(relTarget.bytesOf(), hdMetadataEnvelope))[0 ..< 16]
  let cloneReceiptRel = ".repro" / "workspace" / "receipts" /
    ("develop-all-clone-" & placementSeg & ".receipt")
  let resetReceiptRel = ".repro" / "workspace" / "receipts" /
    ("develop-all-reset-" & placementSeg & ".receipt")
  # (1) clone — ``ref`` (advisory branch/tag) narrows the clone; a bare SHA is
  # NOT passed as ``--branch`` (git refuses that). The reset step pins the SHA.
  let cloneBranch =
    if coords.gitRef.len > 0 and coords.gitRef != coords.revision:
      coords.gitRef
    else: ""
  # ``cacheable = false``, for the same reason ``gitForceResetAction`` is: the
  # PRODUCT of this action is a WORKING TREE at ``relTarget``, and a working
  # tree is not a declared output — only the receipt is. The clone
  # fingerprint deliberately OMITS ``repoPath`` (git_actions.nim
  # ``fingerprintPayload``, M2 design rule 1) so two temp roots cloning the
  # same (remote, revision, identity) share one cache entry; that is sound
  # when the receipt IS the product, and unsound here. With the engine
  # default ``rebuildMissingOutputsOnCacheHit = false``, a second
  # ``develop --all`` into a DIFFERENT ``--into`` root hit that shared entry,
  # materialized the receipt, cloned NOTHING, and the chained force-reset
  # then failed against a directory that was never created:
  #   `force-reset target is not a git working tree: <into>/<node>`
  # Always executing is correct and cheap: this path only ever clones into a
  # target it has just proved absent (or has deliberately removed for
  # ``--reset``), so there is nothing for a cache hit to save.
  var cloneAction = gitCloneAction(
    "workspace-develop-all-clone-" & placementSeg,
    identity, remoteUrl = coords.url, repoPath = relTarget,
    receiptPath = cloneReceiptRel, revision = cloneBranch,
    cacheable = false)
  cloneAction.cwd = workspaceRoot
  # (2) force-reset onto the exact locked SHA (depends on the clone).
  var resetAction = gitForceResetAction(
    "workspace-develop-all-reset-" & placementSeg,
    identity, revision = coords.revision, repoPath = relTarget,
    receiptPath = resetReceiptRel, deps = @[cloneAction.id])
  resetAction.cwd = workspaceRoot
  let cacheRoot = workspaceRoot / ".repro" / "workspace" / "engine-cache"
  var config = defaultBuildEngineConfig(cacheRoot)
  config.suppressTrace = true
  let res = runBuild(graph(@[cloneAction, resetAction]), config)
  var cloneStatus, resetStatus: ActionStatus
  var cloneSeen, resetSeen = false
  var diag = ""
  for outcome in res.results:
    if outcome.id == cloneAction.id:
      cloneStatus = outcome.status; cloneSeen = true
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        diag = "clone failed: status=" & $outcome.status & " reason=" &
          outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: "")
    elif outcome.id == resetAction.id:
      resetStatus = outcome.status; resetSeen = true
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        diag = "reset-to-locked-revision failed: status=" & $outcome.status &
          " reason=" & outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: "")
  proc discardPartialCheckout() =
    ## DS-5 — a FAILED placement leaves NO checkout behind.
    ##
    ## The two actions are chained: the clone lands a working tree, and only
    ## then does the reset pin it to the locked SHA. When the reset fails
    ## (an unresolvable revision is exactly how it fails) the clone's tree
    ## survives — sitting at whatever the remote's default branch tip happened
    ## to be, i.e. a revision NOBODY locked, in the one command whose contract
    ## is that a checkout is only ever at a locked revision. A partial mutation
    ## at a wrong revision is worse than a refusal: the next run sees a
    ## populated directory and reports `already exists ... refusing to
    ## overwrite`, so the wrong tree becomes sticky.
    ##
    ## The caller either created ``absTarget`` in this call (the fresh-clone
    ## path) or deliberately removed a pre-existing one first (the ``--reset``
    ## path), so in both cases nothing that predates this call is destroyed.
    try:
      if dirExists(absTarget): removeDir(absTarget)
    except CatchableError:
      discard
  if not cloneSeen or not resetSeen:
    discardPartialCheckout()
    return (ok: false,
      diagnostic: if diag.len > 0: diag
                  else: "build engine returned no result for clone/reset of " &
                    node.name)
  if cloneStatus notin {asSucceeded, asCacheHit, asUpToDate} or
      resetStatus notin {asSucceeded, asCacheHit, asUpToDate}:
    discardPartialCheckout()
    return (ok: false, diagnostic: diag)
  (ok: true, diagnostic: "")

proc failure(diagnostic: string; notices: seq[string]; code: int):
    DevelopAllResult =
  DevelopAllResult(
    outcomes: @[DevelopAllNodeOutcome(node: "*", mode: "error", ok: false,
      diagnostic: diagnostic)],
    notices: notices, exitCode: code)

proc executeDevelopAll(args: DevelopAllArgs): DevelopAllResult =
  ## L1 driver, DS-1..DS-5 shape. (1) Resolve the git tool. (2) COMPOSE the
  ## workspace lock set across EVERY backend the configuration plane resolves —
  ## FAIL LOUD when the UNION is empty, when two backends disagree about a
  ## revision (DS-2), or when a public/team backend cannot be read (DS-3).
  ## (3) Resolve the develop set over the union, excluding evidence-only repos
  ## (DS-4). (4) For each node: adopt a suitable existing checkout, else clone
  ## at the locked revision — FAIL LOUD on an unmappable node. (5) Record every
  ## successfully placed node's override via M20.
  let root = args.workspaceRoot

  # (1) Resolve the git tool once for the whole batch. This moved AHEAD of the
  # lock read because the composer constructs git-backed ``LockStore`` backends
  # and needs the resolved ``GitToolIdentity``.
  var identity: GitToolIdentity
  try:
    identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
    installGitVcsExecutor()
  except CatchableError as err:
    return failure("git tool not resolvable: " & err.msg, @[], 1)
  let gitBinary = identity.binaryPath

  # (2) DS-1 — "No single row is a precondition for the others."
  #
  # The committed lock USED to be gated here: a workspace with no ``repro.lock``
  # returned exit 1 BEFORE the composer ever ran, so a workspace whose lock
  # records live entirely in a routed team backend — the metacraft workspaces,
  # which carry 126 published ``locks/<project>/<repo>/<sha>.toml`` records and
  # no ``repro.lock`` at all — could not resolve a single repo. Reading the
  # union as "the committed lock, optionally augmented" INVERTS the rule: the
  # committed lock is one source of EQUAL STATUS, not a gate.
  #
  # So the composer always runs, and the ONLY lock-set failure is an EMPTY
  # UNION (below), which names every backend it consulted.
  #
  # DS-1 — the whole lock set, across every backend, not one file.
  var composed = composeDevelopLockSet(root, identity, args)
  # DS-1 compatibility contract: a public-only workspace resolves to the
  # built-in public default alone, so the composer reports NO warning, NO
  # omission and NO unpinned repo, and this notice list stays EMPTY — the
  # command's output is byte-identical to the pre-DS-1 single-backend read.
  # The per-backend inventory belongs to `--list` (DS-6), not to every run.
  var notices: seq[string]
  # DS-5 — the ancestry walk NAMES the ancestor it landed on. A pin silently
  # resolved from a different commit than the one asked for is exactly the
  # class of surprise this command exists to prevent, so this is a notice on
  # EVERY run, not a `--list`-only detail.
  for k in composed.keyNotes: notices.add(k)
  for w in composed.warnings: notices.add(w)
  for n in composed.omitted:
    notices.add("OMITTED from the develop set (its backend was unreadable): " & n)
  for n in composed.noRecord:
    notices.add("no exact locked revision recorded for '" & n &
      "' in its assigned backend; it contributes nothing to the develop set " &
      "(there is no branch-tip fallback)")
  # DS-2 / DS-3 — refusals are fatal and never resolved into a guess.
  if composed.refusals.len > 0:
    var outcomes: seq[DevelopAllNodeOutcome]
    for r in composed.refusals:
      outcomes.add(DevelopAllNodeOutcome(node: "*", mode: "error", ok: false,
        diagnostic: r))
    return DevelopAllResult(outcomes: outcomes, notices: notices, exitCode: 2,
      backends: composed.backends)

  let lock = composed.lock
  if lock.deps.len == 0:
    # DS-1 — "An empty union — no backend yielded any record — is the only
    # lock-set failure, and it names every backend consulted."
    #
    # Naming them is the whole point. The previous shape returned a bare exit 1
    # whose message was about ONE file (``repro.lock``), which was both wrong
    # (that file is not a precondition) and unactionable for a routed workspace
    # (it named a backend the user was not using). The inventory below tells
    # the user exactly which media were asked and what each one said, so an
    # empty answer is attributable rather than mysterious.
    var inventory: seq[string]
    for b in composed.backends:
      var line = "  - " & b.tier & " tier / " & b.backendKind & " backend at " &
        b.location & ": "
      if b.excluded:
        # DS-8 — this backend was NOT asked for its records: `--tier` excluded
        # its tier. Saying "readable but holds nothing" here would blame the
        # backend for a restriction the invocation imposed.
        line.add("excluded from this invocation by --tier=" &
          args.tiers.join(","))
      elif b.diagnostic.len > 0: line.add(b.diagnostic)
      elif b.records > 0: line.add($b.records & " record(s), all filtered out")
      else: line.add("readable, but it holds no lock record for this workspace")
      if b.repos.len > 0:
        line.add(" (asked about: " & b.repos.join(", ") & ")")
      inventory.add(line)
    let msg = "the workspace lock set at " & root & " is EMPTY: no lock " &
      "backend readable from this workspace yielded a single lock record, so " &
      "there is nothing `repro develop` can manage. Every backend the " &
      "configuration plane resolved was consulted:\n" & inventory.join("\n") &
      "\nPublish a lock record through one of them (`repro lock refresh` " &
      "writes the committed lock; `repro workspace lock` records a routed " &
      "tier's per-repo entries)."
    var r = failure(msg, notices, 1)
    r.backends = composed.backends
    return r

  # DS-4 — evidence-only repos are excluded from the develop set, but they are
  # NAMED here rather than silently dropped, and naming one explicitly is a
  # loud error explaining why.
  var evidenceOnlyNames: seq[string]
  var knownNames = initHashSet[string]()
  for d in lock.deps:
    if d.name.len > 0: knownNames.incl(d.name)
    if isEvidenceOnlyLockedDep(d) and not isRootLockedDep(d):
      evidenceOnlyNames.add(d.name)
  evidenceOnlyNames.sort()

  # DS-7 — TAG attribution, for every repo in the union rather than only for
  # those the MANIFEST pass reached.
  #
  # ``composed.tagsOf`` is filled from the resolved manifest membership, and
  # the composer only gets that far when some configuration layer declares a
  # route. "A workspace with no routing config resolves to the built-in public
  # default alone" (CLI/develop.md §"Composing the lock set") — the DS-1
  # compatibility baseline — so in exactly that shape the composer returns
  # early and every tag table is empty. `--tag=<tag>` then refused with
  # "the declared tags are: (none)" for a tag the committed lock ITSELF
  # declares, which is not a narrower answer but a false one.
  #
  # A lock record carries the repo's ``tags``, so use it for any repo the
  # manifest pass did not attribute. The manifest values still win where both
  # exist, and the implicit-``default`` rule is the same one ``effectiveTags``
  # applies: a repo that lists tags without naming `default` is not in it.
  for d in lock.deps:
    if d.name.len == 0 or composed.tagsOf.hasKey(d.name): continue
    let ts = if d.tags.len > 0: d.tags else: @[defaultManifestTag]
    composed.tagsOf[d.name] = ts
    for t in ts:
      if t notin composed.knownTags: composed.knownTags.add(t)
  composed.knownTags.sort()
  if not args.list:
    # ``--list`` shows each of these as a ROW with state `evidence-only`
    # (CLI/develop.md §"Evidence-only repos"), so repeating them as notices
    # would say the same thing twice. Every mutating run still names them.
    for n in evidenceOnlyNames:
      notices.add("excluded from the develop set: '" & n &
        "' is evidence-only (state=evidence-only, tier=" &
        composed.tierOf.getOrDefault(n, "private") &
        ") — it publishes a source-free evidence triple and never its source, " &
        "so it has no obtainable source to check out")

  # ---- DS-7 — EXACT-NAME loudness for every exact-name selector. ----------
  #
  # "``--only`` and ``--except`` name repos EXACTLY; a name matching nothing is
  # a loud error, never a silent no-op." The same rule binds ``--project`` and
  # ``--tag``, which also name things exactly. Only ``--filter`` is a glob,
  # and it alone may legitimately match nothing.
  #
  # Every exact-name selector is validated against the WHOLE lock set (or the
  # whole active project / group universe), NOT against whatever an earlier
  # stage happened to leave: `--direct --except=X` for an X that exists but is
  # not a direct edge is a legitimate no-op, not a typo, and validating against
  # a stage's input would additionally make the ERROR depend on argv order,
  # which is the very thing the fixed composition order exists to prevent.
  block exactNameSelectors:
    var outcomes: seq[DevelopAllNodeOutcome]
    proc unknownName(flag, name, universe, hint: string) =
      outcomes.add(DevelopAllNodeOutcome(node: name, mode: "error", ok: false,
        diagnostic: "'" & flag & "=" & name & "' names no " & universe &
          " (names are matched EXACTLY" & hint & ")"))
    # ``--transitive-of`` also names a repo EXACTLY, so it obeys the same rule
    # — and it must obey it on the QUERY path too, where an unknown name would
    # otherwise come out as a plausible-looking empty table.
    if args.mode == dasmTransitiveOf and args.transitiveOf.len > 0 and
        args.transitiveOf notin knownNames:
      unknownName("--transitive-of", args.transitiveOf,
        "repo in this workspace's lock set",
        "; use `repro develop --list` to see the set")
    # ``--only`` / ``--except`` — repo names, against the composed lock set.
    for n in args.only:
      if n notin knownNames:
        unknownName("--only", n, "repo in this workspace's lock set",
          "; use --filter for a glob, or `repro develop --list` to see the set")
    for n in args.exceptNames:
      if n notin knownNames:
        unknownName("--except", n, "repo in this workspace's lock set",
          "; use --filter for a glob, or `repro develop --list` to see the set")
    # ``--project`` — against the ACTIVE PROJECT SET. Note this is a MEMBERSHIP
    # filter and nothing else: a commit-addressed backend's record is looked up
    # under the PRIMARY project (Workspace-And-Develop-Mode.md §"The Primary
    # Project") whether or not ``--project`` names it. The two concerns are
    # deliberately separate — re-keying record lookup off a membership filter
    # would make the same commit resolve different pins depending on which
    # projects the caller asked to see.
    for p in args.projects:
      if p notin composed.activeProjects:
        unknownName("--project", p,
          "project in this workspace's active project set",
          "; this workspace's set is: " &
            (if composed.activeProjects.len > 0:
               composed.activeProjects.join(", ")
             else: "(none recorded)"))
    # ``--tag`` — against the tags the participating manifest fragments
    # actually declare (plus the implicit ``default``).
    for t in args.tags:
      if t notin composed.knownTags:
        unknownName("--tag", t, "manifest tag in this workspace",
          "; the declared tags are: " &
            (if composed.knownTags.len > 0: composed.knownTags.join(", ")
             else: "(none)"))
    if outcomes.len > 0:
      return DevelopAllResult(outcomes: outcomes, notices: notices,
        exitCode: 2, backends: composed.backends)

  block contradictorySelection:
    # DS-7 (CLI/develop.md §"Membership axis") — a name given to BOTH
    # ``--only`` and ``--except`` is a contradiction and refuses.
    #
    # ``--only=X --except=X`` used to exit 0 having selected nothing: stage 5
    # keeps exactly {X}, stage 6 removes X, and the run reported an empty
    # selection and did no work. Neither name is unknown, so the exact-name
    # check above has nothing to say about it — yet the caller asked for X and
    # simultaneously for not-X, which cannot be anything but a mistake, and
    # silently doing nothing is the failure mode this section legislates
    # against everywhere else. `--filter` is the selector that may match
    # nothing; the exact-name selectors are loud.
    #
    # Stated over the NAMES, not over the resulting set. ``--only=a,b
    # --except=b`` refuses too: it is exactly ``--only=a`` written in a way
    # that also says "not b", and a rule that fired only when the FINAL
    # selection came out empty would depend on which other repos happen to
    # exist — the same "the answer depends on something other than what you
    # typed" hazard the fixed composition order exists to remove.
    #
    # Checked AFTER the exact-name block so a typo is still diagnosed as a
    # typo: ``--only=X --except=X-typo`` names an unknown repo, which is the
    # more basic error and the more useful message.
    if args.only.len > 0 and args.exceptNames.len > 0:
      var exceptSet = initHashSet[string]()
      for n in args.exceptNames: exceptSet.incl(n)
      var contradicted: seq[string]
      var seenContradiction = initHashSet[string]()
      for n in args.only:
        if n in exceptSet and n notin seenContradiction:
          seenContradiction.incl(n)
          contradicted.add(n)
      if contradicted.len > 0:
        contradicted.sort()
        var outcomes: seq[DevelopAllNodeOutcome]
        for n in contradicted:
          outcomes.add(DevelopAllNodeOutcome(node: n, mode: "error", ok: false,
            diagnostic: "'" & n & "' is named by BOTH --only and --except: " &
              "the selection asks for it and excludes it at once, so it can " &
              "never be selected. Neither flag wins — drop '" & n &
              "' from one of them (dropping it from --only is the same " &
              "selection written without the contradiction). --filter is " &
              "the selector that may legitimately match nothing; --only and " &
              "--except name repos exactly and refuse rather than silently " &
              "select nothing."))
        return DevelopAllResult(outcomes: outcomes, notices: notices,
          exitCode: 2, backends: composed.backends)

  block namedEvidenceOnly:
    # DS-4 — naming an evidence-only repo for PLACEMENT is a loud error that
    # explains why. ``--list`` is a query with no placement, and the spec says
    # the repo "appears in --list output with state evidence-only", so the
    # query lists it instead of refusing.
    if args.list: break namedEvidenceOnly
    var named: seq[string] = args.only
    if args.mode == dasmTransitiveOf and args.transitiveOf.len > 0:
      named.add(args.transitiveOf)
    # The develop-manageable set is the union "**minus** the workspace root
    # repo itself (`path == "."`, the consumer) and **minus** evidence-only
    # repos" (CLI/develop.md §"Composing the lock set"). BOTH exclusions
    # remove a repo that IS in the lock set, so an exact name hitting either
    # one is a name that resolves to nothing placeable — and the rule
    # "``--only`` and ``--except`` name repos EXACTLY; a name matching nothing
    # is a LOUD ERROR, never a silent no-op" binds them the same way. The
    # upstream exact-name check cannot catch these: it validates against the
    # whole lock set, which contains both.
    var rootNames: seq[string]
    for d in lock.deps:
      if isRootLockedDep(d) and d.name.len > 0: rootNames.add(d.name)
    var evidence, roots: seq[string]
    for n in named:
      if n in evidenceOnlyNames: evidence.add(n)
      elif n in rootNames: roots.add(n)
    if evidence.len > 0 or roots.len > 0:
      var outcomes: seq[DevelopAllNodeOutcome]
      for n in evidence:
        outcomes.add(DevelopAllNodeOutcome(node: n, mode: "error", ok: false,
          diagnostic: "'" & n & "' is an EVIDENCE-ONLY repo (tier=" &
            composed.tierOf.getOrDefault(n, "private") & " backend=" &
            composed.backendOf.getOrDefault(n, "unknown") &
            "): it participates by publishing a source-free evidence triple " &
            "(head-sha / clean / published) and never its source, so it can " &
            "never be placed into develop mode. It appears in the lock set " &
            "with state `evidence-only`; drop it from the selection."))
      for n in roots:
        outcomes.add(DevelopAllNodeOutcome(node: n, mode: "error", ok: false,
          diagnostic: "'" & n & "' is THIS WORKSPACE'S ROOT REPO (path \".\"): " &
            "it is the consumer the develop set is assembled FOR, not a " &
            "dependency of it, so it can never be placed into develop mode " &
            "— you are already standing in it. Drop it from the selection " &
            "(`repro develop --list` shows what the lock set does manage)."))
      return DevelopAllResult(outcomes: outcomes, notices: notices,
        exitCode: 2, backends: composed.backends)

  # (3) Resolve the develop set over the UNION, through the fixed-order
  # membership axis (DS-7).
  let (selected, stages) = developSetFromLock(lock, composed, args,
    keepEvidenceOnly = args.list)

  # Load the existing override file once; fold every placed node into it. Read
  # BEFORE the ``--list`` branch too: the `develop` state of a row is exactly
  # "this repo has an override entry".
  var overrides =
    try:
      let existing = readDevelopOverridesFile(root)
      if existing.isSome: existing.get() else: newDevelopOverrides()
    except WorkspaceManifestParseError:
      newDevelopOverrides()

  # ---- DS-6 — ``--list``: print the resolved lock set and exit. -----------
  #
  # "``--list`` is the query form of the rule at the top of this section: it
  # answers 'what does this workspace's lock set manage?' WITHOUT TOUCHING THE
  # TREE." It therefore returns here, before the override file, the engine
  # cache, the receipts dir or any checkout is written — a query has no
  # destructive edge, and a `--list` that left a receipt behind would not be
  # read-only however it was documented.
  if args.list:
    var rows: seq[DevelopListRow]
    for node in selected:
      var row = DevelopListRow(name: node.name,
        # The PIN's provenance, not the routing assignment — see
        # ``DevelopLockSet.pinTierOf``.
        tier: composed.pinTierOf.getOrDefault(node.name,
          composed.tierOf.getOrDefault(node.name, "public")),
        backend: composed.pinBackendOf.getOrDefault(node.name,
          composed.backendOf.getOrDefault(node.name, "committed-lock")),
        revision: node.coordinates.revision,
        path: developAllTargetPath(node, root, args.intoDir))
      if isEvidenceOnlyLockedDep(node):
        # An evidence-only repo has no obtainable source by construction, so
        # neither `absent` nor `at-lock` is a truthful answer for it.
        row.state = "evidence-only"
        row.path = ""
      else:
        let prior = findOverride(overrides, node.name)
        if prior.isSome:
          row.state = "develop"
          row.path = os.normalizedPath(absolutePath(prior.get().local_path))
        elif not dirExists(extendedPath(row.path)):
          row.state = "absent"
        else:
          let headSha = gitHeadShaOf(gitBinary, row.path)
          row.state =
            if headSha.len > 0 and headSha == node.coordinates.revision:
              "at-lock"
            else: "drifted"
      rows.add(row)
    return DevelopAllResult(notices: notices, exitCode: 0, listed: true,
      rows: rows, stages: stages, backends: composed.backends)

  if selected.len == 0:
    # An UNKNOWN ``--transitive-of`` root already refused above, with the same
    # exact-name loudness every other name-taking selector gets. Reaching here
    # means every name was real and the composed selectors simply left nothing:
    # an empty selection, which is a legitimate outcome (``--filter`` may match
    # nothing) and is reported as such rather than as a failure.
    return DevelopAllResult(notices: notices, exitCode: 0, stages: stages,
      backends: composed.backends)

  var outcomes: seq[DevelopAllNodeOutcome]
  var anyFailure = false
  var mutated = false
  for node in selected:
    var outcome = DevelopAllNodeOutcome(node: node.name)
    if node.coordinates.kind == ckVcs:
      outcome.revision = node.coordinates.revision
    # Unmappable node: no reproducible source origin. FAIL LOUD (per node).
    if node.coordinates.kind != ckVcs or node.coordinates.url.len == 0 or
        node.coordinates.revision.len == 0:
      outcome.mode = "error"
      outcome.ok = false
      outcome.diagnostic = "node '" & node.name &
        "' cannot be mapped to a reproducible source origin (missing VCS " &
        "url/revision in the committed lock)"
      outcomes.add(outcome)
      anyFailure = true
      continue
    # DS-5 — a revision comes from a lock record or not at all, and a record
    # pins an EXACT 40-hex revision. Asked BEFORE any placement decision so the
    # answer is the same for a real run and for ``--dry-run``: an inexact pin
    # is a per-node refusal, never a checkout at a revision nobody locked.
    if not isExactLockedRevision(node.coordinates.revision):
      outcome.mode = "error"
      outcome.ok = false
      outcome.diagnostic = "node '" & node.name & "' is pinned to '" &
        node.coordinates.revision & "', which is NOT an exact locked " &
        "revision (a lock record pins exactly 40 lowercase hex characters). " &
        "An abbreviated SHA, a 41-hex string and an all-hex branch name are " &
        "all refused: an abbreviation is not an exact pin, and a hex-looking " &
        "branch name is the `revision = \"main\"` hazard wearing a costume. " &
        "Nothing was placed for this node."
      outcomes.add(outcome)
      anyFailure = true
      continue

    let absTarget = developAllTargetPath(node, root, args.intoDir)
    outcome.path = absTarget

    # Reuse / adopt an existing suitable checkout over cloning a duplicate.
    let prior = findOverride(overrides, node.name)
    if prior.isSome and os.normalizedPath(absolutePath(prior.get().local_path)) ==
        absTarget:
      # Already in develop mode at this exact path — idempotent no-op.
      outcome.mode = "idempotent"
      outcome.ok = true
      outcomes.add(outcome)
      continue
    if prior.isSome:
      # Existing override for this node points elsewhere — refuse (do not
      # silently relocate someone's checkout).
      outcome.mode = "refused"
      outcome.ok = false
      outcome.diagnostic = "existing override for '" & node.name &
        "' points at " & prior.get().local_path & "; drop it before " &
        "re-developing into " & absTarget
      outcomes.add(outcome)
      anyFailure = true
      continue

    if dirExists(absTarget):
      # A checkout already exists on disk. Adopt it when it is a git checkout at
      # the EXACT locked revision; otherwise refuse (never overwrite) — UNLESS
      # ``--reset`` was requested, in which case reconcile the drifted checkout
      # to the lock by overwriting it (re-clone + hard-reset at the locked SHA).
      let headSha = gitHeadShaOf(gitBinary, absTarget)
      if headSha.len > 0 and headSha == node.coordinates.revision:
        outcome.mode = "adopted"
        outcome.ok = true
      elif args.reset and args.dryRun:
        # ``--dry-run`` reports the plan and stops short of the destructive
        # re-clone. Nothing is removed, nothing is fetched.
        outcome.mode = "would-reset"
        outcome.ok = true
      elif args.reset:
        # ``--reset``: the drift is the expected case (e.g. a CI pre-clone
        # placed the sibling at a `=dev` branch tip). Force it back to the
        # locked revision. The overwrite is a destructive re-clone that
        # fetches the EXACT locked SHA and force-resets onto it, so the tree
        # ends byte-identical to a fresh lock-pinned checkout regardless of
        # what the prior checkout contained (shallow, dirty, or diverged).
        removeDir(absTarget)
        let resetRes =
          cloneNodeAtLockedRevision(root, absTarget, node, identity)
        if not resetRes.ok:
          outcome.mode = "error"
          outcome.ok = false
          outcome.diagnostic = "reset-to-locked-revision failed for " &
            node.name & " (was at " &
            (if headSha.len == 0: "non-git-checkout" else: headSha) & "): " &
            resetRes.diagnostic
          outcomes.add(outcome)
          anyFailure = true
          continue
        outcome.mode = "reset"
        outcome.ok = true
      else:
        outcome.mode = "refused"
        outcome.ok = false
        outcome.diagnostic = "path " & absTarget & " already exists and is " &
          (if headSha.len == 0: "not a git checkout"
           else: "at " & headSha & ", not the locked revision " &
             node.coordinates.revision) &
          "; refusing to overwrite (pass --reset to force it to the lock)"
        outcomes.add(outcome)
        anyFailure = true
        continue
    elif args.dryRun:
      # ``--dry-run`` — the node WOULD be cloned at its locked revision. The
      # revision was already proved exact above, so this plan line is a
      # commitment, not a guess.
      outcome.mode = "would-clone"
      outcome.ok = true
    else:
      # Clone fresh at the locked revision.
      let cloneRes = cloneNodeAtLockedRevision(root, absTarget, node, identity)
      if not cloneRes.ok:
        outcome.mode = "error"
        outcome.ok = false
        outcome.diagnostic = cloneRes.diagnostic
        outcomes.add(outcome)
        anyFailure = true
        continue
      outcome.mode = "cloned"
      outcome.ok = true

    if args.dryRun:
      # Mutate NOTHING: no override entry is folded in, so nothing is written.
      outcomes.add(outcome)
      continue

    # Record the override (solved node -> local path) via M20.
    var entry: repro_workspace_manifests.DevelopOverrideEntry
    entry.package = node.name
    entry.local_path = absTarget
    entry.state = "editable"
    entry.created_at = currentRfc3339Timestamp()
    entry.provenance = some("repro develop --all")
    overrides = addOverride(overrides, entry)
    mutated = true
    outcomes.add(outcome)

  # POST-CONDITION. Every mode this command reports as done is a claim that a
  # checkout of <node> is now on disk at <path>: `cloned` and `reset` say this
  # run put it there, `adopted` and `idempotent` say it was already there. Not
  # one of them was ever checked against the filesystem AFTER the fact — the
  # claim was inferred from a helper's exit status, or from an override record
  # written on some earlier run. So a clone that exited zero without leaving a
  # tree, and an override naming a directory that has since been deleted, both
  # rendered as success and the command exited 0.
  #
  # That is the same shape as a build reporting a target built because the
  # compiler did not complain: the only evidence that settles it is the
  # artefact, so look at the artefact.
  #
  # What is verified is deliberately different per mode, because the modes
  # promise different things:
  #
  #   cloned / reset  — THIS run placed the tree at the LOCKED revision, so
  #                     both the checkout and its exact HEAD are verified.
  #   adopted         — the revision was proved before adoption; re-verify only
  #                     that the checkout is still there.
  #   idempotent      — develop mode means an EDITABLE checkout, and a
  #                     developer is expected to commit on top of the lock, so
  #                     HEAD is NOT required to match. Only its existence as a
  #                     git checkout is, which is exactly the claim "already in
  #                     develop mode at <path>" makes.
  #
  # `--dry-run` promises nothing was placed, so it is exempt: verifying a plan
  # against the filesystem would fail it for being a plan.
  if not args.dryRun:
    for outcome in outcomes.mitems:
      if not outcome.ok: continue
      if outcome.mode notin ["cloned", "reset", "adopted", "idempotent"]:
        continue
      if outcome.path.len == 0: continue
      if not dirExists(outcome.path):
        outcome.diagnostic = "reported '" & outcome.mode & "' for '" &
          outcome.node & "' but no checkout exists at " & outcome.path &
          ". Nothing that reads this dependency from disk will find it, so " &
          "the run is reported as the failure it is rather than as success."
        outcome.mode = "error"
        outcome.ok = false
        anyFailure = true
        continue
      # `.git` is a DIRECTORY in an ordinary clone and a FILE in a linked
      # worktree or a submodule, so both count as a checkout here. Only the
      # absence of either is evidence that nothing was placed.
      let gitEntry = outcome.path / ".git"
      if not (dirExists(gitEntry) or fileExists(gitEntry)):
        outcome.diagnostic = "reported '" & outcome.mode & "' for '" &
          outcome.node & "' but " & outcome.path &
          " is not a git checkout (no .git). Whatever is at that path, it is " &
          "not the dependency this run claims to have placed."
        outcome.mode = "error"
        outcome.ok = false
        anyFailure = true
        continue
      let headSha = gitHeadShaOf(gitBinary, outcome.path)
      if outcome.mode in ["cloned", "reset"] and
          outcome.revision.len > 0 and headSha != outcome.revision:
        outcome.diagnostic = "reported '" & outcome.mode & "' for '" &
          outcome.node & "' at the locked revision " & outcome.revision &
          ", but " & outcome.path & " is at " & headSha & "."
        outcome.mode = "error"
        outcome.ok = false
        anyFailure = true

  if mutated:
    try:
      writeDevelopOverridesFile(root, overrides)
    except CatchableError as err:
      outcomes.add(DevelopAllNodeOutcome(node: "*", mode: "error", ok: false,
        diagnostic: "failed to write develop-overrides.toml: " & err.msg))
      anyFailure = true

  DevelopAllResult(outcomes: outcomes, notices: notices,
    exitCode: (if anyFailure: 1 else: 0), stages: stages,
    backends: composed.backends)

proc runDevelopAllCommand(args: DevelopAllArgs): int =
  ## Run the driver and render per-node results.
  ##
  ## DS-1 — this used to short-circuit on a missing ``repro.lock`` BEFORE the
  ## driver ran, which made the committed lock a precondition for every other
  ## lock source rather than one source of equal status. The empty-lock-set
  ## failure now comes from the composer, which is the only place that knows
  ## which backends were actually consulted; it names all of them, including
  ## the committed lock and its path.
  let res = executeDevelopAll(args)
  let outcomes = res.outcomes
  let notices = res.notices
  let exitCode = res.exitCode
  let label = if args.list: "repro develop --list" else: "repro develop --all"

  # DS-6/DS-7/DS-8 — the shared machine-readable blocks. The per-backend
  # inventory (tier / kind / location / reachable / repos / records) was
  # computed by the composer on EVERY run but printed only on an empty union;
  # it belongs to the query, so `--list` reports it and `--json` carries it.
  proc backendsJson(): JsonNode =
    result = newJArray()
    for b in res.backends:
      var o = %*{"tier": b.tier, "kind": b.backendKind, "location": b.location,
        "reachable": b.reachable, "records": b.records, "adhoc": b.adhoc,
        "excluded": b.excluded}
      if b.diagnostic.len > 0: o["diagnostic"] = %b.diagnostic
      if b.keyedOn.len > 0: o["keyedOn"] = %b.keyedOn
      var repos = newJArray()
      for r in b.repos: repos.add(%r)
      o["repos"] = repos
      result.add(o)
  proc stagesJson(): JsonNode =
    result = newJArray()
    for s in res.stages:
      result.add(%*{"stage": s.stage, "flag": s.flag, "kept": s.kept})

  if args.list:
    # DS-6 — the query form. Mutates nothing; prints the resolved lock set.
    if args.json:
      var rows = newJArray()
      for r in res.rows:
        rows.add(%*{"name": r.name, "tier": r.tier, "backend": r.backend,
          "revision": r.revision, "path": r.path, "state": r.state})
      var noticeArr = newJArray()
      for n in notices: noticeArr.add(%n)
      # "Machine consumers should use ``--json``" (CLI/develop.md §"Action
      # axis"). A refusal on the query path — an unknown ``--only`` name, an
      # unresolvable ``--at``, an unreadable backend — sets ``exitCode`` and
      # produces NO rows, and its explanation lives in ``outcomes``. Dropping
      # them here left the machine consumer holding a non-zero exit, an empty
      # repo list and nothing at all saying why, while the text form printed
      # the full diagnostic. The two forms answer the same question.
      var errorArr = newJArray()
      for o in outcomes:
        if not o.ok:
          errorArr.add(%*{"node": o.node, "diagnostic": o.diagnostic})
      stdout.writeLine(pretty(%*{"schemaId": "reprobuild.develop-list.v1",
        "workspaceRoot": args.workspaceRoot, "repos": rows,
        "backends": backendsJson(), "selection": stagesJson(),
        "notices": noticeArr, "errors": errorArr,
        "exitCode": exitCode}, indent = 2))
    else:
      for n in notices:
        stderr.writeLine(label & ": " & n)
      if res.listed:
        for b in res.backends:
          var line = "backend: " & b.tier & " tier / " & b.backendKind & " at " &
            b.location & " — " &
            (if not b.reachable: "UNREADABLE: " & b.diagnostic
             elif b.excluded: "excluded by --tier"
             else: $b.records & " record(s)")
          if b.adhoc: line.add(" [--lock-store]")
          if b.keyedOn.len > 0: line.add(" [keyed on " & b.keyedOn & "]")
          stdout.writeLine(line)
        for s in res.stages:
          stdout.writeLine("selection: " & s.stage &
            (if s.flag.len > 0: " " & s.flag else: " (not given)") &
            " -> " & $s.kept & " repo(s)")
        # Six columns, per CLI/develop.md §"Action axis": name, resolved tier,
        # backend, locked revision, intended path, state.
        var w = "REPO".len
        for r in res.rows: w = max(w, r.name.len)
        stdout.writeLine("REPO".alignLeft(w) & "  TIER      BACKEND         " &
          "REVISION                                  STATE         PATH")
        for r in res.rows:
          stdout.writeLine(r.name.alignLeft(w) & "  " &
            r.tier.alignLeft(8) & "  " & r.backend.alignLeft(14) & "  " &
            (if r.revision.len > 0: r.revision else: "-").alignLeft(40) & "  " &
            r.state.alignLeft(12) & "  " & r.path)
        if res.rows.len == 0:
          stdout.writeLine(label & ": the selection is empty")
      else:
        for o in outcomes:
          stderr.writeLine(label & ": error " & o.node & " — " & o.diagnostic)
    return exitCode

  if args.json:
    var arr = newJArray()
    for o in outcomes:
      var node = %*{
        "node": o.node, "path": o.path, "revision": o.revision,
        "mode": o.mode, "ok": o.ok}
      if o.diagnostic.len > 0:
        node["diagnostic"] = %o.diagnostic
      arr.add(node)
    var noticeArr = newJArray()
    for n in notices: noticeArr.add(%n)
    stdout.writeLine(pretty(%*{"schemaId": "reprobuild.develop-all.v1",
      "workspaceRoot": args.workspaceRoot, "nodes": arr,
      "notices": noticeArr, "backends": backendsJson(),
      "selection": stagesJson(),
      "exitCode": exitCode}, indent = 2))
  else:
    # DS-3/DS-4 — every notice is printed. A narrowed set that is not named is
    # indistinguishable from a complete one, which is the failure mode the
    # unreachable-backend and evidence-only rules exist to prevent.
    for n in notices:
      stderr.writeLine("repro develop --all: " & n)
    for o in outcomes:
      case o.mode
      of "cloned":
        stdout.writeLine("repro develop --all: cloned " & o.node & " @ " &
          o.revision & " -> " & o.path)
      of "adopted":
        stdout.writeLine("repro develop --all: adopted existing checkout of " &
          o.node & " @ " & o.revision & " -> " & o.path)
      of "reset":
        stdout.writeLine("repro develop --all: reset drifted checkout of " &
          o.node & " to locked revision " & o.revision & " -> " & o.path)
      of "would-clone":
        stdout.writeLine("repro develop --all: would clone " & o.node & " @ " &
          o.revision & " -> " & o.path & " (dry run; nothing was changed)")
      of "would-reset":
        stdout.writeLine("repro develop --all: would reset drifted checkout " &
          "of " & o.node & " to locked revision " & o.revision & " -> " &
          o.path & " (dry run; nothing was changed)")
      of "idempotent":
        stdout.writeLine("repro develop --all: " & o.node &
          " already in develop mode at " & o.path & " (no change)")
      of "refused":
        stderr.writeLine("repro develop --all: refused " & o.node & " — " &
          o.diagnostic)
      else:
        stderr.writeLine("repro develop --all: error " & o.node & " — " &
          o.diagnostic)
    if exitCode == 0 and outcomes.len == 0:
      stdout.writeLine("repro develop --all: no dependency nodes selected")
  exitCode

proc parseCommaList(value: string): seq[string] =
  for n in value.split(','):
    let item = n.strip()
    if item.len > 0: result.add(item)

const developLockStoreKinds = ["committed-file", "git-checkout", "git-notes",
                               "separate-branch", "external-cli"]

proc parseAdhocLockStore(spec: string): DevelopAdhocLockStore =
  ## DS-8 — parse ``--lock-store=[<tier>:]<kind>:<location>``.
  ##
  ## The spec's documented (and CI) form is the two-field
  ## ``<kind>:<location>``. A route needs a TIER to compose with the
  ## configuration plane at all, and the two-field form does not carry one, so
  ## the tier is **`team`** — announced on every run that uses the flag, never
  ## applied silently. That choice is not arbitrary: `--lock-store` exists
  ## because "a CI checkout is shallow and has no VCS-private layer-5 config —
  ## that file is never pushed, by design — so the private route must be
  ## supplied explicitly", and `public` is precisely the one tier that needs no
  ## escape hatch (its records are the in-tree committed lock). Any other tier
  ## is named explicitly with the three-field
  ## ``<tier>:<kind>:<location>`` form.
  ##
  ## A location containing ``:`` (a Windows drive letter, a URL) is preserved:
  ## the split is from the LEFT and only over the recognized leading tokens.
  let raw = spec.strip()
  if raw.len == 0:
    raise newException(ValueError,
      "--lock-store requires a value of the form <kind>:<location> " &
      "(kinds: " & developLockStoreKinds.join(" | ") & ")")
  result.spec = raw
  result.tier = wvTeam
  var rest = raw
  let firstColon = rest.find(':')
  if firstColon <= 0:
    raise newException(ValueError,
      "--lock-store=" & raw & " is malformed: expected " &
      "<kind>:<location> (kinds: " & developLockStoreKinds.join(" | ") &
      "), optionally prefixed with <tier>: (public | org | team | personal)")
  let firstTok = rest[0 ..< firstColon].strip().toLowerAscii()
  if firstTok in ["public", "org", "team", "personal", "private"]:
    result.tierExplicit = true
    result.tier =
      case firstTok
      of "public": wvPublic
      of "org": wvOrg
      of "team": wvTeam
      else: wvPersonal
    rest = rest[firstColon + 1 .. ^1]
  let kindColon = rest.find(':')
  if kindColon <= 0:
    raise newException(ValueError,
      "--lock-store=" & raw & " is malformed: expected " &
      "<kind>:<location> after the tier (kinds: " &
      developLockStoreKinds.join(" | ") & ")")
  result.kind = rest[0 ..< kindColon].strip().toLowerAscii()
  result.location = rest[kindColon + 1 .. ^1].strip()
  if result.kind notin developLockStoreKinds:
    raise newException(ValueError,
      "--lock-store=" & raw & " names an unknown backend kind '" &
      result.kind & "' (expected one of: " &
      developLockStoreKinds.join(" | ") & ")")
  if result.location.len == 0:
    raise newException(ValueError,
      "--lock-store=" & raw & " names no location for the '" & result.kind &
      "' backend")

proc parseDevelopAllArgs(args: openArray[string]): DevelopAllArgs =
  ## ``repro develop --list|--all|--direct|--indirect|--transitive-of=<pkg>
  ## [--project=<list>] [--tag=<list>] [--filter=<glob>] [--only=<list>]
  ## [--except=<list>] [--tier=<list>] [--at=<rev>]
  ## [--lock-store=<kind>:<location>]... [--into=<dir>] [--reset] [--strict]
  ## [--dry-run] [--workspace-root=<path>]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## The three axes of CLI/develop.md §"Command Surface" are kept separate, and
  ## a flag belongs to exactly one of them:
  ##
  ##   * SOURCE — ``--tier``, ``--at``, ``--lock-store``, ``--strict``: which
  ##     lock records contribute at all;
  ##   * MEMBERSHIP — the mode flags, ``--project``, ``--tag``, ``--filter``,
  ##     ``--only``, ``--except``: which repos are selected, composed in the
  ##     FIXED order the spec fixes so the result never depends on argv order;
  ##   * ACTION — ``--list``, ``--dry-run``, ``--into``, ``--reset``, ``--json``:
  ##     what happens to the selected set.
  ##
  ## ``--list`` (DS-6) prints the resolved lock set and exits, mutating
  ## nothing. It REQUIRES NO SELECTOR and defaults to the whole lock set,
  ## because a query has no destructive edge. ``--dry-run`` is the same
  ## promise one step further down: it resolves the set AND the placement plan
  ## and prints what WOULD happen.
  ##
  ## ``--only`` / ``--except`` / ``--project`` / ``--tag`` name things
  ## EXACTLY; a name that matches nothing is a loud error, never a silent
  ## no-op. ``--filter`` is a glob and may legitimately match nothing.
  ##
  ## ``--strict`` promotes the personal-tier unreachable-backend warning to the
  ## same refusal the public/team tiers get (DS-3).
  ##
  ## ``--reset`` force-reconciles an already-present sibling checkout that has
  ## drifted off the locked revision back to the lock (destructive re-clone at
  ## the locked SHA) instead of refusing. Default off = refuse-on-drift.
  result.mode = dasmAll
  result.toolProvisioning = tpmPathOnly
  var i = 0
  var sawSelector = false
  var sawMode = false
  # "Selectors compose in a FIXED ORDER, **so the result never depends on argv
  # order**" (CLI/develop.md §"Membership axis"). The fixed stage order alone
  # does not deliver that promise: the list-valued selectors (`--only`,
  # `--except`, `--project`, `--tag`) ACCUMULATE and are order-free, but the
  # SINGLE-VALUED ones would silently take the LAST occurrence — so
  # `--all --direct` and `--direct --all` are the same flag set in two argv
  # orders and would answer differently, which is exactly what the rule
  # forbids. A repeated single-valued selector is therefore a LOUD refusal
  # rather than a silent last-wins; repeating the SAME value is harmless and
  # stays accepted, because a script assembling argv from several fragments
  # legitimately does that.
  var modeFlag = ""
  proc chooseMode(flag: string) =
    if modeFlag.len > 0 and modeFlag != flag:
      raise newException(ValueError,
        "`repro develop` was given two different selection modes (" &
        modeFlag & " and " & flag & "). They are alternatives, not a " &
        "composition, and taking the last one would make the answer depend " &
        "on argv order — which the fixed selector order exists to prevent. " &
        "Pass exactly one of --all / --direct / --indirect / --transitive-of.")
    modeFlag = flag
  proc single(field: var string; flag, value: string) =
    if field.len > 0 and field != value:
      raise newException(ValueError,
        flag & " was given twice with different values ('" & field &
        "' and '" & value & "'). It takes a single value, and taking the " &
        "last one would make the answer depend on argv order. Pass one " &
        flag & (if flag == "--filter":
                  " (a glob: `--filter='{a,b}'` is not supported, but " &
                  "`--only=a,b` names both exactly)"
                else: "") & ".")
    field = value
  while i < args.len:
    let arg = args[i]
    if arg == "--all":
      chooseMode("--all")
      result.mode = dasmAll; sawSelector = true; sawMode = true
    elif arg == "--direct":
      chooseMode("--direct")
      result.mode = dasmDirect; sawSelector = true; sawMode = true
    elif arg == "--indirect":
      chooseMode("--indirect")
      result.mode = dasmIndirect; sawSelector = true; sawMode = true
    elif arg == "--transitive-of" or arg.startsWith("--transitive-of="):
      let pkg = valueFromFlag(args, i, "--transitive-of")
      chooseMode("--transitive-of=" & pkg)
      result.mode = dasmTransitiveOf
      single(result.transitiveOf, "--transitive-of", pkg)
      sawSelector = true; sawMode = true
    elif arg == "--filter" or arg.startsWith("--filter="):
      single(result.filter, "--filter", valueFromFlag(args, i, "--filter"))
    elif arg == "--only" or arg.startsWith("--only="):
      result.only.add(parseCommaList(valueFromFlag(args, i, "--only")))
      sawSelector = true
    elif arg == "--except" or arg.startsWith("--except="):
      result.exceptNames.add(parseCommaList(valueFromFlag(args, i, "--except")))
    elif arg == "--project" or arg.startsWith("--project="):
      result.projects.add(parseCommaList(valueFromFlag(args, i, "--project")))
      sawSelector = true
    elif arg == "--tag" or arg.startsWith("--tag="):
      result.tags.add(parseCommaList(valueFromFlag(args, i, "--tag")))
      sawSelector = true
    elif arg == "--tier" or arg.startsWith("--tier="):
      for t in parseCommaList(valueFromFlag(args, i, "--tier")):
        let tier = t.toLowerAscii()
        if tier notin ["public", "org", "team", "personal", "private"]:
          raise newException(ValueError,
            "--tier=" & t & " names no locking tier (expected one or more " &
            "of: public | org | team | personal)")
        # `private` is the workspace TOML's other spelling of `personal`
        # (WorkspaceVisibility carries one canonical name); normalize so the
        # tier compares equal to ``lockingTierLabel``'s output.
        result.tiers.add(if tier == "private": "personal" else: tier)
    elif arg == "--lock-store" or arg.startsWith("--lock-store="):
      result.lockStores.add(
        parseAdhocLockStore(valueFromFlag(args, i, "--lock-store")))
    elif arg == "--at" or arg.startsWith("--at="):
      let rev = valueFromFlag(args, i, "--at").strip()
      if rev.len == 0:
        raise newException(ValueError, "--at requires a revision")
      # Single-valued for the same reason the mode flags are: two `--at`s
      # would key the commit-addressed backends on whichever came last.
      single(result.at, "--at", rev)
    elif arg == "--list":
      result.list = true
    elif arg == "--strict":
      result.strict = true
    elif arg == "--into" or arg.startsWith("--into="):
      result.intoDir = valueFromFlag(args, i, "--into")
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--json":
      result.json = true
    elif arg == "--reset":
      result.reset = true
    elif arg == "--dry-run":
      result.dryRun = true
    else:
      raise newException(ValueError,
        "unsupported `repro develop` set-form argument: " & arg)
    inc i
  if not sawSelector and result.transitiveOf.len == 0:
    result.mode = dasmAll
  if result.mode == dasmTransitiveOf and result.transitiveOf.len == 0:
    raise newException(ValueError,
      "`repro develop --transitive-of=<pkg>` requires a package name")
  if result.list and result.reset:
    raise newException(ValueError,
      "`repro develop --list` is a query and cannot be combined with " &
      "--reset (a destructive action)")
  # ``--list`` requires no selector; every OTHER form does, because "a bulk
  # mutation of the working tree is never implicit".
  if not result.list and not sawMode and not sawSelector:
    raise newException(ValueError,
      "`repro develop` with no target and no selector is not a bulk " &
      "operation: pass --all/--direct/--indirect/--transitive-of, a " &
      "membership selector, or --list to query the lock set")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc looksLikeDevelopAllArgs(args: openArray[string]): bool =
  ## The L1 develop-SET form is distinguished by a set-selection flag
  ## (``--all`` / ``--direct`` / ``--indirect`` / ``--transitive-of`` /
  ## ``--only`` / ``--project`` / ``--tag``) or by the SET-PATH ``--list``
  ## (DS-6). ``--into`` / ``--filter`` alone stay on the pre-L1
  ## single-dependency ``--into`` route (that route already owns ``--into``).
  ##
  ## DS-6 — ``--list`` used to route AWAY from here unconditionally, which is
  ## why "today `--list` only reaches the pre-set route". The pre-set route's
  ## `--list` printed the local develop-OVERRIDE map; that output now lives on
  ## the explicit ``--list-overrides``, and bare ``--list`` answers the
  ## question CLI/develop.md §"Action axis" assigns it: "what does this
  ## workspace's lock set manage?". Nothing is lost — every override still
  ## appears, as a row with state `develop`.
  for arg in args:
    if arg == "--" or arg == "--cmake" or arg == "--list-overrides":
      return false
  for arg in args:
    if arg == "--all" or arg == "--direct" or arg == "--indirect" or
        arg == "--list" or
        arg == "--transitive-of" or arg.startsWith("--transitive-of=") or
        arg == "--only" or arg.startsWith("--only=") or
        arg == "--project" or arg.startsWith("--project=") or
        arg == "--tag" or arg.startsWith("--tag="):
      return true
  false

proc looksLikeWorkspaceDevelopArgs(args: openArray[string]): bool =
  ## Decide whether the argv looks like the M22 workspace-overlay form
  ## (``repro develop <pkg> [--source=...] [--workspace-root=...]
  ## [--json]``) as opposed to the pre-M22 surfaces (``--list``,
  ## ``<dependency> --into=PATH``, ``<target> -- <command>``,
  ## ``--cmake``). Returns true when at least one M22-distinctive
  ## marker is present AND none of the pre-M22 markers are present.
  ##
  ## The M22-distinctive markers are: ``--source[=...]``, ``--json``,
  ## ``--write-report[=...]``, ``--workspace-root[=...]``. The pre-M22 markers
  ## are: ``--list``,
  ## ``--into[=...]``, ``--cmake``, ``--cmake-binary[=...]``,
  ## ``--work-root[=...]``, ``--tool-provisioning[=...]``, ``--``
  ## (the command separator).
  var hasM22Marker = false
  for arg in args:
    if arg == "--source" or arg.startsWith("--source=") or
        arg == "--json" or
        arg == "--write-report" or arg.startsWith("--write-report=") or
        arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      hasM22Marker = true
    if arg == "--list" or arg == "--list-overrides" or
        arg == "--into" or arg.startsWith("--into=") or
        arg == "--cmake" or
        arg == "--cmake-binary" or arg.startsWith("--cmake-binary=") or
        arg == "--work-root" or arg.startsWith("--work-root=") or
        arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning=") or
        arg == "--":
      return false
  hasM22Marker

proc runDevelopCommand*(args: openArray[string]): int =
  ## `repro develop …`. Exported for the same reason `runReproLockCommand` is:
  ## a test that asserts on what the verb WRITES has to reach the verb, and
  ## reaching a private copy of its body instead would let the two drift.
  # L1 routing: a set-selection flag (``--all`` / ``--direct`` /
  # ``--transitive-of``) routes to the lock-driven develop-SET command that
  # clones every selected dependency at its locked revision (CLI/develop.md
  # §"Develop Set Selection"). Checked FIRST so ``--all --into=...`` reaches the
  # set path rather than the single-dependency ``--into`` route.
  if looksLikeDevelopAllArgs(args):
    return runDevelopAllCommand(parseDevelopAllArgs(args))
  # M22 routing: when the argv carries an M22-distinctive flag
  # (``--source``, ``--workspace-root``, ``--json``) and none of the
  # pre-M22 markers (``--list``, ``--into``, ``--cmake``,
  # ``--tool-provisioning``, ``--work-root``, ``--``), dispatch to the
  # workspace-overlay form documented in ``CLI/develop.md``.
  if looksLikeWorkspaceDevelopArgs(args):
    return runWorkspaceDevelopCommand(args)
  var target = ""
  var mode = tpmUnspecified
  var command: seq[string] = @[]
  var afterSeparator = false
  var workRoot = ""
  var cmakeMode = false
  var cmakeBinary = ""
  var listOverrides = false
  var intoPath = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if afterSeparator:
      command.add(arg)
    elif arg == "--":
      afterSeparator = true
    elif arg == "--cmake":
      cmakeMode = true
    elif arg == "--list-overrides":
      # DS-6 — this is the pre-set route's old ``--list``: the local
      # develop-OVERRIDE map (`<node>\t<path>`), byte-identical. Bare ``--list``
      # now answers the lock-set question CLI/develop.md assigns it, so the two
      # meanings got one name each instead of sharing one.
      listOverrides = true
    elif arg == "--into" or arg.startsWith("--into="):
      intoPath = valueFromFlag(args, i, "--into")
    elif arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(arg.split("=", maxsplit = 1)[1])
    elif arg == "--tool-provisioning":
      raise newException(ValueError,
        "--tool-provisioning requires an inline value, for example " &
        "--tool-provisioning=nix")
    elif arg.startsWith("--cmake-binary="):
      cmakeBinary = arg.split("=", maxsplit = 1)[1]
    elif arg == "--cmake-binary":
      raise newException(ValueError,
        "--cmake-binary requires an inline value, for example " &
          "--cmake-binary=/path/to/cmake")
    elif arg.startsWith("--work-root="):
      workRoot = arg.split("=", maxsplit = 1)[1]
    elif arg == "--work-root":
      raise newException(ValueError,
        "--work-root requires an inline value, for example --work-root=.repro")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported develop flag: " & arg)
    elif target.len == 0:
      target = arg
    else:
      raise newException(ValueError, "unexpected develop argument before --: " & arg)
    inc i

  if listOverrides:
    if target.len > 0 or intoPath.len > 0 or command.len > 0 or cmakeMode:
      raise newException(ValueError,
        "repro develop --list-overrides does not accept a target, --into, " &
        "--cmake, or a command")
    let projectRoot = activeProjectRootFromCwd()
    for entry in readDevelopOverrides(developOverridesMetadataPath(projectRoot)):
      echo entry.node & "\t" & entry.path
    return 0

  if intoPath.len > 0:
    if cmakeMode or mode != tpmUnspecified or command.len > 0:
      raise newException(ValueError,
        "repro develop <dependency> --into=PATH cannot be combined with " &
          "--cmake, --tool-provisioning, or -- <command>")
    if target.len == 0:
      raise newException(ValueError,
        "repro develop --into=PATH requires a dependency name")
    let projectRoot = activeProjectRootFromCwd()
    let localPath = resolveDevelopOverrideCheckout(target, intoPath)
    let metadataPath = upsertDevelopOverride(projectRoot, target, localPath)
    echo target & "\t" & localPath
    echo "metadata\t" & metadataPath
    return 0

  if target.len == 0:
    raise newException(ValueError, "missing develop target")

  if cmakeMode:
    if mode == tpmUnspecified:
      raise newException(ValueError,
        "repro develop --cmake requires --tool-provisioning=path|nix")
    return runCMakeDevelopCommand(target, mode, command, workRoot, cmakeBinary)

  let modulePath = absolutePath(moduleForTarget(target))
  if not fileExists(extendedPath(modulePath)):
    raise newException(IOError, "develop target module not found: " & modulePath)

  let scopedRoot = scopedWorktreeRoot(modulePath, workRoot)
  let outDir =
    if scopedRoot.len > 0:
      scopedRoot / "develop"
    else:
      parentDir(modulePath) / ".repro" / "develop"
  let interfacePath = outDir / "project-interface.rbsz"
  let stubPath = outDir / "project-interface.nim"
  let compileWorkDir = reprobuildLibraryWorkDir()
  let compileScratchDir = outDir / "provider-work"
  # MR5 — see executeBuildTarget for the bootstrap toolchain rationale.
  ensureBootstrapToolchainEnv(mode, resolveStoreRoot() / "tool-store")
  var developStats: BuildStats
  let artifact = extractInterfaceEdge(modulePath, interfacePath, stubPath,
    compileWorkDir, compileScratchDir, projectRootForModule(modulePath),
    stablePublicCliPath(), outDir / "build-engine-cache", developStats)

  var effectiveMode = mode
  if effectiveMode == tpmUnspecified and
      artifact.projectInterface.defaultToolProvisioning.len > 0:
    effectiveMode = parseToolProvisioning(
      artifact.projectInterface.defaultToolProvisioning)

  if artifact.projectInterface.toolUses.len > 0 and
      effectiveMode == tpmUnspecified:
    raise newException(ValueError,
      "typed tool provisioning is required for uses declarations; refusing " &
        "implicit PATH fallback. Pass --tool-provisioning=path for the weak " &
        "local profile, or --tool-provisioning=nix|tarball for a provisioned " &
        "development environment.")

  if effectiveMode == tpmUnspecified:
    echo "repro develop: compatibility dev-env path active (provider-driven " &
      "artifact integration pending); no external tools requested"
    if command.len == 0:
      return 0
    return runInDevelopEnvironment(command, projectRootForModule(modulePath),
      PathOnlyBuildIdentity(projectName: artifact.projectInterface.projectName,
        interfaceFingerprint: artifact.interfaceFingerprint),
      "", "", interfacePath)

  if not shouldEnterBuildPipeline(effectiveMode):
    raise newException(ValueError,
      "unsupported develop tool provisioning mode: " & effectiveMode.modeName)

  let resolved = warmResolveAndWriteIdentity(artifact, outDir, effectiveMode)
  echo "repro develop: compatibility dev-env path active (provider-driven " &
    "artifact integration pending, tool-provisioning=" & effectiveMode.modeName & ")"
  echo "project: " & artifact.projectInterface.projectName
  echo "interface: " & interfacePath
  echo "toolIdentity: " & resolved.identityPath
  echo "inspection: " & resolved.inspectionPath
  echo "binDirs: " & binDirsForDevelop(resolved.identity).join($PathSep)

  if command.len == 0:
    for profile in resolved.identity.profiles:
      echo "tool: " & profile.executableName & " " &
        profile.resolvedExecutablePath
    return 0

  runInDevelopEnvironment(command, projectRootForModule(modulePath),
    resolved.identity, resolved.identityPath, resolved.inspectionPath,
    interfacePath)

proc runStoreDaemonCommand(args: seq[string]): int =
  if args.len == 0:
    echo "usage: repro store daemon {start | status | stop} --dev " &
      "[--store-root <path>]"
    return 2
  let action = args[0]
  let rest = if args.len > 1: args[1 .. ^1] else: @[]
  if "--dev" notin rest:
    stderr.writeLine("repro store daemon: only --dev is implemented in " &
      "this pass; production service hardening is not implemented")
    return 2
  var filtered: seq[string] = @[]
  for arg in rest:
    if arg != "--dev":
      filtered.add(arg)
  try:
    let parsed = parseDevConfig(filtered)
    if parsed.rest.len > 0:
      stderr.writeLine("repro store daemon: unexpected argument: " &
        parsed.rest[0])
      return 2
    case action
    of "start":
      let status = startDevDaemon(stablePublicCliPath(), parsed.config)
      echo renderStatus(status)
      return 0
    of "status":
      echo renderStatus(queryDevStatus(parsed.config.endpoint))
      return 0
    of "stop":
      let status = queryDevStatus(parsed.config.endpoint)
      if not status.running:
        echo renderStatus(status)
        return 0
      stopDevDaemon(parsed.config.endpoint)
      echo "repro store daemon: stopped"
      return 0
    else:
      stderr.writeLine("repro store daemon: unknown action: " & action)
      return 2
  except CatchableError as err:
    stderr.writeLine("repro store daemon " & action & ": error: " & err.msg)
    return 1

proc runStoreCommand*(args: seq[string]): int =
  ## Implements `repro store <subcommand>` for the M56 unified local
  ## content-addressed store. Supported subcommands:
  ##
  ##   gc       — eager garbage collection (SQL dead-set query plus a
  ##              filesystem move into `gc/pending-deletion/` and a
  ##              post-grace unlink sweep).
  ##   recover  — `PRAGMA quick_check`, sweep `tmp/`, and reconcile
  ##              on-disk `prefixes/...` directories against the
  ##              SQLite index.
  ##   roots    — list the currently-registered roots.
  ##   list     — list every realized prefix recorded in the index.
  ##
  ## Each subcommand accepts an optional `--store-root=PATH` to
  ## override the per-user default; the `$REPRO_STORE_ROOT` env var
  ## is honoured otherwise.
  if args.len == 0:
    echo "usage: repro store {gc | recover | roots | list} " &
      "[--store-root=PATH] [--grace-seconds=N]"
    return 2
  if args[0] == "serve":
    # Executable-Consolidation M3: `repro store serve` is the store daemon
    # PROCESS entry — the role formerly carried by the standalone `reprostored`
    # binary (whose program name stays a compatibility alias). `repro store
    # daemon …` remain the client control commands.
    return runReprostoredCommand(if args.len > 1: args[1 .. ^1] else: @[])
  if args[0] == "daemon":
    let daemonArgs = if args.len > 1: args[1 .. ^1] else: @[]
    return runStoreDaemonCommand(daemonArgs)
  var storeRootOverride = ""
  var graceSeconds = DefaultGcGraceSeconds
  var sub = ""
  for raw in args:
    if raw.startsWith("--store-root="):
      storeRootOverride = raw[len("--store-root=") .. ^1]
    elif raw.startsWith("--grace-seconds="):
      graceSeconds = parseInt(raw[len("--grace-seconds=") .. ^1])
    elif raw.startsWith("--"):
      stderr.writeLine("repro store: unknown flag: " & raw)
      return 2
    elif sub.len == 0:
      sub = raw
    else:
      stderr.writeLine("repro store: unexpected argument: " & raw)
      return 2
  if sub.len == 0:
    stderr.writeLine("repro store: missing subcommand")
    return 2

  let root = resolveStoreRoot(storeRootOverride)
  try:
    case sub
    of "gc":
      var store = openStore(root)
      defer: store.close()
      let report = store.gc(graceSeconds = graceSeconds)
      echo "repro store gc: store-root=" & root
      echo "quarantined: " & $report.quarantined.len
      for row in report.quarantined:
        echo "  - " & row.adapter & " " & row.packageName & " " &
          row.version
      echo "reclaimed: " & $report.reclaimed.len
      for path in report.reclaimed:
        echo "  - " & path
      return 0
    of "recover":
      let report = recoverStoreRoot(root)
      echo "repro store recover: store-root=" & root
      echo "index rebuilt: " & (if report.indexRebuilt: "yes" else: "no")
      if report.indexRebuilt:
        echo "index recovery reason: " & report.indexRecoveryReason
        echo "index quarantine: " & report.indexQuarantineDir
        echo "quarantined index files: " & $report.quarantinedIndexFiles.len
        for path in report.quarantinedIndexFiles: echo "  - " & path
      echo "quick_check: " & report.quickCheck
      echo "swept staging dirs: " & $report.sweptStagingDirs.len
      for path in report.sweptStagingDirs: echo "  - " & path
      echo "reinserted prefixes: " & $report.reinsertedPrefixes.len
      for path in report.reinsertedPrefixes: echo "  - " & path
      echo "quarantined prefixes: " & $report.quarantinedPrefixes.len
      for path in report.quarantinedPrefixes: echo "  - " & path
      return 0
    of "roots":
      var store = openStore(root)
      defer: store.close()
      echo "repro store roots: store-root=" & root
      for row in store.listRoots():
        echo "  - " & row.rootId & " (" & row.kind & ")"
      return 0
    of "list":
      var store = openStore(root)
      defer: store.close()
      echo "repro store list: store-root=" & root
      for row in store.listPrefixes():
        echo "  - " & row.adapter & " " & row.packageName & " " &
          row.version & " " & row.realizedPath
      return 0
    else:
      stderr.writeLine("repro store: unknown subcommand: " & sub)
      return 2
  except CatchableError as err:
    stderr.writeLine("repro store " & sub & ": error: " & err.msg)
    return 1

proc runCasCommand*(args: seq[string]): int =
  ## Implements ``repro cas <subcommand>`` for the R11 Layer-1
  ## content-addressed blob store. This is the NARROW view onto the
  ## same on-disk store ``repro store`` operates against — it exposes
  ## only the blob-level surface (put / get / verify / path / gc) and
  ## does NOT touch the Layer-2 prefix / roots / receipts tables.
  ##
  ## Spec: Store-And-Installation-Layout.md §R11 Two-Layer Split.
  ##
  ## Supported subcommands:
  ##
  ##   gc [--keep=HEX,HEX,...] [--store-root=PATH]
  ##     Reclaim CAS blobs NOT in the ``--keep`` retain set. Returns
  ##     the freed bytes count. NOTE: this is the narrow Layer-1 GC;
  ##     for the store-wide GC that walks the prefix graph and
  ##     reclaims everything unreachable from any live root, use
  ##     ``repro store gc`` (which delegates through the SQLite root
  ##     tables).
  ##
  ##   verify <hex> [--store-root=PATH]
  ##     Verify one blob's on-disk bytes against its digest.
  ##
  ##   path <hex> [--store-root=PATH]
  ##     Print the absolute on-disk path for one blob.
  ##
  ##   exists <hex> [--store-root=PATH]
  ##     Exit 0 if the blob is present, 1 if not.
  if args.len == 0:
    echo "usage: repro cas {gc | verify <hex> | path <hex> | " &
      "exists <hex>} [--store-root=PATH] [--keep=HEX,HEX,...]"
    return 2
  var storeRootOverride = ""
  var keepList = ""
  var sub = ""
  var positional: seq[string] = @[]
  for raw in args:
    if raw.startsWith("--store-root="):
      storeRootOverride = raw[len("--store-root=") .. ^1]
    elif raw.startsWith("--keep="):
      keepList = raw[len("--keep=") .. ^1]
    elif raw.startsWith("--"):
      stderr.writeLine("repro cas: unknown flag: " & raw)
      return 2
    elif sub.len == 0:
      sub = raw
    else:
      positional.add(raw)
  if sub.len == 0:
    stderr.writeLine("repro cas: missing subcommand")
    return 2

  let root = resolveStoreRoot(storeRootOverride)

  proc parseHex64(hex: string): (bool, ContentHash) =
    if hex.len != 64:
      return (false, ContentHash(default(array[32, byte])))
    var raw: array[32, byte]
    for i in 0 ..< 32:
      let hi = hex[2 * i]
      let lo = hex[2 * i + 1]
      let hiVal =
        if hi >= '0' and hi <= '9': int(hi) - int('0')
        elif hi >= 'a' and hi <= 'f': 10 + int(hi) - int('a')
        elif hi >= 'A' and hi <= 'F': 10 + int(hi) - int('A')
        else: return (false, ContentHash(default(array[32, byte])))
      let loVal =
        if lo >= '0' and lo <= '9': int(lo) - int('0')
        elif lo >= 'a' and lo <= 'f': 10 + int(lo) - int('a')
        elif lo >= 'A' and lo <= 'F': 10 + int(lo) - int('A')
        else: return (false, ContentHash(default(array[32, byte])))
      raw[i] = byte((hiVal shl 4) or loVal)
    (true, toContentHash(raw))

  try:
    case sub
    of "gc":
      var cas = openCasStore(root)
      defer: cas.close()
      var retain: HashSet[ContentHash]
      if keepList.len > 0:
        for entry in keepList.split(','):
          let trimmed = entry.strip()
          if trimmed.len == 0: continue
          let (ok, h) = parseHex64(trimmed)
          if not ok:
            stderr.writeLine(
              "repro cas gc: --keep entry is not a 64-char hex digest: " &
              trimmed)
            return 2
          retain.incl(h)
      let freed = cas.casGc(retain)
      echo "repro cas gc: store-root=" & root
      echo "retain count: " & $retain.len
      echo "freed bytes: " & $freed
      return 0
    of "verify":
      if positional.len != 1:
        stderr.writeLine(
          "repro cas verify: exactly one 64-char hex digest required")
        return 2
      let (ok, h) = parseHex64(positional[0])
      if not ok:
        stderr.writeLine(
          "repro cas verify: argument is not a 64-char hex digest")
        return 2
      var cas = openCasStore(root)
      defer: cas.close()
      if cas.casVerify(h):
        echo "repro cas verify: ok " & positional[0]
        return 0
      else:
        stderr.writeLine("repro cas verify: FAILED " & positional[0])
        return 1
    of "path":
      if positional.len != 1:
        stderr.writeLine(
          "repro cas path: exactly one 64-char hex digest required")
        return 2
      let (ok, h) = parseHex64(positional[0])
      if not ok:
        stderr.writeLine(
          "repro cas path: argument is not a 64-char hex digest")
        return 2
      var cas = openCasStore(root)
      defer: cas.close()
      echo cas.casPath(h)
      return 0
    of "exists":
      if positional.len != 1:
        stderr.writeLine(
          "repro cas exists: exactly one 64-char hex digest required")
        return 2
      let (ok, h) = parseHex64(positional[0])
      if not ok:
        stderr.writeLine(
          "repro cas exists: argument is not a 64-char hex digest")
        return 2
      var cas = openCasStore(root)
      defer: cas.close()
      if cas.casExists(h):
        return 0
      else:
        return 1
    else:
      stderr.writeLine("repro cas: unknown subcommand: " & sub)
      return 2
  except CatchableError as err:
    stderr.writeLine("repro cas " & sub & ": error: " & err.msg)
    return 1

proc runUserDaemonCliCommand(args: seq[string]): int =
  if args.len == 0:
    echo "usage: repro daemon {status | start | stop | restart | logs | sessions} " &
      "[--foreground] [--dev] [--endpoint PATH] [--state-dir PATH] " &
      "[--log PATH]"
    return 2
  let action = args[0]
  let rest = if args.len > 1: args[1 .. ^1] else: @[]
  try:
    let parsed = parseUserDaemonConfigFlags(rest)
    if parsed.rest.len > 0:
      stderr.writeLine("repro daemon: unexpected argument: " &
        parsed.rest[0])
      return 2
    let config = parsed.config
    case action
    of "status":
      let status = queryUserDaemonStatus(config.endpoint)
      if not status.running:
        discard cleanupStaleUserDaemonDiscovery(config)
      echo renderUserDaemonStatus(status)
      return 0
    of "start":
      if config.foreground:
        return runUserDaemonForeground(config)
      let status = startUserDaemon(stablePublicCliPath(), config)
      echo renderUserDaemonStatus(status)
      return 0
    of "stop":
      let status = queryUserDaemonStatus(config.endpoint)
      if not status.running:
        discard cleanupStaleUserDaemonDiscovery(config)
        echo renderUserDaemonStatus(status)
        return 0
      stopUserDaemon(config.endpoint)
      cleanupPlatformBackgroundRegistration(config)
      discard cleanupStaleUserDaemonDiscovery(config)
      echo "repro daemon: stopped"
      return 0
    of "restart":
      let status = queryUserDaemonStatus(config.endpoint)
      if status.running:
        stopUserDaemon(config.endpoint)
        cleanupPlatformBackgroundRegistration(config)
        let deadline = epochTime() + 10.0
        while epochTime() < deadline:
          if not queryUserDaemonStatus(config.endpoint).running:
            break
          sleep(25)
        discard cleanupStaleUserDaemonDiscovery(config)
      let started = startUserDaemon(stablePublicCliPath(), config)
      echo renderUserDaemonStatus(started)
      return 0
    of "logs":
      let logs = renderUserDaemonLogs(config)
      stdout.write(logs)
      if not logs.endsWith("\n"):
        stdout.writeLine("")
      return 0
    of "sessions":
      let status = queryUserDaemonStatus(config.endpoint)
      if not status.running:
        discard cleanupStaleUserDaemonDiscovery(config)
        stderr.writeLine("repro daemon sessions: daemon is not running")
        return 1
      echo renderUserDaemonSessions(requestUserDaemonSessions(config.endpoint))
      return 0
    else:
      stderr.writeLine("repro daemon: unknown action: " & action)
      return 2
  except CatchableError as err:
    stderr.writeLine("repro daemon " & action & ": error: " & err.msg)
    return 1

proc runLaunchPlanCommand*(args: seq[string]): int =
  ## Implements `repro launch-plan <subcommand>`. v1 subcommands:
  ##
  ##   show <hex-id>      Render the LaunchPlan stored in the local M56
  ##                      CAS as a JSON inspection view. The JSON form
  ##                      is debug output only — the canonical record is
  ##                      the binary RBLP envelope.
  ##   id <path>          Compute the BLAKE3-256 launchPlanId of a
  ##                      LaunchPlan envelope on disk without opening
  ##                      the store. Useful when verifying activation
  ##                      artifacts.
  ##
  ## Both subcommands accept `--store-root=PATH` and honour
  ## `$REPRO_STORE_ROOT` exactly as `repro store ...` does.
  if args.len == 0:
    echo "usage: repro launch-plan {show <hex-id> | id <path>} " &
      "[--store-root=PATH]"
    return 2
  var storeRootOverride = ""
  var positional: seq[string] = @[]
  for raw in args:
    if raw.startsWith("--store-root="):
      storeRootOverride = raw[len("--store-root=") .. ^1]
    elif raw.startsWith("--"):
      stderr.writeLine("repro launch-plan: unknown flag: " & raw)
      return 2
    else:
      positional.add(raw)
  if positional.len == 0:
    stderr.writeLine("repro launch-plan: missing subcommand")
    return 2
  let sub = positional[0]
  case sub
  of "show":
    if positional.len < 2:
      stderr.writeLine("repro launch-plan show: missing <hex-id>")
      return 2
    let hex = positional[1].toLowerAscii
    if hex.len != 64:
      stderr.writeLine(
        "repro launch-plan show: expected 64-char hex digest, got " &
        $hex.len & " chars")
      return 2
    let root = resolveStoreRoot(storeRootOverride)
    try:
      var store = openStore(root)
      defer: store.close()
      var id: PrefixIdBytes
      for i in 0 ..< 32:
        let hi = parseHexInt($hex[i * 2])
        let lo = parseHexInt($hex[i * 2 + 1])
        id[i] = byte((hi shl 4) or lo)
      let plan = store.loadLaunchPlan(id)
      echo launchPlanToJson(plan)
      return 0
    except CatchableError as err:
      stderr.writeLine("repro launch-plan show: error: " & err.msg)
      return 1
  of "id":
    if positional.len < 2:
      stderr.writeLine("repro launch-plan id: missing <path>")
      return 2
    let path = positional[1]
    try:
      let raw = readFile(extendedPath(path))
      var buf = newSeq[byte](raw.len)
      for i, ch in raw: buf[i] = byte(ord(ch))
      let plan = decodeLaunchPlan(buf)
      echo launchPlanIdHex(plan)
      return 0
    except CatchableError as err:
      stderr.writeLine("repro launch-plan id: error: " & err.msg)
      return 1
  else:
    stderr.writeLine("repro launch-plan: unknown subcommand: " & sub)
    return 2

type
  HcrCoordinateArgs = object
    project: string
    target: string
    socketPath: string
    sourceEditDriver: string
    artifacts: string
    patchFunction: string

proc parseHcrCoordinateArgs(args: seq[string]): HcrCoordinateArgs =
  result.patchFunction = "reprobuild_hcr_patchable_value"
  var index = 0
  while index < args.len:
    let arg = args[index]
    proc valueFor(flag: string): string =
      let prefix = flag & "="
      if arg.startsWith(prefix):
        return arg[prefix.len .. ^1]
      if arg == flag:
        if index + 1 >= args.len:
          raise newException(ValueError, flag & " requires a value")
        index.inc
        return args[index]
      raise newException(ValueError, "internal HCR argument parse error")

    if arg == "--project" or arg.startsWith("--project="):
      result.project = valueFor("--project")
    elif arg == "--target" or arg.startsWith("--target="):
      result.target = valueFor("--target")
    elif arg == "--socket" or arg.startsWith("--socket="):
      result.socketPath = valueFor("--socket")
    elif arg == "--source-edit-driver" or
        arg.startsWith("--source-edit-driver="):
      result.sourceEditDriver = valueFor("--source-edit-driver")
    elif arg == "--artifacts" or arg.startsWith("--artifacts="):
      result.artifacts = valueFor("--artifacts")
    elif arg == "--patch-function" or arg.startsWith("--patch-function="):
      result.patchFunction = valueFor("--patch-function")
    else:
      raise newException(ValueError, "unsupported HCR coordinate flag: " & arg)
    index.inc

proc requireHcrArg(value, name: string) =
  if value.len == 0:
    raise newException(ValueError, name & " is required")

proc requireHcrFile(path, name: string) =
  requireHcrArg(path, name)
  if not fileExists(extendedPath(path)):
    raise newException(ValueError, name & " does not exist: " & path)

proc requireHcrDir(path, name: string) =
  requireHcrArg(path, name)
  if not dirExists(extendedPath(path)):
    raise newException(ValueError, name & " does not exist: " & path)

proc runHcrBuildCycle(project, target, logPath: string): string =
  let targetArg = project & "#" & target
  let command = shellCommand([
    getAppFilename(), "build", targetArg,
    "--tool-provisioning=path",
    "--progress=none",
    "--log=actions"])
  let res = execCmdEx(command, workingDir = project)
  result = res.output
  createDir(extendedPath(parentDir(logPath)))
  writeFile(extendedPath(logPath), res.output)
  if res.exitCode != 0:
    raise newException(ValueError,
      "repro build failed during HCR coordination with exit code " &
        $res.exitCode & "\n" & res.output)

type HcrPrepareObjectArgs = object
  input: string
  output: string
  functionName: string
  segmentName: string
  allCodeSections: bool

proc parseHcrPrepareObjectArgs(args: seq[string]): HcrPrepareObjectArgs =
  result.segmentName = "__HCR"
  var index = 0
  proc valueFor(name: string): string =
    let arg = args[index]
    let prefix = name & "="
    if arg.startsWith(prefix):
      arg[prefix.len .. ^1]
    else:
      index.inc
      if index >= args.len:
        raise newException(ValueError, name & " requires a value")
      args[index]

  while index < args.len:
    let arg = args[index]
    if arg == "--input" or arg.startsWith("--input="):
      result.input = valueFor("--input")
    elif arg == "--output" or arg.startsWith("--output="):
      result.output = valueFor("--output")
    elif arg == "--function" or arg.startsWith("--function="):
      result.functionName = valueFor("--function")
    elif arg == "--all-code":
      result.allCodeSections = true
    elif arg == "--segment" or arg.startsWith("--segment="):
      result.segmentName = valueFor("--segment")
    else:
      raise newException(ValueError,
        "unsupported HCR prepare-object flag: " & arg)
    index.inc

proc runHcrPrepareObjectCommand(args: seq[string]): int =
  let parsed = parseHcrPrepareObjectArgs(args)
  requireHcrFile(parsed.input, "--input")
  requireHcrArg(parsed.output, "--output")
  if parsed.functionName.len == 0 and not parsed.allCodeSections:
    raise newException(ValueError, "--function or --all-code is required")
  if parsed.functionName.len > 0 and parsed.allCodeSections:
    raise newException(ValueError, "--function and --all-code are mutually exclusive")
  requireHcrArg(parsed.segmentName, "--segment")
  createDir(extendedPath(parentDir(parsed.output)))
  if parsed.allCodeSections:
    let count = rewriteMachOArm64CodeSectionSegments(
      parsed.input, parsed.output, parsed.segmentName)
    echo "repro hcr prepare-object: output=" & parsed.output &
      " codeSections=" & $count & " segment=" & parsed.segmentName
  else:
    rewriteMachOArm64FunctionSectionSegment(
      parsed.input, parsed.output, parsed.functionName, parsed.segmentName)
    echo "repro hcr prepare-object: output=" & parsed.output &
      " function=" & parsed.functionName & " segment=" & parsed.segmentName
  0

proc runHcrCoordinateCommand(args: seq[string]): int =
  if args.len == 0:
    stderr.writeLine(
      "repro hcr coordinate --project PATH --target NAME --socket PATH " &
      "--source-edit-driver PATH --artifacts PATH\n" &
      "repro hcr prepare-object --input PATH --output PATH " &
      "(--function NAME|--all-code) " &
      "[--segment NAME]")
    return 2
  if args[0] == "prepare-object":
    return runHcrPrepareObjectCommand(args[1 .. ^1])
  if args[0] != "coordinate":
    stderr.writeLine("repro hcr: unknown subcommand: " & args[0])
    return 2

  var parsed = parseHcrCoordinateArgs(args[1 .. ^1])
  requireHcrDir(parsed.project, "--project")
  requireHcrArg(parsed.target, "--target")
  requireHcrArg(parsed.socketPath, "--socket")
  requireHcrFile(parsed.sourceEditDriver, "--source-edit-driver")
  requireHcrArg(parsed.artifacts, "--artifacts")
  createDir(extendedPath(parsed.artifacts))

  let patchObject = parsed.project / "build" / "patchable.o"
  requireHcrFile(patchObject, "initial patchable object")
  let oldObject = parsed.artifacts / "patchable-generation0.o"
  copyFile(extendedPath(patchObject), extendedPath(oldObject))

  var listener = listenHcrAgentUnixSocket(parsed.socketPath)
  defer: listener.close()
  var connection = acceptHcrAgentConnection(listener)
  defer: connection.close()

  var client = initHcrCoordinatorClient(CodetracerHcrSupportProfile)
  discard client.receiveAgentMessage(connection)
  client.sendCoordinatorMessage(connection, client.coordinatorHelloAckMessage())

  let edit = execCmdEx(shellCommand([parsed.sourceEditDriver, parsed.project]),
    workingDir = parsed.project)
  writeFile(extendedPath(parsed.artifacts / "source-edit-driver.log"), edit.output)
  if edit.exitCode != 0:
    raise newException(ValueError,
      "source edit driver failed with exit code " & $edit.exitCode &
        "\n" & edit.output)

  discard runHcrBuildCycle(parsed.project, parsed.target,
    parsed.artifacts / "reprobuild-build-report.txt")
  requireHcrFile(patchObject, "rebuilt patchable object")
  let newObject = parsed.artifacts / "patchable-generation1.o"
  copyFile(extendedPath(patchObject), extendedPath(newObject))

  let symbolName = "_" & parsed.patchFunction
  let patchBytes = objectFunctionBytes(newObject, symbolName)
  let sourcePath = parsed.project / "src" / "patchable.c"
  let sourceGeneration = HcrSourceGenerationEntry(
    sourcePath: sourcePath,
    generation: 1'u32,
    snapshotDigest: hcrSourceDigest(sourcePath),
    lineTableDigest: byteDigest(patchBytes))
  let objectBytes = readFile(extendedPath(newObject)).bytesOf()
  let plan = directPatchPlanFromBytes(parsed.patchFunction, patchBytes,
    supportProfile = CodetracerHcrSupportProfile,
    snapshotId = "codetracer-hcr-generation-1")
  let request = directPatchRequest(
    patchId = "codetracer-hcr-patch-0001",
    supportProfile = CodetracerHcrSupportProfile,
    changedFunctions = [parsed.patchFunction],
    targetSymbols = [parsed.patchFunction],
    directPatchBytes = patchBytes,
    debugObjectBytes = objectBytes,
    unwindMetadataBytes = minimalAarch64EhFrameTemplate(),
    sourceGenerationMap = [sourceGeneration])
  client.sendCoordinatorMessage(connection,
    client.coordinatorPatchRequestMessage(request))
  while client.session.state == hssPatchRequested:
    discard client.receiveAgentMessage(connection)

  let delivery = HcrCoordinatorDelivery(
    session: client.session,
    transcript: client.transcript,
    patchApplied: client.patchApplied,
    patchFailed: client.patchFailed)
  writeJsonFile(parsed.artifacts / "hcr-coordinator-report.json",
    coordinatorDeliveryJson(delivery))
  writeJsonFile(parsed.artifacts / "agent-protocol-transcript.json",
    transcriptJson(client.transcript))
  writeJsonFile(parsed.artifacts / "patch-bundle-metadata.json", %*{
    "schemaId": "reprobuild.hcr.codetracer-patch-bundle-metadata.v1",
    "supportProfile": CodetracerHcrSupportProfile,
    "patchId": request.patchId,
    "changedFunction": parsed.patchFunction,
    "targetSymbol": parsed.patchFunction,
    "objectSymbol": symbolName,
    "oldObject": oldObject,
    "newObject": newObject,
    "patchByteCount": patchBytes.len,
    "patchDigest": byteDigest(patchBytes),
    "debugObjectDigest": request.debugObjectPayload.digest,
    "unwindMetadataDigest": request.unwindMetadataPayload.digest,
    "sourceGeneration": %*{
      "sourcePath": sourceGeneration.sourcePath,
      "generation": sourceGeneration.generation,
      "snapshotDigest": sourceGeneration.snapshotDigest,
      "lineTableDigest": sourceGeneration.lineTableDigest
    },
    "patchPlan": patchPlanJson(plan)
  })

  if client.patchFailed.isSome:
    stderr.writeLine("repro hcr coordinate: agent patch failed: " &
      client.patchFailed.get().message)
    return 1
  if client.patchApplied.isNone:
    stderr.writeLine("repro hcr coordinate: no patchApplied response")
    return 1
  0

proc runPrivilegedBrokerMode(args: openArray[string]): int =
  ## The hidden `repro --privileged-broker --channel <name> --token
  ## <nonce> [--file-prefix <dir>]` entrypoint (M81 deliverable 3).
  ## The broker is the SAME `repro` binary re-execed; this mode
  ## connects back to the launching parent over the authenticated
  ## RBEB channel and services the closed, typed `PrivilegedOperation`
  ## stream. It is one-shot — it exits when the parent sends `Done`.
  try:
    let parsed = parseBrokerModeArgs(args)
    doAssert parsed.isBrokerMode
    let ctx = FixtureContext(filePrefix: parsed.filePrefix)
    return runBrokerSession(parsed.token, ctx)
  except EElevation as err:
    stderr.writeLine("repro --privileged-broker: " & err.msg)
    return 7
  except CatchableError as err:
    stderr.writeLine("repro --privileged-broker: error: " & err.msg)
    return 7

proc prewarmBuildFileMetadata(info: BuildGraphInspection) =
  if info.actions.len == 0:
    return
  var cache = openActionCache(currentActionCacheRoot() / "action-cache")
  var metadataCache = initFileMetadataCache()
  var probes: seq[HotMetadataProbe] = @[]
  for action in info.actions:
    if action.cacheable and action.dynamicDepsFile.len == 0:
      probes.add(HotMetadataProbe(
        weakFingerprint: action.weakFingerprint,
        policy: action.actionCachePolicy))
  if probes.len == 0:
    return
  let scan = cache.scanHotIndexMetadataInputsUnchanged(probes,
    addr metadataCache)
  if scan.status != hmssUnavailable:
    return

  var records: seq[ActionResultRecord] = @[]
  for action in info.actions:
    if not action.cacheable or action.dynamicDepsFile.len > 0:
      continue
    let record = cache.lookupHotMetadataRecord(action.weakFingerprint,
      action.actionCachePolicy)
    if record.isSome:
      records.add(record.get())
  if records.len > 0:
    discard hotMetadataRecordInputsUnchanged(records, addr metadataCache)

proc prewarmBuildCommand(args: openArray[string]; publicCliPath: string) =
  var target = ""
  var mode = tpmUnspecified
  var workRoot = ""
  var targetWasOmitted = true
  var forceRefresh = false
  var prepareOnly = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i,
        "--tool-provisioning"))
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      workRoot = valueFromFlag(args, i, "--work-root")
    elif arg == "--action-cache-root" or arg.startsWith("--action-cache-root="):
      setActionCacheRootOverride(valueFromFlag(args, i,
        "--action-cache-root"))
    elif arg == "--force-rebuild" or arg == "--rebuild" or arg == "--dry-run":
      forceRefresh = true
    elif arg in ["--daemon", "--progress", "--progress-bars",
        "--write-diagnostics", "--show", "--measure", "--write-report",
        "--log", "--write-benchmark", "--write-stats"]:
      discard valueFromFlag(args, i, arg)
    elif arg == "--no-write-report":
      discard
    elif arg.startsWith("--daemon=") or arg.startsWith("--progress=") or
        arg.startsWith("--progress-bars=") or
        arg.startsWith("--write-diagnostics=") or
        arg.startsWith("--show=") or arg.startsWith("--measure=") or
        arg.startsWith("--write-report=") or
        arg.startsWith("--log=") or arg.startsWith("--write-benchmark=") or
        arg.startsWith("--write-stats=") or
        arg.startsWith("--stats-groups="):
      discard
    elif arg == "--prepare-only":
      prepareOnly = true
    elif arg in ["-v", "--verbose", "-vv", "--very-verbose",
        "--skip-cmake-regeneration", "--no-runquota", "--runquota"]:
      discard
    elif not arg.startsWith("-") and target.len == 0:
      target = arg
      targetWasOmitted = false
    inc i
  if forceRefresh or prepareOnly:
    return
  if target.len == 0:
    target = "."
  let info = prepareBuildGraphInspection(target, mode, publicCliPath,
    selectDefaultAction = targetWasOmitted, workRoot = workRoot,
    forceRefresh = false)
  prewarmBuildFileMetadata(info)

proc installUserDaemonBuildPrewarmer() =
  setUserDaemonBuildPrewarmer(proc(request: UserDaemonBuildRequest) =
    let previousCwd = getCurrentDir()
    var previousEnv: seq[tuple[key: string; value: string; present: bool]] = @[]
    proc setRestorableEnv(key, value: string) =
      previousEnv.add((key: key, value: getEnv(key), present: existsEnv(key)))
      putEnv(key, value)
    try:
      # Defense in depth for direct/in-process callers that bypass protocol
      # serialization. Never install the runner-private ownership marker in
      # the build prewarmer's live environment.
      for item in sanitizeUserDaemonRequestEnvironment(request.environment):
        let split = item.find('=')
        if split < 0:
          continue
        let key = item[0 ..< split]
        let value = item[split + 1 .. ^1]
        setRestorableEnv(key, value)
      # Prewarm is a daemon-internal cache-warming pass, not user-scheduled
      # work, so it must NOT contend for RunQuota leases. Forcing the documented
      # full-bypass switch makes the nested provider-compile `runBuild` here run
      # its actions as plain children instead of through the inline-RunQuota
      # lease/exec path. That path, driven from inside the detached daemon
      # worker, could deadlock: the worker launched a leased compile, the child
      # exited, but the worker never reaped it / never sent LeaseFinished, so the
      # lease stayed `running`, runquotad's connection worker blocked reading the
      # next request, and the attached client blocked reading the build response.
      # Bypassing here both avoids that hang and keeps the prewarm cheap; the
      # subsequent real build reuses the provider-compile artifact this pass
      # writes, so build output and scheduling are unaffected.
      setRestorableEnv("REPROBUILD_NO_RUNQUOTA", "1")
      let providerSession =
        if request.runId.len > 0:
          "daemon-build-" & request.runId
        else:
          "daemon-build-pid-" & $getCurrentProcessId()
      setRestorableEnv(ProviderNimcacheSessionEnv, providerSession)
      if request.workingDir.len > 0:
        setCurrentDir(request.workingDir)
      let cliPath =
        if request.publicCliPath.len > 0: request.publicCliPath
        else: stablePublicCliPath()
      prewarmBuildCommand(request.rawArgs, cliPath)
    finally:
      try:
        setCurrentDir(previousCwd)
      except CatchableError:
        discard
      for item in previousEnv:
        if item.present:
          putEnv(item.key, item.value)
        else:
          delEnv(item.key))

proc installUserDaemonBuildExecutor() =
  setUserDaemonBuildExecutor(proc(request: UserDaemonBuildRequest;
      emit: UserDaemonBuildEmit;
      cancelCheck: UserDaemonBuildCancelCheck): int =
    let previousCwd = getCurrentDir()
    var previousEnv: seq[tuple[key: string; value: string; present: bool]] = @[]
    try:
      # Defense in depth for direct/in-process callers that bypass protocol
      # serialization. The executor environment feeds action fingerprints,
      # cache inputs, and every exec'd action child.
      for item in sanitizeUserDaemonRequestEnvironment(request.environment):
        let split = item.find('=')
        if split < 0:
          continue
        let key = item[0 ..< split]
        let value = item[split + 1 .. ^1]
        previousEnv.add((key: key, value: getEnv(key), present: existsEnv(key)))
        putEnv(key, value)
      previousEnv.add((key: ProviderNimcacheSessionEnv,
        value: getEnv(ProviderNimcacheSessionEnv),
        present: existsEnv(ProviderNimcacheSessionEnv)))
      let providerSession =
        if request.runId.len > 0:
          "daemon-build-" & request.runId
        else:
          "daemon-build-pid-" & $getCurrentProcessId()
      putEnv(ProviderNimcacheSessionEnv, providerSession)
      if request.workingDir.len > 0:
        setCurrentDir(request.workingDir)
      let cliPath =
        if request.publicCliPath.len > 0: request.publicCliPath
        else: stablePublicCliPath()
      proc emitBuildCommandEvent(kind, message, payloadJson: string) =
        if cancelCheck != nil and cancelCheck():
          raise newException(IOError, "build cancelled")
        let eventKind =
          case kind
          of "diagnostic": bekDiagnostic
          else: bekDiagnostic
        emit(eventKind, message, false, 0, "info", payloadJson)
      proc buildCancelRequested(): bool =
        cancelCheck != nil and cancelCheck()
      try:
        result = runBuildCommand(request.rawArgs, cliPath,
          forceDirect = true,
          daemonHosted = true,
          eventSink = emitBuildCommandEvent,
          cancelCheck = buildCancelRequested)
      except BuildTargetAmbiguousError as err:
        # Named-Targets M2: mirror the top-level CLI dispatch arm's
        # ``target_ambiguous`` translation inside the daemon-side
        # executor so the daemon-hosted path produces identical exit
        # code 2 + stderr text. The diagnostic is emitted as a
        # ``bekDiagnostic`` event carrying ``"stream":"stderr"`` in
        # its payload; the client-side ``runDaemonBuild`` event
        # handler routes such events verbatim to stderr. The
        # following ``bekFinished`` is emitted with ``terminal=true``
        # and exit code 2 so the daemon's terminal-emit guard
        # suppresses the generic "daemon-hosted build failed" line
        # that would otherwise tail the diagnostic.
        emit(bekDiagnostic, renderAmbiguousTargetDiagnostic(err[]),
          false, 0, "error",
          "{\"stream\":\"stderr\",\"diagnostic\":\"target_ambiguous\"}")
        emit(bekFinished, "", true, 2, "error",
          "{\"diagnostic\":\"target_ambiguous\"}")
        result = 2
      except BuildTargetUnknownError as err:
        # Named-Targets M2: same translation for the
        # ``unknown_target`` diagnostic. Shared formatter keeps the
        # daemon-hosted and direct-mode emissions byte-identical.
        emit(bekDiagnostic, renderUnknownTargetDiagnostic(err[]),
          false, 0, "error",
          "{\"stream\":\"stderr\",\"diagnostic\":\"unknown_target\"}")
        emit(bekFinished, "", true, 2, "error",
          "{\"diagnostic\":\"unknown_target\"}")
        result = 2
    finally:
      try:
        setCurrentDir(previousCwd)
      except CatchableError:
        discard
      for item in previousEnv:
        if item.present:
          putEnv(item.key, item.value)
        else:
          delEnv(item.key))

proc installUserDaemonWatchExecutor() =
  setUserDaemonWatchExecutor(proc(request: UserDaemonWatchRequest;
      emit: UserDaemonWatchEmit;
      cancelCheck: UserDaemonWatchCancelCheck): int =
    let previousCwd = getCurrentDir()
    var previousEnv: seq[tuple[key: string; value: string; present: bool]] = @[]
    try:
      # Match the build executor: watch cycles may spawn the same actions and
      # must enforce the same private-environment boundary.
      for item in sanitizeUserDaemonRequestEnvironment(request.environment):
        let split = item.find('=')
        if split < 0:
          continue
        let key = item[0 ..< split]
        let value = item[split + 1 .. ^1]
        previousEnv.add((key: key, value: getEnv(key), present: existsEnv(key)))
        putEnv(key, value)
      if request.workingDir.len > 0:
        setCurrentDir(request.workingDir)
      let cliPath =
        if request.publicCliPath.len > 0: request.publicCliPath
        else: stablePublicCliPath()
      proc emitWatchCommandEvent(kind, message, payloadJson: string;
                                 terminal: bool; exitCode: int;
                                 watchedPaths: seq[string];
                                 lastResult: string) =
        if cancelCheck != nil and cancelCheck():
          raise newException(IOError, "watch cancelled")
        let eventKind =
          if kind == "accepted":
            bekAccepted
          else:
            bekDiagnostic
        emit(eventKind, message, false, exitCode, "info", payloadJson,
          watchedPaths, lastResult)
      proc watchCancelRequested(): bool =
        cancelCheck != nil and cancelCheck()
      try:
        result = runWatchCommand(request.rawArgs, cliPath,
          forceDirect = true,
          daemonHosted = true,
          eventSink = emitWatchCommandEvent,
          cancelCheck = watchCancelRequested)
      except BuildTargetAmbiguousError as err:
        # Named-Targets M3: mirror the M2 ``installUserDaemonBuildExecutor``
        # arm so daemon-hosted watch produces the same exit code 2 +
        # stderr text as the direct-mode CLI dispatch. The diagnostic is
        # emitted as a ``bekDiagnostic`` event with ``"stream":"stderr"``;
        # the client-side ``runDaemonWatch`` event renderer routes it to
        # stderr verbatim. The terminal ``bekFinished`` carries exit code
        # 2 so the daemon's terminal-emit guard suppresses the generic
        # "daemon-hosted watch failed" status line.
        emit(bekDiagnostic, renderAmbiguousTargetDiagnostic(err[]),
          false, 0, "error",
          "{\"stream\":\"stderr\",\"diagnostic\":\"target_ambiguous\"}",
          @[], "")
        emit(bekFinished, "", true, 2, "error",
          "{\"diagnostic\":\"target_ambiguous\"}", @[], "")
        result = 2
      except BuildTargetUnknownError as err:
        # Named-Targets M3: same translation for ``unknown_target``. The
        # shared ``renderUnknownTargetDiagnostic`` keeps the daemon-hosted
        # and direct-mode emissions byte-identical with ``repro build``.
        emit(bekDiagnostic, renderUnknownTargetDiagnostic(err[]),
          false, 0, "error",
          "{\"stream\":\"stderr\",\"diagnostic\":\"unknown_target\"}",
          @[], "")
        emit(bekFinished, "", true, 2, "error",
          "{\"diagnostic\":\"unknown_target\"}", @[], "")
        result = 2
    finally:
      try:
        setCurrentDir(previousCwd)
      except CatchableError:
        discard
      for item in previousEnv:
        if item.present:
          putEnv(item.key, item.value)
        else:
          delEnv(item.key))

# ---- M9: `repro workspace init` -------------------------------------------
#
# Drive the M6 single-project resolver (or M7 variant composer, or M8
# manifest-layer composer when ``.repo/workspace.toml`` is present) into
# a ``bakWorkspaceVcs.clone`` build plan that materialises missing repos.
# Existing repos are inspected via the M2 observation-only
# ``headShaQuery`` and classified as ``up-to-date`` or ``divergence``;
# the milestone deliberately does NOT auto-modify divergent checkouts —
# the user resolves them by hand and re-runs ``repro workspace init``
# (or, once M10 lands, ``repro workspace sync``).

type
  MaterializedFileEntry* = object
    ## RA-18 — one copyfile/linkfile dest materialized at the workspace
    ## root after a repo's checkout succeeds. Emitted by both
    ## ``executeWorkspaceInit`` and ``executeWorkspaceSync``.
    repo*: string        ## repo ``path`` that declared the directive
    kind*: string        ## "copyfile" | "linkfile"
    src*: string         ## repo-relative source
    dest*: string        ## workspace-root-relative destination
    status*: string      ## "materialized" | "failed"
    diagnostic*: string  ## empty on success

  WorkspaceInitClonedEntry* = object
    name*: string
    path*: string
    remote*: string
    revision*: string

  WorkspaceInitUpToDateEntry* = object
    name*: string
    path*: string
    headSha*: string

  WorkspaceInitDivergenceEntry* = object
    name*: string
    path*: string
    expected*: string
    observed*: string

  WorkspaceInitSkippedLayerEntry* = object
    ## M25 — one per manifest layer that was dropped because the
    ## operator passed ``--allow-missing-layers`` and the layer's URL
    ## was unreachable. The four fields mirror
    ## ``repro_workspace_manifests.SkippedLayer``. ``visibility`` is
    ## the canonical lowercase tier label ("public" / "org" / "team" /
    ## "private") so the JSON consumer can filter on it without
    ## reinventing the enum string mapping.
    index*: int
    provenance*: string
    visibility*: string
    diagnostic*: string

  TrustEntry* = object
    ## RA-12 — one ``.envrc`` directory the auto-trust pass acted on.
    dir*: string                ## absolute directory holding the ``.envrc``
    status*: string             ## "trusted" | "failed" — the outcome tag
    diagnostic*: string         ## populated when ``status == "failed"``

  TrustReport* = object
    ## RA-12 — structured outcome of one ``autoTrustEnvrcFiles`` pass.
    ##
    ## ``activatorAvailable`` is false when no activator (direnv) could be
    ## resolved on PATH / via ``REPRO_DIRENV_BIN`` — in that case the whole
    ## pass is skipped (``entries`` is empty and ``skipReason`` explains it).
    activatorAvailable*: bool
    activatorBin*: string       ## resolved activator path (empty when absent)
    skipReason*: string         ## non-empty when the pass was skipped
    entries*: seq[TrustEntry]

  WorkspaceInitReport* = object
    ## Structured outcome of one ``repro workspace init`` invocation.
    ## ``project`` carries the ``ResolvedProject.projectName`` (the
    ## variant's or project's resolved name); ``workspaceRoot`` is the
    ## absolute path of the directory containing ``.repo/``. The three
    ## per-repo lists are emitted both as stdout text lines and as the
    ## ``.repro/build/reports/init-report.json`` machine-readable artifact.
    ##
    ## ``skippedLayers`` (M25) is the list of manifest layers the
    ## composer dropped because the operator passed
    ## ``--allow-missing-layers`` and the layer's URL was unreachable.
    ## A non-empty list does NOT raise the exit code on its own — the
    ## operator opted into the skip explicitly — but downstream
    ## inspection can tell which part of the workspace is missing.
    project*: string
    workspaceRoot*: string
    cloned*: seq[WorkspaceInitClonedEntry]
    upToDate*: seq[WorkspaceInitUpToDateEntry]
    divergences*: seq[WorkspaceInitDivergenceEntry]
    skippedLayers*: seq[WorkspaceInitSkippedLayerEntry]
    materialized*: seq[MaterializedFileEntry]
      ## RA-18 — copyfile/linkfile dest paths materialized post-checkout.
    autoTrust*: TrustReport
      ## RA-12 — outcome of the post-clone shell-hook (.envrc) auto-trust
      ## pass over the workspace/host roots and each checked-out repo.

  WorkspaceInitOutcome* = object
    ## Internal aggregate the dispatcher consumes to compute the exit
    ## code. ``cloneFailures > 0`` raises the exit code to 1; any
    ## ``divergences`` (with no clone failure) raises it to 2.
    report*: WorkspaceInitReport
    cloneFailures*: int

proc toJsonNode*(report: WorkspaceInitReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  var cloned = newJArray()
  for entry in report.cloned:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["remote"] = %entry.remote
    obj["revision"] = %entry.revision
    cloned.add(obj)
  result["cloned"] = cloned
  var upToDate = newJArray()
  for entry in report.upToDate:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["headSha"] = %entry.headSha
    upToDate.add(obj)
  result["upToDate"] = upToDate
  var divergences = newJArray()
  for entry in report.divergences:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["expected"] = %entry.expected
    obj["observed"] = %entry.observed
    divergences.add(obj)
  result["divergences"] = divergences
  var skipped = newJArray()
  for entry in report.skippedLayers:
    var obj = newJObject()
    obj["index"] = %entry.index
    obj["provenance"] = %entry.provenance
    obj["visibility"] = %entry.visibility
    obj["diagnostic"] = %entry.diagnostic
    skipped.add(obj)
  result["skippedLayers"] = skipped
  var materialized = newJArray()
  for entry in report.materialized:
    var obj = newJObject()
    obj["repo"] = %entry.repo
    obj["kind"] = %entry.kind
    obj["src"] = %entry.src
    obj["dest"] = %entry.dest
    obj["status"] = %entry.status
    obj["diagnostic"] = %entry.diagnostic
    materialized.add(obj)
  result["materialized"] = materialized
  # RA-12 — the shell-hook (.envrc) auto-trust pass.
  var autoTrust = newJObject()
  autoTrust["activatorAvailable"] = %report.autoTrust.activatorAvailable
  autoTrust["activatorBin"] = %report.autoTrust.activatorBin
  autoTrust["skipReason"] = %report.autoTrust.skipReason
  var trusted = newJArray()
  for entry in report.autoTrust.entries:
    var obj = newJObject()
    obj["dir"] = %entry.dir
    obj["status"] = %entry.status
    obj["diagnostic"] = %entry.diagnostic
    trusted.add(obj)
  autoTrust["entries"] = trusted
  result["autoTrust"] = autoTrust

proc renderTrustReportLines*(prefix: string; report: TrustReport): seq[string] =
  ## RA-12 — human-readable lines for the shell-hook auto-trust pass,
  ## shared by both ``init`` and ``pull``.
  if not report.activatorAvailable:
    result.add(prefix & ": shell-hook auto-trust skipped — " &
      report.skipReason)
    return
  for entry in report.entries:
    if entry.status == "trusted":
      result.add(prefix & ": trusted shell hook (.envrc) at " & entry.dir)
    else:
      result.add(prefix & ": shell-hook trust FAILED at " & entry.dir &
        " — " & entry.diagnostic & " (continuing)")

proc renderInitTextLines*(report: WorkspaceInitReport): seq[string] =
  for entry in report.skippedLayers:
    result.add("workspace init: skipped manifest layer " &
      entry.provenance & " (visibility=" & entry.visibility &
      ") — " & entry.diagnostic)
  for entry in report.cloned:
    result.add("workspace init: cloned " & entry.path & " from " &
      entry.remote & " @ " & entry.revision)
  for entry in report.upToDate:
    result.add("workspace init: up-to-date " & entry.path)
  for entry in report.divergences:
    result.add("workspace init: divergence " & entry.path &
      " expected=" & entry.expected &
      " observed=" & entry.observed)
  for line in renderTrustReportLines("workspace init", report.autoTrust):
    result.add(line)

type
  WorkspaceInitArgs = object
    projectName: string
    workspaceRoot: string
    toolProvisioning: ToolProvisioningMode
    allowMissingLayers: bool
      ## M25 — when set, the composer downgrades unreachable URL-backed
      ## manifest layers from a fatal diagnostic to a structured
      ## ``WorkspaceInitSkippedLayerEntry``. Used by public-only users
      ## of a mixed workspace so they can still init the public subset.
    manifestUrl: string
      ## RA-11 — bootstrap manifest URL. When set AND the workspace has
      ## no ``.repo/manifests`` checkout yet, ``init`` clones the manifest
      ## repo into the tool-managed bootstrap manifest cache
      ## (``$XDG_CACHE_HOME/reprobuild/manifests`` / ``REPRO_MANIFEST_CACHE``
      ## override; keyed by source URL) and materialises ``.repo/manifests``
      ## from it, so ``init`` works OUTSIDE an existing workspace.
    manifestBranch: string
      ## RA-11 — optional branch for the bootstrap manifest clone.
    privateManifestUrl: string
      ## RA-11 — optional private companion manifest URL. Cloned into the
      ## PARALLEL private cache (``…/manifests-private``) so a private
      ## companion never shares a slug namespace with the public manifest.
    manifestUrlExplicit: bool
      ## RA-8 — set when ``--manifest-url`` was passed on the command line.
      ## The resolution order treats an explicit flag as the highest
      ## precedence source; without it the manifest URL/branch are resolved
      ## from the host bootstrap config and then the host repo's ``origin``.
    defaultProjects: seq[string]
      ## RA-8 — the host bootstrap config's ``[projects] default`` set. Used
      ## to fill the project-to-init when the user did not pass an explicit
      ## positional project name.
    additionalProjects: seq[string]
      ## PS-6 — projects to materialize ALONGSIDE ``projectName``, unioned into
      ## one participating repo set.
      ##
      ## An interactive ``repro workspace init <project>`` names exactly one
      ## project on purpose (see ``resolveWorkspaceInitProject``), so this stays
      ## empty there. It is set by callers that are reproducing an EXISTING
      ## workspace's membership rather than starting a fresh one — the fork
      ## form of ``repro branch``, whose new workspace must contain the same
      ## repos as the workspace it was cut from. Without it the fork clones the
      ## primary project only and every repo belonging to the other enabled
      ## projects has no checkout to branch.
    verifySpec: ManifestVerifySpec
      ## RA-17 — manifest provenance trust anchor resolved from the host
      ## bootstrap config's ``[manifest] revision`` + ``[verify]`` table. When
      ## ``isVerificationActive`` is false the verifier is a no-op and existing
      ## init flows are unaffected; when ``require_signature`` (or a revision
      ## pin) is configured, ``bootstrapManifestCache`` verifies the manifest
      ## source's signature/pin and FAILS CLOSED on any mismatch.
    json: bool
      ## ``--json`` — echo the structured init report to stdout (same
      ## document that ``--write-report`` persists).
    report: ReportSpec
      ## Opt-in ``--write-report[=PATH]`` artifact.

  WorkspaceInitResolution = object
    project: ResolvedProject
    skippedLayers: seq[WorkspaceInitSkippedLayerEntry]

# ---- RA-31: `repro workspace init <url>` — cold-start one-command join -------
#
# The cold-start entry point clones the org ROOT workspace repo (convention
# ``<org>/repro-workspace``), reads its host bootstrap config, and syncs the
# workspace into a NEW NAMED directory (defaulting to the org name) so init
# never touches the current or any ancestor directory.
#
# ``<url>`` resolves three ways to the root-repo URL:
#   - a full HTTPS/git/SSH URL → used verbatim;
#   - a ``host:org`` shorthand (``github:metacraft-labs``) → mapped through a
#     known host-alias base URL + the ``repro-workspace`` repo-name convention;
#   - a bare org (``metacraft-labs``) → resolved via the DEFAULT VCS HOST from
#     system/user config, then ``<default-host>/<org>/repro-workspace``.

const
  rootWorkspaceRepoName = "repro-workspace"
    ## RA-31 — the convention repo name carrying the host bootstrap config.
  defaultVcsHostAlias = "github"
    ## RA-31 — GitHub is the initial default VCS host when system/user config
    ## sets none. Documented in CLI/workspace.md § "Default VCS host".

proc builtinHostAliasBase(host: string): string =
  ## Map a known VCS-host alias to its HTTPS base URL (no trailing slash).
  ## At least GitHub/GitLab/Bitbucket/Codeberg/sourcehut are grounded here;
  ## an unknown alias returns the empty string and the caller fails loud.
  case host.toLowerAscii()
  of "github": "https://github.com"
  of "gitlab": "https://gitlab.com"
  of "bitbucket": "https://bitbucket.org"
  of "codeberg": "https://codeberg.org"
  of "sourcehut", "srht": "https://git.sr.ht"
  else: ""

proc hostAliasBase(host: string;
                   env: proc(name: string): string): string =
  ## Resolve a host alias (``github``, ``gitlab``, …) to its base URL. A
  ## per-host env override (``REPRO_VCS_HOST_BASE_<HOST>``, uppercased) wins
  ## over the built-in table — this is the hermetic test seam: a test points
  ## ``github:`` / the default host at a local ``file://…/hosts/<host>`` dir.
  let overrideKey = "REPRO_VCS_HOST_BASE_" & host.toUpperAscii()
  let override = env(overrideKey)
  if override.len > 0:
    return override.strip(leading = false, chars = {'/'})
  builtinHostAliasBase(host)

proc readDefaultVcsHostFromConfig(env: proc(name: string): string): string =
  ## RA-31 — read the DEFAULT VCS HOST setting from system/user config.
  ## Resolution order (highest precedence first):
  ##   1. ``REPRO_DEFAULT_VCS_HOST`` env override (also the hermetic test seam);
  ##   2. user config ``$XDG_CONFIG_HOME/reprobuild/config.toml`` (else
  ##      ``$HOME/.config/reprobuild/config.toml``);
  ##   3. system config ``/etc/repro/config.toml``.
  ## The setting is the single key ``default_vcs_host = "<alias>"`` under a
  ## ``[vcs]`` table. Returns the empty string when unset (the caller then
  ## falls back to the built-in GitHub default).
  let envOverride = env("REPRO_DEFAULT_VCS_HOST")
  if envOverride.len > 0:
    return envOverride.strip()

  proc readKey(path: string): string =
    if not fileExists(path):
      return ""
    # A deliberately tiny line scanner: we only need ``default_vcs_host``
    # under ``[vcs]`` and want zero coupling to the workspace TOML schema
    # machinery (this is plain user/system config, not a manifest). Lines
    # are ``key = "value"`` / ``key = value`` with ``#`` comments.
    var inVcsTable = false
    for rawLine in readFile(path).splitLines():
      var line = rawLine.strip()
      let hashAt = line.find('#')
      if hashAt >= 0:
        line = line[0 ..< hashAt].strip()
      if line.len == 0:
        continue
      if line.startsWith("[") and line.endsWith("]"):
        inVcsTable = line[1 ..< ^1].strip().toLowerAscii() == "vcs"
        continue
      if not inVcsTable:
        continue
      let eq = line.find('=')
      if eq < 0:
        continue
      let key = line[0 ..< eq].strip()
      if key != "default_vcs_host":
        continue
      var value = line[eq + 1 .. ^1].strip()
      if value.len >= 2 and value[0] == '"' and value[^1] == '"':
        value = value[1 ..< ^1]
      return value.strip()
    ""

  let xdg = env("XDG_CONFIG_HOME")
  let userBase =
    if xdg.len > 0: xdg
    else: env("HOME") / ".config"
  let userConfig = userBase / "reprobuild" / "config.toml"
  let fromUser = readKey(userConfig)
  if fromUser.len > 0:
    return fromUser
  readKey("/etc/repro" / "config.toml")

proc looksLikeFullVcsUrl(spec: string): bool =
  ## A FULL URL is used verbatim. We recognise the scheme-bearing forms
  ## (``https://``, ``http://``, ``git://``, ``ssh://``, ``file://``) and the
  ## scp-like SSH form (``git@host:org/repo``), which carries a ``@`` before
  ## the first ``:``. Everything else is a shorthand (``host:org``) or a bare
  ## org and is resolved through the conventions below.
  let lower = spec.toLowerAscii()
  if lower.startsWith("https://") or lower.startsWith("http://") or
      lower.startsWith("git://") or lower.startsWith("ssh://") or
      lower.startsWith("file://"):
    return true
  # scp-like ssh: ``user@host:path`` — a ``@`` appearing before the ``:``.
  let colon = spec.find(':')
  let at = spec.find('@')
  if at >= 0 and colon > at:
    return true
  false

proc orgNameFromRootUrl(url: string): string =
  ## Derive the org name (used as the default local-path directory) from a
  ## resolved root-repo URL of the convention ``<base>/<org>/repro-workspace``.
  ## Strips any ``.git`` suffix and a trailing slash, then takes the path
  ## segment immediately before the ``repro-workspace`` repo name.
  var trimmed = url.strip(leading = false, chars = {'/'})
  if trimmed.toLowerAscii().endsWith(".git"):
    trimmed = trimmed[0 ..< ^4]
  # Split on both separators a URL/scp path may use.
  var segments: seq[string]
  for piece in trimmed.replace(':', '/').split('/'):
    if piece.len > 0:
      segments.add(piece)
  if segments.len >= 2 and
      segments[^1].toLowerAscii() == rootWorkspaceRepoName:
    return segments[^2]
  if segments.len >= 1:
    return segments[^1]
  ""

type
  RootRepoResolution = object
    ## Outcome of RA-31 ``<url>`` resolution.
    url: string      ## the resolved org root-repo URL (clone target)
    org: string      ## the derived org name (default local-path)
    form: string     ## "full-url" | "host:org" | "bare-org" (for diagnostics)

proc resolveOrgRootRepoUrl(spec: string;
                           env: proc(name: string): string):
    RootRepoResolution =
  ## RA-31 — resolve a ``<url>`` argument to the org ROOT workspace repo URL.
  ## Three forms (most explicit to most terse):
  ##   - a full HTTPS/git/SSH/file URL → used verbatim;
  ##   - ``host:org`` → ``<host-base>/<org>/repro-workspace``;
  ##   - bare ``org`` → ``<default-host-base>/<org>/repro-workspace``.
  ## Raises ``ValueError`` with a clear message when a host alias is unknown
  ## or the spec is empty.
  let trimmed = spec.strip()
  if trimmed.len == 0:
    raise newException(ValueError,
      "`repro workspace init` requires a <url> (a full repo URL, a " &
        "`host:org` shorthand, or a bare org name)")

  if looksLikeFullVcsUrl(trimmed):
    result.url = trimmed
    result.org = orgNameFromRootUrl(trimmed)
    result.form = "full-url"
    return

  # ``host:org`` shorthand vs bare org. A single ``:`` with non-empty sides
  # and no path separator on the left is the shorthand; otherwise treat the
  # whole token as a bare org resolved through the default host.
  let colon = trimmed.find(':')
  if colon > 0 and colon < trimmed.high and '/' notin trimmed[0 ..< colon]:
    let host = trimmed[0 ..< colon]
    let org = trimmed[colon + 1 .. ^1].strip(chars = {'/'})
    let base = hostAliasBase(host, env)
    if base.len == 0:
      raise newException(ValueError,
        "unknown VCS host alias '" & host & "' in `repro workspace init " &
          trimmed & "`: pass a full repo URL, set " &
          "`REPRO_VCS_HOST_BASE_" & host.toUpperAscii() & "`, or use a " &
          "known alias (github, gitlab, bitbucket, codeberg, sourcehut)")
    if org.len == 0:
      raise newException(ValueError,
        "missing org in `host:org` shorthand '" & trimmed & "'")
    result.url = base & "/" & org & "/" & rootWorkspaceRepoName
    result.org = org
    result.form = "host:org"
    return

  # Bare org → default VCS host.
  let org = trimmed.strip(chars = {'/'})
  if org.len == 0:
    raise newException(ValueError,
      "empty org name in `repro workspace init " & spec & "`")
  var host = readDefaultVcsHostFromConfig(env)
  if host.len == 0:
    host = defaultVcsHostAlias
  let base = hostAliasBase(host, env)
  if base.len == 0:
    raise newException(ValueError,
      "default VCS host '" & host & "' is not a known alias: set " &
        "`default_vcs_host` in your reprobuild config to a known host " &
        "(github, gitlab, bitbucket, codeberg, sourcehut) or " &
        "`REPRO_VCS_HOST_BASE_" & host.toUpperAscii() & "`")
  result.url = base & "/" & org & "/" & rootWorkspaceRepoName
  result.org = org
  result.form = "bare-org"

proc sysEnv(name: string): string = getEnv(name)
  ## Default environment lookup for RA-31 resolution (overridable in tests).

proc parseWorkspaceInitArgs(args: openArray[string]): WorkspaceInitArgs =
  ## Parse ``repro workspace init`` argv. The single positional is the
  ## project-or-variant bare name. Optional flags:
  ##   ``--workspace-root=PATH``
  ##   ``--tool-provisioning=path|nix|tarball|scoop``
  ##   ``--allow-missing-layers`` (M25)
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  result.allowMissingLayers = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--allow-missing-layers":
      # M25 — opt-in flag. Public-only users pass this when a workspace
      # lists a private manifest layer they cannot fetch; the composer
      # drops the unreachable layer and the init proceeds with the
      # public subset.
      result.allowMissingLayers = true
    elif arg == "--manifest-url" or arg.startsWith("--manifest-url="):
      # RA-11 — bootstrap manifest URL (init outside an existing
      # workspace). Clones the manifest repo into the bootstrap cache.
      # RA-8 — an explicit flag is the highest-precedence source in the
      # manifest resolution order.
      result.manifestUrl = valueFromFlag(args, i, "--manifest-url")
      result.manifestUrlExplicit = true
    elif arg == "--manifest-branch" or arg.startsWith("--manifest-branch="):
      result.manifestBranch = valueFromFlag(args, i, "--manifest-branch")
    elif arg == "--private-manifest-url" or
        arg.startsWith("--private-manifest-url="):
      # RA-11 — private companion manifest, cloned into the parallel
      # private cache.
      result.privateManifestUrl = valueFromFlag(args, i,
        "--private-manifest-url")
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace init` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace init`: " & arg)
    inc i
  # RA-8 — the positional project name is OPTIONAL: when omitted, the
  # project-to-init is taken from the host bootstrap config's
  # ``[projects] default`` (resolved later in ``resolveBootstrapConfig``).
  # ``executeWorkspaceInit`` raises a clear error if neither a positional
  # nor a config default resolves a project name.
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc visibilityLabel(v: WorkspaceVisibility): string =
  ## Lowercase tier label used in the structured init report so the
  ## downstream JSON consumer can filter on visibility without having
  ## to know the enum's stringification.
  case v
  of wvPublic: "public"
  of wvOrg: "org"
  of wvTeam: "team"
  of wvPersonal: "private"

proc resolveWorkspaceInitProject(parsed: WorkspaceInitArgs):
    WorkspaceInitResolution =
  ## Pick the right resolver / composer entry point. The composer wins
  ## when ``<workspaceRoot>/.repo/workspace.toml`` declares at least one
  ## ``[[manifest]]`` layer (M8 semantics); otherwise we look up the
  ## named project / variant under ``<workspaceRoot>/.repo/manifests/``
  ## (M6 / M7 semantics). A metadata-only workspace.toml (M13 — written
  ## by single-project init to record the active branch) routes to the
  ## single-project path because the composer requires manifest layers.
  ## A missing name in either place surfaces as a structured
  ## ``ValueError`` naming both candidate paths the user should look at.
  ##
  ## When ``parsed.allowMissingLayers`` is set (M25), the compositional
  ## path uses the extended composer entry point so an unreachable
  ## URL-backed layer is dropped and reported back to the caller rather
  ## than aborting the whole init.
  # PS-6 — union in the caller-supplied extra projects. Applied to BOTH
  # resolver paths so "materialize this exact membership" means the same thing
  # in a compositional and a single-project workspace.
  proc withAdditional(primary: ResolvedProject): ResolvedProject =
    var extra: seq[string]
    for name in parsed.additionalProjects:
      if name.len > 0 and name != primary.projectName and name notin extra:
        extra.add(name)
    if extra.len == 0: primary
    else: unionProjectSet(parsed.workspaceRoot, primary, extra)
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    let options = ComposeOptions(
      skipInaccessibleLayers: parsed.allowMissingLayers)
    let composed = composeManifestLayersFromFileWithOptions(
      workspaceToml, options)
    # PS-2 — init restores the WHOLE workspace, so a recorded project set is
    # materialized in full rather than just its primary project.
    result.project = withAdditional(extendWithActiveProjectSet(
      parsed.workspaceRoot, composed.project))
    for sl in composed.skippedLayers:
      result.skippedLayers.add(WorkspaceInitSkippedLayerEntry(
        index: sl.index,
        provenance: sl.provenance,
        visibility: visibilityLabel(sl.visibility),
        diagnostic: sl.diagnostic))
    return
  let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
  let projectFile = manifestsRoot / "projects" /
    (parsed.projectName & ".toml")
  let variantFile = manifestsRoot / "variants" /
    (parsed.projectName & ".toml")
  # An EXPLICIT ``repro workspace init <project>`` names one project and
  # initializes exactly that one; the active project set is materialized by
  # ``repro sync`` / ``repro workspace enable`` instead. (The
  # compositional branch above has no explicit-name semantics — membership
  # there comes from workspace.toml — so it does extend.) ``additionalProjects``
  # is the caller saying "this membership, explicitly", which is not the same
  # as inferring one, so it applies here too.
  if fileExists(projectFile):
    result.project = withAdditional(resolveProject(projectFile))
    return
  if fileExists(variantFile):
    result.project = withAdditional(resolveVariant(variantFile))
    return
  raise newException(ValueError,
    "no project or variant named '" & parsed.projectName &
      "' found under '" & manifestsRoot &
      "' (looked for '" & projectFile & "' and '" & variantFile & "')")

proc localHeadOrEmpty(identity: GitToolIdentity; repoPath: string): string =
  ## Best-effort HEAD-SHA query. A failed observation returns the empty
  ## string so the dispatcher can still emit a structured divergence
  ## diagnostic (with ``observed=<empty>``) rather than abort the run.
  let res = queryGitState(headShaQuery(repoPath), identity)
  if res.status == gqsOk:
    res.headSha
  else:
    ""

proc revParse(identity: GitToolIdentity;
              repoPath, refSpec: string): string =
  ## Run ``git -C <repo> rev-parse <ref>`` and return the resolved SHA.
  ## Returns the empty string on failure. The divergence check uses
  ## this both for the local branch tip AND the remote-tracking branch
  ## (typically ``origin/<branch>``) so a local checkout that has
  ## diverged from the manifest's pinned remote tip surfaces correctly.
  if refSpec.len == 0:
    return ""
  let res = execCmdEx(
    quoteShell(identity.binaryPath) & " -C " & quoteShell(repoPath) &
      " rev-parse " & quoteShell(refSpec),
    options = {poStdErrToStdOut, poUsePath},
    env = scrubbedGitRepositoryEnv())
  if res.exitCode == 0:
    res.output.strip()
  else:
    ""

type
  GitOperationState* = enum
    ## Whether a MULTI-STEP git operation is currently in flight in a
    ## checkout. The managed `post-checkout` / `post-commit` / `post-merge`
    ## hooks fire in the middle of those operations, and anything they do
    ## there is done to somebody else's half-finished working tree.
    gosIdle             ## no operation in flight; the hook owns this moment
    gosInProgress       ## git is mid-operation; the hook must stand down
    gosIndeterminate    ## the question could not be answered at all

  GitOperationProbe* = object
    state*: GitOperationState
    marker*: string      ## which state path proved it (``gosInProgress``)
    diagnostic*: string  ## why the probe failed (``gosIndeterminate``)

# `MERGE_HEAD` and `REVERT_HEAD` are DELIBERATELY ABSENT from the set below,
# on measurement rather than taste. Both are git's own in-progress markers and
# both were tried; on git 2.50 git clears them BEFORE it invokes either hook,
# in every path they can be reached from:
#   * conflicted merge, then `git checkout -f <branch>` — `post-checkout`
#     fires with `MERGE_HEAD` already gone;
#   * conflicted merge, then `git commit` — likewise for `post-commit`;
#   * conflicted `git revert`, then `git revert --continue` — `post-commit`
#     fires with `REVERT_HEAD` already gone.
# A name git deletes before it calls you is not a discriminator; it is a
# branch no test can reach, which is a branch that rots. If a later git keeps
# them alive across the hook, the case that proves it comes first.
const InFlightGitStatePaths* = [
  # `git rebase` (merge/interactive backend, the default since 2.26) and
  # `git rebase -r`. THE marker for the reported defect.
  "rebase-merge",
  # `git rebase --apply` (the am backend) and `git am`. A separate directory
  # from the above — neither name covers both rebase backends. Note it does
  # NOT cover that backend's exposed moment: measured, `--apply` rewinds HEAD
  # and fires `post-checkout` BEFORE creating this directory, which is what
  # the reflog discriminator below exists for.
  "rebase-apply",
  # A pick in flight. Observed present at `post-commit` for every commit the
  # merge-backend rebase replays, alongside `rebase-merge`.
  "CHERRY_PICK_HEAD",
  # A multi-commit `git cherry-pick A..B` / `git revert`. Observed live: the
  # post-commit hook fires for every picked commit with `sequencer` present
  # and `CHERRY_PICK_HEAD` absent, so it is not redundant with the name above.
  "sequencer",
  # `git bisect`, which checks out a detached commit per step. Reattaching a
  # branch here destroys the bisect exactly the way it destroys a rebase.
  "BISECT_LOG",
]

# The SECOND discriminator, and it is not redundant with the state paths.
#
# Measured, not assumed: `git rebase --apply` (the am backend) rewinds HEAD
# onto the upstream and fires `post-checkout` — detached, flag `1` — BEFORE it
# creates `rebase-apply`. At that instant not one of the state paths above
# exists, and a state-path-only probe answers "idle" for a rebase that has
# already started. Reattaching a branch there is the same corruption as in the
# merge backend.
#
# What git does have at that instant is the reflog entry it just wrote for
# HEAD: `rebase (start): checkout main`, where an ordinary checkout writes
# `checkout: moving from X to Y`. That is git's own record of WHY HEAD moved,
# which is precisely the question.
#
# Deliberately only these two actions. `merge` is excluded: a plain
# `git merge` writes a `merge` reflog entry and then fires `post-merge`, and
# standing down on it would disable that hook entirely.
const InFlightGitReflogActions* = ["rebase", "am"]

proc reflogActionSuggestsOperation*(subject: string): bool =
  ## Does this HEAD reflog subject name an operation that was in flight when
  ## the hook fired? The subject's shape is ``<action>: <detail>``, with the
  ## action optionally carrying a parenthetical stage (``rebase (start)``,
  ## ``rebase -i (start)``). Only the first word is matched, so every spelling
  ## of a rebase collapses onto ``rebase``.
  let head = subject.strip()
  if head.len == 0:
    return false
  let colon = head.find(':')
  let action = (if colon >= 0: head[0 ..< colon] else: head).strip()
  var firstWord = action
  let space = action.find(' ')
  if space >= 0:
    firstWord = action[0 ..< space]
  firstWord in InFlightGitReflogActions

proc probeGitOperationInProgress*(identity: GitToolIdentity;
                                  repoPath: string): GitOperationProbe =
  ## Is git in the middle of a multi-step operation in this checkout?
  ##
  ## Every path is resolved with ``git rev-parse --git-path`` rather than
  ## by gluing the name onto ``<repo>/.git``. That is not defensive
  ## politeness — in a LINKED WORKTREE ``<repo>/.git`` is a FILE, so
  ## ``<repo>/.git/rebase-merge`` can never exist and a naive test is
  ## unconditionally false there; the real state lives at
  ## ``<common-dir>/worktrees/<name>/rebase-merge``, and a test against the
  ## MAIN checkout's ``.git`` misses it too. ``--git-path`` knows which of
  ## these names are per-worktree and returns the right one.
  ##
  ## One subprocess for the whole set: ``rev-parse`` accepts repeated
  ## ``--git-path`` and answers one line each, and this runs on every commit
  ## and every checkout in every participating repo.
  ##
  ## A probe that cannot answer returns ``gosIndeterminate`` — never
  ## ``gosIdle``. "I could not tell" and "nothing is happening" have opposite
  ## consequences for a caller that is deciding whether to touch refs.
  if repoPath.len == 0:
    result.state = gosIndeterminate
    result.diagnostic = "no repository path was supplied"
    return
  var command = quoteShell(identity.binaryPath) & " -C " &
    quoteShell(repoPath) & " rev-parse"
  for name in InFlightGitStatePaths:
    command.add(" --git-path " & quoteShell(name))
  var res: tuple[output: string; exitCode: int]
  try:
    res = execCmdEx(command, options = {poStdErrToStdOut, poUsePath},
      env = scrubbedGitRepositoryEnv())
  except CatchableError as err:
    result.state = gosIndeterminate
    result.diagnostic = "`git rev-parse --git-path` could not be run in " &
      repoPath & ": " & err.msg
    return
  if res.exitCode != 0:
    result.state = gosIndeterminate
    result.diagnostic = "`git rev-parse --git-path` failed in " & repoPath &
      " (exit " & $res.exitCode & "): " & res.output.strip()
    return
  var lines: seq[string]
  for raw in res.output.splitLines():
    let line = raw.strip()
    if line.len > 0:
      lines.add(line)
  if lines.len != InFlightGitStatePaths.len:
    # A `git` that answered a different number of paths than it was asked
    # about is a `git` whose answers cannot be mapped back onto the names.
    result.state = gosIndeterminate
    result.diagnostic = "`git rev-parse --git-path` in " & repoPath &
      " answered " & $lines.len & " path(s) for " &
      $InFlightGitStatePaths.len & " name(s)"
    return
  for i, name in InFlightGitStatePaths:
    let resolved =
      if isAbsolute(lines[i]): lines[i]
      else: repoPath / lines[i]
    if fileExists(resolved) or dirExists(resolved):
      result.state = gosInProgress
      result.marker = name
      return

  # No state directory — which does NOT yet mean idle. See
  # ``InFlightGitReflogActions``: the am-backend rebase's rewind fires this
  # hook before its state directory exists.
  #
  # A reflog that cannot be read is NOT indeterminate. An unborn HEAD (a
  # fresh `git init`, or a clone of an empty repository — both of which fire
  # `post-checkout`) exits 128 here, and a repo with `core.logAllRefUpdates`
  # off exits 0 with nothing. Both are ordinary, answerable states in which
  # git simply recorded no action, so absence of a reflog is absence of THIS
  # signal, not absence of an answer; the state paths above already gave one.
  var reflog: tuple[output: string; exitCode: int]
  try:
    reflog = execCmdEx(
      quoteShell(identity.binaryPath) & " -C " & quoteShell(repoPath) &
        " reflog show --format=%gs -1 HEAD",
      options = {poUsePath}, env = scrubbedGitRepositoryEnv())
  except CatchableError:
    result.state = gosIdle
    return
  if reflog.exitCode == 0:
    let subject = reflog.output.strip().splitLines()[0].strip()
    if reflogActionSuggestsOperation(subject):
      result.state = gosInProgress
      result.marker = "HEAD reflog: " & subject
      return
  result.state = gosIdle

proc managedHookStandDown*(hookName, repoPath: string):
    tuple[standDown: bool; report: string; loud: bool] =
  ## The gate every managed ``post-*`` hook passes through before it touches
  ## anything.
  ##
  ## Git fires these hooks for its OWN intermediate steps: `post-checkout`
  ## once per ref update inside a rebase or a bisect, `post-commit` once per
  ## commit a rebase or a cherry-pick replays. Those are transient states
  ## belonging to an operation already in flight, and a hook that writes into
  ## the working tree, pushes a ref, or — as this one did — runs
  ## `git checkout <branch>` there is corrupting somebody else's operation.
  ##
  ## Git's own hook contract supplies no "am I inside an operation" argument,
  ## so it is answered the way git answers it for itself: the presence of the
  ## in-flight state paths (`wt_status_get_state` reads the same names).
  ##
  ## Returns ``loud = true`` only for the INDETERMINATE case. An in-flight
  ## skip is a decision, not a problem, and a 50-commit rebase that printed
  ## 50 lines would teach its user to stop reading them. A probe that could
  ## not decide is different: the hook is inert and the operator is told so,
  ## rather than left to infer it from silence.
  var identity: GitToolIdentity
  try:
    identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
  except CatchableError as err:
    return (true, hookName & " inert: cannot determine whether a git " &
      "operation is in progress in " & repoPath & " — git is not " &
      "resolvable (" & err.msg & "); nothing was inspected or modified",
      true)
  let probe = probeGitOperationInProgress(identity, repoPath)
  case probe.state
  of gosIdle:
    (false, "", false)
  of gosInProgress:
    (true, hookName & " skipped: a git operation is in progress (" &
      probe.marker & ") in " & repoPath &
      "; the workspace is reconciled by the operation's own final " &
      "checkout, or by `repro workspace migrate`", false)
  of gosIndeterminate:
    (true, hookName & " inert: cannot determine whether a git operation " &
      "is in progress — " & probe.diagnostic &
      "; nothing was inspected or modified", true)

proc expectedBranchTip(identity: GitToolIdentity;
                       repoPath, branch: string;
                       remoteName: string = "origin"): string =
  ## Resolve the *expected* tip for a branch-pinned manifest. The
  ## divergence check is "does the working tree's HEAD match what the
  ## upstream branch points at" — we therefore consult the
  ## remote-tracking branch first (``refs/remotes/<remoteName>/<branch>``
  ## after a fresh clone) and fall back to the local branch only when
  ## no remote-tracking ref exists. Any other arrangement would
  ## misclassify a checkout that has local-only commits beyond the
  ## manifest pin (which is exactly the divergence M9 must surface).
  let rName = if remoteName.len > 0: remoteName else: "origin"
  let remoteTip = revParse(identity, repoPath, "refs/remotes/" & rName & "/" & branch)
  if remoteTip.len > 0:
    return remoteTip
  revParse(identity, repoPath, branch)

proc looksLikeSha(value: string): bool =
  ## Heuristic for the branch-vs-SHA divergence test. Git SHA-1s are
  ## 40-character lowercase hex; SHA-256 builds extend to 64. A user
  ## abbreviation of 7-39 hex characters is also accepted so an
  ## explicit short SHA in the manifest is not misclassified as a
  ## branch name.
  if value.len < 7 or value.len > 64:
    return false
  for ch in value:
    if ch notin {'0'..'9', 'a'..'f'}:
      return false
  true

proc classifyExistingRepo(
    identity: GitToolIdentity;
    workspaceRoot: string;
    repo: ResolvedRepo;
    upToDate: var seq[WorkspaceInitUpToDateEntry];
    divergences: var seq[WorkspaceInitDivergenceEntry]) =
  ## A repo directory exists at ``<workspaceRoot>/<repo.path>``. Decide
  ## whether it matches the manifest's declared revision (record as
  ## up-to-date) or diverges (record as a structured divergence). The
  ## milestone explicitly forbids auto-modifying a divergent checkout —
  ## we observe and report.
  let repoPath = workspaceRoot / repo.path
  let headSha = localHeadOrEmpty(identity, repoPath)
  if repo.revision.len == 0:
    # Manifest didn't pin a revision; any non-empty HEAD is treated as
    # up-to-date. An empty HEAD (bare directory? broken clone?) is a
    # divergence so the user fixes it.
    if headSha.len > 0:
      upToDate.add(WorkspaceInitUpToDateEntry(
        name: repo.name, path: repo.path, headSha: headSha))
    else:
      divergences.add(WorkspaceInitDivergenceEntry(
        name: repo.name, path: repo.path,
        expected: "<unspecified>", observed: ""))
    return
  if looksLikeSha(repo.revision):
    if headSha.startsWith(repo.revision) or repo.revision.startsWith(headSha):
      upToDate.add(WorkspaceInitUpToDateEntry(
        name: repo.name, path: repo.path, headSha: headSha))
    else:
      divergences.add(WorkspaceInitDivergenceEntry(
        name: repo.name, path: repo.path,
        expected: repo.revision, observed: headSha))
  else:
    # Branch name. The repo matches when the local HEAD's SHA equals
    # the remote-tracking branch's tip — i.e. ``origin/<branch>``.
    # ``expectedBranchTip`` prefers the remote-tracking ref and falls
    # back to the local branch when no remote-tracking ref exists.
    # Any other state (detached HEAD, ahead of origin, behind origin)
    # is a divergence: the user has work to do.
    let branchTip = expectedBranchTip(identity, repoPath, repo.revision, remoteName = gitRemoteNameFor(repo))
    if branchTip.len > 0 and branchTip == headSha:
      upToDate.add(WorkspaceInitUpToDateEntry(
        name: repo.name, path: repo.path, headSha: headSha))
    else:
      divergences.add(WorkspaceInitDivergenceEntry(
        name: repo.name, path: repo.path,
        expected: (if branchTip.len > 0: branchTip else: repo.revision),
        observed: headSha))

proc safeRepoIdSegment(value: string): string =
  for ch in value:
    if ch in {'A'..'Z', 'a'..'z', '0'..'9', '-', '_', '.'}:
      result.add(ch)
    else:
      result.add('-')
  if result.len == 0:
    result = "repo"

proc gitRemoteOriginUrl(identity: GitToolIdentity; repoPath: string): string =
  ## RA-8 — read ``remote.origin.url`` for the host repo at ``repoPath``.
  ## Returns the empty string when the directory is not a git repo or has no
  ## ``origin`` remote; the resolution order treats that as "origin did not
  ## resolve" and continues to fail-loud rather than guessing.
  if not dirExists(repoPath):
    return ""
  let res = execCmdEx(
    quoteShell(identity.binaryPath) & " -C " & quoteShell(repoPath) &
      " config --get remote.origin.url",
    options = {poStdErrToStdOut, poUsePath},
    env = scrubbedGitRepositoryEnv())
  if res.exitCode == 0:
    res.output.strip()
  else:
    ""

proc findBootstrapConfigPath(workspaceRoot: string): string =
  ## RA-8 — locate the host bootstrap config (``.repro-workspace.toml``).
  ## Resolution of the FILE PATH:
  ##   1. ``REPRO_WORKSPACE_CONFIG`` env override (an explicit path).
  ##   2. ``<workspaceRoot>/.repro-workspace.toml`` and then each ancestor
  ##      directory (the host product repo committing the config may be a
  ##      parent of the directory ``init`` runs in).
  ## Returns the empty string when no config file is found.
  let override = getEnv("REPRO_WORKSPACE_CONFIG")
  if override.len > 0:
    return (if fileExists(override): absolutePath(override) else: "")
  var dir = absolutePath(workspaceRoot)
  while true:
    let candidate = dir / bootstrapConfigFileName
    if fileExists(candidate):
      return candidate
    let parent = dir.parentDir
    if parent.len == 0 or parent == dir:
      break
    dir = parent
  ""

proc resolveBootstrapConfig(args: var WorkspaceInitArgs) =
  ## RA-8 — resolve the manifest URL/branch (+ default projects) for ``init``
  ## from the host bootstrap config, with NO hardcoded org default.
  ##
  ## Resolution order for the manifest URL/branch:
  ##   1. explicit ``--manifest-url`` / ``--manifest-branch`` (RA-11 flags);
  ##   2. the host bootstrap config ``.repro-workspace.toml``
  ##      (``REPRO_WORKSPACE_CONFIG`` or discovered in the host repo);
  ##   3. the host repo's own ``remote.origin.url``.
  ## If none resolves, ``init`` later fails loud — the ``repro`` binary ships
  ## NO built-in/hardcoded manifest URL fallback.
  ##
  ## When the workspace already has a ``.repo/manifests`` checkout (a sibling
  ## checkout or a prior bootstrap), no manifest URL is needed at all and the
  ## resolution is skipped; ``init`` reads the existing checkout directly.
  if dirExists(args.workspaceRoot / "projects"):
    return

  # (1) Explicit flag wins outright — and may still pull default projects /
  # a private URL from the config below without overriding the URL/branch.
  let configPath = findBootstrapConfigPath(args.workspaceRoot)
  if configPath.len > 0:
    let cfg = readWorkspaceBootstrap(configPath)
    if not args.manifestUrlExplicit:
      args.manifestUrl = cfg.manifest.url
      if cfg.manifest.branch.isSome and args.manifestBranch.len == 0:
        args.manifestBranch = cfg.manifest.branch.get()
    if args.privateManifestUrl.len == 0 and cfg.manifest.private_url.isSome:
      args.privateManifestUrl = cfg.manifest.private_url.get()
    if cfg.projects.default.len > 0:
      args.defaultProjects = cfg.projects.default
    # Fill the project-to-init from the config default when no positional
    # project name was supplied.
    if args.projectName.len == 0 and args.defaultProjects.len > 0:
      args.projectName = args.defaultProjects[0]
    # RA-17 — resolve the manifest-provenance trust anchor from the config's
    # ``[manifest] revision`` + ``[verify]`` table. Paths in ``allowed_signers``
    # are resolved relative to the config's directory. The resulting spec is a
    # no-op unless the config opts into verification.
    args.verifySpec = resolveVerifySpec(cfg, configPath.parentDir)

  # (3) Host repo origin — only when neither an explicit flag nor the config
  # supplied a manifest URL.
  if args.manifestUrl.len == 0:
    let identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
    let origin = gitRemoteOriginUrl(identity, args.workspaceRoot)
    if origin.len > 0:
      args.manifestUrl = origin

proc bootstrapManifestCache(args: WorkspaceInitArgs) =
  ## RA-11 bootstrap manifest cache. When ``--manifest-url`` is given and
  ## the workspace has no manifest checkout yet, clone the
  ## manifest repo into the tool-managed bootstrap cache
  ## (``resolveManifestCacheRoot`` order: ``REPRO_MANIFEST_CACHE`` →
  ## ``XDG_CACHE_HOME`` → ``%LOCALAPPDATA%`` → ``~/.cache``, all under
  ## ``reprobuild/manifests``; keyed by source URL) and materialise
  ## workspace manifests from it so the resolver finds
  ## ``projects/<name>.toml`` without a pre-existing sibling checkout.
  ##
  ## A private companion manifest (``--private-manifest-url``) is cloned
  ## into the PARALLEL private cache (``…/manifests-private``) and
  ## materialised at ``.repro/manifests-private`` — a separate cache tree
  ## so the two never share a slug namespace.
  if args.manifestUrl.len == 0:
    return
  let manifestsDir = args.workspaceRoot / ".repro" / "manifests"
  if dirExists(manifestsDir / "projects"):
    # Already have a manifest checkout — bootstrap is a no-op (a sibling
    # checkout or a prior bootstrap already populated it).
    return
  let identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
  createDir(args.workspaceRoot / ".repro")

  let cacheRoot = defaultManifestCacheRoot(private = false)
  let cached = ensureManifestCache(identity.binaryPath, cacheRoot,
    args.manifestUrl, args.manifestBranch)
  if not cached.ok:
    raise newException(ValueError,
      "could not bootstrap manifest repo '" & args.manifestUrl &
        "' into the manifest cache at '" & cacheRoot & "': " &
        cached.diagnostic)

  # RA-17 — fail closed BEFORE the manifest checkout is trusted. When the host
  # bootstrap config requires a signature (or pins a revision), verify the
  # freshly-fetched manifest source's HEAD/pinned-tag signature against the
  # configured allowed-signers set. An unsigned / wrong-key / tampered /
  # moved-pin source raises here, so workspace manifests are never materialised
  # from an unverified source. When verification is NOT configured this is a
  # guaranteed no-op and the flow is unchanged.
  if isVerificationActive(args.verifySpec):
    try:
      verifyManifestProvenance(identity.binaryPath, cached.sharedBarePath,
        args.verifySpec)
    except ManifestProvenanceError as e:
      raise newException(ValueError,
        "refusing to initialise workspace: manifest provenance " &
          "verification failed for '" & args.manifestUrl & "': " & e.msg)

  # Materialise the workspace's manifest checkout from the cache. A
  # symlink keeps a single cached copy shared across workspaces; on a
  # platform/filesystem that rejects the symlink we fall back to a copy.
  try:
    createSymlink(cached.sharedBarePath, manifestsDir)
  except OSError, IOError:
    copyDir(cached.sharedBarePath, manifestsDir)

  if args.privateManifestUrl.len > 0:
    let privateDir = args.workspaceRoot / ".repro" / "manifests-private"
    if not dirExists(privateDir):
      let privateCacheRoot = defaultManifestCacheRoot(private = true)
      let privCached = ensureManifestCache(identity.binaryPath,
        privateCacheRoot, args.privateManifestUrl, args.manifestBranch)
      if not privCached.ok:
        raise newException(ValueError,
          "could not bootstrap private companion manifest '" &
            args.privateManifestUrl & "' into the private manifest cache " &
            "at '" & privateCacheRoot & "': " & privCached.diagnostic)
      try:
        createSymlink(privCached.sharedBarePath, privateDir)
      except OSError, IOError:
        copyDir(privCached.sharedBarePath, privateDir)

proc normalizeMaterializeRel(raw: string): string =
  ## A copyfile/linkfile path is authored with forward slashes (the
  ## Workspace-Manifests "Common Conventions" rule) and must stay inside
  ## its anchor (repo for `src`, workspace root for `dest`). Reject
  ## absolute paths and any `..` segment; return the host-separator form.
  ## Empty string signals an invalid path the caller must report.
  if raw.len == 0 or isAbsolute(raw) or '\\' in raw:
    return ""
  for component in raw.split('/'):
    if component == ".." or component == "":
      return ""
  raw.replace('/', DirSep)

proc materializeRepoFiles(workspaceRoot: string;
                          repo: ResolvedRepo): seq[MaterializedFileEntry] =
  ## Apply `repo`'s copyfile (copy) and linkfile (symlink) directives.
  ## Idempotent: an existing `dest` (regular file or symlink) is removed
  ## and rewritten so the materialized file/symlink tracks the current
  ## checkout. Every directive is best-effort and independently reported;
  ## a failure on one never aborts the others or the surrounding sync.
  let repoAbs = workspaceRoot / repo.path

  proc apply(kind: string; entry: CopyLinkFileEntry): MaterializedFileEntry =
    result = MaterializedFileEntry(
      repo: repo.path, kind: kind, src: entry.src, dest: entry.dest)
    let srcRel = normalizeMaterializeRel(entry.src)
    let destRel = normalizeMaterializeRel(entry.dest)
    if srcRel.len == 0:
      result.status = "failed"
      result.diagnostic = "invalid src path '" & entry.src &
        "' (must be repo-relative, forward-slashed, no `..`)"
      return
    if destRel.len == 0:
      result.status = "failed"
      result.diagnostic = "invalid dest path '" & entry.dest &
        "' (must be workspace-root-relative, forward-slashed, no `..`)"
      return
    let srcAbs = repoAbs / srcRel
    let destAbs = workspaceRoot / destRel
    if not fileExists(srcAbs) and not dirExists(srcAbs):
      result.status = "failed"
      result.diagnostic = "source '" & srcRel & "' does not exist in repo '" &
        repo.path & "'"
      return
    try:
      createDir(destAbs.parentDir)
      # Idempotent overwrite: clear any prior materialized file/symlink so
      # a re-run replaces stale content (the checked-out src may have
      # changed) and a copyfile→linkfile switch is honored.
      if symlinkExists(destAbs) or fileExists(destAbs):
        removeFile(destAbs)
      if kind == "linkfile":
        createSymlink(srcAbs, destAbs)
      else:
        copyFile(srcAbs, destAbs)
      result.status = "materialized"
    except OSError as e:
      result.status = "failed"
      result.diagnostic = e.msg
    except IOError as e:
      result.status = "failed"
      result.diagnostic = e.msg

  for entry in repo.copyfile:
    result.add(apply("copyfile", entry))
  for entry in repo.linkfile:
    result.add(apply("linkfile", entry))

# ---- RA-12: post-clone / post-pull shell-hook auto-trust ------------------
#
# After ``init`` / ``pull`` materialise repos, freshly cloned shell-hook
# files (``.envrc``) are NOT yet trusted by the activator (direnv), so the
# environment would not activate until the user manually ran ``direnv allow``
# in each directory. RA-12 runs that trust pass automatically over every
# discovered ``.envrc`` (workspace root, host/org root, and each checked-out
# repo). The pass is best-effort: if the activator is unavailable it is
# SKIPPED cleanly, and a single trust failure is reported but never aborts
# init/pull.

proc resolveDirenvBin*(): string =
  ## Resolve the direnv activator binary. Honors the ``REPRO_DIRENV_BIN``
  ## test/override seam FIRST (so a fake direnv can be injected hermetically),
  ## then falls back to ``direnv`` on PATH. Returns the empty string when no
  ## activator is available (the graceful-skip signal). An override pointing
  ## at a NON-EXISTENT path resolves to empty, so the skip path is reachable
  ## by pointing the seam at a missing file.
  let override = getEnv("REPRO_DIRENV_BIN")
  if override.len > 0:
    if fileExists(override):
      return override
    return ""
  findExe("direnv")

proc autoTrustEnvrcFiles*(roots: openArray[string]): TrustReport =
  ## Discover ``.envrc`` files across ``roots`` (deduplicated, in order) and
  ## run the activator's trust command (``direnv allow <dir>``) for each.
  ##
  ## Graceful skip: when no activator resolves, the whole pass is skipped —
  ## ``activatorAvailable`` is false and ``skipReason`` is set; no error is
  ## raised. Per-file isolation: a trust failure on one ``.envrc`` is recorded
  ## as a ``failed`` entry and does NOT abort the remaining roots. Trusting an
  ## already-trusted ``.envrc`` is a no-op for direnv (idempotent).
  let direnvBin = resolveDirenvBin()
  if direnvBin.len == 0:
    result.activatorAvailable = false
    result.skipReason = "direnv not found on PATH (set REPRO_DIRENV_BIN to " &
      "override); skipping shell-hook auto-trust"
    return
  result.activatorAvailable = true
  result.activatorBin = direnvBin
  var seen = initHashSet[string]()
  for root in roots:
    if root.len == 0:
      continue
    let envrcPath = root / ".envrc"
    if not fileExists(envrcPath):
      continue
    let dir = absolutePath(root)
    if seen.containsOrIncl(dir):
      continue
    var entry = TrustEntry(dir: dir)
    try:
      let res = execCmdEx(
        quoteShell(direnvBin) & " allow " & quoteShell(dir))
      if res.exitCode == 0:
        entry.status = "trusted"
      else:
        entry.status = "failed"
        entry.diagnostic = res.output.strip()
    except CatchableError as err:
      entry.status = "failed"
      entry.diagnostic = err.msg
    result.entries.add(entry)

proc discoverEnvrcRoots(workspaceRoot: string;
                        repos: seq[ResolvedRepo]): seq[string] =
  ## Enumerate the candidate roots for the auto-trust pass, in a stable
  ## order: the workspace root (which, after a cold-start ``init <url>``, is
  ## ALSO the org/host root checkout), then every checked-out repo at its
  ## declared ``path`` whose working tree exists on disk. The trust pass
  ## itself filters to the roots that actually contain a ``.envrc`` and
  ## deduplicates, so listing a root without one is harmless.
  result.add(workspaceRoot)
  for repo in repos:
    let abs = workspaceRoot / repo.path
    if dirExists(abs):
      result.add(abs)

proc workspaceProjectsPlaceholderContent(): string =
  """
No projects have been initialized in this workspace yet.

Run `repro workspace init` to initialize configured defaults, or `repro workspace init <project>` to add one.
""".strip() & "\n"

proc writeGeneratedWorkspaceProjects(workspaceRoot: string) =
  let workspaceToml = workspaceTomlPath(workspaceRoot)
  var projectNames: seq[string] = @[]
  if fileExists(workspaceToml):
    try:
      let workspaceLocal = readWorkspaceLocal(workspaceToml)
      projectNames = workspaceLocal.workspace.projects
      if projectNames.len == 0 and workspaceLocal.workspace.project.len > 0:
        projectNames.add(workspaceLocal.workspace.project)
    except CatchableError:
      discard
  projectNames.sort()

  if projectNames.len == 0:
    writeFile(workspaceRoot / "workspace-projects.md",
        workspaceProjectsPlaceholderContent())
    return

  var output: seq[string] = @["# Active Workspace Projects"]
  for projectName in projectNames:
    let projectFile = workspaceRoot / "projects" / (projectName & ".toml")
    output.add ""
    output.add "## " & projectName

    if not fileExists(projectFile):
      output.add ""
      output.add "No project description is available; the active manifest was not found on disk."
      continue

    let projectDescriptionFile = workspaceRoot / "projects" / (projectName & ".md")
    var projectDescription = ""
    if fileExists(projectDescriptionFile):
      projectDescription = readFile(projectDescriptionFile).strip()
    if projectDescription.len > 0:
      output.add ""
      output.add projectDescription

    try:
      let resolved = resolveProject(projectFile)
      if resolved.repos.len > 0:
        output.add ""
        output.add "Repositories:"
        for repo in resolved.repos:
          let repoDescFile = workspaceRoot / "repos" / (repo.name & ".md")
          var repoDesc = ""
          if fileExists(repoDescFile):
            repoDesc = readFile(repoDescFile).strip()
          if repoDesc.len > 0:
            output.add "- `" & repo.path & "` - " & repoDesc
          else:
            output.add "- `" & repo.path & "`"
    except CatchableError as err:
      output.add ""
      output.add "Error resolving repositories: " & err.msg

  writeFile(workspaceRoot / "workspace-projects.md", output.join("\n") & "\n")

proc gitRunPlain(identity: GitToolIdentity;
                 args: openArray[string]): tuple[code: int; output: string]

proc repoCheckoutRecognized(identity: GitToolIdentity; repoAbs: string;
    repo: ResolvedRepo; existingRemoteUrls: seq[string]): bool =
  ## Decide whether the git checkout at ``repoAbs`` is recognizably THIS
  ## manifest repo. Used to gate the auto-modifying remote alignment so a
  ## foreign checkout that happens to occupy a repo path is left untouched
  ## rather than having its git remotes silently rewritten.
  ##
  ## Recognized when ANY of:
  ##   * it has no remotes configured yet — nothing to clobber; a fresh or
  ##     partial clone we may safely populate;
  ##   * one of its remote URLs already matches an expected manifest URL —
  ##     it is ours, possibly with drifted remote *names* or extras;
  ##   * its HEAD is at the manifest's pinned revision — content identity,
  ##     which covers a genuinely drifted remote *URL* (e.g. an org rename)
  ##     where rewriting the remote is exactly the intended fix.
  ##
  ## Only a checkout that matches NONE of these — remotes present, none
  ## pointing at an expected URL, and HEAD not at the pinned revision — is
  ## treated as unrecognized (left untouched by the caller).
  if existingRemoteUrls.len == 0:
    return true
  var expectedUrls = initHashSet[string]()
  if repo.fetchUrl.len > 0: expectedUrls.incl(repo.fetchUrl)
  for r in repo.remotes:
    if r.fetchUrl.len > 0: expectedUrls.incl(r.fetchUrl)
  for u in existingRemoteUrls:
    if u in expectedUrls:
      return true
  if repo.revision.len > 0:
    let headSha = localHeadOrEmpty(identity, repoAbs)
    if headSha.len > 0:
      if looksLikeSha(repo.revision):
        if headSha.startsWith(repo.revision) or repo.revision.startsWith(headSha):
          return true
      else:
        let branchTip = expectedBranchTip(identity, repoAbs, repo.revision,
          remoteName = gitRemoteNameFor(repo))
        if branchTip.len > 0 and branchTip == headSha:
          return true
  false

proc alignWorkspaceRemotes*(workspaceRoot: string; repos: seq[ResolvedRepo]; identity: GitToolIdentity) =
  ## Align on-disk Git remote configurations to match the resolved TOML manifests.
  ## Expected remotes are added/updated with correct URLs, and stale remotes are cleaned up.
  ##
  ## Rewriting remotes is an auto-modification, so — consistent with the
  ## "observe, don't auto-modify an unrecognized checkout" contract the init
  ## classifier follows — a checkout whose identity we cannot confirm
  ## (``repoCheckoutRecognized`` false) is skipped and reported rather than
  ## having its remotes rewritten. This protects an unrelated repository that
  ## happens to occupy a repo path from being silently re-pointed.
  ##
  ## Workspace-Membership-Model.md — the loop below is already the model's
  ## contract and needs no special case for it: it configures EVERY
  ## `ResolvedRepo.remotes` entry under the LOCAL name the fragment gave it,
  ## so a fork's `upstream` lands beside `origin` and at its own URL, which
  ## per-binding `url_prefix` / `url_suffix` now makes a different path than
  ## the fork's. The resolver guarantees the primary entry is named `origin`;
  ## nothing here has to enforce that, and nothing here may assume the list has
  ## exactly one entry.
  for repo in repos:
    let repoAbs = workspaceRoot / repo.path
    if not dirExists(repoAbs / ".git"):
      continue
    # 1. Get existing remotes (names + URLs)
    let existingRes = gitRunPlain(identity, ["-C", repoAbs, "remote"])
    var existingRemotes = initHashSet[string]()
    var existingRemoteUrls: seq[string]
    if existingRes.code == 0:
      for line in existingRes.output.strip().splitLines():
        let name = line.strip()
        if name.len > 0:
          existingRemotes.incl(name)
          let urlRes = gitRunPlain(identity, ["-C", repoAbs, "remote", "get-url", name])
          if urlRes.code == 0 and urlRes.output.strip().len > 0 and
              urlRes.output.strip() notin existingRemoteUrls:
            existingRemoteUrls.add(urlRes.output.strip())

    # Identity guard: never rewrite the remotes of a checkout we cannot
    # recognize as this manifest repo.
    if not repoCheckoutRecognized(identity, repoAbs, repo, existingRemoteUrls):
      stderr.writeLine("workspace: skipping remote alignment for '" & repo.path &
        "' — its git remotes (" & existingRemoteUrls.join(", ") &
        ") do not match the manifest source and its HEAD is not at the pinned " &
        "revision; leaving this checkout untouched (not recognized as '" &
        repo.name & "').")
      continue

    # 2. Add or update expected remotes
    var expectedRemotes = initHashSet[string]()
    for r in repo.remotes:
      expectedRemotes.incl(r.localName)
    for r in repo.remotes:
      if r.localName in existingRemotes:
        let getRes = gitRunPlain(identity, ["-C", repoAbs, "remote", "get-url", r.localName])
        if getRes.code == 0 and getRes.output.strip() != r.fetchUrl:
          discard gitRunPlain(identity, ["-C", repoAbs, "remote", "set-url", r.localName, r.fetchUrl])
        continue
      # The declared name is absent. Before adding it — and letting step 3
      # prune whatever carried the same URL under another name — look for THAT
      # remote and RENAME it. Add-then-prune reaches the same URL under the
      # same name, but it destroys `refs/remotes/<old>/*` and orphans every
      # `branch.<b>.remote` that named it, so a checkout whose remote was named
      # after its org (the predecessor tool's convention) silently loses its
      # tracking configuration on the first sync after the rename.
      var renamedFrom = ""
      for existing in existingRemotes:
        if existing in expectedRemotes:
          continue
        let urlRes = gitRunPlain(identity,
          ["-C", repoAbs, "remote", "get-url", existing])
        if urlRes.code == 0 and urlRes.output.strip() == r.fetchUrl:
          renamedFrom = existing
          break
      if renamedFrom.len > 0:
        let renamed = gitRunPlain(identity,
          ["-C", repoAbs, "remote", "rename", renamedFrom, r.localName])
        if renamed.code == 0:
          existingRemotes.excl(renamedFrom)
          existingRemotes.incl(r.localName)
          continue
      discard gitRunPlain(identity, ["-C", repoAbs, "remote", "add", r.localName, r.fetchUrl])

    # 3. Clean up/remove unexpected remotes.
    #
    # The invariant, stated as the outcome rather than as a property of the
    # input: ALIGNMENT NEVER LEAVES A CHECKOUT WITH ZERO REMOTES. A tidying
    # step has no business disconnecting a working tree from everywhere it
    # came from, whatever the manifest happens to say.
    #
    # Guarding on "the declared set is empty" was the first attempt and it was
    # too narrow, because it reasons about the input to a step whose damage
    # depends on the OUTPUT. Two ways a non-empty declaration still strips
    # everything:
    #
    #   * the declared name is one git will not accept — `git remote add ""`
    #     exits 128 — so the add silently does nothing while the name still
    #     counts as "expected", and the prune then removes the real remote;
    #   * an add or rename fails for any other reason (a locked config, a
    #     name collision) and the replacement that justified the prune was
    #     never actually created.
    #
    # So the decision is made against what the checkout ACTUALLY has after the
    # add/rename pass, re-read from git rather than from this proc's own
    # bookkeeping — the bookkeeping is what was wrong in both cases above. If
    # every surviving remote would be pruned, the whole prune is refused and
    # SAID OUT LOUD, because at that point the manifest and the checkout
    # disagree in a way no amount of quiet tidying can settle.
    var actualRemotes: seq[string]
    let afterAdds = gitRunPlain(identity, ["-C", repoAbs, "remote"])
    if afterAdds.code == 0:
      for line in afterAdds.output.strip().splitLines():
        let name = line.strip()
        if name.len > 0:
          actualRemotes.add(name)
    var prunable: seq[string]
    var surviving = 0
    for name in actualRemotes:
      if name in expectedRemotes:
        inc surviving
      else:
        prunable.add(name)
    if prunable.len > 0 and surviving == 0:
      stderr.writeLine("workspace: refusing to prune the remote(s) of '" &
        repo.path & "' (" & prunable.join(", ") &
        ") — the manifest declares " &
        (if expectedRemotes.len == 0: "none"
         else: "only remote(s) this checkout does not have and could not be " &
           "given") &
        ", so pruning would leave it with no remote at all. Left untouched; " &
        "check what '" & repo.name & "' resolves to.")
    else:
      for name in prunable:
        discard gitRunPlain(identity, ["-C", repoAbs, "remote", "remove", name])

# ---- workspace sibling ignore set -----------------------------------------
#
# A workspace root is a git checkout whose siblings are OTHER checkouts, so
# without an ignore set `git status` there reports one untracked directory per
# participating repo. ``repro_workspace_vcs/sibling_ignores`` maintains a
# marker-delimited block in the root's ``.git/info/exclude`` naming them; see
# ``reprobuild-specs/Workspace-Sibling-Ignore-Set.md``.
#
# Regeneration is hooked into the verbs that can CHANGE the sibling set
# (``init``, ``enable``, ``disable``, ``sync``, ``pull``). It is cheap and
# idempotent — the marker block means a re-run rewrites only its own lines and
# an unchanged result does not touch the file at all — so erring toward more
# hooks is safe.
#
# Forward-declared: the sync/pull/init call sites precede
# ``resolveWorkspaceReposForHook``, which supplies the DECLARED (possibly
# nested) checkout paths so discovery is not reimplemented here.
proc refreshWorkspaceSiblingIgnoresBestEffort(workspaceRoot: string)

proc executeWorkspaceInit(argsIn: WorkspaceInitArgs): WorkspaceInitOutcome =
  ## End-to-end driver. Resolves the named project / variant, classifies
  ## each declared repo against the on-disk workspace, schedules a
  ## ``bakWorkspaceVcs.clone`` build plan for the missing ones, then
  ## emits the structured report.
  var args = argsIn
  # RA-8: resolve the manifest URL/branch (+ default projects, project name)
  # from the host bootstrap config / host repo origin BEFORE bootstrapping,
  # with NO hardcoded org default. The resolution is a no-op when a manifest
  # checkout already exists.
  resolveBootstrapConfig(args)
  let manifestsDir = manifestsRoot(args.workspaceRoot) / "projects"
  # A compositional ``.repro/workspace.toml`` (one or more ``[[manifest]]``
  # layers, M8/M25 semantics) IS the manifest configuration: the composer
  # (``resolveWorkspaceInitProject`` → ``composeManifestLayersFromFile*``)
  # clones each layer URL itself, so such a workspace has no on-disk
  # projects/repos files and needs no ``--manifest-url``. The
  # "no manifest configured" guard (added by the host-bootstrap-config
  # change AFTER M25) must not fire for it, or compositional init aborts
  # before the composer ever runs.
  if not dirExists(manifestsDir) and args.manifestUrl.len == 0 and
      not isCompositionalWorkspaceToml(args.workspaceRoot):
    raise newException(ValueError,
      "no manifest configured for `repro workspace init`: pass " &
        "`--manifest-url=…`, commit a `" & bootstrapConfigFileName &
        "` host bootstrap config (or set `REPRO_WORKSPACE_CONFIG`), or run " &
        "inside a host repo whose `origin` is the manifest source. `repro` " &
        "ships no built-in manifest URL.")
  if args.projectName.len == 0:
    raise newException(ValueError,
      "`repro workspace init` requires a <project-or-variant> name " &
        "(none was given and the host bootstrap config declared no " &
        "`[projects] default`)")
  # RA-11: bootstrap the manifest repo into the tool-managed cache when
  # a manifest URL resolved and no manifest checkout exists yet, so
  # ``init`` works OUTSIDE an existing workspace.
  bootstrapManifestCache(args)
  let resolution = resolveWorkspaceInitProject(args)
  let resolved = resolution.project
  var report: WorkspaceInitReport
  report.project = resolved.projectName
  report.workspaceRoot = args.workspaceRoot
  report.skippedLayers = resolution.skippedLayers
  var cloneFailures = 0

  # M9 requires git tool resolution before we can either query existing
  # checkouts OR schedule a clone. Raising ``EGitToolUnresolved`` here
  # surfaces the M1 structured error directly to the dispatcher.
  let identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # RA-5: resolve the shared object-cache root once for this workspace and
  # refresh each unique upstream's shared bare BEFORE scheduling the
  # per-repo clones. The refresh is the single shared-state write per URL;
  # doing it up front means concurrent clones read a consistent pool
  # without racing a fetch into the same bare. Every step is best-effort:
  # if a shared bare can't be populated, the affected clone simply runs
  # standalone (no ``--reference``) and the accelerator is a no-op for it.
  let cacheRoot = defaultCacheRoot(args.workspaceRoot)
  var sharedBareByUrl = initTable[string, string]()
  proc sharedReferenceFor(fetchUrl: string): string =
    if fetchUrl.len == 0:
      return ""
    if sharedBareByUrl.hasKey(fetchUrl):
      return sharedBareByUrl[fetchUrl]
    let refreshed = refreshSharedBare(identity.binaryPath, cacheRoot, fetchUrl)
    let reference = if refreshed.ok: refreshed.sharedBarePath else: ""
    if not refreshed.ok and refreshed.diagnostic.len > 0:
      stderr.writeLine("workspace init: shared-clone cache miss for " &
        fetchUrl & " (falling back to standalone clone): " &
        refreshed.diagnostic)
    sharedBareByUrl[fetchUrl] = reference
    reference

  var cloneActions: seq[BuildAction]
  var cloneEntries: seq[WorkspaceInitClonedEntry]
  for idx, repo in resolved.repos:
    let absPath = args.workspaceRoot / repo.path
    if dirExists(absPath):
      classifyExistingRepo(identity, args.workspaceRoot, repo,
        report.upToDate, report.divergences)
      continue
    # Missing — schedule a clone. The receipt lives next to the working
    # tree under a hidden ``.repro/workspace/receipts/`` subtree so the
    # action cache has a stable per-repo output path that does not
    # collide with anything inside the repo itself.
    let receiptDir = args.workspaceRoot / ".repro" / "workspace" / "receipts"
    createDir(receiptDir)
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("clone-" & safeRepoIdSegment(repo.name) & "-" & $idx & ".receipt")
    let cloneId = "workspace-init-clone-" & safeRepoIdSegment(repo.name) &
      "-" & $idx
    let initCloneUrl = cloneUrlFor(repo)
    var action = gitCloneAction(cloneId, identity,
      remoteUrl = initCloneUrl,
      repoPath = repo.path,
      receiptPath = receiptRel,
      revision = repo.revision,
      referencePath = sharedReferenceFor(initCloneUrl),
      cloneFilter = repo.cloneFilter,
      depth = repo.depth,
      singleBranch = repo.singleBranch)
    action.cwd = args.workspaceRoot
    # RA-5c: tag init's clones with the same ``vcs/fetch`` pool so init
    # also respects ``jobs-network`` (the network-concurrency bound shared
    # with sync/pull). The shared-bare refresh per URL is already done up
    # front (above), so the pool only bounds the per-repo clones.
    action.pool = "vcs/fetch"
    action.poolUnits = 1'u32
    cloneActions.add(action)
    cloneEntries.add(WorkspaceInitClonedEntry(
      name: repo.name, path: repo.path,
      remote: initCloneUrl, revision: repo.revision))

  if cloneActions.len > 0:
    let cacheRoot = args.workspaceRoot / ".repro" / "workspace" /
      "engine-cache"
    var config = defaultBuildEngineConfig(cacheRoot)
    config.suppressTrace = true
    # RA-5c: declare the ``vcs/fetch`` pool so the clones' pool tag binds
    # to a concrete capacity (the shared network-concurrency bound).
    let res = runBuild(
      graph(cloneActions, @[pool("vcs/fetch", 8'u32)]), config)
    # The build engine returns outcomes in completion order. Re-key
    # them by id so we can map each back to its source entry without
    # depending on the engine's emission order.
    var outcomeById = initTable[string, ActionResult]()
    for outcome in res.results:
      outcomeById[outcome.id] = outcome
    for i, action in cloneActions:
      let outcome = outcomeById.getOrDefault(action.id)
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        inc cloneFailures
        stderr.writeLine("workspace init: clone failed for " &
          cloneEntries[i].path & ": status=" & $outcome.status &
          " reason=" & outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: ""))
      else:
        report.cloned.add(cloneEntries[i])

  # RA-18: materialize copyfile/linkfile directives post-checkout. Applied
  # for every repo whose working tree now exists (freshly cloned OR already
  # present), so the workspace-root files track the checked-out revision.
  # Idempotent and best-effort: a failure on one directive is reported but
  # never fails init.
  for repo in resolved.repos:
    if repo.copyfile.len == 0 and repo.linkfile.len == 0:
      continue
    if not dirExists(args.workspaceRoot / repo.path):
      continue
    for m in materializeRepoFiles(args.workspaceRoot, repo):
      report.materialized.add(m)
      if m.status == "failed":
        stderr.writeLine("workspace init: " & m.kind & " '" & m.dest &
          "' <- '" & repo.path & "/" & m.src & "' failed: " & m.diagnostic)

  # RA-12: auto-trust freshly cloned shell-hook (.envrc) files. The
  # workspace root doubles as the host/org root after a cold-start
  # ``init <url>`` (which clones the org root repo and runs this in-workspace
  # init rooted there), so discovering over the workspace root + each
  # checked-out repo covers all three documented roots. The pass is
  # best-effort: a missing activator skips cleanly and a single trust
  # failure is reported without aborting init.
  report.autoTrust = autoTrustEnvrcFiles(
    discoverEnvrcRoots(args.workspaceRoot, resolved.repos))
  for line in renderTrustReportLines("workspace init", report.autoTrust):
    if "FAILED" in line or "skipped" in line:
      stderr.writeLine(line)

  result.report = report
  result.cloneFailures = cloneFailures

  # M13: record the active workspace branch in .repo/workspace.toml so
  # downstream commands (``repro workspace status``, M14 ``repro branch``,
  # M15 ``repro switch``) can read it back as a single source of truth.
  # The branch value is the resolver's ``trunk`` (the manifest's
  # documented default branch); when ``trunk`` is empty we fall back to
  # ``defaultRevision``. We only write when we have a meaningful value
  # AND no clone failures (writing on a half-broken init would record a
  # branch the workspace cannot honor). The write is idempotent — if the
  # composer mode already produced a workspace.toml with a branch, this
  # call is a no-op (the writer preserves any pre-existing branch when
  # we pass the same value, and the value comes from the same composed
  # ``resolved.trunk``).
  if cloneFailures == 0:
    let branchValue =
      if resolved.trunk.len > 0: resolved.trunk
      elif resolved.defaultRevision.len > 0: resolved.defaultRevision
      else: ""
    if branchValue.len > 0:
      try:
        writeWorkspaceBranch(args.workspaceRoot,
          project = resolved.projectName, branch = branchValue)
      except WorkspaceManifestParseError as e:
        # A malformed pre-existing workspace.toml shouldn't break init
        # — surface a structured diagnostic on stderr and continue.
        stderr.writeLine(
          "workspace init: could not record active branch: " & e.msg)
    try:
      writeGeneratedWorkspaceProjects(args.workspaceRoot)
    except CatchableError as err:
      stderr.writeLine("workspace init: could not generate workspace-projects.md: " & err.msg)
    alignWorkspaceRemotes(args.workspaceRoot, resolved.repos, identity)
    refreshWorkspaceSiblingIgnoresBestEffort(args.workspaceRoot)
proc writeWorkspaceInitReport(report: WorkspaceInitReport;
                              destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspaceInitCommand*(args: openArray[string]): int =
  ## ``repro workspace init <project-or-variant> [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]
  ## [--write-report[=PATH]]``.
  ##
  ## Exit codes (per M9 design):
  ##   - 0 — every missing repo cloned successfully AND no divergences.
  ##   - 1 — at least one clone action failed (e.g. unreachable remote,
  ##         malformed URL, the underlying git tool refused).
  ##   - 2 — there were divergences in pre-existing checkouts. We did
  ##         NOT auto-modify them; the user has work to do. Distinct
  ##         from exit-1 ("init blew up") so scripts can tell the two
  ##         apart.
  let parsed = parseWorkspaceInitArgs(args)
  let outcome = executeWorkspaceInit(parsed)
  writeWorkspaceInitReport(outcome.report,
    reportDestination(parsed.report, outcome.report.workspaceRoot, "init"))
  stageFailureReport(parsed.report, outcome.report.workspaceRoot, "init",
    outcome.report.toJsonNode())
  # ``init`` leaves every materialized repo on the manifest's revision, i.e. on
  # the workspace branch, so the cache records the count with no drift. The
  # init report carries no per-repo branch field to be more precise than that.
  block:
    var branches: seq[string]
    for _ in outcome.report.cloned: branches.add("")
    for _ in outcome.report.upToDate: branches.add("")
    for _ in outcome.report.divergences: branches.add("")
    writePromptCache(outcome.report.workspaceRoot, "init", branches)
  if parsed.json:
    stdout.writeLine(pretty(outcome.report.toJsonNode(), indent = 2))
  else:
    for line in renderInitTextLines(outcome.report):
      stdout.writeLine(line)
  if outcome.cloneFailures > 0:
    return 1
  if outcome.report.divergences.len > 0:
    return 2
  0

# ---- RA-31: `repro workspace init <url> [local-path]` cold-start front-end --

type
  ColdStartInitArgs = object
    ## Parsed argv for the RA-31 cold-start ``init <url> [local-path]`` form.
    url: string                          ## the <url> argument (form 1/2/3)
    localPath: string                    ## optional explicit destination dir
    toolProvisioning: ToolProvisioningMode
    printResolvedUrl: bool               ## ``--print-resolved-url`` dry-run
    passthrough: seq[string]             ## remaining flags forwarded to init

proc parseColdStartInitArgs(args: openArray[string]): ColdStartInitArgs =
  ## Parse the cold-start ``init`` argv. The first positional is ``<url>``;
  ## an optional second positional is ``local-path``. ``--print-resolved-url``
  ## resolves and prints the root-repo URL WITHOUT cloning (a dry run); any
  ## unrecognised flag is forwarded to the inner ``init`` (so e.g.
  ## ``--allow-missing-layers`` still works).
  result.toolProvisioning = tpmPathOnly
  var positionals: seq[string]
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--print-resolved-url":
      result.printResolvedUrl = true
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
      result.passthrough.add(arg)
    elif arg.startsWith("-"):
      result.passthrough.add(arg)
    else:
      positionals.add(arg)
    inc i
  if positionals.len >= 1:
    result.url = positionals[0]
  if positionals.len >= 2:
    result.localPath = positionals[1]
  if positionals.len > 2:
    raise newException(ValueError,
      "unexpected positional argument to `repro workspace init`: " &
        positionals[2])

proc looksLikeColdStartUrl(spec: string): bool =
  ## A ``<url>`` argument (full URL, ``host:org`` shorthand, or bare org) is
  ## the cold-start form. Distinguished from a legacy ``<project-or-variant>``
  ## name purely by the dispatcher's surrounding conditions (no
  ## ``--workspace-root`` / ``--manifest-url`` and no ``.repo/manifests`` in
  ## cwd); this helper just rejects an empty spec.
  spec.strip().len > 0

proc canonicalPathForCompare*(path: string): string =
  ## Resolve symlinks so two spellings of the SAME directory compare equal.
  ## This matters on macOS, where the process cwd reports ``/private/var/...``
  ## while a caller-supplied path is the ``/var/...`` symlink — a plain string
  ## compare would silently miss and let a destination guard through.
  ## A path that does not exist yet is resolved through its deepest existing
  ## ancestor, since the destination of a fresh materialization is by
  ## definition not on disk.
  if path.len == 0:
    return path
  try:
    if dirExists(path) or fileExists(path):
      return expandFilename(path)
  except OSError, IOError:
    discard
  var head = absolutePath(path)
  var tail: seq[string] = @[]
  while head.len > 1 and not dirExists(head):
    tail.add(head.extractFilename)
    let parent = head.parentDir
    if parent.len == 0 or parent == head:
      break
    head = parent
  var base = head
  try:
    if dirExists(base):
      base = expandFilename(base)
  except OSError, IOError:
    discard
  for i in countdown(tail.high, 0):
    base = base / tail[i]
  base

proc pathIsCwdOrAncestor*(candidate, fromDir: string): bool =
  ## True when ``candidate`` IS ``fromDir`` or one of its ancestors. Shared by
  ## RA-31 ``workspace init <url>`` and M27 ``branch <name> <path>``:
  ## both materialize into a fresh NAMED directory and must refuse to operate
  ## on the current or an enclosing checkout (the destructive upward-walk trap
  ## that made the repo-workspaces pilot drop its own ``init``/``start``).
  let wanted = canonicalPathForCompare(candidate)
  var dir = canonicalPathForCompare(fromDir)
  while true:
    if dir == wanted:
      return true
    let parent = dir.parentDir
    if parent.len == 0 or parent == dir:
      break
    dir = parent
  false

proc cloneOrgRootRepo(identity: GitToolIdentity;
                      url, destination: string):
    tuple[ok: bool; diagnostic: string] =
  ## Clone the org root workspace repo at ``url`` into ``destination`` (a
  ## fresh named directory). Best-effort; returns a structured failure so
  ## the caller can report a clear error instead of crashing.
  ##
  ## ``--recurse-submodules`` because the root repo's submodules are part of
  ## the workspace, not of some repo inside it. Reprobuild treats a develop-mode
  ## sibling as a submodule REPLACEMENT and so declares member repos in the
  ## manifest — but that rule governs the repos the manifest owns, and says
  ## nothing about the root repo's own git dependencies. Cloning it plainly
  ## left every such path an empty directory in a forked or freshly-joined
  ## workspace: present enough that nothing reported it missing, empty enough
  ## that whatever needed it failed later and elsewhere. (On Windows the
  ## visible symptom was `reprobuild/env.ps1` aborting on a missing
  ## `../repo-workspaces/env.ps1`, so a brand-new workspace could not build.)
  ##
  ## A repo with no submodules is unaffected — the flag is a no-op there.
  var cmd = quoteShell(identity.binaryPath) &
    " clone --recurse-submodules " & quoteShell(url) &
    " " & quoteShell(destination)
  let res = execCmdEx(cmd, options = {poStdErrToStdOut, poUsePath},
    env = scrubbedGitRepositoryEnv())
  if res.exitCode != 0:
    return (ok: false, diagnostic: res.output.strip())
  (ok: true, diagnostic: "")

proc runWorkspaceInitFromUrl*(args: openArray[string];
                              env: proc(name: string): string = sysEnv): int =
  ## RA-31 — the cold-start one-command join. ``repro workspace init <url>
  ## [local-path]``:
  ##   1. resolve ``<url>`` → the org ROOT workspace repo URL (full URL /
  ##      ``host:org`` shorthand / bare-org via the default VCS host);
  ##   2. derive the destination directory (``local-path`` else the org
  ##      name) — ALWAYS a new NAMED directory, NEVER cwd or an ancestor;
  ##   3. clone the root repo into that directory;
  ##   4. run the existing ``executeWorkspaceInit`` rooted in that directory,
  ##      which reads the cloned ``.repro-workspace.toml`` host bootstrap
  ##      config, bootstraps the manifest cache (RA-11), verifies provenance
  ##      (RA-17), and syncs the member repos.
  ## Ends by pointing the user at ``repro health``.
  let parsed = parseColdStartInitArgs(args)
  let resolution = resolveOrgRootRepoUrl(parsed.url, env)

  # ``--print-resolved-url``: resolution-only dry run (hermetic, no clone).
  if parsed.printResolvedUrl:
    stdout.writeLine(resolution.url)
    return 0

  # Destination: explicit ``local-path`` else the derived org name. This is
  # ALWAYS a named directory; the cold-start path never operates on the
  # current or an ancestor directory.
  var dest = parsed.localPath
  if dest.len == 0:
    dest = resolution.org
  if dest.len == 0:
    raise newException(ValueError,
      "could not derive a destination directory from '" & parsed.url &
        "'; pass an explicit <local-path>")
  let destAbs = absolutePath(dest)
  let cwd = absolutePath(getCurrentDir())
  # Safety: refuse to clone INTO the cwd itself or an ancestor of it. We test
  # this by walking cwd's ancestry up to the filesystem root and checking
  # whether destAbs is cwd or one of its ancestors.
  if pathIsCwdOrAncestor(destAbs, cwd):
    raise newException(ValueError,
      "`repro workspace init <url>` refuses to materialise into the " &
        "current or an ancestor directory ('" & destAbs & "'); it always " &
        "creates a fresh named directory (default: the org name)")
  if dirExists(destAbs) and toSeq(walkDir(destAbs)).len > 0:
    raise newException(ValueError,
      "destination '" & destAbs & "' already exists and is not empty; " &
        "choose a different <local-path> or remove it first")

  # Announce the plan (communicate-before-execute, RA-27 principle).
  stdout.writeLine("workspace init: resolved " & resolution.form & " '" &
    parsed.url & "' → " & resolution.url)
  stdout.writeLine("workspace init: plan — clone org root repo '" &
    resolution.url & "' into '" & destAbs &
    "', then read its bootstrap config and sync the workspace")

  let identity = ensureGitToolResolvable(parsed.toolProvisioning, getEnv("PATH"))

  # (3) Clone the org ROOT workspace repo into the named directory.
  stdout.writeLine("workspace init: cloning org root repo …")
  let cloned = cloneOrgRootRepo(identity, resolution.url, destAbs)
  if not cloned.ok:
    stderr.writeLine("repro workspace init: error: could not clone org root " &
      "repo '" & resolution.url & "': " & cloned.diagnostic)
    return 1

  # (4) Run the existing in-workspace init rooted in the cloned directory. It
  # reads the cloned ``.repro-workspace.toml`` (host bootstrap config), clones
  # the manifest into the bootstrap cache, verifies provenance if configured,
  # and syncs the declared member repos — we DO NOT duplicate that logic.
  var innerArgs = @["--workspace-root=" & destAbs]
  for flag in parsed.passthrough:
    innerArgs.add(flag)
  stdout.writeLine("workspace init: reading bootstrap config and syncing " &
    "the workspace …")
  let inner = runWorkspaceInitCommand(innerArgs)

  if inner == 0:
    stdout.writeLine("workspace init: workspace ready at '" & destAbs & "'.")
    stdout.writeLine("workspace init: next, run `repro health` to confirm " &
      "your environment is ready.")
  inner

# ---- M10: `repro workspace sync` ------------------------------------------
#
# The M10 dispatcher mirrors M9's structure: parse argv, resolve the project
# (or compose layers), inspect the local checkout of each ``ResolvedRepo``,
# and emit a structured report. The decision-making (the seven sync corner
# cases from ``Workspace-And-Develop-Mode.md`` §"Sync Corner Cases") is
# delegated to the pure-policy ``planSync`` proc in
# ``repro_workspace_manifests/sync_planner``; this dispatcher's job is to
# gather the per-repo observation and, once the plan is known, drive the
# minimal mutating actions through the M2 ``bakWorkspaceVcs`` executor.
#
# Before any per-repo work the dispatcher fast-forwards the manifest layers
# themselves (via ``refreshManifestLayers``) so the resolver reads the
# freshest manifest data. The same proc is what the M19a auto-refresh hook
# will eventually call.

type
  WorkspaceSyncManifestLayerEntry* = object
    ## One per manifest layer encountered during the pre-sync refresh.
    ## Mirrors ``ManifestLayerRefreshEntry`` 1:1; we keep a separate
    ## CLI-side record so the JSON shape stays stable even if the
    ## refresh helper later adds fields.
    index*: int
    provenance*: string
    layerPath*: string
    status*: string
    beforeSha*: string
    afterSha*: string
    diagnostic*: string

  WorkspaceSyncRepoEntry* = object
    ## One per ``ResolvedRepo`` after sync. ``syncCase`` is the
    ## snake_case tag of the planner's decision; ``action`` is the
    ## scheduled mutating-action tag (``none`` for refuse-and-report or
    ## no-op outcomes); ``executionStatus`` is the post-execution
    ## summary (``noop`` / ``refused`` / ``succeeded`` / ``failed``)
    ## the dispatcher fills in once the plan has run.
    name*: string
    path*: string
    syncCase*: string
    action*: string
    expected*: string
    observed*: string
    branch*: string
    message*: string
    refusalReason*: string
    executionStatus*: string
    executionDiagnostic*: string
    forcePushedBaseSha*: string

  WorkspaceSyncPlanEntry* = object
    ## RA-27 — one announced-before-acting plan line per participating repo.
    ## ``intendedAction`` is the action the sync expects to take based on
    ## the cheap pre-execution observation (``clone`` when the working tree
    ## is missing, else ``update`` for an existing checkout). It is a
    ## PREVIEW, not the planner's final seven-case decision (which needs a
    ## network fetch); the post-execution ``repos`` entries carry the real
    ## outcome. Never hardcoded — derived from the resolved repo set + the
    ## on-disk presence of each ``.git``.
    name*: string
    path*: string
    fetchUrl*: string
    intendedAction*: string
    revision*: string
      ## MO-8 — the resolved (locked) revision for this repo. For a
      ## committed-lock-only workspace this comes from the lock's CONTENT
      ## (coordinates), so it reflects the LOCKED state, not live ``git HEAD``.

  WorkspaceSyncReport* = object
    ## Structured outcome of one ``repro workspace sync`` invocation.
    ## ``project`` carries the ``ResolvedProject.projectName``;
    ## ``workspaceRoot`` is the absolute path of the directory
    ## containing ``.repo/``; ``manifestLayers`` records the
    ## pre-reconciliation refresh; ``repos`` carries the planner's
    ## seven-case classification per declared repo.
    project*: string
    workspaceRoot*: string
    scopeProjects*: seq[string]
      ## RA-27 — the ``<project>`` names this sync was scoped to (empty =
      ## whole workspace). Surfaced so an agent/CI can confirm the scope.
    dryRun*: bool
      ## RA-27 — true when ``--dry-run`` was given: the plan was computed
      ## and announced but NO mutation ran.
    plan*: seq[WorkspaceSyncPlanEntry]
      ## RA-27 — the announce-before-acting preview (one line per repo).
    manifestLayers*: seq[WorkspaceSyncManifestLayerEntry]
    repos*: seq[WorkspaceSyncRepoEntry]
    materialized*: seq[MaterializedFileEntry]
      ## RA-18 — copyfile/linkfile dests materialized after the checkout
      ## phase (idempotent; re-applied on every sync).
    exitCode*: int

  WorkspaceSyncOutcome* = object
    report*: WorkspaceSyncReport

type
  WorkspaceSyncSummary* = object
    ## RA-27 — the scannable per-repo digest at the end of a sync. Counts
    ## are derived from the per-repo execution statuses + actions, so the
    ## digest always reflects the real run (never hardcoded).
    total*: int
    succeeded*: int   ## existing checkout updated (ff / attach / merge).
    cloned*: int      ## a newly-declared repo cloned.
    forceReset*: int  ## ``--force-sync`` overwrote a divergent/dirty repo.
    noop*: int        ## already at the locked revision / nothing to do.
    skipped*: int     ## reported but deliberately not acted on.
    cloneFailed*: int ## a newly-declared repo could not be cloned.
    refused*: int     ## refuse-and-report (dirty / locally unpublished).
    failed*: int      ## a mutating action failed.

proc summarize*(report: WorkspaceSyncReport): WorkspaceSyncSummary =
  result.total = report.repos.len
  for entry in report.repos:
    case entry.executionStatus
    of "succeeded": inc result.succeeded
    of "cloned": inc result.cloned
    of "skipped": inc result.skipped
    of "clone_failed": inc result.cloneFailed
    of "refused": inc result.refused
    of "failed": inc result.failed
    of "noop":
      if entry.action == "force_reset": inc result.forceReset
      else: inc result.noop
    else:
      # Force-reset surfaces as a non-"noop" status path; count it via the
      # action tag so it is not silently dropped from the digest.
      if entry.action == "force_reset": inc result.forceReset
      else: inc result.noop

proc toJsonNode*(summary: WorkspaceSyncSummary): JsonNode =
  result = newJObject()
  result["total"] = %summary.total
  result["succeeded"] = %summary.succeeded
  result["cloned"] = %summary.cloned
  result["forceReset"] = %summary.forceReset
  result["noop"] = %summary.noop
  result["skipped"] = %summary.skipped
  result["cloneFailed"] = %summary.cloneFailed
  result["refused"] = %summary.refused
  result["failed"] = %summary.failed

proc toJsonNode*(report: WorkspaceSyncReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  var scope = newJArray()
  for name in report.scopeProjects:
    scope.add(%name)
  result["scopeProjects"] = scope
  result["dryRun"] = %report.dryRun
  var plan = newJArray()
  for entry in report.plan:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["fetchUrl"] = %entry.fetchUrl
    obj["intendedAction"] = %entry.intendedAction
    obj["revision"] = %entry.revision
    plan.add(obj)
  result["plan"] = plan
  var layers = newJArray()
  for entry in report.manifestLayers:
    var obj = newJObject()
    obj["index"] = %entry.index
    obj["provenance"] = %entry.provenance
    obj["layerPath"] = %entry.layerPath
    obj["status"] = %entry.status
    obj["beforeSha"] = %entry.beforeSha
    obj["afterSha"] = %entry.afterSha
    obj["diagnostic"] = %entry.diagnostic
    layers.add(obj)
  result["manifestLayers"] = layers
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["syncCase"] = %entry.syncCase
    obj["action"] = %entry.action
    obj["expected"] = %entry.expected
    obj["observed"] = %entry.observed
    obj["branch"] = %entry.branch
    obj["message"] = %entry.message
    obj["refusalReason"] = %entry.refusalReason
    obj["executionStatus"] = %entry.executionStatus
    obj["executionDiagnostic"] = %entry.executionDiagnostic
    obj["forcePushedBaseSha"] = %entry.forcePushedBaseSha
    repos.add(obj)
  result["repos"] = repos
  var materialized = newJArray()
  for entry in report.materialized:
    var obj = newJObject()
    obj["repo"] = %entry.repo
    obj["kind"] = %entry.kind
    obj["src"] = %entry.src
    obj["dest"] = %entry.dest
    obj["status"] = %entry.status
    obj["diagnostic"] = %entry.diagnostic
    materialized.add(obj)
  result["materialized"] = materialized
  result["summary"] = report.summarize().toJsonNode()
  result["exitCode"] = %report.exitCode

proc renderSyncPlanLines*(report: WorkspaceSyncReport): seq[string] =
  ## RA-27 Principle 1: ANNOUNCE the plan before acting. One scope header
  ## line plus one line per participating repo naming the intended action.
  ## Printed BEFORE any per-repo result so the user/agent sees what the
  ## command is about to do (and, under ``--dry-run``, all it will do).
  let scopeDesc =
    if report.scopeProjects.len > 0:
      "project(s) " & report.scopeProjects.join(", ")
    else: "the whole workspace"
  let prefix = if report.dryRun: "workspace sync (dry-run): "
               else: "workspace sync plan: "
  result.add(prefix & "will reconcile " & $report.plan.len &
    " repo(s) across " & scopeDesc)
  for entry in report.plan:
    result.add(prefix & "  [" & entry.intendedAction & "] " & entry.path &
      " (" & entry.name & ")" &
      (if entry.revision.len > 0: " @ " & entry.revision else: "") &
      (if entry.fetchUrl.len > 0: " <- " & entry.fetchUrl else: ""))
  if report.dryRun:
    result.add(
      "workspace sync (dry-run): no repos were modified " &
      "(re-run without --dry-run to apply)")

proc renderSyncSummaryLines*(report: WorkspaceSyncReport): seq[string] =
  ## RA-27 Principle 1: end with a scannable per-repo digest the human can
  ## scan and an agent can parse — counts, not a wall of raw git output.
  let s = report.summarize()
  result.add("workspace sync summary: " &
    "updated " & $s.succeeded & ", cloned " & $s.cloned &
    ", force-reset " & $s.forceReset & ", up-to-date " & $s.noop &
    ", skipped " & $s.skipped &
    (if s.cloneFailed > 0: ", CLONE FAILED " & $s.cloneFailed else: "") &
    ", refused " & $s.refused &
    ", failed " & $s.failed & " (" & $s.total & " repo(s))")

proc renderSyncTextLines*(report: WorkspaceSyncReport;
    verbose = false): seq[string] =
  result.add(renderSyncPlanLines(report))
  if report.dryRun:
    # ``--dry-run`` announces the plan and stops; there are no per-repo
    # results or summary to render (nothing was executed).
    return
  for entry in report.manifestLayers:
    result.add("workspace sync: manifest-layer " & entry.provenance &
      " status=" & entry.status &
      (if entry.beforeSha.len > 0 and entry.afterSha.len > 0 and
          entry.beforeSha != entry.afterSha:
        " " & entry.beforeSha & " → " & entry.afterSha
       else: ""))
  for entry in report.repos:
    # RA-27 live-progress digest line per repo (the same per-repo motion the
    # engine emits as actions complete; here it is the final, ordered form).
    var line = "workspace sync: " & entry.path & " case=" & entry.syncCase &
      " action=" & entry.action
    if entry.executionStatus.len > 0 and entry.executionStatus != "noop":
      line.add(" → " & entry.executionStatus)
    if entry.refusalReason.len > 0:
      line.add(" (" & entry.refusalReason & ")")
    elif entry.message.len > 0:
      line.add(" — " & entry.message)
    result.add(line)
    if verbose and entry.executionDiagnostic.len > 0:
      # RA-27 ``--verbose``: surface the raw tool diagnostic behind the flag
      # so the default output stays a legible digest.
      result.add("    | " & entry.executionDiagnostic)
  result.add(renderSyncSummaryLines(report))

type
  WorkspaceSyncArgs = object
    workspaceRoot: string
    projectName: string
    scopeProjects: seq[string]
      ## RA-27 scoped sync. When non-empty, sync ONLY the union of these
      ## named projects' repos (each resolved from
      ## ``.repo/manifests/projects/<name>.toml`` / ``variants/<name>.toml``);
      ## an unknown name is a clear error. Empty = whole-workspace sync
      ## (the pre-RA-27 behavior). ``projectName`` retains the single-project
      ## resolution dispatch for a workspace that lacks a composed
      ## ``workspace.toml``; when ``scopeProjects`` is set the first entry
      ## also seeds ``projectName`` for that dispatch.
    toolProvisioning: ToolProvisioningMode
    jobs: int            ## ``--jobs``/``-j``: default for both phases (0 = auto).
    jobsNetwork: int     ## ``--jobs-network``: vcs/fetch pool capacity (0 = auto).
    jobsCheckout: int    ## ``--jobs-checkout``: checkout (CPU) parallelism (0 = auto).
    noInterleaved: bool  ## ``--no-interleaved``: explicit fetch→checkout barrier.
    failFast: bool       ## ``--fail-fast``: stop on first fetch failure.
    forceSync: bool      ## ``--force-sync``: OVERWRITE divergent/dirty checkouts (RA-16).
    rebaseOnForcePush: bool ## ``--rebase-on-force-push``: rebase local commits on force push.
    assumeYes: bool      ## ``--yes``/``--force``: skip the destructive-action confirmation.
    dryRun: bool         ## RA-27 ``--dry-run``: print the plan and exit WITHOUT mutating.
    json: bool           ## RA-27 ``--json``: machine surface (plan + per-repo results).
    verbose: bool        ## RA-27 ``--verbose``/``-v``: include raw tool output diagnostics.
    includeTags: seq[string]
      ## RA-18 ``--tags=a,b``: only repos carrying one of these tags (plus the
      ## implicit ``default`` rule) are synced. Empty = no tag filter.
    excludeTags: seq[string]
      ## RA-18 ``--tags=-a`` / ``-a`` entries: repos carrying any of these tags
      ## are excluded (exclusion wins over inclusion).
    report: ReportSpec   ## Opt-in ``--write-report[=PATH]`` artifact.

const
  SyncDefaultJobsNetwork = 8
    ## ``repo``-equivalent default network concurrency when neither
    ## ``--jobs`` nor ``--jobs-network`` is given. Bounded (not
    ## ``countProcessors()``) because each fetch is network-bound, not
    ## CPU-bound: oversubscribing the network rarely helps and risks
    ## upstream rate-limiting.

proc resolveJobs(explicit, jobsDefault, fallback: int): int =
  ## ``--jobs-network`` / ``--jobs-checkout`` resolution order (RA-5c,
  ## mirroring ``repo``'s ``--jobs`` baseline): the phase-specific flag
  ## wins, then the shared ``--jobs`` default, then the built-in
  ## fallback. The result is clamped to ``>= 1``.
  let chosen =
    if explicit > 0: explicit
    elif jobsDefault > 0: jobsDefault
    else: fallback
  max(1, chosen)

proc parseSyncJobsValue(raw, flag: string): int =
  ## Parse a positive integer jobs value, raising a clear error rather
  ## than silently coercing. ``0`` is rejected (use "omit the flag" for
  ## auto) so a typo like ``--jobs-network=0`` doesn't quietly disable
  ## the pool bound.
  var value: int
  try:
    value = parseInt(raw.strip())
  except ValueError:
    raise newException(ValueError,
      flag & " expects a positive integer, got: " & raw)
  if value <= 0:
    raise newException(ValueError,
      flag & " expects a positive integer, got: " & raw)
  value

proc parseWorkspaceSyncArgs(args: openArray[string]): WorkspaceSyncArgs =
  ## ``repro workspace sync`` argv parser. Unlike M9's ``init`` there is
  ## no required positional: sync operates on the existing workspace
  ## root. An optional positional ``<project>`` is accepted so the
  ## non-composer (M6 / M7) path still works in a workspace that lacks
  ## a ``.repo/workspace.toml`` — the milestone spec says sync works on
  ## "the existing workspace", which in single-project mode requires
  ## the project name to find ``projects/<name>.toml``.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  result.rebaseOnForcePush = true
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--jobs" or arg == "-j" or arg.startsWith("--jobs="):
      result.jobs = parseSyncJobsValue(valueFromFlag(args, i, "--jobs"), "--jobs")
    elif arg == "--jobs-network" or arg.startsWith("--jobs-network="):
      result.jobsNetwork = parseSyncJobsValue(
        valueFromFlag(args, i, "--jobs-network"), "--jobs-network")
    elif arg == "--jobs-checkout" or arg.startsWith("--jobs-checkout="):
      result.jobsCheckout = parseSyncJobsValue(
        valueFromFlag(args, i, "--jobs-checkout"), "--jobs-checkout")
    elif arg == "--tags" or arg.startsWith("--tags="):
      # RA-18 subset selection. A comma-separated list; an entry prefixed
      # with ``-`` (e.g. ``--tags=default,-heavy``) is an EXCLUDE term,
      # otherwise an INCLUDE term. Mirrors ``repo``'s ``--groups`` syntax,
      # under the word the membership model left free for a filter.
      for raw in valueFromFlag(args, i, "--tags").split(','):
        let term = raw.strip()
        if term.len == 0:
          continue
        if term.startsWith("-"):
          let t = term[1 .. ^1]
          if t.len > 0:
            result.excludeTags.add(t)
        else:
          result.includeTags.add(term)
    elif arg == "--no-interleaved":
      result.noInterleaved = true
    elif arg == "--fail-fast":
      result.failFast = true
    elif arg == "--force-sync":
      result.forceSync = true
    elif arg == "--rebase-on-force-push":
      result.rebaseOnForcePush = true
    elif arg == "--no-rebase-on-force-push":
      result.rebaseOnForcePush = false
    elif arg == "--yes" or arg == "--force":
      result.assumeYes = true
    elif arg == "--dry-run":
      result.dryRun = true
    elif arg == "--json":
      result.json = true
    elif arg == "--verbose" or arg == "-v":
      result.verbose = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace sync` flag: " & arg)
    else:
      # RA-27: one or more positional ``<project>`` arguments SCOPE the sync
      # to those projects' repos. The first one also seeds ``projectName``
      # so the single-project resolution dispatch (workspaces with no
      # composed ``workspace.toml``) keeps working; the full list drives the
      # scoped-repo filter in ``resolveWorkspaceSyncProject``.
      if result.projectName.len == 0:
        result.projectName = arg
      result.scopeProjects.add(arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

const
  LegacyRepoMigrationMarkerBody = "reprobuild migration complete\n"
    ## Exact sentinel written by repo-workspaces v2.10 after its one-time
    ## Reprobuild hook/cache migration. It is deliberately narrower than a
    ## generic ``.repo`` compatibility switch: only an already-migrated
    ## workspace may use the legacy location as a read-only project-selection
    ## artifact.

proc legacyMigratedWorkspaceProjectName(workspaceRoot: string): string =
  ## Compatibility seam for workspaces migrated by repo-workspaces v2.10
  ## before Reprobuild's native-layout cutover. That migration recorded the
  ## active project set in ``.repo/workspace.toml`` and its completion marker
  ## in ``.repo/.repro-migration-complete``; the later native layout moved
  ## canonical metadata to ``.repro/workspace.toml`` and membership to the
  ## workspace root.
  ##
  ## Keep native layout authoritative. This helper supplies ONLY the primary
  ## project name, and only when:
  ##   * native root-level membership is present;
  ##   * both legacy artifacts are regular, non-symlink files;
  ##   * the completion marker has the exact producer-written body;
  ##   * the legacy metadata passes the strict WorkspaceLocal reader; and
  ##   * that project exists in native root-level membership.
  ##
  ## It never composes or resolves content from ``.repo/manifests``. A stray
  ## ``.repo`` directory, an incomplete migration, or a malformed artifact
  ## therefore cannot expand the workspace's trust or membership boundary.
  let nativeProjects = workspaceRoot / "projects"
  let nativeVariants = workspaceRoot / "variants"
  if not dirExists(nativeProjects) and not dirExists(nativeVariants):
    return ""
  let legacyRoot = workspaceRoot / ".repo"
  let marker = legacyRoot / ".repro-migration-complete"
  let metadata = legacyRoot / "workspace.toml"
  try:
    if getFileInfo(marker, followSymlink = false).kind != pcFile or
        readFile(marker) != LegacyRepoMigrationMarkerBody:
      return ""
    if getFileInfo(metadata, followSymlink = false).kind != pcFile:
      return ""
    let recorded =
      readWorkspaceLocal(absolutePath(metadata)).workspace.project
    if recorded.len == 0:
      return ""
    let projectFile = nativeProjects / (recorded & ".toml")
    let variantFile = nativeVariants / (recorded & ".toml")
    if not fileExists(projectFile) and not fileExists(variantFile):
      return ""
    return recorded
  except CatchableError:
    return ""

proc resolveWorkspaceProjectShared*(workspaceRoot, projectName, opLabel: string):
    tuple[resolved: ResolvedProject; workspaceLocal: Option[WorkspaceLocal]] =
  ## MO-9 — the ONE membership-resolution ladder shared by ``sync`` / ``pull``
  ## / ``check`` / the pre-push gate. It collapses the previously hand-
  ## duplicated dispatch (compositional ``.repo/workspace.toml`` composer ->
  ## committed-lock-derived fallback -> named manifest project / variant) into a
  ## single seam. ``opLabel`` only flavors the not-a-workspace error message;
  ## the resolution itself is byte-identical across the callers.
  ##
  ## The compositional branch also returns the parsed ``WorkspaceLocal`` so the
  ## gate / check can reuse it (active-branch derivation, manifest-layer root);
  ## the non-compositional branches return ``none`` exactly as before.
  let workspaceToml = workspaceTomlPath(workspaceRoot)
  if isCompositionalWorkspaceToml(workspaceRoot):
    let absToml = absolutePath(workspaceToml)
    let wl = readWorkspaceLocal(absToml)
    # PS-2 — layers compose WITHIN the project; the active project set unions
    # ACROSS projects. Both axes apply, layers first.
    return (extendWithActiveProjectSet(workspaceRoot,
      composeManifestLayers(wl, workspaceRoot, absToml)), some(wl))
  # MO-2 — manifest-optional fallback. When there is no resolved manifest
  # checkout (and no compositional workspace.toml, handled above), a
  # committed-lock-only workspace resolves its participating repo set from
  # repo-local state (now via the committed-lock ``populateLockedDeps`` source)
  # instead of raising. Fires ONLY when no manifest data is on disk, so every
  # manifest-present path below is byte-unchanged.
  if not hasResolvedManifestCheckout(workspaceRoot):
    let derived = committedLockDerivedProject(workspaceRoot)
    if derived.isSome:
      return (derived.get(), none(WorkspaceLocal))
  var name = projectName
  if name.len == 0:
    # A metadata-only workspace.toml (M13) can supply the project name so the
    # single-project branch resolves without the user repeating it.
    if fileExists(workspaceToml):
      try:
        let recorded =
          readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
        if recorded.len > 0: name = recorded
      except WorkspaceManifestParseError:
        discard
    else:
      # repo-workspaces v2.10 wrote its metadata immediately before the
      # native-layout cutover. Read that known migration artifact narrowly;
      # never treat arbitrary legacy `.repo` state as canonical metadata.
      name = legacyMigratedWorkspaceProjectName(workspaceRoot)
  if name.len == 0:
    raise newException(ValueError,
      opLabel & " requires either `.repro/workspace.toml` or a <project> " &
        "argument; neither was present at " & workspaceRoot)
  let manifestsRoot = manifestsRoot(workspaceRoot)
  let projectFile = manifestsRoot / "projects" / (name & ".toml")
  let variantFile = manifestsRoot / "variants" / (name & ".toml")
  # PS-2 — when the project name was NOT supplied by the caller (it came from
  # the workspace's own metadata), the question being asked is "what does this
  # WORKSPACE consist of", so the answer is the union of the active project
  # set. An explicit ``<project>`` argument still resolves that one project.
  # A single-project workspace resolves byte-identically either way.
  let membershipFromMetadata = projectName.len == 0
  proc withSet(resolved: ResolvedProject): ResolvedProject =
    if membershipFromMetadata:
      extendWithActiveProjectSet(workspaceRoot, resolved)
    else: resolved
  # Workspace-Membership-Model.md — a repo-set that is ENABLED is what used to
  # be called a project, so `repo-sets/<name>.toml` joins THIS ladder too,
  # under the same name and in the same last position `project_set.nim` gives
  # it. Without this rung a workspace whose recorded active set predates the
  # manifest repo's conversion keeps resolving through `project_set.nim` (which
  # already knows repo-sets) while sync / pull / check — the verbs that come
  # through here — fail with "no project or variant named …" for a name that is
  # perfectly resolvable. Looked up LAST, so a manifest repo mid-conversion
  # keeps preferring the project it already has and nothing resolves
  # differently until the `projects/` file is actually gone.
  let repoSetFile = manifestsRoot / repoSetsDirName / (name & ".toml")
  if fileExists(projectFile):
    return (withSet(resolveProject(projectFile)), none(WorkspaceLocal))
  if fileExists(variantFile):
    return (withSet(resolveVariant(variantFile)), none(WorkspaceLocal))
  if fileExists(repoSetFile):
    return (withSet(resolveRepoSet(repoSetFile)), none(WorkspaceLocal))
  raise newException(ValueError,
    "no repo-set, project or variant named '" & name & "' found under '" &
      manifestsRoot & "' (looked for '" & projectFile & "', '" &
      variantFile & "' and '" & repoSetFile & "')")

proc resolveWorkspaceSyncProject(parsed: WorkspaceSyncArgs): ResolvedProject =
  ## MO-9 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder
  ## (collapsed from the former per-op copies). Same dispatch rule as M9:
  ## prefer ``.repro/workspace.toml`` when it
  ## declares at least one ``[[manifest]]`` layer (composer mode),
  ## otherwise look up the named project / variant under
  ## ``projects/``. A metadata-only workspace.toml (M13 — only
  ## carrying ``[workspace].project`` / ``[workspace].branch``) is
  ## treated as single-project mode because the composer requires
  ## manifest layers. A missing workspace.toml AND a missing project
  ## argument is a structured error.
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro workspace sync`").resolved

proc resolveNamedProjectOrVariant(workspaceRoot, name: string): ResolvedProject =
  ## RA-27 scoped sync: resolve ONE named project (or variant) from the
  ## manifest layer so its repo set can scope the participating set. An
  ## unknown name is a clear, actionable error (Principle 2) naming where
  ## we looked — the spec's "unknown project name → clear error".
  let manifestsRoot = manifestsRoot(workspaceRoot)
  let projectFile = manifestsRoot / "projects" / (name & ".toml")
  let variantFile = manifestsRoot / "variants" / (name & ".toml")
  if fileExists(projectFile):
    return resolveProject(projectFile)
  if fileExists(variantFile):
    return resolveVariant(variantFile)
  raise newException(ValueError,
    "unknown project '" & name & "' passed to `repro workspace sync` " &
      "(no `projects/" & name & ".toml` or `variants/" & name &
      ".toml` under '" & manifestsRoot &
      "'); run `repro workspace sync` with no project to sync the whole " &
      "workspace, or pass a known project name")

proc scopeRepoPathSet(workspaceRoot: string;
    scopeProjects: openArray[string]): HashSet[string] =
  ## The union of repo ``path`` values declared by the named projects.
  ## ``executeWorkspaceSync`` filters the workspace's participating repo
  ## set to this union — the resolver already knows project→repos, so a
  ## scoped sync is exactly "keep only repos that belong to a named
  ## project". An unknown name raises (see ``resolveNamedProjectOrVariant``).
  result = initHashSet[string]()
  for name in scopeProjects:
    let proj = resolveNamedProjectOrVariant(workspaceRoot, name)
    for repo in proj.repos:
      result.incl(repo.path)

proc gitRunPlain(identity: GitToolIdentity;
                 args: openArray[string]): tuple[code: int; output: string] =
  ## Tiny ``execCmdEx`` wrapper used by the sync observation gatherer.
  ## Shares the same shape as ``revParse`` above but takes an argv so
  ## callers don't have to quoteShell every arg.
  when defined(windows):
    # Keep argv structured. Besides avoiding Windows command-line quoting
    # ambiguities, drain the pipe with PeekNamedPipe: Nim 2.2's readAll stops
    # after the first short pipe read on Windows. `git log --name-only`, for
    # example, then yielded only its first format marker and silently made a
    # committed lock checkout look like an unordered working-tree scan.
    let process = startProcess(identity.binaryPath, args = @args,
      env = scrubbedGitRepositoryEnv(),
      options = {poStdErrToStdOut, poUsePath})
    defer: process.close()
    const PollSleepMs = 25
    let outHandle = Handle(process.outputHandle)
    var buf {.noinit.}: array[4096, char]
    while true:
      var bytesAvail: int32 = 0
      let peeked = peekNamedPipe(outHandle,
        lpTotalBytesAvail = addr bytesAvail)
      if peeked and bytesAvail > 0:
        var bytesRead: int32 = 0
        let toRead = min(int(bytesAvail), buf.len).int32
        let ok = readFile(outHandle, addr buf[0], toRead,
          addr bytesRead, nil)
        if ok != 0 and bytesRead > 0:
          let previousLen = result.output.len
          result.output.setLen(previousLen + bytesRead)
          copyMem(addr result.output[previousLen], addr buf[0], bytesRead)
          continue
      result.code = process.peekExitCode()
      if result.code != -1:
        break
      sleep(PollSleepMs)
  else:
    var cmd = quoteShell(identity.binaryPath)
    for arg in args:
      cmd.add(" ")
      cmd.add(quoteShell(arg))
    let res = execCmdEx(cmd, options = {poStdErrToStdOut, poUsePath},
      env = scrubbedGitRepositoryEnv())
    (code: res.exitCode, output: res.output)

type
  GitWorktreeDiscovery = object
    ok: bool
    worktreeRoot: string
    commonDir: string
    diagnostic: string

  RepoWorktreeMatch = object
    found: bool
    ambiguous: bool
    repoIndex: int
    worktree: GitWorktreeDiscovery
    diagnostic: string

proc canonicalDiscoveredGitPath(repoRoot, value: string): string =
  let candidate =
    if value.isAbsolute: value
    else: repoRoot / value
  try:
    os.normalizedPath(expandFilename(candidate))
  except OSError:
    os.normalizedPath(absolutePath(candidate))

proc samePathIdentity(a, b: string): bool =
  ## Do two paths name the same directory? Compared through the same
  ## canonicalization ``discoverGitWorktree`` applies to what Git reports, so a
  ## symlinked or non-normalized spelling of one side does not read as a
  ## different directory. ``sameFile`` is not used because it raises when
  ## either side does not exist, and callers ask this question about paths Git
  ## merely *reported*.
  if a.len == 0 or b.len == 0:
    return false
  canonicalDiscoveredGitPath(a, a) == canonicalDiscoveredGitPath(b, b)

proc discoverGitWorktree(identity: GitToolIdentity;
    candidate: string): GitWorktreeDiscovery =
  ## Publication code must ask Git whether a path IS a worktree ROOT. In a
  ## linked worktree `.git` is a file, while the common directory (where
  ## capabilities live) is elsewhere; probing `dirExists(.git)` rejects that
  ## valid layout, so the question is put to Git instead.
  ##
  ## Git repository discovery walks UPWARDS, so `rev-parse --show-toplevel`
  ## answers for the nearest ANCESTOR checkout when `candidate` is a plain
  ## directory nested inside one. Every caller here treats `candidate` as a
  ## repository/backend root and then drives `git -C <candidate> …` against it
  ## (staging, committing, pushing, reading HEAD). Accepting an ancestor's
  ## answer silently retargets those commands at the WRONG repository — e.g. a
  ## workspace whose `.repro/manifests` lock layer is a plain directory inside
  ## a git-tracked workspace checkout would try to stage its locks into the
  ## workspace repo (which ignores `.repro/`) and refuse every push, instead of
  ## taking the "no publishable manifest remote" skip. So the discovered top
  ## level must be the candidate itself.
  if candidate.len == 0:
    result.diagnostic = "empty Git worktree path"
    return
  let top = gitRunPlain(identity,
    ["-C", candidate, "rev-parse", "--show-toplevel"])
  if top.code != 0 or top.output.strip().len == 0:
    result.diagnostic = "not a Git worktree: " & candidate
    return
  let common = gitRunPlain(identity,
    ["-C", candidate, "rev-parse", "--git-common-dir"])
  if common.code != 0 or common.output.strip().len == 0:
    result.diagnostic = "cannot resolve Git common directory for " & candidate
    return
  let worktreeRoot = canonicalDiscoveredGitPath(candidate, top.output.strip())
  let commonDir = canonicalDiscoveredGitPath(candidate, common.output.strip())
  if worktreeRoot.len == 0 or commonDir.len == 0:
    result.diagnostic = "cannot canonicalize Git worktree identity for " &
      candidate
    return
  # Canonicalize the candidate exactly the way the discovered paths were, so
  # symlinked / non-normalized spellings of the same directory still compare
  # equal. `cmpPaths` is case-insensitive on case-insensitive filesystems.
  let canonicalCandidate = canonicalDiscoveredGitPath(candidate, candidate)
  if cmpPaths(canonicalCandidate, worktreeRoot) != 0:
    result.diagnostic = "not a Git worktree root: " & candidate &
      " (it is a plain directory inside the Git worktree at " &
      worktreeRoot & ")"
    return
  result.worktreeRoot = worktreeRoot
  result.commonDir = commonDir
  result.ok = true

proc configuredRemoteDigests(identity: GitToolIdentity;
    repoRoot: string): HashSet[string] =
  ## Repository identity may need a remote fallback when the workspace's
  ## canonical checkout is absent. Keep URLs out of diagnostics and compare the
  ## same credential-insensitive canonical digests used by protocol v2.
  result = initHashSet[string]()
  let remotes = gitRunPlain(identity, ["-C", repoRoot, "remote"])
  if remotes.code != 0:
    return
  for rawName in remotes.output.splitLines():
    let name = rawName.strip()
    if name.len == 0:
      continue
    let urls = gitRunPlain(identity,
      ["-C", repoRoot, "remote", "get-url", "--all", name])
    if urls.code != 0:
      continue
    for rawUrl in urls.output.splitLines():
      let value = rawUrl.strip()
      if value.len > 0:
        result.incl(remoteLocationDigest(value))

proc expectedRemoteDigests(repo: ResolvedRepo): HashSet[string] =
  result = initHashSet[string]()
  for value in [repo.fetchUrl, cloneUrlFor(repo)]:
    if value.len > 0:
      result.incl(remoteLocationDigest(value))
  for remote in repo.remotes:
    if remote.fetchUrl.len > 0:
      result.incl(remoteLocationDigest(remote.fetchUrl))

proc sharesRemoteIdentity(actual, expected: HashSet[string]): bool =
  for digest in actual:
    if digest in expected:
      return true

proc resolveRepoWorktreeMatch(identity: GitToolIdentity;
    workspaceRoot: string; repos: openArray[ResolvedRepo];
    currentRepo: string): RepoWorktreeMatch =
  ## Resolve a hook's checkout to one manifest repo without using a basename or
  ## project/repo name. Linked worktrees have different top-level paths but the
  ## same Git common directory as the workspace checkout; that is the primary
  ## identity. A unique manifest-remote match is the conservative fallback for
  ## a valid checkout whose canonical workspace worktree is absent.
  result.repoIndex = -1
  result.worktree = discoverGitWorktree(identity, currentRepo)
  if not result.worktree.ok:
    result.diagnostic = result.worktree.diagnostic
    return

  var pathMatches: seq[int]
  var commonMatches: seq[int]
  var missingDeclaredWorktrees = initHashSet[int]()
  for index, repo in repos:
    let declaredPath = workspaceRoot / repo.path
    if samePathIdentity(result.worktree.worktreeRoot, declaredPath):
      pathMatches.add(index)
      continue
    let declaredWorktree = discoverGitWorktree(identity, declaredPath)
    if declaredWorktree.ok:
      if samePathIdentity(result.worktree.commonDir, declaredWorktree.commonDir):
        commonMatches.add(index)
    elif not dirExists(declaredPath) and not fileExists(declaredPath) and
        not symlinkExists(declaredPath):
      # Remote identity is a recovery path for an ABSENT declared checkout,
      # not for one that exists but Git cannot validate. A present plain
      # directory, broken worktree, unreadable checkout, or dangling symlink
      # is workspace corruption; letting an arbitrary same-remote clone stand
      # in for it would turn a failed structural check into authorization.
      missingDeclaredWorktrees.incl(index)

  let structural = if pathMatches.len > 0: pathMatches else: commonMatches
  if structural.len == 1:
    result.found = true
    result.repoIndex = structural[0]
    return
  if structural.len > 1:
    result.ambiguous = true
    result.diagnostic = "more than one declared repo shares the pushed " &
      "worktree's filesystem identity"
    return

  let actualRemotes = configuredRemoteDigests(identity,
    result.worktree.worktreeRoot)
  if actualRemotes.len == 0:
    result.diagnostic = "the pushed worktree has no configured remote identity"
    return
  var remoteMatches: seq[int]
  for index, repo in repos:
    # A URL match is only a fallback for a manifest checkout that is absent.
    # When the declared checkout exists with a different Git common directory,
    # an arbitrary second clone of the same forge repository is not that
    # workspace member. Treating it as one lets an explicit managed-hook root
    # escape the workspace's structural identity boundary.
    if index in missingDeclaredWorktrees and
        sharesRemoteIdentity(actualRemotes, expectedRemoteDigests(repo)):
      remoteMatches.add(index)
  if remoteMatches.len == 1:
    result.found = true
    result.repoIndex = remoteMatches[0]
  elif remoteMatches.len > 1:
    result.ambiguous = true
    result.diagnostic = "more than one declared repo matches the pushed " &
      "worktree's configured remote identity"
  else:
    result.diagnostic = "the pushed worktree does not match a declared repo " &
      "by path, Git common directory, or configured remote"

# ---- RA-1: per-repo lock resolution via Git history ------------------------
#
# RA-1 dropped the shared ``locks/<project>/index.toml`` mapping. The
# "latest published lock for repo X" lookup is now a Git-history query
# over the per-repo lock subtree (``git log -1 -- locks/<project>/<repo>/``)
# rather than a read of a mutable index. The resolver walks first-parent
# ancestry to the nearest locked commit when an exact commit has no lock
# yet, and falls back to a working-tree filesystem scan for locks that
# have been written but not yet committed (the common case while
# ``repro check`` / ``repro workspace status`` run against a freshly
# written lock).

type
  LockCandidate = object
    relPath: string   ## manifest-layer-relative, forward slashes
    committed: bool    ## true when the file is reachable from HEAD
    commitOrder: int   ## position in `git log` (0 = newest); -1 when uncommitted

  ExpectedLockRecord* = object
    ## The operation-specific immutable coordinate. `relPath` alone is not an
    ## identity: a syntactically valid record for another repository can be
    ## transplanted under a matching lock filename unless name, manifest path,
    ## and object id are all bound here before verification begins.
    project*: string
    repoName*: string
    repoPath*: string
    oid*: string
    relPath*: string

proc orderedLockCandidates(identity: GitToolIdentity;
    manifestLayerRoot, lockPrefix: string): seq[LockCandidate] =
  ## Return the lock files under ``lockPrefix`` ordered newest-first.
  ## Committed locks are ordered by first-parent ``git log`` recency
  ## (the exact ordering source the spec names); uncommitted
  ## working-tree locks sort ahead of every committed one (a lock just
  ## written by the current operation is "newer" than anything in
  ## history). ``lockPrefix`` carries a trailing slash.
  let isGit = discoverGitWorktree(identity, manifestLayerRoot).ok
  var committedOrder = initTable[string, int]()
  if isGit:
    # `git log --first-parent --name-only` over the subtree yields the
    # touched lock paths newest-commit-first; the first time we see a
    # path fixes its recency rank.
    let logRes = gitRunPlain(identity,
      ["-C", manifestLayerRoot, "log", "--first-parent",
       "--format=%x01", "--name-only", "--", lockPrefix])
    if logRes.code == 0:
      var rank = 0
      for raw in logRes.output.splitLines():
        let p = raw.strip()
        if p.len == 0 or p == "\x01":
          continue
        # Ignore any legacy ``index.toml`` left in older manifest
        # history (RA-1: never written, never resolved).
        if p.startsWith(lockPrefix) and p.endsWith(".toml") and
            extractFilename(p) != "index.toml":
          if p notin committedOrder:
            committedOrder[p] = rank
            inc rank
  # Working-tree scan: enumerate every on-disk lock under the subtree,
  # including not-yet-committed ones.
  let subtreeAbs = manifestLayerRoot / lockPrefix.replace('/', DirSep)
  var seen = initHashSet[string]()
  var uncommitted: seq[string]
  if dirExists(subtreeAbs):
    for path in walkDirRec(subtreeAbs):
      if not path.endsWith(".toml"):
        continue
      let base = extractFilename(path)
      if base == "index.toml":
        continue
      var rel = path
      if rel.startsWith(manifestLayerRoot):
        rel = rel[manifestLayerRoot.len .. ^1]
      rel = rel.strip(chars = {'/', '\\'}).replace('\\', '/')
      seen.incl(rel)
      if rel notin committedOrder:
        uncommitted.add(rel)
  # Uncommitted first (deterministic order), then committed by recency.
  uncommitted.sort()
  for rel in uncommitted:
    result.add(LockCandidate(relPath: rel, committed: false, commitOrder: -1))
  var committed: seq[(int, string)]
  for rel, rank in committedOrder:
    # Skip committed entries whose file was deleted in the working tree
    # but still appears in history; only surface files we can read.
    if fileExists(manifestLayerRoot / rel.replace('/', DirSep)):
      committed.add((rank, rel))
  committed.sort(proc (a, b: (int, string)): int = cmp(a[0], b[0]))
  for (_, rel) in committed:
    result.add(LockCandidate(relPath: rel, committed: true, commitOrder: 0))

proc parseTriggerFromLockRelPath*(relPath: string):
    tuple[repo: string; sha: string] =
  ## Decompose a per-repo lock path
  ## ``locks/<project>/<repo>/<sha>.toml`` into its trigger repo and
  ## trigger SHA (the filename stem). Returns empty strings when the
  ## path does not match the RA-1 layout. Forward slashes expected.
  ##
  ## RA-32 — this used to accept ``parts.len < 4`` (i.e. FOUR OR MORE) and
  ## then read ``parts[^2]``, while four other call sites required exactly
  ## four. That disagreement is why a record written one level too deep was
  ## accepted here — silently reporting ``sync-engine`` as the trigger repo
  ## of a record belonging to ``stripe/sync-engine`` — and refused much later
  ## at publish, with a diagnostic pointing at the publisher rather than at
  ## the write. All five now share ``parseLockRecordRelPath``.
  let parsed = parseLockRecordRelPath(relPath)
  if not parsed.ok:
    return ("", "")
  (repo: parsed.repo, sha: parsed.sha)

proc latestLockRelPathForRepoViaGit*(identity: GitToolIdentity;
    manifestLayerRoot, project, repo: string): string =
  ## RA-1 per-repo "latest lock" query: the manifest-layer-relative
  ## path (forward slashes) of the newest lock under
  ## ``locks/<project>/<repo>/`` by Git first-parent history, falling
  ## back to a working-tree scan for an as-yet-uncommitted lock.
  ## Returns "" when no lock exists for the repo. This is the resolver
  ## the dropped ``index.toml`` used to back; it reads **no** index.
  let lockPrefix = lockRepoSubtreeRelativePath(project, repo)
  let candidates = orderedLockCandidates(identity, manifestLayerRoot, lockPrefix)
  if candidates.len == 0:
    return ""
  candidates[0].relPath

proc latestLockShasViaGit(identity: GitToolIdentity;
    manifestLayerRoot, project: string): tuple[
      shas: Table[string, string]; lockRelPath: string] =
  ## Overall "latest lock" map for ``repro check`` stage 5 / ``repro
  ## workspace status``: the ``path -> revision`` contents of the newest
  ## lock file across **all** per-repo subtrees of ``project``, located
  ## via Git history (uncommitted working-tree locks counted as newest).
  ## Returns an empty table + "" when no lock exists. Replaces the
  ## former index-backed ``readLatestLockedShasByPath``.
  result.shas = initTable[string, string]()
  # RA-32 — the PROJECT is a name too, and the writer encodes it into one path
  # component. A raw join here reads a prefix nothing was ever written under, so
  # for any project name outside ``[A-Za-z0-9._-]`` this query silently answered
  # "no lock" and `repro check` stage 5 / `repro workspace status` saw none.
  let lockPrefix = "locks/" & encodeLockPathSegment(project) & "/"
  let candidates = orderedLockCandidates(identity, manifestLayerRoot, lockPrefix)
  if candidates.len == 0:
    return
  # Merge ``path -> revision`` across every candidate newest-first, so BOTH
  # lock shapes populate the map:
  #   * the monolithic all-repos lock — a single newest file carrying every
  #     repo (the no-explicit-route ``.repo/manifests`` default), and
  #   * the HL-2 tier-routed records — one minimal file per repo under
  #     ``locks/<project>/<repo>/`` written by the git-checkout backend.
  # ``shasFromBody`` (repro_lock_store) tolerates both the full-schema lock
  # body and the schema-less ``[[repo]]`` backend record; the strict
  # ``readLock`` rejects the latter (``double bracket not allowed`` on a
  # schema-less body), so it must NOT be used here — doing so crashed
  # ``status`` / ``check`` / ``sync`` once a workspace adopted the manifest as
  # its team backend. Newest-first with "first writer wins per path" keeps the
  # most recent revision for each repo.
  for cand in candidates:
    let lockPath = manifestLayerRoot / cand.relPath.replace('/', DirSep)
    if not fileExists(extendedPath(lockPath)):
      continue
    let body =
      try: readFile(extendedPath(lockPath))
      except CatchableError: ""
    for path, rev in shasFromBody(body):
      if path notin result.shas:
        result.shas[path] = rev
  result.lockRelPath = candidates[0].relPath

# ---------------------------------------------------------------------------
# Lock coherence — a DIFF, not a solve.
#
# A workspace can hold several locks that each claim a revision for the same
# node: every participating repo may carry its own committed ``repro.lock``, and
# the manifests DB carries the private pins. Nothing forces those claims to
# agree with each other, or with what is actually checked out.
#
# The solver's job is to FIND a set of revisions that satisfies every
# constraint. This check does something far simpler and correspondingly
# cheaper: it collects what each lock claims, compares that to the checked-out
# HEAD, and reports where they disagree. No solve, no network, a bounded number
# of local git queries — so it is affordable on every ``sync`` / ``status`` /
# ``check``, and it is naturally ADVISORY. It never blocks and never mutates.
#
# The classification is by REACHABILITY, because that is what decides whether a
# disagreement is a problem:
#   * ancestor    — the claim is behind the checkout. The lock lags; the
#                   checkout is a superset of what the lock describes.
#   * descendant  — the claim is ahead of the checkout. A fast-forward closes
#                   it.
#   * unreachable — the claim and the checkout are on divergent histories.
#                   Nothing cheap reconciles them.
#   * not-fetched — the claimed object is not in the checkout at all, so the
#                   relationship cannot even be evaluated.
# Only the last two normally warrant interrupting the operator. The first two
# are information: a lagging lock is the NORMAL state of a repo under active
# development.
#
# Whose claim wins is stated plainly rather than left to inference: in develop
# mode the CHECKOUT is what the build reads. A lock that disagrees is a stale
# record, not an override.
# ---------------------------------------------------------------------------

type
  CoherenceRelation* = enum
    ## How a lock's claimed revision relates to the checked-out HEAD.
    crMatch = "match"
    crAncestor = "ancestor"
    crDescendant = "descendant"
    crUnreachable = "unreachable"
    crNotFetched = "not-fetched"
    crNoCheckout = "no-checkout"

  LockClaim* = object
    ## One lock's claim about one node.
    node*: string        ## the node identity the claim is about
    revision*: string    ## the revision it claims
    source*: string      ## operator-facing origin ("lib-a/repro.lock", …)
    relation*: CoherenceRelation

  CoherenceFinding* = object
    ## One node about which at least one lock disagrees with reality.
    node*: string
    path*: string          ## workspace-relative checkout path
    checkoutHead*: string  ## observed HEAD ("" when nothing is checked out)
    branch*: string        ## checked-out branch ("" when detached/absent)
    claims*: seq[LockClaim]
    claimsDisagree*: bool  ## two or more locks claim DIFFERENT revisions
    interrupting*: bool    ## unreachable / not-fetched / no-checkout
    remedies*: seq[string] ## cheapest first

  CoherenceReport* = object
    workspaceRoot*: string
    findings*: seq[CoherenceFinding]
    interrupting*: int
    informational*: int

proc relationTag*(r: CoherenceRelation): string = $r

proc sameRevision(a, b: string): bool =
  ## Revision equality that tolerates an abbreviated prefix on either side —
  ## a lock may legitimately carry an abbreviation. An empty side matches
  ## NOTHING, which is what lets the caller distinguish "no claim" from a hit.
  if a.len == 0 or b.len == 0: return false
  if a == b: return true
  a.startsWith(b) or b.startsWith(a)

proc objectPresent(identity: GitToolIdentity; repoPath, sha: string): bool =
  ## ``cat-file -e <sha>^{commit}`` exits 0 only when the object is present AND
  ## peels to a commit. A blobless/partial clone still has the commit object, so
  ## this correctly answers "can I reason about this revision locally".
  if sha.len == 0 or not looksLikeSha(sha):
    return false
  gitRunPlain(identity,
    ["-C", repoPath, "cat-file", "-e", sha & "^{commit}"]).code == 0

proc isAncestorOf(identity: GitToolIdentity;
                  repoPath, maybeAncestor, descendant: string): bool =
  gitRunPlain(identity, ["-C", repoPath, "merge-base", "--is-ancestor",
    maybeAncestor, descendant]).code == 0

proc classifyClaim(identity: GitToolIdentity;
                   repoPath, claimed, head: string): CoherenceRelation =
  if head.len == 0:
    return crNoCheckout
  if claimed.len == 0:
    return crMatch
  if sameRevision(claimed, head):
    return crMatch
  if not objectPresent(identity, repoPath, claimed):
    return crNotFetched
  if isAncestorOf(identity, repoPath, claimed, head):
    return crAncestor
  if isAncestorOf(identity, repoPath, head, claimed):
    return crDescendant
  crUnreachable

proc coherenceRemedies(finding: CoherenceFinding): seq[string] =
  ## Cheapest first. Every entry is something the operator can actually run;
  ## the ordering is the cost of doing it, not the tidiness of the result.
  var worst = crMatch
  for claim in finding.claims:
    if ord(claim.relation) > ord(worst):
      worst = claim.relation
  case worst
  of crMatch:
    @[]
  of crDescendant:
    @["`repro sync` — the checkout is behind the claim and fast-forwards to it"]
  of crAncestor:
    @["nothing, if the lock is simply older than your work",
      "`repro workspace lock` — re-pin the lagging lock at the checkout"]
  of crNotFetched:
    @["`repro sync` — fetch the claimed revision so it can be compared",
      "`repro workspace lock` — re-pin the lock at the checkout if the claimed " &
        "revision is gone for good"]
  of crUnreachable:
    @["`repro workspace lock` — re-pin the lagging lock at the checkout, if the " &
        "checkout is the history you want",
      "`git -C " & finding.path & " checkout <locked-revision>` — point the " &
        "checkout at the locked revision instead",
      "materialize a second checkout and `repro develop --into` it — last " &
        "resort, when both revisions must exist at once"]
  of crNoCheckout:
    @["`repro sync` — materialize the missing checkout"]

proc collectLockCoherence*(identity: GitToolIdentity;
                           workspaceRoot: string;
                           repos: openArray[ResolvedRepo];
                           manifestLayerRoot, project: string):
                          CoherenceReport =
  ## The one shared read-only implementation behind ``sync`` / ``status`` /
  ## ``check``. Read-only in the strict sense: it runs only git QUERIES and
  ## writes nothing.
  ##
  ## A private pin is NOT a special case. The diff is identical whether the
  ## claim came from a committed ``repro.lock`` or from the manifests DB — only
  ## the ``source`` label differs. On a feature branch that bumped a private
  ## revision there is nowhere branch-local to record the bump, so this will
  ## report a discrepancy that no remedy clears. That is the honest output: it
  ## surfaces a modeling gap instead of hiding it behind a special case.
  result.workspaceRoot = workspaceRoot

  # Claim source 1: the manifests DB (the private-pin lock).
  var dbClaims = initTable[string, string]()
  var dbSource = ""
  if manifestLayerRoot.len > 0 and project.len > 0:
    try:
      let latest = latestLockShasViaGit(identity, manifestLayerRoot, project)
      dbClaims = latest.shas
      if latest.lockRelPath.len > 0:
        dbSource = latest.lockRelPath
    except CatchableError:
      discard

  # Claim source 2: every participating repo's own committed lock. Keyed by the
  # dep's workspace-relative path so a claim lines up with a checkout.
  var repoClaims = initTable[string, seq[LockClaim]]()
  for repo in repos:
    let lockPath = committedLockPath(workspaceRoot / repo.path)
    if not fileExists(extendedPath(lockPath)):
      continue
    var parsed: LockedDependencies
    try:
      parsed = parseLockedDependencies(readFile(extendedPath(lockPath)))
    except CatchableError:
      # A lock we cannot parse is not a coherence question; the lock verbs
      # already report malformed locks loudly.
      continue
    for dep in parsed.deps:
      if dep.coordinates.kind != ckVcs: continue
      if dep.coordinates.revision.len == 0: continue
      # ``.`` is the lock's own repo; anything else is workspace-relative to
      # the repo holding the lock.
      let key =
        if dep.path.len == 0 or dep.path == ".": repo.path
        else: os.normalizedPath(repo.path / dep.path).replace('\\', '/')
      if key notin repoClaims:
        repoClaims[key] = @[]
      repoClaims[key].add(LockClaim(
        node: dep.name,
        revision: dep.coordinates.revision,
        source: (repo.path & "/" & CommittedLockFileName).replace('\\', '/')))

  for repo in repos:
    let repoAbs = workspaceRoot / repo.path
    var claims: seq[LockClaim]
    if repo.path in dbClaims:
      claims.add(LockClaim(node: repo.name, revision: dbClaims[repo.path],
        source: (if dbSource.len > 0: dbSource else: "manifests lock DB")))
    if repo.path in repoClaims:
      for claim in repoClaims[repo.path]:
        claims.add(claim)
    if claims.len == 0:
      continue

    var finding = CoherenceFinding(node: repo.name, path: repo.path)
    let hasCheckout = dirExists(extendedPath(repoAbs / ".git")) or
      fileExists(extendedPath(repoAbs / ".git"))
    if hasCheckout:
      finding.checkoutHead = revParse(identity, repoAbs, "HEAD")
      let branchRes = gitRunPlain(identity,
        ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
      if branchRes.code == 0:
        finding.branch = branchRes.output.strip()

    var distinctRevisions = initHashSet[string]()
    for claim in claims.mitems:
      claim.relation = classifyClaim(identity, repoAbs, claim.revision,
        finding.checkoutHead)
      distinctRevisions.incl(claim.revision.toLowerAscii())
      if claim.relation in {crUnreachable, crNotFetched, crNoCheckout}:
        finding.interrupting = true
    finding.claims = claims
    # Two locks naming DIFFERENT revisions for one node is worth surfacing even
    # when both are ancestors of the checkout: the locks contradict each other,
    # not merely reality, and no single re-pin fixes both.
    finding.claimsDisagree = distinctRevisions.len > 1
    if finding.claimsDisagree:
      finding.interrupting = true

    var allMatch = true
    for claim in finding.claims:
      if claim.relation != crMatch:
        allMatch = false
    if allMatch and not finding.claimsDisagree:
      continue

    finding.remedies = coherenceRemedies(finding)
    if finding.interrupting: inc result.interrupting
    else: inc result.informational
    result.findings.add(finding)

proc resolveCoherenceLayerRoot(workspaceRoot, project: string): string =
  ## Where the manifests-DB locks live. Both supported layouts are probed by
  ## looking for the thing we actually need (``locks/<project>/``) rather than
  ## by inferring the layout, so a workspace in either shape gets the private
  ## pins folded in and a workspace in neither simply contributes no DB claim.
  if project.len == 0:
    return ""
  # RA-32 — the thing we probe for is the directory the WRITER created, which is
  # the encoded project component. Probing the raw name made a workspace whose
  # project name is not filename-shaped contribute no DB claim at all.
  let segment = encodeLockPathSegment(project)
  for candidate in [workspaceRoot / ".repro" / "manifests", workspaceRoot]:
    if dirExists(extendedPath(candidate / "locks" / segment)):
      return candidate
  ""

proc lockCoherenceFor*(identity: GitToolIdentity;
                       workspaceRoot, project: string;
                       repos: openArray[tuple[name, path: string]]):
                      CoherenceReport =
  ## The call shape the three host commands use. They each already know their
  ## participating repo set from their own report, so nothing is re-resolved
  ## just to run the check.
  var resolved: seq[ResolvedRepo]
  for repo in repos:
    if repo.path.len == 0: continue
    resolved.add(ResolvedRepo(name: repo.name, path: repo.path))
  collectLockCoherence(identity, workspaceRoot, resolved,
    resolveCoherenceLayerRoot(workspaceRoot, project), project)

proc coherenceReportToJson*(report: CoherenceReport): JsonNode =
  result = %*{
    "workspaceRoot": report.workspaceRoot,
    "interrupting": report.interrupting,
    "informational": report.informational,
    "findings": newJArray(),
  }
  for finding in report.findings:
    let entry = %*{
      "node": finding.node,
      "path": finding.path,
      "checkoutHead": finding.checkoutHead,
      "branch": finding.branch,
      "claimsDisagree": finding.claimsDisagree,
      "interrupting": finding.interrupting,
      "claims": newJArray(),
      "remedies": newJArray(),
    }
    for claim in finding.claims:
      entry["claims"].add(%*{
        "node": claim.node,
        "revision": claim.revision,
        "source": claim.source,
        "relation": relationTag(claim.relation),
      })
    for remedy in finding.remedies:
      entry["remedies"].add(%remedy)
    result["findings"].add(entry)

proc renderCoherenceTextLines*(report: CoherenceReport): seq[string] =
  ## Advisory text. Emitted after the host command's own output and never
  ## instead of it. Silent when every lock agrees with reality — the common
  ## case must cost the operator no attention.
  if report.findings.len == 0:
    return @[]
  result.add("lock coherence: " & $report.interrupting &
    " needing attention, " & $report.informational & " informational")
  for finding in report.findings:
    let head =
      if finding.checkoutHead.len > 0: finding.checkoutHead
      else: "<no checkout>"
    result.add("  " & finding.path & ": checked out " & head &
      (if finding.branch.len > 0: " on " & finding.branch else: ""))
    for claim in finding.claims:
      result.add("    " & claim.source & " claims " & claim.revision &
        " (" & relationTag(claim.relation) & ")")
    if finding.claimsDisagree:
      result.add("    these locks contradict EACH OTHER, not just the " &
        "checkout — no single re-pin satisfies both")
    # Say what the build will do, so nobody has to infer it.
    result.add("    the build uses the CHECKOUT (develop mode); a " &
      "disagreeing lock is a stale record, not an override")
    for remedy in finding.remedies:
      result.add("    remedy: " & remedy)
  result.add("lock coherence is ADVISORY: nothing was blocked or changed")

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-3 — git-checkout LockStore backend
# ---------------------------------------------------------------------------
#
# ``GitCheckoutLockStore`` is the ``LockStore`` (repro_lock_store) backend for
# today's ``.repo/manifests`` ``locks/<project>/<repo>/<sha>.toml`` layout. It
# is defined HERE rather than in repro_lock_store so it can DELEGATE to the
# byte-identical RA-1/RA-7 procs that already implement the publish/read
# semantics — ``publishWorkspaceLock`` (commit + push, RA-7/RA-21/RA-29),
# ``latestLockShasViaGit`` / ``latestLockRelPathForRepoViaGit`` (RA-1 git
# history "latest lock"). The read methods are placed next to those helpers;
# ``publishPending`` is defined below ``publishWorkspaceLock`` (it needs that
# proc in scope). The on-disk record is the verbatim lock body at
# ``locks/<project>/<repo>/<sha>.toml`` — identical bytes to the existing lock
# writer — with the identity tuple carried by the path, so no behavior of the
# manifest-present path changes.

type
  GitCheckoutLockStore* = ref object of LockStore
    identity*: GitToolIdentity
    manifestRepoRoot*: string
    pendingExpected*: seq[ExpectedLockRecord]

proc newGitCheckoutLockStore*(identity: GitToolIdentity;
    manifestRepoRoot: string): GitCheckoutLockStore =
  var canonicalRoot = os.normalizedPath(absolutePath(manifestRepoRoot))
  when defined(windows):
    # Config files intentionally use portable forward slashes, but Nim's
    # Windows filesystem walkers do not treat a mixed ``C:/root\subtree``
    # path identically to the native-separator form. Canonicalize once at the
    # backend boundary so a store routed from TOML resolves the same Git
    # history and lock subtree as one constructed from an OS-native path.
    canonicalRoot = canonicalRoot.replace('/', DirSep)
  GitCheckoutLockStore(identity: identity, manifestRepoRoot: canonicalRoot)

proc checkoutRootRefusal(s: GitCheckoutLockStore; action: string): string =
  ## "" when ``manifestRepoRoot`` really is a Git worktree ROOT; otherwise the
  ## refusal every MUTATING method must return instead of touching Git.
  ##
  ## The routed path is operator-supplied (``[[locking.route]] backend =
  ## "git-checkout", path = …``) and nothing before this point proves it names
  ## a checkout — ``newGitCheckoutLockStore`` only canonicalizes the spelling.
  ## Git's repository discovery walks UPWARDS, so when the path is a plain
  ## directory nested inside a checkout every ``git -C <root> add/commit`` this
  ## store runs operates on the ENCLOSING repository: the record is committed
  ## into a repo that merely happens to contain the routed directory, and the
  ## store then reports success. That mis-targeting at least used to fail
  ## loudly whenever the enclosing repo ignored the routed path; forcing the
  ## stage (which a routed record legitimately needs — see ``putLock``) removes
  ## even that accident, so the question "is this path a checkout ROOT?" has to
  ## be asked explicitly. Same reasoning as ``publishWorkspaceLock``'s
  ## not-a-checkout refusal, and deliberately the same phrasing.
  ##
  ## Asked HERE — at each mutating operation — rather than in the constructor
  ## because the constructor has no failure channel and, more importantly,
  ## because CONSTRUCTION is not the operation that can do harm: the pre-push
  ## gate builds this store over a manifest layer that is ALLOWED to be a plain
  ## directory (RA-21) purely to READ from it, and ``getEvidence`` /
  ## ``latestLock`` on such a layer are ordinary file/history reads that must
  ## keep working (and answering "nothing recorded") rather than raising.
  let discovery = discoverGitWorktree(s.identity, s.manifestRepoRoot)
  if discovery.ok: return ""
  result = "git-checkout lock store root '" & s.manifestRepoRoot &
    "' is not a git checkout; cannot " & action
  if discovery.diagnostic.len > 0:
    result.add(" (" & discovery.diagnostic & ")")

method backendId*(s: GitCheckoutLockStore): string = "git-checkout"

method storeLocationLabel*(s: GitCheckoutLockStore): string = s.manifestRepoRoot

method putLock*(s: GitCheckoutLockStore;
    rec: StoreLockRecord): StorePutResult =
  ## Write the lock body to ``locks/<project>/<repo>/<sha>.toml`` (the RA-1
  ## layout — identical bytes to the existing lock writer) and commit it, so
  ## the git-history "latest lock" queries resolve it.
  try:
    # Before ANY filesystem or Git effect: the routed root must be a checkout
    # ROOT, or the commit below lands in whatever repository encloses it.
    let refusal = checkoutRootRefusal(s, "record lock")
    if refusal.len > 0:
      return failed(refusal)
    # RA-32 — the store key becomes the path through the ONE encoder the
    # readers invert (``lockFileRepoRelativePath``), not a raw string join.
    # The raw join is what produced ``locks/codetracer/stripe/sync-engine/
    # <sha>.toml``: a repo NAME carrying a slash (twelve of this workspace's
    # repos are named the way the forge names them) silently became two path
    # components, so the record landed at depth 5 where the format has 4. It
    # was committed here and then refused by the publisher forever after.
    if not isLockPathName(rec.key.project) or
        not isLockPathName(rec.key.repo) or
        not isLockPathName(rec.key.sha):
      return failed("lock store key has an empty or NUL-bearing component " &
        "(project='" & rec.key.project & "' repo='" & rec.key.repo &
        "' sha='" & rec.key.sha & "')")
    if not isCanonicalRepoName(rec.key.repo):
      return failed("lock store key names a repo that is not a canonical " &
        "repo name (a name may carry '/' but not a backslash, an absolute " &
        "anchor, or a '.'/'..'/empty component): '" & rec.key.repo & "'")
    let rel = lockFileRepoRelativePath(rec.key.project, rec.key.repo,
      rec.key.sha)
    let coordinates = shasFromBody(rec.body)
    if coordinates.len != 1:
      return failed("Git lock backend requires one exact repository " &
        "coordinate for " & rel)
    var expected = ExpectedLockRecord(project: rec.key.project,
      repoName: rec.key.repo, oid: rec.key.sha, relPath: rel)
    for repoPath, revision in coordinates:
      if revision.toLowerAscii() != rec.key.sha.toLowerAscii():
        return failed("lock record revision does not match its store key at " &
          rel)
      expected.repoPath = repoPath
    proc rememberExpected() =
      for item in s.pendingExpected:
        if item.relPath == expected.relPath: return
      s.pendingExpected.add(expected)
    let abs = s.manifestRepoRoot / rel.replace('/', DirSep)
    # RA-32 — ``extendedPath`` at the filesystem boundary, the same rule
    # ``putEvidence`` below already applied. Its comment cites LOCK paths as
    # the reason, but the lock write itself was left bare, so on Windows the
    # evidence blob survived a long path while the primary record — the longest
    # path in the subsystem, and the one component encoding LENGTHENS (``%HH``
    # expands a byte up to 3x) — did not. The ordinary form is what is stored,
    # compared and handed to ``git``; only these calls take the extended form.
    createDir(extendedPath(parentDir(abs)))
    if fileExists(extendedPath(abs)):
      if readFile(extendedPath(abs)) != rec.body:
        return failed("immutable lock record already exists with different " &
          "content at " & rel)
    else:
      writeFile(extendedPath(abs), rec.body)
    # ``-f`` for the same reason ``publishWorkspaceLock`` forces its stage: the
    # operator may legitimately ignore the manifest layer (a global
    # ``core.excludesFile`` or a ``.gitignore`` naming ``.repro/`` / ``locks/``
    # applies inside this checkout too), and a routed team/personal record must
    # still be written under it — an unrecorded team-tier participation
    # escalates to a push REFUSAL. The pathspec is this one generated record.
    let addRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "add", "-f", "--", rel])
    if addRes.code != 0:
      return failed("git add " & rel & " failed: " & addRes.output.strip())
    # Idempotent re-record: writing the SAME lock record again stages no
    # change (the record is content-addressed by its SHA, so identical bytes
    # land at the same path). ``git commit`` would then exit non-zero with
    # "nothing to commit", which was surfaced as a spurious "failed to record"
    # — and under the tier-isolation policy a failed team-tier record escalates
    # to a push REFUSAL. Treat an unchanged re-write as success. ``git diff
    # --cached --quiet`` exits 0 when the staged tree matches HEAD for this
    # path (nothing to commit) and 1 when there is a real change to commit.
    let stagedRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "diff", "--cached", "--quiet", "--", rel])
    if stagedRes.code == 0:
      rememberExpected()
      return ok()
    let commitRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "commit", "--quiet", "-m",
       "lockstore: " & rec.key.project & "/" & rec.key.repo & "@" &
       rec.key.sha, "--", rel])
    if commitRes.code != 0:
      return failed("git commit failed: " & commitRes.output.strip())
    rememberExpected()
    ok()
  except CatchableError as err:
    failed(err.msg)

method latestLock*(s: GitCheckoutLockStore; project, repo: string):
    Option[StoreLockRecord] =
  let rel = latestLockRelPathForRepoViaGit(
    s.identity, s.manifestRepoRoot, project, repo)
  if rel.len == 0: return none(StoreLockRecord)
  let abs = s.manifestRepoRoot / rel.replace('/', DirSep)
  if not fileExists(abs): return none(StoreLockRecord)
  let trig = parseTriggerFromLockRelPath(rel)
  some(StoreLockRecord(
    key: StoreLockKey(project: project, repo: trig.repo, sha: trig.sha),
    body: readFile(abs)))

method latestLockAny*(s: GitCheckoutLockStore; project: string):
    Option[StoreLockRecord] =
  # Newest lock across every repo of the project by Git history, read as the
  # verbatim record BODY (no workspace-lock schema parse — the store records
  # an arbitrary body, unlike ``latestLockShas`` which extracts path/revision
  # from a real workspace lock).
  # RA-32 — encoded project component, exactly as ``putLock`` wrote it.
  let candidates = orderedLockCandidates(
    s.identity, s.manifestRepoRoot,
    "locks/" & encodeLockPathSegment(project) & "/")
  if candidates.len == 0: return none(StoreLockRecord)
  let rel = candidates[0].relPath
  let abs = s.manifestRepoRoot / rel.replace('/', DirSep)
  if not fileExists(abs): return none(StoreLockRecord)
  let trig = parseTriggerFromLockRelPath(rel)
  some(StoreLockRecord(
    key: StoreLockKey(project: project, repo: trig.repo, sha: trig.sha),
    body: readFile(abs)))

method latestLockShas*(s: GitCheckoutLockStore; project: string):
    tuple[shas: Table[string, string]; lockKey: StoreLockKey] =
  let r = latestLockShasViaGit(s.identity, s.manifestRepoRoot, project)
  var key: StoreLockKey
  if r.lockRelPath.len > 0:
    let trig = parseTriggerFromLockRelPath(r.lockRelPath)
    key = StoreLockKey(project: project, repo: trig.repo, sha: trig.sha)
  (shas: r.shas, lockKey: key)

method manifestLayerRoots*(s: GitCheckoutLockStore): seq[string] =
  @[s.manifestRepoRoot]

method readabilityDiagnostic*(s: GitCheckoutLockStore): string =
  ## DS-3 — the medium is the ``locks/`` subtree of the checkout at
  ## ``manifestRepoRoot``. An ABSENT root cannot be read at all (the private
  ## manifests repo was never cloned, or the route names the wrong path); an
  ## existing root that merely holds no records yet is reachable and
  ## legitimately contributes nothing.
  ##
  ## An EXISTING root that cannot be enumerated is treated exactly like an
  ## absent one, per "an existing-but-unreadable backend must refuse exactly
  ## like an absent one". The ``locks/`` subtree is probed separately: a root
  ## whose ``locks/`` exists but is unreadable is the finer case that used to
  ## come out as "reachable, holds no record" — a SILENTLY NARROWED set.
  ##
  ## Deliberately NOT ``checkoutRootRefusal``: RA-21 allows a manifest layer
  ## the gate only READS from to be a plain directory, and
  ## ``orderedLockCandidates`` falls back to a working-tree scan for exactly
  ## that shape. Refusing a readable plain directory here would narrow the
  ## develop set for a workspace whose records are perfectly readable.
  if not dirExists(extendedPath(s.manifestRepoRoot)):
    return "git-checkout lock store root does not exist: " & s.manifestRepoRoot
  let rootDiag = directoryReadDiagnostic(s.manifestRepoRoot)
  if rootDiag.len > 0:
    return "git-checkout lock store root exists but cannot be read: " &
      s.manifestRepoRoot & " (" & rootDiag & ")"
  let locksDir = s.manifestRepoRoot / "locks"
  if dirExists(extendedPath(locksDir)):
    let locksDiag = directoryReadDiagnostic(locksDir)
    if locksDiag.len > 0:
      return "git-checkout lock store's `locks/` subtree exists but cannot " &
        "be read: " & locksDir & " (" & locksDiag & ")"
  ""

proc lockRecordAtCommit*(store: LockStore; project, repo, sha: string):
    Option[StoreLockRecord] =
  ## The COMMIT-KEYED record read. The ``LockStore`` interface exposes only
  ## "the latest record for (project, repo)"; a commit-addressed backend can
  ## additionally be asked for the record belonging to ONE exact commit —
  ## ``locks/<project>/<repo>/<sha>.toml`` — which is what
  ## CLI/develop.md §"Which record, for a commit-addressed backend" keys the
  ## develop lock set on, and what the pre-push gate reads to prefer the
  ## immutable record at the exact outgoing coordinate over an alphabetically
  ## earlier sibling inside the same publication commit.
  ##
  ## Both callers had (or would have had) the same three lines inlined; this is
  ## that read promoted to one named entry point rather than duplicated.
  ## Backends that are not commit-addressed answer ``none`` — the caller then
  ## uses the ordinary ``latestLock`` resolver.
  if store.isNil or project.len == 0 or repo.len == 0 or sha.len == 0:
    return none(StoreLockRecord)
  if not (store of GitCheckoutLockStore):
    return none(StoreLockRecord)
  let gs = GitCheckoutLockStore(store)
  let rel = lockFileRepoRelativePath(project, repo, sha)
  let abs = gs.manifestRepoRoot / rel.replace('/', DirSep)
  if not fileExists(extendedPath(abs)):
    return none(StoreLockRecord)
  some(StoreLockRecord(
    key: StoreLockKey(project: project, repo: repo, sha: sha),
    body: readFile(extendedPath(abs))))

method putEvidence*(s: GitCheckoutLockStore; project, repo: string;
    ev: seq[WorkspaceVcsEvidence]): StorePutResult =
  try:
    # Same checkout-ROOT precondition as ``putLock``: without it the commit
    # below is made in whatever repository encloses the routed root.
    let refusal = checkoutRootRefusal(s, "record evidence")
    if refusal.len > 0:
      return failed(refusal)
    # RA-32 — same component encoding as ``putLock``: a repo NAME is one path
    # component here too, and ``../../etc`` must not write outside
    # ``evidence/``.
    if not isLockPathName(project) or not isCanonicalRepoName(repo):
      return failed("evidence key has a non-canonical project/repo name " &
        "(project='" & project & "' repo='" & repo & "')")
    let rel = "evidence/" & encodeLockPathSegment(project) & "/" &
      encodeLockPathSegment(repo) & ".ev"
    let abs = s.manifestRepoRoot / rel.replace('/', DirSep)
    # ``extendedPath`` at the filesystem boundary only: ``%HH`` escapes expand a
    # name up to 3x, so an evidence or lock path is measurably closer to
    # Windows' 260-char MAX_PATH than the raw name was.
    createDir(extendedPath(parentDir(abs)))
    writeFile(extendedPath(abs), encodeEvidenceBlob(ev))
    # ``-f``: same generated-record-under-a-possibly-ignored-layer case as
    # ``putLock`` above — the operator may legitimately ignore the manifest
    # layer, and this one generated blob must still be recorded under it.
    let addRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "add", "-f", "--", rel])
    if addRes.code != 0:
      return failed("git add " & rel & " failed: " & addRes.output.strip())
    # These two results used to be DISCARDED, so this method reported ``ok()``
    # whenever staging or committing had in fact recorded nothing — and the
    # MO-5 consume path then had nothing to verify a private repo's boundary
    # from, with no diagnostic anywhere to say why. Both callers act on the
    # outcome (``publishRoutedEvidence`` reports FAILED and exits non-zero; the
    # post-commit refresh reports "evidence refresh failed"), so surfacing the
    # failure is what makes the record's absence visible.
    #
    # Re-recording IDENTICAL evidence bytes stages no change, and ``git
    # commit`` then exits non-zero with "nothing to commit"; that is a
    # successful no-op, exactly as in ``putLock``. ``git diff --cached
    # --quiet`` distinguishes the two: 0 = nothing staged for this path.
    let stagedRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "diff", "--cached", "--quiet", "--", rel])
    if stagedRes.code == 0:
      return ok()
    let commitRes = gitRunPlain(s.identity,
      ["-C", s.manifestRepoRoot, "commit", "--quiet", "-m",
       "lockstore evidence: " & project & "/" & repo, "--", rel])
    if commitRes.code != 0:
      return failed("git commit failed: " & commitRes.output.strip())
    ok()
  except CatchableError as err:
    failed(err.msg)

method getEvidence*(s: GitCheckoutLockStore; project, repo: string):
    seq[WorkspaceVcsEvidence] =
  let abs = s.manifestRepoRoot /
    ("evidence/" & encodeLockPathSegment(project) & "/" &
      encodeLockPathSegment(repo) & ".ev").replace('/', DirSep)
  if not fileExists(extendedPath(abs)): return @[]
  decodeEvidenceBlob(readFile(extendedPath(abs)))

# ---------------------------------------------------------------------------
# MO-4 — per-repo-set locking-backend routing (config → per-repo backend)
# ---------------------------------------------------------------------------
#
# The host bootstrap config's ``[locking]`` table (``BootstrapLockingBody``)
# maps each visibility tier (``wvPublic`` / ``wvOrg`` / ``wvTeam`` /
# ``wvPersonal``) to a ``LockStore`` backend (the five MO-3 mediums). MO-4
# RESOLVES that table into a PER-REPO backend assignment — reusing the
# ``ResolvedRepo.visibility`` tier the manifest-layer composer already stamps
# — and the workspace operations record each repo's participation through its
# ASSIGNED backend.
#
# Defaults & boundary (per the milestone):
#   - A PUBLIC repo with NO route ⇒ the committed solved-graph lock
#     (``repro.lock``, MO-1): ``store == nil``, NO backend constructed. With no
#     ``[locking]`` table at all and an all-public workspace this is every
#     repo, so an all-public workspace touches no store backend (MO-2/MO-3).
#   - A PRIVATE repo (org/team/personal) with NO route ⇒ a loud
#     ``StoreRoutingError`` naming the repo + the remedy: its participation
#     cannot be recorded in the public committed lock and there is nowhere
#     else to put it.
#   - Backends are constructed ONLY for repos that actually need one, and at
#     most once per distinct (kind, location) so sibling repos of the same
#     tier share a single backend object.

type
  ConfigLayerKind* = enum
    ## HL-1 (Unified-Locking-And-Hooks §4.1) — the configuration layers, in
    ## increasing precedence. A repo's TIER is determined by which layer
    ## DECLARES it (tier-by-layer), never by a per-repo ``visibility`` field;
    ## within a single tier the most-specific (highest-precedence) layer wins
    ## the backend.
    clkBuiltinDefault    ## layer 1 — a bare public repo ⇒ the in-repo committed lock
    clkSystem            ## layer 2 — IT/system config (e.g. /etc/reprobuild)
    clkUserDotfiles      ## layer 3 — user dotfiles (~/.config/reprobuild)
    clkParentWorkspace   ## layer 4 — parent ``.repro-workspace.toml`` [locking]
    clkVcsPrivate        ## layer 5 — VCS-private dir (<git-common-dir>/repro)
    clkInvocation        ## DS-8 — layer 6, THIS INVOCATION's
                         ## ``--lock-store=<kind>:<location>``. Above every
                         ## configuration file layer, because it is the escape
                         ## hatch for a context (a CI checkout) that cannot
                         ## carry one. It is a LAYER, not a bypass: it claims
                         ## repos, agrees-or-conflicts on tier, and loses to
                         ## nothing except a later ``--lock-store`` — the same
                         ## precedence vocabulary layers 2..5 use.

  RepoBackendAssignment* = object
    ## One repo's resolved store assignment. ``store`` is ``nil`` exactly for
    ## the ``committed-lock`` kind (a public repo covered by ``repro.lock``);
    ## every other kind carries a constructed ``LockStore``.
    repoName*: string
    repoPath*: string
    visibility*: WorkspaceVisibility
    backendKind*: string
    store*: LockStore
    declaringLayer*: ConfigLayerKind
      ## HL-1 — which configuration LAYER fixed this repo's ``(tier, backend)``.
      ## ``clkBuiltinDefault`` for a repo no explicit layer claimed (the public
      ## committed-lock default). Surfaced by ``repro locking explain``.
    layerSource*: string
      ## HL-1 — a human-readable provenance of the declaring layer (the config
      ## file path, or ``"built-in default"``). Empty for the legacy
      ## visibility-keyed ``resolveRepoBackends(BootstrapLockingBody, …)`` path.

  ParticipationOutcome* = object
    ## Result of recording one repo's participation through its assigned
    ## backend. ``recorded`` is false for a committed-lock repo (already
    ## captured by ``repro.lock`` — nothing is written to a separate store).
    ##
    ## HL-3 (§6 Decision 2) — the gate inspects this per-repo outcome by TIER
    ## to decide refuse-for-shared / warn-for-personal on an unreachable
    ## backend. ``tier`` is the repo's resolved visibility (from the HL-1
    ## ``RepoBackendAssignment.tier``). ``attempted`` distinguishes a genuine
    ## write attempt from the committed-lock no-op skip (``store == nil``): a
    ## committed-lock repo has ``attempted == false`` and is NEVER a failure,
    ## while an attempted write that did not succeed (``attempted == true`` and
    ## ``recorded == false``) is the unreachable/unwritable backend the policy
    ## refuses-or-warns on. ``repoPath`` is the workspace-relative path the
    ## remedy text names.
    repoName*: string
    repoPath*: string
    backendKind*: string
    backendLocation*: string
      ## HL-3 — a human-readable location of the backend (its manifest root(s)
      ## or program), so the refusal remedy can name WHERE the backend lives.
    tier*: WorkspaceVisibility
    recorded*: bool
    attempted*: bool
    diagnostic*: string

  DeferredParticipationWrite = object
    outcome: ParticipationOutcome
    store: LockStore
    record: StoreLockRecord

  StoreRoutingError* = object of CatchableError

proc lockingTierLabel*(v: WorkspaceVisibility): string =
  case v
  of wvPublic: "public"
  of wvOrg: "org"
  of wvTeam: "team"
  of wvPersonal: "personal"

# ---------------------------------------------------------------------------
# The two lock ARTIFACTS, and the verb that re-pins each.
#
# Reprobuild has two locks and they are not interchangeable:
#
#   * the COMMITTED lock — ``repro.lock``, schema
#     ``reprobuild.solved-graph-lock.v2``, solved from a recipe's solver inputs.
#     ``repro lock refresh`` re-pins it, and it needs those inputs: run at a
#     workspace root that has none it answers "no solver inputs found …" and
#     exits 1.
#   * the WORKSPACE lock — ``locks/<project>/<repo>/<sha>.toml`` inside a
#     tier's backend (a git-checkout manifest store, an external DB, …).
#     ``repro workspace lock`` re-pins it.
#
# A refusal about the workspace lock that names ``repro lock refresh`` sends
# the operator to a command that cannot succeed however many times it is
# retried — which is exactly what happened. These two builders are the single
# place either verb is named, so the artifact a refusal is about decides the
# command it prints.
# ---------------------------------------------------------------------------

proc workspaceLockCommand*(workspaceRoot: string): string =
  ## The copy-pasteable ``repro workspace lock`` invocation that re-pins the
  ## WORKSPACE lock. ``--workspace-root`` is spelled out because the pre-push
  ## hook, the post-commit hook and ``repro push`` all speak from INSIDE a
  ## participating repo, and the verb resolves a bare invocation against the
  ## current directory with no upward search: without the flag the command
  ## works only if the operator first guesses a ``cd``.
  if workspaceRoot.len == 0: "repro workspace lock"
  else: "repro workspace lock --workspace-root=" & workspaceRoot

proc firstNamedReproCommand*(message: string): string =
  ## The first backtick-quoted ``repro …`` invocation a diagnostic names, or
  ## ``""`` when it names none.
  ##
  ## A refusal that travels (the lock writer raises; the pre-push gate catches
  ## and renders a ``CheckFailure``) must not lose the one copy-pasteable step
  ## the inner message worked out — §6 Decision 2, "The named command must RUN
  ## where the message is printed". The outer layer knows the failure class,
  ## not the repo names the inner layer resolved, so it lifts rather than
  ## re-derives.
  var i = 0
  while true:
    let a = message.find('`', i)
    if a < 0: return ""
    let b = message.find('`', a + 1)
    if b < 0: return ""
    let span = message[(a + 1) ..< b].strip()
    if span.startsWith("repro "):
      return span
    i = b + 1

proc committedLockCommand*(workspaceRoot: string): string =
  ## The copy-pasteable ``repro lock refresh`` invocation that re-pins the
  ## COMMITTED ``repro.lock``. It takes the workspace as a positional.
  if workspaceRoot.len == 0: "repro lock refresh"
  else: "repro lock refresh " & workspaceRoot

proc lockedIntegrityCauseToken*(c: LockedIntegrityCause): string =
  ## The machine-readable ``cause=`` token a refusal's EVIDENCE carries, so a
  ## consumer can tell "the revision vanished" from "the content changed"
  ## without parsing the prose.
  case c
  of licContentMismatch: "content-mismatch"
  of licRevisionUnreachable: "locked-revision-unreachable"
  of licNoRevisionPinned: "no-revision-pinned"

proc lockedIntegrityRemedy*(f: LockedIntegrityFailure; qualifier: string;
                            restoreWhere, repinCommand: string): string =
  ## The ONE wording every ``locked-integrity-mismatch`` refusal carries,
  ## rendered from the failure's CAUSE so the prose and the evidence agree.
  ##
  ## ``qualifier`` is the ``(tier=… backend=… location=…)`` parenthetical (empty
  ## for the committed lock's single unqualified source), ``restoreWhere`` names
  ## where the locked revision would be restored, and ``repinCommand`` is the
  ## verb for the artifact this refusal is about.
  let where = if qualifier.len > 0: " " & qualifier else: ""
  case f.cause
  of licRevisionUnreachable:
    "the locked revision " & f.revision & " for '" & f.path &
      "' is not present in the checkout, so the locked record cannot be " &
      "verified" & where & ". A force-push or history rewrite upstream is " &
      "the usual cause — the revision is GONE, not changed. Restore it in " &
      restoreWhere & ", or re-pin at the current revision with `" &
      repinCommand & "`"
  of licNoRevisionPinned:
    "the locked record for '" & f.path & "' pins no concrete revision to " &
      "verify its recorded integrity at" & where & "; re-pin at the current " &
      "revision with `" & repinCommand & "`"
  of licContentMismatch:
    "the content at the locked coordinates no longer matches the recorded " &
      "integrity for '" & f.path & "'" & where & "; restore the locked " &
      "revision in " & restoreWhere & " or run `" & repinCommand & "` to re-pin"

proc visibilityMatchesRouteLabel(v: WorkspaceVisibility; label: string): bool =
  case label.strip().toLowerAscii()
  of "public": v == wvPublic
  of "org": v == wvOrg
  of "team": v == wvTeam
  of "personal", "private": v == wvPersonal
  else: false

proc routeForVisibility(locking: BootstrapLockingBody;
                        v: WorkspaceVisibility): Option[LockingRouteEntry] =
  for entry in locking.route:
    if visibilityMatchesRouteLabel(v, entry.visibility):
      return some(entry)
  none(LockingRouteEntry)

proc resolveStoreLocation(workspaceRoot, p: string): string =
  if p.len == 0: workspaceRoot
  elif isAbsolute(p): p
  else: workspaceRoot / p

proc constructRoutedBackend(entry: LockingRouteEntry;
    workspaceRoot, repoPath: string; identity: GitToolIdentity;
    gitBin: string): LockStore =
  ## Construct the MO-3 backend named by one route entry. Raises
  ## ``StoreRoutingError`` on an unknown kind or a kind missing its required
  ## location parameter.
  let kind = entry.backend.strip().toLowerAscii()
  let pathParam = (if entry.path.isSome: entry.path.get() else: "")
  case kind
  of "committed-file":
    let base =
      if pathParam.len > 0: resolveStoreLocation(workspaceRoot, pathParam)
      else: workspaceRoot / ".repro" / "lockstore"
    newCommittedFileLockStore(base)
  of "git-checkout":
    if pathParam.len == 0:
      raise newException(StoreRoutingError,
        "locking backend 'git-checkout' for visibility=\"" & entry.visibility &
        "\" requires a `path` (the manifest-repo root, e.g. " &
        "`.repro/manifests-team`)")
    newGitCheckoutLockStore(identity,
      resolveStoreLocation(workspaceRoot, pathParam))
  of "git-notes":
    let repo =
      if pathParam.len > 0: resolveStoreLocation(workspaceRoot, pathParam)
      else: workspaceRoot / repoPath
    newGitNotesLockStore(gitBin, repo)
  of "separate-branch":
    let repo =
      if pathParam.len > 0: resolveStoreLocation(workspaceRoot, pathParam)
      else: workspaceRoot / repoPath
    newSeparateBranchLockStore(gitBin, repo)
  of "external-cli":
    if entry.program.isNone or entry.program.get().len == 0:
      raise newException(StoreRoutingError,
        "locking backend 'external-cli' for visibility=\"" & entry.visibility &
        "\" requires a `program` (the store CLI honoring " &
        ExternalCliContractSchemaV1 & ")")
    newExternalCliLockStore(
      resolveStoreLocation(workspaceRoot, entry.program.get()))
  else:
    raise newException(StoreRoutingError,
      "unknown locking backend '" & entry.backend & "' for visibility=\"" &
      entry.visibility & "\" (expected: committed-file | git-checkout | " &
      "git-notes | separate-branch | external-cli)")

proc resolveRepoBackends*(locking: BootstrapLockingBody;
    repos: seq[ResolvedRepo]; workspaceRoot: string;
    identity: GitToolIdentity; gitBin: string): seq[RepoBackendAssignment] =
  ## MO-4 — resolve each repo to the backend that records its participation,
  ## keyed by ``ResolvedRepo.visibility``. See the section comment for the
  ## default (public ⇒ committed lock, no backend) and the loud
  ## ``StoreRoutingError`` for an unrouted private repo.
  result = @[]
  var cache = initTable[string, LockStore]()
  for repo in repos:
    var asg = RepoBackendAssignment(
      repoName: repo.name, repoPath: repo.path, visibility: repo.visibility)
    let route = routeForVisibility(locking, repo.visibility)
    if route.isNone:
      if repo.visibility == wvPublic:
        asg.backendKind = "committed-lock"
        asg.store = nil
      else:
        raise newException(StoreRoutingError,
          "no locking backend configured for " &
          lockingTierLabel(repo.visibility) & " repo '" & repo.name &
          "': a " & lockingTierLabel(repo.visibility) & " repo's " &
          "participation cannot be recorded in the public committed lock. " &
          "Add a `[[locking.route]]` entry with visibility=\"" &
          lockingTierLabel(repo.visibility) & "\" (e.g. backend=" &
          "\"git-checkout\" or backend=\"external-cli\") to " &
          bootstrapConfigFileName & ".")
    else:
      let entry = route.get()
      let kind = entry.backend.strip().toLowerAscii()
      # Per-tier backends are shared; git-notes / separate-branch attach to a
      # specific repo's checkout, so they key on the repo path too.
      let locKey =
        if kind in ["git-notes", "separate-branch"] and
            (entry.path.isNone or entry.path.get().len == 0): repo.path
        else: (if entry.path.isSome: entry.path.get() else: "")
      let cacheKey = kind & "\0" & locKey & "\0" &
        (if entry.program.isSome: entry.program.get() else: "")
      if cache.hasKey(cacheKey):
        asg.store = cache[cacheKey]
      else:
        asg.store = constructRoutedBackend(
          entry, workspaceRoot, repo.path, identity, gitBin)
        cache[cacheKey] = asg.store
      asg.backendKind = asg.store.backendId()
    result.add(asg)

proc routedParticipationBody(repoName, repoPath, sha: string): string =
  ## A minimal workspace-lock-shaped body recording a single repo's pinned
  ## revision. ``shasFromBody`` (repro_lock_store) parses it back to the
  ## ``path -> revision`` map the gate/check consume.
  "[[repo]]\nname = \"" & repoName & "\"\npath = \"" & repoPath &
    "\"\nrevision = \"" & sha & "\"\n"

proc isWorkspaceLockDocument*(body: string): bool =
  ## True when ``body`` is a ``reprobuild.workspace.lock.v1`` DOCUMENT — it
  ## announces a top-level ``schema`` key, i.e. one appearing before any table
  ## header — as opposed to a routed ``routedParticipationBody`` record, which
  ## is a bare ``[[repo]]`` table announcing nothing. This is the same
  ## discriminator ``resolve-sibling-rev.sh`` applies at discovery (its
  ## ``is_participation_record``), and the same one that separates reprobuild's
  ## strict ``readLock`` from the tolerant ``shasFromBody``.
  for rawLine in body.splitLines():
    let line = rawLine.strip()
    if line.len == 0 or line.startsWith("#"): continue
    if line.startsWith("["): return false
    let eq = line.find('=')
    if eq <= 0: continue
    if line[0 ..< eq].strip() == "schema": return true
  false

proc storeRootMatches(store: LockStore; manifestLayerRoot: string): bool
  ## Forward declaration — defined with the HL-2 partition helpers below.

proc prepareWorkspaceParticipation(
    assignments: seq[RepoBackendAssignment]; projectName: string;
    repoShas: Table[string, string]; partitionRoot = ""):
    seq[DeferredParticipationWrite] =
  ## HL-2 (§6 Decision 1) — ``partitionRoot``, when non-empty, is the
  ## git-checkout manifest root whose repos are recorded by the PARTITION LOCK
  ## (the ``locks/<project>/<trigger>/<sha>.toml`` workspace-lock document
  ## ``executeWorkspaceLock`` writes into that same backend). Decision 1 gives
  ## the team partition ONE such document — "a ``locks/<project>/<repo>/<sha>``
  ## .toml written into the team's durable backend, containing only the team
  ## partition's repos" — and reserves the per-repo ``routedParticipationBody``
  ## records for the PERSONAL/other backends. Emitting both into one
  ## git-checkout store is not additive; the two writers collide on the SAME
  ## key for the trigger repo, and ``GitCheckoutLockStore.putLock`` correctly
  ## refuses to rewrite what the partition just wrote ("immutable lock record
  ## already exists with different content"). The partition survives, but the
  ## trigger repo's participation is then a FAILED team-tier outcome, which
  ## §6 Decision 2 escalates to a push REFUSAL. And at every other repo's
  ## ``(repo, sha)`` key the minimal record lands unopposed, permanently
  ## costing that repo the lock document its own pre-push would have published
  ## there: a published coordinate can afterwards be neither rewritten
  ## (publication is additions-only) nor refused (that would block the push).
  ## Repos covered by the partition are therefore skipped here; the partition
  ## lock is their record.
  for asg in assignments:
    var outc = ParticipationOutcome(
      repoName: asg.repoName, repoPath: asg.repoPath,
      backendKind: asg.backendKind, tier: asg.visibility)
    if asg.store.isNil:
      result.add(DeferredParticipationWrite(outcome: outc))
      continue
    if partitionRoot.len > 0 and storeRootMatches(asg.store, partitionRoot):
      continue
    outc.backendLocation = asg.store.storeLocationLabel()
    let sha = repoShas.getOrDefault(asg.repoPath,
      repoShas.getOrDefault(asg.repoName, ""))
    result.add(DeferredParticipationWrite(outcome: outc, store: asg.store,
      record: StoreLockRecord(
        key: StoreLockKey(project: projectName, repo: asg.repoName, sha: sha),
        body: routedParticipationBody(asg.repoName, asg.repoPath, sha))))

proc executeParticipationWrites(
    writes: seq[DeferredParticipationWrite]): seq[ParticipationOutcome] =
  ## This is the only durable `putLock` point used by the pre-push gate. The
  ## caller invokes it after every read-only visibility/integrity/certificate
  ## policy has passed, so a later policy failure cannot partially publish a
  ## successful earlier store.
  for write in writes:
    var outc = write.outcome
    if write.store.isNil:
      result.add(outc)
      continue
    outc.attempted = true
    let put = write.store.putLock(write.record)
    outc.recorded = put.outcome == spoOk
    outc.diagnostic = put.diagnostic
    result.add(outc)

proc recordWorkspaceParticipation*(assignments: seq[RepoBackendAssignment];
    projectName: string; repoShas: Table[string, string];
    partitionRoot = ""): seq[ParticipationOutcome] =
  ## The MO-4 workspace operation: record EACH repo's participation through
  ## its ASSIGNED backend. A committed-lock (public, ``store == nil``) repo is
  ## already captured by the committed solved-graph lock, so it is not
  ## re-recorded. Every repo with a real backend gets a ``StoreLockRecord``
  ## written into that backend's own medium — except the repos covered by the
  ## ``partitionRoot`` workspace-lock partition (see
  ## ``prepareWorkspaceParticipation``).
  executeParticipationWrites(
    prepareWorkspaceParticipation(
      assignments, projectName, repoShas, partitionRoot))

proc loadLockingRouting*(workspaceRoot: string): BootstrapLockingBody =
  ## Read the ``[locking]`` routing table from the host bootstrap config, or an
  ## empty body (the all-public default) when no config is present. The
  ## empty-default keeps the no-``[locking]`` operations byte-unchanged.
  let configPath = findBootstrapConfigPath(workspaceRoot)
  if configPath.len == 0: return BootstrapLockingBody()
  let cfg = readWorkspaceBootstrap(configPath)
  cfg.locking

# ---------------------------------------------------------------------------
# HL-1 (Unified-Locking-And-Hooks §4) — the layered configuration plane
# ---------------------------------------------------------------------------
#
# A repo's ``(tier, backend)`` is produced by COMPOSING the configuration
# layers (§4.1) in increasing precedence, NOT by a per-repo ``visibility``
# field:
#
#   1. built-in default  — a bare public repo ⇒ the in-repo committed lock.
#   2. system config     — IT-maintained (REPROBUILD_SYSTEM_CONFIG / /etc/…).
#   3. user dotfiles     — REPROBUILD_USER_CONFIG / ~/.config/reprobuild/.
#   4. parent workspace  — the ``.repro-workspace.toml`` ``[locking]`` table.
#   5. VCS-private dir   — ``<git-common-dir>/repro/config.toml`` (never pushed).
#
# Each non-built-in layer is a ``reprobuild.config.v1`` file that may carry
# ``[locking] route`` entries inline AND ``apply_if`` path-scoped bindings
# (both authored as inline-table arrays) whose referenced file contributes
# routes into the SAME layer. A
# route may NAME repos (``repos = [...]``): a named repo's tier is fixed by the
# DECLARING LAYER (tier-by-layer), so a repo named only in a private/system
# layer can never fall to the public committed lock. A route that names no
# repos keeps the legacy MO-4 visibility-keyed match, so a single ``[locking]``
# table resolves byte-identically to before HL-1.
#
# Conflict precedence (§4.4, owner-decided — disjoint composition): layers that
# name different repos union; a higher-precedence layer MAY refine the BACKEND
# within the SAME tier (most-specific wins); any attempt to move a repo ACROSS
# a tier between layers is a loud ``StoreRoutingError`` naming both sources.

proc layerLabel*(k: ConfigLayerKind): string =
  ## Stable human/JSON label for a configuration layer (used by
  ## ``repro locking explain`` and the cross-tier diagnostic).
  case k
  of clkBuiltinDefault: "built-in"
  of clkSystem: "system"
  of clkUserDotfiles: "dotfiles"
  of clkParentWorkspace: "parent-workspace-repo"
  of clkVcsPrivate: "vcs-private"
  of clkInvocation: "invocation (--lock-store)"

type
  ComposedRoute* = object
    ## One route contributed by one configuration layer, after apply_if
    ## resolution. ``repos`` empty ⇒ legacy visibility-keyed match.
    tier*: WorkspaceVisibility
    entry*: LockingRouteEntry
    layer*: ConfigLayerKind
    source*: string            ## provenance: the config file path
    repos*: seq[string]        ## explicitly named repos (name or path)

  ComposedRouting* = object
    ## The folded configuration plane: every layer's routes in INCREASING
    ## precedence order (lowest-precedence first), so ``claims[^1]`` is the
    ## most-specific claim.
    routes*: seq[ComposedRoute]

proc hasExplicitRoutes*(c: ComposedRouting): bool =
  ## True when at least one non-built-in layer declared a route. False keeps
  ## the all-public no-op (``recordRoutedParticipation`` returns ``@[]``),
  ## byte-identical to the pre-HL-1 ``locking.route.len == 0`` short-circuit.
  c.routes.len > 0

proc tierFromLabel(label: string): WorkspaceVisibility =
  ## Parse a route's ``visibility`` string into a tier. Loud on an unknown
  ## label so a typo never silently routes a repo to the wrong tier.
  case label.strip().toLowerAscii()
  of "public": wvPublic
  of "org": wvOrg
  of "team": wvTeam
  of "personal", "private": wvPersonal
  else:
    raise newException(StoreRoutingError,
      "unknown locking tier/visibility '" & label & "' (expected: public | " &
      "org | team | personal)")

proc vcsPrivateMetadataDir*(repoRoot: string; gitBin = ""): string =
  ## HL-1 (§4.3) — the absolute path of the repo's never-tracked, never-pushed
  ## VCS-private metadata dir, where the layer-5 reprobuild config lives. This
  ## is VCS-AGNOSTIC, never a hardcoded ``.git``:
  ##   * git → ``<git-common-dir>/repro`` resolved via
  ##     ``git rev-parse --git-common-dir`` so it is correct inside a LINKED
  ##     WORKTREE (whose ``.git`` is a file and whose private dir is the COMMON
  ##     dir, not the per-worktree dir);
  ##   * Mercurial → ``<repoRoot>/.hg/repro``;
  ##   * otherwise → a never-tracked ``<repoRoot>/.repro-private`` dir.
  ## The directory is NOT created; callers test for the config file's
  ## existence. Prior art: ``.git/info/exclude`` / ``.git/config`` are git's
  ## established local-only, never-pushed configuration locations.
  let root = absolutePath(repoRoot)
  let dotGit = root / ".git"
  if dirExists(dotGit) or fileExists(dotGit):
    let git = if gitBin.len > 0: gitBin else: findExe("git")
    if git.len > 0:
      let res = execCmdEx(quoteShell(git) & " -C " & quoteShell(root) &
        " rev-parse --git-common-dir",
        options = {poStdErrToStdOut, poUsePath},
        env = scrubbedGitRepositoryEnv())
      if res.exitCode == 0:
        var common = res.output.strip()
        if common.len > 0:
          if not isAbsolute(common): common = root / common
          try:
            return os.normalizedPath(expandFilename(common)) / "repro"
          except OSError, CatchableError:
            return os.normalizedPath(absolutePath(common)) / "repro"
    # No git on PATH: fall back to the literal .git dir when it is a real
    # directory (a non-worktree checkout). A worktree's ``.git`` is a file, so
    # this fallback is only reached for a plain checkout.
    if dirExists(dotGit):
      return dotGit / "repro"
    return root / ".repro-private"
  if dirExists(root / ".hg"):
    return root / ".hg" / "repro"
  root / ".repro-private"

proc systemConfigPath(): string =
  ## Layer-2 config path: ``REPROBUILD_SYSTEM_CONFIG`` override, else the
  ## platform system-config location.
  let o = getEnv("REPROBUILD_SYSTEM_CONFIG")
  if o.len > 0: return o
  when defined(windows):
    getEnv("PROGRAMDATA", "C:\\ProgramData") / "reprobuild" / "config.toml"
  else:
    "/etc/reprobuild/config.toml"

proc userConfigPath(): string =
  ## Layer-3 config path: ``REPROBUILD_USER_CONFIG`` override, else
  ## ``~/.config/reprobuild/config.toml`` (XDG via ``getConfigDir``).
  let o = getEnv("REPROBUILD_USER_CONFIG")
  if o.len > 0: return o
  getConfigDir() / "reprobuild" / "config.toml"

proc vcsPrivateConfigPath(repoRoot, gitBin: string): string =
  ## Layer-5 config path: ``REPROBUILD_VCS_PRIVATE_CONFIG`` override, else
  ## ``vcsPrivateMetadataDir(repoRoot)/config.toml``.
  let o = getEnv("REPROBUILD_VCS_PRIVATE_CONFIG")
  if o.len > 0: return o
  vcsPrivateMetadataDir(repoRoot, gitBin) / "config.toml"

proc normalizeScopePath(p: string): string =
  ## Q-B normalization: expand ``~``, make absolute, symlink-resolve when the
  ## path exists, then normalize lexically. Used to compare an ``apply_if``
  ## ``under`` scope against a workspace path.
  var s = expandTilde(p)
  s = absolutePath(s)
  try:
    if fileExists(s) or dirExists(s): s = expandFilename(s)
  except OSError, CatchableError:
    discard
  os.normalizedPath(s)

proc workspaceUnderApplyIfScope(workspaceRoot, under: string): bool =
  ## Q-B matching: the workspace activates an ``apply_if`` when its normalized
  ## path EQUALS the scope or is nested under ``scope/`` (path-prefix after
  ## normalization). Models Git's ``includeIf "gitdir:…"``.
  if under.len == 0: return false
  let ws = normalizeScopePath(workspaceRoot)
  let scope = normalizeScopePath(under)
  ws == scope or ws.startsWith(scope & $DirSep)

proc toComposedRoute(entry: LockingRouteEntry; layer: ConfigLayerKind;
    source: string): ComposedRoute =
  ComposedRoute(
    tier: tierFromLabel(entry.visibility), entry: entry,
    layer: layer, source: source, repos: entry.repos)

proc readConfigLayerRoutes(configFile: string; layer: ConfigLayerKind;
    workspaceRoot: string; acc: var seq[ComposedRoute]) =
  ## Read one ``reprobuild.config.v1`` file and fold its inline
  ## ``[[locking.route]]`` entries plus every in-scope ``[[apply_if]]``-
  ## referenced file's routes into ``acc``, all attributed to ``layer``. A
  ## missing file is a no-op (the layer is simply absent).
  if configFile.len == 0 or not fileExists(configFile): return
  let cfg = readReprobuildConfig(configFile)
  for entry in cfg.locking.route:
    acc.add(toComposedRoute(entry, layer, configFile))
  for ai in cfg.apply_if:
    if ai.under.len == 0 or ai.config.len == 0: continue
    if not workspaceUnderApplyIfScope(workspaceRoot, ai.under): continue
    let referenced =
      if isAbsolute(ai.config): ai.config
      else: configFile.parentDir / ai.config
    if not fileExists(referenced): continue
    # One level of inclusion (like Git's includeIf): the referenced file's own
    # apply_if is not followed, only its routes are contributed.
    let refCfg = readReprobuildConfig(referenced)
    for entry in refCfg.locking.route:
      acc.add(toComposedRoute(entry, layer, referenced))

proc composeLockingRouting*(workspaceRoot: string; gitBin = ""):
    ComposedRouting =
  ## HL-1 — fold the configuration layers (§4.1) into one composed routing
  ## table, in INCREASING precedence order. The parent-workspace layer (4) is
  ## the existing single-file ``.repro-workspace.toml`` ``[locking]`` read, so
  ## a workspace with only that table composes to exactly those routes and
  ## resolves identically to the pre-HL-1 behavior.
  result = ComposedRouting(routes: @[])
  let root = absolutePath(workspaceRoot)
  # Layer 2 — system config.
  readConfigLayerRoutes(systemConfigPath(), clkSystem, root, result.routes)
  # Layer 3 — user dotfiles.
  readConfigLayerRoutes(userConfigPath(), clkUserDotfiles, root, result.routes)
  # Layer 4 — parent ``.repro-workspace.toml`` ``[locking]`` table.
  let bootstrap = loadLockingRouting(root)
  if bootstrap.route.len > 0:
    let bootstrapSource = findBootstrapConfigPath(root)
    for entry in bootstrap.route:
      result.routes.add(toComposedRoute(entry, clkParentWorkspace,
        (if bootstrapSource.len > 0: bootstrapSource else: "parent workspace")))
  # Layer 5 — VCS-private dir.
  readConfigLayerRoutes(vcsPrivateConfigPath(root, gitBin), clkVcsPrivate,
    root, result.routes)

proc resolveRepoBackends*(composed: ComposedRouting;
    repos: seq[ResolvedRepo]; workspaceRoot: string;
    identity: GitToolIdentity; gitBin: string): seq[RepoBackendAssignment] =
  ## HL-1 — resolve each repo to exactly one ``(tier, backend)`` by composing
  ## the configuration layers. Keeps the ``RepoBackendAssignment`` shape and
  ## the five-backend construction of the legacy overload; only the SOURCE of
  ## the ``(tier, backend)`` decision changes (tier-by-layer, not
  ## ``ResolvedRepo.visibility``).
  ##
  ## Per repo: NAMED claims (routes whose ``repos`` names it) take precedence
  ## over VISIBILITY-KEYED claims (legacy routes whose tier matches
  ## ``visibility``), so a repo named in a private layer is never also pulled
  ## into a visibility-keyed public route. All surviving claims MUST agree on
  ## the tier (else a loud cross-tier ``StoreRoutingError`` naming both
  ## sources); within that tier the most-specific (highest-precedence) layer
  ## wins the backend. An unclaimed PUBLIC repo is the built-in committed-lock
  ## default; an unclaimed non-public repo is a loud ``StoreRoutingError``
  ## (identical to the legacy overload).
  result = @[]
  var cache = initTable[string, LockStore]()
  for repo in repos:
    var namedClaims: seq[ComposedRoute] = @[]
    var visClaims: seq[ComposedRoute] = @[]
    for r in composed.routes:
      if r.repos.len > 0:
        if repo.name in r.repos or repo.path in r.repos:
          namedClaims.add(r)
      elif visibilityMatchesRouteLabel(repo.visibility, r.entry.visibility):
        visClaims.add(r)
    let claims = if namedClaims.len > 0: namedClaims else: visClaims
    var asg = RepoBackendAssignment(
      repoName: repo.name, repoPath: repo.path, visibility: repo.visibility)
    if claims.len == 0:
      if repo.visibility == wvPublic:
        asg.backendKind = "committed-lock"
        asg.store = nil
        asg.declaringLayer = clkBuiltinDefault
        asg.layerSource = "built-in default"
      else:
        raise newException(StoreRoutingError,
          "no locking backend configured for " &
          lockingTierLabel(repo.visibility) & " repo '" & repo.name &
          "': a " & lockingTierLabel(repo.visibility) & " repo's " &
          "participation cannot be recorded in the public committed lock. " &
          "Add a `[locking] route` entry with visibility=\"" &
          lockingTierLabel(repo.visibility) & "\" (e.g. backend=" &
          "\"git-checkout\" or backend=\"external-cli\") to a configuration " &
          "layer (e.g. " & bootstrapConfigFileName & ", a system/dotfiles " &
          "reprobuild config, or an `apply_if`-referenced routes file).")
    else:
      let tier = claims[0].tier
      let tierSource = claims[0]
      for c in claims[1 .. ^1]:
        if c.tier != tier:
          raise newException(StoreRoutingError,
            "repo '" & repo.name & "' is declared at CONFLICTING TIERS by " &
            "different configuration layers: " & lockingTierLabel(tier) &
            " (declared by the " & layerLabel(tierSource.layer) &
            " layer — " & tierSource.source & ") vs " & lockingTierLabel(c.tier) &
            " (declared by the " & layerLabel(c.layer) & " layer — " &
            c.source & "). A cross-tier move between layers is REFUSED: each " &
            "repo resolves to exactly one (tier, backend). Reconcile the two " &
            "layers so they agree on the tier for this repo.")
      # Same tier across all claims — most-specific (highest-precedence,
      # last-appended) claim wins the backend.
      let winner = claims[^1]
      asg.visibility = tier
      asg.declaringLayer = winner.layer
      asg.layerSource = winner.source
      let entry = winner.entry
      let kind = entry.backend.strip().toLowerAscii()
      let locKey =
        if kind in ["git-notes", "separate-branch"] and
            (entry.path.isNone or entry.path.get().len == 0): repo.path
        else: (if entry.path.isSome: entry.path.get() else: "")
      let cacheKey = kind & "\0" & locKey & "\0" &
        (if entry.program.isSome: entry.program.get() else: "")
      if cache.hasKey(cacheKey):
        asg.store = cache[cacheKey]
      else:
        asg.store = constructRoutedBackend(
          entry, workspaceRoot, repo.path, identity, gitBin)
        cache[cacheKey] = asg.store
      asg.backendKind = asg.store.backendId()
    result.add(asg)

proc resolveWorkspaceRepoBackends*(workspaceRoot: string;
    repos: seq[ResolvedRepo]; identity: GitToolIdentity):
    tuple[assignments: seq[RepoBackendAssignment]; composed: ComposedRouting] =
  ## Convenience: compose the configuration layers for ``workspaceRoot`` and
  ## resolve every repo's ``(tier, backend, layer)``. The shared entry point
  ## for the routed write path and ``repro locking explain``.
  let composed = composeLockingRouting(workspaceRoot, identity.binaryPath)
  let assignments = resolveRepoBackends(
    composed, repos, workspaceRoot, identity, identity.binaryPath)
  (assignments: assignments, composed: composed)

proc recordRoutedParticipation*(workspaceRoot: string;
    repos: seq[ResolvedRepo]; repoShas: Table[string, string];
    projectName: string; identity: GitToolIdentity; partitionRoot = ""):
    seq[ParticipationOutcome] =
  ## MO-4 / HL-1 — the shared step the lock / publish operations call. A no-op
  ## (empty result) when NO configuration layer declares a route, so the
  ## all-public default + every manifest-present operation is unchanged. When
  ## routes ARE declared, the COMPOSED configuration plane (HL-1: built-in →
  ## system → dotfiles → parent workspace → VCS-private) resolves each repo to
  ## its ``(tier, backend)`` and records participation; an unrouted private
  ## repo raises ``StoreRoutingError``. A workspace whose only routes are the
  ## ``.repro-workspace.toml`` ``[locking]`` table composes to exactly those
  ## routes, so its result is byte-identical to the pre-HL-1 single-table read.
  let composed = composeLockingRouting(workspaceRoot, identity.binaryPath)
  if not composed.hasExplicitRoutes: return @[]
  let assignments = resolveRepoBackends(
    composed, repos, workspaceRoot, identity, identity.binaryPath)
  recordWorkspaceParticipation(
    assignments, projectName, repoShas, partitionRoot)

proc prepareRoutedParticipation(workspaceRoot: string;
    repos: seq[ResolvedRepo]; repoShas: Table[string, string];
    projectName: string; identity: GitToolIdentity; partitionRoot = ""):
    seq[DeferredParticipationWrite] =
  let composed = composeLockingRouting(workspaceRoot, identity.binaryPath)
  if not composed.hasExplicitRoutes: return @[]
  let assignments = resolveRepoBackends(
    composed, repos, workspaceRoot, identity, identity.binaryPath)
  prepareWorkspaceParticipation(
    assignments, projectName, repoShas, partitionRoot)

# ---------------------------------------------------------------------------
# HL-2 (Unified-Locking-And-Hooks §6 Decision 1) — strict per-backend, tier-
# isolated write / read / publish. The monolithic all-repos lock TOML is the
# cross-tier leak (a personal repo's SHA and a team repo's SHA landing together
# in the one git manifest). The procs below partition the observed repos by
# their resolved ``(tier, backend)`` so each backend receives ONLY the repos
# routed to it, and the pre-push read / post-gate publish iterate per-backend.
# ---------------------------------------------------------------------------

proc storeRootMatches(store: LockStore; manifestLayerRoot: string): bool =
  ## True when ``store`` is a durable backend whose on-disk root is exactly
  ## ``manifestLayerRoot`` (the git-checkout manifest the partitioned
  ## ``writeLockFile`` targets). Used to decide which observed repos belong in
  ## the manifest lock file: only the repos routed to THAT git-checkout backend.
  if store.isNil: return false
  let want = os.normalizedPath(absolutePath(manifestLayerRoot))
  for r in store.manifestLayerRoots():
    if os.normalizedPath(absolutePath(r)) == want:
      return true
  false

proc manifestOwnedRepos*(composed: ComposedRouting;
    lockRepos: seq[ResolvedRepo]; workspaceRoot, manifestLayerRoot: string;
    identity: GitToolIdentity): seq[ResolvedRepo] =
  ## HL-2 — the subset of ``lockRepos`` whose resolved backend is the
  ## git-checkout manifest at ``manifestLayerRoot``. When NO configuration
  ## layer declares an explicit route (the today's-common single-tier shape),
  ## every observed repo is manifest-owned, so the monolithic ``writeLockFile``
  ## stays BYTE-IDENTICAL to the pre-HL-2 behavior (all repos, one TOML). When
  ## routes ARE declared, a public repo (committed-lock) and a personal/other-
  ## backend repo are EXCLUDED — their SHAs never land in the git manifest.
  if not composed.hasExplicitRoutes:
    return lockRepos
  let assignments = resolveRepoBackends(
    composed, lockRepos, workspaceRoot, identity, identity.binaryPath)
  var byPath = initTable[string, RepoBackendAssignment]()
  for a in assignments:
    byPath[a.repoPath] = a
  for repo in lockRepos:
    if byPath.hasKey(repo.path) and
        storeRootMatches(byPath[repo.path].store, manifestLayerRoot):
      result.add(repo)

# ---------------------------------------------------------------------------
# HL-2 (§10 Migration) — legacy ``.repo/manifests`` migration guard.
#
# "No implicit team route" (spec §10) means a legacy ``.repo/manifests``
# workspace with no team route declared would silently become public-only and
# stop writing its team manifest lock. That is a BREAKING change we must never
# make silently. When a manifest checkout is present but the composed
# configuration plane declares NO explicit route (so no team tier points at the
# manifest), we emit a LOUD, ONE-TIME guidance naming the exact
# ``repro locking adopt-manifest`` remedy that keeps the manifest as the team
# backend. The guidance is throttled by a sentinel under ``.repro/`` so it does
# not spam every lock/gate run.
# ---------------------------------------------------------------------------

proc legacyManifestMigrationSentinelPath(workspaceRoot: string): string =
  workspaceRoot / ".repro" / "workspace" / "legacy-manifest-migration.warned"

proc maybeWarnLegacyManifestWithoutTeamRoute*(workspaceRoot: string;
    composed: ComposedRouting) =
  ## HL-2 (§10) — emit the one-time guidance when a ``.repro/manifests`` DB
  ## checkout exists but no explicit route is declared (the workspace that WOULD
  ## silently go public-only). Best-effort: never raises, never blocks the caller.
  let manifestsDir = workspaceRoot / ".repro" / "manifests"
  if not dirExists(manifestsDir): return
  if composed.hasExplicitRoutes: return
  let sentinel = legacyManifestMigrationSentinelPath(workspaceRoot)
  if fileExists(sentinel): return
  stderr.writeLine(
    "repro: WARNING — this workspace has a `.repro/manifests` checkout but NO " &
    "team route declared in any configuration layer.")
  stderr.writeLine(
    "  Under the tier-isolated locking model there is NO implicit team route: " &
    "without an explicit route this workspace is PUBLIC-ONLY and will stop " &
    "writing its team manifest lock (`" & manifestsDir & "/locks/...`).")
  stderr.writeLine(
    "  To keep `.repro/manifests` as the TEAM backend, run:  " &
    "repro locking adopt-manifest --workspace-root=" & workspaceRoot)
  stderr.writeLine(
    "  That scaffolds a `[locking] route = [{ visibility = \"team\", " &
    "backend = \"git-checkout\", path = \".repro/manifests\", repos = [...] }]` " &
    "route mapping the team tier to the existing manifest checkout.")
  try:
    createDir(sentinel.parentDir)
    writeFile(sentinel, "warned\n")
  except CatchableError:
    discard

# ---------------------------------------------------------------------------
# MO-5 — evidence-only private-repo participation
# ---------------------------------------------------------------------------
#
# A private repo can participate in the build WITHOUT being shared
# (Workspace-And-Develop-Mode.md §"Evidence-only participation"). Instead of
# exposing its source, the workspace publishes only the source-free
# ``WorkspaceVcsEvidence`` triple (head-sha / is-clean / is-published) through
# the repo's MO-4-assigned backend (MO-3 ``putEvidence``). A teammate who cannot
# clone the private source verifies the reproducibility boundary from that
# published evidence + the committed lock — the gate/check CONSUME the evidence
# (MO-3 ``getEvidence``) in lieu of a clonable sibling rather than refusing
# because the repo is unreadable.
#
# The marker is the EXPLICIT per-repo ``ResolvedRepo.participation`` field
# (authored as ``participation = "evidence-only"`` in a ``repos/<repo>.toml``
# fragment; see ``RepoBody.participation``). A private repo WITHOUT the marker
# is a SHARED-private repo whose source is expected present — an unreadable one
# is an actionable clone-required error, NOT evidence-only.
#
# SECURITY: ``WorkspaceVcsEvidence`` carries NO source (no file blobs / no
# working-tree contents) — only the three observation scalars. The verdict is
# computed from the REAL evidence: a dirty or unpublished evidence-only repo, or
# one whose published head-sha does not match the locked SHA, still FAILS the
# gate. Evidence-only participation never silently passes a bad boundary.

const participationEvidenceOnly* = "evidence-only"
  ## The sole ``ResolvedRepo.participation`` value that designates a private
  ## repo as evidence-only (published-evidence-sufficient, never cloned).

proc isEvidenceOnlyRepo*(repo: ResolvedRepo): bool =
  ## True iff ``repo`` is explicitly marked evidence-only. Independent of
  ## visibility, but only meaningful for a private repo (a public repo is
  ## always shared/cloneable).
  repo.participation.strip().toLowerAscii() == participationEvidenceOnly

proc isEvidenceOnlyLockedDep(d: LockedDep): bool =
  ## DS-4 — the ``LockedDep`` sibling of ``isEvidenceOnlyRepo``. The unified
  ## model carries the repo's ``participation`` verbatim (every
  ## ``populateLockedDeps`` source fills it), so the develop-set composer can
  ## ask the same question of a dependency it read from ANY backend.
  d.participation.strip().toLowerAscii() == participationEvidenceOnly

type
  UnreadableRepoVerdict* = enum
    ## The MO-5 reproducibility verdict for a private repo whose source is NOT
    ## present locally (unreadable / never cloned).
    urvCloneRequired        ## shared-private — source expected; actionable error
    urvEvidenceSatisfied    ## evidence-only — evidence clean+published+at-locked-sha
    urvEvidenceMissing      ## evidence-only — store holds NO published evidence
    urvEvidenceDirty        ## evidence-only — evidence says the repo was dirty
    urvEvidenceUnpublished  ## evidence-only — evidence says HEAD not published
    urvEvidenceShaMismatch  ## evidence-only — head-sha != the locked SHA
    urvEvidenceNoLock       ## evidence-only — no locked SHA to verify against
    urvEvidenceNoBackend    ## evidence-only — repo has no assigned store backend

  UnreadableRepoResult* = object
    ## Outcome of evaluating one unreadable repo's participation.
    verdict*: UnreadableRepoVerdict
    headSha*: string
    lockedSha*: string
    isClean*: bool
    isPublished*: bool
    diagnostic*: string

proc gatherRepoEvidence*(identity: GitToolIdentity;
    repoAbsPath, recordPath, toolDigestHex: string; observedAtUnixMs: int64;
    remoteName: string = "origin"):
    seq[WorkspaceVcsEvidence] =
  ## Observe the source-free head-sha / is-clean / is-published triple for a
  ## repo's LOCAL checkout at ``repoAbsPath``. The OWNER of an evidence-only
  ## private repo (the one that HAS the source) runs this and publishes the
  ## result via the store's ``putEvidence`` — NO source content (no file blobs /
  ## no working-tree contents) is ever captured; ``WorkspaceVcsEvidence`` has no
  ## source field. ``recordPath`` is the workspace-relative path stamped on each
  ## record (never the absolute on-disk path).
  let headRes = queryGitState(headShaQuery(repoAbsPath), identity)
  let cleanRes = queryGitState(isCleanQuery(repoAbsPath), identity)
  let pubRes = queryGitState(isPublishedQuery(repoAbsPath, remoteName), identity)
  @[
    workspaceVcsEvidence.evidenceFor(
      headRes, recordPath, wvqHeadSha, toolDigestHex, observedAtUnixMs),
    workspaceVcsEvidence.evidenceFor(
      cleanRes, recordPath, wvqIsClean, toolDigestHex, observedAtUnixMs),
    workspaceVcsEvidence.evidenceFor(
      pubRes, recordPath, wvqIsPublished, toolDigestHex, observedAtUnixMs)]

proc evidenceTriple(ev: seq[WorkspaceVcsEvidence]):
    tuple[headSha: string; isClean, isPublished, haveClean, havePub: bool] =
  ## Reduce a published evidence list to the three meaningful scalars,
  ## honoring each record's ``op`` discriminator and ``status``.
  for rec in ev:
    if rec.status != wvesResolved: continue
    case rec.op
    of wvqHeadSha:
      if rec.headSha.len > 0: result.headSha = rec.headSha
    of wvqIsClean:
      result.isClean = rec.isClean
      result.haveClean = true
    of wvqIsPublished:
      result.isPublished = rec.isPublished
      result.havePub = true

proc evaluateEvidenceOnlyParticipation*(store: LockStore;
    project, repoName, repoPath, lockedSha: string): UnreadableRepoResult =
  ## MO-5 — compute the reproducibility verdict for an EVIDENCE-ONLY private
  ## repo whose source is unreadable, from its PUBLISHED source-free evidence
  ## (read via MO-3 ``getEvidence``) plus the locked SHA. The boundary is
  ## verified ONLY when the evidence proves the repo was clean, published, AND
  ## at the locked SHA — every other case is a falsifiable failure verdict.
  if store.isNil:
    return UnreadableRepoResult(verdict: urvEvidenceNoBackend,
      diagnostic: "evidence-only repo '" & repoName &
        "' has no assigned locking backend to read published evidence from")
  let ev = store.getEvidence(project, repoName)
  if ev.len == 0:
    return UnreadableRepoResult(verdict: urvEvidenceMissing,
      diagnostic: "no published WorkspaceVcsEvidence for evidence-only repo '" &
        repoName & "' in its assigned " & store.backendId() & " store")
  let t = evidenceTriple(ev)
  result.headSha = t.headSha
  result.lockedSha = lockedSha
  result.isClean = t.haveClean and t.isClean
  result.isPublished = t.havePub and t.isPublished
  if not t.haveClean or not t.isClean:
    result.verdict = urvEvidenceDirty
    result.diagnostic = "published evidence reports evidence-only repo '" &
      repoName & "' was NOT clean at observation"
    return
  if not t.havePub or not t.isPublished:
    result.verdict = urvEvidenceUnpublished
    result.diagnostic = "published evidence reports evidence-only repo '" &
      repoName & "' HEAD is NOT published"
    return
  if lockedSha.len == 0:
    result.verdict = urvEvidenceNoLock
    result.diagnostic = "no locked revision recorded for evidence-only repo '" &
      repoName & "' to verify the published head-sha against"
    return
  if t.headSha != lockedSha:
    result.verdict = urvEvidenceShaMismatch
    result.diagnostic = "evidence-only repo '" & repoName &
      "' published head-sha " & t.headSha & " does not match locked SHA " &
      lockedSha
    return
  result.verdict = urvEvidenceSatisfied
  result.diagnostic = "evidence-only repo '" & repoName &
    "' verified from published evidence: clean, published, at locked SHA " &
    lockedSha

proc lockedShaFromStore*(store: LockStore; project, repoName, repoPath: string):
    string =
  ## Read the newest locked revision a repo's assigned backend holds for its
  ## PATH.  The path is the identity inside a workspace-lock body; ``repoName``
  ## is only the trigger/key used by legacy one-record-per-repo backends.
  ##
  ## A git-checkout partition is deliberately written ONCE, under the repo that
  ## triggered ``workspace lock``, and its body can name every sibling routed
  ## to that backend.  Looking only at ``latestLock(project, repoName)`` makes
  ## those siblings disappear: no duplicate file is (or should be) written
  ## under each sibling's key.  ``latestLockShas(project)`` is the canonical
  ## project read.  For git-checkout it folds every trigger-keyed candidate in
  ## the existing deterministic newest-first Git-history order, first claim
  ## winning per path; for the other backends its default is their existing
  ## project-latest record.  Thus stale/overlapping partitions have one defined
  ## winner without a mutable index, aliases, or duplicated lock contents.
  ##
  ## The exact-key fallback preserves legacy single-repo stores whose newest
  ## project record belongs to another repo.  The final single-coordinate
  ## fallback tolerates the historical path-spelling case it was written for,
  ## but never guesses from a multi-coordinate partition.
  if store.isNil: return ""
  let projectLatest = store.latestLockShas(project).shas
  if repoPath in projectLatest: return projectLatest[repoPath]
  let latest = store.latestLock(project, repoName)
  if latest.isNone: return ""
  let shas = shasFromBody(latest.get().body)
  if repoPath in shas: return shas[repoPath]
  # Fall back to a single-entry body keyed by some other path form.
  if shas.len == 1:
    for _, v in shas:
      return v
  ""

# ---------------------------------------------------------------------------
# MO-13 (correcting MO-5) — the evidence-PUBLISH verb.
#
# MO-5 wired the gather (``gatherRepoEvidence``) + put (``store.putEvidence``)
# building blocks and the gate-side CONSUME path, but left the dedicated owner
# verb that PUBLISHES an evidence-only repo's ``WorkspaceVcsEvidence`` to its
# store as follow-up. ``publishRoutedEvidence`` is that verb's worker: it
# routes each evidence-only repo to its MO-4-assigned backend and publishes the
# source-free triple. ``repro workspace publish-evidence`` dispatches to it.
# ---------------------------------------------------------------------------

type
  EvidencePublishOutcome* = object
    ## Result of publishing ONE evidence-only repo's source-free evidence.
    repoName*: string
    repoPath*: string
    backendKind*: string
    published*: bool
    headSha*: string
    diagnostic*: string

proc publishRoutedEvidence*(workspaceRoot: string;
    repos: seq[ResolvedRepo]; projectName: string;
    identity: GitToolIdentity; observedAtUnixMs: int64):
    seq[EvidencePublishOutcome] =
  ## MO-13 (correcting MO-5) — the OWNER-side publish operation the
  ## ``repro workspace publish-evidence`` verb performs. For EVERY repo marked
  ## ``participation = "evidence-only"`` (``isEvidenceOnlyRepo``), gather its
  ## source-free ``WorkspaceVcsEvidence`` triple from the local checkout
  ## (``gatherRepoEvidence`` — NO source ever captured) and publish it through
  ## the repo's MO-4-assigned backend (``store.putEvidence``). A no-op (empty
  ## result) when the workspace declares no ``[[locking.route]]`` entries or no
  ## repo is evidence-only, so the all-public default is unchanged. An
  ## evidence-only repo with no assigned backend, or no local checkout to
  ## observe, is reported as a clear non-published outcome (the owner must
  ## publish from a real, clean, published checkout) — never silently skipped.
  result = @[]
  let locking = loadLockingRouting(workspaceRoot)
  if locking.route.len == 0: return @[]
  var anyEvidenceOnly = false
  for repo in repos:
    if isEvidenceOnlyRepo(repo):
      anyEvidenceOnly = true
      break
  if not anyEvidenceOnly: return @[]
  let assignments = resolveRepoBackends(
    locking, repos, workspaceRoot, identity, identity.binaryPath)
  var storeByName = initTable[string, LockStore]()
  var kindByName = initTable[string, string]()
  for asg in assignments:
    storeByName[asg.repoName] = asg.store
    kindByName[asg.repoName] = asg.backendKind
  let toolDigest = digestHex(identity)
  for repo in repos:
    if not isEvidenceOnlyRepo(repo): continue
    var outc = EvidencePublishOutcome(
      repoName: repo.name, repoPath: repo.path,
      backendKind: kindByName.getOrDefault(repo.name))
    let store = storeByName.getOrDefault(repo.name)
    if store.isNil:
      outc.diagnostic = "evidence-only repo '" & repo.name &
        "' has no assigned locking backend to publish evidence to (add a " &
        "`[[locking.route]]` entry for its visibility tier)"
      result.add(outc); continue
    let repoAbs = workspaceRoot / repo.path
    if not dirExists(extendedPath(repoAbs / ".git")):
      outc.diagnostic = "evidence-only repo '" & repo.name &
        "' has no local checkout at '" & repo.path & "' to gather evidence " &
        "from — the OWNER publishes from a clean, published checkout at the " &
        "locked revision"
      result.add(outc); continue
    let rName = gitRemoteNameFor(repo)
    let triple = gatherRepoEvidence(
      identity, repoAbs, repo.path, toolDigest, observedAtUnixMs, remoteName = rName)
    for rec in triple:
      if rec.op == wvqHeadSha and rec.status == wvesResolved:
        outc.headSha = rec.headSha
    let put = store.putEvidence(projectName, repo.name, triple)
    outc.published = put.outcome == spoOk
    if not outc.published:
      outc.diagnostic = "putEvidence failed for evidence-only repo '" &
        repo.name & "': " & put.diagnostic
    result.add(outc)

# ---------------------------------------------------------------------------
# MO-9 — populateLockedDeps bodies + the unified resolver + integrity verify.
# ---------------------------------------------------------------------------

proc lockedDepFromStoreRepo(source: LockSource; repo: ResolvedRepo): LockedDep =
  ## Build one ``LockedDep`` for a repo whose locked revision is supplied by a
  ## ``LockStore`` backend (a manifest-repo SHA lock or an external DB), or — when
  ## ``source.store`` is nil — by the repo's own resolved coordinates (a public
  ## committed-lock repo). The coordinates come from the resolved repo facts; the
  ## INTEGRITY is the VCS-native git object id at the locked revision (the commit
  ## IS the integrity), tagged self-describingly. This is the SAME per-dep shape
  ## the committed-lock source produces from the lock's content, so the two
  ## populate one uniform model.
  var rev = lockedShaFromStore(
    source.store, source.projectName, repo.name, repo.path)
  if rev.len == 0: rev = repo.revision
  var integrity = ""
  if looksLikeSha(rev):
    let repoAbs = source.workspaceRoot / repo.path
    let fmt =
      if dirExists(extendedPath(repoAbs / ".git")): gitObjectFormatOf(repoAbs)
      else: "sha1"
    integrity = gitObjectMultihash(fmt, rev)
  LockedDep(
    name: repo.name, path: repo.path,
    coordinates: Coordinates(kind: ckVcs, url: repo.fetchUrl,
      gitRef: repo.revision, revision: rev),
    integrity: integrity, version: "",
    visibility: lockingTierLabel(repo.visibility),
    participation: repo.participation, depends: repo.depends,
    tags: repo.tags)

proc populateLockedDeps*(source: LockSource): LockedDependencies =
  ## MO-9 — the ONE entry point that fills the MO-8 ``LockedDependencies`` model
  ## from ANY source. Each branch yields the SAME per-dependency shape (a
  ## ``LockedDep`` with checkout COORDINATES + a self-describing INTEGRITY
  ## multihash), so a caller cannot tell — from the populated object — which
  ## source supplied a given repo's locked entry.
  ##
  ##   * ``lskCommittedLock`` — parse the committed ``repro.lock`` (schema v2)
  ##     and return its content verbatim (coordinates + integrity already in the
  ##     lock; NOT re-derived from live ``git HEAD``). A missing / unparseable /
  ##     non-v2 lock yields an empty ``deps`` set so callers fall back cleanly.
  ##   * ``lskManifestRepo`` / ``lskExternalStore`` — for each repo in the
  ##     source's repo-set, read its locked revision from the backend
  ##     ``LockStore`` (the manifest-repo SHA lock, or the external DB) and emit
  ##     a ``LockedDep`` with coordinates + git-native integrity. Both kinds run
  ##     the SAME code — only the backend differs — which is exactly the
  ##     unification: a manifest repo and a database are interchangeable sources.
  case source.kind
  of lskCommittedLock:
    let lockP = committedLockPath(absolutePath(source.workspaceRoot))
    if not fileExists(extendedPath(lockP)):
      return LockedDependencies(schema: SolvedGraphLockSchemaV2, deps: @[])
    try:
      return parseLockedDependencies(readFile(extendedPath(lockP)))
    except CatchableError:
      return LockedDependencies(schema: SolvedGraphLockSchemaV2, deps: @[])
  of lskManifestRepo, lskExternalStore:
    result = LockedDependencies(schema: SolvedGraphLockSchemaV2, deps: @[])
    for repo in source.repos:
      result.deps.add(lockedDepFromStoreRepo(source, repo))

proc resolveWorkspaceLockedDeps*(workspaceRoot, projectName: string;
    identity: GitToolIdentity): LockedDependencies =
  ## MO-9 — the unified resolver the lock-handling algorithms consult. It picks
  ## the source(s) covering the workspace and returns ONE ``LockedDependencies``:
  ##
  ##   * a committed-lock-only workspace (no manifest checkout, no compositional
  ##     ``workspace.toml``, a ``repro.lock`` present) populates entirely from
  ##     the committed-lock source;
  ##   * a manifest / MIXED workspace resolves membership through the shared
  ##     ladder, then routes each repo-set to its MO-4-assigned backend and
  ##     populates EACH repo from its OWN source — a public/committed-lock repo
  ##     from the committed lock (or its coordinates), a team repo from the
  ##     git-checkout SHA lock, a personal repo from the external DB — MERGING
  ##     every per-repo entry into the same object. The gate / sync then consume
  ##     this one object regardless of which source filled any given repo.
  let root = absolutePath(workspaceRoot)
  if not hasResolvedManifestCheckout(root) and
      not isCompositionalWorkspaceToml(root) and
      hasCommittedLockWorkspaceMarker(root):
    return populateLockedDeps(
      LockSource(kind: lskCommittedLock, workspaceRoot: root))
  let (resolved, _) = resolveWorkspaceProjectShared(
    root, projectName, "`repro` workspace resolution")
  result = LockedDependencies(schema: SolvedGraphLockSchemaV2, deps: @[])
  let routing = loadLockingRouting(root)
  # The committed lock (when present) supplies the public / committed-lock repos.
  var lockLd = LockedDependencies(deps: @[])
  let haveLock = hasCommittedLockWorkspaceMarker(root)
  if haveLock:
    lockLd = populateLockedDeps(
      LockSource(kind: lskCommittedLock, workspaceRoot: root))
  if routing.route.len == 0:
    # All-public default: no per-repo-set routing. Every repo is covered by the
    # committed lock if it carries it, else by its resolved coordinates.
    for repo in resolved.repos:
      var placed = false
      for d in lockLd.deps:
        if d.path == repo.path or d.name == repo.name:
          result.deps.add(d); placed = true; break
      if not placed:
        result.deps.add(lockedDepFromStoreRepo(
          LockSource(kind: lskManifestRepo, workspaceRoot: root,
            projectName: resolved.projectName, store: nil), repo))
    return result
  # MIXED: route each repo to its assigned backend and populate from its source.
  let assignments = resolveRepoBackends(
    routing, resolved.repos, root, identity, identity.binaryPath)
  var repoByName = initTable[string, ResolvedRepo]()
  for r in resolved.repos: repoByName[r.name] = r
  for asg in assignments:
    let repo = repoByName.getOrDefault(asg.repoName)
    if asg.store.isNil:
      # Public / committed-lock repo: prefer the committed lock's entry.
      var placed = false
      if haveLock:
        for d in lockLd.deps:
          if d.path == repo.path or d.name == repo.name:
            result.deps.add(d); placed = true; break
      if not placed:
        result.deps.add(lockedDepFromStoreRepo(
          LockSource(kind: lskManifestRepo, workspaceRoot: root,
            projectName: resolved.projectName, store: nil), repo))
    else:
      let kind =
        if asg.backendKind == "external-cli" or asg.backendKind == "committed-file":
          lskExternalStore
        else: lskManifestRepo
      let src = LockSource(kind: kind, workspaceRoot: root,
        projectName: resolved.projectName, repos: @[repo], store: asg.store)
      result.deps.add(populateLockedDeps(src).deps)

# ---------------------------------------------------------------------------
# DS-1..DS-4 — the develop-set lock-set composer (body).
#
# Declared far above, beside the ``repro develop --all`` driver that consumes
# it; the body lives here because it needs the configuration plane
# (``composeLockingRouting`` / ``resolveRepoBackends``) and the ``LockStore``
# backends, none of which are in scope up there.
#
# What it reads, in order:
#   1. the PUBLIC tier's backend — the in-repo committed ``repro.lock``, via
#      ``populateLockedDeps(LockSource(kind: lskCommittedLock, ...))``. This is
#      exactly what the pre-DS-1 driver read, and for a workspace with no
#      routing config it is ALSO the whole answer (byte-identical). Its ABSENCE
#      is NOT a failure — "no single row is a precondition for the others";
#   2. the CONFIGURATION PLANE — ``composeLockingRouting`` folds layers 2..5
#      (system / dotfiles / parent-workspace / VCS-private) and
#      ``resolveRepoBackends`` resolves every participating repo to exactly one
#      ``(tier, backend)``;
#   2b. every DECLARED ROUTE's medium is PROBED FOR READABILITY BEFORE
#      membership is resolved (step "(2b)" in the body below). Membership
#      resolution reads the same media, so a probe placed after it can be
#      pre-empted by membership silently degrading;
#   3. every DISTINCT resolved backend — each read through the SAME
#      ``populateLockedDeps(source)`` entry point, with a commit-keyed
#      ``lockRecordAtCommit`` seed for commit-addressed backends.
#
# Nothing here is a parallel lock reader: the membership ladder, the routing
# composer, the backend construction, the record readers and the populator are
# all the existing machinery.
# ---------------------------------------------------------------------------

proc unreadableBackendRemedy(tierLbl, kind, location: string): string =
  ## The ONE copy-pasteable remedy an unreadable-backend refusal carries. Shared
  ## by the route-level probe (DS-3, before membership) and the per-assignment
  ## probe (DS-3, after membership) so both refusals read identically — the
  ## whole point of "the rule binds the observable outcome, not one code path".
  ## An ABSENT medium and an UNREADABLE one refuse identically (that is the
  ## rule), but they are not fixed the same way, and a remedy that cannot be
  ## pasted is not a remedy. Pick by what is actually on disk, and pick for
  ## EVERY kind — "make the … readable" is prose, not a command, and the rule
  ## asks each refusal to carry one copy-pasteable remedy regardless of which
  ## backend kind happened to be routed.
  if kind == "external-cli":
    if fileExists(extendedPath(location)):
      "make the " & tierLbl & " lock backend program executable (e.g. " &
        "`chmod u+x " & location & "`)"
    else:
      "install the " & tierLbl & " lock backend program at " & location
  elif dirExists(extendedPath(location)):
    "make the " & tierLbl & " lock backend readable (e.g. `chmod -R u+rX " &
      location & "`)"
  elif kind == "git-checkout":
    "clone the " & tierLbl & " lock backend to " & location &
      " (e.g. `git clone <its-remote> " & location & "`)"
  else:
    "create or restore the " & tierLbl & " lock backend at " & location

proc unreadableBackendMessage(tierLbl, kind, location, diag: string): string =
  tierLbl & " lock backend (kind=" & kind & " location=" & location &
    ") could not be read: " & diag & " — " &
    unreadableBackendRemedy(tierLbl, kind, location)

proc lockRecordAtCommitOrAncestor*(store: LockStore; project, repo, sha: string;
                                   gitBin, repoRoot: string;
                                   maxWalk = 4096):
    tuple[rec: Option[StoreLockRecord]; foundAt: string; distance: int] =
  ## DS-5 — the commit-keyed record read, EXTENDED with the FIRST-PARENT
  ## ANCESTRY WALK the resolver behavior of
  ## Workspace-Manifests.md §"No shared lock index" already specifies:
  ##
  ##   > The resolver walks first-parent ancestry to the nearest locked commit
  ##   > when an exact commit has no lock yet.
  ##
  ## This WRAPS ``lockRecordAtCommit`` rather than forking a second reader: the
  ## exact-commit read stays the one entry point, and this proc only decides
  ## WHICH commits to ask it about. A record found at ``sha`` itself answers
  ## with ``distance == 0``; otherwise the first-parent chain of ``sha`` is
  ## walked oldest-first-order-preserved (``git rev-list --first-parent``, which
  ## emits ``sha`` then each first parent in turn) and the FIRST commit holding
  ## a record wins.
  ##
  ## There is deliberately **no branch-tip fallback**: the walk only ever goes
  ## BACKWARD through the asked-for commit's own history, so every candidate is
  ## an ancestor of what the caller asked about. When the whole chain holds
  ## nothing, this answers ``none`` and the caller says so.
  ##
  ## ``foundAt`` is returned so the caller can REPORT which ancestor it landed
  ## on. A pin silently resolved from a different commit than the one asked for
  ## is exactly the class of surprise `repro develop` exists to prevent, so an
  ## ancestor hit is never allowed to look like an exact hit.
  result.foundAt = ""
  result.distance = 0
  result.rec = lockRecordAtCommit(store, project, repo, sha)
  if result.rec.isSome:
    result.foundAt = sha
    return
  if store.isNil or not (store of GitCheckoutLockStore): return
  if gitBin.len == 0 or repoRoot.len == 0 or sha.len == 0: return
  var chain: seq[string]
  try:
    let res = execCmdEx(quoteShell(gitBin) & " -C " & quoteShell(repoRoot) &
      " rev-list --first-parent --max-count=" & $maxWalk & " " &
      quoteShell(sha), options = {poUsePath},
      env = scrubbedGitRepositoryEnv())
    if res.exitCode != 0: return
    for line in res.output.splitLines():
      let c = line.strip()
      if c.len == 40: chain.add(c)
  except CatchableError:
    return
  for idx, ancestor in chain:
    if idx == 0 and ancestor == sha: continue   # already asked, above
    let rec = lockRecordAtCommit(store, project, repo, ancestor)
    if rec.isSome:
      return (rec: rec, foundAt: ancestor, distance: idx)

proc composeDevelopLockSet(workspaceRoot: string; identity: GitToolIdentity;
                           args: DevelopAllArgs): DevelopLockSet =
  let root = absolutePath(workspaceRoot)
  let gitBin = identity.binaryPath
  let strict = args.strict
  result.tierOf = initTable[string, string]()
  result.backendOf = initTable[string, string]()
  result.locationOf = initTable[string, string]()
  result.pinTierOf = initTable[string, string]()
  result.pinBackendOf = initTable[string, string]()
  result.tagsOf = initTable[string, seq[string]]()
  result.projectsOf = initTable[string, seq[string]]()

  # DS-8 — ``--tier=<list>``: which TIERS may contribute records at all. This
  # is a SOURCE-axis restriction: an excluded tier's backend is still probed
  # for readability (an unreadable declared backend is fatal whether or not
  # this invocation wanted its records) but folds nothing, and says so in the
  # inventory. Empty list = no restriction.
  var tierAllowed = initHashSet[string]()
  for t in args.tiers: tierAllowed.incl(t)
  proc tierContributes(tierLbl: string): bool =
    tierAllowed.len == 0 or tierLbl in tierAllowed

  # ---- (1) PUBLIC tier: the in-repo committed lock. ----------------------
  # Kept as the WHOLE result object (schema / platform / solved-graph payload
  # included) so a public-only workspace comes out byte-identical to the
  # pre-DS-1 single-source read.
  #
  # An ABSENT ``repro.lock`` yields an empty ``deps`` set and is recorded as a
  # backend that contributed nothing — NOT as a refusal. "No single row is a
  # precondition for the others": a workspace with no committed lock but a
  # declared team route resolves that route's repos, and only an EMPTY UNION
  # (checked by the caller, which then names every backend below) fails.
  let committedLockP = committedLockPath(root)
  let committedLockPresent = fileExists(extendedPath(committedLockP))
  let publicContributes = tierContributes("public")
  if publicContributes:
    result.lock = populateLockedDeps(
      LockSource(kind: lskCommittedLock, workspaceRoot: root))
  var committedLockReport = DevelopBackendReport(tier: "public",
    backendKind: "committed-lock", location: committedLockP,
    reachable: committedLockPresent,
    diagnostic:
      (if committedLockPresent: ""
       else: "no committed lock at " & committedLockP),
    records: result.lock.deps.len)
  if not publicContributes:
    # DS-8 — ``--tier`` excluded the public tier. The committed lock is not
    # read at all, and the inventory says exactly that rather than implying the
    # file was missing or empty.
    committedLockReport.excluded = true
    committedLockReport.records = 0
  var indexByName = initTable[string, int]()
  # PROVENANCE of each entry already IN the union — which tier/backend actually
  # supplied it. Deliberately distinct from ``result.tierOf`` / ``backendOf``,
  # which carry the repo's RESOLVED ``(tier, backend)`` assignment: for a repo
  # named by two backends those two views differ, and the DS-2 conflict
  # diagnostic must name the tier that supplied the pin it already holds, not
  # the tier the second reader happens to be.
  var provTier = initTable[string, string]()
  var provBackend = initTable[string, string]()
  for i, d in result.lock.deps:
    if d.name.len > 0:
      indexByName[d.name] = i
      provTier[d.name] =
        (if d.visibility.len > 0: d.visibility else: "public")
      provBackend[d.name] = "committed-lock"
      result.pinTierOf[d.name] = provTier[d.name]
      result.pinBackendOf[d.name] = "committed-lock"
      result.tierOf[d.name] = provTier[d.name]
      result.backendOf[d.name] = "committed-lock"

  # ---- (2) The configuration plane. --------------------------------------
  var composed: ComposedRouting
  try:
    composed = composeLockingRouting(root, gitBin)
  except CatchableError as err:
    result.refusals.add("the locking configuration plane could not be " &
      "composed for " & root & ": " & err.msg &
      " — fix the offending configuration layer and re-run")
    return
  # ---- (2a) DS-8 — the INVOCATION layer: ``--lock-store``. ---------------
  #
  # "The escape hatch for contexts that cannot carry a configuration layer."
  # A CI checkout is shallow and has no VCS-private layer-5 config (that file
  # is never pushed, by design), so the private route must be supplied on the
  # command line — and it must COMPOSE with the configuration plane in the same
  # precedence vocabulary rather than bypass it. So each ``--lock-store``
  # becomes an ordinary ``ComposedRoute`` at ``clkInvocation`` (layer 6),
  # appended in argv order so a later one out-precedes an earlier one:
  # "repeatable, in increasing precedence".
  #
  # The entries are built with an EMPTY ``repos`` list here so the readability
  # probe below can run BEFORE membership resolution (an unreadable
  # ``--lock-store`` is fatal exactly like any other declared backend, and must
  # never downgrade to "just use what the config plane found"). The repo list
  # is filled in once membership resolves, at (2c).
  var adhocRoutes: seq[ComposedRoute]
  for ls in args.lockStores:
    var entry = LockingRouteEntry(visibility: lockingTierLabel(ls.tier),
      backend: ls.kind)
    if ls.kind == "external-cli": entry.program = some(ls.location)
    else: entry.path = some(ls.location)
    adhocRoutes.add(ComposedRoute(tier: ls.tier, entry: entry,
      layer: clkInvocation,
      source: "--lock-store=" & ls.spec, repos: @[]))
    if not ls.tierExplicit:
      # NEVER a silent default: every run that leans on the two-field form is
      # told, in the report, which tier it just declared.
      result.keyNotes.add("--lock-store=" & ls.spec &
        " declares a " & lockingTierLabel(ls.tier) & "-tier " & ls.kind &
        " backend at " & ls.location &
        " (the two-field form carries no tier; write " &
        "--lock-store=<tier>:" & ls.kind & ":" & ls.location &
        " to declare another)")
  composed.routes.add(adhocRoutes)

  if not composed.hasExplicitRoutes:
    # No layer declares a route: the built-in public default is the only tier,
    # so the workspace lock set IS the committed lock. Nothing else is read and
    # nothing else is reported — the compatibility contract of DS-1.
    result.backends.add(committedLockReport)
    return

  result.backends.add(committedLockReport)

  # ---- (2b) DS-3, BEFORE membership: probe every DECLARED route's medium. --
  #
  # "'Unreadable' includes degrading to silence. The rule binds the OBSERVABLE
  # OUTCOME, not one code path. […] an unreadable backend must never be allowed
  # to degrade MEMBERSHIP RESOLUTION first, such that its repos never become
  # assignments and the policy above is bypassed entirely."
  #
  # That bypass is real and it is the common shape: the routed medium for a
  # team tier is typically the SAME ``.repro/manifests`` checkout that supplies
  # the workspace's membership. Make it unreadable and membership resolution
  # quietly yields a smaller repo set, so the route's repos never become
  # ``RepoBackendAssignment``s, so no ``LockStore`` is ever constructed for
  # them, so the per-backend probe below never runs — exit 0, set narrowed,
  # nothing said. Probing the DECLARED routes (which come from the
  # configuration plane alone, and are therefore immune to membership
  # degrading) closes that door.
  #
  # Only routes that name a location WITHOUT needing a repo are probed here:
  # ``git-notes`` / ``separate-branch`` without an explicit ``path`` are
  # per-repo media whose location is a repo path, so they have nothing to probe
  # until membership resolves, and they are covered by the per-backend probe.
  var probedRouteLocations = initHashSet[string]()
  # Backends the route-level probe already refused-or-warned about. The
  # per-backend probe below must not report the SAME medium twice (a personal
  # route warns and continues, so its repos may still reach that loop).
  var alreadyReportedUnreadable = initHashSet[string]()
  # DS-8 — which resolved media came from ``--lock-store`` rather than from a
  # configuration file, so `--list` can label them.
  var adhocBackendLocations = initHashSet[string]()
  for route in composed.routes:
    let entry = route.entry
    let kind = entry.backend.strip().toLowerAscii()
    let hasPath = entry.path.isSome and entry.path.get().len > 0
    if kind notin ["git-checkout", "committed-file", "external-cli"] and
        not hasPath:
      continue
    var probeStore: LockStore
    try:
      probeStore = constructRoutedBackend(entry, root, "", identity, gitBin)
    except CatchableError:
      # A malformed route (missing `path`/`program`) is the routing layer's own
      # loud error, raised by ``resolveRepoBackends`` below with the full
      # remedy. Nothing to probe here.
      continue
    if probeStore.isNil: continue
    let location = probeStore.storeLocationLabel()
    let tierLbl = lockingTierLabel(route.tier)
    let probeKey = tierLbl & "\0" & kind & "\0" & location
    if route.layer == clkInvocation: adhocBackendLocations.incl(probeKey)
    if probeKey in probedRouteLocations: continue
    probedRouteLocations.incl(probeKey)
    let diag = probeStore.readabilityDiagnostic()
    if diag.len == 0: continue
    alreadyReportedUnreadable.incl(probeKey)
    var report = DevelopBackendReport(tier: tierLbl, backendKind: kind,
      location: location, reachable: false, diagnostic: diag,
      adhoc: route.layer == clkInvocation)
    report.repos = route.repos
    result.backends.add(report)
    let message = unreadableBackendMessage(tierLbl, kind, location, diag) &
      (if route.layer == clkInvocation:
         " (declared by " & route.source & " for this invocation)"
       elif route.repos.len > 0:
         " (this route declares: " & route.repos.join(", ") & ")"
       else: "")
    # DS-8 — an unreadable ``--lock-store`` is FATAL whatever tier it names,
    # including `personal`: the flag is an explicit, per-invocation assertion
    # that THIS backend is the route, so degrading it to "just use what the
    # configuration plane found" would silently answer a different question
    # than the one asked. The personal-tier warn-and-continue rule exists for a
    # route the user did not restate on this command line.
    if route.tier == wvPersonal and not strict and
        route.layer != clkInvocation:
      result.warnings.add("WARNING: " & message &
        "; continuing without it (pass --strict to make this fatal)")
      for r in route.repos: result.omitted.add(r & " (tier=personal)")
    else:
      result.refusals.add(message)
  if result.refusals.len > 0:
    # A public/team/org medium that cannot be read refuses HERE, before
    # membership resolution is even attempted — otherwise the membership read
    # of that same medium decides the outcome instead of this rule.
    return

  var resolved: ResolvedProject
  try:
    resolved = resolveWorkspaceProjectShared(root, "", "`repro develop`").resolved
  except CatchableError as err:
    result.refusals.add("this workspace declares lock routes, but its " &
      "membership could not be resolved at " & root & ": " & err.msg &
      " — run `repro sync` to materialize the manifest layers, then re-run")
    return

  # ---- (2c) DS-8 — finish the invocation-layer routes now that membership
  #          is known, and DS-7 — record the group / project attribution the
  #          membership axis selects on. -----------------------------------
  #
  # An ad-hoc ``--lock-store`` NAMES every participating repo. A visibility-
  # keyed route would match nothing in exactly the workspaces the flag exists
  # for: a repo carries the default ``wvPublic`` visibility unless a manifest
  # layer says otherwise, and the routes that make such a repo team-tier are
  # the NAMED ones a configuration layer declares — the layer a CI checkout
  # does not have. Naming every repo is what makes the flag able to SUPPLY that
  # missing route rather than merely relocate one that is already there.
  #
  # It is still tier-checked, not a bypass: ``resolveRepoBackends`` requires
  # every named claim on a repo to AGREE on the tier, so an invocation route at
  # a tier the configuration plane contradicts is a loud cross-tier refusal,
  # and within an agreed tier the invocation layer (highest) wins the backend.
  if adhocRoutes.len > 0:
    var allRepoNames: seq[string]
    for r in resolved.repos:
      if r.name.len > 0: allRepoNames.add(r.name)
    var rebuilt: seq[ComposedRoute]
    for r in composed.routes:
      if r.layer != clkInvocation: rebuilt.add(r)
    for r in adhocRoutes:
      var withRepos = r
      withRepos.repos = allRepoNames
      withRepos.entry.repos = allRepoNames
      rebuilt.add(withRepos)
    composed.routes = rebuilt

  for r in resolved.repos:
    if r.name.len == 0: continue
    let tags = effectiveTags(r)
    result.tagsOf[r.name] = tags
    for t in tags:
      if t notin result.knownTags: result.knownTags.add(t)
  result.knownTags.sort()

  # DS-7 ``--project`` attribution. The active project set is the workspace's
  # recorded ``[workspace] projects``; each project is resolved on its own to
  # learn which repos IT contributes. This is MEMBERSHIP bookkeeping and
  # nothing more: ``resolved.projectName`` — the PRIMARY project
  # (Workspace-And-Develop-Mode.md §"The Primary Project") — remains the key
  # every lock-record lookup below uses, whatever ``--project`` names. Keeping
  # them separate is the point: re-keying record lookup off a membership filter
  # would make one commit resolve different pins depending on which projects
  # the caller asked to see.
  result.activeProjects = activeProjectSetOrEmpty(root)
  if result.activeProjects.len == 0 and resolved.projectName.len > 0:
    result.activeProjects = @[resolved.projectName]
  if result.activeProjects.len <= 1:
    for r in resolved.repos:
      if r.name.len > 0:
        result.projectsOf[r.name] = @[result.activeProjects[0]]
  else:
    for p in result.activeProjects:
      var contributed: ResolvedProject
      try:
        contributed = resolveWorkspaceProjectByName(root, p)
      except CatchableError:
        # An unresolvable member of the recorded set is reported by the
        # membership ladder itself; here it simply contributes no attribution,
        # and ``--project=<that name>`` therefore selects nothing — which the
        # exact-name check upstream turns into a loud error rather than a
        # silent empty selection.
        continue
      for r in contributed.repos:
        if r.name.len == 0: continue
        var cur = result.projectsOf.getOrDefault(r.name, @[])
        if p notin cur:
          cur.add(p)
          result.projectsOf[r.name] = cur

  var assignments: seq[RepoBackendAssignment]
  try:
    assignments = resolveRepoBackends(
      composed, resolved.repos, root, identity, gitBin)
  except StoreRoutingError as err:
    result.refusals.add(err.msg)
    return
  except CatchableError as err:
    result.refusals.add("lock-backend routing failed: " & err.msg)
    return

  # ---- (3) Group the assignments by DISTINCT backend. --------------------
  # Two repos of the same tier routed to the same medium share one backend
  # object (``resolveRepoBackends`` caches them), so folding per-backend rather
  # than per-repo reads each medium once. The key carries the tier as well as
  # the medium so a per-tier report line stays meaningful.
  var backendOrder: seq[string]
  var reposOfBackend = initTable[string, seq[ResolvedRepo]]()
  var storeOfBackend = initTable[string, LockStore]()
  var tierOfBackend = initTable[string, WorkspaceVisibility]()
  var kindOfBackend = initTable[string, string]()
  for asg in assignments:
    if asg.store.isNil:
      # A public / committed-lock repo: already supplied by (1). Record its
      # resolved provenance so a conflict diagnostic can name the tier.
      if asg.repoName.len > 0 and not result.tierOf.hasKey(asg.repoName):
        result.tierOf[asg.repoName] = lockingTierLabel(asg.visibility)
        result.backendOf[asg.repoName] = "committed-lock"
      continue
    let key = lockingTierLabel(asg.visibility) & "\0" & asg.backendKind &
      "\0" & asg.store.storeLocationLabel()
    if not reposOfBackend.hasKey(key):
      backendOrder.add(key)
      reposOfBackend[key] = @[]
      storeOfBackend[key] = asg.store
      tierOfBackend[key] = asg.visibility
      kindOfBackend[key] = asg.backendKind
    var repo: ResolvedRepo
    var found = false
    for r in resolved.repos:
      if r.name == asg.repoName: repo = r; found = true; break
    if found:
      reposOfBackend[key] = reposOfBackend[key] & @[repo]
    result.tierOf[asg.repoName] = lockingTierLabel(asg.visibility)
    result.backendOf[asg.repoName] = asg.backendKind
    result.locationOf[asg.repoName] = asg.store.storeLocationLabel()

  # The root repo's identity, for the commit-keyed read of a commit-addressed
  # backend (CLI/develop.md §"Which record, for a commit-addressed backend").
  var rootRepoName = ""
  for r in resolved.repos:
    if r.path == "." or r.path.len == 0: rootRepoName = r.name; break
  # DS-5 — the KEY. Default: the workspace ROOT repo's ``HEAD``.
  # ``--at=<rev>`` overrides it. The override is resolved THROUGH GIT (so a
  # tag, a branch name or an abbreviation names the commit it names) and the
  # result must be a full object id: a key that cannot be resolved is a
  # refusal, never a fall-through to HEAD — asking about one commit and
  # silently being answered about another is the whole hazard here.
  var rootHeadSha = ""
  if rootRepoName.len > 0:
    rootHeadSha = gitHeadShaOf(gitBin, root)
  if args.at.len > 0:
    var resolvedAt = ""
    if gitBin.len > 0:
      try:
        let rp = execCmdEx(quoteShell(gitBin) & " -C " & quoteShell(root) &
          " rev-parse --verify --quiet " & quoteShell(args.at & "^{commit}"),
          options = {poUsePath}, env = scrubbedGitRepositoryEnv())
        if rp.exitCode == 0: resolvedAt = rp.output.strip()
      except CatchableError:
        resolvedAt = ""
    if resolvedAt.len != 40 or not isExactLockedRevision(resolvedAt):
      result.refusals.add("--at=" & args.at & " does not resolve to a commit " &
        "in the workspace root repository at " & root &
        " — commit-addressed lock backends are keyed on a commit of THIS " &
        "repository, and this command never silently keys on a different one. " &
        "Fetch the commit (e.g. `git -C " & root & " fetch --unshallow`) or " &
        "pass a revision this repository has.")
      return
    if rootRepoName.len == 0:
      # No manifest entry places a repo at ``.``, so nothing keys a
      # commit-addressed backend on a commit at all and ``--at`` would be a
      # no-op. Saying so beats appearing to honour it.
      result.keyNotes.add("--at=" & args.at & " resolved to " & resolvedAt &
        ", but this workspace's manifest declares no repo at path \".\", so " &
        "no lock backend is commit-addressed here and the key is unused")
    rootHeadSha = resolvedAt

  for key in backendOrder:
    let store = storeOfBackend[key]
    let tier = tierOfBackend[key]
    let tierLbl = lockingTierLabel(tier)
    let kind = kindOfBackend[key]
    let location = store.storeLocationLabel()
    let repos = reposOfBackend[key]
    var report = DevelopBackendReport(tier: tierLbl, backendKind: kind,
      location: location, reachable: true,
      adhoc: adhocBackendLocations.contains(
        lockingTierLabel(tier) & "\0" & kind & "\0" & location))
    for r in repos: report.repos.add(r.name)

    # DS-3 — an unreachable backend must NEVER narrow the set silently.
    let diag = store.readabilityDiagnostic()
    if diag.len > 0:
      if key in alreadyReportedUnreadable:
        # The route-level probe (2b) already refused-or-warned about this exact
        # medium. Reporting it twice would double the warning and the omitted
        # list; the outcome is unchanged either way.
        continue
      report.reachable = false
      report.diagnostic = diag
      result.backends.add(report)
      let message = unreadableBackendMessage(tierLbl, kind, location, diag)
      if tier == wvPersonal and not strict:
        result.warnings.add("WARNING: " & message &
          "; continuing without it (pass --strict to make this fatal)")
        for r in repos: result.omitted.add(r.name & " (tier=personal)")
      else:
        result.refusals.add(message)
      continue
    # DS-8 — ``--tier`` excluded this tier from contributing. The backend was
    # still PROBED above (a declared backend that cannot be read is fatal
    # whether or not this invocation wanted its records), and it is still named
    # in the inventory — it simply folds nothing.
    if not tierContributes(tierLbl):
      report.excluded = true
      result.backends.add(report)
      continue

    # Remember where this backend's report sits so its contributed-record count
    # can be filled in as the fold below adds entries. The empty-union failure
    # prints that count, so "readable but held nothing" is distinguishable from
    # "contributed, then everything was filtered out".
    let reportIdx = result.backends.len
    result.backends.add(report)

    # DS-5 — a commit-addressed backend is keyed by a commit. The key is the
    # workspace ROOT repo's ``HEAD``, or ``--at=<rev>`` when given, and the
    # record it holds pins every repo the lock covers.
    #
    # When the key itself carries no record the FIRST-PARENT ANCESTRY WALK
    # finds the nearest LOCKED ANCESTOR — the resolver behavior
    # Workspace-Manifests.md §"No shared lock index" already specifies, and the
    # reason a workspace whose HEAD has not been published yet still resolves
    # its pins. The walk only ever goes backward through the key's own history,
    # so there is still NO BRANCH-TIP FALLBACK; and it REPORTS the ancestor it
    # landed on, because a pin silently resolved from a different commit than
    # the one asked for is precisely the surprise this command exists to
    # prevent.
    var commitKeyed = initTable[string, string]()
    if rootRepoName.len > 0 and rootHeadSha.len > 0:
      let hit = lockRecordAtCommitOrAncestor(
        store, resolved.projectName, rootRepoName, rootHeadSha, gitBin, root)
      if hit.rec.isSome:
        commitKeyed = shasFromBody(hit.rec.get().body)
        result.backends[reportIdx].keyedOn = hit.foundAt
        if hit.foundAt != rootHeadSha:
          result.keyNotes.add(tierLbl & " tier / " & kind & " backend (" &
            location & ") holds no lock record for " & rootHeadSha &
            "; the first-parent ancestry walk resolved it from the nearest " &
            "locked ancestor " & hit.foundAt & " (" & $hit.distance &
            " commit(s) back). Every pin below comes from THAT commit's " &
            "record, not from " & rootHeadSha & ".")
      else:
        result.backends[reportIdx].keyedOn = rootHeadSha
        result.keyNotes.add(tierLbl & " tier / " & kind & " backend (" &
          location & ") holds no lock record for " & rootHeadSha &
          " nor for any first-parent ancestor of it; it contributes nothing " &
          "commit-keyed (there is no branch-tip fallback)")

    # The ONE populator entry point, per backend.
    let srcKind =
      if kind == "external-cli" or kind == "committed-file": lskExternalStore
      else: lskManifestRepo
    var backendLd: LockedDependencies
    try:
      backendLd = populateLockedDeps(LockSource(kind: srcKind,
        workspaceRoot: root, projectName: resolved.projectName,
        repos: repos, store: store))
    except CatchableError as err:
      result.refusals.add(tierLbl & " lock backend (kind=" & kind &
        " location=" & location & ") failed while reading its records: " &
        err.msg & " — make the backend readable and re-run")
      continue

    for d0 in backendLd.deps:
      var d = d0
      if d.name.len == 0: continue
      if commitKeyed.hasKey(d.path):
        d.coordinates.revision = commitKeyed[d.path]
      if isEvidenceOnlyLockedDep(d):
        # DS-4 — an evidence-only repo's backend holds MEMBERSHIP plus the
        # source-free evidence triple and NEVER a SHA write
        # (Unified-Locking-And-Hooks.md §6 Decision 1 / §7), so no exact pin is
        # required of it here. It joins the lock set so it can be NAMED (state
        # `evidence-only`) and is excluded from the develop SET downstream —
        # an exclusion that is reported, never silent.
        if not indexByName.hasKey(d.name):
          indexByName[d.name] = result.lock.deps.len
          result.lock.deps.add(d)
          provTier[d.name] = tierLbl
          provBackend[d.name] = kind
          result.pinTierOf[d.name] = tierLbl
          result.pinBackendOf[d.name] = kind
          inc result.backends[reportIdx].records
        continue
      # "A repo is develop-manageable in workspace W if some lock record
      # readable from W NAMES it and PINS IT TO AN EXACT REVISION."
      #
      # ``lockedDepFromStoreRepo`` falls back to the repo's ADVISORY MANIFEST
      # revision when the backend holds no record for it. Sniffing the RESULT
      # for SHA shape is not enough to tell the two apart: it rejects the
      # common branch-name form (``main`` / ``dev``), but a manifest fragment
      # may legitimately pin a SHA directly — that is what ``repo manifest -r``
      # style snapshots emit — and then the advisory revision is indisting-
      # uishable from a real pin, and the repo would enter the develop set at
      # the MANIFEST's revision while its backend held no lock record at all.
      #
      # So ask the backend directly whether it holds a record, and require the
      # answer to also be an exact revision. A repo failing either half
      # contributes nothing, and says so — no branch-tip fallback and no
      # manifest-advisory fallback.
      #
      # "Exact" is ``isExactLockedRevision`` (exactly 40 lowercase hex), NOT the
      # ``looksLikeSha`` heuristic this used to call. That heuristic accepts
      # 7..64 hex, so it admitted an ABBREVIATION, an all-hex BRANCH NAME, and
      # a 41-hex string — and for the 41-hex case the clone ran, the reset
      # failed, and a checkout was left behind at a revision nobody locked.
      # Both halves are checked: the record the backend HOLDS and the revision
      # the populator RESOLVED must each be an exact pin.
      let backendRev =
        if commitKeyed.hasKey(d.path): commitKeyed[d.path]
        else: lockedShaFromStore(store, resolved.projectName, d.name, d.path)
      if backendRev.len == 0 or
          not isExactLockedRevision(backendRev) or
          not isExactLockedRevision(d.coordinates.revision):
        result.noRecord.add(d.name & " (tier=" & tierLbl & " backend=" &
          kind & ")")
        continue
      if indexByName.hasKey(d.name):
        # DS-2 — the same repo named by two backends.
        let idx = indexByName[d.name]
        let existing = result.lock.deps[idx]
        if existing.coordinates.revision == d.coordinates.revision:
          continue   # identical revisions merge silently — one entry
        result.refusals.add(
          "repo '" & d.name & "' is pinned to DIFFERENT revisions by two lock " &
          "backends: " &
          provTier.getOrDefault(d.name, "public") & " tier / " &
          provBackend.getOrDefault(d.name, "committed-lock") &
          " backend pins " & existing.coordinates.revision & ", while the " &
          tierLbl & " tier / " & kind & " backend (" & location & ") pins " &
          d.coordinates.revision & ". Reprobuild does NOT pick a winner: a " &
          "checkout holds one revision, and guessing which backend wins would " &
          "make your source tree depend on the order the backends happened to " &
          "resolve in. Reconcile the two backends so they agree on this repo's " &
          "revision (a repo should be named by exactly one tier's backend).")
        continue
      indexByName[d.name] = result.lock.deps.len
      result.lock.deps.add(d)
      provTier[d.name] = tierLbl
      provBackend[d.name] = kind
      result.pinTierOf[d.name] = tierLbl
      result.pinBackendOf[d.name] = kind
      inc result.backends[reportIdx].records

proc verifyLockedIntegrityAtCoordinates*(workspaceRoot: string;
    ld: LockedDependencies): seq[LockedIntegrityFailure] =
  ## MO-9 — the gate's SOURCE-AGNOSTIC integrity verification. For each locked
  ## dependency that declares an integrity, recompute the multihash over the
  ## content obtained AT THE LOCKED COORDINATES and compare to the locked value:
  ##
  ##   * for a VCS (git) dependency the obtained content is the commit object at
  ##     the locked revision — it must be PRESENT in the checkout (we observe the
  ##     repo's object store) AND its self-describing object id must equal the
  ##     locked integrity. A tampered integrity field, or a coordinate whose
  ##     object is missing/unreachable, fails;
  ##   * for a non-git source the obtained content is the materialized tree,
  ##     recomputed as the NAR-style own-file-hash and compared.
  ##
  ## Because the verification reads ``LockedDep.coordinates`` + ``integrity`` —
  ## fields the populator fills identically from every source — it behaves the
  ## same whether the locked entry came from the committed lock, the manifest SHA
  ## lock, or the external DB.
  result = @[]
  let root = absolutePath(workspaceRoot)
  let gitBin = findExe("git")
  for d in ld.deps:
    if d.integrity.len == 0: continue
    let repoAbs =
      if d.path == "." or d.path.len == 0: root
      else: root / d.path
    case d.coordinates.kind
    of ckVcs:
      if dirExists(extendedPath(repoAbs / ".git")):
        if d.integrity.startsWith("blake3:"):
          # MO-13 (correcting MO-9) — NON-CONSERVATIVE where SAFE. A lock
          # refreshed BEFORE the repo's first commit records a ``blake3:``
          # NAR-style tree hash (a transient content-address) rather than a
          # git object id. MO-9 conservatively SKIPPED such a lock on a git
          # checkout (the git branch only handled ``git-sha`` integrities), so
          # a tampered pre-commit hash slipped through. It is SAFE to verify it
          # non-conservatively: the tree hash is content-addressed and
          # recomputable from the materialized working tree, regardless of the
          # locked revision (empty or not). A tamper now FAILS with a clear
          # diagnostic instead of being silently skipped.
          let observed = narStyleTreeMultihash(collectTreeEntries(repoAbs))
          if observed != d.integrity:
            result.add(LockedIntegrityFailure(name: d.name, path: d.path,
              expected: d.integrity, observed: observed,
              diagnostic: "recomputed tree hash " & observed & " at '" &
                d.path & "' does not match the lock's recorded pre-commit " &
                "integrity " & d.integrity & " (the lock predates the repo's " &
                "first commit; regenerate it if the tree changed legitimately)"))
          continue
        # Git checkout: the VCS-native integrity is the commit object at the
        # locked revision. A MISSING git binary is the one genuinely
        # unverifiable case here (the host cannot recompute a git object id) —
        # skip it rather than fail an environment without git.
        if gitBin.len == 0: continue
        if d.coordinates.revision.len == 0:
          # MO-13 (correcting MO-9) — a git-native integrity with NO concrete
          # revision genuinely cannot be verified (there is no coordinate to
          # recompute the object id at). Surface a CLEAR diagnostic rather than
          # skipping silently, so a stale/malformed lock is named, not ignored.
          result.add(LockedIntegrityFailure(name: d.name, path: d.path,
            expected: d.integrity, observed: "",
            cause: licNoRevisionPinned,
            diagnostic: "lock records a git-native integrity " & d.integrity &
              " for '" & d.path & "' but pins no concrete revision to verify " &
              "it at (regenerate the lock at the repo's current revision)"))
          continue
        if not d.integrity.startsWith("git-sha"): continue
        # Observe the repo: the locked revision's commit object must be present.
        let rp = execCmdEx(quoteShell(gitBin) & " -C " & quoteShell(repoAbs) &
          " rev-parse --verify --quiet " &
          quoteShell(d.coordinates.revision & "^{commit}"),
          options = {poUsePath}, env = scrubbedGitRepositoryEnv())
        if rp.exitCode != 0 or rp.output.strip().len == 0:
          result.add(LockedIntegrityFailure(name: d.name, path: d.path,
            expected: d.integrity, observed: "",
            revision: d.coordinates.revision,
            cause: licRevisionUnreachable,
            diagnostic: "locked revision " & d.coordinates.revision &
              " is not present/reachable in '" & d.path & "'"))
          continue
        let observed =
          gitObjectMultihash(gitObjectFormatOf(repoAbs), d.coordinates.revision)
        if observed != d.integrity:
          result.add(LockedIntegrityFailure(name: d.name, path: d.path,
            expected: d.integrity, observed: observed,
            diagnostic: "recomputed integrity " & observed &
              " at locked coordinates does not match the lock's recorded " &
              "integrity " & d.integrity))
      elif dirExists(extendedPath(repoAbs)) and d.integrity.startsWith("blake3:"):
        # No VCS metadata at the coordinates: the source is NOT
        # content-addressed by a VCS, so verify the materialized tree against
        # Reprobuild's own-file-hash (a NAR-style canonical tree hash).
        let observed = narStyleTreeMultihash(collectTreeEntries(repoAbs))
        if observed != d.integrity:
          result.add(LockedIntegrityFailure(name: d.name, path: d.path,
            expected: d.integrity, observed: observed,
            diagnostic: "materialized content at '" & d.path &
              "' does not match the lock's recorded integrity"))
    of ckStore:
      # MO-11 — a repro-store-realized solved package. The store address is the
      # content hash of the package's solved identity (name + version +
      # platform), so RECOMPUTE that address and require BOTH the ``storeHash``
      # coordinate AND the recorded integrity to equal it. Tampering the
      # coordinate, the integrity, or any identity field diverges -> mismatch.
      let recomputed = solvedPackageStoreHash(d.name, d.version, ld.platform)
      let observed = formatMultihash("blake3", recomputed)
      if d.coordinates.storeHash != recomputed or observed != d.integrity:
        result.add(LockedIntegrityFailure(name: d.name, path: d.path,
          expected: d.integrity, observed: observed,
          diagnostic: "recomputed store integrity " & observed &
            " at the locked store coordinates does not match the lock's " &
            "recorded integrity " & d.integrity))
    of ckRegistry:
      # MO-11 — a registry-sourced solved package. RECOMPUTE the package
      # checksum over the locked registry coordinate (registry + name +
      # version) and compare to the recorded integrity.
      let observed = solvedPackageRegistryIntegrity(
        d.coordinates.registryName, d.name, d.coordinates.registryVersion)
      if observed != d.integrity:
        result.add(LockedIntegrityFailure(name: d.name, path: d.path,
          expected: d.integrity, observed: observed,
          diagnostic: "recomputed registry integrity " & observed &
            " at the locked registry coordinates does not match the lock's " &
            "recorded integrity " & d.integrity))
    of ckForeign:
      discard

proc commitReachableLocally(identity: GitToolIdentity;
                            repoPath, sha: string): bool =
  ## RA-14 optimized-fetch predicate. Return ``true`` iff ``sha`` names a
  ## commit object that is already present (reachable) in the
  ## per-workspace repo at ``repoPath`` — counting objects borrowed from
  ## the shared bare via ``objects/info/alternates`` (RA-5), since
  ## ``git cat-file`` reads through alternates transparently.
  ##
  ## ``cat-file -e <sha>^{commit}`` exits 0 only when the object exists
  ## AND peels to a commit, so a partial/blobless clone that has the
  ## commit but lazily-absent blobs still counts as present (the commit
  ## object itself is always fetched). It exits non-zero — and we return
  ## ``false``, forcing the fetch — whenever the SHA is genuinely absent,
  ## which is exactly the case the optimization must NOT skip.
  if sha.len == 0 or not looksLikeSha(sha):
    return false
  let res = gitRunPlain(identity,
    ["-C", repoPath, "cat-file", "-e", sha & "^{commit}"])
  res.code == 0

proc observeRepoForSync(identity: GitToolIdentity;
                        repoPath: string;
                        resolved: ResolvedRepo;
                        forcePushedSHAs: HashSet[string]): RepoSyncObservation =
  ## Gather everything the M10 planner needs about ONE checkout. A
  ## missing directory short-circuits with ``exists=false``; every
  ## other observation field is filled in best-effort (a failed probe
  ## leaves the field empty so the planner's tolerant-compare logic
  ## degrades to "divergent_feature_branch" rather than crashing).
  if not dirExists(repoPath / ".git"):
    result.exists = false
    return
  result.exists = true
  let headRes = queryGitState(headShaQuery(repoPath), identity)
  if headRes.status == gqsOk:
    result.headSha = headRes.headSha
  let cleanRes = queryGitState(isCleanQuery(repoPath), identity)
  if cleanRes.status == gqsOk:
    result.isClean = cleanRes.isClean
  else:
    # Treat an un-probable status as "not clean" — refuse-and-report
    # is the safer choice when we cannot prove cleanliness.
    result.isClean = false

  # Current branch (empty when detached). Use ``symbolic-ref --short``
  # so the value is the bare branch name like ``main``.
  let branchRes = gitRunPlain(identity,
    ["-C", repoPath, "symbolic-ref", "--short", "-q", "HEAD"])
  if branchRes.code == 0:
    result.currentBranch = branchRes.output.strip()

  # Branch tips (local + remote-tracking).
  let rName = gitRemoteNameFor(resolved)
  if result.currentBranch.len > 0:
    result.localBranchTip = revParse(identity, repoPath,
      "refs/heads/" & result.currentBranch)
    result.remoteBranchTip = revParse(identity, repoPath,
      "refs/remotes/" & rName & "/" & result.currentBranch)

  # Where does the manifest's revision actually point in this clone?
  # SHA pin → itself; branch pin → ``remoteName/<branch>`` (matches M9's
  # ``expectedBranchTip``).
  if resolved.revision.len > 0:
    if looksLikeSha(resolved.revision):
      result.lockedRevisionTip = resolved.revision
    else:
      result.lockedRevisionTip = expectedBranchTip(identity, repoPath,
        resolved.revision, remoteName = rName)

  # Unpublished commits: the M2 ``isPublished`` query already answers
  # "is HEAD on any remote tracking branch". We also fall back to the
  # local-vs-remote tip compare when ``isPublished`` cannot be probed
  # (e.g. brand-new branch with no upstream).
  let pubRes = queryGitState(
    isPublishedQuery(repoPath, rName), identity)
  if pubRes.status == gqsOk:
    result.hasUnpublishedCommits = not pubRes.isPublished
  else:
    # If we can't tell published-vs-not, only flag when there is a
    # concrete local-vs-remote disagreement we can attribute to local
    # work (i.e. local tip strictly ahead of remote tip).
    if result.remoteBranchTip.len > 0 and result.headSha.len > 0 and
        result.remoteBranchTip != result.headSha:
      # ``hasUnpublishedCommits`` is "local has commits beyond remote".
      # The planner does not require an exact ahead-count; it only
      # needs to know that the operator owns work we shouldn't touch.
      let ancestorRes = gitRunPlain(identity, ["-C", repoPath,
        "merge-base", "--is-ancestor", result.headSha, result.remoteBranchTip])
      result.hasUnpublishedCommits = ancestorRes.code != 0

  if result.currentBranch.len > 0 and forcePushedSHAs.len > 0:
    let remoteRef = "refs/remotes/" & rName & "/" & result.currentBranch
    let logRes = gitRunPlain(identity, ["-C", repoPath, "log", "--format=%H", remoteRef & "..HEAD"])
    if logRes.code == 0:
      for rawSha in logRes.output.strip().splitLines():
        let sha = rawSha.strip()
        if sha.len > 0 and sha in forcePushedSHAs:
          result.hasForcePushedCommits = true
          result.forcePushedBaseSha = sha
          break

# ---- RA-5c: parallel fetch / checkout phases ------------------------------
#
# The sync/pull path used to run repo-by-repo: a serial per-repo
# pre-classification ``git fetch`` followed by a serial per-repo one-action
# build graph for the checkout/merge/attach mutation. RA-5c replaces both
# with two engine-scheduled phases, modelled after Google ``repo``'s
# ``subcmds/sync.py``:
#
#   Phase A (network)  — one graph of per-repo ``git fetch`` actions, each
#       tagged to the ``vcs/fetch`` named pool (capacity = jobs-network) so
#       RunQuota bounds network concurrency. The fetch is a ``bakProcess``
#       git subprocess (not a synchronous ``gitRunPlain``) so the engine's
#       running-set genuinely overlaps the fetches. The single shared-state
#       write — refreshing each unique upstream's shared bare — is done once
#       up front before the graph runs, so concurrent fetches read a
#       consistent object pool without racing a fetch into the same bare.
#
#   (classification) — the planner runs between the phases: it needs the
#       post-fetch ``<remote>/<branch>`` tip to tell "clean at locked" from
#       "fast-forwardable". This is exactly ``repo``'s ``--no-interleaved``
#       barrier, which the planner-in-the-middle makes mandatory here.
#
#   Phase B (checkout) — one graph of per-repo mutating actions
#       (``gitCloneAction`` / ``gitMergeFfAction`` / ``gitSwitchAction``),
#       run once through the engine. These consume CPU slots
#       (jobs-checkout).
#
# Determinism is preserved: a fetch only updates ``refs/remotes/<remote>/*``
# (never the working tree), the planner classification is unchanged, and the
# resolved revisions are identical to the old serial path. Dirty /
# locally-unpublished / divergent-feature-branch checkouts are still
# classified AFTER the fetch and never mutated.

const SyncFetchPool = "vcs/fetch"

proc syncFetchActionFor(identity: GitToolIdentity; workspaceRoot: string;
                        repo: ResolvedRepo; repoIdx: int;
                        sharedBareRefreshDep: string): BuildAction =
  ## Build a ``vcs/fetch``-pooled ``git fetch --quiet <remote>`` action for
  ## one existing checkout. The action runs as a ``bakProcess`` subprocess
  ## (genuinely parallel through the engine's running set, RunQuota-bound
  ## by the pool capacity) rather than a synchronous ``gitRunPlain``. A pure
  ## ``git fetch`` is a network action with no monitorable file evidence, so
  ## it is marked NON-CACHEABLE (always re-run) under the spec baseline rather
  ## than completed on declared inputs — the removed ``dgNoRuntimeDependencies``
  ## declared-only mode MUST NOT be re-added (Reprobuild-Development M17,
  ## Monitor-Hook-Shim.md:501). ``action()`` defaults ``cacheable = false`` and
  ## ``automaticMonitorGatheringPolicy()``; the fetch carries no declared
  ## outputs and its effect (updated remote-tracking refs) is observed by the
  ## post-fetch classification, not cached.
  let repoAbs = workspaceRoot / repo.path
  let id = "workspace-sync-fetch-" & safeRepoIdSegment(repo.name) &
    "-" & $repoIdx
  var deps: seq[string]
  if sharedBareRefreshDep.len > 0:
    deps.add(sharedBareRefreshDep)
  let rName = gitRemoteNameFor(repo)
  result = action(id,
    @[identity.binaryPath, "-C", repoAbs, "fetch", "--quiet", rName],
    # Named-Lock-Files §7.2. `repro sync` fetches workspace CHECKOUTS;
    # `Workspace-Manifests.md` §"Mode-agnostic" keeps checkout state out of
    # the lock entirely. See `lockIdentityOutsideSolvedGraph`.
    governingLockIdentity = lockIdentityOutsideSolvedGraph(),
    cwd = workspaceRoot,
    deps = deps,
    pool = SyncFetchPool,
    poolUnits = 1'u32,
    cacheable = false)

proc syncCheckoutActionFor(identity: GitToolIdentity; workspaceRoot: string;
                           resolved: ResolvedRepo; decision: RepoSyncDecision;
                           repoIdx: int;
                           cloneReferencePath = ""): tuple[hasAction: bool;
                           action: BuildAction; immediateStatus: string;
                           immediateDiagnostic: string] =
  ## Translate one planner decision into a mutating ``bakWorkspaceVcs``
  ## action for the checkout phase, OR an immediate status string for the
  ## no-mutation cases (``noop`` / ``refused``). The returned actions are
  ## collected into ONE graph and run together (jobs-checkout parallelism)
  ## instead of a per-repo serial graph.
  ##
  ## RA-23: ``cloneReferencePath`` is the shared bare (RA-5) for a
  ## ``missing_checkout`` → ``saClone`` repo's upstream URL, so cloning a
  ## newly-declared dependency reuses the same shared-object-cache
  ## acceleration the ``init`` clone path uses (an empty path falls back to
  ## a standalone clone, exactly like init).
  let receiptDir = workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  let idSeg = safeRepoIdSegment(resolved.name) & "-" & $repoIdx
  case decision.action
  of saNone:
    if decision.syncCase in {scDirty, scLocallyUnpublished, scForcePushRebase}:
      # Named-Lock-Files §7.2. `hasAction: false` means the `action` field
      # is never read; the identity is supplied because the type requires it,
      # and it is the honest one for an edge that does not exist.
      return (false, noScheduledAction(), "refused", decision.refusalReason)
    return (false, noScheduledAction(), "noop", "")
  of saClone:
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("sync-clone-" & idSeg & ".receipt")
    # RA-16 resume correctness: a clone the planner schedules is, by
    # construction, for a checkout that is genuinely MISSING (the planner
    # only emits ``missing_checkout`` → ``saClone`` when ``.git`` is
    # absent). The clone's cached receipt records only the resolved SHA,
    # NOT the materialized working tree, so a cache hit would replay the
    # receipt WITHOUT re-creating a deleted / half-cloned tree — the exact
    # "interrupted clone, no usable checkout" case resume must redo. We
    # therefore make the sync clone NON-CACHEABLE so a re-run always
    # actually re-materializes the missing repo. This does not slow the
    # common resume case: a COMPLETED repo classifies as
    # ``clean_at_locked_revision`` (a planner-level noop), so no clone
    # action is scheduled for it at all — only the genuinely-incomplete
    # repo pays for the re-clone.
    var a = gitCloneAction("workspace-sync-clone-" & idSeg, identity,
      remoteUrl = cloneUrlFor(resolved),
      repoPath = resolved.path,
      receiptPath = receiptRel,
      revision = resolved.revision,
      cacheable = false,
      referencePath = cloneReferencePath,
      cloneFilter = resolved.cloneFilter,
      depth = resolved.depth,
      singleBranch = resolved.singleBranch)
    a.cwd = workspaceRoot
    a.pool = SyncFetchPool
    a.poolUnits = 1'u32
    return (true, a, "", "")
  of saFetchFastForward:
    # The fetch phase already advanced ``<remote>/<branch>``. The planner
    # established HEAD is an ancestor of it (strict fast-forward) on a
    # clean tree. ``gitMergeFfAction`` runs ``git merge --ff-only`` as an
    # engine action (RA-5c: no more synchronous ``gitRunPlain`` merge).
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("sync-merge-ff-" & idSeg & ".receipt")
    let rName = gitRemoteNameFor(resolved)
    var a = gitMergeFfAction("workspace-sync-merge-ff-" & idSeg, identity,
      remoteName = rName,
      branchName = decision.branch,
      repoPath = resolved.path,
      receiptPath = receiptRel)
    a.cwd = workspaceRoot
    return (true, a, "", "")
  of saAttachBranch:
    # Detached HEAD at the locked revision — re-attach by switching to the
    # manifest's pinned branch. ``gitSwitchAction`` (gvoSwitch) is the
    # engine action; it refuses on a dirty tree, but the detached-at-locked
    # case the planner emits this for is clean by construction.
    let targetBranch =
      if resolved.revision.len > 0 and not looksLikeSha(resolved.revision):
        resolved.revision
      else:
        "main"
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("sync-attach-" & idSeg & ".receipt")
    var a = gitSwitchAction("workspace-sync-attach-" & idSeg, identity,
      branchName = targetBranch,
      repoPath = resolved.path,
      receiptPath = receiptRel,
      cacheable = false)
    a.cwd = workspaceRoot
    return (true, a, "", "")
  of saForcePushRebase:
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("sync-force-push-rebase-" & idSeg & ".receipt")
    let rName = gitRemoteNameFor(resolved)
    var a = gitForcePushRebaseAction("workspace-sync-force-push-rebase-" & idSeg, identity,
      branchName = decision.branch,
      baseSha = decision.forcePushedBaseSha,
      repoPath = resolved.path,
      receiptPath = receiptRel,
      remoteName = rName)
    a.cwd = workspaceRoot
    return (true, a, "", "")

# ---- RA-9: shared destructive-command confirmation ------------------------
#
# ``remove`` / ``checkout`` / ``sync --force-sync`` all DISCARD uncommitted
# sibling work when they proceed. Per RA-9 (and Interactive-UX-And-Progress
# §"communicate before execute") they must share ONE confirmation contract:
#
#   1. The CALLER prints a per-repo PREVIEW of the effect first (so the
#      operator sees what is about to be discarded BEFORE any mutation).
#   2. ``--yes`` / ``--force`` opts out of the prompt and proceeds.
#   3. Otherwise a prompt is only answerable on a TTY. In a non-interactive
#      context (stdin is not a TTY — the natural state under ``execCmdEx``)
#      we REFUSE CLEANLY with a clear message naming the opt-out flag and a
#      non-zero exit; we NEVER block on ``stdin.readLine`` that can never be
#      answered.
#   4. On a TTY we ask once; ``y``/``yes`` confirms, anything else declines.
#
# ``confirmDestructive`` is the single chokepoint. TTY detection is injected
# (``isTty``) so tests can drive the non-TTY refuse path deterministically
# (``isatty(stdin)`` is false under ``execCmdEx``), and the refuse message is
# parameterized so each command names its own flag.

type
  DestructiveDecision* = enum
    ## Outcome of the shared RA-9 confirmation chokepoint.
    ddConfirmed        ## opt-out flag set, or a TTY operator answered "yes".
    ddRefusedNonTty    ## non-TTY without the opt-out flag → refuse cleanly.
    ddDeclined         ## TTY operator answered "no".

proc confirmDestructive*(prompt: string; autoYes: bool; isTty: bool;
                         flagName: string; refuseMessage: string;
                         declineMessage = ""): DestructiveDecision =
  ## The single destructive-command confirmation gate shared by
  ## ``remove`` (``--force``), ``checkout`` (``--yes``) and
  ## ``sync --force-sync`` (``--yes``). The caller is responsible for
  ## printing the per-repo preview BEFORE calling this. ``flagName`` is the
  ## opt-out flag named in the non-TTY refusal so the operator knows exactly
  ## how to proceed. Returns the decision; the caller maps it to an exit
  ## code and acts (or not) accordingly. This proc NEVER reads stdin unless
  ## ``isTty`` is true, so it can never hang in a non-interactive context.
  if autoYes:
    return ddConfirmed
  if not isTty:
    stderr.writeLine(refuseMessage & " (re-run with " & flagName &
      " to confirm)")
    return ddRefusedNonTty
  stderr.write(prompt)
  stderr.flushFile()
  var answer: string
  try:
    answer = stdin.readLine().strip().toLowerAscii()
  except CatchableError:
    # ``isatty`` reported a TTY, yet the read failed. On Windows a console
    # handle attached to a non-interactive context (CI / an agent harness)
    # reports ``isatty == true`` but ``ReadConsole`` fails with
    # ERROR_INVALID_FUNCTION ("Incorrect function"); POSIX would have
    # returned EOF on a closed stdin. Either way we could not obtain an
    # answer, so refuse cleanly (matching the non-TTY contract) instead of
    # crashing the destructive command.
    stderr.writeLine("")
    stderr.writeLine(refuseMessage & " (re-run with " & flagName &
      " to confirm)")
    return ddRefusedNonTty
  if answer == "y" or answer == "yes":
    return ddConfirmed
  if declineMessage.len > 0:
    stderr.writeLine(declineMessage)
  ddDeclined

type
  OfferDecision* = enum
    ## Outcome of the shared "offer to run a SAFE remedy" prompt
    ## (Interactive-UX-And-Progress.md Principle 2: "offer to run it
    ## where safe"). Unlike ``confirmDestructive`` this gates a
    ## NON-destructive fix, so the default in a non-TTY is to DESCRIBE the
    ## remedy (print the copy-pasteable command) rather than run it — the
    ## operator opts in to auto-run with ``--offer-fixes`` /
    ## ``REPRO_OFFER_FIXES=1`` (the same opt-in shape as ``health --fix``).
    odRun          ## opt-in flag/env set, or a TTY operator answered "yes".
    odDescribed    ## non-TTY without opt-in → printed the remedy, did not run.
    odDeclined     ## TTY operator answered "no".

proc offerFixesOptIn*(): bool =
  ## True when the operator has opted into auto-running safe remedies in a
  ## non-interactive context. Honoured by every offer-to-run site so the
  ## behavior is uniform (CI / agents set the env once).
  let v = getEnv("REPRO_OFFER_FIXES").strip().toLowerAscii()
  v == "1" or v == "true" or v == "yes" or v == "on"

proc offerSafeRemedy*(description: string; remedyCommand: string;
                      autoRun: bool; isTty: bool): OfferDecision =
  ## The shared offer-to-run gate for a SAFE, non-destructive remedy
  ## (Principle 2 "offer to run it where safe"). The caller prints any
  ## context first, then calls this with a one-line ``description`` of what
  ## the remedy does and the exact ``remedyCommand`` string (always shown,
  ## so a refusal is never just "no"). Returns:
  ##   - ``odRun``       when ``autoRun`` (``--offer-fixes`` /
  ##                     ``REPRO_OFFER_FIXES``) OR a TTY operator answered
  ##                     "yes" — the caller performs the remedy.
  ##   - ``odDescribed`` in a non-TTY without opt-in — the remedy command is
  ##                     printed; the caller does NOT run it (honest: we
  ##                     never silently mutate state in a script).
  ##   - ``odDeclined``  when a TTY operator answered "no".
  ## This proc NEVER reads stdin unless ``isTty`` is true, so it can never
  ## hang in a non-interactive context.
  if autoRun:
    stderr.writeLine("offering safe remedy (auto-run): " & description &
      " — running `" & remedyCommand & "`")
    return odRun
  if not isTty:
    stderr.writeLine("safe remedy available: " & description &
      " — run `" & remedyCommand & "`" &
      " (or set REPRO_OFFER_FIXES=1 to run it automatically)")
    return odDescribed
  stderr.write(description & " — run `" & remedyCommand & "` now? [y/N] ")
  stderr.flushFile()
  let answer = stdin.readLine().strip().toLowerAscii()
  if answer == "y" or answer == "yes":
    return odRun
  stderr.writeLine("remedy not run; to fix manually: " & remedyCommand)
  odDeclined

type
  ForceSyncGuardOutcome = enum
    ## Result of the RA-16 / RA-9 destructive-command safety gate for
    ## ``--force-sync``.
    fsgNoTargets       ## no divergent/dirty repos → nothing to force, sync as normal.
    fsgConfirmed       ## the overwrite is authorized (``--yes``/``--force`` or a TTY confirm).
    fsgRefusedNonTty   ## non-TTY with no ``--yes`` → refuse cleanly (do not hang, do not overwrite).
    fsgDeclined        ## interactive operator answered "no".

  ForceSyncTarget = object
    repoIdx: int
    path: string
    syncCase: SyncCase
    observed: string
    expected: string

proc forceSyncGuard(args: WorkspaceSyncArgs;
                    targets: seq[ForceSyncTarget]): ForceSyncGuardOutcome =
  ## RA-16 ``--force-sync`` is a destructive multi-repo command, so it is
  ## subject to the RA-9 destructive-command safety rules: PREVIEW the
  ## per-repo effect, then CONFIRM. ``--yes``/``--force`` opts out of the
  ## prompt. In a non-interactive context (no TTY) WITHOUT the flag we
  ## REFUSE cleanly with a clear message rather than hanging on a prompt
  ## that can never be answered. A normal sync (no ``--force-sync``) never
  ## reaches this gate and keeps report-only-skipping divergent repos.
  if targets.len == 0:
    return fsgNoTargets
  # Preview: one line per repo we are about to OVERWRITE.
  stderr.writeLine("repro workspace sync --force-sync will OVERWRITE " &
    $targets.len & " checkout(s) to the locked revision (discarding local " &
    "changes):")
  for t in targets:
    stderr.writeLine("  " & t.path & " [" & syncCaseTag(t.syncCase) & "]" &
      (if t.observed.len > 0: " " & t.observed else: "") &
      " → " & t.expected)
  # RA-9: defer the opt-out / TTY / non-TTY decision to the shared
  # ``confirmDestructive`` chokepoint so ``--force-sync`` refuses in a
  # non-interactive context identically to ``remove`` and ``checkout``.
  case confirmDestructive(
      prompt = "Overwrite the checkout(s) above? This DISCARDS local " &
        "changes. [y/N] ",
      autoYes = args.assumeYes,
      isTty = isatty(stdin),
      flagName = "--yes",
      refuseMessage = "refusing to --force-sync in a non-interactive " &
        "context without --yes/--force (would discard local changes)",
      declineMessage =
        "force-sync declined; leaving divergent checkouts untouched")
  of ddConfirmed: fsgConfirmed
  of ddRefusedNonTty: fsgRefusedNonTty
  of ddDeclined: fsgDeclined

proc loadForcePushedCommits(workspaceRoot: string): JsonNode =
  let path = workspaceRoot / ".repro" / "workspace" / "force-pushes.json"
  if fileExists(path):
    try:
      return parseFile(path)
    except CatchableError:
      discard
  newJObject()

proc saveForcePushedCommits(workspaceRoot: string; node: JsonNode) =
  let dir = workspaceRoot / ".repro" / "workspace"
  createDir(dir)
  let path = dir / "force-pushes.json"
  writeFile(path, pretty(node, indent = 2) & "\n")

proc executeWorkspaceSync(args: WorkspaceSyncArgs): WorkspaceSyncOutcome =
  ## End-to-end driver. (1) Refresh manifest layers so the composer
  ## reads the freshest manifest data. (2) Resolve the project / compose
  ## layers. (3) Gather an observation for every declared repo. (4) Run
  ## the planner. (5) Execute the resulting actions through M2's
  ## executor. (6) Emit the structured report.
  var report: WorkspaceSyncReport
  report.workspaceRoot = args.workspaceRoot

  # Step 1: manifest-layer refresh. RA-27 ``--dry-run`` must not mutate
  # anything — the manifest-layer refresh fast-forwards the manifest repo's
  # own checkout, which is a mutation — so a dry run skips it and resolves
  # against the on-disk manifest as-is (stale manifest data is acceptable
  # for a preview).
  if not args.dryRun:
    let refresh = refreshManifestLayers(args.workspaceRoot)
    for entry in refresh.layers:
      report.manifestLayers.add(WorkspaceSyncManifestLayerEntry(
        index: entry.index,
        provenance: entry.provenance,
        layerPath: entry.layerPath,
        status: manifestLayerStatusTag(entry.status),
        beforeSha: entry.beforeSha,
        afterSha: entry.afterSha,
        diagnostic: entry.diagnostic))

  # Step 2: resolve (or compose) the project.
  #
  # RA-27 scoped sync: ``repro workspace sync <projectA> <projectB>`` syncs
  # ONLY the named projects' repos. When scope projects are given we resolve
  # the FULL workspace set independent of the positionals — preferring a
  # composer ``workspace.toml`` or a metadata-recorded project so that the
  # positionals act purely as a SCOPE FILTER (not as the resolution target).
  # That is what makes the filter load-bearing: the full set may span more
  # repos than the named project, and the filter narrows it down. In a plain
  # single-project workspace (no ``workspace.toml`` at all) there is nothing
  # else to resolve, so the first scope project is the base — the union then
  # equals that project's repos and the pre-RA-27 behavior is preserved.
  var resolveArgs = args
  if args.scopeProjects.len > 0:
    let workspaceToml = workspaceTomlPath(args.workspaceRoot)
    var haveBase = isCompositionalWorkspaceToml(args.workspaceRoot)
    if not haveBase and fileExists(workspaceToml):
      try:
        haveBase =
          readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project.len > 0
      except WorkspaceManifestParseError:
        haveBase = false
    if haveBase:
      # Resolve the recorded/composed workspace, not the positional, so the
      # scope filter below can narrow the full set.
      resolveArgs.projectName = ""
  var resolved = resolveWorkspaceSyncProject(resolveArgs)
  report.project = resolved.projectName
  report.scopeProjects = args.scopeProjects
  report.dryRun = args.dryRun

  # Apply the scope filter: keep only repos that belong to one of the named
  # projects (the resolver already knows project→repos). An unknown name
  # raises a clear error inside ``scopeRepoPathSet`` (Principle 2).
  if args.scopeProjects.len > 0:
    let scopePaths = scopeRepoPathSet(args.workspaceRoot, args.scopeProjects)
    var kept: seq[ResolvedRepo]
    for repo in resolved.repos:
      if repo.path in scopePaths:
        kept.add(repo)
    resolved.repos = kept

  # RA-18: subset selection by manifest tag. ``--tags=a,b`` keeps only
  # repos carrying one of the requested tags; ``-<tag>`` excludes. A repo with
  # no declared ``tags`` carries the implicit ``default`` tag, so a
  # plain ``--tags=default`` (or no filter at all) keeps every untagged
  # repo. When no tag flags are given the filter is a no-op and the repo
  # set is exactly the resolved set (no regression for fragments without
  # ``tags``).
  if args.includeTags.len > 0 or args.excludeTags.len > 0:
    var kept: seq[ResolvedRepo]
    for repo in resolved.repos:
      if repoSelectedByTags(repo, args.includeTags, args.excludeTags):
        kept.add(repo)
    resolved.repos = kept

  # RA-27 Principle 1: ANNOUNCE the plan before acting. Build a real
  # preview from the now-final participating repo set + the cheap on-disk
  # presence check (clone vs update). This is computed BEFORE any fetch /
  # clone, so under ``--dry-run`` we can print it and return without ever
  # touching the network or the working trees.
  for repo in resolved.repos:
    let repoPath = args.workspaceRoot / repo.path
    let intended =
      if dirExists(repoPath / ".git"): "update"
      else: "clone"
    report.plan.add(WorkspaceSyncPlanEntry(
      name: repo.name, path: repo.path, fetchUrl: repo.fetchUrl,
      intendedAction: intended, revision: repo.revision))

  # RA-27 ``--dry-run``: the plan is the deliverable; STOP before any
  # mutating phase. No manifest-layer refresh has touched a working tree
  # (it only fast-forwards the manifest repo's own checkout), and no
  # per-repo fetch/clone/merge runs. Exit 0 — a dry run is informational.
  if args.dryRun:
    report.exitCode = 0
    result.report = report
    return

  # Step 3: resolve the git identity once.
  let identity = ensureGitToolResolvable(
    args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()
  alignWorkspaceRemotes(args.workspaceRoot, resolved.repos, identity)

  # RA-5c jobs resolution: ``--jobs-network`` (or ``--jobs``) bounds the
  # ``vcs/fetch`` pool; ``--jobs-checkout`` (or ``--jobs``) bounds the
  # checkout phase's CPU parallelism. Both default through built-in
  # baselines when unset — these are RunQuota budgets, not a second engine
  # knob (RA-13).
  let jobsNetwork = resolveJobs(args.jobsNetwork, args.jobs,
    SyncDefaultJobsNetwork)
  let jobsCheckout = resolveJobs(args.jobsCheckout, args.jobs,
    int(osproc.countProcessors()))
  let engineCacheRoot = args.workspaceRoot / ".repro" / "workspace" /
    "engine-cache"

  # Step 3a (RA-5c): parallel pre-classification fetch. Every existing
  # checkout is fetched so the post-fetch ``origin/<branch>`` ref reflects
  # the remote's current tip BEFORE the planner classifies. Without this a
  # clone strictly behind a now-advanced ``origin/main`` would be
  # misclassified as "clean_at_locked_revision". A fetch only updates
  # ``refs/remotes/origin/*``, never the working tree, so it is safe even
  # on a dirty / locally-unpublished checkout (refuse-and-report
  # classifications are still made AFTER this pass).
  #
  # The fetches run as ONE graph of ``vcs/fetch``-pooled ``bakProcess``
  # actions: the engine + RunQuota overlap them up to ``jobs-network``
  # instead of the old repo-by-repo serial loop. The single shared-state
  # write — refreshing each unique upstream's shared bare — is done once up
  # front per URL and made a dependency of that URL's fetches so concurrent
  # fetches read a consistent object pool without racing into the same
  # bare.
  let cacheRoot = defaultCacheRoot(args.workspaceRoot)

  # RA-14 optimized-fetch: load the locked ``path -> sha`` map once so the
  # fetch loop can skip the network round-trip for any repo already at (or
  # past) its locked SHA. A branch-pinned fragment records its concrete
  # SHA in the lock file; a SHA-pinned fragment carries it inline. When no
  # lock exists the map is empty and every existing tree is fetched (the
  # pre-RA-14 behavior), so the optimization can never skip a fetch the
  # workspace genuinely needs.
  var lockedShasByPath = initTable[string, string]()
  block:
    # Membership resolves at the workspace root (or a `.repro/manifests`
    # checkout); the lock records live in the `.repro/manifests` store DB.
    let storeRoot = args.workspaceRoot / ".repro" / "manifests"
    if resolved.projectName.len > 0 and dirExists(storeRoot):
      try:
        # MO-10: route the RA-14 optimized-fetch lock read through the abstract
        # ``LockStore``. The git-checkout backend's ``latestLockShas`` delegates
        # to the byte-identical ``latestLockShasViaGit``; we take its ``shas``
        # exactly as before.
        let fetchStore: LockStore =
          newGitCheckoutLockStore(identity, storeRoot)
        lockedShasByPath = fetchStore.latestLockShas(resolved.projectName).shas
      except CatchableError:
        lockedShasByPath = initTable[string, string]()

  # HL-7 (§5 durability + §8.4 capstone) — the durable lock-storage plane is
  # not limited to the ``.repo/manifests`` git-checkout: a personal/team repo's
  # locked SHA lives in ITS assigned durable backend (a private manifests repo,
  # an external-cli DB, …) resolved by the HL-1 configuration plane (§4). On a
  # FRESH MACHINE the config plane arrives via synced dotfiles (an ``apply-if``
  # route, Plane A) and the durable lock via the pushed backend (Plane B); the
  # ``.repo/manifests`` map above holds ONLY the repos routed to that backend
  # (none, for a personal-only restore). Compose the routing and merge each
  # ROUTED repo's locked SHA from its assigned backend, so the reconstruction
  # below lands every tier's repo at the revision its own durable backend pins
  # — not just the manifest tier's. A no-explicit-route workspace composes to no
  # routed backends, so this is a byte-identical no-op there (RA-14 unchanged).
  if resolved.projectName.len > 0:
    try:
      let syncComposed = composeLockingRouting(
        args.workspaceRoot, identity.binaryPath)
      if syncComposed.hasExplicitRoutes:
        let syncAssignments = resolveRepoBackends(
          syncComposed, resolved.repos, args.workspaceRoot, identity,
          identity.binaryPath)
        for asg in syncAssignments:
          if asg.store.isNil: continue
          let revision = lockedShaFromStore(asg.store,
            resolved.projectName, asg.repoName, asg.repoPath)
          if revision.len > 0:
            lockedShasByPath[asg.repoPath] = revision
    except CatchableError:
      # Best-effort: an unresolvable routing layer must never break a plain
      # sync. The reconstruction below simply falls back to the manifest map.
      discard

  proc lockedShaFor(repo: ResolvedRepo): string =
    ## The concrete SHA the fetch would need to make reachable for this
    ## repo: a SHA-pinned revision is itself; otherwise the lock file's
    ## recorded SHA for this path (empty when unknown → never skip).
    if repo.revision.len > 0 and looksLikeSha(repo.revision):
      return repo.revision
    lockedShasByPath.getOrDefault(repo.path)

  var oldRemoteTips = newSeq[string](resolved.repos.len)
  for repoIdx, repo in resolved.repos:
    let repoPath = args.workspaceRoot / repo.path
    if dirExists(repoPath / ".git") and repo.revision.len > 0 and not looksLikeSha(repo.revision):
      let rName = gitRemoteNameFor(repo)
      oldRemoteTips[repoIdx] = revParse(identity, repoPath,
        "refs/remotes/" & rName & "/" & repo.revision)

  var sharedBareRefreshAction = initTable[string, string]()
  var fetchActions: seq[BuildAction]
  var refreshActions: seq[BuildAction]
  var optimizedFetchSkips = 0
  for repoIdx, repo in resolved.repos:
    let repoPath = args.workspaceRoot / repo.path
    if not dirExists(repoPath / ".git"):
      continue
    # RA-14 optimized-fetch (``repo --optimized-fetch`` equivalent): if the
    # locked SHA is already reachable in this checkout (counting objects
    # borrowed from the shared bare via alternates), the network fetch
    # would transfer nothing the planner needs. Skip it entirely — this is
    # the single biggest re-``sync`` win for an already-current workspace.
    let lockedSha = lockedShaFor(repo)
    if lockedSha.len > 0 and
        commitReachableLocally(identity, repoPath, lockedSha):
      inc optimizedFetchSkips
      continue
    # Refresh this URL's shared bare once, up front, and expose it as a
    # dependency action id so the URL's fetches wait on it.
    var refreshDepId = ""
    # The shared bare is keyed by the FULL repo URL (`cloneUrlFor`), not the
    # bare remote base (`repo.fetchUrl`) — the latter is un-cloneable for the
    # common one-remote-many-repos manifest layout, which left the cache
    # permanently unpopulated.
    let cloneUrl = cloneUrlFor(repo)
    if cloneUrl.len > 0:
      if not sharedBareRefreshAction.hasKey(cloneUrl):
        # RA-27 — the RA-5 shared-bare warm-up used to run HERE, serially, one
        # blocking `git fetch`/`clone --bare` per unique URL BEFORE any progress
        # was announced. On a 30+ repo workspace that is minutes of silence, and
        # it is the phase that actually dominates `repro sync`.
        #
        # It is now an engine action per unique URL on the same ``vcs/fetch``
        # pool as the fetches, which each fetch depends on (that is what the
        # long-present-but-unpopulated ``refreshDepId`` was always for). Safe to
        # parallelise: the race the serial loop guarded against is per-BARE, and
        # each URL maps to its own bare directory — this table is exactly the
        # per-URL dedupe that guarantees no two actions target the same one.
        let barePath = sharedBarePath(cacheRoot, cloneUrl)
        let rid = "workspace-sync-refresh-bare-" &
          $sharedBareRefreshAction.len
        var ra = gitRefreshBareAction(rid, identity,
          remoteUrl = cloneUrl, barePath = barePath,
          receiptPath = ".repro" / "workspace" / "receipts" /
            (rid & ".receipt"))
        ra.cwd = args.workspaceRoot
        ra.pool = SyncFetchPool
        ra.poolUnits = 1'u32
        refreshActions.add(ra)
        sharedBareRefreshAction[cloneUrl] = rid
      refreshDepId = sharedBareRefreshAction[cloneUrl]
    fetchActions.add(syncFetchActionFor(identity, args.workspaceRoot,
      repo, repoIdx, refreshDepId))

  if optimizedFetchSkips > 0:
    stderr.writeLine("workspace sync: optimized-fetch skipped " &
      $optimizedFetchSkips & " repo(s) already at the locked revision")

  # RA-27 live progress: never a silent hang. Announce the network phase so
  # the user/agent sees motion before the (potentially slow) parallel fetch
  # begins. Suppressed under ``--json`` so the machine surface stays a single
  # clean document on stdout (progress goes to stderr regardless).
  let emitProgress = not args.json
  if emitProgress and refreshActions.len > 0:
    stderr.writeLine("workspace sync: warming " & $refreshActions.len &
      " shared clone(s) in parallel (jobs-network=" & $jobsNetwork & ") ...")
  if emitProgress and fetchActions.len > 0:
    stderr.writeLine("workspace sync: fetching " & $fetchActions.len &
      " repo(s) in parallel (jobs-network=" & $jobsNetwork & ") ...")

  if fetchActions.len > 0:
    var config = defaultBuildEngineConfig(engineCacheRoot)
    config.suppressTrace = true
    config.maxParallelism = uint32(max(jobsNetwork, jobsCheckout))
    config.fallbackToRunQuotaBypass = true
    # The warm-up actions ride in the SAME graph so the engine orders each
    # fetch after its bare's refresh (via ``refreshDepId``) while still running
    # independent URLs concurrently.
    let res = runBuild(graph(refreshActions & fetchActions,
      @[pool(SyncFetchPool, uint32(jobsNetwork))]), config)
    var fetchById = initTable[string, ActionResult]()
    for outcome in res.results:
      fetchById[outcome.id] = outcome
    var fetchOk = 0
    for a in fetchActions:
      let outcome = fetchById.getOrDefault(a.id)
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        # A pre-classification fetch failure is non-fatal (e.g. transient
        # network): the planner still classifies against whatever the
        # local remote-tracking refs already say. Surface a diagnostic.
        stderr.writeLine("workspace sync: pre-classification fetch failed (" &
          a.id & "): status=" & $outcome.status &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: ""))
      else:
        inc fetchOk
    if emitProgress:
      stderr.writeLine("workspace sync: fetched " & $fetchOk & "/" &
        $fetchActions.len & " repo(s)")

  # Detect force pushes after parallel fetch
  var forcePushes = loadForcePushedCommits(args.workspaceRoot)
  var forcePushesUpdated = false
  for repoIdx, repo in resolved.repos:
    let repoPath = args.workspaceRoot / repo.path
    if oldRemoteTips[repoIdx].len > 0:
      let rName = gitRemoteNameFor(repo)
      let newTip = revParse(identity, repoPath,
        "refs/remotes/" & rName & "/" & repo.revision)
      if newTip.len > 0 and newTip != oldRemoteTips[repoIdx]:
        let ancestorRes = gitRunPlain(identity, ["-C", repoPath,
          "merge-base", "--is-ancestor", oldRemoteTips[repoIdx], newTip])
        if ancestorRes.code != 0:
          # A force push occurred! Query the superseded commits
          let logRes = gitRunPlain(identity, ["-C", repoPath,
            "log", "--format=%H", newTip & ".." & oldRemoteTips[repoIdx]])
          if logRes.code == 0:
            let forcePushedSHAs = logRes.output.strip().splitLines()
            if not forcePushes.hasKey(repo.path):
              forcePushes[repo.path] = newJArray()
            for rawSha in forcePushedSHAs:
              let sha = rawSha.strip()
              if sha.len > 0:
                var exists = false
                for existing in forcePushes[repo.path]:
                  if existing.getStr() == sha:
                    exists = true
                    break
                if not exists:
                  forcePushes[repo.path].add(%sha)
                  forcePushesUpdated = true
  if forcePushesUpdated:
    saveForcePushedCommits(args.workspaceRoot, forcePushes)

  # Step 3b: observe each repo (now with fresh remote-tracking refs). No
  # workspace-wide metadata is folded in: a repo's classification is a function
  # of that repo's own git state and the manifest's pin for it. The M16
  # ``feature_started`` mark used to ride along here to suppress the
  # fast-forward arm on the marked branch; nothing reads it any more.
  var observations: seq[RepoSyncObservation]
  for repo in resolved.repos:
    let repoPath = args.workspaceRoot / repo.path
    var repoForcePushed = initHashSet[string]()
    if forcePushes.hasKey(repo.path):
      for val in forcePushes[repo.path]:
        repoForcePushed.incl(val.getStr())
    observations.add(
      observeRepoForSync(identity, repoPath, repo, repoForcePushed))

  # Step 4: planner.
  let planned = planSync(resolved.repos, observations, args.rebaseOnForcePush)

  # Step 5 (RA-5c): checkout phase. Collect every repo's mutating action
  # (clone / merge-ff / attach) into ONE graph and run it once. No-op /
  # refused cases carry an immediate status and contribute no action. The
  # engine runs the mutations with up to ``jobs-checkout`` CPU parallelism
  # instead of the old per-repo serial graph. (The planner already ran the
  # ``--no-interleaved`` fetch barrier by construction; ``--no-interleaved``
  # is therefore the only mode and the flag is accepted as a no-op /
  # explicit affirmation.)
  var anyRefusal = false
  var anyFailure = false
  # Per-repo immediate (non-action) status keyed by repo index.
  var immediateStatus = initTable[int, (string, string)]()
  var checkoutActions: seq[BuildAction]
  var actionRepoIdx = initTable[string, int]()

  # RA-23: ``sync`` clones newly-declared dependencies (the planner emits
  # ``missing_checkout`` → ``saClone`` for a declared repo with no on-disk
  # checkout — e.g. a repo a teammate just added). Such a clone reuses the
  # SAME RA-5 shared-object-cache acceleration the ``init`` clone path uses:
  # we refresh the missing repo's upstream shared bare once per URL and pass
  # it as the clone's ``--reference``. ``cloneRepoIdx`` records which
  # checkout actions are NEW-repo clones so a clone FAILURE (an unreadable /
  # private repo a teammate added) is reported + SKIPPED rather than aborting
  # the whole sync (RA-23 deliverable 2; consistent with RA-11's no-rollback
  # partial-advance — the readable repos still converge).
  var sharedBareForClone = initTable[string, string]()
  proc cloneReferenceFor(fetchUrl: string): string =
    if fetchUrl.len == 0:
      return ""
    if sharedBareForClone.hasKey(fetchUrl):
      return sharedBareForClone[fetchUrl]
    let refreshed = refreshSharedBare(identity.binaryPath, cacheRoot, fetchUrl)
    let reference = if refreshed.ok: refreshed.sharedBarePath else: ""
    if not refreshed.ok and refreshed.diagnostic.len > 0:
      stderr.writeLine("workspace sync: shared-clone cache miss for " &
        fetchUrl & " (cloning newly-declared repo standalone): " &
        refreshed.diagnostic)
    sharedBareForClone[fetchUrl] = reference
    reference
  var cloneRepoIdx = initHashSet[int]()

  # RA-16 ``--force-sync``: the planner SKIPS-and-reports a divergent /
  # dirty / locally-unpublished checkout (``saNone``). With ``--force-sync``
  # the operator opts into OVERWRITING those to the locked revision. We
  # gather the candidate set, run them through the destructive-command
  # safety gate ONCE (preview + confirm, or refuse cleanly in a non-TTY
  # without ``--yes``), and only then schedule the force-reset actions. A
  # normal sync (no flag) never enters this branch — it keeps skipping.
  var forceResetRepos = initHashSet[int]()
  var forceResetTarget = initTable[int, string]()
  if args.forceSync:
    var targets: seq[ForceSyncTarget]
    for repoIdx, decision in planned.report.decisions:
      if decision.action != saNone:
        continue
      if decision.syncCase notin
          {scDirty, scLocallyUnpublished, scDivergentFeatureBranch}:
        continue
      let repo = resolved.repos[repoIdx]
      # The concrete commit to reset onto: the SHA-pinned revision itself,
      # else the lock file's recorded SHA, else the post-fetch remote
      # tracking tip ``<remote>/<branch>`` for a branch pin (the fetch phase
      # already advanced it), else the bare revision as a last resort. The
      # fetch phase made the locked commit reachable for a tree with
      # ``.git``.
      var target = lockedShaFor(repo)
      if target.len == 0 and repo.revision.len > 0:
        if looksLikeSha(repo.revision):
          target = repo.revision
        else:
          # Branch pin: reset onto the remote-tracking tip so the overwrite
          # converges to the published revision, not a stale local branch.
          let repoAbs = args.workspaceRoot / repo.path
          let rName = gitRemoteNameFor(repo)
          let remoteTip = revParse(identity, repoAbs,
            "refs/remotes/" & rName & "/" & repo.revision)
          target = if remoteTip.len > 0: remoteTip else: repo.revision
      if target.len == 0:
        continue
      forceResetTarget[repoIdx] = target
      targets.add(ForceSyncTarget(
        repoIdx: repoIdx, path: decision.path, syncCase: decision.syncCase,
        observed: decision.observed, expected: decision.expected))
    let guard = forceSyncGuard(args, targets)
    if guard == fsgConfirmed:
      for t in targets:
        forceResetRepos.incl(t.repoIdx)

  for repoIdx, decision in planned.report.decisions:
    let resolvedRepo = resolved.repos[repoIdx]
    if repoIdx in forceResetRepos:
      # RA-16 overwrite path. Build a ``git reset --hard <sha>`` +
      # ``git clean -ffdx`` engine action that resets the divergent tree
      # to the locked revision.
      let receiptDir = args.workspaceRoot / ".repro" / "workspace" / "receipts"
      createDir(receiptDir)
      let idSeg = safeRepoIdSegment(resolvedRepo.name) & "-" & $repoIdx
      let receiptRel = ".repro" / "workspace" / "receipts" /
        ("sync-force-reset-" & idSeg & ".receipt")
      var a = gitForceResetAction("workspace-sync-force-reset-" & idSeg,
        identity,
        revision = forceResetTarget[repoIdx],
        repoPath = resolvedRepo.path,
        receiptPath = receiptRel)
      a.cwd = args.workspaceRoot
      checkoutActions.add(a)
      actionRepoIdx[a.id] = repoIdx
      continue
    # RA-23: for a newly-declared (missing) repo the planner emits
    # ``saClone``; resolve its shared bare so the clone reuses the RA-5
    # acceleration, and remember it as a clone so a failure is skip-not-fatal.
    var cloneRef = ""
    if decision.action == saClone:
      cloneRef = cloneReferenceFor(cloneUrlFor(resolvedRepo))
      cloneRepoIdx.incl(repoIdx)
    let built = syncCheckoutActionFor(
      identity, args.workspaceRoot, resolvedRepo, decision, repoIdx, cloneRef)
    if built.hasAction:
      checkoutActions.add(built.action)
      actionRepoIdx[built.action.id] = repoIdx
    else:
      immediateStatus[repoIdx] = (built.immediateStatus,
        built.immediateDiagnostic)

  # Run the checkout graph once. Results are re-keyed by action id (like
  # ``executeWorkspaceInit``) so the per-repo report is rebuilt
  # independent of the engine's completion order.
  var checkoutStatus = initTable[int, (string, string)]()
  if checkoutActions.len > 0:
    if emitProgress:
      stderr.writeLine("workspace sync: updating " & $checkoutActions.len &
        " repo(s) (clone/fast-forward/attach, jobs-checkout=" &
        $jobsCheckout & ") ...")
    var config = defaultBuildEngineConfig(engineCacheRoot)
    config.suppressTrace = true
    config.maxParallelism = uint32(max(jobsNetwork, jobsCheckout))
    config.fallbackToRunQuotaBypass = true
    # RA-23: newly-declared-repo clones carry the ``vcs/fetch`` pool tag
    # (network economy), so the checkout graph must declare that pool with
    # the same ``jobs-network`` capacity. Non-clone checkout actions
    # (merge-ff / attach / force-reset) carry no pool and consume CPU slots.
    let res = runBuild(graph(checkoutActions,
      @[pool(SyncFetchPool, uint32(jobsNetwork))]), config)
    var byId = initTable[string, ActionResult]()
    for outcome in res.results:
      byId[outcome.id] = outcome
    for a in checkoutActions:
      let repoIdx = actionRepoIdx[a.id]
      let outcome = byId.getOrDefault(a.id)
      let isClone = repoIdx in cloneRepoIdx
      if outcome.status in {asSucceeded, asCacheHit, asUpToDate}:
        # RA-23: a successful NEW-repo clone is named distinctly (``cloned``)
        # from an updated existing checkout (``succeeded``).
        checkoutStatus[repoIdx] =
          (if isClone: ("cloned", "") else: ("succeeded", ""))
        # RA-27 per-repo live progress: emit motion as each repo finishes.
        if emitProgress:
          stderr.writeLine("workspace sync: [" &
            (if isClone: "cloned" else: "updated") & "] " &
            resolved.repos[repoIdx].path)
      elif isClone:
        # RA-23: cloning a newly-declared dependency failed (auth /
        # unreadable / private repo a teammate added). Report + SKIP it —
        # do NOT abort the whole sync. Consistent with RA-11's no-rollback
        # partial-advance: readable repos still converge, the partial state
        # is reported, nothing is rolled back.
        # Principle 2: name the offending repo AND a concrete remedy. The
        # clone failed because the operator cannot read the repo (auth /
        # private / wrong URL); the remedy is to gain access and re-run
        # sync, or to drop the unreadable dependency from the workspace.
        let offender = resolved.repos[repoIdx].path
        let remedy = "ensure read access to '" &
          resolved.repos[repoIdx].fetchUrl &
          "' (auth / network) then 're-run 'repro sync', or " &
          "'repro remove " & resolved.repos[repoIdx].name &
          "' to drop the dependency"
        checkoutStatus[repoIdx] = ("clone_failed",
          "clone of newly-declared repo failed: " &
          "status=" & $outcome.status & " reason=" & outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: "") &
          " — remedy: " & remedy)
        stderr.writeLine("workspace sync: FAILED to clone newly-declared " &
          "repo '" & offender & "' (continuing with the other repos): " &
          (if outcome.stderr.len > 0: outcome.stderr.strip()
           else: outcome.reason) & " — remedy: " & remedy)
      else:
        checkoutStatus[repoIdx] = ("failed",
          "action " & a.id & " status=" & $outcome.status &
          " reason=" & outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: ""))

  # HL-7 (§8.4 capstone) — reconstruct a FRESHLY-CLONED repo AT ITS DURABLE
  # LOCKED REVISION. A ``git clone --branch <branch>`` lands the new checkout on
  # the branch TIP, which may be AHEAD of the revision the durable lock pins
  # (the branch advanced after the lock was published). A fresh-machine restore
  # must reproduce the LOCKED state, not the latest tip, so for each repo that
  # was cloned in THIS sync we compare the cloned HEAD to the durable locked SHA
  # (from ``.repo/manifests`` OR the routed backend, merged above) and, when
  # they differ and the locked commit is reachable in the fresh clone, reset the
  # checkout to it. This is scoped strictly to NEW clones: an existing checkout
  # keeps its fast-forward/attach semantics unchanged (no regression to the RA
  # sync corner cases), and a repo with no durable locked SHA (no lock, or a
  # branch-tip==locked case) is a no-op. Best-effort: a reset failure is
  # reported but never aborts the sync (RA-11 no-rollback partial-advance).
  for repoIdx in cloneRepoIdx:
    if not checkoutStatus.hasKey(repoIdx): continue
    if checkoutStatus[repoIdx][0] != "cloned": continue
    let repo = resolved.repos[repoIdx]
    let lockedSha = lockedShaFor(repo)
    if lockedSha.len == 0: continue
    let repoAbs = args.workspaceRoot / repo.path
    let headNow = revParse(identity, repoAbs, "HEAD")
    if headNow.len == 0 or headNow == lockedSha: continue
    if not commitReachableLocally(identity, repoAbs, lockedSha):
      # The locked commit is not in the fresh clone (a shallow / narrow clone,
      # or an unreachable pin). Surface it — the restore is INCOMPLETE — rather
      # than silently leaving the checkout on the wrong (tip) revision.
      checkoutStatus[repoIdx] = ("failed",
        "cloned '" & repo.path & "' but the durable locked revision " &
        lockedSha & " is not reachable in the fresh clone (HEAD=" & headNow &
        "); the pushed lock and the repo's history are out of sync")
      continue
    let resetRes = gitRunPlain(identity,
      ["-C", repoAbs, "reset", "--hard", lockedSha])
    if resetRes.code != 0:
      checkoutStatus[repoIdx] = ("failed",
        "cloned '" & repo.path & "' but could not reset to the durable " &
        "locked revision " & lockedSha & ": " & resetRes.output.strip())
    else:
      checkoutStatus[repoIdx] = ("cloned",
        "cloned '" & repo.path & "' and reconstructed at the durable locked " &
        "revision " & lockedSha & " (branch tip was " & headNow & ")")
      if emitProgress:
        stderr.writeLine("workspace sync: [restored] " & repo.path &
          " @ locked " & lockedSha)

  for repoIdx, decision in planned.report.decisions:
    var status = ""
    var diagnostic = ""
    if immediateStatus.hasKey(repoIdx):
      (status, diagnostic) = immediateStatus[repoIdx]
    elif checkoutStatus.hasKey(repoIdx):
      (status, diagnostic) = checkoutStatus[repoIdx]
    else:
      # Should not happen: every decision is either immediate or has an
      # action. Treat as a noop to avoid an empty status.
      status = "noop"
    if status == "refused":
      anyRefusal = true
    elif status == "failed" or status == "clone_failed":
      # A clone failure does not abort the run — the other repos still
      # converge (RA-23's partial-advance). It DOES fail the run: the
      # workspace is missing a declared repo, and every consumer that reads
      # only the exit code would otherwise be told the workspace is complete.
      # That is how a workspace stays silently incomplete for weeks.
      anyFailure = true
    # RA-16: surface the force-reset overwrite in the report so it is
    # distinguishable from the planner's original report-only decision.
    let wasForceReset = repoIdx in forceResetRepos
    let actionTag =
      if wasForceReset: "force_reset" else: syncActionTag(decision.action)
    let message =
      if wasForceReset:
        "force-sync overwrote '" & decision.path & "' to " &
          forceResetTarget.getOrDefault(repoIdx)
      else: decision.message
    report.repos.add(WorkspaceSyncRepoEntry(
      name: decision.name,
      path: decision.path,
      syncCase: syncCaseTag(decision.syncCase),
      action: actionTag,
      expected: decision.expected,
      observed: decision.observed,
      branch: decision.branch,
      message: message,
      refusalReason: (if wasForceReset: "" else: decision.refusalReason),
      executionStatus: status,
      executionDiagnostic: diagnostic,
      forcePushedBaseSha: decision.forcePushedBaseSha))

  # RA-18: materialize copyfile/linkfile directives AFTER the checkout
  # phase, for every selected repo whose working tree exists. Re-applied on
  # every sync (idempotent overwrite), so the materialized files always
  # track the just-checked-out revision. Best-effort: a directive failure is
  # reported but does not change the sync exit code (the checkout itself
  # succeeded; the materialization is a post-step convenience).
  for repo in resolved.repos:
    if repo.copyfile.len == 0 and repo.linkfile.len == 0:
      continue
    if not dirExists(args.workspaceRoot / repo.path):
      continue
    for m in materializeRepoFiles(args.workspaceRoot, repo):
      report.materialized.add(m)
      if m.status == "failed":
        stderr.writeLine("workspace sync: " & m.kind & " '" & m.dest &
          "' <- '" & repo.path & "/" & m.src & "' failed: " & m.diagnostic)

  alignWorkspaceRemotes(args.workspaceRoot, resolved.repos, identity)

  # Step 6: exit code.
  if anyFailure:
    report.exitCode = 1
  elif anyRefusal:
    report.exitCode = 2
  else:
    report.exitCode = 0
  result.report = report

proc writeWorkspaceSyncReport(report: WorkspaceSyncReport;
                              destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc emitLockCoherenceAdvisory*[T](toolProvisioning: ToolProvisioningMode;
                                   workspaceRoot, project: string;
                                   repos: openArray[T]) =
  ## Print the lock-coherence advisory after a host command's own text output.
  ## Generic over the report entry type because ``sync`` and ``status`` each
  ## already know their participating set — the check reuses it rather than
  ## resolving the project a second time. Every entry type it is instantiated
  ## with supplies ``name`` and ``path``.
  ##
  ## Wrapped in a blanket catch on purpose: an advisory diff must never be able
  ## to change the outcome of the command it is advising on.
  try:
    let identity = ensureGitToolResolvable(toolProvisioning, getEnv("PATH"))
    var pairs: seq[tuple[name, path: string]]
    for entry in repos:
      pairs.add((entry.name, entry.path))
    for line in renderCoherenceTextLines(
        lockCoherenceFor(identity, workspaceRoot, project, pairs)):
      stdout.writeLine(line)
  except CatchableError:
    discard

proc runWorkspaceSyncCommand*(args: openArray[string]): int =
  ## ``repro workspace sync [<project>...] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop]
  ## [--jobs N|-j N] [--jobs-network N] [--jobs-checkout N]
  ## [--no-interleaved] [--fail-fast] [--force-sync] [--yes|--force]
  ## [--dry-run] [--json] [--verbose|-v]``.
  ##
  ## RA-27 communicate-before-execute + live progress (Principle 1):
  ##   - Positional ``<project>...`` SCOPES the sync to those projects'
  ##     repos only (the participating set is filtered to the named
  ##     projects' repos); an unknown name errors clearly. No positional =
  ##     the whole workspace.
  ##   - The plan (which repos / what action) is ANNOUNCED before acting;
  ##     ``--dry-run`` prints the plan and exits WITHOUT mutating.
  ##   - Per-repo live progress is emitted to stderr (suppressed under
  ##     ``--json``); the run ends with a scannable per-repo summary digest.
  ##   - ``--json`` emits the machine surface (plan + per-repo results +
  ##     summary) on stdout; ``--verbose``/``-v`` includes raw tool
  ##     diagnostics behind the digest.
  ##
  ## RA-5c: ``--jobs-network`` bounds the ``vcs/fetch`` pool (parallel
  ## network fetch concurrency); ``--jobs-checkout`` bounds the checkout
  ## phase's CPU parallelism; ``--jobs``/``-j`` is the shared default for
  ## both. ``--no-interleaved`` is the only (and intrinsic) phase model
  ## here and is accepted as an explicit affirmation. ``--fail-fast`` is
  ## accepted but currently a no-op (default continue-and-report).
  ##
  ## RA-16 resume + force:
  ##   - Re-running an interrupted sync RESUMES at the first incomplete
  ##     repo: completed per-repo clone/fetch actions are receipt cache
  ##     hits (engine cache root persists under
  ##     ``.repro/workspace/engine-cache``), and a half-cloned tree with
  ##     no ``.git`` (no receipt) is cleaned up and re-cloned.
  ##   - ``--force-sync`` OVERWRITES a checkout that diverged from the
  ##     manifest revision (``divergent`` / ``dirty`` /
  ##     ``locally_unpublished``) to the locked SHA via
  ##     ``git reset --hard`` + ``git clean -ffdx``. It is destructive, so
  ##     it previews the per-repo effect and CONFIRMS; ``--yes``/``--force``
  ##     opts out of the prompt, and a non-TTY without the flag REFUSES
  ##     cleanly (never hangs, never overwrites). A NORMAL sync (no
  ##     ``--force-sync``) still report-only-skips divergent/dirty repos —
  ##     force is the only overwrite path.
  ##
  ## Exit codes (per M10 design):
  ##   - 0 — every repo is at its locked revision, was cleanly
  ##         fast-forwarded, was re-attached to its branch, was
  ##         cloned successfully, or is a divergent-feature-branch
  ##         report-only case.
  ##   - 1 — at least one mutating action (clone, fetch, fast-forward,
  ##         branch attach) failed.
  ##   - 2 — at least one repo was in a refuse-and-report state
  ##         (``dirty`` or ``locally_unpublished``). The operator has
  ##         manual work to do. Distinct from exit-1 ("sync blew up")
  ##         so scripts can tell the two apart.
  let parsed = parseWorkspaceSyncArgs(args)
  let outcome = executeWorkspaceSync(parsed)
  # RA-27: a dry run does not run any mutating step, so it does not write a
  # report artifact (there is nothing to persist about a run that did not
  # happen). The plan is rendered to the chosen surface and we exit 0.
  if not parsed.dryRun:
    writeWorkspaceSyncReport(outcome.report,
      reportDestination(parsed.report, outcome.report.workspaceRoot, "sync"))
    stageFailureReport(parsed.report, outcome.report.workspaceRoot, "sync",
      outcome.report.toJsonNode())
    # Refresh the prompt cache. Unconditional and independent of ``--write-report``:
    # the prompt is not allowed to depend on an operator flag, and this is
    # workspace state we just observed rather than a record of the invocation.
    block:
      var branches: seq[string]
      for entry in outcome.report.repos:
        branches.add(entry.branch)
      writePromptCache(outcome.report.workspaceRoot, "sync", branches)
    try:
      writeGeneratedWorkspaceProjects(parsed.workspaceRoot)
    except CatchableError as err:
      stderr.writeLine("workspace sync: could not generate workspace-projects.md: " & err.msg)
    # A sync is exactly when checkouts appear (or a `--force-sync` removes
    # one), so the sibling set is refreshed here. Skipped under `--dry-run`
    # along with every other mutation.
    refreshWorkspaceSiblingIgnoresBestEffort(outcome.report.workspaceRoot)
  if parsed.json:
    # RA-27 machine surface: the plan + per-repo results + summary digest as
    # one JSON document on stdout (the same shape persisted to
    # ``sync-report.json``). Agents/CI consume this without scraping text.
    stdout.writeLine(pretty(outcome.report.toJsonNode(), indent = 2))
  else:
    for line in renderSyncTextLines(outcome.report, parsed.verbose):
      stdout.writeLine(line)
    emitLockCoherenceAdvisory(parsed.toolProvisioning,
      outcome.report.workspaceRoot, outcome.report.project,
      outcome.report.repos)
  outcome.report.exitCode

# ---- RA-11: `repro workspace pull` ----------------------------------------
#
# ``pull`` is the converge-to-manifest-revision operation, distinct from
# ``sync`` (per Workspace-And-Develop-Mode.md §"sync vs pull"):
#
#   - ``sync`` honors each repo's CURRENT branch: fetch + ``merge
#     --ff-only @{u}`` on whatever branch is checked out (per-repo
#     upstream tracking). It does NOT realign repos to the
#     manifest-declared revisions.
#   - ``pull`` converges the workspace TO the manifest-declared revisions:
#     refresh the manifest, then put every repo on a LOCAL TRACKING
#     BRANCH matching its manifest revision (the repo-workspaces
#     ``ensureRepoTrackingBranches`` behavior). HEAD ends at the manifest
#     revision AND attached to a branch — never detached.
#
# No-rollback partial-sync policy: ``pull`` refreshes the manifest FIRST
# (advancing it, recording before→after SHAs). If a later per-repo
# convergence step fails, the manifest repo is NOT rolled back — the
# report shows the before→after SHAs and ``pull`` stops with a non-zero
# exit, leaving the partial state for a manual rerun.

type
  WorkspacePullRepoOutcome* = enum
    ppoConvergedExisting   ## Existing checkout converged to the manifest
                           ## revision on a tracking branch.
    ppoCloned              ## Missing checkout cloned + put on a tracking
                           ## branch at the manifest revision.
    ppoFailed              ## A clone / fetch / branch-attach step failed.
    ppoSkippedWorkAtRisk   ## Converging would have repointed a branch (or
                           ## moved HEAD off one) carrying work no remote
                           ## carries. The checkout is left EXACTLY as it was
                           ## and the report names what stopped it.

  WorkspacePullRepoEntry* = object
    ## One per declared repo after ``pull``. ``trackingBranch`` is the
    ## local branch HEAD is attached to after convergence (empty only on
    ## failure); ``revision`` is the manifest-declared revision the repo
    ## was converged to; ``headSha`` is the resolved HEAD afterward.
    name*: string
    path*: string
    revision*: string
    trackingBranch*: string
    headSha*: string
    outcome*: string
    diagnostic*: string

  WorkspacePullReport* = object
    ## Structured outcome of one ``repro workspace pull`` invocation.
    ## ``manifestLayers`` carries the SAME before→after refresh entries
    ## sync emits — the explicit no-rollback evidence. ``manifestStopped``
    ## is set when a manifest layer advanced AND a later step failed: the
    ## report then names the layer whose advance was kept (NOT rolled
    ## back).
    project*: string
    workspaceRoot*: string
    manifestLayers*: seq[WorkspaceSyncManifestLayerEntry]
    manifestStopped*: bool
    repos*: seq[WorkspacePullRepoEntry]
    autoTrust*: TrustReport
      ## RA-12 — outcome of the post-pull shell-hook (.envrc) auto-trust pass.
    exitCode*: int

  WorkspacePullOutcome* = object
    report*: WorkspacePullReport

proc pullOutcomeTag(outcome: WorkspacePullRepoOutcome): string =
  case outcome
  of ppoConvergedExisting: "converged"
  of ppoCloned: "cloned"
  of ppoFailed: "failed"
  of ppoSkippedWorkAtRisk: "skipped_work_at_risk"

proc toJsonNode*(report: WorkspacePullReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  var layers = newJArray()
  for entry in report.manifestLayers:
    var obj = newJObject()
    obj["index"] = %entry.index
    obj["provenance"] = %entry.provenance
    obj["layerPath"] = %entry.layerPath
    obj["status"] = %entry.status
    obj["beforeSha"] = %entry.beforeSha
    obj["afterSha"] = %entry.afterSha
    obj["diagnostic"] = %entry.diagnostic
    layers.add(obj)
  result["manifestLayers"] = layers
  result["manifestStopped"] = %report.manifestStopped
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["revision"] = %entry.revision
    obj["trackingBranch"] = %entry.trackingBranch
    obj["headSha"] = %entry.headSha
    obj["outcome"] = %entry.outcome
    obj["diagnostic"] = %entry.diagnostic
    repos.add(obj)
  result["repos"] = repos
  # RA-12 — the shell-hook (.envrc) auto-trust pass.
  var autoTrust = newJObject()
  autoTrust["activatorAvailable"] = %report.autoTrust.activatorAvailable
  autoTrust["activatorBin"] = %report.autoTrust.activatorBin
  autoTrust["skipReason"] = %report.autoTrust.skipReason
  var trusted = newJArray()
  for entry in report.autoTrust.entries:
    var obj = newJObject()
    obj["dir"] = %entry.dir
    obj["status"] = %entry.status
    obj["diagnostic"] = %entry.diagnostic
    trusted.add(obj)
  autoTrust["entries"] = trusted
  result["autoTrust"] = autoTrust
  result["exitCode"] = %report.exitCode

proc renderPullTextLines*(report: WorkspacePullReport): seq[string] =
  for entry in report.manifestLayers:
    if entry.beforeSha.len > 0 and entry.afterSha.len > 0 and
        entry.beforeSha != entry.afterSha:
      result.add("workspace pull: manifest-layer " & entry.provenance &
        " advanced " & entry.beforeSha & " → " & entry.afterSha)
  for entry in report.repos:
    var line = "workspace pull: " & entry.path & " " & entry.outcome
    if entry.trackingBranch.len > 0:
      line.add(" → branch " & entry.trackingBranch & " @ " & entry.headSha)
    if entry.diagnostic.len > 0:
      line.add(" (" & entry.diagnostic & ")")
    result.add(line)
  if report.manifestStopped:
    result.add("workspace pull: STOPPED after a step failed — the manifest " &
      "repo was advanced and is NOT rolled back; rerun `repro workspace " &
      "pull` to resume from the partial state")
  var skipped = 0
  for entry in report.repos:
    if entry.outcome == pullOutcomeTag(ppoSkippedWorkAtRisk):
      inc skipped
  if skipped > 0:
    # Said once, at the end, in the summary position. The per-repo lines above
    # already carry the detail; what a reader needs here is the count and the
    # fact that the rest of the workspace DID converge, so a non-zero exit is
    # not mistaken for "nothing happened".
    result.add("workspace pull: " & $skipped & " checkout(s) left untouched " &
      "to protect work that exists nowhere else; every other repo converged")
  for line in renderTrustReportLines("workspace pull", report.autoTrust):
    result.add(line)

type
  WorkspacePullArgs = object
    workspaceRoot: string
    projectName: string
    toolProvisioning: ToolProvisioningMode
    report: ReportSpec   ## Opt-in ``--write-report[=PATH]`` artifact.
    force: bool
      ## Converge a repo even when doing so repoints a branch carrying commits
      ## no remote has. Same spelling and same meaning as `disable --force` and
      ## `remove --force`: the work-loss refusal is the default, and this is
      ## how the operator says they have decided otherwise.

proc parseWorkspacePullArgs(args: openArray[string]): WorkspacePullArgs =
  ## ``repro workspace pull`` argv parser. Mirrors ``sync``'s shape: an
  ## optional ``<project>`` positional (single-project mode) plus
  ## ``--workspace-root=PATH`` / ``--tool-provisioning=...``.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--force":
      result.force = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace pull` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace pull`: " & arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveWorkspacePullProject(parsed: WorkspacePullArgs): ResolvedProject =
  ## MO-9 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder.
  ## Same dispatch rule as sync: compose layers when a compositional
  ## ``.repo/workspace.toml`` is present, else committed-lock-derived, else look
  ## up the named project / variant under ``.repo/manifests/`` (a metadata-only
  ## workspace.toml can supply the project name).
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro workspace pull`").resolved

# ---- work-loss probes, shared by every destructive workspace verb ---------
#
# Three verbs in this file destroy local state that no remote carries:
# `disable` deletes a checkout, `pull` repoints a branch ref, and `migrate`
# moves a detached HEAD. They endanger DIFFERENT things, so they must ask
# different questions — but they must ask them the same WAY, or the narrowest
# implementation ends up in front of the widest destruction. Hence one probe
# per question here, composed per verb below, rather than a single omnibus
# check that each caller either over- or under-applies.
#
# The shared rule across all of them: a probe that FAILS is itself a blocker.
# "We could not tell" and "there is nothing there" must never collapse into
# the same answer when the consequence is irreversible.

proc uncommittedChangesBlocker(identity: GitToolIdentity;
                               repoDir: string): seq[string] =
  let status = gitRunPlain(identity, ["-C", repoDir, "status", "--porcelain"])
  if status.code != 0:
    return @["could not read git status: " & status.output.strip()]
  let body = status.output.strip()
  if body.len > 0:
    return @[$body.splitLines().len & " uncommitted change(s)"]
  @[]

proc unpushedCommitsBlocker(identity: GitToolIdentity;
                            repoDir: string): seq[string] =
  ## Commits on ANY local branch that no remote carries.
  ##
  ## `rev-list --branches --not --remotes` is every commit reachable from some
  ## local branch and from no remote-tracking ref — exactly "work that would be
  ## gone" when the whole checkout is deleted. Counting is enough; naming the
  ## branches is the report's job.
  let unpushed = gitRunPlain(identity,
    ["-C", repoDir, "rev-list", "--count", "--branches", "--not", "--remotes"])
  if unpushed.code != 0:
    return @["could not check for unpushed commits: " & unpushed.output.strip()]
  try:
    let n = parseInt(unpushed.output.strip())
    if n > 0:
      return @[$n & " unpushed commit(s)"]
  except ValueError:
    return @["could not check for unpushed commits: unexpected output '" &
      unpushed.output.strip() & "'"]
  @[]

proc branchAheadOfRemoteBlocker(identity: GitToolIdentity;
                                repoDir, branch, remoteName: string):
    seq[string] =
  ## Commits on ONE branch that its remote-tracking ref does not carry.
  ##
  ## This is the question a branch REPOINT has to ask, and it is deliberately
  ## narrower than the all-branches probe above. Repointing `dev` cannot harm a
  ## commit on some unrelated feature branch, so refusing over one would make
  ## the safe answer useless: nearly every real checkout has an unpushed branch
  ## somewhere, and a gate that fires on all of them is a gate people pass
  ## `--force` to by reflex.
  if branch.len == 0:
    return @[]
  let localRef = "refs/heads/" & branch
  if revParse(identity, repoDir, localRef).len == 0:
    return @[]                    # no such local branch: nothing to repoint
  let remoteRef = "refs/remotes/" & remoteName & "/" & branch
  if revParse(identity, repoDir, remoteRef).len == 0:
    # The branch exists locally and the remote-tracking ref does not, so
    # EVERYTHING on it is unpublished by definition.
    return @["local branch '" & branch & "' has no '" & remoteName &
      "/" & branch & "' to compare against, so all of it is unpublished"]
  let ahead = gitRunPlain(identity, ["-C", repoDir, "rev-list", "--count",
    localRef, "--not", remoteRef])
  if ahead.code != 0:
    return @["could not compare '" & branch & "' against " & remoteName &
      "/" & branch & ": " & ahead.output.strip()]
  try:
    let n = parseInt(ahead.output.strip())
    if n > 0:
      return @[$n & " commit(s) on '" & branch & "' that " & remoteName &
        "/" & branch & " does not carry"]
  except ValueError:
    return @["could not compare '" & branch & "' against " & remoteName &
      "/" & branch & ": unexpected output '" & ahead.output.strip() & "'"]
  @[]

proc detachedHeadOnlyCommits(identity: GitToolIdentity;
                             repoDir: string): seq[string] =
  ## Work that exists ONLY at a detached HEAD.
  ##
  ## The all-branches probe structurally cannot see it: a commit made while
  ## HEAD is detached belongs to no branch, so it falls outside `--branches` by
  ## construction. Both moving HEAD onto a branch and repointing the branch
  ## HEAD is about to land on would leave such a commit reachable only from the
  ## reflog, which is the exact loss these gates exist to prevent.
  let res = gitRunPlain(identity, ["-C", repoDir, "rev-list", "--count",
    "HEAD", "--not", "--branches", "--remotes"])
  if res.code != 0:
    return @["could not check for commits held only by the detached HEAD: " &
      res.output.strip()]
  try:
    let n = parseInt(res.output.strip())
    if n > 0:
      return @[$n & " commit(s) reachable only from the detached HEAD"]
  except ValueError:
    return @["could not check for commits held only by the detached HEAD: " &
      "unexpected output '" & res.output.strip() & "'"]
  @[]

proc stashBlocker(identity: GitToolIdentity; repoDir: string): seq[string] =
  let stash = gitRunPlain(identity, ["-C", repoDir, "stash", "list"])
  if stash.code != 0:
    return @["could not read the stash list: " & stash.output.strip()]
  let body = stash.output.strip()
  if body.len > 0:
    return @[$body.splitLines().len & " stash entr(ies)"]
  @[]

proc repoRemovalBlockers(identity: GitToolIdentity;
                         repoDir: string): seq[string] =
  ## Reasons this checkout must not be DELETED without an explicit override.
  ##
  ## Deleting the tree destroys everything in it, so this composes the widest
  ## set: work in the working tree, on any local branch, or in the stash. A
  ## checkout with none of them is reconstructible from its remote, which is
  ## what makes deleting it a cheap, reversible act rather than data loss.
  if not dirExists(repoDir):
    return @[]
  if not dirExists(repoDir / ".git"):
    # Occupied, but not a checkout we can reason about. Its contents are not
    # reconstructible from any remote and no probe below applies, so it is a
    # blocker by construction: "we cannot tell" must never collapse into "there
    # is nothing there" when the consequence is a recursive delete.
    var entries = 0
    for _ in walkDir(repoDir):
      inc entries
      break
    if entries > 0:
      return @["not a git checkout, and not empty"]
    return @[]
  result.add(uncommittedChangesBlocker(identity, repoDir))
  result.add(unpushedCommitsBlocker(identity, repoDir))
  result.add(stashBlocker(identity, repoDir))

proc branchConvergenceBlockers(identity: GitToolIdentity;
                               repoDir, branch, remoteName: string):
    seq[string] =
  ## Reasons this checkout must not be CONVERGED onto `branch` without an
  ## explicit override.
  ##
  ## Narrower than the removal set, and deliberately so, because converging
  ## destroys less: `checkout -B <branch> --track <remote>/<branch>` repoints
  ## ONE branch ref and moves HEAD. It cannot touch another branch, and it
  ## cannot touch the stash — so this asks about the working tree, about the
  ## one branch being repointed, and about a detached HEAD whose commits would
  ## be left unreferenced when HEAD moves away. The stash is checked anyway
  ## because a stash entry means an interrupted piece of work whose owner is
  ## almost certainly not expecting their branch to move underneath it, and the
  ## probe is one cheap command.
  if not dirExists(repoDir / ".git"):
    return @[]
  result.add(uncommittedChangesBlocker(identity, repoDir))
  let attached = gitRunPlain(identity,
    ["-C", repoDir, "symbolic-ref", "--short", "-q", "HEAD"])
  if attached.code == 0 and attached.output.strip().len > 0:
    result.add(branchAheadOfRemoteBlocker(identity, repoDir, branch,
      remoteName))
  else:
    result.add(detachedHeadOnlyCommits(identity, repoDir))
    result.add(branchAheadOfRemoteBlocker(identity, repoDir, branch,
      remoteName))
  result.add(stashBlocker(identity, repoDir))

proc convergeRepoToManifestRevision(
    identity: GitToolIdentity;
    repoPath, revision: string;
    remoteName: string = "origin"): tuple[ok: bool; branch, headSha, diag: string] =
  ## ``ensureRepoTrackingBranches`` core (RA-11). Put the existing
  ## checkout at ``repoPath`` onto a LOCAL TRACKING BRANCH matching the
  ## manifest-declared ``revision``, with HEAD at that revision.
  ##
  ##   - Branch-named revision (e.g. ``dev``): fetch remote, then
  ##     ensure a local branch ``<revision>`` exists tracking
  ##     ``<remoteName>/<revision>``, check it out, and fast-forward it to the
  ##     remote tip. The steady state is "on branch ``<revision>`` at
  ##     ``<remoteName>/<revision>``".
  ##   - SHA-pinned revision: fetch remote, then create / reset a
  ##     synthetic local tracking branch
  ##     ``reprobuild/pinned/<short-sha>`` at the pinned SHA and check it
  ##     out, so HEAD is at the SHA but ATTACHED to a branch (never
  ##     detached — the spec's explicit requirement).
  # Always fetch first so <remoteName>/<branch> reflects the manifest's
  # upstream tip (pull is a network-converge op, unlike a pure checkout).
  let rName = if remoteName.len > 0: remoteName else: "origin"
  let fetched = gitRunPlain(identity, ["-C", repoPath, "fetch", "--quiet",
    "--prune", rName])
  if fetched.code != 0:
    return (false, "", "",
      "git fetch failed: " & fetched.output.strip())

  if revision.len == 0:
    return (false, "", "", "manifest declares no revision for this repo")

  if looksLikeSha(revision):
    let shortSha =
      if revision.len > 12: revision[0 ..< 12] else: revision
    let branch = "reprobuild/pinned/" & shortSha
    # Create or move the synthetic branch to the pinned SHA, then check
    # it out. ``branch -f`` is idempotent across reruns.
    let mk = gitRunPlain(identity, ["-C", repoPath, "branch", "-f",
      branch, revision])
    if mk.code != 0:
      return (false, "", "",
        "could not create pinned tracking branch '" & branch & "' at " &
          revision & ": " & mk.output.strip())
    let co = gitRunPlain(identity, ["-C", repoPath, "checkout", "--quiet",
      branch])
    if co.code != 0:
      return (false, "", "",
        "could not check out pinned tracking branch '" & branch & "': " &
          co.output.strip())
    let head = revParse(identity, repoPath, "HEAD")
    return (true, branch, head, "")

  # Branch-named revision. Resolve the remote-tracking tip first.
  let remoteTip = revParse(identity, repoPath, "refs/remotes/" & rName & "/" & revision)
  if remoteTip.len == 0:
    return (false, "", "",
      "no remote-tracking branch '" & rName & "/" & revision & "' after fetch")
  # Create the local branch tracking <remoteName>/<revision> if it does not yet
  # exist; ``checkout -B`` resets it to the remote tip and attaches HEAD.
  let co = gitRunPlain(identity, ["-C", repoPath, "checkout", "--quiet",
    "-B", revision, "--track", "refs/remotes/" & rName & "/" & revision])
  if co.code != 0:
    return (false, "", "",
      "could not converge to tracking branch '" & revision & "': " &
        co.output.strip())
  let head = revParse(identity, repoPath, "HEAD")
  return (true, revision, head, "")

proc executeWorkspacePull(args: WorkspacePullArgs): WorkspacePullOutcome =
  ## End-to-end ``pull`` driver:
  ##   (1) refresh manifest layers (records before→after SHAs; the
  ##       advance is KEPT on any later failure — no rollback).
  ##   (2) resolve / compose the project.
  ##   (3) for each repo: clone if missing, then converge to the
  ##       manifest-declared revision on a local tracking branch.
  ##   (4) emit the structured report; stop (non-zero) on the first
  ##       per-repo failure, surfacing that the manifest stays advanced.
  var report: WorkspacePullReport
  report.workspaceRoot = args.workspaceRoot

  # Step 1: manifest-layer refresh — advances the manifest repo. The
  # before→after SHAs are recorded; this advance is NEVER rolled back.
  let refresh = refreshManifestLayers(args.workspaceRoot)
  var manifestAdvanced = false
  for entry in refresh.layers:
    if entry.beforeSha.len > 0 and entry.afterSha.len > 0 and
        entry.beforeSha != entry.afterSha:
      manifestAdvanced = true
    report.manifestLayers.add(WorkspaceSyncManifestLayerEntry(
      index: entry.index,
      provenance: entry.provenance,
      layerPath: entry.layerPath,
      status: manifestLayerStatusTag(entry.status),
      beforeSha: entry.beforeSha,
      afterSha: entry.afterSha,
      diagnostic: entry.diagnostic))

  # Step 2: resolve / compose.
  let resolved = resolveWorkspacePullProject(args)
  report.project = resolved.projectName

  let identity = ensureGitToolResolvable(args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  let cacheRoot = defaultCacheRoot(args.workspaceRoot)
  var sharedBareByUrl = initTable[string, string]()
  proc sharedReferenceFor(fetchUrl: string): string =
    if fetchUrl.len == 0:
      return ""
    if sharedBareByUrl.hasKey(fetchUrl):
      return sharedBareByUrl[fetchUrl]
    let refreshed = refreshSharedBare(identity.binaryPath, cacheRoot, fetchUrl)
    let reference = if refreshed.ok: refreshed.sharedBarePath else: ""
    sharedBareByUrl[fetchUrl] = reference
    reference

  var anyFailure = false
  var anySkipped = false
  for idx, repo in resolved.repos:
    let absPath = args.workspaceRoot / repo.path
    var entry = WorkspacePullRepoEntry(
      name: repo.name, path: repo.path, revision: repo.revision)
    if not dirExists(absPath):
      # Missing checkout — clone first (so the converge step has a tree).
      let receiptDir = args.workspaceRoot / ".repro" / "workspace" / "receipts"
      createDir(receiptDir)
      let idSeg = safeRepoIdSegment(repo.name) & "-" & $idx
      let receiptRel = ".repro" / "workspace" / "receipts" /
        ("pull-clone-" & idSeg & ".receipt")
      let pullCloneUrl = cloneUrlFor(repo)
      var action = gitCloneAction("workspace-pull-clone-" & idSeg, identity,
        remoteUrl = pullCloneUrl,
        repoPath = repo.path,
        receiptPath = receiptRel,
        revision = repo.revision,
        referencePath = sharedReferenceFor(pullCloneUrl),
        cloneFilter = repo.cloneFilter,
        depth = repo.depth,
        singleBranch = repo.singleBranch)
      action.cwd = args.workspaceRoot
      let engineCacheRoot = args.workspaceRoot / ".repro" / "workspace" /
        "engine-cache"
      var config = defaultBuildEngineConfig(engineCacheRoot)
      config.suppressTrace = true
      config.fallbackToRunQuotaBypass = true
      let res = runBuild(graph([action]), config)
      if res.results.len != 1 or
          res.results[0].status notin {asSucceeded, asCacheHit, asUpToDate}:
        let outcome =
          if res.results.len > 0: res.results[0]
          else: ActionResult(status: asFailed, reason: "no-result")
        entry.outcome = pullOutcomeTag(ppoFailed)
        entry.diagnostic = "clone failed: status=" & $outcome.status &
          " reason=" & outcome.reason &
          (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: "")
        report.repos.add(entry)
        anyFailure = true
        break
      entry.outcome = pullOutcomeTag(ppoCloned)
    else:
      entry.outcome = pullOutcomeTag(ppoConvergedExisting)

      # The work-loss gate. Convergence repoints `<revision>` to the remote
      # tip, so any commit on it that the remote does not carry stops being
      # referenced by anything — and until now nothing asked. `disable` refuses
      # to delete a checkout over a single uncommitted file while `pull` would
      # silently rewind that same checkout's branch; being reflog-recoverable
      # is not a defence when nothing in the report tells the developer to go
      # looking.
      #
      # Skipped, not fatal: the rest of the workspace still converges, which is
      # the partial-advance contract every other verb here follows. A repo left
      # behind is named with its remedy and counted in the exit code.
      #
      # Only an EXISTING checkout is gated. A tree this run just cloned has, by
      # construction, no work in it that a remote does not carry.
      if not args.force:
        let blockers = branchConvergenceBlockers(identity, absPath,
          repo.revision, gitRemoteNameFor(repo))
        if blockers.len > 0:
          entry.outcome = pullOutcomeTag(ppoSkippedWorkAtRisk)
          entry.diagnostic = "converging to '" & repo.revision &
            "' would put work at risk: " & blockers.join(", ") &
            "; push or stash it and rerun, or pass --force to converge anyway"
          report.repos.add(entry)
          anySkipped = true
          continue

    # Converge to the manifest revision on a local tracking branch.
    let converged = convergeRepoToManifestRevision(
      identity, absPath, repo.revision, remoteName = gitRemoteNameFor(repo))
    if not converged.ok:
      entry.outcome = pullOutcomeTag(ppoFailed)
      entry.diagnostic = converged.diag
      report.repos.add(entry)
      anyFailure = true
      break
    entry.trackingBranch = converged.branch
    entry.headSha = converged.headSha
    report.repos.add(entry)

  if anyFailure:
    report.exitCode = 1
    # No-rollback: when the manifest advanced AND a later step failed,
    # surface that the advance is kept (the partial state stays for a
    # rerun) rather than being silently reverted.
    if manifestAdvanced:
      report.manifestStopped = true
  elif anySkipped:
    # 2, matching every other verb here that declines to touch something to
    # protect work. Distinct from 1: nothing went wrong, some repos are simply
    # still waiting on a decision only their owner can make.
    report.exitCode = 2
  else:
    report.exitCode = 0
    # On full success, record the converged branch in workspace metadata
    # so downstream commands read a coherent active branch (mirrors init).
    let branchValue =
      if resolved.trunk.len > 0: resolved.trunk
      elif resolved.defaultRevision.len > 0: resolved.defaultRevision
      else: ""
    if branchValue.len > 0:
      try:
        writeWorkspaceBranch(args.workspaceRoot,
          project = resolved.projectName, branch = branchValue)
      except WorkspaceManifestParseError as e:
        stderr.writeLine(
          "workspace pull: could not record active branch: " & e.msg)

  # RA-12: auto-trust freshly cloned shell-hook (.envrc) files across the
  # workspace/host root + each checked-out repo. Runs regardless of the
  # per-repo exit code so already-materialised hooks are trusted even when a
  # later repo failed; best-effort (graceful skip + per-file isolation).
  report.autoTrust = autoTrustEnvrcFiles(
    discoverEnvrcRoots(args.workspaceRoot, resolved.repos))
  for line in renderTrustReportLines("workspace pull", report.autoTrust):
    if "FAILED" in line or "skipped" in line:
      stderr.writeLine(line)

  result.report = report

proc writeWorkspacePullReport(report: WorkspacePullReport;
                              destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspacePullCommand*(args: openArray[string]): int =
  ## ``repro workspace pull [<project>] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop]``.
  ##
  ## Converges every repo to its manifest-declared revision on a local
  ## tracking branch (distinct from ``sync``, which honors each repo's
  ## current branch). Exit codes:
  ##   - 0 — every repo converged to the manifest revision on a tracking
  ##         branch.
  ##   - 1 — a clone / fetch / branch-attach step failed. When the
  ##         manifest had already advanced, it is NOT rolled back: the
  ##         report names the before→after SHAs and the partial state is
  ##         left for a rerun.
  ##   - 2 — every repo that could be converged was, and at least one was
  ##         SKIPPED because converging it would have repointed a branch
  ##         carrying commits no remote has (or moved HEAD off commits held
  ##         only by a detached HEAD). Those checkouts are untouched; the
  ##         report names each one and its remedy. ``--force`` converges them
  ##         anyway, which is the pre-gate behaviour.
  let parsed = parseWorkspacePullArgs(args)
  let outcome = executeWorkspacePull(parsed)
  writeWorkspacePullReport(outcome.report,
    reportDestination(parsed.report, outcome.report.workspaceRoot, "pull"))
  stageFailureReport(parsed.report, outcome.report.workspaceRoot, "pull",
    outcome.report.toJsonNode())
  block:
    var branches: seq[string]
    for entry in outcome.report.repos:
      branches.add(entry.trackingBranch)
    writePromptCache(outcome.report.workspaceRoot, "pull", branches)
  refreshWorkspaceSiblingIgnoresBestEffort(outcome.report.workspaceRoot)
  for line in renderPullTextLines(outcome.report):
    stdout.writeLine(line)
  outcome.report.exitCode

# ---- M11: `repro workspace lock` ------------------------------------------
#
# Generate ``locks/<project>/<repo>/<full-sha>.toml`` from the live
# VCS state of the workspace, per Workspace-Manifests.md
# §"locks/<project>/<repo>/<sha>.toml" (RA-1 per-repo layout, no
# index). The same code path is invoked by the
# M16 post-commit hook with an explicit ``--sha=<commit>`` so a fresh
# commit lands as its own lock entry.
#
# Steady-state semantics:
#   1. Resolve the project (single-project M6 path) or compose layers
#      (M8 path), exactly as M9/M10 do. The composer returns the live
#      ``ResolvedRepo`` list — the same tuple the planner already
#      consumes.
#   2. Pick the manifest layer that will OWN the lock file. The lock
#      lives in the manifest repo (per spec), and a workspace with
#      multiple layers picks the FIRST layer (the "anchor" layer —
#      typically the public manifest). The operator can override with
#      ``--manifest-layer-root=PATH`` to target an internal/private
#      layer instead.
#   3. For every declared repo, gather a fresh observation: HEAD SHA
#      via the M2 ``headShaQuery`` adapter; clean/dirty via
#      ``isCleanQuery``; current branch via ``symbolic-ref --short``.
#      A repo whose checkout is dirty short-circuits to refuse-and-
#      report (exit 2). A locked snapshot of a dirty tree would lie:
#      its recorded SHA wouldn't reproduce the working tree.
#   4. Build the in-memory ``WorkspaceLockFile``, write the per-repo
#      lock TOML (RA-1: ``locks/<project>/<repo>/<sha>.toml``, no
#      shared index), emit the structured stdout + ``lock-report.json``.
#
# Exit codes:
#   0 — lock written (or already up-to-date).
#   1 — IO failure, VCS query failure, or a missing trigger repo.
#   2 — at least one declared checkout is dirty.

type
  WorkspaceLockRepoEntry* = object
    ## One per locked repo in the JSON report. The ``branch`` field
    ## is the advisory current branch (empty when the working tree is
    ## detached); the lock TOML carries the same value.
    name*: string
    path*: string
    remote*: string
    revision*: string
    branch*: string

  WorkspaceLockDirtyEntry* = object
    ## One per repo whose live checkout was DIRTY when the lock was
    ## attempted. Carried separately from the locked entries so the
    ## report has a per-case enumeration of refuse-and-report
    ## outcomes.
    name*: string
    path*: string
    reason*: string

  WorkspaceLockUnmaterializedReport* = object
    ## One per DECLARED repo the lock could not pin because the
    ## workspace has no on-disk checkout of it. Mirrors the
    ## ``[extensions] unmaterialized_repos`` record the lock document
    ## carries, so the JSON report and the lock file agree.
    name*: string
    path*: string
    reason*: string
      ## The MACHINE-INDEPENDENT reason, and the only part that reaches
      ## the committed lock document. A lock is shared history: an
      ## absolute path from whoever happened to run the gate would make
      ## two developers write different bytes for the same workspace
      ## state, and would publish one of their home directories.
    detail*: string
      ## Host-local elaboration (the absolute path probed, a git
      ## diagnostic). Report- and terminal-only; never serialized.

  WorkspaceLockReport* = object
    ## Structured outcome of one ``repro workspace lock`` invocation.
    ## ``lockFilePath`` is the absolute path the writer landed on;
    ## ``triggerRepo`` + ``triggerSha`` reflect the (repo, commit) tuple
    ## that anchors the per-repo lock path
    ## ``locks/<project>/<repo>/<sha>.toml``. RA-1 dropped the shared
    ## index: ``indexFilePath`` is always empty (kept for report-shape
    ## stability) and ``replacedExistingEntry`` is true when a lock file
    ## already existed at that path before this write — the idempotent
    ## re-lock-at-same-SHA case.
    project*: string
    workspaceRoot*: string
    manifestLayerRoot*: string
    lockFilePath*: string
    indexFilePath*: string
    triggerRepo*: string
    triggerSha*: string
    createdAt*: string
    workspaceBranch*: string
    replacedExistingEntry*: bool
    repos*: seq[WorkspaceLockRepoEntry]
    dirty*: seq[WorkspaceLockDirtyEntry]
    unmaterialized*: seq[WorkspaceLockUnmaterializedReport]
      ## Declared repos with no on-disk checkout. They contribute no
      ## revision (there is none to observe) but are NAMED here and in
      ## the lock's ``[extensions] unmaterialized_repos`` — a skip the
      ## lock states rather than a repo the lock silently drops.
    participation*: seq[ParticipationOutcome]
      ## MO-4 — per-repo participation recorded through each repo's ASSIGNED
      ## locking backend (empty unless the host bootstrap config declares
      ## `[locking]` routes; the all-public default records nothing here).
    exitCode*: int

  WorkspaceLockOutcome* = object
    report*: WorkspaceLockReport
    deferredParticipation: seq[DeferredParticipationWrite]

proc toJsonNode*(report: WorkspaceLockReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["manifestLayerRoot"] = %report.manifestLayerRoot
  result["lockFilePath"] = %report.lockFilePath
  result["indexFilePath"] = %report.indexFilePath
  result["triggerRepo"] = %report.triggerRepo
  result["triggerSha"] = %report.triggerSha
  result["createdAt"] = %report.createdAt
  result["workspaceBranch"] = %report.workspaceBranch
  result["replacedExistingEntry"] = %report.replacedExistingEntry
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["remote"] = %entry.remote
    obj["revision"] = %entry.revision
    obj["branch"] = %entry.branch
    repos.add(obj)
  result["repos"] = repos
  var dirty = newJArray()
  for entry in report.dirty:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["reason"] = %entry.reason
    dirty.add(obj)
  result["dirty"] = dirty
  var unmaterialized = newJArray()
  for entry in report.unmaterialized:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["reason"] = %entry.reason
    obj["detail"] = %entry.detail
    unmaterialized.add(obj)
  result["unmaterialized"] = unmaterialized
  result["exitCode"] = %report.exitCode

proc unmaterializedLockNotice*(
    entries: openArray[WorkspaceLockUnmaterializedReport]): string =
  ## The single wording both ``repro workspace lock`` and the pre-push
  ## gate use to surface repos the lock could not pin. Shared so the two
  ## surfaces cannot drift, and so a test can assert one string.
  ## Returns ``""`` for a fully materialized workspace.
  if entries.len == 0:
    return ""
  var names: seq[string]
  for entry in entries:
    names.add(entry.path & " (" & entry.reason & ")")
  "lock does not pin " & $entries.len &
    " declared repo(s) with no on-disk checkout: " & names.join(", ") &
    " — recorded under [extensions] unmaterialized_repos; run " &
    "'repro workspace sync' to materialize and pin them"

proc renderLockTextLines*(report: WorkspaceLockReport): seq[string] =
  if report.exitCode == 0:
    if report.lockFilePath.len > 0:
      result.add("workspace lock: wrote " & report.lockFilePath &
        " (trigger=" & report.triggerRepo & "@" &
        report.triggerSha & ")")
    else:
      # HL-2 (§6 Decision 1) routed case: no manifest partition lock was
      # written because the git-checkout manifest backend owns no repo in this
      # workspace (every declared route points elsewhere, or the workspace is
      # public-only). Each repo's record went to its assigned backend and is
      # reported by the `recorded … via … backend` lines below. Avoid printing
      # a blank path.
      result.add("workspace lock: recorded per-repo lock entries" &
        " (trigger=" & report.triggerRepo & "@" &
        report.triggerSha & ")")
    for entry in report.repos:
      result.add("workspace lock: locked " & entry.path & " @ " &
        entry.revision &
        (if entry.branch.len > 0: " (branch " & entry.branch & ")" else: ""))
    if report.replacedExistingEntry:
      result.add("workspace lock: overwrote existing lock for (" &
        report.triggerRepo & ", " & report.triggerSha & ")")
    # MO-4 — per-repo locking-backend routing (only when `[locking]` routes
    # are declared; otherwise `participation` is empty and nothing prints).
    for p in report.participation:
      if p.recorded:
        result.add("workspace lock: recorded " & p.repoName &
          " via " & p.backendKind & " backend")
      elif p.backendKind == "committed-lock":
        result.add("workspace lock: " & p.repoName &
          " covered by committed lock (no backend)")
      elif p.diagnostic.len > 0:
        result.add("workspace lock: failed to record " & p.repoName &
          " via " & p.backendKind & " backend: " & p.diagnostic)
  let unmaterializedNotice = unmaterializedLockNotice(report.unmaterialized)
  if unmaterializedNotice.len > 0:
    result.add("workspace lock: " & unmaterializedNotice)
  for entry in report.dirty:
    result.add("workspace lock: refused — '" & entry.path &
      "' is dirty (" & entry.reason & ")")

type
  WorkspaceLockArgs = object
    workspaceRoot: string
    projectName: string
    manifestLayerRoot: string
    triggerRepo: string
    triggerRepoPath: string
      ## RA-30 — the ON-DISK path of the repo whose commit triggered this
      ## lock, for callers that know the directory but not the manifest
      ## NAME. The two are not interchangeable: a repo's ``name`` may
      ## differ from its ``path`` (``nim`` lives at ``codetracer-nim``),
      ## and the post-commit hook is handed a directory
      ## (``--current-repo=<dir>``), never a name. Consulted only when
      ## ``triggerRepo`` is empty; resolved against the project's declared
      ## repos by ``pickTriggerRepo``.
    triggerSha: string
    triggerOutsideEveryPartition: bool
      ## The operation was triggered by a repo that belongs to NO lock
      ## partition — today that is exactly the MEMBERSHIP repo (the checkout
      ## carrying ``projects/``/``repos/``), which no project declares and
      ## which therefore has no manifest ``name`` to key a record by
      ## ([Workspace-Manifests.md] §"Path components are encoded names": the
      ## ``<repo>`` component is a declared repo's *name*).
      ##
      ## Unified-Locking-And-Hooks.md §6 Decision 1, consequence 2 settles
      ## what to do: "the partition is anchored only at a trigger that BELONGS
      ## to it … when the trigger is outside the partition, the manifest gets
      ## no trigger-keyed document for that operation." So no trigger-keyed
      ## record is written, and — crucially — the anchor does NOT fall through
      ## to ``pickTriggerRepo``'s project-named default, which would file the
      ## membership repo's workspace state under an unrelated repo's name and
      ## commit. See the block comment at the partition write for what that
      ## cost in the field.
    toolProvisioning: ToolProvisioningMode
    # RA-21 — when non-empty, the dirty-tree refusal only considers repos
    # whose NAME is in this set (the pushed repo's develop-set dependency
    # closure). The lock body still records EVERY workspace repo (full
    # reproducibility); only the refusal is scoped, so an out-of-closure
    # dirty repo cannot block a scoped pre-push lock refresh. Empty means
    # the legacy whole-workspace refusal (explicit ``repro workspace lock``
    # and post-commit keep that behavior).
    dirtyScopeNames: HashSet[string]
    dirtyScopeIsExplicit: bool
      ## ``dirtyScopeNames`` was DECIDED by the caller, so an empty set means
      ## "no repo is in scope" rather than "no scope was supplied".
      ##
      ## A bare ``HashSet`` cannot tell those apart, and the pre-push gate has
      ## a scope that is legitimately empty: a membership-repo push whose
      ## commit range touches no manifest fragment
      ## ([Workspace-And-Develop-Mode.md] §"Gate scope when the pushed repo is
      ## the membership repo" — "A commit touching no manifest fragment has an
      ## empty scope and checks only the membership repo's own cleanliness and
      ## publication"). The gate's own cleanliness stage honours that; the lock
      ## writer read the same empty set as the legacy whole-workspace refusal
      ## and blocked the push on an unrelated sibling's dirty tree — the exact
      ## outcome that section names as the friction its rule removes.
      ##
      ## Left ``false`` by ``repro workspace lock`` and the post-commit hook,
      ## which supply no scope and keep the whole-workspace refusal.
    report: ReportSpec
      ## Opt-in ``--write-report[=PATH]`` artifact. Left default-empty by the
      ## in-process (hook / pre-push) constructions of this object, which
      ## manage their own report destinations.

proc parseWorkspaceLockArgs(args: openArray[string]): WorkspaceLockArgs =
  ## ``repro workspace lock`` argv parser. The single optional
  ## positional is the project name (only required when no
  ## ``.repo/workspace.toml`` is present — same dispatch rule as
  ## M10's sync command). Optional flags:
  ##   ``--workspace-root=PATH``
  ##   ``--manifest-layer-root=PATH``
  ##   ``--sha=SHA``           — explicit trigger commit (M16 hook)
  ##   ``--trigger-repo=NAME``  — explicit trigger repo
  ##   ``--tool-provisioning=path|nix|tarball|scoop``
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--manifest-layer-root" or
        arg.startsWith("--manifest-layer-root="):
      result.manifestLayerRoot = valueFromFlag(args, i,
        "--manifest-layer-root")
    elif arg == "--sha" or arg.startsWith("--sha="):
      result.triggerSha = valueFromFlag(args, i, "--sha")
    elif arg == "--trigger-repo" or arg.startsWith("--trigger-repo="):
      result.triggerRepo = valueFromFlag(args, i, "--trigger-repo")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace lock` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace lock`: " & arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)
  if result.manifestLayerRoot.len > 0:
    result.manifestLayerRoot = absolutePath(result.manifestLayerRoot)

proc resolveWorkspaceLockProject(parsed: WorkspaceLockArgs):
    tuple[resolved: ResolvedProject; workspaceLocal: Option[WorkspaceLocal]] =
  ## Same dispatch rule as M10: prefer ``.repo/workspace.toml`` when it
  ## declares at least one ``[[manifest]]`` layer (composer mode),
  ## otherwise look up the named project / variant under
  ## ``.repo/manifests/``. A metadata-only workspace.toml (M13) routes
  ## to single-project mode. Also returns the parsed
  ## ``WorkspaceLocal`` (when composer mode applies) so the caller can
  ## pick the anchor manifest layer for the lock destination.
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    let absToml = absolutePath(workspaceToml)
    let workspaceLocal = readWorkspaceLocal(absToml)
    let resolved = extendWithActiveProjectSet(parsed.workspaceRoot,
      composeManifestLayers(workspaceLocal, parsed.workspaceRoot, absToml))
    return (resolved, some(workspaceLocal))
  if parsed.projectName.len == 0:
    # Allow a metadata-only workspace.toml to supply the project name.
    if fileExists(workspaceToml):
      try:
        let recordedProject =
          readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
        if recordedProject.len > 0:
          var withProject = parsed
          withProject.projectName = recordedProject
          # PS-2 — a lock with no explicit ``<project>`` is a snapshot of the
          # WORKSPACE, so it pins every repo of the active project set. The
          # lock's DESTINATION stays the primary project (see
          # ``pickManifestLayerRoot`` and the ``locks/<project>/`` layout).
          let recovered = resolveWorkspaceLockProject(withProject)
          return (extendWithActiveProjectSet(parsed.workspaceRoot,
            recovered.resolved), recovered.workspaceLocal)
      except WorkspaceManifestParseError:
        discard
    else:
      let migratedProject =
        legacyMigratedWorkspaceProjectName(parsed.workspaceRoot)
      if migratedProject.len > 0:
        var withProject = parsed
        withProject.projectName = migratedProject
        let recovered = resolveWorkspaceLockProject(withProject)
        return (extendWithActiveProjectSet(parsed.workspaceRoot,
          recovered.resolved), recovered.workspaceLocal)
    raise newException(ValueError,
      "`repro workspace lock` requires either `.repro/workspace.toml` " &
        "or a <project> argument; neither was present at " &
        parsed.workspaceRoot)
  let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
  let projectFile = manifestsRoot / "projects" /
    (parsed.projectName & ".toml")
  let variantFile = manifestsRoot / "variants" /
    (parsed.projectName & ".toml")
  if fileExists(projectFile):
    return (resolveProject(projectFile), none(WorkspaceLocal))
  if fileExists(variantFile):
    return (resolveVariant(variantFile), none(WorkspaceLocal))
  raise newException(ValueError,
    "no project or variant named '" & parsed.projectName &
      "' found under '" & manifestsRoot &
      "' (looked for '" & projectFile & "' and '" & variantFile & "')")

proc pickManifestLayerRoot(parsed: WorkspaceLockArgs;
                           workspaceLocal: Option[WorkspaceLocal]): string =
  ## Resolve the directory that will OWN the lock file. Priority:
  ##   1. The explicit ``--manifest-layer-root`` flag (M16 callers,
  ##      multi-tier setups).
  ##   2. The first ``[[manifest]]`` layer in
  ##      ``.repro/workspace.toml`` (composer mode). For ``local_path``
  ##      layers the path is taken verbatim (relative to the
  ##      workspace root); for ``url`` layers it's the on-disk
  ##      checkout the composer materialised at
  ##      ``<workspaceRoot>/.repro/manifests-<i>-<sanitized>``.
  ##   3. ``<workspaceRoot>`` (single-project mode,
  ##      matching M9/M10's resolver dispatch).
  if parsed.manifestLayerRoot.len > 0:
    return parsed.manifestLayerRoot
  if workspaceLocal.isSome:
    let local = workspaceLocal.get()
    if local.manifest.len > 0:
      let first = local.manifest[0]
      if first.local_path.isSome and first.local_path.get().len > 0:
        let raw = first.local_path.get()
        if isAbsolute(raw):
          return raw
        return parsed.workspaceRoot / raw
      if first.url.isSome and first.url.get().len > 0:
        # Mirror the composer's directory-naming convention so the
        # lock lands inside the same on-disk checkout the composer
        # acquired the layer at.
        let sanitizedSegments = block:
          var raw1 = ""
          for ch in first.url.get():
            case ch
            of 'A'..'Z', 'a'..'z', '0'..'9', '-', '.', '_': raw1.add(ch)
            else: raw1.add('-')
          var collapsed = ""
          var prevDash = false
          for ch in raw1:
            if ch == '-':
              if not prevDash: collapsed.add(ch)
              prevDash = true
            else:
              collapsed.add(ch)
              prevDash = false
          if collapsed.len > 80:
            collapsed.setLen(80)
          collapsed.strip(chars = {'-'},
            leading = true, trailing = true)
        let suffix =
          if sanitizedSegments.len > 0: sanitizedSegments
          else: "layer"
        return parsed.workspaceRoot / ".repro" /
          ("manifests-0-" & suffix)
  # Native default git-checkout lock store: the `.repro/manifests` store DB,
  # NOT the membership root. Membership (projects/repos) lives at the workspace
  # root (or a `.repro/manifests` checkout); the lock store is always the
  # `.repro/manifests` DB, separate from where membership resolves.
  #
  # ...but ONLY when that store actually exists as a git checkout. Returning the
  # path unconditionally infers a team route from a path that may never have been
  # declared, which Unified-Locking-And-Hooks.md §10 ("No implicit team route")
  # forbids: "The route is EXPLICIT, not inferred from the manifest's presence. A
  # workspace that never declares a team route is public-only and writes only
  # `repro.lock`." The unconditional return also made every downstream
  # `manifestLayerRoot.len > 0` guard permanently true — including the HL-3 guard
  # on the RA-7/RA-21 manifest publish, documented as firing "ONLY when a
  # `.repro/manifests` git-checkout is present". An all-public workspace would
  # then materialize a lock under a gitignored, non-git directory and report
  # "cannot publish lock" for a publish that should never have been attempted.
  # Empty means "no manifest-backed route declared"; the committed in-tree
  # `repro.lock` is the whole story (spec §8.2 public row).
  let nativeStore = parsed.workspaceRoot / ".repro" / "manifests"
  if dirExists(nativeStore / ".git") or fileExists(nativeStore / ".git"):
    return nativeStore
  ""

proc sameFilesystemPath(a, b: string): bool =
  ## Compare paths robustly across native vs forward-slash spelling.
  if a == b:
    return true
  var aN = os.normalizedPath(absolutePath(a)).replace('\\', '/')
  var bN = os.normalizedPath(absolutePath(b)).replace('\\', '/')
  try: aN = os.normalizedPath(expandFilename(a)).replace('\\', '/')
  except OSError: discard
  try: bN = os.normalizedPath(expandFilename(b)).replace('\\', '/')
  except OSError: discard
  when defined(windows):
    aN.toLowerAscii == bN.toLowerAscii
  else:
    aN == bN

proc pickTriggerRepo(resolved: ResolvedProject;
                     explicit, explicitPath, workspaceRoot: string;
                     identity: GitToolIdentity):
    ResolvedRepo =
  ## Choose the repo whose commit anchors the lock filename.
  ##
  ## The anchor is not cosmetic: consumers resolve a lock at
  ## ``locks/<project>/<repo>/<sha>`` for the COMMIT UNDER TEST (the
  ## `clone-siblings` CI action probes exactly that path for the pushed
  ## repo). A lock anchored at any other repo is therefore unreachable —
  ## it is keyed by a commit nobody will ever look up.
  ##
  ## Precedence:
  ##   1. an explicit ``--trigger-repo=NAME``;
  ##   2. ``triggerRepoPath`` — the on-disk directory of the triggering
  ##      repo, matched against the project's declared repo paths. This is
  ##      what hook-driven callers have: git hands a hook a working
  ##      directory, not a manifest name, and a repo's name and path are
  ##      allowed to differ;
  ##   3. only when NEITHER was supplied, the project-named anchor (the
  ##      repo whose ``name`` equals the project name), falling back to the
  ##      first declared repo.
  ##
  ## (3) is the right default for a caller that genuinely has no trigger —
  ## "lock the workspace as it stands" — and the wrong answer for every
  ## caller that does. A hook that knows the committed repo and lets the
  ## lock fall through to (3) files each repo's lock under the project
  ## anchor's name and SHA, where no consumer looks.
  if explicit.len > 0:
    for index, repo in resolved.repos:
      if repo.name == explicit:
        if explicitPath.len > 0:
          let matched = resolveRepoWorktreeMatch(
            identity, workspaceRoot, resolved.repos, explicitPath)
          if not matched.found or matched.repoIndex != index:
            raise newException(ValueError,
              "triggering worktree at '" & explicitPath &
                "' does not identify declared repo '" & explicit & "'" &
                (if matched.diagnostic.len > 0:
                  " (" & matched.diagnostic & ")"
                else: ""))
        return repo
    raise newException(ValueError,
      "trigger repo '" & explicit &
        "' is not declared in project '" & resolved.projectName & "'")
  if explicitPath.len > 0:
    let matched = resolveRepoWorktreeMatch(
      identity, workspaceRoot, resolved.repos, explicitPath)
    if matched.found:
      return resolved.repos[matched.repoIndex]
    # Refuse rather than fall through to the project anchor. The caller
    # named a specific triggering checkout; anchoring its lock at a
    # DIFFERENT repo's name and SHA would publish a record that claims a
    # commit this operation never observed, and that no consumer of the
    # triggering repo can find. "No lock" is recoverable and legible;
    # a misfiled one is neither.
    raise newException(ValueError,
      "triggering repo at '" & explicitPath &
        "' is not declared in project '" & resolved.projectName &
        "'; no lock can be anchored at it" &
        (if matched.diagnostic.len > 0:
          " (" & matched.diagnostic & ")"
        else: ""))
  for repo in resolved.repos:
    if repo.name == resolved.projectName:
      return repo
  if resolved.repos.len == 0:
    raise newException(ValueError,
      "project '" & resolved.projectName &
        "' declares no repos; cannot pick a trigger anchor")
  resolved.repos[0]

proc executeWorkspaceLock(args: WorkspaceLockArgs;
    deferParticipation = false): WorkspaceLockOutcome =
  ## End-to-end driver. (1) Resolve the project / compose layers.
  ## (2) Pick the manifest layer that owns the lock. (3) Gather
  ## live HEAD-SHA + clean/dirty + current-branch observations for
  ## every declared repo. (4) Refuse on any dirty checkout. (5)
  ## Build the lock model + index entry. (6) Write both files and
  ## emit the structured report.
  var report: WorkspaceLockReport
  report.workspaceRoot = args.workspaceRoot

  let (resolved, workspaceLocal) = resolveWorkspaceLockProject(args)
  report.project = resolved.projectName

  let manifestLayerRoot = pickManifestLayerRoot(args, workspaceLocal)
  report.manifestLayerRoot = manifestLayerRoot

  let identity = ensureGitToolResolvable(
    args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # Resolve the trigger before observing repositories so a linked worktree is
  # both anchored under the right manifest repo name and observed at the
  # checkout that actually fired the hook. Reading the workspace's primary
  # checkout here can capture a different branch and HEAD.
  let triggerRepo = pickTriggerRepo(resolved, args.triggerRepo,
    args.triggerRepoPath, args.workspaceRoot, identity)

  # Observation pass. We gather all three values for every repo in
  # one walk so the dirty refusal can land alongside the trigger-
  # resolution check below.
  var headShas = initTable[string, string]()
  var currentBranches = initTable[string, string]()
  var dirtyEntries: seq[WorkspaceLockDirtyEntry]
  # RA-21 — the dirty refusal is scoped to ``dirtyScopeNames`` when the
  # caller supplied one (the pre-push gate passes the pushed repo's
  # dependency closure). An empty scope means "consider every repo" (the
  # legacy whole-workspace behavior). A repo outside the scope still has
  # its HEAD recorded in the lock, but its dirtiness never refuses.
  #
  # MATERIALIZATION IS NOT A PRECONDITION FOR LOCKING. This loop used to
  # gate THREE distinct properties — "must exist", "must answer
  # rev-parse", "must be clean" — on the single ``inDirtyScope`` flag, so
  # a whole-workspace scope (an empty ``dirtyScopeNames``, which is what
  # ``prePushScope``'s no-scope-information fallback yields) demanded that
  # EVERY declared repo in the workspace be materialized before any lock
  # could be written. In a multi-project workspace the declared set is the
  # union of every active project (Workspace-And-Develop-Mode.md
  # §"Multi-Project Workspaces"), so that turned "publish one manifest
  # commit" into "clone every repo of every project, including formal-
  # methods corpora nobody in this workspace builds".
  #
  # Existence is not the same property as cleanliness. A declared repo
  # with no checkout is a legitimate, first-class state: membership is
  # recorded before materialization (ibid. §"Membership and
  # Materialization"), ``repro workspace sync`` materializes on demand
  # (§"Missing local checkout for a develop-mode node" is a sync corner
  # case, not a lock error), and the pre-push gate's OWN cleanliness /
  # publication stage already decided what an absent checkout means —
  # vacuously satisfied for a public repo, an actionable
  # ``clone-required`` failure for a shared-private one (MO-5). Refusing
  # again here contradicted the stage that had just passed.
  #
  # So an unobservable repo is RECORDED, never raised on: it contributes
  # an ``[extensions] unmaterialized_repos`` entry naming it and why,
  # instead of a revision it cannot honestly supply. Silence was the one
  # option ruled out — a lock that is short by a repo, with no way for a
  # consumer to tell, is worse than either refusing or saying so.
  # An EXPLICIT scope is authoritative including when it is empty. Reading a
  # decided-and-empty scope as "no scope supplied" restored the whole-workspace
  # dirty refusal for exactly the push the scope rule exists to unblock — a
  # membership commit touching no manifest fragment, refused because some
  # unrelated sibling had edits in its tree.
  let scopeDirty = args.dirtyScopeIsExplicit or args.dirtyScopeNames.len > 0
  for repo in resolved.repos:
    let repoPath =
      if args.triggerRepoPath.len > 0 and repo.name == triggerRepo.name:
        args.triggerRepoPath
      else:
        args.workspaceRoot / repo.path
    let inDirtyScope = (not scopeDirty) or repo.name in args.dirtyScopeNames
    if not discoverGitWorktree(identity, repoPath).ok:
      report.unmaterialized.add(WorkspaceLockUnmaterializedReport(
        name: repo.name, path: repo.path,
        reason: "no on-disk checkout",
        detail: "probed '" & repoPath & "'"))
      continue
    let headRes = queryGitState(headShaQuery(repoPath), identity)
    if headRes.status != gqsOk:
      # A checkout that exists but cannot answer ``rev-parse HEAD`` (an
      # unborn branch, a corrupt gitdir) is unobservable for the same
      # reason and gets the same treatment — named, not fabricated.
      report.unmaterialized.add(WorkspaceLockUnmaterializedReport(
        name: repo.name, path: repo.path,
        reason: "could not query HEAD SHA",
        detail: headRes.diagnostic))
      continue
    headShas[repo.path] = headRes.headSha
    let cleanRes = queryGitState(isCleanQuery(repoPath), identity)
    let isClean =
      if cleanRes.status == gqsOk: cleanRes.isClean
      else: false
    if not isClean and inDirtyScope:
      let reason =
        if cleanRes.status != gqsOk:
          "clean/dirty probe failed: " & cleanRes.diagnostic
        else:
          "working tree has uncommitted changes"
      dirtyEntries.add(WorkspaceLockDirtyEntry(
        name: repo.name, path: repo.path, reason: reason))
    let branchRes = gitRunPlain(identity,
      ["-C", repoPath, "symbolic-ref", "--short", "-q", "HEAD"])
    if branchRes.code == 0:
      let branch = branchRes.output.strip()
      if branch.len > 0:
        currentBranches[repo.path] = branch

  # Refuse-and-report path: a lock at a dirty tree would lie about
  # what the recorded SHA reproduces.
  if dirtyEntries.len > 0:
    report.dirty = dirtyEntries
    report.exitCode = 2
    result.report = report
    return

  # ``getOrDefault``, not ``[]``: since an unobservable repo is recorded
  # rather than raised on, the trigger repo itself may now be one — and a
  # ``KeyError`` would report that as "key not found" instead of the
  # actionable sentence below. The ANCHOR is the one repo that genuinely
  # must be observable: the record's path and identity are its commit, so
  # there is no lock to write without it.
  let triggerSha =
    if args.triggerSha.len > 0: args.triggerSha
    else: headShas.getOrDefault(triggerRepo.path)
  # ...unless this operation writes no trigger-keyed record at all (the
  # membership repo — see the partition write below). There is then no anchor
  # to demand, and demanding one would refuse a membership push merely because
  # the project's primary repo — a repo the push has nothing to do with — is
  # not materialized here.
  if triggerSha.len == 0 and not args.triggerOutsideEveryPartition:
    raise newException(ValueError,
      "could not determine trigger SHA for repo '" &
        triggerRepo.name & "' at path '" & triggerRepo.path &
        "'; the lock is keyed by the trigger repo's commit, so that repo " &
        "must have an on-disk checkout (run `repro workspace sync`)")

  let createdAt = isoTimestampNow()
  let createdBy = "repro workspace lock"
  var workspaceBranch = ""
  if workspaceLocal.isSome and workspaceLocal.get().workspace.branch.isSome:
    workspaceBranch = workspaceLocal.get().workspace.branch.get()
  elif resolved.trunk.len > 0:
    workspaceBranch = resolved.trunk

  # Record every repo we actually observed. A declared repo we could not
  # observe is not silently dropped: it was collected into
  # ``report.unmaterialized`` above and is written into the lock's
  # ``[extensions] unmaterialized_repos`` below, so the document's repo
  # list and its stated omissions together account for the whole declared
  # set.
  var lockRepos: seq[ResolvedRepo]
  for repo in resolved.repos:
    if repo.path in headShas:
      lockRepos.add(repo)

  # HL-2 (§6 Decision 1) — partition by resolved tier so the git-checkout
  # manifest lock TOML holds ONLY the repos routed to THAT backend, never a
  # cross-tier mix. ``manifestOwnedRepos`` returns every observed repo when no
  # explicit route is declared (today's single-tier shape ⇒ byte-identical
  # monolithic write); when routes ARE declared it drops the public
  # (committed-lock) and personal/other-backend repos from the manifest file —
  # their records are written to their OWN backends by
  # ``recordRoutedParticipation`` below. The tier→backend binding comes from the
  # HL-1 composed configuration plane.
  let composed = composeLockingRouting(args.workspaceRoot, identity.binaryPath)
  # HL-2 (§10) — a legacy ``.repo/manifests`` workspace with no team route must
  # never silently go public-only; warn (once) and name the ``adopt-manifest``
  # remedy. Best-effort — never blocks the lock.
  maybeWarnLegacyManifestWithoutTeamRoute(args.workspaceRoot, composed)
  let manifestRepos = manifestOwnedRepos(
    composed, lockRepos, args.workspaceRoot, manifestLayerRoot, identity)

  var lock = buildLockFromLiveState(
    project = resolved.projectName,
    workspaceBranch = workspaceBranch,
    createdAt = createdAt,
    createdBy = createdBy,
    resolved = manifestRepos,
    headShasByPath = headShas,
    currentBranchesByPath = currentBranches)

  # Carry the unobserved repos into the document itself. The report alone
  # is not enough: the report is consumed by whoever ran the command, and
  # the omission has to be legible to whoever READS THE LOCK later — the
  # CI sibling resolver that finds no ``[[repo]]`` for a path needs to
  # distinguish "not in this workspace" from "this workspace could not
  # observe it".
  for entry in report.unmaterialized:
    var remoteName = ""
    for repo in resolved.repos:
      if repo.path == entry.path:
        remoteName = repo.projectRemote
        break
    lock.unmaterialized.add(WorkspaceLockUnmaterializedEntry(
      name: entry.name, path: entry.path, remoteName: remoteName,
      reason: entry.reason))

  let lockPath = lockFilePath(manifestLayerRoot, resolved.projectName,
    triggerRepo.name, triggerSha)
  # RA-1: per-repo lock directory keyed by the full trigger SHA; no
  # shared index is written. Re-locking the same SHA overwrites the
  # same file, so "replaced an existing lock" is simply "the lock file
  # already existed on disk before this write".
  let lockAlreadyExisted = fileExists(extendedPath(lockPath))
  # RA-31 — "a file is at that path" and "a record is published there" are
  # different claims, and only the second one is immutable.
  #
  # The refusal below exists to stop a re-run from REWRITING AN ALREADY-TRACKED
  # RECORD (its own wording). It was testing ``fileExists``, which also matches
  # a file this same workspace wrote moments ago and has not committed. Two
  # hooks legitimately address the same key: post-commit writes
  # ``locks/<p>/<repo>/<sha>`` when the commit lands, and the pre-push gate
  # writes the same key when that commit is pushed. Between them the OTHER
  # repos in the workspace may move — the key is (trigger repo, trigger sha),
  # so it does not change when a sibling commits. The gate then found its own
  # uncommitted draft, saw different coordinates for the siblings, and refused
  # the push:
  #
  #   lock-failure — immutable lock record already exists at
  #   'locks/app/lib/<libSha>.toml' with different repository coordinates
  #   (changed paths: app, other)
  #
  # The draft was strictly LESS complete than the record the gate was about to
  # write; superseding it is what "create or refresh the lock" means. Only a
  # record git is tracking is history, and history is what must not be
  # rewritten. An untracked path is a draft.
  let lockRelForTracking =
    if manifestLayerRoot.len > 0 and lockPath.startsWith(manifestLayerRoot):
      lockPath[manifestLayerRoot.len .. ^1].strip(
        chars = {DirSep, '/'}, trailing = false).replace('\\', '/')
    else: ""
  let lockAlreadyPublished =
    lockAlreadyExisted and lockRelForTracking.len > 0 and
      gitRunPlain(identity, ["-C", manifestLayerRoot, "ls-files",
        "--error-unmatch", "--", lockRelForTracking]).code == 0
  # HL-2 (§6 Decision 1 — target write path) — the trigger-keyed
  # ``writeLockFile`` is the git-checkout manifest backend's PARTITION of the
  # workspace lock, and it is written whenever that backend owns the trigger
  # repo (see the anchoring rule below). Decision 1 spells the team row out:
  # "**team** partition → a
  # ``locks/<project>/<repo>/<sha>.toml`` written into the team's durable
  # backend, containing only the team partition's repos", and closes with "the
  # git manifest lock file, when one is produced, contains **only** the repos
  # routed to that backend". ``manifestOwnedRepos`` above computes exactly that
  # subset, so tier isolation is enforced by WHAT the document contains, not by
  # suppressing the document.
  #
  # Suppressing it on ``hasExplicitRoutes`` (as this gate previously did) threw
  # that partition away precisely when it is meaningful, and left the
  # per-repo ``routedParticipationBody`` records as the only thing in the
  # manifest. Those records announce no ``schema`` and pin one repo each, so
  # they answer no cross-repo question: CI sibling resolution
  # (``clone-siblings`` / ``resolve-sibling-rev.sh``, which reads exactly this
  # path) degraded to "no workspace lock found" for every commit locked that
  # way. The partition lock is what that consumer reads, and the reason the
  # record is keyed by the TRIGGER commit at all.
  #
  # ``manifestLayerRoot`` is EMPTY when no manifest-backed route is declared
  # (§10 "No implicit team route"): there is no git-checkout store to write a
  # trigger-keyed record into, and the committed in-tree ``repro.lock`` is the
  # whole publication story. Writing anyway would resolve ``lockPath`` relative
  # to the process CWD and scatter a ``locks/`` tree wherever the gate happened
  # to run. Public-only workspaces write no manifest lock at all.
  #
  # The routed partition is additionally anchored ONLY at a trigger that
  # BELONGS to it. The record's path is ``locks/<project>/<TRIGGER>/<sha>``, and
  # a consumer reaches it by asking "what did the workspace look like at THIS
  # repo's commit" (``pickTriggerRepo``'s own contract). Filing the team
  # partition under a public or personal trigger would both put a record where
  # nobody looks and drop a team SHA into a directory named for a repo of
  # another tier. When the trigger is outside the partition the manifest simply
  # gets no trigger-keyed document for this operation, and its repos keep their
  # per-repo participation records until one of them is itself the trigger.
  #
  # The MEMBERSHIP repo is the extreme of that rule: it belongs to no
  # partition at all, because no project declares it. It has no manifest
  # ``name``, so there is no ``<repo>`` component to encode
  # ([Workspace-Manifests.md] §"Path components are encoded names, not joined
  # paths" — the component is a declared repo's *name*), and
  # Workspace-And-Develop-Mode.md §"Gate scope when the pushed repo is the
  # membership repo" says plainly that it "is not a project repo".
  #
  # ``pickTriggerRepo``'s fallback (3) nevertheless answered with the
  # PROJECT-NAMED repo, because a membership push supplies neither a trigger
  # name nor a trigger path. The record then claimed, at some unrelated repo's
  # old commit, a workspace state that commit never saw — and because
  # publication is additions-only and records are immutable, the coordinate was
  # burned: every later membership push produced the same key with different
  # sibling coordinates and refused,
  #
  #   immutable lock record already exists at
  #   'locks/<project>/<primary>/<primarySha>.toml' with different repository
  #   coordinates (changed paths: …)
  #
  # with no way to advance until the primary repo's HEAD happened to move.
  # ``repro workspace lock`` refused identically, so the workspace was wedged.
  var triggerInManifestPartition = false
  for repo in manifestRepos:
    if repo.path == triggerRepo.path:
      triggerInManifestPartition = true
      break
  let writeManifestPartition = manifestLayerRoot.len > 0 and
    not args.triggerOutsideEveryPartition and
    (not composed.hasExplicitRoutes or triggerInManifestPartition)
  # False only when the trigger coordinate is already occupied by a PUBLISHED
  # participation record, which this operation must neither overwrite nor claim
  # as its own lock (see below). The report must not name a path holding
  # somebody else's record, and the repos the partition would have covered must
  # keep their per-repo records, so both follow this flag rather than the
  # intent above.
  var partitionRecordPresent = writeManifestPartition
  if writeManifestPartition:
    if lockAlreadyPublished:
      # The path is content-addressed by the exact trigger commit and lock
      # publication accepts canonical additions only. Re-running a gate must
      # therefore never rewrite an already-tracked record merely because
      # generated metadata such as ``created_at`` changed. Accept the existing
      # immutable record only when its complete path→revision coordinate map is
      # identical to the state we would write; otherwise fail closed instead of
      # turning an addition into a mutable lock-history update.
      #
      # RA-31 — gated on TRACKED, not on present-on-disk. An untracked file at
      # this path is this workspace's own unpublished draft (see above); it is
      # overwritten by the ``else`` arm rather than defended.
      let existingBody = readFile(extendedPath(lockPath))
      # HL-2 — a routed ``routedParticipationBody`` record announces no
      # ``schema`` and pins one repo; it is not a workspace lock and never was
      # one. Workspaces that locked while the partition write was suppressed
      # have such records TRACKED at exactly the coordinates their own partition
      # lock would occupy. Two things must not happen there:
      #
      #   * the coordinate-mismatch refusal below (1 path vs N) must not fire —
      #     it reads as "someone published a different workspace state at this
      #     commit", which is false, and it would turn every lock in such a
      #     workspace into a lock-failure and block the push; and
      #   * the partition must not be written over it — publication is
      #     ADDITIONS-ONLY at both the staging check and the ahead-chain
      #     verifier (``verifyLockOnlyAheadChain``: "additions-only, with NO
      #     exception"), so an ``M`` entry would be refused on this and every
      #     later publish, wedging the store rather than repairing it.
      #
      # So the historical record is left exactly as published, and the operator
      # is told plainly what it costs. No repair verb is named: ``repro
      # workspace migrate-locks`` repairs a record at a NON-CANONICAL PATH,
      # which this is not — the path is canonical and the BODY is the wrong
      # shape — so pointing at it would send the operator to a verb whose
      # planner will not select this record. Commits already carrying such a
      # record stay unresolvable for cross-repo CI (the resolver treats them as
      # unlocked, which is the mild, correct answer for history); every NEW
      # commit gets its partition normally.
      if not isWorkspaceLockDocument(existingBody):
        partitionRecordPresent = false
        stderr.writeLine(
          "repro workspace lock: '" & lockPath & "' already holds a published " &
          "per-repo participation record, which is where this workspace's " &
          "lock document belongs. Published lock records are immutable and " &
          "lock publication is additions-only, so it is left untouched: this " &
          "commit cannot be used for cross-repo sibling resolution. Later " &
          "commits lock normally.")
      else:
        let existingShas = shasFromBody(existingBody)
        var sameCoordinates = existingShas.len == lock.repos.len
        var mismatchedPaths: seq[string]
        # The NAMES behind those paths, because the remedy below has to be a
        # command and ``--trigger-repo`` takes a name, not a path (the two are
        # allowed to differ — ``nim`` lives at ``codetracer-nim``).
        var mismatchedNames: seq[string]
        proc noteMismatch(entry: WorkspaceLockEntry) =
          mismatchedPaths.add(entry.path)
          if entry.name.len > 0 and entry.name != triggerRepo.name and
              entry.name notin mismatchedNames:
            mismatchedNames.add(entry.name)
        if sameCoordinates:
          for entry in lock.repos:
            if entry.path notin existingShas or
                existingShas[entry.path] != entry.revision:
              sameCoordinates = false
              noteMismatch(entry)
        else:
          for entry in lock.repos:
            if entry.path notin existingShas or
                existingShas[entry.path] != entry.revision:
              noteMismatch(entry)
        if not sameCoordinates:
          # Unified-Locking-And-Hooks.md §6 Decision 2, "Remedy text shape":
          # "**The named command must RUN where the message is printed.**"
          # This refusal used to end with "keep the existing record and create
          # a lock anchored by the commit that changed" — a correct
          # description of the repair and not a command anybody can type. The
          # gate wrapped it in "investigate the lock writer error and re-run
          # `repro check`", which is the invocation that had just refused, so
          # the whole message pair named no way forward at all.
          #
          # The repair IS expressible: the record at this key is history and
          # stays as published; a NEW record is anchored at a repo whose commit
          # actually moved, and ``--trigger-repo=`` is how the operator says
          # which. Its coordinate is free precisely BECAUSE that repo moved, so
          # the command has somewhere to write. ``--workspace-root=`` is spelled
          # out for the same reason ``workspaceLockCommand`` spells it out: the
          # gate speaks from inside the pushed repo.
          let remedy =
            if mismatchedNames.len > 0:
              workspaceLockCommand(args.workspaceRoot) &
                " --trigger-repo=" & mismatchedNames[0]
            else:
              workspaceLockCommand(args.workspaceRoot)
          raise newException(ValueError,
            "immutable lock record already exists at '" & lockPath &
            "' with different repository coordinates" &
            (if mismatchedPaths.len > 0:
              " (changed paths: " & mismatchedPaths.join(", ") & ")"
            else: "") &
            "; that record is published history and is kept as-is — anchor " &
            "the new workspace state at a commit that did change: `" &
            remedy & "`")
    else:
      writeLockFile(lock, lockPath)
  if partitionRecordPresent:
    report.lockFilePath = lockPath
    report.replacedExistingEntry = lockAlreadyExisted
    for entry in lock.repos:
      report.repos.add(WorkspaceLockRepoEntry(
        name: entry.name,
        path: entry.path,
        remote: entry.remoteName,
        revision: entry.revision,
        branch: entry.branch))
  report.indexFilePath = ""
  # Report the anchor only when one was USED. Naming ``pickTriggerRepo``'s
  # unused fallback here would print "trigger=<primary>@<primarySha>" for an
  # operation that deliberately anchored nothing.
  report.triggerRepo =
    if args.triggerOutsideEveryPartition: ""
    else: triggerRepo.name
  report.triggerSha =
    if args.triggerOutsideEveryPartition: ""
    else: triggerSha
  report.createdAt = createdAt
  report.workspaceBranch = workspaceBranch

  # MO-4 — record each repo's participation through its ASSIGNED locking
  # backend (config → per-repo backend, keyed by visibility). A no-op when the
  # workspace declares no `[locking]` routes, so the all-public default and
  # every manifest-present operation are byte-unchanged. An unrouted private
  # repo raises `StoreRoutingError` (loud, names the repo) — propagated to the
  # operator by `repro workspace lock`; the gate surfaces it as a lock-failure.
  #
  # HL-2 (§6 Decision 1) — repos covered by the manifest PARTITION LOCK written
  # just above are recorded by that document, so they are excluded here rather
  # than double-written as minimal per-repo records into the very same
  # git-checkout store (where the trigger repo's write collides with the
  # partition and fails — a failed TEAM outcome the gate escalates to a push
  # refusal — and every other repo's write squats on its own future key).
  # `partitionRoot` is empty when no partition was written, so the per-repo
  # fan-out is unchanged there.
  #
  # ...and the same exclusion holds when this operation deliberately wrote NO
  # trigger-keyed document because the trigger belongs to no partition (the
  # membership repo). "No document was added" is not "these repos are not
  # covered": the manifest backend still owns them, and each already has — or
  # will publish — its own trigger-keyed partition at its own commit. Letting
  # the fan-out run there is precisely the squatting the paragraph above
  # describes, and it is not hypothetical: a membership push in a routed
  # workspace refused with one
  #
  #   lock-backend-unreachable — team repo '<r>' could not be published …
  #   (immutable lock record already exists with different content at
  #   locks/<project>/<r>/<its own head>.toml)
  #
  # per repo, naming the very partitions those repos had published themselves.
  let participationPartitionRoot =
    if partitionRecordPresent or args.triggerOutsideEveryPartition:
      manifestLayerRoot
    else: ""
  if deferParticipation:
    result.deferredParticipation = prepareRoutedParticipation(
      args.workspaceRoot, lockRepos, headShas, resolved.projectName, identity,
      participationPartitionRoot)
  else:
    report.participation = recordRoutedParticipation(
      args.workspaceRoot, lockRepos, headShas, resolved.projectName, identity,
      participationPartitionRoot)

  report.exitCode = 0
  result.report = report

proc writeWorkspaceLockReport(report: WorkspaceLockReport;
                              destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

# ---- RA-7: lock publication (commit + push) ------------------------------
#
# Writing a lock and *publishing* it are distinct (Workspace-Manifests.md
# § "Lock publication (commit + push)"). The writer drops the TOML under
# ``locks/<project>/<repo>/<sha>.toml`` in the manifest-repo checkout;
# ``publishWorkspaceLock`` then commits and pushes that subtree to the
# manifest repo's upstream so the lock actually reaches teammates.
#
# Contract (models repo-workspaces ``publishWorkspaceLock``, commits
# ``8c60ca7`` + ``24252a0`` + ``5884c31``):
#
#   - Stage everything under ``locks/`` (``git add -- locks``).
#   - REFUSE if the manifest repo is dirty OUTSIDE ``locks/`` — a publish
#     commit must touch only locks, never sweep up unrelated edits. When
#     refusing, unstage what we just staged so the index is left as we
#     found it; the dirty file itself is never touched.
#   - Reject empty / zero-byte staged lock files before committing.
#   - Commit with a focused message (``Publish N workspace lock entr…``).
#   - Push to the manifest repo's upstream (``git push <remote>
#     HEAD:<branch>``), resolving the remote/branch from the current
#     branch's ``@{u}``.
#
# Best-effort: every failure path (no upstream, dirty-outside-locks,
# nothing to commit, network/push error) is logged and returns ``false``;
# it never raises and never blocks the parent operation. Callers that gate
# on publication (the pre-push path) treat ``false`` as "lock not
# published" and decide their own policy; post-commit never calls this at
# all (it stays strictly local — Workspace-Manifests.md publish table).

type
  LockPublishOutcome* = enum
    lpoPublished        ## Staged locks committed AND pushed to upstream.
    lpoNothingToPublish ## No staged lock changes; nothing to commit/push.
    lpoRefusedDirty     ## Manifest repo dirty outside ``locks/``; refused.
    lpoNotPublishable   ## Manifest layer is not a git checkout / has no
                        ## upstream — this workspace is not configured to
                        ## publish locks at all. RA-21 treats this as a
                        ## benign best-effort skip (NOT a loud refusal):
                        ## there is no publication boundary to honour.
    lpoFailed           ## A real publish ATTEMPT failed (empty lock, commit
                        ## or push error). RA-21 treats this as a loud
                        ## refusal in the pre-push gate.

  LockPublishResult* = object
    outcome*: LockPublishOutcome
    diagnostic*: string
    verifiedLocalHead*: string
      ## Non-empty only when a local-only backend HEAD was proven to be a
      ## valid additions-only lock chain before a transport failure. Callers
      ## surface this in partial-success reports so recovery is auditable.


proc gitPorcelainEntries(identity: GitToolIdentity;
                         repoRoot: string): seq[tuple[code, path: string]] =
  ## Parse ``git status --porcelain=v1`` lines into (XY, path) pairs.
  ## Renames (``R  old -> new``) surface the destination path, which is
  ## what the dirty-outside-``locks/`` guard cares about.
  let res = gitRunPlain(identity,
    ["-C", repoRoot, "status", "--porcelain=v1", "--untracked-files=all"])
  if res.code != 0:
    return
  for rawLine in res.output.splitLines():
    if rawLine.len < 4:
      continue
    let code = rawLine[0 .. 1]
    var path = rawLine[3 .. ^1]
    let arrow = path.find(" -> ")
    if arrow >= 0:
      path = path[(arrow + 4) .. ^1]
    path = path.strip(chars = {'"'})
    result.add((code: code, path: path))

proc pathIsUnderLocks(path: string): bool =
  ## A repo-relative status path is "in scope" for the lock commit when it
  ## lives under the top-level ``locks/`` directory.
  let normalized = path.replace('\\', '/')
  normalized == "locks" or normalized.startsWith("locks/")

proc pushOutputIsNonFastForward*(output: string): bool =
  ## A push rejected because a COMPETING WRITER moved the remote ref (or held
  ## its lock) while we were pushing — the lost race RA-29's bounded, verified
  ## re-apply loop may retry. Every failure whose cause is transport,
  ## credentials, or branch policy returns ``false`` and stays LOUD (RA-21).
  ## We fold stderr into stdout (``poStdErrToStdOut``), so all markers are
  ## matched case-insensitively against the combined transcript.
  ##
  ## Git's wording for the SAME compare-and-swap loss changes between
  ## releases, so no single phrase may be a required conjunct (that bug shipped
  ## once already: requiring ``cannot lock ref`` made every 2.51 race a
  ## user-visible hard failure). Observed transcripts:
  ##
  ## * git 2.50.1 — ``remote: error: cannot lock ref 'refs/heads/main': is at
  ##   <new> but expected <advertised>`` plus
  ##   ``! [remote rejected] HEAD -> main (failed to update ref)``.
  ## * git 2.51.2 — ``! [remote rejected] HEAD -> main (incorrect old value
  ##   provided)`` and NOTHING else; the ``cannot lock ref`` detail line is
  ##   gone.
  ## * client-side detection (remote already ahead at advertisement time) —
  ##   ``! [rejected]        HEAD -> main (fetch first)`` /
  ##   ``(non-fast-forward)``.
  ##
  ## So we require two facts that ARE stable across every observed release:
  ##
  ## 1. Git reported a rejected ref update. Both spellings are live —
  ##    ``[rejected]`` for a client-side non-fast-forward, ``[remote
  ##    rejected]`` for a receive-pack compare-and-swap loss — and neither is
  ##    a substring of the other, so both are matched. A DNS, connection or
  ##    credential failure dies before ref-update reporting and prints
  ##    neither, which is what keeps those loud.
  ## 2. At least ONE marker that the rejection was about the ref's VALUE or
  ##    LOCK rather than about policy. ``(pre-receive hook declined)``,
  ##    ``(deny current branch)`` and similar refusals satisfy fact 1 but
  ##    carry none of these markers, so a protected branch never enters the
  ##    retry loop.
  ##
  ## Widening fact 2 is safe by construction because this predicate only
  ## decides whether to ENTER recovery, never whether recovery may mutate
  ## anything: the caller re-fetches an immutable tip, refuses unless the
  ## previously observed tip is still an ancestor of it, and replays the
  ## chain only after re-proving it is lock-only and matches the exact
  ## expected records. A false positive therefore costs at most
  ## ``lockPublishNonFfRetryBudget`` non-destructive attempts before the
  ## failure is reported loudly anyway; a false negative costs a spurious
  ## "check backend connectivity" failure on a perfectly healthy remote.
  ##
  ## Pinned against literal captured transcripts from both git versions in
  ## this library's ``tests/t_lock_publish_push_race_classification.nim`` — a
  ## live-git test only ever proves whichever wording the local git emits.
  let low = output.toLowerAscii()
  if not (("[rejected]" in low) or ("[remote rejected]" in low)):
    return false
  # Client-side: the ref we advertised was already behind the remote tip.
  if ("non-fast-forward" in low) or ("fetch first" in low) or
     ("behind" in low):
    return true
  # receive-pack side: the compare-and-swap against the advertised old value
  # lost, or the ref could not be locked because another writer held it.
  # ``incorrect old value provided`` (2.51+) and ``failed to update ref``
  # (2.50 and earlier) are the reason parentheticals; ``cannot lock ref`` and
  # ``is at <new> but expected <advertised>`` are the detail lines that older
  # Git (including Git-for-Windows 2.47) additionally emits. ``stale info`` is
  # the same loss reported against an explicit lease.
  ("incorrect old value provided" in low) or
    ("failed to update ref" in low) or
    ("cannot lock ref" in low) or
    (("is at" in low) and ("but expected" in low)) or
    ("stale info" in low)

const lockPublishNonFfRetryBudget = 8
  ## RA-29: bounded re-apply attempts for a non-fast-forward (concurrent
  ## publisher) push. Because lock files are commit-addressed —
  ## ``locks/<project>/<repo>/<sha>.toml`` — concurrent publishers write
  ## DISJOINT paths, so re-applying our lock commit onto the freshly fetched
  ## tip NEVER conflicts; the budget only guards against pathological churn
  ## or a genuinely wedged remote (after which we stay loud, RA-21).

type
  LockUpstream = object
    remote: string
    branch: string
    display: string

proc resolveLockUpstream(identity: GitToolIdentity; repoRoot: string):
    tuple[ok: bool; target: LockUpstream; diagnostic: string] =
  let upstreamRes = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--abbrev-ref",
     "--symbolic-full-name", "@{u}"])
  if upstreamRes.code != 0 or upstreamRes.output.strip().len == 0:
    return (false, LockUpstream(),
      "manifest repo has no upstream (@{u}); cannot publish lock")
  let upstream = upstreamRes.output.strip()
  let slash = upstream.find('/')
  if slash <= 0 or slash == upstream.high:
    return (false, LockUpstream(), "unparseable upstream ref: " & upstream)
  (true, LockUpstream(remote: upstream[0 ..< slash],
    branch: upstream[(slash + 1) .. ^1], display: upstream), "")

proc fetchImmutableLockTip(identity: GitToolIdentity; repoRoot: string;
    target: LockUpstream): tuple[ok: bool; oid: string; diagnostic: string] =
  ## Fetch the exact agreed branch, then immediately capture FETCH_HEAD as an
  ## immutable object id. Later proofs never rely on a moving symbolic tracking
  ## ref.
  let fetchRes = gitRunPlain(identity,
    ["-C", repoRoot, "fetch", "--quiet", "--no-tags", target.remote,
     "refs/heads/" & target.branch])
  if fetchRes.code != 0:
    return (false, "", "git fetch " & target.remote & " " & target.branch &
      " failed; check backend connectivity and credentials")
  let tip = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "FETCH_HEAD^{commit}"])
  if tip.code != 0 or tip.output.strip().len == 0:
    return (false, "", "fetched upstream did not resolve to a commit")
  (true, tip.output.strip().toLowerAscii(), "")

type EffectivePrePushHookKind = enum
  ephNone
  ephReproV2
  ephReproIncompatible
  ephThirdParty

proc effectivePrePushHook(identity: GitToolIdentity; repoRoot: string):
    tuple[kind: EffectivePrePushHookKind; hookPath: string;
          diagnostic: string] =
  let pathRes = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--git-path", "hooks/pre-push"])
  if pathRes.code != 0 or pathRes.output.strip().len == 0:
    return (ephNone, "", "")
  let raw = pathRes.output.strip()
  let path =
    if raw.isAbsolute: os.normalizedPath(raw)
    else: os.normalizedPath(repoRoot / raw)
  if not fileExists(path): return (ephNone, path, "")
  let dispatcher = readFile(path)
  let managed = path.parentDir() / "pre-push.repro-managed"
  let managedContent = if fileExists(managed): readFile(managed) else: ""
  let recognizesRepro = dispatcher.contains("reprobuild hook dispatcher") or
    dispatcher.contains("reprobuild managed pre-push hook") or
    managedContent.contains("reprobuild managed pre-push hook")
  # Comments/markers are discovery hints only. Authorization and orchestration
  # require the complete canonical dispatcher/body pair and executable files;
  # a marker-only or partially refreshed bundle is incompatible, never v2.
  if dispatcher == vcsDispatcherContent("pre-push") and
      managedContent == vcsManagedHookContent("pre-push") and
      executableFile(path) and executableFile(managed):
    return (ephReproV2, path, "")
  if recognizesRepro:
    return (ephReproIncompatible, path,
      "installed Reprobuild pre-push hooks are old or partially upgraded")
  if not executableFile(path):
    return (ephNone, path, "")
  (ephThirdParty, path, "")

proc resolveHookReproCli(repoRoot: string): string =
  ## Byte-for-byte equivalent of the generated managed hook's
  ## `find_repro_cmd`, evaluated from the same repository directory. This is
  ## shared by preflight so it cannot probe getAppFilename() while the installed
  ## hook will later execute a different REPROBUILD_REPRO/PATH binary.
  let configured = getEnv("REPROBUILD_REPRO")
  if configured.len > 0:
    let candidate =
      if configured.isAbsolute: configured else: repoRoot / configured
    if executableFile(candidate): return candidate
    return ""
  findExe("repro")

proc scrubbedGitChildEnv(capability = ""; internalContext = ""):
    StringTableRef =
  result = scrubbedGitRepositoryEnv()
  result.del(HookCapabilityEnv)
  result.del(LegacyHookSentinelEnv)
  result.del(HookDispatcherProtocolEnv)
  result.del(InternalHookContextEnv)
  if capability.len > 0:
    result[HookCapabilityEnv] = capability
  if internalContext.len > 0:
    result[InternalHookContextEnv] = internalContext

proc gitRunPlainEnv(identity: GitToolIdentity; args: openArray[string];
    capability = ""; internalContext = ""):
    tuple[code: int; output: string] =
  when defined(windows):
    # Keep the capability-bearing push on the same structured Windows process
    # boundary as ``gitRunPlain``. Command-string execution can lose or mangle
    # the second non-fast-forward diagnostic in a retry sequence, causing a
    # verified race to be misclassified as a generic transport failure.
    let process = startProcess(identity.binaryPath, args = @args,
      env = scrubbedGitChildEnv(capability, internalContext),
      options = {poStdErrToStdOut, poUsePath})
    defer: process.close()
    const PollSleepMs = 25
    let outHandle = Handle(process.outputHandle)
    var buf {.noinit.}: array[4096, char]
    while true:
      var bytesAvail: int32 = 0
      let peeked = peekNamedPipe(outHandle,
        lpTotalBytesAvail = addr bytesAvail)
      if peeked and bytesAvail > 0:
        var bytesRead: int32 = 0
        let toRead = min(int(bytesAvail), buf.len).int32
        let ok = readFile(outHandle, addr buf[0], toRead,
          addr bytesRead, nil)
        if ok != 0 and bytesRead > 0:
          let previousLen = result.output.len
          result.output.setLen(previousLen + bytesRead)
          copyMem(addr result.output[previousLen], addr buf[0], bytesRead)
          continue
      result.code = process.peekExitCode()
      if result.code != -1:
        break
      sleep(PollSleepMs)
  else:
    var cmd = quoteShell(identity.binaryPath)
    for arg in args:
      cmd.add(" " & quoteShell(arg))
    let res = execCmdEx(cmd, options = {poStdErrToStdOut, poUsePath},
      env = scrubbedGitChildEnv(capability, internalContext))
    (res.exitCode, res.output)

proc configuredPushLocation(identity: GitToolIdentity; repoRoot,
    remote: string): tuple[ok: bool; value: string; diagnostic: string] =
  let url = gitRunPlain(identity,
    ["-C", repoRoot, "remote", "get-url", "--push", remote])
  if url.code != 0 or url.output.strip().len == 0:
    return (false, "", "configured push location is unavailable for remote " &
      remote)
  # The caller never logs ``value``. It is consumed only in-memory for the
  # credential-free digest inside the typed capability.
  (true, url.output.strip(), "")

proc pushLockRef(identity: GitToolIdentity; repoRoot: string;
    target: LockUpstream; remoteOldOid: string):
    tuple[code: int; output: string] =
  let hook = effectivePrePushHook(identity, repoRoot)
  if hook.kind == ephReproIncompatible:
    return (1, hook.diagnostic & "; run '" & getAppFilename() &
      " hooks ensure --vcs " & repoRoot & "'")
  var capability = ""
  if hook.kind == ephReproV2:
    let location = configuredPushLocation(identity, repoRoot, target.remote)
    if not location.ok: return (1, location.diagnostic)
    let head = gitRunPlain(identity,
      ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
    if head.code != 0: return (1, "cannot observe lock backend HEAD")
    let issued = issueHookCapability(identity.binaryPath, repoRoot,
      target.remote, location.value, "HEAD", head.output.strip(),
      "refs/heads/" & target.branch, remoteOldOid)
    if not issued.ok: return (1, issued.diagnostic)
    capability = issued.token
  try:
    result = gitRunPlainEnv(identity,
      ["-C", repoRoot, "push", target.remote, "HEAD:" & target.branch],
      capability)
  finally:
    # Normal return, Git error, and local exceptions all remove an unclaimed
    # pending record. POSIX issueHookCapability also arms an async-signal-safe
    # unlinkat cleanup for HUP/INT/TERM while this child is outstanding.
    if capability.len > 0:
      discardHookCapability(identity.binaryPath, repoRoot, capability)

proc isFullHexOid(value: string; expectedLength: int): bool =
  if value.len != expectedLength: return false
  for ch in value:
    if ch notin {'0'..'9', 'a'..'f', 'A'..'F'}: return false
  true

proc minimalRoutedRepoName(body: string): string =
  ## Routed participation records are intentionally tiny, but the repository
  ## coordinate still has to be explicit so a valid SHA for repo A cannot be
  ## moved under repo B's lock path. Reject duplicates and non-canonical quoted
  ## scalars rather than guessing through a permissive parser.
  var seen = false
  for raw in body.splitLines():
    let line = raw.strip()
    if not line.startsWith("name"): continue
    let eq = line.find('=')
    if eq <= 0 or line[0 ..< eq].strip() != "name" or seen: return ""
    let value = line[(eq + 1) .. ^1].strip()
    if value.len < 2 or value[0] != '"' or value[^1] != '"': return ""
    let decoded = value[1 ..< value.high]
    # RA-32 — a '/' in the NAME is legitimate (forge-shaped names such as
    # ``stripe/sync-engine``); it is only in the PATH that it must not appear
    # as a separator, and the path component is an encoding of this name, so
    # the binding below (``routedName == <decoded path component>``) stays
    # exact. What must still be refused is anything that is not a NAME:
    # a backslash, an absolute anchor, an empty/'.'/'..' component.
    if not isCanonicalRepoName(decoded): return ""
    result = decoded
    seen = true
  if not seen: result = ""

proc canonicalRepoCoordinate(value: string): bool =
  if value.len == 0 or value.isAbsolute or '\0' in value: return false
  # A manifest-less single-repository workspace uses `.` as its canonical
  # root coordinate. It is not traversal: it names the workspace root itself.
  if value == ".": return true
  let normalized = value.replace('\\', '/')
  if normalized.startsWith("/") or normalized.endsWith("/"): return false
  for part in normalized.split('/'):
    if part.len == 0 or part == "." or part == "..": return false
  true

proc verifyLockRecordPath(identity: GitToolIdentity; repoRoot, commit,
    relPath, objectFormat: string;
    expected = none(ExpectedLockRecord)):
    tuple[ok: bool; diagnostic: string] =
  # RA-32 — one shared decomposer. It carries an ACTIONABLE diagnostic: for the
  # historical too-deep record it names the canonical path the record belongs
  # at, which is what the publish-time migration acts on.
  let parsed = parseLockRecordRelPath(relPath)
  if not parsed.ok:
    return (false, "non-canonical lock record path: " & parsed.diagnostic)
  let oid = parsed.sha
  let oidLength = if objectFormat == "sha256": 64 else: 40
  if not isFullHexOid(oid, oidLength):
    return (false, "lock record filename is not a full " & objectFormat &
      " object id: " & relPath)
  if expected.isSome:
    let wanted = expected.get()
    if relPath != wanted.relPath or parsed.project != wanted.project or
        parsed.repo != wanted.repoName or
        oid.toLowerAscii() != wanted.oid.toLowerAscii():
      return (false, "lock record path does not match the exact operation " &
        "coordinate: " & relPath)
    if not canonicalRepoCoordinate(wanted.repoPath):
      return (false, "operation supplied a non-canonical repository path: " &
        wanted.repoPath)
  let show = gitRunPlain(identity,
    ["-C", repoRoot, "show", commit & ":" & relPath])
  if show.code != 0 or show.output.len == 0:
    return (false, "lock record blob is missing or empty: " & relPath)
  let temp = createTempFile("repro-lock-record-", ".toml")
  let tempPath = temp.path
  try:
    temp.cfile.write(show.output)
    temp.cfile.close()
    var triggerMatches = false
    try:
      let lock = readLock(tempPath)
      if lock.lock.project != parsed.project:
        return (false, "lock project does not match its path: " & relPath)
      for entry in lock.repo:
        let coordinateMatches =
          if expected.isSome:
            entry.name == expected.get().repoName and
              entry.path == expected.get().repoPath and
              entry.revision.toLowerAscii() == expected.get().oid.toLowerAscii()
          else:
            entry.name == parsed.repo and canonicalRepoCoordinate(entry.path) and
              entry.revision.toLowerAscii() == oid.toLowerAscii()
        if coordinateMatches:
          triggerMatches = true
          break
    except CatchableError as workspaceLockError:
      # Explicitly routed git-checkout backends carry the established minimal
      # ``[[repo]] path/revision`` record shape rather than a complete
      # ``reprobuild.workspace.lock.v1`` document. It is still typed by the
      # canonical ``locks/<project>/<repo>/<sha>.toml`` store key. Parse it
      # through the same reader used by routed lock consumers and require one
      # non-empty repo coordinate bound to the exact path SHA.
      let routed = shasFromBody(show.output)
      let routedName = minimalRoutedRepoName(show.output)
      if routed.len != 1 or routedName != parsed.repo:
        return (false, "lock record parse/integrity failure at " & relPath &
          ": " & workspaceLockError.msg)
      for repoPath, revision in routed:
        let coordinateMatches =
          if expected.isSome:
            repoPath == expected.get().repoPath and
              routedName == expected.get().repoName and
              revision.toLowerAscii() == expected.get().oid.toLowerAscii()
          else:
            canonicalRepoCoordinate(repoPath) and
              revision.toLowerAscii() == oid.toLowerAscii()
        if coordinateMatches:
          triggerMatches = true
    if not triggerMatches:
      return (false, "lock trigger identity does not match its path: " & relPath)
  except CatchableError as err:
    return (false, "lock record parse/integrity failure at " & relPath &
      ": " & err.msg)
  finally:
    try: removeFile(tempPath)
    except CatchableError: discard
  (true, "")

proc expectedLockRecordFromBody(relPath, body: string):
    Option[ExpectedLockRecord] =
  ## Compatibility seam for explicit `repro workspace lock` and the exported
  ## low-level publisher. Normal pre-push/repro-push paths carry the expected
  ## coordinate from the resolved manifest instead of deriving it here.
  # RA-32 — same shared decomposer as ``verifyLockRecordPath``.
  let parsed = parseLockRecordRelPath(relPath)
  if not parsed.ok:
    return none(ExpectedLockRecord)
  let oid = parsed.sha
  var repoPath = ""
  let temp = createTempFile("repro-lock-expected-", ".toml")
  let tempPath = temp.path
  try:
    temp.cfile.write(body)
    temp.cfile.close()
    try:
      let lock = readLock(tempPath)
      if lock.lock.project != parsed.project: return none(ExpectedLockRecord)
      for entry in lock.repo:
        if entry.name == parsed.repo and
            entry.revision.toLowerAscii() == oid.toLowerAscii():
          repoPath = entry.path
          break
    except CatchableError:
      let routed = shasFromBody(body)
      if routed.len == 1 and minimalRoutedRepoName(body) == parsed.repo:
        for path, revision in routed:
          if revision.toLowerAscii() == oid.toLowerAscii(): repoPath = path
  finally:
    try: removeFile(tempPath)
    except CatchableError: discard
  if not canonicalRepoCoordinate(repoPath): return none(ExpectedLockRecord)
  some(ExpectedLockRecord(project: parsed.project, repoName: parsed.repo,
    repoPath: repoPath, oid: oid, relPath: parsed.relPath))

proc verifyLockBlobAt(identity: GitToolIdentity; repoRoot, commit,
    relPath: string): tuple[ok: bool; diagnostic: string] =
  let tree = gitRunPlain(identity,
    ["-C", repoRoot, "ls-tree", commit, "--", relPath])
  if tree.code != 0 or tree.output.strip().len == 0:
    return (false, "expected lock record is not reachable at " & commit &
      ": " & relPath)
  let fields = tree.output.strip().splitWhitespace()
  if fields.len < 3 or fields[0] != "100644" or fields[1] != "blob":
    return (false, "expected lock record has an unsafe Git mode/type: " &
      relPath)
  (true, "")

proc verifyExpectedRecordCoordinatesAt(identity: GitToolIdentity;
    repoRoot, commit: string;
    expected: openArray[ExpectedLockRecord]):
    tuple[ok: bool; diagnostic: string] =
  if expected.len == 0:
    return (false, "no expected lock records were available to verify")
  for item in expected:
    let path = item.relPath
    let blob = verifyLockBlobAt(identity, repoRoot, commit, path)
    if not blob.ok: return blob
    let format = storageObjectFormat(identity.binaryPath, repoRoot)
    if format.len == 0:
      return (false, "cannot determine backend Git object format")
    let record = verifyLockRecordPath(identity, repoRoot, commit, path, format,
      some(item))
    if not record.ok: return record
  (true, "")

proc verifyExpectedLocksAt(identity: GitToolIdentity; repoRoot, commit: string;
    expected: openArray[ExpectedLockRecord]):
    tuple[ok: bool; diagnostic: string] =
  let coordinates = verifyExpectedRecordCoordinatesAt(identity, repoRoot,
    commit, expected)
  if not coordinates.ok: return coordinates
  for item in expected:
    let path = item.relPath
    let localTree = gitRunPlain(identity,
      ["-C", repoRoot, "ls-tree", "HEAD", "--", path])
    let remoteTree = gitRunPlain(identity,
      ["-C", repoRoot, "ls-tree", commit, "--", path])
    if localTree.code != 0 or remoteTree.code != 0 or
        localTree.output.strip().len == 0 or
        remoteTree.output.strip().len == 0:
      return (false, "could not compare expected lock blob at " & path)
    let localFields = localTree.output.strip().splitWhitespace()
    let remoteFields = remoteTree.output.strip().splitWhitespace()
    if localFields.len < 3 or remoteFields.len < 3 or
        localFields[2] != remoteFields[2]:
      return (false, "upstream lock blob differs from local expected record: " &
        path)
  (true, "")

proc verifyLockOnlyAheadChain(identity: GitToolIdentity; repoRoot, base,
    head: string; expected: openArray[ExpectedLockRecord];
    requireAllExpected = true; rejectUnexpected = false;
    restrictToExpectedCoordinates = false):
    tuple[ok: bool; diagnostic: string] =
  let format = storageObjectFormat(identity.binaryPath, repoRoot)
  if format.len == 0:
    return (false, "cannot determine backend Git object format")
  let ancestry = gitRunPlain(identity,
    ["-C", repoRoot, "merge-base", "--is-ancestor", base, head])
  if ancestry.code != 0:
    return (false, "local backend HEAD is not a fast-forward of fetched upstream")
  let commitsRes = gitRunPlain(identity,
    ["-C", repoRoot, "rev-list", "--reverse", base & ".." & head])
  if commitsRes.code != 0:
    return (false, "could not enumerate local backend ahead commits")
  let commits = commitsRes.output.splitLines().filterIt(it.strip().len > 0)
  if commits.len == 0:
    return (false, "backend is not ahead of the fetched upstream")

  # RA-32 — the ahead chain is ADDITIONS-ONLY, with NO exception.
  #
  # Every commit between the fetched upstream and the local backend HEAD must
  # consist solely of ``A`` entries under ``locks/``, and every added path must
  # be a canonical lock record that verifies against the operation binding.
  # Nothing is ever removed from the chain, at any depth, for any reason: a
  # published record is immutable, and a record that is NOT canonical is not
  # something this verifier may make publishable by rewriting a shared store on
  # the operator's behalf.
  #
  # An earlier revision carved out a "migration" exception here — a commit that
  # deleted one non-canonical record and re-added it at its canonical path —
  # and drove it automatically from ``publishWorkspaceLock``. Every defect two
  # review rounds found came from that machinery, never from the encoding or
  # the shared parser: it committed deletions the verifier then refused
  # forever, mis-parsed quoted paths AFTER moving the files, dropped a path
  # silently, relocated files that were never records, and authorized its own
  # writes to a shared remote past the very guard that exists to stop that. It
  # is gone. A store that already holds a non-canonical record is repaired by
  # the EXPLICIT ``repro workspace migrate-locks`` verb, which rebuilds the
  # UNPUBLISHED portion of the branch so that what reaches this verifier is,
  # once again, additions-only.
  var added: HashSet[string]
  for rawCommit in commits:
    let commit = rawCommit.strip()
    let diff = gitRunPlain(identity,
      ["-C", repoRoot, "diff-tree", "--no-commit-id", "--name-status",
       "-r", "--no-renames", commit & "^", commit])
    if diff.code != 0:
      return (false, "could not inspect backend ahead commit " & commit)
    var touched = 0
    for rawLine in diff.output.splitLines():
      if rawLine.len == 0: continue
      let fields = rawLine.split('\t')
      if fields.len != 2 or fields[0] != "A":
        return (false, "backend ahead chain is not additions-only at " &
          commit & ": " & rawLine)
      let path = fields[1]
      if not pathIsUnderLocks(path):
        return (false, "backend ahead chain touches outside locks/: " & path)
      var exact = none(ExpectedLockRecord)
      for item in expected:
        if item.relPath == path:
          exact = some(item)
          break
      if rejectUnexpected and exact.isNone:
        return (false, "backend ahead chain contains an unexpected lock " &
          "record: " & path)
      if exact.isNone and restrictToExpectedCoordinates:
        let parsed = parseLockRecordRelPath(path)
        if parsed.ok:
          for item in expected:
            if item.project == parsed.project and item.repoName == parsed.repo:
              exact = some(ExpectedLockRecord(project: item.project,
                repoName: item.repoName, repoPath: item.repoPath,
                oid: parsed.sha, relPath: path))
              break
        if exact.isNone:
          return (false, "backend ahead chain contains a lock record outside " &
            "the expected repository coordinates: " & path)
      let record = verifyLockRecordPath(identity, repoRoot, commit, path,
        format, exact)
      if not record.ok: return record
      let blob = verifyLockBlobAt(identity, repoRoot, commit, path)
      if not blob.ok: return blob
      added.incl(path)
      inc touched
    if touched == 0:
      return (false, "backend ahead commit contains no lock additions: " & commit)
  if requireAllExpected:
    for item in expected:
      let path = item.relPath
      if path notin added:
        # Expected records may predate this ahead chain, but they still must be
        # present in HEAD. Reachability, not re-addition, is the invariant.
        let blob = verifyLockBlobAt(identity, repoRoot, head, path)
        if not blob.ok: return blob
  (true, "")

proc rebaseVerifiedLockChain(identity: GitToolIdentity; repoRoot, oldBase,
    newBase: string; expected: openArray[ExpectedLockRecord]):
    tuple[ok: bool; diagnostic: string] =
  let branch = gitRunPlain(identity,
    ["-C", repoRoot, "symbolic-ref", "-q", "HEAD"])
  if branch.code != 0 or not branch.output.strip().startsWith("refs/heads/"):
    return (false, "lock backend must remain on a named branch for rebase")
  let branchRef = branch.output.strip()
  let upstream = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--symbolic-full-name", "@{u}"])
  if upstream.code != 0 or upstream.output.strip().len == 0:
    return (false, "cannot preserve lock backend upstream during rebase")
  let upstreamRef = upstream.output.strip()
  let head = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--verify", "HEAD^{commit}"])
  if head.code != 0: return (false, "cannot observe backend HEAD before rebase")
  let expectedOldHead = head.output.strip().toLowerAscii()
  let verified = verifyLockOnlyAheadChain(identity, repoRoot, oldBase,
    expectedOldHead, expected)
  if not verified.ok: return verified
  let unchanged = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--verify", "HEAD^{commit}"])
  if unchanged.code != 0 or
      unchanged.output.strip().toLowerAscii() != expectedOldHead:
    return (false, "lock backend HEAD changed after verification; refusing rebase")
  let rebase = gitRunPlain(identity,
    ["-C", repoRoot, "rebase", "--onto", newBase, oldBase])
  if rebase.code != 0:
    discard gitRunPlain(identity, ["-C", repoRoot, "rebase", "--abort"])
    return (false, "verified lock-only rebase failed: " & rebase.output.strip())
  let branchAfter = gitRunPlain(identity,
    ["-C", repoRoot, "symbolic-ref", "-q", "HEAD"])
  let upstreamAfter = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "--symbolic-full-name", "@{u}"])
  if branchAfter.code != 0 or branchAfter.output.strip() != branchRef or
      upstreamAfter.code != 0 or upstreamAfter.output.strip() != upstreamRef:
    return (false, "verified rebase did not preserve branch/upstream identity")
  let newHead = gitRunPlain(identity, ["-C", repoRoot, "rev-parse", "HEAD"])
  if newHead.code != 0: return (false, "cannot observe backend HEAD after rebase")
  verifyLockOnlyAheadChain(identity, repoRoot, newBase,
    newHead.output.strip(), expected)

proc publishVerifiedLockState(identity: GitToolIdentity; repoRoot: string;
    target: LockUpstream;
    expected: openArray[ExpectedLockRecord]): LockPublishResult =
  ## Complete or resume a lock publication from observed Git state. Success is
  ## reported only after re-fetching the exact upstream ref and proving both
  ## local-HEAD reachability and every expected lock blob at the immutable tip.
  result.outcome = lpoFailed
  for entry in gitPorcelainEntries(identity, repoRoot):
    # Recovery starts only from an exact clean index/worktree. A pathname being
    # under locks/ is not sufficient: modified, deleted, renamed, symlinked
    # lock files are user state and must never be swept into a resumed
    # publication.
    #
    # RA-32 — with ONE exception, and it is an exception about what this code
    # can reach, not about what it trusts. An UNTRACKED file under ``locks/``
    # that is not a canonical record path can no longer be swept into anything:
    # every writer here stages by explicit path (``putLock`` stages its one
    # record, ``publishWorkspaceLock`` stages the canonical paths it selected)
    # and commits with that same explicit pathspec, so such a file is
    # unreachable from the index and from every commit. Aborting over it gave
    # one unrelated file — an operator's ``NOTES.toml``, or a record some older
    # writer left at a non-canonical path and never tracked — a veto over
    # publication for every repo in the workspace. A canonical untracked record
    # is NOT excused: the publisher stages those, so by the time control
    # reaches here one can only mean the staging step disagreed with this one,
    # which is exactly the kind of split this change exists to remove.
    if entry.code == "??" and pathIsUnderLocks(entry.path) and
        not parseLockRecordRelPath(entry.path).ok:
      continue
    result.diagnostic = "backend has uncommitted state (" & entry.code & " " &
      entry.path & "); refusing verified lock recovery"
    return
  let localHeadBefore = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
  if localHeadBefore.code != 0:
    result.diagnostic = "cannot observe local backend HEAD"
    return
  let localFormat = storageObjectFormat(identity.binaryPath, repoRoot)
  if localFormat.len == 0:
    result.diagnostic = "cannot determine backend Git object format"
    return
  for item in expected:
    let path = item.relPath
    let blob = verifyLockBlobAt(identity, repoRoot,
      localHeadBefore.output.strip(), path)
    if not blob.ok:
      result.diagnostic = blob.diagnostic
      return
    let record = verifyLockRecordPath(identity, repoRoot,
      localHeadBefore.output.strip(), path, localFormat, some(item))
    if not record.ok:
      result.diagnostic = record.diagnostic
      return
  var fetched = fetchImmutableLockTip(identity, repoRoot, target)
  if not fetched.ok:
    result.diagnostic = fetched.diagnostic
    return
  var base = fetched.oid
  let initialHeadRes = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
  if initialHeadRes.code != 0:
    result.diagnostic = "cannot observe local backend HEAD"
    return
  let initialHead = initialHeadRes.output.strip().toLowerAscii()
  var operationExpected = @expected
  if gitRunPlain(identity,
      ["-C", repoRoot, "merge-base", "--is-ancestor", initialHead,
       base]).code == 0:
    if operationExpected.len > 0:
      let remoteProof = verifyExpectedLocksAt(identity, repoRoot, base,
        operationExpected)
      if not remoteProof.ok:
        result.diagnostic = remoteProof.diagnostic
        return
    result.outcome = lpoNothingToPublish
    result.diagnostic =
      if operationExpected.len > 0:
        "expected lock records are already reachable from " & target.display
      else:
        "backend HEAD is already reachable from " & target.display
    return

  # An empty operation binding is sufficient to prove an idle/behind backend
  # is a no-op, but it can never authorize publishing an ahead chain. Without
  # exact records there is no operation-scoped identity proof for those local
  # commits, even when their paths happen to look lock-shaped.
  if operationExpected.len == 0:
    result.diagnostic = "no exact operation lock records were supplied"
    return

  var verified = verifyLockOnlyAheadChain(identity, repoRoot, base,
    initialHead, operationExpected)
  if not verified.ok:
    # Recovery begins from one immutable fetch. If local and remote history
    # were already divergent at that point, this invocation did not observe a
    # push race and must not mutate either branch. Bounded rebase is permitted
    # only after our own later push returns a non-fast-forward rejection.
    result.diagnostic = "unverified local backend state: " & verified.diagnostic
    return
  let verifiedHead = gitRunPlain(identity,
    ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
  if verifiedHead.code == 0:
    result.verifiedLocalHead = verifiedHead.output.strip().toLowerAscii()

  var attempt = 0
  while true:
    # A fresh one-use capability is minted for each exact Git child. Rebase
    # retries change HEAD, so the next loop iteration necessarily receives a
    # new binding; a previous token is never reused.
    let pushRes = pushLockRef(identity, repoRoot, target, base)
    if pushRes.code == 0:
      let completed = fetchImmutableLockTip(identity, repoRoot, target)
      if not completed.ok:
        result.diagnostic = "push completed but remote verification failed: " &
          completed.diagnostic
        return
      let currentHead = gitRunPlain(identity,
        ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
      if currentHead.code != 0 or gitRunPlain(identity,
          ["-C", repoRoot, "merge-base", "--is-ancestor",
           currentHead.output.strip(), completed.oid]).code != 0:
        result.diagnostic = "push completed but local backend HEAD is not " &
          "reachable from the fetched upstream tip"
        return
      let remoteProof = verifyExpectedLocksAt(identity, repoRoot,
        completed.oid, operationExpected)
      if not remoteProof.ok:
        result.diagnostic = "push completed but " & remoteProof.diagnostic
        return
      result.outcome = lpoPublished
      result.verifiedLocalHead = ""
      result.diagnostic = "published verified lock records to " &
          target.display &
        (if attempt > 0: " after " & $attempt & " race rebase attempt" &
          (if attempt == 1: "" else: "s") else: "")
      return

    if not pushOutputIsNonFastForward(pushRes.output):
      # Leave the verified local lock-only ahead chain intact. A normal retry
      # will re-enter this state machine and resume it.
      result.diagnostic = "git push " & target.remote & " HEAD:" &
        target.branch & " failed; verified local lock-only commit retained; " &
        "check backend connectivity, credentials, and branch policy"
      return
    inc attempt
    if attempt > lockPublishNonFfRetryBudget:
      result.diagnostic = "git push " & target.remote & " HEAD:" &
        target.branch & " kept racing after " &
        $lockPublishNonFfRetryBudget & " verified rebase attempts"
      return
    let advanced = fetchImmutableLockTip(identity, repoRoot, target)
    if not advanced.ok:
      result.diagnostic = "non-fast-forward recovery fetch failed: " &
        advanced.diagnostic
      return
    if gitRunPlain(identity,
        ["-C", repoRoot, "merge-base", "--is-ancestor", base,
         advanced.oid]).code != 0:
      result.diagnostic = "remote moved non-fast-forward during lock publication"
      return
    let rebased = rebaseVerifiedLockChain(identity, repoRoot, base,
      advanced.oid, operationExpected)
    if not rebased.ok:
      result.diagnostic = "non-fast-forward recovery refused: " &
        rebased.diagnostic
      return
    base = advanced.oid
    let refreshedHead = gitRunPlain(identity,
      ["-C", repoRoot, "rev-parse", "HEAD^{commit}"])
    if refreshedHead.code != 0:
      result.diagnostic = "cannot observe backend HEAD after verified rebase"
      return
    result.verifiedLocalHead = refreshedHead.output.strip().toLowerAscii()

proc nulSeparatedPaths(output: string): seq[string] =
  ## Split the output of a ``-z`` git query into paths.
  ##
  ## ``-z`` NUL-TERMINATES each path, and the captured output still carries the
  ## trailing newline the child wrote after the last record. Splitting on NUL
  ## therefore yields a final element that is ``"\n"`` rather than ``""``, and a
  ## plain ``if raw.len == 0: continue`` does not drop it. That element then
  ## flows on as if it were a path: it is not under ``locks/``, so the repair
  ## planner read it as "this branch touches something outside locks/" and
  ## refused every store it was pointed at, naming a path that renders as
  ## nothing at all.
  ##
  ## Strip the trailing newlines ONCE, from the whole output, before splitting;
  ## every element is then either a real path or empty. Not a per-element
  ## ``strip``: a path may legitimately begin or end with a byte ``strip``
  ## would eat.
  for raw in output.strip(leading = false, chars = {'\n', '\r'}).split('\0'):
    if raw.len == 0: continue
    result.add(raw.replace('\\', '/'))

proc publishWorkspaceLock*(identity: GitToolIdentity;
                           manifestRepoRoot: string;
                           exactExpected: seq[ExpectedLockRecord] = @[]):
                           LockPublishResult =
  ## RA-7. Commit the staged-under-``locks/`` subtree and push it to the
  ## manifest repo's upstream. Best-effort: never raises. See the block
  ## comment above for the full contract.
  result.outcome = lpoFailed

  let worktree = discoverGitWorktree(identity, manifestRepoRoot)
  if not worktree.ok:
    # The manifest layer is a plain directory, not a publishable git
    # checkout — this workspace simply has no manifest remote to publish
    # to. That is a benign skip, not a publish-attempt failure (RA-21).
    #
    # Carry the discovery diagnostic: it distinguishes "no repository here at
    # all" from the far more confusing "a plain directory nested inside
    # someone else's checkout", which is what the default
    # ``<workspace>/.repro/manifests`` layer looks like in the native layout.
    result.outcome = lpoNotPublishable
    result.diagnostic =
      "manifest repo root '" & manifestRepoRoot &
        "' is not a git checkout; cannot publish lock (" &
        worktree.diagnostic & ")"
    return

  # ...and being INSIDE someone else's checkout is not the same as BEING one.
  # The default store path (`<workspace>/.repro/manifests`) sits inside the
  # workspace's own repo, so `rev-parse` answers for that enclosing repo and
  # the check above passes for a directory that is merely a local-state dir —
  # one the enclosing repo typically gitignores (`.repro/`), which makes the
  # subsequent `git add locks` fail and turns a workspace with NO lock store
  # into one that cannot push at all. A store DB is its own checkout by
  # construction (that is what makes it publishable to a remote), so require
  # the path to be the worktree ROOT and otherwise take the same benign
  # not-publishable skip.
  if not samePathIdentity(worktree.worktreeRoot, manifestRepoRoot):
    result.outcome = lpoNotPublishable
    result.diagnostic =
      "manifest repo root '" & manifestRepoRoot &
        "' is not its own git checkout (it lives inside '" &
        worktree.worktreeRoot &
        "'); no lock store is configured for this workspace, so there is " &
        "nothing to publish to"
    return

  # RA-32 — the publish OWNS exactly one kind of path: a CANONICAL lock record
  # under ``locks/``. It stages those, commits those, and pushes those. Every
  # other file under ``locks/`` — an operator's ``README.md``, the store's
  # legacy ``.xml`` records, a ``NOTES.toml``, or a record some earlier writer
  # left at a non-canonical path — it does not stage, does not commit, and
  # does not refuse over.
  #
  # This replaced a blanket ``git add -f -- locks``. That staged the WHOLE
  # subtree, so a single unrelated file sitting under ``locks/`` became a
  # staged addition the canonical-additions check then refused, denying
  # publication to every repo in the workspace. Selecting the paths makes the
  # isolation real rather than incidental: an unrelated file is never in the
  # index, so it cannot be in the commit, so it cannot be in the ahead chain.
  #
  # ``-f`` (force) because the operator is entitled to keep the whole manifest
  # layer out of ordinary status/add noise — a global ``core.excludesFile`` or
  # a repo ``.gitignore`` naming e.g. ``.repro/`` or ``locks/`` is a legitimate
  # configuration, and lock publication must still work under it. These paths
  # are generated and owned by reprobuild, and the pathspec is now pinned to
  # individual canonical record paths, so the force can only ever stage this
  # tool's own records. This is safe ONLY because the guard above proved
  # ``manifestRepoRoot`` is the checkout ROOT: without it, Git's upward
  # repository discovery would point these commands at an enclosing repository
  # and the force would commit the lock into — and push the branch of — a repo
  # that merely happens to contain the manifest layer.
  #
  # ``-z`` on every enumeration: ``core.quotePath`` C-quotes any path carrying
  # a byte outside ASCII, and a quoted path does not compare equal to what the
  # writer wrote. The encoder's own output alphabet is ``[A-Za-z0-9._%-]`` so a
  # canonical record is never quoted, but a legacy or operator file may be, and
  # it must be recognised as "not ours" rather than mis-parsed.
  var canonicalToStage: seq[string]
  var strayRecords: seq[string]
  var vanishedRecords: seq[string]
  if dirExists(extendedPath(manifestRepoRoot / "locks")):
    # Candidates for staging: untracked (``--others``, deliberately WITHOUT
    # ``--exclude-standard`` so an ignored manifest layer still publishes) and
    # tracked-but-changed (``--modified``, which also reports a tracked file
    # deleted from the worktree).
    let cand = gitRunPlain(identity,
      ["-C", manifestRepoRoot, "ls-files", "-z", "--modified", "--others",
       "--", "locks"])
    if cand.code != 0:
      result.diagnostic = "git ls-files locks failed: " & cand.output.strip()
      return
    var seenCandidate = initHashSet[string]()
    for rel in nulSeparatedPaths(cand.output):
      if rel in seenCandidate: continue
      seenCandidate.incl(rel)
      if not parseLockRecordRelPath(rel).ok:
        if rel.endsWith(lockRecordExt): strayRecords.add(rel)
        continue
      if fileExists(extendedPath(manifestRepoRoot / rel.replace('/', DirSep))):
        canonicalToStage.add(rel)
      else:
        vanishedRecords.add(rel)
    canonicalToStage.sort()
    vanishedRecords.sort()

    # A record-shaped file already TRACKED at a non-canonical path is the state
    # an operator most needs told about: it is committed, so it sits in the
    # ahead chain and the additions-only verifier will refuse the chain until
    # it is repaired. It never shows up in the candidate scan above (it is
    # tracked and unmodified), so scan the index for it too.
    let trackedRes = gitRunPlain(identity,
      ["-C", manifestRepoRoot, "ls-files", "-z", "--cached", "--", "locks"])
    if trackedRes.code == 0:
      for rel in nulSeparatedPaths(trackedRes.output):
        if not rel.endsWith(lockRecordExt): continue
        if parseLockRecordRelPath(rel).ok: continue
        if rel in seenCandidate: continue
        strayRecords.add(rel)
    strayRecords.sort()

  # Unstage exactly what we staged, and NOTHING when we staged nothing.
  # ``git reset HEAD --`` with an EMPTY pathspec is not a no-op: git treats it
  # as "no pathspec" and performs a full mixed reset, which would silently
  # unstage whatever the operator had staged themselves. The guard is the
  # whole point of routing every unstage through here.
  proc unstageOurs() =
    if canonicalToStage.len == 0: return
    discard gitRunPlain(identity,
      @["-C", manifestRepoRoot, "reset", "--quiet", "HEAD", "--"] &
        canonicalToStage)

  # REPORT, never relocate. Naming the file, the reason, and the exact repair
  # verb is the whole remedy this offers: nothing here mutates a shared store,
  # and nothing here denies publication to the canonical records below.
  for stray in strayRecords:
    let parsedStray = parseLockRecordRelPath(stray)
    stderr.writeLine("repro: not publishing '" & stray & "': " &
      parsedStray.diagnostic)
    # Name the STORE. ``migrate-locks`` defaults to ``<cwd>/.repro/manifests``,
    # and a routed team/personal backend is somewhere else entirely — a bare
    # invocation would then plan a repair of the wrong store (or none) and
    # report "nothing to do" about a store that is still wedged.
    stderr.writeLine("repro:   repair it with 'repro workspace migrate-locks " &
      "--dry-run --manifest-layer-root=" & manifestRepoRoot &
      "' (then '--apply'); publication of the other records in " &
      "this store is unaffected")

  if canonicalToStage.len > 0:
    let addRes = gitRunPlain(identity,
      @["-C", manifestRepoRoot, "add", "-f", "--"] & canonicalToStage)
    if addRes.code != 0:
      result.diagnostic = "git add locks failed: " & addRes.output.strip()
      return

  # Dirty-outside-``locks/`` guard. We scan the FULL working-tree+index
  # status; any tracked-or-untracked change whose path is not under
  # ``locks/`` means the publish commit would either sweep up unrelated
  # work (staged) or run against an inconsistent tree. Refuse, and unstage
  # what we just staged so the operator's index is left untouched.
  var dirtyOutside: seq[string]
  for entry in gitPorcelainEntries(identity, manifestRepoRoot):
    if not pathIsUnderLocks(entry.path):
      dirtyOutside.add(entry.path)
  if dirtyOutside.len > 0:
    # Reset only the locks subtree we staged; leave any pre-existing
    # staging of unrelated paths exactly as we found it.
    unstageOurs()
    result.outcome = lpoRefusedDirty
    result.diagnostic =
      "manifest repo is dirty outside locks/ (" &
        dirtyOutside.join(", ") & "); refusing to publish lock"
    return

  # A canonical record that is tracked but GONE from the worktree. Lock records
  # are immutable, so this is never something to publish past: say so, and name
  # the restore. Refusing here is not "blocking an unrelated record" — the
  # missing file IS a published record of this store. Ordered AFTER the
  # dirty-outside guard so that guard keeps its precedence: a tree that is
  # inconsistent outside locks/ is the more fundamental refusal, and it is the
  # one whose outcome (``lpoRefusedDirty``) callers already act on.
  if vanishedRecords.len > 0:
    unstageOurs()
    result.outcome = lpoFailed
    result.diagnostic =
      "lock record(s) missing from the manifest working tree (" &
        vanishedRecords.join(", ") &
        "); lock records are immutable — restore them with 'git -C " &
        manifestRepoRoot & " checkout -- locks' and re-run"
    return

  # Collect the staged lock paths and reject empty/zero-byte locks.
  # Pathspec = exactly what we staged. Anything else the operator may have
  # staged under ``locks/`` is not this publish's business and must not be
  # able to fail it.
  let stagedRes =
    if canonicalToStage.len == 0:
      (code: 0, output: "")
    else:
      gitRunPlain(identity,
        @["-C", manifestRepoRoot, "diff", "--cached", "--name-status",
          "--no-renames", "--"] & canonicalToStage)
  var stagedLocks: seq[string]
  if stagedRes.code == 0:
    for line in stagedRes.output.splitLines():
      if line.len == 0: continue
      let fields = line.split('\t')
      if fields.len != 2 or fields[0] != "A":
        unstageOurs()
        result.diagnostic = "lock publication accepts canonical additions only: " &
          line
        return
      let p = fields[1]
      # RA-32 — the same shared decomposer the writer and the ahead-chain
      # verifier use. Its diagnostic names the canonical path, so an operator
      # who somehow still lands here is told what to do rather than just that
      # something is "non-canonical".
      let parsedStaged = parseLockRecordRelPath(p)
      if not parsedStaged.ok:
        unstageOurs()
        result.diagnostic = "non-canonical generated lock addition: " &
          parsedStaged.diagnostic
        return
      let stage = gitRunPlain(identity,
        ["-C", manifestRepoRoot, "ls-files", "--stage", "--", p])
      let stageFields = stage.output.strip().splitWhitespace()
      if stage.code != 0 or stageFields.len < 4 or stageFields[0] != "100644":
        unstageOurs()
        result.diagnostic = "generated lock addition has unsafe mode/type: " & p
        return
      stagedLocks.add(p)

  for rel in stagedLocks:
    let abs = manifestRepoRoot / rel.replace('/', DirSep)
    if fileExists(abs) and getFileSize(abs) == 0:
      # Unstage the locks subtree; an empty lock must never be committed.
      unstageOurs()
      result.outcome = lpoFailed
      result.diagnostic =
        "refusing to publish empty/zero-byte lock file: " & rel
      return

  let upstream = resolveLockUpstream(identity, manifestRepoRoot)
  if not upstream.ok:
    unstageOurs()
    result.outcome =
      if "no upstream" in upstream.diagnostic: lpoNotPublishable
      else: lpoFailed
    result.diagnostic = upstream.diagnostic
    return

  if stagedLocks.len > 0:
    let plural = if stagedLocks.len == 1: "entry" else: "entries"
    let message = "Publish " & $stagedLocks.len & " workspace lock " & plural
    let commitRes = gitRunPlainEnv(identity,
      @["-C", manifestRepoRoot, "commit", "--quiet", "-m", message, "--"] &
        stagedLocks, internalContext = InternalLockCommitContext)
    if commitRes.code != 0:
      result.outcome = lpoFailed
      result.diagnostic = "git commit failed: " & commitRes.output.strip()
      return

  var expected = exactExpected
  for rel in stagedLocks:
    var alreadyBound = false
    for item in expected:
      if item.relPath == rel:
        alreadyBound = true
        break
    if alreadyBound: continue
    let abs = manifestRepoRoot / rel.replace('/', DirSep)
    if not fileExists(abs):
      result.diagnostic = "staged lock disappeared before publication: " & rel
      return
    let inferred = expectedLockRecordFromBody(rel, readFile(abs))
    if inferred.isNone:
      result.diagnostic = "cannot bind staged lock to an exact repository " &
        "coordinate: " & rel
      return
    expected.add(inferred.get())

  result = publishVerifiedLockState(identity, manifestRepoRoot,
    upstream.target, expected)

  # RA-32 — the one case where a refusal genuinely does hold up unrelated
  # records: a non-canonical record that is already COMMITTED sits in the ahead
  # chain, and a branch push moves a ref, so there is no way to publish the
  # healthy commits and leave that one behind. The chain verifier names the
  # record; attach the repair so an operator is never left with a refusal and
  # no route forward. Appended rather than substituted — the verifier's own
  # diagnostic is the precise reason, and this is the remedy for it.
  if result.outcome notin {lpoPublished, lpoNothingToPublish} and
      strayRecords.len > 0:
    result.diagnostic = result.diagnostic & " — this store also holds " &
      $strayRecords.len & " lock record(s) at a non-canonical path (" &
      strayRecords[0] & (if strayRecords.len > 1: ", ..." else: "") &
      "); repair with 'repro workspace migrate-locks --dry-run " &
      "--manifest-layer-root=" & manifestRepoRoot & "', then '--apply'"

# ---------------------------------------------------------------------------
# RA-32 — `repro workspace migrate-locks`: the EXPLICIT lock-record repair.
#
# A manifest store can hold a lock record at a non-canonical path, because an
# earlier `GitCheckoutLockStore.putLock` joined the store key straight into the
# path: a repo whose NAME carries a slash (`stripe/sync-engine`, and eleven
# more in this workspace, because upstream forks are named the way the forge
# names them) became TWO path components, so the record landed at depth 5 where
# the format has 4. `putLock` COMMITS as it writes, so the record is already in
# the local branch, and the publisher — which requires every record in the
# ahead chain to be canonical — refuses that chain from then on.
#
# This verb is that store's repair, and it is the ONLY one. It is never invoked
# implicitly: not by `repro push`, not by the pre-push gate, not by
# `publishWorkspaceLock`. An earlier revision did run a repair automatically
# inside the push path, and it was withdrawn: machinery that mutates a shared
# store, authorizes its own writes to a remote, and runs unbidden is the wrong
# shape for a repair, however correct its individual steps.
#
# ## What the repair actually is
#
# NOT "relocate the record and commit the move". A commit that DELETES a path
# is not publishable — the ahead chain is additions-only with no exception —
# so a move-on-top would swap one permanent wedge for another.
#
# The repair is instead a rebuild of the UNPUBLISHED portion of the branch. It
# is sound precisely because a non-canonical record is unpublishable BY
# CONSTRUCTION: the publisher refused it, so it never reached the remote. The
# verb resets the branch to the fetched upstream, moves each record to its
# canonical path on disk, and re-commits every ahead record as a single
# ADDITIONS-ONLY commit. Nothing published is rewritten; nothing shared is
# touched. What the publisher then sees is a chain it accepts.
#
# ## Plan before move
#
# Every predicate the publisher will apply is checked BEFORE the first
# `moveFile`, and the verb refuses AS A WHOLE rather than committing a move it
# cannot publish:
#
#   * the record is absent from the fetched upstream (it was never published);
#   * a canonical target is derivable, and is itself canonical;
#   * the target stem is a FULL hex object id of the repo's object format —
#     the publisher's `verifyLockRecordPath` demands it, and a record whose
#     stem is not one could be moved and then refused forever;
#   * the body binds to an exact repository coordinate
#     (`expectedLockRecordFromBody`), which is what authorizes its publication;
#   * the body's own repo name agrees with the target path's;
#   * the target does not already hold a DIFFERENT body;
#   * no two records claim one target (the canonical path is derived by
#     DECODING, so `locks/proj/...` and `locks/%70roj/...` share one) — an
#     N-into-1 collapse would silently lose N-1 records;
#   * every ahead commit touches `locks/` only, and deletes nothing, so the
#     rebuild cannot drop anything the plan did not name.
#
# If any one of these fails, NOTHING moves.
# ---------------------------------------------------------------------------

type
  LockMigrationStep* = object
    ## One record's relocation: `old` -> `target`, both store-relative.
    oldPath*: string
    target*: string

  LockMigrationPlan* = object
    ok*: bool
    diagnostic*: string
    steps*: seq[LockMigrationStep]
      ## Records to relocate.
    carried*: seq[string]
      ## Canonical records already ahead of upstream. They are re-added
      ## unchanged by the rebuild; naming them is what makes "the rebuild
      ## loses nothing" checkable rather than asserted.
    orphans*: seq[string]
      ## Tracked ahead-only paths under `locks/` that are NOT canonical
      ## records and are not relocatable. The rebuild leaves them on disk as
      ## untracked files; they were never published, so nothing is lost, but
      ## the operator is told.
    baseOid*: string
    upstreamDisplay*: string

proc lockMigrationNothingToDo*(plan: LockMigrationPlan): bool =
  plan.ok and plan.steps.len == 0

proc planLockRecordMigration*(identity: GitToolIdentity;
    manifestRepoRoot: string): LockMigrationPlan =
  ## Plan the repair without touching anything. Read-only: every git command
  ## below is a query, except the `fetch` that establishes what "published"
  ## means, which writes only a remote-tracking ref.
  result.ok = false

  let worktree = discoverGitWorktree(identity, manifestRepoRoot)
  if not worktree.ok:
    result.diagnostic = "manifest repo root '" & manifestRepoRoot &
      "' is not a git checkout (" & worktree.diagnostic & ")"
    return
  if not samePathIdentity(worktree.worktreeRoot, manifestRepoRoot):
    result.diagnostic = "manifest repo root '" & manifestRepoRoot &
      "' is not its own git checkout (it lives inside '" &
      worktree.worktreeRoot & "'); there is no lock store here to repair"
    return

  let upstream = resolveLockUpstream(identity, manifestRepoRoot)
  if not upstream.ok:
    result.diagnostic = upstream.diagnostic
    return
  result.upstreamDisplay = upstream.target.display

  let tip = fetchImmutableLockTip(identity, manifestRepoRoot, upstream.target)
  if not tip.ok:
    result.diagnostic = tip.diagnostic
    return
  result.baseOid = tip.oid

  let format = storageObjectFormat(identity.binaryPath, manifestRepoRoot)
  if format.len == 0:
    result.diagnostic = "cannot determine manifest repo Git object format"
    return
  let oidLength = if format == "sha256": 64 else: 40

  # The rebuild replays the ahead commits, so the branch must BE ahead of the
  # upstream and not diverged from it.
  let ancestry = gitRunPlain(identity,
    ["-C", manifestRepoRoot, "merge-base", "--is-ancestor", tip.oid, "HEAD"])
  if ancestry.code != 0:
    result.diagnostic = "the manifest branch has diverged from " &
      upstream.target.display & "; reconcile it (fetch + rebase) before " &
      "repairing lock records"
    return

  # Tracked content must match HEAD exactly, or the rebuild would re-commit a
  # working tree that is not the history it claims to replay. Untracked files
  # are fine — the rebuild never adds them.
  var dirtyTracked: seq[string]
  for entry in gitPorcelainEntries(identity, manifestRepoRoot):
    if entry.code == "??": continue
    dirtyTracked.add(entry.path)
  if dirtyTracked.len > 0:
    result.diagnostic = "the manifest repo has uncommitted changes to " &
      "tracked files (" & dirtyTracked.join(", ") &
      "); commit, stash or discard them before repairing lock records"
    return

  # Every ahead commit must touch locks/ only, and must delete nothing: the
  # rebuild re-adds what it finds under locks/, so anything else in the ahead
  # range would be silently dropped.
  let aheadNames = gitRunPlain(identity,
    ["-C", manifestRepoRoot, "diff", "--name-only", "--no-renames", "-z",
     tip.oid, "HEAD"])
  if aheadNames.code != 0:
    result.diagnostic = "cannot inspect the commits this branch holds beyond " &
      upstream.target.display
    return
  var outsideLocks: seq[string]
  for rel in nulSeparatedPaths(aheadNames.output):
    if not pathIsUnderLocks(rel):
      outsideLocks.add(rel)
  if outsideLocks.len > 0:
    outsideLocks.sort()
    result.diagnostic = "the commits this branch holds beyond " &
      upstream.target.display & " touch paths outside locks/ (" &
      outsideLocks.join(", ") &
      "); this repair only rebuilds lock records, so it refuses rather than " &
      "risk dropping them"
    return
  let aheadDeletes = gitRunPlain(identity,
    ["-C", manifestRepoRoot, "diff", "--diff-filter=D", "--name-only",
     "--no-renames", "-z", tip.oid, "HEAD"])
  if aheadDeletes.code == 0 and nulSeparatedPaths(aheadDeletes.output).len > 0:
    result.diagnostic = "the commits this branch holds beyond " &
      upstream.target.display &
      " delete tracked paths; a lock record is immutable, so this state is " &
      "not one this repair will rebuild"
    return

  # The record inventory: everything tracked under locks/.
  let tracked = gitRunPlain(identity,
    ["-C", manifestRepoRoot, "ls-files", "-z", "--cached", "--", "locks"])
  if tracked.code != 0:
    result.diagnostic = "cannot list the manifest repo's tracked lock paths"
    return

  proc existsInBase(path: string): bool =
    gitRunPlain(identity,
      ["-C", manifestRepoRoot, "cat-file", "-e", tip.oid & ":" & path]).code == 0

  var claimed = initTable[string, string]()
  var steps: seq[LockMigrationStep]
  var carried: seq[string]
  var orphans: seq[string]
  for rel in nulSeparatedPaths(tracked.output):
    let parsed = parseLockRecordRelPath(rel)
    if parsed.ok:
      if existsInBase(rel): continue
      # An ahead-only record that is ALREADY canonical. The rebuild re-commits
      # it, so it is part of the chain this plan promises would publish, and it
      # has to earn that on its own merits — a canonical PATH is not the same
      # thing as a publishable RECORD. ``locks/<p>/<r>/NOTES.toml`` is a
      # perfectly canonical path whose stem is not an object id, and re-adding
      # it would build a chain the publisher then refuses forever: the wedge
      # again, created by the very thing meant to clear it.
      let carriedAbs = manifestRepoRoot / rel.replace('/', DirSep)
      var carriedBody: string
      try:
        carriedBody = readFile(extendedPath(carriedAbs))
      except CatchableError as err:
        result.diagnostic = "'" & rel & "' cannot be read (" & err.msg & ")"
        return
      if not isFullHexOid(parsed.sha, oidLength):
        result.diagnostic = "'" & rel & "' sits at a canonical path but its " &
          "filename stem '" & parsed.sha & "' is not a full " & format &
          " object id, so the publisher refuses it wherever it sits. This " &
          "repair will not rebuild a branch it knows would not publish: " &
          "delete the file if it is not a lock record, and re-run."
        return
      if expectedLockRecordFromBody(rel, carriedBody).isNone:
        result.diagnostic = "'" & rel & "' sits at a canonical path but " &
          "cannot be bound to an exact repository coordinate, so the " &
          "publisher would refuse it. This repair will not rebuild a branch " &
          "it knows would not publish: delete the file if it is not a lock " &
          "record, and re-run."
        return
      carried.add(rel)
      continue
    if not rel.endsWith(lockRecordExt) or parsed.canonicalRelPath.len == 0:
      # Not a lock record at all — either not a ``.toml``, or a ``.toml`` with
      # no project/repo structure to derive a canonical path from
      # (``locks/NOTES.toml``, ``locks/<project>/NOTES.toml``). It is the
      # operator's file. The repair has no opinion about it beyond not losing
      # it, and MUST NOT refuse the whole store over it: relocating files that
      # were never records is exactly what the withdrawn migration did.
      if not existsInBase(rel): orphans.add(rel)
      continue

    # A record-shaped path that is not canonical. This is the repair's subject.
    if existsInBase(rel):
      result.diagnostic = "'" & rel & "' is a non-canonical lock record that " &
        "is ALREADY PUBLISHED on " & upstream.target.display &
        ". This repair only rebuilds commits that never left this machine, " &
        "and a published record is immutable, so it refuses. Removing it " &
        "requires a coordinated change to the manifest repo's shared " &
        "history, agreed with everyone who has cloned it — this tool will " &
        "not do that for you."
      return
    let target = parsed.canonicalRelPath
    if not parseLockRecordRelPath(target).ok:
      result.diagnostic = "'" & rel & "' cannot be repaired automatically: " &
        parsed.diagnostic & ". Move it to the path its own body describes by " &
        "hand, or delete it if it is not a lock record."
      return
    let targetParsed = parseLockRecordRelPath(target)
    # Full hex OID stem, or the publisher would refuse the record after the
    # move and this repair would have created a second wedge.
    if not isFullHexOid(targetParsed.sha, oidLength):
      result.diagnostic = "'" & rel & "' cannot be repaired: its filename " &
        "stem '" & targetParsed.sha & "' is not a full " & format &
        " object id, so the publisher would refuse the record wherever it " &
        "sits. Delete it — the lock writer regenerates a correct record on " &
        "the next lock operation."
      return
    let abs = manifestRepoRoot / rel.replace('/', DirSep)
    var body: string
    try:
      body = readFile(extendedPath(abs))
    except CatchableError as err:
      result.diagnostic = "'" & rel & "' cannot be read (" & err.msg & ")"
      return
    if body.len == 0:
      result.diagnostic = "'" & rel & "' is empty; an empty record is not " &
        "publishable at any path. Delete it — the lock writer regenerates a " &
        "correct record on the next lock operation."
      return
    let named = minimalRoutedRepoName(body)
    if named.len > 0 and named != targetParsed.repo:
      result.diagnostic = "'" & rel & "' names repo '" & named &
        "' in its body but its path decodes to '" & targetParsed.repo &
        "'; the two disagree, so this repair will not guess. Move it to the " &
        "record's own path by hand."
      return
    if expectedLockRecordFromBody(target, body).isNone:
      result.diagnostic = "'" & rel & "' cannot be bound to an exact " &
        "repository coordinate, so it would not publish even from its " &
        "canonical path " & target & ". Delete it — the lock writer " &
        "regenerates a correct record on the next lock operation."
      return
    let absTarget = manifestRepoRoot / target.replace('/', DirSep)
    if fileExists(extendedPath(absTarget)):
      var targetBody: string
      try:
        targetBody = readFile(extendedPath(absTarget))
      except CatchableError as err:
        result.diagnostic = "cannot read the canonical record at " & target &
          " (" & err.msg & ")"
        return
      if targetBody != body:
        result.diagnostic = "'" & rel & "' would move onto " & target &
          ", which already holds a DIFFERENT record. A lock record is " &
          "immutable, so which body survives is your decision, not this " &
          "tool's: compare the two files and delete the one that is wrong."
        return
    if target in claimed:
      result.diagnostic = "'" & rel & "' and '" & claimed[target] &
        "' both resolve to the same canonical path " & target &
        ". Repairing them together would silently lose one, so this repair " &
        "refuses: delete whichever is redundant and re-run."
      return
    claimed[target] = rel
    steps.add(LockMigrationStep(oldPath: rel, target: target))

  steps.sort(proc (a, b: LockMigrationStep): int = cmp(a.oldPath, b.oldPath))
  carried.sort()
  orphans.sort()
  result.steps = steps
  result.carried = carried
  result.orphans = orphans
  result.ok = true

proc applyLockRecordMigration*(identity: GitToolIdentity;
    manifestRepoRoot: string; plan: LockMigrationPlan):
    tuple[ok: bool; diagnostic: string] =
  ## Execute a plan that `planLockRecordMigration` already proved publishable.
  ## Order matters: the branch is reset FIRST, so that the relocations are
  ## additions relative to the new base rather than a delete-and-add pair.
  if not plan.ok: return (false, plan.diagnostic)
  if plan.steps.len == 0: return (true, "")

  let reset = gitRunPlain(identity,
    ["-C", manifestRepoRoot, "reset", "--quiet", "--mixed", plan.baseOid])
  if reset.code != 0:
    return (false, "could not rewind the manifest branch to " &
      plan.upstreamDisplay & ": " & reset.output.strip())

  let locksDir = manifestRepoRoot / "locks"

  proc dirIsEmpty(dir: string): bool =
    for _ in walkDir(extendedPath(dir)): return false
    true

  proc pruneEmptyParents(absOld: string) =
    ## Leave no empty husk of the mis-shaped subtree behind. Path arithmetic is
    ## done on the ORDINARY form (`extendedPath` output must never be compared
    ## or stored); only the filesystem calls take the extended form.
    var dir = parentDir(absOld)
    while dir.len > locksDir.len and dir.startsWith(locksDir):
      try:
        if not dirIsEmpty(dir): break
        removeDir(extendedPath(dir))
      except CatchableError: break
      dir = parentDir(dir)

  var toAdd = plan.carried
  for step in plan.steps:
    let absOld = manifestRepoRoot / step.oldPath.replace('/', DirSep)
    let absNew = manifestRepoRoot / step.target.replace('/', DirSep)
    try:
      createDir(extendedPath(parentDir(absNew)))
      if fileExists(extendedPath(absNew)):
        # Byte-identical by the plan's own check: the record already exists
        # canonically and this file is a redundant duplicate.
        removeFile(extendedPath(absOld))
      else:
        moveFile(extendedPath(absOld), extendedPath(absNew))
    except CatchableError as err:
      return (false, "failed to relocate " & step.oldPath & " to " &
        step.target & ": " & err.msg &
        " (the manifest branch has been rewound to " & plan.upstreamDisplay &
        "; re-run once the filesystem error is resolved)")
    pruneEmptyParents(absOld)
    toAdd.add(step.target)

  toAdd.sort()
  var deduped: seq[string]
  for path in toAdd:
    if deduped.len == 0 or deduped[^1] != path: deduped.add(path)
  if deduped.len == 0: return (true, "")

  let addRes = gitRunPlain(identity,
    @["-C", manifestRepoRoot, "add", "-f", "--"] & deduped)
  if addRes.code != 0:
    return (false, "git add failed during the lock-record repair: " &
      addRes.output.strip())
  let staged = gitRunPlain(identity,
    @["-C", manifestRepoRoot, "diff", "--cached", "--quiet", "--"] & deduped)
  if staged.code == 0:
    # Nothing differs from the base tree; the branch is already repaired.
    return (true, "")
  let plural = if deduped.len == 1: "record" else: "records"
  let commitRes = gitRunPlainEnv(identity,
    @["-C", manifestRepoRoot, "commit", "--quiet", "-m",
      "Rebuild " & $deduped.len & " unpublished workspace lock " & plural &
        " at their canonical paths", "--"] & deduped,
    internalContext = InternalLockCommitContext)
  if commitRes.code != 0:
    return (false, "git commit failed during the lock-record repair: " &
      commitRes.output.strip())
  (true, "")

proc renderLockMigrationPlan*(plan: LockMigrationPlan): seq[string] =
  for step in plan.steps:
    result.add("  relocate  " & step.oldPath)
    result.add("        ->  " & step.target)
  for path in plan.carried:
    result.add("  re-commit " & path & " (unchanged)")
  for path in plan.orphans:
    result.add("  leave     " & path &
      " (not a lock record; it becomes an untracked file on disk)")

proc runWorkspaceMigrateLocksCommand*(args: openArray[string]): int =
  ## `repro workspace migrate-locks [--dry-run|--apply]
  ## [--manifest-layer-root=PATH] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop]`.
  ##
  ## Exit codes:
  ##   - 0 — nothing to repair, or the repair succeeded, or a dry run planned
  ##         a repair successfully.
  ##   - 1 — the store cannot be repaired automatically; the diagnostic names
  ##         the file and the manual step.
  ##   - 2 — bad usage.
  var apply = false
  var dryRun = false
  var manifestLayerRoot = ""
  var workspaceRoot = ""
  # Every other verb's parser seeds ``tpmPathOnly`` and lets
  # ``--tool-provisioning`` override it. This one seeded
  # ``tpmUnspecified``, which ``resolveGitTool`` rejects outright ("no
  # provisioning mode was selected before resolving git; callers must
  # parse --tool-provisioning before invoking resolveGitTool") — so the
  # documented invocation ``repro workspace migrate-locks --dry-run``
  # could never run, and the flag the message tells you to parse was in
  # fact optional everywhere else.
  var toolProvisioning = tpmPathOnly
  var i = 0
  # ``--flag=VALUE`` and ``--flag VALUE`` both accepted, resolved inline: a
  # nested helper would have to capture ``args``, and an ``openArray`` cannot be
  # captured by a closure.
  var flagValue = ""
  var flagName = ""
  while i < args.len:
    let arg = args[i]
    flagName = ""
    flagValue = ""
    for candidate in ["--manifest-layer-root", "--workspace-root",
                      "--tool-provisioning"]:
      if arg == candidate:
        flagName = candidate
        if i + 1 < args.len:
          inc i
          flagValue = args[i]
        break
      elif arg.startsWith(candidate & "="):
        flagName = candidate
        flagValue = arg[(candidate.len + 1) .. ^1]
        break
    if arg == "--apply": apply = true
    elif arg == "--dry-run": dryRun = true
    elif flagName.len > 0:
      if flagValue.len == 0:
        stderr.writeLine("repro workspace migrate-locks: " & flagName &
          " requires a value")
        return 2
      case flagName
      of "--manifest-layer-root": manifestLayerRoot = flagValue
      of "--workspace-root": workspaceRoot = flagValue
      else: toolProvisioning = parseToolProvisioning(flagValue)
    elif arg.startsWith("--"):
      stderr.writeLine("repro workspace migrate-locks: unknown flag " & arg)
      return 2
    else:
      stderr.writeLine("repro workspace migrate-locks: " &
        "unexpected argument " & arg)
      return 2
    inc i
  if apply and dryRun:
    stderr.writeLine("repro workspace migrate-locks: " &
      "--apply and --dry-run are mutually exclusive")
    return 2

  # Same default as ``repro workspace lock``: the current directory, with no
  # upward search, so the two verbs agree about which workspace they mean.
  if workspaceRoot.len == 0: workspaceRoot = getCurrentDir()
  workspaceRoot = absolutePath(workspaceRoot)
  if manifestLayerRoot.len == 0:
    manifestLayerRoot = workspaceRoot / ".repro" / "manifests"
  manifestLayerRoot = absolutePath(manifestLayerRoot)
  if not dirExists(extendedPath(manifestLayerRoot)):
    stderr.writeLine("repro workspace migrate-locks: no manifest layer at '" &
      manifestLayerRoot & "'")
    return 1

  let identity = ensureGitToolResolvable(toolProvisioning, getEnv("PATH"))
  let plan = planLockRecordMigration(identity, manifestLayerRoot)
  if not plan.ok:
    stderr.writeLine("repro workspace migrate-locks: " & plan.diagnostic)
    return 1
  if plan.steps.len == 0:
    stdout.writeLine("repro workspace migrate-locks: every lock record in '" &
      manifestLayerRoot & "' is already at its canonical path; nothing to do")
    return 0

  let plural = if plan.steps.len == 1: "record" else: "records"
  stdout.writeLine("repro workspace migrate-locks: " & $plan.steps.len &
    " unpublished lock " & plural & " to relocate (base " &
    plan.upstreamDisplay & "):")
  for line in renderLockMigrationPlan(plan):
    stdout.writeLine(line)

  if not apply:
    stdout.writeLine("")
    stdout.writeLine("This was a dry run; nothing has changed. Re-run with " &
      "--apply to rebuild the unpublished commits with these records at " &
      "their canonical paths.")
    return 0

  let outcome = applyLockRecordMigration(identity, manifestLayerRoot, plan)
  if not outcome.ok:
    stderr.writeLine("repro workspace migrate-locks: " & outcome.diagnostic)
    return 1
  stdout.writeLine("repro workspace migrate-locks: relocated " &
    $plan.steps.len & " lock " & plural &
    "; the manifest branch now publishes normally")
  0



proc completeExpectedLockPublication*(identity: GitToolIdentity;
    backendRoot: string;
    expected: openArray[ExpectedLockRecord]): LockPublishResult =
  ## Final ``repro push`` completion step. Unlike ``publishWorkspaceLock`` this
  ## never stages, writes, or commits a lock. It proves the exact records that
  ## the real source pre-push gates should already have produced are reachable
  ## upstream, or resumes a previously verified lock-only ahead chain.
  result.outcome = lpoFailed
  if not discoverGitWorktree(identity, backendRoot).ok:
    result.outcome = lpoNotPublishable
    result.diagnostic = "lock backend root '" & backendRoot &
      "' is not a Git checkout"
    return
  if expected.len == 0:
    result.diagnostic = "no expected lock records were supplied"
    return
  let upstream = resolveLockUpstream(identity, backendRoot)
  if not upstream.ok:
    result.outcome =
      if "no upstream" in upstream.diagnostic: lpoNotPublishable
      else: lpoFailed
    result.diagnostic = upstream.diagnostic
    return
  result = publishVerifiedLockState(identity, backendRoot, upstream.target,
    expected)

proc observeVerifiedLocalOnlyLockHead(identity: GitToolIdentity;
    backendRoot: string; expected: openArray[ExpectedLockRecord]): string =
  ## Read-only partial-success evidence used after a source push fails. Return
  ## the local backend HEAD only when it is strictly ahead of the freshly
  ## fetched upstream and the whole ahead chain is verified lock-only.
  if not discoverGitWorktree(identity, backendRoot).ok or expected.len == 0:
    return ""
  let upstream = resolveLockUpstream(identity, backendRoot)
  if not upstream.ok: return ""
  let fetched = fetchImmutableLockTip(identity, backendRoot, upstream.target)
  if not fetched.ok: return ""
  let head = gitRunPlain(identity,
    ["-C", backendRoot, "rev-parse", "HEAD^{commit}"])
  if head.code != 0: return ""
  let headOid = head.output.strip().toLowerAscii()
  if headOid == fetched.oid: return ""
  let proof = verifyLockOnlyAheadChain(identity, backendRoot, fetched.oid,
    headOid, expected)
  if proof.ok: headOid else: ""

# MO-3: the store-level publish outcome (``StorePutOutcome``) and the RA-7
# publish outcome (``LockPublishOutcome``) are a 1:1, lossless mapping, so the
# git-checkout backend can route through ``publishWorkspaceLock`` and the
# routed call-sites can recover the exact ``LockPublishResult`` they branch on.
proc storePutFromLockPublish(o: LockPublishOutcome): StorePutOutcome =
  case o
  of lpoPublished: spoOk
  of lpoNothingToPublish: spoNothing
  of lpoRefusedDirty: spoRefusedDirty
  of lpoNotPublishable: spoNotPublishable
  of lpoFailed: spoFailed

proc lockPublishFromStorePut(o: StorePutOutcome): LockPublishOutcome =
  case o
  of spoOk: lpoPublished
  of spoNothing: lpoNothingToPublish
  of spoRefusedDirty: lpoRefusedDirty
  of spoNotPublishable: lpoNotPublishable
  of spoFailed: lpoFailed

proc pushCommittedLockCommits(identity: GitToolIdentity;
    manifestRepoRoot: string;
    expected: openArray[ExpectedLockRecord]): LockPublishResult =
  ## HL-3 — push ALREADY-COMMITTED-but-unpushed lock commits to the backend's
  ## upstream. ``GitCheckoutLockStore.putLock`` COMMITS each record as it writes
  ## it (so the git-history "latest lock" query resolves it), which means that
  ## by publish time there is nothing STAGED and ``publishWorkspaceLock`` reports
  ## ``lpoNothingToPublish`` without ever pushing. For a ROUTED git-checkout
  ## backend on its OWN remote (a team/personal manifests repo, distinct from
  ## the workspace's ``.repo/manifests``), that would silently skip the remote
  ## push — the record would never leave the machine. This helper closes that
  ## gap: when HEAD is ahead of ``@{u}`` it pushes the committed lock commits
  ## with the SAME bounded non-fast-forward re-apply retry ``publishWorkspaceLock``
  ## uses, so a concurrent publisher is invisible and any other push failure
  ## (unreachable/unwritable remote) stays LOUD (``lpoFailed``) for Decision 2.
  result.outcome = lpoNothingToPublish

  if not discoverGitWorktree(identity, manifestRepoRoot).ok:
    result.outcome = lpoNotPublishable
    result.diagnostic =
      "manifest repo root '" & manifestRepoRoot &
        "' is not a git checkout; cannot publish lock"
    return

  let upstream = resolveLockUpstream(identity, manifestRepoRoot)
  if not upstream.ok:
    result.outcome =
      if "no upstream" in upstream.diagnostic: lpoNotPublishable
      else: lpoFailed
    result.diagnostic = upstream.diagnostic
    return
  result = publishVerifiedLockState(identity, manifestRepoRoot,
    upstream.target, expected)

method publishPending*(s: GitCheckoutLockStore): StorePutResult =
  ## Route to the byte-identical RA-7 ``publishWorkspaceLock`` (commit + push,
  ## non-ff retry, dirty-outside-``locks/`` refusal) and map its rich outcome
  ## onto the store-level outcome.
  ##
  ## HL-3 — ``publishWorkspaceLock`` only pushes what it STAGES; but the routed
  ## ``putLock`` already COMMITTED each record, so a routed git-checkout backend
  ## on its own remote has nothing staged and would be a silent
  ## ``lpoNothingToPublish``. When that happens, fall through to
  ## ``pushCommittedLockCommits`` which pushes the already-committed lock commits
  ## (same non-ff retry), so the routed backend's records actually reach its
  ## remote and a push failure stays LOUD (Decision 2). The dirty-outside /
  ## refused / failed / published outcomes of the staged path are preserved.
  let pub = publishWorkspaceLock(s.identity, s.manifestRepoRoot,
    s.pendingExpected)
  if pub.outcome == lpoNothingToPublish and s.pendingExpected.len > 0:
    let pushed = pushCommittedLockCommits(s.identity, s.manifestRepoRoot,
      s.pendingExpected)
    return StorePutResult(outcome: storePutFromLockPublish(pushed.outcome),
      diagnostic: pushed.diagnostic)
  StorePutResult(outcome: storePutFromLockPublish(pub.outcome),
    diagnostic: pub.diagnostic)

proc runWorkspaceLockCommand*(args: openArray[string]): int =
  ## ``repro workspace lock [<project>] [--workspace-root=PATH]
  ## [--manifest-layer-root=PATH] [--sha=SHA] [--trigger-repo=NAME]
  ## [--tool-provisioning=path|nix|tarball|scoop]``.
  ##
  ## Exit codes (per M11 design):
  ##   - 0 — per-repo lock TOML written (RA-1: no index).
  ##   - 1 — IO failure, VCS query failure, or a mis-specified
  ##         trigger repo / SHA. Distinct from refuse-and-report.
  ##   - 2 — at least one declared repo has a dirty working tree.
  ##         The lock would lie about what the recorded SHA
  ##         reproduces; the operator must commit, stash, or
  ##         discard first.
  let parsed = parseWorkspaceLockArgs(args)
  let outcome = executeWorkspaceLock(parsed)
  writeWorkspaceLockReport(outcome.report,
    reportDestination(parsed.report, outcome.report.workspaceRoot, "lock"))
  stageFailureReport(parsed.report, outcome.report.workspaceRoot, "lock",
    outcome.report.toJsonNode())
  for line in renderLockTextLines(outcome.report):
    stdout.writeLine(line)
  # RA-7: an explicit ``repro workspace lock`` PUBLISHES (commit + push)
  # the lock to the manifest repo. Only attempt when the write succeeded
  # (exit 0). Publication is best-effort: a refusal/failure is surfaced to
  # the operator but does not change the lock command's exit code (the lock
  # was still written locally; post-commit/next-push can re-publish).
  if outcome.report.exitCode == 0 and
      outcome.report.manifestLayerRoot.len > 0:
    let identity = ensureGitToolResolvable(
      parsed.toolProvisioning, getEnv("PATH"))
    # MO-10: route the RA-7 publish through the abstract ``LockStore``. The
    # git-checkout backend's ``publishPending`` delegates to the byte-identical
    # ``publishWorkspaceLock``; the 1:1 outcome mapping recovers the exact
    # ``LockPublishResult`` the branch below acts on.
    let publishStore: LockStore =
      newGitCheckoutLockStore(identity, outcome.report.manifestLayerRoot)
    let storePub = publishStore.publishPending()
    let pub = LockPublishResult(
      outcome: lockPublishFromStorePut(storePub.outcome),
      diagnostic: storePub.diagnostic)
    case pub.outcome
    of lpoPublished:
      stdout.writeLine("workspace lock: " & pub.diagnostic)
    of lpoNothingToPublish:
      discard
    else:
      stderr.writeLine("workspace lock: " & pub.diagnostic)
  outcome.report.exitCode

# ---- M19: post-commit lock refresh (best-effort) -------------------------
#
# The M17-installed post-commit hook dispatcher routes here via
# ``repro hooks dispatch post-commit --repo-root <repo>``. Semantics are
# strictly non-blocking: post-commit MUST exit 0 even when the lock
# writer refuses, no workspace metadata is present, the workspace is
# dirty, or any subprocess errors. The operator-facing trace lives in
# ``<workspaceRoot>/.repro/workspace/post-commit-lock.log`` (append-only)
# and in ``<workspaceRoot>/.repro/build/reports/post-commit-report.json``
# (overwritten on each run with the latest result).
#
# Design choice: a separate ``runPostCommitLockCommand`` wrapper around
# the strict M11 ``runWorkspaceLockCommand`` was preferred over adding a
# ``--best-effort`` flag to the workspace command itself. The strict
# command keeps its 0/1/2 contract intact; the wrapper concentrates the
# "downgrade every failure to exit 0 + a log line" policy in one place,
# adds the M19-specific log/report layout, and avoids leaking the
# best-effort surface into the operator-facing ``repro workspace lock``.

# M19b: post-commit reports WRITE-vs-PUBLISH, never a bare "ok".
#
# Post-commit is local-only by design (Workspace-Manifests.md § "Lock
# publication (commit + push)": the publish table's post-commit row is
# "writes: yes (best-effort) / publishes: **no — local only**"; it must not
# require the network). Publication is the job of the pre-push gate and of an
# explicit ``repro workspace lock``.
#
# The defect this vocabulary replaces: the wrapper reported ``ok wrote <path>``
# for a record that existed on exactly one disk and nowhere else. The message
# was true and useless — a workspace whose publication had been dead for two
# weeks logged an unbroken run of successes. The same held for the two "no lock
# at all" branches, which reported ``skipped-dirty`` / ``failed`` and exit 0
# with no operator-visible trace outside a log file nobody reads.
#
# The rules now are:
#
#   * ``ok`` is spelled ``published`` and is reserved for a record actually
#     present in the lock store's last-known upstream. A local write alone
#     never earns it.
#   * Every other outcome names what did NOT happen (``written-*`` = the
#     record exists but has not been published; ``no-lock-*`` = no record
#     exists) and why, plus the remedy.
#   * Anything that is not the DESIGNED steady state also prints one line to
#     stderr so the operator sees it at the terminal. Post-commit still exits
#     0 unconditionally: loud, never blocking. A hook that fails commits would
#     be strictly worse than the starvation it reports.

type
  PostCommitOutcome* = enum
    pcoPublished         ## Per-repo lock TOML written (RA-1: no index) AND
                         ## already present in the store's last-known
                         ## upstream. The only success tag.
    pcoWrittenPending    ## Record written to a PUBLISHABLE store but not yet
                         ## in its upstream. The designed post-commit steady
                         ## state — pre-push publishes it. Loud only when the
                         ## store carries STRANDED records (below).
    pcoWrittenLocalOnly  ## Record written, but the store is not publishable
                         ## (not its own checkout / no upstream). This record
                         ## will never leave this machine.
    pcoWrittenUnknown    ## Record written; the publication probe itself
                         ## failed. Never reported as success.
    pcoNoManifestRecord  ## The lock writer succeeded but wrote no manifest
                         ## record: this workspace routes per-repo records to
                         ## their own backends, or is public-only and carries
                         ## its lock in the in-repo ``repro.lock``. Nothing to
                         ## publish here, and nothing claimed.
    pcoNoLockDirty       ## At least one in-scope repo is dirty; strict M11
                         ## refused with exit 2 and NO lock exists.
    pcoSkippedNoWorkspace ## No ``.repo/workspace.toml`` or no resolvable
                          ## project; common in a freshly-cloned repo
                          ## that has not been initialised. A genuine
                          ## "this hook does not apply here" no-op, not a
                          ## starvation: log-only.
    pcoNoLockFailed      ## Lock writer raised (IO error, VCS query
                         ## failure, missing checkout, ...) and NO lock
                         ## exists.
    pcoSkippedGitOperation ## Git is mid-rebase / mid-cherry-pick / mid-am /
                           ## mid-bisect in the repo that fired the hook. The
                           ## commit this hook saw is one of that operation's
                           ## intermediate commits, and writing a lock into a
                           ## working tree its owner has not finished with is
                           ## how a hook breaks somebody else's rebase.
    pcoInertGitStateUnknown ## The "is an operation in flight" probe could not
                            ## answer. The hook did nothing and SAID so — an
                            ## unanswerable question is not the same as "no".

  PostCommitPublication* = enum
    ## Publication state of the record this run wrote, probed WITHOUT any
    ## network access (post-commit must not require the network, so the
    ## comparison is against the last-fetched remote-tracking ref).
    pcpNoRecord          ## No lock record was written by this run.
    pcpPublished         ## The record is present in the store's upstream.
    pcpPending           ## Store is publishable; record is not upstream yet.
    pcpLocalOnly         ## Store is not publishable; nothing can ever be.
    pcpUnknown           ## The probe failed; publication state is unproven.

  PostCommitReport* = object
    workspaceRoot*: string
    currentRepo*: string
    project*: string
    outcome*: string
    lockFilePath*: string
    indexFilePath*: string
    triggerRepo*: string
    triggerSha*: string
    diagnostic*: string
    timestamp*: string
    exitCode*: int
    lockWritten*: bool
      ## M19b — did this run leave a lock RECORD on disk at all? The three
      ## exit-0 starvation modes are exactly the runs where this is false
      ## plus the runs where it is true and ``publication`` is not
      ## ``published``.
    publication*: string
      ## M19b — ``postCommitPublicationTag`` of the state above.
    pendingRecords*: int
      ## M19b — how many lock records for the trigger repo exist in the
      ## store but are absent from its last-known upstream.
    strandedRecords*: int
      ## M19b — of ``pendingRecords``, how many are anchored to a trigger
      ## commit that is ALREADY published in the trigger repo. Each one is
      ## proof that a push went out without its lock: publication is broken,
      ## not merely pending. Any non-zero value is loud.

proc postCommitOutcomeTag(outcome: PostCommitOutcome): string =
  case outcome
  of pcoPublished: "published"
  of pcoWrittenPending: "written-pending-publish"
  of pcoWrittenLocalOnly: "written-local-only"
  of pcoWrittenUnknown: "written-publication-unknown"
  of pcoNoManifestRecord: "no-manifest-record"
  of pcoNoLockDirty: "no-lock-dirty-siblings"
  of pcoSkippedNoWorkspace: "skipped-no-workspace"
  of pcoNoLockFailed: "no-lock-failed"
  of pcoSkippedGitOperation: "skipped-git-operation-in-progress"
  of pcoInertGitStateUnknown: "inert-git-state-unknown"

proc postCommitPublicationTag(state: PostCommitPublication): string =
  case state
  of pcpNoRecord: "no-record"
  of pcpPublished: "published"
  of pcpPending: "pending"
  of pcpLocalOnly: "local-only"
  of pcpUnknown: "unknown"

proc toJsonNode*(report: PostCommitReport): JsonNode =
  result = newJObject()
  result["workspaceRoot"] = %report.workspaceRoot
  result["currentRepo"] = %report.currentRepo
  result["project"] = %report.project
  result["outcome"] = %report.outcome
  result["lockFilePath"] = %report.lockFilePath
  result["indexFilePath"] = %report.indexFilePath
  result["triggerRepo"] = %report.triggerRepo
  result["triggerSha"] = %report.triggerSha
  result["diagnostic"] = %report.diagnostic
  result["timestamp"] = %report.timestamp
  result["exitCode"] = %report.exitCode
  result["lockWritten"] = %report.lockWritten
  result["publication"] = %report.publication
  result["pendingRecords"] = %report.pendingRecords
  result["strandedRecords"] = %report.strandedRecords

proc selfAndAncestors(startPath: string): seq[string] =
  ## ``startPath`` and every directory above it, nearest first.
  result = @[]
  if startPath.len == 0:
    return
  var probe = absolutePath(startPath)
  while probe.len > 1:
    result.add(probe)
    let parent = parentDir(probe)
    if parent == probe: break
    probe = parent

proc enclosingWorkspaceRoot*(startPath: string): string =
  ## The nearest ancestor of ``startPath`` (inclusive) that is a WORKSPACE, or
  ## "" when there is none.
  ##
  ## A managed hook fires inside a participating repo and has to walk up to the
  ## workspace. The marker for that walk is the WORKSPACE, never a ``.repro/``
  ## directory: every repo Reprobuild has built carries a repo-local
  ## ``.repro/`` (build reports, engine caches — including the ones the hooks
  ## themselves write), so a walk keyed on ``.repro/`` resolves a participating
  ## repo to ITSELF and never reaches the workspace above it. The strict lock
  ## writer then refuses the directory it was handed —
  ##
  ##   `repro workspace lock` requires either `.repro/workspace.toml` or a
  ##   <project> argument; neither was present at <repo>
  ##
  ## — and because post-commit is non-blocking by design that refusal is
  ## silent: no lock is written for any commit in any built repo, and the
  ## report naming the failure is filed under the REPO's own ``.repro/`` where
  ## nothing looks for it.
  ##
  ## So the nearest ancestor carrying ``.repro/workspace.toml`` or a resolved
  ## manifest checkout wins. Only when there is no such ancestor does the
  ## manifest-optional marker (MO-2, a committed ``repro.lock``) decide, and
  ## then the nearest one wins — a standalone committed-lock repo really is its
  ## own workspace, and a repo nested inside a real workspace is not.
  let ancestors = selfAndAncestors(startPath)
  for candidate in ancestors:
    if fileExists(workspaceTomlPath(candidate)) or
        hasResolvedManifestCheckout(candidate):
      return candidate
  for candidate in ancestors:
    if hasCommittedLockWorkspaceMarker(candidate):
      return candidate
  ""

proc enclosingReproShell*(startPath: string): string =
  ## The nearest ancestor of ``startPath`` (inclusive) holding a ``.repro/``
  ## directory, or "".
  ##
  ## This is NOT a workspace test — a bare ``.repro/`` is explicitly not a
  ## workspace (``isInitializedWorkspace``). It is only the place to FILE a
  ## report when ``enclosingWorkspaceRoot`` found nothing: a half-bootstrapped
  ## parent still deserves a trace saying "not a workspace" rather than
  ## silence.
  for candidate in selfAndAncestors(startPath):
    if dirExists(candidate / ".repro"):
      return candidate
  ""

proc resolvePostCommitWorkspaceRoot(currentRepo, workspaceRoot: string): string =
  ## The workspace this post-commit run belongs to. An explicit
  ## ``--workspace-root`` wins outright; otherwise walk up from
  ## ``--current-repo``.
  if workspaceRoot.len > 0:
    return absolutePath(workspaceRoot)
  enclosingWorkspaceRoot(currentRepo)

proc writePostCommitReport(workspaceRoot: string;
                           report: PostCommitReport) =
  ## Best-effort write of the JSON report. Never raises (a failing
  ## report write is itself just logged below).
  try:
    let reportDir = workspaceRoot / ".repro" / "workspace"
    createDir(reportDir)
    let reportPath = reportDir / "post-commit-report.json"
    writeFile(reportPath, pretty(report.toJsonNode(), indent = 2) & "\n")
  except CatchableError:
    discard

proc appendPostCommitLog(workspaceRoot, line: string) =
  ## Append a single line to ``post-commit-lock.log``. Never raises —
  ## a failed log write must not block the commit.
  try:
    let reportDir = workspaceRoot / ".repro" / "workspace"
    createDir(reportDir)
    let logPath = reportDir / "post-commit-lock.log"
    var f: File
    if open(f, logPath, fmAppend):
      f.writeLine(line)
      f.close()
  except CatchableError:
    discard

proc emitPostCommitWarning(tag, diagnostic, workspaceRoot: string) =
  ## M19b — one line to stderr for any post-commit run that did not end with a
  ## published lock record and is not the designed local-only steady state.
  ##
  ## Loud, NOT blocking: the caller still returns 0. Failing the commit would
  ## be a worse defect than the starvation this reports — the operator's work
  ## is already committed and a hook has no business rejecting it after the
  ## fact. Git relays a post-commit hook's stderr to the terminal, so this is
  ## the only channel that reaches a human without one; the log file is where
  ## the same line goes for anyone reading after the fact.
  try:
    stderr.writeLine("repro post-commit: " & tag & ": " & diagnostic)
    if workspaceRoot.len > 0:
      stderr.writeLine("repro post-commit: details in " &
        (workspaceRoot / ".repro" / "workspace" / "post-commit-lock.log"))
  except CatchableError:
    discard

proc parsePostCommitArgs(args: openArray[string]):
    tuple[currentRepo, workspaceRoot, triggerSha, triggerRepo: string;
          toolProvisioning: ToolProvisioningMode] =
  ## Minimal argv parser for the post-commit wrapper. The dispatcher
  ## installs ``--current-repo=PATH``; the rest are pass-throughs the
  ## operator can supply when invoking ``repro workspace post-commit``
  ## manually. Unknown flags are silently ignored — post-commit must
  ## never raise on argv shape.
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--":
      inc i
      continue
    if arg == "--current-repo" or arg.startsWith("--current-repo="):
      try: result.currentRepo = valueFromFlag(args, i, "--current-repo")
      except CatchableError: discard
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      try: result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
      except CatchableError: discard
    elif arg == "--sha" or arg.startsWith("--sha="):
      try: result.triggerSha = valueFromFlag(args, i, "--sha")
      except CatchableError: discard
    elif arg == "--trigger-repo" or arg.startsWith("--trigger-repo="):
      try: result.triggerRepo = valueFromFlag(args, i, "--trigger-repo")
      except CatchableError: discard
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      try:
        result.toolProvisioning = parseToolProvisioning(
          valueFromFlag(args, i, "--tool-provisioning"))
      except CatchableError: discard
    inc i

# ---- RA-4 / RA-19: post-commit detached cache-ref push -------------------
#
# After the best-effort lock refresh, the post-commit hook fires a
# detached, fire-and-forget push of the just-committed branch into the
# shared bare cache under ``refs/cache/<workspace>/<branch>`` (the RA-5
# ``pushCacheRef`` mechanism). The push MUST NOT block the commit: it
# runs detached with stdio redirected away, so it survives the
# post-commit process exiting.
#
#   * POSIX: a new session via ``setsid ... &`` with stdio to /dev/null.
#   * Windows (RA-19): a detached child via ``cmd /c start /b "" ...``
#     with stdio to NUL — ``start /b`` launches the re-invoked
#     ``repro hooks cache-push`` without a new window and returns
#     immediately, so the commit is never blocked.
#
# The DECISION (which detach mechanism + command line for a given OS) is
# factored into the pure ``cachePushSpawnCommand`` below so it is
# computable and assertable on any host; only the actual ``execShellCmd``
# launch is platform-guarded.

type
  WorkspaceTargetOs* = enum
    ## Platform parameter for the workspace decision/plan layer. Kept
    ## independent of ``when defined(windows)`` so the plan builders can be
    ## exercised for either target on any host (e.g. asserting the Windows
    ## provisioning plan + detached-spawn form from a Linux test).
    wtPosix
    wtWindows

  CachePushSpawnSpec* = object
    ## The fully-resolved, platform-parameterized spec for the detached
    ## post-commit cache push. ``shellInvocation`` is the command handed to
    ## the host shell; ``detach`` names the mechanism (for diagnostics /
    ## tests). Empty ``shellInvocation`` means "nothing to launch".
    targetOs*: WorkspaceTargetOs
    detach*: string            ## e.g. "setsid&" (POSIX) / "start /b" (Win)
    shellInvocation*: string   ## the command string for the host shell

proc cachePushSpawnCommand*(targetOs: WorkspaceTargetOs;
                            exePath, repoRoot, workspaceName: string):
                            CachePushSpawnSpec =
  ## PURE decision function: given a target OS and the re-invocation
  ## arguments, build the detached-spawn command for the post-commit eager
  ## cache push. No process is launched here — callers feed
  ## ``shellInvocation`` to the host shell under a platform guard.
  ##
  ##   * ``wtPosix``  → ``setsid <repro hooks cache-push …> </dev/null
  ##                    >/dev/null 2>&1 &`` (new session, fully detached).
  ##   * ``wtWindows``→ ``cmd /c start /b "" <repro hooks cache-push …>
  ##                    >NUL 2>&1`` (no new window, returns immediately).
  ##
  ## Returns an empty ``shellInvocation`` when ``workspaceName`` or
  ## ``exePath`` is empty (nothing to push / no re-invokable binary).
  result.targetOs = targetOs
  if workspaceName.len == 0 or exePath.len == 0:
    return
  let childArgs = shellCommand(@[exePath, "hooks", "cache-push",
    "--repo-root", repoRoot, "--workspace-name", workspaceName])
  case targetOs
  of wtPosix:
    result.detach = "setsid&"
    result.shellInvocation =
      "setsid " & childArgs & " </dev/null >/dev/null 2>&1 &"
  of wtWindows:
    # ``start /b`` (via ``cmd /c``) launches the child without a console
    # window and returns immediately, detaching it from the post-commit
    # process. The empty ``""`` is ``start``'s title argument (required so
    # a quoted exe path is not mistaken for the title). Stdio → NUL.
    result.detach = "start /b"
    result.shellInvocation =
      "start /b \"\" " & childArgs & " >NUL 2>&1"

proc resolveWorkspaceReposForHook(workspaceRoot: string): seq[ResolvedRepo] =
  ## Resolve the workspace's project repos in the best-effort post-commit /
  ## cache-push hook context. Mirrors the manifest-vs-compositional dispatch of
  ## the pre-push gate; returns ``@[]`` on any resolution failure so the caller
  ## (always best-effort) can silently no-op.
  try:
    if isCompositionalWorkspaceToml(workspaceRoot):
      let workspaceToml = absolutePath(workspaceTomlPath(workspaceRoot))
      return composeManifestLayersFromFile(workspaceToml).repos
    else:
      let projectName = detectWorkspaceProjectName(workspaceRoot)
      if projectName.len == 0:
        return @[]
      let manifestsRoot = manifestsRoot(workspaceRoot)
      let projectFile = manifestsRoot / "projects" / (projectName & ".toml")
      let variantFile = manifestsRoot / "variants" / (projectName & ".toml")
      if fileExists(projectFile):
        return resolveProject(projectFile).repos
      elif fileExists(variantFile):
        return resolveVariant(variantFile).repos
      else:
        return @[]
  except CatchableError:
    return @[]

proc refreshWorkspaceSiblingIgnoresBestEffort(workspaceRoot: string) =
  ## Regenerate the workspace root's managed sibling-ignore block (see the
  ## forward declaration above for why the verbs call it).
  ##
  ## Best-effort in the strict sense: a workspace root that is not a git
  ## checkout, a missing ``git`` on PATH, or an unwritable ``info/exclude``
  ## leaves the workspace exactly as it was and never changes the exit code of
  ## the verb that triggered it. The ignore set is an ergonomic convenience;
  ## failing a sync over it would be a worse outcome than 132 untracked
  ## directories.
  ##
  ## ``resolveWorkspaceReposForHook`` is reprobuild's existing workspace
  ## enumeration (the same one the post-commit hook uses). Its repo paths are
  ## passed through so NESTED checkouts — ``a/references/b`` — are covered
  ## without a second discovery implementation; the top-level scan inside
  ## ``collectSiblingIgnoreEntries`` covers standalone clones the manifest does
  ## not declare.
  if workspaceRoot.len == 0:
    return
  try:
    let gitBin = findExe("git")
    if gitBin.len == 0:
      return
    var declared: seq[string]
    for repo in resolveWorkspaceReposForHook(workspaceRoot):
      if repo.path.len > 0:
        declared.add(repo.path)
    discard refreshWorkspaceSiblingIgnores(gitBin,
      absolutePath(workspaceRoot), declared)
  except CatchableError:
    discard

proc findRepoByWorkspacePath(workspaceRoot: string;
    repos: seq[ResolvedRepo]; repoAbsPath: string): Option[ResolvedRepo] =
  ## Match the repo whose working tree is at ``repoAbsPath`` against a resolved
  ## repo set (normalized-path equality). ``none`` when no repo matches.
  let target = os.normalizedPath(absolutePath(repoAbsPath))
  for repo in repos:
    let repoAbs = os.normalizedPath(absolutePath(workspaceRoot / repo.path))
    if repoAbs == target:
      return some(repo)
  none(ResolvedRepo)

proc resolveRepoFetchUrl(workspaceRoot, repoAbsPath: string): string =
  ## Resolve the upstream fetch URL of the repo whose working tree is at
  ## ``repoAbsPath`` by matching it against the resolved project repos.
  ## Returns "" when no match (e.g. the repo is not part of the workspace
  ## manifest) — the caller then skips the cache push.
  let repos = resolveWorkspaceReposForHook(workspaceRoot)
  let matched = findRepoByWorkspacePath(workspaceRoot, repos, repoAbsPath)
  if matched.isNone: return ""
  matched.get().fetchUrl

proc runCachePushCommand*(args: openArray[string]): int =
  ## Internal entry point for the detached post-commit cache push:
  ## ``repro hooks cache-push --repo-root=PATH --workspace-name=NAME``.
  ## Resolves the repo's upstream fetch URL, locates the shared bare for
  ## that URL, and pushes the current branch to
  ## ``refs/cache/<workspace>/<branch>`` via the RA-5 ``pushCacheRef``
  ## mechanism. Best-effort: always exits 0, never raises. Designed to be
  ## run from a detached background process (it is a no-op if the shared
  ## bare is absent or the repo is detached).
  var repoRoot = ""
  var workspaceName = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--repo-root" or arg.startsWith("--repo-root="):
      try: repoRoot = valueFromFlag(args, i, "--repo-root")
      except CatchableError: discard
    elif arg == "--workspace-name" or arg.startsWith("--workspace-name="):
      try: workspaceName = valueFromFlag(args, i, "--workspace-name")
      except CatchableError: discard
    inc i
  if repoRoot.len == 0 or workspaceName.len == 0:
    return 0
  try:
    let repoAbs = absolutePath(repoRoot)
    let workspaceRoot = resolvePostCommitWorkspaceRoot(repoAbs, "")
    if workspaceRoot.len == 0:
      return 0
    let repos = resolveWorkspaceReposForHook(workspaceRoot)
    let matched = findRepoByWorkspacePath(workspaceRoot, repos, repoAbs)
    if matched.isNone:
      return 0
    # HL-6 (§7.2): evidence-only / source-secret repos are EXCLUDED from the
    # eager cache push. Propagating the just-committed branch's objects to
    # sibling workspaces alternated to the same shared bare would LEAK the
    # repo's source objects locally. All other schemes (public / team /
    # personal) keep the eager cache push, so this guard is the ONLY behavior
    # change for a non-evidence repo (byte-identical path otherwise).
    if isEvidenceOnlyRepo(matched.get()):
      return 0
    # The shared bare is keyed by the FULL repo URL (`cloneUrlFor`), matching
    # the sync/init clone path — NOT the bare remote base (`fetchUrl`).
    let fetchUrl = cloneUrlFor(matched.get())
    if fetchUrl.len == 0:
      return 0
    let cacheRoot = defaultCacheRoot(workspaceRoot)
    let bare = sharedBarePath(cacheRoot, fetchUrl)
    # No shared bare on disk → nothing to push into. Common before the
    # first ``init``/``shared-clones rewire`` wires the cache.
    if not dirExists(bare / "objects"):
      return 0
    let gitBin = findExe("git")
    if gitBin.len == 0:
      return 0
    discard pushCacheRef(gitBin, repoAbs, bare, workspaceName)
    # Opportunistic, budget-gated shared-bare maintenance (spec:
    # Workspace-And-Develop-Mode.md §"Cache maintenance: gc / repack"). The
    # post-commit cache-ref push is exactly what accumulates loose objects in
    # the shared bare, and this runs inside the already-detached post-commit
    # process, so a gc/repack + dead-workspace-ref prune here never blocks the
    # commit. ``maintenanceDue`` bounds the pass to the loose-object / age /
    # size budget (at most ~weekly on a quiet cache; fires once on a
    # never-maintained bare, then respects the stamp).
    if maintenanceDue(gitBin, bare, defaultMaintenanceBudget()):
      let live = liveWorkspaceNamesForCache(workspaceRoot)
      discard maintainSharedBare(gitBin, bare, live, defaultMaintenanceBudget())
  except CatchableError:
    discard
  0

proc spawnAsyncCachePush(repoRoot, workspaceName: string) =
  ## Fire a detached, fire-and-forget cache-ref push and return
  ## immediately so the originating commit is never blocked. The child
  ## re-invokes ``repro hooks cache-push`` detached from the parent.
  ## Best-effort: any failure to even launch the child is swallowed.
  ##
  ## The command itself is computed by the pure ``cachePushSpawnCommand``
  ## (POSIX ``setsid … &`` vs Windows ``start /b``); only the host-shell
  ## launch is platform-guarded.
  ##   * POSIX: ``sh -c "setsid … &"`` — new session, stdio to /dev/null.
  ##   * Windows (RA-19): ``cmd /c "start /b …"`` — no new window, returns
  ##     immediately, stdio to NUL.
  if workspaceName.len == 0:
    return
  let myExe = getAppFilename()
  if myExe.len == 0:
    return
  when defined(windows):
    const targetOs = wtWindows
  else:
    const targetOs = wtPosix
  let spec = cachePushSpawnCommand(targetOs, myExe, repoRoot, workspaceName)
  if spec.shellInvocation.len == 0:
    return
  try:
    when defined(windows):
      discard execShellCmd("cmd /c " & q(spec.shellInvocation))
    else:
      discard execShellCmd("sh -c " & q(spec.shellInvocation))
  except CatchableError:
    discard

proc refreshEvidenceOnlyRepoAtPostCommit(workspaceRoot, currentRepoAbs: string):
    string =
  ## HL-6 (§7.1) — best-effort, THROTTLED-on-head-sha post-commit refresh of an
  ## EVIDENCE-ONLY repo's source-free ``WorkspaceVcsEvidence`` triple.
  ##
  ##   * captures NO source: only the head-sha / is-clean / is-published triple
  ##     via ``gatherRepoEvidence`` (``WorkspaceVcsEvidence`` has no source
  ##     field), published through the repo's HL-1-assigned backend
  ##     (``store.putEvidence``);
  ##   * is THROTTLED on head-sha change: the refresh runs ONLY when the repo's
  ##     current head-sha differs from the last published evidence triple's
  ##     head-sha (read back via ``store.getEvidence``). An unchanged head-sha is
  ##     a no-op — one ``putEvidence`` per NEW commit-sha, not per commit event;
  ##   * is best-effort and NEVER blocks the commit: every failure (unreachable
  ##     backend, no checkout, unrouted repo, no evidence-only repo) returns a
  ##     short diagnostic string the caller logs; the hook still exits 0.
  ##
  ## Returns a one-line status the caller folds into the post-commit log/report.
  ## An empty string means "not applicable" (the current repo is not an
  ## evidence-only repo, or there is nothing to do) — a common, silent case.
  let repos = resolveWorkspaceReposForHook(workspaceRoot)
  if repos.len == 0: return ""
  let matched = findRepoByWorkspacePath(workspaceRoot, repos, currentRepoAbs)
  if matched.isNone: return ""
  let repo = matched.get()
  if not isEvidenceOnlyRepo(repo): return ""

  var identity: GitToolIdentity
  try:
    identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
  except CatchableError as err:
    return "evidence refresh skipped: git tool unresolvable (" & err.msg & ")"

  # Resolve the repo's HL-1-assigned backend from the COMPOSED configuration
  # layers (tier-by-layer, §4) — the same resolution the pre-push gate uses, so
  # a route naming the repo by ``repos = [...]`` assigns its tier + backend.
  let composed = composeLockingRouting(workspaceRoot, identity.binaryPath)
  if not hasExplicitRoutes(composed):
    return "evidence refresh skipped: evidence-only repo '" & repo.name &
      "' has no `[[locking.route]]` backend to publish to"
  var store: LockStore = nil
  var projectName = ""
  try:
    let assignments = resolveRepoBackends(
      composed, repos, workspaceRoot, identity, identity.binaryPath)
    for asg in assignments:
      if asg.repoName == repo.name:
        store = asg.store
        break
    projectName = detectWorkspaceProjectName(workspaceRoot)
  except CatchableError as err:
    return "evidence refresh skipped: backend resolution failed for '" &
      repo.name & "' (" & err.msg & ")"
  if store.isNil:
    return "evidence refresh skipped: evidence-only repo '" & repo.name &
      "' has no assigned backend"

  let repoAbs = workspaceRoot / repo.path
  if not dirExists(extendedPath(repoAbs / ".git")):
    return "evidence refresh skipped: evidence-only repo '" & repo.name &
      "' has no local checkout at '" & repo.path & "'"

  # Observe the CURRENT head-sha (source-free) so we can throttle.
  let headRes = queryGitState(headShaQuery(repoAbs), identity)
  if headRes.status != gqsOk or headRes.headSha.len == 0:
    return "evidence refresh skipped: could not observe head-sha for '" &
      repo.name & "'"
  let currentHead = headRes.headSha

  # THROTTLE: read the last PUBLISHED evidence triple's head-sha and no-op when
  # it is unchanged. Any read failure is treated as "no prior evidence" so the
  # first publish still happens (best-effort — never blocks).
  var lastHead = ""
  try:
    let prior = store.getEvidence(projectName, repo.name)
    if prior.len > 0:
      lastHead = evidenceTriple(prior).headSha
  except CatchableError:
    lastHead = ""
  if lastHead.len > 0 and lastHead == currentHead:
    return "evidence refresh throttled: '" & repo.name &
      "' head-sha unchanged (" & currentHead & ")"

  # Gather + publish the source-free triple (NO source captured).
  try:
    let toolDigest = digestHex(identity)
    let rName = gitRemoteNameFor(repo)
    let triple = gatherRepoEvidence(
      identity, repoAbs, repo.path, toolDigest, getTime().toUnix * 1000, remoteName = rName)
    let put = store.putEvidence(projectName, repo.name, triple)
    if put.outcome == spoOk:
      return "evidence refreshed: '" & repo.name & "' at head-sha " & currentHead
    else:
      return "evidence refresh failed: putEvidence for '" & repo.name &
        "': " & put.diagnostic
  except CatchableError as err:
    return "evidence refresh failed: '" & repo.name & "' (" & err.msg & ")"

# ---- M19b: post-commit publication probe (local-only) -------------------
#
# Answers "did the record this run wrote actually reach anyone?" using only
# LOCAL git state. Post-commit must not require the network, so "published"
# here means "present in the store's last-fetched remote-tracking ref". That
# is the strongest claim a local-only hook is entitled to make, and it is
# strictly stronger than the claim the old ``ok wrote <path>`` made, which was
# none at all.
#
# It also counts the store's BACKLOG for the trigger repo, and within that the
# STRANDED records: pending records whose trigger commit is already published
# in the trigger repo. A stranded record is not "publication has not happened
# yet" — it is "a push went out and left its lock behind", i.e. proof that the
# publication path is broken. That distinction is what separates the designed
# steady state (quiet) from the two-week starvation (loud), without inventing
# an arbitrary backlog threshold.

const PostCommitBacklogScanLimit = 256
  ## Bound on how many backlog records the probe inspects. A post-commit hook
  ## may not turn into an unbounded git-call loop on a store with years of
  ## history; the counts saturate at this bound and the diagnostic says so.

type
  PostCommitPublicationProbe = object
    state: PostCommitPublication
    detail: string       ## Why the store is/is not publishable, when relevant.
    pending: int
    stranded: int
    saturated: bool

proc lockStoreUpstreamRef(identity: GitToolIdentity; storeRoot: string): string =
  ## The store's upstream tracking ref (``origin/main``), or "" when the store
  ## has no upstream. Read-only, no network.
  let res = gitRunPlain(identity,
    ["-C", storeRoot, "rev-parse", "--abbrev-ref",
     "--symbolic-full-name", "@{u}"])
  if res.code != 0: return ""
  res.output.strip()

proc pathIsInGitTree(identity: GitToolIdentity; repoRoot, treeish,
                     relPath: string): bool =
  ## Is ``relPath`` present in ``treeish``? ``git cat-file -e`` is the cheapest
  ## existence probe and touches no working tree.
  gitRunPlain(identity,
    ["-C", repoRoot, "cat-file", "-e",
     treeish & ":" & relPath.replace('\\', '/')]).code == 0

proc probePostCommitPublication(identity: GitToolIdentity;
                                storeRoot, lockFilePath, triggerRepoRoot: string):
                                PostCommitPublicationProbe =
  ## Classify the record at ``lockFilePath`` inside the lock store at
  ## ``storeRoot``, and count the trigger repo's backlog alongside it. Never
  ## raises and never fetches; any git failure degrades to ``pcpUnknown``
  ## rather than to a success.
  result.state = pcpUnknown
  if lockFilePath.len == 0:
    result.state = pcpNoRecord
    return
  if storeRoot.len == 0:
    result.state = pcpLocalOnly
    result.detail = "no lock store is configured for this workspace"
    return

  # Publishability uses the SAME two preconditions ``publishWorkspaceLock``
  # applies, so the probe cannot claim "pending" for a store the publisher
  # would decline as ``lpoNotPublishable``. In particular the default
  # ``<workspace>/.repro/manifests`` layer is a plain directory nested inside
  # the workspace's own checkout: git's upward discovery answers for the
  # ENCLOSING repo, so "is a git checkout" is not enough — it must BE the
  # worktree root.
  let worktree = discoverGitWorktree(identity, storeRoot)
  if not worktree.ok:
    result.state = pcpLocalOnly
    result.detail = "lock store '" & storeRoot & "' is not a git checkout"
    return
  if not samePathIdentity(worktree.worktreeRoot, storeRoot):
    result.state = pcpLocalOnly
    result.detail = "lock store '" & storeRoot &
      "' is not its own git checkout (it lives inside '" &
      worktree.worktreeRoot & "'), so it has nothing to publish to"
    return
  let upstream = lockStoreUpstreamRef(identity, storeRoot)
  if upstream.len == 0:
    result.state = pcpLocalOnly
    result.detail = "lock store '" & storeRoot & "' has no upstream (@{u})"
    return

  let storeRel = relativePath(lockFilePath, storeRoot).replace('\\', '/')
  if storeRel.len == 0 or storeRel.startsWith(".."):
    result.detail = "lock record '" & lockFilePath &
      "' is not inside the lock store '" & storeRoot & "'"
    return

  result.state =
    if pathIsInGitTree(identity, storeRoot, upstream, storeRel): pcpPublished
    else: pcpPending
  result.detail = "upstream " & upstream

  # Backlog + stranded counts, scoped to the trigger repo's own lock directory
  # (``locks/<project>/<repo>/``) — the directory this run just wrote into, and
  # the only one whose trigger SHAs we can resolve against a checkout we hold.
  let recordDir = parentDir(lockFilePath)
  if not dirExists(recordDir): return
  let dirRel = relativePath(recordDir, storeRoot).replace('\\', '/')
  var scanned = 0
  for entry in walkDir(recordDir):
    if entry.kind notin {pcFile, pcLinkToFile}: continue
    let base = extractFilename(entry.path)
    if not base.endsWith(".toml"): continue
    if scanned >= PostCommitBacklogScanLimit:
      result.saturated = true
      break
    inc scanned
    if pathIsInGitTree(identity, storeRoot, upstream, dirRel & "/" & base):
      continue
    inc result.pending
    # Stranded: the commit this record is anchored to is ALREADY published in
    # the trigger repo, so the push that carried it did not carry the lock.
    if triggerRepoRoot.len == 0: continue
    let sha = base[0 ..< base.len - ".toml".len]
    if sha.len < 7: continue
    if gitRunPlain(identity,
        ["-C", triggerRepoRoot, "merge-base", "--is-ancestor", sha,
         "@{u}"]).code == 0:
      inc result.stranded

proc runPostCommitLockCommand*(args: openArray[string]): int =
  ## ``repro hooks dispatch post-commit --repo-root=<repo>`` (and the
  ## operator-facing manual entry point) routes here. The M19 policy is
  ## "best-effort": every failure is captured into the JSON report +
  ## the log file, and the process exits 0 so the originating commit
  ## never sees a non-zero hook status. RA-4 additionally fires a
  ## detached, non-blocking cache-ref push (see ``spawnAsyncCachePush``).
  let parsed = parsePostCommitArgs(args)
  let timestamp = isoTimestampNow()
  let workspaceRoot = resolvePostCommitWorkspaceRoot(
    parsed.currentRepo, parsed.workspaceRoot)

  var report: PostCommitReport
  report.workspaceRoot = workspaceRoot
  report.currentRepo = parsed.currentRepo
  report.timestamp = timestamp
  report.exitCode = 0

  # `post-commit` shares `post-checkout`'s exposure: git fires it for EVERY
  # commit a rebase, a `git am` or a sequencer run replays (observed live,
  # with `rebase-merge` + `CHERRY_PICK_HEAD` present each time). Everything
  # below writes `repro.lock` into the working tree and spawns a ref push —
  # into a tree mid-rebase, on a detached HEAD, for a commit the operation is
  # about to discard. The post-rebase lock is not lost by standing down: the
  # pre-push gate refreshes it before anything is published.
  let postCommitRepo =
    if parsed.currentRepo.len > 0: parsed.currentRepo
    else: getCurrentDir()   # the managed hook body cd's to the repo root
  let standDown = managedHookStandDown("post-commit", postCommitRepo)
  if standDown.standDown:
    let anchor =
      if workspaceRoot.len > 0: workspaceRoot
      else: enclosingReproShell(parsed.currentRepo)
    report.workspaceRoot = anchor
    report.outcome = postCommitOutcomeTag(
      if standDown.loud: pcoInertGitStateUnknown else: pcoSkippedGitOperation)
    report.publication = postCommitPublicationTag(pcpNoRecord)
    report.diagnostic = standDown.report
    if anchor.len > 0:
      writePostCommitReport(anchor, report)
      appendPostCommitLog(anchor,
        timestamp & " " & report.outcome & " " & report.diagnostic)
    if standDown.loud:
      stderr.writeLine("repro " & standDown.report)
    return 0

  # RA-10: no-op outside an initialized workspace. The post-commit hook
  # may be installed under a half-bootstrapped or non-workspace parent —
  # a plain git repo, or a bare ``.repo/`` with no resolved manifest
  # checkout. We use the canonical ``isInitializedWorkspace`` marker
  # (resolved manifest checkout OR a ``workspace.toml``) rather than a
  # bare ``fileExists(.repo/workspace.toml)`` so a workspace that resolves
  # from a single ``projects/*.toml`` (no metadata-only workspace.toml
  # yet) still runs, while a genuine non-workspace skips silently. A
  # commit must never be blocked by hook failure, so this always exits 0.
  if workspaceRoot.len == 0 or not isInitializedWorkspace(workspaceRoot):
    # No workspace to enforce — but still leave a trace. When the walk found no
    # workspace at all, the report is filed at the nearest ``.repro/`` shell
    # above the repo (a half-bootstrapped parent), which is where an operator
    # looking for one would go. Silence here is what turned this branch into a
    # black hole in the field.
    let reportAnchor =
      if workspaceRoot.len > 0: workspaceRoot
      else: enclosingReproShell(parsed.currentRepo)
    report.workspaceRoot = reportAnchor
    report.outcome = postCommitOutcomeTag(pcoSkippedNoWorkspace)
    report.publication = postCommitPublicationTag(pcpNoRecord)
    report.diagnostic =
      if reportAnchor.len == 0:
        "no workspace root found from --current-repo=" & parsed.currentRepo
      else:
        "not a workspace; nothing to enforce (no resolved manifest " &
          "checkout at " & reportAnchor & ")"
    if reportAnchor.len > 0:
      writePostCommitReport(reportAnchor, report)
      appendPostCommitLog(reportAnchor,
        timestamp & " " & report.outcome & " " & report.diagnostic)
    return 0

  # RA-4: fire the detached cache-ref push independently of the lock
  # refresh. It is best-effort and non-blocking — the originating commit
  # has already landed and a failed/absent shared bare is a silent no-op.
  # We use the post-commit repo (``--current-repo``) as the push source
  # and the workspace directory's basename as the namespace.
  if parsed.currentRepo.len > 0:
    spawnAsyncCachePush(absolutePath(parsed.currentRepo),
      extractFilename(workspaceRoot.strip(leading = false, trailing = true,
        chars = {'/'})))

  # HL-6 (§7.1): best-effort, THROTTLED-on-head-sha refresh of the current
  # repo's source-free evidence triple when it is an EVIDENCE-ONLY repo. This
  # keeps the published evidence fresh between commits without depending solely
  # on the manual ``repro workspace publish-evidence`` verb. It captures NO
  # source, runs at most once per NEW head-sha, and — like every other
  # post-commit action — never blocks the commit: every outcome (including
  # "not applicable" / failure) is folded into the post-commit log and the hook
  # still exits 0.
  if parsed.currentRepo.len > 0:
    let evidenceStatus = refreshEvidenceOnlyRepoAtPostCommit(
      workspaceRoot, absolutePath(parsed.currentRepo))
    if evidenceStatus.len > 0:
      appendPostCommitLog(workspaceRoot, timestamp & " evidence " &
        evidenceStatus)

  # Build the strict M11 args from the dispatched argv and invoke the
  # M11 executor in-process. Any raise is downgraded to ``pcoNoLockFailed``.
  var lockArgs: WorkspaceLockArgs
  lockArgs.workspaceRoot = workspaceRoot
  lockArgs.triggerSha = parsed.triggerSha
  lockArgs.triggerRepo = parsed.triggerRepo
  # RA-30 — anchor the lock at the repo whose commit fired this hook.
  # git hands a post-commit hook a working directory, never a manifest
  # name, so we pass the PATH and let the resolver map it to the declared
  # repo. Leaving this empty made every post-commit lock fall through to
  # ``pickTriggerRepo``'s project-named anchor: six ``ok`` runs across
  # several repos in one workspace produced three records, all filed under
  # ``locks/reprobuild/reprobuild/<sha>`` at reprobuild's own SHAs. CI
  # resolves ``locks/<project>/<repo>/<sha>`` for the commit under test, so
  # for a commit in any repo but the anchor that path could never exist —
  # the write succeeded and the record was unreachable.
  lockArgs.triggerRepoPath =
    if parsed.currentRepo.len > 0: absolutePath(parsed.currentRepo)
    else: ""
  lockArgs.toolProvisioning = parsed.toolProvisioning
  # RA-10: an initialized workspace may resolve from a single
  # ``projects/*.toml`` with no metadata-only ``workspace.toml`` yet. The
  # strict lock resolver needs an explicit project name in THAT case — and
  # only that case.
  #
  # Supplying it unconditionally was NOT harmless. A non-empty
  # ``projectName`` sends ``resolveWorkspaceLockProject`` down its explicit
  # named-project branch, and that branch deliberately does NOT union the
  # active project set: an operator who names a project is asking for that
  # project. Post-commit was naming one nobody asked for, so in a
  # multi-project workspace every commit in a repo outside the PRIMARY
  # project was resolved against the primary's repo set alone and the lock
  # refused —
  #
  #   triggering repo at '<repo>' is not declared in project '<primary>';
  #   no lock can be anchored at it
  #
  # — silently, because post-commit never blocks. A lock with no ``<project>``
  # is a snapshot of the WORKSPACE and pins every repo of the active set,
  # which is exactly what a commit hook wants. So we let the workspace speak
  # for itself whenever it can, and name a project only when it cannot.
  lockArgs.projectName = ""
  block resolveProjectNameOnlyWhenNeeded:
    let workspaceToml = workspaceTomlPath(workspaceRoot)
    var recorded = ""
    if fileExists(workspaceToml):
      try:
        recorded = readWorkspaceLocal(
          absolutePath(workspaceToml)).workspace.project
      except CatchableError:
        discard
    if recorded.len == 0:
      lockArgs.projectName = detectWorkspaceProjectName(workspaceRoot)

  var raised = false
  var raisedDiagnostic = ""
  var outcome: WorkspaceLockOutcome
  try:
    outcome = executeWorkspaceLock(lockArgs)
  except CatchableError as err:
    raised = true
    raisedDiagnostic = err.msg

  if raised:
    # M19b mode 3: no lock exists. The commonest instance of this branch is
    # ``repo '<x>' has no on-disk checkout``, which in one workspace produced
    # 68 consecutive attempts and zero locks while every one of them exited 0
    # in silence. Say what did not happen, and say it at the terminal.
    report.outcome = postCommitOutcomeTag(pcoNoLockFailed)
    report.publication = postCommitPublicationTag(pcpNoRecord)
    report.diagnostic = "NO lock written: " & raisedDiagnostic
    writePostCommitReport(workspaceRoot, report)
    appendPostCommitLog(workspaceRoot,
      timestamp & " " & report.outcome & " " & report.diagnostic)
    emitPostCommitWarning(report.outcome, report.diagnostic, workspaceRoot)
    return 0

  report.project = outcome.report.project
  report.lockFilePath = outcome.report.lockFilePath
  report.indexFilePath = outcome.report.indexFilePath
  report.triggerRepo = outcome.report.triggerRepo
  report.triggerSha = outcome.report.triggerSha

  var loud = true
  case outcome.report.exitCode
  of 0:
    report.lockWritten = outcome.report.lockFilePath.len > 0
    # M19b mode 1 — THE defect. The old code stopped here with
    # ``outcome = "ok"`` and ``diagnostic = "wrote <path>"``, which is a claim
    # about a filesystem, not about a lock store. Probe what actually reached
    # the store's upstream and report THAT.
    var probe: PostCommitPublicationProbe
    # Unproven until proven otherwise: a probe that cannot run must never
    # decay into a success. The one state we can assert without git is "this
    # run wrote no manifest record at all".
    probe.state =
      if outcome.report.lockFilePath.len == 0: pcpNoRecord else: pcpUnknown
    # The backlog lives under ``locks/<project>/<triggerRepo>/``, so the
    # ancestry test for a stranded record must run against the TRIGGER repo's
    # checkout — which is not necessarily ``--current-repo``: the anchor is
    # picked by ``pickTriggerRepo`` (project-named repo, else the first
    # declared one) and post-commit passes no explicit trigger. Resolve it from
    # the locked entries, where each repo's declared path is recorded, and
    # leave it empty if it cannot be resolved (the counts then stay at 0
    # rather than being computed against the wrong repository).
    var triggerRepoRoot = ""
    for entry in outcome.report.repos:
      if entry.name == outcome.report.triggerRepo:
        triggerRepoRoot = workspaceRoot / entry.path
        break
    try:
      let identity = ensureGitToolResolvable(
        parsed.toolProvisioning, getEnv("PATH"))
      probe = probePostCommitPublication(identity,
        outcome.report.manifestLayerRoot, outcome.report.lockFilePath,
        triggerRepoRoot)
    except CatchableError as err:
      probe.detail = err.msg
    report.publication = postCommitPublicationTag(probe.state)
    report.pendingRecords = probe.pending
    report.strandedRecords = probe.stranded

    let backlog =
      if probe.pending > 0:
        "; " & $probe.pending & (if probe.saturated: "+" else: "") &
          " unpublished record(s) for '" & outcome.report.triggerRepo &
          "' in the store" &
          (if probe.stranded > 0:
            ", " & $probe.stranded &
              " of them anchored to ALREADY-PUSHED commits — publication " &
              "is not merely pending, it is not running"
          else: "")
      else: ""
    case probe.state
    of pcpPublished:
      # The only success tag: the record is demonstrably in the store's
      # upstream, not merely on this disk.
      report.outcome = postCommitOutcomeTag(pcoPublished)
      report.diagnostic = "published " & outcome.report.lockFilePath &
        " (" & probe.detail & ")"
      loud = false
    of pcpPending:
      report.outcome = postCommitOutcomeTag(pcoWrittenPending)
      report.diagnostic = "wrote " & outcome.report.lockFilePath &
        " — NOT published (" & probe.detail &
        "); post-commit is local-only, publication happens at pre-push or " &
        "`repro workspace lock`" & backlog
      # The designed steady state (Workspace-Manifests.md publish table) is
      # quiet; a backlog of records stranded behind pushes that already went
      # out is not the steady state and is not quiet.
      loud = probe.stranded > 0
    of pcpLocalOnly:
      report.outcome = postCommitOutcomeTag(pcoWrittenLocalOnly)
      report.diagnostic = "wrote " & outcome.report.lockFilePath &
        " — NOT published and never will be: " & probe.detail &
        "; this record exists on this machine only"
      # A workspace with no publishable store is a benign configuration, not
      # an incident (``lpoNotPublishable`` is a skip, not a failure), so this
      # states itself in the log on every commit but does not shout at the
      # terminal on every commit. It is no longer ``ok``, which is the part
      # that was lying.
      loud = false
    of pcpNoRecord:
      # HL-2 §6 Decision 1 / §8.4 "public-only workspace": no monolithic
      # trigger-keyed lock file is written when the workspace declares
      # explicit `[locking]` routes or is public-only (the in-repo
      # ``repro.lock`` is the record). There is nothing for THIS probe to
      # classify, and nothing was claimed to be published.
      report.outcome = postCommitOutcomeTag(pcoNoManifestRecord)
      report.diagnostic = "no manifest lock record for this workspace " &
        "(records are routed per-repo / carried by the in-repo repro.lock); " &
        "nothing published by post-commit, which is local-only"
      loud = false
    of pcpUnknown:
      report.outcome = postCommitOutcomeTag(pcoWrittenUnknown)
      report.diagnostic = "wrote " & outcome.report.lockFilePath &
        " — publication state UNPROVEN" &
        (if probe.detail.len > 0: " (" & probe.detail & ")" else: "") &
        "; treat this record as unpublished"
    # Best-effort write of the M11 lock-report.json so a manual
    # invocation matches the operator-facing surface. The post-commit
    # hook is driven by git, not by an operator-supplied argv, so there
    # is no ``--write-report`` surface to consult here: it keeps writing to the
    # conventional location unconditionally.
    try:
      writeWorkspaceLockReport(outcome.report,
        outcome.report.workspaceRoot / ".repro" / "workspace" /
          "lock-report.json")
    except CatchableError: discard
  of 2:
    # M19b mode 2. Strict M11 exit-2 = a repo in scope has uncommitted
    # changes, so NO lock was written.
    #
    # Why the refusal is KEPT (and not downgraded to "lock the dirty repo's
    # HEAD anyway"): a lock's whole contract is that checking out the recorded
    # revisions reproduces the state it was taken from. A dirty repo's HEAD
    # does not reproduce the tree that was observed, so a lock recorded over it
    # is not a weaker lock, it is a false one — and it is false in the
    # direction that matters, because the consumer (CI sibling resolution)
    # cannot tell the difference. Recording it would trade a visible gap for an
    # invisible lie.
    #
    # What was actually wrong here was never the refusal; it was that the
    # refusal was inaudible. Two weeks of "skipped-dirty … exit 0" scrolled
    # past in a log nobody reads while the blocker rotated between siblings, so
    # clearing one never revealed the next. It is now loud, and it names the
    # repos to clear.
    report.outcome = postCommitOutcomeTag(pcoNoLockDirty)
    report.publication = postCommitPublicationTag(pcpNoRecord)
    var dirtyNames: seq[string]
    for e in outcome.report.dirty: dirtyNames.add(e.path)
    report.diagnostic = "NO lock written: dirty sibling(s): " &
      dirtyNames.join(", ") &
      " — a lock recorded over uncommitted changes would not reproduce the " &
      "tree it claims; commit or stash them, then run `repro workspace lock`"
  else:
    report.outcome = postCommitOutcomeTag(pcoNoLockFailed)
    report.publication = postCommitPublicationTag(pcpNoRecord)
    report.diagnostic = "NO lock written: executeWorkspaceLock returned " &
      "exit code " & $outcome.report.exitCode

  writePostCommitReport(workspaceRoot, report)
  appendPostCommitLog(workspaceRoot,
    timestamp & " " & report.outcome & " " & report.diagnostic)
  if loud:
    emitPostCommitWarning(report.outcome, report.diagnostic, workspaceRoot)
  return 0

# ---- M19a: post-merge / post-checkout manifest auto-refresh ---------------
#
# The M17-installed post-merge and post-checkout hook dispatchers route
# here via ``repro hooks dispatch <hook-name> --repo-root <repo> --
# <hook-args>``. Semantics mirror M19's post-commit wrapper:
#
#   - The hook NEVER blocks the originating git operation. Every error,
#     skip, or success is captured as one line in
#     ``$HOME/.cache/repro/manifest-refresh.log`` and the process exits
#     0 unconditionally.
#   - For ``post-checkout``, git supplies three positional args:
#     ``<prev-head> <new-head> <flag>``. When ``prev == new`` the
#     participating repo's HEAD did NOT move (a path-only checkout)
#     and the spec mandates we skip SILENTLY — no log line.
#   - For ``post-merge``, git supplies one positional arg (the squash
#     flag). It is not load-bearing for the refresh decision; we accept
#     it and ignore.
#   - When the workspace root cannot be located (the participating repo
#     is outside any ``.repo/``-rooted workspace), we skip silently with
#     a single log line so the operator can correlate against the log.
#   - The actual fast-forward semantics live in M10's
#     ``refreshManifestLayers``; this wrapper just downgrades raises and
#     translates per-layer ``ManifestLayerRefreshStatus`` values into
#     append-only log lines.

const manifestRefreshLogFile = "manifest-refresh.log"

proc manifestRefreshCacheLogPath(): string =
  ## ``$HOME/.cache/repro/manifest-refresh.log`` on POSIX; the
  ## XDG-style cache root on every host. ``getHomeDir`` already returns
  ## the right value on Windows (``%USERPROFILE%``), so the same
  ## layout works there.
  let xdg = getEnv("XDG_CACHE_HOME")
  let cacheRoot =
    if xdg.len > 0: xdg
    else: getHomeDir() / ".cache"
  cacheRoot / "repro" / manifestRefreshLogFile

proc appendManifestRefreshLog(line: string) =
  ## Append a single line to the manifest-refresh log. Never raises —
  ## a failed log write must not block the originating git operation.
  try:
    let logPath = manifestRefreshCacheLogPath()
    createDir(parentDir(logPath))
    var f: File
    if open(f, logPath, fmAppend):
      f.writeLine(line)
      f.close()
  except CatchableError:
    discard

proc parseManifestRefreshArgs(args: openArray[string]):
    tuple[currentRepo, workspaceRoot: string; positional: seq[string]] =
  ## Minimal argv parser for the post-merge / post-checkout wrappers.
  ## The dispatcher in ``runHooksDispatchCommand`` has already peeled
  ## off ``--repo-root`` (and any other flag the canonical hook body
  ## forwards), then placed the remaining hook-supplied positional
  ## args (``post-merge`` ``<squash-flag>`` / ``post-checkout``
  ## ``<prev> <new> <flag>``) after ``--``. Unknown flags are silently
  ## ignored — the hook must never raise on argv shape.
  var sawDoubleDash = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if not sawDoubleDash:
      if arg == "--":
        sawDoubleDash = true
        inc i
        continue
      if arg == "--current-repo" or arg.startsWith("--current-repo="):
        try: result.currentRepo = valueFromFlag(args, i, "--current-repo")
        except CatchableError: discard
      elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
        try: result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
        except CatchableError: discard
      # Tolerate other flags (forward-compat) without recording them.
    else:
      result.positional.add(arg)
    inc i

proc reconcileLocalStateAfterHook(hookName, workspaceRoot,
                                  timestamp: string) =
  ## Workspace-Membership-Model.md — the automatic half of local-state
  ## migration, run on the SAME hooks that already react to "the manifest may
  ## have moved". That is the whole point: a developer who already has the
  ## workspace checked out should need no more than `git pull`, and `git pull`
  ## is precisely what fires `post-merge`.
  ##
  ## Three properties this must not lose, all of them the hook contract's:
  ## it never blocks (the caller returns 0 regardless), it never raises
  ## (`reconcileLocalStateForHook` catches everything), and it is SILENT when
  ## the workspace is already consistent — which is the steady state after the
  ## first pull, so the noisy case is the rare one.
  ##
  ## When it does act it reports to stderr as well as the log. Rewriting
  ## somebody's git remotes without telling them is not an acceptable thing
  ## for a hook to do quietly, and the log alone is a place nobody looks until
  ## after they are already confused.
  ##
  ## The `quiet` half is the mirror image: states the hook OBSERVED and chose
  ## not to act on, chief among them a detached HEAD, which this arm no longer
  ## reattaches. They go to the log and not to stderr — the developer detached
  ## that HEAD themselves, and a hook that reads it back to them after every
  ## git command is a hook they will turn off.
  if workspaceRoot.len == 0:
    return
  let lines = reconcileLocalStateForHook(workspaceRoot)
  for line in lines.quiet:
    appendManifestRefreshLog(timestamp & " " & hookName &
      " local-state " & line)
  if lines.loud.len == 0:
    return
  stderr.writeLine("repro " & hookName & ": reconciled workspace-local git " &
    "state against the manifest —")
  for line in lines.loud:
    stderr.writeLine("  " & line)
    appendManifestRefreshLog(timestamp & " " & hookName &
      " local-state " & line)
  stderr.writeLine("  `repro workspace migrate --dry-run` re-reports this " &
    "at any time")

proc runManifestRefreshHookCommand*(hookName: string;
                                    args: openArray[string]): int =
  ## Best-effort manifest-layer refresh for ``post-merge`` /
  ## ``post-checkout`` dispatch. Always returns 0 — the originating git
  ## operation must never see a non-zero hook status. The operator-facing
  ## trace lives in ``$HOME/.cache/repro/manifest-refresh.log``.
  let parsed = parseManifestRefreshArgs(args)
  let timestamp = isoTimestampNow()

  # post-checkout short-circuit #1 — git's own third argument. The contract
  # is explicit: ``1`` is a branch checkout, ``0`` is a file checkout
  # (``git checkout -- <path>``), which retrieves a file from the index and
  # moves no ref at all. Necessary but NOWHERE NEAR sufficient on its own:
  # every ref update a rebase performs is a BRANCH checkout and arrives here
  # with flag ``1``, so this argument cannot see the case that matters.
  if hookName == "post-checkout" and parsed.positional.len >= 3:
    if parsed.positional[2] == "0":
      return 0

  # The discriminator that actually covers the reported case: is git
  # MID-OPERATION? A rebase, an `am`, a sequencer run and a bisect all fire
  # these hooks for their own intermediate ref updates, and everything below
  # this line — the manifest fast-forward and, above all, the local-state
  # reconciliation — is work done to a working tree its owner has not
  # finished with. Answered against the repo git fired the hook IN, not the
  # workspace root: only that checkout knows whether it is mid-rebase.
  #
  # Ordered BEFORE the ``prev == new`` inference below on purpose. Both
  # return 0, but only this one leaves a trace, and the trace is what makes
  # the decision observable. Measured: a linked-worktree rebase can fire its
  # first `post-checkout` with ``prev == new``, so the weaker rule would
  # sometimes swallow the stronger rule's evidence.
  let hookRepo =
    if parsed.currentRepo.len > 0: parsed.currentRepo
    else: getCurrentDir()   # the managed hook body cd's to the repo root
  let standDown = managedHookStandDown(hookName, hookRepo)
  if standDown.standDown:
    appendManifestRefreshLog(timestamp & " " & standDown.report)
    if standDown.loud:
      stderr.writeLine("repro " & standDown.report)
    return 0

  # post-checkout short-circuit #2: when git reports
  # ``<prev-head> <new-head> <flag>`` with ``prev == new``, the
  # participating repo's HEAD did NOT move and the spec says skip
  # SILENTLY (no log line). An inference rather than a contract, which is
  # why it is not the thing standing between a rebase and this hook.
  if hookName == "post-checkout" and parsed.positional.len >= 2:
    let prev = parsed.positional[0]
    let newer = parsed.positional[1]
    if prev.len > 0 and prev == newer:
      return 0

  let workspaceRoot = resolvePostCommitWorkspaceRoot(
    parsed.currentRepo, parsed.workspaceRoot)

  if workspaceRoot.len == 0:
    appendManifestRefreshLog(timestamp & " " & hookName &
      " skipped: no workspace root reachable from --current-repo=" &
      parsed.currentRepo)
    return 0

  let workspaceToml = workspaceTomlPath(workspaceRoot)
  if not fileExists(workspaceToml):
    # No workspace.toml means M6/M7 single-project mode (or a freshly-
    # initialised .repro): nothing to refresh. Log once so the operator
    # can correlate; never raise.
    appendManifestRefreshLog(timestamp & " " & hookName &
      " skipped: no workspace.toml at " & workspaceRoot)
    reconcileLocalStateAfterHook(hookName, workspaceRoot, timestamp)
    return 0

  var report: ManifestRefreshReport
  try:
    report = refreshManifestLayers(workspaceRoot)
  except CatchableError as err:
    appendManifestRefreshLog(timestamp & " " & hookName &
      " fetch failed: " & err.msg & " (workspace=" & workspaceRoot & ")")
    reconcileLocalStateAfterHook(hookName, workspaceRoot, timestamp)
    return 0

  if report.layers.len == 0:
    # workspace.toml exists but declares no [[manifest]] layers — the
    # M9-init single-project metadata-only shape, which is also the FLAT
    # shape a manifest repo at the workspace root produces. Nothing to
    # refresh, but the checkouts still have to be reconciled: that shape is
    # exactly the one whose manifests arrive by a plain `git pull`.
    appendManifestRefreshLog(timestamp & " " & hookName &
      " noop: workspace declares no manifest layers (" &
      workspaceRoot & ")")
    reconcileLocalStateAfterHook(hookName, workspaceRoot, timestamp)
    return 0

  for entry in report.layers:
    let tag = manifestLayerStatusTag(entry.status)
    case entry.status
    of mrsRefreshed:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " manifest refreshed: " & entry.beforeSha & " -> " &
        entry.afterSha & " (layer=" & entry.provenance & ")")
    of mrsUpToDate:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " manifest already current at " & entry.afterSha &
        " (layer=" & entry.provenance & ")")
    of mrsSkippedLocal:
      # Local-path layers are operator-maintained; the spec says they
      # are not the workspace's job to refresh. Stay quiet — no log
      # line — so the cache log stays focused on actionable signals.
      discard
    of mrsSkippedAbsent:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " layer checkout not present yet (layer=" & entry.provenance &
        "); next `repro workspace sync` will materialise it")
    of mrsSkippedDirty:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " manifest dirty, refresh deferred (layer=" & entry.provenance &
        "): " & entry.diagnostic)
    of mrsSkippedDivergent:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " manifest diverged, refresh deferred (layer=" & entry.provenance &
        "): " & entry.diagnostic)
    of mrsFailed:
      appendManifestRefreshLog(timestamp & " " & hookName & " " & tag &
        " fetch failed (layer=" & entry.provenance & "): " &
        entry.diagnostic)

  reconcileLocalStateAfterHook(hookName, workspaceRoot, timestamp)
  return 0

# ---- M18 / M23 / M26: `repro check --mode=pre-push` (publication gate) ----
#
# The installed pre-push hook (M17 dispatcher) routes into the gate by
# calling ``repro check --mode=pre-push --current-repo=PATH
# --pushed-refs=FILE``. The gate runs five checks in order; the first
# failure short-circuits with a structured ``CheckFailure`` record:
#
# RA-3 removed the former first stage, ``branch-mismatch`` (pushed local
# branch != active workspace branch). repo-workspaces deleted that check
# (`b5a823a`, `ff76825`): heterogeneous per-class branch policies are
# first-class (product repos on ``dev``, spec repos on ``latest``, infra
# on ``live``) and the lock pins SHAs, so the published state is
# reproducible regardless of which branch each repo is on. The
# ``pushedBranch`` / ``activeBranch`` fields are still observed and
# surfaced in the report for informational purposes, but never gate.
#
#   1. ``dirty``            — any sibling repo has a dirty working tree
#                             (M4 ``isCleanQuery`` evidence).
#   2. ``unpublished``      — any sibling repo's HEAD is not reachable
#                             on a remote (M4 ``isPublishedQuery``).
#   3. ``develop_override_*`` — M23: every M20 develop-mode override
#                             must exist on disk, have a clean working
#                             tree, and have its HEAD published.
#                             Properties:
#                               ``develop_override_missing``
#                               ``develop_override_dirty``
#                               ``develop_override_unpublished``.
#                             Absent ``.repro/develop-overrides.toml``
#                             skips this stage entirely so the gate
#                             stays bit-compatible with workspaces that
#                             have never run ``repro develop``.
#   4. ``lock-stale`` /     — workspace lock missing or any repo's
#      ``lock-failure``        HEAD differs from the locked SHA;
#                             the gate creates / refreshes the lock
#                             (via the M11 ``executeWorkspaceLock``
#                             driver) and only fails when creation
#                             itself fails.
#   5. ``lock_references_private_repo`` — M26: when the push touches
#                             one or more ``locks/<project>/<file>.toml``
#                             files in the current-repo (a manifest-layer
#                             repo) AND that manifest layer is declared
#                             ``visibility = "public"`` in
#                             ``.repo/workspace.toml``, every repo
#                             referenced by the touched locks must be
#                             declared by at least one public manifest
#                             layer. A repo declared ONLY in non-public
#                             layers makes the lock unreproducible for
#                             public-only operators; the gate refuses
#                             the push so the operator either drops
#                             the private references or publishes a
#                             non-public lock instead.
#
# The exit-code contract matches the milestone:
#   - 0 — every check passed (and the lock was created / refreshed
#         if it had been missing or stale).
#   - 2 — any of the five publication-gate checks failed.
#   - 1 — IO / resolve / VCS-tool failure unrelated to the gate logic.

type
  CheckMode* = enum
    cmPrePush

  CheckFailure* = object
    ## One structured failure record per gate failure. ``repo`` is the
    ## workspace-relative path of the offending repo (or the empty
    ## string when the failure is workspace-wide, e.g. a malformed
    ## develop-overrides file); ``property``
    ## is the short tag the spec mandates (
    ## ``dirty`` / ``unpublished`` / ``lock-stale`` /
    ## ``lock-failure`` / ``develop_override_dirty`` /
    ## ``develop_override_unpublished`` / ``develop_override_missing`` /
    ## ``lock_references_private_repo``);
    ## ``remediation`` is the operator-facing next-step the JSON report
    ## and text diagnostic surface. ``source`` is populated by the M23
    ## develop-override stage with the override's filesystem path so
    ## the operator can locate the offending checkout without having to
    ## re-read the override file, and by the M26 lock-visibility stage
    ## with the manifest-layer-relative path of the offending lock file.
    ## For the M18 sibling-repo stages ``source`` is left empty.
    repo*: string
    property*: string
    remediation*: string
    evidence*: string
    source*: string

  CheckLockUpdateKind* = enum
    cluNone           ## No lock action taken (e.g. a pre-push check that
                      ## short-circuited before the lock pass).
    cluAlreadyCurrent ## Lock present and every repo's HEAD matches.
    cluCreated        ## No prior lock existed; the gate created one.
    cluRefreshed      ## Lock existed but was stale; the gate refreshed it.
    cluFailed         ## Lock creation or refresh raised. The failure
                      ## entry carries the structured reason; the gate
                      ## exits with code 2.

  CheckLockUpdate* = object
    kind*: CheckLockUpdateKind
    lockFilePath*: string
    indexFilePath*: string
    triggerRepo*: string
    triggerSha*: string
    diagnostic*: string

  CheckReport* = object
    ## Structured outcome of one ``repro check`` invocation. The JSON
    ## form is written to ``<workspaceRoot>/.repro/build/reports/check-report.json``
    ## and (with ``--json``) also echoed to stdout.
    mode*: string
    workspaceRoot*: string
    project*: string
    activeBranch*: string
    currentRepo*: string
    pushedBranch*: string
    pushedRefsPath*: string
    failures*: seq[CheckFailure]
    # TC-3 / RA-32 — advisory (non-blocking) gate notices. The certificate
    # gate in ``advisory`` mode records its coverage verdict here (a warning
    # when uncovered, a confirmation when covered) WITHOUT ever touching
    # ``exitCode`` — the load-bearing onboarding property (RA-32): advisory
    # never blocks a push. Empty for the default ``off`` mode and for every
    # gate run that predates a certificate policy.
    notices*: seq[string]
    lockUpdate*: CheckLockUpdate
    # RA-7: the manifest-layer checkout that owns the lock subtree, so the
    # caller can publish (commit + push) the just-written lock after a
    # successful gate. Empty when the gate short-circuited before the lock
    # stage (e.g. a dirty sibling).
    manifestLayerRoot*: string
    # HL-3 (§6 Decision 2) — per-repo participation outcomes (tier-tagged) from
    # the lock write, so ``runCheckCommand`` and the JSON report can see WHICH
    # repo's backend was unreachable and at what tier. Empty for a workspace
    # with no explicit routes (the single-tier / manifest-less common shape) and
    # for a gate that short-circuited before the lock write.
    participation*: seq[ParticipationOutcome]
    expectedManifestRecords: seq[ExpectedLockRecord]
    deferredPublishWrites: seq[DeferredParticipationWrite]
    exitCode*: int

proc lockUpdateKindTag(kind: CheckLockUpdateKind): string =
  case kind
  of cluNone: "none"
  of cluAlreadyCurrent: "already-current"
  of cluCreated: "created"
  of cluRefreshed: "refreshed"
  of cluFailed: "failed"

proc toJsonNode*(report: CheckReport): JsonNode =
  result = newJObject()
  result["mode"] = %report.mode
  result["workspaceRoot"] = %report.workspaceRoot
  result["project"] = %report.project
  result["activeBranch"] = %report.activeBranch
  result["currentRepo"] = %report.currentRepo
  result["pushedBranch"] = %report.pushedBranch
  result["pushedRefsPath"] = %report.pushedRefsPath
  var failures = newJArray()
  for failure in report.failures:
    var obj = newJObject()
    obj["repo"] = %failure.repo
    obj["property"] = %failure.property
    obj["remediation"] = %failure.remediation
    obj["evidence"] = %failure.evidence
    obj["source"] = %failure.source
    failures.add(obj)
  result["failures"] = failures
  var notices = newJArray()
  for n in report.notices:
    notices.add(%n)
  result["notices"] = notices
  var lockObj = newJObject()
  lockObj["kind"] = %lockUpdateKindTag(report.lockUpdate.kind)
  lockObj["lockFilePath"] = %report.lockUpdate.lockFilePath
  lockObj["indexFilePath"] = %report.lockUpdate.indexFilePath
  lockObj["triggerRepo"] = %report.lockUpdate.triggerRepo
  lockObj["triggerSha"] = %report.lockUpdate.triggerSha
  lockObj["diagnostic"] = %report.lockUpdate.diagnostic
  result["lockUpdate"] = lockObj
  result["manifestLayerRoot"] = %report.manifestLayerRoot
  var participation = newJArray()
  for p in report.participation:
    var obj = newJObject()
    obj["repo"] = %p.repoName
    obj["path"] = %p.repoPath
    obj["tier"] = %lockingTierLabel(p.tier)
    obj["backendKind"] = %p.backendKind
    obj["backendLocation"] = %p.backendLocation
    obj["recorded"] = %p.recorded
    obj["attempted"] = %p.attempted
    obj["diagnostic"] = %p.diagnostic
    participation.add(obj)
  result["participation"] = participation
  result["exitCode"] = %report.exitCode

proc renderCheckTextLines*(report: CheckReport): seq[string] =
  result.add("repro check: mode=" & report.mode &
    " project=" & report.project &
    " branch=" & (if report.activeBranch.len > 0:
                    report.activeBranch
                  else: "<none>"))
  for failure in report.failures:
    var line = "repro check: " &
      (if failure.repo.len > 0: failure.repo & ": " else: "") &
      failure.property
    if failure.remediation.len > 0:
      line.add(" — " & failure.remediation)
    if failure.evidence.len > 0:
      line.add(" [" & failure.evidence & "]")
    result.add(line)
  for notice in report.notices:
    result.add("repro check: " & notice)
  # A public-only workspace declares no manifest-backed route, so no manifest
  # lock record exists to name (§10 "No implicit team route"): the lock-store
  # path is empty and these lines would read "lock created at " with nothing
  # after it. Report the state only when there is a real record to point at —
  # the in-tree ``repro.lock`` is reported by its own advisory.
  case report.lockUpdate.kind
  of cluNone:
    discard
  of cluAlreadyCurrent:
    if report.lockUpdate.lockFilePath.len > 0:
      result.add("repro check: lock already current at " &
        report.lockUpdate.lockFilePath)
  of cluCreated:
    if report.lockUpdate.lockFilePath.len > 0:
      result.add("repro check: lock created at " &
        report.lockUpdate.lockFilePath)
  of cluRefreshed:
    if report.lockUpdate.lockFilePath.len > 0:
      result.add("repro check: lock refreshed at " &
        report.lockUpdate.lockFilePath)
  of cluFailed:
    result.add("repro check: lock update FAILED: " &
      report.lockUpdate.diagnostic)
  if report.exitCode == 0 and report.failures.len == 0:
    result.add("repro check: OK")

type
  CheckArgs* = object
    mode*: CheckMode
    workspaceRoot*: string
    currentRepo*: string
    pushedRefsPath*: string
    json*: bool
    toolProvisioning*: ToolProvisioningMode
    hookRemoteName*: string
    hookRemoteLocation*: string
    skipCertificateGate*: bool
      ## TC-3 / RA-32 — suppress the certificate-coverage stage of the
      ## pre-push gate. Set ONLY by ``evaluateIssuancePreconditions`` (the
      ## TC-1 issuance path), which REUSES the gate to decide whether a cert
      ## is issuable: issuing a certificate must never itself require a
      ## certificate (a chicken-and-egg that would make a project's FIRST
      ## ``required`` cert un-issuable). The real pre-push hook leaves this
      ## ``false`` so the gate enforces the policy as designed.
    report*: ReportSpec
      ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseCheckMode(value: string): CheckMode =
  case value
  of "pre-push": cmPrePush
  else:
    raise newException(ValueError,
      "unsupported --mode value for `repro check`: " & value &
        " (expected: pre-push)")

proc parseCheckArgs*(args: openArray[string]): CheckArgs =
  ## ``repro check --mode=pre-push [--workspace-root=PATH]
  ## [--current-repo=PATH] [--pushed-refs=FILE]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``. ``--mode``
  ## is REQUIRED — there is no implicit mode in the M18 surface.
  result.toolProvisioning = tpmPathOnly
  var modeSet = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--mode" or arg.startsWith("--mode="):
      result.mode = parseCheckMode(valueFromFlag(args, i, "--mode"))
      modeSet = true
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--current-repo" or arg.startsWith("--current-repo="):
      result.currentRepo = valueFromFlag(args, i, "--current-repo")
    elif arg == "--pushed-refs" or arg.startsWith("--pushed-refs="):
      result.pushedRefsPath = valueFromFlag(args, i, "--pushed-refs")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro check` flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro check`: " & arg)
    inc i
  if not modeSet:
    raise newException(ValueError,
      "`repro check` requires --mode=pre-push (no other modes are " &
        "supported yet)")
  if result.workspaceRoot.len == 0:
    # When invoked from inside a participating repo (the usual hook
    # call site) we walk up from ``--current-repo`` to discover the
    # workspace root. The walk keys on the WORKSPACE, not on a ``.repro/``
    # directory: a built repo has one of its own, so the old ``.repro/``
    # walk stopped at the repo and handed the gate a "workspace" that was
    # really just the repo. Failing that, fall back to the nearest
    # ``.repro/`` shell and then to the current repo itself, so the
    # canonical workspace marker can decide that this is a non-workspace
    # and no-op. Falling back to the process cwd is unsafe for managed
    # hooks: test runners and nested invocations often run from a real
    # workspace while dispatching against an unrelated standalone repo.
    if result.currentRepo.len > 0:
      result.workspaceRoot = enclosingWorkspaceRoot(result.currentRepo)
      if result.workspaceRoot.len == 0:
        result.workspaceRoot = enclosingReproShell(result.currentRepo)
    if result.workspaceRoot.len == 0:
      result.workspaceRoot =
        if result.currentRepo.len > 0: absolutePath(result.currentRepo)
        else: getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)
  if result.currentRepo.len > 0:
    result.currentRepo = absolutePath(result.currentRepo)
  if result.pushedRefsPath.len > 0:
    result.pushedRefsPath = absolutePath(result.pushedRefsPath)

proc resolveCheckProject(parsed: CheckArgs):
    tuple[resolved: ResolvedProject;
          workspaceLocal: Option[WorkspaceLocal]] =
  ## MO-9 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder
  ## (returning the parsed ``WorkspaceLocal`` for the gate's active-branch /
  ## manifest-layer derivation). Same dispatch rule as M11 / M12: composer mode
  ## when ``.repo/workspace.toml`` declares ``[[manifest]]`` layers, otherwise
  ## committed-lock-derived or single-project mode. A metadata-only
  ## workspace.toml (M13) supplies the project name for the single-project
  ## branch.
  resolveWorkspaceProjectShared(parsed.workspaceRoot, "",
    "`repro check --mode=pre-push`")

proc parsePushedBranchFromRefs(refsPath: string): string =
  ## Parse a git ``pre-push`` refs stream. Each line carries
  ## ``<local-ref> <local-sha> <remote-ref> <remote-sha>``; we return
  ## the FIRST non-deleting local branch's short name (``refs/heads/X``
  ## → ``X``). An empty file / a file consisting only of deletions
  ## (``local-sha`` is all zeroes) yields the empty string — the gate
  ## treats that as "no branch claim" and skips the active-branch
  ## comparison. Non-existent files also yield the empty string so the
  ## hook stays robust against an empty stdin redirect.
  if refsPath.len == 0 or not fileExists(refsPath):
    return ""
  let zeroSha = "0000000000000000000000000000000000000000"
  for rawLine in readFile(refsPath).splitLines():
    let line = rawLine.strip()
    if line.len == 0:
      continue
    let parts = line.split(' ')
    if parts.len < 2:
      continue
    let localRef = parts[0]
    let localSha = parts[1]
    if localSha == zeroSha:
      # Branch deletion push — no source ref to attribute to the
      # workspace branch.
      continue
    if localRef.startsWith("refs/heads/"):
      return localRef["refs/heads/".len .. ^1]
    return localRef
  ""

proc deriveCheckActiveBranch(parsed: CheckArgs;
    workspaceLocal: Option[WorkspaceLocal];
    resolved: ResolvedProject): string =
  ## Mirror of M12's ``deriveActiveBranch`` but without per-repo
  ## fallback: the pre-push gate must trust the recorded value rather
  ## than guess from an in-flight checkout. Precedence:
  ##   1. ``.repo/workspace.toml``'s ``[workspace].branch`` (M13).
  ##   2. The ``workspaceLocal`` we already loaded (composer-mode
  ##      shortcut that avoids re-reading the file).
  ##   3. The resolver's ``trunk``.
  try:
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      return recorded.get()
  except WorkspaceManifestParseError:
    discard
  if workspaceLocal.isSome and
      workspaceLocal.get().workspace.branch.isSome and
      workspaceLocal.get().workspace.branch.get().len > 0:
    return workspaceLocal.get().workspace.branch.get()
  resolved.trunk

# ---- M26 helpers: lock-visibility classification --------------------------
#
# The publication gate's fifth stage inspects the manifest-layer repo
# the operator is pushing FROM. The three load-bearing pieces are:
#
#   (a) The on-disk path of every ``[[manifest]]`` layer the workspace
#       declares — needed to (i) tell whether ``--current-repo`` IS one
#       of those layer repos and (ii) read each layer's
#       ``projects/<p>.toml`` to discover which repos the layer declares.
#       Mirrors ``compose.layerDirName`` / ``compose.sanitizeForPath``
#       for ``url``-backed layers and the in-tree path for ``local_path``
#       layers (matching ``pickManifestLayerRoot``'s convention).
#
#   (b) A per-repo-path visibility classification — which manifest layer
#       tiers (``public`` / ``org`` / ``team`` / ``private``) declare
#       each repo path. The M8 composer's merge rule overwrites earlier
#       declarations when the same triple appears again, so we cannot
#       rely on ``ResolvedRepo.visibility`` alone — we re-resolve each
#       layer's project file and aggregate the tier set per path.
#
#   (c) Which lock files in ``locks/<project>/<file>.toml`` are touched
#       by the pushed commits. Computed with ``git diff --name-only``
#       between the remote-sha and the local-sha for each pushed ref;
#       branch-creation pushes (zero remote-sha) fall back to a
#       ``ls-tree`` enumeration of every lock file at the local-sha.

type
  ManifestLayerLocation* = object
    ## One entry per ``[[manifest]]`` layer declared in
    ## ``.repo/workspace.toml``. ``absPath`` is the on-disk directory
    ## that owns the layer's project files and (for the first layer)
    ## the lock files. ``visibility`` is the tier declared on the
    ## ``[[manifest]]`` entry. ``provenance`` is the URL or local-path
    ## string the layer was declared with — used in M26 diagnostics so
    ## the operator can identify the offending layer at a glance.
    index*: int
    absPath*: string
    provenance*: string
    visibility*: WorkspaceVisibility
    sourceUrl*: string
      ## Exact URL declared for a URL-backed manifest layer. Local-path layers
      ## leave this empty: a checkout path is not authority for an alternate
      ## Git push remote.

proc sanitizeManifestUrlForPath(raw: string): string =
  ## Mirror of ``compose.sanitizeForPath`` — the dotted alphanumeric +
  ## dash subset, runs of dashes collapsed, capped at 80 chars, leading
  ## / trailing dashes stripped. Lives here so M26 doesn't take a hard
  ## dependency on a compose-private helper.
  var raw1 = newStringOfCap(raw.len)
  for ch in raw:
    case ch
    of 'A'..'Z', 'a'..'z', '0'..'9', '-', '.', '_': raw1.add(ch)
    else: raw1.add('-')
  var collapsed = newStringOfCap(raw1.len)
  var prevDash = false
  for ch in raw1:
    if ch == '-':
      if not prevDash: collapsed.add(ch)
      prevDash = true
    else:
      collapsed.add(ch)
      prevDash = false
  if collapsed.len > 80:
    collapsed.setLen(80)
  result = collapsed.strip(chars = {'-'}, leading = true, trailing = true)
  if result.len == 0:
    result = "layer"

proc enumerateManifestLayerLocations(workspaceRoot: string;
    workspaceLocal: Option[WorkspaceLocal]):
      seq[ManifestLayerLocation] =
  ## Build a list of on-disk locations for every ``[[manifest]]`` layer
  ## in ``workspaceLocal``. ``url``-backed layers map to
  ## ``<workspaceRoot>/.repo/manifests-<i>-<sanitized>/`` (the same
  ## directory ``compose.acquireUrlLayer`` materialises); ``local_path``
  ## layers map to their literal path (resolved against the workspace
  ## root when relative). The ``visibility`` string from the TOML maps
  ## via the same accept-set the composer uses (``private`` and
  ## ``personal`` collapse to ``wvPersonal``).
  if workspaceLocal.isNone:
    return
  let local = workspaceLocal.get()
  for layerIdx, entry in local.manifest:
    var loc = ManifestLayerLocation(index: layerIdx)
    let visStr = entry.visibility.toLowerAscii()
    case visStr
    of "public": loc.visibility = wvPublic
    of "org": loc.visibility = wvOrg
    of "team": loc.visibility = wvTeam
    of "private", "personal": loc.visibility = wvPersonal
    else:
      # An unknown tier means the workspace.toml is malformed; we still
      # emit an entry (with the default ``wvPublic``) so subsequent gate
      # logic doesn't crash. The strict reader path will surface the
      # actual error to the operator separately.
      loc.visibility = wvPublic
    let hasUrl = entry.url.isSome and entry.url.get().len > 0
    let hasLocal = entry.local_path.isSome and entry.local_path.get().len > 0
    if hasUrl:
      let url = entry.url.get()
      loc.provenance = url
      loc.sourceUrl = url
      let suffix = sanitizeManifestUrlForPath(url)
      loc.absPath = workspaceRoot / ".repro" /
        ("manifests-" & $layerIdx & "-" & suffix)
    elif hasLocal:
      let raw = entry.local_path.get()
      loc.provenance = raw
      if isAbsolute(raw):
        loc.absPath = raw
      else:
        loc.absPath = absolutePath(workspaceRoot / raw)
    else:
      # Malformed entry — keep going so other layers can still be
      # inspected; the strict reader will surface the actual error.
      continue
    result.add(loc)

proc classifyRepoPathVisibility(workspaceRoot: string;
    layerLocations: openArray[ManifestLayerLocation];
    projectName: string): Table[string, set[WorkspaceVisibility]] =
  ## For each ``ResolvedRepo.path`` declared across the union of
  ## manifest layers, return the set of visibility tiers that declare
  ## the path. The result is a path-keyed map ``path -> {tiers}``. A
  ## repo path declared exclusively in non-public tiers (the set
  ## doesn't include ``wvPublic``) is what M26 considers
  ## "private-only" — pushing such a path under a public-layer lock is
  ## the violation the spec blocks.
  result = initTable[string, set[WorkspaceVisibility]]()
  for loc in layerLocations:
    if not dirExists(loc.absPath):
      continue
    let projectFile = loc.absPath / "projects" / (projectName & ".toml")
    if not fileExists(projectFile):
      continue
    var layerResolved: ResolvedProject
    try:
      layerResolved = resolveProject(projectFile)
    except CatchableError:
      # Re-resolution failure here is non-fatal for M26: the strict
      # composer path (the rest of the gate) would already have surfaced
      # any structural issue. Skipping the layer in the visibility map
      # treats it as "no declarations" which is the conservative
      # interpretation — a repo only declared here would NOT be marked
      # as having public visibility, which is the safer default.
      continue
    for repo in layerResolved.repos:
      if repo.path notin result:
        result[repo.path] = {}
      result[repo.path].incl(loc.visibility)

proc findCurrentManifestLayer(layerLocations: openArray[ManifestLayerLocation];
    currentRepoAbs: string): Option[ManifestLayerLocation] =
  if currentRepoAbs.len == 0:
    return none(ManifestLayerLocation)
  for loc in layerLocations:
    if sameFilesystemPath(loc.absPath, currentRepoAbs):
      return some(loc)
  none(ManifestLayerLocation)

proc repoNamesDeclaredByLayer(loc: ManifestLayerLocation;
    projectName: string): HashSet[string] =
  ## Manifest-layer pushes scope sibling checks to the repos declared by the
  ## layer being pushed. A public-layer push must not require unreadable private
  ## layer repos to be cloned or routed; M26 separately rejects any public lock
  ## that references them.
  result = initHashSet[string]()
  if not dirExists(loc.absPath):
    return
  let projectFile = loc.absPath / "projects" / (projectName & ".toml")
  if not fileExists(projectFile):
    return
  let layerResolved = resolveProject(projectFile)
  for repo in layerResolved.repos:
    result.incl(repo.name)

proc visibilityTierLabelLocal(v: WorkspaceVisibility): string =
  ## Local mirror of ``compose.visibilityTierLabel`` — kept private to
  ## this module so M26 diagnostics use the same canonical lowercase
  ## labels the M25 init diagnostics use (``private`` rather than
  ## ``personal``).
  case v
  of wvPublic: "public"
  of wvOrg: "org"
  of wvTeam: "team"
  of wvPersonal: "private"

proc visibilitySetLabel(tiers: set[WorkspaceVisibility]): string =
  ## Render a tier set as a stable ``visibility=<a>+<b>`` string for the
  ## evidence field of the structured failure record. Tier order is
  ## fixed by the enum order so the rendered string is byte-stable
  ## across runs.
  var parts: seq[string]
  for v in [wvPublic, wvOrg, wvTeam, wvPersonal]:
    if v in tiers:
      parts.add(visibilityTierLabelLocal(v))
  parts.join("+")

proc lockPathsTouchedInPush(identity: GitToolIdentity;
    currentRepo, refsPath, projectName: string): seq[string] =
  ## Inspect the git ``pre-push`` refs stream and return the list of
  ## ``locks/<project>/<repo>/<sha>.toml`` paths that the pushed commits
  ## introduce or modify in ``currentRepo``. RA-1 dropped the shared
  ## ``index.toml``; with the index gone the check operates on the
  ## whole per-repo lock path set under ``locks/<project>/`` with no
  ## special-casing.
  ##
  ## Each ref-stream line is ``<local-ref> <local-sha> <remote-ref>
  ## <remote-sha>``. We treat the line specially when:
  ##
  ##   - ``local-sha`` is all-zero (a deletion push) — nothing to
  ##     inspect, skip the line.
  ##   - ``remote-sha`` is all-zero (the branch is being created on
  ##     the remote for the first time) — every lock file present at
  ##     ``local-sha`` is "added" by this push, so we enumerate them
  ##     with ``git ls-tree -r local-sha``.
  ##   - Otherwise, we run ``git diff --name-only remote-sha
  ##     local-sha`` and filter the output to the
  ##     ``locks/<project>/`` prefix.
  ##
  ## Paths returned are repository-root-relative with forward slashes
  ## (the form ``git`` emits). The caller resolves them against
  ## ``currentRepo`` to read the lock file from disk.
  if refsPath.len == 0 or not fileExists(refsPath):
    return
  if not discoverGitWorktree(identity, currentRepo).ok:
    return
  let zeroSha = "0000000000000000000000000000000000000000"
  # RA-32 — a fourth reader of the ``locks/<project>/`` prefix (the reviewer
  # named three). Same rule: the prefix is the ENCODED project component, or the
  # pre-push gate sees no touched lock paths at all.
  let lockPrefix = "locks/" & encodeLockPathSegment(projectName) & "/"
  var seen = initHashSet[string]()
  for rawLine in readFile(refsPath).splitLines():
    let line = rawLine.strip()
    if line.len == 0:
      continue
    let parts = line.split(' ')
    if parts.len < 4:
      continue
    let localSha = parts[1]
    let remoteSha = parts[3]
    if localSha == zeroSha:
      continue
    var emitted: seq[string]
    if remoteSha == zeroSha:
      # Branch creation: every lock file at local-sha is "added".
      let lsRes = gitRunPlain(identity,
        ["-C", currentRepo, "ls-tree", "-r", "--name-only", localSha])
      if lsRes.code != 0:
        continue
      for raw in lsRes.output.splitLines():
        let p = raw.strip()
        if p.startsWith(lockPrefix) and p.endsWith(".toml"):
          emitted.add(p)
    else:
      let diffRes = gitRunPlain(identity,
        ["-C", currentRepo, "diff", "--name-only", remoteSha, localSha])
      if diffRes.code != 0:
        # A diff failure (e.g. the remote-sha is not in the local repo)
        # falls back to enumerating every lock file at local-sha — the
        # conservative answer is "treat every present lock as touched".
        let lsRes = gitRunPlain(identity,
          ["-C", currentRepo, "ls-tree", "-r", "--name-only", localSha])
        if lsRes.code != 0:
          continue
        for raw in lsRes.output.splitLines():
          let p = raw.strip()
          if p.startsWith(lockPrefix) and p.endsWith(".toml"):
            emitted.add(p)
      else:
        for raw in diffRes.output.splitLines():
          let p = raw.strip()
          if p.startsWith(lockPrefix) and p.endsWith(".toml"):
            emitted.add(p)
    for p in emitted:
      if p notin seen:
        seen.incl(p)
        result.add(p)

# (relocated) certificate schema/verifier/transport — moved up so the
# RA-21 pre-push gate (executeCheckPrePush) can call the TC-1 verifier
# and TC-2 reader for the TC-3/RA-32 certificate-coverage stage.

# ============================================================================
# TC-1 — Test certificates: schema + reader/writer + verifier.
#
# A test certificate (``reprobuild.test-certificate.v1``; see
# Test-Certificates.md §"What a certificate attests") is a small record that
# attests: ON PLATFORM ``P``, the test targets ``T`` PASSED, with the repo at
# commit ``C`` and its develop-mode dependency closure clean and at the
# revisions pinned by lock ``L``. The binding fields (``commit`` / ``lock`` /
# ``platform`` / ``targets``) make it CHECKABLE; the ``signature`` is what
# makes it UNFORGEABLE WITHOUT THE KEY.
#
# TC-1 deferral (HONEST): TC-1 ships the schema, issuance, the incremental
# no-op, and the verifier. The ``signature`` is left explicitly UNSIGNED
# (empty ``algorithm`` + empty ``value``) — TC-5 wires the privileged daemon's
# real ed25519 signing and key registration. We NEVER fabricate a signature.
# The verifier below is a COVERAGE verifier (does the cert set cover a
# (commit, lock, platform, targets) tuple); the TC-5 SIGNATURE verifier is a
# separate, additive check.
# ============================================================================

const
  testCertificateSchemaV1* = "reprobuild.test-certificate.v1"
    ## The ``schema`` value every v1 certificate carries.

type
  TestCertificateResult* = enum
    ## The ``result`` field. TC-1 issues a certificate ONLY for ``tcrPassed``;
    ## a run with any failing target yields NO certificate (the attestation is
    ## withheld). ``tcrFailed`` exists so a reader can round-trip a record that
    ## was authored out-of-band, but the issuer never emits one.
    tcrPassed = "passed"
    tcrFailed = "failed"

  TestCertificateSignature* = object
    ## The detached signature over the canonical ``[certificate]`` body.
    ## TC-1 leaves BOTH fields empty (clearly unsigned); TC-5 fills them.
    algorithm*: string   ## e.g. ``ed25519`` once TC-5 lands; "" at TC-1.
    value*: string       ## base64 detached signature; "" at TC-1.

  TestCertificate* = object
    ## One ``reprobuild.test-certificate.v1`` record.
    schema*: string
    project*: string
    repo*: string
    commit*: string      ## exact repo commit the tests ran against (HEAD)
    lock*: string        ## digest of the dependency lock (clean deps)
    platform*: string    ## OS/arch the tests executed on, e.g. ``linux/amd64``
    targets*: seq[string]  ## the targets that PASSED (the covered set)
    result*: TestCertificateResult
    issuedAt*: string    ## RFC3339 UTC timestamp
    issuer*: string      ## who observed/issued, e.g. ``repro-test@<host>``
    keyId*: string       ## which registered key signed (empty until TC-5)
    signature*: TestCertificateSignature

proc isSigned*(cert: TestCertificate): bool =
  ## A certificate is SIGNED only when both the algorithm and the signature
  ## value are present. TC-1 always returns ``false`` (the deliberate,
  ## documented deferral to TC-5).
  cert.signature.algorithm.len > 0 and cert.signature.value.len > 0

proc currentPlatformTag*(): string =
  ## The ``platform`` field for a certificate issued on this host: the
  ## ``<os>/<cpu>`` pair from the same ``hostOS`` / ``hostCPU`` the
  ## ``repro capabilities`` host block reports.
  hostOS & "/" & hostCPU

proc certificateLockDigest*(lockFilePath: string): string =
  ## RA-1/RA-7 reuse: the ``lock`` binding is a content digest of the
  ## workspace lock file the gate resolved as current. We hash the lock
  ## file's bytes with the same ``blake3DomainDigest`` the rest of the CLI
  ## uses for metadata envelopes and prefix the algorithm so the digest is
  ## self-describing (``blake3:<hex>``). An empty / missing path yields the
  ## empty string so the caller can decline to issue rather than bind to a
  ## non-existent lock.
  if lockFilePath.len == 0 or not fileExists(lockFilePath):
    return ""
  let body =
    try: readFile(lockFilePath)
    except CatchableError: return ""
  "blake3:" & digestHex(blake3DomainDigest(body.bytesOf(), hdMetadataEnvelope))

proc tomlEscapeCert(value: string): string =
  ## Local copy of the basic-string escaper (mirrors lock_writer's
  ## ``tomlEscape``) so the certificate writer is self-contained.
  result = newStringOfCap(value.len + 2)
  for ch in value:
    case ch
    of '\\': result.add("\\\\")
    of '"': result.add("\\\"")
    of '\n': result.add("\\n")
    of '\r': result.add("\\r")
    of '\t': result.add("\\t")
    of '\b': result.add("\\b")
    of '\f': result.add("\\f")
    else: result.add(ch)

proc serializeCertificateToToml*(cert: TestCertificate): string =
  ## Render a ``TestCertificate`` to the canonical TOML form documented in
  ## Test-Certificates.md. Key order is fixed and deterministic so two issues
  ## of the same observed state produce byte-identical bodies (modulo the
  ## ``issued_at`` timestamp). ``targets`` is a flat string ARRAY (not a
  ## nested array-of-tables) — the nested-table TOML constraint other
  ## milestones hit does not apply to a scalar list. The ``[certificate]``
  ## body is what TC-5 will sign; the ``[certificate.signature]`` block sits
  ## AFTER it and is excluded from the canonical signing payload.
  result = newStringOfCap(512)
  result.add("schema = \"")
  result.add(tomlEscapeCert(testCertificateSchemaV1))
  result.add("\"\n\n")
  result.add("[certificate]\n")
  template kv(key, value: string) =
    result.add(key & " = \"" & tomlEscapeCert(value) & "\"\n")
  kv("project", cert.project)
  kv("repo", cert.repo)
  kv("commit", cert.commit)
  kv("lock", cert.lock)
  kv("platform", cert.platform)
  # targets as an inline string array, stable order (as observed/run).
  result.add("targets = [")
  for i, t in cert.targets:
    if i > 0: result.add(", ")
    result.add("\"" & tomlEscapeCert(t) & "\"")
  result.add("]\n")
  kv("result", $cert.result)
  kv("issued_at", cert.issuedAt)
  kv("issuer", cert.issuer)
  if cert.keyId.len > 0:
    kv("key_id", cert.keyId)
  # Signature block. TC-1 emits it with empty fields so the on-disk shape is
  # stable for TC-5 (which fills algorithm + value) and so a reader can tell
  # "unsigned" (present, empty) from "absent". This is the explicit deferral.
  result.add("\n[certificate.signature]\n")
  result.add("algorithm = \"" &
    tomlEscapeCert(cert.signature.algorithm) & "\"\n")
  result.add("value = \"" & tomlEscapeCert(cert.signature.value) & "\"\n")

proc canonicalCertificatePayload*(cert: TestCertificate): string =
  ## The canonical serialization of the ``[certificate]`` body (EXCLUDING the
  ## signature block) — the exact bytes TC-5's daemon will sign and the
  ## verifier will check the signature against. Re-uses the writer and slices
  ## off the trailing signature block so the two never drift.
  let full = serializeCertificateToToml(cert)
  let marker = "\n[certificate.signature]\n"
  let idx = full.find(marker)
  if idx >= 0: full[0 ..< idx] else: full

type
  TestCertificateParseError* = object of CatchableError

proc unquoteTomlBasic(raw: string): string =
  ## Reverse of ``tomlEscapeCert`` for the basic-string subset the writer
  ## emits. ``raw`` is the text BETWEEN the surrounding double quotes.
  result = newStringOfCap(raw.len)
  var i = 0
  while i < raw.len:
    let ch = raw[i]
    if ch == '\\' and i + 1 < raw.len:
      let nxt = raw[i + 1]
      case nxt
      of '\\': result.add('\\')
      of '"': result.add('"')
      of 'n': result.add('\n')
      of 'r': result.add('\r')
      of 't': result.add('\t')
      of 'b': result.add('\b')
      of 'f': result.add('\f')
      else: result.add(nxt)
      i += 2
    else:
      result.add(ch)
      inc i

proc parseTomlBasicValue(rhs: string): string =
  ## Extract the unescaped value of a ``key = "..."`` right-hand side.
  let s = rhs.strip()
  if s.len >= 2 and s[0] == '"' and s[^1] == '"':
    unquoteTomlBasic(s[1 ..< s.high])
  else:
    s

proc parseTomlStringArray(rhs: string): seq[string] =
  ## Parse a ``[ "a", "b" ]`` inline string array. Tolerant of whitespace;
  ## the writer always emits the canonical comma-space form.
  var s = rhs.strip()
  if s.len >= 2 and s[0] == '[' and s[^1] == ']':
    s = s[1 ..< s.high]
  var i = 0
  while i < s.len:
    while i < s.len and s[i] in {' ', '\t', ','}: inc i
    if i >= s.len: break
    if s[i] == '"':
      inc i
      var buf = ""
      while i < s.len and s[i] != '"':
        if s[i] == '\\' and i + 1 < s.len:
          buf.add(s[i]); buf.add(s[i + 1]); i += 2
        else:
          buf.add(s[i]); inc i
      inc i  # past closing quote
      result.add(unquoteTomlBasic(buf))
    else:
      inc i

proc parseCertificateFromToml*(content: string): TestCertificate =
  ## Strict-enough reader for a ``reprobuild.test-certificate.v1`` record
  ## that round-trips ``serializeCertificateToToml``. Raises
  ## ``TestCertificateParseError`` on a missing/mismatched schema or a
  ## malformed ``result``. Unknown keys are ignored (forward-compatible).
  result.signature = TestCertificateSignature()
  var inSignature = false
  var sawSchema = false
  for rawLine in content.splitLines():
    let line = rawLine.strip()
    if line.len == 0 or line.startsWith("#"):
      continue
    if line.startsWith("["):
      inSignature = (line == "[certificate.signature]")
      continue
    let eq = line.find('=')
    if eq <= 0: continue
    let key = line[0 ..< eq].strip()
    let rhs = line[eq + 1 .. ^1]
    if key == "schema":
      result.schema = parseTomlBasicValue(rhs)
      sawSchema = true
    elif inSignature:
      case key
      of "algorithm": result.signature.algorithm = parseTomlBasicValue(rhs)
      of "value": result.signature.value = parseTomlBasicValue(rhs)
      else: discard
    else:
      case key
      of "project": result.project = parseTomlBasicValue(rhs)
      of "repo": result.repo = parseTomlBasicValue(rhs)
      of "commit": result.commit = parseTomlBasicValue(rhs)
      of "lock": result.lock = parseTomlBasicValue(rhs)
      of "platform": result.platform = parseTomlBasicValue(rhs)
      of "targets": result.targets = parseTomlStringArray(rhs)
      of "result":
        let r = parseTomlBasicValue(rhs)
        case r
        of "passed": result.result = tcrPassed
        of "failed": result.result = tcrFailed
        else:
          raise newException(TestCertificateParseError,
            "invalid certificate result: '" & r & "'")
      of "issued_at": result.issuedAt = parseTomlBasicValue(rhs)
      of "issuer": result.issuer = parseTomlBasicValue(rhs)
      of "key_id": result.keyId = parseTomlBasicValue(rhs)
      else: discard
  if not sawSchema or result.schema != testCertificateSchemaV1:
    raise newException(TestCertificateParseError,
      "not a " & testCertificateSchemaV1 & " certificate (schema='" &
      result.schema & "')")

proc writeCertificateFile*(cert: TestCertificate; path: string) =
  ## Serialize ``cert`` and write it to ``path`` (creating parent dirs).
  let parent = parentDir(path)
  if parent.len > 0 and not dirExists(parent):
    createDir(parent)
  writeFile(path, serializeCertificateToToml(cert))

proc readCertificateFile*(path: string): TestCertificate =
  ## Read + parse a certificate file. Raises on IO / parse error.
  if not fileExists(path):
    raise newException(TestCertificateParseError,
      "certificate file not found: " & path)
  parseCertificateFromToml(readFile(path))

# ---- verifier --------------------------------------------------------------

type
  CoverageRequirement* = object
    ## The tuple a verifier checks a certificate SET against.
    commit*: string
    lock*: string
    platform*: string
    requiredTargets*: seq[string]

  CoverageResult* = object
    ## Outcome of ``verifyCoverage``. ``covered`` is the verdict; the other
    ## fields explain a miss so the gate (TC-3) / CI (TC-4) can render an
    ## actionable diagnostic.
    covered*: bool
    coveredTargets*: seq[string]   ## union of targets across matching certs
    missingTargets*: seq[string]   ## required ∖ covered
    matchingCerts*: int            ## certs matching commit/lock/platform

proc certificateMatches*(cert: TestCertificate;
                         req: CoverageRequirement): bool =
  ## A certificate is RELEVANT to a requirement iff it is a passed cert whose
  ## ``commit`` / ``lock`` / ``platform`` all match. A mismatch on ANY binding
  ## field means the cert attests a DIFFERENT state and is ignored (the spec:
  ## "Verifiers ignore … notes whose ``commit`` field doesn't match").
  cert.result == tcrPassed and
    cert.commit == req.commit and
    cert.lock == req.lock and
    cert.platform == req.platform

proc verifyCoverage*(certs: openArray[TestCertificate];
                     req: CoverageRequirement): CoverageResult =
  ## Does the certificate SET cover ``(commit, lock, platform,
  ## required-targets)``? The covered set is the UNION of ``targets`` across
  ## every matching certificate (partial coverage across several certs is
  ## allowed, per Test-Certificates.md §"Gate integration"); coverage holds
  ## iff that union ⊇ ``requiredTargets``. Certs whose commit/lock/platform
  ## mismatch are ignored entirely.
  var union = initHashSet[string]()
  for cert in certs:
    if certificateMatches(cert, req):
      inc result.matchingCerts
      for t in cert.targets:
        union.incl(t)
  for t in union: result.coveredTargets.add(t)
  sort(result.coveredTargets)
  for t in req.requiredTargets:
    if t notin union:
      result.missingTargets.add(t)
  result.covered = result.missingTargets.len == 0

# ============================================================================
# TC-5 — Daemon signing + key registration.
#
# TC-1 shipped the cert schema with the ``[certificate.signature]`` block left
# explicitly EMPTY (unsigned) and a COVERAGE verifier. TC-5 fills that block on
# issuance with a REAL ed25519 signature and makes a verifier accept a
# certificate only when its ``key_id`` resolves to a REGISTERED, UNREVOKED
# public key AND the signature over ``canonicalCertificatePayload`` checks out.
#
# Crypto primitive (REAL, no hand-rolled crypto): OpenSSH ``ssh-keygen -Y
# sign`` / ``ssh-keygen -Y verify`` over an ed25519 SSH key. This is the same
# ed25519/SSH-signature machinery RA-17 uses for manifest provenance (``git
# verify-commit`` with ``gpg.ssh.allowedSignersFile``), so the toolchain
# already ships it. ``ssh-keygen -Y sign`` produces a detached SSH signature
# (``-----BEGIN SSH SIGNATURE-----``) over arbitrary payload bytes under a
# namespace; ``ssh-keygen -Y verify`` checks it against an allowed-signers
# file. We sign the EXACT bytes of ``canonicalCertificatePayload(cert)``.
#
# Key-protection posture (HONEST — see Test-Certificates.md §"Trust model" and
# §"Signing and key management"): the IDEAL is that the privileged daemon
# (``reprostored``, running as root / a dedicated service account that the
# unprivileged agent cannot read) owns the signing key, so forging a cert
# requires deliberate key exfiltration past the same boundary that protects the
# store. THIS implementation locates the signing key via the daemon-owned key
# path (``reproSigningKeyPath``), but does NOT yet stand up a separate
# privileged signing service: the key is a file readable by whoever runs the
# observed ``repro test`` issuance. That residual risk is stated plainly, not
# hidden — if the key lives where the issuing user can read it, signing resists
# CASUAL/accidental forgery (an agent that skips the tests cannot mint a cert
# without finding+using the key) but NOT a determined local attacker who steals
# the key. The full privileged-daemon/OS-keystore/remote-signer split is the
# documented deferral (DEFER-TC5-PRIV-DAEMON below). The SIGNING ENTRY POINT is
# already shaped correctly: ``signCertificateOnIssuance`` is reachable ONLY as
# a side effect of an observed real run (the ``repro test`` issuance path) —
# there is NO ``repro sign <blob>`` command/API anywhere, so an agent cannot
# obtain a signature over an arbitrary record even with the current key
# placement.
# ============================================================================

const
  certificateSignatureNamespace* = "reprobuild-test-certificate-v1"
    ## The ``ssh-keygen -Y sign -n <namespace>`` namespace. Both sign and
    ## verify MUST use the same namespace; a mismatch fails verification (a
    ## cheap domain-separation guard so a cert signature can never be confused
    ## with, e.g., an RA-17 manifest signature).
  certificateSignatureAlgorithm* = "ed25519"
    ## The ``[certificate.signature] algorithm`` value TC-5 writes.

type
  CertificateSigningError* = object of CatchableError
    ## Raised when the daemon cannot produce a signature (no key, no
    ## ssh-keygen, signing tool failure). Issuance treats this as "no
    ## certificate" — we NEVER emit an unsigned/faked cert in its place.

  RegisteredKeyStatus* = enum
    ## A registered key is either ``active`` (a current allowed signer) or
    ## ``revoked`` (compromised / rotated out — a cert signed by it is
    ## REJECTED even though the signature itself is cryptographically valid).
    rksActive = "active"
    rksRevoked = "revoked"

  RegisteredKey* = object
    ## One entry in the allowed-signers store: a ``key_id`` → ed25519 public
    ## key + status. ``publicKey`` is the OpenSSH public-key line
    ## (``ssh-ed25519 AAAA... [comment]``) as emitted by ``ssh-keygen``.
    keyId*: string
    publicKey*: string
    status*: RegisteredKeyStatus

  RegisteredKeyStore* = object
    ## The set of allowed signers CI / the server registers (the "registered
    ## public keys" of Test-Certificates.md §"Signing and key management").
    ## ROTATION is ``registerKey`` (append a new active key, e.g. a new
    ## quarter's key); REVOCATION is ``revokeKey`` (flip a key to ``revoked``
    ## without removing it, so the audit trail and any "why rejected" diagnostic
    ## survive). A ``key_id`` is unique; registering an existing id replaces it.
    keys*: seq[RegisteredKey]

const
  registeredKeysSchemaV1* = "reprobuild.registered-keys.v1"
    ## ``schema`` value the registered-keys store file carries.

proc resolveSigner*(store: RegisteredKeyStore;
                    keyId: string): tuple[found: bool; publicKey: string;
                                          revoked: bool] =
  ## The reader/resolver: ``key_id`` → (public key, revoked?). ``found`` is
  ## false for an UNREGISTERED id (a cert claiming such an id is rejected by
  ## the verifier). ``revoked`` is true for a registered-but-revoked key (also
  ## rejected). Only a ``found`` + not-``revoked`` result is a trusted signer.
  for k in store.keys:
    if k.keyId == keyId:
      return (found: true, publicKey: k.publicKey,
              revoked: k.status == rksRevoked)
  (found: false, publicKey: "", revoked: false)

proc registerKey*(store: var RegisteredKeyStore; keyId, publicKey: string) =
  ## ROTATION primitive: register (or replace) ``keyId`` as an ACTIVE allowed
  ## signer. Adding a new key id alongside the old ones is how a key rotates in;
  ## the old key stays trusted until explicitly revoked, so certs signed before
  ## the rotation keep verifying.
  for k in store.keys.mitems:
    if k.keyId == keyId:
      k.publicKey = publicKey
      k.status = rksActive
      return
  store.keys.add(RegisteredKey(keyId: keyId, publicKey: publicKey,
    status: rksActive))

proc revokeKey*(store: var RegisteredKeyStore; keyId: string): bool =
  ## REVOCATION primitive: flip ``keyId`` to ``revoked``. Returns false if the
  ## id is not registered. A revoked key's certs are REJECTED by the verifier
  ## even though their signatures are still cryptographically valid — this is
  ## the "revocation list invalidates compromised keys" of the spec.
  for k in store.keys.mitems:
    if k.keyId == keyId:
      k.status = rksRevoked
      return true
  false

proc serializeRegisteredKeyStore*(store: RegisteredKeyStore): string =
  ## Render the store to a deterministic TOML form (one ``[[key]]`` table per
  ## entry). Stored under the workspace so issuance and the gate share one
  ## allowed-signers set.
  result = "schema = \"" & registeredKeysSchemaV1 & "\"\n"
  for k in store.keys:
    result.add("\n[[key]]\n")
    result.add("key_id = \"" & tomlEscapeCert(k.keyId) & "\"\n")
    result.add("public_key = \"" & tomlEscapeCert(k.publicKey) & "\"\n")
    result.add("status = \"" & $k.status & "\"\n")

proc parseRegisteredKeyStore*(content: string): RegisteredKeyStore =
  ## Reader for ``serializeRegisteredKeyStore``. Tolerant of unknown keys; a
  ## missing/empty file parses to an EMPTY store (no allowed signers → every
  ## cert is rejected, fail-closed).
  var cur: RegisteredKey
  var inKey = false
  template flush() =
    if inKey and cur.keyId.len > 0:
      result.keys.add(cur)
    cur = RegisteredKey()
    inKey = false
  for rawLine in content.splitLines():
    let line = rawLine.strip()
    if line.len == 0 or line.startsWith("#"): continue
    if line == "[[key]]":
      flush()
      inKey = true
      cur = RegisteredKey(status: rksActive)
      continue
    if line.startsWith("["): continue
    let eq = line.find('=')
    if eq <= 0: continue
    let key = line[0 ..< eq].strip()
    let rhs = line[eq + 1 .. ^1]
    if not inKey:
      continue
    case key
    of "key_id": cur.keyId = parseTomlBasicValue(rhs)
    of "public_key": cur.publicKey = parseTomlBasicValue(rhs)
    of "status":
      cur.status =
        if parseTomlBasicValue(rhs) == $rksRevoked: rksRevoked else: rksActive
    else: discard
  flush()

proc registeredKeyStorePath*(workspaceRoot: string): string =
  ## Where the allowed-signers store lives for a workspace. CI / the server
  ## owns this set (Test-Certificates.md: "CI/server registers trusted public
  ## keys"); we colocate it with the workspace's daemon-owned ``.repo`` tree so
  ## both the issuance path and the pre-push gate read the SAME registry.
  workspaceRoot / ".repro" / "workspace" / "certificates" / "registered-keys.toml"

proc readRegisteredKeyStore*(path: string): RegisteredKeyStore =
  ## Read the store from ``path``; a missing file is an EMPTY store
  ## (fail-closed: no registered signers → nothing verifies).
  if path.len == 0 or not fileExists(path):
    return RegisteredKeyStore()
  parseRegisteredKeyStore(readFile(path))

proc writeRegisteredKeyStore*(store: RegisteredKeyStore; path: string) =
  ## Persist the store, creating parent dirs.
  let parent = parentDir(path)
  if parent.len > 0 and not dirExists(parent):
    createDir(parent)
  writeFile(path, serializeRegisteredKeyStore(store))

# ---- daemon signing (reachable ONLY via observed-run issuance) -------------

proc reproSigningKeyPath*(workspaceRoot: string): string =
  ## The daemon's ed25519 signing-key path. PRIVILEGED-DAEMON posture (honest):
  ##   1. ``REPRO_DAEMON_SIGNING_KEY`` — the daemon injects the path to the key
  ##      it owns when it observes the run. This is the seam where a real
  ##      privileged ``reprostored`` (or a remote signer) would hand the signing
  ##      capability to the issuance step WITHOUT the key ever being readable by
  ##      the unprivileged agent. Tests set it to a hermetic key.
  ##   2. Otherwise a workspace-local daemon key under ``.repo/workspace/
  ##      certificates/signing-key`` (the colocated daemon-state default).
  ## DEFER-TC5-PRIV-DAEMON: in this implementation the key at either location
  ## is a plain file readable by whoever runs issuance; standing up the actual
  ## privileged signing service (root/service-account-owned key, or a remote
  ## signer) is deferred. The entry point is already correct — see
  ## ``signCertificateOnIssuance`` (no "sign this blob" API exists).
  let injected = getEnv("REPRO_DAEMON_SIGNING_KEY")
  if injected.len > 0:
    return injected
  workspaceRoot / ".repro" / "workspace" / "certificates" / "signing-key"

proc reproSigningKeyId*(): string =
  ## The ``key_id`` the daemon's signing key is registered under (the
  ## ``[certificate] key_id`` field). Daemon-injected via ``REPRO_DAEMON_KEY_ID``
  ## when it observes the run; otherwise a stable default. The verifier resolves
  ## this id against the registered-keys store, so the SAME id must be the one
  ## CI/the server registered the daemon's public half under.
  let injected = getEnv("REPRO_DAEMON_KEY_ID")
  if injected.len > 0: injected else: "repro-daemon-key"

proc sshKeygenBinary(): string =
  ## Resolve ``ssh-keygen`` (the real ed25519 signer/verifier). Empty when
  ## absent — callers fail closed (no signature, no certificate; verify fails).
  findExe("ssh-keygen")

proc signCertificateOnIssuance*(cert: var TestCertificate;
                                keyId, signingKeyPath: string) =
  ## DAEMON-SIDE signing, reachable ONLY from the ``repro test`` issuance path
  ## (see the call in ``runTestCommand``'s issuance arm). There is deliberately
  ## NO general "sign this blob" wrapper: this proc takes a fully-built
  ## ``TestCertificate`` for a state the daemon just OBSERVED passing, signs the
  ## EXACT ``canonicalCertificatePayload(cert)`` bytes with the daemon's
  ## ed25519 key, and fills ``cert.keyId`` + ``cert.signature``. An agent cannot
  ## reach this with an arbitrary payload — it only ever runs as a side effect
  ## of an actually-executed clean+passing run.
  ##
  ## Raises ``CertificateSigningError`` on any failure (no key, no ssh-keygen,
  ## signer error). The issuance caller treats that as "no certificate" rather
  ## than emitting an unsigned/faked one.
  let sshKeygen = sshKeygenBinary()
  if sshKeygen.len == 0:
    raise newException(CertificateSigningError,
      "ssh-keygen not found on PATH; cannot sign the certificate")
  if signingKeyPath.len == 0 or not fileExists(signingKeyPath):
    raise newException(CertificateSigningError,
      "daemon signing key not found at '" & signingKeyPath & "'")
  # ``key_id`` is part of the ``[certificate]`` body, so it MUST be set BEFORE
  # we compute the canonical payload — the verifier reconstructs the payload
  # from the cert it reads (which carries the key_id), and the signed bytes
  # must match those exactly. Setting it after signing would sign a DIFFERENT
  # byte sequence than the one verified, and every signature would fail.
  cert.keyId = keyId
  let payload = canonicalCertificatePayload(cert)
  # ssh-keygen -Y sign signs a FILE in place (writes ``<file>.sig``); use a
  # private scratch file so the exact payload bytes are what gets signed.
  let scratch = createTempDir("repro-cert-sign-", "")
  defer: removeDir(scratch)
  let payloadFile = scratch / "payload"
  writeFile(payloadFile, payload)
  let res = execCmdEx(shellCommand(@[sshKeygen, "-Y", "sign",
    "-n", certificateSignatureNamespace, "-f", signingKeyPath, payloadFile]))
  if res.exitCode != 0:
    raise newException(CertificateSigningError,
      "ssh-keygen -Y sign failed: " & res.output.strip())
  let sigPath = payloadFile & ".sig"
  if not fileExists(sigPath):
    raise newException(CertificateSigningError,
      "ssh-keygen produced no signature file")
  cert.signature = TestCertificateSignature(
    algorithm: certificateSignatureAlgorithm,
    value: encode(readFile(sigPath)))   # base64 of the SSH signature blob

# ---- signature verification (registered + unrevoked + valid sig) -----------

type
  SignatureVerdict* = enum
    ## Outcome of verifying a certificate's signature against the registry.
    svValid              ## signed + key registered + unrevoked + sig checks.
    svUnsigned           ## no ``[certificate.signature]`` (TC-1-shape cert).
    svUnregisteredKey    ## ``key_id`` not in the registry.
    svRevokedKey         ## ``key_id`` registered but REVOKED.
    svBadSignature       ## signed by a registered key but sig does NOT check
                         ## (tampered payload / wrong key for that key_id).
    svToolingUnavailable ## ssh-keygen missing — cannot verify (fail closed).

proc allowedSignerIdentity*(keyId: string): string =
  ## The ``-I`` principal we sign-as / verify-as. The registry's ``key_id`` is
  ## a stable principal so the allowed-signers line ties a key to its id.
  "repro-cert/" & keyId

proc verifyCertificateSignature*(cert: TestCertificate;
                                 store: RegisteredKeyStore): SignatureVerdict =
  ## The TC-5 SIGNATURE verifier (additive to the TC-1 COVERAGE verifier). A
  ## certificate's signature is VALID iff:
  ##   (a) it is signed (``isSigned``), AND
  ##   (b) its ``key_id`` resolves to a REGISTERED key in ``store``, AND
  ##   (c) that key is NOT revoked, AND
  ##   (d) the ed25519 signature over ``canonicalCertificatePayload(cert)``
  ##       checks against that registered public key (via ``ssh-keygen -Y
  ##       verify``).
  ## Any miss → a specific non-``svValid`` verdict the gate/CI renders.
  if not cert.isSigned:
    return svUnsigned
  let signer = resolveSigner(store, cert.keyId)
  if not signer.found:
    return svUnregisteredKey
  if signer.revoked:
    return svRevokedKey
  let sshKeygen = sshKeygenBinary()
  if sshKeygen.len == 0:
    return svToolingUnavailable
  let payload = canonicalCertificatePayload(cert)
  var sigBytes: string
  try:
    sigBytes = decode(cert.signature.value)
  except CatchableError:
    return svBadSignature
  let scratch = createTempDir("repro-cert-verify-", "")
  defer: removeDir(scratch)
  let payloadFile = scratch / "payload"
  let sigFile = scratch / "payload.sig"
  let allowedSigners = scratch / "allowed_signers"
  writeFile(payloadFile, payload)
  writeFile(sigFile, sigBytes)
  # The allowed-signers file ties THIS key_id's registered public key to the
  # principal we verify as, so a signature made by a DIFFERENT key (even a
  # registered one under another id) does not verify for this key_id.
  writeFile(allowedSigners,
    allowedSignerIdentity(cert.keyId) & " " & signer.publicKey & "\n")
  # ``ssh-keygen -Y verify`` reads the signed payload on stdin.
  let cmd = shellCommand(@[sshKeygen, "-Y", "verify",
    "-f", allowedSigners, "-I", allowedSignerIdentity(cert.keyId),
    "-n", certificateSignatureNamespace, "-s", sigFile]) &
    " < " & quoteShell(payloadFile)
  let res = execCmdEx(cmd)
  if res.exitCode == 0: svValid else: svBadSignature

proc certificateIsTrusted*(cert: TestCertificate;
                           store: RegisteredKeyStore): bool =
  ## Convenience predicate the gate composes with coverage: a certificate is
  ## TRUSTED iff its signature verdict is ``svValid``.
  verifyCertificateSignature(cert, store) == svValid

# ============================================================================
# TC-2: certificate TRANSPORT — attach/read certificates bound to a commit and
# carry them on the push.
# ============================================================================
#
# A certificate (TC-1) is a small TOML record that ATTESTS a state. TC-2 binds
# an already-issued certificate to the COMMIT it attests and ships it to the
# upstream alongside the branch, so reviewers, the gate (TC-3) and CI (TC-4)
# read exactly what was attested.
#
# Carrier (Test-Certificates.md §"Transport"): **git notes** under
# ``refs/notes/reprobuild/certificates`` keyed by the commit SHA. A note is
# data attached to a commit WITHOUT changing the commit SHA, stored in its own
# ref whose tree maps ``<commit-sha>`` → a blob holding the signed
# certificate(s). We prefer notes over a ``refs/certificates/<commit>`` ref
# because the note travels with a single, well-known ref (one refspec on the
# push) and one commit may carry MULTIPLE certificates (typically one per
# platform) in the SAME note.
#
# Multiple certs WITHOUT overwrite: each record is framed by a sentinel header
# line and we APPEND (``git notes append``) rather than ``add``/overwrite, so a
# second platform's cert accumulates next to the first instead of replacing it.
# The reader splits on the sentinel and parses each record independently.
#
# Mismatch defense (Test-Certificates.md: "Verifiers ignore … notes whose
# ``commit`` field doesn't match the target commit"): when reading the certs
# attached to commit C, a record whose INTERNAL ``commit`` field is not C is
# dropped — a stale/misfiled note never masquerades as an attestation of C.

const
  certificateNotesRef* = "refs/notes/reprobuild/certificates"
    ## The git-notes ref the certificate carrier lives in. Notes are NOT
    ## pushed/fetched by default; the push path pushes this ref explicitly and
    ## verifiers fetch it.
  certificateRecordSentinel = "# --- reprobuild-certificate ---"
    ## Header line that frames each certificate record inside one commit's
    ## note. ``git notes append`` concatenates records with a blank line, so we
    ## split on this sentinel (which never appears in a serialized cert body —
    ## the writer only emits ``[certificate]``/``[certificate.signature]``
    ## tables and ``key = "..."`` lines) to recover individual records
    ## deterministically regardless of git's join.

proc gitNoteRun(gitBin: string;
                args: openArray[string];
                preserveObjectStore = false):
    tuple[code: int; output: string] =
  ## Free-standing argv runner for the notes commands (same shape as
  ## ``gitRunPlain`` but takes a bare git binary path so the transport layer
  ## does not require a resolved ``GitToolIdentity``).
  ##
  ## ``preserveObjectStore`` keeps Git's object-store bindings
  ## (``GitObjectStoreEnv``) instead of scrubbing them. Set it ONLY for a read
  ## of the invoking repository during ``pre-receive``, where the objects being
  ## examined are still in the push quarantine and are reachable through those
  ## variables alone. Every other caller keeps the default: a cross-repository
  ## ``git -C <sibling>`` must never inherit the invoking repository's objects.
  var cmd = quoteShell(gitBin)
  for arg in args:
    cmd.add(" ")
    cmd.add(quoteShell(arg))
  let res = execCmdEx(cmd, options = {poStdErrToStdOut, poUsePath},
    env = scrubbedGitRepositoryEnv(preserveObjectStore = preserveObjectStore))
  (code: res.exitCode, output: res.output)

proc framedCertificateRecord(cert: TestCertificate): string =
  ## One certificate framed by the sentinel header so multiple records in the
  ## same note can be split apart on read.
  certificateRecordSentinel & "\n" & serializeCertificateToToml(cert)

proc splitCertificateRecords(note: string): seq[string] =
  ## Recover the individual serialized-certificate bodies from a note blob that
  ## may hold several appended records. Splits on the sentinel header; tolerant
  ## of the blank lines ``git notes append`` inserts between records and of a
  ## leading record with no preceding sentinel (defensive).
  var current = ""
  var started = false
  for rawLine in note.splitLines():
    if rawLine.strip() == certificateRecordSentinel:
      if started and current.strip().len > 0:
        result.add(current)
      current = ""
      started = true
    elif started:
      current.add(rawLine)
      current.add("\n")
  if started and current.strip().len > 0:
    result.add(current)

proc attachCertificate*(gitBin, repoPath, commit: string;
                        cert: TestCertificate): tuple[ok: bool; diagnostic: string] =
  ## Bind ``cert`` to ``commit`` in ``repoPath`` as a git note under
  ## ``refs/notes/reprobuild/certificates`` (TC-2 carrier). The cert is
  ## APPENDED to any note already on ``commit`` so multiple platforms'
  ## certificates accumulate on one commit WITHOUT overwriting each other.
  ## Returns ``ok=false`` with a diagnostic on a git failure.
  let record = framedCertificateRecord(cert)
  # ``git notes append`` creates the note when absent and appends otherwise,
  # so a second platform's cert never clobbers the first. ``-F -`` would need a
  # pipe; we pass the framed record via ``-m`` (a single message argument).
  let res = gitNoteRun(gitBin,
    ["-C", repoPath, "notes", "--ref", certificateNotesRef,
     "append", "--no-separator", "-m", record, commit])
  if res.code != 0:
    # Older git (< 2.31) lacks ``--no-separator``; retry without it (the
    # sentinel-based splitter tolerates the extra blank line git inserts).
    let res2 = gitNoteRun(gitBin,
      ["-C", repoPath, "notes", "--ref", certificateNotesRef,
       "append", "-m", record, commit])
    if res2.code != 0:
      return (ok: false, diagnostic: "git notes append failed: " &
        res2.output.strip())
  (ok: true, diagnostic: "")

proc noteBlobFromNotesCommit(gitBin, repoPath, notesCommitSha,
                             commit: string;
                             preserveObjectStore = false): string =
  ## Read the note blob attached to ``commit`` straight out of a raw
  ## NOTES-COMMIT SHA (not a ref). ``git notes --ref <raw-sha>`` does NOT work
  ## (``--ref`` resolves a ref NAME, not a commit-ish), but a notes tree maps
  ## ``<commit-sha>`` (possibly under fanout dirs like ``ab/cdef…``) → a blob,
  ## so we walk the tree with ``git ls-tree -r <notesCommitSha>`` and match the
  ## entry whose path (with fanout ``/`` separators removed) equals ``commit``,
  ## then ``git cat-file blob`` it. This is what lets the gateway read an
  ## INCOMING certificate note in ``pre-receive`` BEFORE the notes ref has been
  ## moved into place (the objects are already present; only the ref update is
  ## pending). Returns "" when there is no note for ``commit``.
  let ls = gitNoteRun(gitBin,
    ["-C", repoPath, "ls-tree", "-r", notesCommitSha],
    preserveObjectStore = preserveObjectStore)
  if ls.code != 0:
    return ""
  for rawLine in ls.output.splitLines():
    let line = rawLine.strip()
    if line.len == 0: continue
    # ``<mode> <type> <objsha>\t<path>``
    let tabIdx = line.find('\t')
    if tabIdx < 0: continue
    let meta = line[0 ..< tabIdx].splitWhitespace()
    if meta.len < 3: continue
    let objSha = meta[2]
    let path = line[tabIdx + 1 .. ^1].strip()
    if path.replace("/", "") == commit:
      let blob = gitNoteRun(gitBin,
        ["-C", repoPath, "cat-file", "blob", objSha],
        preserveObjectStore = preserveObjectStore)
      if blob.code == 0:
        return blob.output
      return ""
  ""

proc readAttachedCertificatesFromRef*(gitBin, repoPath, commit,
                                      notesRef: string;
                                      preserveObjectStore = false):
    seq[TestCertificate] =
  ## Like ``readAttachedCertificates`` but reads from an EXPLICIT notes ref
  ## (a ref name OR a raw notes-commit SHA). The receiving-side gateway (TC-6)
  ## needs this: in a ``pre-receive`` hook the certificate note arrives as a
  ## brand-new value for ``refs/notes/reprobuild/certificates`` that has NOT
  ## yet been moved into place (the ref update is still pending), so the
  ## gateway resolves the certs straight from the INCOMING notes-commit SHA it
  ## reads off the pre-receive stdin. Records whose internal ``commit`` field
  ## does not equal ``commit`` are DROPPED; unparseable records are skipped.
  ##
  ## ``notesRef`` may be a 40-hex notes-COMMIT SHA (the pre-receive case) or a
  ## ref NAME (the post-receive / settled case). ``git notes --ref`` only
  ## accepts a ref name, so we try the raw-SHA tree-walk first and fall back to
  ## ``git notes show`` for a ref name.
  var noteBody = ""
  let looksLikeSha = notesRef.len == 40 and
    notesRef.allCharsInSet(HexDigits)
  if looksLikeSha:
    noteBody = noteBlobFromNotesCommit(gitBin, repoPath, notesRef, commit,
      preserveObjectStore = preserveObjectStore)
  else:
    let res = gitNoteRun(gitBin,
      ["-C", repoPath, "notes", "--ref", notesRef, "show", commit],
      preserveObjectStore = preserveObjectStore)
    if res.code == 0:
      noteBody = res.output
  if noteBody.len == 0:
    return @[]
  for body in splitCertificateRecords(noteBody):
    var cert: TestCertificate
    try:
      cert = parseCertificateFromToml(body)
    except TestCertificateParseError:
      continue
    # Mismatch filter: only certs that genuinely attest THIS commit.
    if cert.commit == commit:
      result.add(cert)

proc readAttachedCertificates*(gitBin, repoPath, commit: string):
    seq[TestCertificate] =
  ## Read the certificates attached to ``commit`` (the note under
  ## ``refs/notes/reprobuild/certificates``) in ``repoPath``. Records whose
  ## INTERNAL ``commit`` field does not equal ``commit`` are DROPPED (defense
  ## against a stale/misfiled note); unparseable records are skipped. Returns
  ## an empty seq when no note is attached.
  readAttachedCertificatesFromRef(gitBin, repoPath, commit, certificateNotesRef)

proc pushCertificateNotes*(gitBin, repoPath, remote: string):
    tuple[ok: bool; pushed: bool; diagnostic: string] =
  ## Carry the certificate notes ref to ``remote`` (TC-2: the push path pushes
  ## ``refs/notes/reprobuild/certificates`` explicitly, since notes are not
  ## pushed by default). All certs attached to all pushed commits travel in the
  ## single ref. ``pushed=false`` with ``ok=true`` means there were no
  ## certificate notes to carry (benign — nothing attached).
  let probe = gitNoteRun(gitBin,
    ["-C", repoPath, "rev-parse", "--verify", "--quiet",
     certificateNotesRef])
  if probe.code != 0:
    # The notes ref does not exist locally → nothing attached, nothing to push.
    return (ok: true, pushed: false, diagnostic: "no certificate notes")
  let res = gitNoteRun(gitBin,
    ["-C", repoPath, "push", remote,
     certificateNotesRef & ":" & certificateNotesRef])
  if res.code != 0:
    return (ok: false, pushed: false,
      diagnostic: "git push " & certificateNotesRef & " failed: " &
        res.output.strip())
  (ok: true, pushed: true, diagnostic: "")

proc certificateGate(report: var CheckReport; policy: CertificatePolicy;
                     pushedCommit, certRepoPath, gitBin,
                     currentRepoName, registeredKeysPath: string) =
  ## TC-3 / RA-32 — the certificate-coverage stage of the RA-21 pre-push gate.
  ## Called ONLY after every other gate stage has passed (clean + published +
  ## at the locked revisions, lock current), from each exit point of stage 5.
  ##
  ## DEFAULT-OFF (RA-32): ``cgmOff`` — the value a project with NO
  ## ``[certificates]`` table resolves to — is a strict NO-OP. It touches
  ## neither ``failures`` nor ``exitCode`` nor ``notices``, so every existing
  ## pre-push gate test (which sets no policy) is byte-for-byte unaffected.
  ##
  ## ``cgmAdvisory`` RECORDS the coverage verdict in ``report.notices`` but
  ## never changes ``exitCode`` (the load-bearing onboarding property: advisory
  ## never blocks). ``cgmRequired`` REFUSES the push (exit 2 + a structured
  ## ``certificate-coverage`` failure) unless the submitted certificates COVER
  ## the pushed commit for the required targets on EACH required platform.
  if policy.gateMode == cgmOff:
    return
  # The lock digest binds a certificate to the clean dependency state. The
  # stage-4 lock pass filled ``report.lockUpdate.lockFilePath`` in every arm
  # (already-current / created / refreshed).
  let lockDigest = certificateLockDigest(report.lockUpdate.lockFilePath)
  # A policy that opts in but lists no required platforms means certificates
  # are advisory-only (the spec: required_platforms may be none). There is
  # nothing to enforce, so ``required`` degrades to a no-op rather than
  # blocking on an empty requirement set.
  if policy.requiredPlatforms.len == 0:
    if policy.gateMode == cgmAdvisory:
      report.notices.add("certificate advisory: policy sets no " &
        "required_platforms — nothing to attest (pushes not gated)")
    return
  if pushedCommit.len == 0 or lockDigest.len == 0:
    let why =
      if pushedCommit.len == 0: "no HEAD commit to attest"
      else: "no resolvable workspace lock to bind the certificate to"
    if policy.gateMode == cgmAdvisory:
      report.notices.add("certificate advisory: coverage NOT verified (" &
        why & ")")
    else:
      report.failures.add(CheckFailure(
        repo: currentRepoName,
        property: "certificate-coverage",
        remediation: "run 'repro certify' to issue a certificate, then " &
          "'repro push' to carry it (" & why & ")",
        evidence: why))
      report.exitCode = 2
    return
  # Read whatever certificates are attached to the pushed commit (TC-2 git-
  # notes carrier), then check EACH required platform independently. The
  # per-platform covered set is the UNION of every matching cert's targets
  # (multi-cert union: a linux cert + a macos cert together satisfy a
  # {linux, macos} requirement).
  let attached = readAttachedCertificates(gitBin, certRepoPath, pushedCommit)
  # TC-5: coverage now requires a VALID REGISTERED SIGNATURE. A certificate
  # counts toward coverage ONLY when its ``key_id`` resolves to a registered,
  # unrevoked key and the ed25519 signature over the canonical payload checks.
  # Unsigned / wrong-key / unregistered / revoked / tampered certs are dropped
  # BEFORE coverage, so the ``required`` gate enforces BOTH coverage AND a
  # trusted signature. We record WHY a present-but-untrusted cert was dropped so
  # the diagnostic distinguishes "no cert" from "cert present but not trusted".
  let keyStore = readRegisteredKeyStore(registeredKeysPath)
  var trusted: seq[TestCertificate] = @[]
  var signatureNotes: seq[string] = @[]
  for cert in attached:
    let verdict = verifyCertificateSignature(cert, keyStore)
    if verdict == svValid:
      trusted.add(cert)
    else:
      let why =
        case verdict
        of svUnsigned: "unsigned"
        of svUnregisteredKey: "key_id '" & cert.keyId & "' not registered"
        of svRevokedKey: "key_id '" & cert.keyId & "' revoked"
        of svBadSignature: "signature does not verify"
        of svToolingUnavailable: "ssh-keygen unavailable (cannot verify)"
        of svValid: ""
      signatureNotes.add(cert.platform & ": " & why)
  var perPlatformMissing: seq[string] = @[]
  for platform in policy.requiredPlatforms:
    let req = CoverageRequirement(
      commit: pushedCommit,
      lock: lockDigest,
      platform: platform,
      requiredTargets: policy.requiredTargets)
    let cov = verifyCoverage(trusted, req)
    if not cov.covered:
      perPlatformMissing.add(platform & " (missing: " &
        (if cov.missingTargets.len > 0: cov.missingTargets.join(", ")
         else: "<no certificate>") & ")")
  if perPlatformMissing.len == 0:
    if policy.gateMode == cgmAdvisory:
      report.notices.add("certificate advisory: coverage OK for " &
        policy.requiredPlatforms.join(", ") & " × [" &
        policy.requiredTargets.join(", ") & "] at " &
        pushedCommit[0 ..< min(12, pushedCommit.len)])
    # In required mode a clean pass adds no failure — the gate keeps whatever
    # exit code stage 5 set (0 on success).
    return
  let sigDetail =
    if signatureNotes.len > 0:
      " (untrusted certs ignored: " & signatureNotes.join("; ") & ")"
    else: ""
  let detail = perPlatformMissing.join("; ") & sigDetail
  if policy.gateMode == cgmAdvisory:
    report.notices.add("certificate advisory: coverage INCOMPLETE — " &
      detail & " (run 'repro certify' on the missing platform(s); advisory " &
      "mode does not block this push)")
  else:
    report.failures.add(CheckFailure(
      repo: currentRepoName,
      property: "certificate-coverage",
      remediation: "run 'repro certify' (on each required platform) to " &
        "issue the missing certificate(s), then 'repro push' to carry them " &
        "with this push",
      evidence: "uncovered: " & detail,
      source: ""))
    report.exitCode = 2

# ============================================================================
# TC-6 — Receiving-side enforcement: the local push gateway.
#
# The CLIENT pre-push gate (TC-3) gives fast local feedback but is bypassable:
# ``git push --no-verify`` skips ALL client hooks and there is no git config
# that disables it (Test-Certificates.md §"Enforcement"). So the AUTHORITATIVE
# certificate check runs on the RECEIVING side, where ``--no-verify`` has no
# effect (it only skips client hooks; ``pre-receive`` always runs on the repo
# being pushed to).
#
# Model (Test-Certificates.md §"Enforcement", "Hosts you don't control"):
#   - reprobuild already controls cloning and keeps a local bare cache, so it
#     sets a daemon-managed BARE repo as the repo's push remote at clone time
#     (``remote.origin.pushurl`` → the gateway bare). A developer's
#     ``git push`` / ``repro push`` lands on the gateway, NOT directly on the
#     real upstream (GitHub).
#   - The gateway bare's ``pre-receive`` hook reads the incoming pushed commit
#     + its certificates (from the INCOMING notes ref / objects already in the
#     repo's quarantine), resolves the project's certificate policy, and — when
#     the policy is ``required`` — VERIFIES that a registered-signed (TC-5)
#     certificate COVERS (TC-1) the pushed commit for the required targets on
#     each required platform. On failure it exits non-zero → git rejects the
#     whole push, so an accidental ``--no-verify`` is caught even though the
#     upstream host can't run a custom hook.
#   - On success the gateway's ``post-receive`` FORWARDS the push to the real
#     upstream bare (a second bare standing in for GitHub). A covered push thus
#     lands on the upstream; an uncovered push is rejected at the gateway and
#     never reaches it.
#
# Both hooks are THIN: they invoke ``repro gateway pre-receive`` /
# ``repro gateway post-receive`` so the verify/forward logic lives here, not in
# shell. A ``deliberate`` ``git remote set-url`` to the upstream bypasses the
# gateway — deliberate circumvention is explicitly out of scope; the goal is to
# stop ACCIDENTS.
#
# Vivafolio-hosted workspaces (vivafolio-specs ``Vivafolio-Hosted-Workspace-
# SaaS.md``) and GitHub branch-protection + a required status check are the
# OTHER receiving-side equivalents. They are EXTERNAL (a separate SaaS / GitHub
# config); the local gateway here is the fully-implemented, hermetically-tested
# path, and the external wiring is documented + honestly deferred
# (DEFER-TC6-VIVAFOLIO-GITHUB below).
# ============================================================================

const
  gatewayConfigSchemaV1* = "reprobuild.push-gateway.v1"
    ## ``schema`` line the gateway config carries.
  gatewayConfigRelPath* = "reprobuild-gateway.toml"
    ## Where the gateway config lives, relative to the gateway BARE repo dir.
    ## The daemon writes it when it wires the gateway; the ``pre-receive`` /
    ## ``post-receive`` hooks read it. (A bare repo has no working tree, so a
    ## file under ``$GIT_DIR`` is the natural home for daemon-owned metadata.)

type
  GatewayConfig* = object
    ## The daemon-owned configuration the gateway bare repo carries. It is the
    ## standalone equivalent of what the client gate resolves from the
    ## workspace: the project's certificate policy (gate mode + required
    ## targets/platforms), the ``lock`` digest a certificate must bind to, the
    ## registered-keys (allowed-signers) store, and the real upstream the
    ## ``post-receive`` forwards a verified push to. It is written by
    ## ``wirePushGateway`` and read by the hooks; the bare repo has no checkout,
    ## so the policy can't be re-resolved from a manifest on the receiving side.
    gateMode*: CertificateGateMode
    requiredTargets*: seq[string]
    requiredPlatforms*: seq[string]
    lockDigest*: string
      ## The ``blake3:<hex>`` lock digest a covering certificate must bind to
      ## (``certificateLockDigest`` of the resolved workspace lock). Empty when
      ## the project does not bind certificates to a lock.
    registeredKeysPath*: string
      ## Absolute path to the allowed-signers store (TC-5 registered keys). The
      ## ``pre-receive`` reads it to verify each cert's signature.
    upstreamUrl*: string
      ## The real upstream (a second bare repo standing in for GitHub) the
      ## ``post-receive`` forwards the push to on success.

proc serializeGatewayConfig*(cfg: GatewayConfig): string =
  ## Deterministic TOML writer for the gateway config.
  result = "schema = \"" & gatewayConfigSchemaV1 & "\"\n\n"
  result.add("[gateway]\n")
  result.add("gate_mode = \"" & $cfg.gateMode & "\"\n")
  result.add("lock = \"" & tomlEscapeCert(cfg.lockDigest) & "\"\n")
  result.add("registered_keys = \"" &
    tomlEscapeCert(cfg.registeredKeysPath) & "\"\n")
  result.add("upstream = \"" & tomlEscapeCert(cfg.upstreamUrl) & "\"\n")
  result.add("required_targets = [")
  for i, t in cfg.requiredTargets:
    if i > 0: result.add(", ")
    result.add("\"" & tomlEscapeCert(t) & "\"")
  result.add("]\n")
  result.add("required_platforms = [")
  for i, p in cfg.requiredPlatforms:
    if i > 0: result.add(", ")
    result.add("\"" & tomlEscapeCert(p) & "\"")
  result.add("]\n")

proc parseGatewayConfig*(content: string): GatewayConfig =
  ## Reader for ``serializeGatewayConfig``. An unrecognized / missing
  ## ``gate_mode`` resolves to ``cgmOff`` (fail-OPEN on policy is wrong for a
  ## security check, but ``cgmOff`` here means "this gateway was not configured
  ## to gate" — an unconfigured gateway forwards transparently; a gateway the
  ## daemon wired for a ``required`` project always carries ``gate_mode =
  ## "required"``).
  result.gateMode = cgmOff
  var sawSchema = false
  for rawLine in content.splitLines():
    let line = rawLine.strip()
    if line.len == 0 or line.startsWith("#"): continue
    if line.startsWith("["): continue
    let eq = line.find('=')
    if eq <= 0: continue
    let key = line[0 ..< eq].strip()
    let rhs = line[eq + 1 .. ^1]
    case key
    of "schema":
      sawSchema = parseTomlBasicValue(rhs) == gatewayConfigSchemaV1
    of "gate_mode":
      case parseTomlBasicValue(rhs)
      of "advisory": result.gateMode = cgmAdvisory
      of "required": result.gateMode = cgmRequired
      else: result.gateMode = cgmOff
    of "lock": result.lockDigest = parseTomlBasicValue(rhs)
    of "registered_keys": result.registeredKeysPath = parseTomlBasicValue(rhs)
    of "upstream": result.upstreamUrl = parseTomlBasicValue(rhs)
    of "required_targets": result.requiredTargets = parseTomlStringArray(rhs)
    of "required_platforms":
      result.requiredPlatforms = parseTomlStringArray(rhs)
    else: discard
  if not sawSchema:
    raise newException(ValueError,
      "not a " & gatewayConfigSchemaV1 & " gateway config")

proc gatewayConfigPath*(gatewayBareDir: string): string =
  ## Where the gateway config lives for a given bare repo dir.
  gatewayBareDir / gatewayConfigRelPath

proc readGatewayConfig*(gatewayBareDir: string): GatewayConfig =
  ## Read the gateway config for ``gatewayBareDir``; raises when absent (a
  ## gateway hook firing without a config is a wiring bug, not a benign state).
  let path = gatewayConfigPath(gatewayBareDir)
  if not fileExists(path):
    raise newException(ValueError,
      "gateway config not found at '" & path & "'")
  parseGatewayConfig(readFile(path))

# ---- gateway hook bodies (thin: invoke ``repro gateway <phase>``) ----------

proc gatewayPreReceiveHookBody*(): string =
  ## The bare gateway's ``pre-receive`` hook. git feeds it
  ## ``<old> <new> <ref>`` lines on stdin (one per pushed ref). The body is
  ## THIN: it locates ``repro`` and forwards stdin to ``repro gateway
  ## pre-receive --gateway-dir <GIT_DIR>``. A non-zero exit REJECTS the whole
  ## push — which is exactly the ``--no-verify``-proof enforcement point.
  result = "#!/usr/bin/env sh\n"
  result.add("# reprobuild managed pre-receive hook (push gateway)\n")
  result.add("set -eu\n\n")
  result.add("GATEWAY_DIR=$(git rev-parse --git-dir)\n")
  result.add("case \"$GATEWAY_DIR\" in /*) : ;; *) " &
    "GATEWAY_DIR=\"$(pwd)/$GATEWAY_DIR\" ;; esac\n")
  result.add("if [ -n \"${REPROBUILD_REPRO:-}\" ] && " &
    "[ -x \"$REPROBUILD_REPRO\" ]; then\n")
  result.add("  REPRO_CMD=\"$REPROBUILD_REPRO\"\n")
  result.add("elif command -v repro >/dev/null 2>&1; then\n")
  result.add("  REPRO_CMD=$(command -v repro)\n")
  result.add("else\n")
  result.add("  echo \"reprobuild gateway: repro CLI not found; " &
    "REJECTING push (fail closed)\" >&2\n")
  result.add("  exit 1\n")
  result.add("fi\n")
  result.add("exec \"$REPRO_CMD\" gateway pre-receive " &
    "--gateway-dir \"$GATEWAY_DIR\"\n")

proc gatewayPostReceiveHookBody*(): string =
  ## The bare gateway's ``post-receive`` hook. Fires only AFTER ``pre-receive``
  ## accepted + the refs were updated. It forwards the just-received refs to the
  ## real upstream by invoking ``repro gateway post-receive``. git feeds it the
  ## same ``<old> <new> <ref>`` lines on stdin.
  result = "#!/usr/bin/env sh\n"
  result.add("# reprobuild managed post-receive hook (push gateway)\n")
  result.add("set -eu\n\n")
  result.add("GATEWAY_DIR=$(git rev-parse --git-dir)\n")
  result.add("case \"$GATEWAY_DIR\" in /*) : ;; *) " &
    "GATEWAY_DIR=\"$(pwd)/$GATEWAY_DIR\" ;; esac\n")
  result.add("if [ -n \"${REPROBUILD_REPRO:-}\" ] && " &
    "[ -x \"$REPROBUILD_REPRO\" ]; then\n")
  result.add("  REPRO_CMD=\"$REPROBUILD_REPRO\"\n")
  result.add("elif command -v repro >/dev/null 2>&1; then\n")
  result.add("  REPRO_CMD=$(command -v repro)\n")
  result.add("else\n")
  result.add("  echo \"reprobuild gateway: repro CLI not found; " &
    "cannot forward to upstream\" >&2\n")
  result.add("  exit 1\n")
  result.add("fi\n")
  result.add("exec \"$REPRO_CMD\" gateway post-receive " &
    "--gateway-dir \"$GATEWAY_DIR\"\n")

# ---- clone-time push-remote wiring -----------------------------------------

proc installGatewayHooks*(gatewayBareDir: string) =
  ## Write the gateway bare's ``pre-receive`` + ``post-receive`` hooks (thin
  ## wrappers that invoke ``repro gateway <phase>``). Idempotent: overwrites
  ## with the canonical bodies.
  let hooksDir = gatewayBareDir / "hooks"
  if not dirExists(hooksDir): createDir(hooksDir)
  let pre = hooksDir / "pre-receive"
  let post = hooksDir / "post-receive"
  writeFile(pre, gatewayPreReceiveHookBody())
  writeFile(post, gatewayPostReceiveHookBody())
  when not defined(windows):
    inclFilePermissions(pre, {fpUserExec, fpGroupExec, fpOthersExec})
    inclFilePermissions(post, {fpUserExec, fpGroupExec, fpOthersExec})

proc wirePushGateway*(gitBin, repoPath, gatewayBareDir, upstreamUrl: string;
                      cfg: GatewayConfig; remoteName: string = "origin"):
    tuple[ok: bool; diagnostic: string] =
  ## CLONE-TIME wiring (Test-Certificates.md §"Enforcement"): make the
  ## daemon-managed BARE repo at ``gatewayBareDir`` the repo's push remote so a
  ## developer's ``git push`` lands on the gateway, not directly on the real
  ## upstream. Concretely:
  ##   1. ``git init --bare`` the gateway if absent.
  ##   2. Install the gateway's ``pre-receive`` + ``post-receive`` hooks.
  ##   3. Write the daemon-owned ``GatewayConfig`` (policy + lock + registered
  ##      keys + the real upstream to forward to) under the bare dir.
  ##   4. Set ``remote.<remoteName>.pushurl`` of ``repoPath`` to the gateway bare,
  ##      while ``remote.<remoteName>.url`` (FETCH) stays the real upstream — so the
  ##      developer still fetches from upstream but PUSHES through the gateway.
  ## The fetch/push split is the load-bearing piece: it routes the OUTBOUND
  ## push through the gateway's ``pre-receive`` without disturbing fetches.
  if not dirExists(gatewayBareDir):
    let initRes = gitNoteRun(gitBin,
      ["init", "--bare", gatewayBareDir])
    if initRes.code != 0:
      return (ok: false, diagnostic: "git init --bare (gateway) failed: " &
        initRes.output.strip())
  installGatewayHooks(gatewayBareDir)
  var fullCfg = cfg
  fullCfg.upstreamUrl = upstreamUrl
  writeFile(gatewayConfigPath(gatewayBareDir), serializeGatewayConfig(fullCfg))
  # Point the repo's push at the gateway; leave fetch on the real upstream.
  # A local bare repo is addressed by its absolute path (git's "local
  # transport"); no ``file://`` wrapper is needed and a plain path avoids the
  # URL-encoding / Windows-drive pitfalls of ``file://``.
  let setRes = gitNoteRun(gitBin,
    ["-C", repoPath, "remote", "set-url", "--push", remoteName,
     absolutePath(gatewayBareDir)])
  if setRes.code != 0:
    return (ok: false, diagnostic: "git remote set-url --push failed: " &
      setRes.output.strip())
  (ok: true, diagnostic: "")

# ---- pre-receive: the AUTHORITATIVE certificate verify ----------------------

type
  GatewayRefUpdate* = object
    ## One ``<old> <new> <ref>`` line from a pre/post-receive stdin stream.
    oldSha*: string
    newSha*: string
    refName*: string

proc parseGatewayRefUpdates*(stdinText: string): seq[GatewayRefUpdate] =
  ## Parse the receive-hook stdin stream into ref updates. Blank / malformed
  ## lines are skipped.
  for rawLine in stdinText.splitLines():
    let line = rawLine.strip()
    if line.len == 0: continue
    let parts = line.split(' ')
    if parts.len < 3: continue
    result.add(GatewayRefUpdate(oldSha: parts[0], newSha: parts[1],
      refName: parts[2]))

type
  GatewayVerifyResult* = object
    ## Outcome of the pre-receive certificate verify for ONE pushed branch.
    accepted*: bool
    diagnostic*: string

# ---- HL-5 (§6 Decision 3) — server-side PUBLIC-TIER lock gate --------------
#
# The pre-receive gateway is certificate-only above. HL-5 makes it ADDITIONALLY
# gate the PUBLIC tier — the ONLY tier the server can see, because the committed
# ``repro.lock`` arrives inside the pushed content while the team / personal /
# evidence backends are invisible to the receiving bare. Two checks, both
# ``--no-verify``-proof (they run server-side where client hooks cannot reach):
#
#   (a) ``lock_references_private_repo`` — REJECT if the pushed committed
#       ``repro.lock`` references a private-only repo. This is the SERVER MIRROR
#       of the client stage-5 ``lock_references_private_repo``
#       (``executeCheckPrePush``): the client uses the workspace's per-layer path
#       visibility; the server has no manifest layers, but the committed lock's
#       own per-dep ``visibility`` field (written by ``lockedDepFromStoreRepo``
#       via ``lockingTierLabel``) carries the tier. A public committed lock that
#       is tier-isolated (HL-1) carries only ``public`` deps; a dep tagged
#       anything else (``org`` / ``team`` / ``personal``) is a private-only
#       reference a public-only cloner cannot reproduce → REJECT.
#   (b) ``locked-integrity-mismatch`` — recompute each locked entry's multihash
#       against the RECEIVED content (the pushed objects, already reachable in
#       the bare) and REJECT on mismatch. Same MO-8/MO-9 integrity model as the
#       client (``verifyLockedIntegrityAtCoordinates``), but sourced from the
#       BARE repo's object store rather than a working tree.
#
# BOUNDARY (§6 Decision 3, Q3): the server gates ONLY the public tier. It never
# reads a team / personal / evidence backend — not even a same-repo
# ``git-notes`` team backend. A push with NO committed ``repro.lock`` (a repo
# that does not use the public tier) passes this gate cleanly (nothing to
# check); the certificate gate still applies independently.

const committedLockPathInTree = CommittedLockFileName
  ## The committed lock's path inside a pushed commit's tree (repo root).

proc gatewayReadPushedLock(gitBin, gatewayBareDir, commit: string): string =
  ## Read the committed ``repro.lock`` blob out of the pushed COMMIT's tree in
  ## the bare repo. In pre-receive the commit object is already present (the
  ## push delivered it) even though the branch ref update is still pending, so
  ## ``git show <commit>:repro.lock`` resolves the blob straight from the
  ## received objects. Returns "" when the pushed commit carries no
  ## ``repro.lock`` (a public-tier-less repo) or on any git error — the caller
  ## treats "no lock" as "nothing to gate", never as a pass-through of a bad
  ## lock.
  ##
  ## ``preserveObjectStore`` is REQUIRED here and is the whole reason the read
  ## works: in ``pre-receive`` the pushed commit is not in the bare's own object
  ## store yet — it sits in the push quarantine that Git names through
  ## ``GIT_OBJECT_DIRECTORY`` / ``GIT_QUARANTINE_PATH``. Dropping those makes
  ## every read of the pushed content fail, which this proc reports as "" —
  ## i.e. as "this push carries no lock" — and the gate then accepts a lock it
  ## never actually saw. The gate that exists to reject cannot be allowed to
  ## mistake blindness for absence.
  let res = gitNoteRun(gitBin,
    ["-C", gatewayBareDir, "show", commit & ":" & committedLockPathInTree],
    preserveObjectStore = true)
  if res.code != 0:
    return ""
  res.output

proc gatewayVerifyReceivedLockIntegrity(gitBin, gatewayBareDir: string;
    ld: LockedDependencies): seq[LockedIntegrityFailure] =
  ## Server-side analogue of ``verifyLockedIntegrityAtCoordinates`` for the
  ## RECEIVED committed lock: recompute each locked entry's git-native multihash
  ## against the BARE repo's object store (no working tree on the server) and
  ## report a failure on mismatch. For a git dep the integrity IS the object id
  ## at the locked revision, so verification is: the revision's object must be
  ## PRESENT in the received bare AND its self-describing object id must equal
  ## the locked integrity. A tampered ``integrity`` field, or a locked revision
  ## whose object is absent/unreachable in the received objects, fails.
  ##
  ## Only ``git-sha*`` integrities pinned at a concrete revision are verified
  ## here — those are the entries whose content the SERVER actually received.
  ## Entries with no integrity, a non-git integrity (a pre-commit ``blake3:``
  ## tree hash needs a working tree the bare does not have), or no concrete
  ## revision are left to the client gate; the server makes no false claim about
  ## content it cannot recompute.
  result = @[]
  if gitBin.len == 0: return
  let objFmt = gitObjectFormatOf(gatewayBareDir)
  for d in ld.deps:
    if d.integrity.len == 0: continue
    if d.coordinates.kind != ckVcs: continue
    if not d.integrity.startsWith("git-sha"): continue
    if d.coordinates.revision.len == 0: continue
    # The locked revision's object must be present among the received objects.
    # ``preserveObjectStore`` keeps the push quarantine visible: without it the
    # objects this push delivered are unreachable and EVERY locked revision
    # would look "not present", turning a clean push into a false refusal.
    let rp = gitNoteRun(gitBin,
      ["-C", gatewayBareDir, "rev-parse", "--verify", "--quiet",
       d.coordinates.revision & "^{commit}"],
      preserveObjectStore = true)
    if rp.code != 0 or rp.output.strip().len == 0:
      result.add(LockedIntegrityFailure(name: d.name, path: d.path,
        expected: d.integrity, observed: "",
        revision: d.coordinates.revision,
        cause: licRevisionUnreachable,
        diagnostic: "locked revision " & d.coordinates.revision &
          " is not present/reachable in the received objects for '" &
          (if d.path.len > 0: d.path else: ".") & "'"))
      continue
    let observed = gitObjectMultihash(objFmt, d.coordinates.revision)
    if observed != d.integrity:
      result.add(LockedIntegrityFailure(name: d.name, path: d.path,
        expected: d.integrity, observed: observed,
        diagnostic: "recomputed integrity " & observed &
          " at the received locked coordinates does not match the lock's " &
          "recorded integrity " & d.integrity))

proc gatewayVerifyPublicLock*(gitBin, gatewayBareDir: string;
                              updates: seq[GatewayRefUpdate]):
    GatewayVerifyResult =
  ## HL-5 (§6 Decision 3) — the PUBLIC-TIER lock gate. For each pushed BRANCH
  ## update, read the committed ``repro.lock`` blob from the received commit and
  ## run the two checks: (a) reject a private-only reference
  ## (``lock_references_private_repo``); (b) reject an integrity mismatch
  ## (``locked-integrity-mismatch``). A branch with NO ``repro.lock`` in its
  ## tree is a no-op (public-tier-less repo). ALWAYS runs (independent of the
  ## certificate ``gate_mode``): the public-tier lock invariant holds for every
  ## public repo regardless of whether the project opts into certificates.
  result.accepted = true
  let zeroSha = "0000000000000000000000000000000000000000"
  for u in updates:
    if not u.refName.startsWith("refs/heads/"): continue
    if u.newSha == zeroSha: continue  # branch deletion — nothing in the tree.
    let lockBlob = gatewayReadPushedLock(gitBin, gatewayBareDir, u.newSha)
    if lockBlob.strip().len == 0:
      continue  # no public lock in this push — nothing to gate (boundary).
    var ld: LockedDependencies
    try:
      ld = parseLockedDependencies(lockBlob)
    except CatchableError as err:
      # A malformed committed lock about to become the public boundary is
      # itself refusal-worthy — a public-only cloner could not consume it.
      result.accepted = false
      result.diagnostic = u.refName &
        ": lock_references_private_repo/lock-parse-failed: the pushed " &
        committedLockPathInTree & " does not parse (" & err.msg & ")"
      return
    # (a) private-ref check — the committed public lock must reference ONLY
    # public-tier repos. ``visibility`` "" (default) or "public" is fine; any
    # other tier is a private-only reference the server rejects.
    for d in ld.deps:
      let vis = d.visibility.strip().toLowerAscii()
      if vis.len > 0 and vis != "public":
        result.accepted = false
        result.diagnostic = u.refName &
          ": lock_references_private_repo: the pushed public " &
          committedLockPathInTree & " references the private-only repo '" &
          (if d.path.len > 0: d.path else: d.name) & "' (visibility=" &
          d.visibility & "); a public-only clone cannot reproduce it — " &
          "remove it from the public lock or publish it under a non-public " &
          "tier's backend"
        return
    # (b) integrity check against the received objects.
    let failures = gatewayVerifyReceivedLockIntegrity(
      gitBin, gatewayBareDir, ld)
    if failures.len > 0:
      let f = failures[0]
      result.accepted = false
      result.diagnostic = u.refName &
        ": locked-integrity-mismatch: '" &
        (if f.path.len > 0: f.path else: f.name) & "' — " & f.diagnostic
      return

proc gatewayVerifyPush*(gitBin, gatewayBareDir: string;
                        updates: seq[GatewayRefUpdate];
                        cfg: GatewayConfig): GatewayVerifyResult =
  ## The AUTHORITATIVE receiving-side check. For each pushed BRANCH update,
  ## read the certificates that arrived for the pushed commit (from the
  ## INCOMING ``refs/notes/reprobuild/certificates`` value — already an object
  ## in this bare repo because the push delivered it) and, under a ``required``
  ## policy, require that a registered-SIGNED (TC-5) certificate COVERS (TC-1)
  ## the pushed commit for the required targets on EACH required platform.
  ##
  ## REUSE, not re-implementation: the per-cert signature check is the TC-5
  ## ``verifyCertificateSignature`` and the per-platform coverage is the TC-1
  ## ``verifyCoverage`` — exactly what the client gate (TC-3) runs, but here on
  ## the receiving side where ``--no-verify`` cannot reach.
  result.accepted = true
  # ``off`` → transparent forward (no cert check at all). ``advisory`` →
  # records the verdict but never rejects. ``required`` → rejects on a miss.
  if cfg.gateMode == cgmOff:
    return
  if cfg.requiredPlatforms.len == 0:
    # Opted in but nothing to enforce (required_platforms may be none).
    return
  # Locate the incoming notes-ref value: the new SHA the push set for
  # ``refs/notes/reprobuild/certificates``. In pre-receive the ref is not yet
  # in place, but the SHA is already a reachable object, so we read the note
  # straight off that commit-ish.
  var notesSha = ""
  for u in updates:
    if u.refName == certificateNotesRef:
      notesSha = u.newSha
  let keyStore = readRegisteredKeyStore(cfg.registeredKeysPath)
  let zeroSha = "0000000000000000000000000000000000000000"
  for u in updates:
    # Only gate branch pushes; the notes ref + tags are not the gated unit.
    if not u.refName.startsWith("refs/heads/"): continue
    if u.newSha == zeroSha: continue  # branch deletion — nothing to attest.
    let pushedCommit = u.newSha
    # Read the certs that arrived for this commit. Prefer the incoming notes
    # SHA (pre-receive: ref not yet updated); fall back to the well-known ref
    # for a post-receive / already-updated read.
    # ``preserveObjectStore``: the certificate note arrives in the SAME push as
    # the commit it attests, so its objects are in the push quarantine too. A
    # scrubbed read finds no certificate for any commit and a ``required``
    # gate then refuses every push — including the covered ones it is meant to
    # let through.
    var attached: seq[TestCertificate]
    if notesSha.len > 0 and notesSha != zeroSha:
      attached = readAttachedCertificatesFromRef(
        gitBin, gatewayBareDir, pushedCommit, notesSha,
        preserveObjectStore = true)
    if attached.len == 0:
      attached = readAttachedCertificatesFromRef(
        gitBin, gatewayBareDir, pushedCommit, certificateNotesRef,
        preserveObjectStore = true)
    # Drop every cert that is not a registered-signed, unrevoked, valid-sig
    # attestation (TC-5) BEFORE coverage (TC-1).
    var trusted: seq[TestCertificate]
    var sigNotes: seq[string]
    for cert in attached:
      let verdict = verifyCertificateSignature(cert, keyStore)
      if verdict == svValid:
        trusted.add(cert)
      else:
        let why =
          case verdict
          of svUnsigned: "unsigned"
          of svUnregisteredKey: "key_id '" & cert.keyId & "' not registered"
          of svRevokedKey: "key_id '" & cert.keyId & "' revoked"
          of svBadSignature: "signature does not verify"
          of svToolingUnavailable: "ssh-keygen unavailable"
          of svValid: ""
        sigNotes.add(cert.platform & ": " & why)
    var missing: seq[string]
    for platform in cfg.requiredPlatforms:
      let req = CoverageRequirement(
        commit: pushedCommit,
        lock: cfg.lockDigest,
        platform: platform,
        requiredTargets: cfg.requiredTargets)
      let cov = verifyCoverage(trusted, req)
      if not cov.covered:
        missing.add(platform & " (missing: " &
          (if cov.missingTargets.len > 0: cov.missingTargets.join(", ")
           else: "<no certificate>") & ")")
    if missing.len > 0:
      let sigDetail =
        if sigNotes.len > 0: " (untrusted certs ignored: " &
          sigNotes.join("; ") & ")"
        else: ""
      let detail = u.refName & ": uncovered: " & missing.join("; ") & sigDetail
      if cfg.gateMode == cgmRequired:
        result.accepted = false
        result.diagnostic = detail
        return
      else:  # advisory — record but accept.
        result.diagnostic = "advisory: " & detail

proc gatewayForwardToUpstream*(gitBin, gatewayBareDir, upstreamUrl: string;
                               updates: seq[GatewayRefUpdate]):
    tuple[ok: bool; diagnostic: string] =
  ## ``post-receive`` forward: push the just-received refs from the gateway
  ## bare to the REAL upstream bare. We push each received ref by its value;
  ## branch deletions propagate as deletions. The certificate notes ref is
  ## forwarded too so the upstream carries the attestations. A failure to
  ## forward is reported but does NOT roll back the gateway (the gateway is the
  ## reproducibility boundary; the upstream catches up on the next push).
  var refspecs: seq[string]
  let zeroSha = "0000000000000000000000000000000000000000"
  for u in updates:
    if u.newSha == zeroSha:
      refspecs.add(":" & u.refName)             # deletion
    else:
      refspecs.add(u.newSha & ":" & u.refName)  # set ref to the received value
  if refspecs.len == 0:
    return (ok: true, diagnostic: "no refs to forward")
  var argv = @["-C", gatewayBareDir, "push", upstreamUrl]
  for r in refspecs: argv.add(r)
  let res = gitNoteRun(gitBin, argv)
  if res.code != 0:
    return (ok: false, diagnostic: "forward push to upstream failed: " &
      res.output.strip())
  (ok: true, diagnostic: "")

# ---- ``repro gateway <phase>`` dispatch ------------------------------------

proc parseGatewayDirFlag(args: openArray[string]): string =
  ## Extract ``--gateway-dir <PATH>`` (or ``--gateway-dir=PATH``). Defaults to
  ## ``GIT_DIR`` / cwd so an operator can run the verb manually inside the bare.
  for i, a in args:
    if a == "--gateway-dir" and i + 1 < args.len:
      return args[i + 1]
    if a.startsWith("--gateway-dir="):
      return a["--gateway-dir=".len .. ^1]
  let gitDir = getEnv("GIT_DIR")
  if gitDir.len > 0: return gitDir
  getCurrentDir()

proc runGatewayCommand*(args: openArray[string]): int =
  ## ``repro gateway <phase> [--gateway-dir PATH]`` — the thin entry point the
  ## gateway bare's hooks invoke. Two phases:
  ##   - ``pre-receive``  : read ``<old> <new> <ref>`` lines from stdin, run the
  ##     AUTHORITATIVE certificate verify, exit non-zero to REJECT on a miss.
  ##   - ``post-receive`` : read the same stream, FORWARD the received refs to
  ##     the real upstream bare.
  if args.len == 0:
    stderr.writeLine("repro gateway: expected a phase " &
      "(pre-receive | post-receive)")
    return 2
  let phase = args[0]
  let gatewayDir = parseGatewayDirFlag(args)
  let gitBin = findExe("git")
  if gitBin.len == 0:
    stderr.writeLine("repro gateway: git not found on PATH; " &
      "REJECTING (fail closed)")
    return 1
  var cfg: GatewayConfig
  try:
    cfg = readGatewayConfig(gatewayDir)
  except CatchableError as err:
    stderr.writeLine("repro gateway: " & err.msg & "; REJECTING (fail closed)")
    return 1
  let stdinText = stdin.readAll()
  let updates = parseGatewayRefUpdates(stdinText)
  case phase
  of "pre-receive":
    # Cert gate (TC-5/TC-1) — kept verbatim (HL-5 is ADDITIVE).
    let verdict = gatewayVerifyPush(gitBin, gatewayDir, updates, cfg)
    if verdict.diagnostic.len > 0:
      stderr.writeLine("reprobuild gateway: " & verdict.diagnostic)
    if not verdict.accepted:
      stderr.writeLine("reprobuild gateway: push REJECTED — no covering " &
        "test certificate (run 'repro certify' then push). The receiving-" &
        "side gateway is authoritative; '--no-verify' does not bypass it.")
      return 1
    # HL-5 (§6 Decision 3) — the ADDITIVE PUBLIC-TIER lock gate. Runs after the
    # certificate gate; BOTH must pass. It reads the received committed
    # ``repro.lock`` and rejects a private-only reference or an integrity
    # mismatch. Server-side, so ``--no-verify`` cannot bypass it (same
    # enforcement point as the cert gate). The server gates ONLY the public
    # tier — team/personal/evidence backends are never read.
    let lockVerdict = gatewayVerifyPublicLock(gitBin, gatewayDir, updates)
    if lockVerdict.diagnostic.len > 0:
      stderr.writeLine("reprobuild gateway: " & lockVerdict.diagnostic)
    if not lockVerdict.accepted:
      stderr.writeLine("reprobuild gateway: push REJECTED — the pushed " &
        "public repro.lock failed the server-side public-tier lock gate. " &
        "The receiving-side gateway is authoritative; '--no-verify' does " &
        "not bypass it.")
      return 1
    return 0
  of "post-receive":
    let fwd = gatewayForwardToUpstream(gitBin, gatewayDir, cfg.upstreamUrl,
      updates)
    if not fwd.ok:
      stderr.writeLine("reprobuild gateway: " & fwd.diagnostic)
      return 1
    return 0
  else:
    stderr.writeLine("repro gateway: unknown phase '" & phase &
      "' (expected: pre-receive | post-receive)")
    return 2

proc developSetClosure(repos: seq[ResolvedRepo];
    pushedRepoName: string): HashSet[string] =
  ## RA-21 — compute the transitive develop-set dependency closure of the
  ## pushed repo, as a set of repo NAMES. The closure is the pushed repo
  ## itself plus every repo reachable through the per-repo ``depends``
  ## edges (Workspace-And-Develop-Mode.md §"VCS Hook Integration": a
  ## develop-mode sibling is a git-submodule replacement, so only the
  ## pushed repo's own dependency closure can break a teammate's build of
  ## it). Unknown dependency names (a ``depends`` entry that names no repo
  ## in the resolved set) are skipped — the closure only ever contains
  ## repos that actually participate in this workspace.
  ##
  ## When ``pushedRepoName`` is empty (the hook was invoked without a
  ## resolvable ``--current-repo``), the closure is empty and the caller
  ## falls back to the whole-workspace scope so the gate never silently
  ## under-checks.
  result = initHashSet[string]()
  if pushedRepoName.len == 0:
    return
  var byName = initTable[string, ResolvedRepo]()
  for repo in repos:
    byName[repo.name] = repo
  if pushedRepoName notin byName:
    return
  var pending = @[pushedRepoName]
  while pending.len > 0:
    let name = pending.pop()
    if name in result:
      continue
    result.incl(name)
    if name in byName:
      for dep in byName[name].depends:
        if dep.len > 0 and dep notin result:
          pending.add(dep)

proc repoNameForFragment(identity: GitToolIdentity; membershipRoot, relPath,
    newTip, oldTip: string): string =
  ## Resolve a changed ``repos/<file>.toml`` fragment to the repo NAME it
  ## declares. The file's basename is NOT the name: a fragment may declare a
  ## different one (``repos/accounting-blocksense.toml`` declares
  ## ``name = "accounting"``), so read the fragment's own ``[repo] name``. The
  ## blob is read from the pushed tip, falling back to the pre-push tip for a
  ## fragment the commit DELETED (removing a repo from the workspace is exactly
  ## the kind of membership change the scope must cover). Basename is the last
  ## resort so an unreadable blob narrows the scope rather than dropping it.
  for tip in [newTip, oldTip]:
    if tip.len == 0:
      continue
    let show = gitRunPlain(identity,
      ["-C", membershipRoot, "show", tip & ":" & relPath])
    if show.code != 0:
      continue
    for rawLine in show.output.splitLines():
      let line = rawLine.strip()
      if line.startsWith("name") and '=' in line:
        let value = line[line.find('=') + 1 .. ^1].strip()
        let unquoted = value.strip(chars = {'"', '\''})
        if unquoted.len > 0:
          return unquoted
  relPath.extractFilename.changeFileExt("")

proc membershipPushScope(identity: GitToolIdentity; resolved: ResolvedProject;
    membershipRoot, newTip, oldTip: string): HashSet[string] =
  ## Workspace-And-Develop-Mode.md §"Gate scope when the pushed repo is the
  ## membership repo" — the repos whose manifest fragments the pushed commit
  ## range actually modifies. A manifest commit can only break a teammate on a
  ## repo whose pin or membership IT changes (a revision re-pinned to a SHA
  ## nobody pushed, a repo added that nobody can clone); a repo the commit does
  ## not mention cannot be broken by it. An empty result is a real answer —
  ## "this commit touches no fragment" — and scopes the gate to the membership
  ## repo's own cleanliness/publication, NOT to the whole workspace.
  result = initHashSet[string]()
  if newTip.len == 0:
    return
  # Prefer the exact pushed range. A brand-new remote branch has no old tip, so
  # fall back to the tip commit's own first-parent diff: still a well-defined
  # "what this push introduces" for the common single-commit case, and far
  # narrower than widening to every repo in the workspace.
  var diff = gitRunPlain(identity,
    ["-C", membershipRoot, "diff", "--name-only", oldTip & ".." & newTip])
  if oldTip.len == 0 or diff.code != 0:
    diff = gitRunPlain(identity,
      ["-C", membershipRoot, "diff", "--name-only", newTip & "^", newTip])
  if diff.code != 0:
    return
  var byName = initTable[string, ResolvedRepo]()
  for repo in resolved.repos:
    byName[repo.name] = repo
  for rawPath in diff.output.splitLines():
    let relPath = rawPath.strip()
    if relPath.len == 0 or not relPath.endsWith(".toml"):
      continue
    if relPath.startsWith("repos/"):
      let name = repoNameForFragment(identity, membershipRoot, relPath,
        newTip, oldTip)
      if name.len > 0 and name in byName:
        result.incl(name)
    elif relPath.startsWith("projects/"):
      # A project manifest changed: its membership as a whole is what moved, so
      # the repos that project declares are in scope. Only repos that actually
      # participate in the resolved workspace can be observed, so intersect.
      let projectName = relPath.extractFilename.changeFileExt("")
      if projectName == resolved.projectName:
        for repo in resolved.repos:
          result.incl(repo.name)
      else:
        let projectFile = membershipRoot / "projects" / (projectName & ".toml")
        if fileExists(projectFile):
          try:
            for repo in resolveProject(projectFile).repos:
              if repo.name in byName:
                result.incl(repo.name)
          except CatchableError:
            # A project manifest we cannot resolve (malformed, or referencing
            # fragments this workspace does not carry) contributes nothing
            # rather than failing the gate on a parse error.
            discard

proc prePushScope(resolved: ResolvedProject; currentRepoName: string;
    currentLayer: Option[ManifestLayerLocation];
    membershipScope: Option[HashSet[string]] = none(HashSet[string])):
      tuple[names: HashSet[string]; wholeWorkspace: bool] =
  ## Normal repo pushes use RA-21's develop-set closure. Manifest-layer pushes
  ## are not project repos, so the old empty-closure fallback would widen them
  ## to the whole composed workspace and make private layers block public-layer
  ## publication. Use the current layer's declarations instead.
  ##
  ## A push of the MEMBERSHIP repo (the ``repro-workspace`` repo carrying
  ## ``projects/``/``repos/``) is neither: it declares no ``depends`` edges, so
  ## its closure is empty, and in the flat native layout it is not a
  ## ``[[manifest]]`` layer either — which is how it used to fall through to the
  ## whole-workspace fallback and let an unrelated dirty sibling block a
  ## one-line manifest edit. ``membershipScope`` carries the touched-fragment
  ## answer (``membershipPushScope``); when present it is authoritative, INCLUDING
  ## when it is empty.
  result.names = developSetClosure(resolved.repos, currentRepoName)
  if result.names.len > 0:
    result.wholeWorkspace = false
    return
  if membershipScope.isSome:
    result.names = membershipScope.get()
    result.wholeWorkspace = false
    return
  if currentLayer.isSome:
    result.names = repoNamesDeclaredByLayer(
      currentLayer.get(), resolved.projectName)
    result.wholeWorkspace = false
    return
  result.wholeWorkspace = true

type
  UnreadableRepoGateOutcome* = object
    ## MO-5 — the gate's decision for ONE private repo whose source is not
    ## present locally. ``failed`` ⇒ ``failure`` is the actionable
    ## ``CheckFailure`` the gate surfaces (clone-required for a shared-private
    ## repo, or evidence-unverified for an evidence-only repo whose published
    ## evidence does not prove the boundary). Otherwise ``notice`` describes the
    ## satisfied evidence-only boundary the gate consumed in lieu of a clone.
    failed*: bool
    failure*: CheckFailure
    notice*: string
    verdict*: UnreadableRepoResult

proc gateDecideUnreadableRepo*(repo: ResolvedRepo; store: LockStore;
    project: string): UnreadableRepoGateOutcome =
  ## MO-5 — the single source of truth for how the pre-push gate / ``repro
  ## check`` treats a PRIVATE repo with no local checkout. Both
  ## ``executeCheckPrePush`` and the MO-5 integration test call this exact proc,
  ## so the test exercises the gate's real decision rather than a re-implementation.
  ##
  ##   * A SHARED-private repo (no ``participation = "evidence-only"`` marker) is
  ##     expected to be cloned — a missing checkout is an actionable
  ##     ``clone-required`` failure.
  ##   * An EVIDENCE-ONLY repo is verified by CONSUMING its published source-free
  ##     evidence (``store.getEvidence``) + the locked SHA from the same backend:
  ##     clean + published + at-locked-SHA satisfies the boundary; anything else
  ##     (dirty / unpublished / sha-mismatch / evidence-missing) still FAILS.
  if not isEvidenceOnlyRepo(repo):
    result.failed = true
    result.failure = CheckFailure(
      repo: repo.path,
      property: "clone-required",
      remediation: "gain read access to '" & repo.fetchUrl &
        "' and clone it into " & repo.path &
        " (a shared-private repo must be checked out), or mark it " &
        "`participation = \"evidence-only\"` if it should participate by " &
        "published evidence instead",
      evidence: "shared-private repo source is not present locally " &
        "(no .git at " & repo.path & ") and the repo is not evidence-only")
    return
  let lockedSha = lockedShaFromStore(store, project, repo.name, repo.path)
  result.verdict = evaluateEvidenceOnlyParticipation(
    store, project, repo.name, repo.path, lockedSha)
  if result.verdict.verdict == urvEvidenceSatisfied:
    result.notice = "evidence-only private repo '" & repo.path &
      "' verified from published evidence (clean, published, at locked SHA " &
      result.verdict.lockedSha & ") — source not required"
  else:
    result.failed = true
    result.failure = CheckFailure(
      repo: repo.path,
      property: "evidence-only-unverified",
      remediation: "re-publish current evidence for '" & repo.path &
        "' from a clean, published checkout at the locked revision " &
        "(repro records the source-free head-sha/clean/published triple)",
      evidence: result.verdict.diagnostic)

# ---------------------------------------------------------------------------
# HL-3 (§6 Decision 2) — refuse-for-shared / warn-for-personal on an
# unreachable backend.
#
# When a repo's assigned durable backend is unreachable/unwritable at pre-push:
#   - public or team backend  ⇒ REFUSE the push (exit 2), loud, with a remedy
#     naming the repo path + tier + backend kind & location + the underlying
#     diagnostic + a single copy-pasteable next step;
#   - personal backend        ⇒ WARN but ALLOW (exit unchanged), advising
#     ``repro workspace lock`` — the verb that records the missed participation
#     in that backend once it is reachable again.
# The signal is a per-repo ``ParticipationOutcome`` that ATTEMPTED a write
# (``attempted == true``, i.e. a real backend, not the committed-lock no-op)
# and did NOT succeed (``recorded == false``). HL-2 discarded this by tier; HL-3
# threads it to the gate and applies the split.
# ---------------------------------------------------------------------------

proc tierIsShared(v: WorkspaceVisibility): bool =
  ## Public and team/org backends are SHARED — teammates depend on them, so an
  ## unreachable one REFUSES. Only ``wvPersonal`` is the user's own backend.
  v in {wvPublic, wvOrg, wvTeam}

proc participationFailed(outc: ParticipationOutcome): bool =
  ## A genuine unreachable/unwritable backend: a real write was attempted and
  ## did not succeed. A committed-lock skip (``attempted == false``) is never a
  ## failure.
  outc.attempted and not outc.recorded

proc backendUnreachableRemedy(outc: ParticipationOutcome): string =
  ## §6 Decision 2 "Remedy text shape": name the repo path, its tier, the
  ## backend kind + location, the underlying diagnostic, and a single
  ## copy-pasteable next step.
  let loc =
    if outc.backendLocation.len > 0: " at " & outc.backendLocation else: ""
  var s = lockingTierLabel(outc.tier) & " repo '" & outc.repoPath &
    "' could not be published to its " & outc.backendKind & " backend" & loc
  if outc.diagnostic.len > 0:
    s.add(" (" & outc.diagnostic & ")")
  s.add("; make the backend reachable and re-run `repro push`")
  s

proc personalBackendWarning(outc: ParticipationOutcome;
                            workspaceRoot: string): string =
  ## §6 Decision 2 personal-tier warning: name the repo, the personal backend,
  ## and the verb that records the participation once the backend is back.
  ##
  ## That record is a WORKSPACE lock entry in the personal backend, so the verb
  ## is ``repro workspace lock``. It used to say ``repro lock refresh``, which
  ## re-pins the committed solved-graph ``repro.lock`` instead and exits 1 with
  ## "no solver inputs found" in a workspace that has no recipe.
  let loc =
    if outc.backendLocation.len > 0: " at " & outc.backendLocation else: ""
  "personal lock backend " & outc.backendKind & loc &
    " is unreachable; personal repo '" & outc.repoPath &
    "' participation was not recorded — run `" &
    workspaceLockCommand(workspaceRoot) & "` when it is reachable"

proc applyParticipationTierPolicy(report: var CheckReport) =
  ## HL-3 (§6 Decision 2) — inspect each per-repo ``ParticipationOutcome`` by
  ## tier and apply the refuse-for-shared / warn-for-personal split. A failed
  ## public/team write adds a ``lock-backend-unreachable`` ``CheckFailure`` and
  ## sets ``exitCode = 2``; a failed personal write adds a ``notices`` warning
  ## and leaves ``exitCode`` unchanged. Idempotent for the empty / all-recorded
  ## case (no explicit routes ⇒ ``@[]`` ⇒ no-op, byte-identical to pre-HL-3).
  # Snapshot before mutating the report. Passing ``report.participation`` as a
  # second argument while also passing ``report`` by ``var`` aliases the same
  # object; Nim may materialize the ``var`` argument through a temporary, so
  # the failure/notice mutations are lost even though the participation array
  # itself is present in the returned report.
  let outcomes = report.participation
  for outc in outcomes:
    if not participationFailed(outc): continue
    if tierIsShared(outc.tier):
      report.failures.add(CheckFailure(
        repo: outc.repoPath,
        property: "lock-backend-unreachable",
        remediation: backendUnreachableRemedy(outc),
        evidence: "tier=" & lockingTierLabel(outc.tier) &
          " backend=" & outc.backendKind &
          (if outc.backendLocation.len > 0:
             " location=" & outc.backendLocation else: "") &
          (if outc.diagnostic.len > 0: " diagnostic=" & outc.diagnostic
           else: "")))
      report.exitCode = 2
    else:
      report.notices.add(personalBackendWarning(outc, report.workspaceRoot))

proc evidenceReadBackendUnreachable(verdict: UnreadableRepoVerdict): bool =
  ## HL-6 (§7.3) — distinguish an evidence-only failure that stems from the
  ## backend being UNREACHABLE for the evidence READ (no store constructed / no
  ## published evidence to read) from one where the evidence WAS read and proves
  ## the boundary violated (dirty / unpublished / sha-mismatch / no-lock). Only
  ## the former is subject to Decision 2's tier split — a violation the evidence
  ## itself reports must FAIL regardless of tier.
  verdict in {urvEvidenceNoBackend, urvEvidenceMissing}

proc evidenceReadUnreachableWarning(repoPath, backendKind,
                                    workspaceRoot: string): string =
  ## §7.3 personal-tier warning for an unreachable evidence READ, shaped like
  ## the write-side ``personalBackendWarning`` — and naming the same verb, for
  ## the same reason: the record is a WORKSPACE lock entry.
  "personal lock backend " & backendKind &
    " is unreachable for the evidence read of personal repo '" & repoPath &
    "' — run `" & workspaceLockCommand(workspaceRoot) &
    "` when it is reachable"

type
  EvidenceReadGateDecision* = enum
    ## HL-6 (§7.3) — how the pre-push gate treats one evidence-only repo whose
    ## published evidence was consumed in lieu of a clone.
    ergdSatisfied   ## evidence proves the boundary (clean+published+at-locked)
    ergdRefuse      ## FAIL exit 2: violation, or a SHARED-tier unreachable read
    ergdWarnAllow   ## exit 0 + notice: a PERSONAL-tier unreachable evidence read

proc decideEvidenceReadTierPolicy*(outcome: UnreadableRepoGateOutcome;
    visibility: WorkspaceVisibility): EvidenceReadGateDecision =
  ## HL-6 (§7.3) — the SINGLE decision the pre-push gate applies to an
  ## evidence-only repo's consumed evidence, so the test drives the gate's real
  ## decision (not a re-implementation). Decision 2's loud-vs-warn applies to the
  ## evidence READ of an UNREACHABLE backend: a team/public (SHARED) tier REFUSES
  ## (teammates depend on it), a PERSONAL tier WARNS but ALLOWS (the user's own
  ## backend). An evidence-proven violation (dirty / unpublished / sha-mismatch /
  ## no-lock) FAILS regardless of tier; a satisfied boundary passes.
  if not outcome.failed:
    return ergdSatisfied
  if evidenceReadBackendUnreachable(outcome.verdict.verdict) and
      not tierIsShared(visibility):
    return ergdWarnAllow
  ergdRefuse

type
  LockPinFinding = object
    ## One lock record that PINS a commit an outgoing history rewrite would
    ## make unreachable. Empty ``orphanOid`` means no such record exists.
    orphanOid*: string
    lockedPath*: string     ## the repo path the record pins at ``orphanOid``
    lockRelPath*: string    ## store-relative path of the offending record
    lockRoot*: string       ## on-disk root that record was found under
    lockTriggerSha*: string ## the commit the record is KEYED at

proc looksLikeCommitOid(value: string): bool =
  ## A manifest ``revision`` may name either a branch or an exact commit. Only
  ## the branch spelling can be compared against a pushed ref name.
  if value.len notin {40, 64}: return false
  for ch in value:
    if ch notin {'0'..'9', 'a'..'f', 'A'..'F'}: return false
  true

proc declaredMainlineBranch(resolved: ResolvedProject;
    repoName: string): string =
  ## The branch the MANIFEST declares this repo's mainline to be: the repo
  ## fragment's ``branch``, else its ``revision`` when that names a branch
  ## rather than a pin, else the project's ``trunk``. Returns "" when the
  ## manifest declares nothing — the caller must not infer one, because a
  ## blanket refusal justified by an inference is exactly the shape that
  ## teaches operators to reach for ``--no-verify``.
  if repoName.len == 0: return ""
  for repo in resolved.repos:
    if repo.name != repoName: continue
    if repo.branch.len > 0: return repo.branch
    if repo.revision.len > 0 and not looksLikeCommitOid(repo.revision):
      return repo.revision
    break
  resolved.trunk

proc lockRecordTriggerSha(relPath: string): string =
  ## The commit a lock record is KEYED at — its filename stem. Handles both
  ## the canonical per-repo shape ``locks/<project>/<repo>/<sha>.toml`` and the
  ## monolithic ``locks/<project>/<sha>.toml`` one, because the exclusion below
  ## must hold for either.
  let parsed = parseLockRecordRelPath(relPath)
  if parsed.ok:
    return parsed.sha.toLowerAscii()
  let parts = relPath.replace('\\', '/').split('/')
  if parts.len < 2 or not parts[^1].endsWith(".toml"): return ""
  let stem = parts[^1][0 ..< parts[^1].len - ".toml".len]
  var decoded: string
  if tryDecodeLockPathSegment(stem, decoded) and decoded.len > 0:
    return decoded.toLowerAscii()
  stem.toLowerAscii()

proc workspaceLockRoots(workspaceRoot: string;
    layerLocations: openArray[ManifestLayerLocation]): seq[string] =
  ## Every on-disk root that can own a ``locks/`` subtree for this workspace.
  ##
  ## This deliberately mirrors every arm of ``pickManifestLayerRoot`` rather
  ## than calling it: that proc answers "where does THIS operation write", and
  ## a rewrite must be checked against every record the workspace can still
  ## READ. The arms are the native ``.repro/manifests`` git-checkout store, the
  ## composer's materialised ``.repro/manifests-<i>-<slug>`` layers, an
  ## explicitly declared ``[[manifest]]`` layer, the membership root, and the
  ## workspace root itself. Roots with no ``locks/`` subtree cost nothing.
  var candidates = @[
    workspaceRoot / ".repro" / "manifests",
    manifestsRoot(workspaceRoot),
    workspaceRoot]
  for loc in layerLocations:
    candidates.add(loc.absPath)
  let reproDirPath = workspaceRoot / ".repro"
  if dirExists(reproDirPath):
    for kind, path in walkDir(reproDirPath):
      if kind in {pcDir, pcLinkToDir} and
          extractFilename(path).startsWith("manifests-"):
        candidates.add(path)
  var seen = initHashSet[string]()
  for candidate in candidates:
    if candidate.len == 0: continue
    let key =
      try: os.normalizedPath(absolutePath(candidate))
      except CatchableError: candidate
    if key in seen: continue
    seen.incl(key)
    if dirExists(candidate / "locks"):
      result.add(candidate)

proc findLockPinningOrphan(identity: GitToolIdentity;
    lockRoots: openArray[string];
    orphans: HashSet[string]): LockPinFinding =
  ## Search every workspace lock record for one that PINS a commit the
  ## outgoing rewrite would make unreachable.
  ##
  ## Records whose OWN trigger commit is in the orphan set are EXCLUDED, and
  ## that exclusion is the whole reason this is not a restatement of the
  ## fast-forward rule it replaces. The gate writes a lock keyed at the commit
  ## it is publishing and pinning that same commit, so after any successful
  ## push the branch tip is pinned by its own record. Counting that record
  ## would refuse every rebase-and-force-push in a locked workspace — exactly
  ## the case this change exists to permit — while protecting nothing: a
  ## snapshot ANCHORED at a commit that no longer exists cannot be asked for.
  ##
  ## What must be protected is a record anchored at a SURVIVING commit (a
  ## sibling repo's, or an earlier one of this repo's) that pins an orphaned
  ## commit: that snapshot is still reachable and reproducing it still needs
  ## the commit this push would delete.
  if orphans.len == 0: return
  for root in lockRoots:
    for cand in orderedLockCandidates(identity, root, "locks/"):
      let trigger = lockRecordTriggerSha(cand.relPath)
      if trigger.len > 0 and trigger in orphans:
        continue
      let lockPath = root / cand.relPath.replace('/', DirSep)
      let body =
        try: readFile(extendedPath(lockPath))
        except CatchableError: ""
      if body.len == 0: continue
      for path, rev in shasFromBody(body):
        let oid = rev.strip().toLowerAscii()
        if oid in orphans:
          return LockPinFinding(orphanOid: oid, lockedPath: path,
            lockRelPath: cand.relPath, lockRoot: root, lockTriggerSha: trigger)

proc executeCheckPrePush(parsed: CheckArgs): CheckReport =
  ## Drive the five-stage gate. Each stage short-circuits on the first
  ## failure — the spec is explicit that the gate names ONE failure at
  ## a time so the operator's next step is unambiguous. RA-3 removed the
  ## former branch-mismatch stage (no branch-name enforcement); the gate
  ## now starts at the sibling-repo cleanliness check. M23 inserted
  ## the develop-override cleanliness stage between the sibling-repo
  ## ``unpublished`` stage and the lock-currency stage; the stage is a
  ## no-op when no ``.repro/develop-overrides.toml`` exists. M26 adds
  ## the fifth ``lock_references_private_repo`` stage after the lock-
  ## currency stage; the stage is a no-op when the current-repo is not
  ## a manifest-layer repo or when no lock files are being pushed.
  result.mode = "pre-push"
  result.workspaceRoot = parsed.workspaceRoot
  result.currentRepo = parsed.currentRepo
  result.pushedRefsPath = parsed.pushedRefsPath

  let (resolved, workspaceLocal) = resolveCheckProject(parsed)
  result.project = resolved.projectName

  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # Build a name-keyed lookup of the pushed checkout before any repository
  # observation. A linked worktree is intentionally outside the declared
  # checkout path, but it still has the same authoritative Git common-dir
  # identity. Every observer (including the advisory coherence pass) must use
  # the actual worktree for that repo rather than its sibling primary checkout.
  var currentRepoPath = ""
  var currentRepoName = ""
  var currentRepoMatch: RepoWorktreeMatch
  if parsed.currentRepo.len > 0:
    currentRepoMatch = resolveRepoWorktreeMatch(
      identity, parsed.workspaceRoot, resolved.repos, parsed.currentRepo)
    if currentRepoMatch.found:
      let repo = resolved.repos[currentRepoMatch.repoIndex]
      currentRepoPath = repo.path
      currentRepoName = repo.name
    elif currentRepoMatch.ambiguous:
      result.failures.add(CheckFailure(
        repo: "",
        property: "current-repo-identity",
        remediation: "remove the ambiguous workspace repo declaration or " &
          "repair its Git remote, then retry the push",
        evidence: currentRepoMatch.diagnostic))
      result.exitCode = 2
      return

  let layerLocations = enumerateManifestLayerLocations(
    parsed.workspaceRoot, workspaceLocal)
  let currentManifestLayer = findCurrentManifestLayer(
    layerLocations, parsed.currentRepo)
  let membershipRoot = manifestsRoot(parsed.workspaceRoot)
  let currentIsMembershipRepo = parsed.currentRepo.len > 0 and
    sameFilesystemPath(absolutePath(membershipRoot), parsed.currentRepo) and
    discoverGitWorktree(identity, membershipRoot).ok
  if parsed.currentRepo.len > 0 and not currentRepoMatch.found and
      currentManifestLayer.isNone and not currentIsMembershipRepo:
    # An explicit managed-hook root is an authority boundary, not a hint. If
    # it cannot be identified as a declared repo, manifest layer, or the
    # membership repo, do not widen to the ambient workspace. That fallback
    # audits an unrelated project and can turn an invalid green hook into the
    # push authorization result.
    result.failures.add(CheckFailure(
      repo: "",
      property: "current-repo-identity",
      remediation: "run 'repro hooks ensure --vcs " & parsed.currentRepo &
        "' from a checkout declared by this workspace, or repair the " &
        "workspace membership before retrying the push",
      evidence: currentRepoMatch.diagnostic))
    result.exitCode = 2
    return

  result.activeBranch = deriveCheckActiveBranch(
    parsed, workspaceLocal, resolved)
  var currentRepoBranch = ""
  if currentRepoName.len > 0:
    let branch = gitRunPlain(identity,
      ["-C", parsed.currentRepo, "symbolic-ref", "--short", "-q", "HEAD"])
    if branch.code == 0:
      currentRepoBranch = branch.output.strip()
      if result.activeBranch.len == 0:
        result.activeBranch = currentRepoBranch
  let toolDigest = digestHex(identity)
  let observedAt = getTime().toUnix * 1000

  # Protocol v2 distinguishes the one ordinary outgoing commit Git is asking
  # this hook to approve from unrelated unpublished dependency state.  The
  # stream itself has already been parsed strictly by ``runCheckCommand``;
  # evaluate it again here with the resolved manifest-agreed remote so only an
  # exact, single, fast-forward HEAD update can receive the provisional
  # ``outgoing-current`` classification.
  var agreedRemoteName = ""
  var agreedRemoteLocation = ""
  if currentRepoName.len > 0:
    for repo in resolved.repos:
      if repo.name == currentRepoName:
        agreedRemoteName = gitRemoteNameFor(repo)
        # ``fetchUrl`` is already the resolver's full base+relative repository
        # URL. Do not reconstruct repository identity from local branch state.
        agreedRemoteLocation = repo.fetchUrl
        break
  elif currentManifestLayer.isSome:
    # Only a URL-backed layer has a manifest-declared repository identity.
    # A local_path layer may retain normal same-name behavior, but cannot
    # authorize a different local remote alias.
    agreedRemoteLocation = currentManifestLayer.get().sourceUrl
    let upstream = gitRunPlain(identity,
      ["-C", parsed.currentRepo, "rev-parse", "--abbrev-ref",
       "--symbolic-full-name", "@{u}"])
    if upstream.code == 0:
      let slash = upstream.output.strip().find('/')
      if slash > 0:
        agreedRemoteName = upstream.output.strip()[0 ..< slash]
  let outgoing =
    if parsed.pushedRefsPath.len > 0:
      evaluateOutgoingCurrent(identity.binaryPath,
        parsed.currentRepo, parsed.pushedRefsPath, parsed.hookRemoteName,
        parsed.hookRemoteLocation, agreedRemoteName, agreedRemoteLocation)
    else:
      OutgoingCurrentDecision(protocolOk: true)
  if not outgoing.protocolOk:
    result.failures.add(CheckFailure(
      repo: currentRepoPath,
      property: "pre-push-protocol",
      remediation: "reinstall the managed hooks with 'repro hooks ensure --vcs " &
        parsed.currentRepo & "' and retry the push",
      evidence: outgoing.diagnostic))
    result.exitCode = 2
    return

  # RA-3: no branch-name enforcement. The pushed and active branch are
  # still observed and surfaced in the report (informational), but a
  # mismatch never gates the push — heterogeneous per-class branch
  # policies are first-class and the lock pins SHAs, so the published
  # state is reproducible regardless of which branch each repo is on.
  result.pushedBranch = parsePushedBranchFromRefs(parsed.pushedRefsPath)
  if currentRepoBranch.len > 0 and
      (result.pushedBranch.len == 0 or result.pushedBranch == "HEAD"):
    result.pushedBranch = currentRepoBranch
  discard currentRepoPath

  # RA-21: scope the gate to the pushed repo's transitive develop-set
  # dependency closure, NOT the whole workspace. A develop-mode sibling is
  # a git-submodule replacement: only the pushed repo's own dependency
  # closure can break a teammate's build of it, so an unrelated dirty repo
  # elsewhere in the workspace MUST NOT block the push. The closure is a
  # set of repo NAMES (pushed repo + everything reachable via the per-repo
  # ``depends`` edges). Recognized manifest-layer and membership pushes have
  # their dedicated scopes below. An explicit root with no recognized identity
  # has already failed closed above, so whole-workspace fallback cannot turn an
  # unrelated checkout into an authorized push.
  #
  # ...except for the MEMBERSHIP repo, which is never a declared repo and would
  # therefore always take that fallback. Its scope is the repos whose manifest
  # fragments the pushed range modifies (Workspace-And-Develop-Mode.md §"Gate
  # scope when the pushed repo is the membership repo").
  var membershipScope = none(HashSet[string])
  if currentRepoName.len == 0 and currentIsMembershipRepo:
    let newTip =
      if outgoing.headOid.len > 0: outgoing.headOid
      else: gitRunPlain(identity,
        ["-C", membershipRoot, "rev-parse", "HEAD"]).output.strip()
    let oldTip =
      if outgoing.remoteOldOid.len > 0 and not isZeroOid(outgoing.remoteOldOid):
        outgoing.remoteOldOid
      else: ""
    membershipScope = some(membershipPushScope(
      identity, resolved, membershipRoot, newTip, oldTip))
  let scope = prePushScope(resolved, currentRepoName, currentManifestLayer,
    membershipScope)
  let scopeClosure = scope.names
  let scopeIsWholeWorkspace = scope.wholeWorkspace
  proc repoInScope(name: string): bool =
    scopeIsWholeWorkspace or name in scopeClosure

  # Lock coherence is advisory, but it still performs repository and lock
  # observations. Apply the same pushed-repo dependency closure as the gate so
  # an explicit managed-hook root cannot cause unrelated active projects to be
  # inspected merely because they share an ambient workspace. Membership and
  # manifest-layer pushes retain their purpose-built scopes above.
  try:
    var pairs: seq[tuple[name, path: string]]
    for repo in resolved.repos:
      if not repoInScope(repo.name):
        continue
      pairs.add((repo.name,
        if repo.name == currentRepoName and parsed.currentRepo.len > 0:
          parsed.currentRepo
        else:
          repo.path))
    for line in renderCoherenceTextLines(lockCoherenceFor(identity,
        parsed.workspaceRoot, resolved.projectName, pairs)):
      result.notices.add(line)
  except CatchableError:
    # An advisory diff must never be able to fail a gate run.
    discard

  # Walk the participating repos for the cleanliness + publication
  # passes. We gather the M4 evidence triple for every repo so the
  # second / third stages can short-circuit cleanly while preserving
  # the full observed state for the lock stage. Repos OUTSIDE the pushed
  # repo's dependency closure are skipped entirely (RA-21).
  type
    RepoObs = object
      name: string
      path: string
      absPath: string
      headSha: string
      isClean: bool
      isPublished: bool
      cleanDiagnostic: string
      pubDiagnostic: string
      branch: string
      remoteName: string
      hasGit: bool
  var observations: seq[RepoObs]
  # MO-5 — PRIVATE repos whose source is NOT present locally (unreadable /
  # never cloned). A public missing repo keeps the prior vacuous-skip
  # behavior (no regression); only a private one is routed to the MO-5 stage
  # below, where an evidence-only repo is verified from published evidence and
  # a shared-private repo is an actionable clone-required error.
  var unreadablePrivate: seq[ResolvedRepo]
  for repo in resolved.repos:
    if not repoInScope(repo.name):
      continue
    let absRepo =
      if repo.name == currentRepoName and parsed.currentRepo.len > 0:
        parsed.currentRepo
      else:
        parsed.workspaceRoot / repo.path
    var obs = RepoObs(name: repo.name, path: repo.path, absPath: absRepo)
    if not discoverGitWorktree(identity, absRepo).ok:
      if repo.visibility != wvPublic:
        unreadablePrivate.add(repo)
      observations.add(obs)
      continue
    obs.hasGit = true
    let headRes = queryGitState(headShaQuery(absRepo), identity)
    if headRes.status == gqsOk:
      obs.headSha = headRes.headSha
    let cleanRes = queryGitState(isCleanQuery(absRepo), identity)
    if cleanRes.status == gqsOk:
      obs.isClean = cleanRes.isClean
    else:
      obs.cleanDiagnostic = cleanRes.diagnostic
    let rName = gitRemoteNameFor(repo)
    obs.remoteName = rName
    let pubRes = queryGitState(
      isPublishedQuery(absRepo, rName), identity)
    if pubRes.status == gqsOk:
      obs.isPublished = pubRes.isPublished
    else:
      obs.pubDiagnostic = pubRes.diagnostic
    let branchRes = gitRunPlain(identity,
      ["-C", absRepo, "symbolic-ref", "--short", "-q", "HEAD"])
    if branchRes.code == 0:
      obs.branch = branchRes.output.strip()
    observations.add(obs)
  if currentRepoName.len > 0:
    for obs in observations:
      if obs.name == currentRepoName and obs.headSha.len > 0:
        result.expectedManifestRecords.add(ExpectedLockRecord(
          project: resolved.projectName, repoName: obs.name,
          repoPath: obs.path, oid: obs.headSha,
          relPath: lockFileRepoRelativePath(
            resolved.projectName, obs.name, obs.headSha)))
        break
  # M4 evidence records are intentionally not folded into the gate
  # report yet — the gate carries its own short-circuiting structure
  # and the unified evidence is already exposed by ``repro workspace
  # status`` for general inspection. ``toolDigest`` and ``observedAt``
  # are retained in scope so a future caller wishing to fold the
  # observation triple into ``WorkspaceVcsEvidence`` can do so without
  # re-querying the M1 identity binding.
  discard toolDigest
  discard observedAt

  # ---- MO-5: evidence-only / shared-private unreadable repos -------------
  # A private repo whose source is not present locally is NOT silently skipped
  # (that would be unsound) and is NOT blanket-refused. Two cases, two clearly
  # distinct diagnostics (Workspace-And-Develop-Mode.md §"Evidence-only
  # participation"):
  #
  #   * SHARED-private (no ``participation = "evidence-only"`` marker): the repo
  #     IS expected to be cloned; a missing checkout is an actionable
  #     ``clone-required`` error (exit 2). This is the "shared private (clone
  #     required)" tier.
  #   * EVIDENCE-ONLY private (marker set): the gate CONSUMES the repo's
  #     PUBLISHED source-free ``WorkspaceVcsEvidence`` (MO-3 ``getEvidence`` via
  #     the repo's MO-4-assigned backend) in lieu of a clone. The verdict is
  #     computed from the REAL evidence + the locked SHA: only a repo that was
  #     clean, published, AND at the locked SHA satisfies the boundary — a
  #     dirty / unpublished / sha-mismatched / evidence-missing repo still FAILS
  #     (exit 2). This is the "evidence-only private (evidence sufficient)" tier.
  #
  # The stage is a strict no-op when no private repo is unreadable, so every
  # all-public / fully-cloned workspace (the existing gate tests) is unchanged.
  if unreadablePrivate.len > 0:
    let routing = loadLockingRouting(parsed.workspaceRoot)
    var assignments: seq[RepoBackendAssignment]
    var routingFailed = false
    try:
      assignments = resolveRepoBackends(
        routing, resolved.repos, parsed.workspaceRoot, identity,
        identity.binaryPath)
    except StoreRoutingError as err:
      routingFailed = true
      result.failures.add(CheckFailure(
        repo: "",
        property: "evidence-only-no-backend",
        remediation: "declare a `[[locking.route]]` backend for the private " &
          "repo so its participation evidence has a store to read",
        evidence: err.msg))
      result.exitCode = 2
    if routingFailed:
      return
    var byName = initTable[string, RepoBackendAssignment]()
    for asg in assignments:
      byName[asg.repoName] = asg
    for repo in unreadablePrivate:
      let asg = byName.getOrDefault(repo.name)
      let outcome = gateDecideUnreadableRepo(
        repo, asg.store, resolved.projectName)
      # HL-6 (§7.3): Decision 2's loud-vs-warn applies to the evidence READ of an
      # unreachable backend. ``decideEvidenceReadTierPolicy`` is the single shared
      # decision (the integration test drives the SAME proc): a PERSONAL-tier
      # unreachable evidence read WARNS but ALLOWS; a team/public (shared) tier —
      # or an evidence-proven violation — REFUSES.
      case decideEvidenceReadTierPolicy(outcome, asg.visibility)
      of ergdSatisfied:
        result.notices.add(outcome.notice)
      of ergdWarnAllow:
        result.notices.add(
          evidenceReadUnreachableWarning(repo.path, asg.backendKind,
            parsed.workspaceRoot))
      of ergdRefuse:
        result.failures.add(outcome.failure)
        result.exitCode = 2
        return

  # ---- TC-3 / RA-32: certificate-coverage gate (opt-in per project) ------
  # This nested stage runs ONLY after every other stage has passed (the gate
  # short-circuits on the first failure, so by the time we reach it the
  # closure is clean + published + at the locked revisions and the lock is
  # current). It is invoked from EACH exit point of stage 5 (and the final
  # fall-through) via ``applyCertificateGate`` so it sees a resolved lock.
  #
  # DEFAULT-OFF guarantee (RA-32): when the project's resolved
  # ``gateMode`` is ``cgmOff`` — which is exactly what a project with NO
  # ``[certificates]`` table resolves to — this stage is a NO-OP: it touches
  # neither ``failures`` nor ``exitCode`` nor ``notices``, so every existing
  # pre-push gate test (none of which set a policy) behaves identically.
  #
  #   - ``cgmAdvisory`` RECORDS the coverage verdict in ``result.notices``
  #     (a warning naming the missing platform/targets, or a confirmation)
  #     but NEVER changes the exit code — advisory never blocks a push.
  #   - ``cgmRequired`` REFUSES the push (exit 2 + a ``certificate-coverage``
  #     CheckFailure naming what's missing and the ``repro certify`` remedy)
  #     unless the submitted certificates (read via the TC-2 git-notes
  #     reader for the pushed commit) COVER (via the TC-1 ``verifyCoverage``
  #     verifier) the pushed commit, against the clean lock, for the required
  #     targets, on EACH required platform. Coverage UNIONS multiple certs:
  #     required {linux, macos} × {t-unit} is satisfied by a linux cert + a
  #     macos cert together (each platform checked independently).
  #
  # The actual logic lives in the top-level ``certificateGate`` proc (defined
  # with the certificate block above) because Nim forbids a nested closure
  # from capturing ``result`` (a stack ``CheckReport``). We pre-compute the
  # two pieces of context that depend on the local ``observations`` /
  # ``identity`` here and pass them in; ``applyCertificateGate`` is a thin
  # local wrapper so the stage-5 exit points read cleanly.
  let certRepoPath =
    if parsed.currentRepo.len > 0: parsed.currentRepo
    else: parsed.workspaceRoot
  var certPushedCommit = ""
  var deferredParticipation: seq[DeferredParticipationWrite]
  if not parsed.skipCertificateGate and
      resolved.certificatePolicy.gateMode != cgmOff:
    # The pushed commit is the current repo's HEAD. Prefer the already-
    # observed SHA; fall back to a fresh probe if the current repo was not
    # one of the in-scope observations (e.g. an empty-closure fallback).
    for obs in observations:
      if obs.name == currentRepoName and obs.headSha.len > 0:
        certPushedCommit = obs.headSha
        break
    if certPushedCommit.len == 0:
      let headRes = queryGitState(headShaQuery(certRepoPath), identity)
      if headRes.status == gqsOk:
        certPushedCommit = headRes.headSha
  template applyCertificateGate() =
    if not parsed.skipCertificateGate:
      certificateGate(result, resolved.certificatePolicy, certPushedCommit,
        certRepoPath, identity.binaryPath, currentRepoName,
        registeredKeyStorePath(parsed.workspaceRoot))
  template finalizePoliciesAndParticipation() =
    ## Durable stores are the final gate side effect. Certificates and every
    ## read-only policy run first; only a passing report may execute putLock.
    applyCertificateGate()
    if result.exitCode == 0:
      result.deferredPublishWrites = deferredParticipation
      result.participation = executeParticipationWrites(deferredParticipation)
      applyParticipationTierPolicy(result)

  # ---- 1. dirty ----------------------------------------------------------
  for obs in observations:
    if not obs.hasGit:
      continue
    if not obs.isClean:
      let evidence =
        if obs.cleanDiagnostic.len > 0:
          "clean-probe-failed: " & obs.cleanDiagnostic
        else: "working tree has uncommitted changes"
      result.failures.add(CheckFailure(
        repo: obs.path,
        property: "dirty",
        # Principle 2: name the offender AND a copy-pasteable command.
        remediation: "commit or stash changes in " & obs.path &
          " — run 'git -C " & obs.path & " commit -a' (or 'git -C " &
          obs.path & " stash') then 'repro push'",
        evidence: evidence))
      result.exitCode = 2
      return

  # ---- 2. unpublished ----------------------------------------------------
  for obs in observations:
    if not obs.hasGit:
      continue
    if not obs.isPublished and not
        (outgoing.outgoingCurrent and obs.name == currentRepoName and
         obs.headSha == outgoing.headOid):
      # RA-32 — when the repo being refused IS the one whose push we are
      # gating, and the object we are gating IS its HEAD, "unpublished" is a
      # true statement with a false remedy: the push it tells you to run is the
      # push it just refused. That shape appears whenever the self-exemption
      # above declines for a reason of its own -- a non-fast-forward update
      # (`--force-with-lease`) being the common one, since `evaluateOutgoing`
      # computes exactly that diagnostic and then discards it, leaving
      # `protocolOk` true so nothing else surfaces it either.
      #
      # This changes no policy: the refusal still stands. It stops the
      # operator being handed an impossible instruction and names the actual
      # reason instead.
      #
      # The non-fast-forward case the paragraph above cites is no longer one
      # of the reasons that reach here — a rewrite now RECEIVES the
      # provisional classification (it does publish this HEAD) and is judged
      # by stage 2b instead, which never claims the repo is unpublished. The
      # remaining reasons are the eligibility ones: a batch, a tag/note-only
      # update, a deletion, a different SHA, a detached or non-branch local
      # ref, and the wrong remote. For those, "unpublished" IS the accurate
      # verdict and this remedy is the accurate wording of it.
      let selfPush =
        obs.name == currentRepoName and obs.headSha.len > 0 and
        obs.headSha == outgoing.headOid and not outgoing.outgoingCurrent
      let evidence =
        if selfPush and outgoing.diagnostic.len > 0:
          "this push is the publication being gated (HEAD " & obs.headSha &
          "), and it was not accepted as outgoing-current: " &
          outgoing.diagnostic
        elif obs.pubDiagnostic.len > 0:
          "publish-probe-failed: " & obs.pubDiagnostic
        else: "HEAD " & obs.headSha &
          " not on a '" & obs.remoteName & "/*' remote-tracking branch"
      let remediation =
        if selfPush and outgoing.diagnostic.len > 0:
          "resolve '" & outgoing.diagnostic & "' in " & obs.path &
          " — re-running 'git push' will not help, this refusal IS that push"
        else:
          "run 'git push' in " & obs.path & " first"
      result.failures.add(CheckFailure(
        repo: obs.path,
        property: "unpublished",
        remediation: remediation,
        evidence: evidence))
      result.exitCode = 2
      return

  # ---- 2b. outgoing history rewrite --------------------------------------
  # A push that names one ref, whose local object is the independently
  # observed HEAD, and whose destination is the manifest-agreed remote branch
  # PUBLISHES that HEAD — fast-forward or not. ``evaluateOutgoingCurrent``
  # used to refuse a non-fast-forward there, which fused two different
  # questions and answered the wrong one: rebasing a feature branch onto a
  # moved mainline and force-pushing it was reported as `unpublished` with the
  # remedy "run 'git push'" — the very push being refused. The only way
  # through was ``--no-verify``, which disables the entire gate, so a rule
  # meant to protect the workspace taught the bypass on a legitimate case.
  #
  # The concern the fast-forward rule really carried is separate and is
  # decided HERE: workspace locks pin commit SHAs, and a rewrite that makes a
  # pinned commit unreachable silently breaks reproduction of the snapshot
  # that pins it. That is a claim about WHAT the overwritten commits are, not
  # about fast-forwardness, so it is asked only of the commits actually being
  # discarded, and only when something still depends on them.
  #
  # Refusals here never say the repository is unpublished — it is being
  # published by this very push — and each names what would be lost.
  if outgoing.outgoingCurrent and
      outgoing.updateShape in {ouRewrite, ouRewriteOpaque}:
    let pushedBranch =
      if outgoing.remoteRef.startsWith("refs/heads/"):
        outgoing.remoteRef["refs/heads/".len .. ^1]
      else: outgoing.remoteRef
    let repoLabel =
      if currentRepoPath.len > 0: currentRepoPath else: parsed.currentRepo
    let remoteLabel =
      if outgoing.remoteName.len > 0: outgoing.remoteName else: "the remote"
    if outgoing.updateShape == ouRewriteOpaque:
      # The old tip is not a commit in this checkout, so what the update
      # discards cannot be enumerated. "Nothing is discarded" and "what is
      # discarded cannot be seen" are different answers and only the first is
      # safe to act on, so refuse — but say which one this is.
      result.failures.add(CheckFailure(
        repo: repoLabel,
        property: "history-rewrite-unverifiable",
        remediation: "run 'git -C " & parsed.currentRepo & " fetch " &
          remoteLabel & " " & pushedBranch & "' so the commits this update " &
          "would replace are present locally, then retry the push — HEAD " &
          outgoing.headOid & " is publishable; this is refused only because " &
          "the gate cannot see what the update would discard",
        evidence: "'" & remoteLabel & "/" & pushedBranch & "' is at " &
          outgoing.remoteOldOid & ", which is not a commit object in this " &
          "checkout, so the commits this non-fast-forward update would make " &
          "unreachable cannot be enumerated"))
      result.exitCode = 2
      return
    let orphanedCommits = commitsMadeUnreachable(identity.binaryPath,
      parsed.currentRepo, outgoing.remoteOldOid, outgoing.headOid)
    var orphans = initHashSet[string]()
    orphans.incl(outgoing.remoteOldOid.toLowerAscii())
    for oid in orphanedCommits:
      orphans.incl(oid)
    # A declared MAINLINE is refused regardless of what is pinned. The
    # asymmetry is the justification: feature branches are rebased constantly
    # and a rewrite there costs nothing, whereas mainline is what every other
    # checkout tracks, so rewriting it invalidates teammates' working state —
    # which no lock records and the check below therefore cannot see. The rule
    # fires only on a branch the MANIFEST declares, never on an inferred one,
    # so its false-refusal rate is the rate at which mainline is deliberately
    # rewritten: near zero, which is what keeps a blanket rule from becoming
    # a bypass lesson.
    let mainline = declaredMainlineBranch(resolved, currentRepoName)
    if mainline.len > 0 and pushedBranch == mainline:
      result.failures.add(CheckFailure(
        repo: repoLabel,
        property: "mainline-history-rewrite",
        remediation: "do not rewrite the shared mainline '" & pushedBranch &
          "' — put this work on top of " & outgoing.remoteOldOid &
          " (rebase onto it, or revert), or push this history to a " &
          "different branch. HEAD " & outgoing.headOid & " is publishable; " &
          "only discarding '" & pushedBranch & "' history is refused",
        evidence: "'" & pushedBranch & "' is the mainline branch the " &
          "manifest declares for " & currentRepoName &
          ", and this update is not a fast-forward: it would make " &
          $orphans.len & " commit(s) unreachable there, including " &
          outgoing.remoteOldOid))
      result.exitCode = 2
      return
    let pinned = findLockPinningOrphan(identity,
      workspaceLockRoots(parsed.workspaceRoot, layerLocations), orphans)
    if pinned.orphanOid.len > 0:
      result.failures.add(CheckFailure(
        repo: repoLabel,
        property: "orphans-locked-commit",
        remediation: "push this history to a different branch, or keep " &
          pinned.orphanOid & " reachable from '" & pushedBranch &
          "' — discarding it makes that lock record unresolvable, and " &
          "re-pinning it is a coordinated change to shared lock history " &
          "that this push must not make implicitly. HEAD " & outgoing.headOid &
          " is publishable; only discarding " & pinned.orphanOid &
          " is refused",
        evidence: "lock record " & pinned.lockRelPath & " (keyed at " &
          pinned.lockTriggerSha & ", which this push does NOT discard) pins " &
          pinned.lockedPath & " at " & pinned.orphanOid &
          ", and this non-fast-forward update to '" & pushedBranch &
          "' would make that commit unreachable",
        source: pinned.lockRoot / pinned.lockRelPath.replace('/', DirSep)))
      result.exitCode = 2
      return

  # ---- 3. develop-mode override cleanliness (M23) ------------------------
  # The blocking condition reproduces
  # ``Workspace-And-Develop-Mode.md`` §"Reproducibility And `repro check`":
  # a develop-mode dependency with uncommitted modifications, or one
  # that points at commits not pushed to an agreed remote, must not
  # silently be folded into a published workspace lock. The stage is a
  # no-op when ``.repro/develop-overrides.toml`` is absent (the common
  # state for workspaces that have never run ``repro develop``).
  let overridesOpt =
    try:
      readDevelopOverridesFile(parsed.workspaceRoot)
    except WorkspaceManifestParseError as err:
      # Surface the parse failure as a gate refusal rather than letting
      # the outer ``try`` translate it into a generic exit-1. A
      # malformed override file is the operator's problem and refusing
      # the push is the only safe answer.
      result.failures.add(CheckFailure(
        repo: "",
        property: "develop_override_missing",
        remediation:
          "fix '.repro/develop-overrides.toml' parse error before pushing",
        evidence: err.msg,
        source: developOverridesPath(parsed.workspaceRoot)))
      result.exitCode = 2
      return
  if overridesOpt.isSome:
    for entry in listOverrides(overridesOpt.get()):
      let sourcePath =
        if isAbsolute(entry.local_path): entry.local_path
        else: absolutePath(parsed.workspaceRoot / entry.local_path)
      if not dirExists(sourcePath):
        result.failures.add(CheckFailure(
          repo: entry.package,
          property: "develop_override_missing",
          remediation: "the develop-override at " & sourcePath &
            " no longer exists; run 'repro develop " & entry.package &
            " --source=PATH' to update it",
          evidence: "override source path does not exist",
          source: sourcePath))
        result.exitCode = 2
        return
      # Skip non-git overrides — the M20 schema accepts overrides that
      # point at any directory (the CLI even has a "register-only" arm
      # that does not require a VCS root). Treat the absence of ``.git``
      # the same way the M18 sibling-repo stages do: cleanliness and
      # publication are vacuously satisfied because there is no VCS
      # state to compare against. A future milestone can tighten this
      # if non-git overrides become disallowed.
      if not discoverGitWorktree(identity, sourcePath).ok:
        continue
      let cleanRes = queryGitState(isCleanQuery(sourcePath), identity)
      if cleanRes.status != gqsOk:
        result.failures.add(CheckFailure(
          repo: entry.package,
          property: "develop_override_dirty",
          remediation: "commit or stash changes in " & sourcePath,
          evidence: "clean-probe-failed: " & cleanRes.diagnostic,
          source: sourcePath))
        result.exitCode = 2
        return
      if not cleanRes.isClean:
        result.failures.add(CheckFailure(
          repo: entry.package,
          property: "develop_override_dirty",
          remediation: "commit or stash changes in " & sourcePath,
          evidence: "working tree has uncommitted changes",
          source: sourcePath))
        result.exitCode = 2
        return
      # Accept ANY remote-tracking branch. A develop-override is an arbitrary
      # local path, not a manifest repo, so there is no `ResolvedRepo` to feed
      # `gitRemoteNameFor` and no configured expectation of which remote it
      # should be published to. Hardcoding "origin" here (the other three
      # isPublishedQuery call sites all resolve the real name) made this check
      # fail for every worktree whose remote is named after its org rather than
      # "origin" -- which is how the `repo` tool names them -- reporting
      # commits that were sitting on the remote's default branch as
      # unpublished and refusing the push.
      let pubRes = queryGitState(
        isPublishedQuery(sourcePath, ""), identity)
      if pubRes.status != gqsOk:
        result.failures.add(CheckFailure(
          repo: entry.package,
          property: "develop_override_unpublished",
          remediation: "run 'git push' in " & sourcePath & " first",
          evidence: "publish-probe-failed: " & pubRes.diagnostic,
          source: sourcePath))
        result.exitCode = 2
        return
      if not pubRes.isPublished:
        let headRes = queryGitState(headShaQuery(sourcePath), identity)
        let headSha =
          if headRes.status == gqsOk: headRes.headSha
          else: ""
        # An override may point at the very checkout Git is asking this hook
        # to approve — `repro develop <pkg> --source=<sibling>` on a repo you
        # then push is the ordinary way to work. Refusing THAT on the grounds
        # that its HEAD is unpublished is circular: this push is what would
        # publish it, so the first push of a new commit/branch could never be
        # made. Stage 2 already grants the same provisional status to the
        # outgoing repo; the ``outgoing-current`` classification is exactly
        # the proof that one well-formed fast-forward update of this HEAD is
        # in flight to the manifest-agreed remote. Every other override —
        # a genuine dependency this push does not publish — still refuses.
        if outgoing.outgoingCurrent and headSha.len > 0 and
            headSha == outgoing.headOid and
            sameFilesystemPath(sourcePath, parsed.currentRepo):
          continue
        let evidence =
          if headSha.len > 0:
            "HEAD " & headSha & " not on any remote-tracking branch"
          else: "HEAD not on any remote-tracking branch"
        result.failures.add(CheckFailure(
          repo: entry.package,
          property: "develop_override_unpublished",
          remediation: "run 'git push' in " & sourcePath & " first",
          evidence: evidence,
          source: sourcePath))
        result.exitCode = 2
        return

  # ---- 4. lock currency --------------------------------------------------
  # Pick the manifest-layer root the way M11 / M12 do, then read the
  # latest locked SHA per repo path. If the locked map covers every
  # IN-SCOPE repo and matches every observed HEAD, the lock is
  # ``already-current``. Otherwise the gate creates or refreshes the
  # lock by delegating to the M11 driver — its refusal arm (a dirty
  # in-scope sibling, exit 2) is unreachable here because stage 1 already
  # short-circuited on any in-scope dirty tree. Stage 3 (M23 develop-
  # override cleanliness) also has to have passed: a dirty or unpublished
  # override would otherwise be silently encoded into the lock.
  #
  # RA-21: the lock refresh is scoped to the pushed repo's dependency
  # closure — an out-of-closure dirty repo must NOT make the refresh
  # refuse (the lock still records every repo it can observe).
  var lockArgs = WorkspaceLockArgs(
    workspaceRoot: parsed.workspaceRoot,
    toolProvisioning: parsed.toolProvisioning,
    dirtyScopeNames: scopeClosure,
    # The gate DECIDED this scope (``prePushScope``), so it stands even when it
    # is empty — which it legitimately is for a membership commit that touches
    # no manifest fragment. Only the genuine "no scope information" verdict
    # (``wholeWorkspace``) keeps the whole-workspace refusal.
    dirtyScopeIsExplicit: not scopeIsWholeWorkspace)
  lockArgs.triggerRepo = currentRepoName
  lockArgs.triggerRepoPath =
    if currentRepoName.len > 0: parsed.currentRepo
    else: ""
  # The membership repo is not a declared repo, so it supplies neither a
  # trigger NAME nor a trigger PATH — and with both empty the lock driver used
  # to fall through to the project-named anchor and file this push's workspace
  # state under an unrelated repo's commit. It belongs to no partition
  # (Unified-Locking-And-Hooks.md §6 Decision 1, consequence 2), so say so
  # instead of letting the absence of a trigger be read as "no trigger in
  # particular".
  lockArgs.triggerOutsideEveryPartition =
    currentRepoName.len == 0 and currentIsMembershipRepo
  let manifestLayerRoot = pickManifestLayerRoot(lockArgs, workspaceLocal)
  # MO-2 — manifest-optional gate. When the workspace has NO resolved manifest
  # checkout on disk (a committed-lock-only / manifest-less workspace), there
  # is no manifest-repo SHA-lock to write or publish: the
  # committed ``repro.lock`` is the reproducibility artifact (validated
  # separately by the MO-1 ``validateCommittedLockAdvisory``). The
  # cleanliness / publication STAGES above already ran on the committed-lock-
  # derived participating set, so the gate verdict is sound; here we simply
  # skip the manifest-SHA-lock write/publish and leave ``manifestLayerRoot``
  # empty so the caller's publish step is a no-op. Manifest-present
  # workspaces always have a real ``.repo/manifests`` (or a composed layer)
  # on disk, so this never changes their behavior.
  if workspaceLocal.isNone and not hasResolvedManifestCheckout(parsed.workspaceRoot):
    # MO-9 — the committed-lock gate consumes the unified ``LockedDependencies``
    # (populated from the committed-lock source) and verifies observed content
    # against the locked INTEGRITY: it recomputes each dependency's multihash at
    # its locked COORDINATES and refuses (exit 2) on a mismatch — a tampered
    # integrity, or a locked revision whose object is missing/unreachable. This
    # is the same verification the gate would apply to a store-sourced locked
    # entry, so the gate's integrity check is SOURCE-AGNOSTIC. On a clean,
    # untampered lock every recomputed integrity equals the recorded one
    # (the locked revision's object is present), so the manifest-less gate
    # passes exactly as before.
    let committedLd = populateLockedDeps(
      LockSource(kind: lskCommittedLock, workspaceRoot: parsed.workspaceRoot))
    let integrityFailures = verifyLockedIntegrityAtCoordinates(
      parsed.workspaceRoot, committedLd)
    if integrityFailures.len > 0:
      let f = integrityFailures[0]
      result.failures.add(CheckFailure(
        repo: f.path,
        property: "locked-integrity-mismatch",
        remediation: lockedIntegrityRemedy(f,
          qualifier = "(tier=public backend=committed-lock)",
          restoreWhere = "the committed `repro.lock`",
          repinCommand = committedLockCommand(parsed.workspaceRoot)),
        evidence: "cause=" & lockedIntegrityCauseToken(f.cause) & " " &
          f.diagnostic))
      result.exitCode = 2
      return
    result.lockUpdate.kind = cluNone
    result.exitCode = 0
    # HL-3 (deliverable 3) — a manifest-LESS workspace may still route repos to
    # durable personal/team backends (a public + personal shape with no team
    # manifest). Record each routed repo's participation through its ASSIGNED
    # backend HERE — the manifest-present path does this via
    # ``executeWorkspaceLock``, but that path is skipped when there is no
    # ``.repo/manifests`` checkout. Without this, a personal git-checkout-on-a-
    # remote backend would never see its lock written/pushed in a manifest-less
    # workspace (the HL-2 disclosed deferral). ``recordRoutedParticipation``
    # returns ``@[]`` when no explicit route is declared (the pure committed-lock
    # shape), so this is a byte-identical no-op there.
    block manifestLessRoutedParticipation:
      let composed = composeLockingRouting(
        parsed.workspaceRoot, identity.binaryPath)
      if not composed.hasExplicitRoutes: break manifestLessRoutedParticipation
      var inScopeRepos: seq[ResolvedRepo] = @[]
      for repo in resolved.repos:
        if repoInScope(repo.name): inScopeRepos.add(repo)
      var repoShas = initTable[string, string]()
      for obs in observations:
        if obs.hasGit: repoShas[obs.path] = obs.headSha
      try:
        deferredParticipation = prepareRoutedParticipation(
          parsed.workspaceRoot, inScopeRepos, repoShas,
          resolved.projectName, identity)
      except StoreRoutingError as err:
        # An unrouted private repo — surface it as a loud lock failure (never a
        # silent pass), mirroring the manifest-present path's propagation.
        result.failures.add(CheckFailure(
          repo: "",
          property: "lock-failure",
          remediation:
          "add a `[[locking.route]]` entry for the unrouted private repo " &
          "named below, then re-run `repro check`",
          evidence: err.msg))
        result.exitCode = 2
        return
    finalizePoliciesAndParticipation()
    return
  # RA-7: surface the manifest-layer root so the caller can publish
  # (commit + push) the lock after the gate passes.
  result.manifestLayerRoot = manifestLayerRoot
  # RA-1: resolve the latest lock via Git history over the per-repo lock
  # subtree (no shared index). MO-3: this gate read is routed through the
  # ``LockStore`` interface — the git-checkout backend delegates to the
  # byte-identical ``latestLockShasViaGit``. ``lockKey.sha`` is "" (no lock
  # record) exactly when the underlying ``lockRelPath`` is "".
  let gateStore: LockStore =
    newGitCheckoutLockStore(identity, manifestLayerRoot)
  # HL-2 (§6 Decision 1 — target read path) — per-backend currency read.
  #
  # When NO explicit route is declared (today's single-tier shape), the read is
  # BYTE-IDENTICAL to the pre-HL-2 single git-checkout store read: the manifest
  # is the lock home for every in-scope repo and ``latestLockShas`` parses the
  # monolithic ``locks/...`` file.
  #
  # When routes ARE declared, each repo's locked SHA is read from ITS ASSIGNED
  # backend (team from the team backend, personal from the personal backend) via
  # the tolerant per-record ``latestLock`` reader — NOT the single monolithic
  # ``latestLockShas`` (which strict-parses one all-repos ``reprobuild.workspace
  # .lock.v1`` file; the routed backends instead hold per-repo participation
  # records). A public (committed-lock) repo has no store SHA — its currency is
  # the committed-lock integrity branch above; it is dropped from the store-SHA
  # comparison here.
  let gateComposed = composeLockingRouting(
    parsed.workspaceRoot, identity.binaryPath)
  var lockedShas = initTable[string, string]()
  var latest: tuple[shas: Table[string, string]; lockKey: StoreLockKey]
  var routedBackendRepos: seq[RepoObs] = @[]
  # Paths whose currency is NOT a store-SHA comparison (public / committed-lock
  # repos, verified by the committed-lock integrity branch). The staleness loop
  # skips these so a public repo is never spuriously marked stale for lacking a
  # store record.
  var committedLockPaths = initHashSet[string]()
  if not gateComposed.hasExplicitRoutes:
    latest = gateStore.latestLockShas(resolved.projectName)
    lockedShas = latest.shas
    # A publication operation is anchored by the exact outgoing current-repo
    # commit. One manifest publication commit can legitimately carry several
    # pending lock records that post-commit hooks created at different moments;
    # Git's name ordering inside that shared commit is not a recency ordering.
    # Prefer the immutable record at the exact outgoing coordinate when it is
    # already present, rather than letting an alphabetically earlier stale
    # sibling record force a rewrite of that exact content-addressed path.
    if outgoing.outgoingCurrent and currentRepoName.len > 0 and
        outgoing.headOid.len > 0:
      # DS-1 — the commit-keyed read is now the shared ``lockRecordAtCommit``
      # entry point (the same one the develop-set composer keys a
      # commit-addressed backend on), not three inlined lines.
      let exact = lockRecordAtCommit(
        gateStore, resolved.projectName, currentRepoName, outgoing.headOid)
      if exact.isSome:
        let exactShas = shasFromBody(exact.get().body)
        if exactShas.len > 0:
          lockedShas = exactShas
          latest = (shas: exactShas, lockKey: exact.get().key)
  else:
    var inScopeRepos: seq[ResolvedRepo] = @[]
    for repo in resolved.repos:
      if repoInScope(repo.name): inScopeRepos.add(repo)
    # HL-7 (§8.4 "private repo declared in no backend-supplying layer") — an
    # in-scope PRIVATE repo the composed configuration plane cannot route
    # (``resolveRepoBackends`` raises ``StoreRoutingError`` naming the repo, its
    # tier, and the remedy) must be a LOUD lock-failure refusal at the gate,
    # NEVER a silent pass. The manifest-LESS routed path already surfaces this as
    # a structured ``lock-failure`` CheckFailure (exit 2); the manifest-PRESENT
    # routed currency read reached this call UNGUARDED, so the routing error
    # propagated as a raw exit-1 with no structured verdict. Catch it here and
    # surface the SAME structured refusal so both routed paths behave
    # identically. A fully-routed workspace never raises, so this is a no-op on
    # the clean/mixed path.
    var gateAssignments: seq[RepoBackendAssignment]
    try:
      gateAssignments = resolveRepoBackends(
        gateComposed, inScopeRepos, parsed.workspaceRoot, identity,
        identity.binaryPath)
    except StoreRoutingError as err:
      result.failures.add(CheckFailure(
        repo: "",
        property: "lock-failure",
        remediation:
          "add a `[[locking.route]]` entry (via the appropriate configuration " &
          "layer / `apply_if`) for the unrouted private repo named below, then " &
          "re-run `repro check`",
        evidence: err.msg))
      result.exitCode = 2
      return
    var byPath = initTable[string, RepoBackendAssignment]()
    for a in gateAssignments: byPath[a.repoPath] = a
    for obs in observations:
      if not obs.hasGit: continue
      if not byPath.hasKey(obs.path): continue
      let asg = byPath[obs.path]
      if asg.store.isNil:
        # Public / committed-lock repo — no store SHA; its currency is the
        # committed-lock integrity check, so exclude it from the store-SHA
        # comparison rather than treating a missing store record as stale.
        committedLockPaths.incl(obs.path)
        continue
      # Routed to a durable backend (team / personal / other) — read this repo's
      # locked SHA from ITS backend via the tolerant per-record reader.
      routedBackendRepos.add(obs)
      let revision = lockedShaFromStore(asg.store,
        resolved.projectName, asg.repoName, obs.path)
      if revision.len > 0:
        lockedShas[obs.path] = revision
    # HL-4 (§8.2 / §8.4 integrity-mismatch row) — PER-TIER INTEGRITY on the
    # manifest-present / MIXED path. The store-SHA currency comparison above only
    # detects a locked SHA that DIFFERS from the observed HEAD (a stale record,
    # which triggers a REFRESH). It does NOT detect a locked entry whose recorded
    # coordinates no longer describe reachable content — a tampered team/personal
    # backend record pinning a revision whose commit object is absent, or a
    # tampered committed lock. Before HL-4 that class of tamper slipped through
    # the manifest-present path entirely: it was verified ONLY on the
    # manifest-LESS committed-lock branch above (:24958-:24987). Here we recompute
    # each in-scope locked entry's multihash AT its coordinates, per tier, via the
    # SAME source-agnostic ``verifyLockedIntegrityAtCoordinates`` machinery
    # (MO-8/MO-9): a public repo is sourced from the committed lock, a routed repo
    # from ITS assigned backend record (``populateLockedDeps`` reading the store's
    # ``path -> revision`` body and re-tagging the git-native integrity). A
    # mismatch REFUSES the push (exit 2) with a diagnostic naming the tier +
    # backend, rather than being silently refreshed. On a CLEAN mixed workspace
    # every recomputed integrity equals the recorded one, so this is a no-op —
    # no false ``locked-integrity-mismatch``.
    var repoByPath = initTable[string, ResolvedRepo]()
    for repo in inScopeRepos: repoByPath[repo.path] = repo
    # (a) PUBLIC / committed-lock repos: verify the committed lock's integrity,
    # scoped to the in-scope public paths (the same check the manifest-less
    # branch runs, applied here so the mixed path also refuses a tampered public
    # lock — §8.4 "tampered committed lock fails at the client (public branch)").
    if committedLockPaths.len > 0:
      let publicLd = populateLockedDeps(
        LockSource(kind: lskCommittedLock, workspaceRoot: parsed.workspaceRoot))
      var scopedPublic = LockedDependencies(
        schema: publicLd.schema, platform: publicLd.platform, deps: @[])
      for d in publicLd.deps:
        if d.path in committedLockPaths: scopedPublic.deps.add(d)
      let publicFailures = verifyLockedIntegrityAtCoordinates(
        parsed.workspaceRoot, scopedPublic)
      if publicFailures.len > 0:
        let f = publicFailures[0]
        result.failures.add(CheckFailure(
          repo: f.path,
          property: "locked-integrity-mismatch",
          remediation: lockedIntegrityRemedy(f,
            qualifier = "(tier=public backend=committed-lock)",
            restoreWhere = "the committed `repro.lock`",
            repinCommand = committedLockCommand(parsed.workspaceRoot)),
          evidence: "tier=public backend=committed-lock cause=" &
            lockedIntegrityCauseToken(f.cause) & " " & f.diagnostic))
        result.exitCode = 2
        return
    # (b) ROUTED repos (team / personal / other): verify EACH against ITS OWN
    # backend record. ``populateLockedDeps`` reads the record's coordinates from
    # the assigned store and re-tags its git-native integrity, so a record
    # pinning an unreachable/absent revision (the tamper) fails at the locked
    # coordinates — exactly the class the SHA-only comparison cannot see.
    for obs in observations:
      if not obs.hasGit: continue
      if not byPath.hasKey(obs.path): continue
      let asg = byPath[obs.path]
      if asg.store.isNil: continue
      if not repoByPath.hasKey(obs.path): continue
      let srcKind =
        if asg.backendKind == "external-cli" or asg.backendKind == "committed-file":
          lskExternalStore
        else: lskManifestRepo
      let routedLd = populateLockedDeps(LockSource(
        kind: srcKind, workspaceRoot: parsed.workspaceRoot,
        projectName: resolved.projectName, repos: @[repoByPath[obs.path]],
        store: asg.store))
      let routedFailures = verifyLockedIntegrityAtCoordinates(
        parsed.workspaceRoot, routedLd)
      if routedFailures.len > 0:
        let f = routedFailures[0]
        let tierLbl = lockingTierLabel(asg.visibility)
        let loc = asg.store.storeLocationLabel()
        result.failures.add(CheckFailure(
          repo: f.path,
          property: "locked-integrity-mismatch",
          # The artifact this refusal is about is the WORKSPACE lock —
          # ``locks/<project>/<repo>/<sha>.toml`` in this tier's backend — so
          # the verb it names is ``repro workspace lock``, NOT the committed
          # lock's ``repro lock refresh``. The gate speaks from inside the
          # pushed repo, so the command carries ``--workspace-root``.
          remediation: lockedIntegrityRemedy(f,
            qualifier = "(tier=" & tierLbl & " backend=" & asg.backendKind &
              (if loc.len > 0: " location=" & loc else: "") & ")",
            restoreWhere = "the " & tierLbl & " backend",
            repinCommand = workspaceLockCommand(parsed.workspaceRoot)),
          evidence: "tier=" & tierLbl & " backend=" & asg.backendKind &
            (if loc.len > 0: " location=" & loc else: "") &
            " cause=" & lockedIntegrityCauseToken(f.cause) &
            " " & f.diagnostic))
        result.exitCode = 2
        return
  # ``lockMissing`` = no lock record exists to compare against. The manifest
  # store contributes ``latest.lockKey.sha``; a routed distinct backend
  # contributes its own record (``routedBackendRepos`` were read above). When
  # neither exists there is nothing to compare — the lock must be created.
  var lockMissing = latest.lockKey.sha.len == 0 and routedBackendRepos.len == 0
  var lockStale = false
  # A global latest lock may already describe identical workspace HEADs, but
  # publication requires an immutable record anchored by the pushed repo's own
  # commit. Do not let another repo's current record suppress creation of this
  # exact trigger record.
  #
  # The obligation is read from ``result.expectedManifestRecords`` — the very
  # list the publisher below verifies — rather than recomputed from
  # ``outgoing``. The two used to be derived from different facts and disagreed
  # about WHEN the record is owed: the verifier appends an expected record
  # whenever ``--current-repo`` resolves to a declared repo with an observable
  # HEAD, while this writer only created one when the push was additionally
  # accepted as ``outgoing-current`` (a strict single fast-forward HEAD update
  # to the manifest-agreed remote, which needs ``--pushed-refs`` and fails for
  # a same-oid or force update). Every gate run outside that narrow shape
  # therefore reported "lock already current", wrote nothing, and then refused
  # the push with
  #
  #   expected lock record is not reachable at <manifests HEAD>:
  #   locks/<project>/<repo>/<sha>.toml
  #
  # — the writer creating no commit and the verifier then looking for one. It
  # was invisible for any repo that had been an explicit ``repro push`` trigger
  # at its current HEAD before (its record already existed, so the missing
  # write went unnoticed), and fatal for its otherwise identical sibling that
  # had not. Both halves now read the same list, so the gate can only demand a
  # record it is also willing to write.
  #
  # Guarded on a manifest layer EXISTING. With no declared route
  # ``manifestLayerRoot`` is empty (§10, "No implicit team route"), there is no
  # git-checkout store to hold a trigger-keyed record and none is verified
  # either; probing ``git -C "" ls-tree`` would merely fail and be misread as
  # "the record is missing".
  if manifestLayerRoot.len > 0:
    for expectedRecord in result.expectedManifestRecords:
      # A record already ON DISK satisfies the obligation even when it is not
      # committed yet: the publisher stages untracked canonical records under
      # ``locks/`` (``ls-files --others``), so a draft this or an earlier
      # operation wrote is exactly what the next publish carries.
      #
      # Testing only ``ls-tree HEAD`` would make every gate run REWRITE that
      # draft for as long as publication has not happened — a store with no
      # upstream, or any run that refuses at a later stage. The bytes are the
      # same except ``created_at``, and that is enough to move the lock's
      # identity: a certificate issued against the draft stops covering it,
      # and "the gate did not rewrite an already-current lock" stops holding.
      if fileExists(extendedPath(manifestLayerRoot /
          expectedRecord.relPath.replace('/', DirSep))):
        continue
      let present = gitRunPlain(identity,
        ["-C", manifestLayerRoot, "ls-tree", "HEAD", "--",
         expectedRecord.relPath])
      if present.code != 0 or present.output.strip().len == 0:
        lockMissing = true
        break
  if not lockMissing:
    if lockedShas.len == 0 and committedLockPaths.len == 0:
      lockMissing = true
    else:
      for obs in observations:
        if not obs.hasGit:
          continue
        if obs.path in committedLockPaths:
          continue
        if obs.path notin lockedShas:
          lockStale = true
          break
        if lockedShas[obs.path] != obs.headSha:
          lockStale = true
          break
  if not lockMissing and not lockStale:
    result.lockUpdate.kind = cluAlreadyCurrent
    # Surface the most-recent lock file path so the operator can audit
    # which lock backed the check. MO-3: the store's ``lockKey`` carries the
    # RA-1 identity tuple, from which the ``locks/<p>/<repo>/<sha>.toml`` path
    # and trigger (repo, sha) reconstruct byte-identically.
    #
    # RA-32 — "byte-identically" is only true through the SAME encoder the
    # writer used. This raw join was the fifth site to disagree with it: for a
    # forge-shaped repo name it showed the operator
    # ``locks/<p>/stripe/sync-engine/<sha>.toml`` — a depth-5 path that does
    # not exist — as the audit trail of a lock that had in fact been written
    # correctly at depth 4.
    #
    # …and only when there IS a manifest lock key to reconstruct from.
    # ``lockMissing`` is false whenever a ROUTED backend contributed a
    # record, which does not imply the manifest store did: ``latest.lockKey``
    # is then all-empty and the join produced the degenerate
    # ``<layer>/locks/.toml`` — a path that names no project, no repo and no
    # commit, printed to the operator as "lock already current at …" as if it
    # were an audit trail. Report a path only when one exists; the renderer
    # already omits the line for an empty path.
    if latest.lockKey.sha.len > 0 and latest.lockKey.repo.len > 0 and
        latest.lockKey.project.len > 0:
      let lockRel = lockFileRepoRelativePath(
        latest.lockKey.project, latest.lockKey.repo, latest.lockKey.sha)
      result.lockUpdate.lockFilePath =
        manifestLayerRoot / lockRel.replace('/', DirSep)
    result.lockUpdate.indexFilePath = ""
    result.lockUpdate.triggerRepo = latest.lockKey.repo
    result.lockUpdate.triggerSha = latest.lockKey.sha
  else:
    # Create or refresh the lock via the M11 driver. The driver writes
    # the lock TOML, updates the index, and returns a structured report
    # carrying the new lock-file path. The driver's own ``exitCode == 2``
    # arm fires only on a dirty tree (which stage 2 above already ruled
    # out), so any non-zero exit here is genuinely lock-failure.
    var lockOutcome: WorkspaceLockOutcome
    try:
      lockOutcome = executeWorkspaceLock(lockArgs, deferParticipation = true)
    except CatchableError as err:
      # §6 Decision 2 "Remedy text shape": the named command must RUN where the
      # message is printed. "re-run 'repro check'" named the invocation that
      # had just refused — the one instruction guaranteed not to help — and it
      # DISCARDED the command the writer had already worked out and put in its
      # own message. Carry that command up verbatim when there is one; only
      # fall back to the generic sentence when the writer named nothing.
      let carried = firstNamedReproCommand(err.msg)
      result.lockUpdate.kind = cluFailed
      result.lockUpdate.diagnostic = err.msg
      result.failures.add(CheckFailure(
        repo: "",
        property: "lock-failure",
        remediation:
          if carried.len > 0:
            "run `" & carried & "` to create the lock this push needs, " &
              "then re-push"
          else:
            "investigate the lock writer error, then re-run the push",
        evidence: err.msg))
      result.exitCode = 2
      return
    if lockOutcome.report.exitCode != 0:
      result.lockUpdate.kind = cluFailed
      let diag =
        if lockOutcome.report.dirty.len > 0:
          "lock writer refused: dirty siblings"
        else: "lock writer exited with code " & $lockOutcome.report.exitCode
      result.lockUpdate.diagnostic = diag
      result.failures.add(CheckFailure(
        repo: "",
        property: "lock-failure",
        remediation: "re-run 'repro workspace lock' to diagnose",
        evidence: diag))
      result.exitCode = 2
      return
    result.lockUpdate.lockFilePath = lockOutcome.report.lockFilePath
    result.lockUpdate.indexFilePath = lockOutcome.report.indexFilePath
    result.lockUpdate.triggerRepo = lockOutcome.report.triggerRepo
    result.lockUpdate.triggerSha = lockOutcome.report.triggerSha
    # A declared repo with no checkout no longer refuses the lock, so the
    # gate must SAY that the lock it just wrote is short and by how much.
    # A notice, not a failure: materialization is the operator's choice
    # (`repro workspace sync` on demand), and the repos that genuinely
    # must be present for this push were already enforced by the
    # cleanliness / publication / MO-5 stages above.
    let unmaterializedNotice =
      unmaterializedLockNotice(lockOutcome.report.unmaterialized)
    if unmaterializedNotice.len > 0:
      result.notices.add(unmaterializedNotice)
    result.lockUpdate.kind =
      if lockMissing: cluCreated else: cluRefreshed
    # HL-3 (§6 Decision 2) — surface the per-repo, tier-tagged participation
    # outcomes from the write so the tier policy below (and ``runCheckCommand``)
    # can see WHICH backend was unreachable. Empty for the no-explicit-route
    # single-tier shape (``recordRoutedParticipation`` returns ``@[]``), so this
    # is byte-identical to pre-HL-3 there.
    deferredParticipation = lockOutcome.deferredParticipation

  # ---- 5. M26: lock visibility (public locks must not reference -----------
  # private-only repos) ----------------------------------------------------
  # The stage is a no-op unless ALL of the following hold:
  #
  #   - The workspace is compositional (``workspaceLocal.isSome``).
  #   - ``--current-repo`` is one of the manifest-layer roots declared
  #     in ``workspace.toml`` AND that layer is declared
  #     ``visibility = "public"``. Pushes from a private manifest-layer
  #     repo are out of scope: a private lock CAN reference private
  #     repos, that's literally the point of a private manifest.
  #   - The pushed refs introduce or modify at least one
  #     ``locks/<project>/<repo>/<sha>.toml`` path in the current-repo
  #     (the git-diff probe above). RA-1 dropped the shared
  #     ``index.toml`` from the lock layout, so the check operates on
  #     the whole per-repo lock path set with no special-casing.
  #
  # When triggered, the stage reads each touched lock file via the M5
  # strict ``readLock`` reader, gathers the set of declared repo paths,
  # and looks up each path in the per-path visibility map. A path that
  # exists only in non-public layers (``wvPublic notin tiers``) is a
  # violation: the lock cannot be reproduced by a public-only operator
  # who cannot acquire the private layer, which is exactly the
  # condition ``Workspace-And-Develop-Mode.md §"Interaction with
  # Locking and Publication"`` proscribes.
  if layerLocations.len == 0:
    result.exitCode = 0
    finalizePoliciesAndParticipation()
    return
  if parsed.currentRepo.len == 0:
    result.exitCode = 0
    finalizePoliciesAndParticipation()
    return
  let currentRepoAbs = parsed.currentRepo
  let currentLayer = currentManifestLayer
  if currentLayer.isNone:
    result.exitCode = 0
    finalizePoliciesAndParticipation()
    return
  if currentLayer.get().visibility != wvPublic:
    # A non-public layer pushing locks is allowed to reference any
    # tier. The spec only blocks public-lock references to private-only
    # repos.
    result.exitCode = 0
    finalizePoliciesAndParticipation()
    return
  let touchedLocks = lockPathsTouchedInPush(
    identity, currentRepoAbs, parsed.pushedRefsPath, resolved.projectName)
  if touchedLocks.len == 0:
    # No lock changes in this push — the rule is vacuously satisfied.
    result.exitCode = 0
    finalizePoliciesAndParticipation()
    return
  let pathVisibility = classifyRepoPathVisibility(
    parsed.workspaceRoot, layerLocations, resolved.projectName)
  for relLockPath in touchedLocks:
    let absLockPath = currentRepoAbs / relLockPath.replace('/', DirSep)
    if not fileExists(absLockPath):
      # The touched-lock probe reported a path the diff included but
      # which is no longer on disk (e.g. a renamed file). Treat as a
      # gate refusal so the operator investigates rather than silently
      # passing — the conservative answer.
      result.failures.add(CheckFailure(
        repo: "",
        property: "lock_references_private_repo",
        remediation: "investigate the touched lock file at " & relLockPath &
          " — it appears in the pushed diff but is not on disk",
        evidence: "lock-file-missing-on-disk: " & relLockPath,
        source: relLockPath))
      result.exitCode = 2
      return
    var parsedLock: Lock
    try:
      parsedLock = readLock(absLockPath)
    except CatchableError as err:
      # A malformed lock about to be pushed is itself a refusal-worthy
      # condition — exit-1 (IO/parse) would mask the gate intent. We
      # emit a structured failure with the parse error in the evidence.
      result.failures.add(CheckFailure(
        repo: "",
        property: "lock_references_private_repo",
        remediation: "fix lock-file parse error at " & relLockPath &
          " before pushing",
        evidence: "lock-parse-failed: " & err.msg,
        source: relLockPath))
      result.exitCode = 2
      return
    for lockedRepo in parsedLock.repo:
      let tiers =
        if lockedRepo.path in pathVisibility:
          pathVisibility[lockedRepo.path]
        else: {}
      # An unknown path (not declared by any layer's project file) is
      # treated as "private-only": no public layer publishes it, so a
      # public-only operator cannot reproduce the entry. Skipping such
      # paths silently would defeat the spec rule.
      if wvPublic notin tiers:
        let tierLabel =
          if tiers.len > 0: visibilitySetLabel(tiers)
          else: "<undeclared>"
        let layerProv = currentLayer.get().provenance
        result.failures.add(CheckFailure(
          repo: lockedRepo.path,
          property: "lock_references_private_repo",
          remediation:
            "remove the private-only repo '" & lockedRepo.path &
            "' from the lock '" & relLockPath &
            "' before publishing it to the public manifest layer '" &
            layerProv & "', or publish the lock under a non-public " &
            "manifest layer instead",
          evidence: "lock=" & relLockPath &
            " repo=" & lockedRepo.path &
            " visibility=" & tierLabel,
          source: relLockPath))
        result.exitCode = 2
        return
  result.exitCode = 0
  # HL-3 (§6 Decision 2) — the lock write recorded each repo's participation
  # through its ASSIGNED backend; inspect those tier-tagged outcomes and apply
  # the refuse-for-shared / warn-for-personal split. A failed public/team write
  # flips ``exitCode`` to 2 (REFUSE) with a ``lock-backend-unreachable`` remedy;
  # a failed personal write adds a warning notice and leaves the exit unchanged
  # (WARN + ALLOW). A no-explicit-route workspace has an empty ``participation``
  # ⇒ this is a byte-identical no-op there.
  finalizePoliciesAndParticipation()

proc writeCheckReport(report: CheckReport; destination: string) =
  ## Persist the structured JSON report at the spec-mandated location.
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

type
  PerBackendPublishTarget = object
    ## HL-2 (§6 Decision 1 — target publish path) — one DISTINCT durable
    ## backend (other than the manifest git-checkout) that a routed workspace
    ## must publish its pending records through at pre-push. ``backendKind`` is
    ## the human/JSON label for the diagnostics; ``store`` is the constructed
    ## backend whose ``publishPending`` commits + pushes its own pending records.
    ## HL-3 — ``tier`` drives the refuse-for-shared / warn-for-personal publish
    ## policy (§6 Decision 2); ``location`` names WHERE the backend lives for the
    ## remedy/warning text.
    backendKind: string
    tier: WorkspaceVisibility
    location: string
    store: LockStore
    repoNames: seq[string]
      ## Repositories assigned to this de-duplicated backend. The pre-push
      ## publisher uses this identity set to retain exact operation records
      ## when a previous explicit lock command already wrote/committed the
      ## record and the current gate therefore has no deferred write.

proc perBackendPublishTargets(parsed: CheckArgs; manifestLayerRoot: string;
    identity: GitToolIdentity): seq[PerBackendPublishTarget] =
  ## HL-2 — resolve the DISTINCT non-manifest durable backends a routed
  ## workspace must publish through at pre-push, so a personal repo's record
  ## reaches the personal store and a non-manifest team repo's record reaches
  ## its own store — never the one git-checkout manifest. Returns ``@[]`` when
  ## the workspace declares no explicit route (today's single-tier shape ⇒ the
  ## manifest publish alone, byte-identical to pre-HL-2). Backends are
  ## de-duplicated: a per-tier backend serves every repo of that tier, so it is
  ## published once. The manifest git-checkout (published separately by the
  ## RA-7/RA-21 path) and committed-lock repos (carried by the repo's own push)
  ## are excluded.
  result = @[]
  let composed = composeLockingRouting(parsed.workspaceRoot, identity.binaryPath)
  if not composed.hasExplicitRoutes: return
  var resolved: ResolvedProject
  var workspaceLocal: Option[WorkspaceLocal]
  try:
    (resolved, workspaceLocal) = resolveCheckProject(parsed)
  except CatchableError:
    return
  # Mirror the gate's RA-21 scope: only the pushed repo's develop-set closure
  # participated in the write, so only those backends have pending records.
  var currentRepoName = ""
  if parsed.currentRepo.len > 0:
    let matched = resolveRepoWorktreeMatch(
      identity, parsed.workspaceRoot, resolved.repos, parsed.currentRepo)
    if matched.found:
      currentRepoName = resolved.repos[matched.repoIndex].name
  let layerLocations = enumerateManifestLayerLocations(
    parsed.workspaceRoot, workspaceLocal)
  let currentLayer = findCurrentManifestLayer(
    layerLocations, parsed.currentRepo)
  let scope = prePushScope(resolved, currentRepoName, currentLayer)
  let scopeClosure = scope.names
  let scopeIsWholeWorkspace = scope.wholeWorkspace
  var inScope: seq[ResolvedRepo] = @[]
  for repo in resolved.repos:
    if scopeIsWholeWorkspace or repo.name in scopeClosure:
      inScope.add(repo)
  var assignments: seq[RepoBackendAssignment]
  try:
    assignments = resolveRepoBackends(
      composed, inScope, parsed.workspaceRoot, identity, identity.binaryPath)
  except StoreRoutingError:
    # An unrouted private repo already surfaced as a gate failure on the write
    # side; do not double-report here.
    return
  var backendIndexes = initTable[string, int]()
  for asg in assignments:
    if asg.store.isNil: continue          # committed-lock: repo's own push
    if storeRootMatches(asg.store, manifestLayerRoot): continue
    # De-dupe shared backends (a per-tier backend serves every repo of that
    # tier). Key on backend kind + its manifest roots.
    var key = asg.backendKind
    for r in asg.store.manifestLayerRoots():
      key.add("\0" & os.normalizedPath(absolutePath(r)))
    if backendIndexes.hasKey(key):
      result[backendIndexes[key]].repoNames.add(asg.repoName)
      continue
    backendIndexes[key] = result.len
    result.add(PerBackendPublishTarget(
      backendKind: asg.backendKind, tier: asg.visibility,
      location: asg.store.storeLocationLabel(), store: asg.store,
      repoNames: @[asg.repoName]))

proc manifestBackendParticipates(parsed: CheckArgs; manifestLayerRoot: string;
    identity: GitToolIdentity): bool =
  ## A legacy, unrouted workspace owns all of its generated records in the
  ## manifest checkout. With explicit tier routes, publish that checkout only
  ## when an in-scope repo is actually assigned to it. Otherwise an empty
  ## default manifest must not manufacture a second publication failure beside
  ## the real routed backend failure.
  if manifestLayerRoot.len == 0: return false
  let composed = composeLockingRouting(parsed.workspaceRoot,
      identity.binaryPath)
  if not composed.hasExplicitRoutes: return true
  var resolved: ResolvedProject
  var workspaceLocal: Option[WorkspaceLocal]
  try:
    (resolved, workspaceLocal) = resolveCheckProject(parsed)
  except CatchableError:
    return true
  var currentRepoName = ""
  if parsed.currentRepo.len > 0:
    let matched = resolveRepoWorktreeMatch(
      identity, parsed.workspaceRoot, resolved.repos, parsed.currentRepo)
    if matched.found:
      currentRepoName = resolved.repos[matched.repoIndex].name
  let layerLocations = enumerateManifestLayerLocations(
    parsed.workspaceRoot, workspaceLocal)
  let currentLayer = findCurrentManifestLayer(
    layerLocations, parsed.currentRepo)
  let scope = prePushScope(resolved, currentRepoName, currentLayer)
  var inScope: seq[ResolvedRepo]
  for repo in resolved.repos:
    if scope.wholeWorkspace or repo.name in scope.names:
      inScope.add(repo)
  try:
    for asg in resolveRepoBackends(
        composed, inScope, parsed.workspaceRoot, identity,
        identity.binaryPath):
      if storeRootMatches(asg.store, manifestLayerRoot):
        return true
  except StoreRoutingError:
    # The write/gate path reports routing errors. Keep the conservative legacy
    # behavior here rather than silently suppressing a potentially owned store.
    return true
  false

proc runCheckCommand*(args: openArray[string]; hookRemoteName = "";
                      hookRemoteLocation = ""): int =
  ## ``repro check --mode=pre-push [--workspace-root=PATH]
  ## [--current-repo=PATH] [--pushed-refs=FILE]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## Exit codes (per M18 / M23 design):
  ##   - 0 — every gate check passed; the lock was created / refreshed
  ##         when it was missing or stale.
  ##   - 2 — a publication-gate check (branch / clean / published /
  ##         develop-override cleanliness / lock) failed. Git aborts
  ##         the push.
  ##   - 1 — IO / resolve / VCS-tool failure unrelated to the gate.
  var parsed =
    try:
      parseCheckArgs(args)
    except ValueError as err:
      stderr.writeLine("repro check: " & err.msg)
      return 1
  parsed.hookRemoteName = hookRemoteName
  parsed.hookRemoteLocation = hookRemoteLocation
  case parsed.mode
  of cmPrePush:
    # A malformed pre-push stream is an unconditional protocol refusal, even
    # outside an initialized workspace and even when HEAD is already published.
    # Parse before the historical non-workspace no-op below.
    if parsed.pushedRefsPath.len > 0:
      let identity = ensureGitToolResolvable(
        parsed.toolProvisioning, getEnv("PATH"))
      let refs = parsePrePushRefStream(identity.binaryPath,
        if parsed.currentRepo.len > 0: parsed.currentRepo
        else: parsed.workspaceRoot,
        parsed.pushedRefsPath)
      if not refs.ok:
        stderr.writeLine("repro check: malformed pre-push protocol: " &
          refs.diagnostic)
        return 2
    # RA-10: no-op outside an initialized workspace. A managed pre-push
    # hook may be installed under a half-bootstrapped or non-workspace
    # parent (a plain git repo, or a bare ``.repo/`` with no resolved
    # manifest checkout). In that case there is nothing to enforce — the
    # gate must NOT block the push with a fatal error. Detect "not a
    # workspace" via the canonical marker and exit 0 with a clear
    # diagnostic instead of letting ``resolveCheckProject`` raise (which
    # would surface as a blocking exit 1).
    if not isInitializedWorkspace(parsed.workspaceRoot):
      stderr.writeLine("repro check: not a workspace; nothing to enforce " &
        "(no resolved manifest checkout at " & parsed.workspaceRoot &
        "); pre-push gate is a no-op")
      return 0
    # MO-1: non-gating advisory when the current repo carries a committed
    # solved-graph lock (the manifest-optional reproducibility artifact).
    # Fires ONLY when a ``repro.lock`` is present, so it never perturbs the
    # RA gate fixtures (which have none) and never changes the exit code.
    validateCommittedLockAdvisory(
      if parsed.currentRepo.len > 0: parsed.currentRepo
      else: parsed.workspaceRoot)
    var report: CheckReport
    try:
      report = executeCheckPrePush(parsed)
    except CatchableError as err:
      stderr.writeLine("repro check: error: " & err.msg)
      return 1
    # RA-7 / RA-21: on a passing pre-push gate (and only then), PUBLISH the
    # lock — commit + push the ``locks/`` subtree to the manifest repo's
    # upstream so the reproducible state actually reaches teammates. The
    # lock *write/refresh* is best-effort, but the *publication the push
    # depends on* is part of the publication boundary: RA-21 makes a
    # publish FAILURE (network / non-fast-forward / manifest dirty outside
    # ``locks/``) REFUSE the push with a clear diagnostic rather than
    # silently allow a commit whose lock never reached the manifest repo
    # (Workspace-And-Develop-Mode.md §"Lock publication is loud on
    # failure"). ``lpoNothingToPublish`` is benign (the lock was already
    # current and committed earlier). We never publish a failed gate's lock.
    if report.exitCode == 0:
      let identity = ensureGitToolResolvable(
        parsed.toolProvisioning, getEnv("PATH"))
      # HL-3 (deliverable 3) — the RA-7/RA-21 MANIFEST publish runs ONLY when a
      # ``.repo/manifests`` git-checkout is present (``manifestLayerRoot`` set).
      # The per-backend publish below runs whenever the gate passes and there
      # ARE routed non-manifest backends, REGARDLESS of manifest presence —
      # lifting HL-2's ``manifestLayerRoot.len > 0`` gate so a manifest-less
      # workspace's personal/team-on-their-own-remote backends still publish
      # (spec §5/§9). The manifest-present behavior below is byte-identical to
      # HL-2 (same store, same policy, same offer-to-run remedy).
      if report.manifestLayerRoot.len > 0 and
          manifestBackendParticipates(
            parsed, report.manifestLayerRoot, identity):
        # MO-10: route the RA-7/RA-21 pre-push publish through the abstract
        # ``LockStore`` (mirroring the gate's already-routed lock READ and
        # ``executePush``). The git-checkout backend's ``publishPending`` delegates
        # to the byte-identical ``publishWorkspaceLock``; the 1:1 outcome mapping
        # recovers the exact ``LockPublishResult`` the gate policy below branches
        # on.
        let publishStore =
          newGitCheckoutLockStore(identity, report.manifestLayerRoot)
        publishStore.pendingExpected = report.expectedManifestRecords
        let storePub = publishStore.publishPending()
        let pub = LockPublishResult(
         outcome: lockPublishFromStorePut(storePub.outcome),
         diagnostic: storePub.diagnostic)
        case pub.outcome
        of lpoPublished:
          stderr.writeLine("repro check: " & pub.diagnostic)
        of lpoNothingToPublish:
          discard
        of lpoNotPublishable:
          # The workspace is not configured to publish (no manifest git
          # checkout / no upstream). There is no publication boundary to
          # honour, so this stays a benign best-effort skip — surfaced but
          # not gating.
          stderr.writeLine("repro check: lock publish skipped: " &
            pub.diagnostic)
        of lpoRefusedDirty, lpoFailed:
          # Loud-on-failure (RA-21): the reproducible state COULD be published
          # but the attempt was refused (manifest dirty outside ``locks/``) or
          # failed (commit / push / network error). A teammate must never pull
          # a commit whose lock never reached the manifest repo, so the push is
          # refused: record the failure and flip the gate to a non-zero exit.
          var pub2 = pub
          # RA-28 offer-to-run (Principle 2 "offer to run it where safe"). A
          # PUBLISH FAILURE (``lpoFailed``: a transient commit/push/network
          # error) has a genuinely SAFE remedy: re-running the publish only
          # commits + pushes the ``locks/`` subtree — it never touches the
          # operator's working trees. So we OFFER to re-run it (TTY prompt, or
          # ``REPRO_OFFER_FIXES=1`` auto-run in non-TTY). A REFUSED-DIRTY
          # outcome is NOT offered: clearing a manifest dirty outside
          # ``locks/`` is the operator's decision, not a safe auto-fix — we
          # describe the remedy and leave it to them (honest: no faked offer).
          if pub.outcome == lpoFailed:
            let dec = offerSafeRemedy(
              description = "re-publish the workspace lock to the manifest repo",
              remedyCommand = "repro push",
              autoRun = offerFixesOptIn(),
              isTty = isatty(stdin))
            if dec == odRun:
              # MO-10: the offered re-publish also routes through the store.
              let storePub2 = publishStore.publishPending()
              pub2 = LockPublishResult(
                outcome: lockPublishFromStorePut(storePub2.outcome),
                diagnostic: storePub2.diagnostic)
              if pub2.outcome in {lpoPublished, lpoNothingToPublish}:
                stderr.writeLine("repro check: lock re-publish succeeded: " &
                  pub2.diagnostic)
          if pub2.outcome in {lpoPublished, lpoNothingToPublish}:
            # The offered remedy fixed it — the gate passes; do NOT record a
            # failure or flip the exit code.
            if pub2.outcome == lpoPublished:
              stderr.writeLine("repro check: " & pub2.diagnostic)
          else:
            let diag = "lock publication failed: " & pub2.diagnostic
            stderr.writeLine("repro check: " & diag)
            report.failures.add(CheckFailure(
              repo: "",
              property: "lock-publish-failure",
              remediation:
              "run 'repro push' to publish the workspace lock to the manifest " &
              "repo and re-push (fix the network / non-fast-forward / " &
              "manifest-dirty cause above)",
              evidence: pub2.diagnostic))
            report.exitCode = 2

      # HL-2/HL-3 (§6 Decision 1 target publish path + Decision 2 tier policy) —
      # per-backend publish. The manifest git-checkout above is one backend; a
      # mixed workspace also has team/personal records living in DISTINCT durable
      # backends. Iterate every OTHER routed backend and publish its pending
      # records through THAT backend, so a personal repo's record reaches the
      # personal store and a non-manifest team repo's record reaches its own
      # store — never the one manifest.
      #
      # HL-3 lifts HL-2's ``manifestLayerRoot.len > 0`` gate: this loop now runs
      # even in a manifest-LESS workspace (a public + personal shape with no team
      # manifest), so a personal git-checkout-on-a-remote backend gets its remote
      # push. And it applies the tier split on a publish FAILURE: a public/team
      # backend REFUSES (exit 2), a personal backend WARNS + ALLOWS (exit
      # unchanged), per §6 Decision 2.
      for target in perBackendPublishTargets(
          parsed, report.manifestLayerRoot, identity):
        if target.store of GitCheckoutLockStore:
          var expected: seq[ExpectedLockRecord]
          for write in report.deferredPublishWrites:
            if write.store.isNil or
                write.store.backendId() != target.store.backendId() or
                write.store.storeLocationLabel() !=
                  target.store.storeLocationLabel():
              continue
            let relPath = lockFileRepoRelativePath(write.record.key.project,
              write.record.key.repo, write.record.key.sha)
            let exact = expectedLockRecordFromBody(relPath, write.record.body)
            if exact.isSome: expected.add(exact.get())
          # A prior `repro workspace lock` may already have written and
          # committed this operation's routed record. In that case the gate
          # correctly produces no deferred write, but publication still has
          # to prove/resume that exact record rather than degrading to an
          # unbound "nothing to publish" result.
          for exact in report.expectedManifestRecords:
            if exact.repoName notin target.repoNames: continue
            var present = false
            for item in expected:
              if item.relPath == exact.relPath:
                present = true
                break
            if not present: expected.add(exact)
          GitCheckoutLockStore(target.store).pendingExpected = expected
        let otherPub = target.store.publishPending()
        let opub = LockPublishResult(
          outcome: lockPublishFromStorePut(otherPub.outcome),
          diagnostic: otherPub.diagnostic)
        case opub.outcome
        of lpoPublished:
          stderr.writeLine("repro check: published " & target.backendKind &
            " backend: " & opub.diagnostic)
        of lpoNothingToPublish, lpoNotPublishable:
          discard
        of lpoRefusedDirty, lpoFailed:
          let loc =
            if target.location.len > 0: " at " & target.location else: ""
          if tierIsShared(target.tier):
            let diag = "lock publication failed for " &
              lockingTierLabel(target.tier) & " " & target.backendKind &
              " backend" & loc & ": " & opub.diagnostic
            stderr.writeLine("repro check: " & diag)
            report.failures.add(CheckFailure(
              repo: "",
              property: "lock-backend-unreachable",
              remediation:
                lockingTierLabel(target.tier) & " " & target.backendKind &
                " backend" & loc & " could not be published (" &
                opub.diagnostic & "); make the backend reachable and re-run " &
                "`repro push`",
              evidence: "tier=" & lockingTierLabel(target.tier) &
                " backend=" & target.backendKind &
                (if target.location.len > 0: " location=" & target.location
                 else: "") & " diagnostic=" & opub.diagnostic))
            report.exitCode = 2
          else:
            # Personal backend — WARN but ALLOW (exit unchanged), advise the
            # WORKSPACE lock verb (§6 Decision 2): the unpublished record is a
            # ``locks/<project>/<repo>/<sha>.toml`` entry in that backend.
            let warn = "personal lock backend " & target.backendKind & loc &
              " is unreachable; personal repo participation was not published " &
              "(" & opub.diagnostic & ") — run `" &
              workspaceLockCommand(report.workspaceRoot) &
              "` when it is reachable"
            stderr.writeLine("repro check: " & warn)
            report.notices.add(warn)
    writeCheckReport(report,
      reportDestination(parsed.report, report.workspaceRoot, "check"))
    stageFailureReport(parsed.report, report.workspaceRoot, "check",
      report.toJsonNode())
    if parsed.json:
      stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
    else:
      for line in renderCheckTextLines(report):
        stdout.writeLine(line)
    return report.exitCode

# ---- RA-25: `repro push` (closure-ordered push + lock publish + certify) ---
#
# The inverse of the RA-21 publication gate. Where the gate REFUSES a push
# when the pushed repo's develop-mode dependency siblings are dirty,
# unpublished, or out of lock, `repro push` SATISFIES the gate: it pushes the
# pushed repo's develop-mode dependency closure in dependency-first
# (topological) order, then writes + publishes the workspace lock for the
# resulting state (loud on failure). See CLI/push.md and
# Workspace-And-Develop-Mode.md §"Lock publication is loud on failure".
#
# Reuse map (the spec is explicit that most substrate already exists):
#   - closure: ``developSetClosure`` (RA-21) over ``ResolvedRepo.depends``.
#   - topological order: Kahn over the same ``depends`` edges (a dependent is
#     never published before its dependency).
#   - per-repo cleanliness / publication probes: the SAME ``isCleanQuery`` /
#     ``isPublishedQuery`` / ``headShaQuery`` the gate (``executeCheckPrePush``)
#     uses.
#   - lock write: ``executeWorkspaceLock`` (M11), scoped to the closure via
#     ``dirtyScopeNames`` exactly like the gate.
#   - lock publish: ``publishWorkspaceLock`` (RA-7), loud on failure.
#   - ``--sync`` reconcile: a focused fetch + ``--merge``/``--rebase`` pass
#     over the closure (the gate-facing inverse of RA-27 sync's fast-forward;
#     RA-27's executor only fast-forwards, so the genuine upstream-integration
#     step is push-owned per CLI/push.md §"--sync flavor").

# TC-2: ``pushCertificateNotes`` (the certificate-notes carrier) is now
# DEFINED earlier in this module (the certificate schema/verifier/transport
# block was relocated above the RA-21 pre-push gate so the TC-3/RA-32
# coverage stage can call the TC-1 verifier + TC-2 reader). ``executePush``
# below calls it directly — no forward declaration is needed.

type
  PushSyncMode = enum
    psmNone        ## no ``--sync`` — reconcile nothing, just push the closure.
    psmMerge       ## ``--sync --merge`` — integrate upstream via merge.
    psmRebase      ## ``--sync --rebase`` — replay local commits onto upstream.

  PushArgs = object
    workspaceRoot: string
    projectName: string
      ## ``repro push <project>`` scopes to a named project's closure; empty
      ## means "the repo at the current directory" (CLI/push.md §Scope).
    currentRepo: string
      ## Absolute path of the repo the push is for. Defaults to the cwd;
      ## resolved to a declared repo NAME to seed the closure.
    syncMode: PushSyncMode
    certify: bool
      ## ``--certify`` (default true): obtain/attach the test certificate.
      ## The actual obtain+attach is the TC (test-certificate) campaign's
      ## job and is NOT wired yet, so this is an honest documented no-op
      ## (see ``runPushCertifyStub``). ``--no-certify`` skips it entirely.
    toolProvisioning: ToolProvisioningMode
    json: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

  PushRepoOutcome = enum
    proPushed              ## had unpublished commits → ``git push`` succeeded.
    proAlreadyPublished    ## HEAD already on a remote-tracking branch.
    proSkippedDirty        ## dirty/divergent → STOP (never silently discarded).
    proFailed              ## the ``git push`` itself failed.

  PushRepoResult = object
    name: string
    path: string
    branch: string
    headSha: string
    outcome: PushRepoOutcome
    diagnostic: string
    remediation: string

  PushSyncResult = object
    ## One closure member's ``--sync`` reconcile outcome. ``integrated`` is
    ## true when upstream movement was merged/rebased in; ``stopped`` is true
    ## on a conflict/divergence that needs human judgment (CLI/push.md: stop
    ## and report, do not guess).
    name: string
    path: string
    action: string     ## "noop" / "fast-forward" / "merge" / "rebase".
    integrated: bool
    stopped: bool
    diagnostic: string
    remediation: string

  PushReport = object
    project: string
    workspaceRoot: string
    closure: seq[string]        ## the dependency-closure repo NAMES.
    order: seq[string]          ## the TOPOLOGICAL (dependency-first) push order.
    syncMode: string
    syncResults: seq[PushSyncResult]
    repos: seq[PushRepoResult]
    certifyDeferred: bool       ## ``--certify`` requested but TC path not wired.
    certNotesPushed: seq[string]
      ## TC-2: repo paths whose attached certificate notes
      ## (``refs/notes/reprobuild/certificates``) were carried to the upstream.
    certNotesDiagnostic: string ## TC-2: a non-fatal note-push diagnostic.
    lockPublished: bool
    lockDiagnostic: string
    stoppedRepo: string
    stoppedStage: string
    verifiedLocalBackendHead: string
    retryCommand: string
    exitCode: int

  PushPreflightRepo = object
    branch: string
    headSha: string
    remoteName: string
    remoteLocationFingerprint: string
    destinationRef: string
    advertisementFingerprint: string
    published: bool
    pushable: bool

  PushLockBackendPlan = object
    root: string
    backendKind: string
    tier: WorkspaceVisibility
    expected: seq[ExpectedLockRecord]

  AdvertisedPushHead = object
    oid: string
    refName: string

  FreshPushPublication = object
    ok: bool
    published: bool
    pushable: bool
    advertisementFingerprint: string
    diagnostic: string

proc protocolV2HookReady(identity: GitToolIdentity; repoRoot: string):
    tuple[ok: bool; diagnostic: string] =
  let hook = effectivePrePushHook(identity, repoRoot)
  if hook.kind != ephReproV2:
    let reason =
      case hook.kind
      of ephNone: "missing Reprobuild pre-push hook"
      of ephReproIncompatible: hook.diagnostic
      of ephThirdParty: "effective pre-push hook is not Reprobuild protocol v2"
      of ephReproV2: ""
    return (false, reason & "; run '" & getAppFilename() &
      " hooks ensure --vcs " & repoRoot & "'")
  let hookCli = resolveHookReproCli(repoRoot)
  if hookCli.len == 0:
    return (false, "the hook-resolved repro executable is unavailable; run '" &
      getAppFilename() & " hooks ensure --vcs " & repoRoot & "'")
  let probe = execCmdEx(shellCommand(@[hookCli, "hooks", "protocol",
    "--require=2"]), options = {poStdErrToStdOut, poUsePath},
    env = scrubbedGitChildEnv())
  if probe.exitCode != 0 or probe.output.strip() != "2":
    return (false, "hook protocol mismatch; run '" & getAppFilename() &
      " hooks ensure --vcs " & repoRoot & "' and retry")
  (true, "")

proc parsePushArgs(args: openArray[string]): PushArgs =
  ## ``repro push [<project>] [--sync] [--merge|--rebase]
  ## [--certify|--no-certify] [--workspace-root=PATH] [--current-repo=PATH]
  ## [--tool-provisioning=...] [--json]``.
  result.toolProvisioning = tpmPathOnly
  result.certify = true ## CLI/push.md: certify by default; --no-certify opts out.
  var wantSync = false
  var explicitFlavor = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--current-repo" or arg.startsWith("--current-repo="):
      result.currentRepo = valueFromFlag(args, i, "--current-repo")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--sync":
      wantSync = true
    elif arg == "--merge":
      result.syncMode = psmMerge
      explicitFlavor = true
    elif arg == "--rebase":
      result.syncMode = psmRebase
      explicitFlavor = true
    elif arg == "--certify":
      result.certify = true
    elif arg == "--no-certify":
      result.certify = false
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro push` flag: " & arg)
    else:
      if result.projectName.len > 0:
        raise newException(ValueError,
          "`repro push` takes at most one <project> argument; got an " &
          "extra positional: " & arg)
      result.projectName = arg
    inc i
  # ``--merge``/``--rebase`` imply ``--sync`` (you cannot pick a reconcile
  # flavor without reconciling). A bare ``--sync`` defaults to merge — the
  # same conservative, preserve-developer-intent default repo tooling uses
  # when the flavor is unspecified.
  if wantSync and not explicitFlavor:
    result.syncMode = psmMerge
  elif not wantSync and not explicitFlavor:
    result.syncMode = psmNone
  if result.workspaceRoot.len == 0:
    # Same walk as the gate: key on the WORKSPACE, not on a ``.repro/``
    # directory a built repo carries of its own.
    if result.currentRepo.len > 0:
      result.workspaceRoot = enclosingWorkspaceRoot(result.currentRepo)
      if result.workspaceRoot.len == 0:
        result.workspaceRoot = enclosingReproShell(result.currentRepo)
    if result.workspaceRoot.len == 0:
      result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)
  if result.currentRepo.len == 0:
    result.currentRepo = getCurrentDir()
  result.currentRepo = absolutePath(result.currentRepo)

proc topoSortClosure(repos: seq[ResolvedRepo];
                     closure: HashSet[string]): seq[string] =
  ## Kahn topological sort of the closure over the per-repo ``depends``
  ## edges, DEPENDENCY-FIRST: a repo is emitted only after every dependency
  ## it names (that is also in the closure) has been emitted. This is the
  ## load-bearing guarantee of ``repro push`` — a dependent is NEVER pushed
  ## before its dependency (CLI/push.md High-Level Rules).
  ##
  ## Edges are restricted to the closure (an out-of-closure ``depends``
  ## target cannot gate a member). Ties are broken by declaration order so
  ## the push order is deterministic. A dependency cycle (which the manifest
  ## should never contain) is surfaced by appending the unresolved remainder
  ## in declaration order rather than silently dropping repos — the push
  ## still runs, and the lock publish + gate remain the correctness backstop.
  var byName = initTable[string, ResolvedRepo]()
  var declOrder: seq[string]
  for repo in repos:
    if repo.name in closure and repo.name notin byName:
      byName[repo.name] = repo
      declOrder.add(repo.name)
  # In-degree = number of (in-closure) dependencies each node still waits on.
  var indeg = initTable[string, int]()
  var dependents = initTable[string, seq[string]]()  # dep -> nodes that need it
  for name in declOrder:
    indeg[name] = 0
  for name in declOrder:
    for dep in byName[name].depends:
      if dep.len > 0 and dep in byName:
        inc indeg[name]
        dependents.mgetOrPut(dep, @[]).add(name)
  # Seed the ready set with zero-dependency nodes, preserving declaration
  # order for determinism.
  var ready: seq[string]
  for name in declOrder:
    if indeg[name] == 0:
      ready.add(name)
  var emitted = initHashSet[string]()
  while ready.len > 0:
    let name = ready[0]
    ready.delete(0)
    if name in emitted:
      continue
    result.add(name)
    emitted.incl(name)
    if name in dependents:
      for dependent in dependents[name]:
        dec indeg[dependent]
        if indeg[dependent] == 0:
          ready.add(dependent)
  # Cycle / unresolved remainder safety net (never expected in practice).
  if emitted.len < declOrder.len:
    for name in declOrder:
      if name notin emitted:
        result.add(name)
        emitted.incl(name)

proc reconcileMemberForPush(identity: GitToolIdentity; workspaceRoot: string;
                            repo: ResolvedRepo;
                            mode: PushSyncMode): PushSyncResult =
  ## RA-25 ``--sync`` reconcile for one closure member: fetch the upstream,
  ## then integrate any upstream movement on the repo's CURRENT branch via
  ## ``--merge`` or ``--rebase`` BEFORE the closure push runs (CLI/push.md
  ## §"--sync flavor"). The conservative rules mirror ``repro sync``:
  ##
  ##   - no upstream / not on a branch → noop (nothing to reconcile).
  ##   - upstream unchanged from HEAD → noop.
  ##   - HEAD already contains the upstream tip (we're ahead only) → noop;
  ##     the local commits get published by the push step.
  ##   - HEAD strictly behind a fast-forwardable upstream → fast-forward.
  ##   - divergent (local + upstream both moved) → merge or rebase per mode.
  ##
  ## A conflict (merge/rebase fails) STOPS with a remedy naming the repo and
  ## leaves the tree in git's conflicted state for the operator — it never
  ## guesses (CLI/push.md: "stops and reports it with the remedy").
  result.name = repo.name
  result.path = repo.path
  result.action = "noop"
  let repoAbs = workspaceRoot / repo.path
  if not discoverGitWorktree(identity, repoAbs).ok:
    return
  let branchRes = gitRunPlain(identity,
    ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
  if branchRes.code != 0 or branchRes.output.strip().len == 0:
    # Detached HEAD — nothing branch-scoped to reconcile.
    return
  let branch = branchRes.output.strip()
  let rName = gitRemoteNameFor(repo)
  let upstreamBeforeRes = gitRunPlain(identity,
    ["-C", repoAbs, "rev-parse", "--abbrev-ref",
     "--symbolic-full-name", "@{u}"])
  let upstreamBefore =
    if upstreamBeforeRes.code == 0: upstreamBeforeRes.output.strip()
    else: ""
  defer:
    let branchAfterRes = gitRunPlain(identity,
      ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
    let branchAfter =
      if branchAfterRes.code == 0: branchAfterRes.output.strip()
      else: ""
    let upstreamAfterRes = gitRunPlain(identity,
      ["-C", repoAbs, "rev-parse", "--abbrev-ref",
       "--symbolic-full-name", "@{u}"])
    let upstreamAfter =
      if upstreamAfterRes.code == 0: upstreamAfterRes.output.strip()
      else: ""
    if branchAfter != branch or upstreamAfter != upstreamBefore:
      result.stopped = true
      result.integrated = false
      result.diagnostic = "sync changed the checked-out branch or upstream " &
        "binding in " & repo.path
      result.remediation = "restore branch " & branch &
        " and its upstream, then retry 'repro push --sync'"
  # Fetch the upstream so the remote-tracking ref reflects teammate movement.
  let fetchRes = gitRunPlain(identity, ["-C", repoAbs, "fetch", "--quiet",
    rName])
  if fetchRes.code != 0:
    result.stopped = true
    result.diagnostic = "git fetch " & rName & " failed in " & repo.path &
      "; transport output was withheld because remotes may contain credentials"
    result.remediation = "check connectivity / credentials for " & repo.path &
      " then re-run 'repro push --sync'"
    return
  let head = revParse(identity, repoAbs, "HEAD")
  let upstream = revParse(identity, repoAbs, "refs/remotes/" & rName & "/" & branch)
  if upstream.len == 0 or head.len == 0 or head == upstream:
    return
  # Is upstream already contained in HEAD? (we're strictly ahead — pure
  # local work). Nothing to integrate; the push step publishes it.
  let upstreamInHead = gitRunPlain(identity,
    ["-C", repoAbs, "merge-base", "--is-ancestor", upstream, head])
  if upstreamInHead.code == 0:
    return
  # Is HEAD an ancestor of upstream? (pure fast-forward — we're behind).
  let headInUpstream = gitRunPlain(identity,
    ["-C", repoAbs, "merge-base", "--is-ancestor", head, upstream])
  if headInUpstream.code == 0:
    let ff = gitRunPlain(identity,
      ["-C", repoAbs, "merge", "--ff-only", rName & "/" & branch])
    if ff.code != 0:
      result.stopped = true
      result.diagnostic = "fast-forward of " & repo.path & " failed: " &
        ff.output.strip()
      result.remediation = "resolve manually in " & repo.path &
        " then re-run 'repro push'"
      return
    result.action = "fast-forward"
    result.integrated = true
    return
  # Genuine divergence: both HEAD and upstream advanced. Integrate per mode.
  case mode
  of psmNone:
    # ``--sync`` was not requested but we somehow diverged — report-and-stop
    # rather than guess. (Unreachable from the dispatcher, which only calls
    # this when a sync mode is set; kept for completeness.)
    result.stopped = true
    result.diagnostic = repo.path & " has diverged from " & rName & "/" & branch
    result.remediation = "run 'repro push --sync --rebase' (or --merge) to " &
      "integrate " & rName & "/" & branch & " in " & repo.path
  of psmMerge:
    let m = gitRunPlain(identity,
      ["-C", repoAbs, "merge", "--no-edit", rName & "/" & branch])
    if m.code != 0:
      # Abort the half-applied merge so the tree is not left mid-conflict
      # for the operator to puzzle over an unexpected state.
      discard gitRunPlain(identity, ["-C", repoAbs, "merge", "--abort"])
      result.stopped = true
      result.diagnostic = "merge of " & rName & "/" & branch & " into " &
        repo.path &
        " hit a conflict: " & m.output.strip()
      result.remediation = "resolve the conflict in " & repo.path &
        " (git -C " & repo.path & " merge " & rName & "/" & branch &
        "), commit, then re-run 'repro push'"
      return
    result.action = "merge"
    result.integrated = true
  of psmRebase:
    let r = gitRunPlain(identity,
      ["-C", repoAbs, "rebase", rName & "/" & branch])
    if r.code != 0:
      discard gitRunPlain(identity, ["-C", repoAbs, "rebase", "--abort"])
      result.stopped = true
      result.diagnostic = "rebase onto " & rName & "/" & branch & " in " &
        repo.path &
        " hit a conflict: " & r.output.strip()
      result.remediation = "resolve the conflict in " & repo.path &
        " (git -C " & repo.path & " rebase " & rName & "/" & branch &
        "), then re-run 'repro push'"
      return
    result.action = "rebase"
    result.integrated = true

proc runPushCertifyStub(report: var PushReport; certify: bool) =
  ## RA-25 certify FLAG + pipeline slot. The certificate obtain+attach is the
  ## TC (test-certificate) campaign's deliverable and is NOT wired here yet:
  ## this is the HONEST place in the pipeline where certification would run.
  ## ``--certify`` (default) records that the step is deferred (the push
  ## relies on whatever certificates are already attached); ``--no-certify``
  ## skips even that. We NEVER fake running tests or attaching a certificate.
  if certify:
    report.certifyDeferred = true
    stderr.writeLine("repro push: certification is not wired yet " &
      "(deferred to the test-certificate campaign); this push relies on " &
      "whatever certificates are already attached. Use --no-certify to " &
      "silence this notice.")
  else:
    report.certifyDeferred = false

proc configuredPushLocationValues(identity: GitToolIdentity; repoRoot,
    remoteName: string): tuple[ok: bool; values: seq[string];
                               fingerprint: string] =
  ## Return configured push destinations only to in-memory callers. URLs may
  ## contain embedded credentials, so neither this helper nor its callers
  ## include Git's output or an individual URL in a diagnostic.
  let locations = gitRunPlainEnv(identity,
    ["-C", repoRoot, "remote", "get-url", "--push", "--all", remoteName])
  if locations.code != 0: return
  var digests: seq[string]
  for line in locations.output.splitLines():
    let value = line.strip()
    if value.len == 0: continue
    result.values.add(value)
    digests.add(remoteLocationDigest(value))
  digests.sort()
  if result.values.len == 0: return
  result.fingerprint = digests.join(",")
  result.ok = true

proc advertisedPushHeads(identity: GitToolIdentity; probeGitDir,
    pushLocation: string; oidLength: int):
    tuple[ok: bool; heads: seq[AdvertisedPushHead]] =
  ## Read the actual advertised branch tips at one push destination. The
  ## location is passed as structured argv after `--` and never rendered in a
  ## command, log, or error. Malformed advertisements fail closed.
  let advertised = gitRunPlainEnv(identity,
    ["--git-dir=" & probeGitDir, "ls-remote", "--heads", "--", pushLocation])
  if advertised.code != 0: return
  for raw in advertised.output.splitLines():
    let line = raw.strip()
    if line.len == 0: continue
    let fields = line.splitWhitespace()
    if fields.len != 2 or not isFullHexOid(fields[0], oidLength) or
        not fields[1].startsWith("refs/heads/"):
      return
    result.heads.add(AdvertisedPushHead(
      oid: fields[0].toLowerAscii(), refName: fields[1]))
  result.heads.sort(proc(a, b: AdvertisedPushHead): int =
    result = cmp(a.refName, b.refName)
    if result == 0: result = cmp(a.oid, b.oid))
  result.ok = true

proc observeFreshPushPublication(identity: GitToolIdentity; repoRoot,
    remoteName, expectedLocationFingerprint, headOid,
    destinationRef: string):
    FreshPushPublication =
  ## Prove publication against every actual push URL, not against fetch-side
  ## remote-tracking refs. This is used once during global preflight and again
  ## immediately before deciding between a no-op and `git push`.
  ##
  ## A push remote can have multiple push URLs and Git publishes to each one.
  ## For an attached checkout, classify the exact destination ref that the
  ## later ``HEAD:<branch>`` transport will update at every URL. A partially
  ## published set is pushable only when every existing destination tip is an
  ## ancestor of HEAD; otherwise one URL could advance before a later URL
  ## rejects the same multi-push. For a detached checkout there is no
  ## destination ref to update, so only the already-published case is valid:
  ## HEAD must be reachable from some advertised branch at every URL.
  let format = storageObjectFormat(identity.binaryPath, repoRoot)
  let oidLength =
    case format
    of "sha1": 40
    of "sha256": 64
    else: 0
  if oidLength == 0 or not isFullHexOid(headOid, oidLength):
    result.diagnostic = "cannot validate the source object format"
    return
  let beforeLocations = configuredPushLocationValues(identity, repoRoot,
    remoteName)
  if not beforeLocations.ok or
      beforeLocations.fingerprint != expectedLocationFingerprint:
    result.diagnostic = "agreed remote location changed or became unavailable"
    return

  # Transfer any advertised objects into a disposable bare probe. Its only
  # alternate is the source repository's existing object directory, so Git can
  # evaluate ancestry without adding loose objects, packs, refs, FETCH_HEAD, or
  # configuration to the source checkout/common directory.
  let source = discoverGitWorktree(identity, repoRoot)
  if not source.ok:
    result.diagnostic = "cannot locate the source object store"
    return
  let sourceObjects = source.commonDir / "objects"
  if not dirExists(sourceObjects):
    result.diagnostic = "cannot locate the source object store"
    return
  let probeGitDir = createTempDir("repro-push-advertisement-", "")
  defer:
    if dirExists(probeGitDir): removeDir(probeGitDir)
  let initialized = gitRunPlainEnv(identity, ["init", "--bare", probeGitDir])
  if initialized.code != 0:
    result.diagnostic = "cannot initialize an isolated publication probe"
    return
  let alternatesDir = probeGitDir / "objects" / "info"
  createDir(alternatesDir)
  if '\n' in sourceObjects or '\r' in sourceObjects:
    result.diagnostic = "source object-store path cannot be represented safely"
    return
  writeFile(alternatesDir / "alternates", sourceObjects & "\n")

  result.published = true
  result.pushable = true
  var destinationStates: seq[string]
  for index, pushLocation in beforeLocations.values:
    let first = advertisedPushHeads(identity, probeGitDir, pushLocation,
      oidLength)
    if not first.ok:
      result.diagnostic = "push destination " & $(index + 1) &
        " did not provide a valid branch advertisement"
      return

    var relevantHeads: seq[AdvertisedPushHead]
    if destinationRef.len > 0:
      for head in first.heads:
        if head.refName == destinationRef and
            head.oid != repeat('0', oidLength):
          relevantHeads.add(head)
    else:
      relevantHeads = first.heads

    # `ls-remote` gives exact destination OIDs but does not transfer their
    # objects. Fetch only the relevant named advertised heads, without
    # FETCH_HEAD or any local ref update, when ancestry cannot yet be
    # evaluated locally.
    for head in relevantHeads:
      let available = gitRunPlainEnv(identity,
        ["--git-dir=" & probeGitDir, "cat-file", "-e",
         head.oid & "^{commit}"])
      if available.code != 0:
        let fetched = gitRunPlainEnv(identity,
          ["--git-dir=" & probeGitDir, "fetch", "--quiet", "--no-tags",
           "--no-write-fetch-head", "--", pushLocation, head.refName])
        if fetched.code != 0 or gitRunPlainEnv(identity,
            ["--git-dir=" & probeGitDir, "cat-file", "-e",
             head.oid & "^{commit}"]).code != 0:
          result.diagnostic = "push destination " & $(index + 1) &
            " advertised an unverifiable branch tip"
          return

    # Detect a destination race across the object transfer. A changed
    # advertisement is never silently reinterpreted as a no-op or a push.
    let second = advertisedPushHeads(identity, probeGitDir, pushLocation,
      oidLength)
    if not second.ok or second.heads != first.heads:
      result.diagnostic = "push destination " & $(index + 1) &
        " changed while publication was being revalidated"
      return

    let locationId = remoteLocationDigest(pushLocation)
    if destinationRef.len > 0:
      var exactTip = ""
      for advertised in second.heads:
        if advertised.refName == destinationRef and
            advertised.oid != repeat('0', oidLength):
          exactTip = advertised.oid
          break
      destinationStates.add(locationId & "\t" & destinationRef & "\t" &
        (if exactTip.len > 0: exactTip else: "<missing>"))
      if exactTip.len == 0:
        result.published = false
      else:
        let headInTip = gitRunPlainEnv(identity,
          ["--git-dir=" & probeGitDir, "merge-base", "--is-ancestor",
           headOid, exactTip]).code == 0
        let tipInHead = gitRunPlainEnv(identity,
          ["--git-dir=" & probeGitDir, "merge-base", "--is-ancestor",
           exactTip, headOid]).code == 0
        if not headInTip:
          result.published = false
        if not tipInHead:
          result.pushable = false
    else:
      var state = locationId
      var reachable = false
      for advertised in second.heads:
        state.add("\t" & advertised.refName & "\t" & advertised.oid)
        if gitRunPlainEnv(identity,
            ["--git-dir=" & probeGitDir, "merge-base", "--is-ancestor",
             headOid, advertised.oid]).code == 0:
          reachable = true
      destinationStates.add(state)
      if not reachable:
        result.published = false
        result.pushable = false

  # A strict descendant is harmless only for a complete no-op. If another
  # destination is missing or behind, ``pushable`` remains false so the caller
  # refuses before transport instead of risking a partial plural push.
  result.advertisementFingerprint = destinationStates.join("\n")

  # Remote configuration is mutable independently of the advertisement. Read
  # it once more so a concurrent push-URL rewrite cannot switch the following
  # `git push` to a destination that was never checked.
  let afterLocations = configuredPushLocationValues(identity, repoRoot,
    remoteName)
  if not afterLocations.ok or
      afterLocations.fingerprint != beforeLocations.fingerprint:
    result.diagnostic = "agreed remote location changed during revalidation"
    return
  result.ok = true

proc preflightPushRepo(identity: GitToolIdentity; workspaceRoot: string;
    repo: ResolvedRepo; allowSyncDivergence = false):
    tuple[ok: bool; observed: PushPreflightRepo;
                                stage: string; diagnostic: string;
                                remediation: string] =
  ## Observe every predictable source-push prerequisite before the first
  ## closure member is transmitted. Source checkout/common-dir state is
  ## strictly read-only: all network advertisement and object transfer happens
  ## in a disposable bare probe with the source object directory as a
  ## read-only alternate.
  let repoAbs = workspaceRoot / repo.path
  if not discoverGitWorktree(identity, repoAbs).ok:
    return (false, PushPreflightRepo(), "checkout-preflight",
      "no Git checkout at " & repo.path,
      "run 'repro workspace sync' and retry 'repro push'")
  let hook = protocolV2HookReady(identity, repoAbs)
  if not hook.ok:
    return (false, PushPreflightRepo(), "hook-preflight", hook.diagnostic,
      getAppFilename() & " hooks ensure --vcs " & repoAbs)
  let head = gitRunPlain(identity,
    ["-C", repoAbs, "rev-parse", "--verify", "HEAD^{commit}"])
  if head.code != 0 or head.output.strip().len == 0:
    return (false, PushPreflightRepo(), "state-preflight",
      "HEAD does not resolve to a commit in " & repo.path,
      "repair the checkout and retry 'repro push'")
  result.observed.headSha = head.output.strip().toLowerAscii()
  let clean = gitRunPlain(identity,
    ["--no-optional-locks", "-C", repoAbs, "status", "--porcelain=v1"])
  if clean.code != 0 or clean.output.strip().len > 0:
    let reason =
      if clean.code != 0: "clean-probe-failed"
      else: "working tree has uncommitted changes"
    return (false, result.observed, "clean-preflight", reason,
      "commit or stash changes in " & repo.path & " and retry 'repro push'")
  result.observed.remoteName = gitRemoteNameFor(repo)
  let locations = configuredPushLocationValues(identity, repoAbs,
    result.observed.remoteName)
  if not locations.ok:
    return (false, result.observed, "remote-preflight",
      "configured push location is unavailable in " & repo.path,
      "restore the agreed remote and retry 'repro push'")
  result.observed.remoteLocationFingerprint = locations.fingerprint
  let branch = gitRunPlain(identity,
    ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
  if branch.code == 0:
    result.observed.branch = branch.output.strip()
    result.observed.destinationRef =
      "refs/heads/" & result.observed.branch
  let published = observeFreshPushPublication(identity, repoAbs,
    result.observed.remoteName, result.observed.remoteLocationFingerprint,
    result.observed.headSha, result.observed.destinationRef)
  if not published.ok:
    return (false, result.observed, "remote-preflight",
      published.diagnostic & " in " & repo.path &
        "; transport output was withheld because remotes may contain credentials",
      "fix connectivity, credentials, or remote configuration and retry " &
        "'repro push --sync --rebase'")
  result.observed.published = published.published
  result.observed.pushable = published.pushable
  result.observed.advertisementFingerprint =
    published.advertisementFingerprint
  if result.observed.branch.len == 0 and not result.observed.published:
    return (false, result.observed, "branch-preflight",
      "unpublished HEAD is detached in " & repo.path,
      "attach the checkout to a branch and retry 'repro push'")
  if result.observed.branch.len > 0 and
      not result.observed.published and not result.observed.pushable and
      not allowSyncDivergence:
    return (false, result.observed, "divergence-preflight",
      repo.path & " has a divergent exact push destination branch",
      "run 'repro push --sync --rebase' after resolving " & repo.path)
  result.ok = true

proc revalidatePushRepo(identity: GitToolIdentity; workspaceRoot: string;
    repo: ResolvedRepo; expected: PushPreflightRepo):
    tuple[ok: bool; diagnostic: string; remediation: string] =
  ## Run immediately before this repository's transport. A preserved hook on
  ## an earlier dependency, another process, or an operator can change a later
  ## checkout after global preflight; the stale plan must never authorize a
  ## different HEAD/branch/tree/remote relationship.
  let repoAbs = workspaceRoot / repo.path
  if not discoverGitWorktree(identity, repoAbs).ok:
    return (false, "Git worktree disappeared after preflight in " & repo.path,
      "restore the checkout and retry 'repro push'")
  let head = gitRunPlain(identity,
    ["-C", repoAbs, "rev-parse", "--verify", "HEAD^{commit}"])
  if head.code != 0 or
      head.output.strip().toLowerAscii() != expected.headSha:
    return (false, "HEAD changed after preflight in " & repo.path,
      "review the new commit and retry 'repro push'")
  let branch = gitRunPlain(identity,
    ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
  let currentBranch =
    if branch.code == 0: branch.output.strip()
    else: ""
  if currentBranch != expected.branch:
    return (false, "branch changed after preflight in " & repo.path,
      "restore the intended branch and retry 'repro push'")
  let clean = gitRunPlain(identity,
    ["--no-optional-locks", "-C", repoAbs, "status", "--porcelain=v1"])
  if clean.code != 0 or clean.output.strip().len > 0:
    return (false, "working tree changed after preflight in " & repo.path,
      "commit or stash changes and retry 'repro push'")
  let locations = gitRunPlain(identity,
    ["-C", repoAbs, "remote", "get-url", "--push", "--all",
     expected.remoteName])
  var locationDigests: seq[string]
  if locations.code == 0:
    for line in locations.output.splitLines():
      let value = line.strip()
      if value.len > 0:
        locationDigests.add(remoteLocationDigest(value))
  locationDigests.sort()
  if locationDigests.len == 0 or
      locationDigests.join(",") != expected.remoteLocationFingerprint:
    return (false, "agreed remote location changed after preflight in " &
      repo.path, "restore the intended remote and retry 'repro push'")
  let locationsAfterObservation = gitRunPlain(identity,
    ["-C", repoAbs, "remote", "get-url", "--push", "--all",
     expected.remoteName])
  var afterDigests: seq[string]
  if locationsAfterObservation.code == 0:
    for line in locationsAfterObservation.output.splitLines():
      let value = line.strip()
      if value.len > 0:
        afterDigests.add(remoteLocationDigest(value))
  afterDigests.sort()
  if afterDigests.len == 0 or
      afterDigests.join(",") != expected.remoteLocationFingerprint:
    return (false, "agreed remote location changed during revalidation in " &
      repo.path, "restore the intended remote and retry 'repro push'")
  let published = observeFreshPushPublication(identity, repoAbs,
    expected.remoteName, expected.remoteLocationFingerprint,
    expected.headSha, expected.destinationRef)
  if not published.ok:
    return (false, "actual push destination could not be revalidated " &
      "after preflight in " & repo.path & ": " & published.diagnostic &
      "; transport output was withheld because remotes may contain credentials",
      "fix connectivity, credentials, or remote configuration and retry " &
        "'repro push --sync --rebase'")
  if published.advertisementFingerprint !=
      expected.advertisementFingerprint or
      published.published != expected.published or
      published.pushable != expected.pushable:
    return (false, "exact destination advertisement changed after " &
      "preflight in " & repo.path,
      "review the actual push destination and retry " &
        "'repro push --sync --rebase'")
  (true, "", "")

proc preflightBackendHook(identity: GitToolIdentity; backendRoot: string):
    tuple[ok: bool; diagnostic: string] =
  if backendRoot.len == 0 or gitTopLevel(backendRoot).len == 0:
    return (true, "")
  protocolV2HookReady(identity, backendRoot)

proc pushLockBackendPlans(identity: GitToolIdentity; workspaceRoot: string;
    resolved: ResolvedProject; order: openArray[string];
    preflight: Table[string, PushPreflightRepo]; manifestLayerRoot: string):
    seq[PushLockBackendPlan] =
  ## Resolve the same composed routing plane used by the gate and group exact
  ## content-addressed records by their durable Git checkout. A backend shared
  ## by multiple repos is preflighted and completed once. If a configuration
  ## ever aliases personal and shared repos to one location, shared refusal
  ## semantics win (the backend is part of a teammate-visible boundary).
  var reposByName = initTable[string, ResolvedRepo]()
  for repo in resolved.repos: reposByName[repo.name] = repo
  var indexByRoot = initTable[string, int]()
  var plans: seq[PushLockBackendPlan]

  proc canonicalExisting(path: string): string =
    try: os.normalizedPath(expandFilename(path))
    except OSError: os.normalizedPath(absolutePath(path))

  proc add(root, kind: string; tier: WorkspaceVisibility;
      repoName, repoPath, oid, lockPath: string) =
    let canonical = canonicalExisting(root)
    if canonical.len == 0: return
    var index = indexByRoot.getOrDefault(canonical, -1)
    if index < 0:
      index = plans.len
      indexByRoot[canonical] = index
      plans.add(PushLockBackendPlan(root: canonical, backendKind: kind,
        tier: tier))
    elif tierIsShared(tier):
      plans[index].tier = tier
    for item in plans[index].expected:
      if item.relPath == lockPath: return
    plans[index].expected.add(ExpectedLockRecord(
      project: resolved.projectName, repoName: repoName, repoPath: repoPath,
      oid: oid, relPath: lockPath))

  let composed = composeLockingRouting(workspaceRoot, identity.binaryPath)
  if not composed.hasExplicitRoutes:
    if manifestLayerRoot.len > 0 and gitTopLevel(manifestLayerRoot).len > 0:
      for name in order:
        add(manifestLayerRoot, "git-checkout", wvTeam, name,
          reposByName[name].path, preflight[name].headSha,
          lockFileRepoRelativePath(resolved.projectName, name,
            preflight[name].headSha))
    return plans

  var inScope: seq[ResolvedRepo]
  for name in order:
    if reposByName.hasKey(name): inScope.add(reposByName[name])
  let assignments = resolveRepoBackends(composed, inScope, workspaceRoot,
    identity, identity.binaryPath)
  for asg in assignments:
    if asg.store.isNil: continue
    let roots = asg.store.manifestLayerRoots()
    for root in roots:
      add(root, asg.backendKind, asg.visibility, asg.repoName, asg.repoPath,
        preflight[asg.repoName].headSha,
        lockFileRepoRelativePath(resolved.projectName, asg.repoName,
          preflight[asg.repoName].headSha))
  plans

proc expectedPaths(plan: PushLockBackendPlan;
    includedRepos: HashSet[string]): seq[ExpectedLockRecord] =
  for item in plan.expected:
    if item.repoName in includedRepos: result.add(item)

proc allExpectedRecords(plan: PushLockBackendPlan): seq[ExpectedLockRecord] =
  plan.expected

type BackendPlanPreflight = object
  ok: bool
  diagnostic: string
  verifiedLocalHead: string

proc pendingFileIsCanonicalLock(plan: PushLockBackendPlan;
    entry: tuple[code, path: string]): bool =
  ## Post-commit refresh may have prepared an exact lock file without staging
  ## it. That is expected input to the later pre-push publisher, not arbitrary
  ## backend dirt. Preflight remains read-only and accepts only a new regular
  ## file whose path/body form one exact typed coordinate. A dependency's
  ## earlier post-commit refresh may have prepared a still-valid older record;
  ## the publisher can safely append it alongside this operation's records.
  if entry.code notin ["??", "A "]: return false
  let relPath = entry.path.replace('\\', '/')
  if not pathIsUnderLocks(relPath): return false
  let path = plan.root / entry.path.replace('/', DirSep)
  if not fileExists(path) or symlinkExists(path) or getFileSize(path) == 0:
    return false
  expectedLockRecordFromBody(relPath, readFile(path)).isSome

proc verifiedExpectedPrefixAt(identity: GitToolIdentity;
    plan: PushLockBackendPlan; commit: string):
    tuple[ok: bool; records: seq[ExpectedLockRecord]; diagnostic: string] =
  ## A failed earlier invocation can leave the backend ahead after only a
  ## dependency prefix has run its real pre-push hook. Recover that prefix
  ## without pretending later closure records exist: every present record is
  ## exact, presence must be a contiguous topological prefix, and a later
  ## record after a gap is an invalid/unexpected recovery state.
  var sawGap = false
  let format = storageObjectFormat(identity.binaryPath, plan.root)
  if format.len == 0:
    return (false, @[], "cannot determine backend Git object format")
  for item in plan.expected:
    let tree = gitRunPlain(identity,
      ["-C", plan.root, "ls-tree", commit, "--", item.relPath])
    let present = tree.code == 0 and tree.output.strip().len > 0
    if not present:
      sawGap = true
      continue
    if sawGap:
      return (false, @[], "lock backend contains non-prefix operation " &
        "record " & item.relPath)
    let blob = verifyLockBlobAt(identity, plan.root, commit, item.relPath)
    if not blob.ok: return (false, @[], blob.diagnostic)
    let record = verifyLockRecordPath(identity, plan.root, commit,
      item.relPath, format, some(item))
    if not record.ok: return (false, @[], record.diagnostic)
    result.records.add(item)
  if result.records.len == 0:
    return (false, @[], "lock backend ahead chain contains no verified " &
      "operation prefix")
  result.ok = true

proc preflightLockBackendPlan(identity: GitToolIdentity;
    plan: PushLockBackendPlan): BackendPlanPreflight =
  ## A source ref is irreversible once transmitted, so every durable Git
  ## backend is completely inspected first. This routine may authenticate and
  ## fetch into FETCH_HEAD, but never stages, commits, rebases, resets, pushes,
  ## writes a store, or changes a branch/worktree.
  let discovery = discoverGitWorktree(identity, plan.root)
  if not discovery.ok:
    result.diagnostic = discovery.diagnostic
    return
  let hook = preflightBackendHook(identity, plan.root)
  if not hook.ok:
    result.diagnostic = hook.diagnostic
    return
  let dirty = gitPorcelainEntries(identity, plan.root)
  let unexpectedDirty = dirty.filterIt(not plan.pendingFileIsCanonicalLock(it))
  if unexpectedDirty.len > 0:
    result.diagnostic = "lock backend is not clean before source publication: " &
      unexpectedDirty.mapIt(it.code & " " & it.path).join(", ")
    return
  let upstream = resolveLockUpstream(identity, plan.root)
  if not upstream.ok:
    result.diagnostic = upstream.diagnostic
    return
  for item in plan.expected:
    if not canonicalRepoCoordinate(item.repoPath) or
        item.relPath != lockFileRepoRelativePath(item.project, item.repoName,
          item.oid):
      result.diagnostic = "lock backend plan contains a non-canonical exact " &
        "record coordinate for " & item.repoName
      return
  let fetched = fetchImmutableLockTip(identity, plan.root, upstream.target)
  if not fetched.ok:
    result.diagnostic = fetched.diagnostic
    return
  let local = gitRunPlain(identity,
    ["-C", plan.root, "rev-parse", "--verify", "HEAD^{commit}"])
  if local.code != 0 or local.output.strip().len == 0:
    result.diagnostic = "cannot observe lock backend HEAD"
    return
  let localOid = local.output.strip().toLowerAscii()
  let localInRemote = gitRunPlain(identity,
    ["-C", plan.root, "merge-base", "--is-ancestor", localOid, fetched.oid])
  if localInRemote.code == 0:
    # A fresh operation has not run any member gate yet, so its new expected
    # records legitimately do not exist. At this point we prove the backend is
    # clean, authenticated, and not locally divergent; final completion later
    # proves the exact blobs. Only a local-ahead recovery state is required to
    # contain this operation's expected records during preflight.
    result.ok = true
    return
  let remoteInLocal = gitRunPlain(identity,
    ["-C", plan.root, "merge-base", "--is-ancestor", fetched.oid, localOid])
  if remoteInLocal.code != 0:
    result.diagnostic = "lock backend is divergent from " &
      upstream.target.display & "; refusing before source publication"
    return
  let prefix = verifiedExpectedPrefixAt(identity, plan, localOid)
  if not prefix.ok:
    result.diagnostic = "unverified lock backend ahead chain: " &
      prefix.diagnostic
    return
  let ahead = verifyLockOnlyAheadChain(identity, plan.root, fetched.oid,
    localOid, plan.expected, requireAllExpected = false,
    # A partial recovery is operation-scoped and must contain only its verified
    # prefix. A fully materialized routed operation can legitimately include
    # earlier canonical refresh records for the same backend (its post-commit
    # hooks write one immutable record per observed source generation).
    rejectUnexpected = prefix.records.len < plan.expected.len,
    restrictToExpectedCoordinates = true)
  if not ahead.ok:
    result.diagnostic = "unverified lock backend ahead chain: " &
      ahead.diagnostic
    return
  let proof = verifyExpectedRecordCoordinatesAt(identity, plan.root, localOid,
    prefix.records)
  if not proof.ok:
    result.diagnostic = proof.diagnostic
    return
  result.ok = true
  result.verifiedLocalHead = localOid

proc executePush(args: PushArgs): PushReport =
  result.workspaceRoot = args.workspaceRoot
  result.syncMode =
    case args.syncMode
    of psmNone: "none"
    of psmMerge: "merge"
    of psmRebase: "rebase"

  # Resolve the workspace project / compose layers via the SAME dispatch the
  # gate uses, so push and the gate agree on the participating repo set.
  let (resolved, workspaceLocal) = resolveCheckProject(CheckArgs(
    mode: cmPrePush,
    workspaceRoot: args.workspaceRoot,
    currentRepo: args.currentRepo,
    toolProvisioning: args.toolProvisioning))
  result.project = resolved.projectName

  let identity = ensureGitToolResolvable(
    args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # Determine the pushed repo NAME that seeds the closure.
  #   - ``repro push <project>``: the named project's TRUNK repo (the repo
  #     whose name matches the project), else every repo (whole-project
  #     closure) when no single repo carries the project name.
  #   - ``repro push`` (no arg): the repo at ``--current-repo``/cwd.
  var pushedRepoName = ""
  if args.projectName.len > 0:
    for repo in resolved.repos:
      if repo.name == args.projectName:
        pushedRepoName = repo.name
        break
  else:
    let abs = absolutePath(args.currentRepo)
    for repo in resolved.repos:
      if sameFilesystemPath(args.workspaceRoot / repo.path, abs):
        pushedRepoName = repo.name
        break

  var closure: HashSet[string]
  if pushedRepoName.len > 0:
    closure = developSetClosure(resolved.repos, pushedRepoName)
  else:
    # No single trunk repo resolves (a ``repro push <project>`` whose project
    # name is not also a repo name, or a cwd outside any declared repo): the
    # closure is the whole resolved set, so the push is the project's full
    # publication. This mirrors the gate's whole-workspace fallback.
    for repo in resolved.repos:
      closure.incl(repo.name)
  for repo in resolved.repos:
    if repo.name in closure:
      result.closure.add(repo.name)

  # Topological (dependency-first) push order over ``depends``.
  result.order = topoSortClosure(resolved.repos, closure)

  var byName = initTable[string, ResolvedRepo]()
  for repo in resolved.repos:
    byName[repo.name] = repo

  let manifestLayerRoot = pickManifestLayerRoot(WorkspaceLockArgs(
    workspaceRoot: args.workspaceRoot,
    toolProvisioning: args.toolProvisioning), workspaceLocal)

  # TC-2: carry the certificate notes ref of a closure member to its upstream.
  # Runs whether the member was just PUSHED or was already-published (a
  # developer may issue + attach a certificate for an already-published commit
  # and run ``repro push`` purely to ship the attestation). Best-effort: a
  # note-push failure is reported but never fails the branch publication.
  proc carryCertNotes(report: var PushReport;
                      gitBin, repoAbs, repoPath, remoteName: string) =
    let notePush = pushCertificateNotes(gitBin, repoAbs, remoteName)
    if notePush.pushed:
      report.certNotesPushed.add(repoPath)
    elif not notePush.ok:
      if report.certNotesDiagnostic.len > 0:
        report.certNotesDiagnostic.add("; ")
      report.certNotesDiagnostic.add(repoPath & ": " & notePush.diagnostic)

  # ---- 1. complete read-only preflight -----------------------------------
  # Predictable checkout, hook, cleanliness, and divergence failures are
  # collected against the whole closure up front. This prevents a dirty or
  # partially-upgraded later member from being discovered only after an
  # earlier dependency was irreversibly published. Even ``--sync`` performs
  # this entire source-read-only and backend preflight before its first
  # authorized fetch changes a source common directory.
  var preflight = initTable[string, PushPreflightRepo]()
  for name in result.order:
    let observed = preflightPushRepo(identity, args.workspaceRoot, byName[name],
      allowSyncDivergence = args.syncMode != psmNone)
    if not observed.ok:
      result.repos.add(PushRepoResult(
        name: byName[name].name, path: byName[name].path,
        branch: observed.observed.branch,
        headSha: observed.observed.headSha,
        outcome: proFailed, diagnostic: observed.diagnostic,
        remediation: observed.remediation))
      result.stoppedRepo = byName[name].name
      result.stoppedStage = observed.stage
      result.retryCommand =
        if observed.stage == "hook-preflight": observed.remediation
        else: "repro push --sync --rebase"
      result.exitCode = 2
      return
    preflight[name] = observed.observed
  var backendPlans: seq[PushLockBackendPlan]
  try:
    backendPlans = pushLockBackendPlans(identity, args.workspaceRoot, resolved,
      result.order, preflight, manifestLayerRoot)
  except CatchableError as err:
    result.stoppedRepo = result.project
    result.stoppedStage = "lock-backend-plan-preflight"
    result.lockDiagnostic = err.msg
    result.retryCommand = "fix locking routes and retry 'repro push'"
    result.exitCode = 2
    return
  for plan in backendPlans:
    let backend = preflightLockBackendPlan(identity, plan)
    if not backend.ok:
      let diagnostic = lockingTierLabel(plan.tier) & " " &
        plan.backendKind & " backend at " & plan.root & ": " &
        backend.diagnostic
      if not tierIsShared(plan.tier):
        if result.lockDiagnostic.len > 0: result.lockDiagnostic.add("; ")
        result.lockDiagnostic.add("warning: " & diagnostic)
        continue
      result.stoppedRepo = plan.root
      result.stoppedStage = "lock-backend-preflight"
      result.lockDiagnostic = diagnostic
      result.retryCommand =
        if "hook" in backend.diagnostic.toLowerAscii():
          getAppFilename() & " hooks ensure --vcs " & plan.root
        else:
          "repair the lock backend and retry 'repro push --sync --rebase'"
      result.exitCode = 2
      return
    if backend.verifiedLocalHead.len > 0:
      if result.verifiedLocalBackendHead.len > 0:
        result.verifiedLocalBackendHead.add(", ")
      result.verifiedLocalBackendHead.add(plan.root & "@" &
        backend.verifiedLocalHead)

  # ---- 2. optional source mutation, only after complete preflight --------
  # A sync is explicitly authorized to fetch/integrate source state. Recheck
  # the exact source and advertisement immediately before each mutation, then
  # refresh the complete exact source/backend plan before any source ref is
  # transmitted. A URL or advertisement race is a refusal, not a silent
  # reinterpretation of the operation.
  if args.syncMode != psmNone:
    let beforeSync = preflight
    for name in result.order:
      let stable = revalidatePushRepo(identity, args.workspaceRoot,
        byName[name], beforeSync[name])
      if not stable.ok:
        result.repos.add(PushRepoResult(
          name: byName[name].name, path: byName[name].path,
          branch: beforeSync[name].branch,
          headSha: beforeSync[name].headSha,
          outcome: proFailed, diagnostic: stable.diagnostic,
          remediation: stable.remediation))
        result.stoppedRepo = byName[name].name
        result.stoppedStage = "source-revalidation"
        result.retryCommand = "repro push --sync --rebase"
        result.exitCode = 2
        return
      let sr = reconcileMemberForPush(
        identity, args.workspaceRoot, byName[name], args.syncMode)
      result.syncResults.add(sr)
      if sr.stopped:
        result.stoppedRepo = sr.name
        result.stoppedStage = "sync"
        result.retryCommand = "repro push --sync --rebase"
        result.exitCode = 2
        return

    var refreshed = initTable[string, PushPreflightRepo]()
    for name in result.order:
      let observed = preflightPushRepo(identity, args.workspaceRoot,
        byName[name])
      if not observed.ok:
        result.repos.add(PushRepoResult(
          name: byName[name].name, path: byName[name].path,
          branch: observed.observed.branch,
          headSha: observed.observed.headSha,
          outcome: proFailed, diagnostic: observed.diagnostic,
          remediation: observed.remediation))
        result.stoppedRepo = byName[name].name
        result.stoppedStage = observed.stage
        result.retryCommand = "repro push --sync --rebase"
        result.exitCode = 2
        return
      if observed.observed.remoteLocationFingerprint !=
          beforeSync[name].remoteLocationFingerprint or
          observed.observed.advertisementFingerprint !=
            beforeSync[name].advertisementFingerprint:
        result.repos.add(PushRepoResult(
          name: byName[name].name, path: byName[name].path,
          branch: observed.observed.branch,
          headSha: observed.observed.headSha,
          outcome: proFailed,
          diagnostic: "exact destination advertisement changed during sync " &
            "in " & byName[name].path,
          remediation: "review the destination and retry " &
            "'repro push --sync --rebase'"))
        result.stoppedRepo = byName[name].name
        result.stoppedStage = "source-revalidation"
        result.retryCommand = "repro push --sync --rebase"
        result.exitCode = 2
        return
      refreshed[name] = observed.observed
    preflight = refreshed

    try:
      backendPlans = pushLockBackendPlans(identity, args.workspaceRoot,
        resolved, result.order, preflight, manifestLayerRoot)
    except CatchableError as err:
      result.stoppedRepo = result.project
      result.stoppedStage = "lock-backend-plan-preflight"
      result.lockDiagnostic = err.msg
      result.retryCommand = "fix locking routes and retry 'repro push'"
      result.exitCode = 2
      return
    for plan in backendPlans:
      let backend = preflightLockBackendPlan(identity, plan)
      if not backend.ok:
        let diagnostic = lockingTierLabel(plan.tier) & " " &
          plan.backendKind & " backend at " & plan.root & ": " &
          backend.diagnostic
        if not tierIsShared(plan.tier):
          if result.lockDiagnostic.len > 0: result.lockDiagnostic.add("; ")
          result.lockDiagnostic.add("warning: " & diagnostic)
          continue
        result.stoppedRepo = plan.root
        result.stoppedStage = "lock-backend-preflight"
        result.lockDiagnostic = diagnostic
        result.retryCommand =
          if "hook" in backend.diagnostic.toLowerAscii():
            getAppFilename() & " hooks ensure --vcs " & plan.root
          else:
            "repair the lock backend and retry " &
              "'repro push --sync --rebase'"
        result.exitCode = 2
        return

  # ---- 3. closure push in topological order ------------------------------
  # Walk dependency-first. A dirty/divergent member STOPS the push with an
  # actionable {offender, remedy} diagnostic (never silently discarded). A
  # member with unpublished commits is pushed; an already-published member
  # is a benign noop.
  for name in result.order:
    let repo = byName[name]
    let repoAbs = args.workspaceRoot / repo.path
    let observed = preflight[name]
    var entry = PushRepoResult(name: repo.name, path: repo.path,
      branch: observed.branch, headSha: observed.headSha)
    # Published? (reuses the gate's publication probe.) Already-published is a
    # benign noop; unpublished commits get pushed.
    let rName = observed.remoteName
    let current = revalidatePushRepo(identity, args.workspaceRoot, repo,
      observed)
    if not current.ok:
      entry.outcome = proFailed
      entry.diagnostic = current.diagnostic
      entry.remediation = current.remediation
      result.repos.add(entry)
      result.stoppedRepo = repo.name
      result.stoppedStage = "source-revalidation"
      result.retryCommand = "repro push --sync --rebase"
      result.exitCode = 2
      return
    if observed.published:
      entry.outcome = proAlreadyPublished
      result.repos.add(entry)
      # TC-2: ship any attached certificates even though the commit is already
      # published (the cert may have been issued/attached after the push).
      carryCertNotes(result, identity.binaryPath, repoAbs, repo.path, rName)
      continue
    if entry.branch.len == 0:
      # Unpublished work on a detached HEAD: we have no branch to push. STOP
      # with a remedy rather than guessing a refspec.
      entry.outcome = proSkippedDirty
      entry.diagnostic = "HEAD " & entry.headSha &
        " is unpublished but the checkout is on a detached HEAD"
      entry.remediation = "attach " & repo.path &
        " to a branch (git -C " & repo.path &
        " switch -c <branch>) then re-run 'repro push'"
      result.repos.add(entry)
      result.exitCode = 2
      return
    let pushRes = gitRunPlainEnv(identity,
      ["-C", repoAbs, "push", rName, "HEAD:" & entry.branch])
    if pushRes.code != 0:
      entry.outcome = proFailed
      entry.diagnostic = "git push " & rName & " HEAD:" & entry.branch &
        " failed in " & repo.path &
        "; transport output was withheld because remotes may contain credentials"
      entry.remediation = "resolve the push failure in " & repo.path &
        " (fetch + reconcile, then re-run 'repro push --sync')"
      result.repos.add(entry)
      result.stoppedRepo = repo.name
      result.stoppedStage = "source-push"
      var producedRepos = initHashSet[string]()
      for prior in result.repos:
        if prior.headSha.len > 0:
          producedRepos.incl(prior.name)
      var localHeads: seq[string]
      for plan in backendPlans:
        let expected = plan.expectedPaths(producedRepos)
        let localHead = observeVerifiedLocalOnlyLockHead(identity, plan.root,
          expected)
        if localHead.len > 0:
          localHeads.add(plan.root & "@" & localHead)
      result.verifiedLocalBackendHead = localHeads.join(", ")
      result.retryCommand = "repro push --sync --rebase"
      result.exitCode = 1
      return
    entry.outcome = proPushed
    result.repos.add(entry)
    # TC-2: carry any certificates attached to the just-pushed commits to the
    # SAME upstream by pushing the certificate notes ref alongside the branch.
    # Notes are not pushed by default, so this is the explicit step that makes
    # the attestations travel.
    carryCertNotes(result, identity.binaryPath, repoAbs, repo.path, rName)

  # ---- 4. certificate slot (FLAG only; obtain+attach deferred to TC) -----
  runPushCertifyStub(result, args.certify)

  # ---- 5. final lock completion (verify/recover only; never write) -------
  # Each real source pre-push gate has already created and published the record
  # anchored by that member's exact preflight HEAD. The command now proves
  # those exact records remotely reachable. It may resume a verified local-only
  # lock chain, but it must never manufacture a second speculative lock after
  # source refs have landed.
  result.lockPublished = backendPlans.len > 0
  if backendPlans.len == 0:
    result.lockDiagnostic = "no durable Git lock backend requires verification"
  for plan in backendPlans:
    let expectedLocks = plan.allExpectedRecords()
    let pub = completeExpectedLockPublication(identity, plan.root, expectedLocks)
    case pub.outcome
    of lpoPublished, lpoNothingToPublish:
      if result.lockDiagnostic.len > 0: result.lockDiagnostic.add("; ")
      result.lockDiagnostic.add(lockingTierLabel(plan.tier) & " " &
        plan.backendKind & " backend " &
        (if pub.outcome == lpoPublished: "published: "
          else: "already current: ") & pub.diagnostic)
    of lpoNotPublishable, lpoRefusedDirty, lpoFailed:
      let diag = lockingTierLabel(plan.tier) & " " & plan.backendKind &
        " backend at " & plan.root & " is not remotely proven: " &
        pub.diagnostic
      if result.lockDiagnostic.len > 0: result.lockDiagnostic.add("; ")
      result.lockDiagnostic.add(diag)
      if pub.verifiedLocalHead.len > 0:
        if result.verifiedLocalBackendHead.len > 0:
          result.verifiedLocalBackendHead.add(", ")
        result.verifiedLocalBackendHead.add(plan.root & "@" &
          pub.verifiedLocalHead)
      result.lockPublished = false
      if not tierIsShared(plan.tier):
        # Existing tier policy: personal publication is warned but does not
        # retroactively fail source publication.
        continue
      result.lockPublished = false
      result.stoppedRepo = plan.root
      result.stoppedStage = "final-lock-verification"
      var missingRepo = ""
      for item in plan.expected:
        let local = gitRunPlain(identity,
          ["-C", plan.root, "ls-tree", "HEAD", "--", item.relPath])
        if local.code != 0 or local.output.strip().len == 0:
          missingRepo = item.repoName
          break
      if missingRepo.len > 0:
        result.retryCommand = "repro workspace lock " & result.project &
          " --trigger-repo=" & missingRepo & " && repro push --sync --rebase"
        result.lockDiagnostic.add("; expected record was never created; run '" &
          result.retryCommand & "'")
      else:
        result.retryCommand = "repro push --sync --rebase"
      result.exitCode = 2
      return

proc renderPushTextLines(report: PushReport): seq[string] =
  ## Per-repo outcomes + topological order + lock/cert summary, in the
  ## communicate-before-execute style (Interactive-UX-And-Progress.md).
  result.add("repro push: closure " & report.closure.join(", ") &
    " (push order: " & report.order.join(" → ") & ")")
  if report.syncMode != "none":
    for sr in report.syncResults:
      var line = "repro push: sync " & sr.path & " action=" & sr.action
      if sr.stopped:
        line.add(" → STOPPED (" & sr.diagnostic & ")")
      elif sr.integrated:
        line.add(" → integrated upstream")
      result.add(line)
      if sr.stopped and sr.remediation.len > 0:
        result.add("    remedy: " & sr.remediation)
  for entry in report.repos:
    let tag =
      case entry.outcome
      of proPushed: "pushed"
      of proAlreadyPublished: "already-published"
      of proSkippedDirty: "skipped-dirty"
      of proFailed: "failed"
    var line = "repro push: " & entry.path & " (" & entry.name & ") → " & tag
    if entry.diagnostic.len > 0:
      line.add(" — " & entry.diagnostic)
    result.add(line)
    if entry.remediation.len > 0:
      result.add("    remedy: " & entry.remediation)
  if report.certifyDeferred:
    result.add("repro push: certification deferred to the " &
      "test-certificate campaign (not wired yet)")
  if report.certNotesPushed.len > 0:
    result.add("repro push: carried certificate notes " &
      "(refs/notes/reprobuild/certificates) for " &
      report.certNotesPushed.join(", "))
  if report.certNotesDiagnostic.len > 0:
    result.add("repro push: certificate-notes carry warning — " &
      report.certNotesDiagnostic)
  if report.lockDiagnostic.len > 0:
    result.add("repro push: " & report.lockDiagnostic)
  if report.stoppedStage.len > 0:
    result.add("repro push: stopped repo=" & report.stoppedRepo &
      " stage=" & report.stoppedStage)
  if report.verifiedLocalBackendHead.len > 0:
    result.add("repro push: verified local-only lock backend HEAD " &
      report.verifiedLocalBackendHead)
  if report.retryCommand.len > 0:
    result.add("repro push: retry: " & report.retryCommand)

proc toJsonNode(report: PushReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["closure"] = %report.closure
  result["order"] = %report.order
  result["syncMode"] = %report.syncMode
  var syncs = newJArray()
  for sr in report.syncResults:
    var o = newJObject()
    o["name"] = %sr.name
    o["path"] = %sr.path
    o["action"] = %sr.action
    o["integrated"] = %sr.integrated
    o["stopped"] = %sr.stopped
    o["diagnostic"] = %sr.diagnostic
    o["remediation"] = %sr.remediation
    syncs.add(o)
  result["syncResults"] = syncs
  var repos = newJArray()
  for entry in report.repos:
    var o = newJObject()
    o["name"] = %entry.name
    o["path"] = %entry.path
    o["branch"] = %entry.branch
    o["headSha"] = %entry.headSha
    o["outcome"] = %(
      case entry.outcome
      of proPushed: "pushed"
      of proAlreadyPublished: "already-published"
      of proSkippedDirty: "skipped-dirty"
      of proFailed: "failed")
    o["diagnostic"] = %entry.diagnostic
    o["remediation"] = %entry.remediation
    repos.add(o)
  result["repos"] = repos
  result["certifyDeferred"] = %report.certifyDeferred
  result["certNotesPushed"] = %report.certNotesPushed
  result["certNotesDiagnostic"] = %report.certNotesDiagnostic
  result["lockPublished"] = %report.lockPublished
  result["lockDiagnostic"] = %report.lockDiagnostic
  result["stoppedRepo"] = %report.stoppedRepo
  result["stoppedStage"] = %report.stoppedStage
  result["verifiedLocalBackendHead"] = %report.verifiedLocalBackendHead
  result["retryCommand"] = %report.retryCommand
  result["exitCode"] = %report.exitCode

proc writePushReport(report: PushReport; destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2))

proc runPushCommand*(args: openArray[string]): int =
  ## ``repro push [<project>] [--sync] [--merge|--rebase]
  ## [--certify|--no-certify]`` per CLI/push.md.
  ##
  ## Exit codes:
  ##   - 0 — the closure was published (in dependency order) and the lock
  ##         was published (or there was no publication boundary).
  ##   - 2 — a closure member is dirty/divergent, a ``--sync`` reconcile
  ##         needs human judgment, or the lock publication failed (loud).
  ##   - 1 — a ``git push`` of a closure member failed, or the lock writer
  ##         errored.
  let parsed =
    try:
      parsePushArgs(args)
    except ValueError as err:
      stderr.writeLine("repro push: " & err.msg)
      return 1
  if not isInitializedWorkspace(parsed.workspaceRoot):
    stderr.writeLine("repro push: not a workspace (no resolved manifest " &
      "checkout at " & parsed.workspaceRoot & ")")
    return 1
  var report: PushReport
  try:
    report = executePush(parsed)
  except CatchableError as err:
    stderr.writeLine("repro push: error: " & err.msg)
    return 1
  writePushReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "push"))
  stageFailureReport(parsed.report, report.workspaceRoot, "push",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderPushTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# ---- M12: `repro workspace status / list / manifests` ---------------------
#
# Three read-only introspection commands per
# ``reprobuild-specs/CLI/workspace.md``:
#
#   * ``status``    — consumes the M4 evidence schema. Walks every repo
#                     the resolver (or M8 composer) declares, gathers a
#                     fresh ``WorkspaceVcsEvidence`` triple (head-sha,
#                     is-clean, is-published), and compares each live
#                     HEAD against the most-recently-locked SHA from the
#                     latest lock resolved via Git history over the
#                     per-repo lock subtree (RA-1; no index). Emits a
#                     workspace-level header (project, active branch,
#                     manifest-layer drift flag) plus a per-repo body.
#
#   * ``list``      — walks the M6 resolver result and prints the
#                     declared (name, path, remote, revision) tuples
#                     plus M8 layer provenance / visibility tags. No
#                     live VCS queries: this is purely "what does the
#                     manifest say my workspace should contain".
#
#   * ``manifests`` — enumerates the M8 layer set declared in
#                     ``.repo/workspace.toml``: per-layer URL or
#                     local_path, visibility tier, the layer's on-disk
#                     checkout path, and the list of composed repos
#                     each layer ultimately contributed to. When no
#                     workspace.toml is present, prints a single
#                     "no layered workspace" line and exits 0.
#
# All three follow the M9/M10/M11 convention: parse argv, build a
# typed report, render text lines, write the JSON artifact at
# ``<workspaceRoot>/.repro/workspace/<command>-report.json``. Exit
# codes are 0 on success and 1 on IO / resolve failure; there is no
# refuse-and-report branch (these are read-only commands).
#
# ``--json`` mode: when set, suppress the text rendering and print
# only the JSON report to stdout (in addition to writing it under
# ``.repro/workspace/``). Convenient for scripts that want a single
# parseable payload without the human-readable noise.

# ---- M12 shared visibility-tag helper -------------------------------------

proc visibilityTag(visibility: WorkspaceVisibility): string =
  ## Stable string tag for a ``WorkspaceVisibility`` value, used by
  ## both ``list`` and ``manifests`` for their JSON shape and text
  ## rendering. Mirrors the strings the workspace.toml schema accepts
  ## (with "personal" as the canonical name for the per-developer
  ## tier; "private" is treated as a synonym in compose.nim).
  case visibility
  of wvPublic: "public"
  of wvOrg: "org"
  of wvTeam: "team"
  of wvPersonal: "personal"

# ---- M12.A: `repro workspace status` --------------------------------------

type
  WorkspaceStatusRepoEntry* = object
    ## One per declared repo in the live workspace. ``lockState`` is
    ## the three-valued comparison vs the most-recently-locked SHA:
    ## ``at-lock`` / ``drifted-from-lock`` / ``no-lock-recorded``.
    ## ``checkoutState`` is one of ``missing`` / ``dirty`` / ``clean``
    ## and is derived from the M4 evidence ``isClean`` field plus a
    ## directory-existence pre-check.
    name*: string
    path*: string
    branch*: string
    headSha*: string
    isClean*: bool
    isPublished*: bool
    diagnostic*: string
    expectedRevision*: string
    checkoutState*: string
    lockedRevision*: string
    lockState*: string
    manifestLayer*: string
    stashCount*: int
    aheadCount*: int
    behindCount*: int
    untrackedCount*: int
    modifiedCount*: int
    unmergedBranches*: seq[string]
    fileDetails*: seq[FileStatusEntry]

  WorkspaceStatusManifestEntry* = object
    ## One per refreshed manifest layer (M10's ``refreshManifestLayers``
    ## output). M12 mirrors the M10 sync report's shape so the JSON
    ## stays uniform.
    index*: int
    provenance*: string
    layerPath*: string
    status*: string
    beforeSha*: string
    afterSha*: string
    diagnostic*: string

  WorkspaceStatusReport* = object
    ## Structured outcome of one ``repro workspace status`` invocation.
    ## ``activeBranch`` is the workspace's advisory branch — see the
    ## comment on ``deriveActiveBranch`` for the heuristic M12 uses
    ## (M13 will replace this with a metadata-backed value).
    project*: string
    workspaceRoot*: string
    activeBranch*: string
    manifestLayerRoot*: string
    lockIndexPath*: string
    hasLockIndex*: bool
    manifestLayers*: seq[WorkspaceStatusManifestEntry]
    repos*: seq[WorkspaceStatusRepoEntry]
    summary*: tuple[clean, dirty, missing, drifted, atLock,
      noLockRecorded: int]
    exitCode*: int

proc toJsonNode*(report: WorkspaceStatusReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["activeBranch"] = %report.activeBranch
  result["manifestLayerRoot"] = %report.manifestLayerRoot
  result["lockIndexPath"] = %report.lockIndexPath
  result["hasLockIndex"] = %report.hasLockIndex
  var layers = newJArray()
  for entry in report.manifestLayers:
    var obj = newJObject()
    obj["index"] = %entry.index
    obj["provenance"] = %entry.provenance
    obj["layerPath"] = %entry.layerPath
    obj["status"] = %entry.status
    obj["beforeSha"] = %entry.beforeSha
    obj["afterSha"] = %entry.afterSha
    obj["diagnostic"] = %entry.diagnostic
    layers.add(obj)
  result["manifestLayers"] = layers
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["branch"] = %entry.branch
    obj["headSha"] = %entry.headSha
    obj["isClean"] = %entry.isClean
    obj["isPublished"] = %entry.isPublished
    obj["diagnostic"] = %entry.diagnostic
    obj["expectedRevision"] = %entry.expectedRevision
    obj["checkoutState"] = %entry.checkoutState
    obj["lockedRevision"] = %entry.lockedRevision
    obj["lockState"] = %entry.lockState
    obj["manifestLayer"] = %entry.manifestLayer
    obj["stashCount"] = %entry.stashCount
    obj["aheadCount"] = %entry.aheadCount
    obj["behindCount"] = %entry.behindCount
    obj["untrackedCount"] = %entry.untrackedCount
    obj["modifiedCount"] = %entry.modifiedCount
    var unmerged = newJArray()
    for b in entry.unmergedBranches: unmerged.add(%b)
    obj["unmergedBranches"] = unmerged
    var details = newJArray()
    for fd in entry.fileDetails:
      var fdObj = newJObject()
      fdObj["code"] = %fd.code
      fdObj["path"] = %fd.path
      details.add(fdObj)
    obj["fileDetails"] = details
    repos.add(obj)
  result["repos"] = repos
  var summary = newJObject()
  summary["clean"] = %report.summary.clean
  summary["dirty"] = %report.summary.dirty
  summary["missing"] = %report.summary.missing
  summary["drifted"] = %report.summary.drifted
  summary["atLock"] = %report.summary.atLock
  summary["noLockRecorded"] = %report.summary.noLockRecorded
  result["summary"] = summary
  result["exitCode"] = %report.exitCode

proc renderStatusTextLines*(report: WorkspaceStatusReport): seq[string] =
  result.add("workspace status: project=" & report.project &
    " branch=" & (if report.activeBranch.len > 0:
                    report.activeBranch
                  else: "<none>"))
  if report.hasLockIndex:
    result.add("workspace status: latest-lock=" & report.lockIndexPath)
  else:
    result.add("workspace status: no lock recorded")
  for entry in report.manifestLayers:
    result.add("workspace status: manifest-layer " & entry.provenance &
      " status=" & entry.status)
  for entry in report.repos:
    var line = "workspace status: " & entry.path & " " &
      entry.checkoutState
    if entry.branch.len > 0:
      line.add(" branch=" & entry.branch)
    if entry.headSha.len > 0:
      line.add(" head=" & entry.headSha[0 ..< min(8, entry.headSha.len)])
    line.add(" lock=" & entry.lockState)
    if entry.modifiedCount > 0 or entry.untrackedCount > 0:
      line.add(" modified=" & $entry.modifiedCount & " untracked=" & $entry.untrackedCount)
    if entry.stashCount > 0:
      line.add(" stashes=" & $entry.stashCount)
    if entry.aheadCount > 0 or entry.behindCount > 0:
      line.add(" ahead=" & $entry.aheadCount & " behind=" & $entry.behindCount)
    if entry.unmergedBranches.len > 0:
      line.add(" unmerged=" & entry.unmergedBranches.join(","))
    if entry.diagnostic.len > 0:
      line.add(" (" & entry.diagnostic & ")")
    result.add(line)
    # `--file-details`: one indented line per changed path, carrying the raw
    # porcelain `XY` code (staged/unstaged/conflict), like `repo status`.
    for fd in entry.fileDetails:
      result.add("workspace status:     " & fd.code & " " & fd.path)
  result.add("workspace status: summary clean=" & $report.summary.clean &
    " dirty=" & $report.summary.dirty &
    " missing=" & $report.summary.missing &
    " drifted=" & $report.summary.drifted &
    " atLock=" & $report.summary.atLock &
    " noLockRecorded=" & $report.summary.noLockRecorded)

type
  WorkspaceStatusArgs = object
    workspaceRoot: string
    projectName: string
    json: bool
    toolProvisioning: ToolProvisioningMode
    stashes: bool
    files: bool
    aheadBehind: bool
    unmerged: bool
    fileDetails: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseWorkspaceStatusArgs(args: openArray[string]): WorkspaceStatusArgs =
  ## ``repro workspace status`` argv parser. The single optional
  ## positional is the project name (only required when no
  ## ``.repro/workspace.toml`` is present — same dispatch rule as
  ## M10's sync and M11's lock commands). Optional flags:
  ##   ``--workspace-root=PATH``
  ##   ``--tool-provisioning=path|nix|tarball|scoop``
  ##   ``--json``  — print the JSON report to stdout in place of text.
  ##   ``--stashes`` — query/display stash count.
  ##   ``--files`` — query/display modified/untracked file counts and clean/dirty states.
  ##   ``--ahead-behind`` — query/display ahead/behind commit counts.
  ##   ``--unmerged`` — query/display unmerged branches.
  ##   ``--file-details`` — list each changed path with its porcelain ``XY``
  ##     status (staged/unstaged etc.), not just the modified/untracked counts.
  ##     An additive opt-in: it does NOT participate in the "no selector → all
  ##     on" default, so `status --file-details` augments the full default
  ##     output rather than narrowing it. Implies file querying.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--json":
      result.json = true
    elif arg == "--stashes":
      result.stashes = true
    elif arg == "--files":
      result.files = true
    elif arg == "--ahead-behind":
      result.aheadBehind = true
    elif arg == "--unmerged":
      result.unmerged = true
    elif arg == "--file-details":
      result.fileDetails = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace status` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace status`: " &
          arg)
    inc i
  if not (result.stashes or result.files or result.aheadBehind or result.unmerged):
    result.stashes = true
    result.files = true
    result.aheadBehind = true
    result.unmerged = true
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveWorkspaceStatusProject(parsed: WorkspaceStatusArgs):
    tuple[resolved: ResolvedProject;
          workspaceLocal: Option[WorkspaceLocal]] =
  ## MO-10 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder
  ## (collapsed from the former per-command copy). Same dispatch rule as M10 /
  ## M11: prefer ``.repo/workspace.toml`` when it declares at least one
  ## ``[[manifest]]`` layer (composer mode), otherwise look up the named
  ## project / variant. A metadata-only workspace.toml (M13) routes to
  ## single-project mode; a committed-lock-only workspace (no manifest data on
  ## disk) now resolves its participating set through the unified
  ## committed-lock source instead of raising — every manifest-present path is
  ## byte-unchanged.
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro workspace status`")

proc pickStatusManifestLayerRoot(workspaceRoot: string;
    workspaceLocal: Option[WorkspaceLocal]): string =
  ## Resolve the manifest-layer root that OWNS the lock subtree for
  ## status's drift comparison. Mirrors M11's ``pickManifestLayerRoot``
  ## but without the ``--manifest-layer-root`` override (status is
  ## read-only and uses the same anchor M11 wrote to).
  if workspaceLocal.isSome:
    let local = workspaceLocal.get()
    if local.manifest.len > 0:
      let first = local.manifest[0]
      if first.local_path.isSome and first.local_path.get().len > 0:
        let raw = first.local_path.get()
        if isAbsolute(raw):
          return raw
        return workspaceRoot / raw
      if first.url.isSome and first.url.get().len > 0:
        # Mirror the composer's directory-naming convention so the
        # status reader finds the lock written by the M11 dispatcher
        # at the same on-disk path.
        let sanitizedSegments = block:
          var raw1 = ""
          for ch in first.url.get():
            case ch
            of 'A'..'Z', 'a'..'z', '0'..'9', '-', '.', '_': raw1.add(ch)
            else: raw1.add('-')
          var collapsed = ""
          var prevDash = false
          for ch in raw1:
            if ch == '-':
              if not prevDash: collapsed.add(ch)
              prevDash = true
            else:
              collapsed.add(ch)
              prevDash = false
          if collapsed.len > 80:
            collapsed.setLen(80)
          collapsed.strip(chars = {'-'},
            leading = true, trailing = true)
        let suffix =
          if sanitizedSegments.len > 0: sanitizedSegments
          else: "layer"
        return workspaceRoot / ".repro" / ("manifests-0-" & suffix)
  workspaceRoot / ".repro" / "manifests"

proc deriveActiveBranch(workspaceRoot: string;
    workspaceLocal: Option[WorkspaceLocal];
    resolved: ResolvedProject; repos: seq[WorkspaceStatusRepoEntry]): string =
  ## M13 — Workspace-metadata-backed active branch, with the original
  ## M12 heuristic preserved as a fallback for workspaces created
  ## before M13 landed (no recorded ``[workspace].branch``). Precedence:
  ##   1. ``.repo/workspace.toml``'s ``[workspace].branch`` field. M13
  ##      writes this during ``repro workspace init`` (single-project
  ##      mode) and the M8 composer-mode workspaces already carry it
  ##      from the user's own metadata. Reading via
  ##      ``readWorkspaceBranch`` covers BOTH composer- and
  ##      single-project-mode workspaces uniformly, so we no longer
  ##      need a separate composer-mode check before this branch.
  ##   2. The first repo whose live HEAD reports a non-empty branch
  ##      (the original M12 heuristic — typical case: a clean
  ##      workspace where every repo is on the same branch). Used for
  ##      legacy workspaces created before M13 wrote the metadata.
  ##   3. The resolver's ``trunk`` field (the manifest's documented
  ##      default branch, e.g. ``main``). Used when no live repo
  ##      checkout reports a current branch.
  ##   4. Empty string.
  try:
    let recorded = readWorkspaceBranch(workspaceRoot)
    if recorded.isSome:
      return recorded.get()
  except WorkspaceManifestParseError:
    # A malformed workspace.toml: fall back to the M12 heuristic so
    # ``status`` still produces a useful answer. The dispatcher will
    # have already surfaced the structured diagnostic if needed.
    discard
  # Composer-mode workspaces that pre-date M13 and never re-ran init
  # carry their branch directly on the parsed ``WorkspaceLocal`` — the
  # ``readWorkspaceBranch`` path above already covers them, but we
  # leave this defensive check in place for parity with the M12
  # heuristic when the strict reader had to bail out.
  if workspaceLocal.isSome and
      workspaceLocal.get().workspace.branch.isSome and
      workspaceLocal.get().workspace.branch.get().len > 0:
    return workspaceLocal.get().workspace.branch.get()
  # M12 heuristic, tightened: only adopt a live branch as the workspace's
  # active branch when EVERY checked-out repo that reports one agrees on it. A
  # workspace whose repos legitimately sit on different branches (e.g.
  # dev/live/main) has no single active branch, so returning the first repo's
  # branch would misreport it (and disagree with `repro branch`, which reports
  # `<none recorded>`). On divergence, defer to the manifest trunk instead.
  var uniform = ""
  for entry in repos:
    if entry.branch.len == 0: continue
    if uniform.len == 0:
      uniform = entry.branch
    elif uniform != entry.branch:
      uniform = ""
      break
  if uniform.len > 0:
    return uniform
  resolved.trunk

proc executeWorkspaceStatus(args: WorkspaceStatusArgs): WorkspaceStatusReport =
  var report: WorkspaceStatusReport
  report.workspaceRoot = args.workspaceRoot

  let (resolved, workspaceLocal) = resolveWorkspaceStatusProject(args)
  report.project = resolved.projectName

  # Pre-resolution: gather the manifest-layer refresh result the
  # M10 helper exposes. This populates the structured per-layer
  # ``status`` field even when there is no workspace.toml (the helper
  # returns an empty report in that case, which yields no entries).
  # Note: we DO NOT mutate any layer here — the M10 helper only
  # fetches + fast-forwards, which is the read-only behaviour M12's
  # status command needs.
  try:
    let refresh = refreshManifestLayers(args.workspaceRoot)
    for entry in refresh.layers:
      report.manifestLayers.add(WorkspaceStatusManifestEntry(
        index: entry.index,
        provenance: entry.provenance,
        layerPath: entry.layerPath,
        status: manifestLayerStatusTag(entry.status),
        beforeSha: entry.beforeSha,
        afterSha: entry.afterSha,
        diagnostic: entry.diagnostic))
  except CatchableError:
    # A refresh failure is non-fatal for read-only status: leave the
    # manifestLayers slice empty and continue. The per-repo
    # observation pass below still works.
    discard

  let manifestLayerRoot = pickStatusManifestLayerRoot(
    args.workspaceRoot, workspaceLocal)
  report.manifestLayerRoot = manifestLayerRoot

  let identity = ensureGitToolResolvable(
    args.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()
  let toolDigest = digestHex(identity)
  let observedAt = getTime().toUnix * 1000

  # RA-1: locate the latest lock via Git history over the per-repo lock
  # subtree (no shared index). ``hasLockIndex`` now means "a lock was
  # found at all"; ``lockIndexPath`` surfaces the resolved lock file
  # path (empty when none).
  let latestLock = latestLockShasViaGit(
    identity, manifestLayerRoot, resolved.projectName)
  let lockedShas = latestLock.shas
  report.hasLockIndex = latestLock.lockRelPath.len > 0 and lockedShas.len > 0
  report.lockIndexPath =
    if report.hasLockIndex:
      manifestLayerRoot / latestLock.lockRelPath.replace('/', DirSep)
    else: ""

  for repo in resolved.repos:
    let repoAbsPath = args.workspaceRoot / repo.path
    var entry: WorkspaceStatusRepoEntry
    entry.name = repo.name
    entry.path = repo.path
    entry.expectedRevision = repo.revision
    entry.manifestLayer = repo.manifestLayer

    if not dirExists(repoAbsPath / ".git"):
      entry.checkoutState = "missing"
      entry.lockState =
        if repo.path in lockedShas: "missing-but-locked"
        elif report.hasLockIndex: "no-lock-recorded"
        else: "no-lock-recorded"
      inc report.summary.missing
      report.repos.add(entry)
      continue

    let trunkBranch = if resolved.trunk.len > 0: resolved.trunk else: "main"
    # `--file-details` implies file querying (it reads the same porcelain).
    let extQuery = extendedStatusQuery(repoAbsPath, trunkBranch,
      args.stashes, args.files or args.fileDetails, args.aheadBehind,
      args.unmerged, queryFileDetails = args.fileDetails)
    let res = queryGitState(extQuery, identity)

    # Re-create mock results for compatibility with evidence system
    let headRes = GitQueryResult(
      status: res.status,
      headSha: res.headSha,
      diagnostic: res.diagnostic
    )
    let cleanRes = GitQueryResult(
      status: res.status,
      isClean: res.isClean,
      diagnostic: res.diagnostic
    )
    let pubRes = GitQueryResult(
      status: res.status,
      isPublished: res.isPublished,
      diagnostic: res.diagnostic
    )

    let evHeadSha = workspaceVcsEvidence.evidenceFor(
      headRes, repo.path, wvqHeadSha, toolDigest, observedAt)
    let evIsClean = workspaceVcsEvidence.evidenceFor(
      cleanRes, repo.path, wvqIsClean, toolDigest, observedAt)
    let evIsPub = workspaceVcsEvidence.evidenceFor(
      pubRes, repo.path, wvqIsPublished, toolDigest, observedAt)

    entry.headSha = evHeadSha.headSha
    entry.isClean = evIsClean.status == wvesResolved and evIsClean.isClean
    entry.isPublished = evIsPub.status == wvesResolved and evIsPub.isPublished

    entry.stashCount = res.stashCount
    entry.aheadCount = res.aheadCount
    entry.behindCount = res.behindCount
    entry.untrackedCount = res.untrackedCount
    entry.modifiedCount = res.modifiedCount
    entry.unmergedBranches = res.unmergedBranches
    entry.fileDetails = res.fileDetails

    var diagnostic = ""
    if evHeadSha.status == wvesFailed: diagnostic.add(evHeadSha.diagnostic)
    if evIsClean.status == wvesFailed:
      if diagnostic.len > 0: diagnostic.add("; ")
      diagnostic.add(evIsClean.diagnostic)
    if res.diagnostic.len > 0 and res.status == gqsFailed:
      if diagnostic.len > 0: diagnostic.add("; ")
      diagnostic.add(res.diagnostic)
    entry.diagnostic = diagnostic

    let branchRes = gitRunPlain(identity,
      ["-C", repoAbsPath, "symbolic-ref", "--short", "-q", "HEAD"])
    if branchRes.code == 0:
      entry.branch = branchRes.output.strip()

    if not entry.isClean:
      entry.checkoutState = "dirty"
      inc report.summary.dirty
    else:
      entry.checkoutState = "clean"
      inc report.summary.clean

    if not report.hasLockIndex:
      entry.lockState = "no-lock-recorded"
      inc report.summary.noLockRecorded
    elif repo.path notin lockedShas:
      # Index exists but does not name this repo (e.g. the project's
      # repo set has changed since the most recent lock).
      entry.lockState = "no-lock-recorded"
      inc report.summary.noLockRecorded
    else:
      entry.lockedRevision = lockedShas[repo.path]
      if entry.lockedRevision == entry.headSha:
        entry.lockState = "at-lock"
        inc report.summary.atLock
      else:
        entry.lockState = "drifted-from-lock"
        inc report.summary.drifted

    report.repos.add(entry)

  report.activeBranch = deriveActiveBranch(
    args.workspaceRoot, workspaceLocal, resolved, report.repos)
  report.exitCode = 0
  result = report

proc writeWorkspaceStatusReport(report: WorkspaceStatusReport;
                                destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspaceStatusCommand*(args: openArray[string]): int =
  ## ``repro workspace status [<project>] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## Exit codes (per M12 design — read-only command):
  ##   - 0 — status gathered (with whatever drift the live workspace
  ##         exhibits — drift is information, not a failure).
  ##   - 1 — IO failure, missing project, or resolver error.
  let parsed = parseWorkspaceStatusArgs(args)
  let report = executeWorkspaceStatus(parsed)
  writeWorkspaceStatusReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "status"))
  stageFailureReport(parsed.report, report.workspaceRoot, "status",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderStatusTextLines(report):
      stdout.writeLine(line)
    emitLockCoherenceAdvisory(parsed.toolProvisioning, report.workspaceRoot,
      report.project, report.repos)
  report.exitCode

# ---- M12.B: `repro workspace list` ----------------------------------------

type
  WorkspaceListRepoEntry* = object
    ## One per declared repo in the resolved project. Mirrors the
    ## ``ResolvedRepo`` field set the M6 resolver / M8 composer emit
    ## without doing any live-VCS observation.
    name*: string
    path*: string
    remote*: string
    fetchUrl*: string
    revision*: string
    vcs*: string
    stability*: string
    manifestLayer*: string
    visibility*: string
    fragmentPath*: string

  WorkspaceListReport* = object
    ## Structured outcome of one ``repro workspace list`` invocation.
    project*: string
    workspaceRoot*: string
    projectFile*: string
    defaultRevision*: string
    trunk*: string
    repos*: seq[WorkspaceListRepoEntry]
    exitCode*: int

proc toJsonNode*(report: WorkspaceListReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["projectFile"] = %report.projectFile
  result["defaultRevision"] = %report.defaultRevision
  result["trunk"] = %report.trunk
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["remote"] = %entry.remote
    obj["fetchUrl"] = %entry.fetchUrl
    obj["revision"] = %entry.revision
    obj["vcs"] = %entry.vcs
    obj["stability"] = %entry.stability
    obj["manifestLayer"] = %entry.manifestLayer
    obj["visibility"] = %entry.visibility
    obj["fragmentPath"] = %entry.fragmentPath
    repos.add(obj)
  result["repos"] = repos
  result["exitCode"] = %report.exitCode

proc renderListTextLines*(report: WorkspaceListReport): seq[string] =
  result.add("workspace list: project=" & report.project &
    (if report.trunk.len > 0: " trunk=" & report.trunk else: ""))
  for entry in report.repos:
    var line = "workspace list: " & entry.path & " name=" & entry.name &
      " remote=" & entry.remote & " revision=" & entry.revision
    if entry.manifestLayer.len > 0:
      line.add(" layer=" & entry.manifestLayer)
    line.add(" visibility=" & entry.visibility)
    result.add(line)

type
  WorkspaceListArgs = object
    workspaceRoot: string
    projectName: string
    json: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseWorkspaceListArgs(args: openArray[string]): WorkspaceListArgs =
  ## ``repro workspace list`` argv parser. Same dispatch rules as
  ## status — optional positional ``<project>`` for single-project
  ## mode, ``--workspace-root=PATH``, ``--json``. No
  ## ``--tool-provisioning``: list does no live VCS work.
  result.workspaceRoot = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace list` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace list`: " & arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveWorkspaceListProject(parsed: WorkspaceListArgs):
    ResolvedProject =
  ## Same dispatch rule as M9/M10/M11/status: prefer
  ## ``.repo/workspace.toml`` when it declares at least one
  ## ``[[manifest]]`` layer (composer mode), otherwise look up the
  ## named project / variant. A metadata-only workspace.toml (M13)
  ## routes to single-project mode.
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    return extendWithActiveProjectSet(parsed.workspaceRoot,
      composeManifestLayersFromFile(workspaceToml))
  if parsed.projectName.len == 0:
    # Allow a metadata-only workspace.toml to supply the project name. Only the
    # read of workspace.toml is guarded here: if resolving the *named* project
    # fails (e.g. its manifest references an undeclared remote), that error must
    # propagate rather than be masked by the "requires a project" message below.
    var recordedProject = ""
    if fileExists(workspaceToml):
      try:
        recordedProject =
          readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
      except WorkspaceManifestParseError:
        recordedProject = ""
    if recordedProject.len > 0:
      var withProject = parsed
      withProject.projectName = recordedProject
      # PS-2 — no explicit ``<project>``: list what the WORKSPACE consists of,
      # i.e. the union of the active project set (deduplicated by path).
      return extendWithActiveProjectSet(parsed.workspaceRoot,
        resolveWorkspaceListProject(withProject))
    raise newException(ValueError,
      "`repro workspace list` requires either `.repro/workspace.toml` " &
        "or a <project> argument; neither was present at " &
        parsed.workspaceRoot)
  let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
  let projectFile = manifestsRoot / "projects" /
    (parsed.projectName & ".toml")
  let variantFile = manifestsRoot / "variants" /
    (parsed.projectName & ".toml")
  if fileExists(projectFile):
    return resolveProject(projectFile)
  if fileExists(variantFile):
    return resolveVariant(variantFile)
  raise newException(ValueError,
    "no project or variant named '" & parsed.projectName &
      "' found under '" & manifestsRoot &
      "' (looked for '" & projectFile & "' and '" & variantFile & "')")

proc executeWorkspaceList(args: WorkspaceListArgs): WorkspaceListReport =
  var report: WorkspaceListReport
  report.workspaceRoot = args.workspaceRoot
  let resolved = resolveWorkspaceListProject(args)
  report.project = resolved.projectName
  report.projectFile = resolved.projectFile
  report.defaultRevision = resolved.defaultRevision
  report.trunk = resolved.trunk
  for repo in resolved.repos:
    report.repos.add(WorkspaceListRepoEntry(
      name: repo.name,
      path: repo.path,
      remote: repo.projectRemote,
      fetchUrl: repo.fetchUrl,
      revision: repo.revision,
      vcs: repo.vcs,
      stability: repo.stability,
      manifestLayer: repo.manifestLayer,
      visibility: visibilityTag(repo.visibility),
      fragmentPath: repo.fragmentPath))
  report.exitCode = 0
  result = report

proc writeWorkspaceListReport(report: WorkspaceListReport;
                              destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspaceListCommand*(args: openArray[string]): int =
  ## ``repro workspace list [<project>] [--workspace-root=PATH]
  ## [--json]``.
  ##
  ## Exit codes (per M12 design — read-only command):
  ##   - 0 — repo list emitted.
  ##   - 1 — IO failure, missing project, or resolver error.
  let parsed = parseWorkspaceListArgs(args)
  let report = executeWorkspaceList(parsed)
  writeWorkspaceListReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "list"))
  stageFailureReport(parsed.report, report.workspaceRoot, "list",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderListTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# ---- RA-30: `repro health` — environment doctor ---------------------------
#
# One command that diagnoses every layer reprobuild depends on and pairs
# each FAILING check with the EXACT remedy command (Interactive-UX
# Principle 2 — every failure pairs with a remedy). The single source of
# truth is a list of ``HealthCheck`` records; the human table, the
# ``--json`` view, and the ``--fix`` remediation path all consume the
# same list so they can never drift.
#
# ``--fix`` performs ONLY the safe, non-destructive remediations the spec
# authorizes (``direnv allow``, start the user daemon, clone a missing
# develop-mode sibling), announcing each action BEFORE running it
# (communicate-before-execute). Unsafe/ambiguous failures are reported,
# never auto-fixed.

type
  HealthStatus* = enum
    hsOk = "ok"
    hsWarn = "warn"
    hsFail = "fail"

  HealthFixKind* = enum
    ## How (if at all) ``--fix`` may safely remediate a failing check.
    hfNone            ## No safe auto-fix; report the remedy only.
    hfDirenvAllow     ## Run ``direnv allow`` on the workspace ``.envrc``.
    hfStartDaemon     ## Start the per-user store daemon.
    hfCloneSiblings   ## Clone the missing develop-mode siblings.
    hfWorkspaceErgonomics ## Repair workspace-projects.md, gitignore, and AGENTS.md.
    hfEnsureVcsHooks  ## Reinstall the managed VCS hooks in every participating repo.

  HealthCheck* = object
    ## One diagnosed layer. ``remedy`` is the exact command the user (or
    ## an agent) runs to fix a ``warn``/``fail``; it MUST be non-empty for
    ## any non-``ok`` status (Principle 2). ``fixKind`` records whether
    ## ``--fix`` is allowed to perform the remedy automatically.
    name*: string
    status*: HealthStatus
    detail*: string
    remedy*: string
    fixKind*: HealthFixKind

  HealthArgs = object
    workspaceRoot: string
    projectName: string
    json: bool
    fix: bool

  HealthContext = object
    ## Resolved facts the gatherer shares across checks so it only
    ## resolves the project / git identity once.
    workspaceRoot: string
    initialized: bool
    resolved: ResolvedProject
    resolvedOk: bool
    missingSiblings: seq[ResolvedRepo]
    gitIdentity: GitToolIdentity
    gitOk: bool

proc parseHealthArgs(args: openArray[string]): HealthArgs =
  result.workspaceRoot = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--json":
      result.json = true
    elif arg == "--fix":
      result.fix = true
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro health` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro health`: " & arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveHealthProject(parsed: HealthArgs): ResolvedProject =
  ## MO-10 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder
  ## (collapsed from the former per-command copy). Compositional
  ## workspace.toml → composer; otherwise the named project / variant, or the
  ## project recorded in a metadata-only workspace.toml. A committed-lock-only
  ## workspace (no manifest data on disk) now resolves through the unified
  ## committed-lock source instead of raising, so ``repro health`` reports the
  ## same manifest status the lock-handling commands do. Still raises on a
  ## genuinely missing / unresolvable project so the caller can mark the
  ## manifest check ``fail``.
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro health`").resolved

proc reproSelfPath(): string =
  ## Best-effort absolute path to the running ``repro`` binary, used to
  ## render copy-pasteable remedy commands that don't depend on PATH.
  try:
    result = getAppFilename()
  except CatchableError:
    result = ""
  if result.len == 0:
    result = "repro"

proc detectDirenvEnvrcState(workspaceRoot: string):
    tuple[hasEnvrc, trusted: bool] =
  ## Inspect ``<workspaceRoot>/.envrc`` and the direnv allow-list. A
  ## missing ``.envrc`` yields ``(false, false)``. When ``direnv`` is on
  ## PATH we use ``direnv status`` to decide trust; otherwise we fall
  ## back to "present but cannot confirm trust" (``trusted = false``).
  let envrcPath = workspaceRoot / ".envrc"
  result.hasEnvrc = fileExists(envrcPath)
  result.trusted = false
  if not result.hasEnvrc:
    return
  let direnvBin = resolveDirenvBin()
  if direnvBin.len == 0:
    return
  let res = execCmdEx(quoteShell(direnvBin) & " status",
    workingDir = workspaceRoot)
  if res.exitCode == 0:
    # ``direnv status`` prints "Found RC allowed true" when the .envrc is
    # trusted. Be liberal: any "allowed true"/"allowed: true" wins.
    let low = res.output.toLowerAscii()
    result.trusted = ("allowed true" in low) or ("allowed: true" in low)

proc gatherHealthChecks(parsed: HealthArgs):
    tuple[checks: seq[HealthCheck]; ctx: HealthContext] =
  ## Diagnose every layer once and return the ordered check list plus the
  ## resolved context (so ``--fix`` can act without re-resolving).
  var ctx: HealthContext
  ctx.workspaceRoot = parsed.workspaceRoot
  var checks: seq[HealthCheck]
  let self = reproSelfPath()

  # 1. reprobuild install & version. The binary that is running answers
  #    this affirmatively by construction; we still surface the version
  #    so the table is informative.
  checks.add(HealthCheck(
    name: "install-version",
    status: hsOk,
    detail: "repro " & versionString() & " (" & self & ")",
    remedy: "",
    fixKind: hfNone))

  # 2. Daemon / privilege mode. Either the per-user store daemon is
  #    running, or we are on the single-user direct path. Both are
  #    healthy; we report WHICH so a no-sudo user understands the mode.
  block daemonCheck:
    var running = false
    var endpoint = ""
    try:
      let status = queryUserDaemonStatus()
      running = status.running
      endpoint = status.endpoint
    except CatchableError:
      running = false
    if running:
      checks.add(HealthCheck(
        name: "daemon-mode",
        status: hsOk,
        detail: "user store daemon running (" & endpoint & ")",
        remedy: "",
        fixKind: hfNone))
    else:
      # Not running is a WARN, not a hard fail: single-user direct mode
      # is a fully supported path. The remedy starts the daemon for users
      # who want shared coordination; ``--fix`` may safely run it.
      checks.add(HealthCheck(
        name: "daemon-mode",
        status: hsWarn,
        detail: "no user daemon; single-user direct mode",
        remedy: self & " daemon start",
        fixKind: hfStartDaemon))

  # 3. Store health. The content-addressed store root must be present
  #    and readable.
  block storeCheck:
    let storeRoot = resolveStoreRoot("")
    var ok = false
    var detail = ""
    try:
      if dirExists(storeRoot):
        # A readable store: openStore must succeed (it touches the SQLite
        # index). Probe and immediately close.
        var store = openStore(storeRoot)
        store.close()
        ok = true
        detail = "store readable at " & storeRoot
      else:
        detail = "store root absent: " & storeRoot
    except CatchableError as err:
      detail = "store unreadable at " & storeRoot & ": " & err.msg
    if ok:
      checks.add(HealthCheck(
        name: "store", status: hsOk, detail: detail,
        remedy: "", fixKind: hfNone))
    else:
      checks.add(HealthCheck(
        name: "store", status: hsFail, detail: detail,
        remedy: self & " store recover --store-root=" & storeRoot,
        fixKind: hfNone))

  # 4. direnv — installed, and the workspace .envrc is trusted.
  block direnvCheck:
    let direnvBin = resolveDirenvBin()
    let envrc = detectDirenvEnvrcState(parsed.workspaceRoot)
    if direnvBin.len == 0:
      checks.add(HealthCheck(
        name: "direnv",
        status: hsWarn,
        detail: "direnv not found on PATH",
        remedy: self & " hooks ensure --shell-direnv",
        fixKind: hfNone))
    elif not envrc.hasEnvrc:
      checks.add(HealthCheck(
        name: "direnv",
        status: hsWarn,
        detail: "no .envrc in workspace",
        remedy: self & " hooks ensure --shell-direnv",
        fixKind: hfNone))
    elif not envrc.trusted:
      checks.add(HealthCheck(
        name: "direnv",
        status: hsFail,
        detail: ".envrc present but not trusted",
        remedy: "direnv allow " & parsed.workspaceRoot,
        fixKind: hfDirenvAllow))
    else:
      checks.add(HealthCheck(
        name: "direnv",
        status: hsOk,
        detail: ".envrc trusted",
        remedy: "", fixKind: hfNone))

  # 5. Workspace marker (RA-10 ``isInitializedWorkspace``).
  ctx.initialized = isInitializedWorkspace(parsed.workspaceRoot)
  if ctx.initialized:
    checks.add(HealthCheck(
      name: "workspace",
      status: hsOk,
      detail: "initialized workspace at " & parsed.workspaceRoot,
      remedy: "", fixKind: hfNone))
  else:
    checks.add(HealthCheck(
      name: "workspace",
      status: hsFail,
      detail: "no initialized workspace marker at " & parsed.workspaceRoot,
      remedy: self & " workspace init <project>",
      fixKind: hfNone))

  # 6. Manifest resolution + active project set.
  block manifestCheck:
    try:
      ctx.resolved = resolveHealthProject(parsed)
      ctx.resolvedOk = true
      checks.add(HealthCheck(
        name: "manifest",
        status: hsOk,
        detail: "project '" & ctx.resolved.projectName & "' resolved (" &
          $ctx.resolved.repos.len & " repos)",
        remedy: "", fixKind: hfNone))
    except CatchableError as err:
      ctx.resolvedOk = false
      checks.add(HealthCheck(
        name: "manifest",
        status: hsFail,
        detail: "manifest unresolved: " & err.msg,
        remedy: self & " workspace sync",
        fixKind: hfNone))

  # 7. Dependencies / develop-mode siblings — every declared repo must
  #    be checked out. Missing ones get a clone remedy and are eligible
  #    for safe ``--fix``.
  block siblingCheck:
    if not ctx.resolvedOk:
      checks.add(HealthCheck(
        name: "siblings",
        status: hsWarn,
        detail: "skipped: manifest unresolved",
        remedy: self & " workspace sync",
        fixKind: hfNone))
    else:
      for repo in ctx.resolved.repos:
        let abs = parsed.workspaceRoot / repo.path
        if not dirExists(abs / ".git"):
          ctx.missingSiblings.add(repo)
      if ctx.missingSiblings.len == 0:
        checks.add(HealthCheck(
          name: "siblings",
          status: hsOk,
          detail: "all " & $ctx.resolved.repos.len &
            " declared repos checked out",
          remedy: "", fixKind: hfNone))
      else:
        var names: seq[string]
        for repo in ctx.missingSiblings: names.add(repo.path)
        checks.add(HealthCheck(
          name: "siblings",
          status: hsFail,
          detail: "missing checkouts: " & names.join(", "),
          remedy: self & " sync",
          fixKind: hfCloneSiblings))

  # 8. VCS host & auth reachability. Structural: we confirm a git tool is
  #    resolvable (the precondition for clone/fetch). We do NOT require a
  #    live network round-trip in the gatherer — that would make the
  #    doctor itself flaky offline. The remedy still names the auth fix.
  block vcsCheck:
    try:
      ctx.gitIdentity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
      ctx.gitOk = true
      checks.add(HealthCheck(
        name: "vcs-host-auth",
        status: hsOk,
        detail: "git tool resolvable (" & ctx.gitIdentity.binaryPath & ")",
        remedy: "", fixKind: hfNone))
    except CatchableError as err:
      ctx.gitOk = false
      checks.add(HealthCheck(
        name: "vcs-host-auth",
        status: hsFail,
        detail: "no usable git tool: " & err.msg,
        remedy: self & " hooks ensure --vcs",
        fixKind: hfNone))

  # 8b. Managed VCS hooks in every participating repo.
  #
  #     The pre-push publication gate is the only thing that publishes a
  #     workspace lock for a commit, and it runs from a hook file that lives
  #     OUTSIDE version control, in each repo's ``.git/hooks``. Nothing about
  #     a repo's tracked content records whether that file is present, so a
  #     hook that stops running stops running SILENTLY: commits keep landing,
  #     pushes keep succeeding, and the absence surfaces only much later as a
  #     CI job that cannot resolve its siblings.
  #
  #     Two distinct ways it stops, both seen in the fleet:
  #
  #       * missing — the repo never got hooks (``ensure`` never reached it);
  #       * shadowed — a foreign installer (pre-commit) overwrote the
  #         dispatcher at the canonical path while the managed body sits
  #         beside it, unreferenced.
  #
  #     Shadowed is the more dangerous of the two precisely because it LOOKS
  #     installed: ``.git/hooks/pre-push`` exists and is executable.
  block hooksCheck:
    var missing: seq[string]
    var shadowed: seq[string]
    var okCount = 0
    var reposInspected = 0
    let enumerated = enumerateParticipatingRepos(parsed.workspaceRoot)
    for repo in enumerated.repos:
      if gitTopLevel(repo.repoPath).len == 0:
        continue        # not materialized; the siblings check owns that.
      inc reposInspected
      let hooksDir = gitHooksDir(repo.repoPath)
      for hookName in VcsHookNames:
        let standard = hookPath(hooksDir, hookName)
        let managed = managedHookPath(hooksDir, hookName)
        let wired = fileExists(extendedPath(standard)) and
          isReprobuildVcsHook(standard, hookName)
        if wired and fileExists(extendedPath(managed)):
          inc okCount
        elif fileExists(extendedPath(managed)) and
            fileExists(extendedPath(standard)):
          shadowed.add(repo.name & "/" & hookName)
        else:
          missing.add(repo.name & "/" & hookName)
    let remedy = self & " hooks ensure --vcs " & parsed.workspaceRoot
    if enumerated.mode != "workspace":
      checks.add(HealthCheck(
        name: "vcs-hooks",
        status: hsOk,
        detail: "single-repo target; workspace hook enumeration not applicable",
        remedy: "", fixKind: hfNone))
    elif shadowed.len > 0:
      checks.add(HealthCheck(
        name: "vcs-hooks",
        status: hsFail,
        detail: $shadowed.len & " managed hook(s) SHADOWED by a foreign " &
          "installer and not running: " & shadowed.join(", "),
        remedy: remedy,
        fixKind: hfEnsureVcsHooks))
    elif missing.len > 0:
      checks.add(HealthCheck(
        name: "vcs-hooks",
        status: hsFail,
        detail: $missing.len & " managed hook(s) missing across " &
          $reposInspected & " participating repo(s): " & missing.join(", "),
        remedy: remedy,
        fixKind: hfEnsureVcsHooks))
    else:
      checks.add(HealthCheck(
        name: "vcs-hooks",
        status: hsOk,
        detail: $okCount & " managed hook(s) wired across " &
          $reposInspected & " participating repo(s)",
        remedy: "", fixKind: hfNone))

  # 9. Push gateway. Structural/advisory: a certificate-enforcing project
  #    routes pushes through the local gateway. Absent enforcement, the
  #    gateway is not required; we report advisory so the user knows
  #    pushes are direct.
  checks.add(HealthCheck(
    name: "push-gateway",
    status: hsOk,
    detail: "no certificate-enforcing project; pushes are direct",
    remedy: "", fixKind: hfNone))

  # 10. Toolchain provisioning for the active platform. Structural: the
  #     git toolchain probe above is the load-bearing one for workspace
  #     operations; surface it here as the platform toolchain signal so a
  #     failure carries a remedy rather than a bare "ok".
  if ctx.gitOk:
    checks.add(HealthCheck(
      name: "toolchain",
      status: hsOk,
      detail: "platform git toolchain provisioned",
      remedy: "", fixKind: hfNone))
  else:
    checks.add(HealthCheck(
      name: "toolchain",
      status: hsFail,
      detail: "platform toolchain incomplete (no git)",
      remedy: self & " hooks ensure --vcs",
      fixKind: hfNone))

  # 11. Certificate policy. Advisory by default: when no project enforces
  #     test certificates, report "advisory/off" so the user knows pushes
  #     are not gated.
  checks.add(HealthCheck(
    name: "certificate-policy",
    status: hsOk,
    detail: "certificates: advisory/off (pushes not gated)",
    remedy: "", fixKind: hfNone))

  # 12. Workspace projects list and ignore/agents configuration (RA-30).
  block workspaceProjectsCheck:
    var ok = true
    var details: seq[string] = @[]

    let workspaceProjectsFile = parsed.workspaceRoot / "workspace-projects.md"
    if not fileExists(workspaceProjectsFile):
      ok = false
      details.add("workspace-projects.md is missing")

    let gitignoreFile = parsed.workspaceRoot / ".gitignore"
    if fileExists(gitignoreFile):
      let content = readFile(gitignoreFile)
      if "workspace-projects.md" notin content or ".repro/" notin content:
        ok = false
        details.add("workspace-projects.md or .repro/ not ignored in .gitignore")
    else:
      ok = false
      details.add(".gitignore is missing")

    let agentsFile = parsed.workspaceRoot / "AGENTS.md"
    if fileExists(agentsFile):
      let content = readFile(agentsFile)
      if "workspace-projects.md" notin content:
        ok = false
        details.add("workspace-projects.md not referenced in AGENTS.md")
    else:
      ok = false
      details.add("AGENTS.md is missing")

    if ok:
      checks.add(HealthCheck(
        name: "workspace-ergonomics",
        status: hsOk,
        detail: "workspace-projects.md generated, gitignored, and referenced in AGENTS.md",
        remedy: "",
        fixKind: hfNone))
    else:
      checks.add(HealthCheck(
        name: "workspace-ergonomics",
        status: hsFail,
        detail: details.join("; "),
        remedy: self & " health --fix",
        fixKind: hfWorkspaceErgonomics))

  result = (checks: checks, ctx: ctx)

proc healthHasFailure(checks: seq[HealthCheck]): bool =
  for c in checks:
    if c.status == hsFail:
      return true
  false

proc toJsonNode*(check: HealthCheck): JsonNode =
  result = newJObject()
  result["name"] = %check.name
  result["status"] = %($check.status)
  result["detail"] = %check.detail
  result["remedy"] = %check.remedy
  result["fixable"] = %(check.fixKind != hfNone)

proc healthChecksToJson*(checks: seq[HealthCheck]): JsonNode =
  result = newJObject()
  var arr = newJArray()
  var failed = 0
  for c in checks:
    arr.add(c.toJsonNode())
    if c.status == hsFail: inc failed
  result["checks"] = arr
  result["ok"] = %(failed == 0)
  result["failed"] = %failed
  result["exitCode"] = %(if failed > 0: 1 else: 0)

proc renderHealthTextLines*(checks: seq[HealthCheck]): seq[string] =
  ## Human table: one row per check with status, detail, and — for any
  ## non-ok row — the exact remedy command.
  var nameWidth = len("CHECK")
  for c in checks:
    if c.name.len > nameWidth: nameWidth = c.name.len
  result.add("CHECK".alignLeft(nameWidth) & "  STATUS  DETAIL")
  for c in checks:
    var line = c.name.alignLeft(nameWidth) & "  " &
      ($c.status).alignLeft(6) & "  " & c.detail
    result.add(line)
    if c.status != hsOk and c.remedy.len > 0:
      result.add("  remedy: " & c.remedy)

proc applyHealthFixes(parsed: HealthArgs; checks: seq[HealthCheck];
                      ctx: HealthContext): seq[string] =
  ## Perform ONLY the safe remediations the spec authorizes, announcing
  ## each action before running it. Returns the announcement / outcome
  ## lines for the report. Never performs a destructive or ambiguous fix.
  let self = reproSelfPath()
  for c in checks:
    if c.status == hsOk:
      continue
    case c.fixKind
    of hfNone:
      # Unsafe / ambiguous: report only, never auto-fix.
      result.add("fix: skip " & c.name &
        " (no safe auto-fix; remedy: " & c.remedy & ")")
    of hfDirenvAllow:
      result.add("fix: running `direnv allow " & parsed.workspaceRoot & "`")
      let direnvBin = resolveDirenvBin()
      if direnvBin.len == 0:
        result.add("fix: direnv not on PATH; cannot allow")
      else:
        let res = execCmdEx(quoteShell(direnvBin) & " allow",
          workingDir = parsed.workspaceRoot)
        if res.exitCode == 0:
          result.add("fix: direnv .envrc now trusted")
        else:
          result.add("fix: direnv allow failed: " & res.output.strip())
    of hfStartDaemon:
      # Single-user direct mode (no daemon) is a fully supported path, so
      # a daemon-mode ``warn`` is NOT force-fixed: we never push a daemon
      # onto a no-sudo / single-user host. We only auto-start the daemon
      # when the daemon-mode check is an outright ``fail`` (i.e. a daemon
      # that should be running is down). For the ``warn`` case we describe
      # the opt-in remedy without executing it.
      if c.status != hsFail:
        result.add("fix: describe " & c.name &
          " (single-user mode is supported; opt-in remedy: " &
          c.remedy & ")")
      else:
        result.add("fix: starting user store daemon (`" & self &
          " daemon start`)")
        try:
          let cfg = defaultUserDaemonConfig()
          let status = startUserDaemon(stablePublicCliPath(), cfg)
          if status.running:
            result.add("fix: user daemon running (" & status.endpoint & ")")
          else:
            result.add("fix: daemon start did not report running")
        except CatchableError as err:
          result.add("fix: daemon start failed: " & err.msg)
    of hfCloneSiblings:
      if not ctx.gitOk:
        result.add("fix: cannot clone siblings (no usable git tool)")
        continue
      for repo in ctx.missingSiblings:
        let abs = parsed.workspaceRoot / repo.path
        result.add("fix: cloning missing sibling " & repo.path &
          " from " & repo.fetchUrl)
        let res = gitRunPlain(ctx.gitIdentity,
          ["clone", repo.fetchUrl, abs])
        if res.code == 0 and dirExists(abs / ".git"):
          result.add("fix: cloned " & repo.path)
        else:
          result.add("fix: clone of " & repo.path & " failed: " &
            res.output.strip())
    of hfEnsureVcsHooks:
      # Reinstalling a managed hook is additive and reversible: a foreign
      # hook found at the canonical path is preserved as
      # ``<hook>.repro-local`` and still runs first. Nothing is discarded,
      # so this is a safe auto-fix.
      result.add("fix: reinstalling managed VCS hooks across the workspace")
      try:
        let report = ensureWorkspaceHooks(parsed.workspaceRoot)
        var keys: seq[string]
        for k in report.summary.keys: keys.add(k)
        keys.sort()
        var parts: seq[string]
        for k in keys: parts.add(k & "=" & $report.summary[k])
        result.add("fix: " & $report.entries.len & " hook(s) across " &
          $report.repos.len & " repo(s) (" & parts.join(", ") & ")")
      except CatchableError as err:
        result.add("fix: hooks ensure failed: " & err.msg)
    of hfWorkspaceErgonomics:
      result.add("fix: repairing workspace ergonomics files")
      let gitignoreFile = parsed.workspaceRoot / ".gitignore"
      var gitignoreContent = ""
      if fileExists(gitignoreFile):
        gitignoreContent = readFile(gitignoreFile)
      
      var gitignoreModified = false
      if ".repro/" notin gitignoreContent:
        if gitignoreContent.len > 0 and not gitignoreContent.endsWith("\n"):
          gitignoreContent.add("\n")
        gitignoreContent.add("# reprobuild local workspace state\n.repro/\n")
        gitignoreModified = true
      if "workspace-projects.md" notin gitignoreContent:
        if gitignoreContent.len > 0 and not gitignoreContent.endsWith("\n"):
          gitignoreContent.add("\n")
        gitignoreContent.add("# generated workspace project documentation\nworkspace-projects.md\n")
        gitignoreModified = true
      
      if gitignoreModified:
        writeFile(gitignoreFile, gitignoreContent)
        result.add("fix: updated .gitignore to ignore .repro/ and workspace-projects.md")

      let agentsFile = parsed.workspaceRoot / "AGENTS.md"
      var agentsContent = ""
      if fileExists(agentsFile):
        agentsContent = readFile(agentsFile)
      else:
        agentsContent = "# Workspace\n\nThis is a multi-repo reprobuild workspace.\n"
      
      if "workspace-projects.md" notin agentsContent:
        if not agentsContent.endsWith("\n"):
          agentsContent.add("\n")
        agentsContent.add("\nRead @workspace-projects.md for the active project set and per-repo descriptions.\n")
        writeFile(agentsFile, agentsContent)
        result.add("fix: updated AGENTS.md with workspace-projects.md reference")

      try:
        writeGeneratedWorkspaceProjects(parsed.workspaceRoot)
        result.add("fix: generated workspace-projects.md")
      except CatchableError as err:
        result.add("fix: failed generating workspace-projects.md: " & err.msg)

proc runHealthCommand*(args: openArray[string]): int =
  ## ``repro health [<project>] [--workspace-root=PATH] [--fix] [--json]``.
  ##
  ## Diagnose every layer and pair each failure with the exact remedy
  ## command. Exit non-zero (1) if any check is ``fail`` so CI / agents
  ## can gate on a healthy environment.
  let parsed = parseHealthArgs(args)
  var (checks, ctx) = gatherHealthChecks(parsed)

  if parsed.fix:
    let actions = applyHealthFixes(parsed, checks, ctx)
    # Re-diagnose after fixing so the final report reflects the new state.
    (checks, ctx) = gatherHealthChecks(parsed)
    if not parsed.json:
      for line in actions:
        stdout.writeLine(line)

  if parsed.json:
    stdout.writeLine(pretty(healthChecksToJson(checks), indent = 2))
  else:
    for line in renderHealthTextLines(checks):
      stdout.writeLine(line)

  if healthHasFailure(checks): 1 else: 0

# ---- M12.C: `repro workspace manifests` -----------------------------------

type
  WorkspaceManifestsLayerEntry* = object
    ## One per layer in ``.repo/workspace.toml``. ``url`` and
    ## ``localPath`` are mutually exclusive (M5 enforces this at parse
    ## time); ``layerCheckoutPath`` is the on-disk directory the
    ## composer materialised (for ``url`` layers) or pointed at (for
    ## ``local_path`` layers). ``contributedRepos`` lists the repo
    ## names this layer ultimately contributed to the composed result
    ## — i.e. the names whose ``manifestLayer`` field matches this
    ## layer's provenance after the composer's shadow-merge resolved.
    index*: int
    url*: string
    localPath*: string
    visibility*: string
    branch*: string
    provenance*: string
    layerCheckoutPath*: string
    contributedRepos*: seq[string]

  WorkspaceManifestsReport* = object
    ## Structured outcome of one ``repro workspace manifests``
    ## invocation. ``hasLayeredWorkspace`` is false when no
    ## ``.repo/workspace.toml`` is present; in that case ``layers`` is
    ## empty and the renderer prints a single "no layered workspace"
    ## line. Otherwise ``layers`` carries one entry per declared layer
    ## in source order.
    workspaceRoot*: string
    workspaceTomlPath*: string
    hasLayeredWorkspace*: bool
    project*: string
    layers*: seq[WorkspaceManifestsLayerEntry]
    exitCode*: int

proc toJsonNode*(report: WorkspaceManifestsReport): JsonNode =
  result = newJObject()
  result["workspaceRoot"] = %report.workspaceRoot
  result["workspaceTomlPath"] = %report.workspaceTomlPath
  result["hasLayeredWorkspace"] = %report.hasLayeredWorkspace
  result["project"] = %report.project
  var layers = newJArray()
  for entry in report.layers:
    var obj = newJObject()
    obj["index"] = %entry.index
    obj["url"] = %entry.url
    obj["localPath"] = %entry.localPath
    obj["visibility"] = %entry.visibility
    obj["branch"] = %entry.branch
    obj["provenance"] = %entry.provenance
    obj["layerCheckoutPath"] = %entry.layerCheckoutPath
    var contributed = newJArray()
    for name in entry.contributedRepos:
      contributed.add(%name)
    obj["contributedRepos"] = contributed
    layers.add(obj)
  result["layers"] = layers
  result["exitCode"] = %report.exitCode

proc renderManifestsTextLines*(report: WorkspaceManifestsReport):
    seq[string] =
  if not report.hasLayeredWorkspace:
    # ``hasLayeredWorkspace`` is false in two distinct cases; report each
    # accurately rather than always claiming the file is absent. A
    # single-project (metadata-only) ``.repo/workspace.toml`` IS present — it
    # simply declares no ``[[manifest]]`` layers — so ``executeWorkspaceManifests``
    # populates ``project`` for it while leaving it empty when the file is
    # genuinely missing.
    if report.project.len > 0:
      result.add("workspace manifests: single-project workspace '" &
        report.project & "' — no manifest layers declared in " &
        report.workspaceTomlPath)
    else:
      result.add("workspace manifests: no workspace metadata " &
        "(.repro/workspace.toml not present at " & report.workspaceRoot & ")")
    return
  result.add("workspace manifests: project=" & report.project &
    " layers=" & $report.layers.len)
  for entry in report.layers:
    var line = "workspace manifests: layer[" & $entry.index & "] " &
      entry.provenance & " visibility=" & entry.visibility
    if entry.branch.len > 0:
      line.add(" branch=" & entry.branch)
    if entry.layerCheckoutPath.len > 0:
      line.add(" checkout=" & entry.layerCheckoutPath)
    line.add(" repos=" & $entry.contributedRepos.len)
    result.add(line)

type
  WorkspaceManifestsArgs = object
    workspaceRoot: string
    json: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseWorkspaceManifestsArgs(args: openArray[string]):
    WorkspaceManifestsArgs =
  ## ``repro workspace manifests`` argv parser. No project positional
  ## (the workspace.toml carries the project name); accepts only
  ## ``--workspace-root=PATH`` and ``--json``.
  result.workspaceRoot = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace manifests` flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace manifests`: " &
          arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc layerProvenanceString(entry: ManifestLayer): string =
  ## Mirror compose.nim's ``layerLabel`` so this report's
  ## ``provenance`` field matches the value M8 stamped onto each
  ## composed ``ResolvedRepo.manifestLayer``.
  if entry.url.isSome and entry.url.get().len > 0:
    entry.url.get()
  elif entry.local_path.isSome and entry.local_path.get().len > 0:
    entry.local_path.get()
  else:
    "<unknown manifest layer>"

proc layerCheckoutPathFor(workspaceRoot: string; layerIdx: int;
    entry: ManifestLayer): string =
  ## Compute the on-disk checkout path the composer would have
  ## materialised this layer at. For ``local_path`` layers this is
  ## just the (resolved-relative-to-workspaceRoot) path the operator
  ## supplied. For ``url`` layers we reproduce the composer's
  ## directory naming so the path printed by this command matches
  ## whatever M8 actually placed on disk.
  if entry.local_path.isSome and entry.local_path.get().len > 0:
    let raw = entry.local_path.get()
    if isAbsolute(raw): return raw
    return workspaceRoot / raw
  if entry.url.isSome and entry.url.get().len > 0:
    let sanitizedSegments = block:
      var raw1 = ""
      for ch in entry.url.get():
        case ch
        of 'A'..'Z', 'a'..'z', '0'..'9', '-', '.', '_': raw1.add(ch)
        else: raw1.add('-')
      var collapsed = ""
      var prevDash = false
      for ch in raw1:
        if ch == '-':
          if not prevDash: collapsed.add(ch)
          prevDash = true
        else:
          collapsed.add(ch)
          prevDash = false
      if collapsed.len > 80:
        collapsed.setLen(80)
      collapsed.strip(chars = {'-'}, leading = true, trailing = true)
    let suffix =
      if sanitizedSegments.len > 0: sanitizedSegments
      else: "layer"
    return workspaceRoot / ".repro" /
      ("manifests-" & $layerIdx & "-" & suffix)
  ""

proc executeWorkspaceManifests(args: WorkspaceManifestsArgs):
    WorkspaceManifestsReport =
  var report: WorkspaceManifestsReport
  report.workspaceRoot = args.workspaceRoot
  let workspaceToml = workspaceTomlPath(args.workspaceRoot)
  report.workspaceTomlPath = workspaceToml
  if not fileExists(workspaceToml):
    report.hasLayeredWorkspace = false
    report.exitCode = 0
    return report
  # M13: a metadata-only workspace.toml (zero ``[[manifest]]`` entries —
  # written by M9 init in single-project mode to record the active
  # branch) is NOT a layered workspace. Mirror the dispatch sites in
  # init / sync / lock / status / list and treat such a file the same
  # way we treat a missing workspace.toml.
  let absToml = absolutePath(workspaceToml)
  let workspaceLocal = readWorkspaceLocal(absToml)
  if workspaceLocal.manifest.len == 0:
    report.hasLayeredWorkspace = false
    report.project = workspaceLocal.workspace.project
    report.exitCode = 0
    return report
  report.hasLayeredWorkspace = true
  report.project = workspaceLocal.workspace.project

  # Compose the layers to learn which repo each layer ultimately
  # contributed to the result (after the shadow-merge resolved).
  # A composition failure (missing layer, bad URL) leaves the
  # ``contributedRepos`` slice empty for the affected layer entries
  # but still lets us emit the declared structure.
  var contributedByProvenance = initTable[string, seq[string]]()
  try:
    let resolved = composeManifestLayers(
      workspaceLocal, args.workspaceRoot, absToml)
    for repo in resolved.repos:
      let key =
        if repo.manifestLayer.len > 0: repo.manifestLayer
        else: "<unknown manifest layer>"
      var current =
        if key in contributedByProvenance: contributedByProvenance[key]
        else: @[]
      current.add(repo.name)
      contributedByProvenance[key] = current
  except CatchableError:
    # Treat composition failures as "we know the declared layers but
    # not the contribution map". The report still ships with the
    # declared layer set so the operator sees the workspace shape.
    discard

  for layerIdx, entry in workspaceLocal.manifest:
    let provenance = layerProvenanceString(entry)
    var layerEntry = WorkspaceManifestsLayerEntry(
      index: layerIdx,
      url:
        if entry.url.isSome: entry.url.get()
        else: "",
      localPath:
        if entry.local_path.isSome: entry.local_path.get()
        else: "",
      visibility: entry.visibility,
      branch:
        if entry.branch.isSome: entry.branch.get()
        else: "",
      provenance: provenance,
      layerCheckoutPath: layerCheckoutPathFor(
        args.workspaceRoot, layerIdx, entry))
    if provenance in contributedByProvenance:
      layerEntry.contributedRepos = contributedByProvenance[provenance]
    report.layers.add(layerEntry)
  report.exitCode = 0
  result = report

proc writeWorkspaceManifestsReport(report: WorkspaceManifestsReport;
                                   destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspaceManifestsCommand*(args: openArray[string]): int =
  ## ``repro workspace manifests [--workspace-root=PATH] [--json]``.
  ##
  ## Exit codes (per M12 design — read-only command):
  ##   - 0 — layer set emitted (also when no workspace.toml is
  ##         present; the report carries ``hasLayeredWorkspace =
  ##         false`` and the text renderer prints the single
  ##         "no layered workspace" line).
  ##   - 1 — IO failure or malformed workspace.toml.
  let parsed = parseWorkspaceManifestsArgs(args)
  let report = executeWorkspaceManifests(parsed)
  writeWorkspaceManifestsReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "manifests"))
  stageFailureReport(parsed.report, report.workspaceRoot, "manifests",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderManifestsTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# ---- RA-5: `repro workspace shared-clones [list|rewire|root]` --------------
#
# Inspection / repair surface for the shared object-cache (per-upstream bare
# clones + per-repo ``objects/info/alternates`` wiring). The accelerator is
# transparent — it never changes what is built — so these verbs are purely
# operational:
#
#   * ``root``   — print the resolved cache root for this workspace and exit.
#   * ``list``   — for each resolved repo, show its shared bare path, whether
#                  the bare is present on disk, and whether the per-workspace
#                  repo is wired to it via alternates. Read-only; no network.
#   * ``rewire`` — idempotently retrofit an existing workspace: refresh each
#                  unique upstream's shared bare (clone-if-missing /
#                  fetch-if-present) and write the alternates entry into every
#                  already-checked-out repo that is missing it. Best-effort
#                  per repo — a failure to populate one bare is reported but
#                  does not abort the others.
#   * ``gc`` (alias ``maintenance``) — RA-15 maintenance pass per unique
#                  shared bare: prune ``refs/cache/<ws>/*`` for dead
#                  workspaces (those whose directory no longer exists among
#                  the live siblings), then ``git gc``/repack the bare when a
#                  loose-object / size / age budget is exceeded. ``--force``
#                  bypasses the budget gate. Best-effort — a maintenance error
#                  is reported but never raised (it must never block a
#                  clone/commit when run opportunistically).
#
# Exit codes:
#   * 0 — verb completed (``list``/``root`` always 0 on success; ``rewire``
#         0 when every wiring step that had a present bare succeeded).
#   * 1 — bad usage, resolve/IO failure, or a ``rewire`` that could not wire
#         a repo whose bare WAS present (a genuine failure, distinct from a
#         best-effort cache miss which is only reported).

type
  SharedClonesArgs = object
    verb: string
    workspaceRoot: string
    projectName: string
    json: bool
    force: bool
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

  SharedClonesRepoReport* = object
    name*: string
    path*: string
    fetchUrl*: string
    sharedBarePath*: string
    barePresent*: bool
    wired*: bool
    rewired*: bool
    # RA-15 maintenance fields (populated for the ``gc`` verb).
    maintenanceRan*: bool
    looseBefore*: int
    looseAfter*: int
    prunedRefs*: seq[string]
    diagnostic*: string

  SharedClonesReport* = object
    verb*: string
    workspaceRoot*: string
    cacheRoot*: string
    project*: string
    repos*: seq[SharedClonesRepoReport]
    exitCode*: int

proc toJsonNode*(report: SharedClonesReport): JsonNode =
  result = newJObject()
  result["verb"] = %report.verb
  result["workspaceRoot"] = %report.workspaceRoot
  result["cacheRoot"] = %report.cacheRoot
  result["project"] = %report.project
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["fetchUrl"] = %entry.fetchUrl
    obj["sharedBarePath"] = %entry.sharedBarePath
    obj["barePresent"] = %entry.barePresent
    obj["wired"] = %entry.wired
    obj["rewired"] = %entry.rewired
    obj["maintenanceRan"] = %entry.maintenanceRan
    obj["looseBefore"] = %entry.looseBefore
    obj["looseAfter"] = %entry.looseAfter
    var pruned = newJArray()
    for r in entry.prunedRefs:
      pruned.add(%r)
    obj["prunedRefs"] = pruned
    obj["diagnostic"] = %entry.diagnostic
    repos.add(obj)
  result["repos"] = repos
  result["exitCode"] = %report.exitCode

proc renderSharedClonesTextLines*(report: SharedClonesReport): seq[string] =
  if report.verb == "root":
    result.add(report.cacheRoot)
    return
  result.add("workspace shared-clones: root=" & report.cacheRoot &
    " project=" & report.project & " repos=" & $report.repos.len)
  for entry in report.repos:
    var line = "workspace shared-clones: " & entry.path &
      " bare=" & entry.sharedBarePath &
      " present=" & $entry.barePresent &
      " wired=" & $entry.wired
    if report.verb == "rewire":
      line.add(" rewired=" & $entry.rewired)
    if report.verb == "gc":
      line.add(" maintenanceRan=" & $entry.maintenanceRan &
        " loose=" & $entry.looseBefore & "->" & $entry.looseAfter &
        " prunedRefs=" & $entry.prunedRefs.len)
    if entry.diagnostic.len > 0:
      line.add(" diagnostic=" & entry.diagnostic)
    result.add(line)

proc parseSharedClonesArgs(args: openArray[string]): SharedClonesArgs =
  ## ``repro workspace shared-clones <verb> [<project>] [--workspace-root]
  ## [--json]``. ``verb`` defaults to ``list`` when omitted.
  result.verb = ""
  result.workspaceRoot = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--json":
      result.json = true
    elif arg == "--force":
      # RA-15: bypass the budget gate for the manual ``gc`` trigger.
      result.force = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace shared-clones` flag: " & arg)
    elif result.verb.len == 0:
      result.verb = arg
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to " &
          "`repro workspace shared-clones`: " & arg)
    inc i
  if result.verb.len == 0:
    result.verb = "list"
  # ``gc`` and ``maintenance`` are aliases for the RA-15 maintenance pass.
  if result.verb == "maintenance":
    result.verb = "gc"
  if result.verb notin ["list", "rewire", "root", "gc"]:
    raise newException(ValueError,
      "`repro workspace shared-clones` verb must be " &
        "list|rewire|root|gc|maintenance, got: " & result.verb)
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc liveWorkspaceNamesForCache(workspaceRoot: string): seq[string] =
  ## RA-15 liveness predicate for dead-workspace ref pruning. The cache-ref
  ## namespace (``refs/cache/<workspace>/<branch>``) uses each workspace
  ## directory's basename (see RA-4 ``spawnAsyncCachePush``). A shared bare is
  ## shared by sibling workspaces that live next to each other on disk, so the
  ## live set is: this workspace plus every *initialized* sibling workspace
  ## directory under the same parent. A ``refs/cache/<ws>/*`` whose ``<ws>`` is
  ## not in this set belongs to a workspace that no longer exists on disk and
  ## is safe to prune. We err on the side of KEEPING a ref: only directories
  ## that fail the initialized-workspace check are treated as dead.
  var roots: seq[string]
  roots.add(workspaceRoot)
  let parent = workspaceRoot.parentDir
  if parent.len > 0 and dirExists(parent):
    for kind, entry in walkDir(parent):
      if kind notin {pcDir, pcLinkToDir}:
        continue
      if entry == workspaceRoot:
        continue
      if isInitializedWorkspace(entry):
        roots.add(entry)
  discoverLiveWorkspaceNames(roots)

proc executeSharedClones(parsed: SharedClonesArgs): SharedClonesReport =
  result.verb = parsed.verb
  result.workspaceRoot = parsed.workspaceRoot
  result.cacheRoot = defaultCacheRoot(parsed.workspaceRoot)
  result.exitCode = 0
  if parsed.verb == "root":
    return

  # ``list`` and ``rewire`` enumerate the resolved repos. Reuse the M12
  # list resolver so the project-selection rules stay identical.
  var listArgs: WorkspaceListArgs
  listArgs.workspaceRoot = parsed.workspaceRoot
  listArgs.projectName = parsed.projectName
  let resolved = resolveWorkspaceListProject(listArgs)
  result.project = resolved.projectName

  # ``rewire`` and ``gc`` do live VCS work. ``list`` is read-only. Resolve
  # git only when we will use it.
  var identity: GitToolIdentity
  if parsed.verb in ["rewire", "gc"]:
    identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))

  # RA-15: the dead-workspace prune needs the live-workspace set. Compute it
  # once for the whole pass (it is the same for every bare in this run).
  var liveWorkspaces: seq[string]
  if parsed.verb == "gc":
    liveWorkspaces = liveWorkspaceNamesForCache(parsed.workspaceRoot)

  var sharedBareByUrl = initTable[string, SharedCloneResult]()
  # RA-15: maintain each unique shared bare at most once per pass.
  var maintainedBares = initHashSet[string]()
  for repo in resolved.repos:
    # The shared bare is keyed by the FULL repo URL (`cloneUrlFor`), not the
    # bare remote base (`repo.fetchUrl`) — using the base leaves the cache
    # un-cloneable and permanently unwired for one-remote-many-repos layouts.
    let cloneUrl = cloneUrlFor(repo)
    var entry = SharedClonesRepoReport(
      name: repo.name,
      path: repo.path,
      fetchUrl: cloneUrl)
    let info = inspectRepoWiring(parsed.workspaceRoot, result.cacheRoot,
      repo.path, cloneUrl)
    entry.sharedBarePath = info.sharedBarePath
    entry.barePresent = info.barePresent
    entry.wired = info.wired

    if parsed.verb == "rewire":
      let repoAbs = parsed.workspaceRoot / repo.path
      if not dirExists(repoAbs):
        # Nothing to retrofit for a repo that isn't checked out yet.
        entry.diagnostic = "repo not checked out; nothing to rewire"
        result.repos.add(entry)
        continue
      # Refresh the shared bare for this URL once.
      if not sharedBareByUrl.hasKey(cloneUrl):
        sharedBareByUrl[cloneUrl] =
          refreshSharedBare(identity.binaryPath, result.cacheRoot,
            cloneUrl)
      let refreshed = sharedBareByUrl[cloneUrl]
      if not refreshed.ok:
        entry.diagnostic = "shared bare unavailable: " & refreshed.diagnostic
        result.repos.add(entry)
        continue
      entry.barePresent = true
      if info.wired:
        entry.wired = true
        entry.rewired = false
      else:
        let wired = wireAlternates(repoAbs, refreshed.sharedBarePath)
        if wired.ok:
          entry.wired = true
          entry.rewired = true
          # Align the checkout's remote-tracking refs with the freshly-mirrored
          # bare. ``refreshSharedBare`` rebuilds the bare from the CURRENT remote
          # (``clone --bare`` / ``fetch --all --prune``), so a branch DELETED or
          # FORCE-PUSHED upstream leaves the checkout's remote-tracking ref
          # pointing at an object the new bare no longer has. Without this, the
          # rewired checkout still depends on whatever OLD object pool held that
          # object (e.g. a legacy shared clone being retired) and is fsck-dirty
          # on the shared bare alone. ``fetch --all --prune`` updates the moved
          # refs and prunes the deleted ones to match the mirror. Best-effort —
          # an offline/fetch failure does not fail the rewire; the checkout is
          # already wired and functional. (Reflog entries a force-push stranded
          # are harmless and are reaped by normal ``git gc`` reflog expiry.)
          discard gitRunPlain(identity,
            ["-C", repoAbs, "fetch", "--all", "--prune", "--quiet"])
        else:
          entry.diagnostic = "alternates wiring failed: " & wired.diagnostic
          # The bare WAS present but we could not wire — a genuine failure.
          result.exitCode = 1

    elif parsed.verb == "gc":
      # RA-15 maintenance: prune dead-workspace cache refs and gc/repack the
      # shared bare, once per unique bare. Best-effort — a maintenance error
      # is reported per repo but does not abort the others.
      if not info.barePresent:
        entry.diagnostic = "shared bare not present; nothing to maintain"
      elif info.sharedBarePath in maintainedBares:
        entry.diagnostic = "shared bare maintained via an earlier repo entry"
      else:
        maintainedBares.incl(info.sharedBarePath)
        let m = maintainSharedBare(identity.binaryPath, info.sharedBarePath,
          liveWorkspaces, defaultMaintenanceBudget(), parsed.force)
        entry.maintenanceRan = m.ran
        entry.looseBefore = m.looseBefore
        entry.looseAfter = m.looseAfter
        entry.prunedRefs = m.prunedRefs
        if not m.ok:
          entry.diagnostic = "maintenance failed: " & m.diagnostic
          result.exitCode = 1
    result.repos.add(entry)

proc writeSharedClonesReport(report: SharedClonesReport;
                             destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runWorkspaceSharedClonesCommand*(args: openArray[string]): int =
  ## ``repro workspace shared-clones [list|rewire|root|gc] [<project>]
  ## [--workspace-root=PATH] [--json] [--force]``. ``maintenance`` is an alias
  ## for ``gc``; ``--force`` bypasses the gc budget gate.
  let parsed = parseSharedClonesArgs(args)
  let report = executeSharedClones(parsed)
  # ``root`` prints just the path; do not write a report file for it (it
  # makes no per-repo claims).
  if parsed.verb != "root":
    writeSharedClonesReport(report,
      reportDestination(parsed.report, report.workspaceRoot,
        "shared-clones"))
    stageFailureReport(parsed.report, report.workspaceRoot, "shared-clones",
      report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderSharedClonesTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# ---- RA-20: `repro workspace forall` --------------------------------------
#
# Native cross-repo command — the ``repo forall -c`` equivalent, since
# reprobuild does not wrap Google's ``repo``. Built on
# ``enumerateParticipatingRepos`` (the same repo set the M17 hook installer
# and the workspace gate enumerate), so ``forall`` and the rest of the
# workspace surface always agree on "which repos participate".
#
# Semantics mirror ``repo forall -c <cmd>``:
#   * The command runs once per participating repo, via the shell, with the
#     repo's working tree as the working directory.
#   * Per-repo helper env vars are exported for the duration of each run
#     (``REPRO_REPO_PATH`` / ``REPRO_REPO_NAME`` / ``REPRO_PROJECT`` plus the
#     ``REPO_*`` aliases ``repo forall`` users expect), so the command body
#     can branch on which repo it is in.
#   * Each repo's success/failure + captured output is reported in the
#     existing per-repo digest style (Interactive-UX Principle 1).
#   * Exit code is non-zero if ANY repo's command failed.
#
# Failure policy is configurable per the deliverable:
#   * default — run EVERY repo, report each, exit non-zero if any failed
#     (this is ``repo forall``'s default and the safest cross-repo posture).
#   * ``--fail-fast`` — stop at the first failing repo (skip the rest).
# ``--keep-going`` is accepted as an explicit affirmation of the default.

type
  WorkspaceForallRepoResult* = object
    ## One repo's outcome from a ``forall`` run.
    name*: string
    path*: string
    exitCode*: int
    output*: string    ## captured stdout+stderr of the command.
    ran*: bool         ## false when skipped (fail-fast bailout, or the
                       ## repo's working tree is not materialized yet).
    skipReason*: string

  WorkspaceForallReport* = object
    project*: string
    workspaceRoot*: string
    command*: string
    repos*: seq[WorkspaceForallRepoResult]
    failed*: int
    succeeded*: int
    skipped*: int
    exitCode*: int

  WorkspaceForallArgs = object
    workspaceRoot: string
    projectName: string
    command: string
    haveCommand: bool
    failFast: bool
    json: bool
    quiet: bool       ## suppress per-repo captured output in text mode.
    report: ReportSpec    ## Opt-in ``--write-report[=PATH]`` artifact.

proc toJsonNode*(report: WorkspaceForallReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["command"] = %report.command
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["exitCode"] = %entry.exitCode
    obj["output"] = %entry.output
    obj["ran"] = %entry.ran
    obj["skipReason"] = %entry.skipReason
    repos.add(obj)
  result["repos"] = repos
  result["failed"] = %report.failed
  result["succeeded"] = %report.succeeded
  result["skipped"] = %report.skipped
  result["exitCode"] = %report.exitCode

proc parseWorkspaceForallArgs(args: openArray[string]):
    WorkspaceForallArgs =
  ## ``repro workspace forall [<project>] -c <cmd> [--workspace-root=PATH]
  ## [--fail-fast] [--keep-going] [--quiet] [--json]``.
  ##
  ## ``-c`` / ``--command`` takes the shell command to run in every repo
  ## (matching ``repo forall -c``). The first bare positional is an optional
  ## project selector; anything after that is rejected so a stray word is
  ## not silently swallowed.
  result.workspaceRoot = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "-c":
      # Short form: the next argv element is the command body.
      if i + 1 >= args.len:
        raise newException(ValueError, "-c requires a command")
      inc i
      result.command = args[i]
      result.haveCommand = true
    elif arg.startsWith("-c="):
      result.command = arg.split("=", maxsplit = 1)[1]
      result.haveCommand = true
    elif arg == "--command" or arg.startsWith("--command="):
      result.command = valueFromFlag(args, i, "--command")
      result.haveCommand = true
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--fail-fast":
      result.failFast = true
    elif arg == "--keep-going" or arg == "--ignore-errors":
      # Explicit affirmation of the default (run all, report each, exit
      # non-zero if any failed). Accepted as a no-op so scripts can be
      # explicit about the policy.
      result.failFast = false
    elif arg == "--quiet":
      result.quiet = true
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro workspace forall` flag: " & arg)
    elif result.projectName.len == 0:
      result.projectName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro workspace forall`: " &
          arg)
    inc i
  if not result.haveCommand or result.command.len == 0:
    raise newException(ValueError,
      "`repro workspace forall` requires a command: " &
        "`repro workspace forall -c '<command>'`")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc runForallInRepo(repo: HookRepoTarget; command, projectName: string):
    tuple[exitCode: int; output: string] =
  ## Run ``command`` via the shell in ``repo``'s working tree with the
  ## per-repo helper env vars set, capturing stdout+stderr. Mirrors the
  ## env contract of ``repo forall`` (``REPO_PROJECT`` / ``REPO_PATH`` /
  ## ``REPO_REMOTE``-style vars) plus reprobuild-namespaced equivalents.
  let argv = @["sh", "-c", command]
  # Export the per-repo context like ``repo forall`` does. We set them in
  # the parent env around the spawn (restoring afterward) so the child and
  # any subshells inherit them.
  let saved = [
    ("REPRO_REPO_PATH", getEnv("REPRO_REPO_PATH")),
    ("REPRO_REPO_NAME", getEnv("REPRO_REPO_NAME")),
    ("REPRO_PROJECT", getEnv("REPRO_PROJECT")),
    ("REPO_PATH", getEnv("REPO_PATH")),
    ("REPO_NAME", getEnv("REPO_NAME")),
    ("REPO_PROJECT", getEnv("REPO_PROJECT"))]
  let savedHad = [
    existsEnv("REPRO_REPO_PATH"), existsEnv("REPRO_REPO_NAME"),
    existsEnv("REPRO_PROJECT"), existsEnv("REPO_PATH"),
    existsEnv("REPO_NAME"), existsEnv("REPO_PROJECT")]
  putEnv("REPRO_REPO_PATH", repo.repoPath)
  putEnv("REPRO_REPO_NAME", repo.name)
  putEnv("REPRO_PROJECT", projectName)
  putEnv("REPO_PATH", repo.repoPath)
  putEnv("REPO_NAME", repo.name)
  putEnv("REPO_PROJECT", projectName)
  defer:
    for idx, pair in saved:
      if savedHad[idx]:
        putEnv(pair[0], pair[1])
      else:
        delEnv(pair[0])
  let process = startProcess(argv[0],
    workingDir = repo.repoPath,
    args = argv[1 .. ^1],
    options = {poUsePath, poStdErrToStdOut})
  defer: process.close()
  let outStream = process.outputStream
  var buf = ""
  var line = ""
  while outStream.readLine(line):
    buf.add(line)
    buf.add("\n")
  let code = process.waitForExit()
  (code, buf)

proc executeWorkspaceForall(args: WorkspaceForallArgs):
    WorkspaceForallReport =
  var report: WorkspaceForallReport
  report.workspaceRoot = args.workspaceRoot
  report.command = args.command
  let enumerated = enumerateParticipatingRepos(args.workspaceRoot)
  report.project = enumerated.projectName
  if enumerated.mode != "workspace" or enumerated.repos.len == 0:
    raise newException(ValueError,
      "`repro workspace forall` found no participating repos at " &
        args.workspaceRoot &
        " (is this an initialized workspace? run `repro workspace init`)")
  var bailed = false
  for repo in enumerated.repos:
    if bailed:
      report.repos.add(WorkspaceForallRepoResult(
        name: repo.name, path: repo.repoPath, ran: false,
        skipReason: "skipped after earlier failure (--fail-fast)"))
      inc report.skipped
      continue
    if not dirExists(repo.repoPath):
      report.repos.add(WorkspaceForallRepoResult(
        name: repo.name, path: repo.repoPath, ran: false,
        skipReason: "working tree not materialized"))
      inc report.skipped
      continue
    let outcome = runForallInRepo(repo, args.command, enumerated.projectName)
    report.repos.add(WorkspaceForallRepoResult(
      name: repo.name, path: repo.repoPath, exitCode: outcome.exitCode,
      output: outcome.output, ran: true))
    if outcome.exitCode == 0:
      inc report.succeeded
    else:
      inc report.failed
      if args.failFast:
        bailed = true
  report.exitCode = if report.failed > 0: 1 else: 0
  result = report

proc renderForallTextLines(report: WorkspaceForallReport;
    quiet: bool): seq[string] =
  result.add("workspace forall: running `" & report.command &
    "` in " & $report.repos.len & " repo(s) of project " &
    report.project)
  for entry in report.repos:
    if not entry.ran:
      result.add("  [skip] " & entry.path & " (" & entry.name & "): " &
        entry.skipReason)
      continue
    let tag = if entry.exitCode == 0: "ok" else: "FAILED"
    result.add("  [" & tag & "] " & entry.path & " (" & entry.name &
      ") exit=" & $entry.exitCode)
    if not quiet and entry.output.strip().len > 0:
      for outLine in entry.output.strip(leading = false).splitLines():
        result.add("    | " & outLine)
  result.add("workspace forall: " & $report.succeeded & " ok, " &
    $report.failed & " failed, " & $report.skipped & " skipped")
  if report.failed > 0:
    var names: seq[string]
    for entry in report.repos:
      if entry.ran and entry.exitCode != 0:
        names.add(entry.name)
    result.add("workspace forall: command failed in " & names.join(", ") &
      " — re-run after fixing, or inspect with `repro workspace forall -c " &
      "'<diagnostic>'`")

proc writeWorkspaceForallReport(report: WorkspaceForallReport;
                                destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  try:
    createDir(parentDir(destination))
    writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")
  except CatchableError:
    # The report file is a convenience artifact; never let it change the
    # command's exit code.
    discard

proc runWorkspaceForallCommand*(args: openArray[string]): int =
  ## ``repro workspace forall [<project>] -c <cmd> [flags]``. The
  ## ``repo forall -c`` equivalent — runs ``<cmd>`` via the shell in every
  ## participating repo (RA-20).
  let parsed = parseWorkspaceForallArgs(args)
  let report = executeWorkspaceForall(parsed)
  writeWorkspaceForallReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "forall"))
  stageFailureReport(parsed.report, report.workspaceRoot, "forall",
    report.toJsonNode())
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderForallTextLines(report, parsed.quiet):
      stdout.writeLine(line)
  report.exitCode

# ---- M14: `repro branch` (show / create) ----------------------------------
#
# Per ``reprobuild-specs/CLI/branch.md`` and Phase 4 of
# ``reprobuild-specs/Workspace-Management.milestones.org``. Unlike the
# M9–M12 family this is a TOP-LEVEL subcommand (``repro branch``, not
# ``repro workspace new``) — branch operations are the most frequent
# workspace coordination commands and earn a short alias.
#
# Two forms:
#
#   * ``repro branch`` (no positional)
#       Read-only show form. Returns the recorded
#       ``[workspace].branch`` value from M13 metadata via
#       ``readWorkspaceBranch``. Prints a clear "no active branch"
#       diagnostic and still exits 0 when neither metadata nor a
#       resolver result is available — the operator's question
#       ("what branch am I on?") has a legitimate "none recorded"
#       answer in a fresh workspace that pre-dates M13.
#
#   * ``repro branch <name>`` (create form)
#       Per-repo plan: refuse-and-report when ANY participating repo
#       is dirty (exit 2, no repo modified), refuse-and-report when
#       ANY repo already carries a branch by that name at a different
#       SHA (exit 2 — branch-name collision), idempotently treat a
#       pre-existing branch by that name at the same HEAD as success,
#       and otherwise schedule a ``gitBranchCreate`` action per repo.
#       On success update the M13 metadata's ``[workspace].branch`` to
#       ``<name>``.
#
# Exit codes:
#   * 0 — show form succeeded; or create form succeeded (including
#         the idempotent re-create case).
#   * 1 — IO / VCS / resolve failure that wasn't a refuse-and-report.
#   * 2 — at least one repo was dirty, OR at least one repo had a
#         pre-existing branch by that name pointing at a different
#         SHA (operator has manual work).

type
  BranchRepoOutcome* = enum
    broCreated         ## ``gitBranchCreate`` ran successfully.
    broAlreadyAtHead   ## Pre-existing branch at HEAD — idempotent.
    broDirtyRefused    ## Repo was dirty; nothing scheduled.
    broCollisionRefused
                       ## Pre-existing branch at a different SHA.
    broActionFailed    ## ``gitBranchCreate`` action returned non-OK.

  BranchRepoEntry* = object
    ## Per-repo line in the JSON report. ``existingSha`` carries the
    ## SHA the colliding branch pointed at (empty unless ``outcome``
    ## is ``collision_refused``); ``dirtyReason`` carries the
    ## human-facing reason when ``outcome`` is ``dirty_refused``.
    name*: string
    path*: string
    headSha*: string
    outcome*: string
    existingSha*: string
    dirtyReason*: string
    diagnostic*: string

  BranchReport* = object
    ## Structured outcome of one ``repro branch`` invocation.
    ## ``form`` is ``show`` for the read-only path and ``create`` for
    ## the workspace-wide creation path; ``branch`` is the value the
    ## show form returned, or the requested name on the create path.
    ## ``recordedBranch`` is the value of ``[workspace].branch`` AFTER
    ## the command finished (so a successful create reflects the new
    ## value; a refuse-and-report reflects whatever was already there).
    project*: string
    workspaceRoot*: string
    form*: string
    branch*: string
    recordedBranch*: string
    repos*: seq[BranchRepoEntry]
    exitCode*: int
    sourceWorkspaceRoot*: string
      ## M27 fork form (``form = "fork"``) only: the workspace the fork was cut
      ## FROM. ``workspaceRoot`` is then the NEW workspace. Empty otherwise.
    includeChanges*: bool
      ## M27 fork form only: whether ``--include-changes`` was requested.
    featureStarted*: bool
      ## M27 fork form only: the M16 feature mark recorded in the NEW workspace.
    projects*: seq[string]
      ## PS-6 fork form only: the project set the new workspace was given —
      ## inherited from the source, or the ``--projects`` override. Reported so
      ## a fork's membership is auditable without diffing two workspace.toml
      ## files after the fact.

proc branchOutcomeTag(outcome: BranchRepoOutcome): string =
  case outcome
  of broCreated: "created"
  of broAlreadyAtHead: "already_at_head"
  of broDirtyRefused: "dirty_refused"
  of broCollisionRefused: "collision_refused"
  of broActionFailed: "action_failed"

proc toJsonNode*(report: BranchReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["form"] = %report.form
  result["branch"] = %report.branch
  result["recordedBranch"] = %report.recordedBranch
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["headSha"] = %entry.headSha
    obj["outcome"] = %entry.outcome
    obj["existingSha"] = %entry.existingSha
    obj["dirtyReason"] = %entry.dirtyReason
    obj["diagnostic"] = %entry.diagnostic
    repos.add(obj)
  result["repos"] = repos
  result["exitCode"] = %report.exitCode
  result["featureStarted"] = %report.featureStarted
  if report.sourceWorkspaceRoot.len > 0:
    result["sourceWorkspaceRoot"] = %report.sourceWorkspaceRoot
    result["includeChanges"] = %report.includeChanges
    var projects = newJArray()
    for name in report.projects:
      projects.add(%name)
    result["projects"] = projects

proc renderBranchTextLines*(report: BranchReport): seq[string] =
  if report.form == "show":
    if report.branch.len > 0:
      result.add("workspace branch: " & report.branch)
    else:
      result.add("workspace branch: <none recorded>")
    return
  # create form
  for entry in report.repos:
    var line = "workspace branch: " & entry.path & " " & entry.outcome
    if entry.headSha.len > 0:
      line.add(" head=" &
        entry.headSha[0 ..< min(8, entry.headSha.len)])
    if entry.existingSha.len > 0:
      line.add(" existing=" &
        entry.existingSha[0 ..< min(8, entry.existingSha.len)])
    if entry.dirtyReason.len > 0:
      line.add(" (" & entry.dirtyReason & ")")
    elif entry.diagnostic.len > 0:
      line.add(" (" & entry.diagnostic & ")")
    result.add(line)
  if report.exitCode == 0:
    result.add("workspace branch: '" & report.branch &
      "' created across " & $report.repos.len & " repos; metadata=" &
      report.recordedBranch)
    # M27 fork form: the operator's next step is in a DIFFERENT directory than
    # the one they ran from, so say where it is (communicate-before-execute's
    # closing half) and point at the readiness check.
    if report.sourceWorkspaceRoot.len > 0:
      result.add("workspace branch: forked from " &
        report.sourceWorkspaceRoot & " (left untouched) into " &
        report.workspaceRoot)
      result.add("workspace branch: cd " & report.workspaceRoot &
        " && repro health")
  else:
    # Failure. There are two shapes and they must not be worded the same way.
    #
    # A REFUSAL happens in the pre-flight pass: every repo was checked, at
    # least one blocked, and nothing was created anywhere. A PARTIAL ADVANCE
    # happens once the execute pass has started: the branch exists in the
    # repos that succeeded and the tree is deliberately left in place for the
    # re-run (the no-rollback contract).
    #
    # Reporting a partial advance as "no branch was created in any repo
    # (creation is atomic)" is worse than saying nothing: the operator has
    # branches on disk that the summary swears do not exist, so they neither
    # clean them up nor trust the re-run. Which case this is, is decided by
    # the per-repo outcomes rather than asserted up front.
    var blockers: seq[string]
    var created: seq[string]
    for entry in report.repos:
      if entry.outcome in ["branched", "branched_with_changes",
                           branchOutcomeTag(broCreated)]:
        created.add(entry.path)
      elif entry.outcome != "ready" and
          entry.outcome != branchOutcomeTag(broAlreadyAtHead):
        blockers.add(entry.path & "=" & entry.outcome)
    var summary =
      if created.len > 0:
        "workspace branch: INCOMPLETE — '" & report.branch &
          "' was created in " & $created.len & " repo(s) and the partial " &
          "workspace is left in place; re-run the same command to finish it"
      else:
        "workspace branch: ABORTED — no branch '" & report.branch &
          "' was created in any repo (nothing had been created when the " &
          "first blocker was found)"
    if blockers.len > 0:
      summary.add("; " & $blockers.len & " repo(s) blocked: " &
        blockers.join(", "))
    summary.add(". Fix the blocker(s) and re-run.")
    result.add(summary)

type
  BranchArgs = object
    workspaceRoot: string
    projectName: string
    branchName: string
    forkPath: string        ## WV-6: the positional — the fork destination.
    includeChanges: bool    ## M27: also copy the source's uncommitted work.
    existingBranch: bool    ## WV-6: adopt an existing branch instead of cutting one.
    projects: seq[string]
      ## PS-6 ``--projects=A,B`` — the project set the NEW workspace should
      ## have. Empty (the default) means "whatever this workspace has", which
      ## is the only answer that makes a fork a fork: a branch of a workspace
      ## is the same workspace on a different branch, so its membership is
      ## inherited rather than re-derived. A non-empty value REPLACES the
      ## inherited set, which is how a developer forks a narrower (or wider)
      ## slice than they currently have checked out.
    destinationRefusal: string
      ## WV-6 — a destination guard that fired during parsing. Carried rather
      ## than raised so the command reports it as an ordinary refusal (exit 2,
      ## nothing created) instead of as a usage error.
    checkout: bool          ## M28: create AND switch every repo onto the branch.
    json: bool
    toolProvisioning: ToolProvisioningMode
    report: ReportSpec      ## Opt-in ``--write-report[=PATH]`` artifact.

proc ascendToWorkspaceRoot(startDir: string): string =
  ## Walk up from ``startDir`` to the nearest directory carrying the RA-10
  ## ``isInitializedWorkspace`` marker, so the prompt works from any
  ## subdirectory of a workspace (like ``__git_ps1``). Returns "" when no
  ## ancestor is an initialized workspace. Pure filesystem stat walk — no
  ## git, bounded by the path depth.
  var dir = absolutePath(startDir)
  while true:
    if isInitializedWorkspace(dir):
      return dir
    let parent = parentDir(dir)
    if parent.len == 0 or parent == dir:
      return ""
    dir = parent

proc resolveInvokedWorkspaceRoot(explicit: string): string =
  ## The workspace root a workspace-wide verb should act on.
  ##
  ## An explicit ``--workspace-root`` wins. Otherwise walk UP from the current
  ## directory to the nearest initialized workspace, so `repro branch` and
  ## `repro switch` work from inside a member repo — which is where a developer
  ## actually stands. Taking the cwd verbatim made them the only workspace-wide
  ## verbs that had to be run from the root, and the failure was obscure: the
  ## member repo has no `.repro/workspace.toml`, so the error talked about
  ## missing metadata rather than about where you were.
  ##
  ## Falls back to the cwd when no ancestor is a workspace, preserving the
  ## previous diagnostic for the genuinely-not-in-a-workspace case.
  if explicit.len > 0:
    return absolutePath(explicit)
  let here = getCurrentDir()
  let ascended = ascendToWorkspaceRoot(here)
  if ascended.len > 0: ascended else: absolutePath(here)

proc parseBranchArgs*(args: openArray[string]; verb = "repro branch";
                      requirePath = false): BranchArgs =
  ## ``repro branch [<path>] [--branch=NAME] [--existing-branch]
  ## [--include-changes] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## WV-6 — the positional, when present, is the fork DESTINATION PATH, and
  ## the branch name defaults to its basename. A workspace branch is a set of
  ## coordinated branches across every participating repo, and what the
  ## operator wants when they start one is somewhere to put it; making the
  ## argument a path means the directory name and the branch name stop being
  ## two things to keep in sync. ``--branch=NAME`` covers the case where they
  ## should differ.
  ##
  ## ``project`` is intentionally NOT a positional here — the active project is
  ## recovered either from a composer-mode workspace.toml or from a
  ## metadata-only workspace.toml's ``[workspace].project`` field (M13).
  ##
  ## ``verb`` is the spelling the operator actually typed, so a diagnostic
  ## names the command they ran rather than its sibling. ``requirePath`` is set
  ## by ``repro workspace new``, whose whole job is to produce a workspace: the
  ## no-argument show form belongs to ``repro branch`` alone, and a ``new``
  ## that quietly answered a question instead of creating anything would be the
  ## same class of surprise the verb split exists to remove.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var explicitBranch = ""
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--branch" or arg.startsWith("--branch="):
      explicitBranch = valueFromFlag(args, i, "--branch")
    elif arg == "--existing-branch":
      result.existingBranch = true
    elif arg == "--include-changes":
      result.includeChanges = true
    elif arg == "--projects" or arg.startsWith("--projects="):
      # Comma-separated and repeatable both work, so the flag reads the same
      # whether it is typed by hand or assembled by a script.
      for name in valueFromFlag(args, i, "--projects").split(','):
        let trimmed = name.strip()
        if trimmed.len > 0 and trimmed notin result.projects:
          result.projects.add(trimmed)
    elif arg == "--json":
      result.json = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `" & verb & "` flag: " & arg)
    elif result.forkPath.len == 0:
      result.forkPath = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `" & verb & "`: " & arg &
          " (the single positional is the destination PATH; use " &
          "`--branch=NAME` to name the branch something else)")
    inc i
  result.workspaceRoot = resolveInvokedWorkspaceRoot(result.workspaceRoot)
  if result.forkPath.len == 0:
    if requirePath:
      raise newException(ValueError,
        "`" & verb & "` requires the destination <path> of the new " &
          "workspace, e.g. `" & verb & " ../my-feature`. To ask which " &
          "branch this workspace is on, run `repro branch`")
    # The read-only show form. Every flag below only means something for a
    # destination, so accepting them here would silently do nothing.
    if explicitBranch.len > 0 or result.existingBranch or
        result.includeChanges or result.projects.len > 0:
      raise newException(ValueError,
        "`--branch` / `--existing-branch` / `--include-changes` / " &
          "`--projects` require a " &
          "destination path (`" & verb & " <path>`); with no path " &
          "`repro branch` only reports the current workspace branch")
    return
  let destination = absolutePath(result.forkPath)
  # A destination INSIDE this workspace is refused. Nesting a workspace inside
  # a workspace is always wrong — the inner tree gets swept up by the outer
  # one's repo enumeration, hooks and locks — and a bare single-segment name
  # (`repro branch my-feature`) lands here, which is exactly the argument most
  # likely to be typed by accident. Failing loudly beats producing a nested
  # workspace that only misbehaves later.
  if pathIsCwdOrAncestor(result.workspaceRoot, destination):
    result.destinationRefusal =
      "'" & result.forkPath & "' is inside the current workspace (" &
      result.workspaceRoot & ").\n" &
      "  To create a branch and switch this workspace onto it:  " &
      "repro switch -b " & lastPathPart(result.forkPath) & "\n" &
      "  To fork into a new workspace directory:                " &
      verb & " ../" & lastPathPart(result.forkPath)
  elif pathIsCwdOrAncestor(destination, result.workspaceRoot):
    # The inverse overlap is just as unsafe: cloning into an ancestor of the
    # source would collide with the source tree itself.  Compare through the
    # deepest existing ancestor so a not-yet-created spelling reached through
    # a symlink (notably macOS /var -> /private/var) cannot evade the guard.
    result.destinationRefusal =
      "'" & result.forkPath & "' contains the current workspace (" &
      result.workspaceRoot & "); the fork destination must be a separate " &
      "directory outside the source workspace"
  result.forkPath = destination
  result.branchName =
    if explicitBranch.len > 0: explicitBranch
    else: lastPathPart(destination)
  if result.branchName.len == 0:
    raise newException(ValueError,
      "cannot derive a branch name from '" & result.forkPath &
        "'; pass `--branch=NAME`")

proc resolveBranchProject(parsed: BranchArgs):
    tuple[resolved: ResolvedProject;
          workspaceLocal: Option[WorkspaceLocal]] =
  ## Same dispatch rule as M9–M13: composer mode when
  ## ``.repo/workspace.toml`` declares ``[[manifest]]`` layers,
  ## single-project mode otherwise. The single-project path needs a
  ## project name; we recover it from a metadata-only workspace.toml's
  ## ``[workspace].project`` field rather than asking the user to
  ## repeat it (M13's contract).
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    let absToml = absolutePath(workspaceToml)
    let workspaceLocal = readWorkspaceLocal(absToml)
    let resolved = extendWithActiveProjectSet(parsed.workspaceRoot,
      composeManifestLayers(workspaceLocal, parsed.workspaceRoot, absToml))
    return (resolved, some(workspaceLocal))
  var projectName = parsed.projectName
  # PS-2 — a workspace branch is workspace-wide, so with no explicit project
  # argument every repo of the active project set participates.
  let membershipFromMetadata = parsed.projectName.len == 0
  if projectName.len == 0 and fileExists(workspaceToml):
    try:
      let recorded =
        readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
      if recorded.len > 0:
        projectName = recorded
    except WorkspaceManifestParseError:
      discard
  if projectName.len == 0:
    raise newException(ValueError,
      "`repro branch <name>` requires either `.repro/workspace.toml` " &
        "or a project name recoverable from one; neither was present at " &
        parsed.workspaceRoot)
  let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
  let projectFile = manifestsRoot / "projects" / (projectName & ".toml")
  let variantFile = manifestsRoot / "variants" / (projectName & ".toml")
  proc withSet(resolved: ResolvedProject): ResolvedProject =
    if membershipFromMetadata:
      extendWithActiveProjectSet(parsed.workspaceRoot, resolved)
    else: resolved
  if fileExists(projectFile):
    return (withSet(resolveProject(projectFile)), none(WorkspaceLocal))
  if fileExists(variantFile):
    return (withSet(resolveVariant(variantFile)), none(WorkspaceLocal))
  raise newException(ValueError,
    "no project or variant named '" & projectName &
      "' found under '" & manifestsRoot &
      "' (looked for '" & projectFile & "' and '" & variantFile & "')")

proc executeBranchShow(parsed: BranchArgs): BranchReport =
  ## Read-only path. Returns the value recorded in M13 metadata. We
  ## intentionally do NOT consult the live HEAD heuristic that
  ## ``deriveActiveBranch`` falls back on — the M13 contract makes the
  ## metadata-recorded value authoritative, and a workspace that has
  ## never been initialised under M13 legitimately has no recorded
  ## branch.
  result.form = "show"
  result.workspaceRoot = parsed.workspaceRoot
  try:
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.branch = recorded.get()
      result.recordedBranch = recorded.get()
  except WorkspaceManifestParseError as err:
    result.recordedBranch = ""
    result.exitCode = 1
    # Surface the parse diagnostic via a synthetic repo entry so
    # ``--json`` callers don't have to scrape stderr.
    result.repos.add(BranchRepoEntry(
      outcome: "metadata_unreadable",
      diagnostic: err.msg))
    return
  # Best-effort project name recovery for the JSON report's
  # ``project`` field. The show form never fails when no project is
  # recoverable; we just leave the field empty.
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if fileExists(workspaceToml):
    try:
      let local = readWorkspaceLocal(absolutePath(workspaceToml))
      if local.workspace.project.len > 0:
        result.project = local.workspace.project
    except WorkspaceManifestParseError:
      discard
  result.exitCode = 0

proc executeBranchCreate(parsed: BranchArgs): BranchReport =
  ## Workspace-wide create planner. Two-pass:
  ##
  ##   1. Observation pass — for every declared repo gather HEAD SHA,
  ##      clean/dirty, and (if the branch already exists) the
  ##      existing branch tip. Classify into:
  ##      ``ready`` (clean, branch absent), ``ready-idempotent`` (clean,
  ##      branch already at HEAD), ``collision`` (branch at a different
  ##      SHA), ``dirty`` (working tree dirty).
  ##
  ##   2. Decision pass — if ANY repo classified as ``dirty`` or
  ##      ``collision`` we refuse-and-report (exit 2). Otherwise we
  ##      schedule ``gitBranchCreate`` actions for the ``ready`` repos
  ##      and produce ``broCreated`` / ``broAlreadyAtHead`` per repo.
  ##
  ## On success the M13 metadata's ``[workspace].branch`` is updated
  ## via ``writeWorkspaceBranch``. We perform the write AFTER the
  ## per-repo plan succeeds so a refuse-and-report leaves the
  ## metadata exactly as it was.
  result.form = "create"
  result.workspaceRoot = parsed.workspaceRoot
  result.branch = parsed.branchName

  let (resolved, _) = resolveBranchProject(parsed)
  result.project = resolved.projectName

  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # Observation pass.
  type
    RepoStateKind = enum
      rsReady, rsReadyIdempotent, rsCollision, rsDirty, rsProbeFailed
    RepoState = object
      kind: RepoStateKind
      repo: ResolvedRepo
      repoPath: string
      headSha: string
      existingSha: string
      reason: string

  var states: seq[RepoState]
  for repo in resolved.repos:
    var state: RepoState
    state.repo = repo
    state.repoPath = parsed.workspaceRoot / repo.path
    if not dirExists(state.repoPath / ".git"):
      state.kind = rsProbeFailed
      state.reason = "no on-disk checkout at '" & state.repoPath &
        "'; run `repro workspace init` or `repro workspace sync` first"
      states.add(state)
      continue
    let headRes = queryGitState(headShaQuery(state.repoPath), identity)
    if headRes.status != gqsOk:
      state.kind = rsProbeFailed
      state.reason = "head-sha probe failed: " & headRes.diagnostic
      states.add(state)
      continue
    state.headSha = headRes.headSha
    let cleanRes = queryGitState(isCleanQuery(state.repoPath), identity)
    if cleanRes.status != gqsOk:
      state.kind = rsProbeFailed
      state.reason = "clean/dirty probe failed: " & cleanRes.diagnostic
      states.add(state)
      continue
    if not cleanRes.isClean:
      state.kind = rsDirty
      state.reason = "working tree has uncommitted changes"
      states.add(state)
      continue
    # Probe whether the branch already exists locally. ``git rev-parse
    # --verify --quiet refs/heads/<name>`` exits 0 + emits the SHA
    # when it does, exits 1 + emits nothing when it does not.
    let probe = gitRunPlain(identity,
      ["-C", state.repoPath, "rev-parse", "--verify", "--quiet",
       "refs/heads/" & parsed.branchName])
    if probe.code == 0:
      let existing = probe.output.strip()
      if existing == state.headSha:
        state.kind = rsReadyIdempotent
        state.existingSha = existing
      elif parsed.checkout:
        # M28 — with ``--checkout`` the operator is asserting "put me ON this
        # branch", which an already-existing branch satisfies. Only the bare
        # create form asserts "make this branch HERE", where a branch at a
        # different SHA is a genuine collision. Nothing is created for this
        # repo; the switch pass below moves it.
        state.kind = rsReadyIdempotent
        state.existingSha = existing
      else:
        state.kind = rsCollision
        state.existingSha = existing
        state.reason = "branch '" & parsed.branchName &
          "' already exists at " & existing & " (≠ HEAD " &
          state.headSha & ")"
    elif probe.output.strip().len == 0:
      state.kind = rsReady
    else:
      state.kind = rsProbeFailed
      state.reason = "git rev-parse --verify exited " & $probe.code &
        ": " & probe.output.strip()
    states.add(state)

  # Decision pass.
  var dirtyCount = 0
  var collisionCount = 0
  var probeFailures = 0
  for state in states:
    case state.kind
    of rsDirty: inc dirtyCount
    of rsCollision: inc collisionCount
    of rsProbeFailed: inc probeFailures
    else: discard

  if probeFailures > 0:
    # Probe failure is a hard error: we cannot reason about the
    # workspace's state at all. Distinct from dirty/collision (which
    # are operator-visible policy outcomes).
    for state in states:
      var entry = BranchRepoEntry(
        name: state.repo.name,
        path: state.repo.path,
        headSha: state.headSha,
        existingSha: state.existingSha)
      case state.kind
      of rsProbeFailed:
        entry.outcome = "probe_failed"
        entry.diagnostic = state.reason
      of rsDirty:
        entry.outcome = branchOutcomeTag(broDirtyRefused)
        entry.dirtyReason = state.reason
      of rsCollision:
        entry.outcome = branchOutcomeTag(broCollisionRefused)
        entry.diagnostic = state.reason
      of rsReady:
        entry.outcome = "ready"
      of rsReadyIdempotent:
        entry.outcome = branchOutcomeTag(broAlreadyAtHead)
      result.repos.add(entry)
    result.exitCode = 1
    # Recorded branch is whatever the metadata currently has.
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  if dirtyCount > 0 or collisionCount > 0:
    # Refuse-and-report. Surface the per-repo classification but
    # mutate nothing — even the clean repos sit untouched so the
    # operator's "fix the blockers and re-run" loop is atomic.
    for state in states:
      var entry = BranchRepoEntry(
        name: state.repo.name,
        path: state.repo.path,
        headSha: state.headSha,
        existingSha: state.existingSha)
      case state.kind
      of rsDirty:
        entry.outcome = branchOutcomeTag(broDirtyRefused)
        entry.dirtyReason = state.reason
      of rsCollision:
        entry.outcome = branchOutcomeTag(broCollisionRefused)
        entry.diagnostic = state.reason
      of rsReady:
        entry.outcome = "ready"
      of rsReadyIdempotent:
        entry.outcome = branchOutcomeTag(broAlreadyAtHead)
      of rsProbeFailed:
        entry.outcome = "probe_failed"
        entry.diagnostic = state.reason
      result.repos.add(entry)
    result.exitCode = 2
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  # Execute pass: schedule a ``gitBranchCreate`` action for every
  # repo classified as ``rsReady``. The idempotent ``rsReadyIdempotent``
  # repos already point their branch at HEAD; the executor would just
  # short-circuit (already-at-head) so we skip scheduling at the
  # planner level too — fewer actions in the engine graph.
  var actions: seq[BuildAction]
  var actionRepoIndex = initTable[string, int]()
  let receiptDir = parsed.workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  for idx, state in states:
    if state.kind != rsReady:
      continue
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("branch-create-" & safeRepoIdSegment(state.repo.name) & "-" &
       $idx & ".receipt")
    let actionId = "workspace-branch-create-" &
      safeRepoIdSegment(state.repo.name) & "-" & $idx
    var action = gitBranchCreate(actionId, identity,
      branchName = parsed.branchName,
      repoPath = state.repo.path,
      receiptPath = receiptRel)
    action.cwd = parsed.workspaceRoot
    actions.add(action)
    actionRepoIndex[actionId] = idx

  var perRepoOutcome = initTable[int, tuple[outcome: BranchRepoOutcome;
                                            diagnostic: string]]()
  if actions.len > 0:
    let cacheRoot = parsed.workspaceRoot / ".repro" / "workspace" /
      "engine-cache"
    var config = defaultBuildEngineConfig(cacheRoot)
    config.suppressTrace = true
    let res = runBuild(graph(actions), config)
    var outcomeById = initTable[string, ActionResult]()
    for outcome in res.results:
      outcomeById[outcome.id] = outcome
    for action in actions:
      let outcome = outcomeById.getOrDefault(action.id)
      let idx = actionRepoIndex[action.id]
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        var diag = "status=" & $outcome.status &
          " reason=" & outcome.reason
        if outcome.stderr.len > 0:
          diag.add(" stderr=" & outcome.stderr)
        perRepoOutcome[idx] = (outcome: broActionFailed, diagnostic: diag)
      else:
        perRepoOutcome[idx] = (outcome: broCreated, diagnostic: "")

  var actionFailures = 0
  for idx, state in states:
    var entry = BranchRepoEntry(
      name: state.repo.name,
      path: state.repo.path,
      headSha: state.headSha,
      existingSha: state.existingSha)
    case state.kind
    of rsReadyIdempotent:
      entry.outcome = branchOutcomeTag(broAlreadyAtHead)
    of rsReady:
      let r = perRepoOutcome.getOrDefault(idx,
        (outcome: broActionFailed,
         diagnostic: "internal: missing action outcome"))
      entry.outcome = branchOutcomeTag(r.outcome)
      entry.diagnostic = r.diagnostic
      if r.outcome == broActionFailed:
        inc actionFailures
    else:
      # Unreachable here (probe-failed and refuse-and-report paths
      # returned early above); keep the case exhaustive so a future
      # state addition stays compile-safe.
      entry.outcome = "internal_unexpected_state"
    result.repos.add(entry)

  if actionFailures > 0:
    # An action failure under the engine is exit 1 (engine blew up),
    # not exit 2 (operator policy). Record the metadata state we
    # actually achieved — none.
    result.exitCode = 1
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  # Metadata update — write only after every per-repo action
  # succeeded (or the idempotent re-run case classified them all as
  # already-at-head).
  try:
    # M28 — creating a branch across EVERY participating repo is what starting
    # a feature means, so record the M16 ``feature_started`` mark here (it used
    # to require a separate verb). The mark is inert until
    # a repo is actually ON the marked branch — it only tells `repro sync` not
    # to fast-forward the workspace branch back to the lock's pins — so setting
    # it on a create that does not switch changes nothing until you check out.
    writeWorkspaceBranchWithStarted(parsed.workspaceRoot,
      project = resolved.projectName, branch = parsed.branchName,
      featureStarted = true)
    result.recordedBranch = parsed.branchName
    result.featureStarted = true
  except WorkspaceManifestParseError as err:
    # We made VCS-level branches; surfacing the metadata-write error
    # as a non-zero exit is the safer signal so the operator notices
    # and reconciles workspace.toml.
    result.exitCode = 1
    result.recordedBranch = ""
    result.repos.add(BranchRepoEntry(
      outcome: "metadata_write_failed",
      diagnostic: err.msg))
    return

  result.exitCode = 0

proc executeBranchCreateAndCheckout(parsed: BranchArgs): BranchReport
  ## M28 forward declaration — defined after ``executeWorkspaceSwitch``, which it
  ## delegates the switch pass to.

proc executeBranchFork(parsed: BranchArgs): BranchReport
  ## M27 forward declaration — the fork engine is defined further down,
  ## after ``resolveSwitchProject`` (which it reuses so the fork resolves
  ## the participating repo set exactly like ``checkout``/``start`` do).

proc branchReportRoot(report: BranchReport): string =
  # M27: in the fork form ``workspaceRoot`` is the NEW workspace, which is
  # where the report belongs. But a fork refused BEFORE materializing (a bad
  # destination, a remote-branch collision) must not conjure that directory
  # into existence just to drop a report in it — fall back to the source.
  result = report.workspaceRoot
  if report.sourceWorkspaceRoot.len > 0 and not dirExists(result / ".git"):
    result = report.sourceWorkspaceRoot

proc writeBranchReport(report: BranchReport; destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runBranchCommand*(args: openArray[string]; verb = "repro branch";
                       requirePath = false): int =
  ## ``repro branch [<path>] [--branch=NAME] [--existing-branch]
  ## [--include-changes] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## ``repro workspace new <path>`` is the same command under the workspace
  ## namespace, invoked with ``requirePath = true`` — see ``parseBranchArgs``.
  ##
  ## See the M14 block comment above for the contract. With
  ## ``--write-report`` it writes a ``branch-report.json`` artifact under
  ## ``<workspaceRoot>/.repro/workspace/`` (or the explicit
  ## ``--write-report=PATH``) so a script consumer has a parseable record of
  ## what happened, in addition to the stdout-formatted text lines.
  ## Without ``--write-report`` nothing is written to disk.
  ##
  ## M27 / WV-6 — when the ``<path>`` positional is present the command
  ## FORKS: it materializes a new workspace there with every repo (and the
  ## workspace root repo) on the branch, cut from THIS workspace's committed
  ## HEADs, leaving the current workspace untouched.
  ##
  ## PS-6 — the new workspace inherits this workspace's enabled PROJECT SET;
  ## ``--projects=A,B`` replaces it. See ``executeBranchFork``.
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo verb & " [<path>] [--branch=NAME] [--existing-branch] " &
      "[--include-changes] [--projects=A,B] [--workspace-root=PATH] " &
      "[--json] [--write-report[=PATH]]"
    echo "  (no argument)     print the current workspace branch"
    echo "  <path>            fork into a NEW workspace directory at <path>;"
    echo "                    the branch is named after the path's basename"
    echo "  --branch=NAME     name the branch something other than the basename"
    echo "  --existing-branch check out an EXISTING branch instead of creating one"
    echo "  --include-changes also copy the source's uncommitted work"
    echo "  --projects=A,B    give the new workspace THIS project set instead"
    echo "                    of inheriting the current one (repeatable)"
    echo ""
    echo "  The new workspace inherits this workspace's enabled projects."
    echo "  To switch THIS workspace onto a branch, use `repro switch`."
    return 0
  let parsed = parseBranchArgs(args, verb, requirePath)
  # WV-6 — two forms only: a destination path forks, no argument shows. The
  # in-place create forms are `repro switch -b`, which reaches
  # ``executeBranchCreateAndCheckout`` on its own.
  if parsed.destinationRefusal.len > 0:
    # A guard that fired before anything was resolved. Reported as a refusal —
    # exit 2, nothing created — not as a usage error, because the operator's
    # command was well-formed and the destination is the thing at fault.
    stderr.writeLine(verb & ": " & parsed.destinationRefusal)
    return 2
  let report =
    if parsed.forkPath.len > 0:
      executeBranchFork(parsed)
    else:
      executeBranchShow(parsed)
  writeBranchReport(report,
    reportDestination(parsed.report, branchReportRoot(report), "branch"))
  stageFailureReport(parsed.report, branchReportRoot(report), "branch",
    report.toJsonNode())
  # The read-only ``show`` form answers a question and must not write anything —
  # the same rule that made the report opt-in. Only the forms that MOVE the
  # workspace refresh the cache, and they leave every repo on the new branch.
  if report.form != "show" and report.repos.len > 0:
    var branches: seq[string]
    for _ in report.repos:
      branches.add(report.recordedBranch)
    writePromptCache(branchReportRoot(report), "branch", branches)
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderBranchTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# --- RA-29: per-repo stash-on-leave / restore-on-return -------------------
#
# CLI/checkout.md's V1 surface "requires a clean workspace — commit, stash,
# or discard changes first". RA-29 makes the *stash* path automatic and
# COHERENT across the workspace: when ``repro switch`` leaves a branch
# with uncommitted work in some repos, each dirty repo's WIP is stashed
# (per-repo, independently) keyed by the branch being LEFT; when a later
# ``repro switch`` RETURNS to that branch, the matching stash is restored
# in each repo. WIP is never lost on a task-switch
# (Workspace-And-Develop-Mode.md — switching tasks is the steady-state loop).
#
# Keying. The stash message is ``repro-checkout:<branch-left>`` so the
# restore on return finds exactly the stash that belongs to that branch and
# never pops an unrelated user stash. Each repo carries its own stash entry
# (git's per-repo stash stack), so the operation is genuinely per-repo:
# repo A's WIP and repo B's WIP round-trip independently.

const reproCheckoutStashPrefix = "repro-checkout:"

proc reproCheckoutStashMessage(branch: string): string =
  reproCheckoutStashPrefix & branch

proc stashRepoWipOnLeave(identity: GitToolIdentity;
                         repoPath, branchLeft: string):
    tuple[ok: bool; diagnostic: string] =
  ## Stash the repo's WIP (tracked + untracked) under a branch-keyed
  ## message so a later return to ``branchLeft`` can restore it. Returns
  ## ``ok=false`` with a diagnostic if the stash push fails (the caller
  ## then refuses, never silently dropping the change).
  let msg = reproCheckoutStashMessage(branchLeft)
  let res = gitRunPlain(identity,
    ["-C", repoPath, "stash", "push", "--include-untracked", "-m", msg])
  if res.code != 0:
    return (ok: false, diagnostic: "git stash push failed: " &
      res.output.strip())
  (ok: true, diagnostic: "")

proc findReproCheckoutStashRef(identity: GitToolIdentity;
                               repoPath, branchReturned: string): string =
  ## Return the ``stash@{N}`` ref whose message is the branch-keyed
  ## ``repro-checkout:<branchReturned>`` marker, or "" if none. We match
  ## the most recent such entry (the stash list is newest-first), so a
  ## leave/return pair round-trips even if other stashes were pushed in
  ## between.
  let wanted = reproCheckoutStashMessage(branchReturned)
  let res = gitRunPlain(identity,
    ["-C", repoPath, "stash", "list", "--format=%gd%x01%gs"])
  if res.code != 0:
    return ""
  for raw in res.output.splitLines():
    let sep = raw.find('\x01')
    if sep < 0:
      continue
    let refName = raw[0 ..< sep]
    var subject = raw[(sep + 1) .. ^1]
    # ``%gs`` renders the reflog subject as ``On <branch>: <message>``;
    # match on the trailing message exactly so we never pop an unrelated
    # stash.
    let colon = subject.find(": ")
    if colon >= 0:
      subject = subject[(colon + 2) .. ^1]
    if subject.strip() == wanted:
      return refName.strip()
  ""

proc restoreRepoWipOnReturn(identity: GitToolIdentity;
                            repoPath, branchReturned: string):
    tuple[restored: bool; diagnostic: string] =
  ## Pop the branch-keyed stash for ``branchReturned`` if one exists.
  ## ``restored=false`` with empty diagnostic means there was nothing to
  ## restore (the common case); a non-empty diagnostic means a stash WAS
  ## found but the pop failed (surfaced, never silently lost).
  let stashRef = findReproCheckoutStashRef(identity, repoPath, branchReturned)
  if stashRef.len == 0:
    return (restored: false, diagnostic: "")
  let res = gitRunPlain(identity, ["-C", repoPath, "stash", "pop", stashRef])
  if res.code != 0:
    return (restored: false, diagnostic: "git stash pop " & stashRef &
      " failed: " & res.output.strip())
  (restored: true, diagnostic: "")

# --- M15 / WV-5: `repro switch <branch>` ---------------------------------
#
# Top-level subcommand per ``reprobuild-specs/CLI/checkout.md``. Same
# convention deviation flagged by M9—M14: the milestone description hints
# at a separate planner module, but the actual implementation lives here
# alongside ``runBranchCommand`` so we reuse the M9/M10/M11/M12/M14
# resolver-and-composer dispatch helpers without a third copy.
#
# Two-pass design (mirrors M14 ``executeBranchCreate``):
#
#   Pass 1 — per-repo observation. For each declared repo gather HEAD
#     SHA, clean/dirty, current branch (so we can detect the no-op
#     ``already-on-branch`` case), local-branch existence, and (if the
#     branch does not exist locally) remote-tracking existence on the
#     standard ``origin`` remote.
#
#     Classification (in priority order):
#       - ``rsRefMissing`` — no on-disk checkout / probe failed.
#       - ``rsDirty`` — working tree has uncommitted changes.
#       - ``rsAlreadyOnBranch`` — clean and ``HEAD`` is the requested
#         branch (no action needed).
#       - ``rsReadyLocal`` — clean, the requested branch already exists
#         as ``refs/heads/<name>`` locally; we can call
#         ``gitSwitchAction`` directly.
#       - ``rsReadyFetchAndTrack`` — clean, branch is absent locally but
#         present on ``origin``; we need ``gitFetchAction`` first, then
#         ``gitSwitchAction`` (git ``switch`` DWIMs the tracking branch
#         when ``refs/remotes/origin/<name>`` is present).
#       - ``rsBranchMissing`` — clean, branch absent both locally AND on
#         every configured remote (refuse).
#
#   Pass 2 — decision. If ANY repo is ``rsBranchMissing``, ``rsDirty``,
#     or ``rsRefMissing`` we refuse-and-report with exit 2 (or exit 1
#     for the probe-failed case) and mutate NOTHING (matching M14's
#     atomicity rule). Otherwise:
#       - ``rsReadyLocal`` repos get a ``gitSwitchAction``.
#       - ``rsReadyFetchAndTrack`` repos get a chained
#         ``gitFetchAction`` then ``gitSwitchAction``. The switch
#         action declares the fetch's receipt as a dep so they run in
#         order in the build graph.
#       - ``rsAlreadyOnBranch`` repos schedule no action.
#     On full success we update ``[workspace].branch`` via
#     ``writeWorkspaceBranch`` so M13 metadata follows the on-disk
#     state.
#
# Exit codes:
#   0 — success (every repo switched / fetched-and-switched /
#       already-on-branch).
#   1 — IO / VCS / probe / engine failure.
#   2 — operator-visible refuse (any dirty repo, OR the requested
#       branch is missing in any repo locally and remotely).
#
# The JSON report at ``<workspaceRoot>/.repro/build/reports/switch-report.json``
# carries the per-repo classification, previous branch, new branch, and
# the post-command ``recordedBranch`` (the M13 metadata value).

type
  SwitchRepoOutcome* = enum
    croSwitched           ## Local branch existed; ``git switch`` ran.
    croFetchedAndSwitched ## Remote-only branch; fetched + tracked.
    croAlreadyOnBranch    ## Already on the requested branch (no-op).
    croDirtyRefused       ## Repo dirty; nothing scheduled.
    croBranchMissingRefused
                          ## Branch absent locally AND on every remote.
    croProbeFailed        ## Pre-pass probe failed for this repo.
    croActionFailed       ## A scheduled action returned non-OK.
    croConfirmRefused     ## RA-9 confirmation refused (non-TTY/declined).
    croStashFailed        ## RA-29 leave-stash failed; nothing scheduled.

  SwitchRepoEntry* = object
    ## Per-repo line in the JSON report. ``previousBranch`` is the
    ## branch the repo was on going into the command (empty when
    ## detached); ``newBranch`` is what it is on after — typically the
    ## requested branch on success, the unchanged ``previousBranch`` on
    ## a refuse.
    name*: string
    path*: string
    headSha*: string
    previousBranch*: string
    newBranch*: string
    outcome*: string
    remoteHadBranch*: bool
    localHadBranch*: bool
    dirtyReason*: string
    diagnostic*: string
    stashedOnLeave*: bool   ## RA-29: WIP was stashed leaving the old branch.
    restoredOnReturn*: bool ## RA-29: a prior stash was restored on return.

  SwitchReport* = object
    ## Structured outcome of one ``repro switch`` invocation.
    ## ``branch`` is the requested branch; ``recordedBranch`` is what
    ## ``[workspace].branch`` carries AFTER the command finished (the
    ## new branch on success, the pre-existing value on refuse).
    project*: string
    workspaceRoot*: string
    branch*: string
    recordedBranch*: string
    repos*: seq[SwitchRepoEntry]
    exitCode*: int

proc switchOutcomeTag(outcome: SwitchRepoOutcome): string =
  case outcome
  of croSwitched: "switched"
  of croFetchedAndSwitched: "fetched_and_switched"
  of croAlreadyOnBranch: "already_on_branch"
  of croDirtyRefused: "dirty_refused"
  of croBranchMissingRefused: "branch_missing_refused"
  of croProbeFailed: "probe_failed"
  of croActionFailed: "action_failed"
  of croConfirmRefused: "confirm_refused"
  of croStashFailed: "stash_failed"

proc toJsonNode*(report: SwitchReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["branch"] = %report.branch
  result["recordedBranch"] = %report.recordedBranch
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["headSha"] = %entry.headSha
    obj["previousBranch"] = %entry.previousBranch
    obj["newBranch"] = %entry.newBranch
    obj["outcome"] = %entry.outcome
    obj["remoteHadBranch"] = %entry.remoteHadBranch
    obj["localHadBranch"] = %entry.localHadBranch
    obj["dirtyReason"] = %entry.dirtyReason
    obj["diagnostic"] = %entry.diagnostic
    obj["stashedOnLeave"] = %entry.stashedOnLeave
    obj["restoredOnReturn"] = %entry.restoredOnReturn
    repos.add(obj)
  result["repos"] = repos
  result["exitCode"] = %report.exitCode

proc renderSwitchTextLines*(report: SwitchReport): seq[string] =
  for entry in report.repos:
    var line = "workspace checkout: " & entry.path & " " & entry.outcome
    if entry.previousBranch.len > 0 and entry.newBranch.len > 0 and
        entry.previousBranch != entry.newBranch:
      line.add(" " & entry.previousBranch & " -> " & entry.newBranch)
    elif entry.newBranch.len > 0:
      line.add(" branch=" & entry.newBranch)
    if entry.stashedOnLeave:
      line.add(" [stashed WIP]")
    if entry.restoredOnReturn:
      line.add(" [restored WIP]")
    if entry.dirtyReason.len > 0:
      line.add(" (" & entry.dirtyReason & ")")
    elif entry.diagnostic.len > 0:
      line.add(" (" & entry.diagnostic & ")")
    result.add(line)
  if report.exitCode == 0:
    result.add("workspace checkout: '" & report.branch &
      "' active across " & $report.repos.len &
      " repos; metadata=" & report.recordedBranch)

type
  SwitchArgs = object
    workspaceRoot: string
    projectName: string
    branchName: string
    newBranch: bool      ## WV-5 ``-b``: create the branch before switching.
    json: bool
    assumeYes: bool      ## RA-9 ``--yes``: skip the per-repo confirmation.
    toolProvisioning: ToolProvisioningMode
    report: ReportSpec   ## Opt-in ``--write-report[=PATH]`` artifact.

proc parseSwitchArgs*(args: openArray[string]): SwitchArgs =
  ## ``repro switch <branch> [-b|--new-branch] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``. The
  ## positional ``<branch>`` is REQUIRED — unlike ``repro branch`` the
  ## argument-less form is not a defined surface.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "-b" or arg == "--new-branch":
      result.newBranch = true
    elif arg == "--json":
      result.json = true
    elif arg == "--yes" or arg == "--force":
      result.assumeYes = true
    elif consumeReportFlag(arg, result.report):
      discard
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro switch` flag: " & arg)
    elif result.branchName.len == 0:
      result.branchName = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro switch`: " & arg)
    inc i
  if result.branchName.len == 0:
    raise newException(ValueError,
      "`repro switch` requires a branch name positional argument")
  result.workspaceRoot = resolveInvokedWorkspaceRoot(result.workspaceRoot)

proc resolveSwitchProject(parsed: SwitchArgs):
    tuple[resolved: ResolvedProject;
          workspaceLocal: Option[WorkspaceLocal]] =
  ## Same dispatch rule as M14 ``resolveBranchProject``: composer mode
  ## when ``.repo/workspace.toml`` declares ``[[manifest]]`` layers,
  ## single-project mode otherwise. The single-project path recovers
  ## the project name from a metadata-only workspace.toml's
  ## ``[workspace].project`` field (the M13 schema).
  let workspaceToml = workspaceTomlPath(parsed.workspaceRoot)
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    let absToml = absolutePath(workspaceToml)
    let workspaceLocal = readWorkspaceLocal(absToml)
    let resolved = extendWithActiveProjectSet(parsed.workspaceRoot,
      composeManifestLayers(workspaceLocal, parsed.workspaceRoot, absToml))
    return (resolved, some(workspaceLocal))
  var projectName = parsed.projectName
  # PS-2 — ``repro switch`` switches the WHOLE workspace, so with no
  # explicit project argument every repo of the active project set switches.
  let membershipFromMetadata = parsed.projectName.len == 0
  if projectName.len == 0 and fileExists(workspaceToml):
    try:
      let recorded =
        readWorkspaceLocal(absolutePath(workspaceToml)).workspace.project
      if recorded.len > 0:
        projectName = recorded
    except WorkspaceManifestParseError:
      discard
  if projectName.len == 0:
    raise newException(ValueError,
      "this command requires either `.repro/workspace.toml` " &
        "or a project name recoverable from one; neither was present at " &
        parsed.workspaceRoot)
  let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
  let projectFile = manifestsRoot / "projects" / (projectName & ".toml")
  let variantFile = manifestsRoot / "variants" / (projectName & ".toml")
  proc withSet(resolved: ResolvedProject): ResolvedProject =
    if membershipFromMetadata:
      extendWithActiveProjectSet(parsed.workspaceRoot, resolved)
    else: resolved
  if fileExists(projectFile):
    return (withSet(resolveProject(projectFile)), none(WorkspaceLocal))
  if fileExists(variantFile):
    return (withSet(resolveVariant(variantFile)), none(WorkspaceLocal))
  raise newException(ValueError,
    "no project or variant named '" & projectName &
      "' found under '" & manifestsRoot &
      "' (looked for '" & projectFile & "' and '" & variantFile & "')")

proc executeWorkspaceSwitch(parsed: SwitchArgs): SwitchReport =
  result.workspaceRoot = parsed.workspaceRoot
  result.branch = parsed.branchName

  let (resolved, _) = resolveSwitchProject(parsed)
  result.project = resolved.projectName

  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # Observation pass.
  type
    RepoStateKind = enum
      rsReadyLocal, rsReadyFetchAndTrack, rsAlreadyOnBranch,
      rsBranchMissing, rsDirty, rsProbeFailed
    RepoState = object
      kind: RepoStateKind
      repo: ResolvedRepo
      repoPath: string
      headSha: string
      previousBranch: string
      localHadBranch: bool
      remoteHadBranch: bool
      needsStash: bool      ## RA-29: dirty on leave → stash before switch.
      reason: string

  var states: seq[RepoState]
  for repo in resolved.repos:
    var state: RepoState
    state.repo = repo
    state.repoPath = parsed.workspaceRoot / repo.path
    if not dirExists(state.repoPath / ".git"):
      state.kind = rsProbeFailed
      state.reason = "no on-disk checkout at '" & state.repoPath &
        "'; run `repro workspace init` or `repro workspace sync` first"
      states.add(state)
      continue
    let headRes = queryGitState(headShaQuery(state.repoPath), identity)
    if headRes.status != gqsOk:
      state.kind = rsProbeFailed
      state.reason = "head-sha probe failed: " & headRes.diagnostic
      states.add(state)
      continue
    state.headSha = headRes.headSha
    # Current branch (empty when detached). ``symbolic-ref --short -q``
    # prints the branch name and exits non-zero in the detached state
    # rather than emitting an error to stderr.
    let branchRes = gitRunPlain(identity,
      ["-C", state.repoPath, "symbolic-ref", "--short", "-q", "HEAD"])
    if branchRes.code == 0:
      state.previousBranch = branchRes.output.strip()
    let cleanRes = queryGitState(isCleanQuery(state.repoPath), identity)
    if cleanRes.status != gqsOk:
      state.kind = rsProbeFailed
      state.reason = "clean/dirty probe failed: " & cleanRes.diagnostic
      states.add(state)
      continue
    if not cleanRes.isClean:
      # RA-29: a dirty repo no longer REFUSES the checkout. We mark it for
      # a per-repo stash-on-leave (keyed by the branch being left) so the
      # WIP is preserved and restored when the operator returns to this
      # branch. The stash only happens if the repo will actually SWITCH
      # (i.e. not the already-on-branch no-op below), so we just record
      # the intent here and let the branch-availability probes proceed.
      state.needsStash = true
    # No-op short circuit: already on the requested branch.
    if state.previousBranch == parsed.branchName:
      state.kind = rsAlreadyOnBranch
      state.localHadBranch = true
      states.add(state)
      continue
    # Probe local branch.
    let localProbe = gitRunPlain(identity,
      ["-C", state.repoPath, "rev-parse", "--verify", "--quiet",
       "refs/heads/" & parsed.branchName])
    if localProbe.code == 0 and localProbe.output.strip().len > 0:
      state.localHadBranch = true
      state.kind = rsReadyLocal
      states.add(state)
      continue
    if localProbe.code != 0 and localProbe.output.strip().len != 0:
      # Genuine probe failure (not just "missing ref"): bail.
      state.kind = rsProbeFailed
      state.reason = "git rev-parse --verify exited " &
        $localProbe.code & ": " & localProbe.output.strip()
      states.add(state)
      continue
    # Local branch missing — probe the configured remote. We ask
    # ``git ls-remote --heads <remote> <branch>`` rather than relying
    # on the remote-tracking ref (which may be stale) so we get a
    # truthful answer even before any fetch. The standard remote name
    # after ``git clone`` is ``origin``.
    let remoteName =
      gitRemoteNameFor(repo)
    let lsRemote = gitRunPlain(identity,
      ["-C", state.repoPath, "ls-remote", "--heads", remoteName,
       parsed.branchName])
    if lsRemote.code != 0:
      # Network / config failure: treat as probe-failed so the
      # operator sees the real diagnostic rather than a misleading
      # "branch missing" verdict.
      state.kind = rsProbeFailed
      state.reason = "git ls-remote --heads " & remoteName & " " &
        parsed.branchName & " exited " & $lsRemote.code & ": " &
        lsRemote.output.strip()
      states.add(state)
      continue
    if lsRemote.output.strip().len == 0:
      state.kind = rsBranchMissing
      # Principle 2: name the offending repo + missing branch AND a concrete
      # remedy — create the branch across the workspace first, then checkout.
      state.reason = "branch '" & parsed.branchName &
        "' is absent locally and not present on remote '" &
        remoteName & "' in repo '" & repo.path &
        "' — run 'repro branch " & parsed.branchName &
        "' to create it across the workspace (or 'repro start " &
        parsed.branchName & "')"
      states.add(state)
      continue
    state.remoteHadBranch = true
    state.kind = rsReadyFetchAndTrack
    states.add(state)

  # Decision pass. RA-29: a dirty repo NO LONGER refuses the checkout — its
  # WIP is stashed on leave (and restored on return), so the only refuse
  # conditions are a missing branch or a probe failure. (``rsDirty`` is no
  # longer produced; the branch is kept in the case-matches for safety.)
  var dirtyCount = 0
  var missingCount = 0
  var probeFailures = 0
  for state in states:
    case state.kind
    of rsDirty: inc dirtyCount
    of rsBranchMissing: inc missingCount
    of rsProbeFailed: inc probeFailures
    else: discard

  if probeFailures > 0 or dirtyCount > 0 or missingCount > 0:
    # Refuse-and-report path: mutate nothing, surface the per-repo
    # classification. ``rsReadyLocal`` / ``rsReadyFetchAndTrack`` repos
    # report ``ready_*`` (the work was scheduled-then-cancelled by the
    # decision pass) rather than the post-success tag.
    for state in states:
      var entry = SwitchRepoEntry(
        name: state.repo.name,
        path: state.repo.path,
        headSha: state.headSha,
        previousBranch: state.previousBranch,
        remoteHadBranch: state.remoteHadBranch,
        localHadBranch: state.localHadBranch)
      case state.kind
      of rsAlreadyOnBranch:
        entry.outcome = switchOutcomeTag(croAlreadyOnBranch)
        entry.newBranch = parsed.branchName
      of rsDirty:
        entry.outcome = switchOutcomeTag(croDirtyRefused)
        entry.dirtyReason = state.reason
        entry.newBranch = state.previousBranch
      of rsBranchMissing:
        entry.outcome = switchOutcomeTag(croBranchMissingRefused)
        entry.diagnostic = state.reason
        entry.newBranch = state.previousBranch
      of rsProbeFailed:
        entry.outcome = switchOutcomeTag(croProbeFailed)
        entry.diagnostic = state.reason
        entry.newBranch = state.previousBranch
      of rsReadyLocal:
        entry.outcome = "ready_local"
        entry.newBranch = state.previousBranch
      of rsReadyFetchAndTrack:
        entry.outcome = "ready_fetch_and_track"
        entry.newBranch = state.previousBranch
      result.repos.add(entry)
    result.exitCode =
      if probeFailures > 0: 1
      else: 2
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  # RA-9 destructive-command safety: ``checkout`` switches every
  # participating repo's working tree, so PREVIEW the per-repo
  # ``current -> target`` change and CONFIRM before mutating anything.
  # ``--yes`` opts out; a non-interactive context without it REFUSES
  # cleanly (non-zero, naming the flag) rather than hanging on a prompt.
  # Only the repos that would actually switch (``rsReadyLocal`` /
  # ``rsReadyFetchAndTrack``) are previewed — an all-``already_on_branch``
  # checkout is a no-op and skips the gate entirely.
  var switchPreview: seq[string]
  for state in states:
    if state.kind in {rsReadyLocal, rsReadyFetchAndTrack}:
      let from0 =
        if state.previousBranch.len > 0: state.previousBranch
        else: "(detached)"
      switchPreview.add("  " & state.repo.path & ": " & from0 &
        " -> " & parsed.branchName &
        (if state.kind == rsReadyFetchAndTrack: " (fetch+track)" else: "") &
        (if state.needsStash: " (stash WIP)" else: ""))
  if switchPreview.len > 0:
    stderr.writeLine("repro switch will switch " & $switchPreview.len &
      " repo(s) to '" & parsed.branchName & "':")
    for line in switchPreview:
      stderr.writeLine(line)
    let decision = confirmDestructive(
      prompt = "Switch the repo(s) above to '" & parsed.branchName &
        "'? [y/N] ",
      autoYes = parsed.assumeYes,
      isTty = isatty(stdin),
      flagName = "--yes",
      refuseMessage = "refusing to checkout in a non-interactive context " &
        "without --yes (would switch the working tree of " &
        $switchPreview.len & " repo(s))",
      declineMessage = "checkout declined; no repo switched")
    if decision != ddConfirmed:
      # Refuse-and-report: mutate nothing, surface the per-repo
      # classification just like the dirty/missing refuse path above.
      for state in states:
        var entry = SwitchRepoEntry(
          name: state.repo.name,
          path: state.repo.path,
          headSha: state.headSha,
          previousBranch: state.previousBranch,
          newBranch: state.previousBranch,
          remoteHadBranch: state.remoteHadBranch,
          localHadBranch: state.localHadBranch)
        case state.kind
        of rsAlreadyOnBranch:
          entry.outcome = switchOutcomeTag(croAlreadyOnBranch)
          entry.newBranch = parsed.branchName
        of rsReadyLocal, rsReadyFetchAndTrack:
          entry.outcome = switchOutcomeTag(croConfirmRefused)
          # RA-28 Principle 2: the per-repo diagnostic must NAME the offender
          # (this repo + the working-tree switch that requires confirmation,
          # plus the WIP-stash it would trigger when dirty) AND a concrete,
          # copy-pasteable remedy command. The switch of a working tree is the
          # destructive act being gated, so the offender is this repo's path.
          let from0 =
            if state.previousBranch.len > 0: state.previousBranch
            else: "(detached)"
          let stashNote =
            if state.needsStash:
              " (its uncommitted WIP would be stashed on leave)"
            else: ""
          let cause =
            if decision == ddRefusedNonTty:
              "non-interactive context without --yes"
            else: "operator declined"
          entry.diagnostic =
            "refused: switching repo '" & state.repo.path & "' from '" &
            from0 & "' to '" & parsed.branchName & "'" & stashNote &
            " requires confirmation (" & cause &
            ") — re-run 'repro switch " & parsed.branchName &
            " --yes' to confirm"
        else:
          entry.outcome = "internal_unexpected_state"
        result.repos.add(entry)
      result.exitCode = 2
      let recorded = readWorkspaceBranch(parsed.workspaceRoot)
      if recorded.isSome:
        result.recordedBranch = recorded.get()
      return

  # Execute pass: schedule a ``gitFetchAction`` (for the
  # fetch-and-track group) chained to a ``gitSwitchAction``, and a
  # bare ``gitSwitchAction`` for the local-ready group. The
  # ``rsAlreadyOnBranch`` repos schedule no action — the executor
  # would refuse to no-op a ``switch`` to the current branch with
  # any noisier diagnostic than necessary, so we just skip it.
  # RA-29 stash-on-leave: a dirty repo that is about to SWITCH gets its WIP
  # stashed FIRST (keyed by the branch being left) so the tree is clean for
  # the switch and the change is recoverable on return. If the stash itself
  # fails we record ``croStashFailed`` and do NOT schedule that repo's
  # switch — WIP is never dropped on the floor. Repos that are already on
  # the branch (no leave) or clean are untouched.
  var stashFailure = initTable[int, string]()
  var stashedOnLeave = initTable[int, bool]()
  for idx, state in states:
    if state.needsStash and state.kind in {rsReadyLocal, rsReadyFetchAndTrack}:
      let leftBranch =
        if state.previousBranch.len > 0: state.previousBranch
        else: state.headSha   # detached HEAD: key by the commit we leave.
      let st = stashRepoWipOnLeave(identity, state.repoPath, leftBranch)
      if not st.ok:
        stashFailure[idx] = st.diagnostic
      else:
        stashedOnLeave[idx] = true

  var actions: seq[BuildAction]
  var switchActionByIdx = initTable[int, string]()
  let receiptDir = parsed.workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  for idx, state in states:
    if stashFailure.hasKey(idx):
      # Stash failed for this repo — skip scheduling its switch; the
      # outcome loop below reports ``croStashFailed`` and fails the run.
      continue
    case state.kind
    of rsReadyLocal:
      let receiptRel = ".repro" / "workspace" / "receipts" /
        ("checkout-switch-" & safeRepoIdSegment(state.repo.name) &
         "-" & $idx & ".receipt")
      let actionId = "workspace-checkout-switch-" &
        safeRepoIdSegment(state.repo.name) & "-" & $idx
      var action = gitSwitchAction(actionId, identity,
        branchName = parsed.branchName,
        repoPath = state.repo.path,
        receiptPath = receiptRel)
      action.cwd = parsed.workspaceRoot
      actions.add(action)
      switchActionByIdx[idx] = actionId
    of rsReadyFetchAndTrack:
      let fetchReceiptRel = ".repro" / "workspace" / "receipts" /
        ("checkout-fetch-" & safeRepoIdSegment(state.repo.name) &
         "-" & $idx & ".receipt")
      let fetchActionId = "workspace-checkout-fetch-" &
        safeRepoIdSegment(state.repo.name) & "-" & $idx
      let rName = gitRemoteNameFor(state.repo)
      var fetchAction = gitFetchAction(fetchActionId, identity,
        remoteName = rName,
        repoPath = state.repo.path,
        receiptPath = fetchReceiptRel)
      fetchAction.cwd = parsed.workspaceRoot
      actions.add(fetchAction)
      let switchReceiptRel = ".repro" / "workspace" / "receipts" /
        ("checkout-switch-" & safeRepoIdSegment(state.repo.name) &
         "-" & $idx & ".receipt")
      let switchActionId = "workspace-checkout-switch-" &
        safeRepoIdSegment(state.repo.name) & "-" & $idx
      # The switch declares the fetch action's id as a dep so the
      # engine orders them. ``git switch`` DWIMs the tracking branch
      # off the ``origin/<name>`` ref the fetch just populated.
      var switchAction = gitSwitchAction(switchActionId, identity,
        branchName = parsed.branchName,
        repoPath = state.repo.path,
        receiptPath = switchReceiptRel,
        deps = @[fetchActionId])
      switchAction.cwd = parsed.workspaceRoot
      actions.add(switchAction)
      switchActionByIdx[idx] = switchActionId
    else:
      discard

  var perRepoOutcome = initTable[int, tuple[outcome: SwitchRepoOutcome;
                                            diagnostic: string]]()
  if actions.len > 0:
    let cacheRoot = parsed.workspaceRoot / ".repro" / "workspace" /
      "engine-cache"
    var config = defaultBuildEngineConfig(cacheRoot)
    config.suppressTrace = true
    let res = runBuild(graph(actions), config)
    var outcomeById = initTable[string, ActionResult]()
    for outcome in res.results:
      outcomeById[outcome.id] = outcome
    for idx, state in states:
      if not switchActionByIdx.hasKey(idx):
        continue
      let switchId = switchActionByIdx[idx]
      let outcome = outcomeById.getOrDefault(switchId)
      if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
        var diag = "status=" & $outcome.status &
          " reason=" & outcome.reason
        if outcome.stderr.len > 0:
          diag.add(" stderr=" & outcome.stderr)
        perRepoOutcome[idx] = (outcome: croActionFailed, diagnostic: diag)
      else:
        let tag =
          if state.kind == rsReadyFetchAndTrack: croFetchedAndSwitched
          else: croSwitched
        perRepoOutcome[idx] = (outcome: tag, diagnostic: "")

  # RA-29 restore-on-return: a repo that successfully switched TO the
  # requested branch may have a prior ``repro-checkout:<branch>`` stash
  # (left the last time this branch was checked out away from). Pop it so
  # the WIP reappears. Done after the switch (clean tree at switch time),
  # per-repo (each repo finds its own keyed stash).
  var restoredOnReturn = initTable[int, bool]()
  for idx, state in states:
    if state.kind notin {rsReadyLocal, rsReadyFetchAndTrack}:
      continue
    if not perRepoOutcome.hasKey(idx):
      continue   # stash-on-leave failed → no switch happened, no restore.
    let r = perRepoOutcome[idx]
    if r.outcome in {croSwitched, croFetchedAndSwitched}:
      let rest = restoreRepoWipOnReturn(identity, state.repoPath,
        parsed.branchName)
      if rest.restored:
        restoredOnReturn[idx] = true
      elif rest.diagnostic.len > 0:
        # A stash WAS found but the pop failed (e.g. a conflict). Surface
        # it as a failure rather than silently leaving the stash stuck.
        perRepoOutcome[idx] = (outcome: croActionFailed,
          diagnostic: "restore-on-return: " & rest.diagnostic)

  var actionFailures = 0
  for idx, state in states:
    var entry = SwitchRepoEntry(
      name: state.repo.name,
      path: state.repo.path,
      headSha: state.headSha,
      previousBranch: state.previousBranch,
      remoteHadBranch: state.remoteHadBranch,
      localHadBranch: state.localHadBranch,
      stashedOnLeave: stashedOnLeave.getOrDefault(idx, false),
      restoredOnReturn: restoredOnReturn.getOrDefault(idx, false))
    case state.kind
    of rsAlreadyOnBranch:
      entry.outcome = switchOutcomeTag(croAlreadyOnBranch)
      entry.newBranch = parsed.branchName
    of rsReadyLocal, rsReadyFetchAndTrack:
      if stashFailure.hasKey(idx):
        # RA-29: the leave-stash failed; this repo did not switch. WIP is
        # still in place (we never touched the tree), but the operator must
        # resolve it. Refuse this repo with a non-zero exit.
        entry.outcome = switchOutcomeTag(croStashFailed)
        entry.dirtyReason =
          "could not stash WIP before leaving '" & state.previousBranch &
          "': " & stashFailure[idx]
        entry.newBranch = state.previousBranch
        inc actionFailures
      else:
        let r = perRepoOutcome.getOrDefault(idx,
          (outcome: croActionFailed,
           diagnostic: "internal: missing action outcome"))
        entry.outcome = switchOutcomeTag(r.outcome)
        entry.diagnostic = r.diagnostic
        entry.newBranch =
          if r.outcome == croActionFailed: state.previousBranch
          else: parsed.branchName
        if r.outcome == croActionFailed:
          inc actionFailures
    else:
      # Unreachable: refuse / probe-failed paths returned early above.
      entry.outcome = "internal_unexpected_state"
      entry.newBranch = state.previousBranch
    result.repos.add(entry)

  if actionFailures > 0:
    result.exitCode = 1
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  # Metadata update — only after every per-repo action succeeded.
  # M16: the feature-started mark is a per-workspace flag tied to the
  # CURRENT recorded branch. Switching to a different branch implicitly
  # leaves the "started" feature, so the mark is CLEARED unless the
  # checkout target matches the branch that was already marked started
  # (the no-op-style re-checkout case, where we keep the mark).
  var preserveStartedMark = false
  try:
    if readWorkspaceFeatureStarted(parsed.workspaceRoot):
      let recordedBranch = readWorkspaceBranch(parsed.workspaceRoot)
      if recordedBranch.isSome and recordedBranch.get() == parsed.branchName:
        preserveStartedMark = true
  except WorkspaceManifestParseError:
    preserveStartedMark = false
  try:
    writeWorkspaceBranchWithStarted(parsed.workspaceRoot,
      project = resolved.projectName, branch = parsed.branchName,
      featureStarted = preserveStartedMark)
    result.recordedBranch = parsed.branchName
  except WorkspaceManifestParseError as err:
    result.exitCode = 1
    result.recordedBranch = ""
    result.repos.add(SwitchRepoEntry(
      outcome: "metadata_write_failed",
      diagnostic: err.msg))
    return

  result.exitCode = 0

proc writeSwitchReport(report: SwitchReport; destination: string) =
  ## Opt-in: writes only when ``--write-report[=PATH]`` supplied a destination.
  if destination.len == 0:
    return
  createDir(parentDir(destination))
  writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")

proc runSwitchCommand*(args: openArray[string]): int =
  ## ``repro switch <branch> [-b|--new-branch] [--workspace-root=PATH]
  ## [--tool-provisioning=path|nix|tarball|scoop] [--json]``.
  ##
  ## See the M15 block comment above for the contract. With ``--write-report``
  ## it writes a ``switch-report.json`` artifact under
  ## ``<workspaceRoot>/.repro/workspace/`` (or the explicit
  ## ``--write-report=PATH``) so a script consumer has a parseable record of
  ## what happened, in addition to the stdout-formatted text lines.
  ## Without ``--write-report`` nothing is written to disk.
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo "repro switch <branch> [-b|--new-branch] [--yes] " &
      "[--workspace-root=PATH] [--json] [--write-report[=PATH]]"
    echo "  <branch>          switch every participating repo onto <branch>,"
    echo "                    stashing and restoring per-repo work in progress"
    echo "  -b, --new-branch  create <branch> across every repo first"
    echo "  --yes, --force    skip the per-repo confirmation preview"
    echo ""
    echo "  To fork a NEW workspace directory instead, use `repro branch`."
    return 0
  let parsed = parseSwitchArgs(args)

  # WV-5 ``-b`` — create the branch across every participating repo, then
  # switch onto it. The create-then-switch engine is M28's: one operation, one
  # decision tree, so ``-b`` cannot drift from what the fork form does about
  # dirty repos, collisions, and the M16 feature mark. The BranchReport it
  # returns is written under THIS verb's name, because the run the operator
  # asked for is a switch.
  if parsed.newBranch:
    let branchParsed = BranchArgs(
      workspaceRoot: parsed.workspaceRoot,
      projectName: parsed.projectName,
      branchName: parsed.branchName,
      checkout: true,
      json: parsed.json,
      toolProvisioning: parsed.toolProvisioning,
      report: parsed.report)
    var created = executeBranchCreateAndCheckout(branchParsed)
    created.form = "create_and_switch"
    writeBranchReport(created,
      reportDestination(parsed.report, branchReportRoot(created), "switch"))
    stageFailureReport(parsed.report, branchReportRoot(created), "switch",
      created.toJsonNode())
    if created.repos.len > 0:
      var branches: seq[string]
      for _ in created.repos:
        branches.add(created.recordedBranch)
      writePromptCache(branchReportRoot(created), "switch", branches)
    if parsed.json:
      stdout.writeLine(pretty(created.toJsonNode(), indent = 2))
    else:
      for line in renderBranchTextLines(created):
        stdout.writeLine(line)
    return created.exitCode

  let report = executeWorkspaceSwitch(parsed)
  writeSwitchReport(report,
    reportDestination(parsed.report, report.workspaceRoot, "switch"))
  stageFailureReport(parsed.report, report.workspaceRoot, "switch",
    report.toJsonNode())
  block:
    var branches: seq[string]
    for entry in report.repos:
      branches.add(entry.newBranch)
    writePromptCache(report.workspaceRoot, "switch", branches)
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderSwitchTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# --- RA-22: `repro add <repo>` (workspace membership / develop-mode policy) -
#
# Per CLI/add.md §"Develop-Mode Policy" + Workspace-And-Develop-Mode.md
# §"Workspace Membership": `repro add` is the single verb for bringing a
# dependency into the workspace. Whether the dependency materializes as a
# DEVELOP-mode local sibling checkout (a `depends`-graph repo fragment that is
# cloned) or a BINARY pinned dependency (recorded but NOT checked out) is
# decided by POLICY, with `--develop`/`--binary` per-invocation overrides.
#
# The policy default is DATA, never a hardcoded org: the RA-8 host bootstrap
# config's `[develop] org_urls` lists fetch-URL prefixes whose repos default
# to develop mode; everything else defaults to binary. An explicit, NON-default
# `--no-membership` mode clones a repo WITHOUT making it a workspace
# dependency (useful to inspect a repo you don't intend to depend on).

type
  AddMode = enum
    amPolicy        ## decide develop vs binary from the bootstrap policy.
    amDevelop       ## `--develop`: force a local sibling checkout.
    amBinary        ## `--binary` / `--no-develop`: force a pinned artifact.
    amNoMembership  ## `--no-membership`: clone WITHOUT adding a dependency.

  AddArgs = object
    workspaceRoot: string
    projectName: string
    target: string            ## repo NAME to add (a logical dependency).
    remoteUrl: string         ## fetch URL (drives the develop/binary policy).
    revision: string          ## revision/branch pin (defaults to project default).
    dependsOf: string         ## optional repo whose `depends` gains the new edge.
    mode: AddMode
    dryRun: bool
    json: bool
    toolProvisioning: ToolProvisioningMode

  AddReport* = object
    project*: string
    workspaceRoot*: string
    target*: string
    resolvedMode*: string     ## ``develop`` / ``binary`` / ``no-membership``.
    policyDefault*: string    ## the policy's default before any override.
    overridden*: bool         ## whether a flag overrode the policy default.
    checkedOut*: bool         ## whether a sibling checkout was created.
    declarationChanged*: bool
    dependsEdgeOn*: string    ## the repo whose `depends` gained an edge, if any.
    diagnostic*: string
    exitCode*: int

proc toJsonNode*(report: AddReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["target"] = %report.target
  result["resolvedMode"] = %report.resolvedMode
  result["policyDefault"] = %report.policyDefault
  result["overridden"] = %report.overridden
  result["checkedOut"] = %report.checkedOut
  result["declarationChanged"] = %report.declarationChanged
  result["dependsEdgeOn"] = %report.dependsEdgeOn
  result["diagnostic"] = %report.diagnostic
  result["exitCode"] = %report.exitCode

proc parseAddArgs*(args: openArray[string]): AddArgs =
  ## ``repro add <repo> --remote=URL [--revision=R] [--develop|--binary|
  ## --no-develop|--no-membership] [--depends-of=REPO] [--workspace-root=PATH]
  ## [--dry-run] [--json] [--tool-provisioning=...]``.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  result.mode = amPolicy
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--remote" or arg.startsWith("--remote="):
      result.remoteUrl = valueFromFlag(args, i, "--remote")
    elif arg == "--revision" or arg.startsWith("--revision="):
      result.revision = valueFromFlag(args, i, "--revision")
    elif arg == "--depends-of" or arg.startsWith("--depends-of="):
      result.dependsOf = valueFromFlag(args, i, "--depends-of")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--develop":
      result.mode = amDevelop
    elif arg == "--binary" or arg == "--no-develop":
      result.mode = amBinary
    elif arg == "--no-membership":
      result.mode = amNoMembership
    elif arg == "--dry-run":
      result.dryRun = true
    elif arg == "--json":
      result.json = true
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro add` flag: " & arg)
    elif result.target.len == 0:
      result.target = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro add`: " & arg)
    inc i
  if result.target.len == 0:
    raise newException(ValueError,
      "`repro add` requires a repo name positional argument")
  if result.remoteUrl.len == 0:
    raise newException(ValueError,
      "`repro add` requires `--remote=<fetch-url>` so the develop-vs-binary " &
        "policy can classify the dependency's origin")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveAddProject(parsed: AddArgs): ResolvedProject =
  ## MO-10 — delegates the single-project resolution to the shared
  ## ``resolveWorkspaceProjectShared`` ladder (collapsed from the former
  ## per-command copy). ``add`` MUTATES the owning project file, so it keeps
  ## its mutation-specific guard: a compositional (multi-layer) workspace has
  ## no single owning file to append the new include to, so it is refused here
  ## BEFORE delegating (the shared ladder would otherwise compose the layers).
  ## For the non-compositional path the shared ladder resolves the named
  ## project / variant (or the project recorded in a metadata-only
  ## workspace.toml) identically to the old projects-only copy for every
  ## manifest-present workspace.
  if isCompositionalWorkspaceToml(parsed.workspaceRoot):
    raise newException(ValueError,
      "`repro add` is not supported in a compositional (multi-layer) " &
        "workspace; add the repo to the owning manifest layer directly")
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro add <repo>`").resolved

proc developPolicyMatches(remoteUrl: string; workspaceRoot: string): bool =
  ## RA-22 develop-vs-binary POLICY DEFAULT. The decision is driven ENTIRELY
  ## by the RA-8 host bootstrap config's ``[develop] org_urls`` prefix list —
  ## there is NO hardcoded org name in the binary. A dependency whose fetch
  ## URL begins with one of the configured prefixes defaults to develop mode;
  ## everything else (and the case of no config / empty list) defaults to
  ## binary. The config is located with the same ``findBootstrapConfigPath``
  ## resolution ``init`` uses (``REPRO_WORKSPACE_CONFIG`` or an ancestor
  ## ``.repro-workspace.toml``).
  let configPath = findBootstrapConfigPath(workspaceRoot)
  if configPath.len == 0:
    return false
  let cfg = readWorkspaceBootstrap(configPath)
  for prefix in cfg.develop.org_urls:
    if prefix.len > 0 and remoteUrl.startsWith(prefix):
      return true
  false

proc ensureRemoteEntry(projectFile, remoteName, fetchUrl: string) =
  ## Append a ``[[remote]]`` entry naming ``fetchUrl`` if the project file
  ## does not already declare a remote with that name. The new entry is
  ## inserted right before the ``includes = [`` array so it sits with the
  ## other remotes; when no includes array is present it is appended.
  let content = readFile(projectFile)
  if ("name = \"" & remoteName & "\"") in content:
    return
  let remoteBlock = "[[remote]]\nname = \"" & remoteName & "\"\nfetch = \"" &
    fetchUrl & "\"\n\n"
  let idx = content.find("includes")
  if idx >= 0:
    writeFile(projectFile, content[0 ..< idx] & remoteBlock & content[idx .. ^1])
  else:
    writeFile(projectFile, content & "\n" & remoteBlock)

proc appendFragmentInclude(projectFile, includePath: string): bool =
  ## Append ``"<includePath>",`` to the project's ``includes = [ … ]`` array.
  ## Returns true when the include was added; false when it was already
  ## present (idempotent). The append preserves the existing array entries.
  let content = readFile(projectFile)
  let quoted = "\"" & includePath & "\""
  if quoted in content:
    return false
  var outLines: seq[string]
  var inserted = false
  for line in content.splitLines():
    # Insert before the closing ``]`` of the includes array. The closing
    # bracket sits alone on its own line in the canonical multi-line form.
    if not inserted and line.strip() == "]":
      outLines.add("  " & quoted & ",")
      inserted = true
    outLines.add(line)
  if not inserted:
    # No multi-line includes array to extend — append a fresh one.
    outLines.add("")
    outLines.add("includes = [")
    outLines.add("  " & quoted & ",")
    outLines.add("]")
  writeFile(projectFile, outLines.join("\n"))
  true

proc addDependsEdge(fragmentPath, depName: string): bool =
  ## Add ``depName`` to the ``depends`` array of the repo fragment at
  ## ``fragmentPath`` (RA-21 develop-set edge). Returns true when the edge
  ## was added; false when it was already present. Rewrites/creates the
  ## ``depends = [ … ]`` inline array under ``[repo]``.
  let content = readFile(fragmentPath)
  var lines = content.splitLines()
  var dependsIdx = -1
  for idx, line in lines:
    if line.strip().startsWith("depends"):
      dependsIdx = idx
      break
  if dependsIdx >= 0:
    let line = lines[dependsIdx]
    if ("\"" & depName & "\"") in line:
      return false
    let open = line.find('[')
    let close = line.rfind(']')
    if open < 0 or close < 0 or close <= open:
      raise newException(ValueError,
        "malformed `depends` array in fragment: " & fragmentPath)
    let inner = line[open + 1 ..< close].strip()
    let newInner =
      if inner.len == 0: "\"" & depName & "\""
      else: inner & ", \"" & depName & "\""
    lines[dependsIdx] = line[0 .. open] & newInner & line[close .. ^1]
    writeFile(fragmentPath, lines.join("\n"))
    return true
  # No `depends` key yet — append one to the `[repo]` table. The fragment's
  # `[repo]` table is the last table in the file, so a trailing append lands
  # inside it.
  var trimmed = content
  while trimmed.len > 0 and trimmed[^1] in {'\n', '\r'}:
    trimmed.setLen(trimmed.len - 1)
  writeFile(fragmentPath,
    trimmed & "\ndepends = [\"" & depName & "\"]\n")
  true

proc appendBinaryDependency(projectFile, name, remoteUrl, revision: string):
    bool =
  ## Record a BINARY-mode dependency in the project manifest as a
  ## ``[[binary_dependency]]`` entry. A binary dependency is NEVER an
  ## ``includes`` repo fragment, so it is never cloned, synced, or part of
  ## the checkout GC graph. Returns true when the entry was added; false when
  ## an entry of the same name already existed (idempotent).
  let content = readFile(projectFile)
  if ("name = \"" & name & "\"") in content and
      "[[binary_dependency]]" in content:
    # A binary_dependency or remote with this name may already exist; only
    # skip when a binary_dependency block already names it.
    for blk in content.split("[[binary_dependency]]"):
      if ("name = \"" & name & "\"") in blk:
        return false
  var entry = "\n[[binary_dependency]]\nname = \"" & name & "\"\nremote = \"" &
    remoteUrl & "\"\n"
  if revision.len > 0:
    entry.add("revision = \"" & revision & "\"\n")
  var trimmed = content
  while trimmed.len > 0 and trimmed[^1] in {'\n', '\r'}:
    trimmed.setLen(trimmed.len - 1)
  writeFile(projectFile, trimmed & "\n" & entry)
  true

proc cloneAddSibling(workspaceRoot, repoPath, fetchUrl, revision: string;
                     identity: GitToolIdentity):
    tuple[ok: bool; diagnostic: string] =
  ## Arrange the develop-mode sibling checkout for ``repro add --develop`` by
  ## scheduling a one-shot ``bakWorkspaceVcs`` clone through the SAME
  ## ``gitCloneAction`` engine path ``init``/``sync`` use (RA-5c). The target
  ## ``<workspaceRoot>/<repoPath>`` must not pre-exist.
  let absTarget = workspaceRoot / repoPath
  if dirExists(absTarget):
    return (ok: false,
      diagnostic: "add clone target already exists: " & absTarget)
  let receiptDir = workspaceRoot / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  let idSeg = safeRepoIdSegment(repoPath)
  let receiptRel = ".repro" / "workspace" / "receipts" /
    ("add-clone-" & idSeg & ".receipt")
  var action = gitCloneAction("workspace-add-clone-" & idSeg, identity,
    remoteUrl = fetchUrl,
    repoPath = repoPath,
    receiptPath = receiptRel,
    revision = revision)
  action.cwd = workspaceRoot
  let cacheRoot = workspaceRoot / ".repro" / "workspace" / "engine-cache"
  var config = defaultBuildEngineConfig(cacheRoot)
  config.suppressTrace = true
  let res = runBuild(graph([action]), config)
  if res.results.len == 0:
    return (ok: false, diagnostic: "build engine returned no clone results")
  let outcome = res.results[0]
  if outcome.status notin {asSucceeded, asCacheHit, asUpToDate}:
    return (ok: false,
      diagnostic: "add clone failed: status=" & $outcome.status &
        " reason=" & outcome.reason &
        (if outcome.stderr.len > 0: " stderr=" & outcome.stderr else: ""))
  (ok: true, diagnostic: "")

proc executeAdd(parsed: AddArgs): AddReport =
  result.workspaceRoot = parsed.workspaceRoot
  result.target = parsed.target

  let resolved = resolveAddProject(parsed)
  result.project = resolved.projectName

  # Decide develop vs binary. The POLICY DEFAULT comes from the bootstrap
  # config (`[develop] org_urls`); `--develop`/`--binary` override it;
  # `--no-membership` is a distinct standalone-checkout mode.
  let policyDevelop = developPolicyMatches(parsed.remoteUrl, parsed.workspaceRoot)
  result.policyDefault = if policyDevelop: "develop" else: "binary"

  var mode = parsed.mode
  result.overridden =
    (mode == amDevelop and not policyDevelop) or
    (mode == amBinary and policyDevelop)
  if mode == amPolicy:
    mode = if policyDevelop: amDevelop else: amBinary

  let revision =
    if parsed.revision.len > 0: parsed.revision
    elif resolved.defaultRevision.len > 0: resolved.defaultRevision
    else: "main"

  case mode
  of amPolicy:
    # Unreachable: ``amPolicy`` is resolved to ``amDevelop``/``amBinary``
    # above before this dispatch. Kept for case exhaustiveness.
    result.exitCode = 1
    result.diagnostic = "internal: unresolved add policy mode"
  of amBinary:
    result.resolvedMode = "binary"
    result.checkedOut = false
    if parsed.dryRun:
      result.exitCode = 0
      stderr.writeLine("repro add would record '" & parsed.target &
        "' as a BINARY dependency of project '" & resolved.projectName &
        "' (no checkout)")
      return
    result.declarationChanged =
      appendBinaryDependency(resolved.projectFile, parsed.target,
        parsed.remoteUrl, revision)
    result.exitCode = 0
  of amDevelop, amNoMembership:
    let isMembership = mode == amDevelop
    result.resolvedMode = if isMembership: "develop" else: "no-membership"
    let repoPath = parsed.target
    if dirExists(parsed.workspaceRoot / repoPath):
      result.exitCode = 1
      result.diagnostic = "checkout target already exists: " &
        (parsed.workspaceRoot / repoPath)
      return
    if parsed.dryRun:
      result.exitCode = 0
      stderr.writeLine("repro add would clone '" & parsed.target & "' as a " &
        (if isMembership: "DEVELOP-mode sibling" else: "standalone checkout") &
        " of project '" & resolved.projectName & "'" &
        (if isMembership: " and record it as a dependency" else: ""))
      return
    # Arrange the sibling checkout via the shared clone engine path (RA-5c).
    let identity = ensureGitToolResolvable(
      parsed.toolProvisioning, getEnv("PATH"))
    installGitVcsExecutor()
    let cloneRes = cloneAddSibling(parsed.workspaceRoot, repoPath,
      parsed.remoteUrl, revision, identity)
    if not cloneRes.ok:
      result.exitCode = 1
      result.diagnostic = cloneRes.diagnostic
      return
    result.checkedOut = true
    if not isMembership:
      # `--no-membership`: cloned, but NOT a workspace dependency. No
      # manifest mutation, no `depends` edge.
      result.declarationChanged = false
      result.exitCode = 0
      return
    # Develop membership: record the remote, the repo fragment, and the
    # `includes` edge so the dependency participates in the workspace.
    # Reuse a declared remote that already serves this URL for this repo
    # name; only fall back to a per-repo remote when none can. `repro add`
    # keeps `[repo].name == target` because the develop-set `depends` edges
    # it writes name the target, and the closure keys off `[repo].name` — a
    # fragment named after its server-side path would leave those edges
    # dangling. So the plan is asked to PRESERVE the name (`repro workspace
    # repos add`, which writes no `depends` edges, takes the
    # unrestricted plan and may put a server-side path in `name`), and a plan
    # that would still rename the repo — a bare `…/<repo>.git` directory URL,
    # where the name can only come out as `<repo>.git` — is declined in favour
    # of a per-repo remote that keeps the fragment's identity intact.
    var remoteName = ""
    var remoteFetch = parsed.remoteUrl
    try:
      let declared = readProjectManifest(resolved.projectFile)
      let defaultRemote =
        if declared.project.default_remote.isSome:
          declared.project.default_remote.get()
        else:
          ""
      let plan = planRepoRemote(declared.remote, defaultRemote,
        parsed.target, parsed.remoteUrl, preserveRepoName = true)
      if plan.error.len == 0 and plan.repoName == parsed.target:
        remoteName = plan.remoteName
        remoteFetch = plan.mintedFetch
    except CatchableError:
      discard
    if remoteName.len == 0:
      remoteName = parsed.target & "-origin"
      remoteFetch = parsed.remoteUrl
    if remoteFetch.len > 0:
      ensureRemoteEntry(resolved.projectFile, remoteName, remoteFetch)
    let manifestsRoot = manifestsRoot(parsed.workspaceRoot)
    createDir(manifestsRoot / "repos")
    let fragmentRel = "repos/" & parsed.target & ".toml"
    let fragmentAbs = manifestsRoot / "repos" / (parsed.target & ".toml")
    # Omit `revision` when the fragment would inherit exactly the same value
    # from the project's `default_revision`; a redundant pin freezes the repo
    # on the day it was added and silently stops tracking the project's
    # branch. The key is written only when the caller asked for a specific
    # revision (`--revision` is an explicit pin, even if it happens to name
    # the current default) or when there is no `default_revision` to inherit
    # and `revision` therefore has to be stated.
    let pinRevision =
      parsed.revision.len > 0 or resolved.defaultRevision.len == 0
    if not fileExists(fragmentAbs):
      writeFile(fragmentAbs,
        "schema = \"reprobuild.workspace.repo.v1\"\n\n" &
        "[repo]\n" &
        "name = \"" & parsed.target & "\"\n" &
        "path = \"" & repoPath & "\"\n" &
        "remote = \"" & remoteName & "\"\n" &
        (if pinRevision: "revision = \"" & revision & "\"\n" else: ""))
    result.declarationChanged =
      appendFragmentInclude(resolved.projectFile, fragmentRel)
    # RA-21 develop-set edge: when `--depends-of=<repo>` is given, record
    # that the named repo depends on the newly added one.
    if parsed.dependsOf.len > 0:
      var dependentFragment = ""
      for repo in resolved.repos:
        if repo.name == parsed.dependsOf:
          dependentFragment = repo.fragmentPath
          break
      if dependentFragment.len == 0:
        result.exitCode = 1
        result.diagnostic = "`--depends-of` names '" & parsed.dependsOf &
          "' which is not a repo in project '" & resolved.projectName & "'"
        return
      if addDependsEdge(dependentFragment, parsed.target):
        result.dependsEdgeOn = parsed.dependsOf
    result.exitCode = 0

proc renderAddTextLines*(report: AddReport): seq[string] =
  if report.exitCode != 0:
    result.add("repro add: error: " & report.diagnostic)
    return
  var line = "repro add: " & report.target & " -> " & report.resolvedMode
  if report.overridden:
    line.add(" (override; policy default was " & report.policyDefault & ")")
  result.add(line)
  if report.checkedOut:
    result.add("repro add: checked out '" & report.target & "'")
  if report.dependsEdgeOn.len > 0:
    result.add("repro add: recorded depends edge: '" & report.dependsEdgeOn &
      "' -> '" & report.target & "'")

proc runAddCommand*(args: openArray[string]): int =
  ## ``repro add <repo> --remote=URL [--develop|--binary|--no-membership]
  ## [--depends-of=REPO] …``. RA-22 develop-mode policy + workspace
  ## membership (CLI/add.md, Workspace-And-Develop-Mode.md).
  let parsed = parseAddArgs(args)
  let report = executeAdd(parsed)
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderAddTextLines(report):
      stdout.writeLine(line)
  report.exitCode

# --- RA-9: `repro remove <repo>` (workspace context) ----------------------
#
# Per CLI/remove.md (workspace/develop-mode responsibilities) + the RA-10
# note: removing a repo from the active workspace drops its declaration AND
# cleans its working tree (keyed by ``path``) and its object store (the
# per-repo ``.git`` under that path; the shared bare is keyed by fetch URL
# and SHARED across repos, so it is intentionally NOT deleted here). The
# removal is DESTRUCTIVE — if the working tree has uncommitted changes it
# would be discarded — so it is subject to the RA-9 confirmation contract:
# preview the per-repo effect, ``--force`` to opt out, and REFUSE CLEANLY in
# a non-interactive context without ``--force`` rather than hanging.
#
# Scope is deliberately minimal (RA-9 is about destructive-safety, not a
# full dependency-graph cleanup): we mutate the single-project declaration by
# dropping the matching ``repos/<repo>.toml`` include line from
# ``projects/<project>.toml`` and remove the working tree. ``--dry-run``
# prints the preview and exits without mutating.

type
  RemoveArgs = object
    workspaceRoot: string
    projectName: string
    target: string       ## repo name (or path) to remove.
    force: bool          ## ``--force``: opt out of the dirty-discard prompt.
    dryRun: bool         ## ``--dry-run``: preview only, mutate nothing.
    json: bool
    toolProvisioning: ToolProvisioningMode

  RemoveRepoEntry* = object
    name*: string
    path*: string
    effect*: string      ## ``would_remove`` / ``removed`` / ``refused`` / ``declined``.
    dirty*: bool
    diagnostic*: string

  RemoveReport* = object
    project*: string
    workspaceRoot*: string
    target*: string
    repos*: seq[RemoveRepoEntry]
    declarationChanged*: bool
    exitCode*: int

proc toJsonNode*(report: RemoveReport): JsonNode =
  result = newJObject()
  result["project"] = %report.project
  result["workspaceRoot"] = %report.workspaceRoot
  result["target"] = %report.target
  result["declarationChanged"] = %report.declarationChanged
  result["exitCode"] = %report.exitCode
  var repos = newJArray()
  for entry in report.repos:
    var obj = newJObject()
    obj["name"] = %entry.name
    obj["path"] = %entry.path
    obj["effect"] = %entry.effect
    obj["dirty"] = %entry.dirty
    obj["diagnostic"] = %entry.diagnostic
    repos.add(obj)
  result["repos"] = repos

proc parseRemoveArgs*(args: openArray[string]): RemoveArgs =
  ## ``repro remove <repo> [--workspace-root=PATH] [--force] [--dry-run]
  ## [--tool-provisioning=...] [--json]``.
  result.workspaceRoot = ""
  result.toolProvisioning = tpmPathOnly
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--tool-provisioning" or
        arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--force" or arg == "--yes":
      result.force = true
    elif arg == "--dry-run":
      result.dryRun = true
    elif arg == "--json":
      result.json = true
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro remove` flag: " & arg)
    elif result.target.len == 0:
      result.target = arg
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro remove`: " & arg)
    inc i
  if result.target.len == 0:
    raise newException(ValueError,
      "`repro remove` requires a repo name positional argument")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc resolveRemoveProject(parsed: RemoveArgs): ResolvedProject =
  ## MO-10 — delegates to the shared ``resolveWorkspaceProjectShared`` ladder
  ## (collapsed from the former per-command copy). Same single-project /
  ## composer dispatch rule as ``checkout``: a metadata-only ``workspace.toml``
  ## (``[workspace].project``) or a compositional one both resolve to a flat
  ## repo set we can scan; a committed-lock-only workspace (no manifest data on
  ## disk) now resolves through the unified committed-lock source instead of
  ## raising — every manifest-present path is byte-unchanged.
  resolveWorkspaceProjectShared(parsed.workspaceRoot, parsed.projectName,
    "`repro remove <repo>`").resolved

proc dropFragmentInclude(projectFile, fragmentAbs: string): bool =
  ## Remove the ``includes`` entry that resolves to ``fragmentAbs`` from
  ## ``projectFile`` by rewriting the include list textually. Returns
  ## true when a line was dropped. The match is on the resolved absolute
  ## fragment path so a ``repos/<repo>.toml`` entry is identified even if
  ## another repo shares a name prefix.
  let content = readFile(projectFile)
  var outLines: seq[string]
  var dropped = false
  for line in content.splitLines():
    let trimmed = line.strip()
    # An include line looks like ``"repos/<repo>.toml",`` (inside the
    # ``includes = [ ... ]`` array). Extract the quoted path and compare
    # its resolved form to the target fragment.
    if trimmed.startsWith("\""):
      let closeIdx = trimmed.find('"', 1)
      if closeIdx > 1:
        let raw = trimmed[1 ..< closeIdx]
        let manifestRoot = parentDir(parentDir(absolutePath(projectFile)))
        let resolvedInc = manifestRoot / raw.replace('/', DirSep)
        if absolutePath(resolvedInc) == absolutePath(fragmentAbs):
          dropped = true
          continue
    outLines.add(line)
  if dropped:
    writeFile(projectFile, outLines.join("\n"))
  dropped

proc reachableExcluding(repos: seq[ResolvedRepo];
                        rootNames: HashSet[string];
                        excluded: string): HashSet[string] =
  ## RA-22 reachability for removal GC. Compute the set of repo NAMES
  ## reachable from ``rootNames`` by walking the per-repo ``depends`` edges
  ## (RA-21), treating ``excluded`` (the repo being removed) as a DELETED
  ## node: it is never entered and never traversed through. A repo that is
  ## still reachable from a remaining root WITHOUT routing through the
  ## removed repo is kept; anything only the removed repo brought in is
  ## eligible for GC. This mirrors the pilot's ``projects remove``, which
  ## deletes only repos unique to the removed project and keeps shared ones.
  result = initHashSet[string]()
  var byName = initTable[string, ResolvedRepo]()
  for repo in repos:
    byName[repo.name] = repo
  var pending: seq[string]
  for r in rootNames:
    if r != excluded:
      pending.add(r)
  while pending.len > 0:
    let name = pending.pop()
    if name == excluded or name in result:
      continue
    result.incl(name)
    if name in byName:
      for dep in byName[name].depends:
        if dep.len > 0 and dep != excluded and dep notin result:
          pending.add(dep)

proc executeRemove(parsed: RemoveArgs): RemoveReport =
  result.workspaceRoot = parsed.workspaceRoot
  result.target = parsed.target

  let resolved = resolveRemoveProject(parsed)
  result.project = resolved.projectName

  # Locate the target repo by name, falling back to path.
  var matchIdx = -1
  for idx, repo in resolved.repos:
    if repo.name == parsed.target or repo.path == parsed.target:
      matchIdx = idx
      break
  if matchIdx < 0:
    result.exitCode = 1
    result.repos.add(RemoveRepoEntry(
      name: parsed.target, effect: "not_found",
      diagnostic: "no repo named '" & parsed.target &
        "' is declared in project '" & resolved.projectName & "'"))
    return

  let target = resolved.repos[matchIdx]

  # RA-22 reachability GC. The removed dependency is the target. The set of
  # checkouts considered for collection (the CANDIDATE set) is the target
  # plus everything in the target's ``depends`` closure. A candidate is GC'd
  # ONLY when it is no longer reachable from a SURVIVING root — a membership
  # root that remains after the removal — once the target is treated as a
  # deleted node. Shared repos that a surviving root still reaches STAY. The
  # graph boundary, not name matching, decides — so removing one dependency
  # never blindly deletes a checkout that something else needs.
  #
  # In reprobuild's model every entry in ``resolved.repos`` is a directly
  # declared project membership (an ``includes`` edge), and ``depends`` are
  # the transitive develop-set edges between them (RA-21). The membership
  # set is therefore the universe of roots; ``depends`` is the universe of
  # graph edges walked for reachability.

  # Candidate GC set: the target's own ``depends`` closure, walked through
  # the FULL graph (the target itself is a root of this walk).
  var candidatesSet = initHashSet[string]()
  block:
    var byName = initTable[string, ResolvedRepo]()
    for repo in resolved.repos:
      byName[repo.name] = repo
    var pending = @[target.name]
    while pending.len > 0:
      let name = pending.pop()
      if name in candidatesSet:
        continue
      candidatesSet.incl(name)
      if name in byName:
        for dep in byName[name].depends:
          if dep.len > 0 and dep notin candidatesSet:
            pending.add(dep)

  # Surviving roots: the membership roots that REMAIN after the removal —
  # every project membership EXCEPT the target and EXCEPT the candidates
  # being considered for GC. A candidate must not seed itself as its own
  # root (that is precisely the bug that makes a transitive-only repo
  # trivially "reachable" and never collected); it survives only if a
  # genuinely independent surviving root still reaches it via ``depends``.
  var survivingRoots = initHashSet[string]()
  for repo in resolved.repos:
    if repo.name != target.name and repo.name notin candidatesSet:
      survivingRoots.incl(repo.name)
  let stillReachable = reachableExcluding(
    resolved.repos, survivingRoots, excluded = target.name)
  # Final GC set: candidates that are NOT still reachable from a surviving
  # root. The target itself is always collected.
  var gcNames: seq[string]
  for repo in resolved.repos:
    if repo.name in candidatesSet and
        (repo.name == target.name or repo.name notin stillReachable):
      gcNames.add(repo.name)
  var gcRepos: seq[ResolvedRepo]
  for repo in resolved.repos:
    if repo.name in gcNames:
      gcRepos.add(repo)

  # Dirty-detection per GC repo: a working tree with uncommitted changes is
  # what makes the removal destructive. A missing/clean tree is safe to
  # remove without a discard. A dirty/unpublished tree is NEVER silently
  # deleted (RA-9 destructive-command safety).
  var identityResolved = false
  var identity: GitToolIdentity
  proc gitIdentity(): GitToolIdentity =
    if not identityResolved:
      identity = ensureGitToolResolvable(parsed.toolProvisioning, getEnv("PATH"))
      identityResolved = true
    identity
  type GcEntry = object
    repo: ResolvedRepo
    dirty: bool
    dirtyDiag: string
  var plan: seq[GcEntry]
  var anyDirty = false
  for repo in gcRepos:
    let repoPath = parsed.workspaceRoot / repo.path
    var dirty = false
    var dirtyDiag = ""
    if dirExists(repoPath / ".git"):
      let cleanRes = queryGitState(isCleanQuery(repoPath), gitIdentity())
      if cleanRes.status != gqsOk:
        dirty = true
        dirtyDiag = "clean/dirty probe failed: " & cleanRes.diagnostic
      elif not cleanRes.isClean:
        dirty = true
        dirtyDiag = "working tree has uncommitted changes"
    if dirty: anyDirty = true
    plan.add(GcEntry(repo: repo, dirty: dirty, dirtyDiag: dirtyDiag))

  # Preview the per-repo effect BEFORE mutating anything.
  let effectVerb = if parsed.dryRun: "would remove" else: "remove"
  stderr.writeLine("repro remove will " & effectVerb & " " & $plan.len &
    " repo(s) from project '" & resolved.projectName & "':")
  for p in plan:
    stderr.writeLine("  " & p.repo.path & " (name=" & p.repo.name & ")" &
      (if p.dirty: " [DIRTY — uncommitted changes WILL BE DISCARDED]"
       else: " [clean]"))

  if parsed.dryRun:
    for p in plan:
      var entry = RemoveRepoEntry(name: p.repo.name, path: p.repo.path,
        dirty: p.dirty, effect: "would_remove")
      if p.dirty: entry.diagnostic = p.dirtyDiag
      result.repos.add(entry)
    result.exitCode = 0
    return

  # RA-9 confirmation: a DIRTY removal in the GC set needs the destructive
  # prompt (discarding uncommitted work). A wholly-clean GC set proceeds
  # without a prompt. The whole removal is gated on a single confirmation so
  # the operator answers once for the destructive batch.
  if anyDirty:
    let decision = confirmDestructive(
      prompt = "Remove " & $plan.len & " repo(s) and DISCARD uncommitted " &
        "changes? [y/N] ",
      autoYes = parsed.force,
      isTty = isatty(stdin),
      flagName = "--force",
      refuseMessage = "refusing to remove in a non-interactive context " &
        "without --force (would discard uncommitted changes)",
      declineMessage = "remove declined; nothing removed")
    if decision != ddConfirmed:
      for p in plan:
        var entry = RemoveRepoEntry(name: p.repo.name, path: p.repo.path,
          dirty: p.dirty)
        entry.effect =
          if decision == ddRefusedNonTty: "refused" else: "declined"
        if p.dirty: entry.diagnostic = p.dirtyDiag
        result.repos.add(entry)
      result.exitCode = 2
      result.declarationChanged = false
      return

  # Proceed: drop the target's declaration, then clean each GC repo's working
  # tree (path) and its object store (the per-repo ``.git``, removed with the
  # tree). Only the target's include is dropped; transitive develop-set
  # siblings are GC'd as CHECKOUTS (their fragments are not the user's direct
  # dependency, so the declaration drop is scoped to the named target).
  let changed = dropFragmentInclude(resolved.projectFile, target.fragmentPath)
  result.declarationChanged = changed
  for p in plan:
    let repoPath = parsed.workspaceRoot / p.repo.path
    if dirExists(repoPath):
      removeDir(repoPath)
    var entry = RemoveRepoEntry(name: p.repo.name, path: p.repo.path,
      dirty: p.dirty, effect: "removed")
    result.repos.add(entry)
  result.exitCode = 0

proc renderRemoveTextLines*(report: RemoveReport): seq[string] =
  for entry in report.repos:
    var line = "repro remove: " & entry.path & " " & entry.effect
    if entry.diagnostic.len > 0:
      line.add(" (" & entry.diagnostic & ")")
    result.add(line)
  if report.exitCode == 0 and report.declarationChanged:
    result.add("repro remove: dropped '" & report.target &
      "' from project '" & report.project & "'")

proc runRemoveCommand*(args: openArray[string]): int =
  ## ``repro remove <repo> [--force] [--dry-run] [--json]
  ## [--workspace-root=PATH]``. RA-9 destructive-command safety: preview +
  ## confirm + refuse-cleanly-in-non-TTY for a workspace repo removal.
  let parsed = parseRemoveArgs(args)
  let report = executeRemove(parsed)
  if parsed.json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderRemoveTextLines(report):
      stdout.writeLine(line)
  report.exitCode

proc copyWorkingTreeChanges(identity: GitToolIdentity;
                            srcRepo, dstRepo, scratchDir, label: string):
    tuple[ok: bool; changed: bool; diagnostic: string] =
  ## M27 ``--include-changes`` — copy ``srcRepo``'s uncommitted work into
  ## ``dstRepo``. The source is only READ: its changes stay exactly where they
  ## are (copy, never move), so a failed apply can never cost the operator
  ## work that exists nowhere else.
  ##
  ## Two disjoint halves, because one git command covers neither:
  ##   * TRACKED modifications (staged + unstaged) via ``git diff HEAD
  ##     --binary`` piped through ``git apply`` in the destination;
  ##   * UNTRACKED, non-ignored files via ``ls-files --others
  ##     --exclude-standard``, copied verbatim. Starting a feature branch
  ##     almost always means new files, so skipping these would silently
  ##     drop the most interesting part of the WIP.
  var anyChange = false
  # ---- tracked ----------------------------------------------------------
  let diff = gitRunPlain(identity,
    ["-C", srcRepo, "diff", "HEAD", "--binary"])
  if diff.code != 0:
    return (ok: false, changed: false,
      diagnostic: "git diff HEAD failed in " & srcRepo & " (" & $diff.code &
        "): " & diff.output.strip())
  if diff.output.strip().len > 0:
    createDir(scratchDir)
    let patchPath = scratchDir / ("include-changes-" & label & ".patch")
    try:
      writeFile(patchPath, diff.output)
    except IOError as err:
      return (ok: false, changed: false,
        diagnostic: "could not stage patch file: " & err.msg)
    let applied = gitRunPlain(identity,
      ["-C", dstRepo, "apply", "--whitespace=nowarn", patchPath])
    if applied.code != 0:
      return (ok: false, changed: false,
        diagnostic: "git apply failed in " & dstRepo & " (" & $applied.code &
          "): " & applied.output.strip())
    anyChange = true
  # ---- untracked --------------------------------------------------------
  let others = gitRunPlain(identity,
    ["-C", srcRepo, "ls-files", "--others", "--exclude-standard"])
  if others.code != 0:
    return (ok: false, changed: anyChange,
      diagnostic: "git ls-files --others failed in " & srcRepo & " (" &
        $others.code & "): " & others.output.strip())
  for rawLine in others.output.splitLines():
    let rel = rawLine.strip()
    if rel.len == 0:
      continue
    let from0 = srcRepo / rel
    let to0 = dstRepo / rel
    if not fileExists(from0):
      continue          # a directory entry or a file that vanished mid-run.
    try:
      createDir(to0.splitPath.head)
      copyFile(from0, to0)
      anyChange = true
    except OSError, IOError:
      return (ok: false, changed: anyChange,
        diagnostic: "could not copy untracked file '" & rel & "' into " &
          dstRepo)
  (ok: true, changed: anyChange, diagnostic: "")

proc executeBranchCreateAndCheckout(parsed: BranchArgs): BranchReport =
  ## M28 / WV-5 — the engine behind ``repro switch -b <name>``: create the
  ## branch across every participating repo AND leave them all switched onto
  ## it. This is the in-place feature-branch flow.
  ##
  ## The create pass runs first and is authoritative for refusals (dirty repos,
  ## probe failures). Because the caller asserts "put me on this branch" rather
  ## than "create this branch here", a branch that already exists locally is NOT
  ## a collision — it is simply a switch target — so this also covers the
  ## "branch already exists everywhere" and the interrupted-midway-through
  ## mixed cases without a separate decision tree.
  # A branch that already exists on a REMOTE is not ours to create: creating a
  # local branch at HEAD would silently diverge from it. Adopting a remote
  # branch is plain `repro switch`'s job (it fetch-and-tracks a remote-only
  # branch), so refuse and name that remedy — the same rule the fork form
  # applies.
  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  let (resolvedForProbe, _) = resolveSwitchProject(SwitchArgs(
    workspaceRoot: parsed.workspaceRoot,
    projectName: parsed.projectName,
    branchName: parsed.branchName,
    assumeYes: true,
    toolProvisioning: parsed.toolProvisioning))
  var remoteHits: seq[string]
  for repo in resolvedForProbe.repos:
    let repoAbs = parsed.workspaceRoot / repo.path
    if not dirExists(repoAbs / ".git"):
      continue
    let localProbe = gitRunPlain(identity,
      ["-C", repoAbs, "rev-parse", "--verify", "--quiet",
       "refs/heads/" & parsed.branchName])
    if localProbe.code == 0 and localProbe.output.strip().len > 0:
      continue          # already local here — a plain switch target.
    let remoteProbe = gitRunPlain(identity,
      ["-C", repoAbs, "ls-remote", "--heads", gitRemoteNameFor(repo),
       parsed.branchName])
    if remoteProbe.code == 0 and remoteProbe.output.strip().len > 0:
      remoteHits.add(repo.path)
  if remoteHits.len > 0:
    result.form = "create"
    result.project = resolvedForProbe.projectName
    result.workspaceRoot = parsed.workspaceRoot
    result.branch = parsed.branchName
    for path in remoteHits:
      result.repos.add(BranchRepoEntry(
        path: path,
        outcome: "branch_exists_on_remote",
        diagnostic: "branch '" & parsed.branchName &
          "' already exists on this repo's remote; `repro switch -b` " &
          "creates a NEW branch — to work on the existing one run " &
          "`repro switch " & parsed.branchName & "`, which fetches and " &
          "tracks a remote-only branch"))
    result.exitCode = 2
    let recorded = readWorkspaceBranch(parsed.workspaceRoot)
    if recorded.isSome:
      result.recordedBranch = recorded.get()
    return

  result = executeBranchCreate(parsed)
  if result.exitCode != 0:
    return
  let switchArgs = SwitchArgs(
    workspaceRoot: parsed.workspaceRoot,
    projectName: parsed.projectName,
    branchName: parsed.branchName,
    assumeYes: true,          # the create pass already confirmed the plan
    toolProvisioning: parsed.toolProvisioning)
  let switched = executeWorkspaceSwitch(switchArgs)
  # Fold the switch outcome into the per-repo lines so one report describes the
  # whole operation. The switch outcome REPLACES the create one: it names the
  # repo's END state (``switched`` / ``already_on_branch``), which is what the
  # operator and any script consumer care about, and it keeps this report's
  # vocabulary identical to `repro switch`'s rather than inventing a
  # compound ``created+switched`` tag nothing else emits.
  for centry in switched.repos:
    for i in 0 ..< result.repos.len:
      if result.repos[i].path == centry.path:
        if centry.outcome.len > 0:
          result.repos[i].outcome = centry.outcome
        if centry.diagnostic.len > 0 and result.repos[i].diagnostic.len == 0:
          result.repos[i].diagnostic = centry.diagnostic
        break
  if switched.exitCode != 0:
    result.exitCode = switched.exitCode
    return
  # ``executeWorkspaceSwitch`` rewrites the metadata; re-assert the M16 mark so the
  # created feature branch stays protected from `repro sync`.
  try:
    writeWorkspaceBranchWithStarted(parsed.workspaceRoot,
      project = result.project, branch = parsed.branchName,
      featureStarted = true)
    result.recordedBranch = parsed.branchName
    result.featureStarted = true
  except WorkspaceManifestParseError as err:
    result.exitCode = 1
    result.repos.add(BranchRepoEntry(
      outcome: "metadata_write_failed", diagnostic: err.msg))

proc executeBranchFork(parsed: BranchArgs): BranchReport =
  ## M27 / WV-6 — ``repro branch <path>`` (a.k.a. ``repro workspace new``):
  ## materialize a NEW workspace at ``parsed.forkPath`` on a branch named after
  ## the destination's basename, cut from THIS workspace's committed HEADs. The
  ## source workspace is never modified, switched or stashed.
  ##
  ## ``--existing-branch`` inverts the branch assertion: the named branch must
  ## already exist and the new workspace is checked out onto it rather than
  ## cutting a new one.
  ##
  ## Cutting from committed HEADs (not the remote tips, not the recorded lock)
  ## is the point of the command: "branch off exactly what I have right now",
  ## including commits that have never been pushed. Those are transferred by
  ## the M27 fork-branch action, which fetches a missing object straight from
  ## the source checkout.
  ##
  ## The source's uncommitted work is deliberately NOT carried unless
  ## ``--include-changes`` says so — which is also why a dirty source is not a
  ## refusal here, unlike the in-place form where dirt would be switched on top
  ## of. See ``reprobuild-specs/CLI/branch.md``.
  ##
  ## PS-6 — membership is INHERITED: the new workspace gets the source's
  ## enabled project set, so it holds the same repos. ``--projects=A,B``
  ## replaces that set outright for the new workspace only; the source's
  ## membership is never edited either way.
  result.branch = parsed.branchName
  result.form = "fork"
  result.sourceWorkspaceRoot = parsed.workspaceRoot
  result.workspaceRoot = parsed.forkPath
  result.includeChanges = parsed.includeChanges

  # ---- membership of the NEW workspace -----------------------------------
  # PS-6 — a fork INHERITS the source workspace's enabled project set. It is
  # the same workspace on a different branch, so it must contain the same
  # repos; deriving membership afresh from the primary project instead would
  # silently drop every repo the other enabled projects contribute, and those
  # repos then have no checkout for the branch pass to act on.
  #
  # ``--projects`` replaces the inherited set outright (not extends it), so
  # forking a narrower slice is expressible without first disabling projects
  # in the source workspace.
  var forkProjects: seq[string]
  var resolved: ResolvedProject
  if parsed.projects.len > 0:
    forkProjects = parsed.projects
    try:
      resolved = resolveProjectSet(parsed.workspaceRoot, forkProjects)
    except CatchableError as err:
      # Refused before anything is created, like every other fork guard.
      result.exitCode = 2
      result.repos.add(BranchRepoEntry(
        outcome: "projects_unresolved",
        diagnostic: "`--projects=" & forkProjects.join(",") &
          "` does not resolve against '" & parsed.workspaceRoot & "': " &
          err.msg))
      return
  else:
    let parsedSwitch = SwitchArgs(
      workspaceRoot: parsed.workspaceRoot,
      projectName: parsed.projectName,
      branchName: parsed.branchName,
      assumeYes: true,
      toolProvisioning: parsed.toolProvisioning)
    (resolved, _) = resolveSwitchProject(parsedSwitch)
    forkProjects = activeProjectSetOrEmpty(parsed.workspaceRoot)
  if forkProjects.len == 0:
    # No recorded set (a single-project workspace, or unreadable metadata):
    # the resolved primary IS the membership.
    forkProjects = @[resolved.projectName]
  result.project = resolved.projectName
  result.projects = forkProjects

  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()

  # The ROOT workspace repo carries the membership manifests; the fork clones
  # it from the SOURCE workspace's own origin (this is a fork of a workspace we
  # are already inside, so no URL resolution is involved). Resolved BEFORE the
  # destination guard because it is what tells an unrelated directory apart
  # from a fork of THIS workspace that is already under way.
  let rootOrigin = gitRemoteOriginUrl(identity, parsed.workspaceRoot)
  if rootOrigin.len == 0:
    result.exitCode = 1
    result.repos.add(BranchRepoEntry(
      outcome: "root_origin_missing",
      diagnostic: "the workspace root '" & parsed.workspaceRoot &
        "' has no `origin` remote to fork from"))
    return

  # ---- destination guard -------------------------------------------------
  # Refusing cwd/an ancestor is absolute (RA-31's upward-walk trap). A NON-EMPTY
  # destination is refused too — EXCEPT when it is recognizably this same fork
  # already materialized (a checkout of the same root origin), which is the
  # resumable case the no-rollback contract promises: a run that failed partway
  # leaves the tree in place precisely so the identical command finishes it.
  # Without this exception "resumable" and "refuse non-empty" contradict.
  var resuming = false
  if pathIsCwdOrAncestor(parsed.forkPath, absolutePath(getCurrentDir())):
    result.exitCode = 2
    result.repos.add(BranchRepoEntry(
      outcome: "destination_refused",
      diagnostic: "`repro branch <name> <path>` refuses to " &
        "materialise into the current or an ancestor directory ('" &
        parsed.forkPath & "'); it always creates a fresh named directory"))
    return
  if dirExists(parsed.forkPath) and toSeq(walkDir(parsed.forkPath)).len > 0:
    let destOrigin = gitRemoteOriginUrl(identity, parsed.forkPath)
    if destOrigin.len > 0 and destOrigin == rootOrigin:
      resuming = true
    else:
      result.exitCode = 2
      result.repos.add(BranchRepoEntry(
        outcome: "destination_refused",
        diagnostic: "destination '" & parsed.forkPath & "' already exists, " &
          "is not empty, and is not a fork of this workspace " &
          "(no `origin` matching '" & rootOrigin & "'); choose a different " &
          "path or remove it first"))
      return

  # ---- observation pass over the SOURCE workspace ------------------------
  type
    ForkSourceState = object
      repo: ResolvedRepo
      srcPath: string
      headSha: string
      isClean: bool
      probeFailed: bool
      probeReason: string
      remoteHasBranch: bool

  var states: seq[ForkSourceState]
  var anyProbeFailed = false
  var remoteCollisions: seq[string]
  var missingBranch: seq[string]   ## WV-6 ``--existing-branch``: repos lacking it.
  for repo in resolved.repos:
    var state: ForkSourceState
    state.repo = repo
    state.srcPath = parsed.workspaceRoot / repo.path
    state.isClean = true
    if not dirExists(state.srcPath / ".git"):
      state.probeFailed = true
      state.probeReason = "no on-disk checkout at '" & state.srcPath &
        "'; run `repro workspace init` or `repro workspace sync` first"
      anyProbeFailed = true
      states.add(state)
      continue
    let headRes = queryGitState(headShaQuery(state.srcPath), identity)
    if headRes.status != gqsOk:
      state.probeFailed = true
      state.probeReason = "head-sha probe failed: " & headRes.diagnostic
      anyProbeFailed = true
      states.add(state)
      continue
    state.headSha = headRes.headSha
    let cleanRes = queryGitState(isCleanQuery(state.srcPath), identity)
    if cleanRes.status == gqsOk:
      state.isClean = cleanRes.isClean
    # The default form starts something NEW, so a branch that already exists
    # upstream is a refusal. ``--existing-branch`` inverts the assertion to
    # "put a workspace on this branch", where the SAME probe answers the
    # opposite question: a branch that exists nowhere is the refusal. One probe,
    # two mirror-image guards, so neither flag can silently do the other's job.
    let rName = gitRemoteNameFor(repo)
    let remoteProbe = gitRunPlain(identity,
      ["-C", state.srcPath, "ls-remote", "--heads", rName, parsed.branchName])
    if remoteProbe.code == 0 and remoteProbe.output.strip().len > 0:
      state.remoteHasBranch = true
    if parsed.existingBranch:
      var found = state.remoteHasBranch
      if not found:
        let localProbe = gitRunPlain(identity,
          ["-C", state.srcPath, "rev-parse", "--verify", "--quiet",
           "refs/heads/" & parsed.branchName])
        found = localProbe.code == 0 and localProbe.output.strip().len > 0
      if not found:
        missingBranch.add(repo.path)
    elif state.remoteHasBranch:
      remoteCollisions.add(repo.path)
    states.add(state)

  if anyProbeFailed or remoteCollisions.len > 0 or missingBranch.len > 0:
    for state in states:
      var entry = BranchRepoEntry(
        name: state.repo.name,
        path: state.repo.path,
        headSha: state.headSha)
      if state.probeFailed:
        entry.outcome = "probe_failed"
        entry.diagnostic = state.probeReason
      elif parsed.existingBranch and state.repo.path in missingBranch:
        entry.outcome = "branch_missing"
        entry.diagnostic = "branch '" & parsed.branchName &
          "' exists neither locally nor on remote '" &
          gitRemoteNameFor(state.repo) & "'; `--existing-branch` adopts an " &
          "EXISTING branch — drop the flag to cut a new one"
      elif not parsed.existingBranch and state.remoteHasBranch:
        entry.outcome = "branch_exists_on_remote"
        entry.diagnostic = "branch '" & parsed.branchName &
          "' already exists on remote '" & gitRemoteNameFor(state.repo) &
          "'; this creates a NEW branch — pass `--existing-branch` to check " &
          "the existing one out into " & parsed.forkPath & " instead"
      else:
        entry.outcome = "ready"
      result.repos.add(entry)
    result.exitCode = if anyProbeFailed: 1 else: 2
    return

  # ---- materialize the new workspace ------------------------------------
  # Resuming (see the destination guard) means the root clone is already there.
  if not resuming and not dirExists(parsed.forkPath / ".git"):
    let rootClone = cloneOrgRootRepo(identity, rootOrigin, parsed.forkPath)
    if not rootClone.ok:
      result.exitCode = 1
      result.repos.add(BranchRepoEntry(
        outcome: "root_clone_failed", diagnostic: rootClone.diagnostic))
      return

  # Member repos: reuse the M9 materialization pass verbatim — it already
  # schedules the clones concurrently on the engine and is resumable, so a
  # re-run after a partial fork only clones what is still missing.
  var initArgs: WorkspaceInitArgs
  initArgs.workspaceRoot = parsed.forkPath
  initArgs.projectName = forkProjects[0]
  # PS-6 — materialize the WHOLE inherited set, not just its primary. The
  # branch pass below iterates `resolved.repos` (the union), so anything init
  # leaves uncloned reaches it as a missing target rather than as a repo it
  # knows to skip.
  if forkProjects.len > 1:
    initArgs.additionalProjects = forkProjects[1 .. ^1]
  initArgs.toolProvisioning = parsed.toolProvisioning
  let initOutcome = executeWorkspaceInit(initArgs)
  if initOutcome.cloneFailures > 0:
    # Partial materialization is LEFT IN PLACE (no rollback): re-running the
    # identical command clones only what is still missing.
    result.exitCode = 1
    result.repos.add(BranchRepoEntry(
      outcome: "clone_failed",
      diagnostic: $initOutcome.cloneFailures & " repo clone(s) failed while " &
        "materializing '" & parsed.forkPath & "'; the partial workspace is " &
        "left in place — re-run the same command to finish it (see " &
        "init-report.json there for the per-repo detail)"))
    return

  # ---- branch pass (concurrent) -----------------------------------------
  # One fork-branch action per repo, PLUS the root workspace repo itself so
  # membership edits made on the feature branch stay on the feature branch.
  let receiptDir = parsed.forkPath / ".repro" / "workspace" / "receipts"
  createDir(receiptDir)
  var actions: seq[BuildAction]
  var actionRepoIndex = initTable[string, int]()

  const RootEntryIndex = -1
  let rootActionId = "workspace-start-fork-root"
  let rootHead = queryGitState(headShaQuery(parsed.workspaceRoot), identity)
  if rootHead.status != gqsOk:
    result.exitCode = 1
    result.repos.add(BranchRepoEntry(
      name: "<workspace-root>", path: ".",
      outcome: "probe_failed",
      diagnostic: "head-sha probe failed on the workspace root: " &
        rootHead.diagnostic))
    return
  # WV-6 — the ROOT repo carries the membership manifests. Under
  # ``--existing-branch`` the branch belongs to somebody else's feature and the
  # root repo usually has no such branch, so it is switched only when the
  # branch is actually there and otherwise left on its default branch. Cutting
  # a new root branch to match would invent a membership line of history the
  # operator did not ask for.
  var rootParticipates = true
  if parsed.existingBranch:
    let rootProbe = gitRunPlain(identity,
      ["-C", parsed.workspaceRoot, "rev-parse", "--verify", "--quiet",
       "refs/heads/" & parsed.branchName])
    rootParticipates = rootProbe.code == 0 and rootProbe.output.strip().len > 0
  if rootParticipates:
    var rootAction =
      if parsed.existingBranch:
        gitSwitchAction(rootActionId, identity,
          branchName = parsed.branchName,
          repoPath = ".",
          receiptPath = ".repro" / "workspace" / "receipts" /
            "start-fork-root.receipt")
      else:
        gitForkBranchAction(rootActionId, identity,
          branchName = parsed.branchName,
          sourceRepoPath = parsed.workspaceRoot,
          targetSha = rootHead.headSha,
          repoPath = ".",
          receiptPath = ".repro" / "workspace" / "receipts" /
            "start-fork-root.receipt")
    rootAction.cwd = parsed.forkPath
    actions.add(rootAction)
    actionRepoIndex[rootActionId] = RootEntryIndex

  for idx, state in states:
    let receiptRel = ".repro" / "workspace" / "receipts" /
      ("start-fork-" & safeRepoIdSegment(state.repo.name) & "-" & $idx &
       ".receipt")
    let actionId = "workspace-start-fork-" &
      safeRepoIdSegment(state.repo.name) & "-" & $idx
    var action =
      if parsed.existingBranch:
        # The repo was just cloned, so the branch is reachable as a
        # remote-tracking ref; `git switch <name>` DWIMs the tracking branch
        # off ``refs/remotes/origin/<name>`` — the same path `repro switch`
        # relies on for a remote-only branch.
        gitSwitchAction(actionId, identity,
          branchName = parsed.branchName,
          repoPath = state.repo.path,
          receiptPath = receiptRel)
      else:
        gitForkBranchAction(actionId, identity,
          branchName = parsed.branchName,
          sourceRepoPath = state.srcPath,
          targetSha = state.headSha,
          repoPath = state.repo.path,
          receiptPath = receiptRel)
    action.cwd = parsed.forkPath
    action.pool = "vcs/fetch"
    action.poolUnits = 1'u32
    actions.add(action)
    actionRepoIndex[actionId] = idx

  var outcomeById = initTable[string, ActionResult]()
  if actions.len > 0:
    let cacheRoot = parsed.forkPath / ".repro" / "workspace" / "engine-cache"
    var config = defaultBuildEngineConfig(cacheRoot)
    config.suppressTrace = true
    let res = runBuild(graph(actions, @[pool("vcs/fetch", 8'u32)]), config)
    for outcome in res.results:
      outcomeById[outcome.id] = outcome

  var failures = 0
  var rootFailed = false
  for action in actions:
    let outcome = outcomeById.getOrDefault(action.id)
    let ok = outcome.status in {asSucceeded, asCacheHit, asUpToDate}
    let idx = actionRepoIndex.getOrDefault(action.id, RootEntryIndex)
    if idx == RootEntryIndex:
      if not ok:
        rootFailed = true
        inc failures
        result.repos.add(BranchRepoEntry(
          name: "<workspace-root>", path: ".",
          outcome: "fork_failed",
          diagnostic: "status=" & $outcome.status & " reason=" &
            outcome.reason & " " & outcome.stderr))
      else:
        result.repos.add(BranchRepoEntry(
          name: "<workspace-root>", path: ".",
          outcome: "branched"))
      continue
    let state = states[idx]
    var entry = BranchRepoEntry(
      name: state.repo.name,
      path: state.repo.path,
      headSha: state.headSha)
    if not ok:
      inc failures
      entry.outcome = "fork_failed"
      entry.diagnostic = "status=" & $outcome.status & " reason=" &
        outcome.reason & " " & outcome.stderr
    else:
      entry.outcome = "branched"
      # ---- optional WIP carry-over ------------------------------------
      if parsed.includeChanges and not state.isClean:
        let copied = copyWorkingTreeChanges(identity, state.srcPath,
          parsed.forkPath / state.repo.path,
          parsed.forkPath / ".repro" / "workspace",
          safeRepoIdSegment(state.repo.name))
        if not copied.ok:
          inc failures
          entry.outcome = "changes_failed"
          entry.diagnostic = copied.diagnostic
        elif copied.changed:
          entry.outcome = "branched_with_changes"
    result.repos.add(entry)

  if failures > 0 or rootFailed:
    result.exitCode = 1
    return

  # ---- metadata (only after every repo landed) --------------------------
  # Order matters: the project set is written FIRST so the branch writer's
  # read-modify-write preserves it. Both writers go through the strict reader,
  # so the second one carries the first one's fields forward verbatim.
  try:
    writeWorkspaceProjects(parsed.forkPath, forkProjects)
    writeWorkspaceBranchWithStarted(parsed.forkPath,
      project = forkProjects[0], branch = parsed.branchName,
      featureStarted = true)
    result.recordedBranch = parsed.branchName
    result.featureStarted = true
  except WorkspaceManifestParseError as err:
    result.exitCode = 1
    result.repos.add(BranchRepoEntry(
      outcome: "metadata_write_failed", diagnostic: err.msg))
    return
  result.exitCode = 0

## ----------------------------------------------------------------------------
## CI-Sharding M2 — ``repro test`` shard runner.
##
## This block implements the user-facing surface specified in
## ``reprobuild-specs/CI-Sharding.md`` §"CLI Surface" and wired up
## end-to-end in milestone M2 of
## ``reprobuild-specs/CI-Sharding.milestones.org``:
##
##   repro test --shard <k>/<N>
##              [--partition-strategy <slice|hash|duration|joint-duration>]
##              [--peer-cache=<none|lan://CIDR|remote://URL>]
##              [--emit-partition-plan=<path>] [--plan-from=<path>]
##              [<test-selectors>...]
##
## Test-edge discovery is intentionally pluggable: when the workspace
## already carries an aggregated target-export table the CLI will
## eventually walk it (that is M2-followup work; see the planner
## docstring), but for the M2 verification tests and for the
## first-end-to-end demo a JSON fixture path can be supplied via
## ``--fixture-from=<path>``.  The fixture format is:
##
##   {
##     "buildActions": [
##       { "id": <int>, "commandStatsId": <str>, "deps": [<int>, ...],
##         "buildCmd": [<argv>, ...] }, ...
##     ],
##     "testEdges": [
##       { "id": <int>, "selector": <str>, "historyKey": <str>,
##         "buildDeps": [<int>, ...], "runCmd": [<argv>, ...],
##         "testName": "<binary>::<suite>::<test>" }, ...
##     ],
##     "fallbackBuildCostNs": <int>,
##     "fallbackTestCostNs": <int>,
##     "historyDir": <str>, "estimateDbPath": <str>,
##     "estimateScope": <str>, "policy": "independent"|"shared"
##   }
##
## The M2 per-shard report lives at
## ``test-logs/shard-<k>-of-<N>.json`` and carries the fields specified
## in CI-Sharding.milestones.org M2 "Per-shard report writer".

type
  ReproTestFixtureAction = object
    id: NodeId
    commandStatsId: string
    deps: seq[NodeId]
    buildCmd: seq[string]

  ReproTestFixtureEdge = object
    id: NodeId
    selector: string
    historyKey: string
    buildDeps: seq[NodeId]
    runCmd: seq[string]
    testName: string  # ``<binary>::<suite>::<test>`` or just ``<binary>``

  ReproTestFixture = object
    actions: seq[ReproTestFixtureAction]
    edges: seq[ReproTestFixtureEdge]
    fallbackBuildCostNs: int64
    fallbackTestCostNs: int64
    historyDir: string
    estimateDbPath: string
    estimateScope: string
    policy: SharedInputPolicy
    refinementPasses: int

  ReproTestShardOpts = object
    shardIndex: int                # 1-indexed; 0 means none parsed
    shardCount: int
    strategy: string               # "joint-duration" | "slice" | "hash" | "duration"
    peerCacheSpec: string          # raw text
    emitPlanPath: string
    planFromPath: string
    selectors: seq[string]
    fixturePath: string
    binDir: string
    reportPath: string
    buildFlags: seq[string]        # Build-only flags retained for the
                                   # non-sharded ``repro build test`` alias.
    daemonFlag: string             # ``--daemon=on|off|auto`` carry-through
                                   # for the verb-alias path.
    lockFlag: string               # MO-1 ``--lock=<file>`` carry-through:
                                   # the alternate committed solved-graph
                                   # lock, forwarded to ``runBuildCommand``
                                   # on the verb-alias path.
    toolProvisioning: ToolProvisioningMode
      ## Workspace-mode discovery needs typed tool provisioning when the
      ## project's interface declares ``uses:`` blocks (the default for any
      ## real reprobuild workspace).  ``tpmUnspecified`` defers to the
      ## project-interface's declared default; if there is none the engine
      ## raises the documented "pass --tool-provisioning=path" diagnostic.
    # ---- TC-1: certificate issuance flags --------------------------------
    certify: bool
      ## ``--certify`` (the default) — issue a test certificate when the run
      ## passes AND the gate preconditions hold. ``--no-certify`` suppresses
      ## issuance entirely (tests still run).
    certifyExplicit: bool
      ## ``repro certify`` / ``--certify`` was given explicitly (the "run the
      ## full required set to get a certificate" form). Distinguishes the
      ## explicit ceremony from a default-on ``repro test`` issuance for the
      ## diagnostic text; does not change the issuance LOGIC.
    noCertify: bool
      ## ``--no-certify`` was given explicitly (suppress issuance).
    certificateOut: string
      ## ``--certificate-out=PATH`` — where to write the issued certificate.
      ## Defaults to ``<workspaceRoot>/.repro/workspace/certificates/
      ## <commit>-<platform>.toml`` when a workspace is resolvable.
    certWorkspaceRoot: string  ## ``--workspace-root=PATH`` for the gate.
    certCurrentRepo: string    ## ``--current-repo=PATH`` for the gate.
    certTraceDir: string
      ## ``--ct-incremental-trace-dir=PATH`` — the incremental adapter's
      ## trace dir; when set, the no-op decision consults the canonical
      ## ct-incremental change signal in addition to the commit/lock signal.

proc emitShardDiagnostic(msg: string) =
  stderr.writeLine("repro test: error: " & msg)

type
  PeerCacheSpecKind* = enum
    pcsNone, pcsLan, pcsRemote

  PeerCacheSpecResult* = object
    ## Peer-Cache M2: structured result of parsing ``--peer-cache=...``.
    ## ``ok`` is ``false`` for structurally invalid specs (the CLI
    ## emits a diagnostic in that case). ``kind`` distinguishes the
    ## three spec forms reserved in
    ## ``CI-Sharding.md`` §"CLI Surface". For ``pcsLan``, ``config``
    ## carries the fully-populated ``PeerCacheConfig`` (CIDR
    ## allowlist + multicast group) ready to thread through to the
    ## peer-cache server / client.
    ok*: bool
    kind*: PeerCacheSpecKind
    rawArg*: string
    config*: PeerCacheConfig

proc modeName*(kind: PeerCacheSpecKind): string =
  case kind
  of pcsNone: "none"
  of pcsLan: "lan"
  of pcsRemote: "remote"

proc parsePeerCache*(spec: string): PeerCacheSpecResult =
  ## Peer-Cache M2: parser for the ``--peer-cache=`` flag. Recognises
  ## the three forms documented in
  ## ``CI-Sharding.md`` §"CLI Surface":
  ##
  ##   - ``none`` / empty string — ``pcsNone``.
  ##   - ``remote://<url>`` — ``pcsRemote``, ``rawArg`` is the URL.
  ##   - ``lan://<CIDR>[:port]`` — ``pcsLan``, ``config`` is populated
  ##     with ``discoveryMode = pdmMulticast``, the parsed CIDR in
  ##     ``cidrAllowlistRaw``, and the multicast group address
  ##     ``224.0.0.123:<port>`` (default 7654; the test suite uses
  ##     ``17654`` to avoid kernel filtering on low ports).
  ##
  ## Returns ``ok=false`` for structurally invalid specs.
  result.ok = false
  result.kind = pcsNone
  result.rawArg = ""
  if spec.len == 0 or spec == "none":
    result.ok = true
    result.kind = pcsNone
    return
  if spec.startsWith("remote://"):
    result.ok = true
    result.kind = pcsRemote
    result.rawArg = spec[len("remote://") .. ^1]
    return
  if spec.startsWith("lan://"):
    var arg = spec[len("lan://") .. ^1]
    # Peer-Cache-BearSSL M4: strip an optional ``?tls=1`` query knob
    # before parsing the CIDR + port. When present, populate the
    # ``tlsCertPath`` / ``tlsKeyPath`` / ``tlsTrustAnchorsPath`` fields
    # from ``XDG_STATE_HOME/repro-peer-cache/tls/`` and flip the trust
    # mode to ``tmTls``. Any other query knob is rejected.
    var enableTls = false
    let queryIdx = arg.find('?')
    if queryIdx >= 0:
      let query = arg[queryIdx + 1 .. ^1]
      arg = arg[0 ..< queryIdx]
      for piece in query.split('&'):
        case piece
        of "tls=1":
          enableTls = true
        of "tls=0", "":
          discard
        else:
          result.ok = false
          return
    # ``lan://<CIDR>[:port]`` — split on the *last* colon so the CIDR
    # itself (which may contain dots and a single ``/`` for the
    # prefix length) is preserved verbatim. A trailing ``:port`` is
    # optional; missing ⇒ the spec default (7654).
    var cidrPart = arg
    var port = Port(DefaultMulticastPort)
    let lastColon = arg.rfind(':')
    if lastColon >= 0:
      let portStr = arg[lastColon + 1 .. ^1]
      try:
        let parsed = parseInt(portStr)
        if parsed >= 1 and parsed <= 65535:
          port = Port(uint16(parsed))
          cidrPart = arg[0 ..< lastColon]
      except ValueError:
        # Not a port — leave the whole ``arg`` as the CIDR and use
        # the default port. The CIDR validator below will reject
        # anything truly malformed.
        discard
    # Validate the CIDR by running it through ``parseCidrV4`` so we
    # fail closed at parse time (rather than at service start). The
    # validated value isn't kept here; the server side calls
    # ``parseCidrV4`` again at start time so the failure surface for
    # CIDR errors is a single code path.
    try:
      discard parseCidrV4(cidrPart)
    except CatchableError:
      result.ok = false
      return
    result.ok = true
    result.kind = pcsLan
    result.rawArg = arg
    var cfg = PeerCacheConfig(
      discoveryMode: pdmMulticast,
      seedPeers: @[],
      multicastGroup: MulticastGroup(
        address: parseIpAddress(DefaultMulticastAddress),
        port: port,
        interfaceIp: parseIpAddress("0.0.0.0")),
      cidrAllowlistRaw: @[cidrPart],
      advertiseIntervalMs: DefaultAdvertiseIntervalMs,
      pingIntervalMs: DefaultPingIntervalMs,
      maxBlobBytes: DefaultMaxBlobBytes)
    if enableTls:
      let envState = getEnv("XDG_STATE_HOME")
      let stateRoot =
        if envState.len > 0: envState
        else: getHomeDir() / ".local" / "state"
      let tlsDir = stateRoot / "repro-peer-cache" / "tls"
      cfg.trustMode = tmTls
      cfg.tlsCertPath = tlsDir / "peer.crt"
      cfg.tlsKeyPath = tlsDir / "peer.key"
      cfg.tlsTrustAnchorsPath = tlsDir / "anchors"
    result.config = cfg
    return
  # Unrecognised prefix.
  result.ok = false

# ---------------------------------------------------------------------------
# Peer-Cache M2: thin wiring helper called from ``runReproTestCommand``
# before the partition planner runs. Constructs and starts a
# `PeerCacheServer` + `PeerCacheClient` from a parsed `PeerCacheConfig`
# (`pdmMulticast` mode). The returned tuple is held by the caller for
# the lifetime of the shard so a subsequent `stop()` cleans up.
#
# This is the thinnest possible wiring: the partition planner doesn't
# yet consult the peer cache (that's an action-cache reader
# concern, tracked in Peer-Cache M1 Outstanding Tasks), but per the
# milestone spec the services must start so the M2 CLI verification
# test can assert `server.started == true`.
# ---------------------------------------------------------------------------

type
  PeerCacheRuntime* = object
    server*: PeerCacheServer
    client*: PeerCacheClient
    registry*: PeerRegistry

var lastStartedPeerCacheRuntime*: PeerCacheRuntime
  ## Peer-Cache M2 test seam: the most recent `PeerCacheRuntime` started
  ## by `runReproTestCommand` is captured here so the
  ## `t_peer_cache_cli_lan_spec_enables_multicast` test can assert
  ## `server.started == true` after `runReproTestCommand` returns. The
  ## production code path doesn't read this variable; it exists purely
  ## for in-process introspection from the verification harness.

proc startPeerCacheServices*(config: PeerCacheConfig;
                            selfPeerId: PeerId;
                            listenAddr: string = "0.0.0.0"):
                            PeerCacheRuntime =
  ## Boots the peer-cache TCP server + multicast receiver and the
  ## client-side multicast broadcaster from a parsed `PeerCacheConfig`.
  ## The CIDR allowlist is converted from the parser's raw strings to
  ## typed `CidrV4` values here so any drift between the parser and
  ## the server's matcher surfaces as a single diagnostic at start
  ## time.
  let endpoint = initEndpoint(listenAddr, Port(0))
  result.registry = newPeerRegistry(selfPeerId, endpoint)
  var allowlist: seq[CidrV4] = @[]
  for cidrStr in config.cidrAllowlistRaw:
    allowlist.add(parseCidrV4(cidrStr))
  result.server = newPeerCacheServer(
    selfPeerId = selfPeerId,
    listenAddr = listenAddr,
    listenPort = Port(0),
    registry = result.registry,
    cidrAllowlist = allowlist,
    maxBlobBytes = config.maxBlobBytes)
  result.server.start()
  if config.discoveryMode == pdmMulticast:
    result.server.multicastListen(config.multicastGroup)
  result.client = newPeerCacheClient(
    selfPeerId = selfPeerId,
    listenPort = uint16(result.server.actualPort),
    registry = result.registry,
    seedPeers = config.seedPeers,
    cidrAllowlist = allowlist,
    advertiseIntervalMs = config.advertiseIntervalMs)
  if config.discoveryMode == pdmMulticast:
    result.client.multicastBroadcast(config.multicastGroup)

# ---------------------------------------------------------------------------
# Peer-Cache M1 build wiring (Linux-Distro-Recipe-Validation M5,
# 2026-06-12).
#
# Given a `PeerCacheActionCacheReader` (wired to a `PeerCacheClient` for
# the LAN-discovered peer pool) and a local CAS + ActionCache pair, the
# three procs below produce the engine closures the `BuildEngineConfig`
# peer-cache fields accept. The reader's own counters
# (`peerHits`/`peerMisses`/`localHits`) survive the wrap so verification
# tests can assert against them.
#
# The closures are pure value-capturing — no daemon round-trip happens
# here; `PeerCacheActionCacheReader.readActionOutput` already drives the
# blocking `waitFor` for the `mkFetchRequest` round trip, and the
# publisher closure dispatches an async `peerCacheServer.serveLocalBlob`
# equivalent via the registry's `selfAddBlob` hook plus a local store
# writer call.
# ---------------------------------------------------------------------------

proc newBuildPeerCacheWiring*(reader: PeerCacheActionCacheReader;
                               cas: LocalCas;
                               cache: ptr ActionCache;
                               localPeerRegistry: PeerRegistry = nil):
                               BuildPeerCacheWiring =
  ## Returns a wiring bundle the engine can adopt. `cas` and `cache` are
  ## the same handles the engine uses internally — the installer closure
  ## writes peer-fetched bundles into them so the engine's next
  ## `lookupActionResult` call hits locally.
  ##
  ## `localPeerRegistry`, when non-nil, receives `selfAddBlob(digest)`
  ## calls on every publish so the local peer's advertise plane learns
  ## the new blob immediately (otherwise the next advertise tick
  ## propagates it). Tests typically pass the loopback peer's registry
  ## here so the second peer's `requestFetch` finds the bundle without
  ## waiting for an advertise round.
  result.reader = reader
  # `cas` and `cache` are retained for API stability but the active
  # install path uses the engine-supplied handles (the engine pushes
  # its own `CasStore` and `ptr ActionCache` into the installer
  # closure). Earlier drafts of this helper closed over them locally;
  # we keep the parameters so existing callers don't break.
  discard cas
  discard cache
  let registryRef = localPeerRegistry
  let readerRef = reader
  result.fetcher = proc(weakFingerprint: ContentDigest):
      Option[seq[byte]] {.gcsafe, closure.} =
    let key = actionBundleKey(weakFingerprint)
    readerRef.readActionOutput(key)
  result.installer = proc(weakFingerprint: ContentDigest;
                          bundleBytes: seq[byte];
                          engineCas: var CasStore;
                          engineCache: ptr ActionCache):
                          tuple[ok: bool; reason: string]
      {.gcsafe, closure.} =
    let bundle =
      try:
        decodeActionBundle(bundleBytes)
      except CatchableError as exc:
        return (false, "decode failed: " & exc.msg)
    installActionBundle(engineCas, engineCache[], bundle)
  result.publisher = proc(weakFingerprint: ContentDigest;
                          bundleBytes: seq[byte]) {.gcsafe, closure.} =
    let key = actionBundleKey(weakFingerprint)
    # Push the bundle bytes into the reader's local-write closure so a
    # subsequent `readActionOutput(key)` from any peer that picks up the
    # advertise (or from the same reader on the next lookup) gets a
    # cache hit. Mirrors how `PeerCacheClient.requestFetch` writes a
    # verified `mkFetchResponse` payload to the local store before
    # returning.
    if readerRef.localWrite != nil:
      readerRef.localWrite(key, bundleBytes)
    if registryRef != nil:
      registryRef.selfAddBlob(key)

var lastStartedBuildPeerCacheRuntime*: PeerCacheRuntime
  ## Peer-Cache M1 / LDRV M5 test seam: the most recent `PeerCacheRuntime`
  ## started by ``runBuildCommand`` is captured here so verification tests
  ## can assert against the runtime's counters or stop the services
  ## after a build run. Production code does not consume this variable.

proc buildPeerCacheWiringFor*(spec: string): BuildPeerCacheWiring =
  ## CLI-side ``--peer-cache=<spec>`` wiring helper for ``repro build``.
  ## Empty / ``none`` spec returns a zero-valued wiring (all closures
  ## nil) so the engine falls through to its legacy local-only path.
  ## Structural-parse failures raise `ValueError`; runtime-start
  ## failures raise `IOError` / `OSError` with the underlying message.
  if spec.len == 0:
    return BuildPeerCacheWiring()
  let parsed = parsePeerCache(spec)
  if not parsed.ok:
    raise newException(ValueError,
      "invalid --peer-cache spec: " & spec &
      " (expected ``none``, ``lan://<CIDR>``, or ``remote://<URL>``)")
  case parsed.kind
  of pcsNone:
    return BuildPeerCacheWiring()
  of pcsRemote:
    # ``remote://`` is parsed for forward-compatibility but the action-
    # cache reader bridge for it lands in a follow-up milestone.
    # Returning a no-op wiring keeps `--peer-cache=remote://...` from
    # crashing existing harnesses that pass it speculatively.
    return BuildPeerCacheWiring()
  of pcsLan:
    var raw: array[32, byte]
    raw[0] = byte(ord('B'))  # ``B`` for repro build, distinct from
                             # the loopback helper's ``L`` and the
                             # repro-test path's ``R``.
    let nowSeconds = uint64(epochTime())
    for k in 0 ..< 8:
      raw[1 + k] = byte((nowSeconds shr uint64(k * 8)) and 0xff'u64)
    let cliPeerId = peerIdFromBytes(raw)
    lastStartedBuildPeerCacheRuntime = startPeerCacheServices(
      parsed.config, cliPeerId, listenAddr = "127.0.0.1")
    # The CLI doesn't have the engine's CAS + ActionCache in scope (the
    # engine opens them lazily inside ``runBuild``). Close over the
    # spec'd root paths instead so the installer closure re-opens
    # them on demand. Tests that need direct access to the engine's
    # internal handles call ``newBuildPeerCacheWiring`` instead.
    let runtime = lastStartedBuildPeerCacheRuntime
    let actionCacheRoot = currentActionCacheRoot()
    let casRoot =
      if actionCacheRoot.len > 0: actionCacheRoot / "cas"
      else: getCurrentDir() / ".repro" / "build-engine-cache" / "cas"
    let cacheDir =
      if actionCacheRoot.len > 0: actionCacheRoot / "action-cache"
      else: getCurrentDir() / ".repro" / "build-engine-cache" /
            "action-cache"
    let peerCasReader: LocalStoreReader =
      proc(digest: BlobDigest): Option[seq[byte]] {.gcsafe.} =
        # The CLI path doesn't keep a process-local map of bundle
        # digests — every bundle hit goes through the engine's
        # installer closure and the next `lookupActionResult`. The
        # peer-cache reader's "local-read" branch is therefore a
        # constant miss; the fall-through to `peerCacheClient.
        # requestFetch` is the active code path.
        none(seq[byte])
    let peerCasWriter: LocalStoreWriter =
      proc(digest: BlobDigest; payload: seq[byte]) {.gcsafe.} =
        # The fetched bundle is written to the local CAS + ActionCache
        # by the engine's installer closure on the lookup retry; we
        # intentionally do not double-write here.
        discard
    result.reader = newPeerCacheActionCacheReader(
      localRead = peerCasReader,
      localWrite = peerCasWriter,
      peerCacheClient = runtime.client)
    let readerRef = result.reader
    let registryRef = runtime.registry
    result.fetcher = proc(weakFingerprint: ContentDigest):
        Option[seq[byte]] {.gcsafe, closure.} =
      let key = actionBundleKey(weakFingerprint)
      readerRef.readActionOutput(key)
    result.installer = proc(weakFingerprint: ContentDigest;
                            bundleBytes: seq[byte];
                            engineCas: var CasStore;
                            engineCache: ptr ActionCache):
                            tuple[ok: bool; reason: string]
        {.gcsafe, closure.} =
      let bundle =
        try:
          decodeActionBundle(bundleBytes)
        except CatchableError as exc:
          return (false, "decode failed: " & exc.msg)
      installActionBundle(engineCas, engineCache[], bundle)
    # `casRoot` / `cacheDir` are unused now — the engine threads its
    # own opened handles into the installer. Keep the local
    # declarations so the build path doesn't drift from earlier
    # drafts; the compiler folds the unused locals out.
    discard casRoot
    discard cacheDir
    result.publisher = proc(weakFingerprint: ContentDigest;
                            bundleBytes: seq[byte]) {.gcsafe, closure.} =
      let key = actionBundleKey(weakFingerprint)
      if readerRef.localWrite != nil:
        readerRef.localWrite(key, bundleBytes)
      if registryRef != nil:
        registryRef.selfAddBlob(key)

proc parseShardSpec(value: string): tuple[ok: bool; k, n: int] =
  let parts = value.split('/')
  if parts.len != 2:
    return (false, 0, 0)
  try:
    let k = parseInt(parts[0])
    let n = parseInt(parts[1])
    if n <= 0 or k < 1 or k > n:
      return (false, 0, 0)
    return (true, k, n)
  except ValueError:
    return (false, 0, 0)


# ---- TC-1 issuance: precondition evaluation + no-op decision ----------------

type
  IssuancePreconditionKind* = enum
    ## Why a certificate can / cannot be issued for the current state.
    ipOk                ## clean closure + at locked revisions → issuable.
    ipDirty             ## a repo in the closure has a dirty tree.
    ipUnpublished       ## a repo in the closure has unpublished HEAD.
    ipOffLock           ## HEAD differs from the locked revision (lock stale).
    ipNoWorkspace       ## not a resolvable workspace → cannot bind to a lock.
    ipGateError         ## the gate raised (IO / resolve / VCS error).

  IssuancePreconditions* = object
    ## Result of evaluating the issuance preconditions by REUSING the RA-21
    ## pre-push gate (cleanliness / develop-closure / lock-currency). On
    ## ``ipOk`` the binding fields (``commit`` of the current repo's HEAD,
    ## ``lockDigest`` from the resolved lock file, ``platform``) are filled.
    ## On a non-OK kind, ``offender`` / ``remedy`` carry the RA-28-style
    ## ambient message (Interactive-UX Principle 2).
    kind*: IssuancePreconditionKind
    commit*: string
    lockDigest*: string
    lockFilePath*: string
    platform*: string
    project*: string
    repo*: string
    offender*: string
    remedy*: string

proc evaluateIssuancePreconditions*(workspaceRoot, currentRepo: string;
    toolProvisioning: ToolProvisioningMode): IssuancePreconditions =
  ## REUSE the RA-21 gate: a certificate is issuable EXACTLY when the pre-push
  ## gate would pass (closure clean + published + at the locked revisions).
  ## We run the gate logic (NOT the publish side-effect) and translate its
  ## first failure into an issuance-precondition reason + RA-28-style remedy.
  result.platform = currentPlatformTag()
  var parsed = CheckArgs(
    mode: cmPrePush,
    workspaceRoot: workspaceRoot,
    currentRepo: currentRepo,
    pushedRefsPath: "",
    # Issuance must not require a certificate (chicken-and-egg): suppress the
    # TC-3/RA-32 certificate stage when the gate is reused to decide whether a
    # cert is ISSUABLE. The real pre-push hook keeps it enabled.
    skipCertificateGate: true,
    toolProvisioning:
      if toolProvisioning == tpmUnspecified: tpmPathOnly else: toolProvisioning)
  if not isInitializedWorkspace(parsed.workspaceRoot):
    result.kind = ipNoWorkspace
    result.offender = parsed.workspaceRoot
    result.remedy = "run inside an initialized reprobuild workspace " &
      "(no resolved manifest checkout at " & parsed.workspaceRoot & ")"
    return
  var report: CheckReport
  try:
    report = executeCheckPrePush(parsed)
  except CatchableError as err:
    result.kind = ipGateError
    result.offender = ""
    result.remedy = "investigate the workspace gate error and retry: " & err.msg
    return
  result.project = report.project
  if report.exitCode != 0 and report.failures.len > 0:
    let f = report.failures[0]
    result.offender = f.repo
    result.remedy = f.remediation
    case f.property
    of "dirty", "develop_override_dirty":
      result.kind = ipDirty
    of "unpublished", "develop_override_unpublished",
       "lock-publish-failure":
      result.kind = ipUnpublished
    of "lock-stale", "lock-failure":
      result.kind = ipOffLock
    else:
      # A visibility / develop-missing failure is still a "not in a
      # publishable state" condition; treat it as off-lock so no cert is
      # issued and the gate's own remedy is surfaced.
      result.kind = ipOffLock
    return
  # Gate passed → issuable. Resolve the binding fields.
  result.lockFilePath = report.lockUpdate.lockFilePath
  result.lockDigest = certificateLockDigest(result.lockFilePath)
  if result.lockDigest.len == 0:
    # The gate passed but no lock file was resolvable (a workspace with no
    # lock subtree). Without a lock there is nothing reproducible to bind
    # to, so decline rather than emit an unbindable certificate.
    result.kind = ipOffLock
    result.offender = report.project
    result.remedy = "create a workspace lock first — run 'repro workspace lock'"
    return
  # The current repo's HEAD is the commit the certificate binds to.
  let identity = ensureGitToolResolvable(
    parsed.toolProvisioning, getEnv("PATH"))
  installGitVcsExecutor()
  let repoForHead =
    if currentRepo.len > 0: currentRepo else: parsed.workspaceRoot
  let headRes = queryGitState(headShaQuery(repoForHead), identity)
  if headRes.status == gqsOk:
    result.commit = headRes.headSha
  if result.commit.len == 0:
    result.kind = ipOffLock
    result.offender = repoForHead
    result.remedy = "commit your work so the certificate binds to a HEAD commit"
    return
  result.repo =
    if report.lockUpdate.triggerRepo.len > 0: report.lockUpdate.triggerRepo
    else: result.project
  result.kind = ipOk

proc certificateNoOpDecision*(existingCertPath: string;
    pre: IssuancePreconditions; requestedTargets: seq[string];
    traceDir, projectRoot, cachePath: string): bool =
  ## TC-1 incremental no-op: a re-certify with NO relevant change is a NO-OP —
  ## the existing valid certificate stands and the tests are NOT re-run.
  ##
  ## The decision is driven by TWO honest signals (both must say "unchanged"):
  ##
  ##   1. A CONTENT/COMMIT/LOCK signal: an existing certificate at the output
  ##      path already covers (commit, lock, platform) and the requested
  ##      targets. Because the issuance preconditions require a CLEAN tree at
  ##      HEAD, the (commit, lock) pair is a precise fingerprint of the tested
  ##      state — if it is unchanged AND a covering cert exists, nothing
  ##      relevant changed.
  ##   2. The canonical ct-incremental change signal, WHEN a trace dir is
  ##      supplied: ``watchTestEdgeDecision`` (the codetracer-backed adapter)
  ##      returns ``weaSkip`` only when no executed function changed. This is
  ##      the spec's "re-run only tests whose executed functions changed".
  ##      When no trace dir is supplied (the hermetic-without-the-ct-stack
  ##      case) the decision rests on signal (1) alone — see the milestone
  ##      note on how the test drives this.
  if not fileExists(existingCertPath):
    return false
  var existing: TestCertificate
  try:
    existing = readCertificateFile(existingCertPath)
  except CatchableError:
    return false
  let req = CoverageRequirement(
    commit: pre.commit, lock: pre.lockDigest, platform: pre.platform,
    requiredTargets: requestedTargets)
  let cov = verifyCoverage(@[existing], req)
  if not cov.covered:
    return false
  # Signal (1) says unchanged. If a trace dir is wired, also require the
  # canonical adapter to agree (no executed function changed). The adapter is
  # consulted per requested target; ANY rerun verdict means a relevant change.
  if traceDir.len > 0:
    for target in requestedTargets:
      let decision = watchTestEdgeDecision(target, traceDir, projectRoot,
        cachePath)
      if decision.action != weaSkip:
        return false
  true

proc issueCertificate*(pre: IssuancePreconditions;
    passedTargets: seq[string]; issuer: string): TestCertificate =
  ## Build a ``reprobuild.test-certificate.v1`` for an issuable state. The
  ## ``result`` is always ``tcrPassed`` (callers only issue on a real pass);
  ## the SIGNATURE is left explicitly EMPTY — TC-5 wires real daemon signing.
  result = TestCertificate(
    schema: testCertificateSchemaV1,
    project: pre.project,
    repo: pre.repo,
    commit: pre.commit,
    lock: pre.lockDigest,
    platform: pre.platform,
    targets: passedTargets,
    result: tcrPassed,
    issuedAt: getTime().utc.format("yyyy-MM-dd'T'HH:mm:ss'Z'"),
    issuer: issuer,
    keyId: "",
    signature: TestCertificateSignature(algorithm: "", value: ""))

proc defaultCertificatePath*(workspaceRoot, commit, platform: string): string =
  ## Default ``--certificate-out`` location: one file per (commit, platform)
  ## under the workspace's ``.repro`` tree so re-certify finds the prior cert.
  let safePlatform = platform.replace('/', '-')
  let safeCommit = if commit.len >= 12: commit[0 ..< 12] else: commit
  workspaceRoot / ".repro" / "workspace" / "certificates" /
    (safeCommit & "-" & safePlatform & ".toml")

# ============================================================================
# TC-4 — CI fast-track: skip targets covered by a valid certificate per platform.
#
# CI for a platform ``P`` should not re-run a target set that a VALID
# certificate already attests passed for ``(commit, lock, P, targets)`` — it can
# SKIP that work and fast-track the PR (Test-Certificates.md §"CI integration —
# skipping certified work"). The decision is a PURE function of the same
# primitives the push gate (TC-3/TC-6) uses, so the trust boundary is identical:
#
#   * the BINDING — ``commit`` (HEAD), ``lock`` digest, platform ``P`` — is
#     resolved exactly as issuance/gating resolves it, so a cert only counts for
#     the state it actually attests (a wrong-commit / wrong-lock / wrong-platform
#     cert is ignored — TC-1 ``certificateMatches``).
#   * a cert counts toward a SKIP ONLY when ``verifyCertificateSignature``
#     (TC-5) returns ``svValid`` — registered key, unrevoked, ed25519 signature
#     over the canonical payload checks. An unsigned / wrong-key / unregistered /
#     revoked / tampered cert is DROPPED before coverage, so a FORGED cert can
#     NEVER cause a skip (the security-critical property).
#   * coverage is the TC-1 ``verifyCoverage`` UNION over the trusted certs: a
#     required target is SKIPPED iff it is in the covered set for ``P``; every
#     other required target is RUN. A platform with no valid cert runs the full
#     required set (skip set empty) — exactly the "platforms without a valid
#     certificate run normally" rule.
#
# Trust is an EXPLICIT project decision (``ci_trust``): under ``cctSkip`` the
# covered targets are skipped; under ``cctAdvisory`` (the default) NOTHING is
# skipped — CI re-runs everything authoritatively and the valid cert is surfaced
# as an informational note. So a project never fast-tracks by omission; granting
# the trust is a deliberate ``ci_trust = "skip"``.
#
# The GitHub-Actions YAML / external CI wiring is OUT OF SCOPE here (the same
# honest deferral as the TC-6 Vivafolio/GitHub receiving side): this milestone
# ships the DECISION + issuance core (``repro ci plan`` + the existing TC-1/TC-5
# issuance path) and DOCUMENTS how a CI job consumes the machine-readable plan
# (run the RUN set, skip the SKIP set, issue a cert on green). See
# DEFER-TC4-CI-YAML below.
# ============================================================================

type
  CiTargetDecision* = enum
    ## Per-target verdict in a CI plan. ``ctdSkip`` — a VALID cert covers this
    ## target for the platform and the project's ``ci_trust`` is ``skip`` →
    ## fast-track (do not re-run). ``ctdRun`` — no valid coverage (or
    ## ``ci_trust = advisory``) → CI runs the target authoritatively.
    ctdSkip = "skip"
    ctdRun = "run"

  CiPlatformPlan* = object
    ## The CI fast-track plan for ONE platform. ``skip`` is the set of required
    ## targets a valid certificate already covers (empty under ``advisory`` or
    ## when no valid cert covers them); ``run`` is the complement CI must
    ## execute. ``advisoryNote`` carries the human-readable trust framing
    ## (e.g. "valid cert present but ci_trust=advisory — re-running").
    platform*: string
    skip*: seq[string]
    run*: seq[string]
    matchingCerts*: int          ## valid certs matching commit/lock/platform.
    untrustedCerts*: seq[string] ## why a present-but-untrusted cert was dropped.
    advisoryNote*: string

  CiPlan* = object
    ## The whole-project CI fast-track plan: one ``CiPlatformPlan`` per platform
    ## requested (or per required platform when ``--platform`` is omitted),
    ## plus the binding the decision was made against.
    commit*: string
    lock*: string
    requiredTargets*: seq[string]
    ciTrust*: CertificateCiTrust
    platforms*: seq[CiPlatformPlan]

proc computeCiPlatformPlan*(certs: openArray[TestCertificate];
                            commit, lock, platform: string;
                            requiredTargets: seq[string];
                            ciTrust: CertificateCiTrust;
                            keyStore: RegisteredKeyStore): CiPlatformPlan =
  ## The CORE per-platform decision (pure: no IO). Given the certs attached to
  ## ``commit`` and the project's required targets, returns which targets CI can
  ## SKIP (covered by a VALID cert for ``platform``) and which it must RUN.
  ##
  ## SECURITY-CRITICAL: a cert counts ONLY when ``verifyCertificateSignature``
  ## says ``svValid`` (TC-5) AND it matches the binding (TC-1
  ## ``certificateMatches`` inside ``verifyCoverage``). A forged / unsigned /
  ## wrong-key / revoked / wrong-commit / wrong-platform cert is dropped, so it
  ## CANNOT move a target into ``skip``.
  result.platform = platform
  # 1. Filter to TRUSTED certs (registered-signed, unrevoked, sig verifies).
  #    REUSE the exact TC-5 verifier the push gate uses — no second code path.
  var trusted: seq[TestCertificate]
  for cert in certs:
    let verdict = verifyCertificateSignature(cert, keyStore)
    if verdict == svValid:
      trusted.add(cert)
    else:
      let why =
        case verdict
        of svUnsigned: "unsigned"
        of svUnregisteredKey: "key_id '" & cert.keyId & "' not registered"
        of svRevokedKey: "key_id '" & cert.keyId & "' revoked"
        of svBadSignature: "signature does not verify"
        of svToolingUnavailable: "ssh-keygen unavailable (cannot verify)"
        of svValid: ""
      result.untrustedCerts.add(cert.platform & ": " & why)
  # 2. Coverage for THIS platform — REUSE the TC-1 ``verifyCoverage`` union (it
  #    also enforces the commit/lock/platform binding via ``certificateMatches``).
  let req = CoverageRequirement(
    commit: commit, lock: lock, platform: platform,
    requiredTargets: requiredTargets)
  let cov = verifyCoverage(trusted, req)
  result.matchingCerts = cov.matchingCerts
  # 3. Apply the EXPLICIT trust decision. Under ``cctSkip`` a covered required
  #    target is skipped; under ``cctAdvisory`` nothing is skipped (re-run all)
  #    but a valid covering cert is surfaced as advisory. ``coveredTargets`` is
  #    already the union restricted to matching certs, so intersecting with the
  #    required set yields exactly the skippable targets.
  let covered = cov.coveredTargets.toHashSet()
  for t in requiredTargets:
    if ciTrust == cctSkip and t in covered:
      result.skip.add(t)
    else:
      result.run.add(t)
  if ciTrust == cctAdvisory and result.matchingCerts > 0:
    # A valid cert exists but the project chose advisory: re-run everything,
    # surface the cert as a signal (NOT a skip).
    let coveredReq = requiredTargets.filterIt(it in covered)
    if coveredReq.len > 0:
      result.advisoryNote = "valid certificate covers [" &
        coveredReq.join(", ") & "] for " & platform &
        " but ci_trust=advisory — re-running authoritatively (cert is a signal)"

proc renderCiPlanJson*(plan: CiPlan): JsonNode =
  ## Machine-readable plan a CI job consumes: per platform, the ``skip`` and
  ## ``run`` target sets plus the binding and trust mode. A CI job runs the
  ## ``run`` set, skips the ``skip`` set, and (on green) issues a cert for the
  ## platform covering the run set (see DEFER-TC4-CI-YAML).
  result = newJObject()
  result["schema"] = %"reprobuild.ci-plan.v1"
  result["commit"] = %plan.commit
  result["lock"] = %plan.lock
  result["ci_trust"] = %($plan.ciTrust)
  result["required_targets"] = %plan.requiredTargets
  var platforms = newJArray()
  for pp in plan.platforms:
    var o = newJObject()
    o["platform"] = %pp.platform
    o["skip"] = %pp.skip
    o["run"] = %pp.run
    o["matching_certs"] = %pp.matchingCerts
    if pp.untrustedCerts.len > 0:
      o["untrusted_certs"] = %pp.untrustedCerts
    if pp.advisoryNote.len > 0:
      o["advisory_note"] = %pp.advisoryNote
    platforms.add(o)
  result["platforms"] = platforms

type
  TestRunOutcome* = object
    ## TC-1: the REAL result of a test run, captured so certificate issuance
    ## reflects what actually happened (never a hardcoded pass). ``ran`` is
    ## true once a real run occurred (vs. a plan-only / discovery-only path);
    ## ``allPassed`` is true only when at least one target ran and none
    ## failed; ``passedTargets`` is exactly the targets that PASSED (the
    ## certificate's covered set).
    ran*: bool
    allPassed*: bool
    passedTargets*: seq[string]
    failedTargets*: seq[string]

proc parseReproTestFlags(args: openArray[string]): ReproTestShardOpts =
  result.strategy = "joint-duration"
  result.binDir = "build/test-bin"
  # TC-1: issuance is on by default (a ``repro test`` run issues a certificate
  # in a clean state). ``--no-certify`` opts out.
  result.certify = true
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--shard" or arg.startsWith("--shard="):
      let v = valueFromFlag(args, i, "--shard")
      let parsed = parseShardSpec(v)
      if not parsed.ok:
        raise newException(ValueError,
          "invalid --shard value: " & v & " (expected <k>/<N>, 1-indexed)")
      result.shardIndex = parsed.k
      result.shardCount = parsed.n
    elif arg == "--partition-strategy" or arg.startsWith("--partition-strategy="):
      result.strategy = valueFromFlag(args, i, "--partition-strategy")
    elif arg == "--peer-cache" or arg.startsWith("--peer-cache="):
      result.peerCacheSpec = valueFromFlag(args, i, "--peer-cache")
    elif arg == "--emit-partition-plan" or
        arg.startsWith("--emit-partition-plan="):
      result.emitPlanPath = valueFromFlag(args, i, "--emit-partition-plan")
    elif arg == "--plan-from" or arg.startsWith("--plan-from="):
      result.planFromPath = valueFromFlag(args, i, "--plan-from")
    elif arg == "--fixture-from" or arg.startsWith("--fixture-from="):
      result.fixturePath = valueFromFlag(args, i, "--fixture-from")
    elif arg == "--bin-dir" or arg.startsWith("--bin-dir="):
      result.binDir = valueFromFlag(args, i, "--bin-dir")
    elif arg == "--write-report":
      # The build verb accepts the bare form and writes to its conventional
      # report path. Do not consume the following selector as a path.
      result.buildFlags.add(arg)
    elif arg.startsWith("--write-report="):
      result.reportPath = valueFromFlag(args, i, "--write-report")
      result.buildFlags.add("--write-report=" & result.reportPath)
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      result.toolProvisioning = parseToolProvisioning(
        valueFromFlag(args, i, "--tool-provisioning"))
    elif arg == "--variant" or arg.startsWith("--variant="):
      # Spec-Implementation M1 — relay through ``runBuildCommand``'s
      # contract: ``--variant name=value`` is appended to the
      # ``REPRO_VARIANTS`` env var so the provider process picks it up
      # via ``repro_dsl_stdlib/configurables/variants.nim``. The CLI
      # surface mirrors the ``repro build`` arm so ``repro test``
      # inherits the same flag automatically.
      let spec = valueFromFlag(args, i, "--variant")
      if spec.find('=') <= 0:
        raise newException(ValueError,
          "--variant expects name=value (got: " & spec & ")")
      var existing = getEnv("REPRO_VARIANTS")
      if existing.len > 0:
        existing.add(',')
      existing.add(spec)
      putEnv("REPRO_VARIANTS", existing)
    elif arg == "--release" or arg == "--debug":
      # Standard-configuration shorthand: sugar for ``--variant
      # buildType=release|debug`` (Standard-Configurations.md).
      let cfg = arg[2 .. ^1]
      var existing = getEnv("REPRO_VARIANTS")
      if existing.len > 0:
        existing.add(',')
      existing.add("buildType=" & cfg)
      putEnv("REPRO_VARIANTS", existing)
    elif arg == "--daemon" or arg.startsWith("--daemon="):
      # Pass-through to ``runBuildCommand`` when ``repro test`` falls
      # through to the verb-alias path (no shard flags supplied). The
      # plain ``--daemon=off`` / ``--daemon=auto`` shape is widely
      # used by the recorder CIs and by manual triage — without
      # threading it here the alias path's diagnostic "unsupported
      # repro test flag: --daemon=off" surprises users who learned
      # the flag from ``repro build``.
      let v = valueFromFlag(args, i, "--daemon")
      result.daemonFlag = "--daemon=" & v
    elif arg == "--lock" or arg.startsWith("--lock="):
      # MO-1 carry-through: select an alternate committed solved-graph
      # lock for the verb-alias path. ``runBuildCommand`` honours
      # ``--lock <file>`` (default = the canonical ``repro.lock``).
      result.lockFlag = "--lock=" & valueFromFlag(args, i, "--lock")
    elif arg == "--work-root" or arg.startsWith("--work-root="):
      result.buildFlags.add("--work-root=" &
        valueFromFlag(args, i, "--work-root"))
    elif arg == "--action-cache-root" or
        arg.startsWith("--action-cache-root="):
      result.buildFlags.add("--action-cache-root=" &
        valueFromFlag(args, i, "--action-cache-root"))
    elif arg == "--progress" or arg.startsWith("--progress="):
      result.buildFlags.add("--progress=" &
        valueFromFlag(args, i, "--progress"))
    elif arg == "--progress-bars" or arg.startsWith("--progress-bars="):
      result.buildFlags.add("--progress-bars=" &
        valueFromFlag(args, i, "--progress-bars"))
    elif arg == "--measure" or arg.startsWith("--measure="):
      result.buildFlags.add("--measure=" &
        valueFromFlag(args, i, "--measure"))
    elif arg == "--show" or arg.startsWith("--show="):
      result.buildFlags.add("--show=" & valueFromFlag(args, i, "--show"))
    elif arg == "--write-diagnostics" or
        arg.startsWith("--write-diagnostics="):
      result.buildFlags.add("--write-diagnostics=" &
        valueFromFlag(args, i, "--write-diagnostics"))
    elif arg == "--write-benchmark" or
        arg.startsWith("--write-benchmark="):
      result.buildFlags.add("--write-benchmark=" &
        valueFromFlag(args, i, "--write-benchmark"))
    elif arg == "--write-stats":
      result.buildFlags.add(arg)
    elif arg.startsWith("--write-stats="):
      result.buildFlags.add(arg)
    elif arg == "--stats-groups" or arg.startsWith("--stats-groups="):
      result.buildFlags.add("--stats-groups=" &
        valueFromFlag(args, i, "--stats-groups"))
    elif arg == "--log" or arg.startsWith("--log="):
      result.buildFlags.add("--log=" & valueFromFlag(args, i, "--log"))
    elif arg == "--package" or arg.startsWith("--package="):
      result.buildFlags.add("--package=" &
        valueFromFlag(args, i, "--package"))
    elif arg in [
        "--no-write-report", "-v", "--verbose", "-vv", "--very-verbose",
        "--prepare-only", "--dry-run", "--force-rebuild", "--rebuild",
        "--no-output-cleanup", "--publish-cache-hits",
        "--publish-materialized", "--skip-cmake-regeneration",
        "--no-runquota", "--runquota", "--unicode", "--no-unicode",
        "--list-targets", "--list-targets-json", "--json",
        "--print-solved-graph"]:
      result.buildFlags.add(arg)
    elif arg == "--certify":
      result.certify = true
      result.certifyExplicit = true
    elif arg == "--no-certify":
      result.certify = false
      result.noCertify = true
    elif arg == "--certificate-out" or arg.startsWith("--certificate-out="):
      result.certificateOut = valueFromFlag(args, i, "--certificate-out")
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.certWorkspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--current-repo" or arg.startsWith("--current-repo="):
      result.certCurrentRepo = valueFromFlag(args, i, "--current-repo")
    elif arg == "--ct-incremental-trace-dir" or
        arg.startsWith("--ct-incremental-trace-dir="):
      result.certTraceDir = valueFromFlag(args, i, "--ct-incremental-trace-dir")
    elif arg.startsWith("-"):
      raise newException(ValueError, "unsupported repro test flag: " & arg)
    else:
      result.selectors.add(arg)
    inc i

proc loadReproTestFixture(path: string): ReproTestFixture =
  if not fileExists(path):
    raise newException(IOError, "fixture file not found: " & path)
  let raw = readFile(path)
  let parsed = parseJson(raw)
  result.fallbackBuildCostNs =
    if parsed.hasKey("fallbackBuildCostNs"):
      parsed["fallbackBuildCostNs"].getBiggestInt().int64
    else: 1_000_000'i64
  result.fallbackTestCostNs =
    if parsed.hasKey("fallbackTestCostNs"):
      parsed["fallbackTestCostNs"].getBiggestInt().int64
    else: 1_000_000'i64
  result.historyDir =
    if parsed.hasKey("historyDir"): parsed["historyDir"].getStr()
    else: ""
  result.estimateDbPath =
    if parsed.hasKey("estimateDbPath"): parsed["estimateDbPath"].getStr()
    else: ""
  result.estimateScope =
    if parsed.hasKey("estimateScope"): parsed["estimateScope"].getStr()
    else: ""
  result.policy =
    if parsed.hasKey("policy") and parsed["policy"].getStr() == "shared":
      sipShared
    else: sipIndependent
  result.refinementPasses =
    if parsed.hasKey("refinementPasses"):
      parsed["refinementPasses"].getInt()
    else: DefaultRefinementPasses
  if parsed.hasKey("buildActions"):
    for a in parsed["buildActions"].elems:
      var deps: seq[NodeId] = @[]
      if a.hasKey("deps"):
        for d in a["deps"].elems:
          deps.add(nodeId(uint64(d.getInt())))
      var buildCmd: seq[string] = @[]
      if a.hasKey("buildCmd"):
        for s in a["buildCmd"].elems:
          buildCmd.add(s.getStr())
      result.actions.add(ReproTestFixtureAction(
        id: nodeId(uint64(a["id"].getInt())),
        commandStatsId:
          if a.hasKey("commandStatsId"): a["commandStatsId"].getStr() else: "",
        deps: deps,
        buildCmd: buildCmd))
  if parsed.hasKey("testEdges"):
    for e in parsed["testEdges"].elems:
      var buildDeps: seq[NodeId] = @[]
      if e.hasKey("buildDeps"):
        for d in e["buildDeps"].elems:
          buildDeps.add(nodeId(uint64(d.getInt())))
      var runCmd: seq[string] = @[]
      if e.hasKey("runCmd"):
        for s in e["runCmd"].elems:
          runCmd.add(s.getStr())
      result.edges.add(ReproTestFixtureEdge(
        id: nodeId(uint64(e["id"].getInt())),
        selector:
          if e.hasKey("selector"): e["selector"].getStr() else: "",
        historyKey:
          if e.hasKey("historyKey"): e["historyKey"].getStr() else: "",
        buildDeps: buildDeps,
        runCmd: runCmd,
        testName:
          if e.hasKey("testName"): e["testName"].getStr() else: ""))

proc fixtureToShardPlanRequest(f: ReproTestFixture; shardCount: int;
                               selectors: seq[string]): ShardPlanRequest =
  result.shardCount = shardCount
  result.targetSelectors = selectors
  result.policy = f.policy
  result.historyDir = f.historyDir
  result.estimateDbPath = f.estimateDbPath
  result.estimateScope = f.estimateScope
  result.fallbackBuildCostNs = f.fallbackBuildCostNs
  result.fallbackTestCostNs = f.fallbackTestCostNs
  result.refinementPasses = f.refinementPasses
  for a in f.actions:
    result.buildActions.add(ShardBuildAction(
      id: a.id,
      commandStatsId: a.commandStatsId,
      deps: a.deps))
  for e in f.edges:
    result.testEdges.add(ShardTestEdge(
      id: e.id,
      selector: e.selector,
      historyKey: e.historyKey,
      buildDeps: e.buildDeps))

proc shardAssignmentIds(plan: ShardPlan; shardIndex: int): seq[NodeId] =
  for a in plan.partition.assignments:
    if a.shardIndex == shardIndex:
      result.add(a.root)

proc closureActionsForShard(fixture: ReproTestFixture; rootIds: seq[NodeId]):
    seq[ReproTestFixtureAction] =
  var actionById = initTable[NodeId, ReproTestFixtureAction]()
  for a in fixture.actions:
    actionById[a.id] = a
  var edgeById = initTable[NodeId, ReproTestFixtureEdge]()
  for e in fixture.edges:
    edgeById[e.id] = e
  var visited = initHashSet[NodeId]()
  var ordered: seq[NodeId] = @[]

  proc dfs(id: NodeId) =
    if id in visited:
      return
    visited.incl(id)
    if actionById.hasKey(id):
      for dep in actionById[id].deps:
        dfs(dep)
      ordered.add(id)

  for root in rootIds:
    if edgeById.hasKey(root):
      for dep in edgeById[root].buildDeps:
        dfs(dep)
  for id in ordered:
    result.add(actionById[id])

proc runFixtureCmd(cmd: seq[string]; cwd: string): tuple[code: int; output: string] =
  if cmd.len == 0:
    return (0, "")
  # Redirect the child's stdout+stderr to a temp file rather than a pipe.
  # A pipe-based ``readLine`` loop blocks indefinitely when a test forks
  # a long-lived subprocess that keeps the inherited stdout fd open past
  # the test's own exit (a reproducible failure mode in the CI-sharding
  # M4 demonstration harness on the real reprobuild suite — multiple
  # tests spawn sibling daemons / monitors that survive the test).
  # File-backed IO has no liveness coupling: ``waitForExit`` on the
  # leader returns as soon as the leader is gone regardless of any
  # grandchild state.
  let logPath = getTempDir() / ("repro-test-fixture-" &
    $epochTime() & "-" & $getCurrentProcessId() & ".log")
  # Build an argv that pipes the original command through ``sh -c`` with
  # explicit stdout/stderr redirection.  When the caller already wraps
  # in ``sh -c``, we append the redirection to the existing -c body.
  var argv: seq[string] = @[]
  if cmd.len >= 3 and cmd[0] == "sh" and cmd[1] == "-c":
    let body = cmd[2] & " >'" & logPath & "' 2>&1"
    argv = @["sh", "-c", body]
  else:
    var quoted: seq[string] = @[]
    for s in cmd:
      quoted.add(quoteShell(s))
    let body = quoted.join(" ") & " >'" & logPath & "' 2>&1"
    argv = @["sh", "-c", body]
  let process = startProcess(argv[0],
    workingDir = cwd,
    args = argv[1 .. ^1],
    options = {poUsePath, poStdErrToStdOut})
  defer: process.close()
  let code = process.waitForExit(timeout = -1)
  var buf = ""
  if fileExists(logPath):
    try:
      buf = readFile(logPath)
    except CatchableError:
      discard
    try:
      removeFile(logPath)
    except OSError:
      discard
  return (code, buf)

proc writePartitionFile(path: string; edges: seq[ReproTestFixtureEdge]) =
  var lines: seq[string] = @[]
  lines.add("# CI-Sharding M2 partition file — one fully-qualified test per line.")
  for e in edges:
    if e.testName.len > 0:
      lines.add(e.testName)
    elif e.selector.len > 0:
      lines.add(e.selector)
  let parent = parentDir(path)
  if parent.len > 0 and not dirExists(parent):
    createDir(parent)
  writeFile(path, lines.join("\n") & "\n")

proc edgesAssignedToShard(fixture: ReproTestFixture;
                          plan: ShardPlan;
                          shardIndex: int): seq[ReproTestFixtureEdge] =
  var byId = initTable[NodeId, ReproTestFixtureEdge]()
  for e in fixture.edges:
    byId[e.id] = e
  for a in plan.partition.assignments:
    if a.shardIndex == shardIndex and byId.hasKey(a.root):
      result.add(byId[a.root])

proc predictedShardCostNs(plan: ShardPlan; shardIndex: int): int64 =
  let idx = shardIndex - 1
  if idx < 0 or idx >= plan.partition.perShardCost.len:
    return 0
  plan.partition.perShardCost[idx].inNanoseconds

proc writeShardReport(path: string; meta: JsonNode) =
  let parent = parentDir(path)
  if parent.len > 0 and not dirExists(parent):
    createDir(parent)
  writeFile(path, meta.pretty() & "\n")

## ----------------------------------------------------------------------------
## CI-Sharding M2 deviation fix — workspace-driven discovery, build, and
## ct-test-runner handoff. Replaces the M2 ``--fixture-from=<JSON>`` deviation
## with the real reprobuild integration the M3 benchmark milestone depends on.
##
## The three helpers below mirror the M2 follow-up bullets in
## ``CI-Sharding.milestones.org``:
##
##   1. ``discoverTestEdgesFromWorkspace`` — walks the engine's normalised
##      graph artefact (via ``prepareBuildGraphInspection``) and returns one
##      ``ShardTestEdge`` per declared ``NimUnittestBinary`` action plus the
##      build-action graph that backs the edges' closures.
##   2. ``buildClosureForShard`` — delegates to ``runBuildCommand`` (the
##      Named-Targets M2 resolver) to build the ``:test`` aggregate.  The
##      simpler whole-aggregate path is acceptable here because the M3
##      benchmark milestone is the one that optimises build-phase
##      parallelism.
##   3. ``invokeCtTestRunner`` — locates the sibling ct-test-runner (mirroring
##      ``scripts/run_tests.sh``'s cut-over rule from Test-Edges M4) or the
##      fallback ``tools/test-runner/repro_test_runner`` and invokes it with
##      the assigned binary paths as positional arguments — that gives
##      whole-binary sharding without requiring per-test protocol probing.

type
  WorkspaceTestDiscovery = object
    actions: seq[ShardBuildAction]
    edges: seq[ShardTestEdge]
    edgeBinaryPath: Table[NodeId, string]
      ## Maps each test-edge root id to the binary stem (``build/test-bin/<stem>``)
      ## the engine emits for that edge.  Populated from ``typedOutputs.path``.

proc stableNodeIdFromString(value: string): NodeId =
  ## Deterministic 64-bit id derived from an action id string.  We use the
  ## std/hashes ``Hash`` (which mixes the bytes) and reinterpret it as
  ## ``uint64`` so the resulting ``NodeId`` is stable across runs and
  ## reproducible across shards (every shard recomputes the plan locally,
  ## per CI-Sharding.md §"CI Sharding").
  nodeId(cast[uint64](hashes.hash(value)))

proc isNimUnittestBinaryEdge(action: BuildAction): bool =
  for typedOutput in action.typedOutputs:
    for typeName in typedOutput.types:
      if typeName == "NimUnittestBinary":
        return true
  false

proc nimUnittestBinaryPath(action: BuildAction): string =
  for typedOutput in action.typedOutputs:
    for typeName in typedOutput.types:
      if typeName == "NimUnittestBinary":
        return typedOutput.path
  ""

proc discoverTestEdgesFromWorkspace(projectRoot: string;
                                    publicCliPath: string;
                                    mode: ToolProvisioningMode = tpmUnspecified):
    WorkspaceTestDiscovery =
  ## Walks the engine's normalised graph artefact for ``projectRoot`` and
  ## returns one ``ShardTestEdge`` per action whose typed-output type is
  ## ``NimUnittestBinary``.  The whole build-action graph is returned as
  ## ``actions`` so the planner can walk the dependency closures when
  ## costing each edge.
  result.edgeBinaryPath = initTable[NodeId, string]()
  let info = prepareBuildGraphInspection(projectRoot, mode,
    publicCliPath, selectDefaultAction = false)
  # Build a unique-id table so we don't double-add an action that appears
  # multiple times in ``info.actions`` (the engine returns one entry per
  # action id but defensive code is cheap).
  var seenIds = initHashSet[NodeId]()
  for action in info.actions:
    let nid = stableNodeIdFromString(action.id)
    if nid in seenIds:
      continue
    seenIds.incl(nid)
    var deps: seq[NodeId] = @[]
    for depId in action.deps:
      deps.add(stableNodeIdFromString(depId))
    result.actions.add(ShardBuildAction(
      id: nid,
      commandStatsId: action.commandStatsId,
      deps: deps))
  # Test edges: actions whose typedOutputs declare ``NimUnittestBinary``.
  # Use a separate id space for the edge root (hash of "test:" + actionId)
  # so the planner's ``PartitionRoot.id`` and the build-graph node id never
  # collide on the same NodeId — the bridge node the planner adds for the
  # root would otherwise overwrite the action's real node.
  for action in info.actions:
    if not isNimUnittestBinaryEdge(action):
      continue
    let buildActionId = stableNodeIdFromString(action.id)
    let edgeId = stableNodeIdFromString("test::" & action.id)
    let binaryPath = nimUnittestBinaryPath(action)
    result.edges.add(ShardTestEdge(
      id: edgeId,
      selector: action.id,
      historyKey: extractFilename(binaryPath),
      buildDeps: @[buildActionId]))
    result.edgeBinaryPath[edgeId] = binaryPath

proc writeWorkspacePartitionFile(path: string;
                                 binaryPaths: openArray[string]) =
  ## Writes the per-shard partition file in the ct-test-runner format:
  ## one fully-qualified test name per line.  For the workspace path we
  ## record the binary stem (whole-binary sharding) which the runner
  ## treats as an opaque-binary entry; this matches the documented format
  ## while still being trivial to author from the test-edge metadata.
  var lines: seq[string] = @[]
  lines.add(
    "# CI-Sharding M2 workspace partition file " &
    "— one fully-qualified test per line.")
  for binPath in binaryPaths:
    let stem = splitFile(binPath).name
    if stem.len > 0:
      lines.add(stem)
  let parent = parentDir(path)
  if parent.len > 0 and not dirExists(parent):
    createDir(parent)
  writeFile(path, lines.join("\n") & "\n")

proc buildClosureForShard(assignedSelectors: seq[string];
                          publicCliPath: string;
                          mode: ToolProvisioningMode = tpmUnspecified;
                          lockFlag = ""):
    tuple[code: int; output: string] =
  ## Builds the closure of the assigned test edges via ``runBuildCommand``.
  ## The strategy note in the milestone documents the trade-off: building
  ## the whole ``:test`` aggregate is simpler than computing the union of
  ## per-shard closures and lets the engine's existing dedup do its job;
  ## M3 will optimise this once the benchmark milestone is on the table.
  ##
  ## ``lockFlag`` (Workspace-Manifest-Optional MO-13, correcting MO-1) is the
  ## ``--lock=<file>`` carry-through. When set, the sharded build PINS the
  ## locked solved graph — the sharded run builds against the LOCKED
  ## revisions, exactly like the verb-alias path already did — rather than
  ## re-solving from live inputs.
  if assignedSelectors.len == 0:
    return (0, "")
  let bin =
    if publicCliPath.len > 0 and fileExists(publicCliPath): publicCliPath
    else: stablePublicCliPath()
  doAssert fileExists(bin), "repro binary missing at " & bin
  var buildArgs = @["build", "test"]
  if mode != tpmUnspecified:
    buildArgs.add("--tool-provisioning=" & modeName(mode))
  if lockFlag.len > 0:
    buildArgs.add(lockFlag)
  let p = startProcess(bin,
    workingDir = getCurrentDir(),
    args = buildArgs,
    options = {poUsePath, poStdErrToStdOut})
  defer: p.close()
  var buf = ""
  let outp = p.outputStream
  var line = newStringOfCap(120)
  while true:
    if outp.readLine(line):
      buf.add(line)
      buf.add("\n")
    else:
      let code = p.peekExitCode()
      if code != -1:
        return (code, buf)

proc locateCtTestRunner(): string =
  ## Prefer an explicitly installed ``ct-test-runner`` binary and otherwise
  ## fall back to ``tools/test-runner/repro_test_runner`` (the M3 internal
  ## protocol-level runner). Returns ``""`` when neither is available — the
  ## caller surfaces a diagnostic.
  let exeExt = when defined(windows): ".exe" else: ""
  let fromEnv = getEnv("CT_TEST_RUNNER")
  if fromEnv.len > 0 and fileExists(fromEnv):
    return absolutePath(fromEnv)
  let fromPath = findExe("ct-test-runner" & exeExt)
  if fromPath.len > 0:
    return fromPath
  let fallback = "build" / "bin" / "repro_test_runner" & exeExt
  if fileExists(fallback):
    return absolutePath(fallback)
  let toolsFallback = "tools" / "test-runner" / "repro_test_runner" & exeExt
  if fileExists(toolsFallback):
    return absolutePath(toolsFallback)
  ""

proc invokeCtTestRunner(runnerBin, binDir, partitionFile, summaryJson,
                        resultsDir: string;
                        threads: int;
                        assignedBinaryPaths: seq[string]):
    tuple[code: int; output: string] =
  ## Spawns the located runner with the per-shard parameters.  Passes
  ## assigned binary paths positionally (the runner skips ``--bin-dir``
  ## scanning when positionals are supplied, per its ``main`` proc).  We
  ## pass ``--partition`` too so the run is documented end-to-end even
  ## when positionals would otherwise have selected the same set — that
  ## keeps the partition file as a load-bearing input rather than a
  ## post-hoc record.
  var args: seq[string] = @[]
  args.add("run")
  args.add("--bin-dir=" & binDir)
  args.add("--summary-json=" & summaryJson)
  args.add("--results-dir=" & resultsDir)
  if threads > 0:
    args.add("--threads=" & $threads)
  args.add("--no-build")  # Build phase already completed via repro build.
  for binPath in assignedBinaryPaths:
    args.add(binPath)
  let p = startProcess(runnerBin,
    workingDir = getCurrentDir(),
    args = args,
    options = {poUsePath, poStdErrToStdOut})
  defer: p.close()
  var buf = ""
  let outp = p.outputStream
  var line = newStringOfCap(120)
  while true:
    if outp.readLine(line):
      buf.add(line)
      buf.add("\n")
    else:
      let code = p.peekExitCode()
      if code != -1:
        return (code, buf)

proc discoveryToShardPlanRequest(disc: WorkspaceTestDiscovery;
                                 shardCount: int;
                                 selectors: seq[string]): ShardPlanRequest =
  result.shardCount = shardCount
  result.targetSelectors = selectors
  result.policy = sipIndependent
  result.fallbackBuildCostNs = 1_000_000_000'i64
  result.fallbackTestCostNs = 1_000_000_000'i64
  result.refinementPasses = DefaultRefinementPasses
  result.buildActions = disc.actions
  result.testEdges = disc.edges

proc edgesAssignedToShardWorkspace(disc: WorkspaceTestDiscovery;
                                   plan: ShardPlan;
                                   shardIndex: int): seq[ShardTestEdge] =
  var byId = initTable[NodeId, ShardTestEdge]()
  for e in disc.edges:
    byId[e.id] = e
  for a in plan.partition.assignments:
    if a.shardIndex == shardIndex and byId.hasKey(a.root):
      result.add(byId[a.root])

proc loadSummaryJsonOrNull(path: string): JsonNode =
  if path.len == 0 or not fileExists(path):
    return newJNull()
  try:
    return parseJson(readFile(path))
  except CatchableError:
    return newJNull()

proc summarizeTestResults(summary: JsonNode): tuple[passed, failed: int] =
  ## Reads ``summary["summary"]["passed"]`` / ``["failed"]`` (the schema the
  ## ct-test-runner / repro_test_runner writes).  Returns ``(0, 0)`` on a
  ## null / malformed document so callers can still write a report.
  if summary.isNil or summary.kind != JObject:
    return (0, 0)
  if not summary.hasKey("summary"):
    return (0, 0)
  let s = summary["summary"]
  if s.kind != JObject:
    return (0, 0)
  result.passed =
    if s.hasKey("passed") and s["passed"].kind == JInt: s["passed"].getInt()
    else: 0
  result.failed =
    if s.hasKey("failed") and s["failed"].kind == JInt: s["failed"].getInt()
    else: 0

proc shardLockProvenance(opts: ReproTestShardOpts):
    tuple[lockPath, inputsDigest: string; packageCount: int; found: bool] =
  ## Workspace-Manifest-Optional MO-13 (correcting MO-1) — resolve the
  ## committed solved-graph lock the sharded run should honor, using the
  ## SAME loader (``resolveSolvedGraphForBuild``) the real ``repro build``
  ## uses. ``opts.lockFlag`` carries ``--lock=<file>``; absent, the canonical
  ## ``<cwd>/repro.lock`` is used. The provenance (resolved path + the lock's
  ## ``inputs_digest`` + pinned package count) is recorded in the shard report
  ## so the sharded/fixture run is demonstrably tied to the LOCKED graph, not
  ## a fresh re-solve. A no-op (``found = false``) when no lock is present, so
  ## every pre-existing shard run (no ``repro.lock``) is byte-unchanged.
  let lockOverride =
    if opts.lockFlag.startsWith("--lock="):
      opts.lockFlag["--lock=".len .. ^1]
    else: ""
  let resolved = resolveSolvedGraphForBuild(getCurrentDir(), lockOverride, "")
  result.found = resolved.found and resolved.source == "lock"
  if result.found:
    result.lockPath = resolved.lockPath
    result.packageCount = resolved.solution.packages.len
    try:
      result.inputsDigest =
        parseSolvedGraphLock(readFile(extendedPath(resolved.lockPath))).inputsDigest
    except CatchableError:
      result.inputsDigest = ""

proc addShardLockProvenance(report: JsonNode; opts: ReproTestShardOpts) =
  ## Stamp the resolved lock provenance onto a shard report (MO-13).
  let prov = shardLockProvenance(opts)
  report["lock_flag"] = %opts.lockFlag
  report["lock_file"] = %(if prov.found: prov.lockPath else: "")
  report["locked_inputs_digest"] = %prov.inputsDigest
  report["locked_package_count"] = %prov.packageCount

proc runFixtureModeShard(opts: ReproTestShardOpts;
                         peer: PeerCacheSpecResult;
                         outcome: var TestRunOutcome): int =
  ## The M2 fixture path, preserved verbatim for the existing M2 e2e
  ## tests.  Behaviour is unchanged from the original
  ## ``runReproTestCommand`` body — the workspace-mode dispatch above
  ## simply forwards here when ``--fixture-from`` is supplied. TC-1 adds
  ## the ``outcome`` out-param so certificate issuance can reflect the REAL
  ## per-target pass/fail (never a hardcoded pass).
  var fixture: ReproTestFixture
  try:
    fixture = loadReproTestFixture(opts.fixturePath)
  except CatchableError as exc:
    emitShardDiagnostic("failed to load fixture: " & exc.msg)
    return 2

  var plan: ShardPlan
  var planMeta: ShardPlanRequest
  if opts.planFromPath.len > 0:
    try:
      let loaded = readPartitionPlanJson(opts.planFromPath)
      plan = loaded.plan
      planMeta = loaded.meta
    except PartitionPlanReadError as exc:
      emitShardDiagnostic("failed to read partition plan: " & exc.msg)
      return 2
  else:
    let shardCount =
      if opts.shardCount > 0: opts.shardCount
      else: 1
    let req = fixtureToShardPlanRequest(fixture, shardCount, opts.selectors)
    plan = planTestShards(req)
    planMeta = req

  if opts.emitPlanPath.len > 0:
    try:
      writePartitionPlanJson(plan, opts.emitPlanPath, planMeta)
    except CatchableError as exc:
      emitShardDiagnostic("failed to write partition plan: " & exc.msg)
      return 1
    return 0

  if opts.shardCount == 0:
    emitShardDiagnostic("--shard <k>/<N> is required for an actual run")
    return 2

  let peerCacheMode = modeName(peer.kind)
  let assignedRoots = shardAssignmentIds(plan, opts.shardIndex)
  let assignedEdges = edgesAssignedToShard(fixture, plan, opts.shardIndex)
  let actionsClosure = closureActionsForShard(fixture, assignedRoots)

  let buildStart = epochTime()
  var buildFailed = false
  var buildOutput = ""
  for a in actionsClosure:
    let res = runFixtureCmd(a.buildCmd, getCurrentDir())
    buildOutput.add(res.output)
    if res.code != 0:
      buildFailed = true
      stderr.writeLine("repro test: build action failed: " &
        $a.id.value & " — exit " & $res.code)
      break
  let buildElapsedNs = int64((epochTime() - buildStart) * 1_000_000_000.0)

  let partitionFilePath =
    "test-logs" / ("partition-" & $opts.shardIndex & "-of-" &
      $opts.shardCount & ".txt")
  writePartitionFile(partitionFilePath, assignedEdges)

  let testStart = epochTime()
  var testResults = newJArray()
  var passed = 0
  var failed = 0
  if not buildFailed:
    for e in assignedEdges:
      let res = runFixtureCmd(e.runCmd, getCurrentDir())
      var node = newJObject()
      node["edge_id"] = %int(e.id.value)
      node["selector"] = %e.selector
      node["test_name"] = %e.testName
      node["status"] = %(if res.code == 0: "PASS" else: "FAIL")
      node["exit_code"] = %res.code
      node["output"] = %res.output
      testResults.add(node)
      # TC-1: record the REAL per-target verdict. The covered set is exactly
      # the selectors whose run command exited 0.
      let targetName = if e.selector.len > 0: e.selector else: e.testName
      if res.code == 0:
        inc passed
        outcome.passedTargets.add(targetName)
      else:
        inc failed
        outcome.failedTargets.add(targetName)
  let testElapsedNs = int64((epochTime() - testStart) * 1_000_000_000.0)

  let predictedNs = predictedShardCostNs(plan, opts.shardIndex)
  let actualNs = buildElapsedNs + testElapsedNs
  let delta =
    if predictedNs > 0:
      (float(actualNs) - float(predictedNs)) / float(predictedNs)
    else:
      0.0
  let driftThreshold = 0.5
  let drift = abs(delta) > driftThreshold

  var report = newJObject()
  report["schemaId"] = %"reprobuild.shard-report.v1"
  report["shard"] = %opts.shardIndex
  report["shardCount"] = %opts.shardCount
  report["strategy"] = %opts.strategy
  report["peer_cache"] = %peerCacheMode
  report["fixture_path"] = %opts.fixturePath
  addShardLockProvenance(report, opts)
  var assignedNames = newJArray()
  for e in assignedEdges:
    assignedNames.add(%e.selector)
  report["assigned_selectors"] = assignedNames
  report["predicted_shard_cost_ns"] = %predictedNs
  report["predicted_build_time_ns"] = %0
  report["predicted_test_time_ns"] = %0
  report["actual_build_time_ns"] = %buildElapsedNs
  report["actual_test_time_ns"] = %testElapsedNs
  report["actual_total_time_ns"] = %actualNs
  report["cost_model_delta"] = %delta
  report["cost_model_drift"] = %drift
  report["build_failed"] = %buildFailed
  report["tests"] = testResults
  report["test_pass_count"] = %passed
  report["test_fail_count"] = %failed
  report["partition_file"] = %partitionFilePath
  report["degraded_plan"] = %plan.degraded
  report["unknown_build_count"] = %plan.unknownBuildCount
  report["unknown_test_count"] = %plan.unknownTestCount

  let reportPath =
    if opts.reportPath.len > 0: opts.reportPath
    else:
      "test-logs" / ("shard-" & $opts.shardIndex & "-of-" &
        $opts.shardCount & ".json")
  writeShardReport(reportPath, report)

  # TC-1: finalise the run outcome. A run "ran" once we got past the build
  # phase to the per-edge loop; ``allPassed`` requires at least one edge and
  # no failure (and no build failure).
  outcome.ran = not buildFailed
  outcome.allPassed = (not buildFailed) and failed == 0 and passed > 0

  if buildFailed:
    return 1
  if failed > 0:
    return 1
  0

proc runWorkspaceModeShard(opts: ReproTestShardOpts;
                           peer: PeerCacheSpecResult;
                           publicCliPath: string): int =
  ## Workspace-driven shard runner.  Discovers real test edges via the
  ## engine's normalised graph artefact, builds the closure via
  ## ``repro build test``, and hands off to ct-test-runner with the
  ## assigned binaries.  Replaces the M2 ``--fixture-from`` deviation
  ## for the on-the-suite case the M3 benchmark milestone depends on.
  var disc: WorkspaceTestDiscovery
  try:
    disc = discoverTestEdgesFromWorkspace(".", publicCliPath,
      opts.toolProvisioning)
  except CatchableError as exc:
    emitShardDiagnostic(
      "workspace test-edge discovery failed: " & exc.msg)
    return 2
  if disc.edges.len == 0:
    emitShardDiagnostic(
      "workspace test-edge discovery returned no NimUnittestBinary " &
      "edges; nothing to shard.  (Did you mean to pass --fixture-from?)")
    return 2

  var plan: ShardPlan
  var planMeta: ShardPlanRequest
  if opts.planFromPath.len > 0:
    try:
      let loaded = readPartitionPlanJson(opts.planFromPath)
      plan = loaded.plan
      planMeta = loaded.meta
    except PartitionPlanReadError as exc:
      emitShardDiagnostic("failed to read partition plan: " & exc.msg)
      return 2
  else:
    let shardCount =
      if opts.shardCount > 0: opts.shardCount
      else: 1
    let req = discoveryToShardPlanRequest(disc, shardCount, opts.selectors)
    plan = planTestShards(req)
    planMeta = req

  if opts.emitPlanPath.len > 0:
    try:
      writePartitionPlanJson(plan, opts.emitPlanPath, planMeta)
    except CatchableError as exc:
      emitShardDiagnostic("failed to write partition plan: " & exc.msg)
      return 1
    return 0

  if opts.shardCount == 0:
    emitShardDiagnostic("--shard <k>/<N> is required for an actual run")
    return 2

  let peerCacheMode = modeName(peer.kind)
  let assignedEdges =
    edgesAssignedToShardWorkspace(disc, plan, opts.shardIndex)
  var assignedBinaryPaths: seq[string] = @[]
  var assignedSelectors: seq[string] = @[]
  for e in assignedEdges:
    assignedSelectors.add(e.selector)
    if disc.edgeBinaryPath.hasKey(e.id):
      assignedBinaryPaths.add(disc.edgeBinaryPath[e.id])

  # ----- Build phase: build the :test aggregate.  See the milestone
  # strategy note for why we don't compute per-shard closures here.
  let buildStart = epochTime()
  var buildFailed = false
  let buildRes = buildClosureForShard(assignedSelectors, publicCliPath,
    opts.toolProvisioning, opts.lockFlag)
  if buildRes.code != 0:
    buildFailed = true
    stderr.writeLine("repro test: workspace build phase failed " &
      "(exit " & $buildRes.code & ")")
    stderr.write(buildRes.output)
  let buildElapsedNs = int64((epochTime() - buildStart) * 1_000_000_000.0)

  # ----- Partition file: written before the test phase so the
  # per-shard report can reference it even when the runner skips it.
  let partitionFilePath =
    "test-logs" / ("partition-" & $opts.shardIndex & "-of-" &
      $opts.shardCount & ".txt")
  writeWorkspacePartitionFile(partitionFilePath, assignedBinaryPaths)

  # ----- Test phase: locate ct-test-runner (or the internal fallback),
  # invoke with the assigned binary set.
  let summaryJson =
    "test-logs" / ("shard-" & $opts.shardIndex & "-of-" &
      $opts.shardCount & "-summary.json")
  let resultsDir =
    "test-logs" / ("shard-" & $opts.shardIndex & "-of-" &
      $opts.shardCount & "-results")
  if not dirExists(resultsDir):
    createDir(resultsDir)
  let runnerBin = locateCtTestRunner()
  let testStart = epochTime()
  var runnerOutput = ""
  var runnerCode = 0
  var runnerInvoked = false
  if buildFailed:
    discard
  elif runnerBin.len == 0:
    stderr.writeLine("repro test: no ct-test-runner located " &
      "(checked CT_TEST_RUNNER, PATH, build/bin/repro_test_runner, " &
      "tools/test-runner/repro_test_runner). " &
      "Build a runner before sharding.")
    runnerCode = 1
  elif assignedBinaryPaths.len == 0:
    # Nothing assigned to this shard — still write a summary record.
    discard
  else:
    runnerInvoked = true
    let invocation = invokeCtTestRunner(runnerBin,
      "build/test-bin", partitionFilePath, summaryJson, resultsDir,
      0, assignedBinaryPaths)
    runnerCode = invocation.code
    runnerOutput = invocation.output
  let testElapsedNs = int64((epochTime() - testStart) * 1_000_000_000.0)

  let runnerSummary = loadSummaryJsonOrNull(summaryJson)
  let counts = summarizeTestResults(runnerSummary)

  let predictedNs = predictedShardCostNs(plan, opts.shardIndex)
  let actualNs = buildElapsedNs + testElapsedNs
  let delta =
    if predictedNs > 0:
      (float(actualNs) - float(predictedNs)) / float(predictedNs)
    else:
      0.0
  let driftThreshold = 0.5
  let drift = abs(delta) > driftThreshold

  # Build the per-test results array from the runner's summary, so the
  # per-shard report carries per-test outcomes (not just aggregate
  # counts).
  var testResults = newJArray()
  if runnerSummary.kind == JObject and runnerSummary.hasKey("tests") and
      runnerSummary["tests"].kind == JArray:
    for entry in runnerSummary["tests"].elems:
      testResults.add(entry)

  var report = newJObject()
  report["schemaId"] = %"reprobuild.shard-report.v1"
  report["shard"] = %opts.shardIndex
  report["shardCount"] = %opts.shardCount
  report["strategy"] = %opts.strategy
  report["peer_cache"] = %peerCacheMode
  report["fixture_path"] = %""  # workspace mode — no fixture
  report["mode"] = %"workspace"
  addShardLockProvenance(report, opts)
  report["runner_binary"] = %runnerBin
  report["runner_invoked"] = %runnerInvoked
  report["runner_exit_code"] = %runnerCode
  report["summary_json"] = %summaryJson
  if not runnerSummary.isNil and runnerSummary.kind != JNull:
    report["runner_summary"] = runnerSummary
  else:
    report["runner_summary"] = newJNull()
  var assignedNames = newJArray()
  for sel in assignedSelectors:
    assignedNames.add(%sel)
  report["assigned_selectors"] = assignedNames
  var assignedBins = newJArray()
  for p in assignedBinaryPaths:
    assignedBins.add(%p)
  report["assigned_binaries"] = assignedBins
  report["predicted_shard_cost_ns"] = %predictedNs
  report["predicted_build_time_ns"] = %0
  report["predicted_test_time_ns"] = %0
  report["actual_build_time_ns"] = %buildElapsedNs
  report["actual_test_time_ns"] = %testElapsedNs
  report["actual_total_time_ns"] = %actualNs
  report["cost_model_delta"] = %delta
  report["cost_model_drift"] = %drift
  report["build_failed"] = %buildFailed
  report["tests"] = testResults
  report["test_pass_count"] = %counts.passed
  report["test_fail_count"] = %counts.failed
  report["partition_file"] = %partitionFilePath
  report["degraded_plan"] = %plan.degraded
  report["unknown_build_count"] = %plan.unknownBuildCount
  report["unknown_test_count"] = %plan.unknownTestCount

  let reportPath =
    if opts.reportPath.len > 0: opts.reportPath
    else:
      "test-logs" / ("shard-" & $opts.shardIndex & "-of-" &
        $opts.shardCount & ".json")
  writeShardReport(reportPath, report)

  if buildFailed:
    return 1
  if counts.failed > 0 or runnerCode != 0:
    return 1
  0

proc issuerHostTag(): string =
  ## A best-effort host label for the certificate's ``issuer`` field. Reads
  ## the conventional env vars (set on every platform's shells / CI) and
  ## falls back to ``unknown-host``. We avoid ``std/net.getHostname`` so this
  ## module does not pull in the networking stack for a cosmetic label.
  for key in ["HOSTNAME", "COMPUTERNAME", "HOST"]:
    let v = getEnv(key)
    if v.len > 0:
      return v
  "unknown-host"

proc fixtureSelectors(opts: ReproTestShardOpts): seq[string] =
  ## TC-1: the set of test-target selectors a fixture run will execute — the
  ## covered set a re-certify's existing certificate must already include for
  ## the no-op decision. Reads the fixture file; on any load error returns the
  ## empty seq (the caller then treats it as "nothing to cover" → never a
  ## no-op, so the tests run).
  try:
    let fixture = loadReproTestFixture(opts.fixturePath)
    for e in fixture.edges:
      let name = if e.selector.len > 0: e.selector else: e.testName
      if name.len > 0:
        result.add(name)
  except CatchableError:
    discard

proc runReproTestCommand*(args: openArray[string];
                          publicCliPath: string): int =
  ## ``repro test`` entry point with the CI-sharding flag surface from
  ## ``CI-Sharding.md`` §"CLI Surface".  See the block comment above
  ## for the per-flag semantics.
  var opts: ReproTestShardOpts
  try:
    opts = parseReproTestFlags(args)
  except ValueError as exc:
    emitShardDiagnostic(exc.msg)
    return 2

  # ``--peer-cache=lan://CIDR[:port]`` — Peer-Cache M2 wires this
  # through to the multicast discovery plane. The CI-Sharding M3
  # benchmark consumes the resulting peer-cache via the
  # action-cache-reader seam (which is opt-in at the engine level
  # until the digest impedance from Peer-Cache.milestones.org §M1
  # Outstanding Tasks is resolved).
  let peer = parsePeerCache(opts.peerCacheSpec)
  if not peer.ok:
    emitShardDiagnostic(
      "invalid --peer-cache spec: " & opts.peerCacheSpec &
      " (expected ``none``, ``lan://<CIDR>``, or ``remote://<URL>``)")
    return 2
  if peer.kind == pcsLan:
    # Generate a transient peer ID for this shard. The CLI doesn't
    # yet persist a peer ID to ``peer_cache.peer_id_path`` from the
    # spec's configuration surface — that lands once M3 introduces a
    # multi-host setup. For M2's loopback validation the transient
    # ID is sufficient.
    var raw: array[32, byte]
    raw[0] = byte(ord('R'))  # ``R`` for repro test, distinct from
                             # the loopback helper's ``L``.
    let nowSeconds = uint64(epochTime())
    for i in 0 ..< 8:
      raw[1 + i] = byte((nowSeconds shr uint64(i * 8)) and 0xff'u64)
    let cliPeerId = peerIdFromBytes(raw)
    try:
      lastStartedPeerCacheRuntime =
        startPeerCacheServices(peer.config, cliPeerId,
                              listenAddr = "127.0.0.1")
    except CatchableError as exc:
      emitShardDiagnostic(
        "failed to start peer-cache services: " & exc.msg)
      return 2

  # ``--partition-strategy hash`` / ``duration`` — recognised by the
  # parser but the wired strategies in M2 are ``joint-duration`` (the
  # planner-driven path) and ``slice`` (a planner cold-cache fallback).
  case opts.strategy
  of "joint-duration", "slice":
    discard
  of "hash", "duration":
    emitShardDiagnostic(
      "--partition-strategy=" & opts.strategy &
      " is not implemented in this milestone — see CI-Sharding " &
      "M3+ for the duration/hash strategies.")
    return 2
  else:
    emitShardDiagnostic(
      "unknown --partition-strategy value: " & opts.strategy)
    return 2

  if opts.shardCount == 0 and opts.emitPlanPath.len == 0 and
      opts.planFromPath.len == 0:
    # Verb-alias path per Build-Graph-Collections.md §"Verb Aliases for
    # Conventional Collections": ``repro test`` without any shard flags
    # is byte-for-byte equivalent to ``repro build test``. Delegate to
    # ``runBuildCommand`` so the user gets the conventional ``test``
    # collection materialised end-to-end without having to remember
    # the CI-sharding-specific surface. The shard CLI is the
    # multi-machine CI path; the alias is the inner-loop "run my
    # tests" path.
    var buildArgs = opts.buildFlags
    if opts.toolProvisioning != tpmUnspecified:
      buildArgs.add("--tool-provisioning=" & opts.toolProvisioning.modeName)
    if opts.daemonFlag.len > 0:
      buildArgs.add(opts.daemonFlag)
    if opts.lockFlag.len > 0:
      buildArgs.add(opts.lockFlag)
    if opts.peerCacheSpec.len > 0:
      buildArgs.add("--peer-cache=" & opts.peerCacheSpec)
    if opts.selectors.len == 0:
      buildArgs.add("test")
    else:
      for sel in opts.selectors:
        buildArgs.add(sel)
    return runBuildCommand(buildArgs, publicCliPath)

  # Two code paths from here:
  #   (a) ``--fixture-from=<path>`` — the M2 fixture path, kept for
  #       backwards compatibility with the existing M2 e2e tests.  See
  #       ``runFixtureModeShard`` below.
  #   (b) Workspace mode — discover real test edges via the engine's
  #       normalised graph artefact, build the closure, and hand off to
  #       ct-test-runner.  This is the CI-Sharding M2 follow-up that
  #       this milestone fix delivers.
  if opts.fixturePath.len > 0:
    # ---- TC-1 certificate issuance (fixture path) ----------------------
    # The fixture path runs REAL trivial commands and reports REAL per-target
    # pass/fail, so a certificate issued here reflects the actual run (never a
    # hardcoded pass). When ``--certify`` is set (the default) AND a workspace
    # is resolvable, we:
    #   1. Evaluate the issuance preconditions by REUSING the RA-21 gate.
    #   2. If a re-certify with NO relevant change → NO-OP (keep the existing
    #      cert, do NOT re-run the tests).
    #   3. Otherwise run the tests; on a real pass in a clean state, issue a
    #      certificate; on dirty/unpushed/off-lock, run but withhold the cert
    #      and print the ambient remedy.
    if not opts.certify:
      # ``--no-certify``: just run, no issuance.
      var outcome: TestRunOutcome
      return runFixtureModeShard(opts, peer, outcome)
    if opts.certWorkspaceRoot.len == 0:
      # No workspace target → fall back to a plain run (cannot bind a cert to
      # a lock without a workspace). Honest: no silent partial issuance.
      var outcome: TestRunOutcome
      let code = runFixtureModeShard(opts, peer, outcome)
      stderr.writeLine("repro test: no certificate — pass --workspace-root " &
        "(and --current-repo) so the run can be bound to a committed lock")
      return code
    let pre = evaluateIssuancePreconditions(
      opts.certWorkspaceRoot, opts.certCurrentRepo, opts.toolProvisioning)
    let certOut =
      if opts.certificateOut.len > 0: opts.certificateOut
      elif pre.kind == ipOk:
        defaultCertificatePath(opts.certWorkspaceRoot, pre.commit, pre.platform)
      else: ""
    # Requested targets = the selectors the fixture will run (the covered set
    # a re-certify must already cover for the no-op to hold).
    let requestedTargets = fixtureSelectors(opts)
    # No-op check BEFORE running: only meaningful when issuable + a prior cert.
    if pre.kind == ipOk and certOut.len > 0:
      let projectRoot =
        if opts.certCurrentRepo.len > 0: opts.certCurrentRepo
        else: opts.certWorkspaceRoot
      let cachePath = defaultCachePath(projectRoot)
      if certificateNoOpDecision(certOut, pre, requestedTargets,
          opts.certTraceDir, projectRoot, cachePath):
        stderr.writeLine("repro test: re-certify is a no-op — the existing " &
          "certificate at " & certOut & " already covers " &
          $pre.commit & " on " & pre.platform & " (no relevant change; " &
          "tests not re-run)")
        return 0
    # Run the tests (real result captured in ``outcome``).
    var outcome: TestRunOutcome
    let code = runFixtureModeShard(opts, peer, outcome)
    # Decide issuance from the REAL outcome + preconditions.
    if pre.kind != ipOk:
      let label =
        case pre.kind
        of ipDirty: "working tree dirty"
        of ipUnpublished: "dependency has unpushed commits"
        of ipOffLock: "repo not at the locked revision"
        of ipNoWorkspace: "not a workspace"
        of ipGateError: "workspace gate error"
        of ipOk: ""
      stderr.writeLine("repro test: no certificate — " & label &
        (if pre.offender.len > 0: " (" & pre.offender & ")" else: "") &
        (if pre.remedy.len > 0: " — " & pre.remedy else: ""))
    elif not outcome.allPassed:
      stderr.writeLine("repro test: no certificate — the run did not pass " &
        "(result is not 'passed'); fix the failing targets and re-run")
    else:
      var cert = issueCertificate(pre, outcome.passedTargets,
        "repro-test@" & issuerHostTag())
      # TC-5: the daemon signs the canonical certificate payload (ed25519) as a
      # side effect of THIS observed clean+passing run. Signing is reachable
      # ONLY here (the issuance path) — there is no "sign this blob" command.
      # Fail closed: if the daemon cannot sign (no key / no ssh-keygen), no
      # certificate is written — we never emit an unsigned/faked one.
      let keyId = reproSigningKeyId()
      let keyPath = reproSigningKeyPath(opts.certWorkspaceRoot)
      try:
        signCertificateOnIssuance(cert, keyId, keyPath)
      except CertificateSigningError as err:
        stderr.writeLine("repro test: no certificate — the daemon could not " &
          "sign it (" & err.msg & "); the attestation is withheld")
        return code
      writeCertificateFile(cert, certOut)
      stderr.writeLine("repro test: issued " & testCertificateSchemaV1 &
        " covering [" & outcome.passedTargets.join(", ") & "] for " &
        cert.platform & " at " & cert.commit & " → " & certOut &
        " (signed " & certificateSignatureAlgorithm & ", key_id=" &
        cert.keyId & ")")
    return code
  return runWorkspaceModeShard(opts, peer, publicCliPath)

# --------------------------------------------------------------------
# TC-4 — `repro ci plan` subcommand (the CI fast-track decision)
# --------------------------------------------------------------------
#
# `repro ci plan [--platform=P ...] [--json]` resolves the project's certificate
# policy + the (commit, lock) binding the certs must match, reads the certs
# attached to HEAD (TC-2 git-notes carrier), and emits the per-platform SKIP/RUN
# plan a CI job consumes. The decision REUSES the TC-5 signature verifier + the
# TC-1 coverage union (via ``computeCiPlatformPlan``) so the CI trust boundary is
# byte-for-byte the push gate's: only a registered-signed, unrevoked,
# commit+lock+platform-matching cert can move a target into SKIP, and only when
# the project explicitly set ``ci_trust = "skip"``.
#
# HOW A CI JOB CONSUMES THE PLAN (the external-YAML deferral, DEFER-TC4-CI-YAML):
# a CI workflow runs `repro ci plan --platform=$RUNNER_PLATFORM --json`, runs the
# `run` target set (e.g. `repro test --certify <run targets>`), skips the `skip`
# set, and — on green — the issuance path (already wired into `repro test`)
# writes + signs a certificate covering the run set for the platform, which the
# workflow attaches with `repro push` so a green CI run is itself a presentable
# certificate. The `.github/workflows/*.yml` that glues these calls together is
# EXTERNAL (CI-runner-specific) and intentionally NOT shipped here — the
# hermetically-testable decision + issuance core is complete and the YAML is the
# honest deferral.

type
  CiPlanArgs = object
    workspaceRoot: string
    currentRepo: string
    platforms: seq[string]   ## explicit ``--platform`` values; empty ⇒ all required.
    json: bool
    toolProvisioning: ToolProvisioningMode

proc parseCiPlanArgs(args: openArray[string]): CiPlanArgs =
  result.toolProvisioning = tpmUnspecified
  for a in args:
    if a == "--json": result.json = true
    elif a.startsWith("--platform="):
      let v = a["--platform=".len .. ^1].strip()
      if v.len > 0: result.platforms.add(v)
    elif a.startsWith("--workspace-root="):
      result.workspaceRoot = a["--workspace-root=".len .. ^1]
    elif a.startsWith("--current-repo="):
      result.currentRepo = a["--current-repo=".len .. ^1]
    else:
      raise newException(ValueError, "repro ci plan: unknown argument '" &
        a & "'")
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc runCiPlanCommand(args: openArray[string]): int =
  ## ``repro ci plan`` — the per-platform CI fast-track decision (TC-4).
  let parsed = parseCiPlanArgs(args)
  # Resolve the project's certificate policy (required targets/platforms +
  # ci_trust). REUSE the same manifest resolution the develop/check paths use.
  var policy: CertificatePolicy
  try:
    let resolved = resolveDevelopWorkspaceProject(parsed.workspaceRoot)
    policy = resolved.certificatePolicy
  except CatchableError as err:
    stderr.writeLine("repro ci plan: could not resolve a project policy: " &
      err.msg)
    return 1
  # The platforms to plan for: explicit ``--platform`` values, else every
  # required platform. (A platform CI asks about that is NOT in the required set
  # is still planned — it simply has no required coverage obligation, so it runs
  # the full required target set.)
  let planPlatforms =
    if parsed.platforms.len > 0: parsed.platforms
    else: policy.requiredPlatforms
  if policy.requiredTargets.len == 0:
    stderr.writeLine("repro ci plan: project declares no required_targets — " &
      "nothing to plan (CI runs its own targets normally)")
  # Resolve the (commit, lock) binding the certs must match. We REUSE the
  # issuance-precondition evaluator so the binding is IDENTICAL to what issuance
  # and the push gate bind to (HEAD commit + clean-lock digest). When the state
  # is not issuable (dirty / off-lock / no lock), there is no trustworthy
  # binding, so NOTHING is skipped — CI runs everything (fail-safe).
  let pre = evaluateIssuancePreconditions(
    parsed.workspaceRoot, parsed.currentRepo, parsed.toolProvisioning)
  var commit = pre.commit
  var lock = pre.lockDigest
  var bindingNote = ""
  if pre.kind != ipOk:
    commit = ""
    lock = ""
    bindingNote = "no trustworthy (commit, lock) binding (" &
      (if pre.remedy.len > 0: pre.remedy else: "state not issuable") &
      ") — running every target"
  # Read the certs attached to HEAD (TC-2). With no binding we have nothing to
  # match against, so the trusted-cert set is empty and every target runs.
  var attached: seq[TestCertificate]
  if commit.len > 0:
    let certRepoPath =
      if parsed.currentRepo.len > 0: parsed.currentRepo
      else: parsed.workspaceRoot
    let identity = ensureGitToolResolvable(
      if parsed.toolProvisioning == tpmUnspecified: tpmPathOnly
      else: parsed.toolProvisioning, getEnv("PATH"))
    attached = readAttachedCertificates(identity.binaryPath, certRepoPath, commit)
  let keyStore = readRegisteredKeyStore(
    registeredKeyStorePath(parsed.workspaceRoot))
  var plan = CiPlan(
    commit: commit, lock: lock,
    requiredTargets: policy.requiredTargets,
    ciTrust: policy.ciTrust)
  for platform in planPlatforms:
    var pp =
      if commit.len == 0 or lock.len == 0:
        # No binding ⇒ run the full required set on this platform.
        CiPlatformPlan(platform: platform, run: policy.requiredTargets)
      else:
        computeCiPlatformPlan(attached, commit, lock, platform,
          policy.requiredTargets, policy.ciTrust, keyStore)
    if bindingNote.len > 0 and pp.advisoryNote.len == 0:
      pp.advisoryNote = bindingNote
    plan.platforms.add(pp)
  if parsed.json:
    echo renderCiPlanJson(plan).pretty()
  else:
    echo "ci plan @ " & (if commit.len >= 12: commit[0 ..< 12]
                         else: "<no-binding>") &
      "  ci_trust=" & $policy.ciTrust
    for pp in plan.platforms:
      echo "  " & pp.platform & ":  skip=[" & pp.skip.join(", ") &
        "]  run=[" & pp.run.join(", ") & "]" &
        (if pp.advisoryNote.len > 0: "  (" & pp.advisoryNote & ")" else: "")
  return 0

proc runCiCommand(args: openArray[string]): int =
  ## ``repro ci <subcommand>``. Currently ``plan`` (the TC-4 fast-track
  ## decision) is the only subcommand; the verb namespace is reserved for
  ## further CI-facing helpers.
  if args.len == 0:
    stderr.writeLine("repro ci: missing subcommand (expected: plan)")
    return 1
  case args[0]
  of "plan":
    return runCiPlanCommand(if args.len > 1: args[1 .. ^1] else: @[])
  else:
    stderr.writeLine("repro ci: unknown subcommand '" & args[0] &
      "' (expected: plan)")
    return 1

# --------------------------------------------------------------------
# Spec-Implementation M2e — `repro lock explain <variant>` subcommand
# --------------------------------------------------------------------
#
# Surfaces the M2e structured ``ExplainChain`` (for chosen-variant
# justifications) and the assumption-interface unsat-core (for
# unsatisfiable solves) on the operator-facing CLI. The verb lives
# under the ``repro lock`` namespace per Locking-And-Solver.md
# §"CLI Surface" (which earmarks ``repro lock solve``, ``debug``, and
# ``visualize`` for the same namespace; ``explain`` is the M2e sibling).
#
# The subcommand operates in two modes:
#
#   1. **Fixture mode** (``--fixture <path>``): the fixture file is a
#      tiny declarative format describing variants + packages so the
#      command is testable without a full project on disk. The format
#      is line-oriented and intentionally minimal — it is NOT a
#      replacement for the project DSL.
#
#   2. **Default mode**: when no fixture is supplied, the command
#      reports an error explaining that workspace-driven explain
#      requires an active build context (M3+ wiring; M2e ships the
#      fixture mode so the diagnostic surface is testable on its
#      own).
#
# Output: human-readable text by default; ``--json`` emits a
# machine-readable JSON document.

type
  FixtureParserState = object
    variants: seq[variant_encoder.VariantDecl]
    packages: seq[PackageDecl]
    currentKind: string
    currentName: string
    vKind: VariantKind
    vValues: seq[string]
    vContribs: seq[VariantContribution]
    vConstraints: seq[ConstraintExpr]
    vPinned: string
    pVersions: seq[string]
    pDepends: seq[DependencyDecl]
    pSource: string
    pPinned: bool

proc flushFixtureBlock(s: var FixtureParserState) =
  if s.currentKind == "variant":
    s.variants.add(variant_encoder.VariantDecl(
      name: s.currentName, kind: s.vKind,
      allowedValues: s.vValues,
      contributions: s.vContribs,
      constraints: s.vConstraints,
      pinnedValue: s.vPinned))
  elif s.currentKind == "package":
    s.packages.add(PackageDecl(
      name: s.currentName, versions: s.pVersions,
      depends: s.pDepends, variants: @[], source: s.pSource,
      pinned: s.pPinned))
  s.currentKind = ""
  s.currentName = ""
  s.vKind = vkEnum
  s.vValues = @[]
  s.vContribs = @[]
  s.vConstraints = @[]
  s.vPinned = ""
  s.pVersions = @[]
  s.pDepends = @[]
  s.pSource = ""
  s.pPinned = false

proc parseExplainFixture(text: string): tuple[
    variants: seq[variant_encoder.VariantDecl],
    packages: seq[PackageDecl]] =
  ## Parse the M2e fixture format. The format is a sequence of blocks
  ## separated by blank lines; each block declares one variant or one
  ## package. Variant blocks start with ``variant <name>``; package
  ## blocks start with ``package <name>``. Inside a variant block:
  ##
  ##   kind: bool|enum
  ##   values: a, b, c          (enum only)
  ##   default: <value>
  ##   pinned: <value>          (NLF-M3 — assignment decided by a lock)
  ##   set: <value>             (vpSet contribution)
  ##   override: <value>        (vpOverride contribution)
  ##   force: <value>           (vpForce contribution)
  ##   requires: <src> -> <target> = <value>
  ##   conflicts: <src> -> <target> = <value>
  ##   propagates: <src> -> <target> = <value>
  ##
  ## Inside a package block:
  ##
  ##   versions: 1.0.0, 1.1.0
  ##   depends: <name> <range>
  ##   depends: <name> <range> when <variant>=<value>
  ##   source: store                  (MO-11 — a repro-store-realized artifact)
  ##   source: registry <registry>    (MO-11 — a package-registry dependency)
  ##   pinned: true                   (NLF-M2 — version observed, not solved)
  var s = FixtureParserState(
    variants: @[], packages: @[],
    currentKind: "", currentName: "",
    vKind: vkEnum, vValues: @[],
    vContribs: @[], vConstraints: @[],
    pVersions: @[], pDepends: @[], pSource: "")

  for rawLine in text.splitLines():
    let line = rawLine.strip()
    if line.len == 0:
      if s.currentKind.len > 0:
        flushFixtureBlock(s)
      continue
    if line.startsWith("#"):
      continue
    if line.startsWith("variant "):
      if s.currentKind.len > 0: flushFixtureBlock(s)
      s.currentKind = "variant"
      s.currentName = line[len("variant ") .. ^1].strip()
      continue
    if line.startsWith("package "):
      if s.currentKind.len > 0: flushFixtureBlock(s)
      s.currentKind = "package"
      s.currentName = line[len("package ") .. ^1].strip()
      continue
    let colonAt = line.find(':')
    if colonAt < 0: continue
    let key = line[0 ..< colonAt].strip()
    let val = line[colonAt + 1 .. ^1].strip()
    case s.currentKind
    of "variant":
      case key
      of "kind":
        if val == "bool":
          s.vKind = vkBool
          s.vValues = @["true", "false"]
        else:
          s.vKind = vkEnum
      of "values":
        s.vKind = vkEnum
        s.vValues = @[]
        for piece in val.split(','):
          s.vValues.add(piece.strip())
      of "default":
        s.vContribs.add(contribution(vpDefault, val))
      of "set":
        s.vContribs.add(contribution(vpSet, val))
      of "override":
        s.vContribs.add(contribution(vpOverride, val))
      of "force":
        s.vContribs.add(contribution(vpForce, val))
      of "pinned":
        # NLF-M3 — the variant's value is DECIDED by a governing committed
        # lock. Round-tripped for the same reason the package-level `pinned`
        # is: this reader is what re-solves a rendered fixture, and dropping
        # the pin here would turn an asserted assignment back into a preference
        # on the way in, so the re-solve would answer a different question than
        # the solve that produced the text.
        s.vPinned = val.strip()
      of "requires", "conflicts", "propagates":
        # Format: "<sourceValue> -> <target> = <value>"
        let arrow = val.find("->")
        if arrow < 0: continue
        let sourceValue = val[0 ..< arrow].strip()
        let rhs = val[arrow + 2 .. ^1].strip()
        let eq = rhs.find('=')
        if eq < 0: continue
        let target = rhs[0 ..< eq].strip()
        let targetValue = rhs[eq + 1 .. ^1].strip()
        case key
        of "requires":
          s.vConstraints.add(requiresExpr(sourceValue, target, targetValue))
        of "conflicts":
          s.vConstraints.add(conflictsExpr(sourceValue, target, targetValue))
        of "propagates":
          s.vConstraints.add(propagatesExpr(sourceValue, target, targetValue))
        else: discard
      else: discard
    of "package":
      case key
      of "versions":
        s.pVersions = @[]
        for piece in val.split(','):
          s.pVersions.add(piece.strip())
      of "depends":
        # "name range" or "name range when variant=value"
        let whenAt = val.find(" when ")
        var head = val
        var gateVariant = ""
        var gateValue = ""
        if whenAt >= 0:
          head = val[0 ..< whenAt].strip()
          let gate = val[whenAt + len(" when ") .. ^1].strip()
          let eq = gate.find('=')
          if eq >= 0:
            gateVariant = gate[0 ..< eq].strip()
            gateValue = gate[eq + 1 .. ^1].strip()
        let firstSpace = head.find(' ')
        if firstSpace < 0:
          s.pDepends.add(newDependency(head.strip(), ""))
        else:
          let depName = head[0 ..< firstSpace].strip()
          let depRange = head[firstSpace + 1 .. ^1].strip()
          if gateVariant.len > 0:
            s.pDepends.add(newConditionalDependency(
              depName, depRange, gateVariant, gateValue))
          else:
            s.pDepends.add(newDependency(depName, depRange))
      of "pinned":
        # NLF-M2 — the package's version is OBSERVED (a develop-mode
        # checkout), not selected. Round-tripped because this reader is what
        # re-solves a rendered fixture: dropping the flag here would turn a
        # pinned package back into a searched one on the way in, and the
        # re-solve would silently answer a different question than the solve
        # that produced the text.
        s.pPinned = val.strip().toLowerAscii() in ["true", "yes", "1"]
      of "source":
        # MO-11 — the package's source provenance. ``store`` marks a
        # repro-store-realized artifact; ``registry <name>`` marks a
        # package-registry dependency. Normalize to the canonical descriptor
        # the lock writer's lift consumes (``store`` / ``registry:<name>``).
        let parts = val.splitWhitespace()
        if parts.len > 0:
          if parts[0] == "registry" and parts.len >= 2:
            s.pSource = "registry:" & parts[1]
          elif parts[0] == "store":
            s.pSource = "store"
          else:
            s.pSource = val.strip()
      else: discard
    else: discard
  if s.currentKind.len > 0:
    flushFixtureBlock(s)
  result = (variants: s.variants, packages: s.packages)

# ---------------------------------------------------------------------------
# MO-1 — committed solved-graph lock: solver-inputs loading + the shared
# build-time resolver. These consume ``parseExplainFixture`` (above) and the
# ``repro_lock`` writer/reader, so their bodies live here; the forward
# declarations near ``runBuildCommand`` let the build path call them.
# ---------------------------------------------------------------------------

proc loadSolverInputsFile(path: string): tuple[
    variants: seq[variant_encoder.VariantDecl],
    packages: seq[PackageDecl], text: string] =
  ## Read a sidecar ``repro.solver`` (explain-fixture format) and parse it
  ## into the solver's input lists. ``text`` is the raw body, retained so
  ## the lock can record its ``inputs_digest`` provenance.
  let text = readFile(extendedPath(path))
  let parsed = parseExplainFixture(text)
  (variants: parsed.variants, packages: parsed.packages, text: text)

proc resolveSolvedGraphForBuild(projectDir, lockOverride,
                                inputsOverride: string): tuple[
    solution: UnifiedSolution, source: string, lockPath: string,
    found: bool] =
  ## The single chokepoint both ``repro build`` and ``--print-solved-graph``
  ## use to obtain the solved graph:
  ##   * a committed lock present (``--lock`` override or the canonical
  ##     ``<projectDir>/repro.lock``) → LOAD it (``source = "lock"``); the
  ##     build pins this graph rather than re-solving.
  ##   * else a ``repro.solver`` sidecar present → solve it implicitly
  ##     (``source = "solve"``), matching the spec's "ordinary commands
  ##     solve implicitly when no lock is present".
  ##   * else → an empty graph (``found = false``).
  ##
  ## Named-Lock-Files NLF-M5 — the implicit-solve branch is now the GENERATION
  ## PATH's ``runImplicitBuildSolve``, so ``repro build``'s implicit solve runs
  ## the same edges ``repro lock solve`` and ``repro lock refresh`` run (design
  ## §5.6, "one path, several doors"). It used to call ``solve()`` inline,
  ## which is the deviation `Core-Invariants.md` §"Graph Construction Is Not
  ## Side-Effect Execution" and `Build-Engine-And-Scheduler.md`
  ## §"Universal Edge-Based Execution and Invalidation" both rule out.
  ##
  ## The lock branch is unchanged and still comes FIRST, which is the whole of
  ## `Repository-And-Index-Format.md` §"Refresh Is Performed By Graph Edges"'s
  ## "a pinned build refreshes nothing": with a lock present the generation
  ## wave is never CONSTRUCTED, so there is no ``netFetch`` edge to skip.
  ##
  ## No registry is configured on this path, so an implicit solve emits no
  ## metadata-fetch edge at all and consults only the declared candidate
  ## versions — the same answer the pre-NLF-M5 inline ``solve()`` produced,
  ## which is why the rewiring is not a behaviour change for any existing
  ## workspace. ``--registry`` on the lock verbs is what turns the fetch on.
  let effectiveLock =
    if lockOverride.len > 0: lockOverride
    else: committedLockPath(projectDir)
  if fileExists(extendedPath(effectiveLock)):
    let lock = parseSolvedGraphLock(readFile(extendedPath(effectiveLock)))
    return (solution: lockToSolution(lock), source: "lock",
            lockPath: effectiveLock, found: true)
  let inputsP =
    if inputsOverride.len > 0: inputsOverride
    else: solverInputsPath(projectDir)
  if fileExists(extendedPath(inputsP)):
    let inputs = loadSolverInputsFile(inputsP)
    let workDir = getTempDir() /
      ("repro-implicit-solve-" & $getCurrentProcessId())
    defer:
      try: removeDir(extendedPath(workDir))
      except CatchableError: discard
    let generated = runImplicitBuildSolve(LockGenerationRequest(
      variants: inputs.variants,
      packages: inputs.packages,
      inputsText: inputs.text,
      platform: currentPlatformId(),
      strategy: lsDefault,
      endpoints: @[],
      workDir: workDir,
      extraDeps: @[],
      entryPoint: lgeImplicitBuildSolve))
    return (
      solution: lockToSolution(
        solvedPartOf(parseLockedDependencies(generated.lockDocument))),
      source: "solve", lockPath: effectiveLock, found: true)
  (solution: UnifiedSolution(variants: initTable[string, string](),
                             packages: initTable[string, string](),
                             optimal: false),
   source: "none", lockPath: effectiveLock, found: false)

proc renderExplainChainText(chain: ExplainChain): string =
  ## Human-readable rendering of an ExplainChain. Mirrors the shape
  ## of Spack's ``spack spec --explain`` output: one block per
  ## evidence kind, each prefixed by the variant name and the chosen
  ## value at the top.
  result = ""
  result.add("variant: " & chain.variant & "\n")
  result.add("chosen: " & chain.chosen & "\n")
  result.add("contributions:\n")
  if chain.contributions.len == 0:
    result.add("  (none)\n")
  else:
    for c in chain.contributions:
      let pName = case c.priority
        of vpDefault: "default"
        of vpSet: "set"
        of vpOverride: "override"
        of vpForce: "force"
      result.add("  - " & pName & " -> " & c.value & "\n")
  result.add("gating constraints:\n")
  if chain.gatingConstraints.len == 0:
    result.add("  (none)\n")
  else:
    for g in chain.gatingConstraints:
      let kindStr = case g.kind
        of crkRequires: "requires"
        of crkConflicts: "conflicts"
        of crkPropagates: "propagates"
      result.add("  - " & kindStr & ": " & g.sourceValue & " -> " &
                 g.target & "=" & g.targetValue & "\n")
  result.add("parent influences:\n")
  if chain.parentInfluences.len == 0:
    result.add("  (none)\n")
  else:
    for p in chain.parentInfluences:
      result.add("  - " & p.parentPackage & "." & p.parentVariant &
                 "==" & p.parentValue & "\n")

proc renderExplainChainJson(chain: ExplainChain): JsonNode =
  result = newJObject()
  result["variant"] = %chain.variant
  result["chosen"] = %chain.chosen
  let contribs = newJArray()
  for c in chain.contributions:
    let cj = newJObject()
    cj["priority"] = %(
      case c.priority
      of vpDefault: "default"
      of vpSet: "set"
      of vpOverride: "override"
      of vpForce: "force")
    cj["value"] = %c.value
    contribs.add(cj)
  result["contributions"] = contribs
  let gates = newJArray()
  for g in chain.gatingConstraints:
    let gj = newJObject()
    gj["kind"] = %(case g.kind
      of crkRequires: "requires"
      of crkConflicts: "conflicts"
      of crkPropagates: "propagates")
    gj["sourceValue"] = %g.sourceValue
    gj["target"] = %g.target
    gj["targetValue"] = %g.targetValue
    gates.add(gj)
  result["gatingConstraints"] = gates
  let parents = newJArray()
  for p in chain.parentInfluences:
    let pj = newJObject()
    pj["parentPackage"] = %p.parentPackage
    pj["parentVariant"] = %p.parentVariant
    pj["parentValue"] = %p.parentValue
    parents.add(pj)
  result["parentInfluences"] = parents

proc renderUnsatCoreText(entries: seq[UnsatCoreEntry];
                         programText: string): string =
  result = "UNSAT — minimal core:\n"
  if entries.len == 0:
    result.add("  (no minimal core produced; falling back to " &
               "best-effort participants)\n")
  else:
    for e in entries:
      result.add("  - [" & e.kind & "] " & e.source & "\n")

proc renderUnsatCoreJson(entries: seq[UnsatCoreEntry];
                        programText: string): JsonNode =
  result = newJObject()
  result["status"] = %"unsat"
  let arr = newJArray()
  for e in entries:
    let j = newJObject()
    j["kind"] = %e.kind
    j["source"] = %e.source
    j["atom"] = %e.atom
    arr.add(j)
  result["core"] = arr

type
  LockVerbOptions = object
    ## NLF-M5 — the generation-path flags shared by ``solve`` / ``refresh``.
    strategy: LockStrategy
    registries: seq[string]
    write: bool

proc parseLockVerbArgs(rest: openArray[string]; verb: string;
                       projectDir, inputsOverride, lockOverride,
                       platformOverride: var string; asJson: var bool;
                       gen: var LockVerbOptions): int =
  ## Shared arg parser for ``repro lock solve`` / ``refresh`` / ``validate``:
  ## ``[<projectDir>] [--inputs <file>] [--lock <file>] [--platform <p>]
  ## [--strategy <default|lowest|highest|lowest-direct>] [--lowest]
  ## [--highest] [--registry <url>] [--write] [--json]``. Returns 0 on
  ## success, 2 on a usage error (diagnostic already emitted).
  ##
  ## ``--lowest`` / ``--highest`` are the spellings `Locking-And-Solver.md`
  ## §"CLI Surface" names for `repro lock solve`, and NLF-M6 ships them as
  ## SUGAR over ``--strategy``: they assign the same field, so there is one
  ## strategy value and not two ways for it to be set. A later flag wins,
  ## which is the ordinary last-flag-wins rule every other option here
  ## follows.
  ##
  ## ``--strategy`` is `Named-Lock-Files.md` §5.5's whole-build spelling.
  ## ``--registry`` names a metadata index the generation wave may reach; with
  ## none given the generation emits no ``netFetch`` edge at all and the
  ## declared candidate versions are the whole universe, which is the
  ## behaviour every pre-NLF-M5 invocation had.
  var i = 0
  while i < rest.len:
    let arg = rest[i]
    if arg == "--inputs" or arg.startsWith("--inputs="):
      inputsOverride = valueFromFlag(rest, i, "--inputs")
    elif arg == "--lock" or arg.startsWith("--lock="):
      lockOverride = valueFromFlag(rest, i, "--lock")
    elif arg == "--platform" or arg.startsWith("--platform="):
      platformOverride = valueFromFlag(rest, i, "--platform")
    elif arg == "--strategy" or arg.startsWith("--strategy="):
      let raw = valueFromFlag(rest, i, "--strategy")
      if not parseLockStrategy(raw, gen.strategy):
        stderr.writeLine(
          unknownStrategyDiagnostic("repro lock " & verb, raw))
        return 2
    elif arg == "--lowest":
      gen.strategy = lsLowest
    elif arg == "--highest":
      gen.strategy = lsHighest
    elif arg == "--registry" or arg.startsWith("--registry="):
      gen.registries.add(valueFromFlag(rest, i, "--registry"))
    elif arg == "--write":
      gen.write = true
    elif arg == "--json":
      asJson = true
    elif arg.startsWith("--"):
      stderr.writeLine("repro lock " & verb & ": unknown flag " & arg)
      return 2
    else:
      if projectDir.len > 0:
        stderr.writeLine("repro lock " & verb &
          ": at most one <projectDir> positional accepted")
        return 2
      projectDir = arg
    inc i
  if projectDir.len == 0:
    projectDir = getCurrentDir()
  projectDir = absolutePath(projectDir)
  return 0

# ---------------------------------------------------------------------------
# Workspace-Manifest-Optional MO-12 — provider-sourced solver inputs.
#
# ``repro lock refresh`` / ``validate`` obtain their solver inputs from the
# COMPILED PROJECT PROVIDER (the same ``solve()`` the DSL runs via
# ``finalizeVariants()``) rather than the hand-maintained ``repro.solver``
# sidecar, so the lock reflects the REAL recipe. The provider is compiled and
# run with ``REPRO_EMIT_SOLVER_INPUTS`` set; its module-init ``finalizeVariants``
# writes the exact inputs it solved as M2e explain-fixture text, which we parse
# back through the SAME ``parseExplainFixture`` reader the sidecar path uses —
# so every downstream step (MO-11 ``source:`` provenance → store/registry
# coordinates, ``solutionToLock``, the per-dep lift) is byte-identical to the
# sidecar path; only the SOURCE of the text changes.
#
# The sidecar remains an OPTIONAL FALLBACK: a project with no recipe (or a
# recipe declaring no solver-bound ``uses:``) yields no provider inputs and
# falls straight back to ``repro.solver``. An explicit ``--inputs <file>``
# always selects that sidecar verbatim (the provider is skipped). This keeps
# MO-1/MO-7/MO-11 sidecar fixtures byte-unchanged while a recipe-bearing
# workspace is sourced from its real provider.
# ---------------------------------------------------------------------------

const SolverInputsEmitEnvVar = "REPRO_EMIT_SOLVER_INPUTS"
  ## MUST match ``repro_dsl_stdlib/configurables/variants.SolverInputsEmitEnvVar``
  ## — the env var the compiled provider's ``finalizeVariants()`` honours to
  ## emit the solved inputs.

type CompiledProviderSolverInputs = object
  variants: seq[variant_encoder.VariantDecl]
  packages: seq[PackageDecl]
  text: string
  toolUses: seq[InterfaceToolUse]
  usesSelectors: seq[string]
  defaultToolProvisioning: string
  sourceRecipeRoots: seq[string]

proc solverInputsFromCompiledProvider(projectDir: string;
                                      requireSolverBinding = true;
                                      strict = false):
    Option[CompiledProviderSolverInputs] =
  ## MO-12 — obtain solver inputs from the compiled project provider. Compiles
  ## the project's ``repro.nim`` / ``reprobuild.nim`` recipe to a provider
  ## binary and runs it with ``REPRO_EMIT_SOLVER_INPUTS`` set so module-init's
  ## ``finalizeVariants()`` writes the exact inputs it solved; the emitted
  ## explain-fixture text is parsed back into the solver's input lists.
  ##
  ## Best-effort by design — ANY of {no recipe, no ``build:`` block, no
  ## solver-bound ``uses:``, interface-extraction / provider-compile / run
  ## failure, an empty solve} returns ``none`` so the caller falls back to the
  ## ``repro.solver`` sidecar. All scratch lives under the system temp dir, so
  ## refresh still writes NO build artifacts into the project tree.
  result = none(CompiledProviderSolverInputs)
  let match =
    try: resolveProjectFile(projectDir)
    except CatchableError: return result
  if match.path.len == 0:
    return result
  let modulePath = absolutePath(match.path)
  if requireSolverBinding and not moduleHasBuildBlock(modulePath):
    # NLF-M8, folded from NLF-M7. This return, and the `toolUses` one below,
    # are correct for the SOLVER-INPUTS caller: a recipe with no `build:`
    # block and no solver-bound `uses:` has no non-trivial solve, and the
    # expensive provider compile would buy nothing.
    #
    # They were NOT correct for `repro lock list`, which borrowed this probe
    # to get the DECLARATIONS out of the same process. A workspace whose
    # whole content is two `lockFile` declarations — §4.2's own example —
    # took this branch, never ran the provider, and the listing silently fell
    # back to the well-known set. A listing that reports confidently about
    # the wrong thing is the defect class this campaign exists to catch, and
    # it had got inside the feature's own diagnostics.
    return result
  let scratchRoot = getTempDir() /
    ("repro-lock-provider-" & $getCurrentProcessId())
  try:
    removeDir(extendedPath(scratchRoot))
    createDir(extendedPath(scratchRoot))
    defer:
      try: removeDir(extendedPath(scratchRoot))
      except CatchableError: discard
    let compileWorkDir = reprobuildLibraryWorkDir()
    let scratchDir = scratchRoot / "work"
    # MR5 bootstrap toolchain (same provisioning the build path arranges before
    # an interface extraction / provider compile).
    ensureBootstrapToolchainEnv(tpmPathOnly, resolveStoreRoot() / "tool-store")
    let interfacePath = scratchRoot / "project-interface.rbsz"
    let stubPath = scratchRoot / "project-interface.nim"
    # Deliberately NOT the extraction edge (Compiles-Are-Normal-Edges.md):
    # every path here — artifact, stub, sidecars, nimcache — lives under a
    # temp root this proc creates and deletes in the same call, so an edge
    # would be keyed on paths that never exist again and could never hit.
    # This is a best-effort probe for the lock refresh, not a build; its
    # results are thrown away and it writes nothing into the project tree.
    # A refresh always re-solves. Clear inherited build pins before interface
    # extraction as well as provider execution: module initialization can run
    # during either process, and an old pin must not prevent us from observing
    # the declaration that supersedes it.
    let inheritedPins = getEnv(LockPinsEnvVar)
    let inheritedLockPath = getEnv(LockPathEnvVar)
    delEnv(LockPinsEnvVar)
    delEnv(LockPathEnvVar)
    defer:
      if inheritedPins.len > 0: putEnv(LockPinsEnvVar, inheritedPins)
      if inheritedLockPath.len > 0: putEnv(LockPathEnvVar, inheritedLockPath)
    let artifact = extractInterfaceFromModule(modulePath, interfacePath,
      stubPath, compileWorkDir, scratchDir, requireStub = false,
      consumerRoot = projectRootForModule(modulePath))
    # Only recipes with solver-bound ``uses:`` produce a non-trivial solve;
    # skip the (more expensive) provider compile otherwise so a plain recipe
    # falls straight back to the sidecar without paying for it.
    if requireSolverBinding and artifact.projectInterface.toolUses.len == 0:
      return result
    # FUP-M — capture the recipe's declared ``uses:`` producer selectors so
    # ``lockedDepsForWorkspace`` can fold each sibling PRODUCER edge into the
    # committed lock's ``deps``. A toolchain / host ``uses:`` (``nim`` / ``gcc``)
    # that names no on-disk sibling producer is resolved to ``none`` there, so
    # only genuine cross-repo source siblings become locked deps.
    var usesSelectors: seq[string] = @[]
    for useDef in artifact.projectInterface.toolUses:
      if useDef.packageSelector.len > 0 and
          useDef.packageSelector notin usesSelectors:
        usesSelectors.add(useDef.packageSelector)
    let providerBinaryPath = scratchRoot / "provider" / "project-provider"
    let provider = compileProviderBinary(modulePath, providerBinaryPath,
      artifact.interfaceFingerprint, "", compileWorkDir, scratchDir)
    let emitPath = scratchRoot / "solver-inputs.explain"
    let protocolRoot = scratchRoot / "protocol"
    let cwd = if projectDir.len > 0: absolutePath(projectDir) else: getCurrentDir()
    putEnv(SolverInputsEmitEnvVar, emitPath)
    # Named-Lock-Files NLF-M3 — a REFRESH must re-solve, never re-affirm. The
    # provider now honours ``REPRO_LOCK_PINS`` as hard pins, so a probe that
    # inherited them from an enclosing build would emit the OLD lock's answer
    # as the new solve's inputs and every refresh would be a fixed point. The
    # pins are removed for the probe's lifetime and put back afterwards.
    try:
      # A bare manifest request is enough: ``finalizeVariants()`` runs at the
      # provider's MODULE INITIALISATION (the variant decls + finalize call are
      # emitted at top-level module scope), BEFORE any request is dispatched —
      # so the emission happens regardless of the request kind, and a manifest
      # request provisions no tools and builds nothing (no-build semantics).
      discard runStableProviderProtocol(provider.outputBinaryPath, protocolRoot,
        "solver-inputs", cwd, ProviderGraphRequest(
          kind: prkManifest,
          providerArtifactId: digestHex(provider.providerFingerprint),
          reason: girExplicitUserRequest))
    finally:
      delEnv(SolverInputsEmitEnvVar)
    if not fileExists(extendedPath(emitPath)):
      return result
    let text = readFile(extendedPath(emitPath))
    let parsed = parseExplainFixture(text)
    if parsed.packages.len == 0 and parsed.variants.len == 0:
      return result
    return some(CompiledProviderSolverInputs(
      variants: parsed.variants,
      packages: parsed.packages,
      text: text,
      toolUses: artifact.projectInterface.toolUses,
      usesSelectors: usesSelectors,
      defaultToolProvisioning:
        artifact.projectInterface.defaultToolProvisioning))
  except CatchableError:
    if strict:
      raise
    return result

proc dependencyDeclEqual(a, b: DependencyDecl): bool =
  a.name == b.name and a.range == b.range and a.conditional == b.conditional

proc mergeProviderSolverInputs(aggregate: var CompiledProviderSolverInputs;
                               incoming: CompiledProviderSolverInputs) =
  ## Fold independently compiled package providers into one solver universe.
  ## A global lock must satisfy every selected producer, not only the root
  ## recipe that happened to start the build.
  for incomingVariant in incoming.variants:
    var found = false
    for existing in aggregate.variants:
      if existing.name != incomingVariant.name:
        continue
      if existing != incomingVariant:
        raise newException(ValueError,
          "conflicting variant declarations for '" & incomingVariant.name &
          "' while composing from-source solver inputs")
      found = true
      break
    if not found:
      aggregate.variants.add(incomingVariant)

  for incomingPackage in incoming.packages:
    var match = -1
    for i, existing in aggregate.packages:
      if existing.name == incomingPackage.name:
        match = i
        break
    if match < 0:
      aggregate.packages.add(incomingPackage)
      continue

    var existing = aggregate.packages[match]
    if existing.source.len > 0 and incomingPackage.source.len > 0 and
        existing.source != incomingPackage.source:
      raise newException(ValueError,
        "conflicting source declarations for package '" &
        incomingPackage.name & "'")
    if existing.source.len == 0:
      existing.source = incomingPackage.source
    if existing.instanceOf.len > 0 and incomingPackage.instanceOf.len > 0 and
        existing.instanceOf != incomingPackage.instanceOf:
      raise newException(ValueError,
        "conflicting instance declarations for package '" &
        incomingPackage.name & "'")
    if existing.instanceOf.len == 0:
      existing.instanceOf = incomingPackage.instanceOf
    if existing.pinned and incomingPackage.pinned and
        existing.versions != incomingPackage.versions:
      raise newException(ValueError,
        "conflicting pinned versions for package '" & incomingPackage.name &
        "'")
    if incomingPackage.pinned:
      existing.pinned = true
      existing.versions = incomingPackage.versions
    elif not existing.pinned:
      for version in incomingPackage.versions:
        if version notin existing.versions:
          existing.versions.add(version)
    for dependency in incomingPackage.depends:
      var found = false
      for current in existing.depends:
        if dependencyDeclEqual(current, dependency):
          found = true
          break
      if not found:
        existing.depends.add(dependency)
    for packageVariant in incomingPackage.variants:
      var found = false
      for current in existing.variants:
        if current.name != packageVariant.name:
          continue
        if current != packageVariant:
          raise newException(ValueError,
            "conflicting package variant declarations for '" &
            packageVariant.name & "'")
        found = true
        break
      if not found:
        existing.variants.add(packageVariant)
    existing.versions.sort()
    existing.depends.sort(proc(a, b: DependencyDecl): int =
      result = cmp(a.name, b.name)
      if result == 0: result = cmp(a.range, b.range)
      if result == 0: result = cmp($a.conditional, $b.conditional))
    existing.variants.sort(proc(a, b: variant_encoder.VariantDecl): int =
      cmp(a.name, b.name))
    aggregate.packages[match] = existing

  for useDef in incoming.toolUses:
    var found = false
    for current in aggregate.toolUses:
      if current.packageSelector == useDef.packageSelector and
          current.executableName == useDef.executableName and
          current.rawConstraint == useDef.rawConstraint:
        found = true
        break
    if not found:
      aggregate.toolUses.add(useDef)
  for selector in incoming.usesSelectors:
    if selector notin aggregate.usesSelectors:
      aggregate.usesSelectors.add(selector)
  aggregate.variants.sort(proc(a, b: variant_encoder.VariantDecl): int =
    cmp(a.name, b.name))
  aggregate.packages.sort(proc(a, b: PackageDecl): int = cmp(a.name, b.name))

proc foldFromSourceProviderSolverInputs(projectDir: string;
                                        aggregate: var
                                          CompiledProviderSolverInputs) =
  ## Discover the same corpus recipes that from-source execution would select,
  ## compile their metadata only, and merge their transitive constraints into
  ## the root solve. No package build action is executed.
  let recipeRoot = fromSourceRecipeRoot(projectDir)
  if not dirExists(extendedPath(recipeRoot)):
    return
  seedBootstrapCycleBreakTools()
  var pending = aggregate.toolUses
  var seenRecipeDirs: seq[string] = @[]
  var cursor = 0
  while cursor < pending.len:
    let useDef = pending[cursor]
    inc cursor
    if useDef.executableName.len == 0:
      continue
    let outcome = tryResolveFromSourceTool(useDef, recipeRoot)
    var recipeDir = ""
    case outcome.kind
    of rrResolved:
      recipeDir = outcome.profile.selectedStorePath
    of rrNeedsBuild:
      if useDef.executableName in fromSourceCycleBrokenTools:
        continue
      recipeDir = outcome.recipeDir
    of rrSiblingMissing:
      continue
    if recipeDir.len == 0:
      continue
    recipeDir = absolutePath(recipeDir)
    if recipeDir in seenRecipeDirs:
      continue
    seenRecipeDirs.add(recipeDir)
    let provider = solverInputsFromCompiledProvider(recipeDir, strict = true)
    if provider.isNone:
      continue
    let producerInputs = provider.get()
    for transitiveUse in producerInputs.toolUses:
      pending.add(transitiveUse)
    aggregate.mergeProviderSolverInputs(producerInputs)
  aggregate.sourceRecipeRoots = seenRecipeDirs
  aggregate.text = solver_variants.renderSolverInputsFixture(
    aggregate.variants, aggregate.packages)

proc resolveRefreshSolverInputs(projectDir, inputsOverride: string): tuple[
    found: bool; variants: seq[variant_encoder.VariantDecl];
    packages: seq[PackageDecl]; text: string; source: string;
    usesSelectors: seq[string]; sourceRecipeRoots: seq[string]] =
  ## MO-12 — resolve the solver inputs for ``lock refresh`` / ``validate``,
  ## PREFERRING the compiled project provider (the real recipe's solve) and
  ## falling back to the ``repro.solver`` sidecar. An explicit ``--inputs``
  ## override always selects that sidecar file verbatim (provider skipped) so
  ## the historical override semantics are preserved.
  ##
  ## FUP-M — ``usesSelectors`` carries the recipe's declared ``uses:`` producer
  ## selectors (provider path only; the sidecar has none) so ``lock refresh``
  ## folds each sibling PRODUCER edge into the committed lock's ``deps``.
  if inputsOverride.len == 0:
    let fromProvider = solverInputsFromCompiledProvider(projectDir)
    if fromProvider.isSome:
      var p = fromProvider.get()
      if p.defaultToolProvisioning == "from-source":
        foldFromSourceProviderSolverInputs(projectDir, p)
      return (true, p.variants, p.packages, p.text, "provider",
        p.usesSelectors, p.sourceRecipeRoots)
  let inputsP =
    if inputsOverride.len > 0: absolutePath(inputsOverride)
    else: solverInputsPath(projectDir)
  if fileExists(extendedPath(inputsP)):
    let loaded = loadSolverInputsFile(inputsP)
    return (true, loaded.variants, loaded.packages, loaded.text, "sidecar",
      @[], @[])
  return (false, @[], @[], "", "", @[], @[])

proc buildLockGenerationRequest(projectDir, inputsOverride,
                                platformOverride: string;
                                gen: LockVerbOptions;
                                entryPoint: LockGenerationEntryPoint;
                                verb: string;
                                request: var LockGenerationRequest): int =
  ## Assemble the generation request the four CLI doors share.
  ##
  ## MO-12 — the solver inputs come from the COMPILED PROJECT PROVIDER (the
  ## real recipe's solve) when available, falling back to the ``repro.solver``
  ## sidecar otherwise (see ``resolveRefreshSolverInputs``). FUP-M — the
  ## workspace's participating repos become the request's ``extraDeps`` so the
  ## generated lock carries their coordinates + integrity.
  let resolved =
    try: resolveRefreshSolverInputs(projectDir, inputsOverride)
    except CatchableError as e:
      stderr.writeLine("repro lock " & verb & ": failed to read inputs: " &
        e.msg)
      return 1
  if not resolved.found:
    stderr.writeLine("repro lock " & verb & ": no solver inputs found for " &
      projectDir & " (expected a compiled `" & CommittedLockFileName &
      "`-adjacent recipe, a `" & SolverInputsFileName &
      "` sidecar, or pass --inputs <file>)")
    return 1
  # MO-11 — overlay each package's DECLARED source provenance (the
  # solver-inputs ``source:`` directive) onto the decls handed to the
  # generation path, which re-attaches it to the solved-graph ``source`` field
  # so the MO-11 lift can produce store / registry coordinates.
  request = LockGenerationRequest(
    variants: resolved.variants,
    packages: resolved.packages,
    inputsText: resolved.text,
    platform:
      if platformOverride.len > 0: platformOverride else: currentPlatformId(),
    strategy: gen.strategy,
    endpoints: gen.registries,
    workDir: getTempDir() /
      ("repro-lock-generation-" & $getCurrentProcessId() & "-" & verb),
    extraDeps: lockedDepsForWorkspace(projectDir, resolved.usesSelectors,
      resolved.sourceRecipeRoots),
    entryPoint: entryPoint)
  return 0

proc reportGeneratedLock(verb, lockP: string;
                         generated: LockGenerationResult): int =
  ## Sandbox-And-Monitoring.md §"The Network Dimension" rule 4: the network
  ## classification must be "visible in logs, debugging output, per-action
  ## explain output". Reporting the fetch-edge count and the wave count is the
  ## generation path's end of that — an operator can see that a lock cost N
  ## non-hermetic edges, and see it go to zero when nothing was reachable.
  let ld = parseLockedDependencies(generated.lockDocument)
  var fetches = 0
  for wave in generated.fetchWaves: fetches += wave.len
  stdout.writeLine("repro lock " & verb & ": " &
    (if lockP.len > 0: "wrote " & lockP else: "generated (not written)") &
    " (" & $ld.variants.len & " variant(s), " & $ld.packages.len &
    " package(s), " & $ld.deps.len & " locked dep(s); platform " &
    ld.platform & "; entry point " & $generated.entryPoint & "; " & $fetches &
    " metadata fetch edge(s) in " & $generated.fetchWaves.len & " wave(s))")
  stdout.writeLine("repro lock " & verb & ": lock identity " &
    $generated.lockIdentity)
  # NLF-M6, third folded criterion — a strategy that cannot take effect must
  # SAY SO. NLF-M5 shipped `--strategy` accepted, printed in the run summary,
  # and silently inert wherever no candidate universe existed to rank; the
  # instance was fixed and the CLASS was not. This is the class: the report is
  # produced by the generation path (`strategyEffectivenessReport`) and every
  # door prints it, so a new door cannot acquire silence by omission.
  if generated.strategyReport.len > 0:
    stderr.writeLine("repro lock " & verb & ": " & generated.strategyReport)
  # §5.7's two-phase lookup, made visible: whether the solve ran at all, and
  # which recorded path set answered when it did not. An operator who cannot
  # see that a lock came from cache cannot tell a working filter from a
  # fingerprint that never changes — the exact confusion NLF-M6's exit criteria
  # forbid a TEST from resting on, and the same argument applies to the log.
  stdout.writeLine("repro lock " & verb & ": solve " &
    (if generated.solveExecuted: "ran"
     else: "served from recorded path set #" & $generated.pathSetHitIndex) &
    " (" & $generated.pathSetsRecorded & " path set(s) under this weak " &
    "fingerprint, " & $generated.pathSet.observations.len &
    " consulted observation(s))")
  return 0

proc runLockGenerationVerb(rest: openArray[string]; verb: string;
                           entryPoint: LockGenerationEntryPoint;
                           writeByDefault: bool): int =
  ## The shared body of ``repro lock solve`` and ``repro lock refresh``.
  ##
  ## NLF-M5 §5.6: both are the SAME edges — metadata-fetch edges upstream, the
  ## solve as a rule generator downstream — reached through different doors.
  ## What differs is `writeByDefault`, which is §5.4's "where the file lands
  ## and whether it is committed" and nothing else.
  var projectDir, inputsOverride, lockOverride, platformOverride: string
  var asJson = false
  var gen = LockVerbOptions(strategy: lsDefault, registries: @[], write: false)
  let rc = parseLockVerbArgs(rest, verb, projectDir, inputsOverride,
                             lockOverride, platformOverride, asJson, gen)
  if rc != 0: return rc
  let lockP =
    if lockOverride.len > 0: absolutePath(lockOverride)
    else: committedLockPath(projectDir)
  var request: LockGenerationRequest
  let prc = buildLockGenerationRequest(projectDir, inputsOverride,
    platformOverride, gen, entryPoint, verb, request)
  if prc != 0: return prc
  let writeTo = if writeByDefault or gen.write: lockP else: ""
  try:
    defer:
      try: removeDir(extendedPath(request.workDir))
      except CatchableError: discard
    let generated =
      case entryPoint
      of lgeLockRefresh: runLockRefresh(request, writeTo)
      else: runLockSolve(request, writeTo)
    return reportGeneratedLock(verb, writeTo, generated)
  except EUnsatisfiable as e:
    stderr.writeLine("repro lock " & verb & ": solver UNSAT — cannot pin a " &
      "lock: " & e.msg)
    return 3
  except CatchableError as e:
    stderr.writeLine("repro lock " & verb & ": generation failed: " & e.msg)
    return 1

proc runReproLockRefresh(rest: openArray[string]): int =
  ## ``repro lock refresh`` — re-solve the project's solver inputs and
  ## (re)write the committed lock WITHOUT building. No build artifacts are
  ## produced; only the lock file is written.
  runLockGenerationVerb(rest, "refresh", lgeLockRefresh,
    writeByDefault = true)

proc applyStrategyHiddenLock(projectDir: string; strategy: LockStrategy;
                             committedLock: string;
                             solved: var UnifiedSolution): int =
  ## `repro build --strategy <s>` / `repro test --strategy <s>` — the fourth
  ## door of §5.6.
  ##
  ## §5.4 defines it exhaustively: "generate a lock file under the given
  ## strategy into a **hidden, uncommitted** location, then use it. Nothing
  ## else." So this runs the SAME `generateLock` the other three doors run,
  ## into a scratch directory that is removed on the way out, and pins the
  ## build from the result. The hidden lock is never written to
  ## `committedLock`; that path is read only so the override can be REPORTED.
  ##
  ## §5.5: "A strategy invocation SHOULD report that it is overriding a
  ## committed lock. A build whose inputs differ from committed state and says
  ## nothing is the shape this campaign keeps finding."
  var gen = LockVerbOptions(strategy: strategy, registries: @[], write: false)
  var request: LockGenerationRequest
  let prc = buildLockGenerationRequest(projectDir, "", "", gen,
    lgeStrategyHiddenLock, "build --strategy", request)
  if prc != 0: return prc
  # NLF-M3 — a strategy invocation must SOLVE, not re-affirm. Any pins an
  # enclosing context left in the environment would make the hidden lock a
  # copy of the committed one and the whole experiment vacuous.
  let inheritedPins = getEnv(LockPinsEnvVar)
  let inheritedLockPath = getEnv(LockPathEnvVar)
  delEnv(LockPinsEnvVar)
  delEnv(LockPathEnvVar)
  try:
    defer:
      try: removeDir(extendedPath(request.workDir))
      except CatchableError: discard
    let generated = runStrategyHiddenLock(request, strategy)
    solved = lockToSolution(
      solvedPartOf(parseLockedDependencies(generated.lockDocument)))
    putEnv(LockPinsEnvVar,
           renderLockPins(solved.packages, solved.variants))
    putEnv(LockPathEnvVar, generated.lockPath)
    if fileExists(extendedPath(committedLock)):
      stderr.writeLine("repro build: --strategy " & $strategy &
        " OVERRIDES the committed lock " & committedLock &
        " for this invocation; the committed lock is not modified")
    stderr.writeLine("repro build: --strategy " & $strategy &
      " hidden lock identity " & $generated.lockIdentity)
    if generated.strategyReport.len > 0:
      stderr.writeLine("repro build: " & generated.strategyReport)
    return 0
  except CatchableError as e:
    if inheritedPins.len > 0: putEnv(LockPinsEnvVar, inheritedPins)
    if inheritedLockPath.len > 0: putEnv(LockPathEnvVar, inheritedLockPath)
    stderr.writeLine("repro build: --strategy " & $strategy &
      " could not generate a hidden lock: " & e.msg)
    return 1

proc runReproLockSolve(rest: openArray[string]): int =
  ## ``repro lock solve [--lowest|--highest|--strategy <s>] [--write]`` —
  ## generate a lock under a strategy.
  ##
  ## NLF-M6 adds ``--lowest`` / ``--highest``, which is the spelling
  ## `Locking-And-Solver.md` §"CLI Surface" and `Named-Lock-Files.md` §5.4 both
  ## name; ``--strategy`` is the general form and the two set the same field.
  ##
  ## **Behaviour change, stated rather than slipped in.** Before NLF-M5,
  ## ``solve`` was accepted as a bare ALIAS of ``refresh`` and therefore always
  ## wrote the committed lock. `Named-Lock-Files.md` §5.5 makes the two
  ## spellings two intentions — "Writing back requires the generate operation
  ## explicitly: `repro lock solve --lowest --write`. Two spellings, because
  ## they are two intentions." — so ``solve`` now writes only under
  ## ``--write``. A caller that wants the old behaviour spells ``refresh``,
  ## which is unchanged.
  runLockGenerationVerb(rest, "solve", lgeLockSolve, writeByDefault = false)

proc runReproLockValidate(rest: openArray[string]): int =
  ## ``repro lock validate`` — check the committed lock is loadable,
  ## internally consistent, platform-resolvable, and (when the solver
  ## inputs are available) still consistent with a fresh solve. No build.
  ## Exit 0 = valid; exit 2 = invalid/tampered/stale (diagnostic emitted);
  ## exit 1 = IO error.
  var projectDir, inputsOverride, lockOverride, platformOverride: string
  var asJson = false
  var gen = LockVerbOptions(strategy: lsDefault, registries: @[], write: false)
  let rc = parseLockVerbArgs(rest, "validate", projectDir, inputsOverride,
                             lockOverride, platformOverride, asJson, gen)
  if rc != 0: return rc
  let lockP =
    if lockOverride.len > 0: absolutePath(lockOverride)
    else: committedLockPath(projectDir)
  if not fileExists(extendedPath(lockP)):
    stderr.writeLine("repro lock validate: no committed lock at " & lockP &
      " (run `repro lock refresh` first)")
    return 2
  var lock: SolvedGraphLock
  try:
    lock = parseSolvedGraphLock(readFile(extendedPath(lockP)))
  except SolvedGraphLockParseError as e:
    stderr.writeLine("repro lock validate: malformed lock: " & e.msg)
    return 2
  except CatchableError as e:
    stderr.writeLine("repro lock validate: failed to read lock: " & e.msg)
    return 1
  var problems: seq[string] = @[]
  # (a) structural consistency: every package has a concrete version,
  #     every variant has a name.
  for p in lock.packages:
    if p.name.len == 0 or p.version.len == 0:
      problems.add("package entry missing name/version")
  for v in lock.variants:
    if v.name.len == 0:
      problems.add("variant entry missing name")
  # (b) loadable + round-trips deterministically. ``serializeSolvedGraphLock``
  # delegates to ``serializeLockedDependencies``, so this is the writer the
  # committed lock is produced by — it used to be spelled out here because the
  # solved-graph writer emitted an unreadable ``…lock.v1`` document.
  let reparsed =
    try: parseSolvedGraphLock(serializeSolvedGraphLock(lock))
    except CatchableError:
      problems.add("lock does not round-trip through the serializer")
      lock
  if not sameSolution(lockToSolution(lock), lockToSolution(reparsed)):
    problems.add("lock is not deterministically loadable (round-trip drift)")
  # (c) platform-resolvable on THIS host.
  let host = currentPlatformId()
  if lock.platform != host:
    problems.add("lock platform '" & lock.platform &
      "' is not resolvable on this host '" & host & "'")
  # (c2) Platform-And-Microarchitecture-Constraints PMC-4 — microarchitecture
  # resolvable on THIS host.
  #
  # `lock.platform` is the cpu-os coordinate and says nothing about the
  # instruction set the locked artifacts were selected FOR. A lock refreshed
  # on an x86-64-v3 machine can name a v3 floor and still carry
  # `platform: amd64-linux`, so every check above passes on a v2 host while
  # the artifacts it names cannot execute there. The failure without this is a
  # SIGILL inside a later build with nothing pointing back at the lock, which
  # is precisely the "works until it doesn't" shape PMC-4 exists to close.
  #
  # Report it rather than re-resolving. The acceptance criterion is that such
  # a lock either resolves something satisfiable or fails LOUDLY -- silently
  # picking a different artifact would mean the lock no longer names what gets
  # built, which is the one outcome worse than refusing.
  #
  # The host target is read through the same detection PMC-2/PMC-3 use, so
  # `REPRO_HOST_MICROARCH_LEVEL` / `REPRO_HOST_CPU_FEATURES` steer this check
  # exactly as they steer selection. A validator that disagreed with the
  # resolver about the same pair would be worse than no validator.
  let hostTarget = initPlatformTarget(
    detectHostCpu(), detectHostMicroarchLevel(detectHostCpu()),
    detectHostCpuFeatures(detectHostCpu()))
  for p in lock.packages:
    if p.target.len == 0:
      continue
    let verdict = resolvedTargetSatisfiedBy(p.target, hostTarget)
    if verdict.ok:
      continue
    if verdict.badToken.len > 0:
      # A vocabulary problem, not a capability one -- `missing` is empty and
      # would render as a misleading "missing cpu features: " with nothing
      # after it. See `resolvedTargetSatisfiedBy`.
      problems.add("lock package '" & p.name & "' records an unreadable " &
        "target '" & p.target & "' (unknown token '" & verdict.badToken & "')")
    else:
      problems.add("lock package '" & p.name & "' needs target '" &
        p.target & "', which this host does not provide (" &
        renderResolvedTarget(hostTarget) & "); missing cpu features: " &
        describeCpuFeatures(verdict.missing))
  # (d) consistency with the current solver inputs (tamper/stale check).
  # MO-12 — source the inputs the SAME way refresh does (compiled provider
  # preferred, sidecar fallback) so a provider-sourced lock validates against
  # the provider's solve rather than mis-comparing it to a stale sidecar.
  block staleCheck:
    var resolved: tuple[found: bool;
      variants: seq[variant_encoder.VariantDecl];
      packages: seq[PackageDecl]; text: string; source: string;
      usesSelectors: seq[string]; sourceRecipeRoots: seq[string]]
    try:
      resolved = resolveRefreshSolverInputs(projectDir, inputsOverride)
    except CatchableError as e:
      stderr.writeLine("repro lock validate: failed to read inputs: " & e.msg)
      return 1
    if not resolved.found:
      break staleCheck
    try:
      let fresh = solve(resolved.variants, resolved.packages)
      if not sameSolution(lockToSolution(lock), fresh):
        problems.add("lock does not match a fresh solve of the current " &
          "inputs (tampered or stale — run `repro lock refresh`)")
      if lock.inputsDigest != inputsDigestOf(resolved.text):
        problems.add("inputs_digest mismatch (the solver inputs changed " &
          "since the lock was written)")
    except EUnsatisfiable:
      problems.add("current solver inputs are UNSAT")
    except CatchableError as e:
      stderr.writeLine("repro lock validate: failed to re-solve inputs: " &
        e.msg)
      return 1
  # (e) MO-8 — integrity verification. Recompute each locked dependency's
  # self-describing integrity from the on-disk checkout and compare to the
  # locked value; a malformed/unrecognized multihash or a content drift is a
  # loud failure. Also assert the v2 model round-trips deterministically.
  block integrity:
    var ld: LockedDependencies
    try:
      ld = parseLockedDependencies(readFile(extendedPath(lockP)))
    except CatchableError:
      break integrity
    let once = serializeLockedDependencies(ld)
    if once != serializeLockedDependencies(parseLockedDependencies(once)):
      problems.add("lock does not round-trip deterministically (v2 model)")
    for d in ld.deps:
      if not isWellFormedMultihash(d.integrity):
        problems.add("dep '" & d.name &
          "' has a malformed/unrecognized integrity '" & d.integrity & "'")
        continue
      case d.coordinates.kind
      of ckVcs:
        let depAbs =
          if d.path == "." or d.path.len == 0: absolutePath(projectDir)
          else: absolutePath(projectDir) / d.path
        if not dirExists(extendedPath(depAbs)):
          continue  # not checked out here — cannot recompute (not a tamper).
        let observed = committedLockRepoFacts(depAbs).headSha
        let recomputed = computeDepIntegrity(depAbs, observed)
        if recomputed != d.integrity:
          problems.add("dep '" & d.name & "' integrity mismatch: locked '" &
            d.integrity & "' but on-disk content hashes to '" & recomputed & "'")
      of ckStore:
        # MO-11 — a store-realized solved package. Recompute the store address
        # from the package's solved identity (name + version + platform) and
        # require the coordinate AND the integrity to match it.
        let recomputed = solvedPackageStoreHash(d.name, d.version, lock.platform)
        if d.coordinates.storeHash != recomputed or
            d.integrity != formatMultihash("blake3", recomputed):
          problems.add("dep '" & d.name & "' store integrity mismatch: locked '" &
            d.integrity & "' but recomputes to 'blake3:" & recomputed & "'")
      of ckRegistry:
        # MO-11 — a registry-sourced solved package. Recompute the package
        # checksum over the locked registry coordinate.
        let recomputed = solvedPackageRegistryIntegrity(
          d.coordinates.registryName, d.name, d.coordinates.registryVersion)
        if d.integrity != recomputed:
          problems.add("dep '" & d.name &
            "' registry integrity mismatch: locked '" & d.integrity &
            "' but recomputes to '" & recomputed & "'")
      of ckForeign:
        discard
  if asJson:
    let arr = newJArray()
    for p in problems: arr.add(%p)
    let obj = %*{
      "lock": lockP,
      "valid": problems.len == 0,
      "platform": lock.platform,
      "problems": arr,
    }
    stdout.writeLine($obj)
  if problems.len > 0:
    if not asJson:
      stderr.writeLine("repro lock validate: INVALID (" & lockP & ")")
      for p in problems:
        stderr.writeLine("  - " & p)
    return 2
  if not asJson:
    stdout.writeLine("repro lock validate: OK (" & lockP & ")")
  return 0

proc validateCommittedLockAdvisory(repoRoot: string) =
  ## MO-1 — ``repro check`` advisory. When the current repo carries a
  ## committed solved-graph lock AND its solver inputs, validate it and
  ## print a NON-GATING advisory. Never raises and never alters the gate
  ## exit code; emits nothing when no committed lock is present (so the
  ## RA pre-push gate fixtures, which have no ``repro.lock``, stay
  ## byte-stable).
  if repoRoot.len == 0: return
  let lockP = committedLockPath(absolutePath(repoRoot))
  if not fileExists(extendedPath(lockP)): return
  try:
    let lock = parseSolvedGraphLock(readFile(extendedPath(lockP)))
    let inputsP = solverInputsPath(absolutePath(repoRoot))
    if fileExists(extendedPath(inputsP)):
      let inputs = loadSolverInputsFile(inputsP)
      let fresh = solve(inputs.variants, inputs.packages)
      if sameSolution(lockToSolution(lock), fresh):
        stderr.writeLine("repro check: committed solved-graph lock OK (" &
          lockP & ")")
      else:
        stderr.writeLine("repro check: committed solved-graph lock is stale " &
          "— run `repro lock refresh` (" & lockP & ")")
    else:
      stderr.writeLine("repro check: committed solved-graph lock present (" &
        lockP & ")")
  except CatchableError:
    discard

proc lockFileDeclarationsFromCompiledProvider*(projectDir: string):
    seq[LockFileDecl] =
  ## Named-Lock-Files NLF-M7 (§4.2 consumer 1) — the declared lock files of
  ## the project at `projectDir`, obtained by running its compiled provider.
  ##
  ## `lockFile hostTools` lowers to a `let` binding whose initializer
  ## registers the declaration at module init, so the declarations exist in
  ## the RECIPE process and `repro lock list` runs in the CLI one. This
  ## borrows the probe `repro lock refresh` already uses to get solver inputs
  ## out of the same process, adding one env var: the recipe writes its
  ## registry on exit and this reads it back.
  ##
  ## Best-effort in the same way and for the same reason as that probe. A
  ## project with no recipe, or one whose provider cannot be compiled here,
  ## yields the well-known set alone — which is the honest answer to "what
  ## lock files are in scope" for a workspace that declares none, and is
  ## never an error, because §5.3 makes an unbound lock file a non-error and
  ## a fortiori an undeclared workspace one.
  ##
  ## NLF-M8, folded from NLF-M7 — it borrows the probe but NOT the probe's
  ## early returns. `requireSolverBinding = false` is the whole of the fix and
  ## the reason is stated where the returns are: a project with no `build:`
  ## block, or none with a solver-bound `uses:`, never ran the provider, so
  ## the listing fell back to the well-known set and printed it as though it
  ## were the answer. The fallback is indistinguishable from "this workspace
  ## declares nothing", which is exactly the two-things-look-the-same failure
  ## the campaign is about — and §4.2's own worked example, a `workspace.nim`
  ## whose entire content is two `lockFile` declarations, took that branch.
  result = predeclaredLockFiles()
  let emitPath = getTempDir() /
    ("repro-lock-list-" & $getCurrentProcessId() & ".tsv")
  putEnv(LockFilesEmitEnvVar, emitPath)
  try:
    # `requireSolverBinding = false` — the two early returns that are right
    # for the solver-inputs caller are wrong for this one. See the comment at
    # the first of them.
    discard solverInputsFromCompiledProvider(projectDir,
      requireSolverBinding = false)
    if fileExists(extendedPath(emitPath)):
      let parsed = parseLockFileDeclarations(readFile(emitPath))
      if parsed.len > 0:
        result = parsed
  except CatchableError:
    discard
  finally:
    delEnv(LockFilesEmitEnvVar)
    try: removeFile(extendedPath(emitPath))
    except CatchableError: discard

proc siblingVariantDeclarations(checkout: string):
    seq[DevelopOverrideVariantDecl] =
  ## Named-Lock-Files NLF-M2, the variant half of the writer — the variant
  ## DECLARATIONS the develop sibling at ``checkout`` makes.
  ##
  ## `develop_sources.nim`'s second KNOWN GAP names this work and says where it
  ## belongs: "the engine does not write `variants` yet either … The durable
  ## fix is for the engine to record the sibling's declarations when it
  ## registers the override, since introspecting the sibling's recipe is work
  ## it is already positioned to do."
  ##
  ## HOW IT IS INTROSPECTED, and why it is not cheaper. A recipe's variants are
  ## `declareVariant` calls that run at the RECIPE process's module init; they
  ## do not exist in the CLI's process and cannot be recovered from the
  ## project-interface artifact, which carries no variant surface. The only
  ## thing that knows them is the sibling's own compiled provider — so this
  ## borrows the probe `repro lock refresh` and `repro lock list` already use,
  ## with `requireSolverBinding = false` for the same reason `repro lock list`
  ## passes it: a recipe that declares variants and no `build:` block would
  ## otherwise never run the provider and would report nothing as though it
  ## were the answer.
  ##
  ## Reading the recipe's TEXT instead would be cheap and is refused: a
  ## hand-rolled scan of `name: variant T = default` lines is a second,
  ## divergent implementation of the DSL's parser, and its failure mode is to
  ## quietly report fewer variants than the recipe declares — a package
  ## configured out of a universe nobody declared, which is precisely the
  ## outcome the reader raises `EDevelopVariantsMalformed` to prevent.
  ##
  ## THE SIBLING'S OWN DECLARATIONS, and nobody else's. Any develop overrides
  ## governing the CLI's process are withdrawn for the probe's lifetime: left
  ## in place, the sibling's solve would fold in ITS develop siblings'
  ## qualified variants and this entry would end up claiming declarations that
  ## belong to a third package.
  ##
  ## Best-effort in the same way and for the same reason as the probe it
  ## borrows: an empty result means the field is not written, and the reader's
  ## behaviour for an override with no `variants` is unchanged from every
  ## override on disk today. "Declares none" and "could not be asked" are not
  ## distinguished, because the probe cannot distinguish them — a recipe with
  ## no variants emits no solver inputs at all, which is the same `none` a
  ## failed provider compile returns.
  ##
  ## KNOWN LIMITATION, recorded rather than papered over and pinned by
  ## `a recipe with no build: block cannot be asked` in
  ## `t_develop_override_records_the_identity_it_replaced`: a sibling whose
  ## recipe has neither a `build:` nor a `devEnv:` body contributes nothing,
  ## even when it declares variants. `buildCode` (`macros_b.nim`) emits the
  ## provider's `runPackageProvider` entry point only for a recipe with one of
  ## those bodies, so the compiled binary runs its module init — emitting the
  ## solver inputs — and exits without answering the protocol, and the probe
  ## discards the emission along with the failed request. Closing it means
  ## teaching that probe to keep inputs the provider demonstrably wrote before
  ## the request failed, which is a change to `repro lock refresh`'s source of
  ## truth and belongs to its own milestone. A develop sibling is a project you
  ## build, so the shape that misses out is the rare one.
  result = @[]
  if checkout.len == 0:
    return
  let inheritedOverrides = getEnv(DevelopOverridesEnvVar)
  delEnv(DevelopOverridesEnvVar)
  try:
    let probed = solverInputsFromCompiledProvider(checkout,
      requireSolverBinding = false)
    if probed.isNone:
      return
    for decl in probed.get().variants:
      if decl.name.len == 0:
        continue
      var recorded = DevelopOverrideVariantDecl(name: decl.name)
      if decl.kind == vkBool:
        # The bool universe is closed and the reader hard-codes it, so the
        # probe's synthesized `["true", "false"]` value list is not carried:
        # writing it would invite a later reader to treat it as declared.
        recorded.kind = "bool"
      else:
        recorded.kind = "enum"
        recorded.values = decl.allowedValues
        if recorded.values.len == 0:
          # The reader refuses an enum with no universe, and it is right to:
          # a universe re-derived from contributions alone drops every value
          # nobody contributed. Recording one anyway would turn that refusal
          # into every consumer's problem, so the declaration is left out and
          # the sibling contributes what it can.
          continue
      for contributed in decl.contributions:
        # The DECLARED default only. A `set` / `override` / `force`
        # contribution is somebody's ANSWER, and Q-4 keeps answers out of the
        # record: recorded here it would reach the consumer's solve as this
        # checkout's declared default and quietly configure a package the
        # solve was supposed to configure.
        if contributed.priority == vpDefault:
          recorded.default = contributed.value
      result.add(recorded)
  except CatchableError:
    result = @[]
  finally:
    if inheritedOverrides.len > 0:
      putEnv(DevelopOverridesEnvVar, inheritedOverrides)

proc runReproLockList(rest: openArray[string]): int =
  ## `repro lock list` — §4.2's first consumer of a captured doc comment, and
  ## the reason the capture is a requirement rather than a nicety:
  ##
  ## > A `repro lock list` (or `--list-lock-files`) prints each declared name
  ## > with its description. This is the primary surface: a workspace with
  ## > three declared lock files is unusable if a reader cannot find out what
  ## > each is *for* without grepping the recipes.
  ##
  ## §4.2 also records that this is the FIRST such consumer: "No CLI surface
  ## prints a captured doc comment today … So `lockFile` would be the first
  ## declaration form whose captured doc text has a working consumer."
  var projectDir = ""
  var i = 0
  while i < rest.len:
    let arg = rest[i]
    if arg.startsWith("--"):
      stderr.writeLine("repro lock list: unknown flag " & arg)
      return 2
    if projectDir.len > 0:
      stderr.writeLine("repro lock list: at most one <projectDir> positional " &
        "accepted")
      return 2
    projectDir = arg
    inc i
  if projectDir.len == 0:
    projectDir = getCurrentDir()
  stdout.write(listingTextOf(
    lockFileDeclarationsFromCompiledProvider(absolutePath(projectDir))))
  0

proc runReproLockCommand*(args: openArray[string]): int =
  ## Top-level dispatcher for ``repro lock <verb> ...``.
  ##
  ## MO-1 (Workspace-Manifest-Optional) lands the committed solved-graph
  ## lock verbs ``refresh`` / ``validate`` and folds in the existing M2e
  ## ``explain``. Named-Lock-Files NLF-M5 promotes ``solve`` from an alias of
  ## ``refresh`` to a verb of its own: both run the SAME generation edges
  ## (§5.6), and they differ only in whether the result is written back —
  ## ``refresh`` writes, ``solve`` writes under ``--write``, which is §5.5's
  ## "two spellings, because they are two intentions". ``debug`` /
  ## ``visualize`` (Locking-And-Solver.md §"CLI Surface") remain future work.
  if args.len == 0:
    stderr.writeLine("repro lock: error: missing verb " &
      "(one of: list, solve, refresh, validate, explain)")
    return 2
  let rest =
    if args.len > 1: args[1 .. ^1]
    else: @[]
  case args[0]
  of "list":
    return runReproLockList(rest)
  of "refresh":
    return runReproLockRefresh(rest)
  of "solve":
    return runReproLockSolve(rest)
  of "validate":
    return runReproLockValidate(rest)
  of "explain":
    var variantName = ""
    var fixturePath = ""
    var asJson = false
    var i = 0
    while i < rest.len:
      let arg = rest[i]
      if arg == "--json":
        asJson = true
        inc i
      elif arg == "--fixture" or arg.startsWith("--fixture="):
        if arg.startsWith("--fixture="):
          fixturePath = arg["--fixture=".len .. ^1]
        else:
          if i + 1 >= rest.len:
            stderr.writeLine("repro lock explain: --fixture requires a path")
            return 2
          fixturePath = rest[i + 1]
          inc i
        inc i
      elif arg.startsWith("--"):
        stderr.writeLine("repro lock explain: unknown flag " & arg)
        return 2
      else:
        if variantName.len > 0:
          stderr.writeLine("repro lock explain: at most one variant " &
                           "positional accepted")
          return 2
        variantName = arg
        inc i
    if variantName.len == 0:
      stderr.writeLine("repro lock explain: missing <variant> positional")
      return 2
    if fixturePath.len == 0:
      stderr.writeLine("repro lock explain: --fixture <path> is required " &
                       "in M2e (workspace-driven explain lands in M3+)")
      return 2
    if not fileExists(fixturePath):
      stderr.writeLine("repro lock explain: fixture not found: " & fixturePath)
      return 1
    let text = readFile(fixturePath)
    let parsed = parseExplainFixture(text)
    var sol: UnifiedSolution
    var unsatErr: ref EUnsatisfiable = nil
    try:
      sol = solve(parsed.variants, parsed.packages)
    except EUnsatisfiable as e:
      unsatErr = (ref EUnsatisfiable)()
      unsatErr.msg = e.msg
      unsatErr.programText = e.programText
      unsatErr.unsatCore = e.unsatCore
      unsatErr.coreAtoms = e.coreAtoms
    if unsatErr != nil:
      let entries = explainUnsat(unsatErr.coreAtoms, parsed.variants,
                                  parsed.packages)
      if asJson:
        echo $renderUnsatCoreJson(entries, unsatErr.programText)
      else:
        stdout.write(renderUnsatCoreText(entries, unsatErr.programText))
      return 3  # exit code 3 reserved for "unsat"
    try:
      let chain = explainChosen(sol, variantName, parsed.variants,
                                parsed.packages)
      if asJson:
        echo $renderExplainChainJson(chain)
      else:
        stdout.write(renderExplainChainText(chain))
      return 0
    except EVariantNotInSolution as e:
      stderr.writeLine("repro lock explain: " & e.msg)
      return 1
  else:
    stderr.writeLine("repro lock: unknown verb '" & args[0] & "'")
    return 2

# ---------------------------------------------------------------------------
# RA-26 — `repro prompt` ambient workspace-state segment (+ `repro prompt
# init <shell>`). Per CLI/prompt.md the prompt is recomputed on EVERY shell
# render, so this path MUST be fast and side-effect-free: it reads only CHEAP
# CACHED workspace state and never fans out a `git` subprocess per repo.
#
# Cached signals consulted (all plain filesystem reads — NO git):
#   * ``.repo/workspace.toml``                   — the RA-10 workspace marker
#     and the active workspace branch (``readWorkspaceBranch``). Absence of
#     the marker is what makes the command silent + exit 0 outside a
#     workspace.
#   * ``.repro/build/prompt-cache.json``         — the purpose-built prompt
#     cache (``promptCachePath`` / ``writePromptCache``), refreshed by the
#     commands that CHANGE workspace state; read for the repo count and the
#     drift signal. It carries the timestamp and the branch it describes, so a
#     cache that can no longer be trusted is rendered with a ``?`` marker
#     instead of silently asserting a stale number. This replaced scraping
#     ``sync-report.json``, which had no invalidation at all and went blank
#     once the report became opt-in.
#   * ``develop-overrides.json``                 — the registered develop-mode
#     (writable-checkout) dependencies; read for the ``dev:N`` count. This is
#     also the on-disk side of the *physical signal* documented in
#     CLI/prompt.md: develop deps are writable checkouts, pinned deps are
#     read-only store paths.
#
# Editor/LSP integration and a daemon-pushed live-status stream are
# explicitly OUT OF SCOPE for RA-26 (milestone scope_note).
# ---------------------------------------------------------------------------

type
  PromptFormat = enum
    pfPlain,    ## bare text, no escapes — safe everywhere
    pfAnsi,     ## colorized with SGR escapes for terminals
    pfJson,     ## structured, for custom prompt integrations
    pfTemplate  ## user-supplied template string with ``{placeholders}``

  PromptArgs = object
    format: PromptFormat
    templateStr: string   ## populated only when format == pfTemplate
    workspaceRoot: string
    explicitWorkspaceRoot: bool

  PromptState = object
    ## The cheap cached facts the segment renders. Computed once per
    ## invocation from filesystem reads only — never a per-repo git call.
    inWorkspace: bool
    branch: string        ## active workspace branch ("" if unknown)
    repoCount: int        ## participating repos per the prompt cache
    driftRepos: int       ## repos whose cached branch != workspace branch
    developCount: int     ## registered develop-mode (writable) dependencies
    haveCache: bool       ## a readable prompt cache was found
    stale: bool           ## the cache may no longer describe the workspace
    staleReason: string   ## which staleness signal fired (empty when fresh)
    cacheAgeSeconds: int64
    cacheWrittenBy: string  ## the verb that last refreshed the cache

proc promptCacheStaleness(workspaceRoot, cachePath, cacheBranch,
                          liveBranch: string;
                          writtenAtUnix: int64): tuple[stale: bool;
                                                       reason: string;
                                                       age: int64] =
  ## Three cheap signals, no git and no per-repo work — one string compare and
  ## at most two stats. Order matters: report the most specific cause.
  let age = max(0'i64, getTime().toUnix - writtenAtUnix)
  # 1. The workspace moved to another branch after the cache was written, so
  #    the drift count is computed against the wrong baseline.
  if liveBranch != cacheBranch:
    return (true, "branch-changed", age)
  # 2. The workspace metadata changed after the cache was written. Cheaper and
  #    sharper than any heuristic: whatever touched `workspace.toml` also
  #    plausibly changed the repo set.
  try:
    let markerPath = workspaceRoot / ".repro" / "workspace.toml"
    if fileExists(extendedPath(markerPath)) and
        fileExists(extendedPath(cachePath)) and
        getLastModificationTime(extendedPath(markerPath)) >
          getLastModificationTime(extendedPath(cachePath)):
      return (true, "metadata-newer", age)
  except CatchableError:
    discard
  # 3. Absolute age bound — the backstop for everything we cannot observe
  #    cheaply (a repo deleted by hand, a branch switched with plain git).
  if age > PromptCacheMaxAgeSeconds:
    return (true, "expired", age)
  (false, "", age)

proc readPromptState(workspaceRoot: string): PromptState =
  ## Populate the segment facts from cached state ONLY. Each read is
  ## defensive: a missing or malformed cache degrades to a partial segment
  ## rather than raising (the prompt must never break the user's shell).
  result.inWorkspace = true
  # Active branch — from ``.repro/workspace.toml`` (filesystem read, no git).
  try:
    let branchOpt = readWorkspaceBranch(workspaceRoot)
    if branchOpt.isSome:
      result.branch = branchOpt.get()
  except CatchableError:
    discard
  # Repo count + drift — from the purpose-built prompt cache, if one exists.
  # We do NOT observe the live repos; we report what the last state-changing
  # command recorded, and whether that record can still be trusted.
  let cachePath = promptCachePath(workspaceRoot)
  if fileExists(extendedPath(cachePath)):
    try:
      let root = parseFile(extendedPath(cachePath))
      if root.kind == JObject and
          root{"schema"}.getStr() == PromptCacheSchema:
        result.haveCache = true
        result.repoCount = root{"repoCount"}.getInt()
        result.driftRepos = root{"driftRepos"}.getInt()
        result.cacheWrittenBy = root{"writtenBy"}.getStr()
        let staleness = promptCacheStaleness(workspaceRoot, cachePath,
          root{"branch"}.getStr(), result.branch,
          root{"writtenAtUnix"}.getBiggestInt())
        result.stale = staleness.stale
        result.staleReason = staleness.reason
        result.cacheAgeSeconds = staleness.age
    except CatchableError:
      discard
  # Develop-mode (writable-checkout) dependency count — from the registered
  # overrides file. This is the cheap, cached side of the physical signal.
  try:
    let overridesPath = developOverridesMetadataPath(workspaceRoot)
    result.developCount = readDevelopOverrides(overridesPath).len
  except CatchableError:
    discard

proc promptStaleMark(state: PromptState): string =
  ## The one-character staleness marker appended to any field the prompt cache
  ## sourced. A visible ``?`` is the whole point: the previous behaviour was to
  ## print a confidently wrong number, and "3 repos drifted, probably" is a
  ## strictly better answer than "3 repos drifted".
  if state.stale: "?" else: ""

proc segmentFields(state: PromptState): seq[(string, string)] =
  ## The ordered (placeholder-key, rendered-value) pairs. Only non-empty
  ## fields are emitted, matching the CLI/prompt.md example
  ## ``[ws:feat-x ●3 dev:2]``. The branch comes from workspace metadata and is
  ## therefore always current; only the cache-sourced drift count can be stale.
  if state.branch.len > 0:
    result.add(("ws", "ws:" & state.branch))
  if state.driftRepos > 0:
    result.add(("drift", "●" & $state.driftRepos & promptStaleMark(state)))
  if state.developCount > 0:
    result.add(("dev", "dev:" & $state.developCount))

proc renderPromptPlain(state: PromptState): string =
  let fields = segmentFields(state)
  if fields.len == 0:
    # An initialized workspace with no cached drift/develop facts still
    # produces a stable, non-empty marker so the segment is visible.
    return "[ws]"
  var parts: seq[string]
  for (_, value) in fields:
    parts.add(value)
  "[" & parts.join(" ") & "]"

proc renderPromptAnsi(state: PromptState): string =
  ## Same content as plain, wrapped in a dim-cyan SGR pair. We emit the
  ## escapes unconditionally for ``--format ansi`` (the caller opts in);
  ## ``--format plain`` stays escape-free for prompts that dislike them.
  const sgrOn = "\e[36m"
  const sgrOff = "\e[0m"
  sgrOn & renderPromptPlain(state) & sgrOff

proc renderPromptJson(state: PromptState): string =
  let obj = %*{
    "inWorkspace": state.inWorkspace,
    "branch": state.branch,
    "repoCount": state.repoCount,
    "driftRepos": state.driftRepos,
    "developCount": state.developCount,
    "haveCache": state.haveCache,
    "stale": state.stale,
    "staleReason": state.staleReason,
    "cacheAgeSeconds": state.cacheAgeSeconds,
    "cacheWrittenBy": state.cacheWrittenBy,
    "segment": renderPromptPlain(state),
  }
  $obj

proc renderPromptTemplate(state: PromptState; tmpl: string): string =
  ## Substitute documented ``{placeholder}`` tokens in a user format
  ## string. Unknown tokens are left verbatim. Documented placeholders:
  ##   {branch}  active workspace branch ("" if unknown)
  ##   {repos}   participating repo count from the prompt cache
  ##   {drift}   repos whose cached branch differs from the workspace branch
  ##   {develop} registered develop-mode (writable) dependency count
  ##   {stale}   "?" when the cache may no longer describe the workspace, else ""
  ##   {segment} the default plain segment string
  result = tmpl
  result = result.replace("{branch}", state.branch)
  result = result.replace("{repos}", $state.repoCount)
  result = result.replace("{drift}", $state.driftRepos)
  result = result.replace("{develop}", $state.developCount)
  result = result.replace("{stale}", promptStaleMark(state))
  result = result.replace("{segment}", renderPromptPlain(state))

proc renderPromptSegment(state: PromptState; args: PromptArgs): string =
  case args.format
  of pfPlain: renderPromptPlain(state)
  of pfAnsi: renderPromptAnsi(state)
  of pfJson: renderPromptJson(state)
  of pfTemplate: renderPromptTemplate(state, args.templateStr)

proc parsePromptArgs(args: openArray[string]): PromptArgs =
  ## ``repro prompt [--format <plain|ansi|json|<template>>]
  ## [--workspace-root=PATH]``. ``--format`` accepts the three named modes
  ## or, for any other value, treats the value as a template string
  ## (matching the spec's ``<template>`` form).
  result.format = pfPlain
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--format" or arg.startsWith("--format="):
      let value = valueFromFlag(args, i, "--format")
      case value
      of "plain": result.format = pfPlain
      of "ansi": result.format = pfAnsi
      of "json": result.format = pfJson
      else:
        result.format = pfTemplate
        result.templateStr = value
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      result.workspaceRoot = valueFromFlag(args, i, "--workspace-root")
      result.explicitWorkspaceRoot = true
    elif arg.startsWith("-"):
      raise newException(ValueError,
        "unsupported `repro prompt` flag: " & arg)
    else:
      raise newException(ValueError,
        "unexpected positional argument to `repro prompt`: " & arg)
    inc i
  if result.workspaceRoot.len == 0:
    result.workspaceRoot = getCurrentDir()
  result.workspaceRoot = absolutePath(result.workspaceRoot)

proc runPromptCommand*(args: openArray[string]): int =
  ## ``repro prompt`` — print a compact ambient workspace-state segment for
  ## a shell prompt / statusline. Reads ONLY cheap cached state (no
  ## per-render git fan-out). Silent + exit 0 outside a workspace so it is
  ## safe to drop into any prompt unconditionally. Read-only: no side
  ## effects, never blocks on the network.
  let parsed = parsePromptArgs(args)
  let root =
    if parsed.explicitWorkspaceRoot:
      if isInitializedWorkspace(parsed.workspaceRoot):
        parsed.workspaceRoot
      else: ""
    else:
      ascendToWorkspaceRoot(parsed.workspaceRoot)
  if root.len == 0:
    # Outside a workspace: print NOTHING, exit 0 (CLI/prompt.md hard
    # requirement — safe to call unconditionally with no shell guards).
    return 0
  let state = readPromptState(root)
  stdout.writeLine(renderPromptSegment(state, parsed))
  0

proc renderPromptInitSnippet(shell: string; reproBin: string): string =
  ## Emit the per-shell integration snippet (``repro prompt init <shell>``).
  ## Like ``starship init zsh`` / ``direnv hook bash``: prints a snippet for
  ## the user to add to their rc — it NEVER mutates the prompt itself. The
  ## segment is appended (opt-in) so an existing prompt is preserved.
  case shell
  of "bash":
    "# repro prompt — add to ~/.bashrc (opt-in; does not replace your prompt)\n" &
    "__repro_prompt() { " & reproBin & " prompt 2>/dev/null; }\n" &
    "PROMPT_COMMAND='PS1=\"$(__repro_prompt)$PS1_BASE\"; '\"$PROMPT_COMMAND\"\n" &
    "# Or simpler, inline in PS1:\n" &
    "#   PS1='$(" & reproBin & " prompt) '\"$PS1\"\n"
  of "zsh":
    "# repro prompt — add to ~/.zshrc (opt-in)\n" &
    "__repro_prompt() { " & reproBin & " prompt 2>/dev/null; }\n" &
    "setopt prompt_subst\n" &
    "RPROMPT='$(__repro_prompt)'\"$RPROMPT\"\n"
  of "fish":
    "# repro prompt — add to ~/.config/fish/config.fish (opt-in)\n" &
    "function __repro_prompt\n" &
    "    " & reproBin & " prompt 2>/dev/null\n" &
    "end\n" &
    "# Append to your fish_prompt, e.g.:\n" &
    "#   functions -c fish_prompt __fish_prompt_orig\n" &
    "#   function fish_prompt; __fish_prompt_orig; __repro_prompt; end\n"
  of "starship":
    "# repro prompt — add to ~/.config/starship.toml (opt-in)\n" &
    "[custom.repro]\n" &
    "command = \"" & reproBin & " prompt\"\n" &
    "when = true\n" &
    "format = \"[$output]($style) \"\n" &
    "shell = [\"sh\"]\n"
  of "p10k", "powerlevel10k":
    "# repro prompt — add to ~/.p10k.zsh (opt-in)\n" &
    "function prompt_repro() {\n" &
    "  local seg; seg=$(" & reproBin & " prompt 2>/dev/null)\n" &
    "  [[ -n $seg ]] && p10k segment -f cyan -t \"$seg\"\n" &
    "}\n" &
    "# Then add `repro` to POWERLEVEL9K_RIGHT_PROMPT_ELEMENTS.\n"
  of "oh-my-zsh", "omz":
    "# repro prompt — drop into ~/.oh-my-zsh/custom/ as repro.zsh (opt-in)\n" &
    "__repro_prompt() { " & reproBin & " prompt 2>/dev/null; }\n" &
    "setopt prompt_subst\n" &
    "RPROMPT='$(__repro_prompt)'\"$RPROMPT\"\n"
  of "prezto":
    "# repro prompt — Prezto plugin snippet (opt-in)\n" &
    "# Place in a module's init.zsh and append to your prompt:\n" &
    "__repro_prompt() { " & reproBin & " prompt 2>/dev/null; }\n" &
    "setopt prompt_subst\n" &
    "RPROMPT='$(__repro_prompt)'\"$RPROMPT\"\n"
  else:
    ""

proc renderPromptInitUsage(programName: string): string =
  programName & " prompt init <bash|zsh|fish|starship|p10k|oh-my-zsh|prezto>"

proc runPromptInitCommand*(programName: string; args: openArray[string];
                           reproBin: string): int =
  ## ``repro prompt init <shell>`` — print the integration snippet for the
  ## named shell/prompt framework. Opt-in: it only PRINTS a snippet for the
  ## user to add; it never edits any rc file or mutates the live prompt.
  if args.len == 0 or args[0] in ["--help", "-h", "help"]:
    echo renderPromptInitUsage(programName)
    return (if args.len == 0: 2 else: 0)
  let shell = args[0].toLowerAscii()
  let snippet = renderPromptInitSnippet(shell, reproBin)
  if snippet.len == 0:
    stderr.writeLine("repro prompt init: unsupported shell '" & args[0] &
      "'\n" & renderPromptInitUsage(programName))
    return 2
  stdout.write(snippet)
  0

const internalHelperAliases = {
  # Documented ``repro internal <name>`` spellings (Executable-Consolidation
  # M1) mapped to the historical ``__repro-<name>`` argument forms. The
  # ``__``-prefixed forms remain accepted as compatibility aliases for one
  # release; both route to the identical handler. ``io monitor`` is handled
  # separately because it has no ``__repro-`` form (its user-facing spelling
  # is ``repro debug io monitor``).
  "runquota-helper": "__repro-runquota-helper",
  "compile-provider": "__repro-compile-provider",
  "extract-interface": "__repro-extract-interface",
  "compile-profile": "__repro-compile-profile",
  "dev-env-introspect": "__repro-dev-env-introspect",
  "render-dev-env-shell": "__repro-render-dev-env-shell",
  "direnv-activate": "__repro-direnv-activate",
  "native-shell-activate": "__repro-native-shell-activate",
  "dev-session-supervisor": "__repro-dev-session-supervisor",
  "dev-session-http": "__repro-dev-session-http",
  "cmake-regenerate": "__repro-cmake-regenerate",
}.toTable

proc normalizeInternalArgs(args: seq[string]): seq[string] =
  ## Map ``internal <name> <rest…>`` onto the same argument vector the
  ## ``__repro-<name>`` helper forms use, so the documented ``internal``
  ## namespace and the historical ``__``-prefixed aliases share one set of
  ## handlers below. Subcommands without a ``__repro-`` equivalent
  ## (``io monitor``, usage/help) are left untouched for the dedicated
  ## ``internal`` arm in ``runThinApp`` to handle.
  if args.len >= 1 and args[0] == "internal" and args.len >= 2 and
      internalHelperAliases.hasKey(args[1]):
    result = @[internalHelperAliases[args[1]]]
    if args.len > 2:
      result.add(args[2 .. ^1])
  else:
    result = args

proc normalizeWorkspaceNamespaceAlias*(args: seq[string]): seq[string] =
  ## WV-1 — accept ``repro ws <verb>`` as ``repro workspace <verb>``.
  ##
  ## The alias is resolved HERE, once, before any subcommand routing, rather
  ## than by teaching each ``args[0] == "workspace"`` dispatch arm about a
  ## second spelling. That is the difference between an alias and a fork in the
  ## surface: every workspace verb that exists today and every one added later
  ## inherits it with no per-verb work, and no arm can drift by recognizing one
  ## spelling and not the other.
  ##
  ## Only the leading token is rewritten. ``ws`` in any later position is an
  ## ordinary argument — a project named ``ws``, a path, a forall command body —
  ## and must survive untouched.
  if args.len >= 1 and args[0] == "ws":
    result = @["workspace"]
    if args.len > 1:
      result.add(args[1 .. ^1])
  else:
    result = args

# ---- RA-6: host-ergonomics verbs -------------------------------------------
#
# RA-6 adopts the host-ergonomics surface the repo-workspaces pilot grew that
# reprobuild lacked:
#
#   * ``repro workspace bootstrap`` — scaffold an empty host with the
#     direnv/agent/project-index files a workspace checkout expects
#     (``.envrc`` / ``AGENTS.md`` / ``workspace-projects.md``). Idempotent:
#     a re-run never clobbers an existing file; it reports each as written
#     or skipped.
#   * ``repro workspace enable`` / ``disable`` — activate or deactivate
#     projects in THIS workspace. ``enable --default`` auto-layers the set
#     from ``REPRO_DEFAULT_PROJECTS`` (then the RA-8 ``[projects] default``)
#     when the user has not chosen an explicit set.
#   * ``repro completion <shell>`` — emit a shell completion script
#     (RA-26 ``prompt init`` style: print a snippet, mutate nothing).
#   * ``repro workspace sets`` / ``repos`` — manifest-authoring verbs that
#     write + commit + push repo-set and repo DEFINITIONS to the manifest repo.

const
  bootstrapEnvrcContent = """# shellcheck shell=bash
# reprobuild workspace .envrc — scaffolded by `repro workspace bootstrap`.
# Core direnv behavior for this checkout. Workspace-specific facts belong in
# optional generated files such as `.envrc.workspace`, sourced if present.

source_env_if_exists .envrc.workspace

# Bring the reprobuild dev environment onto PATH for this directory tree.
# `repro shell hook` emits the activation; `direnv allow` opts in once.
if has repro; then
  eval "$(repro shell hook bash 2>/dev/null)"
fi
"""

  bootstrapAgentsContent = """# Workspace

This is a multi-repo reprobuild workspace. Sibling repos are cloned
side-by-side and coordinated through the workspace manifest. Read
@workspace-projects.md for the active project set and per-repo descriptions.

To activate a repo-set in this workspace use `repro ws enable <set>`
(and `repro ws disable <set>` to drop it). To DEFINE a new repo-set or
repo for everyone, use `repro ws sets add` / `repro ws repos add`; the
manifest is the workspace bill of materials. `workspace-projects.md` is
generated from the manifest — do not edit it by hand.
"""

  bootstrapProjectsDocContent = """# Workspace Projects

This file is generated from the workspace manifest. It lists the repo-sets
layered into this workspace and the repos each one contributes.

Run `repro workspace sets list` to see every defined repo-set and
whether it is enabled here, and `repro workspace enable <set>` to layer
another one in.
"""

  bootstrapGitignoreContent = """# reprobuild local workspace state
.repro/

# generated workspace project documentation
workspace-projects.md
"""

type
  BootstrapFilePlan = object
    name: string
    content: string

  BootstrapFileResult = object
    name: string
    written: bool       ## true when the file was created by this run
    skipped: bool       ## true when the file already existed (left untouched)

proc bootstrapHostFiles(): seq[BootstrapFilePlan] =
  @[
    BootstrapFilePlan(name: ".envrc", content: bootstrapEnvrcContent),
    BootstrapFilePlan(name: ".gitignore", content: bootstrapGitignoreContent),
    BootstrapFilePlan(name: "AGENTS.md", content: bootstrapAgentsContent),
    BootstrapFilePlan(name: "workspace-projects.md",
      content: bootstrapProjectsDocContent),
  ]

proc parseBootstrapTargetDir(args: openArray[string]): string =
  ## ``repro workspace bootstrap [<dir>] [--workspace-root=PATH]``. The target
  ## host directory defaults to the cwd. An explicit positional or
  ## ``--workspace-root`` overrides it.
  result = getCurrentDir()
  for arg in args:
    if arg.startsWith("--workspace-root="):
      result = arg["--workspace-root=".len .. ^1]
    elif not arg.startsWith("-"):
      result = arg

proc runWorkspaceBootstrapCommand*(args: openArray[string]): int =
  ## ``repro workspace bootstrap [<dir>]`` — scaffold the host ergonomics
  ## files (``.envrc`` / ``AGENTS.md`` / ``workspace-projects.md``) into an
  ## empty host directory. IDEMPOTENT: an existing file is never clobbered —
  ## it is reported as ``skipped`` and left byte-for-byte untouched. Reports
  ## what was written vs skipped on stdout; exit 0 always (a re-run is a safe
  ## no-op, not an error).
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo "repro workspace bootstrap [<dir>] [--workspace-root=PATH]"
    return 0
  let targetDir = parseBootstrapTargetDir(args)
  createDir(targetDir)
  var results: seq[BootstrapFileResult]
  for plan in bootstrapHostFiles():
    let path = targetDir / plan.name
    if fileExists(path):
      results.add(BootstrapFileResult(
        name: plan.name, written: false, skipped: true))
    else:
      writeFile(path, plan.content)
      results.add(BootstrapFileResult(
        name: plan.name, written: true, skipped: false))
  for r in results:
    if r.written:
      stdout.writeLine("repro workspace bootstrap: wrote " & r.name)
    else:
      stdout.writeLine("repro workspace bootstrap: skipped " & r.name &
        " (already exists)")
  let wrote = results.filterIt(it.written).len
  let skipped = results.filterIt(it.skipped).len
  stdout.writeLine("repro workspace bootstrap: " & $wrote & " written, " &
    $skipped & " skipped in " & targetDir)
  0

# ---- RA-19: Windows env activation + toolchain provisioning parity ---------
#
# On Linux/macOS the Nix devShell (``repro shell hook`` / the scaffolded
# ``.envrc``) supplies the workspace toolchain. Windows has no such flake,
# so — mirroring the repo-workspaces pilot (``env.ps1`` +
# ``windows/ensure-{gcc,gh,gpg,just,nim,python,repo}.ps1``) — reprobuild
# ensures each required tool itself and activates a PowerShell env.
#
# The DECISION (which ensure-steps, in what order, with which check /
# install commands, under which skip toggle, and the env activation) is
# factored into the PURE, platform-parameterized ``windowsProvisioningPlan``
# below so it is computable + assertable on any host. Only the actual
# ``& pwsh -Command …`` execution (``runWorkspaceProvisionCommand``) is
# guarded by ``when defined(windows)``; live Windows toolchain provisioning
# cannot be exercised on a Linux host.

type
  ProvisionStep* = object
    ## One toolchain ensure-step in a host provisioning plan. ``tool`` names
    ## the tool; ``checkCommand`` is the idempotent "already installed?"
    ## probe (skip the install when it succeeds with the wanted version);
    ## ``installCommand`` is the ensure/install action; ``skipEnvVar`` is the
    ## operator toggle that bypasses this step (parity with the pilot's
    ## ``WINDOWS_DIY_SKIP_*`` knobs).
    tool*: string
    checkCommand*: string
    installCommand*: string
    skipEnvVar*: string

  HostEnvActivation* = object
    ## The env-activation descriptor a provisioning plan produces. On
    ## Windows this is the PowerShell dot-source of the scaffolded
    ## ``env.ps1`` that puts the ensured toolchain on ``$env:PATH``.
    targetOs*: WorkspaceTargetOs
    shell*: string             ## e.g. "powershell"
    activateCommand*: string   ## the env-activation command line

  WindowsProvisioningPlan* = object
    ## The fully-resolved Windows provisioning plan: the ordered ensure
    ## steps plus the env activation. Pure data — no side effects.
    installRoot*: string
    arch*: string
    steps*: seq[ProvisionStep]
    activation*: HostEnvActivation

const
  ## The Windows toolchain reprobuild ensures, in dependency order. ``nim``
  ## + ``gcc`` come first (needed to build/run the native workspace tools),
  ## then the per-workspace dev tools (``just``/``gh``/``python``), then the
  ## ``repo`` launcher, then native ``gpg`` (used to verify the repo release
  ## tag without msys2 gpg's path-mangling). Mirrors the pilot ``env.ps1``
  ## ``$frameworkScripts`` order.
  windowsProvisionTools* = [
    "nim", "gcc", "just", "gh", "python", "repo", "gpg"]

proc windowsToolSkipEnvVar(tool: string): string =
  ## The ``WINDOWS_DIY_SKIP_<TOOL>`` operator toggle for a given tool —
  ## parity with the pilot env.ps1 skip knobs.
  "WINDOWS_DIY_SKIP_" & tool.toUpperAscii()

proc windowsProvisioningPlan*(installRoot: string;
                              arch = "x64"): WindowsProvisioningPlan =
  ## PURE decision function: compute the ordered Windows toolchain ensure
  ## steps + the PowerShell env activation for a host with toolchains under
  ## ``installRoot`` (``%LOCALAPPDATA%\reprobuild\toolchains`` by default)
  ## and CPU ``arch``. No process is launched; the returned plan is asserted
  ## by the RA-19 test on any host and executed only under Windows by
  ## ``runWorkspaceProvisionCommand``.
  ##
  ## Each step names a tool, an idempotent ``--version`` check (skip the
  ## install when the wanted tool is already present), an ensure/install
  ## command (the reprobuild equivalent of ``windows/ensure-<tool>.ps1``),
  ## and the ``WINDOWS_DIY_SKIP_<TOOL>`` toggle. The activation dot-sources
  ## the scaffolded ``env.ps1`` so the ensured toolchain lands on PATH.
  result.installRoot = installRoot
  result.arch = arch
  for tool in windowsProvisionTools:
    let toolDir = installRoot & "\\" & tool
    result.steps.add(ProvisionStep(
      tool: tool,
      checkCommand: tool & " --version",
      installCommand: "repro internal windows ensure-" & tool &
        " --install-root " & q(toolDir) & " --arch " & arch,
      skipEnvVar: windowsToolSkipEnvVar(tool)))
  result.activation = HostEnvActivation(
    targetOs: wtWindows,
    shell: "powershell",
    # Dot-source the scaffolded env.ps1 so the ensured toolchain (under
    # installRoot) is put on $env:PATH for this PowerShell session.
    activateCommand: ". " & q(installRoot & "\\env.ps1"))

proc runWorkspaceProvisionCommand*(args: openArray[string]): int =
  ## ``repro workspace provision`` — ensure the host toolchain and activate
  ## the workspace env. On Linux/macOS this is a no-op (the Nix devShell /
  ## ``.envrc`` already provides the toolchain) and we say so. On Windows it
  ## walks ``windowsProvisioningPlan`` and runs each non-skipped ensure step
  ## through PowerShell, then activates the env.
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo "repro workspace provision [--install-root=PATH] [--arch=x64|arm64]"
    return 0
  var installRoot = ""
  var arch = "x64"
  for arg in args:
    if arg.startsWith("--install-root="):
      installRoot = arg["--install-root=".len .. ^1]
    elif arg.startsWith("--arch="):
      arch = arg["--arch=".len .. ^1]
  when defined(windows):
    if installRoot.len == 0:
      let localAppData = getEnv("LOCALAPPDATA")
      installRoot =
        if localAppData.len > 0:
          localAppData & "\\reprobuild\\toolchains"
        else:
          getHomeDir() / "reprobuild-toolchains"
    let plan = windowsProvisioningPlan(installRoot, arch)
    for step in plan.steps:
      if getEnv(step.skipEnvVar).len > 0:
        stdout.writeLine("repro workspace provision: skipped " & step.tool &
          " (" & step.skipEnvVar & " set)")
        continue
      stdout.writeLine("repro workspace provision: ensuring " & step.tool)
      # Run the idempotent check; install only when it fails. Best-effort
      # per tool — a failed ensure is reported, not fatal to the others.
      let checkRc = execShellCmd("powershell -NoProfile -Command " &
        q(step.checkCommand))
      if checkRc != 0:
        discard execShellCmd("powershell -NoProfile -Command " &
          q(step.installCommand))
    stdout.writeLine("repro workspace provision: activating env via " &
      plan.activation.activateCommand)
    discard execShellCmd("powershell -NoProfile -Command " &
      q(plan.activation.activateCommand))
    return 0
  else:
    # POSIX hosts get their toolchain from the Nix devShell / scaffolded
    # .envrc; explicit provisioning is a Windows-only concern.
    stdout.writeLine("repro workspace provision: no-op on this platform " &
      "(toolchain comes from the Nix devShell / .envrc; Windows hosts " &
      "ensure the toolchain via windowsProvisioningPlan)")
    return 0

# ---- RA-6: workspace-root + default-set helpers ----------------------------

proc parseProjectsWorkspaceRoot(args: openArray[string]): string =
  result = getCurrentDir()
  var explicit = ""
  for arg in args:
    if arg.startsWith("--workspace-root="):
      explicit = arg["--workspace-root=".len .. ^1]
  if explicit.len > 0:
    return absolutePath(explicit)
  let ascended = ascendToWorkspaceRoot(result)
  if ascended.len > 0:
    return ascended
  result = absolutePath(result)

proc readDefaultTemplateFromHostConfig(workspaceRoot: string): string =
  ## Workspace-Membership-Model.md §"Templates" — the host bootstrap config's
  ## `[projects] default_template`. Policy lives in ORG CONFIG, never hardcoded
  ## in the binary, so an absent config or an absent key means "no default" and
  ## the empty stub is what gets written.
  ##
  ## Best-effort in the same sense `[projects] default` is: an unreadable
  ## config yields "" rather than failing the `add`. That is the safe
  ## direction here — no template is the pre-template behaviour, whereas
  ## refusing would make an unrelated config typo block authoring entirely.
  let configPath = findBootstrapConfigPath(workspaceRoot)
  if configPath.len == 0:
    return ""
  try:
    let cfg = readWorkspaceBootstrap(configPath)
    return cfg.projects.default_template.get("")
  except CatchableError:
    return ""

proc readDefaultProjectsFromHostConfig(workspaceRoot: string): seq[string] =
  ## RA-8 fallback source for ``enable --default``: the host bootstrap
  ## config's ``[projects] default`` set. Best-effort — a missing/malformed
  ## config yields an empty set (the env var is the primary source).
  let configPath = findBootstrapConfigPath(workspaceRoot)
  if configPath.len == 0:
    return @[]
  try:
    let cfg = readWorkspaceBootstrap(configPath)
    return cfg.projects.default
  except CatchableError:
    return @[]

# ---- WV-2: `repro workspace enable` / `disable` -----------------------------
#
# The MEMBERSHIP axis: which projects are active in THIS workspace. The
# DEFINITION axis (which projects and repos exist at all) is the manifest-
# authoring `projects` / `repos` verbs further down. See
# `reprobuild-specs/CLI/workspace.md` §"The Two Axes".

proc definedProjectNames*(workspaceRoot: string): seq[string] =
  ## Every repo-set (project, variant) the workspace's manifests root DEFINES,
  ## sorted.
  ##
  ## This is the definition axis's view of the world and it is deliberately a
  ## directory listing rather than a resolve: a set whose manifest is
  ## malformed still EXISTS, and reporting it as undefined would send the
  ## operator to `sets add` to create a file that is already there.
  ##
  ## `repo-sets/` joins the same listing rather than getting a parallel one:
  ## Workspace-Membership-Model.md retires "project" as a separate kind, so a
  ## set and a project are one namespace here as they are in resolution
  ## (`resolveWorkspaceProjectByName`). An unconverted manifest repo has no
  ## `repo-sets/` directory and the listing is unchanged for it.
  let manifests = manifestsRoot(workspaceRoot)
  var seen: seq[string]
  for sub in ["projects", "variants", "repo-sets"]:
    let dir = manifests / sub
    if not dirExists(dir):
      continue
    for kind, path in walkDir(dir):
      if kind notin {pcFile, pcLinkToFile}:
        continue
      if path.splitFile.ext != ".toml":
        continue
      let name = path.splitFile.name
      if name notin seen:
        seen.add(name)
  sort(seen)
  seen

proc manifestDefinitionsAreVisible*(workspaceRoot: string): bool =
  ## Whether this workspace can tell a defined project from an undefined one.
  ##
  ## It cannot during the RA-6 fresh-clone bootstrap: `enable --default` runs
  ## before any manifest checkout exists, so EVERY name looks undefined. Guards
  ## that refuse unknown names must consult this first and stay silent when the
  ## answer is "no manifests yet" — the PS-4 lesson, which learned the same
  ## thing the hard way about conflict refusal.
  let manifests = manifestsRoot(workspaceRoot)
  dirExists(manifests / "projects") or dirExists(manifests / "variants") or
    dirExists(manifests / "repo-sets")

proc projectSetRepoPaths(workspaceRoot: string;
                         names: openArray[string]): seq[string] =
  ## Checkout paths the named project set declares. An empty set declares
  ## nothing (rather than raising, which is what `resolveProjectSet` does for
  ## an empty name list) — "the remaining set after disabling everything" is a
  ## legitimate question with the answer "no repos".
  if names.len == 0:
    return @[]
  let resolved = resolveProjectSet(workspaceRoot, names)
  for repo in resolved.repos:
    result.add(repo.path)

proc projectSetRepoPathsMissingOnDisk(workspaceRoot: string;
                                      names: openArray[string]): seq[string] =
  ## WV-2 — the checkout paths the named projects declare that are NOT on disk
  ## yet. `enable` materializes only when this is non-empty, so enabling
  ## projects whose repos are all present (or which declare no repos at all)
  ## stays a pure metadata operation and never reaches for the network.
  for path in projectSetRepoPaths(workspaceRoot, names):
    if not dirExists(workspaceRoot / path / ".git"):
      result.add(path)

proc parseMembershipProjects(rest: openArray[string]): seq[string] =
  ## Positional project names from a membership verb's argv.
  for arg in rest:
    if not arg.startsWith("-"):
      result.add(arg)

proc defaultProjectsToEnable(workspaceRoot: string): seq[string] =
  ## The `--default` set: `REPRO_DEFAULT_PROJECTS` (primary), then the RA-8
  ## host config. With NEITHER set the result is empty and the caller no-ops —
  ## no env var means no auto-layer, not an error.
  let envRaw = getEnv("REPRO_DEFAULT_PROJECTS")
  if envRaw.len > 0:
    for tok in envRaw.split({':', ';', ',', ' ', '\t', '\n'}):
      let t = tok.strip()
      if t.len > 0 and t notin result:
        result.add(t)
  if result.len == 0:
    result = readDefaultProjectsFromHostConfig(workspaceRoot)

proc runWorkspaceEnableCommand*(args: openArray[string]): int =
  ## ``repro workspace enable <project>... [--default] [--no-sync]`` — activate
  ## already-DEFINED projects in this workspace.
  ##
  ## Recording and materializing are ONE operation: membership without working
  ## trees is not a state any other command can act on, so the repos the
  ## enlarged set introduces are checked out through the ordinary sync path.
  ## Membership itself stays idempotent, while the clone phase still creates
  ## anything missing — which makes a re-run the repair path for a partially
  ## cloned workspace.
  let workspaceRoot = parseProjectsWorkspaceRoot(args)
  var explicit = parseMembershipProjects(args)
  var useDefault = false
  var noSync = false
  # Flags the materialization phase understands are forwarded to it rather
  # than rejected here: `enable`'s real work IS a sync, so the report and the
  # JSON digest describing what happened are that sync's.
  var forwarded: seq[string]
  for arg in args:
    if arg == "--default":
      useDefault = true
    elif arg == "--no-sync":
      noSync = true
    elif arg.startsWith("--workspace-root="):
      discard
    elif arg == "--json" or arg == "--verbose" or arg == "--dry-run" or
        arg == "--write-report" or arg.startsWith("--write-report=") or
        arg.startsWith("--jobs") or arg.startsWith("--tags="):
      forwarded.add(arg)
    elif arg.startsWith("-"):
      stderr.writeLine("repro workspace enable: unknown flag " & arg)
      return 2

  var toAdd: seq[string]
  if useDefault:
    toAdd = defaultProjectsToEnable(workspaceRoot)
  for p in explicit:
    if p notin toAdd:
      toAdd.add(p)

  if toAdd.len == 0:
    if useDefault:
      # No env var, no host-config default: a deliberate no-op (exit 0). The
      # active set is untouched — there is no default to layer.
      stdout.writeLine(
        "repro workspace enable: no default project set " &
        "(REPRO_DEFAULT_PROJECTS unset and no host config [projects] " &
        "default); nothing enabled")
      return 0
    stderr.writeLine("repro workspace enable: no project named " &
      "(pass one or more <project> names, or --default)")
    return 2

  # An UNDEFINED name is refused rather than recorded. Membership that no
  # manifest layer can resolve breaks every later workspace command, and the
  # operator's real intent is one of two other verbs. Skipped entirely when the
  # workspace cannot yet see its manifests — see
  # `manifestDefinitionsAreVisible`.
  if manifestDefinitionsAreVisible(workspaceRoot):
    let defined = definedProjectNames(workspaceRoot)
    var undefined: seq[string]
    for p in toAdd:
      if p notin defined:
        undefined.add(p)
    if undefined.len > 0:
      stderr.writeLine("repro workspace enable: no such project: " &
        undefined.join(", "))
      stderr.writeLine("  defined projects: " &
        (if defined.len > 0: defined.join(", ") else: "<none>"))
      stderr.writeLine("  `repro ws sets list` shows them all; " &
        "`repro ws sets add <name>` defines a new one")
      return 2

  let existing = readWorkspaceProjects(workspaceRoot)
  var merged = existing
  for p in toAdd:
    if p notin merged:
      merged.add(p)

  # PS-4 — validate the PROSPECTIVE set before touching anything. Two projects
  # that declare one checkout path with different facts refuse the whole
  # command: no metadata is written and no working tree is touched, so a
  # refused `enable` leaves the workspace exactly as it was.
  #
  # Any OTHER resolution failure is not a refusal. A workspace whose manifest
  # checkout has not landed yet can still record membership; it just has
  # nothing to materialize yet, so the clone phase is skipped and the reason is
  # reported.
  var missing: seq[string]
  var unresolved = ""
  try:
    discard resolveProjectSet(workspaceRoot, merged)
    missing = projectSetRepoPathsMissingOnDisk(workspaceRoot, toAdd)
  except WorkspaceProjectSetConflictError as err:
    stderr.writeLine("repro workspace enable: refusing to record " &
      "the project set — " & err.msg)
    stderr.writeLine("  active set unchanged: " &
      (if existing.len > 0: existing.join(", ") else: "<empty>"))
    return 1
  except CatchableError as err:
    unresolved = err.msg

  writeWorkspaceProjects(workspaceRoot, merged)
  for p in readWorkspaceProjects(workspaceRoot):
    stdout.writeLine(p)

  # The enlarged set can already have checkouts on disk (a re-enable), and the
  # `--no-sync` / nothing-missing paths return without reaching the sync that
  # would otherwise refresh. Refreshing here covers every exit; the sync path
  # refreshes again and the second pass is a no-op.
  refreshWorkspaceSiblingIgnoresBestEffort(workspaceRoot)

  # PS-3 — materialize what was just recorded. Only the repos the named
  # projects introduce are missing-checkout candidates; everything already on
  # disk is left untouched by the sync policy.
  if unresolved.len > 0:
    stderr.writeLine("repro workspace enable: recorded membership " &
      "but could not resolve the manifest yet, so nothing was checked " &
      "out — " & unresolved)
    stderr.writeLine("  run `repro workspace sync` once the manifest is " &
      "available")
    return 0
  if noSync or missing.len == 0:
    return 0
  stdout.writeLine("repro workspace enable: checking out " &
    $missing.len & " repo(s) introduced by " & toAdd.join(", "))
  var syncArgs = @(toAdd)
  syncArgs.add("--workspace-root=" & workspaceRoot)
  for f in forwarded:
    syncArgs.add(f)
  return runWorkspaceSyncCommand(syncArgs)

# ---- Workspace-Membership-Model.md: local-state reconciliation -------------
#
# Manifests arrive by `git pull`; CHECKOUTS do not follow. Three facts about a
# workspace live in `.git/config` and `.git/HEAD` rather than in any manifest,
# so converting the manifest repo leaves every existing checkout stale in ways
# no amount of re-resolving fixes:
#
#   * the primary remote may carry the URL-PREFIX name (`metacraft-labs`)
#     instead of `origin`, which the model makes the always-primary binding;
#   * a fork's `upstream` binding only became expressible with per-binding
#     `url_prefix` / `url_suffix`, so no pre-existing checkout has one;
#   * a checkout may sit on a DETACHED HEAD, which a branch declaration cannot
#     move on its own.
#
# `alignWorkspaceRemotes` already converges the remote SET, but it converges
# it by add-then-prune, and add-then-prune is not a rename: dropping
# `metacraft-labs` deletes `refs/remotes/metacraft-labs/*` and orphans every
# `branch.<b>.remote` that named it, so the developer's tracking configuration
# evaporates while the URL looks right. Reconciliation renames, and says so.
#
# What it refuses to do, and why:
#
#   * It never touches a checkout `repoCheckoutRecognized` cannot identify as
#     the manifest's repo — the same "observe, don't auto-modify an
#     unrecognized checkout" contract sync already follows.
#   * It never PRUNES an undeclared remote. Pruning belongs to sync, where the
#     operator asked for convergence; a migration that also deleted somebody's
#     personal fork remote would be doing a second, unrequested job.
#   * It performs NO network I/O. It runs inside a git hook, so a fetch would
#     make every `git pull` pay for a second round trip — and every question it
#     asks (does this branch exist, is this commit published) is answerable
#     from refs already on disk.
#   * It moves a detached HEAD only when nothing would be lost, and it moves it
#     with `checkout <branch>` rather than `checkout -B <branch>`, so no branch
#     ref is ever repointed. `pull`'s converge step deliberately DOES reset;
#     migration deliberately does not, because a migration nobody asked for
#     must not be able to rewind anybody's branch.
#
# A note for whoever next reads this and wonders whether the RENAME path is
# dead code: measured against the workspace this was written for, it is
# currently inert. Every checkout there already has `origin`, and the only two
# detached HEADs are commit-pinned fragments that are CORRECTLY detached (this
# code defers them, because a pin declares no branch). That is a statement
# about one workspace on one day, not about the code. The paths that carry
# their weight today are `upstream` — which no pre-existing checkout has,
# because per-binding `url_prefix` / `url_suffix` is what made a fork's
# upstream expressible at all — and every OTHER developer's workspace, which
# may predate any of this and is exactly the case that cannot be inspected
# from here. Deleting the rename because the local `git remote -v` looks tidy
# would remove the only thing standing between those workspaces and a silent
# add-then-prune.

type
  LocalStateRepoReport* = object
    ## One checkout's reconciliation outcome.
    ##
    ## `changes` are mutations that happened (or, under `--dry-run`, would);
    ## `deferrals` are the ones this refused to make, each paired with the
    ## `remedy` that unblocks it; `failures` are git operations that were
    ## attempted and did not succeed. A checkout that needed nothing produces
    ## an entry with all three empty, and the drivers drop it — silence is the
    ## steady state, so a second run reports nothing at all.
    ##
    ## `notices` are the fourth kind: states this reconciler observed and
    ## deliberately does not act on FROM A HOOK, because acting would mean
    ## moving a ref inside somebody else's git operation. They are recorded
    ## (the cache log keeps the trace) but never printed to stderr — a
    ## detached HEAD is a position its owner chose, and narrating it on every
    ## subsequent git command is how a hook trains people to stop reading it.
    ## `repro workspace migrate` reports the same states on stdout, on demand.
    name*: string
    path*: string
    changes*: seq[string]
    deferrals*: seq[string]
    remedy*: string
    failures*: seq[string]
    notices*: seq[string]

  WorkspaceLocalStateReport* = object
    ## Structured outcome of one `repro workspace migrate` invocation.
    ## `membership` carries active-set entries that no longer name anything
    ## resolvable — reported, never rewritten.
    workspaceRoot*: string
    project*: string
    dryRun*: bool
    inspected*: int
    repos*: seq[LocalStateRepoReport]
    membership*: seq[string]
    exitCode*: int

proc toJsonNode*(report: WorkspaceLocalStateReport): JsonNode =
  result = newJObject()
  result["workspaceRoot"] = %report.workspaceRoot
  result["project"] = %report.project
  result["dryRun"] = %report.dryRun
  result["inspected"] = %report.inspected
  var repos = newJArray()
  for entry in report.repos:
    var node = newJObject()
    node["name"] = %entry.name
    node["path"] = %entry.path
    node["changes"] = %entry.changes
    node["deferrals"] = %entry.deferrals
    node["remedy"] = %entry.remedy
    node["failures"] = %entry.failures
    node["notices"] = %entry.notices
    repos.add(node)
  result["repos"] = repos
  result["membership"] = %report.membership
  result["exitCode"] = %report.exitCode

proc observedGitRemotes(identity: GitToolIdentity;
                        repoDir: string): seq[tuple[name, url: string]] =
  let names = gitRunPlain(identity, ["-C", repoDir, "remote"])
  if names.code != 0:
    return
  for raw in names.output.strip().splitLines():
    let name = raw.strip()
    if name.len == 0:
      continue
    let url = gitRunPlain(identity, ["-C", repoDir, "remote", "get-url", name])
    result.add((name: name,
      url: (if url.code == 0: url.output.strip() else: "")))

proc declaresExactPin(repo: ResolvedRepo): bool =
  ## Does this fragment pin an exact commit, as opposed to tracking a branch?
  ##
  ## `branch` and `revision` are not alternatives once a fragment carries both:
  ## `branch` says WHERE TO CLONE FROM and `revision` says WHERE TO SIT, and for
  ## a vendored reference tree those are deliberately different — clone `main`,
  ## then sit on the commit the consumer was built against. So a pin has to be
  ## detected from `revision` ALONE. Reading it as "no pin, because a branch is
  ## declared" is exactly the mistake that made this reconciler walk four
  ## vendored trees off their pinned commits and onto whatever `main` had
  ## reached.
  ##
  ## Both pin spellings count: a commit id, and a fully-qualified ref
  ## (`refs/tags/v1`), which names one commit just as narrowly.
  repo.revision.len > 0 and
    (looksLikeSha(repo.revision) or repo.revision.startsWith("refs/"))

proc pinnedCommitFor(identity: GitToolIdentity; repoAbs: string;
                     repo: ResolvedRepo): string =
  ## The commit `declaresExactPin` refers to, resolved against this checkout,
  ## or "" when it cannot be resolved here (an unfetched tag). Callers must
  ## treat "" as "I cannot confirm this checkout is at its pin", never as "it
  ## has no pin" — the two have opposite consequences.
  if not declaresExactPin(repo):
    return ""
  if looksLikeSha(repo.revision):
    return repo.revision
  revParse(identity, repoAbs, repo.revision)

proc declaredBranchFor(repo: ResolvedRepo): string =
  ## The branch a detached checkout should land on, or "" when the fragment
  ## does not name one.
  ##
  ## Only consulted for a repo that `declaresExactPin` says is NOT pinned; a
  ## pinned one is answered before this is reached, because for those the
  ## declared branch is the clone source rather than the resting place.
  if repo.branch.len > 0:
    return repo.branch
  if repo.revision.len > 0 and not looksLikeSha(repo.revision) and
      not repo.revision.startsWith("refs/"):
    return repo.revision
  ""

proc primaryRemoteNameFor(repo: ResolvedRepo): string =
  ## The LOCAL git remote name of the repo's primary binding. The model makes
  ## that `origin` always; the fallbacks exist so a `ResolvedRepo` synthesized
  ## outside the resolver (lock files, develop-set discovery) still answers.
  for r in repo.remotes:
    if r.localName == "origin":
      return "origin"
  if repo.remotes.len > 0 and repo.remotes[0].localName.len > 0:
    return repo.remotes[0].localName
  "origin"

proc localStateMayBeStale(workspaceRoot: string; repo: ResolvedRepo): bool =
  ## A SUBPROCESS-FREE pre-filter: could this checkout possibly need work?
  ##
  ## The managed `post-merge` hook fires in every participating repo, and a
  ## workspace of this size has a couple of hundred of them. Probing each one
  ## with git would cost ~800 process spawns on every merge, which is how a
  ## helpful hook becomes the reason people disable hooks. Reading
  ## `.git/HEAD` and `.git/config` answers the same question from two file
  ## reads.
  ##
  ## Deliberately biased toward "yes": a false positive costs one full probe
  ## that then decides correctly, so the filter can never change an outcome —
  ## only how long reaching it takes. `repro workspace migrate` skips the
  ## filter entirely and probes everything, which is what makes it the
  ## debuggable surface.
  let gitDir = workspaceRoot / repo.path / ".git"
  if not dirExists(gitDir):
    # A `.git` FILE (worktree / submodule link) or nothing at all. Not a shape
    # this filter can read, so hand it to the full probe rather than guess.
    return fileExists(gitDir)
  try:
    let head = readFile(gitDir / "HEAD").strip()
    if not head.startsWith("ref:"):
      return true                       # detached
  except CatchableError:
    return true
  var config = ""
  try:
    config = readFile(gitDir / "config")
  except CatchableError:
    return true
  for binding in repo.remotes:
    if binding.localName.len == 0 or binding.fetchUrl.len == 0:
      continue
    # Look for the section header and, after it, the exact URL. Matching the
    # url anywhere in the file would accept a correct URL filed under the WRONG
    # remote name, which is the very drift being looked for.
    let header = "[remote \"" & binding.localName & "\"]"
    let at = config.find(header)
    if at < 0:
      return true
    var section = config[(at + header.len) .. ^1]
    let nextSection = section.find("\n[")
    if nextSection >= 0:
      section = section[0 ..< nextSection]
    var sawUrl = false
    for line in section.splitLines():
      let trimmed = line.strip()
      if trimmed.startsWith("url"):
        let eq = trimmed.find('=')
        if eq >= 0 and trimmed[(eq + 1) .. ^1].strip() == binding.fetchUrl:
          sawUrl = true
    if not sawUrl:
      return true
  false

proc reconcileRepoLocalState(identity: GitToolIdentity;
                             workspaceRoot: string; repo: ResolvedRepo;
                             dryRun: bool;
                             attachDetachedHead: bool): LocalStateRepoReport =
  ## Reconcile ONE checkout's git remotes and HEAD attachment against its
  ## resolved fragment. Idempotent: every step is expressed as "the observed
  ## state differs from the declared state", so a second run finds no
  ## difference, runs no git command, and reports nothing.
  ##
  ## ``attachDetachedHead`` gates the ONE step here that moves HEAD. It is
  ## true for `repro workspace migrate` — an operator verb, typed on purpose,
  ## at a moment of the operator's choosing — and false for the managed hook
  ## arm, which runs inside somebody else's `git checkout`. `git checkout`
  ## from a `post-checkout` hook is a hook overruling the very operation that
  ## invoked it, and no amount of in-flight detection makes that the right
  ## default: the in-flight probe answers "is git busy", while this answers
  ## "was a human asking". Both have to be true, and only the second is
  ## knowable from the argv. When it is false the reconciler still SAYS what
  ## it found, with the verb that would fix it.
  result.name = repo.name
  result.path = repo.path
  let repoAbs = workspaceRoot / repo.path
  if not dirExists(repoAbs / ".git"):
    # Not materialized. Cloning is sync's job; a migration invents no
    # checkouts.
    return

  var live = observedGitRemotes(identity, repoAbs)
  var urls: seq[string]
  for r in live:
    if r.url.len > 0 and r.url notin urls:
      urls.add(r.url)
  if not repoCheckoutRecognized(identity, repoAbs, repo, urls):
    result.deferrals.add("its git remotes (" &
      (if urls.len > 0: urls.join(", ") else: "<none>") &
      ") match no manifest URL and its HEAD is not at the declared revision")
    result.remedy = "inspect what is checked out at '" & repo.path &
      "'; nothing in it was modified"
    return

  proc isDeclaredName(name: string): bool =
    for b in repo.remotes:
      if b.localName == name:
        return true
    false

  # A template rather than a nested proc: the body appends to `result`, and a
  # closure may not capture it.
  template runGit(gitArgs: openArray[string]; description: string) =
    if dryRun:
      result.changes.add(description)
    else:
      let res = gitRunPlain(identity, gitArgs)
      if res.code == 0:
        result.changes.add(description)
      else:
        result.failures.add(description & " — failed: " & res.output.strip())

  # ---- remotes -------------------------------------------------------------
  for binding in repo.remotes:
    if binding.localName.len == 0 or binding.fetchUrl.len == 0:
      continue
    var presentIdx = -1
    for i, r in live:
      if r.name == binding.localName:
        presentIdx = i
        break
    if presentIdx >= 0:
      if live[presentIdx].url != binding.fetchUrl:
        runGit(["-C", repoAbs, "remote", "set-url", binding.localName,
          binding.fetchUrl],
          "remote '" & binding.localName & "' retargeted: " &
            live[presentIdx].url & " -> " & binding.fetchUrl)
        live[presentIdx].url = binding.fetchUrl
      continue

    # Absent under the declared name. Before adding a second remote, look for
    # the SAME remote under a different name — the predecessor tool named the
    # primary after the URL prefix — and RENAME it. `git remote rename` carries
    # `refs/remotes/<old>/*` and rewrites every `branch.<b>.remote` that named
    # it; add-then-prune silently discards both.
    var renameFrom = -1
    for i, r in live:
      if r.url == binding.fetchUrl and not isDeclaredName(r.name):
        renameFrom = i
        break
    if renameFrom < 0 and binding.localName == primaryRemoteNameFor(repo) and
        repo.projectRemote.len > 0:
      # No URL match. A remote named after this repo's URL PREFIX is still the
      # predecessor spelling of the primary binding even when the URL has since
      # drifted (an org rename is exactly that case), so rename it and correct
      # the URL below rather than stranding it beside a new `origin`.
      for i, r in live:
        if r.name == repo.projectRemote and not isDeclaredName(r.name):
          renameFrom = i
          break
    if renameFrom >= 0:
      let oldName = live[renameFrom].name
      runGit(["-C", repoAbs, "remote", "rename", oldName, binding.localName],
        "remote '" & oldName & "' renamed to '" & binding.localName &
          "' (tracking refs and branch upstreams carried over)")
      live[renameFrom].name = binding.localName
      if live[renameFrom].url != binding.fetchUrl:
        runGit(["-C", repoAbs, "remote", "set-url", binding.localName,
          binding.fetchUrl],
          "remote '" & binding.localName & "' retargeted: " &
            live[renameFrom].url & " -> " & binding.fetchUrl)
        live[renameFrom].url = binding.fetchUrl
    else:
      runGit(["-C", repoAbs, "remote", "add", binding.localName,
        binding.fetchUrl],
        "remote '" & binding.localName & "' added at " & binding.fetchUrl)
      live.add((name: binding.localName, url: binding.fetchUrl))

  # ---- HEAD ----------------------------------------------------------------
  #
  # A pinned fragment is asking for a DETACHED HEAD at its pinned commit — that
  # is what a pin is, and it is why the vendored reference trees sit detached.
  # Answered BEFORE anything reads `branch`, because those fragments declare a
  # branch too: it is the ref to clone, not the ref to rest on. Reading the
  # branch first is what turned this reconciler into the "reference trees float
  # off their pin" regression the retained pin exists to prevent.
  let pinned = pinnedCommitFor(identity, repoAbs, repo)
  if declaresExactPin(repo):
    let head = localHeadOrEmpty(identity, repoAbs)
    if head.len > 0 and pinned.len > 0 and
        (head.startsWith(pinned) or pinned.startsWith(head)):
      # Exactly where the manifest says it should be. Silent: a detached HEAD
      # here is the steady state, not drift, and a reconciler that narrated it
      # would report four repos on every merge forever.
      return
    let onBranch = gitRunPlain(identity,
      ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
    if onBranch.code == 0 and onBranch.output.strip().len > 0:
      # Pinned, but somebody has deliberately put it on a branch. Left alone
      # and left unmentioned, for the same reason every other attached checkout
      # is: being on a branch is a human decision this verb does not overrule.
      # "Is this repo at its pinned revision" is a real question, but it
      # belongs to `sync` (which converges it) and `workspace status` (which
      # reports it); answering it a second time from inside a post-merge hook
      # would just add a voice that fires on every merge.
      return
    # Detached and NOT at the pin. Attaching would move it to the branch TIP —
    # further from the pin, not closer — so this is the one case where the
    # reconciler must say something and do nothing.
    result.deferrals.add("HEAD is detached at " &
      (if pinned.len == 0: "an unknown commit"
       else: localHeadOrEmpty(identity, repoAbs)) &
      " but the fragment pins " & repo.revision &
      (if pinned.len == 0: " (which this checkout cannot resolve)" else: ""))
    result.remedy = "run `repro workspace sync` to bring '" & repo.path &
      "' back to its pinned revision; attaching it to a branch would move it " &
      "further away"
    return

  let attached = gitRunPlain(identity,
    ["-C", repoAbs, "symbolic-ref", "--short", "-q", "HEAD"])
  if attached.code == 0 and attached.output.strip().len > 0:
    # Already on a branch. WHICH branch is not this command's business: a
    # developer on a feature branch is working, not drifting, and moving them
    # off it would be the data loss this whole gate exists to prevent.
    return

  let declared = declaredBranchFor(repo)
  if declared.len == 0:
    result.deferrals.add("HEAD is detached and the fragment declares no " &
      "branch to attach it to")
    result.remedy = "declare `branch = \"<name>\"` in the repo fragment for '" &
      repo.name & "', then rerun `repro workspace migrate`"
    return

  if not attachDetachedHead:
    # The hook arm. A detached HEAD is RECORDED, never corrected: a
    # `post-checkout` hook that runs `git checkout` is a hook overruling the
    # operation that invoked it, and the operator who typed `git checkout
    # <sha>` chose that detachment. A `notice` rather than a `deferral` so the
    # trace lands in the cache log without stderr narrating somebody's own
    # detached HEAD back at them after every git command.
    result.notices.add("HEAD is detached and the fragment declares '" &
      declared & "'; a hook does not move refs (run `repro workspace " &
      "migrate` to put '" & repo.path & "' back on '" & declared & "')")
    return

  var blockers = repoRemovalBlockers(identity, repoAbs)
  for extra in detachedHeadOnlyCommits(identity, repoAbs):
    blockers.add(extra)
  if blockers.len > 0:
    result.deferrals.add("HEAD is detached, but attaching it to '" & declared &
      "' would put work at risk: " & blockers.join(", "))
    result.remedy = "commit and push (or stash) the work in '" & repo.path &
      "', then rerun `repro workspace migrate`; nothing in it was modified"
    return

  let remoteName = primaryRemoteNameFor(repo)
  let tracking = "refs/remotes/" & remoteName & "/" & declared
  if revParse(identity, repoAbs, "refs/heads/" & declared).len > 0:
    runGit(["-C", repoAbs, "checkout", "--quiet", declared],
      "detached HEAD attached to existing local branch '" & declared & "'")
  elif revParse(identity, repoAbs, tracking).len > 0:
    runGit(["-C", repoAbs, "checkout", "--quiet", "-b", declared,
      "--track", tracking],
      "detached HEAD attached to a new local branch '" & declared &
        "' tracking " & remoteName & "/" & declared)
  else:
    # No local branch and no remote-tracking ref on disk. Fetching would fix
    # it, and fetching is exactly what this must not do from inside a hook.
    result.deferrals.add("HEAD is detached and neither a local branch '" &
      declared & "' nor '" & remoteName & "/" & declared & "' exists here")
    result.remedy = "run `repro workspace sync` to fetch '" & declared &
      "', then rerun `repro workspace migrate`"

proc reconcileWorkspaceLocalState*(workspaceRoot: string;
                                   repos: seq[ResolvedRepo];
                                   identity: GitToolIdentity;
                                   dryRun = false;
                                   prefilter = false;
                                   attachDetachedHead = true):
    seq[LocalStateRepoReport] =
  ## Reconcile every declared checkout. Only repos with something to say are
  ## returned, so an already-consistent workspace yields an empty seq — which
  ## is what lets the hook stay silent without a second "did anything happen"
  ## test.
  ##
  ## ``attachDetachedHead`` defaults to true because the operator verb is this
  ## proc's reason to exist; the hook arm passes false explicitly.
  for repo in repos:
    if prefilter and not localStateMayBeStale(workspaceRoot, repo):
      continue
    let entry = reconcileRepoLocalState(identity, workspaceRoot, repo, dryRun,
      attachDetachedHead)
    if entry.changes.len > 0 or entry.deferrals.len > 0 or
        entry.failures.len > 0 or entry.notices.len > 0:
      result.add(entry)

proc unresolvableActiveSetNames(workspaceRoot: string): seq[string] =
  ## Entries of the recorded active set that no longer name anything.
  ##
  ## A name that used to be a project and is now a repo-set needs no rewrite —
  ## the resolution ladder consults `repo-sets/` too, so the same string keeps
  ## resolving. What DOES need saying is a name that resolves nowhere. It is
  ## reported and never rewritten: membership is the developer's statement
  ## about which trees they want side by side, and guessing a replacement for a
  ## vanished name would silently change what their workspace builds.
  for name in activeProjectSetOrEmpty(workspaceRoot):
    try:
      discard resolveWorkspaceProjectByName(workspaceRoot, name)
    except CatchableError:
      result.add(name)

proc renderLocalStateTextLines(report: WorkspaceLocalStateReport): seq[string] =
  let verb = if report.dryRun: "would " else: ""
  if report.repos.len == 0 and report.membership.len == 0:
    result.add("repro workspace migrate: " & $report.inspected &
      " checkout(s) already match the manifest; nothing to do")
    return
  for entry in report.repos:
    result.add(entry.path & ":")
    for change in entry.changes:
      result.add("  " & verb & change)
    for deferral in entry.deferrals:
      result.add("  SKIPPED — " & deferral)
    for failure in entry.failures:
      result.add("  FAILED — " & failure)
    for notice in entry.notices:
      result.add("  NOTICE — " & notice)
    if entry.remedy.len > 0:
      result.add("  remedy: " & entry.remedy)
  for name in report.membership:
    result.add("active set entry '" & name & "' resolves to no repo-set, " &
      "project or variant")
    result.add("  remedy: `repro ws sets list` shows what exists; " &
      "`repro ws disable " & name & "` drops it from this workspace")
  var changed = 0
  var deferred = 0
  var failed = 0
  for entry in report.repos:
    if entry.changes.len > 0: inc changed
    if entry.deferrals.len > 0: inc deferred
    if entry.failures.len > 0: inc failed
  result.add("repro workspace migrate: " & $report.inspected &
    " checkout(s) inspected, " & $changed & " " & verb & "reconciled, " &
    $deferred & " skipped, " & $failed & " failed")

proc runWorkspaceMigrateCommand*(args: openArray[string]): int =
  ## ``repro workspace migrate [--dry-run] [--json] [--workspace-root=PATH]``
  ##
  ## Reconcile every checkout's LOCAL git state with the resolved manifest:
  ## rename the primary remote to `origin` carrying its URL and tracking refs,
  ## add or correct a fork's `upstream`, and attach a detached HEAD to the
  ## branch its fragment declares.
  ##
  ## Explicit AND automatic on purpose. The managed `post-merge` hook runs the
  ## same reconciliation so `git pull` is genuinely all a developer needs, but a
  ## hook is a bad place to LEARN what a tool did: it cannot be re-run on
  ## demand, its output competes with git's, and a `--dry-run` of it does not
  ## exist. This verb is the surface you point somebody at when the hook
  ## reported something they did not expect.
  ##
  ## Exit codes follow sync's convention:
  ##   0 — everything reconciled, or already consistent.
  ##   1 — a git operation was attempted and failed.
  ##   2 — at least one checkout was skipped to protect work that exists
  ##       nowhere else. Nothing in it was modified.
  var workspaceRoot = ""
  var dryRun = false
  var json = false
  var reportSpec = ReportSpec()
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--dry-run":
      dryRun = true
    elif arg == "--json":
      json = true
    elif consumeReportFlag(arg, reportSpec):
      discard
    elif arg.startsWith("-"):
      stderr.writeLine("repro workspace migrate: unknown flag " & arg)
      return 2
    else:
      stderr.writeLine("repro workspace migrate: unexpected argument " & arg)
      return 2
    inc i
  if workspaceRoot.len == 0:
    workspaceRoot = getCurrentDir()
  workspaceRoot = os.normalizedPath(absolutePath(workspaceRoot))

  var report: WorkspaceLocalStateReport
  report.workspaceRoot = workspaceRoot
  report.dryRun = dryRun

  let resolved = resolveWorkspaceProjectShared(workspaceRoot, "",
    "`repro workspace migrate`").resolved
  report.project = resolved.projectName
  report.inspected = resolved.repos.len

  let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
  report.repos = reconcileWorkspaceLocalState(workspaceRoot, resolved.repos,
    identity, dryRun = dryRun)
  report.membership = unresolvableActiveSetNames(workspaceRoot)

  var anyFailure = false
  var anyDeferral = false
  for entry in report.repos:
    if entry.failures.len > 0: anyFailure = true
    if entry.deferrals.len > 0: anyDeferral = true
  report.exitCode =
    if anyFailure: 1
    elif anyDeferral: 2
    else: 0

  let destination = reportDestination(reportSpec, workspaceRoot, "migrate")
  if destination.len > 0:
    createDir(parentDir(destination))
    writeFile(destination, pretty(report.toJsonNode(), indent = 2) & "\n")
  stageFailureReport(reportSpec, workspaceRoot, "migrate", report.toJsonNode())
  if json:
    stdout.writeLine(pretty(report.toJsonNode(), indent = 2))
  else:
    for line in renderLocalStateTextLines(report):
      stdout.writeLine(line)
  report.exitCode

proc reconcileLocalStateForHook(workspaceRoot: string):
    tuple[loud, quiet: seq[string]] =
  ## The `post-merge` arm. Best-effort by construction: every failure path
  ## becomes a log line and NOTHING propagates, because a checkout that could
  ## not be reconciled is a thing to fix later, never a reason for somebody's
  ## `git pull` to fail.
  ##
  ## ``loud`` is what the developer is told on stderr — mutations that
  ## happened, and failures. ``quiet`` is recorded in the cache log only.
  ## Both are empty when there is nothing at all to record, which is what
  ## lets the hook stay silent without a second "did anything happen" test.
  ##
  ## ``attachDetachedHead = false``: the remote realignment stays (that is the
  ## whole point of doing this on `git pull`), the ref-moving step does not.
  ## It was the reattachment — `git checkout <declared branch>` fired from
  ## `post-checkout` during a rebase's detached phase — that landed a topic
  ## branch's commits on the mainline and reported "Successfully rebased".
  try:
    let resolved = resolveWorkspaceProjectShared(workspaceRoot, "",
      "`repro hooks dispatch post-merge`").resolved
    let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
    for entry in reconcileWorkspaceLocalState(workspaceRoot, resolved.repos,
        identity, dryRun = false, prefilter = true,
        attachDetachedHead = false):
      for change in entry.changes:
        result.loud.add(entry.path & ": " & change)
      for deferral in entry.deferrals:
        result.loud.add(entry.path & ": SKIPPED — " & deferral &
          (if entry.remedy.len > 0: " (remedy: " & entry.remedy & ")" else: ""))
      for failure in entry.failures:
        result.loud.add(entry.path & ": FAILED — " & failure)
      for notice in entry.notices:
        result.quiet.add(entry.path & ": NOTICE — " & notice)
    for name in unresolvableActiveSetNames(workspaceRoot):
      result.loud.add("active set entry '" & name & "' resolves to no " &
        "repo-set, project or variant (remedy: `repro ws sets list`)")
  except CatchableError as err:
    result.loud.add("local-state reconciliation skipped: " & err.msg)

proc runWorkspaceDisableCommand*(args: openArray[string]): int =
  ## ``repro workspace disable <project>... [--keep-checkouts] [--force]`` —
  ## deactivate projects in this workspace and remove the working trees that
  ## ONLY they declared.
  ##
  ## A repo any still-enabled project also declares is left exactly where it
  ## is: disabling narrows the active set, it does not ask to delete shared
  ## infrastructure. The union rule that makes two projects share one checkout
  ## path (`project_set.nim`) is the same rule that decides what survives here.
  let workspaceRoot = parseProjectsWorkspaceRoot(args)
  var toRemove = parseMembershipProjects(args)
  var keepCheckouts = false
  var force = false
  for arg in args:
    if arg == "--keep-checkouts":
      keepCheckouts = true
    elif arg == "--force":
      force = true
    elif arg.startsWith("--workspace-root="):
      discard
    elif arg.startsWith("-"):
      stderr.writeLine("repro workspace disable: unknown flag " & arg)
      return 2
  if toRemove.len == 0:
    stderr.writeLine("repro workspace disable: no project named " &
      "(pass one or more <project> names)")
    return 2

  let existing = readWorkspaceProjects(workspaceRoot)
  var actuallyLeaving: seq[string]
  for p in toRemove:
    if p in existing and p notin actuallyLeaving:
      actuallyLeaving.add(p)
  if actuallyLeaving.len == 0:
    stdout.writeLine("repro workspace disable: not enabled: " &
      toRemove.join(", ") & "; active set unchanged")
    return 0

  var remaining: seq[string]
  for p in existing:
    if p notin actuallyLeaving:
      remaining.add(p)

  # Which checkouts become unreferenced. Resolution failures here are fatal
  # BEFORE any deletion: a set we cannot resolve is a set whose unique repos we
  # cannot compute, and guessing would delete the wrong tree.
  var orphaned: seq[string]
  if not keepCheckouts:
    try:
      let leavingPaths = projectSetRepoPaths(workspaceRoot, actuallyLeaving)
      let remainingPaths = projectSetRepoPaths(workspaceRoot, remaining)
      for path in leavingPaths:
        if path notin remainingPaths and path notin orphaned:
          orphaned.add(path)
    except CatchableError as err:
      stderr.writeLine("repro workspace disable: cannot determine which " &
        "checkouts are unique to " & actuallyLeaving.join(", ") & " — " &
        err.msg)
      stderr.writeLine("  nothing was removed and the active set is " &
        "unchanged; `--keep-checkouts` records the membership change without " &
        "touching disk")
      return 1

  # The work-loss gate. Deleting a checkout is the one irreversible thing this
  # verb does, so it is decided for EVERY repo before the first one is touched:
  # a refusal leaves the workspace exactly as it was, rather than half-disabled
  # with some trees already gone.
  if orphaned.len > 0 and not force:
    let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
    var blocked: seq[string]
    for path in orphaned:
      let blockers = repoRemovalBlockers(identity, workspaceRoot / path)
      if blockers.len > 0:
        blocked.add("  " & path & ": " & blockers.join(", "))
    if blocked.len > 0:
      stderr.writeLine("repro workspace disable: refusing to remove " &
        $blocked.len & " checkout(s) carrying work that exists nowhere else:")
      for line in blocked:
        stderr.writeLine(line)
      stderr.writeLine("  active set unchanged. Push or discard the work, " &
        "or pass --keep-checkouts to drop membership and leave the " &
        "checkouts, or --force to remove them anyway")
      return 2

  writeWorkspaceProjects(workspaceRoot, remaining)

  var removed = 0
  var removalFailures = 0
  for path in orphaned:
    # A checkout path that is empty, absolute, or escapes the workspace would
    # turn this into a recursive delete of the workspace or something outside
    # it. Manifest data is not trusted with that: refuse the individual removal
    # and say so, rather than resolving the path and hoping.
    #
    # The manifest reader now refuses those shapes at the schema boundary, so
    # this is a second line rather than the only one — but it asks the SAME
    # question, via `checkoutPathRejection`, instead of keeping a private copy
    # of the rule. Two independently-written definitions of "degenerate path"
    # is how one of them ends up narrower than the other, and the narrower one
    # is always the one in front of the `removeDir`.
    let normalized = path.strip()
    let rejection = checkoutPathRejection(normalized)
    if rejection.len > 0:
      inc removalFailures
      stderr.writeLine("repro workspace disable: refusing to remove the " &
        "declared checkout path '" & path & "' — it " & rejection)
      continue
    let dir = workspaceRoot / normalized
    if not dirExists(dir):
      continue
    try:
      removeDir(dir)
      inc removed
      stdout.writeLine("repro workspace disable: removed " & path)
    except CatchableError as err:
      inc removalFailures
      stderr.writeLine("repro workspace disable: failed to remove " & path &
        ": " & err.msg)

  # Removed checkouts must leave the ignore set, or the block keeps naming
  # directories that no longer exist.
  refreshWorkspaceSiblingIgnoresBestEffort(workspaceRoot)

  stdout.writeLine("repro workspace disable: disabled " &
    actuallyLeaving.join(", ") & "; active set: " &
    (if remaining.len > 0: remaining.join(", ") else: "<empty>"))
  if keepCheckouts:
    stdout.writeLine("repro workspace disable: --keep-checkouts — every " &
      "working tree left on disk")
  elif orphaned.len == 0:
    stdout.writeLine("repro workspace disable: every checkout is also " &
      "declared by a still-enabled project; none removed")
  else:
    stdout.writeLine("repro workspace disable: removed " & $removed &
      " checkout(s) unique to the disabled project(s)")
  if removalFailures > 0: 1 else: 0

# ---- RA-6: `repro completion <shell>` --------------------------------------

const reproTopLevelCommands = [
  "build", "watch", "develop", "add", "remove", "push", "sync", "pull",
  "branch",
  "switch", "hooks", "check", "workspace", "ws", "prompt", "completion",
  "store",
  # M9.R.77.5 — ``repro cas <sub>`` is the R11 Layer-1 CLI. It exposes
  # a narrow view of the CAS (blob-level put/get/verify/path/gc) that
  # doesn't touch the Layer-2 prefix / roots / receipts surface
  # ``repro store`` operates against. See runCasCommand for the
  # supported subcommands.
  "cas",
  "daemon", "stats", "graph", "why", "deps", "home", "infra", "system",
  "deploy-agent",
  "hardware", "disk", "launch-plan", "locking",
  # Binary-Caches.md §"Client CLI Surface" — ``repro cache <sub>`` folds
  # in the retired standalone ``repro-binary-cache-client`` toolset.
  "cache",
]

const reproCacheSubcommands = [
  "lookup", "substitute", "publish", "derive-key", "gen-key",
]

const reproLockingSubcommands = [
  "explain", "adopt-manifest",
]

proc runReproLockingExplain(args: openArray[string]): int =
  ## HL-1 (Unified-Locking-And-Hooks §4) — ``repro locking explain``. For the
  ## current workspace, resolve each repo's ``(tier, backend)`` by composing
  ## the configuration LAYERS (built-in → system → dotfiles → parent workspace
  ## → VCS-private) and report, per repo, the resolved tier, backend, AND which
  ## LAYER declared it (with the declaring file's path). ``--json`` emits the
  ## machine-readable form the tests consume. This is the introspection verb a
  ## user runs to debug a layered config without guessing.
  var workspaceRoot = ""
  var projectName = ""
  var mode = tpmUnspecified
  var asJson = false
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--json":
      asJson = true
    elif arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--project" or arg.startsWith("--project="):
      projectName = valueFromFlag(args, i, "--project")
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i, "--tool-provisioning"))
    elif arg.startsWith("-"):
      stderr.writeLine("repro locking explain: unknown flag " & arg)
      return 2
    elif projectName.len == 0:
      projectName = arg
    inc i
  if workspaceRoot.len == 0:
    workspaceRoot = getCurrentDir()
  workspaceRoot = absolutePath(workspaceRoot)
  let (resolved, _) = resolveWorkspaceProjectShared(
    workspaceRoot, projectName, "`repro locking explain`")
  # ``explain`` is read-only introspection; default to PATH-only git
  # resolution (no provisioning) when the caller did not select a mode, the
  # same default the other read-only workspace verbs use.
  let effectiveMode = if mode == tpmUnspecified: tpmPathOnly else: mode
  let identity = ensureGitToolResolvable(effectiveMode, getEnv("PATH"))
  let (assignments, _) =
    resolveWorkspaceRepoBackends(workspaceRoot, resolved.repos, identity)
  if asJson:
    var arr = newJArray()
    for a in assignments:
      arr.add(%*{
        "repo": a.repoName,
        "path": a.repoPath,
        "tier": lockingTierLabel(a.visibility),
        "backend": a.backendKind,
        "layer": layerLabel(a.declaringLayer),
        "source": a.layerSource})
    echo (%*{"schema": "reprobuild.locking-explain.v1",
             "workspaceRoot": workspaceRoot,
             "repos": arr}).pretty
  else:
    if assignments.len == 0:
      echo "repro locking explain: no repos resolved for this workspace"
      return 0
    echo "repro locking explain — resolved (tier, backend) per repo:"
    for a in assignments:
      echo "  " & a.repoName & " (" & a.repoPath & "): tier=" &
        lockingTierLabel(a.visibility) & " backend=" & a.backendKind &
        " layer=" & layerLabel(a.declaringLayer) &
        (if a.layerSource.len > 0: " [" & a.layerSource & "]" else: "")
  return 0

proc runReproLockingAdoptManifest(args: openArray[string]): int =
  ## HL-2 (Unified-Locking-And-Hooks §10 Migration) — ``repro locking
  ## adopt-manifest``. Scaffold an explicit TEAM route mapping the existing
  ## ``.repo/manifests`` git-checkout backend to the team tier, so a legacy
  ## manifest workspace keeps writing its team manifest lock instead of
  ## silently going public-only. The route names every resolved repo (tier-by-
  ## layer) and is written into the VCS-PRIVATE configuration layer (layer 5,
  ## ``<git-common-dir>/repro/config.toml``) — workspace-local, never pushed —
  ## so the scaffold does not touch any committed or shared config. Idempotent:
  ## re-running refreshes the same file.
  var workspaceRoot = ""
  var projectName = ""
  var mode = tpmUnspecified
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--project" or arg.startsWith("--project="):
      projectName = valueFromFlag(args, i, "--project")
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i, "--tool-provisioning"))
    elif arg.startsWith("-"):
      stderr.writeLine("repro locking adopt-manifest: unknown flag " & arg)
      return 2
    elif projectName.len == 0:
      projectName = arg
    inc i
  if workspaceRoot.len == 0:
    workspaceRoot = getCurrentDir()
  workspaceRoot = absolutePath(workspaceRoot)

  let manifestsDir = workspaceRoot / ".repro" / "manifests"
  if not dirExists(manifestsDir):
    stderr.writeLine("repro locking adopt-manifest: no `.repro/manifests` " &
      "checkout at " & manifestsDir & " — nothing to adopt (this verb makes " &
      "an EXISTING manifest the team backend).")
    return 2

  let effectiveMode = if mode == tpmUnspecified: tpmPathOnly else: mode
  let identity = ensureGitToolResolvable(effectiveMode, getEnv("PATH"))
  let (resolved, _) = resolveWorkspaceProjectShared(
    workspaceRoot, projectName, "`repro locking adopt-manifest`")

  # Name every resolved repo so tier-by-layer moves them all into the team
  # tier backed by the existing manifest (the migration keeps the manifest as
  # the team backend for the whole workspace).
  var repoNames: seq[string] = @[]
  for repo in resolved.repos:
    repoNames.add(repo.name)
  if repoNames.len == 0:
    stderr.writeLine("repro locking adopt-manifest: no repos resolved for " &
      "this workspace; nothing to route.")
    return 2

  var quoted: seq[string] = @[]
  for n in repoNames:
    quoted.add("\"" & n & "\"")
  let reposList = quoted.join(", ")
  # The git-checkout backend path is workspace-relative (``.repro/manifests``),
  # resolved against the workspace root by ``constructRoutedBackend``.
  let configBody =
    "schema = \"reprobuild.config.v1\"\n\n" &
    "# HL-2 adopt-manifest: keep the existing `.repro/manifests` checkout as the\n" &
    "# TEAM locking backend (VCS-private layer 5 — never tracked, never pushed).\n" &
    "[locking]\n" &
    "route = [{ visibility = \"team\", backend = \"git-checkout\", " &
    "path = \".repro/manifests\", repos = [" & reposList & "] }]\n"

  let configPath = vcsPrivateConfigPath(workspaceRoot, identity.binaryPath)
  try:
    createDir(configPath.parentDir)
    writeFile(configPath, configBody)
  except CatchableError as err:
    stderr.writeLine("repro locking adopt-manifest: failed to write " &
      configPath & ": " & err.msg)
    return 1

  stderr.writeLine("repro locking adopt-manifest: wrote team route for " &
    $repoNames.len & " repo(s) → git-checkout at `.repro/manifests`")
  stderr.writeLine("  config layer (VCS-private, never pushed): " & configPath)
  stderr.writeLine("  run `repro locking explain` to verify the resolved " &
    "(tier, backend) for each repo.")
  return 0

proc runReproLockingCommand*(args: openArray[string]): int =
  ## Top-level dispatcher for ``repro locking <verb> ...``. HL-1 ships
  ## ``explain``; HL-2 adds ``adopt-manifest``.
  if args.len == 0:
    stderr.writeLine("repro locking: error: missing verb (one of: explain, " &
      "adopt-manifest)")
    return 2
  let rest = if args.len > 1: args[1 .. ^1] else: @[]
  case args[0]
  of "explain":
    return runReproLockingExplain(rest)
  of "adopt-manifest":
    return runReproLockingAdoptManifest(rest)
  else:
    stderr.writeLine("repro locking: error: unknown verb '" & args[0] &
      "' (one of: explain, adopt-manifest)")
    return 2

proc runWorkspacePublishEvidenceCommand*(args: openArray[string]): int =
  ## Workspace-Manifest-Optional MO-13 (correcting MO-5) —
  ## ``repro workspace publish-evidence``. Gather each evidence-only private
  ## repo's source-free ``WorkspaceVcsEvidence`` triple and publish it to the
  ## repo's MO-4-assigned backend (``publishRoutedEvidence``). The owner runs
  ## this from a clean, published checkout at the locked revision; a teammate
  ## who cannot clone the private source then verifies the boundary from the
  ## published evidence (the MO-5 gate-side consume path).
  var workspaceRoot = ""
  var projectName = ""
  var mode = tpmUnspecified
  var i = 0
  while i < args.len:
    let arg = args[i]
    if arg == "--workspace-root" or arg.startsWith("--workspace-root="):
      workspaceRoot = valueFromFlag(args, i, "--workspace-root")
    elif arg == "--project" or arg.startsWith("--project="):
      projectName = valueFromFlag(args, i, "--project")
    elif arg == "--tool-provisioning" or arg.startsWith("--tool-provisioning="):
      mode = parseToolProvisioning(valueFromFlag(args, i, "--tool-provisioning"))
    elif not arg.startsWith("-") and projectName.len == 0:
      projectName = arg
    i.inc
  if workspaceRoot.len == 0:
    workspaceRoot = getCurrentDir()
  workspaceRoot = absolutePath(workspaceRoot)
  let (resolved, _) = resolveWorkspaceProjectShared(
    workspaceRoot, projectName, "`repro workspace publish-evidence`")
  let identity = ensureGitToolResolvable(mode, getEnv("PATH"))
  let observedAt = getTime().toUnix * 1000
  let outcomes = publishRoutedEvidence(
    workspaceRoot, resolved.repos, resolved.projectName, identity, observedAt)
  if outcomes.len == 0:
    echo "repro workspace publish-evidence: no evidence-only repos to publish " &
      "(none marked `participation = \"evidence-only\"`, or no locking routes " &
      "declared)"
    return 0
  var failed = 0
  for o in outcomes:
    if o.published:
      echo "repro workspace publish-evidence: published evidence for '" &
        o.repoName & "' (" & o.backendKind & ") at " & o.headSha
    else:
      inc failed
      stderr.writeLine("repro workspace publish-evidence: FAILED for '" &
        o.repoName & "': " & o.diagnostic)
  if failed > 0: 1 else: 0

const reproWorkspaceSubcommands = [
  "init", "sync", "pull", "lock", "status", "list", "manifests",
  "shared-clones", "forall", "bootstrap", "provision",
  # WV-2..WV-6 — membership, definition, and the two branch-family verbs.
  # `sets` is the membership model's spelling of `projects`, which is kept
  # alongside it until the manifest repo is converted.
  "enable", "disable", "sets", "projects", "repos", "new", "switch",
  "publish-evidence",
  # RA-32 — the explicit lock-record repair. Never invoked implicitly.
  "migrate-locks",
  # Workspace-Membership-Model.md — the explicit local-state reconciliation.
  # Also runs automatically from the managed `post-merge` hook, so this
  # spelling exists to be re-run and dry-run rather than to be required.
  "migrate",
]

proc renderCompletionSnippet(shell, reproBin: string): string =
  ## Emit a static shell-completion script for the named shell. Like
  ## ``repro prompt init``: prints a snippet for the user to source; it
  ## NEVER edits an rc file or mutates shell state. The completion is a
  ## first-level command list (+ the ``workspace`` subcommand list) — enough
  ## to make the common verbs tab-completable without a per-keystroke
  ## ``repro`` subprocess.
  let topCmds = reproTopLevelCommands.join(" ")
  let wsSubs = reproWorkspaceSubcommands.join(" ")
  let lockingSubs = reproLockingSubcommands.join(" ")
  let cacheSubs = reproCacheSubcommands.join(" ")
  case shell
  of "bash":
    "# repro bash completion — add to ~/.bashrc:  source <(repro completion bash)\n" &
    "_repro_complete() {\n" &
    "  local cur prev\n" &
    "  cur=\"${COMP_WORDS[COMP_CWORD]}\"\n" &
    "  prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n" &
    "  if [[ $COMP_CWORD -eq 1 ]]; then\n" &
    "    COMPREPLY=( $(compgen -W \"" & topCmds & "\" -- \"$cur\") )\n" &
    "    return\n" &
    "  fi\n" &
    "  if [[ ( ${COMP_WORDS[1]} == workspace || ${COMP_WORDS[1]} == ws ) && $COMP_CWORD -eq 2 ]]; then\n" &
    "    COMPREPLY=( $(compgen -W \"" & wsSubs & "\" -- \"$cur\") )\n" &
    "    return\n" &
    "  fi\n" &
    "  if [[ ${COMP_WORDS[1]} == locking && $COMP_CWORD -eq 2 ]]; then\n" &
    "    COMPREPLY=( $(compgen -W \"" & lockingSubs & "\" -- \"$cur\") )\n" &
    "    return\n" &
    "  fi\n" &
    "  if [[ ${COMP_WORDS[1]} == cache && $COMP_CWORD -eq 2 ]]; then\n" &
    "    COMPREPLY=( $(compgen -W \"" & cacheSubs & "\" -- \"$cur\") )\n" &
    "    return\n" &
    "  fi\n" &
    "}\n" &
    "complete -F _repro_complete repro\n"
  of "zsh":
    "# repro zsh completion — add to ~/.zshrc:  source <(repro completion zsh)\n" &
    "_repro() {\n" &
    "  local -a cmds wscmds lockingcmds cachecmds\n" &
    "  cmds=(" & topCmds & ")\n" &
    "  wscmds=(" & wsSubs & ")\n" &
    "  lockingcmds=(" & lockingSubs & ")\n" &
    "  cachecmds=(" & cacheSubs & ")\n" &
    "  if (( CURRENT == 2 )); then\n" &
    "    compadd -- $cmds\n" &
    "  elif [[ ( ${words[2]} == workspace || ${words[2]} == ws ) && CURRENT == 3 ]]; then\n" &
    "    compadd -- $wscmds\n" &
    "  elif [[ ${words[2]} == locking && CURRENT == 3 ]]; then\n" &
    "    compadd -- $lockingcmds\n" &
    "  elif [[ ${words[2]} == cache && CURRENT == 3 ]]; then\n" &
    "    compadd -- $cachecmds\n" &
    "  fi\n" &
    "}\n" &
    "compdef _repro repro\n"
  of "fish":
    "# repro fish completion — add to ~/.config/fish/config.fish:\n" &
    "#   repro completion fish | source\n" &
    "complete -c repro -f\n" &
    "complete -c repro -n \"__fish_use_subcommand\" -a \"" & topCmds & "\"\n" &
    "complete -c repro -n \"__fish_seen_subcommand_from workspace ws\" -a \"" &
      wsSubs & "\"\n" &
    "complete -c repro -n \"__fish_seen_subcommand_from locking\" -a \"" &
      lockingSubs & "\"\n" &
    "complete -c repro -n \"__fish_seen_subcommand_from cache\" -a \"" &
      cacheSubs & "\"\n"
  else:
    ""

proc renderCompletionUsage(programName: string): string =
  programName & " completion <bash|zsh|fish>"

proc runCompletionCommand*(programName: string; args: openArray[string];
                           reproBin: string): int =
  ## ``repro completion <shell>`` — print a tab-completion script for the
  ## named shell. Opt-in and side-effect-free: it only prints a snippet for
  ## the user to ``source``.
  if args.len == 0 or args[0] in ["--help", "-h", "help"]:
    echo renderCompletionUsage(programName)
    return (if args.len == 0: 2 else: 0)
  let shell = args[0].toLowerAscii()
  let snippet = renderCompletionSnippet(shell, reproBin)
  if snippet.len == 0:
    stderr.writeLine("repro completion: unsupported shell '" & args[0] &
      "'\n" & renderCompletionUsage(programName))
    return 2
  stdout.write(snippet)
  0

# ---- WV-3 / WV-4: `repro workspace projects|repos <list|add|remove>` --------

proc gitOutput(gitBin, repoRoot: string; sub: openArray[string]): tuple[
    code: int; output: string] =
  var argv = @[gitBin, "-C", repoRoot]
  for a in sub: argv.add(a)
  let res = execCmdEx(quoteShellCommand(argv))
  (code: res.exitCode, output: res.output)

proc manifestRepoRootFor(workspaceRoot: string): string =
  ## The membership manifest repo carrying ``projects/*.toml`` — the native
  ## ``<org>/repro-workspace`` repo at the workspace root, where
  ## ``repro workspace projects add`` / ``repos add`` write and commit new
  ## membership. (The lock-store DB is a separate concern under ``.repro/``.)
  workspaceRoot

type
  RemoteRevisionState = enum
    ## Outcome of asking a remote whether a revision exists.
    rrsOk       ## the remote advertises the ref (or it is a full commit id)
    rrsMissing  ## the remote answered, and the ref is NOT there
    rrsUnknown  ## the remote could not be asked (offline, auth, no git)

proc remoteRevisionState(gitBin, remoteUrl, revision: string): tuple[
    state: RemoteRevisionState; diagnostic: string] =
  ## Ask the remote whether `revision` resolves, via `git ls-remote`. Used to
  ## validate a revision the caller supplied rather than writing it into a
  ## manifest unchecked: a manifest that pins a non-existent branch resolves
  ## fine at authoring time and fails for everyone at sync time.
  if revision.len == 0:
    return (rrsUnknown, "empty revision")
  # A full commit id is not advertised by `ls-remote` in the general case
  # (only tips are), so it cannot be refuted this way — accept it.
  if revision.len == 40 and revision.allCharsInSet(HexDigits):
    return (rrsOk, "")
  if gitBin.len == 0:
    return (rrsUnknown, "no git binary")
  # Never let a credential prompt block manifest authoring.
  putEnv("GIT_TERMINAL_PROMPT", "0")
  let res = execCmdEx(quoteShellCommand(
    [gitBin, "ls-remote", "--heads", "--tags", remoteUrl, revision]))
  if res.exitCode != 0:
    return (rrsUnknown, res.output.strip())
  for line in res.output.splitLines():
    let trimmed = line.strip()
    if trimmed.len == 0: continue
    if trimmed.endsWith("refs/heads/" & revision) or
       trimmed.endsWith("refs/tags/" & revision) or
       trimmed.endsWith("refs/tags/" & revision & "^{}"):
      return (rrsOk, "")
  (rrsMissing, "")

type
  MembershipSeed = object
    ## What a template contributes to a freshly scaffolded set: the same two
    ## membership keys the set itself carries, so what is seeded reads as the
    ## thing it produces.
    memberSets: seq[string]
    memberRepos: seq[string]

proc renderMemberArray(key: string; members: openArray[string]): string =
  ## One membership array, one entry per line — the shape `editSetMember`
  ## expects to find later, so a seeded set stays editable by the same CLI that
  ## created it.
  result = key & " = [\n"
  for m in members:
    result.add("  \"" & m & "\",\n")
  result.add("]\n")

proc projectManifestStub(project: string; seed: MembershipSeed): string =
  ## A NEW project has no remotes yet, so the stub carries none.
  ##
  ## The membership arrays are written BEFORE the `[project]` table, and the
  ## order is load-bearing rather than stylistic: a bare `member_sets = [ … ]`
  ## written AFTER `[project]` is standard-TOML-bound to that table, the strict
  ## decode then rejects `project.member_sets`, and the file stops parsing.
  ## (The old `includes` array had the same problem and was simply omitted from
  ## the stub; a template has content to place, so it is placed where it
  ## parses. Verified against the pinned reader in both orders.)
  ##
  ## Both keys are written whenever a template applies, even when it seeds only
  ## one, because which one an entry belongs in is the whole point:
  ## `member_sets` and `member_repos` are two NAMESPACES, and a file carrying
  ## only one would invite the next entry into whichever happened to be there.
  ##
  ## No `default_revision`. The model removes it: revision is lock territory,
  ## and the value it carried was org branching policy restated once per
  ## project. A stub that keeps emitting it re-seeds, into every project
  ## authored from now on, exactly the field a manifest conversion has just
  ## finished deleting — and the next conversion would have to delete it again.
  ## The reader still ACCEPTS the key, so manifests that predate the conversion
  ## keep parsing; what stops is this tool authoring new ones.
  ##
  ## `trunk` stays. It is not the same kind of field: it is live data with no
  ## other declaration site, selecting the workspace branch for `repro branch`,
  ## `repro switch` and `workspace init`.
  let membership =
    if seed.memberSets.len > 0 or seed.memberRepos.len > 0:
      renderMemberArray("member_sets", seed.memberSets) & "\n" &
      renderMemberArray("member_repos", seed.memberRepos) & "\n"
    else:
      ""
  "schema = \"reprobuild.workspace.project.v1\"\n\n" &
  membership &
  "[project]\n" &
  "name = \"" & project & "\"\n" &
  "trunk = \"main\"\n"

proc repoSetManifestStub(name: string; seed: MembershipSeed): string =
  ## Workspace-Membership-Model.md — a NEW repo-set: a name and an empty
  ## membership list, and nothing else. There is no `default_revision` and no
  ## `default_remote` to stub, deliberately: a set that carried them would make
  ## a member resolve differently depending on who referenced it, and a repo
  ## fragment fully determining its own checkout is the invariant that makes it
  ## portable between workspaces.
  ##
  ## Unlike `projectManifestStub`, the membership arrays ARE written out. A
  ## repo-set manifest has no array-of-tables for a bare key to attach itself
  ## to, so the "written after `[[remote]]` and read as a field of the last
  ## remote" trap that forced the project stub to omit `includes` cannot arise
  ## here — verified against the pinned reader in both key orders.
  ##
  ## Both keys are stubbed even though a new set has neither, because which one
  ## an entry belongs in is the whole point: `member_sets` and `member_repos`
  ## are two NAMESPACES, and a stub carrying only one would invite the next
  ## entry into whichever happened to be there. A template seeds those same two
  ## arrays; an empty seed leaves them empty, which is the pre-template stub
  ## byte for byte.
  "schema = \"reprobuild.workspace.repo-set.v1\"\n\n" &
  "[repo-set]\n" &
  "name = \"" & name & "\"\n\n" &
  renderMemberArray("member_sets", seed.memberSets) & "\n" &
  renderMemberArray("member_repos", seed.memberRepos)

proc commitAndPushManifest(identity: GitToolIdentity;
                           gitBin, manifestRoot, message: string;
                           paths: openArray[string]): tuple[
    code: int; diagnostic: string] =
  ## Stage ``paths``, commit with ``message``, and push ``HEAD`` to the
  ## manifest repo's upstream when one is configured. Best-effort push: the
  ## commit always lands locally; a missing upstream is reported, not fatal.
  ##
  ## The stage below is deliberately NOT forced: these are operator-AUTHORED
  ## manifest sources (``projects/<name>.toml``, its sibling description,
  ## ``repos/<repo>.toml``), so an ignore rule the operator arranged over their
  ## own sources must fail loudly rather than be quietly overridden.
  ##
  ## The checkout-ROOT guard is a SEPARATE question and applies here all the
  ## same, because it decides WHICH repository the stage/commit/push act on.
  ## Git's discovery walks upwards, so with ``manifestRoot`` a plain directory
  ## nested inside a checkout, ``git -C <manifestRoot> add -- projects/x.toml``
  ## succeeds against the ENCLOSING repository (no ignore involved — these are
  ## ordinary new files), ``git commit`` writes a commit there, and ``git
  ## push`` publishes that repo's branch. Not forcing is no protection against
  ## that; only asking whether the root IS a checkout is.
  let discovery = discoverGitWorktree(identity, manifestRoot)
  if not discovery.ok:
    return (code: 1, diagnostic: "manifest repo root '" & manifestRoot &
      "' is not a git checkout; refusing to commit manifest changes" &
      (if discovery.diagnostic.len > 0: " (" & discovery.diagnostic & ")"
       else: ""))
  for p in paths:
    let st = gitOutput(gitBin, manifestRoot, ["add", "--", p])
    if st.code != 0:
      return (code: st.code, diagnostic: "git add failed: " & st.output)
  let ci = gitOutput(gitBin, manifestRoot, ["commit", "-m", message])
  if ci.code != 0:
    return (code: ci.code, diagnostic: "git commit failed: " & ci.output)
  # Resolve the upstream from @{u}; push only when configured.
  let up = gitOutput(gitBin, manifestRoot,
    ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"])
  if up.code != 0:
    return (code: 0, diagnostic: "committed locally; no upstream configured " &
      "for the manifest repo (skipped push)")
  let upstream = up.output.strip()
  let slash = upstream.find('/')
  if slash <= 0:
    return (code: 0, diagnostic: "committed locally; upstream '" & upstream &
      "' is not a remote/branch pair (skipped push)")
  let remote = upstream[0 ..< slash]
  let branch = upstream[slash + 1 .. ^1]
  let push = gitOutput(gitBin, manifestRoot,
    ["push", remote, "HEAD:" & branch])
  if push.code != 0:
    return (code: push.code, diagnostic: "git push failed: " & push.output)
  (code: 0, diagnostic: "committed and pushed to " & upstream)

proc removeFragmentInclude(projectFile, includePath: string): bool =
  ## Drop ``"<includePath>",`` from the project's ``includes = [ … ]`` array.
  ## Returns true when an entry was removed; false when none was present
  ## (idempotent, the mirror of ``appendFragmentInclude``).
  let content = readFile(projectFile)
  let quoted = "\"" & includePath & "\""
  if quoted notin content:
    return false
  var outLines: seq[string]
  var removed = false
  for line in content.splitLines():
    if line.strip().startsWith(quoted):
      removed = true
      continue
    outLines.add(line)
  if not removed:
    return false
  writeFile(projectFile, outLines.join("\n"))
  true

proc projectFilesUnder(manifestRoot: string): seq[string] =
  ## Absolute paths of every ``projects/*.toml`` under the manifest root,
  ## sorted by project name.
  let dir = manifestRoot / "projects"
  if not dirExists(dir):
    return @[]
  for kind, path in walkDir(dir):
    if kind in {pcFile, pcLinkToFile} and path.splitFile.ext == ".toml":
      result.add(path)
  sort(result)

proc repoSetFilesUnder(manifestRoot: string): seq[string] =
  ## Absolute paths of every ``repo-sets/*.toml`` under the manifest root,
  ## sorted by set name. Empty for an unconverted manifest repo.
  let dir = manifestRoot / "repo-sets"
  if not dirExists(dir):
    return @[]
  for kind, path in walkDir(dir):
    if kind in {pcFile, pcLinkToFile} and path.splitFile.ext == ".toml":
      result.add(path)
  sort(result)

type
  MembershipKind = enum
    ## Which file kind a membership name resolves to. The distinction exists
    ## only where the two are AUTHORED differently — a repo-set names members,
    ## a project lists include paths and carries a remote table. Everywhere
    ## else (listing, enabling, resolving) they are one namespace.
    mkRepoSet
    mkProject

  MembershipFile = object
    name: string
    kind: MembershipKind
    abs: string
    rel: string    ## manifest-root-relative, for git staging and messages

proc membershipFileFor(manifestRoot, name: string): MembershipFile =
  ## The `repo-sets/<name>.toml` or `projects/<name>.toml` that DEFINES
  ## `name`, or a record with an empty `abs` when neither exists.
  ##
  ## `repo-sets/` is consulted first because it is the model's one file kind;
  ## `projects/` remains because the manifest repo is not converted, and while
  ## it is not, a name that exists only there has to keep resolving.
  let setAbs = manifestRoot / "repo-sets" / (name & ".toml")
  if fileExists(setAbs):
    return MembershipFile(name: name, kind: mkRepoSet, abs: setAbs,
      rel: "repo-sets/" & name & ".toml")
  let projectAbs = manifestRoot / "projects" / (name & ".toml")
  if fileExists(projectAbs):
    return MembershipFile(name: name, kind: mkProject, abs: projectAbs,
      rel: "projects/" & name & ".toml")
  MembershipFile(name: name, kind: mkRepoSet, abs: "",
    rel: "repo-sets/" & name & ".toml")

const
  memberSetsKey = "member_sets"
  memberReposKey = "member_repos"

proc membershipKeyFor(manifestRoot, name: string): string =
  ## Which membership key a name belongs under — ``member_repos`` when
  ## ``repos/<name>.toml`` defines it, ``member_sets`` when
  ## ``repo-sets/<name>.toml`` does, and "" when NEITHER does.
  ##
  ## The key is read off what the name actually resolves to rather than
  ## inferred from the verb, because the two keys are two namespaces and
  ## putting a name in the wrong one makes it resolve to nothing (or, worse,
  ## to a different thing that happens to share the name — 7 of the 11
  ## projects in the metacraft manifest repo have a set and a repo with the
  ## same name). A caller that gets "" must fail rather than pick: guessing is
  ## how a name ends up in the key that silently means something else.
  if fileExists(manifestRoot / "repos" / (name & ".toml")):
    return memberReposKey
  if fileExists(manifestRoot / "repo-sets" / (name & ".toml")):
    return memberSetsKey
  ""

proc editSetMember(setFile, key, member: string; add: bool): bool =
  ## Add or drop ``"<member>",`` in the named membership array of a repo-set.
  ## Returns true when the file changed, false when it already said what was
  ## asked (idempotent) — the two-key mirror of ``appendFragmentInclude`` /
  ## ``removeFragmentInclude``.
  ##
  ## The array is located by its KEY rather than by "the next line that is a
  ## lone ``]``": a repo-set carries two arrays, so the positional rule the
  ## include helpers can afford would put half the entries in the wrong
  ## namespace.
  let content = readFile(setFile)
  let quoted = "\"" & member & "\""
  var lines = content.splitLines()
  var arrayStart = -1
  for idx, line in lines:
    let stripped = line.strip()
    if stripped.startsWith(key) and stripped.endsWith("["):
      arrayStart = idx
      break
  var arrayEnd = -1
  if arrayStart >= 0:
    for idx in arrayStart + 1 ..< lines.len:
      if lines[idx].strip() == "]":
        arrayEnd = idx
        break

  if add:
    if arrayStart >= 0 and arrayEnd >= 0:
      for idx in arrayStart + 1 ..< arrayEnd:
        if lines[idx].strip().startsWith(quoted):
          return false
      lines.insert("  " & quoted & ",", arrayEnd)
      writeFile(setFile, lines.join("\n"))
      return true
    # No such array yet — append a fresh one rather than guessing that the
    # other key's array was meant.
    lines.add("")
    lines.add(key & " = [")
    lines.add("  " & quoted & ",")
    lines.add("]")
    writeFile(setFile, lines.join("\n"))
    return true

  if arrayStart < 0 or arrayEnd < 0:
    return false
  var outLines: seq[string]
  var removed = false
  for idx, line in lines:
    if idx > arrayStart and idx < arrayEnd and
        line.strip().startsWith(quoted):
      removed = true
      continue
    outLines.add(line)
  if not removed:
    return false
  writeFile(setFile, outLines.join("\n"))
  true

proc projectsIncludingFragment(manifestRoot, fragmentRel: string): seq[string] =
  ## Which projects carry an ``includes`` edge to ``fragmentRel``. This is the
  ## authority for "is this fragment still referenced" — the question both
  ## `sets remove --prune-orphan-repos` and `repos remove --delete-fragment`
  ## have to answer before deleting a shared declaration.
  for file in projectFilesUnder(manifestRoot):
    var manifest: ProjectManifest
    try:
      manifest = readProjectManifest(file)
    except CatchableError:
      # An unreadable manifest cannot be proven NOT to reference the fragment,
      # so fall back to a textual probe rather than reporting a false orphan.
      if ("\"" & fragmentRel & "\"") in readFile(file):
        result.add(file.splitFile.name)
      continue
    if fragmentRel in manifest.includes:
      result.add(file.splitFile.name)

proc membershipsDeclaringRepo(manifestRoot, repoName: string): seq[string] =
  ## Every repo-set OR project that declares the repo named `repoName` — by
  ## `members` name or by `includes` path.
  ##
  ## The two spellings have to be asked TOGETHER. Half-converted, a fragment
  ## can be referenced from a repo-set by name and from a project by path at
  ## the same time, and answering "is anything still referencing this" from
  ## only one of them is how a `--delete-fragment` deletes a declaration
  ## something still needs.
  let fragmentRel = "repos/" & repoName & ".toml"
  result = projectsIncludingFragment(manifestRoot, fragmentRel)
  for file in repoSetFilesUnder(manifestRoot):
    var manifest: RepoSetManifest
    try:
      manifest = readRepoSet(file)
    except CatchableError:
      if ("\"" & repoName & "\"") in readFile(file):
        result.add(file.splitFile.name)
      continue
    # Only `member_repos` is consulted. `member_sets` is a different NAMESPACE:
    # a set may legitimately carry the same name as this repo (7 of the 11
    # projects in the metacraft manifest repo do), and counting that as a
    # reference would report a fragment as still-declared by a set that names
    # a set.
    if repoName in manifest.member_repos and file.splitFile.name notin result:
      result.add(file.splitFile.name)

proc validateFragmentPath(value: string): string =
  ## Diagnostic for a rejected ``--path``, or "" when it is usable. The value
  ## places a working tree on every machine that later syncs the project, so it
  ## is checked here rather than at sync time on someone else's laptop.
  if value.len == 0:
    return "--path may not be empty"
  if isAbsolute(value) or (value.len >= 2 and value[1] == ':'):
    return "--path must be relative, got '" & value & "'"
  if '\\' in value:
    return "--path must use forward slashes, got '" & value & "'"
  for segment in value.split('/'):
    if segment == "..":
      return "--path may not contain a '..' segment, got '" & value & "'"
  ""

proc runWorkspaceSetsCommand*(args: openArray[string];
                              spelling = "sets"): int =
  ## ``repro workspace sets list|add|remove`` — the DEFINITION axis for repo
  ## sets. `add` / `remove` write, commit and push to the manifest repo;
  ## `list` is read-only.
  ##
  ## Enabling a set in this workspace is `enable` / `disable`; see
  ## `reprobuild-specs/CLI/workspace.md` §"The Two Axes".
  ##
  ## `spelling` is the verb the operator actually typed. `repro ws projects …`
  ## is retained as an alias while the manifest repo is unconverted, and it is
  ## not merely a rename: `sets add` scaffolds a `repo-sets/<name>.toml`, while
  ## `projects add` keeps scaffolding a `projects/<name>.toml`, so the alias
  ## keeps doing exactly what it did rather than quietly converting a repo one
  ## file at a time. Every other operation — listing, removing, resolving —
  ## treats the two directories as ONE namespace, which is the model's claim
  ## that "project" was a role and not a kind.
  let verb = "repro workspace " & spelling
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo verb & " list [--enabled|--disabled|--all] [--json]"
    echo verb & " add <name> [--template=NAME|--no-template] [-m DESC]"
    echo verb & " remove <name> [--prune-orphan-repos]"
    echo "  list   every DEFINED repo-set, marked enabled/disabled for this " &
      "workspace."
    echo "  add    define a NEW " &
      (if spelling == "sets": "repo-set (repo-sets/<name>.toml)"
       else: "project (projects/<name>.toml)") &
      ". To activate an existing one, use `repro ws enable <name>`."
    echo "  --template=NAME  scaffold from templates/<NAME>.toml. Without it, " &
      "the host config's [projects] default_template applies — and is " &
      "REPORTED when it does."
    echo "  --no-template    opt out of that default and write the empty stub."
    echo "  remove delete the definition. Disable it here first."
    return 0
  let sub = if args.len > 0 and not args[0].startsWith("-"): args[0] else: "list"
  let rest = if args.len > 0 and not args[0].startsWith("-"): args[1 .. ^1]
             else: @(args)
  let workspaceRoot = parseProjectsWorkspaceRoot(args)

  if sub == "list":
    var wantEnabled = false
    var wantDisabled = false
    var asJson = false
    for arg in rest:
      case arg
      of "--enabled": wantEnabled = true
      of "--disabled": wantDisabled = true
      of "--all": wantEnabled = false; wantDisabled = false
      of "--json": asJson = true
      else:
        if arg.startsWith("--workspace-root="):
          discard
        elif arg.startsWith("-"):
          stderr.writeLine(verb & " list: unknown flag " & arg)
          return 2
    let active = readWorkspaceProjects(workspaceRoot)
    let defined = definedProjectNames(workspaceRoot)
    # Ordering is meaning, not cosmetics: the primary project answers "what am
    # I working on" and is the one every single-project resolver falls back to,
    # so it leads, followed by the rest of the active set in membership order,
    # then everything else alphabetically.
    var ordered: seq[string]
    for p in active:
      if p notin ordered:
        ordered.add(p)
    for p in defined:
      if p notin ordered:
        ordered.add(p)
    var rows: seq[tuple[name: string; enabled: bool; defined: bool]]
    for name in ordered:
      let enabled = name in active
      if wantEnabled and not enabled: continue
      if wantDisabled and enabled: continue
      rows.add((name: name, enabled: enabled, defined: name in defined))
    if asJson:
      var arr = newJArray()
      for r in rows:
        arr.add(%*{"name": r.name, "enabled": r.enabled, "defined": r.defined})
      # The machine surface names what the model has: repo-sets. "Project" was
      # a ROLE a set plays when it is enabled, not a kind, so a schema keyed on
      # it described a distinction that does not exist. Renaming the schema
      # STRING (rather than only the array key) is deliberate: a consumer that
      # keys off the schema breaks loudly on the shape change instead of
      # reading a `sets` payload as though it were the old `projects` one.
      echo (%*{"schema": "reprobuild.workspace-sets-list.v1",
               "workspaceRoot": workspaceRoot,
               "primary": (if active.len > 0: active[0] else: ""),
               "sets": arr}).pretty
      return 0
    for r in rows:
      var line = r.name & "\t" & (if r.enabled: "enabled" else: "disabled")
      # A name in the active set that no manifest layer defines is a broken
      # membership record, not a project. Say so on its own row rather than
      # letting it read as an ordinary enabled project.
      if not r.defined:
        line.add("\tUNDEFINED (no manifest declares it)")
      stdout.writeLine(line)
    return 0

  let manifestRoot = manifestRepoRootFor(workspaceRoot)
  if not dirExists(manifestRoot):
    stderr.writeLine(verb & ": no manifest repo at " &
      manifestRoot & " (run `repro workspace init` first)")
    return 1
  let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
  let gitBin = identity.binaryPath
  # Which directory `add` scaffolds into. `remove` and `list` do not consult
  # this: they take whichever file DEFINES the name (`membershipFileFor`), so
  # a set defined either way is removable by either spelling.
  let addDir = if spelling == "sets": "repo-sets" else: "projects"

  case sub
  of "add":
    var name = ""
    var desc = ""
    var requestedTemplate = ""
    var noTemplate = false
    var i = 0
    while i < rest.len:
      let a = rest[i]
      if a == "-m" or a == "--message":
        if i + 1 < rest.len:
          desc = rest[i + 1]; inc i
      elif a.startsWith("--message="):
        desc = a["--message=".len .. ^1]
      elif a.startsWith("--template="):
        requestedTemplate = a["--template=".len .. ^1]
      elif a == "--no-template":
        noTemplate = true
      elif a.startsWith("--workspace-root="):
        discard
      elif a.startsWith("-"):
        stderr.writeLine(verb & " add: unknown flag " & a)
        return 2
      else:
        name = a
      inc i
    if name.len == 0:
      stderr.writeLine(verb & " add: missing <name>")
      return 2
    # Naming a template and opting out of templates in one invocation is a
    # contradiction, and picking a winner would make one of the two flags a
    # no-op the operator never sees. Refuse instead.
    if requestedTemplate.len > 0 and noTemplate:
      stderr.writeLine(verb & " add: --template=" & requestedTemplate &
        " and --no-template contradict each other")
      return 2
    # The guard consults BOTH directories even though only one is scaffolded
    # into: `sets add codetracer` in a repo whose `projects/codetracer.toml`
    # exists must not create a second definition of the same name, because the
    # two are one namespace to every reader.
    let existing = membershipFileFor(manifestRoot, name)
    if existing.abs.len > 0:
      # The one guard the axis split needs. This spelling did not disappear, it
      # changed meaning, so it cannot fail as an unknown subcommand — and an
      # operator reaching for the old "activate this" sense lands here.
      stderr.writeLine(verb & " add: '" & name &
        "' already exists at " & existing.abs)
      stderr.writeLine("  `" & spelling & " add` DEFINES a new one. To " &
        "activate this in this workspace: repro ws enable " & name)
      return 1
    # ---- template resolution ------------------------------------------------
    #
    # Templates exist because an empty stub makes every new set hand-list
    # whatever the last one had. A default that applied INVISIBLY would
    # reproduce exactly that defect one level up — the operator would again not
    # know what their set contains or why — so the default is reported on every
    # application, and `--no-template` is how you decline it.
    var templateName = requestedTemplate
    var templateSource = "--template"
    if templateName.len == 0 and not noTemplate:
      templateName = readDefaultTemplateFromHostConfig(workspaceRoot)
      templateSource = bootstrapConfigFileName & " [projects] default_template"
    var seed = MembershipSeed()
    if templateName.len > 0:
      let templateRel = "templates/" & templateName & ".toml"
      let templateAbs = manifestRoot / templateRel
      if not fileExists(templateAbs):
        # Loud in BOTH directions. An explicit `--template=` naming nothing is
        # obviously an error; a configured default naming nothing is the more
        # dangerous one, because silently falling back to the empty stub is
        # indistinguishable from the template having been applied.
        stderr.writeLine(verb & " add: template '" & templateName &
          "' (from " & templateSource & ") does not exist at " & templateAbs)
        if requestedTemplate.len == 0:
          stderr.writeLine("  fix the host config, or pass --no-template to " &
            "scaffold without one")
        return 1
      var loaded: TemplateManifest
      try:
        loaded = readTemplate(templateAbs)
      except CatchableError as exc:
        stderr.writeLine(verb & " add: cannot read " & templateRel & ": " &
          exc.msg)
        return 1
      seed.memberSets = loaded.member_sets
      seed.memberRepos = loaded.member_repos
    createDir(manifestRoot / addDir)
    let fileRel = addDir & "/" & name & ".toml"
    let fileAbs = manifestRoot / addDir / (name & ".toml")
    writeFile(fileAbs,
      if addDir == "repo-sets": repoSetManifestStub(name, seed)
      else: projectManifestStub(name, seed))
    var paths = @[fileRel]
    if desc.len > 0:
      let docRel = addDir & "/" & name & ".md"
      writeFile(manifestRoot / addDir / (name & ".md"),
        "# " & name & "\n\n" & desc & "\n")
      paths.add(docRel)
    let msg = "Add " & (if addDir == "repo-sets": "repo-set " else: "project ") &
      name & (if desc.len > 0: " (" & desc & ")" else: "") &
      (if templateName.len > 0: " from template " & templateName else: "")
    let res = commitAndPushManifest(identity, gitBin, manifestRoot, msg, paths)
    stdout.writeLine(verb & " add: " & name & " — " & res.diagnostic)
    if templateName.len > 0:
      # The reported line names the template AND where the choice came from, so
      # "why does my new set contain these" is answerable from the transcript
      # rather than by reading the org config.
      stdout.writeLine(verb & " add: applied template '" & templateName &
        "' (from " & templateSource & ") — seeded " &
        $seed.memberSets.len & " member_sets, " &
        $seed.memberRepos.len & " member_repos")
    stdout.writeLine(verb & " add: defined, not enabled — " &
      "`repro ws repos add <repo> --" &
      (if addDir == "repo-sets": "set=" else: "project=") & name &
      "` to give it repos, `repro ws enable " & name &
      "` to activate it here")
    return res.code
  of "remove":
    var name = ""
    var pruneOrphans = false
    for a in rest:
      if a == "--prune-orphan-repos":
        pruneOrphans = true
      elif a.startsWith("--workspace-root="):
        discard
      elif a.startsWith("-"):
        stderr.writeLine(verb & " remove: unknown flag " & a)
        return 2
      else:
        name = a
    if name.len == 0:
      stderr.writeLine(verb & " remove: missing <name>")
      return 2
    let target = membershipFileFor(manifestRoot, name)
    if target.abs.len == 0:
      stderr.writeLine(verb & " remove: '" & name &
        "' does not exist (looked for " &
        (manifestRoot / "repo-sets" / (name & ".toml")) & " and " &
        (manifestRoot / "projects" / (name & ".toml")) & ")")
      return 1
    # Removing the definition under a live membership record leaves a set entry
    # no manifest layer can resolve, which breaks every subsequent workspace
    # command. The operator has to sequence it; we will not silently disable on
    # their behalf, because that would delete checkouts as a side effect of a
    # manifest edit.
    if name in readWorkspaceProjects(workspaceRoot):
      stderr.writeLine(verb & " remove: '" & name &
        "' is enabled in this workspace")
      stderr.writeLine("  run `repro ws disable " & name & "` first, then " &
        "remove the definition")
      return 2
    # What this definition referenced, as `repos/<r>.toml` paths regardless of
    # which spelling it used to reference them — the orphan question is about
    # FRAGMENTS, and a member name and an include path name the same file.
    var referencedFragments: seq[string]
    try:
      case target.kind
      of mkProject:
        referencedFragments = readProjectManifest(target.abs).includes
      of mkRepoSet:
        # `member_repos` only: an entry under `member_sets` names a set, and a
        # set has no fragment to orphan even when a repo shares its name.
        for member in readRepoSet(target.abs).member_repos:
          if fileExists(manifestRoot / "repos" / (member & ".toml")):
            referencedFragments.add("repos/" & member & ".toml")
    except CatchableError as exc:
      stderr.writeLine(verb & " remove: warning: cannot read " & target.abs &
        " (" & exc.msg & "); removing it without an orphan report")
    var paths = @[target.rel]
    removeFile(target.abs)
    let docRel = target.rel.changeFileExt("md")
    if fileExists(manifestRoot / docRel):
      removeFile(manifestRoot / docRel)
      paths.add(docRel)
    # Now that the definition is gone, anything it alone referenced is an
    # orphan. A fragment is a REUSABLE declaration, so the default is to leave
    # it: another set may adopt it tomorrow, and deleting it would make that a
    # re-authoring job rather than one member line.
    var orphans: seq[string]
    for fragmentRel in referencedFragments:
      let repoName = fragmentRel.splitFile.name
      if membershipsDeclaringRepo(manifestRoot, repoName).len == 0:
        orphans.add(fragmentRel)
    if pruneOrphans:
      for fragmentRel in orphans:
        let abs = manifestRoot / fragmentRel
        if fileExists(abs):
          removeFile(abs)
          paths.add(fragmentRel)
        let fragmentDocRel = fragmentRel.changeFileExt("md")
        if fileExists(manifestRoot / fragmentDocRel):
          removeFile(manifestRoot / fragmentDocRel)
          paths.add(fragmentDocRel)
    let msg = "Remove " &
      (if target.kind == mkRepoSet: "repo-set " else: "project ") & name &
      (if pruneOrphans and orphans.len > 0:
         " (and " & $orphans.len & " orphaned repo fragment(s))"
       else: "")
    let res = commitAndPushManifest(identity, gitBin, manifestRoot, msg, paths)
    stdout.writeLine(verb & " remove: " & name & " — " & res.diagnostic)
    if orphans.len > 0:
      if pruneOrphans:
        stdout.writeLine(verb & " remove: pruned " & $orphans.len &
          " orphaned fragment(s): " & orphans.join(", "))
      else:
        stdout.writeLine(verb & " remove: " & $orphans.len &
          " fragment(s) are now unreferenced and were KEPT: " &
          orphans.join(", "))
        stdout.writeLine("  pass --prune-orphan-repos to delete them too")
    return res.code
  else:
    stderr.writeLine(verb & ": unknown subcommand '" & sub &
      "' (expected: list, add, remove)")
    return 2

proc runWorkspaceProjectsCommand*(args: openArray[string]): int =
  ## ``repro workspace projects …`` — the retained spelling of `sets`.
  ##
  ## Kept because the manifest repo still carries `projects/*.toml`, and a verb
  ## that named the thing an operator is looking at cannot fail as unknown
  ## while that is true. It is retired from the docs, not from the CLI, and it
  ## is removed with the third migration step rather than the second.
  runWorkspaceSetsCommand(args, "projects")

proc runWorkspaceReposCommand*(args: openArray[string]): int =
  ## ``repro workspace repos list|add|remove`` — the DEFINITION axis for repos:
  ## the fragments under ``repos/`` and the membership edges that wire them
  ## into repo-sets (``members``) or projects (``includes``).
  ##
  ## A repo fragment is declared ONCE and named by any number of sets, which is
  ## precisely what keeps two sets from conflicting over a checkout path
  ## (`resolver.nim`'s dedup-by-path rule). That is why the target is a
  ## repeatable flag here rather than a positional implying exactly one.
  if args.len > 0 and args[0] in ["--help", "-h", "help"]:
    echo "repro workspace repos list [--set=NAME|--project=NAME] " &
      "[--enabled|--disabled|--all] [--json]"
    echo "repro workspace repos add <repo> --remote=URL --branch=B " &
      "[--set=NAME|--project=NAME]... [--revision=REV] " &
      "[--path=DIR] [-m DESC]"
    echo "repro workspace repos remove <repo> " &
      "[--set=NAME|--project=NAME]... [--delete-fragment]"
    echo "  --set          repeatable; the repo-set to name the repo in. " &
      "Defaults to this workspace's primary set."
    echo "  --project      the retained spelling of --set, for a manifest " &
      "repo still carrying projects/<name>.toml."
    echo "  --remote=URL   reuses the matching url-prefix (or, for a project " &
      "target, the matching [[remote]]) when one already serves that URL; " &
      "otherwise adds one org-named prefix."
    echo "  --branch=B     REQUIRED when declaring a new repo: the branch " &
      "the fragment follows. Every fragment declares its own — there is no " &
      "workspace default and none is inferred, so nothing else determines " &
      "its checkout. Optional only when the fragment already exists, or " &
      "when --revision pins an exact commit instead."
    echo "  --revision=REV an exact commit this fragment sits at, validated " &
      "against the remote. Use alongside --branch (\"tracks B, sits at " &
      "REV\") for a vendored source tree. Ordinary repos take --branch " &
      "alone and let a lock record the commit."
    echo "  --path=DIR     checkout directory; defaults to <repo>."
    echo "  -m DESC        writes repos/<repo>.md, the source of the " &
      "generated project docs."
    return 0
  let sub = if args.len > 0 and not args[0].startsWith("-"): args[0] else: "list"
  let rest = if args.len > 0 and not args[0].startsWith("-"): args[1 .. ^1]
             else: @(args)
  let workspaceRoot = parseProjectsWorkspaceRoot(args)
  let manifestRoot = manifestRepoRootFor(workspaceRoot)
  if not dirExists(manifestRoot):
    stderr.writeLine("repro workspace repos: no manifest repo at " &
      manifestRoot & " (run `repro workspace init` first)")
    return 1

  if sub == "list":
    # ONE namespace, whichever flag spelling named it. `--project=` is the
    # retained spelling of `--set=`; the variable is named for the model rather
    # than for the older of the two words.
    var scopeSet = ""
    var wantEnabled = false
    var wantDisabled = false
    var asJson = false
    for arg in rest:
      if arg.startsWith("--project=") or arg.startsWith("--set="):
        scopeSet = arg[arg.find('=') + 1 .. ^1]
      elif arg == "--enabled": wantEnabled = true
      elif arg == "--disabled": wantDisabled = true
      elif arg == "--all": wantEnabled = false; wantDisabled = false
      elif arg == "--json": asJson = true
      elif arg.startsWith("--workspace-root="):
        discard
      elif arg.startsWith("-"):
        stderr.writeLine("repro workspace repos list: unknown flag " & arg)
        return 2
    let active = readWorkspaceProjects(workspaceRoot)
    # "enabled" for a repo means "declared by at least one enabled project" —
    # i.e. it is part of this workspace's participating set. Computed from the
    # resolved set rather than from the fragment, because a fragment says
    # nothing about who includes it.
    var enabledPaths: seq[string]
    if active.len > 0:
      try:
        enabledPaths = projectSetRepoPaths(workspaceRoot, active)
      except CatchableError:
        discard
    var scopePaths: seq[string]
    if scopeSet.len > 0:
      try:
        scopePaths = projectSetRepoPaths(workspaceRoot, @[scopeSet])
      except CatchableError as err:
        stderr.writeLine("repro workspace repos list: cannot resolve " &
          "repo-set '" & scopeSet & "': " & err.msg)
        return 1
    let reposDir = manifestRoot / "repos"
    var files: seq[string]
    if dirExists(reposDir):
      for kind, path in walkDir(reposDir):
        if kind in {pcFile, pcLinkToFile} and path.splitFile.ext == ".toml":
          files.add(path)
    sort(files)
    var arr = newJArray()
    var lines: seq[string]
    for file in files:
      let fragmentName = file.splitFile.name
      var repoPath = fragmentName
      var remote = ""
      var revision = ""
      try:
        let m = readRepoFragment(file)
        repoPath = m.repo.path
        # Report whichever spelling the fragment actually uses, so a listing of
        # a half-converted manifest repo shows what is there rather than a
        # blank column for every converted fragment.
        remote = m.repo.url_prefix.get(m.repo.remote.get(""))
        revision = m.repo.branch.get(m.repo.revision.get(""))
      except CatchableError:
        discard
      if scopeSet.len > 0 and repoPath notin scopePaths:
        continue
      let enabled = repoPath in enabledPaths
      if wantEnabled and not enabled: continue
      if wantDisabled and enabled: continue
      if asJson:
        arr.add(%*{"repo": fragmentName, "path": repoPath, "remote": remote,
                   "revision": revision, "enabled": enabled})
      else:
        lines.add(fragmentName & "\t" & repoPath & "\t" &
          (if remote.len > 0: remote else: "-") & "\t" &
          (if revision.len > 0: revision else: "(inherited)") & "\t" &
          (if enabled: "enabled" else: "disabled"))
    if asJson:
      # `set` rather than `project`: the scope flag accepts either spelling but
      # names ONE namespace, and reporting it under the retired word would make
      # the machine surface the last place the two look like different kinds.
      # The schema string moves with the payload so the break is loud.
      echo (%*{"schema": "reprobuild.workspace-set-repos-list.v1",
               "workspaceRoot": workspaceRoot,
               "set": scopeSet,
               "repos": arr}).pretty
    else:
      for line in lines:
        stdout.writeLine(line)
    return 0

  let identity = ensureGitToolResolvable(tpmPathOnly, getEnv("PATH"))
  let gitBin = identity.binaryPath

  var repo = ""
  var projects: seq[string]
  var remote = ""
  var revision = ""
  var branch = ""
  var checkoutPath = ""
  var desc = ""
  var deleteFragment = false
  var i = 0
  while i < rest.len:
    let a = rest[i]
    # `--set=` and `--project=` name the SAME namespace; which file backs the
    # name is `membershipFileFor`'s answer, not the operator's to state twice.
    if a.startsWith("--project=") or a.startsWith("--set="):
      let p = a[a.find('=') + 1 .. ^1]
      if p notin projects: projects.add(p)
    elif a.startsWith("--remote="):
      remote = a["--remote=".len .. ^1]
    elif a.startsWith("--revision="):
      revision = a["--revision=".len .. ^1]
    elif a.startsWith("--branch="):
      branch = a["--branch=".len .. ^1]
    elif a.startsWith("--path="):
      checkoutPath = a["--path=".len .. ^1]
    elif a == "--delete-fragment":
      deleteFragment = true
    elif a == "-m" or a == "--message":
      if i + 1 < rest.len:
        desc = rest[i + 1]; inc i
    elif a.startsWith("--message="):
      desc = a["--message=".len .. ^1]
    elif a.startsWith("--workspace-root="):
      discard
    elif a.startsWith("-"):
      stderr.writeLine("repro workspace repos " & sub & ": unknown flag " & a)
      return 2
    else:
      repo = a
    inc i
  if repo.len == 0:
    stderr.writeLine("repro workspace repos " & sub & ": missing <repo>")
    return 2

  let fragmentRel = "repos/" & repo & ".toml"
  let fragmentAbs = manifestRoot / "repos" / (repo & ".toml")

  case sub
  of "add":
    if remote.len == 0:
      stderr.writeLine("repro workspace repos add: --remote=URL is required")
      return 2
    if checkoutPath.len > 0:
      let pathError = validateFragmentPath(checkoutPath)
      if pathError.len > 0:
        stderr.writeLine("repro workspace repos add: " & pathError)
        return 2
    if projects.len == 0:
      # Default to the workspace's PRIMARY set — the same one every other
      # single-set verb falls back to, so `repos add` in a single-set
      # workspace needs no flag at all.
      let active = readWorkspaceProjects(workspaceRoot)
      if active.len == 0:
        stderr.writeLine("repro workspace repos add: no --set given and " &
          "this workspace has no active repo-set to default to")
        stderr.writeLine("  pass --set=<name> (repeatable)")
        return 2
      projects.add(active[0])
    var targets: seq[MembershipFile]
    for project in projects:
      let target = membershipFileFor(manifestRoot, project)
      if target.abs.len == 0:
        stderr.writeLine("repro workspace repos add: '" & project &
          "' does not exist (looked for " &
          (manifestRoot / "repo-sets" / (project & ".toml")) & " and " &
          (manifestRoot / "projects" / (project & ".toml")) & ")")
        return 1
      targets.add(target)
    # A fragment carries ONE spelling of where it comes from. A repo-set has no
    # `[[remote]]` table to reference and a project has no `url-prefixes/`
    # contract, so one `add` cannot satisfy both at once. Refusing is honest;
    # writing a fragment that half-resolves for one of the two targets is not.
    var hasSet = false
    var hasProject = false
    for target in targets:
      case target.kind
      of mkRepoSet: hasSet = true
      of mkProject: hasProject = true
    if hasSet and hasProject:
      stderr.writeLine("repro workspace repos add: the named targets mix a " &
        "repo-set and a project, and a fragment can only carry one of " &
        "`url_prefix` (repo-set) or `remote` (project)")
      stderr.writeLine("  run `repos add` once per kind, or convert the " &
        "project to a repo-set first")
      return 2

    let effectivePath = if checkoutPath.len > 0: checkoutPath else: repo
    # An EXISTING fragment is reused, never rewritten: other projects already
    # depend on its facts, and silently re-pointing a shared repo from a
    # command that reads like "add" is exactly the class of surprise the axis
    # split exists to remove.
    var fragmentExisted = fileExists(fragmentAbs)
    if fragmentExisted:
      var existing: RepoFragment
      try:
        existing = readRepoFragment(fragmentAbs)
      except CatchableError as exc:
        stderr.writeLine("repro workspace repos add: cannot read existing " &
          fragmentAbs & ": " & exc.msg)
        return 1
      var conflicts: seq[string]
      if checkoutPath.len > 0 and existing.repo.path != checkoutPath:
        conflicts.add("path (" & existing.repo.path & " vs " & checkoutPath & ")")
      if revision.len > 0 and existing.repo.revision.get("") != revision:
        conflicts.add("revision (" & existing.repo.revision.get("(inherited)") &
          " vs " & revision & ")")
      if branch.len > 0 and existing.repo.branch.get("") != branch:
        conflicts.add("branch (" & existing.repo.branch.get("(none)") &
          " vs " & branch & ")")
      if conflicts.len > 0:
        stderr.writeLine("repro workspace repos add: '" & repo &
          "' is already declared with different " & conflicts.join(", "))
        stderr.writeLine("  the fragment is shared; edit " & fragmentRel &
          " directly if the declaration itself should change")
        return 1

    # Workspace-Membership-Model.md — "every repo fragment declares its own
    # branch … written once per repo, by hand, when the repo is added". A NEW
    # fragment with neither `--branch` nor `--revision` would declare neither
    # key, and this is where that has to be caught.
    #
    # It used to resolve anyway, by inheriting the project's
    # `default_revision` — which is precisely the collection-level default the
    # model removes, and the reason a fragment declaring nothing was writable
    # in the first place. With that field gone from the stub, the same input
    # writes a fragment that resolves to an empty revision: an invalid state,
    # authored silently, discovered by whoever syncs next.
    #
    # The branch is NOT inferred to fill the gap. Deriving it from the remote's
    # default was considered and rejected: measured across this workspace the
    # remote default disagrees with the branch actually in use for roughly a
    # third of the repos, so inference writes a confidently WRONG value where
    # refusing writes an obviously missing one. The whole point of the model is
    # that a fragment fully determines its own checkout, by hand.
    #
    # Placed before the first write of ANY file — ahead of the url-prefix
    # minting in the loop below — so a refused `add` leaves nothing behind, and
    # ahead of the remote probe so it costs no network round trip.
    if not fragmentExisted and branch.len == 0 and revision.len == 0:
      stderr.writeLine("repro workspace repos add: " & repo &
        ": --branch is required when declaring a new repo")
      stderr.writeLine("  Every repo fragment declares the branch it tracks. " &
        "There is no workspace default and none is inferred, so a fragment " &
        "that names no branch has no checkout to resolve to.")
      stderr.writeLine("  Add the branch this repo's mainline lives on, e.g.:")
      stderr.writeLine("    repro workspace repos add " & repo &
        " --remote=" & remote & " --branch=dev")
      stderr.writeLine("  Use --revision=<commit> INSTEAD only to pin a " &
        "vendored source tree to an exact commit, or alongside --branch to " &
        "say \"tracks <branch>, sits at <commit>\".")
      stderr.writeLine("  Nothing was written.")
      return 2

    # `--branch` is validated the same way `--revision` always was, and for the
    # same reason: a manifest naming a branch that does not exist authors fine
    # and fails at sync time on everyone else's machine.
    let requestedRef = if branch.len > 0: branch else: revision
    if requestedRef.len > 0 and not fragmentExisted:
      let check = remoteRevisionState(gitBin, remote, requestedRef)
      if check.state == rrsMissing:
        stderr.writeLine("repro workspace repos add: '" & requestedRef &
          "' does not exist on " & remote & " (no matching branch or tag).")
        return 1
      elif check.state == rrsUnknown:
        stderr.writeLine("repro workspace repos add: warning: could " &
          "not verify '" & requestedRef & "' on " & remote & ": " &
          check.diagnostic)

    var paths: seq[string]
    var remoteNames: seq[string]
    for target in targets:
      case target.kind
      of mkRepoSet:
        # Membership-model authoring: the URL is split against the WORKSPACE's
        # url prefixes rather than against any one collection's remote table,
        # which is what makes the fragment shareable — a consumer no longer has
        # to also learn the remote names it happens to reference.
        let prefixes = loadUrlPrefixes(manifestRoot)
        let plan = planRepoUrlPrefix(prefixes, repo, remote)
        if plan.error.len > 0:
          stderr.writeLine("repro workspace repos add: " & target.name & ": " &
            plan.error)
          return 1
        if plan.mintedUrl.len > 0:
          createDir(manifestRoot / "url-prefixes")
          let prefixRel = "url-prefixes/" & plan.prefixName & ".toml"
          writeFile(manifestRoot / prefixRel,
            "schema = \"reprobuild.workspace.url-prefix.v1\"\n\n" &
            "[url-prefix]\n" &
            "name = \"" & plan.prefixName & "\"\n" &
            "url = \"" & plan.mintedUrl & "\"\n")
          paths.add(prefixRel)
        if not fragmentExisted:
          createDir(manifestRoot / "repos")
          writeFile(fragmentAbs,
            "schema = \"reprobuild.workspace.repo.v1\"\n\n" &
            "[repo]\n" &
            "name = \"" & repo & "\"\n" &
            "path = \"" & effectivePath & "\"\n" &
            (if branch.len > 0: "branch = \"" & branch & "\"\n"
             elif revision.len > 0: "revision = \"" & revision & "\"\n"
             else: "") &
            "url_prefix = \"" & plan.prefixName & "\"\n" &
            # `url_suffix` is written only when it differs from `name` — the
            # point of the split is that identity stops carrying URL structure,
            # so restating it would put the coupling straight back.
            (if plan.urlSuffix != repo:
               "url_suffix = \"" & plan.urlSuffix & "\"\n"
             else: ""))
          paths.add(fragmentRel)
          fragmentExisted = true
        # The fragment was just written, so the name resolves to a repo and the
        # key is `member_repos`. Routed through `membershipKeyFor` all the same,
        # so there is ONE rule deciding which namespace a name goes in.
        let memberKey = membershipKeyFor(manifestRoot, repo)
        if memberKey != memberReposKey:
          stderr.writeLine("repro workspace repos add: '" & repo &
            "' does not resolve to a repo fragment (" &
            (manifestRoot / "repos" / (repo & ".toml")) &
            "); refusing to guess which membership key it belongs under")
          return 2
        discard editSetMember(target.abs, memberKey, repo, add = true)
        paths.add(target.rel)
        remoteNames.add(target.name & "=" & plan.prefixName &
          (if plan.mintedUrl.len > 0: " (new prefix, url " & plan.mintedUrl & ")"
           else: " (reused)"))
      of mkProject:
        var manifest: ProjectManifest
        try:
          manifest = readProjectManifest(target.abs)
        except CatchableError as exc:
          stderr.writeLine("repro workspace repos add: cannot read " &
            target.abs & ": " & exc.msg)
          return 1
        let defaultRemote =
          if manifest.project.default_remote.isSome:
            manifest.project.default_remote.get()
          else:
            ""
        let plan = planRepoRemote(manifest.remote, defaultRemote, repo, remote)
        if plan.error.len > 0:
          stderr.writeLine("repro workspace repos add: " & target.name & ": " &
            plan.error)
          return 1
        if not fragmentExisted:
          createDir(manifestRoot / "repos")
          writeFile(fragmentAbs,
            "schema = \"reprobuild.workspace.repo.v1\"\n\n" &
            "[repo]\n" &
            "name = \"" & plan.repoName & "\"\n" &
            "path = \"" & effectivePath & "\"\n" &
            "remote = \"" & plan.remoteName & "\"\n" &
            (if branch.len > 0: "branch = \"" & branch & "\"\n" else: "") &
            (if revision.len > 0: "revision = \"" & revision & "\"\n" else: ""))
          paths.add(fragmentRel)
          fragmentExisted = true
        if plan.mintedFetch.len > 0:
          ensureRemoteEntry(target.abs, plan.remoteName, plan.mintedFetch)
        discard appendFragmentInclude(target.abs, fragmentRel)
        paths.add(target.rel)
        remoteNames.add(target.name & "=" & plan.remoteName &
          (if plan.mintedFetch.len > 0: " (new, fetch " & plan.mintedFetch & ")"
           else: " (reused)"))
    if branch.len == 0 and revision.len == 0 and hasSet:
      # Reported, not silent. A repo fragment fully determines its own
      # checkout, and one that declares no branch determines it incompletely.
      stderr.writeLine("repro workspace repos add: note: " & fragmentRel &
        " declares no `branch`; nothing else determines which branch this " &
        "repo lands on. Pass --branch=<name>.")

    let docRel = "repos/" & repo & ".md"
    let docAbs = manifestRoot / "repos" / (repo & ".md")
    if desc.len > 0:
      if not fileExists(docAbs):
        writeFile(docAbs, desc.strip() & "\n")
      paths.add(docRel)
    elif not fileExists(docAbs):
      stderr.writeLine("repro workspace repos add: note: no " & docRel &
        " description written (pass -m \"<description>\"); the generated " &
        "project docs will have no entry for " & repo)
    let msg = "Add repo " & repo & " to " & projects.join(", ") &
      (if desc.len > 0: " (" & desc.strip().splitLines()[0] & ")" else: "")
    let res = commitAndPushManifest(identity, gitBin, manifestRoot, msg, paths)
    stdout.writeLine("repro workspace repos add: " & repo & " -> " &
      projects.join(", ") & " — path " & effectivePath & ", remote " &
      remoteNames.join(" ") & ", " &
      (if branch.len > 0: "branch " & branch
       elif revision.len > 0: "revision " & revision & " (pinned)"
       else: "revision (inherited)") &
      " — " & res.diagnostic)
    return res.code
  of "remove":
    let including = membershipsDeclaringRepo(manifestRoot, repo)
    if projects.len == 0:
      # No --set means "stop declaring this repo anywhere". Narrowing the
      # default to the primary set would leave the repo half-declared and is
      # never what "remove this repo" reads as.
      projects = including
    if projects.len == 0 and not deleteFragment:
      stdout.writeLine("repro workspace repos remove: no repo-set or " &
        "project declares " & fragmentRel & "; nothing to do")
      return 0
    var paths: seq[string]
    var droppedFrom: seq[string]
    for project in projects:
      let target = membershipFileFor(manifestRoot, project)
      if target.abs.len == 0:
        stderr.writeLine("repro workspace repos remove: '" & project &
          "' does not exist (looked for " &
          (manifestRoot / "repo-sets" / (project & ".toml")) & " and " &
          (manifestRoot / "projects" / (project & ".toml")) & ")")
        return 1
      var dropped = false
      case target.kind
      of mkRepoSet:
        # Which key the entry sits under is read off what the name resolves to,
        # never off the verb. A repo whose fragment is already gone resolves to
        # nothing, and removing "whichever array mentions it" could strip a
        # same-named entry out of `member_sets` instead.
        let memberKey = membershipKeyFor(manifestRoot, repo)
        if memberKey.len == 0:
          stderr.writeLine("repro workspace repos remove: '" & repo &
            "' resolves to neither a repo fragment nor a repo-set (looked " &
            "for " & (manifestRoot / "repos" / (repo & ".toml")) & " and " &
            (manifestRoot / "repo-sets" / (repo & ".toml")) &
            "); refusing to guess which membership key to edit in " &
            target.rel)
          return 2
        dropped = editSetMember(target.abs, memberKey, repo, add = false)
      of mkProject:
        dropped = removeFragmentInclude(target.abs, fragmentRel)
      if dropped:
        droppedFrom.add(project)
        paths.add(target.rel)
    if deleteFragment:
      let stillIncluding = membershipsDeclaringRepo(manifestRoot, repo)
      if stillIncluding.len > 0:
        stderr.writeLine("repro workspace repos remove: refusing " &
          "--delete-fragment: " & fragmentRel & " is still included by " &
          stillIncluding.join(", "))
        stderr.writeLine("  the include edges above were dropped; re-run " &
          "with --delete-fragment once no project references it")
        if paths.len > 0:
          discard commitAndPushManifest(identity, gitBin, manifestRoot,
            "Remove repo " & repo & " from " & droppedFrom.join(", "), paths)
        return 2
      if fileExists(fragmentAbs):
        removeFile(fragmentAbs)
        paths.add(fragmentRel)
      let docRel = "repos/" & repo & ".md"
      if fileExists(manifestRoot / docRel):
        removeFile(manifestRoot / docRel)
        paths.add(docRel)
    if paths.len == 0:
      stdout.writeLine("repro workspace repos remove: " & repo &
        " was not included by " & projects.join(", ") & "; nothing to do")
      return 0
    let msg = "Remove repo " & repo &
      (if droppedFrom.len > 0: " from " & droppedFrom.join(", ") else: "") &
      (if deleteFragment: " (fragment deleted)" else: "")
    let res = commitAndPushManifest(identity, gitBin, manifestRoot, msg, paths)
    stdout.writeLine("repro workspace repos remove: " & repo & " — " &
      res.diagnostic)
    if not deleteFragment and droppedFrom.len > 0:
      stdout.writeLine("repro workspace repos remove: " & fragmentRel &
        " kept (reusable declaration); pass --delete-fragment to remove it")
    # This edits DECLARATIONS, not this machine. Say so, rather than leaving
    # the operator to discover a checkout that is no longer declared.
    stdout.writeLine("repro workspace repos remove: any existing checkout " &
      "was left on disk")
    return res.code
  else:
    stderr.writeLine("repro workspace repos: unknown subcommand '" & sub &
      "' (expected: list, add, remove)")
    return 2

proc runThinAppDispatch(programName: string): int =
  # Source-only inputs captured by a packaged or locally built CLI must cross
  # every nested interface/resource compiler boundary. Explicit caller
  # overrides remain authoritative; this only fills missing environment keys.
  ensureBuiltSourcePackageEnvironment()
  # M9.R.13a — seed the provider-nimcache session token before any
  # subcommand routing, so every nested subprocess spawned downstream
  # (the build engine's per-recipe `__repro-compile-provider` helpers,
  # the recursive `executeBuildTarget` calls auto-recurse fires for
  # from-source recipes) inherits a stable per-`repro`-session token
  # and lands in one shared provider nimcache. Without this seed each
  # of the ~84 from-source recipes paid a full cold provider compile
  # (~5 min on Windows) because every helper subprocess had a distinct
  # pid -- the M9.R.12 pid-scoped key collapsed cross-recipe sharing.
  # See `sharedProviderNimcacheKey` for the full rationale.
  ensureProviderNimcacheSession()
  when defined(windows):
    let appDir = parentDir(getAppFilename())
    if appDir.len > 0:
      let pathEnv = getEnv("PATH")
      if pathEnv.len > 0:
        putEnv("PATH", appDir & ";" & pathEnv)
      else:
        putEnv("PATH", appDir)
  let args = normalizeWorkspaceNamespaceAlias(
    normalizeInternalArgs(commandLineParams()))
  let publicCliPath = stablePublicCliPath()
  if programName == "repro" and args.len > 0 and
      args[0] == BrokerModeFlag:
    return runPrivilegedBrokerMode(args)
  if wantsVersion(args):
    echo renderVersion(programName)
    return 0
  if wantsHelp(args):
    # Explicit help request — print usage to stdout, exit 0 so the
    # output is pipeable / scriptable. Bare / unknown commands still
    # fall through to the stderr-+-exit-2 path at the end of this
    # proc.
    echo renderUsage(programName)
    return 0
  # ``internal io monitor`` is the canonical self-spawn argv the build
  # engine's monitor wrapper uses (``getAppFilename() internal
  # io monitor …``). Because the engine prepends those args to
  # ``getAppFilename()`` — whichever binary is currently running — we
  # have to dispatch the monitor BEFORE the per-program arms below.
  # Otherwise a ``repro-daemon``-hosted build run would route the
  # monitor's self-spawn into ``runUserDaemonCommand``, which only
  # parses daemon-config flags and rejects ``internal`` with
  # ``repro-daemon: unexpected argument: internal`` and exit code 2.
  # Mirrors ``repro debug io monitor``: forward the remaining args to
  # the shared io-monitor CLI.
  if args.len >= 3 and args[0] == "internal" and args[1] == "io" and
      args[2] == "monitor":
    let monitorArgs =
      if args.len > 3:
        args[3 .. ^1]
      else:
        @[]
    return runIoMonitorCli(programName & " internal io monitor", monitorArgs)
  if programName == "reprostored":
    return runReprostoredCommand(args)
  if programName == "repro-daemon":
    installUserDaemonBuildPrewarmer()
    installUserDaemonBuildExecutor()
    installUserDaemonWatchExecutor()
    return runUserDaemonCommand(args)
  # Documented ``repro internal …`` namespace (Executable-Consolidation M1).
  # ``internal <helper>`` spellings for the role helpers were already rewritten
  # to their ``__repro-<helper>`` argument form by ``normalizeInternalArgs``
  # above, so any ``internal`` argv still reaching here is either an explicit
  # ``--help`` or an unknown/bare subcommand. (``internal io monitor`` was
  # already routed to the io-monitor CLI at the top of this proc so any
  # self-spawn from a non-``repro`` binary like ``repro-daemon`` reaches
  # the right handler.) ``repro internal`` is intentionally absent from
  # the primary ``repro help`` body; it is documented via
  # ``renderInternalUsage`` (and ``CLI/internal/`` in the specs).
  if args.len >= 4 and args[0] == "internal" and args[1] == "resolve-package":
    # ``repro internal resolve-package <consumerDir> <name>``
    #
    # Resolve one declared package dependency to its checkout and print the
    # absolute path, or print nothing when it is not checked out.
    #
    # This exists to be called from a recipe's own macro expansion via
    # ``staticExec``. A macro cannot reuse the engine's resolution directly --
    # it runs at compile time, in a scratch directory, with none of the
    # engine's state -- and reimplementing workspace lookup inside the macro
    # would create a second resolver free to drift from the one that builds
    # ``--path:``. Shelling back into the engine keeps exactly one.
    #
    # ALWAYS exits 0, including when unresolved. ``staticExec`` surfaces a
    # non-zero status as an opaque compile failure with no useful location,
    # so "not found" is reported as empty output and diagnosed by the caller,
    # which can say which recipe asked and for what.
    let consumerDir = args[2]
    let name = args[3]
    let resolved = resolvePackageRoot(consumerDir, name)
    if resolved.len > 0:
      echo resolved
    return 0

  if args.len > 0 and args[0] == "internal":
    # Bare ``repro internal``, ``repro internal --help``, or an unrecognized
    # subcommand: print the internal-namespace usage. Exit 0 for an explicit
    # help request (pipeable), exit 2 for an unknown/missing subcommand —
    # matching the stdout/exit-0 vs stderr/exit-2 convention used elsewhere.
    if args.len == 1 or (args.len >= 2 and args[1] in ["help", "--help", "-h"]):
      echo renderInternalUsage(programName)
      return 0
    stderr.writeLine(renderInternalUsage(programName))
    return 2
  if args.len > 0 and args[0] == "__repro-runquota-helper":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runRunQuotaHelperCli(helperArgs)
  if args.len > 0 and args[0] == "__repro-compile-provider":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runProviderCompileHelper(helperArgs)
  if args.len > 0 and args[0] == "__repro-extract-interface":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runInterfaceExtractHelper(helperArgs)
  if args.len > 0 and args[0] == "__repro-compile-profile":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runProfileCompileHelper(helperArgs)
  if args.len > 0 and args[0] == "__repro-dev-env-introspect":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runDevEnvIntrospectionHelper(helperArgs)
  if args.len > 0 and args[0] == "__repro-render-dev-env-shell":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runDevEnvShellRenderHelper(helperArgs)
  if args.len > 0 and args[0] == "__repro-direnv-activate":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    try:
      return runReproDirenvActivationHelper(helperArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro direnv activate: error: " & err.msg)
      return 1
  if args.len > 0 and args[0] == "__repro-native-shell-activate":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    try:
      return runReproNativeShellActivationHelper(helperArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro native shell activate: error: " & err.msg)
      return 1
  if args.len > 0 and args[0] == "__repro-dev-session-supervisor":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    try:
      return runDevSessionSupervisorHelper(helperArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro dev-session supervisor: error: " & err.msg)
      return 1
  if args.len > 0 and args[0] == "__repro-dev-session-http":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    try:
      return runDevSessionHttpHelper(helperArgs)
    except CatchableError as err:
      stderr.writeLine("repro dev-session http: error: " & err.msg)
      return 1
  if args.len > 0 and args[0] == "__repro-cmake-regenerate":
    let helperArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    try:
      return runCmakeRegenerationHelper(helperArgs)
    except CatchableError as err:
      stderr.writeLine("repro cmake regeneration: error: " & err.msg)
      return 1
  if programName == "repro" and args.len >= 3 and args[0] == "debug" and
      args[1] == "io" and args[2] == "monitor":
    let monitorArgs =
      if args.len > 3:
        args[3 .. ^1]
      else:
        @[]
    return runIoMonitorCli("repro debug io monitor", monitorArgs)
  if programName == "repro" and args.len >= 2 and args[0] == "debug" and
      args[1] == "artifact":
    try:
      let artifactArgs =
        if args.len > 2:
          args[2 .. ^1]
        else:
          @[]
      return runDebugArtifactCommand(artifactArgs)
    except CatchableError as err:
      stderr.writeLine("repro debug artifact: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "configs":
    try:
      let configArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runConfigsCommand(configArgs)
    except CatchableError as err:
      stderr.writeLine("repro configs: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "capabilities":
    try:
      let capabilityArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runCapabilitiesCommand(capabilityArgs)
    except CatchableError as err:
      stderr.writeLine("repro capabilities: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "graph":
    try:
      let graphArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runGraphCommand(graphArgs, publicCliPath)
    except BuildTargetAmbiguousError as err:
      # Named-Targets M5 ``target_ambiguous`` diagnostic for the
      # graph arm. Same shape as ``repro build`` so JSON consumers
      # and test harnesses can rely on the unified text.
      stderr.write(renderAmbiguousTargetDiagnostic(err[]))
      return 2
    except BuildTargetUnknownError as err:
      # Named-Targets M5 ``unknown_target`` diagnostic with the M2
      # Levenshtein candidates.
      stderr.write(renderUnknownTargetDiagnostic(err[]))
      return 2
    except CatchableError as err:
      stderr.writeLine("repro graph: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "why":
    try:
      let whyArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runWhyCommand(whyArgs, publicCliPath)
    except BuildTargetAmbiguousError as err:
      stderr.write(renderAmbiguousTargetDiagnostic(err[]))
      return 2
    except BuildTargetUnknownError as err:
      stderr.write(renderUnknownTargetDiagnostic(err[]))
      return 2
    except CatchableError as err:
      stderr.writeLine("repro why: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "deps":
    try:
      let depsArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runDepsCommand(depsArgs)
    except CatchableError as err:
      stderr.writeLine("repro deps: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and
      args[0] == "show-conventions":
    try:
      let scArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runShowConventionsCommand(scArgs)
    except CatchableError as err:
      stderr.writeLine("repro show-conventions: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "build":
    try:
      let buildArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runBuildCommand(buildArgs, publicCliPath)
    except BuildTargetAmbiguousError as err:
      # Named-Targets M2 ``target_ambiguous`` diagnostic. Exit 2 per the
      # CLI-build §"Target Selection" contract; the message names the
      # qualified candidates so the user can re-run with the
      # ``<package>:<name>`` form. The diagnostic text is rendered by a
      # shared helper so the daemon-side translation in
      # ``installUserDaemonBuildExecutor`` produces identical bytes.
      stderr.write(renderAmbiguousTargetDiagnostic(err[]))
      return 2
    except BuildTargetUnknownError as err:
      # Named-Targets M2 ``unknown_target`` diagnostic. Exit 2 with
      # Levenshtein top-3 suggestions when the project's target-export
      # table has near-matches. Text rendered by the shared helper that
      # the daemon-side hook also calls.
      stderr.write(renderUnknownTargetDiagnostic(err[]))
      return 2
    except CatchableError as err:
      stderr.writeLine("repro build: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "test":
    # CI-Sharding M2 — ``repro test --shard k/N [...]``.  Implementation
    # in ``runReproTestCommand`` above; see the block comment there for
    # the user-visible flag surface and the fixture / plan I/O shape.
    #
    # Spec-Implementation M0 alias contract: ``repro test`` is also the
    # CLI verb alias for ``repro build test`` per Build-Graph-Collections.md
    # §"Verb Aliases for Conventional Collections". The CI-sharding
    # implementation already maps to ``repro build test`` internally
    # (see ``buildArgs = @["build", "test"]`` at the head of this file),
    # so the alias is satisfied without further dispatch routing.
    try:
      let testArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runReproTestCommand(testArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro test: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "certify":
    # TC-1: ``repro certify`` is the explicit "run the full required set to
    # obtain a certificate" form — an alias for ``repro test --certify``
    # (Test-Certificates.md §"Issuance"). It forwards every remaining arg to
    # ``runReproTestCommand`` with ``--certify`` prepended so the same
    # issuance path runs; ``--no-certify`` would contradict the verb and is
    # left to the user's responsibility (last-flag-wins in the parser).
    try:
      var certifyArgs = @["--certify"]
      if args.len > 1:
        for a in args[1 .. ^1]:
          certifyArgs.add(a)
      return runReproTestCommand(certifyArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro certify: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "ci":
    # TC-4: ``repro ci plan`` — the per-platform CI fast-track decision (skip
    # targets a valid certificate already covers; run the rest). The decision
    # reuses the TC-5 signature verifier + TC-1 coverage union, so a forged
    # cert can never cause a skip; the skip-vs-advisory choice is the project's
    # explicit ``ci_trust`` policy (Test-Certificates.md §"CI integration").
    try:
      let ciArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runCiCommand(ciArgs)
    except CatchableError as err:
      stderr.writeLine("repro ci: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "bench":
    # Spec-Implementation M0: ``repro bench`` is a CLI verb alias for
    # ``repro build bench`` per Build-Graph-Collections.md §"Verb Aliases
    # for Conventional Collections" and CLI/bench.md. The alias is a
    # one-arg rewrite that delegates to ``runBuildCommand``; the bench
    # build graph collection itself is the project's responsibility to
    # declare (via ``collect("bench", ...)`` or the M1-era
