      args[1] == "projects":
    # WV-3 — `repro workspace projects list|add|remove`, the retained spelling
    # of `sets`. Kept while the manifest repo still carries `projects/*.toml`;
    # it differs from `sets` in exactly one respect, which directory `add`
    # scaffolds into.
    try:
      let pArgs =
        if args.len > 2: args[2 .. ^1]
        else: @[]
      return runWorkspaceProjectsCommand(pArgs)
    except CatchableError as err:
      stderr.writeLine("repro workspace projects: error: " & err.msg)
      return 1
  if programName == "repro" and args.len >= 2 and args[0] == "workspace" and
      args[1] == "repos":
    # WV-4 — `repro workspace repos list|add|remove`. DEFINITION: inspect or
    # author repo fragments and the `includes` edges wiring them into projects.
    try:
      let pArgs =
        if args.len > 2: args[2 .. ^1]
        else: @[]
      return runWorkspaceReposCommand(pArgs)
    except CatchableError as err:
      stderr.writeLine("repro workspace repos: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "completion":
    # RA-6 — `repro completion <shell>`. Emit a shell completion script
    # (RA-26 `prompt init` style: print a snippet, mutate nothing).
    try:
      let cArgs =
        if args.len > 1: args[1 .. ^1]
        else: @[]
      return runCompletionCommand(programName, cArgs, publicCliPath)
    except CatchableError as err:
      stderr.writeLine("repro completion: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "branch":
    # M14 / WV-6 — `repro branch [<path>]`. Top-level subcommand per
    # ``reprobuild-specs/CLI/branch.md``: NOT under ``repro workspace``.
    # Same convention deviation as M9–M12: the milestone spec names a
    # planner path but the implementation lives in ``repro_cli_support``
    # for symmetry, reachable via ``runBranchCommand``.
    try:
      let branchArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runBranchCommand(branchArgs)
    except CatchableError as err:
      stderr.writeLine("repro branch: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "switch":
    # WV-5 — `repro switch <branch> [-b]`. Top-level subcommand per
    # ``reprobuild-specs/CLI/switch.md``: switches every participating repo to
    # the named branch (creating it first under ``-b``) and updates the M13
    # metadata. ``checkout`` / ``co`` are RETIRED spellings and deliberately
    # absent — they fail as unknown subcommands (see Retired-Names.md).
    try:
      let switchArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runSwitchCommand(switchArgs)
    except CatchableError as err:
      stderr.writeLine("repro switch: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "add":
    # RA-22 — `repro add <repo>` (workspace membership / develop-mode policy
    # per CLI/add.md + Workspace-And-Develop-Mode.md §"Workspace Membership").
    # Policy (RA-8 `[develop] org_urls`) decides develop vs binary by default;
    # `--develop`/`--binary` override; `--no-membership` clones without adding.
    # Implementation in ``runAddCommand``.
    try:
      let addArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runAddCommand(addArgs)
    except CatchableError as err:
      stderr.writeLine("repro add: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "remove":
    # RA-9 — `repro remove <repo>` (workspace context per CLI/remove.md +
    # the RA-10 path/name note). Destructive-command safety: previews the
    # per-repo effect, gates a dirty discard behind ``--force``, and
    # refuses cleanly in a non-interactive context rather than hanging.
    # Implementation in ``runRemoveCommand``.
    try:
      let removeArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runRemoveCommand(removeArgs)
    except CatchableError as err:
      stderr.writeLine("repro remove: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "push":
    # RA-25 — `repro push [<project>]` (closure-ordered push + lock publish +
    # certify) per CLI/push.md. The inverse of the RA-21 publication gate:
    # pushes the pushed repo's develop-mode dependency closure in dependency-
    # first order, then publishes the workspace lock (loud on failure).
    # ``--sync`` (+``--merge``/``--rebase``) reconciles upstream first.
    # Implementation in ``runPushCommand``.
    try:
      let pushArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runPushCommand(pushArgs)
    except CatchableError as err:
      stderr.writeLine("repro push: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "sync":
    # Top-level `repro sync [<project>]` shortcut per CLI/sync.md. Mirrors
    # the `repro switch`/`push` top-level arms above: routes to the same
    # handler `repro workspace sync` uses (``runWorkspaceSyncCommand``),
    # forwarding the remaining args unchanged so every flag (scoped
    # ``<project>``, ``--jobs*``, ``--tags``, ``--force-sync``,
    # ``--dry-run``, ``--json``, ``--verbose``) behaves identically.
    try:
      let syncArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runWorkspaceSyncCommand(syncArgs)
    except CatchableError as err:
      stderr.writeLine("repro sync: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "pull":
    # Top-level `repro pull [<project>]` shortcut per CLI/sync.md. Mirrors
    # the `repro sync` shortcut just above: routes to the same handler
    # `repro workspace pull` uses (``runWorkspacePullCommand``), forwarding
    # the remaining args unchanged.
    try:
      let pullArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runWorkspacePullCommand(pullArgs)
    except CatchableError as err:
      stderr.writeLine("repro pull: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "watch":
    try:
      let watchArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runWatchCommand(watchArgs, publicCliPath)
    except BuildTargetAmbiguousError as err:
      # Named-Targets M3: watch inherits the shared M2 resolver, so the
      # ``target_ambiguous`` diagnostic surfaces identically. The shared
      # ``renderAmbiguousTargetDiagnostic`` helper keeps the watch and
      # build emissions byte-identical at the resolver seam.
      stderr.write(renderAmbiguousTargetDiagnostic(err[]))
      return 2
    except BuildTargetUnknownError as err:
      # Named-Targets M3: same translation for the ``unknown_target``
      # diagnostic. The daemon-side translation lives in
      # ``installUserDaemonWatchExecutor``; both paths render via
      # ``renderUnknownTargetDiagnostic``.
      stderr.write(renderUnknownTargetDiagnostic(err[]))
      return 2
    except CatchableError as err:
      stderr.writeLine("repro watch: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "hcr":
    try:
      let hcrArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runHcrCoordinateCommand(hcrArgs)
    except CatchableError as err:
      stderr.writeLine("repro hcr: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "develop":
    try:
      let developArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      return runDevelopCommand(developArgs)
    except CatchableError as err:
      stderr.writeLine("repro develop: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "store":
    let storeArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runStoreCommand(storeArgs)
  if programName == "repro" and args.len > 0 and args[0] == "cas":
    # M9.R.77.5 — R11 Layer-1 CLI (blob-level put/get/verify/path/gc).
    # Separate from ``repro store`` because it exposes ONLY the CAS
    # surface — see runCasCommand's doc block for the two-layer split.
    let casArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runCasCommand(casArgs)
  if programName == "repro" and args.len > 0 and args[0] == "daemon":
    let daemonArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    # Executable-Consolidation M2: `repro daemon serve` is the daemon PROCESS
    # entry — the role formerly carried by the standalone `repro-daemon` binary
    # (whose program name stays a compatibility alias below). Every other
    # `daemon` subcommand (status / start / stop / restart / logs / sessions)
    # is a client control command.
    if daemonArgs.len > 0 and daemonArgs[0] == "serve":
      installUserDaemonBuildPrewarmer()
      installUserDaemonBuildExecutor()
      installUserDaemonWatchExecutor()
      return runUserDaemonCommand(daemonArgs[1 .. ^1])
    return runUserDaemonCliCommand(daemonArgs)
  if programName == "repro" and args.len > 0 and args[0] == "launch-plan":
    let lpArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runLaunchPlanCommand(lpArgs)
  if programName == "repro" and args.len > 0 and args[0] == "__remote-activate":
    let remoteArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runHomeCommand(@["__remote-activate"] & remoteArgs)
  if programName == "repro" and args.len > 0 and args[0] == "home":
    let homeArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runHomeCommand(homeArgs)
  if programName == "repro" and args.len > 0 and args[0] == "infra":
    let infraArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runInfraCommand(infraArgs)
  if programName == "repro" and args.len > 0 and args[0] == "system":
    let systemArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runSystemCommand(systemArgs)
  if programName == "repro" and args.len > 0 and args[0] == "deploy-agent":
    # Windows-Runner-Binary-Cache-Deploy M5: one tick of the signed
    # desired-state manifest pull loop (poll → verify against the
    # allowed-signers set → apply the highest valid sequence for this
    # target via the M4 runInfraApply path).
    let deployArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return cli_deploy_agent.runDeployAgentCommand(deployArgs)
  if programName == "repro" and args.len > 0 and args[0] == "hardware":
    # M9.R.21.3: `repro hardware probe` writes /etc/repro/hardware.nim
    # from the live system. The dispatcher lives in
    # `repro_cli_support/hardware.nim`; see
    # `reprobuild-specs/ReproOS-Configuration-Architecture.md` §3 for
    # the surface contract.
    let hardwareArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runHardwareCommand(hardwareArgs)
  if programName == "repro" and args.len > 0 and args[0] == "prompt":
    # RA-26 — `repro prompt` ambient workspace-state segment (+ `prompt
    # init <shell>`) per CLI/prompt.md. Reads only cheap cached state (no
    # per-render git fan-out); silent + exit 0 outside a workspace.
    try:
      let promptArgs =
        if args.len > 1:
          args[1 .. ^1]
        else:
          @[]
      if promptArgs.len > 0 and promptArgs[0] == "init":
        let initArgs =
          if promptArgs.len > 1:
            promptArgs[1 .. ^1]
          else:
            @[]
        return runPromptInitCommand(programName, initArgs, publicCliPath)
      return runPromptCommand(promptArgs)
    except CatchableError as err:
      stderr.writeLine("repro prompt: error: " & err.msg)
      return 1
  if programName == "repro" and args.len > 0 and args[0] == "disk":
    # M9.R.22.4: `repro disk` subcommand surface (plan/apply/mount/...)
    # per `reprobuild-specs/ReproOS-Disko-Port.md` §4. The dispatcher
    # lives in `repro_cli_support/disk.nim`.
    let diskArgs =
      if args.len > 1:
        args[1 .. ^1]
      else:
        @[]
    return runDiskCommand(diskArgs)
  stderr.writeLine(renderUsage(programName))
  2

proc runThinApp*(programName: string): int =
  ## Single chokepoint for the outcome-dependent report default: the verbs
  ## stage what they would leave behind, and the real exit code decides.
  result = runThinAppDispatch(programName)
  flushStagedFailureReport(result)
